-- 3. Flashcards Data (8792 cards)
INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1755151899556-0', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Crystals are formed from concentrated sugar solutions.
Sentence B. Crystallization is inversely related to the ease of solubility.', 'Both sentences are correct', 'Sentence A is correct because crystallization occurs when a supersaturated or concentrated sugar solution allows dissolved sugar molecules to arrange into crystals. 

Sentence B is also correct: substances that are less soluble crystallize more readily as the solution becomes supersaturated.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Bothsentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:58:26.602Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:58:26.602Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T13:58:26.792Z"'::jsonb),
('anki-card-1755151950516-1', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Shortening impedes gluten development by hydrolysis.
Sentence B. Impeding gluten development would result in flaky products.', 'Sentence B is correct', 'Sentence A is incorrect because shortening impedes gluten development mainly by coating flour proteins and physically limiting hydration and gluten formation, not by hydrolysis. 

Sentence B is correct because limiting gluten development produces a tender or flaky texture, as desired in products such as pastry.', '["Sentence A is correct","Sentence B is correct","Bothsentences are correct","Bothsentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T12:12:11.743Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T12:12:11.743Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T12:12:11.743Z"'::jsonb),
('anki-card-1755152003615-2', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Vinaigrette is an example of a temporary emulsion.
Sentence B. Temporary emulsions are separated by heat.', 'Sentence A is correct', 'Sentence A is correct because vinaigrette is a temporary emulsion of oil and vinegar that separates on standing. 

Sentence B is incorrect because temporary emulsions separate primarily because the phases are immiscible and the emulsion is unstable, not simply because of heat.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:22:53.292Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:22:53.292Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T16:22:53.292Z"'::jsonb),
('anki-card-1755152054479-3', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Fruits become more brilliant in color during ripening.
Sentence B. This is due to the breakdown of chlorophyll and exposes the underlying pigments.', 'Both sentences are correct', 'During ripening, chlorophyll breaks down and green color diminishes, revealing or allowing the development of pigments such as carotenoids and anthocyanins, which make many fruits appear brighter or more intensely colored.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:50:25.888Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:50:25.888Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T16:50:25.888Z"'::jsonb),
('anki-card-1755152111143-4', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. The tough, fibrous inner core in carrots is due to the high concentration of lignin.
Sentence B. The outer layer of the skin and peel of fruits has a higher proportion of cellulose and hemicelluloses than the inner layers do.', 'Both sentences are correct', 'The tougher central portion of carrots is associated with greater lignification, while outer tissues such as skins and peels generally contain higher proportions of structural carbohydrates, including cellulose and hemicellulose, than softer inner tissues.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:09:23.815Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:09:23.815Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T13:09:23.815Z"'::jsonb),
('anki-card-1755152163455-5', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Using stainless steel may prevent discoloration of fruits
Sentence B. Water lost and absorbed depending on the type of vegetable.', 'Both sentences are correct', 'Stainless steel is relatively nonreactive and helps prevent discoloration caused by reactions between food pigments and reactive metals. 

Vegetables may also lose or absorb water depending on their structure, composition, and cooking or storage conditions.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:40:29.143Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:40:29.143Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T13:40:29.143Z"'::jsonb),
('anki-card-1755152217937-6', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Gelatin is soluble in cold water
Sentence B. Gelatin is immediately poured in boiling water during cooking.', 'Both sentences are incorrect', 'Gelatin absorbs cold water and blooms but is not truly dissolved simply by cold water. It should also not be immediately boiled; excessive heat can reduce its gelling strength.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:42:59.085Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:42:59.085Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T16:42:59.085Z"'::jsonb),
('anki-card-1755152254988-7', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Addition of acid to sucrose produces invert sugars.
Sentence B. Saccharin is an invert sugar', 'Sentence A is correct', 'Sentence A is correct because acid hydrolyzes sucrose into glucose and fructose, producing invert sugar. 

Sentence B is incorrect because saccharine is an artificial sweetener and is not an invert sugar.', '["Sentence A is correct","Sentence B is correct","Bothsentences are correct","Bothsentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:04:23.784Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:04:23.784Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T13:04:23.784Z"'::jsonb),
('anki-card-1755152277751-8', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Fish contains aflatoxin which causes food intoxication.
Sentence B. Aflatoxin is a neurotoxin.', 'Sentence B is correct', 'Fish does not normally contain aflatoxin; aflatoxins are mycotoxins produced mainly by certain molds in susceptible commodities (Mycotoxin, elaborated by Aspergillus flavus) 

Aflatoxins, particularly Aflatoxin B1, cause neurotoxicity by crossing the blood-brain barrier, triggering severe oxidative stress, and inducing brain cell death.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:46.647Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T16:51:46.647Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T16:51:46.647Z"'::jsonb),
('anki-card-1755152300850-9', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Sentence A. Rice starch has smaller granules than potato starch.
Sentence B. Rice starch granules gelatinize earlier than potato starch.', 'Sentence A is correct', 'Rice starch generally has smaller granules than potato starch.

Rice starch gelatinizes at a higher temperature range, usually between 65°C to 85°C (depending on the variety), while potato starch gelatinizes at a lower temperature range, usually starting around 58°C to 66°C. 

Even though smaller granules can sometimes melt faster under specific conditions, potato starch''s molecular structure (such as higher paste viscosity and lower thermal stability requirements for its crystalline arrangement) allows it to start the swelling and gelatinization process earlier during heating than rice starch.', '["Sentence A is correct","Sentence B is correct","Both sentences are correct","Both sentences are incorrect"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T14:59:28.542Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T14:59:28.542Z"'::jsonb, '"2026-09-26T14:32:30.039Z"'::jsonb, '"2026-10-22T14:59:28.542Z"'::jsonb),
