INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1755155482248-100', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Northern Philippines’ version of sisig', 'Dinakdakan', 'Dinakdakan is an authentic delicacy from the Ilocos region in the Northern Philippines. Much like Kapampangan sisig, it is made by boiling and then charcoal-grilling various pig parts (such as the ears, face/jowl, and tongue).

The primary structural differences are that dinakdakan is typically sliced into thin strips rather than being finely minced, and it traditionally uses boiled pig''s brain mashed into a vinegar-calamansi dressing to achieve its signature rich, creamy texture (whereas modern commercial sisig often replaces this with mayonnaise or egg).

• Baguisen: A traditional Ilocano organ meat stew cooked with pig or goat intestines, liver, and heart thickened with pork blood and soured with vinegar or kamias. It is closer in profile to dinuguan.
• Lininta: A traditional Muslim-Filipino (Maranao) dish consisting of fresh fish marinated with palapa, wrapped tightly in banana leaves, and gently steamed.
• Dinardaraan: The strict Ilocano version of dinuguan (pork blood stew). Unlike the Tagalog version which has plenty of thick gravy, dinardaraan is famously cooked until the sauce completely reduces, leaving a much drier, oilier coat on the meat.', '["Lininta","Baguisen","Dinakdakan","Dinardaraan"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:49:26.145Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:49:26.145Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:49:26.145Z"'::jsonb),
('anki-card-1755155505897-101', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Iloilo’s version of espasol', 'Baye-baye', 'Baye-baye is a popular native rice cake delicacy from Western Visayas, especially in Santa Barbara and Miagao, Iloilo. Much like the Tagalog espasol (which is traditionally rolled in toasted rice flour), baye-baye shares a very similar chewy structural profile. It is prepared by mixing finely ground, newly harvested toasted rice (pinipig) or corn with freshly grated young coconut and sugar, then pounding and shaping the mixture into dense patties or cylinders.

• Budbud kabog: A famous native delicacy from Catmon, Cebu. It is a sweet sticky rice cake roll wrapped securely in banana leaves, but it is made using millet seeds (kabog) instead of rice flour.
• Moron: A distinct, two-toned chocolate rice cake specialty from Leyte and Samar. It features a twisted strip of sweet milk-infused glutinous rice intertwined with a rich chocolate-cacao rice paste wrapped in banana leaves.
• Binagol: A famous sweet delicacy from Leyte. It is made from mashed taro root (talyan), condensed milk, and sugar, which is packed and steamed inside a halved coconut shell (bagol) and topped with a rich egg yolk-sweet center.', '["Binagol","Baye-baye","Moron","Budbud kabog"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:57:52.811Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:57:52.811Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:57:52.811Z"'::jsonb),
('anki-card-1755155530413-102', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Roasted Suckling pig', 'Lechon de leche', 'In culinary terms and Spanish-Filipino food culture, a suckling pig is a young piglet that has fed exclusively on its mother''s milk (hence the word leche, meaning milk). When this young, tender piglet is slowly roasted whole over charcoal, it is specifically designated as Lechon de leche.

• Pritchon: A portmanteau of the words prito (fried) and lechon. It refers to a whole or chopped piglet that is deep-fried in oil rather than roasted over charcoal, often carved and wrapped in pita or mandarin pancakes.
• Lechon: A broad, generic term for any whole roasted pig. A standard lechon usually involves a fully matured, adult market hog rather than a young suckling piglet.', '["Pritchon","Lechon de leche","Lechon","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:40:06.265Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:40:06.265Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:40:06.265Z"'::jsonb),
('anki-card-1755155557163-103', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The place Calasiao is associated with what food.', 'Puto', 'Calasiao, a municipality in Pangasinan, is widely celebrated as the "Puto Capital of the Philippines".

Puto Calasiao is a bite-sized, semi-sweet steamed rice cake. It stands out because it is traditionally made using fermented short-grain glutinous rice (galapong), giving it a distinctively soft, chewy, and slightly springy texture.

While the classic white version is the most iconic, it is also sold in variations like ube (purple yam), pandan, cheese, mango, and strawberry.

• Buro: A fermented rice dish (often mixed with fish or shrimp) that is a famous condiment in neighboring Pampanga and other parts of Central/Northern Luzon.
• Patupat: A sweet Ilocano delicacy made of glutinous rice cooked in sugarcane juice and wrapped in a woven pouch of coconut or palm leaves. While found in Pangasinan, it is not uniquely synonymous with Calasiao the way puto is.
• Tocino: A sweet, cured pork breakfast meat most famously associated with Pampanga (the culinary capital of the Philippines).', '["Buro","Tocino","Patupat","Puto"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:17:21.669Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:17:21.669Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:17:21.669Z"'::jsonb),
('anki-card-1755155591209-104', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'It is a popular suman from Leyte flavored with chocolate', 'Moron', 'Moron is a native kakanin (sticky rice cake) originating from the Eastern Visayas region, particularly popular in Leyte (like Tacloban and Abuyog) and Eastern Samar. It is a type of suman made by twisting a milky vanilla-flavored white dough and a chocolate dough together. The chocolate flavor comes from cocoa or local tablea (cacao tablets).

It features a distinct marble swirl, a very smooth texture, and is often embedded with roasted peanuts before being wrapped in banana leaves and steamed. It is traditionally eaten as a snack (merienda) alongside hot coffee or sikwate (native hot chocolate).

• Binakol: A savory Filipino chicken soup traditionally cooked inside a bamboo tube or coconut shell using coconut water.
• Binagol: Another famous sweet delicacy from Leyte (specifically Dagami), but it is made from mashed talyan (taro root crop), condensed milk, and coconut milk, then steamed inside a coconut shell (bagol).
• Baye-baye: A popular Western Visayas (Iloilo/Negros) delicacy made from toasted ground rice or corn mixed with coconut water and sugar.', '["Binagol","Binakol","Moron","Baye-baye"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:15:05.914Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:15:05.914Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:15:05.914Z"'::jsonb),
('anki-card-1755155768935-105', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Linat-an is closest to the dish:', 'Nilaga', 'Linat-an is a traditional boiled pork soup dish native to the Visayas and Mindanao regions. Structurally and visually, it is almost identical to the Tagalog Nilaga. Both dishes involve simmering tough cuts of meat (usually pork ribs or beef) with an abundance of clear broth, paired with vegetables like cabbage, potatoes, leafy greens, and green beans.

The primary difference lies in the flavor aromatics: while Nilaga relies heavily on onions and whole black peppercorns, Linat-an incorporates distinct regional ingredients like lemongrass (tanglad), ginger, and sometimes red bell peppers or taro (gabi) to give the clear broth a more fragrant, refreshing, and slightly sweet flavor profile.', '["Nilaga","Kare-kare","Pochero","Cardillo"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T14:52:12.298Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T14:52:12.298Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T14:52:12.298Z"'::jsonb),
('anki-card-1755155820867-106', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The following statements are true in Judaism, EXCEPT:', 'all grape varieties are restricted', 'Jewish dietary laws prohibit mixing meat and dairy, prohibit consumption of blood, and forbid shellfish. However, it is not correct that all grape varieties are restricted.', '["meat cannot be eaten with dairy","the Torah prohibits consumption of blood","all grape varieties are restricted","all types of shellfish are forbidden"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:40:39.613Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:40:39.613Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:40:39.613Z"'::jsonb),
('anki-card-1755155850133-107', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The following are spices EXCEPT:', 'Chives', 'Chives are classified as a culinary herb. They are the green, aromatic leaves of the plant (Allium schoenoprasum), used fresh or dried to add a mild onion-like flavor to dishes.

Cardamom, nutmeg, and sage are classified in culinary contexts as spices or flavoring botanicals according to the plant part and use.', '["Chives","Cardamom","Nutmeg","Sage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:49:27.020Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:49:27.020Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:49:27.020Z"'::jsonb),
('anki-card-1755155892030-108', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The following statements help conserve nutrients in preparation and cooking, EXCEPT:', 'thaw frozen vegetables before cooking', 'You should never thaw frozen vegetables before cooking them. Thawing frozen vegetables allows their cell walls to collapse as they soften, causing water-soluble vitamins (such as Vitamin C and B-complex vitamins) to leach out into the liquid runoff, which is then discarded. To conserve the highest amount of nutrients, frozen vegetables should be cooked straight from the frozen state by steaming or dropping them directly into boiling water.

The other practices help conserve nutrients by minimizing leaching and excessive cooking.', '["foods should not be stirred","thaw frozen vegetables before cooking","baking soda should not be added","pots should be kept covered"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:14.578Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:51:14.578Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:14.578Z"'::jsonb),
('anki-card-1755155928127-109', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Considered as the best conductor of heat, this type of cookware material is commonly used as base for non-stick pans.', 'Copper', 'Aluminum: Lightweight, budget-friendly, heats quickly, and serves as the standard body or base for most non-stick cookware.

Copper: The absolute best heat conductor among common cookware metals, but it is expensive and rarely used as a cheap non-stick base.

Iron: Retains heat well but conducts slowly and is heavy.

Stainless steel: A poor direct conductor of heat, usually requiring an aluminum or copper core.', '["Aluminum","Iron","Copper","Stainless steel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:46:43.926Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:46:43.926Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:46:43.926Z"'::jsonb),
('anki-card-1755155964192-110', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'All of the following are nuts EXCEPT:', 'Munggo', 'Munggo is a legume, not a culinary nut. 

Kastanyas, pili, and coconut are commonly classified or used as nuts.', '["Kastanyas","Munggo","Pili","Coconut"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:58:08.433Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:58:08.433Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:58:08.433Z"'::jsonb),
('anki-card-1755155988475-111', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Dish made of dried gabi leaves, coconut milk, siling labuyo, and bagoong.', 'Laing', 'Laing is an iconic Bicolano dish composed fundamentally of shredded dried gabi (taro) leaves, simmered slowly in creamy coconut milk (gata).

It is heavily spiced with sliced siling labuyo (bird''s eye chili) and seasoned with bagoong alamang (shrimp paste) along with pork or dried fish (daing) to give it its hallmark spicy and deeply savory profile. It is a culinary standard that the leaves must be completely dried before cooking to prevent the calcium oxalate crystals in the taro plants from causing an itchy sensation in the mouth.

• Pinangat: Also a famous taro leaf delicacy from Bicol (specifically Camalig, Albay), but it is distinctly made by wrapping a mixture of pork, shrimp, and young coconut meat inside layered pouches of fresh, whole gabi leaves before tying them with string and steaming them in seasoned coconut milk.
• Sinanglay: Another Bicolano coconut-milk-based favorite, but its centerpiece is whole fresh fish (like tilapia) stuffed with tomatoes and onions, which is then wrapped in fresh gabi or mustard leaves and cooked in spiced gata.
• Tinimtim: A traditional Ilocano dish primarily featuring saluyot (jute leaves) or ampalaya leaves simmered with garlic, vinegar, and bagoong. It does not utilize gabi leaves or coconut milk as core components.', '["Laing","Tinimtim","Pinangat","Sinanglay"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:51:18.627Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:51:18.627Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:51:18.627Z"'::jsonb),
('anki-card-1755156014590-112', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Aterm used for the Filipino cooking method of wrapping food in leaves', 'All of the above', 'Pinais refers to wrapping food in banana leaves and sometimes inner layers of kamamba (Piper umbellatum) or taro leaves before being cooked in coconut milk or steamed. 

Binagol is a sweet, dense kakanin (rice cake delicacy) from Leyte. It is made from grated gabi (taro root), condensed milk, and sugar, which is packed into a halved coconut shell (baong), wrapped in banana leaves, and securely tied before being steamed.

Binalot means "wrapped" in the Filipino language and refers to a traditional style of serving a complete meal wrapped inside a banana leaf.', '["Binalot","Binagol","Pinais","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:49:04.342Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:49:04.342Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:49:04.342Z"'::jsonb),
('anki-card-1755156050955-113', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A popular dish from Davao and other parts of Mindanao that features internal organs cooked with pineapple and bell peppers.', 'Paklay', 'Paklay is a renowned traditional stew popular across the Visayas and Mindanao regions (especially in Davao and Cebu). It is made from a combination of sliced pork, beef, or goat internal organs (such as tripe, liver, heart, and kidneys) sautéed with ginger, bamboo shoots, bell peppers, and pineapple chunks. The pineapple plays a vital role by lending a subtle, refreshing sweetness and acidity that balances the rich, robust flavor of the offal.

• Sampayna: This is a Northern Mindanao (specifically Camiguin and Cagayan de Oro) variation of dinuguan (pork blood stew). It uses chitterlings and blood but does not feature the sweet pineapple or stir-fried bell pepper profile profile of paklay.
• Barbacoa: In a local context, this often sounds like Balbacua, a very popular viscous beef skin and trotters stew from Southern Mindanao that is slow-cooked with star anise and annatto rather than internal organs and fruit.
• Tiolah Sapi: A festive, sacred beef broth dish native to the Tausug people of the Sulu Archipelago in Mindanao. It features beef and tripe seared in burnt coconut paste (pamapa), giving it a signature green color and lemongrass-ginger profile, but it does not use pineapple.', '["Barbacoa","Sampayna","Paklay","Tiolah Sapi"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:45:29.767Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:45:29.767Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:45:29.767Z"'::jsonb),
('anki-card-1755156074537-114', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The Visayan version of Paksiw na Isda', 'Inun-unan', 'Inun-unan is a classic Visayan fish dish cooked in vinegar, ginger, garlic, onions, and chili peppers. It is the direct Visayan counterpart to the Tagalog Paksiw na Isda, with the traditional distinction that Inun-unan typically does not include any water, soy sauce, or vegetables like eggplant and ampalaya, making the vinegar and ginger profile much sharper.

• Higado: A traditional Ilocano savory dish made from pork tenderloin, pig liver, and other innards cooked with bell peppers, green peas, and vinegar.
• Lininta: A traditional Muslim-Filipino (Maranao) dish where fish is marinated with palapa (a spicy condiment made from native scallions, ginger, and chili), wrapped securely in banana leaves, and then steamed.
• Utan: A general Visayan term for vegetable soup or vegetable dishes (most commonly Utan Bisaya, a clear vegetable broth loaded with leafy greens, squash, okra, and fried/grilled fish).', '["Lininta","Utan","Inun-unan","Higado"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:46:26.647Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:46:26.647Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:46:26.647Z"'::jsonb),
('anki-card-1755156134767-115', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Clearing of the bread and butter plate is done at the __________________.', 'Left of the guest', 'Bread-and-butter plates are conventionally cleared from the guest''s left because they are placed on the left side of the cover.', '["Right of the guest","Left of the guest","Both a and b","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:25:44.706Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:25:44.706Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:25:44.706Z"'::jsonb),
('anki-card-1755156163118-116', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The specific amount of product from the recipe in volume, weight, or number of servings.', 'yield', 'Yield is the specific amount of finished product obtained from a recipe, expressed as weight, volume, or number of portions.', '["trim loss","edible portion","yield factor","yield"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:32:06.881Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:32:06.881Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:32:07.074Z"'::jsonb),
('anki-card-1755156195932-117', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The cost of materials that go directly into the production of the menu item.', 'food cost', 'Food cost is the cost of materials that directly enter into the production of a menu item; overhead costs are indirect operating expenses.', '["edible portion cost","as purchased cost","food cost","overhead cost"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:25:25.809Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:25:25.809Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:25:25.809Z"'::jsonb),
('anki-card-1755156222148-118', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'In storing fruits, the following practices delay the ripening process EXCEPT:', 'wrapping fruits in newspaper', 'Wrapping unpeeled, whole fruits in newspaper accelerates ripening by trapping natural ethylene gas. It is also unsafe because toxic printing inks, heavy metals, and harmful chemicals leach directly into your food, especially when it is hot or oily.

Delays the ripening process:
• Separating ripe from unripe fruit slows ethylene exposure and delays ripening. 
• Refrigeration delays ripening process by slowing down enzyme activity.
• Wrapping in PET bags: Produce packaging often uses specific polymer films with micro-perforations or special barrier properties to let excess ethylene and carbon dioxide escape. This stops moisture buildup and prevents rapid decay.', '["storing fruits inside the refrigerator","wrapping fruits in newspaper","wrapping fruits in polyethylene bags","separating the ripe from the unripe"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:47:42.171Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:47:42.171Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:47:42.171Z"'::jsonb),
('anki-card-1755156283127-119', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Service style with table side service, EXCEPT:', 'American', 'In hospitality and food service management, American service (also commonly known as plate service) is explicitly defined as a style where food is completely portioned, arranged, and plated onto individual dishes inside the kitchen by the chefs. The waitstaff then carries these pre-plated meals directly out to the dining tables to serve the guests. Because everything is completed back in the kitchen, it involves absolutely no tableside assembly, carving, or serving from platters.

• Russian Service: Servers bring heavy silver platters containing large portions of food directly out to the dining room. They then walk around the table and use a spoon and fork to serve individual portions onto the guests'' empty plates tableside.
• French Service: This is the ultimate tableside service style. Food is brought out partially raw or undercooked on a rolling cart called a gueridon. Cooking, finishing (like flambéing), carving, and plating are executed right next to the guests'' seats.
• English Service: Large platters and tureens of food are placed directly onto the dining table right in front of the host. The host then carves the meat and portions the sides onto plates at the table, which are then passed down or distributed by the servers.', '["English","Russian","French","American"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:49:49.578Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:49:49.578Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:49:49.578Z"'::jsonb),
('anki-card-1755156329475-120', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Type of service where food is prepared in the kitchen and carried in serving platters while the waitstaff serves all the guests.', 'Continental', 'Continental Service (also widely known as Russian Service or platter service) is a formal style of dining where all food is fully cooked, portioned, and arranged beautifully on serving platters inside the kitchen.

The waitstaff then carries these platters into the dining room and serves each guest individually from the platter onto their plates. 

• Country-style (or American/Family-style) involves placing large serving dishes on the table for guests to pass around and serve themselves. 
• Plated (or American Service) features food that is already portioned and arranged onto individual plates in the kitchen before being served. 
• Compromise is a hybrid service style where some courses are served directly from the kitchen and others are served at the table by the host or passed around.', '["Country-Style","Plated","Continental","Compromise"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T14:55:09.189Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T14:55:09.189Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T14:55:09.189Z"'::jsonb),
('anki-card-1755156351540-121', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The following tasks are done from the left of the guest, EXCEPT:', 'setting and clearing of dinner plates', 'Dinner plates are served and cleared from the right side. All other options are presented and cleared from the left side of the guest.', '["setting and clearing of dinner plates","presenting and serving from platters","clearing of bread and butter plate","serving salad"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:13:17.116Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:13:17.116Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:13:17.116Z"'::jsonb),
('anki-card-1755156381173-122', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The following tasks are done from the right of the guest, EXCEPT:', 'serving bread', 'Bread is conventionally served from the left, whereas flatware and beverage ware are generally placed, served, or cleared from the right.', '["laying of flatware","serving bread","setting and clearing of beverage ware","pouring of beverage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:24:54.848Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:24:54.848Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:24:54.848Z"'::jsonb),
('anki-card-1755156411788-123', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Fast Food combo meals are', 'Semi a la carte', 'Semi a la carte is when an entrée or main item is bundled together with specific side dishes (such as French fries and a beverage) and sold at a single, combined price. 

• Ala carte: Items are listed and priced completely separate from one another.
• Table d''Hote: This refers to a complete multi-course meal (from appetizer, soup, to main course, and dessert) served at a fixed total price with some options in some categories, usually found in banquets or fine dining rather than fast food.', '["Ala carte menus","Semi a la carte","Table d’Hote","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:52:14.647Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T16:52:14.647Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:52:14.647Z"'::jsonb),
('anki-card-1755156460303-124', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The sum of the sides of a work triangle must not exceed:', 'both a and b', 'The kitchen work triangle is an efficiency design principle that connects the three main work areas: the sink, the stove, and the refrigerator.

According to traditional residential space planning and board exam standards, the total perimeter (the sum of all three sides) should ideally be between 12 to 22 feet.

When converting 22 feet into the metric system (22 x 0.3048), it equals approximately 6.7 meters.', '["22 ft","6.5m","both a and b","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:43:23.383Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:43:23.383Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:43:23.383Z"'::jsonb),
('anki-card-1755156497500-125', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The most important work center is the __________.', 'sink', 'The sink is commonly regarded as the most important work center because food preparation and cleanup require frequent access to water.', '["sink","gas range","refrigerator","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:02:56.861Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:02:56.861Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:02:56.861Z"'::jsonb),
('anki-card-1755156522284-126', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Size of dinner napkin:', '18-26 inches', 'The standard size for a dinner napkin is 18-26 inches (typically spanning 18–20 inches square for informal or everyday use, though formal dinner napkins can range up to 20–26 inches). 

• Informal / Everyday Dinner: 18 to 20 inches square
• Formal / Multi-Course Dinner: 20 to 26 inches square
• Purpose: Large enough to unfold and cover the lap completely', '["24-30 inches","9-12 inches","20-24 inches","18-26 inches"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:40.856Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T16:51:40.856Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:40.856Z"'::jsonb),
('anki-card-1755156542081-127', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'This type of kitchen arrangement allows the refrigerator, range, and sink to be spaced out for efficiency and convenience:', 'U-shaped', 'The U-shaped kitchen layout spans across three adjacent walls. Because it utilizes three separate surfaces, it is considered the most efficient arrangement for maximizing the work triangle. It perfectly allows the refrigerator, range, and sink to be widely spaced out on their own designated walls. This spacing provides dedicated counter segments around each major appliance, creating optimal flow, reducing traffic interference, and making meal prep highly convenient.

• Single line: Places all three major appliances flat against a single wall. This forces an assembly-line setup where components are crammed tightly together rather than being broadly spaced out.
• Island type: Adds a detached island workstation to an existing configuration. While highly versatile, the island itself does not inherently dictate the baseline spacing of the main three appliances.
• L-shaped: Spreads the work area along two perpendicular walls. While highly efficient for open floor plans, it forces at least two of the three main appliances to share a single wall line, making it less spaced out than a full three-walled U-shape.', '["single line","L-shaped","U-shaped","island type"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:56:13.354Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:56:13.354Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:56:13.354Z"'::jsonb),
('anki-card-1755156584596-128', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A set meal with a choice within menu categories is called:', 'table d''hote', 'Table d’hote is a fixed-price, multi-course meal where guests select from a limited number of choices within specific categories (like appetizer, main, and dessert). 

• Semi à la carte: A menu type where some items (usually the main entree) are priced individually, but automatically include specific side components (like a soup, salad, or potato) at no extra charge.
• Prix Fixe: A similar fixed-price menu concept with no choices.', '["table d''hote","prix fixe","semi a la carte","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:49:22.684Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:49:22.684Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:49:22.684Z"'::jsonb),
('anki-card-1755156623094-129', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The following are all vegetable dishes EXCEPT:', 'None of the above', 'Laswa, bulanglang, and utan are vegetable dishes.

• Laswa: A famous, clear-broth vegetable soup native to the Western Visayas (Iloilo). It is packed with local vegetables like okra, saluyot, squash, and eggplant, and seasoned simply with salt or fish sauce.
• Utan: The native Visayan and Mindanao term for a clear, healthy vegetable broth (most commonly Utan Bisaya or Utan Kamunggay), featuring leafy greens, squash, and root vegetables.
• Bulanglang: A traditional Southern Tagalog (specifically Batangas) vegetable stew made by boiling a medley of local crops like calabaza squash, okra, sitaw, and moringa leaves in rice-washing water seasoned with bagoong.', '["Laswa","Bulanglang","Utan","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:42:52.707Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:42:52.707Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:42:52.707Z"'::jsonb),
('anki-card-1755156657429-130', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The following are all noodle dishes, EXCEPT:', 'Picadillo', 'Picadillo is a savory, traditional ground meat dish found in Spain and Latin America. In the Philippines, Picadillo is known locally as giniling, it is often cooked as a hearty soup or dry sauté with diced potatoes, carrots, and green peas and served over steamed white rice or as arroz a la cubana alongside a fried egg.

• La Paz Batchoy: A legendary Filipino noodle soup that originated in the district of La Paz, Iloilo City. It is made with fresh egg noodles (miki), a rich pork and shrimp paste (ginamos) broth, sliced pork innards, and a heavy topping of crushed pork cracklings (chicharon).
• Bami: Also known as Pancit Bami, this is a classic Visayan (particularly Cebuano) stir-fried noodle dish. It features a unique combination of two types of noodles tossed together: thick egg noodles (miki) and translucent mung bean thread noodles (sotanghon).
• Laksa: A widely popular Southeast Asian spicy noodle soup predominant in Peranakan cuisine (Malaysia, Singapore, and Indonesia). It features thick rice noodles submerged in either a rich, fiery coconut curry broth or a sour, tamarind-based fish broth.', '["Bami","La Paz Batchoy","Laksa","Picadillo"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:39:49.436Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:39:49.436Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:39:49.436Z"'::jsonb),
('anki-card-1755156675260-131', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A dish of rice, ground pork and bananas.', 'Arroz a la Cubana', 'Arroz a la Cubana (literally "Cuban-style rice") is a classic comfort dish that is highly popular in Filipino cuisine. It traditionally consists of a visual layout featuring a mound of white rice, a savory ground meat hash (picadillo/giniling usually made with ground pork or beef sautéed with raisins and peas), fried saba bananas (plantains), and a fried egg.

• Paella: A famous Spanish rice dish cooked in a wide, shallow pan, typically flavored with saffron and loaded with seafood, chicken, and vegetables.
• Torta: In Filipino cuisine, a torta refers to an omelet or pan-fried patty (such as tortang talong made with eggplant, or tortang giniling made with ground meat mixed into beaten eggs). It is not served as a specific configuration of rice and bananas.
• Arroz Valenciana: A traditional Filipino festive rice dish heavily influenced by Spanish paella. It features glutinous (sticky) rice cooked with coconut milk, turmeric (or annatto oil), chicken, chorizo, and boiled eggs, but it does not feature ground meat or fried bananas.', '["Arroz Valenciana","Torta","Arroz a la Cubana","Paella"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:33:39.327Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:33:39.327Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:33:39.504Z"'::jsonb),
('anki-card-1755156701159-132', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Tsokolate espeso refers to:', 'thick chocolate drink', 'In Filipino culinary tradition (heavily influenced by Spanish terminology), the word espeso translates to "thick" or "dense." Therefore, Tsokolate Espeso refers to a rich, velvety, and thick hot chocolate beverage traditionally prepared by melting pure cacao tablets (tabliya) in a special copper pitcher called a tsokolatera and frothing it vigorously with a wooden whisk called a batidor.

• Café Mocha / Mochaccino: These are espresso-based coffee drinks that combine milk and chocolate syrup or cocoa powder. They are not purely cacao-based.
• Thin chocolate drink: A thin, lighter version of traditional hot chocolate is instead called Tsokolate Ahon (or tsokolate aguado, meaning watery).', '["Café Mocha","Mochaccino","thick chocolate drink","thin chocolate drink"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:36:44.689Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:36:44.689Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:36:44.689Z"'::jsonb),
('anki-card-1755156722873-133', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Churros is more like which Filipino fritter', 'Bitso-bitso', 'Churros are closest in form to bitso-bitso, a fried Filipino dough snack, rather than vegetable fritters or toasted bread products.

 Classic Filipino bitso-bitso is made by twisting or shaping yeast- or flour-based dough into sticks, deep-frying them until golden and crisp, and then dusting them with white sugar or coating them in a caramel glaze. It mirrors the exact preparation mechanism and eating experience of a Spanish churro.

• Biscocho: A twice-baked, crunchy Filipino bread topper (similar to biscotti or melba toast) that is brushed with butter and sugar. It is baked dry until crisp, not deep-fried.
• Gurgurya: A small, hard, shell-like Filipino pastry or cookie that is deep-fried and then coated in a sugary glaze. While fried, it has a dense, hard cookie crunch rather than the soft-on-the-inside, crisp-on-the-outside structural profile of a churro.
• Okoy: A distinctly savory Filipino street food fritter made of shredded vegetables, bean sprouts, and small whole shrimp tossed in an egg-and-flour batter and fried flat.', '["Okoy","Gurgurya","Biscocho","Bitso-bitso"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:26:34.591Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:26:34.591Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:26:34.591Z"'::jsonb),
('anki-card-1755156750738-134', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Filipino dish traditionally made of chicken, rice washing, green papaya, pepper leaves, and ginger.', 'Tinola', 'Tinola (specifically Tinolang Manok) is a traditional Filipino soup that serves as the quintessential comfort food. It features chicken pieces simmered in rice washing (the water saved from rinsing raw rice, which acts as a starchy, flavorful broth base) heavily flavored with crushed ginger, garlic, and onions. It is traditionally garnished with wedged green papaya (or chayote) and fresh chili pepper leaves (siling labuyo leaves).

• Suam: A traditional Kapampangan soup (like Suam na Mais) made with shredded sweet corn, meat, and spinach or chili leaves. While it uses ginger and rice washing, its main structural component is corn rather than a clear chicken broth with papaya.
• Pesa: A ginger-based fish or chicken stew (like Pesang Dalag) that is cooked with cabbage, potatoes, pechay, and whole black peppercorns. It is traditionally served alongside a side dipping sauce made of fermented soybean cake (miso).
• Nilaga: A broad term for a boiled Filipino meat soup (usually beef or pork). While it features a clear broth, it is seasoned predominantly with whole black peppercorns and onions rather than a heavy ginger base, and it uses vegetables like cabbage, pechay, potatoes, and saba bananas.', '["Suam","Tinola","Pesa","Nilaga"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:50:24.817Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:50:24.817Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:50:24.996Z"'::jsonb),
('anki-card-1755156782804-135', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Type of menu where the entrée is combined and priced with other items such as salad, starch, and/or beverage.', 'Semi a la carte', 'Semi à la carte menus combine an entrée with other selected items, while à la carte prices items separately and table d''hôte offers a complete meal for one price.', '["A la carte","Semi a la carte","Table d'' Hote","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:43:28.284Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:43:28.284Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:43:28.284Z"'::jsonb),
('anki-card-1755156810836-136', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A food or group of foods served at one time or intended to be eaten at the same time is called:', 'Course', 'A course is a food or group of foods served or intended to be eaten at one time;

A menu is the list of offerings. 

A meal is an occasion when food is eaten.', '["Menu","Meal","Course","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:43:54.136Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:43:54.136Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:43:54.136Z"'::jsonb),
('anki-card-1755156837450-137', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Type of menu usually used in schools, hospitals, and institutions is called:', 'None of the above', 'Schools, hospitals, and institutional facilities primarily use a cycle menu (or cyclic menu).', '["Table d'' Hote","Single use","Du jour","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:43:35.434Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:43:35.434Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:43:35.434Z"'::jsonb),
('anki-card-1755156861968-138', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Which should you start planning for first?', 'Entrée', 'Meal planning generally starts with the entrée because it is usually the focal point around which the remaining meal components are selected.

The main dish dictates the overall flavor profile of the meal. Once the entrée is selected, you can curate appetizers, soups, and salads that complement, cleanse the palate for, or contrast its flavor notes instead of competing with them.', '["Entrée","Salads","Appetizer","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T15:55:30.641Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T15:55:30.641Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T15:55:30.641Z"'::jsonb),
('anki-card-1755156886566-139', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Which of the following is arranged according to the prescribed menu pattern for lunch?', 'Chicken Pastel, Steamed Broccoli, Saffron Rice, Jasmine Tea', 'The conventional menu sequence for lunch presents the food items in a specific sequential order:

1. Soup or Appetizer (if included)
2. Main Course / Protein (Chicken Pastel)
3. Vegetables or Salad (Steamed Broccoli)
4. Cereal or Rice (Saffron Rice)
5. Dessert (if included)
6. Beverage (Jasmine Tea)', '["Chicken Pastel, Steamed Broccoli, Saffron Rice, Jasmine Tea","Jasmine Tea, Chicken Pastel, Steamed Broccoli, Saffron Rice","Chicken Pastel, Saffron Rice, Steamed Broccoli, Jasmine Tea","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:32.310Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:51:32.310Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:32.310Z"'::jsonb),
('anki-card-1755156914716-140', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The last recommended day of retail sale is referred to as:', 'pull date', 'A pull date is the last recommended date for retail display or sale before the product should be removed from shelves.

• Expiration: This is the last date on which the product should be used or consumed. It is often used for products where safety is a concern, indicating that after this date, the product may no longer be safe to consume.
• Best before and Freshness Date: both indicate the last date recommended for the use of the product at its peak quality. It does not refer to safety but rather optimal quality.', '["expiration date","freshness date","pull date","best before date"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:17.810Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:51:17.810Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:17.810Z"'::jsonb),
('anki-card-1755156941362-141', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'The size of one cover is preferably:', '24 inches', 'One cover is preferably about 24 inches of table space to provide adequate room for place settings and service.', '["18 inches","24 inches","21 inches","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:51:49.370Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-22T16:51:49.370Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:51:49.370Z"'::jsonb),
('anki-card-1755156962247-142', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A recipe of Buffalo Wings makes 30 pcs (3 servings). What would you do to lower the food cost of the menu item?', 'Make the portion size 6 pcs/serving', 'Reducing the number of pieces per plate from 10 pieces down to 6 pieces uses fewer raw ingredients per order. Using fewer chicken wings directly decreases the cost to make each individual plate.

• 15 pcs/serving: Increasing the portion size uses more ingredients, which raises the food cost per plate.
• Prefabricated products: Pre-made or pre-cut items usually cost more because you pay extra for the supplier''s labor.', '["Make the portion size 6 pcs/serving","Make the portion size 15 pcs/serving","Use prefabricated products","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:43:12.245Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:43:12.245Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:43:12.245Z"'::jsonb),
('anki-card-1755156994027-143', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A menu item that sells for P70.00 has a food cost percent of 20%. What would the food cost percent be if the selling price was increased to P150.00?', '9.3%', 'Original Food Cost Percentage (Php70.00x 0.2 = 14.00 PHP)

New FCP= (Food Cost/New SP) x100

New FCP = (14.00/150.00) x 100 = 9.3%', '["10.3%","11.3%","8.3%","9.3%"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T11:23:50.978Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T11:23:50.978Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T11:23:50.978Z"'::jsonb),
('anki-card-1755157026625-144', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Your recipe calls for 3 kg diced carrots. If a vendor sells a 10 kg case of carrots for P499.00, how much will the carrots purchased for this recipe cost? Yield percent of carrots is 81.3%', 'P184.13', 'The edible yield required is 3 kg. 

With an 81.3% yield, the as-purchased quantity needed is 3 ÷ 0.813 ≈ 3.69 kg. 

At ₱499 per 10 kg, the cost is approximately ₱184.13.', '["P149.70","P184.13","P121.70","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:49:04.541Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:49:04.541Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:49:04.541Z"'::jsonb),
('anki-card-1755157058524-145', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'You have a béarnaise recipe that makes seven 14-gram portions but you need to make enough to have twenty 8-gram portions. What is the recipe conversion factor?', '1.63', 'Original yield is 7 × 14 g = 98 g. 

Required yield is 20 × 8 g = 160 g. 

The conversion factor is 160 ÷ 98 ≈ 1.63.', '["0.61","1.63","0.57","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:46:19.224Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-22T16:46:19.224Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:46:19.224Z"'::jsonb),
('anki-card-1755157090789-146', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A salsa recipe calls for 3 oz chopped fresh cilantro to serve 48 guests. If chopped cilantro gives a 48% yield, how many servings of salsa can you make using 1 ½ lbs of cilantro you have purchased?', '184 servings', '1 ½ lb equals 24 oz AP. At 48% yield, usable cilantro is 11.52 oz. 

At 3 oz per 48 guests, this is about 184 servings.', '["11 servings","12 servings","184 servings","194 servings"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:56:19.678Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:56:19.678Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:56:19.866Z"'::jsonb),
('anki-card-1755157133022-147', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Tea-like beverage using herbs/plants other than Camella sinensis', 'Tisanes', 'Tisanes, commonly known as herbal teas, are beverages made from the infusion or decoction of herbs, spices, fruits, or other plant material in hot water. Unlike true teas (such as Oolong and Sencha), they do not contain leaves from the Camellia sinensis plant.', '["Oolong","Tea imitations","Tisanes","Sencha"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T13:23:04.276Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T13:23:04.276Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T13:23:04.467Z"'::jsonb),
('anki-card-1755157158519-148', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'Café au lait is similar to which Italian coffee concoction', 'Caffe Latte', 'Café au lait is coffee served with hot milk and is most similar to caffè latte in the Italian coffee family. It is made by mixing equal parts of strongly brewed coffee (often from a French press or drip filter) and steamed milk.

• Macchiato: An espresso shot "stained" or marked with just a tiny dollop of frothed milk or foam on top, making it significantly stronger and less milky than a latte.
• Ristretto: A short, highly concentrated shot of espresso extracted with half the amount of water but using the same amount of coffee grounds, resulting in a sweeter, richer flavor.
• Espresso: A concentrated, full-bodied coffee shot brewed by forcing hot water under high pressure through finely-ground coffee beans. It contains no milk at all.', '["Espresso","Macchiato","Caffe Latte","Ristretto"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T16:27:59.639Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T16:27:59.639Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T16:27:59.639Z"'::jsonb),
('anki-card-1755157194385-149', NULL, 'anki-deck-1755151710403-1790432463944-n11t8', 'A detailed work plan showing the arrangement of equipment is called:', 'Layout', 'A layout is a detailed work plan showing the physical arrangement of equipment and work areas. 

A blueprint is a technical drawing, while specifications describe requirements.', '["Blueprint","Specifications","Design","Layout"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-23T12:06:35.329Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-22T12:06:35.329Z"'::jsonb, '"2026-09-26T14:32:34.718Z"'::jsonb, '"2026-10-22T12:06:35.329Z"'::jsonb)
