('anki-card-1758690636730-47', NULL, 'anki-deck-1758689429896-1790185671252', 'If the body is lacking an essential amino acid (EAA), what will be the course of action? *', 'Protein synthesis will be limited.', 'Protein synthesis will be limited.', '["Protein synthesis will be limited.","Health will not be affected as long as other nutrients are adequate.","Proteins will be made but they will lack that particular EAA.","Body cells will synthesize the EAA."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:38:00.332Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:38:00.332Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758690665244-48', NULL, 'anki-deck-1758689429896-1790185671252', 'The following are characteristics of vitamin D nutrition except: *', 'The requirement is increased in most people who are exposed to the sun.', 'It informs the community of the type of intervention that will be implemented.', '["Excessive intake may lead to mineral deposits in the kidney.","Deficient intake may lead to altered bone composition.","Fortified milk is a dietary source of vitamin D.","The requirement is increased in most people who are exposed to the sun."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:41:56.704Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:41:56.704Z"'::jsonb, '"2026-09-23T17:47:52.013Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
