('anki-card-1758693135046-163', NULL, 'anki-deck-1758689429896-1790185671252', 'A digestible meal of several food items contains 70 g CHO, 25 g Fat, 20 g PRO and 45 g alcohol. Assuming 100% of this food energy can be utilized, calculate the approximate total yield of energy. *', '900 kcal', '', '["640 kcal","815 kcal","900 kcal","990 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-01T12:06:21.511Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-09-28T12:06:21.511Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T12:06:21.721Z"'::jsonb),
('anki-card-1758693152446-164', NULL, 'anki-deck-1758689429896-1790185671252', 'Dietary recommendation/s for patients with nephritic syndrome: *', 'Na restriction', '', '["Ca & K restriction","a high protein intake","Na restriction","fluid restriction"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T10:40:16.570Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-09-28T10:40:16.570Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T10:40:16.570Z"'::jsonb),
('anki-card-1758693167078-165', NULL, 'anki-deck-1758689429896-1790185671252', 'It is the surgical creation of an opening from the body surface to the intestinal tract to allow defecation: *', 'ileostomy', '', '["ileostomy","enterocutaneous fistula","stoma","fistula"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-29T11:47:11.365Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-28T11:47:11.365Z"'::jsonb, '"2026-09-23T17:47:52.169Z"'::jsonb, '"2026-09-28T11:47:11.365Z"'::jsonb),
