('anki-card-1754881832392-14', NULL, 'anki-deck-1783608681588-1790433140276-5f3w7', 'The Vit. A recommendation in PDRI for an 11 year old male and female is:', 'the same', '', '["the same","male has higher recommendation","female has higher recommendation","not comparable"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-12T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.763Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
