('anki-card-1757848614201-78', NULL, 'anki-deck-1783608745420-1790433140510-u6mf8', 'The following are included in the Four P’s of Marketing, except:', 'none of the above', 'The traditional Four P''s of Marketing are Product, Price, Place, and Promotion. Since all listed options are true components of the marketing mix, "none of the above" is the correct key.', '["Place","Price","Promotion","none of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T08:06:13.088Z"'::jsonb),
('anki-card-1757848633748-79', NULL, 'anki-deck-1783608745420-1790433140510-u6mf8', 'They are the people to whom behaviour change is desired:', 'Target groups', 'Target groups refer specifically to the primary population segment whose behavior change, knowledge, or practices the program seeks to influence.

