('anki-card-1758609280363-49', NULL, 'anki-deck-1783608770143-1790433142615-evxfc', 'Evaluation- the ability to judge a material according to its purpose belongs to*', 'Cognitive', '', '["Cognitive","Affective","Psychomotor","Cognitive-Affective"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T03:47:09.535Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T03:47:09.535Z"'::jsonb, '"2026-09-26T14:32:28.626Z"'::jsonb, '"2026-11-07T03:47:09.535Z"'::jsonb),
('anki-card-1758683922876-0', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The condition of the body resulting from the utilization of nutrients made available to the body. *', 'nutritional status', 'Nutritional status is defined as the physiological state of an individual resulting from the ingestion, absorption, and cellular utilization of essential nutrients.', '["health","nutritional status","physical fitness","wellness"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.160Z"'::jsonb, '"2026-11-09T09:05:46.323Z"'::jsonb),
('anki-card-1758683936539-1', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A pathological state resulting from the consumption of an inadequate amount of food over an extended period of time. *', 'undernutrition', 'Undernutrition is a pathological state resulting from the consumption of an inadequate quantity or quality of food over an extended period.', '["imbalance","overnutrition","undernutrition","specific nutrient deficiency"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.160Z"'::jsonb, '"2026-11-09T09:05:50.586Z"'::jsonb),
('anki-card-1758683952320-2', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'It is the science and art of preventing disease, prolonging life, and promoting health through organized community effort. *', 'public health', 'Public health is the formal definition describing the science and art of preventing disease, prolonging life, and promoting health through organized community-wide efforts.', '["public health","public health nutrition","community nutrition","public health promotion"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.160Z"'::jsonb, '"2026-11-09T09:05:55.099Z"'::jsonb)
