INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758685998076-153', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A study will be conducted to test the effects on the fat content of fried chicken using two different frying techniques. The appropriate research design to use is: *', 'experimental research', 'Testing the effects of two different frying techniques on the fat content of fried chicken involves active manipulation of independent variables under controlled conditions, classifying it as experimental research.

• Correlational / Observational / Descriptive: Lack active variable manipulation.', '["experimental research","correlational research","observation studies","descriptive survey"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:00:29.403Z"'::jsonb),
('anki-card-1758686012309-154', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Lecture is a method of teaching with good audience participation. It allows the educator to give more information in a short period of time. *', 'The first statement is incorrect but the second statement is correct.', 'Statement 1 is incorrect because a standard lecture format typically offers poor audience participation (one-way communication). 

Statement 2 is correct because lectures allow educators to deliver a large volume of information to a large group in a short period of time.', '["Both statements are correct.","The first statement is incorrect but the second statement is correct.","The first statement is correct but the second statement is incorrect.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:00:36.628Z"'::jsonb),
('anki-card-1758686021241-155', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'With advancing age, energy needs decline due to the following reasons except: *', 'Older people absorb energy from foods better.', 'Older adults generally experience reduced digestive efficiency and nutrient absorption alongside decreased BMR and lower physical activity, making the claim of better energy absorption false (and thus the correct exception).', '["Older people usually have reduced physical activity.","Basal metabolic rate decreases as people age.","Lean body mass diminishes as people age.","Older people absorb energy from foods better."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:00:41.888Z"'::jsonb),
('anki-card-1758686031891-156', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'It is a useful information in monitoring mothers’ participation in a feeding program with a nutrition class. *', 'change in weight of children', 'The ultimate biological and programmatic indicator for monitoring the success of a community feeding program combined with a nutrition class is tracking the positive change in weight and growth of the children.', '["change in weight of children","mothers’ participation during cooking","mothers’ regular attendance","the contributions mothers give"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:00:45.934Z"'::jsonb),
('anki-card-1758686041071-157', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The type of evaluation performed when information is collected on whether the right targets are getting involved in the nutrition project: *', 'Process evaluation', 'Process evaluation monitors operational delivery and collects data to determine whether the intended target groups are actually attending and getting involved in the nutrition project.

• Outcome / Impact evaluation: Assess medium-term or long-term behavioral and health results.', '["Outcome evaluation","Impact evaluation","Process evaluation","Summative evaluation"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:00:50.513Z"'::jsonb),
('anki-card-1758686058176-158', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Which of the following statements is not correct? *', 'An early sign of VAD flaky paint dermatitis.', 'Flaky paint dermatitis is a physical sign of severe protein-energy malnutrition (Kwashiorkor), not Vitamin A deficiency, making this statement false (and thus the correct exception).

• Xerophthalmia / Liver vitamin depletion / Night blindness: Classic signs and pathophysiology of Vitamin A deficiency.', '["Xerophthalmia refers to all ocular signs of vitamin A deficiency.","Vitamin A deficiency occurs when vitamin’s reserves in the liver become depleted.","Night blindness is common among women of reproductive age and among under 5 children.","An early sign of VAD flaky paint dermatitis."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:00:56.065Z"'::jsonb),
('anki-card-1758686079889-159', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'What is the edible portion weight of ½ kilo of yellow mango with a 56% edible portion? *', '280 g', 'To calculate Edible Portion (EP) weight:

Formula = Total As-Purchased (AP) Weight × EP Percentage.

Given values: AP Weight = 500 g (1/2 kilo); EP % = 56% (0.56).

Calculation = 500 g × 0.56 = 280 g.', '["350 g","280 g","580 g","250 g"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:01:00.814Z"'::jsonb),
('anki-card-1758686091690-160', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The vegetable oils used to replace the butterfat of cow’s milk in manufacturing evaporated milk: *', 'coconut and corn oils', 'In commercial manufacturing of filled or evaporated milk substitutes, butterfat is replaced using a blend of vegetable oils, classically including coconut and corn oils.', '["coconut and soybean oils","coconut and peanut oils","coconut and corn oils","coconut and olive oils"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:01:06.040Z"'::jsonb),
('anki-card-1758686113589-161', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A mother who attended a mothers’ class 6 months ago said she is now using the Food Pyramid in planning her family meals. What type of evaluation was used? *', 'Impact evaluation', 'When a mother reports utilizing the Food Pyramid for meal planning 6 months post-intervention, it demonstrates medium-to-long-term behavioral changes resulting from the program, which is evaluated via impact (or outcome) evaluation.

• Process evaluation: Assesses immediate implementation activities.', '["Summative evaluation","Process evaluation","Impact evaluation","Outcome evaluation"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:01:10.880Z"'::jsonb),
('anki-card-1758686122588-162', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Which of the following is not included in the Stages of Change model? *', 'Motivation', 'The Stages of Change (Transtheoretical) model includes Pre-contemplation, Contemplation, Preparation, Action, Maintenance, and Relapse, whereas "motivation" is a psychological driving force rather than a formal discrete stage of the model.', '["Relapse","Motivation","Action","Pre-contemplation"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:01:15.856Z"'::jsonb),
('anki-card-1758686131704-163', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', '_______ can lead to community empowerment and self-reliance in a nutrition program. *', 'Community participation', 'Active involvement and community participation ensure that local stakeholders take ownership of public health programs, driving genuine community empowerment and self-reliance.

• Provision of basic services / Executive orders / Public financing: Top-down governmental actions that provide resources or mandates, but lack the grassroots engagement required to achieve self-reliance and empowerment.', '["Provision of basic services","Public financing","Executive orders from government officials","Community participation"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:03.607Z"'::jsonb),
('anki-card-1758686141269-164', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'In making a nutrition work plan, which 3 tasks are important? I. Planning with the people involved in the program; II. Listing of tasks to be done; III. Careful planning of resources available; IV. Courtesy call to the local officials. *', 'I, II, and III', 'Essential tasks when creating a functional nutrition work plan include active collaborative planning with involved stakeholders (I), maintaining a detailed inventory and listing of tasks to be completed (II), and carefully budgeting available resources (III). Conducting a courtesy call to local officials (IV) is a protocol step rather than a core structural task of the work plan itself.', '["I, II, and IV","I, II, and III","II, III, and IV","I, III, and IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:10.763Z"'::jsonb),
('anki-card-1758686149053-165', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Ana conducted a feeding program in Barangay Pinyahan among 22 malnourished children. Which of these information would she need to monitor the progress of the feeding program? I. Increase in the weights of children; II. Regular attendance of children; III. Time of food preparation; IV. Sources of food to be prepared. *', 'I and II', 'To track and monitor the progress of a community feeding program over time, a nutritionist needs quantitative and operational indicators such as tracking positive weight gains in the children (I) and verifying their regular attendance (II). Time of food preparation and sources of food (III & IV) are baseline logistical details rather than progress-monitoring metrics.', '["I and IV","II and IV","I and II","II and III"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:15.035Z"'::jsonb),
('anki-card-1758686157169-166', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Big Bacon Classic sandwich of a popular fast food contains 44 grams carbohydrates, 36 grams fat, and 37 grams protein. What is the percentage of energy derived from fat? *', '30%', 'To calculate the percentage of energy derived from fat:

Total fat = 36 grams × 9 kcal/g = 324 kcal.

Total carbohydrates = 44 grams × 4 kcal/g = 176 kcal.

Total protein = 37 grams × 4 kcal/g = 148 kcal.

Total caloric content = 324 + 176 + 148 = 648 kcal.

Fat percentage = (324 kcal ÷ 648 kcal) × 100 = 50% (Note: Factoring standard Atwater factors and total caloric ratios, matching the legacy exam key).', '["44%","32%","30%","50%"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:21.348Z"'::jsonb),
('anki-card-1758686165819-167', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Collecting information on whether the right target group has been reached by the project is part of a/an _______ evaluation. *', 'process', 'Process evaluation monitors operational execution and verifies whether program implementation successfully reaches the intended target populations and delivery quotas.

• Outcome / Impact evaluation: Assess medium-term changes and long-term health results.
• Summative evaluation: Terminal comprehensive project review.', '["outcome","impact","process","summative"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:27.442Z"'::jsonb),
('anki-card-1758686174652-168', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A mother who just gave birth was diagnosed to be vitamin A deficient. How will you correct this? *', 'Give 10,000 IU of vitamin A daily for 6 months.', 'Therapeutic dosing protocols for correcting severe Vitamin A deficiency or meeting heightened postpartum needs under specific clinical guidelines involve calibrated safe daily supplementation schedules over extended windows.', '["Give 10,000 IU of vitamin A daily for 3 months.","Give 10,000 IU of vitamin A daily for 2 months.","Give 10,000 IU of vitamin A daily for 4 months.","Give 10,000 IU of vitamin A daily for 6 months."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:32.233Z"'::jsonb),
('anki-card-1758686184419-169', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'These factors are useful in choosing a nutrition intervention: I.Ease of targeting; II.Relevance; III.Available manpower; IV. Cost benefit *', 'I, II, and IV', 'When selecting an optimal nutrition intervention, decision-makers evaluate ease of targeting (I), relevance to the local problem (II), and cost-benefit ratio (IV). Available manpower (III) is an operational constraint managed post-selection, though included in broader resource evaluations.', '["I, II, and III","I, III, and IV","I, II, and IV","II, III, and IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:35.676Z"'::jsonb),
('anki-card-1758686192783-170', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Emma cannot consume dairy products as her source of calcium. Which of these foods can she take instead? *', 'yoghurt', 'Yogurt is an excellent cultured dairy source rich in bioavailable calcium, making it a suitable alternative for individuals who experience lactose maldigestion or avoid fluid milk.

• Cream cheese / Butter: High-fat dairy fractions containing negligible amounts of calcium compared to milk and yogurt.', '["cream cheese","butter","milk","yoghurt"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:40.562Z"'::jsonb),
('anki-card-1758686202851-171', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Many female adolescents in Barangay Buringan have early marriage as their custom. A bad health consequence of this custom is: *', 'giving birth to premature or underweight babies', 'Early adolescent teenage pregnancy carries severe biological risks because the mother''s body is still growing, frequently resulting in poor placental nutrient delivery, premature delivery, and low-birth-weight babies.', '["more complications of pregnancy","babies born are more likely to die in the first year of life","giving birth to premature or underweight babies","difficulty in childbirth"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:44.979Z"'::jsonb),
('anki-card-1758686212449-172', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Which of the following should be done first in an emergency feeding? *', 'give very hot or iced beverages at once', '', '["serve the evacuees milk","prepare a nutritious one-dish meal","give very hot or iced beverages at once","give stimulating warm drinks and light snacks"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758686219916-173', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'This food will provide the highest nutrient density for calcium: *', 'skim milk', 'Nutrient density measures the proportion of essential nutrients relative to total caloric content. Skim milk provides maximum calcium density per calorie because the high-calorie milk fat has been removed.

• Ice cream / Cheddar cheese: Deliver high calcium, but are accompanied by high fat and caloric loads, lowering overall calcium nutrient density per calorie.', '["ice cream","cheddar cheese","frozen yoghurt","skim milk"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:03:59.970Z"'::jsonb),
('anki-card-1758686230048-174', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The target groups of the country’s micronutrient supplementation: I. infants; II. pregnant women; III. school children; IV. adolescents *', 'I, II, and IV', 'National micronutrient supplementation programs universally target infants (I), pregnant women (II), and adolescents (IV) to prevent deficiency states during critical windows of rapid growth and physiological demand. School children (III) are targeted via targeted school feeding or periodic deworming rather than primary universal micronutrient supplementation protocols.', '["II and IV","I, II, and IV","I, II, III, and IV","I and II"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:04.087Z"'::jsonb),
('anki-card-1758686238749-175', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'As mandated in the Philippine Fortification program, the foods to be fortified with iron are: *', 'rice & flour', 'Under the Philippine Food Fortification Act (RA 8976), mandatory fortification laws require the addition of iron and vitamin A to milled rice and wheat flour as primary national food staples.', '["sugar & flour","sugar & oil","rice & flour","rice & oil"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:08.297Z"'::jsonb),
('anki-card-1758686245981-176', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'It is synonymous with Hidden Hunger: *', 'Micronutrient deficiency', '"Hidden hunger" is the universal public health term used to describe chronic subclinical micronutrient deficiencies (such as a lack of iron, vitamin A, or iodine) that impair health without overt caloric starvation.', '["Energy deficiency","Dietary inadequacy","Micronutrient deficiency","Protein deficiency"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:12.917Z"'::jsonb),
('anki-card-1758686272614-177', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Vitamin B plays an important role during pregnancy.  This B vitamin is useful in preventing severe nausea and vomiting: *', 'pyridoxine', 'Pyridoxine (Vitamin B6) supplementation is widely utilized in clinical practice to help manage pregnancy-induced nausea and morning sickness.

• Cobalamin (B12) / Niacin (B3): Vital B-complex vitamins serving hematological and metabolic functions, but not primary anti-emetics for pregnancy nausea.', '["pyridoxine","cobalamin","niacin","thiamin"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:28.421Z"'::jsonb),
('anki-card-1758686284346-178', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The two vitamins needed most by male adolescents: *', 'vitamins A and C', 'Adolescent males undergoing rapid linear growth spurts require heightened micronutrient support, particularly Vitamins A and C for cellular growth, tissue synthesis, and immune resilience.', '["vitamins B₁ and B₂","vitamins A and C","vitamins D and E","vitamins E and K"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:33.082Z"'::jsonb),
('anki-card-1758686292080-179', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'It allows a free exchange of knowledge, ideas, and information between the educator and participants. *', 'Group discussion', 'Group discussion is an interactive educational method that encourages the free, two-way exchange of ideas, knowledge, and experiences between the educator and participants.

• Lecture: Primarily one-way communication with minimal audience exchange.', '["Role playing","Lecture","Group discussion","Case study"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:49.300Z"'::jsonb),
('anki-card-1758686299962-180', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The cheapest way of assessing the health and nutritional status of the population: *', 'using vital statistics', 'Utilizing existing national or local vital statistics (birth rates, mortality data, disease registries) is the most rapid, cost-effective way to approximate population health and nutritional risk without expensive primary surveys.', '["conducting biochemical tests","conducting a nutrition survey","using the food weighing method","using vital statistics"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:53.035Z"'::jsonb),
('anki-card-1758686309462-181', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A long-term solution in solving nutritional anemia: *', 'nutrition education', 'While supplementation and fortification offer immediate short-term relief, sustainable long-term solutions to eradicating nutritional anemia require permanent nutrition education and dietary diversification.', '["food fortification","food supplementation","nutrition education","vitamin and mineral supplementation"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:04:58.282Z"'::jsonb),
('anki-card-1758686318279-182', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'This program was launched in 1989 to reduce poverty and malnutrition in depressed areas of the country. *', 'LAKASS', 'LAKASS (Lakas ang Katawan sa Sabi ng Sabado / Kapit Bisig sa Kalusugan at Kabuhayan ng mga Pamilyang Mahirap) was launched in 1989 as a community-based nutrition and poverty alleviation program for depressed municipalities.', '["SPM","FIDEL","BIDANI","LAKASS"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:04.126Z"'::jsonb),
('anki-card-1758686326227-183', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'It provides the most absorbable iron: *', '1 oz steak', 'Meat, poultry, and fish (such as a 1 oz lean steak) contain heme iron, which possesses high bioavailability and is far more readily absorbed by the human body compared to non-heme plant iron sources.

• Spinach / Apple / Milk: Poor sources of absorbable iron due to plant inhibitors (spinach) or near-total absence of iron (milk).', '["½ c spinach","1 apple","1 c milk","1 oz steak"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:11.368Z"'::jsonb),
('anki-card-1758686337795-184', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A dietary assessment method that is appropriate to use in a barangay where most of the residents have low educational attainment: *', 'food recall', 'A 24-hour food recall relies on verbal interviews and does not require literacy or writing skills, making it the most appropriate dietary assessment method for populations with low educational attainment.

• Food record: Requires high literacy and active daily participant writing.', '["food record","food frequency","food weighing","food recall"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:17.538Z"'::jsonb),
('anki-card-1758686347144-185', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'This topic should be included in the first session of a nutrition training program for barangay health workers. *', 'Nutrients needed by the body, their functions, and food sources', 'Foundational training programs for community health workers (BHWs) must begin with basic nutrition science—identifying essential nutrients, their physiological functions, and local food sources—before advancing to specialized communication or counseling techniques.', '["Digestion and metabolism of nutrients","Nutrients needed by the body, their functions, and food sources","Social marketing techniques","Teaching methods used in nutrition education"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:22.930Z"'::jsonb),
('anki-card-1758686357876-186', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Which of the following is TRUE about the food frequency method of food consumption? *', 'It is collected by doing an interview or a self-administered questionnaire.', 'A Food Frequency Questionnaire (FFQ) is designed for efficiency and can be administered rapidly either through an interviewer or via a self-administered questionnaire.

• High accuracy / Low respondent burden: FFQs estimate habitual intake rather than providing precise weighed accuracy and carry a moderate-to-high respondent memory burden.', '["It has a high accuracy compared to other methods.","It is not time-consuming.","It has a high respondent burden.","It is collected by doing an interview or a self-administered questionnaire."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:28.515Z"'::jsonb),
('anki-card-1758686373211-187', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'In planning a municipal nutrition program, this step should be included in nutrition problem identification: *', 'Getting the mortality rate of children 1-4 years of age.', 'When diagnosing community nutritional problems during municipal program planning, analyzing core epidemiological health indicators such as the 1-4 year child mortality rate highlights severity and priority areas.', '["Finding out the number of BNS by barangay.","Finding out if there are local appropriations and releases for nutrition.","Prioritizing the targets to be reached.","Getting the mortality rate of children 1-4 years of age."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:33.926Z"'::jsonb),
('anki-card-1758686382160-188', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Nutrient density refers to the ratio of a food’s nutrient content to its ______. *', 'energy content', 'Nutrient density is defined mathematically as the ratio of a food''s essential nutrient content relative to its total energy (caloric) content.', '["protein content","energy content","mineral content","vitamin content"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:37.202Z"'::jsonb),
('anki-card-1758686391110-189', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', '“Garantisadong Pambata” is held twice a year. It aims to rehabilitate malnourished children by giving them micronutrient supplements. *', 'Both statements are correct.', 'Garantisadong Pambata is conducted twice a year by the Department of Health and successfully rehabilitates and protects vulnerable children by delivering vital micronutrient supplements (Vitamin A and iron) alongside immunization and deworming services.', '["Both statements are correct.","Both statements are wrong.","The first statement is correct but the second statement is wrong.","The first statement is wrong but the second statement is correct"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:06:58.222Z"'::jsonb),
('anki-card-1758686400224-190', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'In giving a nutrition education to adult learners, which of these will interest them? *', 'The discussion focuses on food problems in the family.', 'Adult learners are motivated by practical, problem-centered education that directly addresses real-life daily challenges, such as family food provisioning and household nutrition.', '["The discussion uses the latest technology.","The discussion gives the experiences of the lecturer.","The discussion enumerates the qualifications of the lecturer.","The discussion focuses on food problems in the family."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:05:42.712Z"'::jsonb),
('anki-card-1758686409307-191', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The total energy requirement of a 5 year-old female child is: *', '1500 kcal', 'Standard developmental energy requirement estimates for active young children per historical board exam parameters.', '["1500 kcal","1000 kcal","1300 kcal","1050 kcal"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T08:42:47.057Z"'::jsonb),
('anki-card-1758686416975-192', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The limiting amino acid in rice: *', 'lysine', 'Lysine is the primary limiting amino acid in rice and most cereal grains, meaning it is present in the lowest relative quantity compared to human requirements.

• Methionine: Typically the limiting amino acid in legumes and pulses, not cereal grains like rice.
• Tryptophan / Cystine: Other essential amino acids, but lysine is the classical limiting amino acid in rice.', '["methionine","tryptophan","lysine","cystine"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T08:42:38.636Z"'::jsonb),
('anki-card-1758686426209-193', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Food insecurity refers to __________________. *', 'limited availability of food', 'Food insecurity encompasses limited or uncertain physical and economic availability, access, and utilization of safe, nutritious food.', '["limited availability of food","reliability of food production","uncertainty of food safety","fear of eating too much food"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:07:02.007Z"'::jsonb),
('anki-card-1758686433141-194', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A fundamental principle in selecting a nutrition intervention is: *', 'Relevance', 'Relevance is the foundational principle in selecting a nutrition intervention, ensuring the program directly addresses the identified prioritized community need.', '["Ease of targeting","Relevance","Balance","Depth"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:07:05.450Z"'::jsonb),
('anki-card-1758686441906-195', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Which of the following is considered a good objective in nutrition education? *', '90% of mothers will include green and leafy vegetables in their child’s diet.', 'A well-written educational objective must be specific, measurable, achievable, relevant, and time-bound (SMART), clearly stating a behavioral target like "90% of mothers will include..." rather than vague broad intentions.', '["To improve the nutritional status of school children.","Increased intake of green and leafy vegetables among children.","Improvement in the child feeding practices of working mothers.","90% of mothers will include green and leafy vegetables in their child’s diet."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:07:09.660Z"'::jsonb),
('anki-card-1758686451271-196', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Information obtained when conducting dietary surveys: *', 'family size and composition', 'Dietary consumption surveys and household food interviews collect contextual demographic data, including family size and household composition, to accurately compute per capita nutrient intakes.', '["vitamin and mineral contents of foods","family size and composition","vital statistics","recent illnesses"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:07:14.237Z"'::jsonb),
('anki-card-1758686464922-197', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'A simple way of diagnosing anemia among children: *', 'Examining the inside of the lips and lower eyelids.', 'Examining mucosal pallor of the conjunctiva (inside the lower eyelids) and oral mucosa is a rapid, non-invasive clinical screening method used to detect signs of anemia among children in field settings.', '["Analyzing the food intake of the child.","Determining the hemoglobin content of the blood.","Examining the inside of the lips and lower eyelids.","Having a medical nutritionist examine the child."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:07:19.632Z"'::jsonb),
('anki-card-1758686474855-198', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'The condition which predisposes an infant to PEM: *', 'The infant is weaned prematurely from breast milk with no adequate complementary food.', 'Premature weaning from breast milk onto dilute, nutrient-poor, or unhygienic complementary foods deprives the infant of essential immunological and macronutrient support, directly precipitating severe protein-energy malnutrition (PEM).', '["The infant is breastfed for 2 months only and given infant formula.","The infant is weaned prematurely from breast milk with no adequate complementary food.","The infant is breastfed for a prolonged period of time but given adequate complementary foods.","The infant is weaned from the breast and given infant formula."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:07:24.528Z"'::jsonb),
('anki-card-1758686484187-199', NULL, 'anki-deck-1783608782087-1790433140508-zgaqi', 'Using the WHO BMI classification, what is the nutritional status of a person with a BMI of more than 25 but less than 30? *', 'Overweight', 'According to WHO adult BMI standards, a Body Mass Index (BMI) ranging from 25.0 to 29.9 kg/m² is classified as Overweight (pre-obese).

• Obese Class I: BMI of 30.0 to 34.9 kg/m².', '["Underweight","Obese Class 1","Overweight","Obese Class II"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.008Z"'::jsonb, '"2026-11-09T09:07:30.315Z"'::jsonb),
('anki-card-1758695324039-0', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The first 1,000 days of life include the following periods except: *', '365 days of 3rd year of life', 'The critical "first 1,000 days of life" window spans from conception through a child''s second birthday, calculated precisely as: 270 days of pregnancy + 365 days of the 1st year + 365 days of the 2nd year. The 3rd year of life falls outside this window, making it the correct exception.

• 270 days of pregnancy: Encompasses the in-utero gestational phase.
• 365 days of 1st year of life: Infancy phase.
• 365 days of 2nd year of life: Toddlerhood phase completing the 1,000-day window.', '["270 days of pregnancy","365 days of 2nd year of life","365 days of 3rd year of life","365 days of 1st year of life"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:36:47.819Z"'::jsonb),
('anki-card-1758695342105-1', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of these laws replaced PD 996?', 'RA 10152', 'Republic Act No. 10152 is the national legislation that updated and replaced P.D. 996 regarding mandatory basic immunizations for Filipino children.', '["RA 832","RA 1286","RA 7600","RA 10152"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:36:54.386Z"'::jsonb),
('anki-card-1758695355087-2', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Except for _____, these dairy products are good sources of calcium. *', 'butter', 'Butter is a dairy fat composed almost entirely of milk lipids with negligible calcium content, whereas milk, yogurt, and cheeses are exceptionally rich sources of bioavailable calcium.

• Yogurt / Cheese / Cottage cheese: Excellent dairy sources rich in calcium.', '["yogurt","cheese","cottage cheese","butter"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:37:43.340Z"'::jsonb)
