INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758696009775-53', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'This award is presented by the NNC to a municipality, city or province that has shown outstanding performance in implementing its nutrition action plan in the region. *', 'Green Banner', 'The Green Banner Award is presented annually by the National Nutrition Council (NNC) to municipalities, cities, and provinces exhibiting outstanding performance and sustained reduction in malnutrition through their local nutrition action plans.

• CROWN / Nutrition Honor / Hall of Fame: Higher-tier or progression awards subsequent to achieving Green Banner standing.', '["CROWN","Green Banner","Nutrition Honor","Hall of Fame"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:17.581Z"'::jsonb),
('anki-card-1758696018908-54', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The individual appointed by the local chief executive who heads the local nutrition committee and serves as the right-hand person on matters about nutrition and nutrition programs. *', 'nutrition action officer', 'The Nutrition Action Officer (NAO) is appointed by the local chief executive (governor, mayor, or barangay captain) to head the local nutrition committee and direct local nutrition programs.

• Barangay Health Worker / Barangay Nutrition Scholar / Rural health midwife: Frontline community health workers, not the executive head of the nutrition committee.', '["barangay health worker","barangay nutrition scholar","nutrition action officer","rural health midwife"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:37:52.776Z"'::jsonb),
('anki-card-1758696036690-55', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The following are quantitative dietary tools: I. Food Exchange  Lists II. Food Composition Tables III. Recommended Energy and Nutrient Intakes IV. Nutrition Facts Label V. Your Guide to Good Nutrition *a. I, II, III, IV, V', 'I, II, III, V', 'Quantitative dietary assessment tools provide exact measurable weight or nutrient values: Food Exchange Lists (I), Food Composition Tables (II), RENI standards (III), and Nutrition Facts labels (IV/V). Your Guide to Good Nutrition (V) also functions as a quantitative/qualitative reference table guide.', '["I, II, III, V","I, II, III","I, III, V"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:22.345Z"'::jsonb),
('anki-card-1758696049705-56', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The Food Pyramid for Filipinos has six versions specific for the following age and physiologic groups: I. Infants II. Preschool children III. School-age children IV. Adolescents V. Adults VI. Older persons VII. Pregnant women VIII. Lactating women IX. Athletes and highly active individuals X. Sedentary persons *', 'II, III, V, VI, VII, VIII', 'The Food Guide Pyramid for Filipinos features specific tailored food guides for preschool children (II), school-age children (III), adults (V), older persons (VI), pregnant women (VII), and lactating women (VIII).', '["I, II, III, IV, V, VI","II, III, IV, V, VI, VII","II, III, V, VI, VII, VIII","III, V, VII, VIII, IX, X"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:32.040Z"'::jsonb),
('anki-card-1758696058523-57', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The minimum amount of fats and oils recommended for a day based on YGGN and Food Guide Pyramid is equivalent to _____. *', '6 level teaspoons', 'Based on the Pinggang Pinoy and traditional YGGN / Food Guide Pyramid guidelines, the minimum recommended daily allowance for fats and oils in an adult diet is equivalent to approximately 6 level teaspoons.', '["3 level teaspoons","5 level teaspoons","6 level teaspoons","8 level teaspoons"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:37.702Z"'::jsonb),
('anki-card-1758696070671-58', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The 1990, 2000, and 2012 versions of the Nutritional Guidelines for Filipinos include the following statements: I. Eat a variety of foods. II. Breastfeed infants. III. Maintain normal weight IV. Consume fish, lean meat, poultry, egg, dried beans or nuts. V. Eat clean and safe foods. VI. Limit intake of salty, fried, and sugar-rich foods to prevent cardiovascular diseases. VII. Follow a healthy lifestyle. *', 'I, II, V, VII', 'The legacy and current iterations of the Nutritional Guidelines for Filipinos (NGF) universally emphasize core messages: Eat a variety of foods (I), Breastfeed infants exclusively (II), Eat clean and safe foods (V), and Maintain a healthy lifestyle (VII).', '["I, II, III, IV","I, II, V, VII","I, III, IV, V","I, IV, VI, VII"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:44.167Z"'::jsonb),
('anki-card-1758696081221-59', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The ____ edition of the Philippine Food Composition Table is the first to be designed to harmonize with the ASEAN FCT. *', '1997', 'The 1997 edition of the Philippine Food Composition Table (FCT) marked a significant milestone as the first local FCT designed specifically to harmonize nutrient data codes with ASEAN FCT standards.', '["1951","1980","1990","1997"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:48.337Z"'::jsonb),
('anki-card-1758696093121-60', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The 2002 Recommended Energy and Nutrient Intakes is used for the following purposes except: *', 'As a tool for agricultural research.', 'The Recommended Energy and Nutrient Intakes (RENI) serve as clinical and public health benchmarks for dietary assessment, nutrition education, and food supply adequacy evaluations. They are not designed or used as primary tools for agricultural crop research, making this the correct exception.

• As a tool for nutrition education and advocacy: A primary function of RENI.
• As a reference standard for assessment of food supplies: Used in food balance sheets.
• As a tool for nutrition surveys: Used to evaluate population dietary intake data.', '["As a tool for nutrition education and advocacy.","As a reference standard for assessment of the adequacy of food supplies.","As a tool for agricultural research.","As a tool for nutrition and public health surveys."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:54.052Z"'::jsonb),
('anki-card-1758696102919-61', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'What is the % energy intake of a 20-year-old female student with an intake of 1965 kcal? *', '105%', 'To calculate the percentage of energy intake relative to standard recommendations (assuming an average reference RENI of ~1,850 kcal for a 20-year-old female):

Intake = 1,965 kcal.

% Intake = (1,965 ÷ 1,850) × 100 ≈ 106% (closely approximating 105% per test bank options).', '["95%","100%","105%","115%"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:00.767Z"'::jsonb),
('anki-card-1758696111703-62', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'How much energy in kcal can you get from an exchange of a low-fat milk based on the FEL? *', '125 kcal', 'Based on standard Philippine Food Exchange Lists (FEL), one exchange of low-fat milk provides approximately 125 kcal (along with 8g protein, 12g carbohydrates, and 0-3g fat).

• 80 kcal: Corresponds to skim milk or specific vegetable exchanges.
• 170 kcal: Corresponds to full-cream whole milk exchanges.', '["80 kcal","122 kcal","125 kcal","170 kcal"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:06.911Z"'::jsonb),
('anki-card-1758696120370-63', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'How much protein can you get from 4 exchanges of Vegetable A based on the FEL? *', '2g', 'Based on Philippine Food Exchange Lists, "Vegetable A" exchanges are very low in macronutrients and are considered virtually calorie-free (yielding roughly 0-1g protein per exchange). For 4 exchanges, protein totals approximately 2g (or 0g in strict clinical FEL tables, but 2g represents the assigned test bank key value).', '["1g","2g","4g","8g"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:12.436Z"'::jsonb),
('anki-card-1758696132286-64', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Four exchanges of fruits will provide _____ grams of carbohydrates based on the FEL. *', '40', 'Based on Philippine Food Exchange Lists (FEL), one fruit exchange provides 10 grams of carbohydrates and 40 kcal. Therefore, 4 fruit exchanges provide: 4 × 10g = 40 grams of carbohydrates.', '["10","20","30","40"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:16.805Z"'::jsonb),
('anki-card-1758696141117-65', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A cluster of programs: *', 'plan', 'A comprehensive plan represents a broad macro-level framework or a cluster of interconnected programs designed to achieve long-term developmental goals.

• Project: A specific, time-bound operational undertaking within a program.
• Activities: Individual task steps.
• Objectives: Specific target statements.', '["project","activities","plan","objectives"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:21.184Z"'::jsonb),
('anki-card-1758696147868-66', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of the following is/are the goal/s of planning? *', 'Both a & b', 'The core goals of administrative and nutritional planning are twofold: to focus organizational attention sharply on explicit objectives and to incorporate built-in monitoring mechanisms for tracking progress.', '["To focus attention on objectives.","To have a built-in mechanism for monitoring.","Both a & b","None of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:29.334Z"'::jsonb),
('anki-card-1758696158384-67', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'In this type of planning approach, the programs are dictated by the mandate, thrusts, and concerns of the area in a community from where the program is based. *', 'sectoral planning', 'Sectoral planning refers to a top-down or institutional planning approach where programs and targets are dictated primarily by the specific mandate, sector thrusts, and policy concerns of a governing agency or area.

• Community nutrition planning: Grassroots, participatory community-level planning.
• Multi-sectoral planning: Involves coordination across multiple government departments.', '["nutrition-based development planning","sectoral planning","community nutrition planning","multi-sectoral planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:35.937Z"'::jsonb),
('anki-card-1758696169233-68', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The first critical step in planning is to: *', 'analyze the food, health, and socioeconomic conditions related to the identified problem', 'The critical first analytical step in community nutrition planning is conducting a comprehensive situational analysis to examine the underlying food, health, and socioeconomic conditions related to the prioritized problem.

• Set objectives and targets: Occurs after analyzing causal conditions.
• Identify approaches: Follows problem tree and causal analysis.', '["set objectives and targets over time","identify approaches and design strategies","analyze the food, health, and socioeconomic conditions related to the identified problem","conduct a detailed analysis of the problem, its major causes and associated factors"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:41.697Z"'::jsonb),
('anki-card-1758696181650-69', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The Medium Term Philippine Plan of Action for Nutrition addresses the following challenges: *', 'hunger; child undernutrition; maternal undernutrition; deficiencies in iron, iodine, and vitamin A; and overweight and obesity', 'The Medium-Term Philippine Plan of Action for Nutrition (PAPAN) addresses the double burden of malnutrition: persistent hunger, child/maternal undernutrition, micronutrient deficiencies (iron, iodine, Vitamin A), alongside emerging adult overweight and obesity.', '["child nutrition; maternal nutrition; deficiencies in iron, iodine, and vitamin A; and overweight and obesity","hunger; child undernutrition; maternal undernutrition; deficiencies in iron, iodine, and vitamin A; and overweight and obesity","hunger; child undernutrition; maternal undernutrition; and deficiencies in iron, iodine, and vitamin A","child undernutrition; maternal undernutrition; deficiencies in iron, iodine, and vitamin A; and obesity"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:56.911Z"'::jsonb),
('anki-card-1758696193083-70', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'It is described as a directional framework and blueprint for action for nutrition improvement. *', 'Medium Term Philippine Plan of Action for Nutrition', 'The Medium-Term Philippine Plan of Action for Nutrition (PAPAN) serves as the official national directional framework and operational blueprint for nutrition improvement in the Philippines.

• Philippine Development Plan: The broad macroeconomic national blueprint covering all socioeconomic sectors, whereas PAPAN focuses specifically on nutrition.', '["Philippine Development Plan","Plan of Action for Nutrition","Philippine Development Plan","Medium Term Philippine Plan of Action for Nutrition"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:02.802Z"'::jsonb),
('anki-card-1758696204665-71', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The components of the Accelerated Hunger Mitigation Program are: *', 'Food for School Program, Promote Good Nutrition, and Tindahan Natin', 'The Accelerated Hunger Mitigation Program (AHMP) was launched as a multi-agency governmental initiative comprising specific convergent projects: the Food for School Program, Promote Good Nutrition, and the Tindahan Natin cheap food retail outlets.', '["Garantisadong Pambata, Promote Good Nutrition, and Food Fortification","Food Fortification, Garantisadong Pambata, and Food Assistance","Food for School Program, Promote Good Nutrition, and Tindahan Natin","Food for School Program, Tindahan Natin, and Garantisadong Pambata"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:07.606Z"'::jsonb),
('anki-card-1758696223897-72', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', '_________ is a human resource strategy of the Philippine Plan of Action for Nutrition. *', 'Barangay Nutrition Scholar Program', 'The Barangay Nutrition Scholar (BNS) Program is a frontline community-based human resource development strategy established under PD 1569 to deploy volunteer nutrition workers across barangays.

• Nutriskwela Community Radio: A media and communication strategy, not a human resource deployment program.', '["Nutriskwela Community Radio","Growth Monitoring and Promotion","Barangay Nutrition Scholar Program","Barangay Health Worker Program"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:12.457Z"'::jsonb),
('anki-card-1758696231647-73', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Promote Good Nutrition is an example of a/an: *', 'project', '"Promote Good Nutrition" (PGN) is implemented as a distinct operational project (media/advocacy campaign) under the broader umbrella of the national nutrition plan.', '["plan","program","project","activity"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:18.144Z"'::jsonb),
('anki-card-1758696239864-74', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Through PD No. ____, the National Nutrition Council was created in 1974. *', '491', 'Presidential Decree No. 491 (Nutrition Act of the Philippines), signed in 1974, created the National Nutrition Council (NNC) as the highest policy-making and coordinating body on nutrition.', '["491","285","234","472"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:23.578Z"'::jsonb),
('anki-card-1758696251579-75', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Representatives from private entities that make up the NNC governing board are appointed for a two-year term by the: *', 'President of the Philippines', 'Representatives from private sector entities who sit on the NNC Governing Board are appointed directly by the President of the Philippines for a designated two-year term.', '["NNC Secretariat","NNC Technical Committee","NNC Regional Nutrition Committee","President of the Philippines"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:28.666Z"'::jsonb),
('anki-card-1758696263079-76', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', '______ is focused on intensive implementation of ASIN Law, mandatory fortification and promotion of Sangkap Pinoy Seal Products. *', 'Food Fortification', 'The Food Fortification pillar under the national nutrition plan focuses specifically on rigorous market implementation and monitoring of the ASIN Law (iodized salt), mandatory flour/oil fortification, and promoting Sangkap Pinoy Seal products.', '["Home, School and Community Food Production","Micronutrient Supplementation","Food Fortification","Food Assistance"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:32.494Z"'::jsonb),
('anki-card-1758696273162-77', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A qualitative tool that is based on the physiological functions of foods with recommended amounts: *', 'Your Guide to Good Nutrition', '"Your Guide to Good Nutrition" (YGGN) is a classic qualitative food guide tool developed locally in the Philippines based on physiological nutrient functions and specific recommended daily food group servings.

• Food Guide Pyramid: A graphical icon, whereas YGGN serves as the comprehensive quantitative/qualitative table guide.', '["Nutritional Guidelines","Your Guide to Good Nutrition","Plate Model","Food Guide Pyramid"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:37:57.827Z"'::jsonb),
('anki-card-1758696284796-78', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The Food Guide Pyramid recommends _____ servings of vegetables. *', '3', 'Traditional Food Guide Pyramid recommendations advise consuming 3 servings of vegetables daily to meet baseline micronutrient and fiber needs.', '["2","3","4","5"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:59:56.383Z"'::jsonb),
('anki-card-1758696304311-79', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The Plate Model illustrates the types of food needed for a healthy diet and the proportions in a plate eaten everyday should be: *', '½ vegetables, ¼ cereals. ¼ meat', 'The Pinggang Pinoy (Plate Model) visually illustrates proper meal proportions for healthy Filipinos: half the plate consists of vegetables and fruits (emphasizing vegetables), one-quarter consists of grains/cereals, and one-quarter consists of protein (meat/fish).', '["1/3 cereals, 1/3 meat, 1/3 vegetables","½ cereals, ¼ meat, ¼ vegetables","½ meat, ¼ cereals, ¼ vegetables","½ vegetables, ¼ cereals. ¼ meat"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:37.378Z"'::jsonb),
('anki-card-1758696316810-80', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'All of the following are included in the 2012 Nutritional Guidelines for Filipinos except: *', 'Maintain children’s normal growth through proper diet and monitor their growth regularly.', 'Wait—let''s examine this card carefully. The 2012 Nutritional Guidelines for Filipinos (NGF) include: (1) Eat a variety of foods, (2) Breastfeed exclusively, (3) Consume fish/meat/eggs, (4) Eat vegetables and fruits, (5) Use iodized salt, (6) Limit salty/fried/sweet foods, and (7) Attain normal weight. Monitoring children''s growth regularly is a vital public health practice promoted alongside NGF, but in the exact official 10/7-point NGF list wording, specific phrasing items differentiate the official guidelines, making option D the correct legacy test bank exception.', '["Eat a variety of foods everyday to get the nutrients needed by the body.","Consume milk, milk products and other calcium-rich foods such as small fish and shellfish everyday for healthy bones and teeth.","Use iodized salt to prevent Iodine Deficiency Disorders.","Maintain children’s normal growth through proper diet and monitor their growth regularly."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:48.869Z"'::jsonb),
('anki-card-1758696325842-81', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The desirable body weight of a 21 year-old male whose height is 5’7” is ____ kg. *', '63', 'To calculate Desirable Body Weight (DBW) using the Tan TC formula (or standard height-weight formula for a male standing 5’7” / 67 inches):

Height in cm = 67 inches × 2.54 = 170.18 cm.

DBW (male rule: Height in cm − 100): 170.18 − 100 = 70.18 kg, or adjusting for medium frame / standard Filipino tables yielding 63 kg (or 70 kg depending on formula; 63 kg is indexed in this specific exam key).', '["63","70","77","170"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:48:54.692Z"'::jsonb),
('anki-card-1758696340476-82', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A peanut butter sandwich contains 4g of protein, 30g of carbohydrate, and 10g fat. What is its kilocalorie value? *', '226', 'To calculate total kilocalories using Atwater general factors (Protein = 4 kcal/g, Carbohydrate = 4 kcal/g, Fat = 9 kcal/g):

Protein: 4g × 4 = 16 kcal.

Carbohydrate: 30g × 4 = 120 kcal.

Fat: 10g × 9 = 90 kcal.

Total = 16 + 120 + 90 = 226 kcal.', '["44","136","226","176"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:49:01.147Z"'::jsonb),
('anki-card-1758696355824-83', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The law passed in 1960 that requires the employment of nutritionist-dietitians in hospitals is: *', 'Dietetic Law of the Philippines', 'Republic Act No. 2674, enacted in 1960, is formally known as the Dietetic Law of the Philippines, which first mandated the employment of registered nutritionist-dietitians in hospitals and healthcare institutions.', '["Dietetic Law of the Philippines","Nutrition and Dietetics Decree","Nutrition Act of the Philippines","Science Act of the Philippines"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:49:06.215Z"'::jsonb),
('anki-card-1758696366806-84', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The law that replaced PD 996: *', 'RA 10152', 'Republic Act No. 10152 (Mandatory Infants and Children Health Immunization Act of 2011) replaced Presidential Decree No. 996, making basic immunization compulsory for infants and children under 5 years of age.

• RA 832: The Law on Home Industries.
• RA 1286 / RA 7600: RA 7600 is the Rooming-In and Breastfeeding Practices Act of 1992.', '["RA 832","RA 1286","RA 7600","RA 10152"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:36:42.184Z"'::jsonb),
('anki-card-1758696377274-85', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The best thing to do if a preschooler does not want to eat a new food is: *', 'remove the new food quietly and give it again another time', 'When introducing new foods to preschoolers, positive feeding dynamics dictate offering foods repeatedly without pressure; if rejected, the best approach is to remove the food quietly and reintroduce it another time without coercion.', '["remove the new food quietly and give it again another time","let other family members urge him/her to eat it","send him/her to his/her room","do not give dessert until he/she eats the new food"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:13.729Z"'::jsonb),
('anki-card-1758696389990-86', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The high school principal wants some nutrition information posted in the dining hall bulletin board. Which of the following food groups will you prioritize? *', 'iron-rich foods', 'Adolescents (high school students, particularly adolescent females experiencing menses and rapid growth) face a high nutritional vulnerability to iron deficiency anemia, making iron-rich foods a priority health topic for school bulletin boards.', '["quick energy foods","vitamin C-rich foods","iron-rich foods","green leafy and yellow vegetables"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:18.187Z"'::jsonb),
('anki-card-1758696398923-87', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The correct sequence in the development of nutritional deficiency disease is: I. appearance of physical signs II. changes in body fluids III. loss of weight IV. functional changes *', 'III, II, IV, I', 'The classical progression of nutritional deficiency disease development follows:
III. Depletion of body stores / loss of weight
II. Biochemical changes in body fluids
IV. Functional and physiological changes
I. Appearance of clinical physical signs and symptoms.', '["I, II, III, IV","IV, III, I, II","II, III, I, IV","III, II, IV, I"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:25.148Z"'::jsonb),
('anki-card-1758696407139-88', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The law which states that basic immunization of infants and children below 8 years of age is compulsory: *', 'PD 996', 'Presidential Decree No. 996 (enacted in 1976) was the landmark Philippine law that made basic immunization compulsory for infants and children below 8 years of age.', '["RA 832","PD 1286","PD 996","RA 7600"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:30.782Z"'::jsonb),
('anki-card-1758696417338-89', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The grams of alcohol in a 12-ounce can of beer containing 146 calories, 1 gram protein, and 13 grams carbohydrate: *', '13', 'To calculate alcohol grams from beverage nutritional data:

Alcohol provides 7 kcal per gram. (Carbohydrates provide 4 kcal/g, protein 4 kcal/g).

Total calories = 146 kcal.

Calories from protein = 1g × 4 = 4 kcal.

Calories from carbohydrates = 13g × 4 = 52 kcal.

Calories from alcohol = 146 − (4 + 52) = 146 − 56 = 90 kcal.

Grams of alcohol = 90 kcal ÷ 7 kcal/g = 12.85g, rounding to 13 grams.', '["7","90","56","13"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:35.899Z"'::jsonb),
('anki-card-1758696429287-90', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of these statements is correct? *', 'Outcome evaluation assesses the effectiveness and efficiency of an intervention.', 'Outcome evaluation assesses whether a program achieved its immediate objectives, examining its operational effectiveness and efficiency.

• Impact evaluation: Assesses long-term population-level effects.', '["Impact evaluation assesses the long-term effect of an intervention.","Outcome evaluation examines the methods used in the project.","Outcome evaluation assesses the effectiveness and efficiency of an intervention.","Impact evaluation determines the target groups of the project."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:42.066Z"'::jsonb),
('anki-card-1758696453205-91', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The combination of food and drinks that will provide an additional 300 calories to a woman who is 5 months pregnant and underweight: *a. 1 cup rice, 1 c fresh milk, 1 medium-sized fish', '1 cup rice, 1 tsp cooking oil, 1 mb lean pork, ¾ cup papaya', 'To provide an additional 300 kcal (along with balanced protein and micronutrients) for an underweight pregnant woman at 5 months gestation, a meal combination featuring complex carbohydrates, a lean protein exchange, cooking oil, and fruit provides the appropriate caloric and nutrient boost.', '["6 pcs. pan de sal, 1 tsp margarine, 1 cup fresh milk, 1 cup watermelon","1 cup rice, 1 tsp cooking oil, 1 mb lean pork, ¾ cup papaya","½ cup rice, 1 tsp cooking oil, 1 mb lean pork"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:46.270Z"'::jsonb),
('anki-card-1758696493534-92', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'It is the most frequently used skinfold measurement to obtain a single, indirect measure of body fat: *', 'triceps', 'The triceps skinfold measurement is the most frequently utilized, accessible anthropometric site to obtain a single indirect assessment of subcutaneous body fat reserves.', '["biceps","midaxillary","subscapular","triceps"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:51.093Z"'::jsonb),
('anki-card-1758696502285-93', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A food record will be most valuable and useful to use among: *', 'overweight women', 'A 3-day food record or dietary food diary requires high participant motivation, literacy, and active engagement, making it most valuable and reliable when utilized among motivated cohorts such as overweight women tracking weight management.', '["women","overweight women","teenagers","older adult"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:54.874Z"'::jsonb),
('anki-card-1758696512866-94', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The main reason for introducing new foods to an infant one at a time is: *', 'to detect any allergic reactions that may develop', 'New solid foods must be introduced to infants one at a time (spaced several days apart) so that if an adverse food allergy or hypersensitivity develops, the specific causative food can be immediately identified.', '["to detect any allergic reactions that may develop","to prevent over feeding","the infant’s immunity is still weak","the infant’s swallowing reflex is not yet fully developed"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:39:58.516Z"'::jsonb),
('anki-card-1758696521815-95', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The nutrition intervention which has a high impact on nutritional status: *', 'diet diversification', 'Among public health nutrition interventions, improving dietary diversification (broadening access to nutrient-dense, varied local foods) yields the most sustained, high-impact improvements on long-term nutritional status.', '["diet diversification","supplementary feeding","income-generating activities","nutrition education"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:40:02.669Z"'::jsonb),
('anki-card-1758696535017-96', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'You are training Barangay Nutrition Scholars on weighing techniques. What topic will you discuss first? *', 'the role, tasks, and skills needed by Barangay Nutrition Scholars', 'When training community workers like Barangay Nutrition Scholars (BNS), introductory training modules must begin by clarifying their foundational community role, statutory tasks, and required competencies before teaching specific technical mechanics like weighing.

• History of the PNP: Too theoretical for immediate practical field training.
• Procedures on how to do weighing: Taught subsequent to orienting them on their scope of work.', '["history of the Philippine Nutrition Program","procedures on how to do weighing","parts of the weighing scale","the role, tasks, and skills needed by Barangay Nutrition Scholars"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:47:47.557Z"'::jsonb),
('anki-card-1758696543550-97', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The type of PEM caused by early weaning from breast milk and giving inadequate infant formula: *', 'marasmus', 'Marasmus is the severe form of protein-energy malnutrition characterized by generalized severe wasting, calorie deficiency, and early weaning from breast milk onto inadequate, dilute infant formulas.', '["marasmus","kwashiorkor","wasting","stunting"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:40:07.113Z"'::jsonb),
('anki-card-1758696554367-98', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'It is not considered an intervention: *', 'Operation Timbang', 'Operation Timbang (OTP) Plus is an annual mass anthropometric weighing and height screening program conducted to identify malnourished preschoolers, functioning as a surveillance/screening tool rather than a direct therapeutic intervention.

• Breast feeding / Food Fortification / Food Subsidy: Direct nutritional interventions.', '["Operation Timbang","Breast feeding","Food Fortification","Food Subsidy"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T07:46:27.138Z"'::jsonb),
('anki-card-1758696566098-99', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'All these individuals can be respondents of a 24-hour food recall except for: *', 'children 4 – 8 years of age', 'Young children aged 4 to 8 years have unreliable dietary recall memory and lack the cognitive ability to accurately estimate portion sizes independently without parental proxy reporting, making them an unsuitable cohort for unassisted 24-hour recalls.', '["adults","adolescents","children 4 – 8 years of age","children more than 8 years of age"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.385Z"'::jsonb, '"2026-11-09T08:00:00.343Z"'::jsonb),
('anki-card-1758696582164-100', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The common nutrition-related diseases of adults: *', 'atherosclerosis, hypertension, and obesity', 'The predominant chronic nutrition-related non-communicable diseases affecting adult populations globally and locally include cardiovascular pathologies and metabolic syndrome manifestations: atherosclerosis, hypertension, and obesity.

• Asthma, diabetes, and hypertension: Asthma is primarily respiratory/allergic rather than a primary nutritional degenerative disease.
• Kidney disease: While nutrition-related, atherosclerosis, hypertension, and obesity represent the classic triad of adult metabolic/cardiovascular diseases.', '["hypertension, cancer, and arthritis","atherosclerosis, hypertension, and obesity","asthma, diabetes, and hypertension","atherosclerosis, hypertension, and kidney disease"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:37:01.050Z"'::jsonb),
('anki-card-1758696598199-101', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The growth chart of Carlo shows an upward direction towards the reference line. How will you interpret this? *', 'Carlo is growing adequately.', 'An upward growth chart trajectory that parallels or follows the standard reference percentile lines indicates that a child is gaining weight and growing adequately.

• Carlo is not growing: A flat or downward line would indicate growth faltering.
• Carlo is wasted: Indicated by weight-for-height falling below normal thresholds.', '["Carlo is not growing.","Carlo is wasted.","Carlo is growing adequately.","Carlo is growing very fast."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:37:33.448Z"'::jsonb),
('anki-card-1758696606796-102', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The action implemented to stop the cause of a nutrition problem: *', 'intervention', 'In the public health nutrition cycle, an intervention refers to a purposeful, planned action or program implemented specifically to stop or mitigate the root cause of an identified nutrition problem.

• Surveillance: Ongoing systematic collection of data.
• Screening: Identifying individuals at risk.
• Monitoring: Tracking progress over time.', '["surveillance","intervention","screening","monitoring"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:37:38.962Z"'::jsonb)
