INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758696615713-103', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The best graphical presentation to show the percentage distribution of foods consumed in relation to total calories. *', 'pie chart', 'A pie chart (circle graph) is the optimal graphical presentation tool to display proportional parts relative to a whole (such as percentage distribution of calories or macronutrients).

• Line graph: Used for trends over continuous time.
• Histogram / Scatter plot: Used for frequency distributions and statistical correlations.', '["line graph","histogram","scatter plot","pie chart"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:49:12.326Z"'::jsonb),
('anki-card-1758696627479-104', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'PEM affects certain population groups only. Adolescents, adult males, non-pregnant and non-lactating women have the lowest prevalence of PEM. *', 'Only the second statement is correct.', 'Statement 1 is incorrect because Protein-Energy Malnutrition (PEM) affects diverse vulnerable demographics (infants, children, pregnant women, elderly) across various settings, not just isolated population groups. 

Statement 2 is correct because epidemiological surveys consistently show that adolescents, adult males, and non-pregnant/non-lactating women exhibit the lowest prevalence rates of severe PEM compared to young children.', '["Only the first statement is correct.","Only the second statement is correct.","Both statements are correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:49:23.603Z"'::jsonb),
('anki-card-1758696648179-105', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'These foods help in meeting the preschoolers’ needs for iron. *', 'whole-grain or enriched breads', 'Whole-grain and enriched breads and cereals provide accessible non-heme iron sources that help meet the high daily iron requirements of growing preschoolers.

• Milk: Exceptionally poor in iron.
• Oranges: Rich in Vitamin C, but poor in iron.', '["milk","whole-grain or enriched breads","oranges","all of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:49:28.535Z"'::jsonb),
('anki-card-1758696659828-106', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'All are weaknesses of the 24-hour recall except: *', 'It is difficult to obtain information.', 'A 24-hour recall is relatively easy and fast to administer in the field, making "difficulty in obtaining information" false (and thus the correct exception representing a non-weakness).

• It provides information on a day''s intake only: A recognized limitation (does not capture habitual individual intake).
• Respondent memory bias: A well-known limitation of recall methods.', '["It provides information on a day’s intake only.","It is not representative of a typical food intake.","The respondent does not give accurate food intake.","It is difficult to obtain information."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:49:34.575Z"'::jsonb),
('anki-card-1758696682993-107', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'This law intends to prevent iodine deficiency disorders in the country. *', 'RA 8172', 'Republic Act No. 8172 is the Act Promoting Salt Iodization Nationwide (ASIN Law), enacted to eliminate iodine deficiency disorders (IDD) in the Philippines.

• RA 2674: Dietetic Law.
• RA 1569: Barangay Health Workers act / BNS precursor.
• RA 8191: National Voluntary Blood Services Act.', '["RA 2674","RA 1569","RA 8191","RA 8172"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:49:41.129Z"'::jsonb),
('anki-card-1758696692775-108', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Giving the infant breast milk substitutes can result in poor growth or illness because: *', 'the bottles and teats used for feeding are not cleaned properly.', 'Infant formula and breast milk substitutes lack the live immunological antibodies found in breast milk; combined with unsterilized bottles and teats, microbial contamination leads to severe infant diarrhea, illness, and growth faltering.

• Calorie content / Protein content: Standard commercial infant formulas are engineered to approximate breast milk macronutrient and caloric profiles.
• Low bioavailability of vitamins/minerals: Formulas are fortified to meet infant requirements.', '["the calorie content of breast milk substitutes is below the infant’s energy needs.","there is a low bioavailability of vitamins and minerals.","the bottles and teats used for feeding are not cleaned properly.","the protein content of milk formulas is low."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:12.994Z"'::jsonb),
('anki-card-1758696702458-109', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The target groups of the Medium Term Philippine Plan of Action for Nutrition: I. children 1-3 years old II. adolescent females III. pregnant and lactating mothers IV. elderly *', 'I, II, and III', 'The Medium-Term Philippine Plan of Action for Nutrition (PAPAN) prioritizes high-risk vulnerable groups: children 1-3 years old, adolescent females, and pregnant/lactating mothers. The elderly are managed through separate geriatric health frameworks.', '["I, II, and IV","I, III, and IV","I, II, and III","II, III, and IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:17.485Z"'::jsonb),
('anki-card-1758696713624-110', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The following foods are considered sources of complete protein: I. casein in milk II. Albumin in egg white III. legumin in legumes IV. zein in corn *', 'I & II', 'Casein in milk and albumin in egg white are complete proteins containing all essential amino acids in sufficient proportions. Legumin in legumes is limiting in methionine, and zein in corn is limiting in lysine and tryptophan.', '["I & II","III & IV","II & III","I & IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:21.508Z"'::jsonb),
('anki-card-1758696734472-111', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Malnutrition among the urban poor is greater than the rural poor. The two main possible causes of high malnutrition among the urban poor are: I. poor housing conditions II. lack of health centers and personnel. III. low level of education IV. inadequate food intake *a. II & IV', 'I & IV', 'Malnutrition among the urban poor is driven largely by poor housing conditions (sanitation/water access) and inadequate food intake (due to cash dependency and volatile food prices).', '["II & III","I & IV","I & III"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:24.590Z"'::jsonb),
('anki-card-1758696744272-112', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The 2013 NNS prevalence of underweight 0-5 year-old children _____ compared to 2008 NNS. *', 'decreased', 'National Nutrition Surveys (NNS) by the Food and Nutrition Research Institute (FNRI) recorded a downward trend in the national prevalence of underweight among children aged 0-5 years.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:29.418Z"'::jsonb),
('anki-card-1758696767923-113', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The prevalence of nutritionally at-risk pregnant women in the 2013 NNS ____ compared to the 2008 NNS. *', 'decreased', 'FNRI National Nutrition Surveys documented a progressive decrease in the prevalence of nutritionally at-risk pregnant women over successive survey cycles.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:33.165Z"'::jsonb),
('anki-card-1758696782556-114', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The prevalence of overweight lactating mothers in 2013 NNS ____ compared to the 2008 NNS. *', 'increased', 'Nutritional surveys highlight an alarming upward trend in the prevalence of overweight and obesity among lactating and adult women.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:37.175Z"'::jsonb),
('anki-card-1758696793672-115', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The prevalence of anemia in 2013 NNS is of high magnitude and considered a public health problem among _______. *', '6-12 year-old children and adolescents', 'National nutrition survey findings classify iron deficiency anemia as a public health problem of high magnitude specifically among school-age children, 6-12 year-old youth, and adolescents.', '["6 months to","6-12 year-old children and adolescents","adults and the elderly","children and lactating mothers"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:41.717Z"'::jsonb),
('anki-card-1758696807654-116', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The prevalence of hypertension among adults ______ in 2013 NNS compared to the 2008 NNS. *', 'decreased', 'Survey tracking on adult blood pressure trends shows fluctuating or managed declines in certain cohort brackets, though hypertension remains a major NCD priority.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:49.281Z"'::jsonb),
('anki-card-1758696816769-117', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The prevalence of high fasting blood glucose among adults _____ in 2013 NNS compared with the 2008 NNS. *', 'increased', 'National health data demonstrates a steady upward trend in the prevalence of elevated fasting blood glucose levels and impaired glucose tolerance among adult populations.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:53.947Z"'::jsonb),
('anki-card-1758696827719-118', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Based on the 2013 NNS, males are more prone to having _____ across all ages. *', 'hypertension', 'Across national nutrition survey data subsets, adult males consistently exhibit a higher prevalence of hypertension across various age brackets compared to females.', '["hypertension","diabetes","high LDL-c","high total cholesterol"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:51:57.868Z"'::jsonb),
('anki-card-1758696839754-119', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The developing organism from the second to eight weeks of gestation is called a/an: *', 'embryo', 'The developing human organism from the second week through the eighth week of gestation is classified as an embryo (during organogenesis).', '["fetus","embryo","ectoderm","mesoderm"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:02.022Z"'::jsonb),
('anki-card-1758696849268-120', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The recommended range of weight gain during pregnancy for a woman with normal weight is: *', '25-30 lbs.', 'According to Institute of Medicine (IOM) guidelines, the recommended total gestational weight gain range for a woman entering pregnancy with a normal BMI is 25 to 30 pounds (approx. 11.5 to 16 kg).', '["10-18 lbs.","19-24 lbs.","25-30 lbs.","35-40 lbs."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:09.554Z"'::jsonb),
('anki-card-1758696857752-121', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The recommended increase in energy intake for the second and third trimester of pregnancy is: *', '300 kcal/day', 'Philippine RENI and international guidelines recommend an additional energy intake of 300 kcal/day during the second and third trimesters of pregnancy.', '["200 kcal/day","300 kcal/day","450 kcal/day","440 kcal/day 2"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:12.345Z"'::jsonb),
('anki-card-1758696866802-122', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'These nutrients are required in higher amounts during pregnancy due to their role in the synthesis of red blood cells. *', 'folate & vitamin B12', 'Folate and Vitamin B12 are required in significantly elevated amounts during pregnancy to support rapid cellular division, DNA synthesis, and expanded red blood cell production.', '["protein & chromium","folate & vitamin B12","calcium & vitamin A","vitamin E & vitamin C"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:16.280Z"'::jsonb),
('anki-card-1758696887449-123', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The condition characterized by high blood pressure, edema, and protein in the urine of a pregnant woman: *', 'preeclampsia', 'Preeclampsia is a serious pregnancy-induced hypertensive disorder characterized by gestational hypertension, generalized edema, and proteinuria.', '["preeclampsia","teratogenic hypertension","gestational diabetes","pregnancy-induced blood pressure crisis"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:21.288Z"'::jsonb),
('anki-card-1758696896882-124', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The factor in breast milk which binds iron and prevents it from supporting the growth of the infant’s intestinal bacteria. *', 'lactoferrin', 'Lactoferrin is an iron-binding protein found abundantly in breast milk that sequesters free iron, inhibiting the proliferation of iron-requiring enteric pathogens in the infant gut.', '["colostrum","lactoferrin","lactalbumin","bifidus factor"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:25.270Z"'::jsonb),
('anki-card-1758696906784-125', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'In medical research, groups sometimes undergo an experience that resembles the experimental manipulation but does not actually involve that manipulation. Such a group is called the: *', 'placebo group', 'In experimental research, a control group that undergoes an experience resembling experimental manipulation without receiving the active treatment is known as a placebo group.', '["independent group","experimental group","control group","placebo group"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:29.527Z"'::jsonb),
('anki-card-1758696917299-126', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'This is an important parameter in assessing a child’s nutritional status: *', 'growth rate', 'Growth rate (velocity of weight and height gain over time) is the single most sensitive and vital parameter for evaluating an infant or child''s health and nutritional status.', '["long bone size and density","blood lipid profile","growth rate","onset of walking and talking"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:33.312Z"'::jsonb),
('anki-card-1758696932382-127', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The adolescent growth spurt ______. *', 'begins and ends earlier in girls than in boys', 'The pubertal adolescent growth spurt typically begins and completes its peak velocity roughly two years earlier in girls than in boys.', '["affects mainly the brain","decreases total nutrient needs","affects every organ except the brain","begins and ends earlier in girls than in boys"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:39.033Z"'::jsonb),
('anki-card-1758696942481-128', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A project that will benefit a specific population is known as the “target approach” while a project that targets the entire population is called a “blanket approach”. *', 'Both statements are correct.', 'A target approach focuses intensive resources on a specific high-risk population subgroup, whereas a blanket approach implements universal coverage across the entire population.', '["Both statements are correct.","The first statement is correct but the second statement is incorrect.","Both statements are incorrect.","The first statement is incorrect but the second statement is correct."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:43.399Z"'::jsonb),
('anki-card-1758696951930-129', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of the following statements is not true of protein energy malnutrition (PEM)? *', 'PEM refers to both undernutrition and overnutrition.', 'Protein-Energy Malnutrition (PEM) strictly refers to forms of undernutrition (kwashiorkor and marasmus), making statement A false and thus the correct exception.', '["PEM refers to both undernutrition and overnutrition.","PEM is previously called protein-calorie malnutrition.","PEM develops when the diet is lacking in protein and energy.","PEM includes marasmus and kwashiorkor."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:53.922Z"'::jsonb),
('anki-card-1758696965646-130', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'According to the 2013 food consumption survey, the common causes of food wastage are: I. wastage during cooking II. plate waste during meals III. food given to neighbors or relatives IV. food given to animals or pets *', 'I & II', 'National food consumption surveys indicate that the most common household food wastes occur at the preparation stage (wastage during cooking) and at the table (plate waste during meals).', '["III & IV","I & III","I & II","II & IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:52:58.131Z"'::jsonb),
('anki-card-1758696975528-131', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Monitoring a nutrition program involves giving updates on the status of program implementation. It is conducted at the end of the program. *', 'The first statement is correct but the second statement is incorrect.', 'Monitoring provides ongoing implementation updates during the life of a program; evaluation (rather than monitoring) is conducted at the terminal conclusion.', '["The first statement is incorrect but the second statement is correct.","Both statements are correct.","Both statements are incorrect.","The first statement is correct but the second statement is incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:01.941Z"'::jsonb),
('anki-card-1758696986330-132', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The nutrient deficiency disease that results due to the consumption of corn as staple and foods low in protein.', 'pellagra', 'Pellagra is the deficiency disease caused by a lack of niacin or tryptophan, classically associated with diets heavily dependent on untreated corn as a staple.', '["scurvy","pellagra","wet beriberi","pernicious anemia"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:06.291Z"'::jsonb),
('anki-card-1758696996127-133', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'It is made of flour fortified with vitamin A and iron: *', 'pan de bida', 'Pan de bida is a commercially developed local bakery product fortified specifically with Vitamin A and iron to combat micronutrient deficiencies among school children.', '["pan de bida","pan de sal","nutria-bun","nutri-bread"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:10.585Z"'::jsonb),
('anki-card-1758697004477-134', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A person with vitamin deficiency will manifest this symptom: *', 'bleeding gums', 'Bleeding gums (gingival hemorrhage) is a classic physical clinical sign of scurvy caused by Vitamin C deficiency.', '["loss of muscle tissues","stunted growth","Food Pyramid","bleeding gums"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:16.694Z"'::jsonb),
('anki-card-1758697014377-135', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'This basic nutrition tool classifies foods according to the same nutrient composition: *', 'Food Exchange List', 'The Food Exchange List (FEL) is a fundamental meal-planning tool that classifies foods into distinct groups based on similar macronutrient and caloric compositions.', '["Food Guide","Food Exchange List","Food Pyramid","Food Composition Table"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:21.277Z"'::jsonb),
('anki-card-1758697025394-136', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'This information is not included in the inventory of resources when doing nutrition program planning: *', 'mortality rate of children 1-4 years of age', 'Child mortality rate is a health status outcome indicator used during situational analysis, not an operational resource (such as BNS personnel, municipal budgets, or institutional facilities) included in a resource inventory.', '["the number of barangay nutrition scholars in the area","the budget allocation for nutrition in the municipality","mortality rate of children 1-4 years of age","a list of government and non-government organizations in the area"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:24.589Z"'::jsonb),
('anki-card-1758697034211-137', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'It is equivalent to one fruit exchange: *', '1 piece guava (4 cm diameter)', 'Under Philippine Food Exchange Lists, one fruit exchange is equivalent to 1 medium fruit portion, such as 1 piece of guava (4 cm diameter) or 1 small banana.', '["1 piece guava (4 cm diameter)","½ cup mashed papaya","1 piece lacatan (9x3 cm)","½ cup diced watermelon"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:29.159Z"'::jsonb),
('anki-card-1758697042709-138', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'E.O. 51 is the Milk Code of the Philippines. It encourages hospitals to practice rooming-in of mothers and the new-born baby. *', 'The first statement is correct but the second statement is incorrect.', 'Statement 1 is correct: Executive Order No. 51 is the Philippine National Code of Marketing of Breastmilk Substitutes. 

Statement 2 is incorrect because the Milk Code regulates marketing practices, whereas rooming-in is mandated separately under RA 7600 (Rooming-In and Breastfeeding Act).', '["Both statements are incorrect.","The first statement is correct but the second statement is incorrect.","Both statements are correct.","The first statement is incorrect but the second statement is correct"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:36.987Z"'::jsonb),
('anki-card-1758697054710-139', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of the following statements is true? *', 'Taste and texture are the most important factors that influence one’s food choices.', 'Sensory attributes like taste, flavor, and texture consistently rank as the primary psychological and physiological drivers influencing everyday human food choices.', '["Fat and carbohydrate contain the same amount of chemical elements.","Taste and texture are the most important factors that influence one’s food choices.","The term organic is related to the concept of organic gardening.","The body requires greater amounts of vitamins than minerals everyday."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:42.245Z"'::jsonb),
('anki-card-1758697066392-140', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Beliefs based on intuition or on common knowledge that people hold firmly and are reluctant to abandon are based on what kind of knowledge? *', 'tenacity', 'Tenacity refers to a method of fixing belief based on superstition, habit, intuition, or common knowledge held firmly without empirical verification.', '["tenacity","empirical","authority","a priori method"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:46.113Z"'::jsonb),
('anki-card-1758697074809-141', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The first two weeks following conception where the blastocyst embeds itself into the uterus: *', 'implantation', 'Implantation is the early developmental stage occurring during the first two weeks post-conception where the blastocyst embeds itself into the uterine endometrial lining.', '["fertilization","fetal growth","implantation","organogenesis"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:50.069Z"'::jsonb),
('anki-card-1758697083241-142', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The stage where the placenta plays an important role in nourishing the fetus: *', 'fetal growth', 'Following organogenesis, the subsequent stage spanning the bulk of gestation is characterized by rapid fetal growth, where the placenta plays a critical nutrient-transfer role.', '["fertilization","fetal growth","implantation","organogenesis"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:54.377Z"'::jsonb),
('anki-card-1758697093158-143', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', '_______ remains elevated resulting in the onset of milk secretion or lactogenesis. *', 'Prolactin', 'Prolactin levels remain elevated postpartum to stimulate and sustain milk synthesis and secretion (lactogenesis).', '["Estrogen","Progesterone","Growth hormone","Prolactin"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:53:58.118Z"'::jsonb),
('anki-card-1758697102073-144', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The fluid requirement of infants is approximately ______ ml/kg IBW per day. *', '100-185', 'Healthy infants require a high fluid volume per kilogram of body weight, averaging approximately 100 to 185 mL/kg/day to compensate for high metabolic turnover and renal immaturity.', '["100-185","50 – 60","200 – 300","250 – 350"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:01.552Z"'::jsonb),
('anki-card-1758697111924-145', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The taste preference of preschoolers is ____. *', 'mildly flavored', 'Preschool children possess heightened taste bud sensitivity, preferring foods that are mildly flavored, lukewarm, and served separately rather than heavily spiced or complex mixtures.', '["strongly flavored","mildly flavored","sweet","spicy"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:05.701Z"'::jsonb),
('anki-card-1758697126889-146', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'It refers to an eating disorder characterized by extreme weight loss, poor body image, and irrational fears of weight gain and obesity: *', 'anorexia nervosa', 'Anorexia nervosa is a severe psychological eating disorder characterized by self-imposed starvation, extreme weight loss, distorted body image, and an intense fear of gaining weight.', '["eat and purge","bulimia nervosa","anorexia nervosa","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:09.909Z"'::jsonb),
('anki-card-1758697134123-147', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A 16 year-old pregnant teenager will need an estimated ____ grams of protein per day. *', '89', 'According to Philippine RENI standards, a pregnant adolescent (e.g., 16 years old) requires heightened protein allowances to support both maternal tissue accretion and fetal growth, totaling approximately 89 grams per day.', '["75","80","85","89"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:13.691Z"'::jsonb),
('anki-card-1758697143220-148', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Loss of teeth and periodontal disease can be managed by giving a: *', 'mechanical soft diet', 'Tooth loss, edentulous states, and periodontal disease impair mastication, making a mechanical soft diet (foods altered in texture to be easily chewed) the appropriate dietary order.', '["regular diet","mechanical soft diet","liquid diet","tube feeding"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:17.796Z"'::jsonb),
('anki-card-1758697151471-149', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'he physiologic change during pregnancy found to be related to obstetric performance. *', 'increase in plasma volume', 'The dramatic 40-50% expansion in maternal plasma volume during pregnancy hemodilutes blood components and is critical for ensuring optimal placental perfusion and obstetric performance.', '["nausea and vomiting","increase in red blood cell production","increase in plasma volume","increased levels of thyroxine"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:21.425Z"'::jsonb),
('anki-card-1758697162254-150', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The variable that undergoes treatment or manipulation in experimental research: *', 'independent variable', 'The independent variable is the experimental factor that is systematically altered, treated, or manipulated by the researcher to observe its effect on the dependent variable.', '["dependent variable","independent variable","extraneous variable","control variable"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:25.929Z"'::jsonb),
('anki-card-1758697178686-151', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The possible research design used in a study entitled “The relation between political beliefs and activism among students” is: *a. descriptive survey', 'correlational research', 'Correlational research design measures statistical relationships and associations between two or more existing variables without experimental manipulation.', '["experimental research","correlational research","observational research"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:31.141Z"'::jsonb),
('anki-card-1758697187851-152', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The following is/are the feature/s of quantitative research: *', 'all of the above', 'Quantitative research features objective measurement of variables, numerical data scores, and the application of statistical analyses to interpret findings.', '["it involves measuring variables for each individual","it involves numerical scores","it uses statistical analysis to summarize and interpret results","all of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:38.172Z"'::jsonb)
