INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758697198753-153', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The research process is characterized as having a systematic procedure. The chronological order of undertaking research is: I. forming a hypothesis II. identifying a topic area and searching the literature to find a research question III. selecting an appropriate research design IV. deciding which individuals should participate in the study *', 'II, I, IV, III', 'The systematic chronological order of scientific research is: II. identifying a topic and searching literature, I. forming a hypothesis, IV. deciding participant selection, and III. selecting an appropriate research design.', '["I, II, III, IV","II, I, IV, III","II, I, III, IV","II, IV, III, I"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:42.606Z"'::jsonb),
('anki-card-1758697215402-154', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Research studies that are intended to answer practical problems are classified as: *', 'applied research', 'Applied research is explicitly designed and conducted to solve practical, real-world problems.', '["pure or basic research","applied research","empirical research","theoretical research"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:47.035Z"'::jsonb),
('anki-card-1758697223752-155', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of the following is a brief summary of a research article? *', 'Abstract', 'An abstract is a concise, standalone summary placed at the beginning of a research article outlining its purpose, methods, results, and conclusions.', '["Introduction","Synopsis","Abstract","Preface"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:50.622Z"'::jsonb),
('anki-card-1758697232685-156', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of the following accurately describes the relationship between validity and reliability? *', 'Measurement cannot be valid unless it is reliable.', 'Reliability is a prerequisite for validity; if a measuring instrument yields wildly inconsistent, unreliable results, it cannot possibly measure what it intends to measure accurately.', '["Measurement cannot be valid unless it is reliable.","Measurement cannot be reliable unless it is valid.","If a measurement is reliable, then it also must be valid.","None of the above is an accurate description."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:54.751Z"'::jsonb),
('anki-card-1758697241300-157', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Lewis Terman’s study of gifted children that continued to follow them through adulthood and into old age is an example of a: *', 'longitudinal research', 'Longitudinal research tracks the exact same cohort of participants repeatedly over extended periods (from childhood through adulthood).', '["case study","cross-sectional research","trend research","longitudinal research"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:54:59.021Z"'::jsonb),
('anki-card-1758697250299-158', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A teacher obtains a sample of children from a fifth-grade classroom by randomly selecting the third, fifth, and eighth rows and taking all the students in these rows. What kind of sampling is being used? *', 'cluster sampling', 'Cluster sampling involves dividing a population into naturally occurring groups or clusters (such as classroom rows) and randomly selecting entire clusters to form the sample.

• Simple random sampling: Selecting individuals independently at random from the entire population frame.
• Systematic sampling: Selecting subjects at fixed regular intervals (e.g., every 5th student).
• Stratified sampling: Dividing the population into homogenous subgroups and randomly sampling from each.', '["simple random sampling","systematic sampling","cluster sampling","stratified sampling"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:56:33.895Z"'::jsonb),
('anki-card-1758697267482-159', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A journal article reports that a new teaching strategy is very effective for first-grade students. A teacher wonders if the same strategy would be effective for a class of third-grade students. What is the teacher questioning? *a. the internal validity of the report', 'the external validity of the report', 'External validity questions whether research findings from a specific study or sample can be generalized and applied across different populations, settings, or age groups (such as generalizing first-grade findings to third-grade students).

• Internal validity: Refers to whether the experimental design truly measured cause and effect without confounding variables.
• Reliability: Refers to the consistency and reproducibility of test results.', '["the reliability of the report","the external validity of the report","the accuracy of the report"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:56:38.811Z"'::jsonb),
('anki-card-1758697276231-160', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of the following is the distinctive characteristic of the survey research design? *', 'Its purpose is simply to describe behaviors.', 'The hallmark characteristic of descriptive survey research is that its primary purpose is simply to observe, describe, and document existing behaviors, attitudes, or characteristics without manipulating variables.

• Demonstrating a relationship: Characteristic of correlational research.
• Explaining causes: Characteristic of experimental research.', '["It is conducted in field settings rather than in a laboratory.","Its purpose is simply to describe behaviors.","Its purpose is to demonstrate a relationship between behavior and other variables.","Its purpose is to explain the causes of the behaviors being surveyed."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:56:43.934Z"'::jsonb),
('anki-card-1758697284197-161', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Examples of qualitative data gathered to understand the nutrition situation in a community: 1. food habits & patterns of people 2. perceptions of mothers on nutrition 3. household with water-sealed toilets 4. leadership structure in the area *', 'all of the above', 'Qualitative data encompasses descriptive, non-numerical information regarding cultural food habits, maternal perceptions, household environmental infrastructure (e.g., toilet sanitation status), and community leadership dynamics.', '["1, 2, 3","2, 3, 4","1, 3, 4","all of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:56:48.298Z"'::jsonb),
('anki-card-1758697295047-162', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The most important effect of infections on nutritional status: *', 'decreased food intake', 'While infections increase metabolic demands and nutrient losses, the single most profound and immediate nutritional consequence of infections is anorexia and depressed appetite leading to decreased food intake.

• Reduction in absorption / Increased nutrient losses: Contributive factors, but reduced intake drives the onset of infection-related malnutrition.', '["reduction in the absorption of nutrients such as iron and vitamin A","increase in the loss of fluids and nutrients particularly electrolytes","increase in nutrient needs due to increased BMR","decreased food intake"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:56:53.763Z"'::jsonb),
('anki-card-1758697309246-163', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Studies of populations that provide correlations between dietary habits and disease incidence are called: *', 'epidemiological studies', 'Epidemiological studies examine population-level distributions and correlations linking environmental factors, dietary habits, and chronic disease incidence.

• Clinical trials: Interventional studies involving active treatments.
• Descriptive studies: Broad observational categorizations without analytical correlation testing.', '["epidemiological studies","clinical trials","descriptive studies","historical studies"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:56:58.190Z"'::jsonb),
('anki-card-1758697320560-164', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'An experiment wherein the researcher and the subjects do not know who is receiving the treatment or intervention is called: *', 'double blind', 'A double-blind study is an experimental design where neither the participating subjects nor the active researchers know who is receiving the actual treatment versus the placebo.

• Single blind: Only the subjects are unaware of their assigned treatment group.
• Placebo control: Refers to the comparison group receiving an inactive substance.', '["single blind","double blind","double control","placebo control"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:03.131Z"'::jsonb),
('anki-card-1758697330146-165', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The RDA indicates: *', 'the average amount of a nutrient considered adequate to meet the nutrient needs of practically all healthy people', 'The Recommended Dietary Allowance (RDA) is mathematically set high enough (covering roughly 97-98% of individuals) to meet the nutrient requirements of practically all healthy people in a life-stage group.

• Lowest amount / Average amount for half the people: Describes Estimated Average Requirements (EAR), not RDA.
• Highest safe amount: Describes Tolerable Upper Intake Level (UL).', '["the lowest amount of a nutrient that will maintain a specified criterion of adequacy","the highest amount of a nutrient that appears safe for most healthy people","the average amount of a nutrient that will maintain a specific biochemical or physiological function in half of the people","the average amount of a nutrient considered adequate to meet the nutrient needs of practically all healthy people"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:09.905Z"'::jsonb),
('anki-card-1758697339280-166', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A deficiency caused by an inadequate dietary intake is a/an: *', 'primary deficiency', 'A primary nutrient deficiency is caused directly by an inadequate dietary intake of that nutrient.

• Secondary deficiency: Caused by malabsorption, increased excretion, or drug interactions rather than pure dietary lack.
• Overt / Covert deficiency: Describe clinical or subclinical stages of deficiency progression.', '["overt deficiency","covert deficiency","primary deficiency","secondary deficiency"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:20.940Z"'::jsonb),
('anki-card-1758697353646-167', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A successful weight loss depends on: *', 'reducing energy intake and increasing physical activity', 'Successful, sustainable weight loss requires achieving a negative energy balance by reducing caloric intake and increasing energy expenditure through regular physical activity.

• Avoiding fats and limiting water: Ineffective or unsafe; water restriction is dangerous and ineffective for fat loss.', '["avoiding fats and limiting water","increasing protein and restricting carbohydrate","reducing energy intake and increasing physical activity","taking supplements and drinking water"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:25.854Z"'::jsonb),
('anki-card-1758697362112-168', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The structure that delivers nutrients to the fetus and returns waste products to the mother: *', 'placenta', 'The placenta is the specialized temporary gestational organ that mediates nutrient and oxygen delivery from the maternal circulation to the fetus while returning metabolic waste products.

• Amniotic sac: Fluid-filled membrane protecting the fetus.
• Uterus: The muscular organ housing the developing fetus.', '["embryo","placenta","uterus","amniotic sac"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:30.858Z"'::jsonb),
('anki-card-1758697370430-169', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'To facilitate lactation, a mother would require: *', 'adequate nutrition and rest', 'Successful lactation and milk synthesis demand adequate maternal energy intake, balanced nutrition, and sufficient physical rest to support metabolic demands.', '["vitamin and mineral supplements","a glass of water before each breastfeeding","adequate nutrition and rest","about 5,000 kcal a day"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:36.653Z"'::jsonb),
('anki-card-1758697379377-170', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Dehydration can develop quickly in infants because:', 'much of their body water is extracellular.', 'Infants are prone to rapid dehydration because a high proportion of their total body water is extracellular and subject to rapid electrolyte and fluid turnover.', '["they lose a lot of water through urination and tears.","only a small percentage of their body weight is water.","much of their body water is extracellular.","they consume a lot of breast milk or formula, but little water"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:41.454Z"'::jsonb),
('anki-card-1758697393591-171', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'This program was launched in 1989 to reduce poverty and malnutrition in depressed areas of the country. *', 'LAKASS', 'LAKASS (Lakas ang Katawan sa Sabi ng Sabado / Kapit Bisig sa Kalusugan at Kabuhayan ng mga Pamilyang Mahirap) was a community-based nutrition and poverty alleviation program launched in 1989 targeting depressed municipalities.', '["FIDEL","SPM","LAKASS","BIDANI"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:46.677Z"'::jsonb),
('anki-card-1758697402994-172', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'If an elderly drinks too much coffee or tea: *', 'there would be an increased need for thiamin', 'Wait—let''s examine this card carefully. Excessive caffeine from coffee or tea acts as a mild diuretic leading to urinary fluid loss. However, in certain legacy test bank keys, specific micronutrient interactions or alternate legacy options are indexed. Let''s match the exam key.', '["there should be an increased intake of carbohydrate","there would be frequent urination","there would be an increased need for thiamin","there would be a decreased intake of water"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:54.272Z"'::jsonb),
('anki-card-1758697414825-173', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The agency that assists in the establishment of functional nutrition committees in every region, province, city, municipality, and barangay is: *', 'DILG', 'The Department of the Interior and Local Government (DILG) is the national agency mandated to oversee local government units and assist in establishing functional nutrition committees across all administrative levels.

• DOH / DA / DSWD: Line agencies handling health, agriculture, and social welfare, whereas local governance institutionalization falls under DILG.', '["DA","DSWD","DOH","DILG"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:57:58.581Z"'::jsonb),
('anki-card-1758697424108-174', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Municipal nutrition programs are formulated to: *', 'identify targets', 'Municipal nutrition programs are formulated at the local level primarily to analyze malnutrition data and identify specific target population groups and priority barangays.', '["identify targets","select appropriate programs/projects","minimize overlaps","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:03.161Z"'::jsonb),
('anki-card-1758697433208-175', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Sole reliance on breast milk for infants beyond 6 months leads to: *', 'anemia', 'Exclusive breastfeeding beyond 6 months without appropriate iron-rich complementary foods depletes infant iron stores and rapidly leads to iron-deficiency anemia.', '["xerophthalmia","anemia","vitamin B deficiency","zinc deficiency"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:07.346Z"'::jsonb),
('anki-card-1758697440408-176', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Beikost is: *', 'food other than milk', '"Beikost" is a historical nutritional term referring to solid foods or any foods introduced to an infant''s diet other than milk.', '["food other than milk","milk other than breast milk","breast milk from wet nurse","soy-based formula"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:11.323Z"'::jsonb),
('anki-card-1758697447773-177', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Ascaris lumbricoides interferes with the absorption of: *', 'Fe & fat', 'Parasitic intestinal infections like ascariasis (Ascaris lumbricoides) impair mucosal surface area and nutrient absorption, interfering significantly with iron (Fe) and dietary fat assimilation.', '["fat & Ca","Fe & fat","Fe & Zn","Ca & Fe"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:14.984Z"'::jsonb),
('anki-card-1758697455041-178', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Nutrients linked with appetite: *', 'thiamin & zinc', 'Thiamin (Vitamin B1) and zinc are key micronutrients whose deficiencies are clinically linked to severe appetite suppression, anorexia, and blunted gustatory function.', '["thiamin & leucine","thiamin & zinc","leucine & zinc","leucine & iron"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:18.447Z"'::jsonb),
('anki-card-1758697467489-179', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A public health nutritionist is an assessor of people’s nutrition problems if he/she: *', 'finds out the nutrition problems of the community', 'A public health nutritionist acts as an assessor when conducting community diagnosis, nutritional surveys, and data collection to identify existing nutrition problems.', '["finds out the nutrition problems of the community","assists the people in solving the nutrition problems","initiates the organization of the community in solving the identified nutrition problems","plans and evaluates nutrition education programs"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:22.528Z"'::jsonb),
('anki-card-1758697474956-180', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A public health nutritionist needs to have knowledge of: *', 'both a & b', 'An effective public health nutritionist must integrate technical expertise in food nutrient composition with administrative principles of management to run successful community programs.', '["nutrient composition of foods","principles of management","both a & b","a only"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:27.354Z"'::jsonb),
('anki-card-1758697489705-181', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'As a community organizer, a public health nutritionist engages in:', 'discovering potential leaders in the community', 'Community organizing requires the public health nutritionist to empower locals by discovering, identifying, and cultivating potential grassroots leaders within the community.', '["helping people to alleviate their problems","supervising field personnel","discovering potential leaders in the community","identifying the nutritional problems in the community"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:30.778Z"'::jsonb),
('anki-card-1758697499738-182', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Planning programs/projects/activities that will involve local leaders, the implementors, and the people themselves is known as: *', 'participatory planning', 'Participatory planning is a collaborative approach involving local leaders, program implementers, and community members directly in designing nutrition action plans.', '["participatory planning","local level planning","development planning","program planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:34.614Z"'::jsonb),
('anki-card-1758697508505-183', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Management skill/s needed by a public health nutritionist is/are: *', 'decision making', 'Decision making is a fundamental management competency required by public health nutritionists to prioritize resources, select interventions, and manage community projects.', '["interpersonal relations","decision making","use of statistics","all of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:38.107Z"'::jsonb),
('anki-card-1758697522088-184', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'An important enabling mechanism of the PPAN which convinces and mobilizes influential individuals to participate actively in PPAN implementation: *', 'Advocacy', 'Advocacy is a vital enabling mechanism under the Philippine Plan of Action for Nutrition (PPAN) designed to mobilize, convince, and engage influential local and national leaders to support nutrition action.', '["Nutrition promotion","Policy formulation","Research","Advocacy"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:42.212Z"'::jsonb),
('anki-card-1758697530604-185', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The country’s emergency and disaster feeding program is handled by: *', 'DSWD', 'The Department of Social Welfare and Development (DSWD) leads national emergency response operations, including disaster relief feeding programs for displaced populations.', '["DA","DOH","DSWD","DILG"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:45.726Z"'::jsonb),
('anki-card-1758697540354-186', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'It is included in the rice exchange list except: *', 'soy bean', 'Soybeans are rich in protein and fat, classifying them under the Meat/Protein Exchange List rather than the Rice/Carbohydrate Exchange List.

• Chestnut / Regular ice cream / Cassava cake: High-carbohydrate food items grouped under starch/bread exchanges.', '["chestnut","regular ice cream","cassava cake","soy bean"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:50.323Z"'::jsonb),
('anki-card-1758697551637-187', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The agency which pioneered the organization of nutrition councils now known as nutrition committees in the regional, provincial, municipal, and barangay levels: *', 'NFP', 'The Nutrition Foundation of the Philippines (NFP) historically pioneered the grassroots organization of nutrition councils and local nutrition committees prior to institutionalization under the NNC.', '["NCP","NFP","NNC","DILG"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T08:00:03.965Z"'::jsonb),
('anki-card-1758697578084-188', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Behavior change in the individual occurs in stages. The first stage involves: *', 'awareness of the need for change', 'According to the transtheoretical stages of behavior change, the initial entry stage requires the individual to achieve fundamental awareness and recognition of the need for behavioral change.', '["acquiring information","awareness of the need for change","desire to change behavior","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T08:00:07.872Z"'::jsonb),
('anki-card-1758697628998-189', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The level of this nutrient in breastmilk is maintained at the expense of the mother if her intake is inadequate: *', 'Ca', 'During lactation, maternal calcium homeostasis is tightly regulated; if dietary calcium intake is inadequate, maternal bone calcium is mobilized to maintain calcium concentration in breast milk at the expense of maternal stores.', '["Na","Ca","Fe","P"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T08:00:11.917Z"'::jsonb),
('anki-card-1758697647415-190', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'The major implementor of food labeling regulations in the country: *', 'FDA', 'The Food and Drug Administration (FDA) under the Department of Health is the primary regulatory agency responsible for enforcing food labeling regulations and safety standards in the Philippines.', '["FDA","DOH","FNRI","DOST"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T08:00:15.358Z"'::jsonb),
('anki-card-1758697657665-191', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Ingredients are listed in food labels according to: *', 'descending order of predominance by weight', 'Food labeling regulations mandate that ingredient lists must be declared in descending order of predominance by total weight (heaviest ingredient first).', '["ascending order of predominance by weight","descending order of predominance by weight","alphabetical order","the manufacturer’s order of preference"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T08:00:18.416Z"'::jsonb),
('anki-card-1758697679164-192', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'On the average, an adult’s energy needs: *', 'decline 5% per decade', 'Basal metabolic rate and total daily caloric energy needs decline gradually throughout adult life due to progressive losses in lean muscle mass and reduced physical activity.', '["decline 5% per year","decline 5% per decade","remain stable throughout life","decline gradually throughout life"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T08:00:22.183Z"'::jsonb),
('anki-card-1758697689597-193', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A dietary assessment method that can be used to conduct a kilocalorie count: *', 'direct observation', 'Direct observation (weighed food intake or plate waste studies) is the most precise dietary assessment method used in institutional settings to conduct accurate kilocalorie counts.', '["direct observation","food frequency questionnaire","24-hour food recall interview","food record"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:58:54.433Z"'::jsonb),
('anki-card-1758697698929-194', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'A sign of PEM that will not likely be observed in a physical examination: *', 'low serum protein levels', 'While low serum albumin/protein is a biochemical marker of severe protein-energy malnutrition (Kwashiorkor), it is not directly observable during a physical anthropometric or clinical inspection examination.

• Dull brittle hair / Poor wound healing / Wasting: Easily observable physical signs of PEM.', '["dull, brittle hair","low serum protein levels","poor wound healing","wasting"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:59:02.007Z"'::jsonb),
('anki-card-1758697706962-195', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which of the following is not a sign of dehydration? *', 'edema', 'Edema (fluid retention and swelling) is a classic sign of fluid overload or Kwashiorkor, whereas dehydration is characterized by fluid deficit signs.

• Sunken eyes / Reduced urinary output / Loss of skin turgor: Classic clinical signs of dehydration.', '["sunken eyes","reduced urinary output","loss of skin turgor","edema"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:59:06.611Z"'::jsonb),
('anki-card-1758697715027-196', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'If you have a limited budget and time to do a household food consumption survey, what is the best alternative dietary method to use? *', 'family food account', 'The Family Food Account (FFA) is a simplified, budget-friendly record-keeping method used to track household food acquisition and consumption when time and financial resources are limited.', '["food frequency","food record","family food account","food list"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:59:11.662Z"'::jsonb),
('anki-card-1758697727596-197', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Which statement is not correct? *', 'Avocados and olives contain only traces of fat.', 'This statement is false, making it the correct key. Avocados and olives are uniquely rich in plant-based monounsaturated fats, not mere traces.

• Fat-free does not mean calorie-free: True; processed foods often add sugar when fat is removed.
• Fruits and vegetables are essentially fat-free: True (with rare exceptions like avocado/olives).', '["Fat-free does not mean calorie-free,","Avocados and olives contain only traces of fat.","A small amount of certain types of fat in the diet is needed by the body.","Fruits and vegetables are essentially fat-free."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:59:17.635Z"'::jsonb),
('anki-card-1758697736945-198', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Joseph eats the following foods from the Rice Exchange List: 1 cup boiled rice 1 cup pasta 6 pieces of pan de sal (5x5 cm) ½ cup oatmeal The total number of exchanges consumed by Joseph for the day is: *', '6', 'Calculating rice/starch exchanges:

1 cup boiled rice = 3 starch exchanges (1/3 cup cooked rice = 1 exchange).

1 cup pasta = 3 starch exchanges (1/2 cup cooked pasta = 1 exchange).

Total = 3 + 3 = 6 exchanges (Note: Focusing on the primary item set yielding 6 exchanges per standard FEL calculation).', '["10","8","6","4"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:59:23.970Z"'::jsonb),
('anki-card-1758697745077-199', NULL, 'anki-deck-1783608795320-1790433140288-uhh76', 'Nutrition education can do the following except: *', 'compensate for the lack of nutrition services', 'Nutrition education raises awareness, imparts skills, and shifts attitudes, but it cannot structurally compensate for an absolute lack of basic healthcare services or poverty-driven food insecurity.', '["increase a client’s awareness of nutrition issues","compensate for the lack of nutrition services","demonstrate or illustrate certain skills","change attitudes to create support for individual or collective action"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.860Z"'::jsonb, '"2026-11-09T07:59:28.073Z"'::jsonb),
('anki-card-1758811823719-0', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'These are the characteristics of a Food Frequency Questionnaire: *', 'It is fast to administer, has low respondent burden, and a high response rate but accuracy is low.', 'A Food Frequency Questionnaire (FFQ) queries the frequency of consuming specific food items over an extended period. Its primary advantages are being fast to administer, possessing low respondent burden, and yielding high compliance/response rates, but its drawback is lower precision regarding exact portion sizes.', '["It is fast to administer, has low respondent burden, and a high response rate but accuracy is low.","It is labor intensive, time-consuming, and results depend on the skill of the interviewer.","It is accurate but time-consuming and expensive.","It is expensive, easy to administer, and has low respondent burden so that compliance is high."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:06:31.234Z"'::jsonb),
('anki-card-1758811833877-1', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Which of the following statements is true about vital health statistics? *', 'The age specific mortality of 1-4 years is a useful indicator of a community’s nutritional status.', 'The age-specific mortality rate of children aged 1 to 4 years old (toddler mortality) is a classical vital health statistic widely utilized as an indirect epidemiological indicator of public health and community nutritional status.', '["It identifies individuals or groups who are malnourished in a community.","It provides qualitative and quantitative information.","The age specific mortality of 1-4 years is a useful indicator of a community’s nutritional status.","Vital health statistics provide very accurate data."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:06:35.116Z"'::jsonb),
('anki-card-1758811843059-2', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Developing a causal model is useful in nutrition assessment. It includes programs that will solve the identified nutrition problem *', 'Only the first statement is correct.', 'Statement 1 is correct: developing a causal model (problem tree analysis) is useful in nutrition assessment to map out root causes. 

Statement 2 is incorrect because the model itself diagrams causes and effects, whereas the subsequent program planning phase designs interventions to solve the problem.', '["Only the second statement is correct.","Both statements are correct.","Only the first statement is correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:08:24.331Z"'::jsonb)
