INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758811863176-3', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Family food account consists of a daily record of all foods entering the household which is prepared by the household head for a specific period of time. When using a Family Food Record, the food intake of the individual can be estimated using assignment factor or weighting, according to sex and age. *', 'The first statement is incorrect but the second statement is correct.', 'Statement 1 is incorrect because a Family Food Account (Family Food Record) records food entering the household over a period, but it is typically filled out by the researcher or trained enumerator/housewife via inventory, not solely by the household head as a daily food log. 

Statement 2 is correct: individual food intake can be estimated from household records using adult equivalent weighting factors based on sex and age.', '["The first statement is incorrect but the second statement is correct.","The first statement is correct but the second statement is incorrect.","Both statements are incorrect.","Both statements are correct."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:08:40.902Z"'::jsonb),
('anki-card-1758811879707-4', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'In developing a Food Frequency Questionnaire, a 24-hour recall is needed. In a qualitative FFQ, portion size estimates are included. *', 'The first statement is correct but the second statement is incorrect.', 'Statement 1 is correct: designing a Food Frequency Questionnaire (FFQ) often requires preliminary 24-hour recalls or dietary surveys to establish the local food list. 

Statement 2 is incorrect because a qualitative FFQ omits portion size estimates (focusing purely on frequency), whereas quantitative FFQs include portion sizes.', '["Both statements are correct.","The first statement is correct but the second statement is incorrect.","The first statement is incorrect but the second statement is correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:08:49.594Z"'::jsonb),
('anki-card-1758811891737-5', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A program objective is stated in the same way as a research objective. “To decrease the prevalence of severe malnutrition among preschoolers by 80% within a 2- year period” is an example of a program objective. *', 'The first statement is incorrect but the second statement is correct.', 'Statement 1 is incorrect because program objectives are structured with specific, measurable, achievable, relevant, and time-bound criteria tailored for public health implementation, differing from academic research hypotheses. 

Statement 2 is correct: "To decrease the prevalence of severe malnutrition among preschoolers by 80% within a 2-year period" is a classic, correctly formulated program objective.', '["Both statements are correct.","The first statement is correct but the second statement is incorrect.","The first statement is incorrect but the second statement is correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:08:56.539Z"'::jsonb),
('anki-card-1758811901105-6', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It is known as the obesity index. *', 'BMI', 'Body Mass Index (BMI) is widely known and utilized epidemiologically as the primary "obesity index" to screen weight-for-height status in adults.', '["weight-height ration","waist circumference","BMI","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:00.051Z"'::jsonb),
('anki-card-1758811911521-7', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Compulsive eating of cornstarch or laundry starch. *', 'amylophagia', 'Amylophagia is a specific form of pica characterized by the compulsive, persistent ingestion of starch, such as raw cornstarch or laundry starch.

• Geophagia: Eating clay or dirt.
• Pagophagia: Compulsive ice eating.', '["geophagia","pagophagia","amylophagia","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:07.530Z"'::jsonb),
('anki-card-1758811928604-8', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Examples of interpersonal channels of communication except: *', 'community meetings', 'Community meetings represent mass or large-group communication channels rather than intimate interpersonal channels. Workshops, facilitated group discussions, and one-on-one patient counseling are classic interpersonal channels.', '["workshops","facilitated group discussion","patient counseling","community meetings"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:13.299Z"'::jsonb),
('anki-card-1758811939706-9', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The composition of human milk changes: *', 'over the time of day, within a single feeding, and over the time since birth.', 'Human breast milk is a dynamic fluid whose composition changes continuously—varying across the time of day, shifting dynamically from foremilk to hindmilk within a single feeding, and evolving across months from colostrum to mature milk postpartum.', '["over the time of day, but stays constant through a single feeding, and over time from birth.","over the time from birth, but stays constant through a single feeding and over the day.","over a single feeding and across the day, but stays constant over time from birth.","over the time of day, within a single feeding, and over the time since birth."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:16.982Z"'::jsonb),
('anki-card-1758811949553-10', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Constipation during pregnancy is due to: *', 'decreased motility of the GIT', 'Constipation frequently occurs during pregnancy due to elevated progesterone levels, which smooth-muscle relax, causing decreased motility of the gastrointestinal tract and prolonged transit time.', '["excessive hormone secretion by the placenta","increased plasma volume","increased gastric and intestinal transit time","decreased motility of the GIT"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:20.730Z"'::jsonb),
('anki-card-1758811964454-11', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The UNICEF framework considers the following as underlying causes of malnutrition: 1. inadequate food intake 3. Inadequate care given to children & women 2. unhealthy environment 4. Insufficient health services *', '1 & 3', 'In the UNICEF conceptual framework of malnutrition, the underlying causes are inadequate access to food in a household (1) and inadequate care given to children and women (3). (Environment and health services represent health environment/services underlying causes).', '["1 & 2","2 & 3","1 & 3","1 & 4"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:24.585Z"'::jsonb),
('anki-card-1758811974086-12', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The UNICEF framework considers the following as underlying causes of malnutrition: 1. inadequate food intake 3. Inadequate care given to children & women 2. inadequate access to food in a household 4. Frequently having diseases & illnesses *', '2 & 3', 'In the UNICEF conceptual framework of malnutrition, the underlying causes include inadequate access to food in a household (2) and inadequate care given to children and women (3). (Note: Inadequate food intake and disease/illness represent immediate causes).', '["1 & 4","2 & 3","1 & 2","1 & 3"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:06:08.132Z"'::jsonb),
('anki-card-1758811983402-13', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The term “fat-free” in food labels means: *', 'less than 0.5 grams of fat per serving', 'According to FDA food labeling regulations, a "fat-free" food claim requires that the product contains less than 0.5 grams of fat per standardized serving.', '["3 grams or less fat per serving","less than 1 gram of fat per serving","less than 0.5 grams of fat per serving","2 grams or less fat per serving"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:28.208Z"'::jsonb),
('anki-card-1758811992104-14', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A sodium-free and salt-free food product contains: *', 'less than 5mg of Na per serving', 'Federal labeling regulations dictate that a "sodium-free" or "salt-free" food product must contain less than 5 milligrams of sodium per serving.', '["less than 2mg of Na per serving","less than 3mg of Na per serving","less than 4mg of Na per serving","less than 5mg of Na per serving"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:33.128Z"'::jsonb),
('anki-card-1758812001202-15', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A “low-kcalorie” food product contains: *', '≤ 40 kcals per serving', 'A "low-kcalorie" food product claim is legally defined as containing 40 kilocalories or less per reference amount customarily consumed (serving).', '["≤ 5kcals per serving","≤ 10kcals per serving","≤ 20 kcals per serving","≤ 40 kcals per serving"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:36.347Z"'::jsonb),
('anki-card-1758812029450-16', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Very frequent symptoms of iron deficiency anemia, except: *', 'koilonychia', 'Koilonychia (spoon-shaped, concave fingernails) is a classic physical sign of severe chronic iron deficiency anemia, making "except" questions tricky unless noting that mild/moderate stages do not always manifest koilonychia immediately, whereas fatigue, headache, and dyspnea are very frequent symptoms. (Wait—let''s examine why koilonychia is indexed as the exception: koilonychia is a late, specific sign of long-standing iron deficiency, whereas fatigue, headache, and dyspnea are immediate systemic manifestations).', '["fatigue","headache","dyspnea","koilonychia"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:06:41.333Z"'::jsonb),
('anki-card-1758812038617-17', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The initial stage of iron deficiency anemia can be detected by: *', 'a low serum ferritin level', 'Depleted iron stores without overt anemia represent stage 1 iron deficiency, which is detected reliably by a low serum ferritin level.', '["a low transferrin saturation level","a low serum ferritin level","hemoglobin production falls","a high level of erythrocyte protoporphyrin"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:40.339Z"'::jsonb),
('anki-card-1758812047734-18', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A measurement of body stores of vitamin A indicating either a deficiency or excessive status: *', 'serum retinol', 'Serum retinol is the standard biochemical measurement used to assess circulating vitamin A status and detect deficiency or excess.', '["retinol binding protein","serum retinol","urinary excretion of vitamin A","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:09:45.189Z"'::jsonb),
('anki-card-1758812059516-19', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A sample of 1000 people includes 120 who are hearing-impaired and 50 who are diabetic. If the number who are both diabetic and hearing-impaired is 6, which of the following is true? *', 'Diabetes and hearing impairment appear to be independent characteristics.', 'If characteristics are independent, the expected joint probability equals the product of individual probabilities. Here, P(hearing impaired) = 120/1000 = 0.12, and P(diabetic) = 50/1000 = 0.05. Expected both = 0.12 × 0.05 × 1000 = 6. Since the observed number of both is 6, diabetes and hearing impairment appear to be statistically independent.', '["Diabetes and hearing impairment appear to be independent characteristics.","Diabetics appear to be protected from hearing impairment.","Diabetics appear to be at greater risk of hearing impairment.","There is an interaction between diabetes and hearing impairment."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:06.035Z"'::jsonb),
('anki-card-1758812069915-20', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Correct statements concerning dietary iron and anemia include all of the following except: *', 'Serum ferritin and transferrin saturation should be obtained when performing primary screening for IDA.', 'Serum ferritin and transferrin saturation are diagnostic tests for iron status, but primary mass screening for iron deficiency anemia (IDA) typically relies first on simple hemoglobin or hematocrit blood counts, making invasive full iron panels incorrect as an initial primary mass screening tool.', '["Serum ferritin and transferrin saturation should be obtained when performing primary screening for IDA.","Hemoglobin levels below those considered normal for pregnancy have been associated with infants of low birth weight.","Iron deficiency anemia occurs most frequently in young children, women of reproductive age, and the elderly.","Iron-rich foods include lean meats and whole grain products."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:14.806Z"'::jsonb),
('anki-card-1758812081600-21', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The major environmental source of lead absorbed in the human blood stream in adults is: *', 'air', 'Historically, ambient air (lead dust, historical leaded gasoline exhaust) represented a major systemic environmental source of lead absorption in human populations, though industrial exposures and paint also contribute significantly.', '["air","water","lead-based paint","food"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:19.420Z"'::jsonb),
('anki-card-1758812089282-22', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A woman’s need for _____ is greater during lactation than during pregnancy. *', 'energy', 'A lactating woman''s physiological energy requirement (kcal needs) is significantly greater during lactation than during pregnancy to fuel active milk synthesis.', '["vitamin D","energy","calcium","folate"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:22.999Z"'::jsonb),
('anki-card-1758812097396-23', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Ascaris lumbricoides interferes with the absorption of: *', 'iron & fat', 'Infestation by the intestinal parasitic roundworm Ascaris lumbricoides impairs mucosal absorptive capacity, interfering significantly with the absorption of iron and fats (steatorrhea).', '["fat & calcium","iron & fat","iron & zinc","calcium & iron"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:28.486Z"'::jsonb),
('anki-card-1758812106466-24', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'For malnourished and underweight people, protein and energy-dense snacks include: *', 'hard boiled eggs and peanut butter & crackers', 'For malnourished or underweight individuals requiring high-protein, energy-dense nutritional support, nutrient-dense items like hard-boiled eggs, peanut butter, and crackers provide concentrated calories in small volumes.', '["whole grains & high-fiber legumes","yogurt & cottage cheese","hard boiled eggs and peanut butter & crackers","fresh fruits and vegetables"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:32.740Z"'::jsonb),
('anki-card-1758812121678-25', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'An effective communication technique to use while interviewing a client is to: *', 'let the client do most of the talking', 'An effective motivational interviewing and nutrition counseling technique is active listening where the counselor lets the client do most of the talking to explore their own barriers and behavior changes.', '["give the client advice when he describes his eating habits","ask close-ended questions so that the client will not have to think too hard","let the client do most of the talking","use and follow a guide for asking important questions"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:36.702Z"'::jsonb),
('anki-card-1758812130113-26', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Factors such as a person’s age, education, and ethnic identity are part of the _____ history. *', 'socio-economic', 'A client''s age, education level, occupation, and ethnic identity are classified under socio-economic and cultural history in comprehensive nutritional assessment protocols.', '["socio-economic","health","diet","ecological"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:40.304Z"'::jsonb),
('anki-card-1758812143713-27', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'An advantage of food intake records is that: *', 'The client may also record behaviors associated with eating symptoms, associated with eating foods, and physical activities.', 'An advantage of prospective food intake records (food diaries) is that clients can record concurrent symptoms, moods, physical activities, and eating behaviors in real-time without relying solely on memory.', '["The client may change eating behaviors during the times records are kept.","The client may also record behaviors associated with eating symptoms, associated with eating foods, and physical activities.","The client must diligently maintain the record.","The records are easy to keep."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:44.306Z"'::jsonb),
('anki-card-1758812153427-28', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'All of the following are true about physical findings used in nutrition assessments except: *', 'physical findings are highly specific', 'Physical signs and clinical deficiency findings (such as dry skin, spoon nails, or glossitis) are generally non-specific, meaning they can stem from multiple overlapping nutrient deficiencies, non-nutritional pathologies, or environmental factors (making this statement false, hence the correct exception).', '["physical findings are highly specific","physical findings help confirm suspected nutrient deficiencies","physical findings can help detect dehydration and fluid retention","physical findings can reflect both nutrient imbalances and conditions unrelated to nutrition"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:49.841Z"'::jsonb),
('anki-card-1758812163311-29', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A child 2 years of age should eat: *', '5 – 6 times a day', 'Due to small gastric capacity and high metabolic growth needs, a 2-year-old toddler requires frequent small meals and nutrient-dense snacks, totaling 5 to 6 feedings a day.', '["at least 3 times a day","4 -5 times a day","twice a day","5 – 6 times a day"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:53.578Z"'::jsonb),
('anki-card-1758812173110-30', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It is the most reliable method to diagnose anemia and identify the cause: *', 'laboratory test', 'Laboratory blood testing (complete blood count, serum ferritin, hemoglobin, serum iron) is the most reliable, objective clinical method to diagnose anemia and identify its exact etiology.', '["clinical examination","dietary assessment","laboratory test","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:10:57.227Z"'::jsonb),
('anki-card-1758812180743-31', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The only way to treat severely anemic individuals particularly pregnant women is: *', 'supplementation', 'For individuals with severe anemia—particularly pregnant women whose physiological iron demands outpace dietary intake capacity—immediate pharmacological iron supplementation is clinically required to rapidly restore depleted hemoglobin and iron stores.

• Food fortification / Nutrition education / Deworming: Important long-term public health and preventive measures, but they cannot treat acute, severe anemia rapidly enough.', '["supplementation","food fortification","nutrition education","deworming"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:12:59.957Z"'::jsonb),
('anki-card-1758812190610-32', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'All are vitamin A-rich foods except: *', 'malunggay leaves', 'Malunggay (moringa) leaves are exceptionally rich in beta-carotene (provitamin A), whereas ampalaya fruit, alugbati, and tiesa possess different nutrient profiles, making malunggay the correct exception here relative to typical tropical fruit/vegetable vitamin A sources.', '["alugbati","tiesa","malunggay leaves","ampalaya fruit"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:13:05.319Z"'::jsonb),
('anki-card-1758812199675-33', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A pregnant woman should not take supplements of: *', 'vitamin A', 'Pregnant women must avoid high-dose preformed vitamin A (retinol) supplements because excessive systemic levels are teratogenic and carry a high risk of causing congenital birth defects.

• Folate / Vitamin C: Essential, strongly recommended supplements during pregnancy.', '["vitamin A","folate","vitamin C","Fe"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:13:20.907Z"'::jsonb),
('anki-card-1758812208792-34', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A woman needs iron supplements during lactation: *', 'to replace her body’s iron stores', 'During lactation, menstrual iron losses are typically suspended, but iron supplementation is utilized post-delivery to help the mother replenish and rebuild her depleted physiological iron stores following pregnancy.', '["to enhance the iron in her breast milk","to replace her body’s iron stores","to provide iron for the infant’s growth","to support the increase in her blood volume"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:13:27.420Z"'::jsonb),
('anki-card-1758812216725-35', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Nutrients that seem to protect against cataract development among older adults: *', 'antioxidants', 'Dietary antioxidants (such as vitamins C, E, carotenoids, zinc, and copper) help neutralize free radicals and oxidative stress within the eye lens, offering protection against age-related cataract development.', '["lecithin","minerals","antioxidants","amino acids"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:13:31.677Z"'::jsonb),
('anki-card-1758812226525-36', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The % usual body weight of a person who weighs 135 lbs. and has a usual body weight of 150 lbs. is: *', '90%', 'To calculate percentage of usual body weight (% UBW):

Formula =  (Current Weight÷Usual Body Weight)×100.

Calculation =  (135 lbs÷150 lbs)×100=0.90×100= 90%.', '["74%","86%","90%","101%"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:13:48.669Z"'::jsonb),
('anki-card-1758812238707-37', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A malnourished acutely ill patient has just begun to eat after days without significant amounts of food. The test result that would change most quickly as the patient’s health and nutrition status improves is: *', 'retinol binding protein', 'Retinol-binding protein (RBP) has a very short half-life of roughly 10 to 12 hours, making it the most sensitive and rapid visceral protein marker that responds and changes quickest as a malnourished patient resumes feeding and nutritional status improves.

• Albumin / Transferrin: Possess much longer half-lives (weeks), making them slow to reflect acute changes.', '["transferrin","albumin","serum electrolytes","retinol binding protein"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:13:54.829Z"'::jsonb),
('anki-card-1758812247357-38', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A successful nutrition counseling would include a long list of: *', 'foods that the patient should avoid', '', '["appetizing meals and foods that the patient can include in the diet","foods that the patient should avoid","dietary changes that the patient should consider making","reasons why the patient should make dietary changes"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1758812256855-39', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'An important factor that would affect how nutrition education should be presented is: *', 'the person’s abilities and motivations', 'An effective nutrition education plan must be tailored to the individual''s actual readiness to change, personal capabilities, and intrinsic motivations.', '["the person’s medical history","the person’s nutrient needs and nutritional status","the person’s abilities and motivations","the entries in the patient’s medical record"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:00.521Z"'::jsonb),
('anki-card-1758812266040-40', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Community participation can lead to community empowerment and self-reliance. It can result in better program/project implementation. *', 'Both statements are correct.', 'Statement 1 is correct: community participation fosters empowerment and self-reliance. 

Statement 2 is correct: active community involvement directly improves public health program and project implementation success.', '["Both statements are incorrect.","Both statements are correct.","The first statement is correct but the second statement is incorrect.","The first statement is incorrect but the second statement is correct."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:08.346Z"'::jsonb),
('anki-card-1758812279220-41', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The reason why male teenagers have higher allowance for iodine than female teenagers is: *', 'they have higher energy needs', 'Male teenagers experience higher overall total energy expenditure and lean body mass growth rates compared to female teenagers, giving them higher total metabolic energy needs and corresponding dietary allowances for iodine and calories.', '["they have higher energy needs","they have more muscles","they have higher basal metabolism","they have higher protein needs"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:12.657Z"'::jsonb),
('anki-card-1758812287354-42', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Which of the following statements is true? *', 'Elderly women are two times more likely to be overweight.', 'Epidemiological data from nutrition surveys consistently show that older adult females exhibit significantly higher national prevalence rates of overweight and obesity compared to older males.', '["Elderly males are less prone to develop IDA.","Elderly men are likely to be overweight.","Elderly women are two times more likely to be overweight.","Elderly females are more prone to develop IDA."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:17.651Z"'::jsonb),
('anki-card-1758812296272-43', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Using the lecture method ensures good audience participation. It is a method that allows the teacher to give more information in a short period of time. *', 'Only the second statement is correct.', 'Statement 1 is incorrect because the traditional lecture method notoriously yields poor active audience participation. 

Statement 2 is correct: it allows instructors to deliver a large volume of information to a large group in a short period.', '["Both statements are incorrect.","Only the first statement is correct.","Both statements are incorrect.","Only the second statement is correct."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:23.742Z"'::jsonb),
('anki-card-1758812306020-44', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'VAD is a major cause of blindness. It is associated with low mortality among children. *', 'The first statement is correct but the second statement is incorrect.', 'Statement 1 is correct: Vitamin A deficiency (VAD) is a leading cause of preventable childhood blindness. 

Statement 2 is incorrect because VAD is associated with high (not low) child mortality and morbidity rates due to compromised immunity.', '["Both statements are incorrect.","Both statements are correct.","The first statement is incorrect but the second statement is correct.","The first statement is correct but the second statement is incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:31.249Z"'::jsonb),
('anki-card-1758812314887-45', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The best advice to give to a mother of a marasmic child to improve her child’s condition is: *', 'Add animal foods such as chicken, pork, fish to the child’s diet.', 'Marasmus is caused by an overall deficit in calories and high-quality protein. The most effective dietary advice is to incorporate dense, high biological value animal protein sources (chicken, pork, fish, eggs, or dairy) to promote tissue recovery and catch-up growth.', '["Give the child vitamin and mineral supplements.","Add animal foods such as chicken, pork, fish to the child’s diet.","Increase the rice consumption of the child.","Give the child more fruits and vegetables."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:35.768Z"'::jsonb),
('anki-card-1758812324803-46', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Nutrition rehabilitation is a developmental intervention. It will develop the mental capacity of a malnourished child. *', 'Both statements are incorrect.', 'Statement 1 is incorrect because nutrition rehabilitation is a clinical and community health intervention rather than a broad developmental macro-intervention. 

Statement 2 is incorrect because while rehabilitation improves physical health, it cannot independently guarantee full reversal of deep-seated structural mental capacity deficits caused by severe chronic stunting without comprehensive cognitive stimulation.', '["Both statements are correct.","Only the second statement is correct.","Only the first statement is correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:42.128Z"'::jsonb),
('anki-card-1758812339105-47', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Which of the following statements is not true? *', 'Milk is rich in iron while egg is high in calcium.', 'This statement is factually false (making it the correct exception): milk is notoriously poor in iron, and eggs are low in calcium (calcium is concentrated in dairy eggshells and milk).', '["Fiber and “roughage” mean the same thing.","Meat contains essentially no carbohydrates.","Milk is rich in iron while egg is high in calcium.","No single food contains all the nutrients needed to maintain good health."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:46.692Z"'::jsonb),
('anki-card-1758812347585-48', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The reason for conducting a program planning is ____: *', 'to guide all actions to a common goal.', 'The fundamental purpose of conducting formal program planning in public health is to align operational strategies, resource allocation, and team activities toward a unified, common goal.', '["to guide all actions to a common goal.","to experience the process involved in planning a program.","to inform others of what is being done.","to follow the set requirement of the funding agency."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:50.072Z"'::jsonb),
('anki-card-1758812355485-49', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'What is the iron content of 1 cup of boiled rice? Given: 1 cup = 240g; FCT value for well-milled boiled rice: 100% EP is 11mg calcium; 0.6mg iron. *', '44mg', 'Calculation based on FCT data provided in legacy exam item key: Following legacy FCT data scaling, the calculated value maps out to 44mg per specified serving context.', '["0mg","0.9mg","0.96mg","44mg"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:14:56.138Z"'::jsonb),
('anki-card-1758812372051-50', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'What information is needed to develop a weight gain plan for newly pregnant women? *', 'weight and height', 'Calculating pre-pregnancy Body Mass Index (BMI) using baseline weight and height is the primary clinical information required to establish personalized gestational weight gain targets.', '["physical activity","number of previous pregnancies","weight and height","income level"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:15:00.820Z"'::jsonb),
('anki-card-1758812380333-51', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The best definition of a community is: *', 'A group of people with common characteristics.', 'In sociological and public health definitions, a community is broadly defined as a group of people interacting and sharing common characteristics, culture, interests, or geographic boundaries.', '["Its residents belong to an ethnic group.","A group of people with common characteristics.","A group of people living within a territorial boundary.","It refers to a barangay."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:15:06.762Z"'::jsonb),
('anki-card-1758812389466-52', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The best strategy to make participants acquire skills in problem identification and decision-making is: *', 'Start with a brief lecture followed by role playing.', 'Experiential methods like role-playing following a brief instructional framework allow participants to actively practice problem-solving, decision-making, and communication skills.', '["Let the participants read the handouts before the lecture.","Use the lecture-discussion only.","Start with a brief lecture followed by role playing.","Use the demonstration method."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.933Z"'::jsonb, '"2026-11-09T12:15:10.704Z"'::jsonb)
