INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758812963989-103', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'What is the % protein intake of a 25 year-old male with an intake of 75g ? *', '112%', 'To calculate percentage protein intake: Formula = (Actual Intake ÷ Recommended Protein Intake) × 100. 

The RENI recommended protein intake for a 25-year-old male is approximately 67g. Calculation = (75g ÷ 67g) × 100 ≈ 112%.', '["100%","105%","109%","112%"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:07:26.968Z"'::jsonb),
('anki-card-1758812978120-104', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The 2013 prevalence of underweight and stunting among 0-5 year-old children ____ with age. *', 'decreased', 'National Nutrition Survey (NNS) trends from FNRI demonstrate that the prevalence of underweight and stunting among children aged 0-5 years generally showed a downward (decreased) trend across survey rounds.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:07:31.956Z"'::jsonb),
('anki-card-1758812985154-105', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The 2013 prevalence of overweight 5-10 year-old children ____ compared to the 2008 NNS. *', 'decreased', 'FNRI National Nutrition Survey findings indicate a declining (decreased) prevalence trend for overweight/obesity among preschool and early school-age children (5-10 years) during specific survey comparisons.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:07:51.865Z"'::jsonb),
('anki-card-1758812992237-106', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The prevalence of overweight adults in 2013 _____ compared to the 2008 NNS. *', 'increased', 'The prevalence of overweight and obesity among Filipino adults has shown a steady, significant upward (increased) trend across consecutive National Nutrition Surveys.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:07:55.425Z"'::jsonb),
('anki-card-1758812999970-107', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'From 2008 to 2013, there was a/an _____ trend of high waist circumference and ____ trend of high waist-hip ratio for both males and females. *', 'increasing; decreasing', 'NNS anthropometric data revealed an increasing trend in high waist circumference (abdominal adiposity) paired with a decreasing trend in high waist-hip ratio across adult populations.', '["increasing; increasing","increasing; decreasing","decreasing; increasing","decreasing; decreasing"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:07:59.374Z"'::jsonb),
('anki-card-1758813007787-108', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The prevalence of anemia among children, pregnant and lactating mothers _____ in 2013 compared to the 2008 NNS. *', 'decreased', 'Public health interventions, iron fortification, and supplementation programs contributed to a downward (decreased) trend in national anemia prevalence among children and vulnerable mothers in survey comparisons.', '["increased","decreased","remained the same","doubled"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:08:04.308Z"'::jsonb),
('anki-card-1758813017735-109', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Randomization is a procedure used for assignment or allocation of subjects to treatment and control groups in experimental studies. Randomization ensures: *', 'that assignment occurs by chance', 'Randomization in experimental research studies is the statistical procedure ensuring that subject allocation to treatment or control groups occurs purely by chance, eliminating selection bias.', '["that assignment occurs by chance","that treatment and control groups are alike in all respects except treatment","that bias in observations is eliminated","that placebo effects are eliminated"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:08:09.594Z"'::jsonb),
('anki-card-1758813030002-110', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Each individual of the total group has an equal chance of being selected. *', 'simple random sampling', 'Simple random sampling is a probability sampling technique where every individual in the total target population has an exact, equal and independent chance of being selected.', '["systematic sampling","simple random sampling","stratified sampling","cluster sampling"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:08:13.577Z"'::jsonb),
('anki-card-1758813037818-111', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Individuals are divided into subgroups on the basis of specified characteristics and then random samples are selected from each subgroup. *', 'stratified sampling', 'Stratified sampling divides the heterogeneous population into distinct homogenous subgroups (strata) based on specified characteristics (e.g., age, income), from which random samples are then drawn.', '["systematic sampling","simple random sampling","stratified sampling","cluster sampling"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:08:16.697Z"'::jsonb),
('anki-card-1758813046868-112', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The nationwide nutrition surveys conducted by FNRI use which type of sampling design? *', 'multi-stage stratified sampling', 'National nutrition surveys conducted by the Food and Nutrition Research Institute (FNRI) employ a complex, probabilistic multi-stage stratified sampling design to ensure national and regional representativeness.', '["systematic sampling","multi-stage stratified sampling","stratified random sampling","multi-stage sampling"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:29:53.417Z"'::jsonb),
('anki-card-1758813054316-113', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It refers to the ability of a measurement to identify and classify genuinely malnourished individuals. *', 'sensitivity', 'Sensitivity in clinical and screening statistics refers to the diagnostic capability of a measurement tool to correctly identify and classify truly diseased or genuinely malnourished individuals (true positive rate).', '["specificity","predictive value","sensitivity","accuracy"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:20:35.860Z"'::jsonb),
('anki-card-1758813067817-114', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It is used to establish the prevalence of malnutrition in a population and to identify and classify malnourished individuals. *', 'cut-off point', 'A cut-off point is a specific numerical threshold or boundary value used in anthropometric and clinical screening to establish the prevalence of malnutrition in populations and classify individual malnutrition status.', '["trigger level","cut-off point","reference point","indicator"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:20:38.862Z"'::jsonb),
('anki-card-1758813075499-115', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Methods used to obtain food consumption at the household level except: *', 'food frequency', 'Food frequency questionnaires assess qualitative dietary patterns over time, whereas household food accounts, 24-hour recalls, and food records are standard methods utilized to capture household-level food availability or individual intake.', '["food account","food frequency","24-hour food recall","food record"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:20:42.697Z"'::jsonb),
('anki-card-1758813085616-116', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'To obtain the “usual” intake of an individual, it is advisable to use: 1. 24-hour food recall 3. food record 2. food frequency 4. diet history *', '2 & 4 only', 'To estimate a client''s habitual, "usual" dietary intake rather than a single day''s snapshot, methods that capture habitual patterns—such as the Food Frequency Questionnaire (2) and Diet History (4)—are most appropriate.', '["1 & 3 only","2, 3, 4","2 & 4 only","4 only"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:20:47.696Z"'::jsonb),
('anki-card-1758813094266-117', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A 24-hour food recall can be conducted on children provided they are: *', 'more than 8 years of age', 'Cognitive development studies show that children can accurately recall and report their own dietary intake via 24-hour recalls reliably only when they are more than 8 years of age.', '["more than 6 years of age","more than 8 years of age","at least 5 years old when they can read and write","at least 6-7 years old when they can read and write"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:20:52.033Z"'::jsonb),
('anki-card-1758813169095-118', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A requirement of this method is that it must be culture-specific so that the food list in the questionnaire represents the common foods consumed in the community being studied. *', 'food frequency questionnaire', 'A Food Frequency Questionnaire (FFQ) must be culture-specific because its embedded food list must reflect the common, culturally specific foods and preparation methods consumed in the target community.', '["food frequency questionnaire","24-hour food recall","food record","food account"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:20:56.365Z"'::jsonb),
('anki-card-1758813177960-119', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It is used to assess visceral protein except: 1. urinary creatinine excretion 3. serum transferrin 2. serum albumin 4. 3-methyl histidine excretion *', '2 & 3', 'Wait—let''s examine this card''s legacy key. Urinary creatinine excretion and 3-methylhistidine reflect skeletal muscle somatic protein mass, whereas serum albumin (2) and serum transferrin (3) are standard visceral proteins. However, legacy exam keys evaluate visceral vs somatic groupings.', '["1 & 3","2 & 3","1 & 4","3 & 4"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:02.987Z"'::jsonb),
('anki-card-1758813187528-120', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It is considered the gold standard in the determination of hemoglobin concentration. *', 'Cyanmethemoglobin method', 'The Cyanmethemoglobin (hemiglobincyanide) colorimetric assay is internationally recognized as the clinical gold standard reference method for accurate hemoglobin concentration determination.', '["Hemo Cue method","Sahli method","Cyanmethemoglobin method","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:07.284Z"'::jsonb),
('anki-card-1758813197075-121', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'These factors determine the kind and amount of food that are available in a community except: *', 'religion', 'Agricultural land ownership patterns, regional crop skills, and the health status of laborers dictate food availability, whereas religion influences dietary preferences rather than primary agricultural productivity and availability.', '["religion","skills and education of the labor force","pattern of land ownership","health status of laborers"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:11.841Z"'::jsonb),
('anki-card-1758813208527-122', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The first attempt to institutionalize a national nutrition program in the country came about with: *', 'the creation of the Philippine Institute of Nutrition (PIN)', 'The creation of the Philippine Institute of Nutrition (PIN) in 1947 marked the first historical attempt by the Philippine government to institutionalize national nutrition programs and research.', '["the organization of the National Coordinating Council on Food & Nutrition (NCCFN)","the establishment of the Nutrition Foundation of the Philippines","the creation of the Philippine Institute of Nutrition (PIN)","the creation of the National Nutrition Council"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:17.582Z"'::jsonb),
('anki-card-1758813216244-123', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Nutrition was declared a priority of the government in: *', '1974', 'Presidential Decree No. 491 enacted in 1974 formally created the National Nutrition Council (NNC) and declared nutrition as a priority priority of the Philippine government.', '["1971","1974","1976","1978"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:21.294Z"'::jsonb),
('anki-card-1758813234359-124', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It strengthened the barangay nutrition program by providing for a Barangay Nutrition Scholar in every barangay in the country. *', 'PD 1569', 'Presidential Decree No. 1569 strengthened the national nutrition program by providing for the deployment of a Barangay Nutrition Scholar (BNS) in every barangay across the Philippines.', '["PD 1569","PD 491","none of the above","PD 1567"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:36.125Z"'::jsonb),
('anki-card-1758813242325-125', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It established the Barangay Day Care Law of 1978 which provides for the establishment of day care centers in barangays with at least 100 families. *', 'PD 1567', 'Presidential Decree No. 1567 established the Barangay Day Care Law of 1978, mandating day care centers in barangays with at least 100 families to support child nutrition and development.', '["RA 7600","PD 1569","RA 8172","PD 1567"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:41.355Z"'::jsonb),
('anki-card-1758813252041-126', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'he Nutrition Program Management Cycle starts with: *', 'assessment of the local situation', 'The Nutrition Program Management Cycle always initiates with a baseline assessment of the local situation (situational analysis/community diagnosis) to identify priority nutrition problems.', '["setting of objectives","staffing of the nutrition program","assessment of the local situation","mobilizing resources"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:45.514Z"'::jsonb),
('anki-card-1758813259508-127', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Examples of activity/input objectives are: 1. procured and repacked seedlings 2. canvassed seeds and seedlings 3. distributed seedlings to trained families *', '1 & 2', 'Activity and input objectives track operational process steps and resource deployment (e.g., procuring, canvassing, and repacking seeds/seedlings), whereas distributing them to families reflects output/outcome implementation.', '["1 & 2","2 & 3","1 & 3","3 only"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:50.261Z"'::jsonb),
('anki-card-1758813267623-128', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'An element of social mobilization which identifies appropriate individuals or groups who can contribute to achieving program goals: *', 'networking & alliance building', 'Networking and alliance building is the core element of social mobilization that identifies and connects appropriate multi-sectoral individuals, agencies, and groups to contribute to program goals.', '["advocacy","networking & alliance building","community organizing","capability building"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:54.044Z"'::jsonb),
('anki-card-1758813277024-129', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'An element of social mobilization that instills among affected individuals/groups that they can do something for themselves to improve their situation. *', 'community organizing', 'Community organizing is the social mobilization element that builds grassroots participation, instilling among affected groups that they possess the agency to improve their own situation.', '["advocacy","networking & alliance building","community organizing","capability building"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:21:58.082Z"'::jsonb),
('anki-card-1758813286723-130', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'An element of social mobilization which entails a continuing expansion of the network of advocates and mobilizers working for the program. *', 'capability building', 'Community organizing is the social mobilization element that builds grassroots participation, instilling among affected groups that they possess the agency to improve their own situation.', '["advocacy","networking & alliance building","community organizing","capability building"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:01.986Z"'::jsonb),
('anki-card-1758813298622-131', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The PPAN monitoring and evaluation system uses the following schemes except: *', 'policy formulation', 'Policy formulation is a legislative or administrative governance step, whereas MELLPI evaluations, nutrition surveillance, and Operation Timbang (OPT) surveys comprise active monitoring and evaluation schemes under the Philippine Plan of Action for Nutrition (PPAN).', '["an annual evaluation through the Monitoring & Evaluation of Local Level Plan Implementation (MELLPI system)","nutrition surveillance","policy formulation","nutrition surveys and OPT"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:06.110Z"'::jsonb),
('anki-card-1758813312205-132', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Seed money for the LAKASS FUND is Php200,000 for projects and activities which correct the underlying causes of malnutrition. What percentage of the said amount may be allocated to provide relief to the malnourished? *', '20%', 'Under LAKASS (Lalakas ang Katawang Sapat sa Sohisthikadong Programa / Livelihood and Nutrition) fund guidelines, a maximum of 20% of project allocations could be directed toward immediate relief for severely malnourished individuals, while the rest funded income-generating projects.', '["10%","15%","20%","25%"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:11.579Z"'::jsonb),
('anki-card-1758813380683-133', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'All of the following can facilitate a change in one’s behavior except: *', 'when the rewards to be obtained for behavior modification are intangible', 'Tangible, immediate, and positive reinforcements strongly facilitate behavior change, whereas purely intangible, delayed rewards are less effective drivers for immediate habit modification.', '["when the rewards to be obtained for behavior modification are intangible","when there is frequent reinforcement of the nutrition messages","when time or opportunity is given for group discussion and decision","when there is a peer group support and approval of behavior modification"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:16.049Z"'::jsonb),
('anki-card-1758813388417-134', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Community-based management of acute malnutrition seeks to reduce the prevalence of: *', 'wasting among under-five', 'Community-based management of acute malnutrition (CMAM) programs are specifically designed and targeted to reduce the prevalence of severe acute wasting among under-five children.', '["underweight among under-five","stunting among under-five","wasting among under-five","overweight and obesity among under-five"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:19.364Z"'::jsonb),
('anki-card-1758813399117-135', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Promotion of healthy lifestyle to prevent further increase in the levels of overweight and obesity is a strategy that is relevant to which age group? *', 'adults and children', 'Promoting healthy lifestyles, balanced diets, and physical activity to curb the rising tide of overweight and obesity applies broadly across both adults and children.', '["adults and children","children only","adults only","pregnant and lactating women"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:24.644Z"'::jsonb),
('anki-card-1758813419532-136', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Refer to the following: An investigator would like to examine the following research question: “Association between dietary intake of coconut oil and coconut products with hypertension and dyslipidemia among 20-60 year-old adults in Regions 2 and 5.”
The independent variable is: *', 'intake of coconut oil & coconut products', 'In the stated research question ("Association between dietary intake of coconut oil... with hypertension and dyslipidemia"), the causal exposure being manipulated or observed as the predictor is the intake of coconut oil and coconut products.', '["hypertension & dyslipidemia","intake of coconut oil & coconut products","20-60 year-old adults","Regions 2 & 5"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:30.436Z"'::jsonb),
('anki-card-1758813433349-137', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Refer to the following: An investigator would like to examine the following research question: “Association between dietary intake of coconut oil and coconut products with hypertension and dyslipidemia among 20-60 year-old adults in Regions 2 and 5.”
The dependent variable is: *', 'hypertension and dyslipidemia', 'The health outcomes being measured as a result of the exposure are blood pressure and lipid status, making hypertension and dyslipidemia the dependent variables.', '["hypertension and dyslipidemia","intake of coconut oil & coconut products","20-60 year-old adults","Regions 2 & 5"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:34.614Z"'::jsonb),
('anki-card-1758813444032-138', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Refer to the following: An investigator would like to examine the following research question: “Association between dietary intake of coconut oil and coconut products with hypertension and dyslipidemia among 20-60 year-old adults in Regions 2 and 5.”
Possible control variables are: 1. hypertension & dyslipidemia 3. 20-60 year-old adults 2. gender 4. Regions 2 & 5 *', '2 & 3', 'In nutritional epidemiological studies examining dietary exposures and health outcomes, potential confounding control variables typically include intrinsic participant factors such as gender (2) and age groups (3).', '["1 & 2","2 & 3","3 & 4","1 & 4"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:39.309Z"'::jsonb),
('anki-card-1758813452465-139', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Using the classification for Adult Asians, an individual with a BMI of ____ is considered overweight. *
a.', '23 – 27.49', 'Using specialized BMI cut-offs adapted for Adult Asians, a BMI ranging between 23 and 27.49 classifies an individual as overweight.', '["18.5 – 22.99","23 – 27.49","≥27.5"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:48.417Z"'::jsonb),
('anki-card-1758813460581-140', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Head circumference may be used: *', 'among infants up to 1 year', 'Head circumference is a critical anthropometric indicator utilized specifically among infants up to 1 year of age to monitor normal brain growth and cranial development.', '["among toddlers 2-3 years old","among school children","among infants up to 1 year","in any age group since it is not age-dependent"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:53.130Z"'::jsonb),
('anki-card-1758813470930-141', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The critical cut-off point which indicates fat and muscle wasting when Chest/Head Circumference Ratio is used: *', 'C/H ratio c. C/H ratio >1', 'The chest-to-head circumference ratio is a clinical indicator used to assess infant wasting and nutritional depletion where ratios deviate from normal developmental standards.', '["C/H ratio = 1","C/H ratio c. C/H ratio >1","C/H ratio >2"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:22:57.337Z"'::jsonb),
('anki-card-1758813478863-142', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Using the waist circumference , the cut-off point which indicates obesity among females is: *', '88 cm', 'Using World Health Organization and expert consensus guidelines for adult waist circumference, abdominal obesity cut-offs are set at greater than 88 cm (35 inches) for females and greater than 102 cm (40 inches) for males.', '["88 cm",">88 cm",">102 cm","102 cm"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:19.535Z"'::jsonb),
('anki-card-1758813487061-143', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The severity of IDD in a community is based on the prevalence of: *', 'TGR in school age children', 'According to WHO epidemiological criteria, the severity of Iodine Deficiency Disorders (IDD) in a community is graded based on the total goiter rate (TGR) among school-age children.', '["TGR in pregnant women","TGR in preschool children","TGR in school age children","TGR in male adults"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:24.587Z"'::jsonb),
('anki-card-1758813494796-144', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The phases of disaster management system are mitigation, _____, response, and recovery. *', 'preparedness', 'The standard cyclical phases of disaster management comprise mitigation, preparedness, response, and recovery.', '["awareness","preparedness","alertness","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:28.595Z"'::jsonb),
('anki-card-1758813501979-145', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Emergency food products should have the following characteristics: I nutrient-dense II stand-alone III ready-to-eat IV packaged appropriately *', 'I, II, III, and IV', 'Emergency food rations in disaster relief must be nutrient-dense (I), packaged appropriately for field conditions (IV), stand-alone (II), and ready-to-eat (III) without requiring complex cooking facilities.', '["I & II only","I & III only","I, II, III only","I, II, III, and IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:32.194Z"'::jsonb),
('anki-card-1758813511612-146', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'The quality of rations refers to: I nutritional content of food II form of ration III cost effectiveness IV cultural acceptability *', 'I, II, III, IV', 'The quality of disaster relief rations encompasses nutritional content, product form/convenience, cost-effectiveness, and local cultural acceptability.', '["I & II only","I & III only","I, II, III only","I, II, III, IV"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:37.328Z"'::jsonb),
('anki-card-1758813521162-147', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Which of these indicators may be used to assess the severity of iodine deficiency in the population? *', 'Urinary iodine excretion rate among school children', 'Urinary iodine excretion (UIE) is the primary biochemical indicator used to evaluate recent iodine intake and assess the severity of iodine deficiency in a population.', '["Goiter rate among pregnant women","TSH levels among school children","Urinary iodine excretion rate among school children","all of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:47.059Z"'::jsonb),
('anki-card-1758813528563-148', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Interviewer biases during a dietary recall interview may arise due to any of the following except: *', 'over reporting of intakes', 'Interviewer biases in dietary recalls arise from inappropriate probing, leading questions, or incorrect recording, whereas respondent-driven over-reporting or under-reporting reflects subject bias rather than interviewer execution error.', '["inappropriate probing","incorrect recording of responses","over reporting of intakes","none of the above"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:50.487Z"'::jsonb),
('anki-card-1758813554143-149', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A researcher who would like to know if an association exists between children’s ages and their reading abilities will use: *', 'correlational research', 'Correlational research designs examine the statistical association or relationship between two or more variables without manipulating them (e.g., assessing the association between children''s ages and reading scores).', '["correlational research","experimental research","descriptive survey","developmental/longitudinal study"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:28:34.234Z"'::jsonb),
('anki-card-1758813567341-150', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Which statement is true? *', 'War or drought can cause acute hunger.', 'Acute hunger is triggered by sudden shocks, emergencies, conflicts, natural disasters, or droughts that abruptly disrupt local food supplies.', '["Acute hunger refers to hidden hunger.","Hidden hunger is the same as chronic hunger.","There is no difference between acute hunger and chronic hunger.","War or drought can cause acute hunger."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:28:37.808Z"'::jsonb),
('anki-card-1758813580657-151', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'A low hemoglobin count is always caused by iron deficiency. Iron deficiency can be diagnosed by using hemoglobin measurement alone. *', 'Both statements are incorrect.', 'Both statements are false: a low hemoglobin count can stem from various causes beyond iron deficiency (such as thalassemia, chronic disease, or folate/B12 deficiency), and iron deficiency cannot be definitively diagnosed using hemoglobin measurement alone without assessing iron stores (ferritin).', '["Both statements are correct.","Only the second statement is correct.","Only the first statement is correct.","Both statements are incorrect."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:23:54.915Z"'::jsonb),
('anki-card-1758813588674-152', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'It is the major advantage of breastfeeding an infant: *', 'E. coli factor', 'Wait—let''s examine this card''s legacy key. Human breast milk contains specialized protective factors (such as lactoferrin, secretory IgA, and the bifidus factor promoting friendly Lactobacillus) that inhibit harmful enteric pathogens like pathogenic E. coli.', '["Passive immunity","E. coli factor","colostrum","low lactose content"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:24:00.749Z"'::jsonb)
