('anki-card-1758813797097-171', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'In a household composed of 4 family members, who is most at-risk of becoming malnourished? *', 'a pregnant mother', 'Within a household, pregnant and lactating mothers have the highest physiological nutrient demands relative to body weight, placing them at the absolute highest risk of becoming malnourished when food resources are constrained.', '["a father working as a laborer","a school child","a preschool child","a pregnant mother"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:26:17.626Z"'::jsonb),
('anki-card-1758813805898-172', NULL, 'anki-deck-1783608806858-1790433140285-ai0do', 'Who are most likely to become malnourished? *', 'infants with low birth weight', 'Infants born with low birth weight (<2,500 grams) suffer from intrauterine growth restriction and underdeveloped physiological stores, making them at the highest risk of neonatal morbidity and malnutrition.', '["infants given infant formula with no complementary foods","infants with low birth weight","babies exclusively breastfed for 3 months only","babies born at full term"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.265Z"'::jsonb, '"2026-11-09T12:30:54.018Z"'::jsonb),
