('anki-card-1755065084805-2', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'A process of formulating a set of interrelated activities designed to meet set goals and objectives which answer community needs.', 'Program Planning', 'Program Planning', '["Planning","Management","Program Planning","Food and Nutrition Planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-19T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":4}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755065144252-3', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'An attempt to identify, develop, implement, and evaluate a range of policies and programs, which have as priority objectives improvement of nutritional status.', 'Food and Nutrition Planning', 'Food and Nutrition Planning', '["Planning","Management","Program Planning","Food and Nutrition Planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-08-27T20:00:00.000Z","interval":9,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755065249397-4', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'Defined as a decision-making process of identifying potential nutrition problems and needs of a specific population group, analyzing possible ways of preventing and controlling malnutrition...', 'Nutrition Program Management', 'Nutrition Program Management (NPM)', '["Nutrition Program Management","Program Planning","Food and Nutrition Planning","Management"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-08-29T20:00:00.000Z","interval":11,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755065369758-5', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'Characterized mainly by a program already prepared by a group external to a community or environment. "Top-down approach".', 'Pre-determined', 'Answer: Pre-determined', '["Pre-determined","Nutrition Honor Awardee","NOBNS","Objective"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-20T20:00:00.000Z","interval":2,"easeFactor":2.35,"repetitions":4}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755065416422-6', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'Based on the principle that people will suport a program if it is based on their "felt" needs. "Bottom-up"', 'Self-determined', 'Answer: Self-determined', '["Self-determined","Input indicator","Macrolevel planning","Effectiveness"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-20T20:00:00.000Z","interval":2,"easeFactor":2.35,"repetitions":5}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755065583348-7', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'Also known as participatory planning and may be a combination of the top-down and bottom-up planning. It involves the local leaders, the implementors, and the people themselves in planning the program.', 'Joint planning', '', '["Joint planning","Microlevel planning","Macrolevel planning","Strategic planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-08-29T20:00:00.000Z","interval":11,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1755065638078-8', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'The planning conducted at the local level; e.g barangay nutrition planning and municipal nutrition planning', 'Microlevel planning', 'Microlevel planning', '["Joint planning","Microlevel planning","Macrolevel planning","Strategic planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-08-28T20:00:00.000Z","interval":10,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755065672894-9', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'The planning undertaken at the national level; e.g. national nutrition planning', 'Macrolevel planning', 'Macrolevel planning', '["Joint planning","Microlevel planning","Macrolevel planning","Strategic planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-08-30T20:00:00.000Z","interval":12,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755065729175-10', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'A systematic process of envisioning a desired future and translating this vision into broadly-defined goals or objectives and a sequence of steps to achieve them', 'Strategic planning', 'Strategic planning', '["Joint planning","Microlevel planning","Macrolevel planning","Strategic planning"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-20T20:00:00.000Z","interval":2,"easeFactor":2.35,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
