('anki-card-1755067592335-22', NULL, 'anki-deck-1783608906608-1790433139854-54onr', 'The general thrust of the organization that is anchored on the vision. It is the primary motivation of the organization; its very reason for existence', 'Mission', '', '["Vision","Mission","Goal","Objective"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-08-19T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:29.105Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
