INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1755048513263-38', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?', 'Theory of Planned Behavior', 'The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:

1. Attitude toward the behavior: The community members'' personal belief that they will benefit from the nutrition program.
2. Subjective Norms: The perceived social pressure from their environment, specifically because their friends think it is also a good idea.
3. Perceived Behavioral Control: Their perceived ease or ability to execute the behavior, which fosters their readiness to get involved.

• Self-determination Theory: Focuses heavily on the internal spectrum of motivation (intrinsic vs. extrinsic), which would be the primary choice if the question emphasized doing the activity out of pure, inherent enjoyment.
• Precaution Adoption Process Model: This is a sequential stage-of-readiness model used to trace how an individual moves from complete unawareness to taking a specific health precaution.
• Health Belief Model: While it includes "perceived benefits", it relies heavily on an individual''s evaluation of a health threat (perceived susceptibility and severity of an illness), which is not the primary focus or motivator described in this scenario.', '["Precaution Adoption Process Model","Health Belief Model","Theory of Planned Behavior","Self-determination Theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:56:36.569Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:56:36.569Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:56:36.881Z"'::jsonb),
('anki-card-1755048610789-39', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'In promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in Zumba session because they are fond of dancing.', 'Self-determination Theory', 'Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already "fond of dancing" and "eager to participate," they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.

• Precaution Adoption Process Model (PAPM): This is a stage theory best used for tracking how people move from being completely unaware of a health hazard to taking a precautionary action. It does not focus on enjoyable physical activities.
• Health Belief Model (HBM): This model relies on a person’s perception of a health threat (susceptibility/severity) and balancing the benefits against the barriers of a preventative action. It is most useful for things like screening or vaccination compliance, not lifestyle activities done out of pure enjoyment.
• Theory of Planned Behavior (TPB): This theory posits that behavior is driven by intentions, which are shaped by attitudes, social pressures (subjective norms), and perceived behavioral control. It would be the choice if the question emphasized that the community members are joining because their friends or family think it is a good idea.', '["Precaution Adoption Process Model","Health Belief Model","Theory of Planned Behavior","Self-determination Theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:33.607Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:33.607Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:33.935Z"'::jsonb),
('anki-card-1755048660438-40', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which communication model is to support action?', 'Diffusion of Innovation', 'Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.

It focuses heavily on how information is packaged and delivered via specific communication channels over time to move groups from initial awareness directly into concrete adoption and action.

• Social cognitive theory / Self-efficacy model: These focus primarily on the cognitive determinants of a behavior—specifically how an individual''s confidence in their own ability (self-efficacy) and their social environment influence their personal behavior.
• Transtheoretical model: This is a stage theory that maps out an individual''s motivational readiness to change behavior (from Precontemplation to Maintenance) rather than functioning primarily as an operational communication model to drive group action.', '["Diffusion of Innovation","Transtheoretical model","Self-efficacy model","Social cognitive theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:31:19.582Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:31:19.582Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:31:19.897Z"'::jsonb),
('anki-card-1755048709234-41', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'A nutrition education method that includes bench conferences.', 'Group discussion', 'In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.

A bench conference occurs when a health worker or nutritionist gathers a small cluster of mothers, caregivers, or patients who are sitting together on a bench waiting for their turn in a rural health unit or clinic.

• Rather than structured one-on-one counseling behind closed doors, the educator utilizes this shared waiting space to initiate a small group interaction.
• Because it encourages the individuals sitting together to exchange ideas, ask questions, and learn from each other''s experiences under the guidance of the facilitator, it is classified academically under Group discussion methods.', '["Nutrition counseling","Group discussion","Mass media","Social marketing"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:39.468Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:39.468Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:39.779Z"'::jsonb),
('anki-card-1755048754384-42', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'What is the first step in conducting a training?', 'Needs assessment', 'In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.

The Training Process Order:

1. Needs assessment (Identify the gaps)
2. Identification of training objectives (Define what success looks like based on the gaps)
3. Preparation for training design / Planning (Outline methods, timelines, and content)
4. Implementation (Conducting the training)
5. Evaluation (Measuring the training''s effectiveness)', '["Planning for the training","Preparation for training design","Needs assessment","Identification of training objectives"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:08:19.321Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:08:19.321Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:08:19.644Z"'::jsonb),
('anki-card-1755048794899-43', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which is an example of non-verbal communication?', 'Tone of voice', 'Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying "I''m fine" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.', '["Tone of voice","Maps","Traffic signals","Reports"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:29:07.332Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:29:07.332Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:29:07.332Z"'::jsonb),
('anki-card-1755048848112-44', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which province is a priority area in the PPAN 2023-2028?', 'Basilan', 'The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.

Basilan is officially classified as a high-priority province, ranking 9th overall nationwide on the target list for intensive nutrition interventions and financial support.

The Top 10 highest priority provinces targeted for intensive, multi-sectoral nutrition interventions are:
1. Leyte
2. Sulu
3. Negros Occidental
4. Negros Oriental
5. Samar
6. Lanao del Norte
7. Masbate
8. Palawan
9. Basilan
10. Cebu

Key Broad Facts on the 34 Priority Areas:
• The Rest of the Top 16: Immediately following the top ten are Camarines Sur, Quezon, Zamboanga del Norte, Zamboanga del Sur, Maguindanao, and Bukidnon.
• Convergent Strategy: Government programs like the Tutok Kainan Dietary Supplementation Program prioritize these specific locations to provide nutritional support during the critical First 1,000 Days of child development.', '["Batangas","Basilan","Batanes","Benguet"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:13:32.270Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:13:32.270Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:13:32.589Z"'::jsonb),
('anki-card-1755048911627-45', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'The first Philippine food and nutrition plan was called ___?', 'Philippine Nutrition Program', 'In 1971, President Ferdinand Marcos Sr. issued Executive Order No. 285, authorizing the National Food and Agriculture Council (NFAC) to coordinate all nutrition activities.

This integrated nationwide operation was officially known as the Philippine Food and Nutrition Program (PFNP) or simply the Philippine Nutrition Program (PNP).

It served as the structural blueprint for national intervention before the creation of the National Nutrition Council (NNC) in 1974 and the later evolution of the framework into what we now call the Philippine Plan of Action for Nutrition (PPAN).

• Philippine Food and Nutrition Program (PFNP, 1971–1974): Before the formal creation of the council, the National Food and Agriculture Council (NFAC) coordinated the first four-year Philippine Food and Nutrition Program under Executive Order No. 285.
• Philippine Nutrition Program (PNP, 1974–1983): In 1974, Presidential Decree No. 491 established the National Nutrition Council (NNC), formally consolidating national nutrition activities into the Philippine Nutrition Program (PNP). It covered iterations such as PNP 1974–1977 and PNP 1978–1982.
• Food and Nutrition Plan / Philippine Food and Nutrition Plan (FNP / PFNP, 1984–1992): In the mid-1980s, the blueprint returned to a linked agriculture-and-nutrition scope, adopted as the Food and Nutrition Plan (1984–1987) and later updated under the post-1986 reorganized NNC (via Executive Order No. 234) as the Philippine Food and Nutrition Plan (1987–1992).
• Philippine Plan of Action for Nutrition (PPAN, 1993–Present): Following the global 1992 International Conference on Nutrition (ICN) in Rome, the Philippines aligned with international frameworks by adopting the title Philippine Plan of Action for Nutrition. 

While sometimes referenced alongside the medium-term planning cycles (e.g., MTPFNP/MTPPAN), the core official name of the plan series became PPAN, which has continued across successive medium-term cycles:
	• PPAN 1993–1998
	• PPAN 1999–2004
	• PPAN 2005–2010
	• PPAN 2011–2016
	• PPAN 2017–2022
	• PPAN 2023–2028', '["Food and Nutrition Plan","Philippine Food and Nutrition Plan","Philippine Nutrition Program","Philippine Plan of Action for Nutrition"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:21:41.907Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:21:41.907Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:21:42.228Z"'::jsonb),
('anki-card-1755048979873-46', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', '___ is a cluster of programs that is comprehensive, long-range in time frame, and includes defined goals, strategies, and guidelines for implementation.', 'Plan', 'According to the official Nutrition Program Management and community planning taxonomy, these structural terms are arranged in a specific hierarchy:

1. Plan: This is the highest level of the hierarchy. It refers to a comprehensive, long-range cluster of programs that contains overarching defined goals, strategies, and broad guidelines for implementation. A prime example is the Philippine Plan of Action for Nutrition (PPAN).
2. Program: This sits below a plan and is a set of interrelated projects that coordinates personnel, facilities, money, equipment, and supplies to accomplish a specific operational objective.
3. Project: This is a specific, time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timetable.
4. Policy: This serves as the broad, overarching legal or administrative instrument—the system of principles or rules—that guides subsequent development plans.', '["Policy","Plan","Program","Project"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T17:12:43.036Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T17:12:43.036Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T10:15:28.964Z"'::jsonb),
('anki-card-1755049041921-47', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', '___ is a specific and time-bound set of tasks or activities undertaken to achieve a given objective according to a defined budget and timeable.', 'Project', 'By standard administrative and project management definitions, a project is a temporary, specific, and time-bound endeavor. It possesses a clearly defined start and end date, sequential activities, and a dedicated budget allocated to produce a unique product, service, or result that fulfills a specific objective.

• Policy: A standing operational plan that serves as a broad, ongoing guideline for decision-making and employee behavior rather than a temporary set of tasks.
• Plan: The overarching blueprint or management process of setting broad organizational goals and mapping out how to achieve them.
• Program: A long-term, continuous framework that aggregates multiple individual projects under a shared theme or broader social goal, usually lacking a singular, short-term definitive timeline.', '["Policy","Plan","Program","Project"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:14:28.524Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:14:28.524Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:14:28.845Z"'::jsonb),
('anki-card-1755049104167-48', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'These are programs that address the immediate determinants of fetal and child nutrition and development.', 'Nutrition-specific', 'According to global health frameworks (such as The Lancet Maternal and Child Nutrition Series) and Philippine law (such as Republic Act 11148), interventions are categorized based on what causes of malnutrition they address:

• Nutrition-specific programs directly address the immediate determinants of fetal and child nutrition and development. These include factors like adequate food and nutrient intake, infant feeding and caregiving practices, and reducing the burden of infectious diseases. Examples include micronutrient supplementation, exclusive breastfeeding promotion, and the treatment of severe acute malnutrition.
• Nutrition-sensitive programs address the underlying determinants of malnutrition. These involve systemic sectors like agriculture, food security, social protection, clean water and sanitation (WASH), and female education.', '["Nutrition-related","Nutrition-sensitive","Nutrition-oriented","Nutrition-specific"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:06:25.619Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:06:25.619Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:06:25.945Z"'::jsonb),
('anki-card-1755049164082-49', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'These are development projects that were tweaked to produce nutritional outcomes.', 'Nutrition-sensitive', 'Nutrition-sensitive', '["Nutrition-related","Nutrition-sensitive","Nutrition-oriented","Nutrition-specific"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T17:11:56.989Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T17:11:56.989Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755049213945-50', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Who is the chair of Provincial Nutrition Committee?', 'Governor', 'At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:

• Provincial Level: Chaired by the Governor.
• City / Municipal Level: Chaired by the Mayor.
• Barangay Level: Chaired by the Barangay Captain (Punong Barangay).

The Provincial Nutrition Action Officer (PNAO) operates under the leadership of the Governor to handle the day-to-day operations, implementation, and coordination of the province''s nutrition programs.', '["Provincial Nutrition Action Officer","Barangay Captain","Mayor","Governor"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:44:30.687Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:44:30.687Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:44:30.687Z"'::jsonb),
('anki-card-1755049247445-51', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', '___is the country''s highest policy-making and coordinating body on nutrition.', 'NNC', 'The National Nutrition Council (NNC) is officially recognized by law as the Philippines'' highest policy-making and coordinating body on nutrition.

It was originally created under Presidential Decree No. 491 (The Nutrition Act of the Philippines) in 1974 and is an attached agency of the Department of Health (DOH). The NNC is responsible for orchestrating multi-sectoral strategies like the Philippine Plan of Action for Nutrition (PPAN) to eliminate hunger and malnutrition nationwide.

• NEDA (National Economic and Development Authority): The country''s premier social and economic development planning and policy coordinating body.
• NFP (Nutrition Foundation of the Philippines): A non-government, non-profit organization dedicated to promoting nutritional wellness.
• NCP (Nutrition Center of the Philippines): A private foundation that develops programmatic interventions and specialized nutritional products.', '["NCP","NNC","NFP","NEDA"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:57:24.751Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:57:24.751Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:57:25.029Z"'::jsonb),
('anki-card-1755049333558-52', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which law was enacted to contribute to the elimination of micronutrient malnutrition in the country, particularly iodine deficiency disorder, through the cost-effective preventive measure of salt-iodization?', 'RA 8172', '', '["RA 7600","RA 8172","RA 8976","RA 10028"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:45:44.046Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:45:44.046Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:45:44.370Z"'::jsonb),
('anki-card-1755049443603-53', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which law targets addressing specific micronutrient deficiencies by mandatory fortification of staple food items such as rice with iron, wheat flour with Vit A and iron, refined sugar with Vit A and cooking oil with Vit A and voluntary fortification of other food items?', 'RA 8976', 'Republic Act 8976 (The Philippine Food Fortification Act of 2000) mandates the fortification of staple foods to address widespread micronutrient deficiencies (specifically Vitamin A, Iron, and Iodine). It explicitly requires the mandatory fortification of:
	• Rice with Iron
	• Wheat flour with Vitamin A and Iron
	• Refined sugar with Vitamin A
	• Cooking oil with Vitamin A

It also covers the voluntary fortification of processed food items through the National Nutrition Council (NNC)''s "Sangkap Pinoy" seal program.

• RA 8172: The ASIN Law (Act for Salt Iodization Nationwide), which mandates the iodization of all food-grade salt.
• RA 10028: The Expanded Breastfeeding Promotion Act of 2009.
• RA 7600: The Rooming-In and Breastfeeding Act of 1992.', '["RA 7600","RA 8172","RA 8976","RA 10028"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:22:45.842Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:22:45.842Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:22:46.168Z"'::jsonb),
('anki-card-1755049517865-54', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'To prepare a potential BNS for deployment in his/her barangay, a BNS should undergo a training and  ___ days of practicum', '20 days', 'According to the National Nutrition Council (NNC) implementing guidelines under Presidential Decree No. 1569, a potential Barangay Nutrition Scholar (BNS) must successfully complete a two-part basic training program before full field deployment:

1. Didactic Phase: A classroom-based instruction course (traditionally structured as a 5-day to 10-day basic course) covering core technical inputs on malnutrition, health, the First 1000 Days, and data tools.
2. Practicum Phase: A mandatory 20-day hands-on community practicum.

During the 20 days of field practice, the scholar learns to master community nutrition management tasks under direct supervision. This includes operating anthropometric equipment to weigh and measure preschoolers (Operation Timbang Plus), conducting localized family profiling interviews, building a community nutrition spot map, and formulating a customized Barangay Nutrition Action Plan (BNAP).', '["5 days","10 days","15 days","20 days"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:59:35.499Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:59:35.499Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:59:35.825Z"'::jsonb),
('anki-card-1755049605576-55', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'In the BNS program guidelines, the direct trainer-supervisor of the BNS is:', 'District/City Nutrition Program Coordinator', 'According to the official guidelines issued by the National Nutrition Council (NNC), the District/City Nutrition Program Coordinator (D/CNPC) serves as the direct trainer-supervisor of the Barangay Nutrition Scholar (BNS).

• The D/CNPC is explicitly tasked with organizing, conducting, and supervising both the core didactic training and the subsequent 20-day local community practicum for new scholars.
• Guidelines specify that only in the structural or operational absence of an assigned D/CNPC will the local City/Municipal Nutrition Action Officer (NAO) step in to assume these training and supervision responsibilities.', '["District/City Nutrition Program Coordinator","City/Municipal Nutrition Action Officer","Provincial Nutrition Action Officer","Regional Nutrition Program Coordinator"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:14.150Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:14.150Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:14.476Z"'::jsonb),
('anki-card-1755049656458-56', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'The basic tasks of BNS are the following EXCEPT:', 'Leads in the preparation of the local nutrition action plan', 'According to the official National Nutrition Council (NNC) guidelines and the Barangay Nutrition Scholar (BNS) Handbook, the basic tasks of a BNS are clearly codified as:

1. Caring for the malnourished (identifying and tracking them via Operation Timbang Plus)
2. Mobilizing the community
3. Linkage-building
4. Keeping records (maintaining barangay nutrition profiles and family sheets)

The BNS does not lead the preparation of the Local Nutrition Action Plan (LNAP). Leadership and authorship of the plan fall under the mandate of the Local Nutrition Committee (LNC) and its Chairperson (the Punong Barangay / Barangay Captain). The role of the BNS is strictly to assist and provide data to the committee during the formulation of the Barangay Nutrition Action Plan (BNAP).', '["Caring for the malnourished","Mobilizing the community","Keeping records","Leads in the preparation of the local nutrition action plan"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:10:59.380Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:10:59.380Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:10:59.706Z"'::jsonb),
('anki-card-1755049737971-57', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'A suitable indicator for the evaluation of child feeding programs is change in:', 'Child''s weight for length/height', 'Supplementary feeding programs for infants and young children primarily target the eradication of wasting (acute malnutrition) and the restoration of normal body mass. The most sensitive, immediate, and reliable indicator to evaluate whether a short-term feeding program is successfully working is the change in a child''s weight-for-length (for infants under 2 years) or weight-for-height (for older children).', '["Child''s weight for length/height","Child''s height","Child''s improved feeding practices","Decreased incidence of diarrhea among children"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:20:27.873Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:20:27.873Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:20:28.201Z"'::jsonb),
('anki-card-1755049797869-58', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'A point person in nutrition who is a regular employee of and under the plantilla of NNC.', 'RNPC', 'The Regional Nutrition Program Coordinator (RNPC) is a permanent, regular civil service worker who occupies a formal plantilla item directly under the budget and structural organization of the National Nutrition Council (NNC). They serve as the head of the NNC Regional Secretariat, managing regional policy execution, monitoring local implementations of the PPAN, and coordinating across subnational administrative levels.

• CNAO / CNPC (City Nutrition Action Officer / City Nutrition Program Coordinator) & DNPC (District Nutrition Program Coordinator): These positions operate at the Local Government Unit (LGU) level. They are typically funded by the local city, municipality, or province budgets rather than holding a national NNC secretariat plantilla item, or they are designated from other existing local health department roles.', '["CNPC","DNPC","CNAO","RNPC"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:23:36.167Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:23:36.167Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:23:36.477Z"'::jsonb),
('anki-card-1755049879115-59', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'The Philippine Plan of Action for Nutrition is integrated and/or consistent with the following EXCEPT:', 'Philippine Environmental Plan', 'The Philippine Plan of Action for Nutrition (PPAN) serves as the country’s comprehensive multi-sectoral framework designed to combat all forms of malnutrition. It is systematically aligned with, and anchored into, the following major national development strategies:

• Philippine Development Plan (PDP): It is an integral sub-component of the national Philippine Development Plan framework, directly contributing to social transformation, human development, and poverty reduction goals.
• Health for All Agenda of the DOH: It directly supports the Department of Health’s principal universal healthcare blueprints (such as the National Objectives for Health and its respective action agendas).
• Ambisyon Natin 2040: It explicitly serves as an operational mechanism to meet the long-term vision of Ambisyon Natin 2040 by ensuring a healthy, well-nourished, and highly productive citizenry.', '["Philippine Development Plan","Health for All Agenda of DOH","Ambisyon Natin 2040","Philippine Environmental Plan"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:21:50.507Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:21:50.507Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:21:50.820Z"'::jsonb),
('anki-card-1755049938960-60', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'The national dietary supplement program targets the following age groups EXCEPT:', 'Infants 0-5 months', 'The National Dietary Supplementation Program (NDSP)—including its banner strategy Tutok Kainan—deliberately excludes infants 0 to 5 months old from receiving solid food or dietary supplements. According to global and local healthcare standards, infants in this age bracket must practice strict exclusive breastfeeding; introducing any form of dietary supplementation or complementary food would disrupt this and increase the risk of infection.

Targeted Vulnerable Groups Under the NDSP:
• Pregnant women (especially those classified as nutritionally at-risk, provided food support for 90 days).
• Young children 6 to 59 months old (broken down into infants/toddlers aged 6–23 months for complementary feeding, and children aged 24–59 months).
• School children (specifically severely wasted or wasted kindergarten to Grade 6 students enrolled in public schools).', '["Infants 0-5 months","Young children 6-59 months old","School children","Pregnant women"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:24:31.730Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:24:31.730Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:24:32.047Z"'::jsonb),
('anki-card-1755050015125-61', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'These are development projects that were tweaked to produce nutritional outcomes by targeting households with undernourished children.', 'Nutrition-Sensitive', 'Nutrition-sensitive', '["Nutrition-Specific","Nutrition-Sensitive","Nutrition Promotion","Nutrition Advocacy"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:08:34.804Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:08:34.804Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755050102842-62', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Mobilization of LGUs; policy development for food and nutrition; and strengthened management support are known as ____. These are necessary for the implementation of PPAN.', 'Enabling programs', 'Under the Philippine Plan of Action for Nutrition (PPAN) framework managed by the National Nutrition Council (NNC), these three components are specifically classified as enabling support programs:

1. Mobilization of LGUs for nutritional outcomes
2. Policy development for food and nutrition
3. Strengthened management support

These programs are designated to ensure that both nutrition-specific and nutrition-sensitive interventions are well-coordinated and effectively implemented across all local government levels.', '["Nutrition advocacy","Support services","Enabling programs","Facilitating initiatives"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:39:46.557Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:39:46.557Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:39:46.884Z"'::jsonb),
('anki-card-1755050161185-63', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'It is known as participatory planning that involves local leaders, implementers and people themselves in planning the program.', 'Joint planning', 'In program planning and management (particularly within nutrition and public health frameworks), Joint planning is explicitly defined as a type of participatory planning. It acts as a hybrid approach that combines elements of both top-down and bottom-up planning strategies. This method ensures comprehensive collaboration by actively involving local leaders, the implementers, and the target beneficiaries (the people themselves) directly in the program design.

• Microlevel planning: This refers strictly to planning conducted at the localized, community, or grass-roots level (such as creating a specific barangay or municipal nutrition plan).
• Strategic planning: This is a systematic process of mapping out a long-term vision, transforming that vision into broadly-defined strategic goals, and determining the sequential steps needed to achieve them.
• Food and nutrition planning: This is the overarching thematic discipline focused on formulating national policies, interventions, and guidelines to combat malnutrition and ensure food security.', '["Food and nutrition planning","Joint planning","Strategic planning","Microlevel planning"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:28:52.574Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:28:52.574Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:28:52.887Z"'::jsonb),
('anki-card-1755050219647-64', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'A principle in planning that refers to desired breadth and depth of the nutrition program.', 'Comprehensiveness', 'Comprehensiveness is a core principle in nutrition program planning and management. It explicitly dictates that the desired breadth and depth of whatever has been selected as the overall scope of the program or project must be thoroughly and accurately reflected in the actual plan.

• Balance: Emphasizes that all specific activities, tasks, and resource allocations are properly distributed so that they directly contribute to the achievement of the program''s objectives.
• Workability: Mandates that the plan must be operationally practical, meaning the objectives are completely realistic and achievable within the set timeframe and available resources.
• Appropriateness: Refers to how well the designed program fits the localized cultural, environmental, and socio-economic context of the target community.', '["Comprehensiveness","Balance","Workability","Appropriateness"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:16:51.662Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:16:51.662Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:16:51.983Z"'::jsonb),
('anki-card-1755050329410-65', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'The following is/are true for problem matrix, causal model, or problem tree EXCEPT:', 'Formulated by the BNS and presented to LCE as an advocacy tool', 'Formulating a problem tree, causal model, or problem matrix is not a task done individually by the Barangay Nutrition Scholar (BNS). According to local nutrition planning guidelines, it requires collective brainstorming and data analysis from the entire members of the Local Nutrition Committee (LNC) during their strategic planning meetings. The entire plan (not just the tree) is what is eventually packaged and presented to the Local Chief Executive (LCE) for adoption and funding.', '["Trace the chain of factors that can affect nutrition situation","Constructed by asking and answering a series of \"whys\" to understand better the factors","Formulated by the BNS and presented to LCE as an advocacy tool","Being updated every year as a result of new data on nutrition situation"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:19:00.747Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:19:00.747Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:19:01.066Z"'::jsonb),
('anki-card-1755050451854-66', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'It refers to concrete and specific statement of desired achievement. It is more focused and specific time dimension, client population and end results.', 'Objectives', 'In program planning and strategic management, objectives are defined as concrete, precise, and short-term statements of desired achievement. Unlike broad statements, an objective is specifically written to outline:
• A defined client population (who will benefit)
• A strict time dimension (when it will be achieved)
• Explicit, measurable end results (what the exact target is)

• Goals: These are broad, long-range, and general statements of an overall vision (e.g., "To reduce the prevalence of malnutrition in the region"), but they lack the operational and highly focused parameters of an objective.
• Mission: This explains the primary motivation, fundamental beliefs, and the overall reason for the organization''s existence.
• Vision: This is an aspirational, long-term description of a desired future state.', '["Vision","Mission","Goals","Objectives"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:17:36.525Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:17:36.525Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:17:36.837Z"'::jsonb),
('anki-card-1755050539867-67', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Among the criteria in selecting nutrition intervention, the following must not be missed:', 'Relevance, feasibiltiy, effectiveness', 'In classical program management and nutrition planning frameworks (such as those taught by FAO and the National Nutrition Council), interventions must pass three fundamental, non-negotiable filters during the screening phase:

1. Relevance (Appropriateness): Does the intervention directly solve the specific, prioritized nutrition problem of that population? (e.g., if the problem is Vitamin A deficiency, the intervention must be Vitamin A supplementation or food fortification, not general sanitation).
2. Feasibility (Practicability): Can it actually be done given the available budget, technical expertise, administrative infrastructure, and time constraints?
3. Effectiveness (Impact): Is there proven scientific or empirical evidence that this specific strategy will successfully lower malnutrition rates or improve the target nutritional indicators?', '["Relevance, feasibility, ease in targeting and evaluation","Relevance, feasibiltiy, effectiveness","Relevance, feasibility, cost-effectiveness","Relevance, feasibility, political support, willingness of beneficiaries to participate"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:30:36.334Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T09:30:36.334Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:30:36.670Z"'::jsonb),
('anki-card-1755050619445-68', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Pre-program evaluation carried out prior to implementation but after program formulation. It is necessary to reassess development needs and project feasibility.', 'Ex-ante evaluation', 'Ex-ante evaluation (literally meaning "before the event" in Latin) is a pre-program evaluation conducted after the program has been formulated but before actual implementation begins. Its primary purpose is to critically re-assess the localized development needs and rigorously audit the overall project feasibility and design viability before resources are officially spent.

• Program implementation review / Mid-term evaluation: These are ongoing, formative evaluations conducted during the execution phase of the project to check progress and implement corrective adjustments.
• Ex-post evaluation: This is an summative evaluation conducted at the very end or after the completion of the implementation stage to assess the total impact and outcomes.', '["Ex-ante evaluation","Ex-post evaluation","Mid-term evaluation","Program implementation review"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:30:21.562Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:30:21.562Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:30:21.851Z"'::jsonb),
('anki-card-1755050737774-69', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Food availability at the national level is not enough to provide food security for all households. Moreover, food security at the national and household level does not automatically result to good nutritional status of an individual.', 'Both statements are true', 'Statement 1 is true: Food availability at the national level (e.g., high national agricultural yields or food imports) speaks only to supply. It does not ensure food security for all households because of barriers to food access (such as low purchasing power, poverty, or poor market distribution systems).

Statement 2 is true: Even if a household is fully food secure and has plenty of food on the table, it does not guarantee that every individual in that house will achieve an optimal nutritional status. This is because individual nutritional status depends heavily on food utilization (how the body absorbs nutrients, which can be ruined by infections or illness), intra-household food distribution (e.g., gender or age disparities in who eats first), and caregiving practices.', '["Only the first statement is true","Only the second statement is true","Both statements are true","Both statements are false"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:49:40.551Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:49:40.551Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:49:40.889Z"'::jsonb),
('anki-card-1755050801439-70', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Understanding the ecology of food and nutrition helps in the identification of the root causes of malnutrition problem. It can also help identifying appropriate solutions.', 'Both statements are true', 'The first statement is true: The "ecology of food and nutrition" refers to the interaction between humans and the environmental, socio-economic, cultural, and political factors that dictate food availability, access, and biological utilization. Understanding this web helps investigators trace how systemic basic causes (like climate or policy) trickle down to underlying causes (like poor sanitation) and immediate causes (like inadequate dietary intake).

The second statement is true: By mapping out these exact ecological pathways, program planners can easily identify where a system is failing and design appropriate, targeted solutions—such as pairing nutrition-specific medical interventions with long-term, nutrition-sensitive agricultural or water security reforms.', '["Only the first statement is true","Only the second statement is true","Both statements are true","Both statements are false"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:16:41.634Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:16:41.634Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:16:41.951Z"'::jsonb),
('anki-card-1755050858702-71', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'It is a condition in which people do not get enough food to provide nutrients for the body.', 'Hunger', 'In public health and food security frameworks, hunger is defined as an individual-level physiological condition where a person does not have access to enough food to provide the essential nutrients and dietary energy their body needs to function normally.

• Food and nutrition security: This is a comprehensive, positive state where all people at all times have physical, social, and economic access to sufficient, safe, and nutritious food to meet their dietary needs for an active and healthy life.
• Malaise: This is a general, non-specific medical term describing a vague feeling of bodily discomfort, illness, uneasiness, or lack of energy.
• Food security: This focuses primarily on the broad availability, access, and stability of food supplies at the household or community level, rather than the specific physical condition of lacking food nutrients.', '["Food and nutrition security","Food security","Hunger","Malaise"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:54:36.296Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:54:36.296Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:54:36.614Z"'::jsonb),
('anki-card-1755050907565-72', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'All of the following are possible causes of transitory food insecurity except:', 'Lack of food storage', 'Transitory food insecurity is defined as a short-term, temporary, or sudden drop in the ability to produce or access enough food. It is typically triggered by unpredictable external shocks.

Droughts and floods are classic examples of acute environmental shocks that cause immediate, temporary food shortages. The lean season represents a cyclical, temporary phase between planting and harvesting where food supplies naturally drop for a limited period.

A lack of food storage, on the other hand, is a structural and systemic infrastructural deficiency. Because it is a permanent condition deeply embedded in a region''s agricultural infrastructure, it serves as a core driver of chronic food insecurity rather than a temporary or passing shock.', '["Lean season","Drought","Floods","Lack of food storage"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T07:53:01.342Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T07:53:01.342Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T07:53:01.621Z"'::jsonb),
('anki-card-1755050962412-73', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'It is the focus of the Sustainable Development Goal #2', 'Hunger and malnutrition', 'The United Nations Sustainable Development Goals (SDGs) are a blueprint of 17 global goals to build a better future. SDG #2 focuses directly on ending hunger, achieving food security, improving nutrition, and promoting sustainable agriculture.

• Health: This is SDG #3 (Good Health and Well-being).
• Access to clean water and sanitation: This is SDG #6 (Clean Water and Sanitation).
• Responsible production and consumption: This is SDG #12 (Responsible Consumption and Production).', '["Health","Access to clean water and sanitation","Hunger and malnutrition","Responsible production and consumption"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T17:12:50.464Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T17:12:50.464Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T10:22:02.136Z"'::jsonb),
('anki-card-1755051623566-74', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following provides information on annual food production, distribution of food within the country, and imports and exports?', 'Food balance sheets', 'A Food Balance Sheet (FBS) is a comprehensive macro-level statistical report compiled annually (often by national agencies like the Philippine Statistics Authority and globally by the Food and Agriculture Organization) to track a country''s total food supply and utilization over a specific timeframe.

It specifically synthesizes three critical dimensions of data:
1. Annual Food Production: The total quantity of food commodities cultivated domestically.
2. Imports and Exports: The flow of food moving into and out of the country''s borders to calculate net available supply.
3. Distribution/Utilization: How the total available food is split within the country across human consumption, livestock feed, seed use, manufacturing, and structural waste.

• Commercial market databases: These track private consumer buying trends, brand performance, and retail sales, rather than integrated national agricultural and border trade balances.
• Food records: This is an individual-level dietary assessment method where a single person logs their personal daily intake, which tells you nothing about nationwide trade or agricultural production.', '["Food balance sheets","Food records","Commercial market databases","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:05:43.163Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:05:43.163Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T09:05:43.478Z"'::jsonb),
('anki-card-1755051762226-75', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following statements are true regarding body measurements?', 'All of the above', 'All of the above', '["Infants and children under the age of two should be measured in the recumbent position","A knee height measurements is useful for people with spinal curvature","Head circumference is used as a measure of brain size in infants and young children","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T09:04:32.383Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T09:04:32.383Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1755052230619-76', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which of the following is not plagiarism?', 'Re-drawing the RCT process, it not original or specific', 'Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.', '["Transcribing or modifying text from any printed material (encylopedias, books, magazines, newspapers)","Using another student''s work and claiming it as your own","Using photographs, video or audio without permission","Re-drawing the RCT process, it not original or specific"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T08:10:26.536Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T08:10:26.536Z"'::jsonb, '"2026-09-26T14:32:29.958Z"'::jsonb, '"2026-10-16T08:10:26.864Z"'::jsonb),
('card-1792143191130-u5v7m', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Based on WHO cut-off points, a BMI of 27 is considered to be which of the following?', 'Overweight', 'WHO Standard Adult BMI Reference Ranges

The international classification breaks down weight status according to these specific metric boundaries:
• Underweight: BMI less than 18.5
• Normal weight: BMI of 18.5 to 24.9
• Overweight: BMI of 25.0 to 29.9 (A BMI of 27 falls directly in this bracket)
• Obese: BMI of 30.0 or higher', '["Overweight","Underweight","Normal weight","Obese"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:33:32.319Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:33:32.319Z"'::jsonb, '"2026-10-16T09:33:11.631Z"'::jsonb, '"2026-10-16T10:33:32.319Z"'::jsonb),
('card-1792143343281-3lpg5', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which dietary assessment method determines nutrient intake by asking how often certain foods are consumed?', 'Food frequency', 'By definition, a Food Frequency Questionnaire (FFQ) asks a participant to report how often (the rate or frequency, such as daily, weekly, or monthly) they consume specific items from a pre-defined checklist of foods over a designated timeframe.

• Diet history: This is an in-depth retrospective interview method that focuses on mapping out overall long-term habitual eating patterns, meal frequencies, cooking behaviors, and general food habits, rather than solely ticking off the frequencies of a structured food item checklist.
• 24-hour recall: This method asks the participant to remember and describe all food and beverages consumed over the exact, immediate 24 hours prior to the interview. It looks at a single-day snapshot of consumption rather than the general frequency of specific items over time.', '["Food frequency","Diet history","24-hour recall","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:33:49.298Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:33:49.298Z"'::jsonb, '"2026-10-16T09:35:44.101Z"'::jsonb, '"2026-10-16T10:33:49.298Z"'::jsonb),
('card-1792143476380-7whhk', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Wasting in children is defined as _________?', 'Weight-for-height that is more than 2 Z-scores below the reference', 'In pediatric anthropometry and public health frameworks managed by the World Health Organization (WHO), childhood malnutrition indicators are divided into distinct categories based on standard deviations (Z-scores) relative to a healthy reference population:

• Wasting (Acute Malnutrition): This measures body mass in relation to body length. It is defined as a weight-for-height (or weight-for-length) value that sits more than 2 standard deviations below (-2 Z-scores) the WHO Child Growth Standards. It signifies rapid, severe weight loss or a failure to gain weight, typically caused by recent starvation, severe illness, or infection.
• Stunting (Chronic Malnutrition): This measures linear growth retardation and is defined as a height-for-age value more than 2 Z-scores below the reference. It reflects long-term, ongoing nutritional deprivation.
• Underweight: This is a composite metric combining acute and chronic factors, defined as a weight-for-age value more than 2 Z-scores below the reference.', '["Weight-for-height that is more than 2 Z-scores below the reference","Height-for-age that is more than 2 Z-scores below the reference","Weight-for-age that is more than 2 Z-scores below the reference","None of the above"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:34:35.302Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:34:35.302Z"'::jsonb, '"2026-10-16T09:37:57.031Z"'::jsonb, '"2026-10-16T10:34:35.302Z"'::jsonb),
('card-1792143640290-s4x09', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Abdominal obesity in females is defined as a waist–hip ratio greater than:', '0.85', 'According to the World Health Organization (WHO) diagnostic guidelines, abdominal obesity (also known as central or android obesity) is measured using specific cutoff thresholds for the waist–hip ratio (WHR):

• Females: Abdominal obesity is defined as a waist–hip ratio greater than 0.85.
• Males: Abdominal obesity is defined as a waist–hip ratio greater than 0.90.

Any values exceeding these points indicate a high concentration of visceral fat around the abdominal organs, which is heavily associated with an elevated risk of developing type 2 diabetes, hypertension, and cardiovascular diseases.', '["0.85","0.70","0.95","1"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:34:43.228Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:34:43.228Z"'::jsonb, '"2026-10-16T09:40:41.593Z"'::jsonb, '"2026-10-16T10:34:43.228Z"'::jsonb),
('card-1792143832799-3zjc5', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'A function of public health nutritionist which focuses on assisting the community to solve their diet and nutrition related problems.', 'Program Implementer', 'According to standard professional public health nutrition curriculum tracking guides (like those from UPLB and the FNDRC mock boards), the roles are explicitly partitioned by these exact action fragments:

1. Program Implementer: The core action of this role explicitly states that the nutritionist "guides or assists the people in solving their diet and nutrition-related problems" directly in the field. It is an on-the-ground execution role focused on helping the community change behaviors and overcome immediate barriers.
2. Program Administrator: This function is academically defined as focusing on financial management, budgeting, and organizing the personnel who are involved in the nutrition program implementation.
3. Program Planner: Focuses on organizing program planning activities, assisting the community in identifying and prioritizing their problems, and designing the specific course of action to be taken.
4. Program Organizer / Assessor: Focuses on initiating the development of the organization or community network to clear the path for future interventions.', '["Program Implementer","Program Planner","Program Organizer","Program Administrator"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:34:52.469Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:34:52.469Z"'::jsonb, '"2026-10-16T09:43:54.483Z"'::jsonb, '"2026-10-16T10:34:52.469Z"'::jsonb),
('card-1792143900814-2647g', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', '“Hidden hunger” refers to:', 'Micronutrient deficiency', '"Hidden hunger" is a specific public health term used to describe a chronic lack of essential vitamins and minerals (micronutrients)—such as iron, iodine, vitamin A, and zinc—in a person''s diet.

Unlike classic undernutrition (like marasmus or wasting), where a person visibly looks emaciated due to a severe shortage of total calories or protein, hidden hunger often goes unnoticed. An individual may consume enough food or calories to feel full or maintain a normal body weight, but their body is still suffering from invisible, internal nutrient starvation that damages their immune system, cognitive development, and overall physical health.', '["Micronutrient deficiency","Calorie deficiency","Protein deficiency","Conditioned malnutrition"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:34:57.611Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:34:57.611Z"'::jsonb, '"2026-10-16T09:45:01.579Z"'::jsonb, '"2026-10-16T10:34:57.611Z"'::jsonb),
('card-1792144030281-4epjh', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'With reference to the UNICEF framework on the causes of undernutrition, unhealthy environment is categorized as:', 'Underlying cause', 'Under the globally recognized UNICEF Conceptual Framework on the Causes of Malnutrition, the factors that lead to undernutrition are structurally categorized into three distinct, hierarchical levels of causation:

1. Immediate Causes (Individual level): These are the direct physical factors that affect the person''s body—specifically inadequate dietary intake and diseases.
2. Underlying Causes (Household/Community level): These are the social, economic, and environmental factors that lead to those immediate causes. An unhealthy environment (such as a lack of safe water, poor sanitation, and inadequate hygiene) falls squarely in this category, alongside a lack of household food security and inadequate caregiving practices.
3. Basic Causes (Societal level): These are the systemic or structural root problems within a society, such as political instability, poverty, poor governance, and lack of resources.', '["Underlying cause","Immediate cause","Potential cause","Basic cause"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:35:19.712Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:35:19.712Z"'::jsonb, '"2026-10-16T09:47:10.965Z"'::jsonb, '"2026-10-16T10:35:19.712Z"'::jsonb),
('card-1792144140131-fgx12', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Which is true about the physical growth of an infant?', 'The infant’s length changes more slowly than the weight', 'An infant''s birth weight typically doubles by about 4 to 6 months, not two months. It does triple by one year, but the first half of the statement is biologically inaccurate for normal infant development.

Weight changes much faster and more dynamically than height (linear growth). During the first year, an infant''s weight triples (a 200% increase), whereas their length increases by roughly 50% (from an average of 20 inches at birth to about 30 inches at one year). Linear growth is a more gradual, steady biological process compared to rapid mass accumulation.', '["The infant’s length changes more slowly than the weight","Infants’ birth weight doubles by about two months and triples by one year","A and B are both TRUE","A and B are both FALSE"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:35:38.689Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:35:38.689Z"'::jsonb, '"2026-10-16T09:49:00.806Z"'::jsonb, '"2026-10-16T10:35:38.689Z"'::jsonb),
('card-1792144266554-0lcij', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'Babies with low birth weight:', 'Have high possibility of neonatal death compared with non-low birth weight infants', 'To understand why only this option is correct, let''s break down the clinical parameters of both statements:

• While it is true that low birth weight (LBW) infants have an increased susceptibility to infection and difficulty regulating their body temperature, they do not have mature kidneys. On the contrary, their organs are highly underdeveloped and immature, often leading to a reduced number of nephrons at birth and an increased risk of chronic kidney disease later in life. Because of the word "mature", Statement A is factually incorrect.
• Epidemiological statistics show that low birth weight is a leading driver of newborn mortality. LBW infants have a significantly higher possibility of neonatal death—ranging from 20 to 24 times more likely to die shortly after birth compared to infants born with a normal weight.', '["Have high possibility of neonatal death compared with non-low birth weight infants","Have an increased susceptibility to infection, difficulty regulating body temperature and mature kidneys","A and B are both TRUE","A and B are both FALSE"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:38:09.740Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-16T10:38:09.740Z"'::jsonb, '"2026-10-16T09:51:07.277Z"'::jsonb, '"2026-10-16T10:38:09.922Z"'::jsonb),
('card-1792144352906-h51rg', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'What is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?', '2:1', 'When preparing traditional, home-modified animal milk for an infant below three months of age, the standard pediatric and public health recommendation is a 2:1 ratio (2 parts whole cow''s milk or carabao''s milk to 1 part water), usually paired with a specific amount of sugar (around 5%).

Whole, undiluted animal milk contains an exceptionally high concentration of protein and minerals (such as sodium and phosphorus). A young infant''s immature kidneys cannot handle this heavy solute load, which can lead to severe dehydration.

Diluting the milk with 1 part water lowers the renal solute load to a safer level for infants under 3 months. After the child passes 3 months of age, their renal function matures slightly, and the ratio is typically advanced to 3:1 before moving to whole, undiluted milk later in infancy if commercial formula or breast milk is absolutely unavailable.', '["2:1","1:2","1:3","3:1"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:36:06.659Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:36:06.659Z"'::jsonb, '"2026-10-16T09:52:33.856Z"'::jsonb, '"2026-10-16T10:36:06.659Z"'::jsonb),
('card-1792144437027-op8jv', NULL, 'anki-deck-1783608929173-1790433142619-teu0e', 'The effortless expulsion of gastric contents caused by GI reflux in babies', 'Regurgitation', 'Regurgitation is clinically defined as the effortless, passive expulsion of swallowed food or gastric contents from the stomach back into the esophagus and mouth. In infants, this is primarily driven by an immature lower esophageal sphincter—a common, normal condition known as gastroesophageal reflux (GER) that usually resolves on its own as the baby grows.

• Colic: This refers to periods of intense, frequent, and unexplained crying in an otherwise healthy infant, often thought to be linked to gas or abdominal discomfort, rather than the physical ejection of stomach contents.
• Diarrhea: This describes loose, watery stools passing through the lower gastrointestinal tract, not an upward reflux into the mouth.
• Spitting-up-food: While this is the casual, everyday term parents use for this exact behavior, Regurgitation is the primary scientific and medical terminology used in public health exams to describe the involuntary mechanism itself.', '["Regurgitation","Colic","Spitting-up-food","Diarrhea"]'::jsonb, '["General Dietetics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, '', '{"dueDate":"2026-10-17T10:36:18.477Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-16T10:36:18.477Z"'::jsonb, '"2026-10-16T09:53:58.190Z"'::jsonb, '"2026-10-16T10:36:18.477Z"'::jsonb)
