INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1754295498266-137', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Adoption of Local Nutrition Action Plan by the LGU requires:', 'All of the above', 'Formal LNAP adoption by a local government unit requires multiple coordinated steps together: acceptance, approval, and endorsement by the local chief executive to the Sanggunian; sponsorship by a member of the local legislative body; and a resolution filed for adoption and funding.', '["Acceptance, approval and endorsement of LCE to Sangguniang Bayan/Panlalawigan","Sponsorship by a member of the local legislative body","Resolution filed for adoption and funding of the LNAP","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:03:48.820Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:03:48.820Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:03:48.820Z"'::jsonb),
('anki-card-1754295580230-138', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Field visits, meeting, record keeping, reporting, plan implementation reviews and special studies are known approaches for:', 'Monitoring and Evaluation', 'The correct answer is monitoring and evaluation combined, since this specific list of activities (field visits, meetings, record keeping, reporting, implementation reviews, special studies) spans both the ongoing, process-tracking functions of monitoring and the more in-depth, periodic assessment functions of evaluation.

• Monitoring alone or evaluation alone would not fully encompass this comprehensive list of approaches, since some (like routine field visits and record keeping) are more monitoring-oriented while others (like special studies) are more evaluation-oriented. 
• "Monitoring or evaluation" incorrectly implies these are separate, alternative approaches and not combined, integrated set of activities.', '["Monitoring","Evaluation","Monitoring and Evaluation","Monitoring or Evaluation"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:55:39.496Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:55:39.496Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:55:39.496Z"'::jsonb),
('anki-card-1754295703656-139', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'In the Monitoring and Evaluation of Local Level Plan Implementation (MELLPI) of the National Nutrition Council, which one refers to the highest award given to an LGU?', 'Nutrition Honor Award', 'The National Nutrition Council (NNC) utilizes the MELLPI framework to monitor Local Government Units (LGUs) and recognize them with progressive awards for outstanding performance in implementing the Philippine Plan of Action for Nutrition (PPAN):

• Nutrition Honor Award (NHA): This is the highest and most prestigious accolade given to an LGU. It is conferred only to LGUs that have maintained excellent nutrition program implementation for six (6) consecutive years, coming with a standard ₱1,000,000 cash prize and trophy.
• Consistent Regional Outstanding Winner in Nutrition (CROWN) Award: Given to an LGU that has been a regional winner for three (3) consecutive years. After achieving the CROWN, an LGU must successfully clear 1st and 2nd Year CROWN Maintenance Evaluations before it can qualify for the final Nutrition Honor Award.
• Green Banner Seal of Compliance: The initial tier of recognition awarded at the regional level to municipalities, cities, or provinces that excel in their annual nutrition performance benchmarks.', '["Green Banner Award","Consistent Regional Outstanding Winner in Nutrition","Nutrition Honor Award","National Outstanding Nutrition Award"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T12:47:03.246Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T12:47:03.246Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T12:47:03.246Z"'::jsonb),
('anki-card-1754295800386-140', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Views malnutrition as a disease which has to be cured by therapeutic approaches', 'Public Health', '• Social Welfare - malnutrition as deprivation of social safety net
• Agriculture - malnutrition due to limited food production
• Education - malnutrition is due to poor nutrition knowledge and skills', '["Social Welfare","Public Health","Agriculture","Education"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:24:36.581Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:24:36.581Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:24:36.581Z"'::jsonb),
('anki-card-1754295877164-141', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'In 2014, the National Nutrition Council Governing Board approved and adopted the guidelines on local nutrition planning that direct LGUS to come up with a ______ local nutrition action plan.', '3 year', 'The 2014 NNC guidelines for LGU-level Local Nutrition Action Plans, aligning with the local government''s typical elected term of office. Aligning the LNAP''s three-year cycle with local elected officials'' terms helps ensure political ownership and continuity of nutrition planning across the term of local leadership.', '["1 year","2 year","3 year","4 year"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:19:21.091Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:19:21.091Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:19:21.091Z"'::jsonb),
('anki-card-1754296007893-142', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'The LNAP is best prepared on the first semester of an election year to ensure that the nutrition agenda is integrated in the Executive Legislative Agenda which becomes the bases for local development plan and in-turn the annual investment plan. This is essential for:', 'Local Budgeting', 'Local budgeting because timely integration of the nutrition agenda into the Executive Legislative Agenda ensures that nutrition programs are properly reflected and funded in the subsequent Annual Investment Plan and local budget allocations. 

While local planning, implementation, and monitoring/evaluation are all eventually affected by this timing, the question mentioning ELA and AIP points most directly to securing adequate budgeting for nutrition programs.', '["Local Planning","Local Budgeting","Local Implementation","Local Monitoring and evaluation"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:08:57.545Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:08:57.545Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:08:57.545Z"'::jsonb),
('anki-card-1754296131638-143', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'In planning for a food for work intervention, the following key decision points must be considered, EXCEPT:', 'Will the assistance be in cash or kind?', 'By definition, food-for-work is already established as a food (in-kind) assistance modality, so this cash-versus-kind question does not apply as a decision point within a program already defined as food-based.', '["What food commodities will be used?","What volume of food will be given for each unit of work?","Will the assistance be in cash or kind?","What complementary services will be provided?"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:54:17.765Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:54:17.765Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:54:17.765Z"'::jsonb),
('anki-card-1754296241345-144', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'In planning for a supplementary feeding, the following are key decision points, EXCEPT:', 'What technology of production will be promoted?', '“What technology of production will be promoted?” refers to a food production intervention.', '["Type of commodity to be used to include for formulationss like Nutripak","What technology of production will be promoted?","Center-based vs home-based","Mechanism for community mobilization and particpation of parents"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:51:02.320Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:51:02.320Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:51:02.320Z"'::jsonb),
('anki-card-1754296322374-145', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'This serves as complementary activity in making the implementation of most of the nutrition interventions effective.', 'Nutrition Education', 'Nutrition Education functions as a cross-cutting, complementary activity that enhances the effectiveness of virtually all other nutrition interventions by ensuring beneficiaries understand and can sustain the benefits of programs like feeding, fortification, or livelihood support. 

Livelihood Assistance, Home/School/Community Food Production, and Supplementary Feeding are specific, standalone interventions.', '["Nutrition Education","Livelihood Assistance","Home, School, and Community Food Production","Supplementary Feeding"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:34:45.115Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:34:45.115Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:34:45.314Z"'::jsonb),
('anki-card-1754296410604-146', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Interventions that address the immediate causes of malnutrition.', 'Nutrition-Specific Interventions', 'Nutrition-specific interventions address the immediate, direct causes of malnutrition at the individual level (e.g., micronutrient supplementation, breastfeeding promotion, treatment of acute malnutrition).

• Nutrition-sensitive interventions instead address the underlying causes of malnutrition, such as food security, health services access, and caregiving practices, operating at a different causal level. 
• "Nutrition and Development Interventions" and "Nutrition-in-Development Interventions" are not standard, recognized terms in this classification framework.', '["Nutrition-Sensitive Interventions","Nutrition and Development Interventions","Nutrition-in-Development Interventions","Nutrition-Specific Interventions"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:32:34.637Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:32:34.637Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:32:34.836Z"'::jsonb),
('anki-card-1754296620729-147', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'In 1976, Letter of Instruction 441 directed the Department of Local Government and Community Development (now called DILG) to establish ____ in every region, province, city, municipality to implement nutrition action plans.', 'Functional nutrition committees', 'Functional nutrition committees, which LOI 441 specifically mandated be established at every administrative level to implement nutrition action plans, laying early institutional groundwork for what would later become the Local Nutrition Committees.', '["Functional nutrition councils","Functional nutrition committees","Functional nutrition coordinating system","Functional nutrition management system"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:23:58.281Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:23:58.281Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:23:58.281Z"'::jsonb),
('anki-card-1754296717625-148', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A BNS is trained volunteer community worker with the following qualifications EXCEPT:', 'At least high school graduate', 'At least high school graduate - the law states ‘elementary’ or ‘primary school’ (see PD 1569)', '["Bonadife resident of the barangay","At least high school graduate","Willingness to serve, part-time or full-time","More than 18 years old, but younger than 60 years old"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:52:15.829Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:52:15.829Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:52:15.829Z"'::jsonb),
('anki-card-1754296874551-149', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A decision-making process of identifying potential nutrition problems and needs of a specific population group, analyzing possible ways of preventing and controlling malnutrition, allocating resources based on needs and expectations, and taking deliberate action to address nutritional problems, including those related to monitoring and evaluation.', 'Nutrition Program Management', 'Nutrition Program Management is executing, supervising, and coordinating all activities to achieve program goals.

• Nutrition Program Planning - designing the specific program: defining objectives, strategies, resources, and implementation steps.
• Nutrition Intervention - specific action designed to directly improve nutritional status (e.g., supplementation, education).
• Food and Nutrition Planning - macro-level process to set national/regional policies and strategies for food supply and consumption.', '["Nutrition Program Management","Nutrition Program Planning","Nutrition Intervention","Food and Nutrition Planning"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:37:36.627Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:37:36.627Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:37:36.627Z"'::jsonb),
('anki-card-1754296966446-150', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A researcher wants to conduct a study wherein men with coronary artery disease and a comparable group of men without coronary artery disease were asked about their prior use of aspirin. This is an example of which type of study?', 'Case control', 'This scenario perfectly illustrates the design of a case-control study based on two defining factors:

• Selection by Outcome (Disease Status): The researcher selects participants based on whether they already have the condition of interest. The "cases" are the men with coronary artery disease, and the "controls" are the comparable group of men without the disease.
• Retrospective Assessment: The researcher then looks backward in time ("asked about their prior use of aspirin") to compare how frequently each group was exposed to the factor being studied.

• Ecological study - Comparing the average per capita salt intake across ten different countries to the average national hypertension rate in those same countries.
• Randomized clinical trial - Dividing 500 patients with a specific disease into two groups: one receiving a new drug and one receiving a placebo (or standard treatment), and then following both groups for a year to see which group has a better outcome.
• Case series - A doctor publishing a report detailing the clinical presentation, diagnosis, treatment, and outcomes for three unusual patients presenting with the same rare cluster of symptoms at their clinic over a six-month period.', '["Case control","Ecological study","Randomized clinial trial","Case series"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T14:55:11.634Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T14:55:11.634Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T14:55:11.634Z"'::jsonb),
('anki-card-1754297053708-151', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'It refers to the epidemiological approach which explains the occurence, nature, and extent of a disease:', 'Man-Agent-Environment Triad', 'Man-Agent-Environment triad - epidemiological model; analyzing disease causation via host, pathogen, and surroundings.

• Triple A approach - cycle for planning: assessment, analysis, action
• UNICEF framework - three-level causes of malnutrition: basic, underlying, and immediate (food/health).
• Undernutrition infection cycle - vicious spiral where poor nutrition weakens immunity, increasing infection risk, which worsens nutrition.', '["Triple A approach","Man-Agent-Environment Triad","UNICEF framework","Undernutrition infection cycle"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:47:05.807Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:47:05.807Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:47:06.113Z"'::jsonb),
('anki-card-1754297142507-152', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A good survey sample is one in which:', 'the subjects are heterogenous', 'In most social, health, and market research, the goal is to have a representative sample that reflects the heterogeneity (diversity) of the larger population.', '["the entire population to be studied is included","all the characteristics of the population are represented proportionately","the subject are willing volunteers","the subjects are heterogenous"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:35:29.932Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:35:29.932Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:35:30.130Z"'::jsonb),
('anki-card-1754297204152-153', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'It describes the adequacy with which any measurement or index reflects the nutritional parameter of interest:', 'Validity', 'Validity - measuring what you intended to measure (truthfulness)

• Accuracy - how close a measurement is to the true or accepted value (correctness)
• Specificity - a test''s ability to correctly identify negative cases (truly non-diseased or non-affected).
• Precision - how close repeated measurements are to each other (consistency/reproducibility)', '["Validity","Accuracy","Specificity","Precision"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:27:04.975Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:27:04.975Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T13:27:04.975Z"'::jsonb),
('anki-card-1754297244199-154', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A measure of years in perfect health lost:', 'DALY', 'DALY - Disability-Adjusted Life Year (Burden of Disease): Measures the total healthy life years lost (YLL + YLD).

• YLL - Years of Life Lost (Mortality): Measures the number of years lost due to premature death.
• YLD - Years Lived with Disability (Morbidity): Measures the number of years lived in less than full health due to illness or injury.
• QALY - Quality-Adjusted Life Year (Health Economics): Measures the value of a year of life adjusted by its quality or utility.', '["YLL","YLD","QALY","DALY"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:39:31.398Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:39:31.398Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:39:31.589Z"'::jsonb),
('anki-card-1754297296463-155', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following methods can be used to estimate height?', 'Arm span', 'When a patient cannot stand straight due to physical disabilities, bedridden status, or severe skeletal deformities (such as kyphosis or scoliosis), indirect anthropometric measurements are used to estimate stature:

 There is a strong biological correlation between an individual''s arm span and their actual height. In a healthy adult, the distance from the tip of the middle finger of one hand to the tip of the middle finger of the other hand (when arms are extended fully at a 90-degree angle from the torso) roughly equals their max height.

Other common clinical measurements used in height-estimation equations include knee height and demispan (half of the arm span).

• Skinfold thickness - fat deposits
• MUAC - muscle mass
• Chest circumference - chest size', '["Arm span","Skinfold thickness","MUAC","Chest circumference"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T11:23:50.928Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T11:23:50.928Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T11:23:51.105Z"'::jsonb),
('anki-card-1754297385077-156', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following is a dietary assessment method which uses specific food item list to record intakes over a given period?', 'Food frequency', 'Food frequency questionnaire (FFQ), which is defined precisely by its use of a structured, predetermined list of food items that respondents report consuming over a specified recall period (e.g., past month or year). 

• The 24-hour food recall instead captures all foods consumed in the preceding 24 hours without being restricted to a predetermined food list. 
• Diet records involve prospectively recording all foods eaten in real time, also without a fixed food item list. 
• Food weighing involves precisely weighing all food consumed.', '["24-hour food recall","Food frequency","Diet record","Food weighing"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:55:27.488Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:55:27.488Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T13:55:27.682Z"'::jsonb),
('anki-card-1754297544770-157', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following describes nutrition surveillance?', 'Keeping watch over nutrition in order to make decisions that will lead to improvement in nutrition in population', 'This responds to the main goal of nutrition surveillance is to continuously monitor a population''s nutritional status so leaders can make informed decisions and policies that improve health and fix nutrition problems.', '["Keeping watch over nutrition in order to make decisions that will lead to improvement in nutrition in population","Provides information about dietary intake patterns, specific foods consumed and estimated nutrient intake","Mortality and morbidity data to identify groups at high risk and indicate the extent of risk of the community","All of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:32:19.169Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:32:19.169Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:32:19.372Z"'::jsonb),
('anki-card-1754297606534-158', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'It is a condition when thiamin is deficient', 'Beri-beri', 'Beri-beri is a classic, well-established clinical deficiency disease resulting from inadequate thiamine (vitamin B1) intake, presenting with neurological (dry beri-beri) or cardiovascular (wet beri-beri) manifestations. 

• Pellagra - niacin (vitamin B3) deficiency 
• Ariboflavinosis - riboflavin (vitamin B2) deficiency 
• Tiqui-tiqui is actually a traditional Filipino rice bran extract historically used as a treatment/cure for beri-beri', '["Pellagra","Ariboflavinosis","Beri-beri","Tiqui-tiqui"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:50:53.657Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:50:53.657Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:50:53.657Z"'::jsonb),
('anki-card-1754297652397-159', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Multiple replicates of 24-hour food recall is used to measure nutrient intake to meet ___ level of study objectives', '2nd', 'Second-level study objectives (often referred to as secondary or specific objectives) break down primary research goal into actionable, measurable steps. First-level (primary) objective states WHAT you want to achieve overall, second-level objectives explain HOW you will achieve it by focusing on specific variables, steps, or populations.', '["1st","2nd","3rd","4th"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:27:10.015Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:27:10.015Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:27:10.214Z"'::jsonb),
('anki-card-1754297710612-160', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Moderate IDD in the population is indicated by median UIE level of:', '20-49 µg/L', 'The severity of Iodine Deficiency Disorders (IDD) in a population is classified based on the Median Urinary Iodine Excretion (UIE) or Concentration (UIC) levels:
• Severe Iodine Deficiency: Median UIE of <20 µg/L
• Moderate Iodine Deficiency: Median UIE of 20–49 µg/L
• Mild Iodine Deficiency: Median UIE of 50–99 µg/L
• Adequate Iodine Nutrition: Median UIE of 100–199 µg/L (Target public health range for school-age children)', '["20-49 µg/L","<20 µg/L","50-99 µg/L",">100 µg/L"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:31:26.812Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:31:26.812Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:31:27.012Z"'::jsonb),
('anki-card-1754297799490-161', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'The plasma retinol level of Flora is 25 µg/dL. How do you interpret this value?', 'Flora has an acceptable plasma retinol level', 'In public health and clinical nutrition, the World Health Organization (WHO) and the National Institutes of Health (NIH) establish specific reference thresholds for circulating plasma or serum retinol to evaluate Vitamin A status:

• Deficient / Severe Deficiency: Less than 10 µg/dL (< 0.35 µmol/L).
• Low / Subclinical Deficiency: 10 to 20 µg/dL (0.35 to 0.70 µmol/L).
• Acceptable / Adequate: More than 20 µg/dL (≥ 0.70 µmol/L).

Flora''s level is 25 µg/dL, which places her comfortably above the 20 µg/dL cutoff, classifying her Vitamin A status as acceptable or adequate.', '["Flora has a deficient plasma retinol level","Flora has a low plasma retinol level","Flora has an acceptable plasma retinol level","Flora has high plasma retinal level"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:34:55.869Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:34:55.869Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:34:56.070Z"'::jsonb),
('anki-card-1754297871940-162', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Using the WHO standard, what is the classification of goiter if the thyroid gland is enlarged and easily visible from a distance?', 'Grade 2', 'In 1994, the WHO, UNICEF, and the International Council for Control of Iodine Deficiency Disorders simplified the scale down to the standard 3-tier system:

• Grade 0: No goiter (neither palpable nor visible).
• Grade 1: A mass that is palpable but not visible when the neck is in a normal position.
• Grade 2: A swelling that is clearly visible when the neck is in a normal position and is consistent with an enlarged thyroid upon palpation.', '["Grade 0","Grade 1","Grade 2","Grade 3"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:32:06.621Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:32:06.621Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:32:06.823Z"'::jsonb),
('anki-card-1754297916202-163', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Keshan disease is a deficiency in?', 'Selenium', 'The correct answer is selenium, a trace mineral deficiency specifically linked to Keshan disease, an endemic cardiomyopathy first identified in selenium-poor regions of China.

Keshan disease is an endemic, potentially fatal form of dilated cardiomyopathy (weakening and enlargement of the heart muscle).

 It is directly linked to severe dietary selenium deficiency, typically occurring in rural regions where the soil lacks selenium, leaving local agricultural crops deplete of the mineral. It was first documented in Keshan County, China.', '["Selenium","Chromium","Zinc","Folate"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:56:46.965Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:56:46.965Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:56:46.965Z"'::jsonb),
('anki-card-1754297971150-164', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A condition characterized as having sand paper feel of the skin:', 'Follicular hyperkeratosis', 'In clinical nutrition and dermatology, follicular hyperkeratosis (also known as phrynoderma or "toad skin") is classic textbook-defined by a rough, sandpaper-like texture on the skin.

This condition occurs when the body overproduces keratin (a structural protein), which forms hard, scaly plugs that block the openings of hair follicles. This creates tiny, elevated, rough bumps typically found on the back of the upper arms, thighs, and buttocks.

In a board exam context, follicular hyperkeratosis is highly pathognomonic for Vitamin A deficiency or a chronic lack of essential fatty acids (like Omega-3).

• Pellagrous dermatitis - symmetric, dark, scaling rash on sun-exposed skin (the "casal''s necklace").
• Petechiae - tiny, non-blanching red or purple dots on the skin due to bleeding under the skin.
• Xerosis - generalized, abnormal dryness of the skin (or mucous membranes).', '["Pellagrous dermatitis","Follicular hyperkeratosis","Petechiae","Xerosis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:37:33.886Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:37:33.886Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:37:34.073Z"'::jsonb),
('anki-card-1754298010483-165', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A condition characterized by vertical fissuring in the lips:', 'Cheilosis', 'Cheilosis is the vertical cracking/fissuring at the lips, sometimes extending to angular fissures at the mouth corners (angular stomatitis).

• Fluorosis - affects tooth enamel (mottling) from excess fluoride
• Glossitis - inflammation of the tongue
• Dermatitis - general skin inflammation', '["Fluorosis","Glossitis","Cheilosis","Dermatitis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:40:59.718Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:40:59.718Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:40:59.718Z"'::jsonb),
('anki-card-1754298054063-166', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Schilling test is used to assess the status of this vitamin?', 'Vit B12', 'The Schilling test is a classic diagnostic procedure specifically designed to assess the body''s ability to absorb vitamin B12, including distinguishing whether malabsorption is due to intrinsic factor deficiency (pernicious anemia) or another cause.', '["Vit B12","Vit B6","Vit B2","Vit B1"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:32:09.489Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:32:09.489Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:32:09.692Z"'::jsonb),
('anki-card-1754298111810-167', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A condition when folate and Vitamin B12 are deficient', 'Megaloblastic anemia', 'Megaloblastic anemia - RBCs are large and immature due to impaired DNA synthesis; large (macrocytic) RBCs; caused by folate or vitamin B12 deficiency.

• Microcytic anemia - RBCs are abnormally small.
• Pernicious anemia - megaloblastic anemia caused specifically by lack of intrinsic factor (for B12 absorption).
• Hypochromic anemia - RBCs are pale due to insufficient hemoglobin.', '["Megaloblastic anemia","Microcytic anemia","Pernicious anemia","Hypochromic anemia"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:22:51.607Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:22:51.607Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:22:51.796Z"'::jsonb),
('anki-card-1754298156308-168', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Which among these food items is a good source of preformed Vitamin A?', 'Egg yolk', 'Egg yolk contains preformed vitamin A (retinol) directly, as animal-source foods provide vitamin A in its ready-to-use, preformed (retinol) state. 

Grains, peanuts, and corn oil are all plant-based foods that, if they contain any vitamin A activity at all, would provide it as provitamin A carotenoids (like beta-carotene) rather than preformed vitamin A, which the body must convert before use.', '["Egg yolk","Grains","Peanuts","Corn oil"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:33:32.238Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:33:32.238Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:33:32.435Z"'::jsonb),
('anki-card-1754298209918-169', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Laxatives can affect nutrient absorption through ___', 'altering motility', 'Laxatives work primarily by speeding up gastrointestinal transit time, which reduces the contact time between food/nutrients and the absorptive intestinal surface, thereby impairing nutrient absorption.', '["binding to nutrients","altering motility","irritating the GIT","interfering with taste"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:33:43.539Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:33:43.539Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:33:43.731Z"'::jsonb),
('anki-card-1754298261902-170', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'The method used to analyze protein content of foods in the FCT:', 'Kjeldahl', 'Kjeldahl method is the standard, classic laboratory technique for determining protein content by measuring total nitrogen and applying a conversion factor, widely used in food composition analysis.

• Soxhlet - fat/lipid extraction and analysis
• Roes-Gottlieb - specific method for fat analysis in dairy products
• Carr-Price - colorimetric method historically used for vitamin A analysis', '["Soxhlet","Rose-Gottlieb","Kjeldahl","Carr-Price"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:29:21.309Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:29:21.309Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:29:21.633Z"'::jsonb),
('anki-card-1754298331816-171', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Sonia has a fasting blood sugar level of 118 mg/dl. According to the assessment criteria of WHO, this value can be classified as  ____', 'impaired', 'According to the World Health Organization (WHO) and standard medical assessment guidelines, intermediate states of glucose regulation are formally categorized using the term "impaired".
• Impaired Fasting Glucose (IFG): Defined as a fasting blood sugar level between 100 mg/dL and 125 mg/dL (or 6.1 mmol/L to 6.9 mmol/L based on specific WHO thresholds). Since Sonia''s value is 118 mg/dl, it falls precisely within this category.
• Impaired Glucose Tolerance (IGT): Refers to blood sugar levels that are elevated during a 2-hour postprandial or oral glucose tolerance test (140–199 mg/dL).
In a clinical or exam context, these clinical categories represent "prediabetes," flagging that the individual''s glucose metabolism is altered but has not yet met the diagnostic cutoff for a diabetes mellitus classification (≥126 mg/dL).

Normal Levels
	• Fasting Blood Sugar: Less than 100 mg/dL (< 5.6 mmol/L)
	• 2-Hour Oral Glucose Tolerance Test: Less than 140 mg/dL (< 7.8 mmol/L)
	• HbA1c: Less than 5.7% (< 39 mmol/mol)

 Impaired Levels (Prediabetes)
	• Fasting Blood Sugar: 100 to 125 mg/dL (5.6 to 6.9 mmol/L) — called Impaired Fasting Glucose (IFG)
	• 2-Hour Oral Glucose Tolerance Test: 140 to 199 mg/dL (7.8 to 11.0 mmol/L) — called Impaired Glucose Tolerance (IGT)
	• HbA1c: 5.7% to 6.4% (39 to 46 mmol/mol)

 Diabetes Mellitus
	• Fasting Blood Sugar: 126 mg/dL or higher (≥ 7.0 mmol/L)
	• 2-Hour Oral Glucose Tolerance Test: 200 mg/dL or higher (≥ 11.1 mmol/L)
	• HbA1c: 6.5% or higher (≥ 48 mmol/mol)
	• Random Blood Sugar: 200 mg/dL or higher when accompanied by severe symptoms like extreme thirst or frequent urination', '["desirable","impaired","borderline","high"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:02:27.780Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:02:27.780Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:02:27.780Z"'::jsonb),
('anki-card-1754298433363-172', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Diagnostic test to determine the sufficiency of post nutriture to permit cells, tissues, organ systems or the host to optimally perform nutrient dependent biologic function.', 'Functional test', 'Functional test is the measure of actual physiological/biological functions.

• Biochemical test - laboratory test
• Clinical test - physical test
• Static test - single-point-in-time biochemical measurement', '["Functional test","Biochemical test","Clinical test","Static test"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:33:21.085Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:33:21.085Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:33:21.282Z"'::jsonb),
('anki-card-1754298484727-173', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'An essential trace element for both humans and animals.', 'Molybdenum', 'Molybdenum is a recognized essential trace element required by both humans and animals for enzymatic cofactor functions (such as in xanthine oxidase). 

Bromine, lithium, and vanadium are elements that have been studied for potential biological roles but are not established as essential trace elements with confirmed dietary requirement status in the same way molybdenum is officially recognized.', '["Bromine","Lithium","Vanadium","Molybdenum"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T07:41:32.820Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T07:41:32.820Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T07:41:32.820Z"'::jsonb),
('anki-card-1754298537274-174', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'It is a condition when Vit B3 is deficient', 'Pellagra', 'Pellagra is a niacin deficiency, classically presenting with the "three Ds": dermatitis, diarrhea, and dementia (and if untreated, a fourth D - death).

• Ariboflavinosis – riboflavin deficiency
• Beri-beri – thiamin deficiency
• Tiqui-tiqui - extract to cure beri-beri', '["Pellagra","Ariboflavinosis","Beri-beri","Tiqui-Tiqui"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:43:51.596Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:43:51.596Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:43:51.596Z"'::jsonb),
('anki-card-1754298586803-175', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the following is a functional test used to assess Vitamin A?', 'Dark adaptation test', 'In nutritional assessment, diagnostic tools are broadly split into biochemical (static) tests and functional tests:

A functional test measures the actual biological or physiological consequence of a nutrient deficiency on body function. Vitamin A is vital for the formation of rhodopsin (visual purple) in the rod cells of the retina, which allows eyes to see in dim light. The dark adaptation test evaluates the functional impairment of night vision caused by early-stage Vitamin A deficiency.

	• Test for serum albumin: A biochemical test primarily used as a general indicator of visceral protein status or systemic inflammation rather than a vitamin check.
	• Immunological test: Assesses immune system components (like T-cell counts or antibody levels). While Vitamin A impacts immunity, it is not a direct diagnostic test for it.
	• Test for urinary creatinine: Used alongside height measurements to calculate the creatinine-height index (CHI), which estimates skeletal muscle mass or evaluates kidney function.', '["Immunological test","Test for serum albumin","Dark adaptation test","Test for urinary creatinine"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:33:42.398Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:33:42.398Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:33:42.598Z"'::jsonb),
('anki-card-1754298630654-176', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Which of the followng is NOT a substrate used to assess zinc status?', 'Nails', 'Nails are not a standard, validated substrate used in clinical or population-level zinc status assessment. 

Hair, saliva, and blood/plasma are all recognized substrates that have been used, with varying degrees of reliability, to assess zinc status in research and clinical settings.', '["Hair","Saliva","Blood","Nails"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T08:19:52.013Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T08:19:52.013Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T08:19:52.013Z"'::jsonb),
('anki-card-1754298675651-177', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Breastmilk can be used for biochemical assessment of ?', 'Vit A', 'In public health and community nutrition assessments, breast milk retinol concentration is a well-established, non-invasive biomarker used to evaluate the Vitamin A status of both lactating mothers and their breastfed infants.

• Breast milk retinol levels are highly sensitive to maternal Vitamin A intake and liver reserves.
• The World Health Organization (WHO) recognizes breast milk testing as a valuable epidemiological tool. A high prevalence of low breast milk retinol concentrations (e.g., < 1.05 µmol/L or < 30 µg/dL) in a community indicates a subclinical Vitamin A deficiency problem requiring public health interventions like maternal postpartum supplementation or food fortification.

• Vitamin K & Vitamin D: Human breast milk is inherently and universally low in both Vitamin K and Vitamin D, regardless of maternal nutritional status. Because their baseline levels in milk are naturally close to zero, breast milk is not used as a reliable biochemical index to assess systemic status for these vitamins.
• Vitamin E: While present in breast milk (especially colostrum), serum alpha-tocopherol blood tests remain the primary clinical diagnostic tool for Vitamin E, rather than breast milk analysis.', '["Vit K","Vit E","Vit D","Vit A"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:33:26.418Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:33:26.418Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:33:26.606Z"'::jsonb),
('anki-card-1754298754614-178', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'What is the biochemical criterion included in the WHO classification scheme for xerophthalmia?', 'Plasma Vitamin A level', 'Plasma vitamin A level is the standard biochemical marker used alongside clinical/ocular signs (like night blindness, Bitot''s spots, corneal xerosis) in the WHO classification of xerophthalmia severity.

• Skinfold thickness – measures body fat
• Sensitivity test for Vitamin A deficiency - vague, non-standard term rather than a recognized biochemical criterion
• Urinary Vitamin A concentration - not the standard biochemical measure used for vitamin A status, since vitamin A is fat-soluble and stored/circulated differently than water-soluble vitamins excreted in urine.', '["Skinfold thickness","Sensitivity test for Vitamin A deficiency","Plasma Vitamin A level","Urinary Vitamin A concentration"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T15:28:22.412Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-24T15:28:22.412Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T15:28:22.615Z"'::jsonb),
('anki-card-1754298810761-179', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Irma weighs 56 kg and stands 5 feet. What is her body mass index?', '24.11 kg/m²', 'Body Mass Index (BMI) is calculated using the formula:
BMI = Weight (kg) / [Height (m)]²

1. Convert height from feet to meters:
	• 5 feet = 60 inches
	• 60 inches × 0.0254 meters/inch = 1.524 meters

2. Square the height in meters:
	• 1.524 × 1.524 = 2.3226 m²

3. Divide weight by squared height:
	• 56 kg / 2.3226 m² = 24.11

According to both WHO and Asia-Pacific standards, a BMI of 24.11 places Irma in the "Normal" weight category.', '["24.11 kg/m²","36.75 kg/m²","23.33 kg/m²","36.14 kg/m²"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:14:10.120Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:14:10.120Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:14:10.450Z"'::jsonb),
('anki-card-1754298899840-180', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'The MUAC of Ivanah Kawali indicates 11.5 cm. What is her nutritional status?', 'Moderate acute malnutrition', 'The correct answer is Moderate Acute Malnutrition (MAM), since a MUAC value in the range of approximately 11.5-12.4 cm in children under five is classified by WHO as indicating moderate acute malnutrition. 

MUAC is a simple, field-friendly screening tool widely used in community and emergency nutrition programs to rapidly identify acute malnutrition in young children.

• Severe Acute Malnutrition (SAM): Diagnosed only when the measurement drops strictly below 11.5 cm (<115 mm), or if bilateral pitting edema is present.
• Normal Nutritional Status: Indicated by a MUAC of 12.5 cm or higher (≥125 mm).', '["Normal","Stunting","Moderate acute malnutrition","Severe Acute malnutrition"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:55:55.747Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:55:55.747Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:55:55.747Z"'::jsonb),
('anki-card-1754298949922-181', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'According to WHO, if the prevalence rate of anemia in a population is 20% it can be classified as?', 'Moderate', 'The World Health Organization (WHO) classifies the severity of anemia as a public health problem based on its prevalence rate within a given population:

• Normal (No problem): Prevalence of 4.9% or lower
• Mild Public Health Problem: Prevalence of 5.0% to 19.9%
• Moderate Public Health Problem: Prevalence of 20.0% to 39.9% — Since the population prevalence is exactly 20%, it marks the lower boundary of a moderate public health crisis, requiring immediate targeted community interventions (such as massive iron-folic acid supplementation or food fortification programs).
• Severe Public Health Problem: Prevalence of 40.0% or higher', '["High","Mild","Moderate","Low"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T13:18:18.780Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T13:18:18.780Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T13:18:18.962Z"'::jsonb),
('anki-card-1754298998121-182', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'A deficiency in ___ can be seen in the nails', 'Selenium', 'Selenium, whose deficiency can manifest with changes visible in the nails (among other signs), consistent with selenium''s role in numerous enzymatic and antioxidant functions. 

• Iodine deficiency instead manifests primarily as goiter and thyroid-related signs. 
• Thiamin deficiency manifests as beri-beri-related neurological/cardiovascular signs. 
• Copper deficiency, while it can affect hair (as in Menkes disease), is not primarily associated with nail changes in the same way selenium is.', '["Iodine","Selenium","Thiamin","Copper"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T08:53:39.418Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T08:53:39.418Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:53:39.603Z"'::jsonb),
('anki-card-1754299083349-183', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Ms. Santos is conducting a research which aims to measure the mean nutrient intake of school children. What dietary assessment method will you recommend?', '24-hour food recall', '24-hour food recall is well-suited and commonly used for estimating the mean (average) nutrient intake of a group or population, since individual day-to-day variation tends to average out across a sufficiently large sample even with a single recall per person. 

• Food frequency questionnaires are better suited for ranking individuals by relative intake or assessing habitual/long-term dietary patterns rather than precise mean nutrient quantities. 
• Diet records and food weighing are more resource-intensive, detailed methods typically reserved for smaller studies or when precise individual intake data is needed.', '["24-hour food recall","Food frequency","Diet record","Food weighing"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:40:58.317Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:40:58.317Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:40:58.510Z"'::jsonb),
('anki-card-1754299134064-184', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'This pertains to the number of deaths per 1000 livebirth of infants under 1 year of age in a calendar year in the same period', 'IMR', 'IMR (Infant Mortality Rate): The number of deaths of children under 1 year of age (0 to 365 days) per 1,000 live births in a given calendar year. It is a standard public health indicator reflecting the overall socio-economic and healthcare status of a population.

• MMR (Maternal Mortality Ratio/Rate): The number of maternal deaths from any cause related to or aggravated by pregnancy or its management during pregnancy and childbirth (or within 42 days of termination) per 100,000 live births.
• NMR (Neonatal Mortality Rate): The number of deaths during the first 28 days of life (neonatal period) per 1,000 live births.
• SMR (Standardized Mortality Ratio): The ratio of observed deaths in the study group to the expected deaths in the general population, or Senile Mortality Rate depending on the epidemiological context.', '["IMR","NMR","MMR","SMR"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T09:31:27.268Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T09:31:27.268Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T09:31:27.445Z"'::jsonb),
('anki-card-1754299193910-185', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Obesity prevalence among adults 20 to 59 years old according to the 2021 ENNS is:', '10.0%', 'According to the 2021 Expanded National Nutrition Survey (DOST-FNRI), based on the WHO Asia-Pacific BMI Classification,

• 18.3% adults were overweight (BMI: 23.0 to 24.9 kg/m²)
• 30.2% were obese class I (BMI: 25.0 to 29.9 kg/m²)
• 10.0% were obese class II (BMI: ≥30 kg/m²).', '["10.0%","11.7%","30.2%","35.5%"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T08:25:18.398Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-29T08:25:18.398Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-29T08:25:18.592Z"'::jsonb),
('anki-card-1754299241177-186', NULL, 'anki-deck-1783608953857-1790433145942-e1oub', 'Menke''s Kinky hair syndrome is a deficiency in ____?', 'Copper', 'Menke''s kinky hair syndrome is the genetic disorder of copper metabolism/transport that results in severe copper deficiency, presenting classically with sparse, kinky, brittle hair along with neurodegenerative symptoms in affected infants.', '["Chromium","Copper","Calcium","Cobalt"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-25T10:53:12.020Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-24T10:53:12.020Z"'::jsonb, '"2026-09-26T14:32:30.310Z"'::jsonb, '"2026-10-24T10:53:12.020Z"'::jsonb)
