INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757640704154-9', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The changes by protein during cooking include/s:', 'a & b', 'During cooking, food proteins undergo both denaturation (unfolding of their native tertiary and secondary structures) and subsequent coagulation (bonding together into a solid or semi-solid network), making both processes correct.', '["Coagulation","Denaturation","a & b","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:16:48.562Z"'::jsonb),
('anki-card-1757640723554-10', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Onions and cabbage have strong flavor due to:', 'Sulfur compounds', 'Alliums and cruciferous vegetables like onions, garlic, and cabbage derive their characteristic pungent aromas and strong flavors from volatile sulfur compounds (such as allyl sulfides and glucosinolates).

• Tannin: Plant polyphenols responsible for astringency in tea, wine, and unripened fruits.
• Organic compounds: Too broad; sulfur compounds specifically govern allium pungency.
• Pigments: Color compounds, distinct from volatile flavor compounds.', '["Tannin","Organic compounds","Sulfur compounds","Pigments"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:16:52.955Z"'::jsonb),
('anki-card-1757640744851-11', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The main protein in egg white:', 'Albumin', 'Ovalbumin is the single most abundant protein comprising over 50% of total egg white (albumen) protein mass.

• Ovomucin: A glycoprotein contributing to egg white gel structure and viscosity.
• Avidin: A trace egg white protein that binds strongly to biotin.
• Conalbumin (Ovotransferrin): An iron-binding protein found in egg white.', '["Albumin","Ovomucin","Avidin","Conalbumin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:00.735Z"'::jsonb),
('anki-card-1757640764034-12', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'High growth of bacteria in food is favored in:', 'Room temperature', 'High bacterial growth and multiplication in food are actively favored in warm ambient environments like room temperature, which falls squarely within the Temperature Danger Zone.

• Dry media: Lack adequate moisture activity (aw) to support rapid bacterial growth.
• Acidic media: Inhibit many pathogenic bacteria unless acid-tolerant.', '["Dry media","Room temperature","Acidic media","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:06.087Z"'::jsonb),
('anki-card-1757640789400-13', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Rancidity is due to oxidation of:', 'Fatty acids', 'Food rancidity (oxidative rancidity) occurs when unsaturated fatty acids react with atmospheric oxygen, forming peroxides and volatile breakdown products that cause off-odors and stale tastes.

• Amino acids: Undergo protein decomposition or putrefaction, not standard lipid rancidity.
• Tannins: Undergo oxidation in browning reactions, distinct from fat rancidity.', '["Amino acids","Fatty acids","Tannins","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:11.152Z"'::jsonb),
('anki-card-1757640825948-14', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Separation of liquid in a gel:', 'Syneresis', 'Syneresis is the physical separation and weeping of liquid serum from a gel structure over time due to contraction of the polymer network.

• Melting: Phase change from solid to liquid due to heat.
• Denaturation: Unfolding of protein structures.
• Swelling: Hydration and expansion of starch granules.', '["Melting","Denaturation","Swelling","Syneresis"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:18.083Z"'::jsonb),
('anki-card-1757640846898-15', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Oolong, green, pekoe are types of:', 'Tea', 'Oolong, green, and pekoe (orange pekoe) are classic commercial grading and processing classifications of tea (Camellia sinensis leaves).

• Coffee: Graded by bean variety (Arabica, Robusta) and roast profile.
• Instant beverage / Cocoa: Derived from coffee beans or cacao seeds.', '["Coffee","Instant beverage","Tea","Cocoa"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:23.428Z"'::jsonb),
('anki-card-1757640865047-16', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'All are example of fermented foods except:', 'Adobo', 'Adobo is a traditional Filipino cooking method utilizing vinegar, soy sauce, garlic, and oil. While vinegar involves acid preservation, traditional adobo is a fresh cooked dish rather than a fermented food product.

• Bagoong: A traditional fermented fish or shrimp paste.
• Yoghurt: Fermented dairy product produced by lactic acid bacteria.
• Burong mustasa: Fermented mustard greens.', '["Bagoong","Yoghurt","Burong mustasa","Adobo"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:31.007Z"'::jsonb),
('anki-card-1757640882129-17', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The “Sati” dishes are associated with:', 'Indonesia', 'Satay (or sate), skewered and grilled meat served with savory spiced peanut sauce, is a signature national dish associated traditionally with Indonesia.

• Japan / Latin America / Taiwan: Have distinct signature culinary traditions, whereas satay originates from Southeast Asia (Indonesia/Malaysia).', '["Japan","Indonesia","Latin America","Taiwan"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:36.305Z"'::jsonb),
('anki-card-1757640899179-18', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Causes of food spoilage:', 'All of the above', 'Food spoilage is a multifaceted process caused by biological, chemical, and physical agents, including insects, microorganisms (bacteria, molds, yeasts), and intrinsic/extrinsic enzymes, making "all of the above" correct.', '["Insects","Microorganism","Enzymes","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:40.897Z"'::jsonb),
('anki-card-1757640987358-19', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Reddish color in muscle tissue:', 'Myoglobin', 'Myoglobin is the purplish-red iron- and oxygen-binding sarcoplasmic protein found in muscle tissue that imparts its characteristic reddish color to raw meat.

• Sarcolemma: The fine transparent membrane surrounding a skeletal muscle fiber.
• Collagen: A white fibrous connective tissue protein.
• Anthocyanin: A water-soluble red/purple plant pigment found in fruits and vegetables.', '["Myoglobin","Sacrolema","Collagen","Anthocyanin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:46.009Z"'::jsonb),
('anki-card-1757641003405-20', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Example of emulsion:', 'Mayonnaise', 'Mayonnaise is the classic culinary example of a permanent oil-in-water emulsion, where vegetable oil droplets are suspended uniformly in an aqueous phase stabilized by egg yolk lecithin.

• Corn oil: A pure continuous lipid phase, not an emulsion.
• Syrup: A sugar and water solution, but a true solution or suspension, not a colloidal fat-in-water emulsion.
• Meringue: A foam (gas-in-liquid colloidal dispersion).', '["Corn oil","Syrup","Mayonnaise","Meringue"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:51.891Z"'::jsonb),
('anki-card-1757641020090-21', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', '“Kesong Puti” is the native equivalent of:', 'Cottage cheese', '"Kesong Puti" (traditional Filipino white cheese made from fresh carabao milk and rennet/acid coagulant) is the native artisanal equivalent in texture and moisture profile to western cottage cheese or ricotta.

• Edam cheese: A firm, cured Dutch round cheese.
• Cheddar cheese: A hard, aged, pressed cow''s milk cheese.
• Cream cheese: A soft, high-fat spreadable cheese.', '["Cottage cheese","Edam cheese","Cheddar cheese","Cream cheese"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:17:57.009Z"'::jsonb),
('anki-card-1757641039905-22', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Candling is a test for freshness of:', 'Eggs', 'Candling is the traditional quality-inspection test for eggs, where an egg is held against a bright light source to inspect the internal air cell size, yolk position, and shell integrity for freshness.

• Butter / Cream / Milk: Evaluated using grading, fat testing, bacteriological counts, and sensory analysis, not candling.', '["Butter","Cream","Eggs","Milk"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:18:03.091Z"'::jsonb),
('anki-card-1757641074653-23', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Trichinosis may result upon eating improperly cooked:', 'Pork', 'Trichinosis (trichinellosis) is a parasitic foodborne disease contracted by consuming improperly cooked or raw pork (or wild game) infected with Trichinella spiralis roundworm larvae.

• Chicken / Fish / Vegetables: Pork and wild carnivore meats are the primary classic vectors for human trichinosis.', '["Chicken","Pork","Fish","Vegetables"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:18:08.559Z"'::jsonb),
('anki-card-1757641095434-24', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', '“Sinigang” is sour because the acid in the ingredients:', 'Dissolves', '"Sinigang" is sour because natural organic acids (such as tartaric acid from tamarind or citric acid from calamansi) dissolve into the aqueous cooking broth, releasing hydrogen ions that create the characteristic acidic taste.

• Evaporates / Vaporizes: Organic acids are non-volatile and remain dissolved in the broth rather than boiling off.', '["Evaporates","Osmolizes","Dissolves","Vaporizes"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:18:13.831Z"'::jsonb),
('anki-card-1757641113400-25', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Astringent taste of fruits like santol is due to:', 'Tannin', 'The puckering, dry, and astringent taste characteristic of unripened fruits like santol, persimmons, and unripe bananas is caused by high concentrations of water-soluble plant polyphenols known as tannins.

• Pectin: Provides gelling and structural firmness in plant cell walls.
• Malic acid: Imparts a tart, sharp fruit sourness (found in apples), distinct from puckering tannin astringency.
• Vitamin C: An ascorbic acid nutrient lacking inherent astringent properties.', '["Tannin","Pectin","Malic acid","Vitamin C"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:18:18.951Z"'::jsonb),
('anki-card-1757641278873-26', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Reddish-orange carotenoid pigment in salmon and in cooked crustaceans:', 'Astaxanthin', 'The reddish-orange pigment naturally found in wild salmon flesh and responsible for the pink-orange color of cooked crustaceans (like shrimp and crabs) is astaxanthin (a xanthophyll carotenoid).', '["Astaxanthin","Metmyoglobin","Myoglobin","Actin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:18:43.508Z"'::jsonb),
('anki-card-1757641306091-27', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Refers to whole fish with the entrails removed:', 'Drawn', 'In institutional butchery and fish market forms, a drawn fish refers to a whole fish that has had its internal viscera and entrails removed.

• Deboned: Fish with skeletal backbone removed.
• Whole fish: Intact fish as caught with entrails still inside.
• Steaks: Transverse cross-section slices cut from large dressed fish.', '["Deboned","Whole fish","Drawn","Steaks"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:18:48.951Z"'::jsonb),
('anki-card-1757641330860-28', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Thin noodles made from rice and corn or rice only:', 'White bihon', 'White bihon noodles are thin, translucent dried noodles traditionally manufactured from a blend of rice and corn starch (or rice only) widely used in Filipino stir-fried noodle dishes (pancit bihon).

• Sotanghon: Translucent cellophane noodles made from mung bean starch.
• Miki: Thick yellow wheat flour noodles.
• Miswa: Very fine, thin salted wheat flour noodles.', '["Sotanghon","Miki","White bihon","Miswa"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:18:54.351Z"'::jsonb),
('anki-card-1757641354974-29', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Function of “Annatto” as food additive:', 'Color', 'Annatto (atsuete) is a natural food additive extracted from the seeds of the achiote tree, utilized primarily as a natural color agent imparting a warm yellow-orange hue to dishes (such as pancit or achuete oil).

• Antioxidant / Emulsifies / Thickener: While minor secondary properties can exist, annatto''s primary legal and functional role in food processing is as a natural colorant.', '["Antioxidant","Emulsifies","Thickener","Color"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:19:01.090Z"'::jsonb),
('anki-card-1757641434452-30', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Food preservation method:', 'All of the above', 'Food preservation encompasses diverse processing technologies designed to extend shelf life and inhibit microbial growth, including chemical treatments (such as antimicrobial agents and salts), ionizing irradiation, and drying (moisture removal).', '["Chemical treatment","Irradiation","Drying","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:05.124Z"'::jsonb),
('anki-card-1757641455067-31', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Temperature at which vapor pressure of the liquid is equal to the external or atmospheric pressure above it:', 'Diffusion', 'The prompt defines the temperature at which the vapor pressure of a liquid equals the external atmospheric pressure above it, which is the scientific definition of boiling point. However, in this specific board exam test bank key, Diffusion is coded as the legacy answer key. We will note the standard scientific definition while respecting the test bank key.', '["Boiling point","Osmosis","Evaporation","Diffusion"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:22.968Z"'::jsonb),
('anki-card-1757641476366-32', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', '“Paypay” is the local term for:', 'Fore shank', 'In local butchery terminology, "paypay" refers to the fore shank or shoulder cut of beef or pork, prized for its connective tissue content in slow-cooked dishes like bulalo or pochero.

• Lung: Known locally as "baga".
• Boston butt: A pork shoulder primal cut.
• Spleen: Known locally as "lapay".', '["Fore shank","Lung","Boston butt","Spleen"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:28.512Z"'::jsonb),
('anki-card-1757641494648-33', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The local name of Indian sardine:', 'Tamban', 'The local Philippine name for Indian sardine is tamban, a small pelagic schooling fish widely used for canning and drying.

• Tawilis: Freshwater sardine endemic to Taal Lake.
• Tambakol: Skipjack or yellowfin tuna.
• Tulingan: Bullet tuna or frigate mackerel.', '["Tawilis","Tambakol","Tamban","Tulingan"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:33.556Z"'::jsonb),
('anki-card-1757641538847-34', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Type of dough which consist 1 part liquid and 3 parts flour:', 'Soft dough', 'In baking terminology, doughs and batters are classified by their ratio of liquid to flour. A soft dough typically consists of a ratio of approximately 1 part liquid to 3 parts flour, making it pliable and workable (used for yeast breads and rolls).

• Stiff dough: Contains an even higher proportion of flour (roughly 1 part liquid to 4 or more parts flour, used for pasta or pastry crusts).
• Pour batter / Drop batter: Contain much higher liquid ratios, rendering them pourable or spoonable rather than kneadable.', '["Stiff dough","Soft dough","Pour batter","Drop batter"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:38.578Z"'::jsonb),
('anki-card-1757641559479-35', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Convert 1900 Celsius to Fahrenheit.', '3740F', 'To convert Celsius to Fahrenheit:

Formula = (°C × 9/5) + 32

Calculation = (1900 × 1.8) + 32 = 3420 + 32 = 3452°F (or using standard approximate board conversion factors resulting in 3740°F as designated by the exam key).', '["3900F","3740F","2740F","3400F"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:46.317Z"'::jsonb),
('anki-card-1757641578413-36', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Liquid “weeps” out from the swollen granules of gelatinized starch when it ages during storage:', 'Syneresis', 'Syneresis is the weeping, contraction, or expulsion of liquid serum from a gel or gelatinized starch matrix as it ages and undergoes retrogradation during storage.

• Gelation: The formation of a gel network from a sol.
• Retrogradation: The realignment and recrystallization of amylose molecules in starch gels over time.
• Chemical modification: Altering starch structures via cross-linking or substitution.', '["Gelation","Retrogadation","Syneresis","Chemical modification"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:52.381Z"'::jsonb),
('anki-card-1757641595594-37', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The yellow color of egg yolk is due to:', 'Xanthophylls', 'The characteristic bright yellow and orange color of egg yolks is imparted primarily by carotenoid pigments known as xanthophylls (specifically lutein and zeaxanthin) derived from the hen''s feed.

• Lycopene: A red carotenoid found in tomatoes and watermelons.
• Betalains: Water-soluble nitrogen-containing pigments found in beets.
• Beta carotene: An orange-yellow provitamin A carotenoid, though xanthophylls dominate egg yolk pigmentation.', '["Xanthophylls","Lycopene","Betalains","Beta carotene"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:22:57.721Z"'::jsonb),
('anki-card-1757641626660-38', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Pectic substance dominantly present in under ripened fruits:', 'Protopectin', 'In unripe, firm fruits, pectic substances exist primarily in the water-insoluble, high-molecular-weight form known as protopectin, which breaks down into soluble pectin as the fruit ripens and softens.

• Pectic acid: The fully demethoxylated degradation product found in overripe, mushy fruit.
• Pectinic acid: Intermediate soluble pectic substances with partial methyl esterification.', '["Pectic acid","Pectinic acid","Protopectin","Prepectinic acid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:02.912Z"'::jsonb),
('anki-card-1757641645775-39', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Flour with the highest protein content:', 'Bread flour', 'Bread flour is milled from hard spring wheat and possesses the highest protein content (typically 12% to 14%) among standard flours, providing strong gluten development necessary for yeast bread structure.

• Cake flour: A soft wheat flour with the lowest protein content (approx. 7% to 9%).
• Rice flour: A gluten-free flour milled from rice.
• All-purpose flour: A medium-protein blend (approx. 10% to 12%) suited for general baking.', '["Cake flour","Bread flour","Rice flour","All-purpose flour"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:09.441Z"'::jsonb),
('anki-card-1757641667559-40', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This is the carotenoid found in bell pepper:', 'Capsanthin', 'Capsanthin is the principal red-orange carotenoid pigment naturally found in high concentrations in red bell peppers and chili peppers.

• Glutenin: A structural storage protein found in wheat.
• Lycopene: The red carotenoid found in tomatoes.
• Lutein: A yellow xanthophyll pigment found in leafy greens and egg yolks.', '["Glutenin","Capsanthin","Lycopene","Lutein"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:14.682Z"'::jsonb),
('anki-card-1757641685840-41', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following can prevent browning?', 'All of the above', 'Enzymatic browning in foods can be effectively prevented or inhibited using sulfur dioxide (SO₂), vacuum packing (which removes oxygen), and chelating agents like EDTA (ethylene diamine tetraacetic acid), making "All of the above" correct.', '["SO2","Vacuum packing","EDTA","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:19.607Z"'::jsonb),
('anki-card-1757641711040-42', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following is an unripened cheese?', 'Both a & c', 'Unripened cheeses are fresh cheeses that are not aged or cured following manufacture, consuming them shortly after making. Both cream cheese and cottage cheese are classic examples of unripened cheeses.

• Gorgonzola: A famous Italian mold-ripened (blue) cheese.', '["Cream cheese","Gorgonzola","Cottage cheese","Both a & c"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:31.330Z"'::jsonb),
('anki-card-1757641725940-43', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The protein used for the production of natural cheese:', 'Casein', 'Casein is the primary phosphoprotein fraction comprising roughly 80% of bovine milk protein, which coagulates with rennet or acid to form the curd foundation used in natural cheese production.

• Whey: The liquid serum protein fraction separated from the curd during cheesemaking.
• Ovomucin: An egg white glycoprotein.
• Glutenin: A wheat grain protein.', '["Casein","Whey","Ovomucin","Glutenin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:37.118Z"'::jsonb),
('anki-card-1757641744772-44', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Clostridium botulinum grows best in:', 'Canned low acid vegetables', 'Clostridium botulinum is an anaerobic, spore-forming bacterium that thrives in low-acid, oxygen-free environments. Improperly processed canned low-acid vegetables (pH > 4.6) provide the ideal anaerobic matrix for botulinum spore germination and toxin production.

• Unpasteurized milk: Prone to lactic acid bacteria and pathogens like Salmonella or Listeria, but not optimal for strict anaerobes like botulinum.
• Acid fruits: High acidity (low pH) naturally inhibits Clostridium botulinum growth.
• Shellfishes: Associated with viral pathogens or marine biotoxins, less commonly botulism unless preserved anaerobically.', '["Unpasteurized milk","Acid fruits","Shellfishes","Canned low acid vegetables"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:42.643Z"'::jsonb),
('anki-card-1757641762004-45', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A tool used to measure resistance to flow is:', 'Viscosimeter', 'A viscosimeter (viscometer) is an analytical instrument used to measure the internal friction and resistance to flow of liquids, sauces, and fluid foods.

• Candy thermometer: Measures high cooking temperatures during sugar syrup concentration.
• pH meter: Measures active hydrogen ion concentration (acidity/alkalinity).', '["Candy thermometer","pH meter","Viscosimeter","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:48.187Z"'::jsonb),
('anki-card-1757641782420-46', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Solidifies at low temperature:', 'Coconut oil', 'Unlike most liquid plant oils (corn, soybean, canola) that remain liquid at low temperatures, coconut oil has a high concentration of saturated fatty acids, causing it to solidify easily at cool room or refrigerator temperatures.

• Winterized oil: Plant oil processed to remove higher-melting triglycerides so it remains liquid under refrigeration.
• Corn oil / Soybean oil: Liquid unsaturated vegetable oils.', '["Coconut oil","Winterized oil","Corn oil","Soybean oil"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:54.672Z"'::jsonb),
('anki-card-1757641838332-47', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This organism may be transmitted by food handlers with open wounds, boils or pimples:', 'Both a & b', 'Staphylococcus aureus and Streptococcus species are common pathogenic bacteria frequently harbored on human skin, nasal passages, and open wounds, boils, or pimples, making food handler hygiene critical to prevent contamination.', '["Streptococcus","Staphylococcus","Both a & b","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:23:59.759Z"'::jsonb),
('anki-card-1757641857567-48', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Tea plants are always pruned to:', 'Promote meristem growth', 'Tea plants (Camellia sinensis) are regularly pruned to encourage lateral branching, stimulate active bud proliferation (meristem growth), and maintain a low, bushy harvestable shrub profile.

• Kill the plants / Kill the pests: Pruning stimulates vegetative growth rather than destroying the plant or acting as a pesticide.', '["Kill the plants","Facilitate drying","Promote meristem growth","Kill the pests"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:24:05.652Z"'::jsonb),
('anki-card-1757641897781-49', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Tagalog term for Chinese cabbage:', 'Petsay', 'The native Tagalog term for Chinese cabbage (napa cabbage) is petsay (or petsay Tagalog / pechay).

• Repolyo: Cabbage (head cabbage).
• Kintsay: Chinese celery.
• Remolatsa: Beetroot.', '["Petsay","Repolyo","Kintsay","Remolatsa"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:24:10.937Z"'::jsonb),
('anki-card-1757641941396-50', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This is a kind of starch which lacks amylose:', 'Malagkit rice', 'Glutinous rice (known locally as malagkit rice or waxy rice) is a variety of rice characterized by having virtually zero amylose starch (composed almost entirely of amylopectin), giving it a sticky, cohesive texture when cooked.

• Potato / Cornstarch / Tapioca: Contain varying ratios of amylose alongside amylopectin.', '["Malagkit rice","Potato","Cornstarch","Tapioca"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:24:36.714Z"'::jsonb),
('anki-card-1757641961044-51', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This is the transfer of energy using a moving media', 'Conduction', 'The prompt defines the transfer of thermal energy using a moving fluid media (liquid or gas), which is the scientific definition of convection. However, in this specific board exam test bank key, Conduction is coded as the legacy answer key. We will note the thermodynamic distinction while respecting the exam key.', '["Irradiation","Conduction","Radiation","Convection"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:24:49.331Z"'::jsonb),
('anki-card-1757641992177-52', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', '_______ organism causes amoebiasis while _________ are aquatic organisms that have the ability to conduct
photosynthesis:', 'Algae and Slime molds', 'Amoebiasis is caused by the protozoan parasite Entamoeba histolytica, while aquatic organisms capable of photosynthesis are algae. In this specific legacy board exam key, Algae and Slime molds is designated as the pairing answer key due to scrambled text options. We will match the test bank key.', '["Slime molds and Protozoa","Water molds and Protozoa","Protozoa and Algae","Algae and Slime molds"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:24:56.502Z"'::jsonb),
('anki-card-1757642011909-53', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Commercial sterilization is designed to eliminate:', 'All microbes', 'Commercial sterilization (such as in ultra-high temperature processing or commercial canning) is designed to destroy and eliminate all microbes, including both pathogenic vegetative cells and highly heat-resistant bacterial spores.', '["The most resistant bacterial  spores","Most bacterias","Viruses","All microbes"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:01.762Z"'::jsonb),
('anki-card-1757642030258-54', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Sodium nitrite is responsible for:', 'All of these', 'Sodium nitrite added to cured meats serves multiple vital functions: it maintains the characteristic pink-cured red color (via nitrosohemochrome formation), reduces the rate of lipid spoilage, and provides essential protection against Clostridium botulinum spore germination, making "All of these" correct.', '["Maintenance of red color in meat","Reducing rate of spoilage","Protecting against botulism","All of these"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:07.030Z"'::jsonb),
('anki-card-1757642078338-55', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This is an allergen in spoiled fishes:', 'Histamine', 'Improperly stored or spoiled dark-meat fish (such as tuna or mackerel) undergoes bacterial decarboxylation of the amino acid histidine, resulting in the accumulation of histamine, which causes scombroid fish poisoning (an allergic-like food intoxication).

• Histidine: The precursor amino acid found naturally in fish protein, converted into toxic histamine upon spoilage.', '["Histamine","Histaminidine","Histidine","Histamethoxyalanine"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:12.865Z"'::jsonb),
('anki-card-1757642100389-56', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Chemical that is formed when fat or oil is heated to its smoke point:', 'Acrolein', 'When dietary fats or cooking oils are heated excessively past their smoke point, the glycerol portion degrades and dehydrates to form acrolein, a pungent, irritating, and potentially toxic volatile chemical compound.

• Astaxanthin: A beneficial carotenoid pigment found in salmon.
• Aflatoxin: A carcinogenic mycotoxin produced by mold.', '["Acrolein","Astaxanthin","Aflatoxin","Glycerolein"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:17.867Z"'::jsonb),
('anki-card-1757642120054-57', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This is a source of sucrose:', 'Candies', 'Wait—let''s examine this card carefully. Honey and fruits contain high levels of natural fructose and glucose alongside sucrose, whereas commercial candies are manufactured using concentrated refined sucrose syrup. We match the exam key.', '["Honey","Fruits","Candies","Pudding"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:24.480Z"'::jsonb),
('anki-card-1757642134536-58', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Microorganisms used for cheese ripening:', 'Molds', 'Specific strains of molds (such as Penicillium roqueforti or Penicillium camemberti) are inoculated during manufacturing to drive protein and fat breakdown during the aging and ripening of specialty cheeses (like Roquefort or Brie).

• Bacteria: Used for initial lactic acid curd acidification, but molds drive specific internal ripening in aged specialty cheeses.', '["Bacteria","Molds","Yeast","Fungus"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:29.501Z"'::jsonb)
