INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757642151502-59', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The best way to extract color from annatto seeds:', 'Use hot oil', 'Annatto (atsuete) pigments (bixin and norbixin) are fat-soluble carotenoids. Therefore, the most efficient culinary way to extract their vibrant red-orange color is to use hot oil or fat, which dissolves the pigments rapidly.

• Use hot water / Use cold water: Annatto pigments are poorly soluble in water, making oil extraction superior.', '["Use hot oil","Use hot water","Use cold water","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:34.924Z"'::jsonb),
('anki-card-1757642174135-60', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Prolonged heating of milk results in:', 'All of the above', 'Prolonged thermal heating of milk causes multiple physical and chemical changes: surface evaporation and skin/scum formation, bottom scorching due to casein precipitation, and fat globule coalescence, making "All of the above" correct.', '["Scum formation","Scorching","Fat coaslescence","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:39.578Z"'::jsonb),
('anki-card-1757642206417-61', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'All soups are based on:', 'Stock', 'Virtually all classic clear, cream, and specialty soups are built upon a foundation of flavorful stock (extracted from bones, meat, mirepoix, and aromatics).

• Water: Serves as a solvent, but stock provides the fundamental flavor base.
• Bouillon: Dehydrated or prepared broth cubes, whereas scratch stock is the culinary base.', '["Stock","Water","Bouillon","Garni"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:44.861Z"'::jsonb),
('anki-card-1757642224765-62', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The transfer of heat via metal is known as:', 'Conduction', 'The direct transfer of thermal energy through molecular collision via solid metal cookware (such as a copper pan or iron skillet) is known as conduction.

• Convection: Heat transfer through circulating fluid or air currents.
• Induction: Electromagnetic energy transfer directly to magnetic cookware.
• Radiation: Heat transfer via infrared waves or electromagnetic energy.', '["Convection","Conduction","Induction","Radiation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:50.381Z"'::jsonb),
('anki-card-1757642241715-63', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Market form of fat produced by rendering fat from hog:', 'Lard', 'Lard is the commercial market form of solid cooking fat produced by rendering the fatty tissue of hogs (pigs).

• Suet: Solid beef or mutton kidney fat.
• Tallow: Rendered beef fat.', '["Suet","Lard","Tallow","Brown butter"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:25:55.993Z"'::jsonb),
('anki-card-1757642259131-64', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A local rice product which is sweetened and puffed:', 'Ampaw', 'Ampaw is a traditional Filipino sweet puffed rice snack made from popped or puffed cooked rice coated in a caramelized sugar syrup.

• Pinipig: Flattened immature green rice grains.
• Malagkit: Glutinous waxy rice.
• Biko: A sweet sticky rice rice-cake dish.', '["Ampaw","Pinipig","Malagkit","Biko"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:00.788Z"'::jsonb),
('anki-card-1757642509935-65', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'As eggs age, what happens to the size of the air sac?', 'It increases', 'As an egg ages during storage, moisture and carbon dioxide evaporate through the porous eggshell, causing the internal air cell (sac) to expand and increase in size.', '["It decreases","It stays the same","It disappears","It increases"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:06.617Z"'::jsonb),
('anki-card-1757642529747-66', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Salmonella bacteria may be commonly found in which type of food?', 'Poultry products', 'Salmonella bacteria are famously harbored in the intestinal tracts of poultry and are most commonly associated with raw or undercooked poultry products (chicken, turkey, and eggs).

• Beef products: Can be contaminated, but poultry and eggs are the classic primary vectors.', '["Beef products","Vegetable products","Poultry products","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:13.197Z"'::jsonb),
('anki-card-1757642548283-67', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Coagulation of milk in cheese making is brought about by adding:', 'Rennin', 'The enzymatic coagulation of milk proteins (casein) during natural cheesemaking is traditionally brought about by adding rennin (chymosin), an enzyme extracted from the fourth stomach of calves.', '["Rennin","Sugar","Both of the above","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:17.464Z"'::jsonb),
('anki-card-1757642571566-68', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Alimentary pastes made from hard wheat flour:', 'All of the above', 'Alimentary pastes (pasta) such as spaghetti, vermicelli, and macaroni are manufactured from semolina flour milled from durum wheat (hard wheat flour), making "All of the above" correct.', '["Spaghetti","Vermicelli","Macaroni","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:21.192Z"'::jsonb),
('anki-card-1757642589813-69', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The process of allowing the sugar to penetrate the fruit in glazed fruit candies:', 'Plumping', 'Plumping is the culinary and food processing technique of allowing sugar syrup to gradually penetrate fruit tissues over time without shrinking or toughening the fruit (used in candied and glazed fruit production).

• Jelling: The setting of pectin-sugar-acid mixtures.
• Stewing: Cooking food slowly in liquid.', '["Jelling","Stewing","Plumping","Soaking"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:26.095Z"'::jsonb),
('anki-card-1757642606330-70', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Batchoy is made from the following internal organ:', 'Heart, kidney, pancreas, liver', 'Traditional Filipino Batchoy (noodle soup) features rich broths seasoned with a variety of pork offal and organ meats, classically including the heart, kidney, pancreas, and liver.', '["Heart, uterus, stomach, brain","Liver, heart, pancreas, brain","Heart, kidney, pancreas, liver","Heart, uterus, tongue, liver"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:30.913Z"'::jsonb),
('anki-card-1757642625663-71', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Mace, cinnamon and oregano are examples of:', 'Spices', 'Mace, cinnamon, and oregano are aromatic plant parts (bark, aril, leaves) categorized botanically and culinarily as spices and herbs used for seasoning.', '["Emulsifiers","Preservatives","Spices","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:35.230Z"'::jsonb),
('anki-card-1757642643545-72', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The toughening of meat after slaughter is due to:', 'Rigor mortis', 'Following animal slaughter, the depletion of cellular ATP causes muscle fibers to lock into a rigid, contracted state known as rigor mortis, which temporarily toughens the meat before enzymatic aging (ripening) tenderizes it.', '["Lactic acid","Ripening","Putrefaction","Rigor mortis"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:39.998Z"'::jsonb),
('anki-card-1757642674044-73', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In frozen desserts, agar-agar acts as:', 'Stabilizer', 'In frozen desserts (like ice cream), gums and hydrocolloids such as agar-agar act as stabilizers to bind free water, prevent large ice crystal growth, and maintain smooth texture.', '["Leavener","Stabilizer","Preservative","Flavoring"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:44.384Z"'::jsonb),
('anki-card-1757642690794-74', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This is a useful equipment in making a puree', 'Blenderizer', 'A mechanical blender (or food processor / blenderizer) is the standard piece of equipment used in professional kitchens to purée cooked fruits, vegetables, and soups.', '["Water purifier","Potato ricer","Pressure cooker","Blenderizer"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:53.668Z"'::jsonb),
('anki-card-1757642708058-75', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'French dressing is a suspension of:', 'Liquid in liquid', 'French dressing (vinaigrette) is a temporary emulsion consisting of oil droplets suspended in an aqueous vinegar solution, representing a liquid-in-liquid colloidal dispersion.', '["Solid in liquid","Liquid in liquid","Gas in liquid","Liquid in solid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:26:58.221Z"'::jsonb),
('anki-card-1757642723942-76', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', '“Hardness” of water is due to:', 'Calcium salts', 'Water "hardness" is caused by the presence of dissolved multivalent metallic cations, predominantly calcium salts (along with magnesium carbonates and sulfates).', '["Calcium salts","Bacterial contamination","Low pH","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:27:02.495Z"'::jsonb),
('anki-card-1757642748624-77', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A potential carcinogen formed on charcoal-broiled meat is:', 'Benzopyrene', 'Benzopyrene (benzo[a]pyrene) is a polycyclic aromatic hydrocarbon (PAH) and potent potential carcinogen formed when fat from meats drips onto hot coals or charcoal during grilling or broiling, depositing smoke compounds onto the food surface.

• Nitrosamines: Formed via reactions involving nitrites and amines in cured meats.
• Aflatoxin: A fungal mycotoxin.', '["Benzopyrene","Nitrosamines","Aflatoxin","Solanine"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:27:07.565Z"'::jsonb),
('anki-card-1757642766623-78', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Butter and butter compounds are usually marketed in bars or packs of:', '½ pound', 'Butter and margarine blocks in standard commercial retail packaging are traditionally marketed and sold in 1/2 pound (250g) blocks or 1-pound quarters (four sticks).', '["1 pound","½ pound","1 kilo","½ kilo"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:27:12.433Z"'::jsonb),
('anki-card-1757642782938-79', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A term used to describe a cream soup made from shellfish:', 'Bisque', 'A bisque is a rich, creamy, velvety French-style thick soup traditionally prepared from a puréed shellfish stock (such as lobster, crab, or shrimp) thickened with rice or cream.

• Consommé: A crystal-clear clarified meat broth.
• Sol / Foam: Colloidal physics states, not soup classifications.', '["Foam","Sol","Bisque","Consommé"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:27:17.637Z"'::jsonb),
('anki-card-1757642811937-80', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'When rice is roasted or browned for kare-kare, the starch undergoes:', 'Gelatinization', 'When rice is dry-roasted or browned (such as when toasting ground rice or apas for kare-kare sauce), the dry heat combined with trace moisture causes the starch granules to swell, lose their crystalline structure, and undergo gelatinization (and partial dextrinization), imparting a rich nutty flavor and thickening capacity.

• Oxidative rancidity: Refers to the spoilage of fats and oils exposed to oxygen, not starch changes.
• Dextrinization: The partial breakdown of starch into shorter dextrin chains, though gelatinization is the specific primary granule hydration process tested here.
• Retrogradation: The recrystallization and firming of gelatinized starch upon cooling during storage.', '["Oxidative rancidity","Gelatinization","Dextrinization","Retrogradation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:31:31.474Z"'::jsonb),
('anki-card-1757642838487-81', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'To make a thinner porridge or oatmeal:', 'Add more water', 'To thin out a thick porridge or oatmeal to a desired consistency, the correct culinary technique is to add more water (or milk) during cooking.', '["Add more water","Increase the stirring","Add the cereal gradually to the boiling water","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:40:55.540Z"'::jsonb),
('anki-card-1757642861150-82', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Enzyme that mediates browning reaction in fruits and vegetables:', 'Phenolase', 'Phenolase (polyphenol oxidase) is the copper-containing enzyme responsible for catalyzing enzymatic browning reactions in cut fruits and vegetables when exposed to oxygen.', '["Pectinase","Phenolase","Oxidase","Melanase"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:00.164Z"'::jsonb),
('anki-card-1757642882217-83', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A measure of egg quality that relates egg weight with the height of its albumin:', 'Haugh unit', 'The Haugh unit is a standardized mathematical measure of egg quality that correlates egg white (albumen) height with the egg''s total weight, serving as the benchmark for USDA egg grading.', '["Haugh unit","Grade A","Candling score","Brix"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:05.431Z"'::jsonb),
('anki-card-1757642903134-84', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Thick soups or stews usually containing seafood, potatoes and milk or cream:', 'Chowder', 'Chowder is a hearty American-style thick soup or stew traditionally containing seafood (clams, fish), diced potatoes, onions, and milk or heavy cream.

• Bisques: Smooth, puréed shellfish cream soups.', '["Bisques","Stocks","Chowder","Potages"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:16.525Z"'::jsonb),
('anki-card-1757642922916-85', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'To brown surface of meat by short application of intense heat:', 'Sear', 'To sear means to brown the exterior surface of meat quickly by applying intense, high heat for a short duration, caramelizing surface proteins and locking in moisture.', '["Steep","Sear","Sterilize","Scald"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:20.541Z"'::jsonb),
('anki-card-1757642937966-86', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Green pigment in milk:', 'Lactoflavin', 'Lactoflavin (historically known as Vitamin B2 or riboflavin) is the water-soluble greenish-yellow fluorescent pigment naturally present in milk whey serum.', '["Lactalbumin","Lactic acid","Lactoflavin","Chlorophyll"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:25.697Z"'::jsonb),
('anki-card-1757642963813-87', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Martha and John are gluten-sensitive or gluten-intolerant which means that their bodies produce an abnormal
immune response when breaking down gluten during digestion. The two proteins found in gluten are:', 'Glutenin & gliadin', 'Dietary gluten is a complex structural protein composite composed of two primary prolamin and glutelin protein fractions: glutenin and gliadin, which trigger autoimmune enteropathy in celiac patients.', '["Glutenin & gliadin","Glycerine & glutenin","Gliadine & mellorine","Glycine & alanine"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:29.846Z"'::jsonb),
('anki-card-1757642980512-88', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following is an example of a subjective food evaluation test?', 'Taste panel', 'A taste (sensory) panel relies on human sensory organs (sight, smell, taste, touch) to evaluate food products, making it a subjective evaluation method.

• Measuring volume: An objective physical evaluation technique.
• Measuring weight: An objective analytical measurement.
• Spectrophotometry: An objective chemical and optical analysis technique.', '["Measuring volume","Measuring weight","Taste panel","Spectrophotometry"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:13:21.738Z"'::jsonb),
('anki-card-1757642995462-89', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', '“Suahe” and “puti” are specifications for:', 'Shrimps', 'In local Filipino markets and seafood trade specifications, terms like suahe (white shrimp / greasyback shrimp) and puti (white shrimp variants) are standard market specifications used to identify species and grades of fresh prawns and shrimps.

• Crabs / Fish / Clams: Invertebrate and finfish categories with entirely different local market size and species specifications.', '["Shrimps","Crabs","Fish","Clams"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:13:26.564Z"'::jsonb),
('anki-card-1757643011846-90', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Starch is used as thickening agent in:', 'Sauces & gravy', 'Starches (such as modified food starches, cornstarch, or flour) are utilized primarily in culinary preparations as thickening agents for sauces, gravies, soups, and pie fillings to impart viscosity and mouthfeel.

• Mayonnaise: An oil-in-water emulsion thickened primarily by egg yolk emulsifiers.
• Cake: Utilizes flour gluten structures and leavening agents for structural baking support.
• Bread: Relies on wheat flour gluten proteins and yeast fermentation.', '["Mayonnaise","Cake","Sauces & gravy","Bread"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:13:31.481Z"'::jsonb),
('anki-card-1757643030227-91', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Type of milk in which fat is removed:', 'Skimmed milk', 'Skimmed milk (non-fat milk) is fluid milk from which virtually all the butterfat has been mechanically removed.', '["Skimmed milk","Whole milk","Evaporated milk","Pasteurized milk"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:33.683Z"'::jsonb),
('anki-card-1757643046342-92', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'To minimize reaching the smoking temperature of fat in frying, use:', 'Deep and narrow pan', 'To minimize reaching the high smoking temperature and thermal breakdown of frying oil, cooks should use a deep and narrow pan, which minimizes the surface area of oil exposed to atmospheric oxygen.', '["Pan without cover","Deep and narrow pan","Shallow and wide diameter pan","Covered pan"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:37.577Z"'::jsonb),
('anki-card-1757643064559-93', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The amount of soda required to neutralize 1 cup sour milk:', '1 tsp', 'In culinary baking science, 1 teaspoon of baking soda (sodium bicarbonate) is the standard neutralizing leavening proportion required to react with and neutralize 1 cup of sour milk or buttermilk.', '["1 tsp","½ tsp","¼ tsp","1/8 tsp"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:41:41.830Z"'::jsonb),
('anki-card-1757643079325-94', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This is used in sensory evaluation', 'Hedonic scale', 'A hedonic scale (such as a 9-point facial or descriptive scale ranging from "dislike extremely" to "like extremely") is the standard subjective rating tool used in food sensory evaluation to measure consumer food acceptance and preference.', '["Hedonic scale","Weighing scale","Salometer","Fish scale"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:40:16.127Z"'::jsonb),
('anki-card-1757643096992-95', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A marbled meat has:', 'Fat between muscle layers', 'Marbled meat refers to skeletal muscle containing white flecks and streaks of intramuscular adipose tissue distributed evenly between the muscle fiber bundles, enhancing juiciness, flavor, and tenderness during cooking.', '["No connective tissues","No fat","Fat between muscle layers","Connective tissues between muscle layers"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:40:29.431Z"'::jsonb),
('anki-card-1757643117940-96', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Increasing the chain length of a saturated fatty acid will ____its melting point.', 'Increase', 'As the carbon chain length of a saturated fatty acid increases, intermolecular Van der Waals forces become stronger, which causes its melting point to increase (requiring more thermal energy to transition from solid to liquid).', '["Increase","Decrease","Saturate","Influence"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:40:33.669Z"'::jsonb),
('anki-card-1757643134722-97', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Presence of Escherichia coli in water indicates:', 'Fecal contamination', 'The presence of Escherichia coli (E. coli) in water or food supplies serves as the definitive indicator organism confirming recent fecal contamination and potential pathogenic hazards.', '["Chemical pollution","Fecal contamination","Soil","Dirt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:40:38.683Z"'::jsonb),
('anki-card-1757643150105-98', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Foods remain unsafe when held in the temperature danger zone for more than:', 'Four hours', 'According to standard public health and food safety codes, perishable TCS foods must not remain within the Temperature Danger Zone for a cumulative total of more than four hours before being consumed, reheated, or discarded.', '["One hour","Two hours","Three hours","Four hours"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:40:43.257Z"'::jsonb),
('anki-card-1757643175838-99', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Stirring of starch in cold water before boiling is done to:', 'Prevent clumping', 'Stirring dry starch into cold water before heating (forming a slurry) is done to separate the starch granules and prevent clumping when heated in boiling liquids.', '["Prevent clumping","Facilitate inversion","Evaporate excess water","Prevent raw-starch flavor"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.234Z"'::jsonb, '"2026-11-09T05:40:46.852Z"'::jsonb),
('anki-card-1757643196053-100', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The area that must be adjacent to the cooking area in the kitchen.', 'Preparation area', 'In efficient kitchen workflow design, the raw preparation area (prep stations) must be located immediately adjacent to the cooking area to streamline the transfer of prepped ingredients to range lines.', '["Receiving area","Serving area","Dishwashing area","Preparation area"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:41:45.422Z"'::jsonb),
('anki-card-1757643219302-101', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A flooring material suitable only for storeroom, laundry, and receiving area.', 'Cement', 'Plain cement (concrete screed) is a porous and utilitarian flooring material suitable primarily for low-traffic utility spaces like storerooms, laundry rooms, and loading receiving bays, rather than wet main kitchen production lines.', '["Wood","Cement","Concrete","Tile"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:41:50.306Z"'::jsonb),
('anki-card-1757643238218-102', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'How many servings may be produced from 1 pint of salsa when each serving is set at 2 tablespoon?', '16 servings', 'To calculate the total portions from a given volume:

1 pint = 2 cups = 32 tablespoons.

Portion size = 2 tablespoons per serving.

Total servings = 32 tablespoons ÷ 2 tablespoons/serving = 16 servings.', '["14 servings","16 servings","18 servings","20 servings"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:41:55.612Z"'::jsonb),
('anki-card-1757643255417-103', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Cooking fruits will result into only one of the following.', 'Softening of the cellulose', 'Cooking fruits breaks down protopectin and softens plant cell wall structural fibers (cellulose and hemicellulose), making fruits tender and digestible.', '["Softening of the cellulose","Burning of the starch","Shorter storage life","Increasing carbohydrate level"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:01.942Z"'::jsonb),
('anki-card-1757643276767-104', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Good cost control means.', 'None of the above', 'Good cost control means maximizing efficiency, minimizing waste, utilizing standard recipes, and controlling portion sizes without blindly sacrificing food quality, omitting necessary ingredients, or arbitrarily starving customer satisfaction. Therefore, options A and B do not define good cost control, making "None of the above" correct.', '["Omitting expensive ingredients","Reducing portion sizes","Both a and b","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:05.849Z"'::jsonb),
('anki-card-1757643342146-105', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The following is true for standardized recipes except:', 'Should only be done by the same cook', 'A standardized recipe guarantees consistent yield, portion size, and sensory quality regardless of who prepares it, provided ingredient specifications and instructions are followed. Claiming it should only be done by the same cook violates the very definition of standardization, making it the correct exception statement.', '["Should only be done by the same cook","Yields the same amount","Yields same sensory quality","Should be done with the same ingredient specifications"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:10.838Z"'::jsonb),
('anki-card-1757643359778-106', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following foodservice system requires the least number of equipment and personnel?', 'Assembly-serve system', 'An assembly-serve system (convenience food service) requires the absolute least amount of heavy equipment, complex food processing, and kitchen personnel because meals arrive pre-prepared.', '["Commissary system","Ready-prepared system","Conventional system","Assembly-serve system"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:15.207Z"'::jsonb),
('anki-card-1757643376912-107', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'She laid the foundation of modern dietetics in the Philippines', 'Irma Florentin', 'Irma Florentin is celebrated in Philippine nutritional history as a pioneering leader who laid the foundational roots for modern clinical dietetics and professional dietetic practice in the Philippines.

• Clara Ruth Darby: An American nutritionist who contributed significantly to early Philippine home economics and nutrition education.
• Velona Corpus / Presentacion Perez: Distinguished leaders in Philippine home economics and education.', '["Clara Ruth Darby","Velona Corpus","Irma Florentin","Presentacion Perez"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:37.421Z"'::jsonb),
('anki-card-1757643395594-108', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A cleaning agent used to remove proteins and organic materials', 'Alkaline cleaner', 'Alkaline cleaners are formulated to break down, saponify, and remove heavy grease, protein films, and organic food soils from institutional kitchen equipment and surfaces.

• Quats (Quaternary ammonium compounds): Chemical sanitizers used to reduce microbial loads after cleaning.
• Chlorine cleaner: A sanitizing and bleaching agent.
• Acid cleaner: Used specifically to remove mineral deposits, scale, and rust (lime-away).', '["Quats","Alkaline cleaner","Chlorine cleaner","Acid cleaner"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:43.253Z"'::jsonb)
