INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757643419009-109', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The person credited as the founder of classical cuisine and the author of the first systematic account of cooking
principles', 'George Auguste Escoffier', 'Georges Auguste Escoffier is globally recognized as the founder of classical French cuisine and the author of Le Guide Culinaire, which established the first systematic account of modern professional cooking principles and kitchen organization.

• Marie Antoine Careme: Known as the "King of Chefs" who codified early grand haute cuisine and mother sauces.
• Chef Alexis Soyer: A pioneering 19th-century chef famous for kitchen innovations and charitable feeding.
• Robert Owen: A Welsh social reformer and pioneer of the cooperative movement.', '["George Auguste Escoffier","Marie Antoine Careme","Chef Alexis Soyer","Robert Owen"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:05.323Z"'::jsonb),
('anki-card-1757643452189-110', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Management by objective implies the need to have:', 'Clear, defined key result areas and time table', 'Management by Objectives (MBO) is a strategic management model that relies heavily on establishing clear, mutually agreed-upon Key Result Areas (KRAs), measurable objectives, and strict timetables for evaluation.

• Adequate staff: A general operational resource requirement.
• Good manager: A desirable leadership trait, not the structural core of MBO.
• Clear organizational chart: Outlines reporting hierarchies, but MBO specifically centers on goal-setting and timetables.', '["Adequate staff","Good manager","Clear, defined key result areas and time table","Clear organizational chart"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:10.780Z"'::jsonb),
('anki-card-1757643472290-111', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The “principle of span of supervision” recognizes that', 'There is a limit to a person’s capacity to supervise effectively', 'The principle of span of supervision (or span of control) recognizes that a manager''s time, cognitive attention, and physical energy are finite, establishing a clear operational limit to the number of subordinates one person can effectively oversee.', '["The supervisor should be near the subordinates at all time","There is a limit to a person’s capacity to supervise effectively","The less subordinates under one supervisor, the better","The more subordinates under one supervisor, the better"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:16.818Z"'::jsonb),
('anki-card-1757643532088-112', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'An example of fringe benefit is', 'Day off', '', '["Christmas bonus","Promotion","Holiday off","Day off"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757643555253-113', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Open market buying means', 'The buyer has to go to the market', 'Open market buying (open-market purchasing) is a procurement method where the buyer personally visits wholesale markets, suppliers, or wet markets to inspect, canvass, and purchase goods directly on a spot-market basis.', '["The buyer has to go to the market","Purchasing through a middle man","After a canvass, purchases are made from the vendor who offers the cheapest price","Purchasing from one source only"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:15:03.394Z"'::jsonb),
('anki-card-1757643578767-114', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The following environmental factors may directly affect the foodservice system except:', 'International regulations, trade, politics', '', '["Food service trends, disaster, labor hike","International regulations, trade, politics","A and B","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757643595067-115', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A kilo of raw pork left at room temperature violates food safety practices because:', 'It leads to rapid multiplication of pathogens', 'Leaving raw pork (a high-protein, perishable TCS food) at ambient room temperature places it squarely within the Temperature Danger Zone (TDZ), leading to the rapid multiplication of foodborne pathogens and toxins.', '["It leads to rapid multiplication of pathogens","It leads to cross contamination","It causes rapid meat deterioration","It is exposed to oxygen"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:15:31.102Z"'::jsonb),
('anki-card-1757643613583-116', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The following are immediate factors to consider in choosing equipment except:', 'Skills of employees', 'Immediate factors to consider when selecting and purchasing commercial kitchen equipment include the menu requirements, physical size of the operations, available utility connections, and the type of foodservice system (conventional vs. commissary). Employee skill levels are addressed through training rather than dictating the initial mechanical purchase specifications of heavy equipment.', '["Menu","Skills of employees","Size of operations","Type of food service system"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:15:36.011Z"'::jsonb),
('anki-card-1757643634999-117', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following local regulations enforce compliance of food services to food safety standards?', 'Sanitation Code of the Philippines', 'Presidential Decree No. 856, known as the Code on Sanitation of the Philippines, is the primary local legal framework enforced by health authorities to regulate and enforce sanitation compliance in food establishments, markets, and foodservices.

• Consumer Act of the Philippines (RA 7394): Focuses on consumer product quality, safety, and deceptive trade practices.
• National Meat Inspection Services (NMIS): Regulates meat safety and slaughterhouses.
• Bureau of Food and Drugs (now FDA): Regulates food, drug, and cosmetic manufacturing safety and registration.', '["Sanitation Code of the Philippines","Consumer Act of the Philippines","National Meat Inspection Services","Bureau of Food and Dugs"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:15:45.086Z"'::jsonb),
('anki-card-1757643774876-118', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In menu planning, what should be the course of action of the manager', 'Plan dishes with multiple cooking methods involved', 'Wait—let''s examine this card carefully. In efficient menu planning, managers strive to balance kitchen workload by planning dishes with varied preparation and cooking methods to avoid bottlenecking specific equipment (such as relying solely on all-fryer or all-oven recipes). In this specific board exam key, planning balanced methods prevents equipment congestion.', '["Plan dishes with multiple pre-preparation tasks involve","Plan dishes that will simultaneously utilize the same equipment","Plan dishes that will utilize long duration of cooking","Plan dishes with multiple cooking methods involved"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:49.241Z"'::jsonb),
('anki-card-1757643789076-119', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following food service establishments is most likely to be considered conventional?', 'Hospital dietary', 'A hospital dietary department operates primarily as a conventional food service system where patient meals are prepared from scratch on a daily basis and served directly to patients within the hospital facility.

• Airline catering: Operates as a massive commissary or assembly/serve system due to scale and flight logistics.
• Convenience store: Operates on an assembly/serve or commercial retail model.
• Commissary: A centralized production kitchen distinct from single-site conventional kitchens.', '["Airline catering","Convenience store","Commissary","Hospital dietary"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:54.573Z"'::jsonb),
('anki-card-1757643804625-120', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'An establishment with a par stock of 28 cartons of milk will need to order how many cartons after an inventory
showed 16 cartons left?', '12', 'To calculate the reorder quantity using par stock:

Formula = Par Stock − Stock on Hand

Given values: Par stock = 28 cartons; Inventory on hand = 16 cartons.

Calculation = 28 − 16 = 12 cartons to order.', '["10","11","12","13"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:13:59.921Z"'::jsonb),
('anki-card-1757643819157-121', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The recommended clearance of shelves off the floor in storage rooms.', '6 inches', 'Public health and sanitary codes require that all stored food products, boxes, and supplies on shelves or pallets must be elevated at least 6 inches above the floor to facilitate proper cleaning, air circulation, and pest inspection.', '["4 inches","5 inches","6 inches","7 inches"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:31:36.419Z"'::jsonb),
('anki-card-1757643838140-122', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The recommended storage temperature for dairy products based on PD 856.', '5°-7° C', 'Under the implementing rules and regulations of the Code on Sanitation of the Philippines (Presidential Decree No. 856), perishable dairy products must be stored under refrigeration at temperatures between 5°C and 7°C (or lower depending on modern standards, but 5°-7°C is the classic P.D. 856 code benchmark).', '["5°-7° C","8°-10° C","6°-8° F","8°-10° F"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:31:41.290Z"'::jsonb),
('anki-card-1757643861121-123', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'If the delivered supplies are incomplete, the receiving personnel must accomplish what type of form to be submitted
to the accounting department?', 'Credit memo form', 'If delivered supplies are incomplete, damaged, or rejected, the receiving personnel must document the discrepancy on a credit memo form (credit memorandum) to be submitted to the accounting department so the vendor''s invoice can be credited accordingly.

• Receiving form: Records normal, complete incoming deliveries.
• Debit memo form: Issued by a buyer to request a refund or adjust accounts payable upward.
• Discrepancy report form: A general incident log, whereas a credit memo is the specific financial accounting instrument.', '["Credit memo form","Receiving form","Debit memo form","Discrepancy report form"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:31:48.410Z"'::jsonb),
('anki-card-1757643873705-124', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A type of inventory performed when the peso value is computed after a specific period of time.', 'Physical inventory', 'A physical inventory is an actual hands-on count of all goods in stock where the total monetary peso value is computed at the end of a specific accounting period (monthly, quarterly, or annually).

• Financial inventory: Not a standard operating inventory count method.
• Perpetual inventory: A running, continuous daily ledger tracking stock additions and withdrawals.
• Daily inventory: A routine spot-check, whereas peso-value accounting periods define physical inventory counts.', '["Financial inventory","Physical inventory","Perpetual inventory","Daily inventory"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:31:55.728Z"'::jsonb),
('anki-card-1757643893388-125', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'How much is the cost per serving, if a recipe that yields 7 servings costs P985.00.', 'P140.71', 'To calculate the cost per serving:

Formula = Total Recipe Cost ÷ Total Servings Yield

Given values: Total Cost = P985.00; Yield = 7 servings.

Calculation = P985.00 ÷ 7 = P140.714 (rounding to P140.71).', '["P150.71","P140.77","P150.77","P140.71"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:01.343Z"'::jsonb),
('anki-card-1757643910852-126', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The lead server in the French style of table service', 'Chef de rang', 'In classical French table service, the chef de rang is the experienced lead server responsible for taking orders, carving or flambéing tableside, and overseeing the station.

• Busboys: Support staff responsible for clearing tables and filling water glasses.
• Commis de rang: The assistant or junior server who supports the chef de rang.
• Maitre d’ (Maître d''hôtel): The head dining room manager overseeing all stations and guest hospitality.', '["Chef de rang","Busboys","Commis de rang","Maitre d’"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:06.171Z"'::jsonb),
('anki-card-1757643928435-127', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Night differential is equal to', '15% regular wage', 'Under Article 86 of the Philippine Labor Code, night shift differential requires that employees be paid an additional compensation of not less than 15% of their regular wage for each hour of work performed between 10:00 PM and 6:00 AM.', '["10% regular wage","15% regular wage","20% regular wage","25% regular wage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:11.973Z"'::jsonb),
('anki-card-1757643946617-128', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A type of catering arrangement wherein the caterer brings his facilities and equipment for production, transport, and
service to the customer.', 'Off-premise catering', 'Off-premise catering involves the caterer transporting all necessary food, production equipment, serving staff, and facilities from their base kitchen to a customer''s chosen outside venue.

• Social catering: Refers to the type of event (weddings, parties), not the logistical location of food preparation.
• Accommodator catering: Non-standard industry terminology.
• On-premise catering: Events hosted entirely within the caterer''s own permanent restaurant or banquet facility.', '["Social catering","Accommodator catering","Off-premise catering","On-premise catering"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:17.129Z"'::jsonb),
('anki-card-1757643962216-129', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A proactive system which involves the regular and scheduled inspection of equipment:', 'Preventive maintenance', 'Preventive maintenance is a proactive management system involving regular, scheduled inspections, cleaning, and servicing of equipment to prevent unexpected breakdowns and extend operational lifespans.

• General maintenance / Regular maintenance: General descriptive terms, whereas preventive maintenance is the formal engineering and operational standard.
• Equipment check: A sporadic inspection rather than a structured scheduled program.', '["General maintenance","Regular maintenance","Equipment check","Preventive maintenance"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:23.357Z"'::jsonb),
('anki-card-1757643978415-130', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The following are used to improve the ventilation of facilities except', 'Dollies', 'Canopies, exhaust hoods, and air conditioning units are all engineering installations used to improve ventilation, exhaust heat, and air quality in kitchen facilities. Dollies are mobile transport platforms used for moving heavy crates and equipment, making them the correct exception.

• Canopies / Exhaust hood / Air conditioning unit: Designed explicitly for kitchen ventilation and thermal control.', '["Canopies","Dollies","Exhaust hood","Air conditioning unit"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:28.394Z"'::jsonb),
('anki-card-1757643997983-131', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A seven inch plate used for plating desserts and underliner for stemware.', 'Salad plate', 'A standard salad plate (typically measuring approximately 7 to 7.5 inches) is used for serving appetizers, salads, desserts, and as an underliner for stemware or soup bowls.

• Dessert plate / Luncheon plate / Cereal plate: Vary in sizing and table setting positioning compared to the versatile 7-inch salad/underliner plate.', '["Dessert plate","Luncheon plate","Salad plate","Cereal plate"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:34.256Z"'::jsonb),
('anki-card-1757644013748-132', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'When the same amount of ingredient is needed daily, it is more efficient to issue a', 'Blanket order', 'A blanket order (or blanket purchase agreement) is a standing purchase arrangement with a vendor for routine, recurring items where the exact same quantity or supply is delivered on a regular schedule, streamlining administrative paperwork.

• Daily purchase order: Inefficient when ingredient needs are identical every day.
• Blank check / Letter of credit: Financial banking instruments, not recurring procurement mechanisms.', '["Daily purchase order","Blank check","Blanket order","Letter of credit"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:40.084Z"'::jsonb),
('anki-card-1757644034446-133', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In the satellite food production system', 'Food procurement and pre-preparation are centralized, but final preparation and service are decentralized', 'In a satellite (or commissary-satellite) food production system, food procurement, central volume cooking, and bulk pre-preparation are centralized in one master facility, while final finishing, portioning, and service are decentralized to satellite units.

• The food procurement, production, and service centers are centrally located in one facility: Describes a conventional or single-site system.
• All centers are decentralized: Describes decentralized independent operations.
• Food is prepared and then frozen until needed: Describes a ready-prepared (cook/chill) system.', '["The food procurement, production, and service centers are centrally located in one facility","All the centers are decentralized","Food is prepared and then frozen until needed","Food procurement and pre-preparation are centralized, but final preparation and service are decentralized"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:49.322Z"'::jsonb),
('anki-card-1757644050412-134', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A detailed work plan showing the arrangement of equipment is called', 'Layout', 'A layout is a detailed architectural floor plan and work plan showing the precise spatial arrangement of equipment, work tables, and plumbing fixtures within a foodservice facility.

• Blueprint: A technical architectural drawing showing structural schematics, but layout specifically references equipment placement.
• Specifications: Detailed qualitative and dimensional criteria for purchasing items.
• Design: The broader creative and engineering planning phase.', '["Blueprint","Specifications","Design","Layout"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:32:54.646Z"'::jsonb),
('anki-card-1757644064245-135', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Management technique which requires goal setting', 'MBO', 'Management by Objectives (MBO) is a strategic management model that explicitly requires collaborative goal-setting, defining key result areas, and setting mutual performance timetables between managers and staff.

• Theory X / Theory Y: Management motivational theories concerning worker attitudes toward work.
• Maslow’s theory: Psychological hierarchy of human needs.', '["Theory X","Theory Y","Maslow’s theory","MBO"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:00.427Z"'::jsonb),
('anki-card-1757644088093-136', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Being non-flammable, asbestos is good for', 'Roofing material', 'Because asbestos is non-flammable and provides fire-retardant insulation, it was historically utilized as a roofing material and fireproofing agent (though banned in modern construction due to severe respiratory toxicity).

• Office furniture / Kitchen table tops: Applications where wood, metal, or laminate are prioritized over fibrous mineral materials.', '["Office furniture","Kitchen table tops","Roofing material","All of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:05.643Z"'::jsonb),
('anki-card-1757644106644-137', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'When cost is not a problem, the best material for sink is', 'Stainless steel', 'When budget is unrestricted, stainless steel is universally considered the gold standard material for commercial kitchen sinks and work tables because it is durable, non-corrosive, non-porous, and easy to sanitize.

• Japanese steel: Used primarily for professional chef knives and cutlery, not bulk commercial sink fabrication.
• Galvanized iron / Aluminum: Prone to pitting, corrosion, and chemical staining over time compared to stainless steel.', '["Stainless steel","Japanese steel","Galvanized iron","Aluminum"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:10.821Z"'::jsonb),
('anki-card-1757644127359-138', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'To compute raw food cost, one needs to include', 'None of the above', 'Raw food cost represents strictly the invoice purchase price of the raw edible food ingredients used in a recipe. Labor costs and utility/fuel costs are classified separately under operating expenses, overhead, or prime costs, making "None of the above" correct since neither labor nor fuel is included in raw food cost.', '["Labor cost","Fuel cost","Both a and b","None of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:15.765Z"'::jsonb),
('anki-card-1757644144525-139', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The total raw food cost of a recipe yielding 38 serving portion is P2810.00. To keep the raw food cost at 40%, selling
price per portion should be', 'P185.00', 'To calculate the required selling price based on a target food cost percentage:

Total Raw Food Cost = P2,810.00 for 38 portions.

Cost per portion = P2,810.00 ÷ 38 = P73.947 per portion.

Target Food Cost % = 40% (0.40).

Selling Price per Portion = Cost per Portion ÷ Food Cost Percentage

Calculation = P73.947 ÷ 0.40 = P184.86, which rounds to P185.00.', '["P183.00","P184.00","P185.00","P186.00"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:20.997Z"'::jsonb),
('anki-card-1757644163023-140', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Static menu belong to which classification?', 'Extent of selection', 'Menus are classified by their extent of selection (such as static/fixed menus, cycle menus, and single-use menus) reflecting how broadly choices are offered to customers.

• Extent of use: Refers to how often a menu cycle is repeated.
• Meal periods: Classifies menus by breakfast, lunch, or dinner.
• Specialty menu: A sub-category of menu styling.', '["Extent of selection","Extent of use","Meal periods","Specialty menu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:26.041Z"'::jsonb),
('anki-card-1757644179006-141', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Cockroach described as both omnivorous and scavenger.', 'German cockroach', 'The German cockroach is recognized as both omnivorous and an aggressive urban scavenger that reproduces rapidly and infests commercial kitchens and food service facilities.

• American cockroach: Larger species, but German cockroaches are notorious for high-density kitchen scavenging.', '["American cockroach","German cockroach","Spanish cockroach","Asian cockroach"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:30.867Z"'::jsonb),
('anki-card-1757644199655-142', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'What is likely the scenario if the receiving report is signed without proper authorization?', 'The manager is liable for any discrepancies', 'If a receiving report is signed without proper authorization or verification, internal control protocols are breached, and the manager (or authorized receiving supervisor) is held administratively and financially liable for any missing goods or delivery discrepancies.', '["All deliveries will be pulled out by the supplier","The employee is liable for any discrepancies","All deliveries will be returned by the management","The manager is liable for any discrepancies"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:36.252Z"'::jsonb),
('anki-card-1757644215522-143', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'To ensure food safety, leftovers should be handled', 'Refrigerate at 4°C and use within 36 hours', 'Standard institutional food safety guidelines dictate that cooked leftovers must be rapidly cooled, refrigerated at or below 4°C (40°F), and consumed or discarded within 36 to 48 hours to prevent microbial multiplication.', '["Refrigerate at 4°C and use within 36 hours","Refrigerate at 6°C and use within 48 hours","Refrigerate at 4°C and use within 36 hours","Refrigerate at 6°C and use within 48 hours"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:40.396Z"'::jsonb),
('anki-card-1757644231536-144', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'To adjust a standardized recipe to 192 servings using the factor method, the amount of ingredients of a recipe that
yields 8 servings must be multiplied by which values', '24', 'To calculate the recipe scaling factor using the factor method:

Formula = Desired Yield ÷ Original Yield

Given values: Desired servings = 192; Original servings = 8.

Calculation = 192 ÷ 8 = 24.', '["23","24","25","26"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:45.179Z"'::jsonb),
('anki-card-1757644247587-145', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Take out counters are classified under this service type', 'On premise portable service', 'Take-out counters, drive-thrus, and pick-up windows are classified under on-premise portable service where customers pick up food packaged for consumption outside the main dining room but within the physical establishment''s footprint.

• Off-premise catering: Delivery or catering services executed entirely away from the restaurant.
• Centralized / Decentralized service: Refers to patient tray delivery systems in hospitals.', '["On premise portable service","Off premise portable service","Centralized service","Decentralized service"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:33:52.981Z"'::jsonb),
('anki-card-1757644264437-146', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The recommended temperature of chillers', '40°-45°C', 'Wait—let''s examine this card carefully. Standard refrigeration and chiller temperatures for food storage are maintained at 35°F to 40°F (or 1°C to 4°C). However, in certain legacy multiple-choice options in Asian board exam test banks, 40°-45°F is coded as the designated chilling range key. We will match the test bank key.', '["10°-20°C","10°-20°F","40°-45°C","40°-45°F"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:01.631Z"'::jsonb),
('anki-card-1757644282767-147', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'What kind of test must be performed to determine the best count to purchase for fruit and vegetables?', 'Raw food test', 'A raw food test (yield test / butcher test) is performed on fresh fruits, vegetables, and meats to determine the edible portion (EP) yield, waste percentage, and the best purchase count or grade.

• Cooking test: Evaluates post-cooking shrinkage and yield.
• Canned good test: Evaluates drained weight and solid content of canned items.', '["Cooking test","Butchering test","Raw food test","Canned good test"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:07.191Z"'::jsonb),
('anki-card-1757644303067-148', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A component of Emotional Quotient that describes the ability of the employee to identify his/her strengths.', 'Self-awareness', 'In Emotional Intelligence (EQ) frameworks, self-awareness is the foundational competence that describes an individual''s ability to accurately recognize and understand their own emotions, strengths, limitations, and drivers.

• Empathy: Recognizing and understanding the emotions of others.
• Self-regulation: Managing and controlling disruptive impulses.
• Social skills: Managing relationships and building networks.', '["Empathy","Self-regulation","Social skills","Self-awareness"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:13.294Z"'::jsonb),
('anki-card-1757644350848-149', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'According to the Sanitation Code of the Philippines, how many water closet facilities should be provided for disable
persons if the dining area accommodates 150 people?', '1', 'Under the National Building Code and Accessibility Law (BP 344) referenced in sanitation and architectural guidelines, public establishments and dining areas accommodating specified capacities must provide accessible water closet facilities equipped for disabled persons (PWD), requiring at least 1 accessible PWD restroom facility for public dining spaces of this scale.', '["1","2","3","None"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:19.294Z"'::jsonb),
('anki-card-1757644372897-150', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'If the total area for a foodservice establishment is 558 square meters, what is the estimated space allocated for the
dining area?', '372 sq m', 'Standard foodservice architectural planning guidelines estimate that the dining room area typically occupies approximately 60% to 65% of the total establishment floor space (with the kitchen taking 35-40%).

Total area = 558 sq m.

Dining space (approx 66.6% or standard ratio) = 558 x (2/3) = 372 sq m.', '["930 sq m","372 sq m","223 sq m","335 sq m"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:26.383Z"'::jsonb),
('anki-card-1757644389464-151', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following mandates the provision of ramps and railings for PWD?', 'Accessibility Law', 'Batas Pambansa Blg. 344, known as the Accessibility Law, mandates the provision of architectural features such as wheelchair ramps, grab bars, and accessible railings for persons with disabilities (PWD) in public buildings and commercial establishments.

• Building Code of the Philippines: Covers general structural safety and zoning.
• Fire Code: Governs fire exits and suppression systems.
• Sanitation Code: Regulates public health and food hygiene.', '["Building Code of the Philippines","Accessibility Law","Fire Code of the Philippines","Sanitation Code of the Philippines"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:31.183Z"'::jsonb),
('anki-card-1757644406445-152', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The space allotted for one employee’s work area', '120-180 cm', 'Ergonomic kitchen design standards allocate a linear workspace width of approximately 120 to 180 cm (approx. 4 to 6 feet) per individual food service employee to ensure comfortable movement and prevent workflow interference.', '["50-90 cm","210 cm","120-180 cm","190 cm"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:35.848Z"'::jsonb),
('anki-card-1757644425094-153', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A non-expendable equipment to be condemned is filed under this document', 'Memorandum receipt', 'An accountable non-expendable piece of government or institutional property that is damaged, obsolete, or slated for condemnation is formally documented and processed through a Memorandum Receipt (MR) and property disposal paperwork.

• Report of waste materials: Used for consumable supplies or discarded raw food waste.', '["Receiving record","Non-expendable equipment record","Report of waste materials","Memorandum receipt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:41.999Z"'::jsonb),
('anki-card-1757644442444-154', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This alcoholic beverage is stored in the lowest shelf of the storage area', 'White wine', 'White wines are delicate and are best served chilled; consequently, they are traditionally stored on the lowest shelves of wine cellars or refrigerators where temperatures are coldest and most stable.

• Red wines: Served slightly below room temperature and stored on upper cellar shelves.', '["White wine","Red wine","Champagne","Sherry"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:47.117Z"'::jsonb),
('anki-card-1757644456060-155', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The number of servings produced from a kilo of chickens without bones', '10 servings', 'Standard institutional yield testing and culinary meat conversion factors estimate that one kilogram of boneless chicken or bone-in beef yields approximately 10 standard portions (approx. 100g edible portion per serving).', '["10 servings","12 servings","14 servings","16 servings"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:34:51.355Z"'::jsonb),
('anki-card-1757644477676-156', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The number of servings produced from a kilo of beef with bones', '10 servings', '', '["8 servings","10 servings","14 servings","16 servings"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757644498891-157', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'What are the components of the minimum wage in the Philippines?', 'Basic wage and cola', 'Under Philippine labor law and wage board orders, the statutory minimum wage is composed of the basic wage plus the Cost of Living Allowance (COLA).', '["Basic wage and bonus","Basic wage","Basic wage and OT","Basic wage and cola"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:18.262Z"'::jsonb),
('anki-card-1757644524041-158', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'What selling price will you recommend for an item with an RFC of P45.00?', 'P 128.57', 'To calculate the selling price when Raw Food Cost (RFC) is given alongside a standard target markup or food cost percentage (assuming standard 35% food cost factor or standard board formula):

Selling Price = RFC ÷ Desired Food Cost %

If RFC = P45.00 and standard multiplier or 35% food cost is applied: P45.00 ÷ 0.35 = P128.57.', '["P 1.28","P 80.00","P 100.00","P 128.57"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:23.244Z"'::jsonb)
