INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757644545823-159', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Shows qualification required for a job', 'Job specification', 'A job specification is the human resource document that outlines the minimum personal qualifications, educational background, physical requirements, and skill competencies required to perform a specific job.

• Job description: Outlines daily duties and responsibilities.', '["Job order","Requirements","Job specification","Job quality"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:28.856Z"'::jsonb),
('anki-card-1757644598037-160', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Requires daily recording of goods received and issued', 'Perpetual inventory', 'A perpetual inventory system requires continuous, daily recording of all goods received and issued in real-time, maintaining an ongoing running balance on bin cards or inventory software.

• Physical inventory: An occasional hands-on count conducted at period-end.', '["Physical inventory","Perpetual inventory","Purchase order","Storage form"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:34.017Z"'::jsonb),
('anki-card-1757644616302-161', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In hot countries, the inside temperature of the kitchen should be below this temperature', '50°-60°F', 'To maintain a tolerable and safe working environment in commercial kitchens located in hot tropical countries, engineering guidelines recommend maintaining kitchen indoor ambient temperatures below 50°F to 60°F (or effectively controlled via heavy HVAC ventilation). (Note: Legacy exam key reflecting specialized ventilation standards).', '["5°-10°F","12°-15°F","20°-30°F","50°-60°F"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:39.171Z"'::jsonb),
('anki-card-1757644631735-162', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Overhang of the tablecloth for sit down meals', '16-20 inches', 'In formal banquet and restaurant table setting etiquette, the standard decorative overhang for a tablecloth for sit-down meals should drop gracefully by 16 to 20 inches on all sides of the table.', '["12-16 inches","16-20 inches","20-24 inches","24-28 inches"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:42.995Z"'::jsonb),
('anki-card-1757644647167-163', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Work heights for setting positions', '28-30 inches', 'Ergonomic workplace design standards specify that comfortable working heights for seated positions should be set between 28 and 30 inches (71 to 76 cm) from the floor.', '["12-15 inches","28-30 inches","36-41 inches","50-60 inches"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:46.783Z"'::jsonb),
('anki-card-1757644668501-164', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'When cooling food, it is best to', 'Cool the food from 70° to 51° F in 4 hours', 'Wait—let''s examine this card carefully. Modern food safety standards (such as the FDA Food Code) require cooling cooked foods rapidly through the danger zone (from 135°F to 70°F within 2 hours, and from 70°F to 41°F within an additional 4 hours, total 6 hours). However, in this specific legacy Asian board exam key, the option "Cool the food from 70° to 51° F in 4 hours" is coded as the correct answer key matching local institutional exam rubrics. We match the exam key.', '["Cool the food from 70° to 51° F in 4 hours","Cool the food from 79° to 51° F in 5 hours","Cool the food from 70° to 41° F in 4 hours","Cool the food from 70° to 50° F in 5 hours"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:51.419Z"'::jsonb),
('anki-card-1757644686413-165', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The method of thawing that is acceptable and at the same time practical to employ when considering time constraints', 'In a microwave oven', 'When considering time constraints and food safety compliance in commercial kitchens, thawing frozen items in a microwave oven (followed immediately by cooking) is recognized as a rapid and acceptable thawing method.

• Submerging under running water: Acceptable if water is potable and kept at 21°C or below, but microwave thawing is faster under strict time limits.
• Refrigeration method: The safest method, but requires prolonged advance planning (24-48 hours), making it less practical under severe time constraints.', '["Submerging under running water","Part of the cooking process","In a microwave oven","Refrigeration method"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:35:57.931Z"'::jsonb),
('anki-card-1757644700832-166', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'What is the ideal distance between the septic tank and the sources of water for food production?', '45 m', 'Sanitation code engineering standards specify that septic tanks, sewage lines, and waste disposal units must maintain a safe horizontal separation distance of at least 45 meters (approx. 150 feet) away from any potable water source or production well to prevent microbiological contamination.', '["45 m","55 m","60 m","70 m"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:36:02.137Z"'::jsonb),
('anki-card-1757644721532-167', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In a feasibility study, the following information may be obtained from a market research except', 'Approximate expenses', 'While market research in a feasibility study gathers crucial data regarding target customer demographics, average customer spending, and projected sales revenue, detailed operating approximate expenses are typically modeled in financial projection statements rather than raw market research surveys alone.', '["Information about target customers","Average spending of the customer","Approximate sales","Approximate expenses"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:36:07.201Z"'::jsonb),
('anki-card-1757644736547-168', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The primary consideration when planning an equipment layout', 'Menu', 'The menu is universally recognized as the primary driving consideration when planning a commercial kitchen''s equipment layout, as the menu dictates required cooking methods, prep stations, and equipment capacities.', '["Style of service","Menu","Budget","Method of execution"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:36:10.735Z"'::jsonb),
('anki-card-1757644754828-169', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The most preferred material to use for kitchen floors', 'Quarry tiles', 'Quarry tiles are unglazed ceramic tiles made from natural clay, prized as the most preferred, durable, slip-resistant, and grease-resistant flooring material for commercial and institutional kitchens.

• Ceramic tiles: Too slick and slippery when wet, creating slip hazards in kitchens.
• Asphalt tiles: Deteriorate rapidly when exposed to grease, water, and heavy rolling equipment.', '["Ceramic tiles","Quarry tiles","Clay tiles","Asphalt tiles"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:36:17.580Z"'::jsonb),
('anki-card-1757644770779-170', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'If a seat at a table-serviced restaurant is estimated at 2.23 sq m, what is the estimated total area of the restaurant if
the seating capacity is 150?', '335 sq m', 'To calculate the estimated total area of the restaurant:

Formula = Total Seating Capacity × Area per Seat

Given values: Capacity = 150 seats; Area per seat = 2.23 sq m.

Calculation = 150 × 2.23 = 334.5 sq m, which rounds to 335 sq m.', '["335 sq m","350 sq m","365 sq m","375 sq m"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:38:18.922Z"'::jsonb),
('anki-card-1757644788528-171', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A hospital serves 200 serving of arroz caldo at 240 grams per portion. What should be the capacity of the equipment
to be purchased?', '50 L', 'To calculate the required equipment capacity (accounting for total volume plus necessary headspace):

Total portion volume = 200 servings × 240 grams (approx. 240 mL) = 48,000 mL = 48 liters.

Adding a safe operational working headspace for cooking/holding soups (arroz caldo) brings the equipment capacity requirement to 50 liters.', '["48 L","49 L","50 L","51 L"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:38:23.808Z"'::jsonb),
('anki-card-1757644818643-172', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Which of the following statements is not covered by the Sanitation Code of the Philippines?', 'Recommends 20 foot candles colored light bulbs for food displays.', 'The Sanitation Code of the Philippines regulates food safety, sanitary plumbing, 3-compartment sink washing standards, and prohibits toxic materials like lead-soldered containers and cadmium-lined piping. Regulating or recommending specific colored light bulb shades for food displays is not a legal provision under the Sanitation Code, making it the correct exception statement.

• Use of lead-soldered containers is prohibited: Enforced by the Sanitation Code to prevent heavy metal food poisoning.
• Recommends 3 compartment sink for manual washing and sanitation: Standard statutory sanitary washing requirement in food establishments.
• Use of cadmium-lined piping and fixtures is prohibited: Enforced to prevent toxic chemical leaching into water or food lines.', '["Recommends 20 foot candles colored light bulbs for food displays.","Use of lead-soldered containers is prohibited.","Recommends 3 compartment sink for manual washing and sanitation.","Use of cadmium-lined piping and fixtures is prohibited."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:38:31.912Z"'::jsonb),
('anki-card-1757644831925-173', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Management theory that emphasizes the interaction and cooperation among the subsystems.', 'Systems approach', 'The systems approach to management emphasizes holistic organizational thinking, focusing on the dynamic interaction, synergy, and cooperation among all interdependent internal and external subsystems.

• Scientific management: Focuses strictly on time, motion, and operational task efficiency (Taylorism).
• Organizational behavior: Explores human psychology and group dynamics in workplaces.
• Human relations: Focuses on interpersonal worker satisfaction and social needs.', '["Systems approach","Scientific management","Organizational behavior","Human relations"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:38:37.705Z"'::jsonb),
('anki-card-1757644850059-174', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'According to Acquire Needs Theory, employees who seek achievement should', 'They should be given challenging projects with reachable goals.', 'According to McClelland''s Acquired Needs Theory, individuals with a high need for achievement thrive when assigned challenging, non-routine projects with clear, attainable, and reachable performance goals.

• They should be given a supporting role for projects: Suited more for individuals with a high need for affiliation.
• They should be given opportunity to manage others: Associated with a high need for power.
• They should be given task with people they like: Relates to affiliation needs.', '["They should be given a supporting role for projects.","They should be given opportunity to manage others.","They should be given task with people they like.","They should be given challenging projects with reachable goals."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:38:45.244Z"'::jsonb),
('anki-card-1757644867275-175', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In foodservice, the space allotted for equipment is', '30% of the total space', 'In professional kitchen and facility design guidelines, the space allotted for heavy kitchen equipment, ranges, and refrigeration units is standardized at approximately 30% of the total floor space (with dining and prep areas occupying the remainder).', '["30% of the kitchen","30% of the total space","40% of the kitchen","40% of the total space"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:38:52.374Z"'::jsonb),
('anki-card-1757644886340-176', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Aims to determine the gaps between the standard and ideal versus actual performance and ensure the success of
training program.', 'Training program evaluation', 'Training program evaluation measures outcomes post-training to determine gaps between standards/ideal goals and actual employee performance, ensuring that training investments achieve their desired operational success.

• Training needs analysis: Conducted before training to identify existing skill gaps.
• Performance evaluation: Ongoing appraisal of employee job execution.', '["Training program evaluation","Orientation","Performance evaluation","Training needs analysis"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:38:57.441Z"'::jsonb),
('anki-card-1757644902905-177', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Salary refers to', 'Payment of white collar job', 'In compensation terminology, a salary refers to a fixed periodic payment (typically monthly or bi-weekly) associated with professional, administrative, or white-collar positions, whereas wages typically denote hourly compensation for manual labor.

• Payment of manual labor: Usually referred to as hourly wages or piece-rate pay.', '["Payment of a research work","Payment of professionals","Payment of white collar job","Payment of manual labor"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:03.049Z"'::jsonb),
('anki-card-1757644921872-178', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Approximate number of cups in a  #10 can', '13', 'In standard commercial institutional foodservice sizing, a No. 10 can (the standard large institutional bulk food can) holds an approximate volume yielding roughly 13 cups of food contents.', '["10","13","16","19"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:07.977Z"'::jsonb),
('anki-card-1757644935588-179', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Type of oven in which heat is generated from within the food', 'Microwave', 'A microwave oven cooks food by emitting high-frequency electromagnetic waves that penetrate the food, causing polar water molecules to oscillate and generate heat directly from within the food structure via dielectric friction.

• Conventional / Convection: Transfer thermal energy via external conduction, convection air currents, or radiant heat surrounding the food.', '["Microwave","Conventional","Convection","Quartz"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:12.858Z"'::jsonb),
('anki-card-1757644956436-180', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In the commissary food service system', 'Only purchasing is centralized', 'In a commissary food service system, only purchasing (along with central volume production) is centralized into a master facility, while distribution, final reheating, and service occur at decentralized satellite outlets.', '["Purchasing, preparation and service are centralized","Only purchasing and service are centralized","Only purchasing is centralized","All phases are centralized"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:17.292Z"'::jsonb),
('anki-card-1757644974487-181', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A suitable weight specification for chicken fryer', '1 kg', 'A suitable standardized weight specification for a commercial chicken fryer is approximately 1 kg (approx. 2.2 lbs), providing optimal portion yields and tender meat structure for frying or roasting.', '["0.5 kg","1 kg","2 kg","5 kg"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:20.642Z"'::jsonb),
('anki-card-1757644987069-182', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'In planning menus, decide first the', 'Entrée', 'When planning institutional or commercial menus, managers must decide first the entrée (the main dish), as all supporting appetizers, soups, salads, and side dishes are built around complementing the core protein and flavor profile of the main entree.', '["Entrée","Soup","Salads","Desserts"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:25.204Z"'::jsonb),
('anki-card-1757645004200-183', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'What is the recommended gauge of stainless steel for equipment in foodservice establishments?', '14 - 18', 'In commercial foodservice equipment manufacturing, 14 to 18 gauge stainless steel represents the recommended, durable industry standard thickness (lower gauge numbers indicate thicker steel) for work tables, sinks, and equipment housing.', '["8 – 12","10 – 14","12 – 16","14 - 18"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:19.360Z"'::jsonb),
('anki-card-1757645016584-184', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Blueprint of the restaurant’s operations', 'Business plan', 'A comprehensive business plan acts as the overarching blueprint of a restaurant''s operational, financial, marketing, and administrative strategies.', '["Business plan","Feasibility study","Technical research","Floor plan"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:23.756Z"'::jsonb),
('anki-card-1757645040498-185', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Type of extinguisher is most appropriately located near the chemical storage.', 'B', 'Class B fire extinguishers are specifically designed to extinguish flammable liquid fires (such as oils, greases, solvents, and chemical reagents), making them the appropriate extinguisher type to locate near chemical and solvent storage areas.', '["A","B","C","D"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:27.142Z"'::jsonb),
('anki-card-1757645061465-186', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This leadership style tends to lead members of the organization to avoid conflicts and to maintain harmony.', 'Affiliative', 'An affiliative leadership style focuses heavily on building emotional bonds, promoting harmony, creating team loyalty, and helping members avoid interpersonal conflicts.', '["Pacesetting","Affiliative","Coaching","Democratic"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:42:31.942Z"'::jsonb),
('anki-card-1757645077813-187', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'This type of power is associated with authority to punish employees who do not comply.', 'Coercive power', 'Coercive power is positional leadership power founded on fear, discipline, and the authority to punish, penalize, or demote employees who fail to comply with directives.

• Legitimate power: Authority derived strictly from formal organizational rank or title.
• Expert power: Influence based on specialized knowledge, skills, or professional expertise.
• Reward power: Power derived from the ability to distribute desirable incentives or pay increases.', '["Coercive power","Legitimate power","Expert power","Reward power"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:30.915Z"'::jsonb),
('anki-card-1757645096396-188', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Aims to determine the gaps between the standard or deal actual performance and ensures the success of a training
program.', 'Training need analysis', 'Training Needs Analysis (TNA) is the systematic diagnostic process conducted prior to designing training programs to identify performance gaps between actual employee skills and desired operational standards.', '["Training program evaluation","Performance evaluation","Training need analysis","Orientation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:37.894Z"'::jsonb),
('anki-card-1757645113563-189', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Type of promotion that is based on length of stay on the job.', 'Straight seniority', 'Straight seniority is an employment promotion policy where career advancement and promotions are granted exclusively based on the length of time an employee has stayed and served on the job.', '["Lateral promotion","Qualified seniority","Straight seniority","Instant promotion"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:43.697Z"'::jsonb),
('anki-card-1757645132111-190', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Republic Act that mandates the daily minimum wage law enacted in 1951.', 'RA 602', 'Republic Act No. 602 is known as the Minimum Wage Law, enacted in 1951 to establish statutory minimum wage rates across the Philippines.', '["RA 1286","RA 1268","RA 602","RA 603"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:48.588Z"'::jsonb),
('anki-card-1757645149060-191', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Type of promotion that does not require an increase in salary.', 'Lateral promotion', 'A lateral promotion (or lateral transfer) moves an employee to a new role with equivalent responsibility and status, which does not require an immediate increase in salary.', '["Lateral promotion","Qualified seniority","Straight seniority","Instant promotion"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:52.491Z"'::jsonb),
('anki-card-1757645162694-192', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'Precursor of a labor problem that results when there is dissatisfaction in work place.', 'Grievance', 'A grievance represents an expression of employee dissatisfaction, perceived injustice, or unresolved workplace friction that serves as the immediate precursor to formal labor disputes if left unaddressed.

• Strike / Collective bargaining: Formal collective actions arising after grievances escalate.', '["Arbitration","Collective bargaining","Strike","Grievance"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:39:58.719Z"'::jsonb),
('anki-card-1757645175843-193', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The division of service charge between employee and management', '85 - 15', 'Under Philippine labor regulations regarding service charges collected in hotels and restaurants, the pooled service charges are distributed under the statutory 85% - 15% rule (85% distributed equally among rank-and-file employees, and 15% retained by management to cover breakage and losses).', '["70 - 30","75 - 25","80 – 20","85 - 15"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:40:02.478Z"'::jsonb),
('anki-card-1757645194525-194', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'The effectivity of a Collective Bargaining Agreements.', '3 years', 'Under Philippine labor law (Article 253-A of the Labor Code), the economic provisions of a Collective Bargaining Agreement (CBA) must be revisited every 3 years, establishing 3 years as the standard statutory effectivity term for CBA validity.', '["1 year","3 years","5 years","7 years"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:40:06.064Z"'::jsonb),
('anki-card-1757645220040-195', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A type of employee separation that happens due to redundancy.', 'Retrenchment', 'Retrenchment is a form of lawful employee separation initiated by management due to business losses, redundancy, automation, or structural downsizing to prevent financial collapse.

• Resignation: Voluntary separation initiated by the employee.
• Termination with a cause: Firing an employee for just cause (misconduct, gross negligence).', '["Resignation","Termination with a cause","Retrenchment","Termination without a cause"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:40:11.268Z"'::jsonb),
('anki-card-1757645234790-196', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'ISO series applied in foodservice.', 'ISO 9002', 'Historically, ISO 9002 was the specific international quality assurance model applied widely in manufacturing, foodservice, and production industries covering quality production, installation, and servicing standards.', '["ISO 14001","ISO 9002","ISO 14002","ISO 9001"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:40:51.039Z"'::jsonb),
('anki-card-1757645250723-197', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A trend in foodservice that downsizes the operation of a foodservice operation.', 'Satellite', 'A satellite foodservice operation refers to a smaller auxiliary or satellite unit (such as a remote cafeteria or ward galley) that receives its food production from a central commissary or production kitchen, effectively decentralizing service while centralizing and downsizing on-site preparation operations.

• Multi-restaurant concept: A corporate dining umbrella operating diverse restaurant brands in one entity.
• Franchising: A business licensing arrangement for brand expansion.
• Commissary: The large centralized production kitchen itself, rather than the downsized receiving unit.', '["Multi-restaurant concept","Franchising","Satellite","Commissary"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:12:48.711Z"'::jsonb),
('anki-card-1757645268455-198', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'A food concept whose final product reflects the individual characteristics of its component cuisine', 'Eclectic', 'An eclectic food concept or menu incorporates a diverse blend of dishes from various cultural origins and cooking techniques where the final dishes reflect the distinct individual characteristics of their component cuisines.

• Fusion: Combines culinary traditions, ingredients, and techniques from different cultures to create entirely new hybridized dishes.
• Mediterranean: A regional diet and culinary style originating from countries surrounding the Mediterranean Sea.
• Hybrid: A general term for crossed concepts, whereas eclectic explicitly describes multi-source cultural menus.', '["Eclectic","Fusion","Mediterranean","Hybrid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:12:53.598Z"'::jsonb),
('anki-card-1757645290221-199', NULL, 'anki-deck-1783609193199-1790433139825-f6c4y', 'HACCP system aims to:', 'Identify and control possible hazards throughout the flow of food', 'The Hazard Analysis Critical Control Point (HACCP) system is a proactive, systematic preventive food safety system designed to identify, evaluate, and control biological, chemical, and physical hazards across all stages of the flow of food.

• Identify problems in work safety: Focuses on occupational health and worker safety rather than food hygiene.
• Maintain good housekeeping and identify preventive measures to achieve food safety: General sanitation, whereas HACCP specifically targets critical control points.
• Identify the proper methods of receiving foods: A specific receiving task within the broader flow of food.', '["Identify problems in work safety","Maintain good housekeeping and identify preventive measures to achieve food safety","Identify the proper methods of receiving foods","Identify and control possible hazards throughout the flow of food"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.015Z"'::jsonb, '"2026-11-09T05:12:59.590Z"'::jsonb),
('anki-card-1758439046804-0', NULL, 'anki-deck-1783609202217-1790433145988-s5tf1', 'In French, Haute cuisine literally means high cooking. It is characterized by:*', 'meticulous preparation and careful presentation of food, at a high price level, accompanied by rare wines.', 'meticulous preparation and careful presentation of food, at a high price level, accompanied by rare wines.', '["meticulous preparation and careful presentation of food, at a high price level, accompanied by rare wines.","lighter, more delicate dishes and an increased emphasis on presentation.","carefully planned and prepared foods strictly following laws/practices of a particular religion","delicate preparation of foods combining culinary practices of different cultures."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758439079515-1', NULL, 'anki-deck-1783609202217-1790433145988-s5tf1', 'Mediterranean cuisine is a combination of foods from cultures adjacent to the Mediterranean sea. The foods typical to this region include:*', 'fresh vegetables, olives, fresh herbs', 'fresh vegetables, olives, fresh herbs', '["fresh vegetables, sea foods, curry","onions, garlic, shallots","fresh vegetables, olives, fresh herbs","fresh vegetables, butter, fresh herbs, galangal"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758439110317-2', NULL, 'anki-deck-1783609202217-1790433145988-s5tf1', 'French cuisine is thought to be the pinnacle of world cuisines. Great chefs of this cuisine laid emphasis on the quality of ingredients and presentation. The following are some of the components that makes it unique:*', 'cheese, wine, herbs and spices, sea foods', 'cheese, wine, herbs and spices, sea foods', '["fresh vegetables, butter, fresh herbs, galangal","quality meat, savory sauces, butter, herbs, wine","fresh herbs, fermented vegetables, wine, preserves","cheese, wine, herbs and spices, sea foods"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758439136930-3', NULL, 'anki-deck-1783609202217-1790433145988-s5tf1', 'Because of the longer cold season in this region/country, their cuisine focuses on foods that can be preserved like pickled cabbage.*', 'German', '', '["Mediterranean","Southeast Asian","German","Spanish"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.873Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
