INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758530743894-49', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'If cost of inventory is P 32,380, and average inventory is P16,190, inventory turnover is _____*', '2', 'The standard inventory turnover formula is Cost of Goods Sold / Average Inventory.', '["2","0.5","5","1"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:31:00.368Z"'::jsonb),
('anki-card-1758530755177-50', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Labor cost is considered a ______ cost.*', 'Fixed', 'Note: While labor cost contains variable components (hourly staff scaling with volume), this specific board exam question categorizes labor cost under Fixed cost structures in institutional macro-budgeting frameworks.', '["Fixed","Variable","Prime","Non controllable"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:31:22.890Z"'::jsonb),
('anki-card-1758530767393-51', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Food cost of Seafood Platter is P 145.00. When sold at P P450, what is the food cost percentage?*', '32.2%', 'To calculate the food cost percentage:

Formula = (Food Cost / Selling Price) x 100

Given values: Food Cost = P 145.00; Selling Price = P 450.00.

Calculation = (145 / 450) x 100 = 32.22%, which rounds to 32.2%.', '["30.5 %","35%","32.2%","36.5 %"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:47:09.679Z"'::jsonb),
('anki-card-1758530779128-52', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following factors is not relevant to labor cost?*', 'Weather', 'Labor cost is directly affected by staff training investments, the use of part-time staff to cover peak hours, and workforce management. Weather is an external environmental factor that can affect daily customer walk-ins, but it is not a structural operational factor directly relevant or tied to labor cost budgeting and scheduling control.

Training: Directly impacts labor hours, payroll costs, and operational efficiency.

Use of part time staff: A labor scheduling strategy to manage payroll costs.

Age of employees: Relates to labor laws, compliance, and work assignments.', '["Training","Use of part time staff","Age of employees","Weather"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:47:15.532Z"'::jsonb),
('anki-card-1758530792059-53', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Who among the following is likely to be a fixed- cost employee?*', 'Supervisor', 'A supervisor receives a fixed salary regardless of hourly volume fluctuations or daily covers served, making them a classic fixed-cost employee.

Dishwasher / Food Server / Utility worker: Typically hourly-wage or part-time staff whose total labor hours and payroll expenses scale directly with guest volume (variable costs).', '["Dishwasher","Food Server","Supervisor","Utility worker"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:47:22.432Z"'::jsonb),
('anki-card-1758530801592-54', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Food cost is an example of what type of cost?*', 'Controllable', 'Food cost is classified as a controllable cost because kitchen management, purchasing officers, and chefs can directly influence and manage it through strict portion control, standardized recipes, waste reduction, careful purchasing, and inventory monitoring.

Non controllable: Refers to fixed overheads like rent, property taxes, and insurance.

Prime: A combined category representing total food, beverage, and labor costs.

Fixed: Costs that do not change with sales volume.', '["Controllable","Non controllable","Prime",". Fixed"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:47:28.284Z"'::jsonb),
('anki-card-1758530814126-55', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'The principle which states that “each employee must know to whom he reports”, refers to*', 'unity of command', 'Unity of command prevents conflicting directives, ambiguity in accountability, and operational confusion by establishing a singular, direct line of authority where a subordinate receives orders from and is accountable to only one immediate superior. In clinical and foodservice management, this structural hierarchy ensures clear communication channels, precise delegation of tasks, and efficient chain-of-command execution during critical operational or patient care workflows.', '["departmentation","delegation of authority","unity of command","delegation of responsibility"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-09-30T02:54:03.484Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-09-29T02:54:03.484Z"'::jsonb, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-09-29T02:54:03.484Z"'::jsonb),
('anki-card-1758530839422-56', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following actions is not relevant to successful delegation?*', 'Make training an option, only if you see that mistakes are being made', 'Successful delegation requires upfront communication, proper training, trust, and clear authority sharing. Making training optional only after mistakes happen is poor management practice; training and clear instructions must be provided proactively before delegating tasks.', '["Make training an option, only if you see that mistakes are being made","Evaluate what responsibilities can be delegated and who is qualified to assume these.","Demonstrate trust in your employees and share the responsibility and authority","Communicate effectively with open lines and clear messages"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:34:26.055Z"'::jsonb),
('anki-card-1758530854172-57', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'In applying the principle of span of control, one needs to consider the following except*', 'the salary of the people involved', 'When applying the principle of span of control (determining how many subordinates a manager can effectively supervise), considerations include the number of people to be supervised, the complexity and amount of supervision required, and the managerial capability of the supervisor. The salary level of the employees has no operational impact on how many staff a supervisor can effectively oversee.

Number of people to be supervised: Directly defines the span of control limit.

Supervision & attention needed to do job: Complex jobs require a narrower span of control (fewer direct reports).

Managerial capability of the supervisor: Experienced managers can handle a wider span of control.', '["number of people to be supervised","supervision & attention needed to do job","the salary of the people involved","managerial capability of the supervisor"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:06:05.075Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:06:05.075Z"'::jsonb, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:48:38.067Z"'::jsonb),
('anki-card-1758530877436-58', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which action is contrary to the principle of homogenous assignment ? *', 'Assign an employee to perform several secondary unrelated jobs.', 'The principle of homogeneous assignment dictates grouping related duties, similar skills, and compatible tasks together so an employee can focus effectively on a specialized role. Assigning an employee to perform several secondary, unrelated jobs violates this principle by causing inefficiency, confusion, and fragmented focus.', '["Group workers who perform similar functions","Limit the variety of jobs assigned to an employee","Assign an employee to perform several secondary unrelated jobs.","Reduce employees’ job inefficiency and confusion"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:31:33.921Z"'::jsonb),
('anki-card-1758530889488-59', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following information is not reflected in the organizational chart?*', 'Specific responsibilities of managers', 'An organizational chart illustrates the macro-structure of a company—showing reporting lines, departmental hierarchy, span of control, and functional relationships. However, it does not detail the specific day-to-day responsibilities of individual managers, which are outlined in job descriptions.', '["Duplication of functions","An overloaded manager","Important functions neglected or overstressed","Specific responsibilities of managers"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:31:42.193Z"'::jsonb),
('anki-card-1758530909003-60', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A manager who waits for situations to arise before taking action is described as ______ manager. *', 'reactive', 'A manager who waits for problems, crises, or operational failures to occur before taking action is characterized as a reactive manager (unlike proactive managers who anticipate and prevent issues beforehand).

Doer: Focuses on physical task execution.

Proactive: Anticipates challenges and plans ahead.

Facilitator: Supports team collaboration and removes workflow blockers.', '["doer","proactive","facilitator","reactive"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:36:28.661Z"'::jsonb),
('anki-card-1758530931935-61', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which statement does not conform with the traditional principles of management?*', 'Employees can receive orders from different bosses.', 'According to Henri Fayol''s classical principles of management (specifically Unity of Command), an employee must receive orders from only one superior. Statement D violates this principle by suggesting employees can report to multiple bosses, which creates confusion and fractured accountability.', '["The interest of the organization is more important than those of any individual/group in the organization.","Decision making authority should rest at the top level of the organization","The same plan should be followed for a group of activities that have the same goal or objective.","Employees can receive orders from different bosses."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:36:35.926Z"'::jsonb),
('anki-card-1758530946033-62', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A leader who uses appropriate supportive & directive behaviors based on the situation is called a ___ leader. *', 'situational', 'A situational leader is one who adapts their supportive and directive behaviors dynamically based on the maturity, readiness, and competence of the followers for each specific task.

Transactional: Focuses on rewards and contractual compliance.

Flexible: A general trait, but "situational leadership" is the formal management term for adapting style to context.

Transformational: Focuses on inspiring a shared vision and driving deep organizational change.', '["transactional","situational","flexible","transformational"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:48:45.627Z"'::jsonb),
('anki-card-1758530963733-63', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'This type of leadership, also called “bartering”, or “leader follower exchange”, uses rewards to extract compliance, and punishment for non compliance.*', 'Transactional', 'Transactional leadership (often referred to as bartering or exchange theory) operates on a "leader-follower exchange" where compliance is enforced through rewards for meeting targets and disciplinary actions or penalties for non-compliance.

Democratic: Involves team participation and shared decision-making.

Transformational: Inspires employees through vision, charisma, and intellectual stimulation rather than transactional bartering.

Autocratic: Centers absolute decision-making power entirely in the leader.', '["Transactional","Democratic","Transformational","Autocratic"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:48:51.404Z"'::jsonb),
('anki-card-1758530974833-64', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'The sequence of steps in strategic management is *', 'analyze, plan, implement, monitor, evaluate', 'The correct logical sequence in strategic management begins with a comprehensive situational audit and SWOT analysis, followed by strategic planning, execution implementation, continuous monitoring of milestones, and final evaluation of outcomes.', '["implement, analyze, plan, monitor, evaluate","analyze, plan, evaluate, implement, monitor","analyze, plan, implement, monitor, evaluate","evaluate, analyze, monitor, plan, implement"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:48:59.281Z"'::jsonb),
('anki-card-1758530994382-65', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which theory says workers are lazy and must be directed and forced to do their work?*', 'Theory X', 'Douglas McGregor’s Theory X management philosophy assumes that average human beings inherently dislike work, are naturally lazy, shirk responsibility, and must therefore be strictly coerced, directed, controlled, and threatened with punishment to put forth adequate effort.

Maslow’s Theory: Focuses on a hierarchy of human motivational needs.

Hawthorne’s Theory: Focuses on social dynamics, attention, and human relations in the workplace.

Theory Y: Assumes workers are self-motivated, seek responsibility, and find work natural.', '["Maslow’s Theory","Hawthorne’s Theory","Theory X","Theory Y"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:49:09.803Z"'::jsonb),
('anki-card-1758531009432-66', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which theory describes workers as committed to their job and want to achieve meaningful results?*', 'Theory Y', 'Douglas McGregor’s Theory Y assumes that employees view work as natural as play, possess self-direction, are committed to organizational objectives, and thrive on responsibility to achieve meaningful results.

Maslow’s Theory: A general needs-satisfaction framework.

Herzberg’s Theory: A two-factor motivation-hygiene theory.

Theory X: Assumes workers are lazy and require strict coercion.', '["Maslow’s Theory","Herzberg’s Theory","Theory X","Theory Y"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:49:20.368Z"'::jsonb),
('anki-card-1758531023895-67', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which management function involves inspiring and motivating staff to willingly get the work done?*', 'Leading', 'Leading (or directing) is the core management function that involves guiding, inspiring, communicating with, and motivating employees to work willingly and productively toward achieving organizational goals.

Planning: Setting goals and mapping out courses of action.

Organizing: Arranging resources, tasks, and structural hierarchies.

Controlling: Monitoring performance against set standards.', '["Planning","Organizing","Leading","Controlling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:49:26.248Z"'::jsonb),
('anki-card-1758531034714-68', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Supervisors must direct the work of their people so that they will do their work...*', 'voluntarily', 'Effective supervisors direct and guide their workforce so that employees execute their duties voluntarily, with internal motivation, professional engagement, and dedication, rather than through fear of punishment.', '["voluntarily","and stay on the job","at their own pace","as directed"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:49:30.466Z"'::jsonb),
('anki-card-1758531046197-69', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Authority derived by virtue of one’s position is called _____ authority.*', 'formal', 'Formal authority is the legitimate power, right, and jurisdiction granted to a position by virtue of an individual''s official hierarchical rank and organizational title.

Informal: Authority earned through peer respect, personal influence, or social rapport.

Line / Staff: Describe departmental roles in the organizational hierarchy rather than the source of structural authority itself.', '["informal","staff","formal","line"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:49:35.174Z"'::jsonb),
('anki-card-1758531059863-70', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Leaders who lead by virtue of the support given by fellow employees are called ______ leaders.*', 'informal', 'Leaders who emerge and lead successfully purely through the respect, trust, and active support of their fellow employees—without holding an official titled management position—are known as informal leaders.', '["transactional","transformational","formal leaders","informal"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:49:40.101Z"'::jsonb),
('anki-card-1758531069179-71', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A detailed outline of routine tasks and side duties for each job position is called*', 'Job description', 'A job description outlines the tasks, duties, responsibilities, and working conditions of a specific position. It acts as a detailed guide of what the employee is expected to do on a daily basis, including their routine tasks and any minor side duties.

	• Job Specification: This focuses on the human qualities needed for the job. It lists the minimum qualifications, skills, education, experience, and physical traits a person must have to perform the tasks. (A simple trick: Descriptions detail the tasks; Specifications detail the person).
	• Job Standards: These define the expected level of performance or measurable targets for the work being done (e.g., "wash 50 pans per hour").
	• Job Classification: This is the system of grouping similar jobs together into classes or grades based on difficulty and responsibility, usually for determining pay scales.', '["Job standards","Job description","Job specification","Job classification"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-30T08:58:50.194Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-29T08:58:50.194Z"'::jsonb, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-10-29T08:58:50.379Z"'::jsonb),
('anki-card-1758531082512-72', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'An employee’s dissatisfaction for unjust company disciplinary action against him is called a....*', 'grievance', 'A formal expression of an employee''s dissatisfaction, protest, or feeling of injustice regarding an unfair company disciplinary action, policy enforcement, or working condition is legally and administratively termed a grievance.

Disciplinary action: The administrative penalty or corrective measure imposed by management.

Corrective action: Steps taken to fix a process or behavior.

Discipline: The system of rules and behavioral compliance enforced within an organization.', '["disciplinary action","corrective action","discipline","grievance"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:31:52.373Z"'::jsonb),
('anki-card-1758531100094-73', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A corrective action by the company to make employees understand and follow company rules.*', 'Discipline', 'Discipline refers to the management system, rules, and corrective measures established by a company to ensure that employees understand, respect, and follow organizational standards and policies.

Corrective action: A broader operational or behavioral fix.

Corrective interview: A one-on-one counseling session between a supervisor and employee.

Grievance: An employee-initiated complaint against management action.', '["Discipline","Corrective action","Corrective interview","Grievance"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:32:00.610Z"'::jsonb),
('anki-card-1758531112492-74', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'An outline of the personal qualification requirements for each position is called*', 'Job specification', 'A job specification is a formal HR document outlining the personal qualifications, educational background, experience, skills, and physical requirements needed by a candidate to successfully perform a specific job.

Job standards: Performance benchmarks or output quotas.

Job description: Outlines duties and responsibilities, not candidate qualifications.

Job classification: Grouping jobs into pay grades.', '["Job standards","Job description","Job specification","Job classification"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:34:36.686Z"'::jsonb),
('anki-card-1758531124176-75', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'The Labor Code of the Philippines is embodied in*', 'PD 442', 'The Labor Code of the Philippines (enacted in 1974) is officially codified and promulgated under Presidential Decree No. 442, governing employment standards, labor relations, and worker welfare.

Presidential Decree No. 440 (PD 440): issued on April 22, 1974 by President Ferdinand E. Marcos, amends Section 105(v) of the Tariff and Customs Code of the Philippines.', '["PD 440","PD 442","PD 540","PD 542"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:35:41.473Z"'::jsonb),
('anki-card-1758531134375-76', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A disagreement among individuals/groups in an organization results in *', 'Conflict', 'A disagreement, clash, or opposition of interests, ideas, or goals among individuals or groups within an organization is defined as conflict.

Harassment: Unwelcome conduct based on protected characteristics.

Discipline / Grievance: Administrative enforcement or formal employee complaints resulting from disputes.', '["Harassment","Conflict","Discipline","Grievance"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:35:54.548Z"'::jsonb),
('anki-card-1758531148757-77', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'As per Labor Code, which situation does not warrant requiring employees to work overtime?*', 'An absent manager or supervisor', 'Under the Philippine Labor Code, compulsory overtime is legally warranted during emergencies, urgent repairs to prevent loss of life or property, urgent operational work, or perishable product salvaging. An absent manager or supervisor is an administrative scheduling failure, not an emergency justifying forced employee overtime.', '["National/local emergency","Urgent office work to be performed","Urgent need to prevent loss of lives or damage to goods","An absent manager or supervisor"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:06:01.484Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:06:01.484Z"'::jsonb, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:49:52.187Z"'::jsonb),
('anki-card-1758531161823-78', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which is not required for a woman to avail of maternity leave?*', 'legally married', 'Under Philippine labor and social security laws (such as the Expanded Maternity Leave Law), a female worker is entitled to maternity leave regardless of her civil status, provided she meets the contribution and notification requirements. Being legally married is not a prerequisite to availing of maternity leave.', '["6 months service for the last 12 months","woman must be in her first four deliveries","legally married","submission of medical certificate."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:50:00.905Z"'::jsonb),
('anki-card-1758531173240-79', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A supervisor who evaluates and compares results with targets and standards previously set, is ...*', 'controlling', 'Controlling is the management function that involves measuring actual performance, evaluating results, and comparing them against pre-established standards and targets to take corrective action if needed.

Planning: Establishing goals upfront.

Organizing: Structuring resources.

Leading: Motivating personnel.', '["planning","organizing","leading","controlling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:50:06.702Z"'::jsonb),
('anki-card-1758531188805-80', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'As per Labor Code, the normal daily hours of work for any employee is*', '8 hours', 'Under Article 83 of the Philippine Labor Code, the normal, regular daily hours of work for any employee shall not exceed 8 hours a day.', '["9 hours","8 hours","10 hours","12 hours"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:50:12.212Z"'::jsonb),
('anki-card-1758531206604-81', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', '“Hours worked” as defined by the Labor Code, refers to *', 'duty hours + short rest periods', 'According to the Labor Code and implementing rules, "hours worked" include all time during which an employee is required to be on duty or at a prescribed workplace, including short rest periods (coffee breaks lasting less than 20 minutes), while standard 1-hour meal breaks are excluded.', '["duty hours + short rest periods","duty hours - short rest periods","duty hours + short rest periods + 1 hr lunch break","duty hours + short rest periods - 1 hr lunch break"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:50:16.584Z"'::jsonb),
('anki-card-1758531220504-82', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'As per Labor Code, our overtime (OT) practice is wrong if we ____________ *', 'offset OT by going under time on another day', 'Under Philippine labor standards, "browbeating" or attempting to offset overtime work by forcing an employee to take undertime on another day is illegal and incorrect. Overtime rendered must be paid in cash with the statutory percentage premium and cannot be arbitrarily offset against future hours within the same pay period to dodge premium pay.', '["give at least 25% of regular wage as OT pay","offset OT by going under time on another day","ask employees to work OT in an emergency","give 40% of pay for OT work rendered"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:50:21.501Z"'::jsonb),
('anki-card-1758531245352-83', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'As per Labor Code, which statement related to holidays is incorrect? *', 'Companies w/ 5 or less employees are exempted from giving regular pay during regular holidays', 'Under the Philippine Labor Code holiday pay rules, retail and service establishments regularly employing fewer than 10 workers (historically 5 or less in older exemptions, but codified as under 10 in modern rules) are exempted from paying regular holiday pay. However, the statement framing "5 or less" as a strict universal exemption across all industries is legally imprecise and tested as the incorrect holiday rule statement in exam keys.', '["Companies w/ 5 or less employees are exempted from giving regular pay during regular holidays","Compensation for employees working on holidays should be twice his regular rate","Employer determines employees’ schedule & weekly rest day","Religion should be considered in determining rest day."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:50:27.845Z"'::jsonb),
('anki-card-1758531262220-84', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'In today’s workplace, the main link/s between the company’s goals and the people who must accomplish these goals are *', 'the supervisors', 'In modern organizational structures, supervisors serve as the vital frontline link connecting top management''s strategic goals directly to the operational workforce responsible for executing them.

The employees: The workforce executing tasks, but supervisors act as the direct communicative link and bridge.

The vendors / customers: External stakeholders, not internal management links.', '["the employees","the vendors","the customers","the supervisors"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:32:11.535Z"'::jsonb),
('anki-card-1758531282452-85', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A supervisor is likely to lose the trust and confidence of his/her employees if*', 'he/she demonstrates any or all of the above listed behaviors', 'A supervisor immediately loses the trust, credibility, and confidence of their team if they exhibit toxic leadership behaviors—such as being inconsistent in words and actions, pursuing selfish personal gains, or withholding information and lying. Therefore, demonstrating any of those behaviors destroys trust.', '["he/she is not consistent with what he says or does","he/she is always after personal gain","he/she withholds in formation and is prone to lying and half truths","he/she demonstrates any or all of the above listed behaviors"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:32:19.769Z"'::jsonb),
('anki-card-1758531313051-86', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Resolving conflicts is likened to the job of a firefighter. The first step in resolving a conflict is to .*', 'contain the problem and prevent it from going out of hand', 'When resolving workplace conflicts (often compared to firefighting), the immediate, critical first step is to contain the problem and prevent it from escalating or spreading across the team before attempting deeper long-term mediation.', '["contain the problem and prevent it from going out of hand","get rid of the problem","look for a win-win solution","let emotions settle down first, before attempting to attack the problem"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:32:31.566Z"'::jsonb),
('anki-card-1758531335184-87', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'The saying: “you can take a horse to the water, but you cannot force it to drink” means ______.*', '“we need to motivate and inspire our employees so that they will develop an inner drive to perform without being pushed”', 'The proverb "you can take a horse to the water, but you cannot force it to drink" is a metaphor for intrinsic motivation in management: you can provide resources and tools, but true performance requires leadership that motivates and inspires employees to develop an inner drive.', '["“our employees must be competent in their job”","“employees must be treated like a work horse, so that they will always follow what we say”","“we need to understand the psychology of our employees”","“we need to motivate and inspire our employees so that they will develop an inner drive to perform without being pushed”"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:36:41.646Z"'::jsonb),
('anki-card-1758531353282-88', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following can make an office memo less effective?*', 'Writing a lengthy memo on varied subjects', 'An office memo loses its effectiveness when it attempts to cover too many unrelated topics in a long, rambling document, which dilutes the main message and confuses readers.', '["Writing a lengthy memo on varied subjects","Indicating the subject of the memo","Indicating the intended receiver and source of the memo","Stating the message clearly and straight to the point"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:32:37.513Z"'::jsonb),
('anki-card-1758531371496-89', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A job analysis is used for the following purposes, except*', 'to determine job satisfaction level of employees.', 'A job analysis systematically examines the tasks, duties, required skills, and working conditions of a specific job. While it aids in recruitment, training, and performance standards, it is not designed to measure employee job satisfaction (which is assessed via attitude surveys and climate questionnaires).', '["to guide in employee recruitment, selection and placement.","to outline employee job opportunities within the company.","to provide information on possible training needs/programs to be conducted.","to determine job satisfaction level of employees."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:32:44.463Z"'::jsonb),
('anki-card-1758531401697-90', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'A supervisor got this advice to promote effective communication in the workplace: “ listen to the whispers and you won ’t have to hear the screams”. What does this statement mean?*', 'Give importance to small issues to prevent them from becoming big issues later on.', 'The advice "listen to the whispers and you won''t have to hear the screams" metaphorically reminds supervisors to pay attention to minor complaints, subtle tensions, and small issues early on, addressing them before they fester and erupt into major organizational crises (screams).', '["Always pay attention to the big issues.","Listen to everything your staff is whispering to you.","Give importance to small issues to prevent them from becoming big issues later on.","Be conscious of what people are saying behind your back."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:32:52.300Z"'::jsonb),
('anki-card-1758531423095-91', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following information is not true about a job description?*', 'It gives information on rules and regulations related to the job', 'A job description details what the job is, its duties, general working conditions, and scope of responsibilities. It does not serve as a rulebook for company policies and disciplinary regulations, which belong in an employee handbook.', '["It contains information on what the job is and the specific duties involved","It shows the responsibilities and general conditions related to the job","It defines the scope of a job, and sets boundaries between positions","It gives information on rules and regulations related to the job"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:36:47.707Z"'::jsonb),
('anki-card-1758531439243-92', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following information is not found in a job description?*', 'Procedure for recruitment, selection and placement', 'A job description outlines the position title, reporting lines, core responsibilities, essential functions, and working conditions. It does not outline internal corporate HR operating manuals such as the step-by-step procedure for recruitment, selection, and placement.', '["The position name/title","Responsibilities or duties entailed in the position","Essential functions of the individual occupying the position","Procedure for recruitment, selection and placement"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:33:03.271Z"'::jsonb),
('anki-card-1758531459559-93', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'What is the sequence of steps involved in employee selection and hiring.*', 'Recruitment, application, testing, interviews, matching, hiring, orientation', 'This sequence represents the standard human resource workflow for onboarding: first attracting candidates (recruitment), collecting paperwork (application), screening capabilities (testing), evaluating fit (interviews), comparing profiles (matching), offering employment (hiring), and welcoming the new staff member (orientation).', '["Recruitment, application, testing, interviews, matching, hiring, orientation","Recruitment, testing, application, matching, interviews, orientation, hiring","Recruitment, interviews, application, selection, hiring, orientation","Recruitment, orientation, interviews, application, hiring"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:33:09.607Z"'::jsonb),
('anki-card-1758531476359-94', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following is not a benefit derived from training employees?*', 'It raises employee’s pay', 'Training improves employees'' skills, knowledge, attitude, quality of work, and career growth, but it does not automatically raise an employee''s pay (which is governed by wage structures, job evaluations, and merit policies rather than training attendance alone).', '["Improves employees’ skills, knowledge & attitude","It raises employee’s pay","It improves quality of work","It improves employee growth & development"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:51:08.278Z"'::jsonb),
('anki-card-1758531486225-95', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'The following situations indicate need for training, except:*', 'pay is low', 'Low pay is an issue of remuneration, wage equity, and economic compensation structures. It cannot be resolved through employee training, making it the correct exception among training needs indicators.

• Need for specific skills: Directly signals a technical or operational training gap.
• Performance is below standard: Indicates a skills or knowledge deficiency that can be corrected through targeted retraining.
• Employee morale is low: Can often be addressed or alleviated through professional development, career growth, and training investments.', '["need for specific skills","performance is below standard","employee morale is low","pay is low"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:53:59.863Z"'::jsonb),
('anki-card-1758531503724-96', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'The Buddy Method is _______ _*', 'an informal type of training where an employee is paired with another', 'The Buddy Method is a practical, on-the-job training approach where a newly hired employee is paired directly with an experienced peer (a "buddy") to observe, ask questions, and learn daily workflows through hands-on practice in a supportive, informal setting.', '["a formal type of employee training used in restaurants","an informal method of training done before an employee is hired","an informal type of training where an employee is paired with another","a seminar type of training where employees are gathered in a session hall"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:53:13.717Z"'::jsonb),
('anki-card-1758531519541-97', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following is not true about on the job training in foodservice operations?*', 'Mostly involves formal classroom instruction', 'On-the-job training (OJT) in foodservice operations is characterized by practical, hands-on execution ("learning by doing") at the actual workstation, supervised by experienced mentors. It does not primarily involve formal classroom instruction (which describes off-the-job or vestibule training).', '["Learning by doing","Needs expert supervision","Also called apprenticeship training","Mostly involves formal classroom instruction"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:33:20.871Z"'::jsonb),
('anki-card-1758531546921-98', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Job shadowing is a commonly used training method in food service operations. What is job shadowing? *', 'when a trainee learns from a more experienced employee by following and observing him as he does', 'Job shadowing is a training method where a newly hired or cross-training employee follows and observes an experienced worker closely through their daily shift to absorb practical workflow routines and task execution.', '["when a more experienced mentor is assigned to coach the trainee","when employees are rotated from one job to another, to learn and familiarize themselves with the different jobs","when a trainee attends regular lecture sessions conducted by experienced employees","when a trainee learns from a more experienced employee by following and observing him as he does"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:33:32.878Z"'::jsonb)
