INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758531571838-99', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'To train effectively, an adult trainor must be guided by the following points, except____*', 'Adults are more knowledgeable than young trainees', 'When training adult learners (andragogy), instructors must be guided by principles of relevance, active participation, and trainee-centered needs. Assuming adults are universally "more knowledgeable than young trainees" is an invalid generalization; adult learning relies instead on valuing their prior experience and practical background.', '["Adults learn by doing & being actively involved","Instruction must be designed based on trainees’ needs","Training content and subject matter must be relevant","Adults are more knowledgeable than young trainees"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.930Z"'::jsonb, '"2026-11-09T02:33:14.709Z"'::jsonb),
('anki-card-1758531594704-100', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'For effective training in the workplace, a supervisor must understand the uniqueness of adult learning. Which statement below is not true about adult learning?*', 'Adult learners are usually more confident compared to younger learners', 'Adult learners often face unique psychological barriers in training environments, such as doubting their ability to learn new technical skills after being out of school and fearing embarrassment or failure. Therefore, claiming that adult learners are universally more confident than younger learners is false.', '["Adults learn more when activities are participative and hands on","Adults learn more when given feedback on how well they are performing","Adults often doubt their ability to learn, and fear embarrassment and failure","Adult learners are usually more confident compared to younger learners"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.092Z"'::jsonb, '"2026-11-09T02:51:15.911Z"'::jsonb),
('anki-card-1758531616785-101', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'Which of the following statements about the difference between training and education is not true. *', 'Training is more general in scope; education is more focused.', 'This statement is false because the reverse is true: training is highly focused and job-specific (teaching exact operational skills for a specific task), whereas education is broader and more general in scope (building conceptual knowledge and critical thinking).', '["Training is intended to improve job skills; education aims to improve knowledge.","Training is short term; education is long term.","Training dwells on how to do something; education teaches concepts and broadens knowledge.","Training is more general in scope; education is more focused."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.092Z"'::jsonb, '"2026-11-09T02:51:23.048Z"'::jsonb),
('anki-card-1758531635851-102', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'For an effective performance appraisal, supervisors must avoid common errors listed below. Which among the following is not an error in performance appraisal?*', 'Appraisal by objective', 'Appraisal by objective (Management by Objectives or MBO) is a formal, structured evaluation technique where managers and employees collaborate to set measurable, specific goals, making it a valid assessment tool rather than a subjective rating error.

• Bias, contrast error and generalization: Common subjective rater errors that distort performance evaluations.
• Leniency: A rating error where supervisors consistently grade all employees overly high or generous to avoid confrontation.
• Halo effect, and fork effect: Cognitive rating errors where an employee''s single outstanding or poor trait unfairly influences the entire performance evaluation.', '["Bias, contrast error and generalization","Leniency","Halo effect, and fork effect","Appraisal by objective"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.092Z"'::jsonb, '"2026-11-09T02:53:38.655Z"'::jsonb),
('anki-card-1758531653451-103', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'The saying: “Deal with the conflict or it will deal with you!” means a conflict that is not resolved will*', 'be tougher to deal with later on, and might undermine you, or your position.', 'The proverb "Deal with the conflict or it will deal with you!" warns that ignoring disputes allows underlying tensions to fester, grow more complex, and eventually erupt into major crises that can undermine a supervisor''s authority and team stability.', '["be tougher to deal with later on, and might undermine you, or your position.","never be resolved at all.","cause employees to leave the company.","just go away and eventually forgotten"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.092Z"'::jsonb, '"2026-11-09T02:53:46.591Z"'::jsonb),
('anki-card-1758531675782-104', NULL, 'anki-deck-1783609212880-1790433142620-mxyd7', 'We are often advised that “change” is constant and we have to always be prepared for organizational change. As a supervisor in an organization, which among the following is the best way to cope with change*', 'Do all of the above', 'To successfully navigate constant workplace changes, supervisors must adopt a proactive multi-pronged approach: maintaining optimism while anticipating shifts, listening to staff ideas while allowing safe room for experimental failure, and actively involving employees in the transition process.

• Be optimistic and anticipate change: A vital mental attitude for resilient leadership.
• Listen to ideas and give allowances for failure: Fosters psychological safety during transitions.
• Involve your staff in the change process: Secures employee buy-in and reduces resistance to change.', '["Be optimistic and anticipate change","Listen to ideas and give allowances for failure","Involve your staff in the change process","Do all of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.092Z"'::jsonb, '"2026-11-09T02:53:53.346Z"'::jsonb),
('anki-card-1758525161661-0', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Main objective of institutional foodservices except*', 'Provide quality food and big serving portions', 'The core objectives of institutional foodservices focus on providing quality service, customer satisfaction, and safe, healthy meals. Providing big serving portions is not a defining operational objective, as institutional foodservice menus are engineered for nutritional adequacy, standardized cost controls, and dietary compliance.

• Provide quality service and customer satisfaction: A primary foundational objective of institutional and commercial foodservices.
• Provide quality safe healthy food: Essential for safeguarding public health in institutional settings.
• Provide quality service and quality food: The standard operational dual goal of foodservice management.', '["Provide quality service and customer satisfaction","Provide quality safe healthy food","Provide quality service and quality food","Provide quality food and big serving portions"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:08.311Z"'::jsonb),
('anki-card-1758525176557-1', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'The following are some essentials considerations to attain the objectives except*', 'Knowledge of clinical principles', 'Institutional foodservices rely on management and operational essentials such as adequate control systems, efficient financial tracking, and effective time utilization. Clinical medical nutrition therapy principles belong to clinical dietetics rather than baseline foodservice management operations.

• Adequate systems of control: Essential for monitoring inventory, waste, and food safety.
• Efficient financial system: Crucial for maintaining budgetary margins and cost accounting.
• Efficient use of time: Necessary for streamlining kitchen production schedules.', '["Adequate systems of control","Efficient financial system","Efficient use of time","Knowledge of clinical principles"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:19.237Z"'::jsonb),
('anki-card-1758525238638-2', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A set of interdependent parts that work together to achieve a common goal*', 'system', 'A system is formally defined as an organized set of interdependent, interacting parts or subsystems working together harmoniously to achieve a common overarching goal or output.

• Subsystem: A smaller, specialized component operating within a broader overarching system.
• Process: A series of actions or steps taken to achieve a particular end result.
• Procedure: A fixed, step-by-step operational instruction for performing a task.', '["subsystem","system","process","procedure"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:24.265Z"'::jsonb),
('anki-card-1758525261538-3', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Management System pertains to*', 'Activities and people who plan, control and make decisions', 'The management system within an organization refers specifically to the core activities and personnel responsible for strategic planning, operational control, and executive decision-making.

• Activities and people who perform their individual functions: Refers to general operational execution rather than overall management governance.
• Collection of people, activities, machines ideas that gather and process data: Defines a management information system (MIS).
• A collection of activities that informs people of their performance rate: Describes performance monitoring metrics.', '["Activities and people who plan, control and make decisions","Activities and people who perform their individual functions","Collection of people, activities, machines ideas that gather and process data to provide formal information needed.","A collection of activities that informs people of their performance rate"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:29.171Z"'::jsonb),
('anki-card-1758525278968-4', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Thruput is the processing of the resources to achieve desired output included are , except*', 'Equipment Maintenance', 'In systems theory, throughput involves processing inputs (labor, raw materials, energy) into desired outputs (meals, services) through administration, assembly, and production. Equipment maintenance is a facility upkeep and support service rather than a core throughput transformation activity.

• Administration: Directs operational oversight and throughput coordination.
• Assembly of materials: A direct throughput step in preparing meals.
• Production: The core transformational processing activity of a foodservice system.', '["Administration","Assembly of materials","Production","Equipment Maintenance"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:33.764Z"'::jsonb),
('anki-card-1758525295503-5', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Element of a system that calls attention to a need for changes or adjustments in the processes of input so that desired goal is achieved*', 'Feedback', 'Feedback is the critical element of a system that provides ongoing information and evaluation on outputs, signaling the need for adjustments or corrective changes in the input and throughput processes to achieve desired goals.

• Assessment / Evaluation: Broad analytical review processes, whereas feedback specifically provides circular loop data to the system.
• Output: The final result or product generated by the system.', '["Assessment","Output","Feedback","Evaluation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:38.845Z"'::jsonb),
('anki-card-1758525308702-6', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'The human and non- human resources are part of the food service system specifically*', 'Input', 'In systems theory applied to foodservice, human resources (staff, labor) and non-human resources (money, equipment, facilities, raw materials) form the fundamental inputs processed by the system.

• Control: The plans, laws, menus, and standards governing the system.
• Output: The final meals, customer satisfaction, and financial reports generated.
• Feedback: Information returned to the system to guide adjustments.', '["Control","Output","Feedback","Input"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:21.820Z"'::jsonb),
('anki-card-1758525321050-7', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A food service system that has central production kitchen*', 'Commissary', 'A commissary food service system (centralized production) prepares large quantities of food in a central kitchen facility, which is then transported and distributed to remote satellite service units for final reheating and distribution.

• Conventional: Food is prepared and served in the same physical location with minimal delay.
• Ready prepared: Food is produced and stored frozen or chilled for future batch service.
• Assembly / served: Kitchens rely heavily on pre-prepared, convenience food items requiring minimal final assembly.', '["Conventional","Commissary","Ready prepared","Assembly /served"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:44.141Z"'::jsonb),
('anki-card-1758525332133-8', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A food service system that has minimal investment in equipment*', 'Assembly/served', 'An assembly/serve (convenience) food service system requires minimal investment in heavy kitchen equipment because meals arrive mostly or fully prepared, requiring only thawing, heating, portioning, and final service.

• Conventional / Commissary / Ready prepared: All require extensive heavy production equipment, cooking ranges, and preparation spaces.', '["Assembly/served","Conventional","Commissary","Ready prepared"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:53.832Z"'::jsonb),
('anki-card-1758525347384-9', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A food service system that stores food either in the chiller or freezer for later use*', 'Ready prepared', 'A ready-prepared (cook/chill or cook/freeze) food service system produces food in advance, after which it is stored in chillers or freezers for later inventory holding, reheating, and service.

• Conventional: Food is prepared close to service time without long-term holding storage.
• Commissary: Centralized production with immediate bulk transport.
• Assembly/served: Relies on commercial convenience foods rather than in-house cook-chill storage.', '["Conventional","Commissary","Ready prepared","Assembly/served"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:54:59.036Z"'::jsonb),
('anki-card-1758525363233-10', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A food service system that has little time between food preparation and service*', 'Conventional', 'In a conventional food service system, ingredients are assembled and cooked with little time elapsing between food preparation and direct customer service.

• Commissary: Involves transport time from a central kitchen to satellite locations.
• Ready prepared: Involves extended holding times via chilling or freezing.
• Assembly/served: Relies on shelf-stable or commercially frozen convenience items.', '["Conventional","Commissary","Ready prepared","Assembly/served"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:04.859Z"'::jsonb),
('anki-card-1758525377598-11', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A food service system where high cost of prepared foods may not be offset by the labor of savings*', 'Assembly/served', 'In an assembly/serve system, the high purchasing cost of specialized, highly processed convenience foods often fails to be offset by labor savings, making food cost ratios uniquely high.

• Conventional: Incurs high labor costs due to scratch-cooking from raw ingredients.
• Commissary: Achieves high labor efficiency through centralized mass production.
• Ready prepared: Smooths labor peaks and valleys through advance batch preparation.', '["Conventional","Commissary","Ready prepared","Assembly/served"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:10.647Z"'::jsonb),
('anki-card-1758525392566-12', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Operating cost of gas, electricity and water are lower than the other three systems*', 'Assembly/served', 'Because assembly/serve kitchens perform little to no heavy cooking from scratch, their utility operating costs for gas, electricity, and heavy water usage are significantly lower than the other three systems.

• Conventional: Requires heavy energy use for daily scratch-cooking ranges and ovens.
• Commissary: Massive central facilities incur high utility loads.
• Ready prepared: Requires intensive energy for blast chilling, freezing, and bulk reheating.', '["Conventional","Commissary","Ready prepared","Assembly/served"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:16.108Z"'::jsonb),
('anki-card-1758525410998-13', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Specialized equipment is needed for transporting food to its outlets*', 'Commissary', 'Because food is produced in a centralized facility and distributed across distant satellite branches, a commissary system requires specialized insulated transport trucks and temperature-controlled equipment to ensure food safety during delivery.

• Conventional / Ready prepared / Assembly/served: Food is generally served on-site or cooked within the immediate facility footprint.', '["Conventional","Commissary","Ready prepared","Assembly/served"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:21.264Z"'::jsonb),
('anki-card-1758525427013-14', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Reduces the “ peaks and valleys” of food production and provides some uniformity in the work load*', 'Ready prepared', 'A ready-prepared system flattens out the "peaks and valleys" of kitchen labor demand by allowing food to be cooked, chilled, and stored ahead of peak service rushes, providing uniformity and flexibility in the daily workload.

• Conventional: Suffers from intense peak labor rushes immediately before meal service.
• Commissary: Shifts production schedules, but is bound by daily transport dispatches.
• Assembly/served: Relies on assembly rather than balanced scratch-production scheduling.', '["Conventional","Commissary","Ready prepared","Assembly/served"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:26.664Z"'::jsonb),
('anki-card-1758525441578-15', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Dry storage should have a temperature', '65-70F', 'Standard institutional guidelines specify that dry storage rooms should be maintained at a cool, climate-controlled temperature range of 65°F to 70°F (approx. 18°C to 21°C) with controlled relative humidity to prevent insect infestation and food spoilage.

• 40-55F: Too cold for general dry storage (refrigeration range is 40°F or lower).
• 75-80F: Too warm; accelerates microbial growth, spoilage, and pest activity.', '["40-55F","55-60F","65-70F","75-80F"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:34.829Z"'::jsonb),
('anki-card-1758525455145-16', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Store foods at the refrigerator*', '40F or lower', 'Perishable foods in refrigerators must be stored safely at temperatures of 40°F (4°C) or lower to inhibit rapid bacterial multiplication and prevent foodborne illness.

• 50F or lower / 60F or lower / 70F or lower: Unsafely warm ranges that fall directly within the "danger zone" for rapid bacterial proliferation.', '["40F or lower","50 F or lower","60F or lower","70F or lower"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:40.397Z"'::jsonb),
('anki-card-1758525468445-17', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Regular Menu planning should consider the market or clientele except*', 'Therapeutic needs', 'Regular menu planning caters to general institutional clientele by considering social needs, paying capacity, and food preferences. Therapeutic medical nutrition therapy needs are addressed through modified or therapeutic menus, making therapeutic needs the correct exception for regular menus.

• Social needs: Important for general acceptance and cultural satisfaction.
• Paying capacity: Determines menu pricing tiers and ingredient budgets.
• Food preferences: Essential for ensuring high customer satisfaction and minimal plate waste.', '["Social needs","Paying capacity","Therapeutic needs","Food preferences"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:47.784Z"'::jsonb),
('anki-card-1758525483726-18', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A meal that consists of soft foods should*', 'have crispy foods to balance meal', 'Menu planning guidelines dictate that meals featuring soft textures should incorporate contrasting textures—such as crispy or crunchy foods—to balance sensory appeal and mouthfeel.

• Have hard foods to balance meal: Too harsh for a soft meal texture profile.
• Have spicy foods to balance the meal: Spiciness addresses flavor profile, not structural texture contrast.
• Have spicy, crispy and hard foods: Hard foods would violate the soft diet requirement.', '["have hard foods to balance meal","have crispy foods to balance meal","have spicy foods to balance the meal","Have spicy, crispy and hard foods"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:55:54.933Z"'::jsonb),
('anki-card-1758525496558-19', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Techniques to eliminate “minimum usage of ingredients” except*', 'Include in regular dishes all the time', 'To eliminate minimum usage of ingredients (which leads to inventory stagnation and spoilage), kitchens should modify recipes, eliminate unpopular dishes entirely, or create new menu items utilizing slow-moving stocks. Forcing ingredients into regular dishes all the time fails to solve inventory imbalances and ruins menu variety.

• Modify recipe: Integrates slow-moving stock into existing successful dishes.
• Eliminate the dish entirely from the menu: Removes dead stock items from purchasing lists.
• Create new dishes: Revitalizes inventory utilization through culinary creativity.', '["Modify recipe","Eliminate the dish entirely from the menu","Create new dishes","Include in regular dishes all the time"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:00.527Z"'::jsonb),
('anki-card-1758525508010-20', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Pricing food items separately so customer can order only what he wants*', 'Ala carte', 'An à la carte menu prices every food item and beverage separately, allowing the customer to select and order only the specific dishes they want.

• Single use: Designed for single-event banquets.
• Du jour: Menu of the day featuring daily specials.
• California menu: Allows ordering any menu item at any time of day.', '["Single use","Ala carte","Du jour","California menu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:31.095Z"'::jsonb),
('anki-card-1758525545123-21', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'For weddings, debuts, conventions, the most applicable*', 'Single use', 'Single-use menus are specifically designed, printed, and utilized for one-time special events, banquets, weddings, debuts, and conventions where the menu is tailored exclusively to the occasion.

• Ala carte: A standard menu offering individually priced items.
• Du jour: A menu of the day designed to utilize specific fresh or slow-moving ingredients.
• California menu: Allows customers to order any item at any time of day.', '["Single use","Ala carte","Du jour","California menu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:05.960Z"'::jsonb),
('anki-card-1758525558174-22', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Convenient way of utilizing items that doesn’t move fast*', 'Du jour', 'A menu du jour (menu of the day) is a convenient operational tool allowing kitchens to feature daily specials and utilize specific food items that need to move fast before inventory spoils.

• Single use: Designed for single-event functions, not daily stock rotation.
• Ala carte: Standard menu structure.
• California menu: All-day flexible ordering format.', '["Single use","Ala carte","Du jour","California menu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:11.111Z"'::jsonb),
('anki-card-1758525571622-23', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Suitability of the product or service for its intended use*', 'Right quality', 'Right quality in procurement is defined as the exact suitability, grade, and standard of a product or service for its intended operational use.

• Right amount: Refers to correct purchasing quantity and par levels.
• Right service: Refers to vendor delivery reliability and support.
• Right source: Refers to reputable, dependable suppliers and distributors.', '["Right amount","Right service","Right quality","Right source"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:16.433Z"'::jsonb),
('anki-card-1758525584488-24', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Shelf life of the product is an essential factor*', 'Buying the right quantity', 'Evaluating inventory holding limits, turnover rates, and the shelf life of a product are essential purchasing considerations when calculating the correct inventory levels and buying the right quantity.

• Buying at the right time: Focuses on market timing and delivery schedules.
• Buying the right quality: Focuses on grade specifications and intended use.
• Buying from the right source: Focuses on vendor evaluation and supplier reliability.', '["Buying at the right time","Buying the right quantity","Buying the right quality","Buying from the right source"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:21.456Z"'::jsonb),
('anki-card-1758525598671-25', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Goods or services received measure up to the specifications*', 'Conformance quality', 'Conformance quality refers to the operational measure confirming that goods or services received physically measure up to exact pre-stated purchase specifications and standards.

• Right quality: A general procurement objective.
• Reliability quality: Refers to long-term product dependability over time.
• Standard quality: Refers to baseline industry benchmarks.', '["Right quality","Reliability quality","Conformance quality","Standard quality"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:27.186Z"'::jsonb),
('anki-card-1758525612022-26', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Milk which does not have any treatment other than cooling and the most vulnerable to spoilage*', 'Raw milk', 'Raw milk has undergone no thermal processing, homogenization, or pasteurization other than chilling, making it the most vulnerable dairy product to microbial contamination and rapid spoilage.

• Fresh milk / Pasteurized milk / Sterilized milk: Have undergone controlled heating processes to destroy pathogens and extend shelf life.', '["Raw milk","Fresh milk","Sterilized milk","Pasteurized milk"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:32.786Z"'::jsonb),
('anki-card-1758525624004-27', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Milk whose fat content is only 2%*', 'Low fat', 'By regulatory standard definitions, low-fat milk has its fat content standardized and reduced to approximately 2% milk fat.

• Skim milk / Non-fat: Contains virtually zero fat (approx. 0% to 0.5%).
• Powdered milk: Dehydrated milk solids, variable in fat depending on whole vs. skim source.', '["Skim milk","Low fat","Non-fat","Powdered milk"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:38.369Z"'::jsonb),
('anki-card-1758525644385-28', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Kesong puti, cottage cheese, cream cheese *', 'Unripened', 'Soft, high-moisture cheeses that are consumed fresh shortly after manufacture—such as kesong puti, cottage cheese, and cream cheese—are classified as unripened cheeses.

• Ripened / Mold ripened / Bacteria ripened: Aged cheeses that undergo long curing, microbial ripening, or mold development (e.g., Cheddar, Brie, Roquefort).', '["Ripened","Unripened","Mold ripened","Bacteria ripened"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:43.888Z"'::jsonb),
('anki-card-1758525655585-29', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Cheese not applicable for topping because it has low moisture content*', 'Edam cheese', 'Edam cheese is a semi-hard cheese with low moisture content and a firm texture, making it unsuitable for easy melting and food-topping applications compared to high-moisture cheeses like Mozzarella.

• Mozzarella: High moisture and fat content, making it the quintessential melting topping cheese.
• Brie / Cream cheese: Soft, high-moisture cheeses that spread and melt easily.', '["Mozzarella","Brie","Edam cheese","Cream cheese"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:49.382Z"'::jsonb),
('anki-card-1758525667984-30', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Meat of a young calf or cattle*', 'Veal', 'Veal is the culinary meat harvested from young calves (cattle under a few months of age), characterized by pale color, tender texture, and delicate flavor.

• Chevon: Goat meat.
• Mutton: Meat from mature adult sheep.
• Steer: A castrated male bovine raised for beef production.', '["Chevon","Mutton","Veal","Steer"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:56:56.458Z"'::jsonb),
('anki-card-1758525702181-31', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Round, rump, and chuck*', 'Less tender cuts', 'Primal cuts containing high amounts of connective tissue and collagen—such as the round, rump, and chuck (muscles subjected to heavy work)—are classified as less tender (or tough) cuts requiring slow, moist-heat cooking.

• Tender cuts: Loin and rib cuts from muscles subjected to minimal work.
• Tough cuts / Toughest cut: General descriptors, whereas "less tender cuts" is the formal culinary and institutional butchery classification.', '["Less tender cuts","Tender cuts","Tough cuts","Toughest cut"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:09.259Z"'::jsonb),
('anki-card-1758525718933-32', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Bivalves or mollusks removed from the shell*', 'Shucked', 'Bivalves and mollusks (such as oysters, clams, and scallops) that have had their edible meat physically removed from their protective hard shells prior to delivery are termed shucked.

• Fresh / Canned / Deshelled: General descriptive terms, whereas shucked is the precise industry market form.', '["Fresh","Shucked","Canned","Deshelled"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:15.402Z"'::jsonb),
('anki-card-1758525730598-33', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Tokwa’t Baboy uses*', 'Jowl', 'In traditional Filipino culinary preparation, Tokwa''t Baboy (fried tofu and pork) specifically utilizes the pork jowl (maskara/face cut) and ears alongside fried tofu due to their rich gelatinous texture and flavor profile.

• Tail / Head / Belly: While pork belly is used in other dishes (like lechon kawali), pork jowl is the traditional cut for classic tokwa''t baboy.', '["Tail","Jowl","Head","Belly"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:20.709Z"'::jsonb),
('anki-card-1758525744616-34', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Tenderizing less tender cuts of meats*', 'Low temperature, long cooking time', 'To tenderize less tender cuts of meat rich in tough connective tissue collagen, moist-heat cookery utilizing low cooking temperatures over a long, sustained cooking time is required to gelatinize collagen without toughening muscle fibers.

• High temperature, Long cooking time: Toughens muscle proteins and dries out meat.
• High temperature, short cooking time: Appropriate only for tender cuts (steaks, chops).
• Low temperature, short cooking time: Leaves connective tissue tough and unsoftened.', '["High temperature, Long cooking time","High temperature, short cooking time","Low temperature, long cooking time","Low temperature, short cooking time"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:26.823Z"'::jsonb),
('anki-card-1758525766146-35', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Dark meat of chicken includes all except*', 'Breast', 'Chicken breast consists of white meat characterized by lower myoglobin content and fast-twitch muscle fibers, whereas thighs, drumsticks, and wings are classified as dark meat due to higher myoglobin and postural activity.

• Thighs / Drumstick / Wings: Classic dark meat chicken portions.', '["Breast","Thighs","Drumstick","Wings"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:32.298Z"'::jsonb),
('anki-card-1758525776996-36', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Kuhol or escargot*', 'Univalve', 'Kuhol (freshwater snails) and marine escargot possess a single, spiral protective shell, classifying them biologically as univalves (gastropods), unlike bivalves which feature two hinged shells.

• Bivalve: Mollusks with two hinged shells (clams, mussels, oysters).
• Mollusk: A broad biological phylum encompassing both univalves and bivalves.
• Shellfish: A general culinary term covering crustaceans and mollusks.', '["Bivalve","Univalve","Mollusk","Shellfish"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:41.772Z"'::jsonb),
('anki-card-1758525786546-37', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Market form of fish for daing*', 'Boneless', 'The traditional Filipino preservation method of making daing (sun-dried or salted fish) typically utilizes butterfly-cut, boneless whole fish halves to facilitate rapid drying and even salt penetration.

• Dressed whole fish: Retains the skeletal bone structure.
• Steaks / Fillets: Thick cuts or side slices, whereas traditional daing split-butterflies the fish.', '["Dressed whole fish","Boneless","Steaks","Fillets"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:46.939Z"'::jsonb),
('anki-card-1758525800894-38', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Characteristics of fresh fish, except*', 'Has a moss like smell “ lumot”', 'Fresh fish should possess a clean, mild, seawater or fresh-smelling aroma. A muddy, moss-like smell ("amoy lumot") or off-odor indicates spoilage, stagnation, or poor water quality, making this the correct exception among fresh fish indicators.

• Bright, clear, full eyes: A primary physiological indicator of true fish freshness.
• Bright colored, glossy scales and adhering to the skin: Indicates fresh, unoxidized dermal layers.
• Gills are reddish pink: Bright red or pink gills indicate good blood oxygenation and freshness.', '["Bright , clear, full eyes","Bright colored, glossy scales and adhering to the skin","Has a moss like smell “ lumot”","Gills are reddish pink"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:53.072Z"'::jsonb),
('anki-card-1758525814962-39', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Washed sugar is cheaper than white sugar and has*', 'Off white or cream color', 'Washed sugar undergoes partial refining where molasses coating is partially washed off, resulting in an off-white or cream-colored appearance, making it less refined and cheaper than pure white sugar.

• Dark brown color / Caramel color: Characteristics of unrefined raw sugars or dark brown sugars.
• Whiter color: Describes highly refined white granulated table sugar.', '["Dark brown color","Caramel color","Whiter color","Off white or cream color"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:57:58.795Z"'::jsonb),
('anki-card-1758525826344-40', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'This type of sugar is attractive and served usually in high end hotels/restos*', 'Lump sugar', 'Lump sugar (sugar cubes or rock sugar) presents an attractive, elegant presentation format traditionally served alongside specialty teas and coffees in high-end hotels and restaurants.

• Brown sugar / Raw sugar / Honey: Standard sweetening formats used across general foodservice applications.', '["Brown sugar","Raw sugar","Honey","Lump sugar"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:04.484Z"'::jsonb),
('anki-card-1758525839176-41', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'This type of sugar has sweetness many times higher than table sugar*', 'Sucralose', 'Sucralose (Splenda) is a high-intensity artificial sweetener manufactured by chlorinating sucrose, possessing a sweetness level approximately 600 times higher than regular table sugar.

• Coco sugar / Brown sugar / Honey: Nutritive caloric sweeteners with sweetness intensity comparable to standard table sugar.', '["Coco sugar","Brown sugar","Sucralose","Honey"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:27.972Z"'::jsonb),
('anki-card-1758525852392-42', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'More finely ground yellow or white corn than corn grits*', 'Corn meal', 'Corn meal consists of coarsely or more finely ground dried yellow or white corn kernels, possessing a coarser texture than fine corn flour or pure corn starch.

• Corn flour: Milled into a fine, smooth powder consistency.
• Corn starch: The pure refined starch fraction extracted from the corn endosperm.
• Cornflakes: Flaked, toasted breakfast cereal.', '["Corn flour","Corn meal","Corn starch","Cornflakes"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:10.251Z"'::jsonb),
('anki-card-1758525864893-43', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'All cereal grains are gluten free except*', 'Rye', 'Among common cereal grains, wheat, rye, and barley naturally contain gluten proteins (prolamins like gliadin and hordein), whereas rice, corn, and quinoa are naturally gluten-free.

• Rice / Corn / Quinoa: Naturally gluten-free grains safe for celiac diets.', '["Rice","Corn","Quinoa","Rye"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:15.842Z"'::jsonb)
