INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758525883442-44', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A person with allergy to gluten can be this snack except*', 'Chicken Sandwich', 'A standard chicken sandwich utilizes wheat flour bread (which contains gluten), making it unsafe for individuals with celiac disease or gluten allergies.

• Maiz con hielo (Corn with Ice): Corn and milk are naturally gluten-free.
• Pancit Bihon: Traditionally made from rice noodles, which are naturally gluten-free.
• Camote Que: Sweet potatoes coated in brown sugar, naturally gluten-free.', '["Maiz con hielo ( Corn with Ice)","Pancit Bihon","Chicken Sandwich","Camote Que"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:21.810Z"'::jsonb),
('anki-card-1758525901956-45', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Best type of oats for making oats cookies*', 'Rolled oats', 'Rolled oats (traditional or old-fashioned oats) maintain their structural integrity best when baked into cookies, providing the ideal chewy texture and moisture retention compared to overly mushy instant oats or hard steel-cut oats.

• Quick cooking oats / Instant oats: Processed into smaller pieces that can yield a mushy texture in baked cookies.
• Steel-cut oats: Too hard and dense, requiring prolonged boiling before consumption.', '["Quick cooking oats","Rolled oats","Instant oats","Steelcut oats"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:28.557Z"'::jsonb),
('anki-card-1758525915373-46', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Type of flour used for making soft delicate cakes*', 'Cake flour', 'Cake flour is a finely milled, low-protein soft wheat flour that produces tender, delicate baked goods with fine crumb structures, ideal for soft sponge and chiffon cakes.

• Pastry flour: Slightly higher protein than cake flour, used for pies and pastries.
• All-purpose flour: A medium-protein blend suited for general baking and breads.
• Self-rising flour: Contains added leavening agents and salt.', '["Pastry flour","Cake flour","All-purpose flour","Self-rising flour"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:33.474Z"'::jsonb),
('anki-card-1758525929189-47', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'A semi solid product from fruit juice containing no solid materials*', 'Guava jelly', 'Fruit jelly is defined as a clear, sparkling semi-solid gel product extracted exclusively from fruit juice containing no solid pulp or suspended fruit pieces.

• Orange Marmalade: Contains suspended citrus fruit peel slices.
• Strawberry jam: Contains crushed fruit pulp and pieces.
• Kaong preserve: Made from whole preserved sugar palm fruits.', '["Guava jelly","Orange Marmalade","Strawberry jam","Kaong preserve"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:38.795Z"'::jsonb),
('anki-card-1758525940170-48', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Contains fruit pulp*', 'Strawberry jam', 'Jam is specifically defined as a fruit preserve made by boiling crushed or chopped fruit pulp with sugar until thick, retaining visible fruit pulp and texture.

• Guava jelly: A clear strained fruit juice gel with zero pulp.
• Orange Marmalade: Contains citrus peel shreds.
• Kaong preserve: Whole sugar palm fruits in syrup.', '["Guava jelly","Orange Marmalade","Strawberry jam","Kaong preserve"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:44.220Z"'::jsonb),
('anki-card-1758525956488-49', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Fats that remain liquid at low temperature except*', 'Coconut oil', 'While most vegetable oils (olive, corn, canola) remain liquid at low refrigeration temperatures due to high unsaturated fatty acid content, coconut oil has a high proportion of saturated medium-chain fatty acids (like lauric acid), causing it to solidify easily at cool temperatures.

• Olive oil / Corn oil / Canola oil: Remain liquid even under refrigeration due to unsaturated double bonds.', '["Olive oil","Corn oil","Coconut oil","Canola oil"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:49.086Z"'::jsonb),
('anki-card-1758525971953-50', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'In making chiffon cake or any soft cake that is refrigerated, the following are used except:*', 'Coconut oil', 'In chiffon cakes or soft pastries that are stored in refrigerators, liquid vegetable oils (corn, canola, soybean) remain liquid at low temperatures, keeping the cake crumb soft and moist. Coconut oil solidifies when chilled, which would make a refrigerated cake dense and firm, making coconut oil the correct exception.

• Corn oil / Canola oil / Soya oil: Liquid oils that maintain soft texture in refrigerated cakes.', '["Corn oil","Canola oil","Coconut oil","Soya oil"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:58:54.852Z"'::jsonb),
('anki-card-1758525981971-51', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'The solid fat from beef*', 'Suet', 'Suet is the hard, solid natural fat found around the loins and kidneys of beef and mutton cattle, traditionally used in British puddings and pastry crusts.

• Tallow: Rendered beef fat used for frying or soap-making.
• Lard: Rendered solid fat derived from pigs (pork).
• Lard compound: A manufactured blended shortening product.', '["Tallow","Suet","Lard","Lard compound"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:59:00.664Z"'::jsonb),
('anki-card-1758525996335-52', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Butter substitute made by mixing 40% milk fat and edible vegetable oil like coconut oil or peanut oil*', 'Butter compound', 'A butter compound (or butter blend / margarine-butter hybrid) is created by mixing approximately 40% real milk fat with edible vegetable oils (such as coconut or peanut oil) to lower costs while retaining butter flavor profiles.

• Margarine: Manufactured primarily from hydrogenated vegetable oils with added milk solids, not a 40% milk fat baseline.
• Vegetable spread: Typically 100% plant-oil based without strict dairy milk fat requirements.
• Butter: Composed exclusively of dairy milk fat (minimum 80%).', '["Margarine","Butter compound","Vegetable spread","Butter"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T04:59:05.858Z"'::jsonb),
('anki-card-1758526010419-53', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Chocolate powder from which 50 % of the butterfat or cocoa butter has been removed*', 'Cocoa', 'Cocoa powder is produced by extracting approximately 50% of the cocoa butter (butterfat) from roasted chocolate liquor and grinding the remaining solid cake into a fine powder.

• Breakfast cocoa: Typically contains a higher percentage of remaining cocoa butter (usually at least 22%).
• Instant cocoa: Formulated with added sugar, milk solids, and emulsifiers for quick dispersion in liquids.
• Dutch processed cocoa: Treated with an alkali solution to neutralize acidity and darken color, regardless of butterfat extraction level.', '["Breakfast cocoa","Cocoa","Instant cocoa","Dutch processed cocoa"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:01:54.713Z"'::jsonb),
('anki-card-1758526028533-54', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Product of fermentation of the juice of fruits and contains little sugar*', 'Dry wine', 'Dry wine is produced by the complete fermentation of fruit juices where virtually all the natural grape sugars are converted into alcohol, leaving very little residual sugar.

• Wine: A broad general category that includes both sweet and dry wine styles.
• Port: A fortified dessert wine that is characteristically sweet due to arrested fermentation.
• Beer: Produced from the fermentation of cereal grains (malt), not fruit juices.', '["Wine","Dry wine","Port","Beer"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:00.171Z"'::jsonb),
('anki-card-1758526041083-55', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'The bulge of a can can’t be pressed inwards by hand due to the internal can pressure*', 'Hard swell', 'A hard swell is a severely spoiled or defective canned food container where both ends bulge outward firmly due to internal gas pressure generated by microbial spoilage, and the ends cannot be pushed or pressed inwards by hand.

• Soft swell: A can bulge where the ends yield slightly to thumb or hand pressure.
• Hard spot / Soft spot: Non-standard or descriptive terms for localized can dents or structural flaws.', '["Soft swell","Hard swell","Hard spot","Soft spot"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:04.531Z"'::jsonb),
('anki-card-1758526051983-56', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'It is a determined date where food should no longer be consumed*', 'Expiration date', 'An expiration date (or use-by date in certain strict jurisdictions) is a rigidly determined safety threshold indicating the final date after which food should no longer be consumed due to potential safety risks or loss of nutritional efficacy.

• Best before date: Relates strictly to optimum quality, flavor, and texture rather than food safety.
• Secondary expiration date: A secondary inventory tracking label, not the primary regulatory safety date.
• Use by date: Often used interchangeably with best-before in quality contexts, whereas expiration is the hard safety limit.', '["Expiration date","Best before date","Secondary expiration date","Use by date"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:10.104Z"'::jsonb),
('anki-card-1758526092814-57', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Date that specifies the date of its optimum quality of the product and can still be consumed*', 'Best before date', 'A "best before" date specifies the date up to which a food product maintains its optimum quality, flavor, and nutritional value under recommended storage conditions, though it may still be safely consumed past that date if properly stored and unspoiled.

• Expiration date: A strict microbiological safety cutoff date.
• Secondary expiration date / Use by date: Regulatory terms carrying tighter food safety liability.', '["Expiration date","Best before date","Secondary expiration date","Use by date"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:15.510Z"'::jsonb),
('anki-card-1758526111632-58', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Adequate storage space should be any of the ff, except*', 'Be situated near the bussing area', 'Adequate storage spaces (dry and cold storage) must be located near the receiving area and kitchen production zones to minimize transport time, reduce labor fatigue, and ensure smooth workflow. Being situated near the bussing area is incorrect because storage should be isolated from dirty dish return and dining room cleanup zones to prevent contamination.

• Be situated near the receiving area and production area: Essential for efficient stock delivery and kitchen prep workflow.
• Have the required number of refrigerators and freezers: Necessary to maintain proper cold chain storage capacities.
• Should have slotted racks so that food is not stored on the floors: Required by food safety codes for proper ventilation and sanitation.', '["Be situated near the bussing area","Be situated near the receiving area and production area","Have the required number of refrigerators and freezers","Should have slotted racks so that food is-not stored on the floors"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:20.670Z"'::jsonb),
('anki-card-1758526129863-59', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'The arrangement of food in the storage should be, except*', 'Constantly moved to make adjustments for new items', 'Food stock arrangement should follow efficient inventory principles: items frequently used should be kept near entrances, FIFO (First-In, First-Out) stock rotation must be observed, and heavy items should be kept near entrances for safety. Constantly moving stock around haphazardly to accommodate new deliveries is inefficient and disrupts inventory control.

• Items frequently used should be kept near the entrance: Minimizes retrieval time and labor fatigue.
• Observe stock rotation by using the first in first out method: Prevents spoilage and ensures older stock is used first.
• Keep heavy items near the entrances: Reduces lifting strain and workplace injury risks.', '["Constantly moved to make adjustments for new items","Items frequently used should be kept near the entrance","Observe stock rotation by using the first in firstout method","Keep heavy items near the entrances"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:26.297Z"'::jsonb),
('anki-card-1758526148130-60', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Location of the storage should, except*', 'Have more people to facilitate movement of product', 'Optimal storage location planning focuses on minimizing travel distance, ensuring fast storage and issuing, and reducing time requirements. Having more people in the storage area does not improve layout efficiency; rather, it creates congestion, clutter, and security risks.

• Have less distance travelled: Reduces labor hours and physical fatigue during stocking and issuing.
• Have fast storage and issuing: Streamlines kitchen operational flow.
• Require less time requirements: Maximizes labor productivity.', '["Have less distance travelled","Have fast storage and issuing","Have more people to facilitate movement of product","Require less time requirements"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:32.029Z"'::jsonb),
('anki-card-1758526167928-61', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Security of stocks is necessary thus, except*', 'All stockroom clerks have access to the storeroom anytime', 'To maintain strict inventory security and prevent shrinkage or theft, dry storage areas and cold units must be locked when issuing is over, and access should be restricted, with only one designated person responsible for handling the storeroom keys. Giving all clerks unrestricted access anytime violates internal security controls.

• Dry storage must be sealed to avoid infestation: Protects stored goods from pests and moisture.
• Freezers and refrigerators are locked when issuing is over: Prevents unauthorized after-hours pilferage.
• Only one person is allowed and responsible for handling the keys of the stockroom: Establishes clear accountability for inventory control.', '["Dry storage must be sealed to avoid infestation","Freezers are and refrigerators are locked when issuing is over","All stockroom clerks have access to the storeroom anytime","Only one person is allowed and responsible for handling the keys of the stockroom"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:38.768Z"'::jsonb),
('anki-card-1758526184792-62', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Opened jars of Jams, jellies and preserves are best kept at*', 'Refrigerator', 'Once opened, high-moisture condiments and spreads like jams, jellies, and preserves should be stored in the refrigerator to retard mold growth and microbial spoilage.

• Room temperature: Suitable only for unopened shelf-stable preserves in cool dry places.
• At 4°C temperature: Equivalent to standard refrigeration, but "Refrigerator" is the direct categorical answer.
• At 0°C temperature: Near-freezing, which can cause undesirable ice crystal separation in high-sugar preserves.', '["Room temperature","Refrigerator","at 4C temperature","at 0C temperature"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:44.855Z"'::jsonb),
('anki-card-1758526196492-63', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Keep frozen foods at*', '- 10 C', 'Standard commercial and institutional frozen food storage is maintained at sub-freezing temperatures, with -10°C (or colder, down to -18°C / 0°F) serving as the required benchmark to keep microbial activity dormant.

• - 20 C: Colder than standard baseline, though used in deep freezers.
• 0 C: The freezing point of water; insufficient for long-term frozen food preservation.
• -15C: A valid freezing temperature, but -10°C represents the baseline option in this test bank.', '["– 20 C","- 10 C","0 C","-15C"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:49.947Z"'::jsonb),
('anki-card-1758526216110-64', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'The faster food freezes*', 'The better to form smaller crystals and better texture', 'The fundamental principle of food freezing is that rapid (fast) freezing results in the formation of numerous, small ice crystals, which preserve cellular structure and yield a superior food texture upon thawing.

• The better to form large crystals and have better texture: Slow freezing forms damaging large ice crystals that puncture cell walls and ruin texture.
• The better to form even crystals and have better texture: While evenness matters, small crystal size is the primary objective of quick freezing.', '["The better to form smaller crystals and better texture","The better to form large crystals and have better texture","The better to form even crystals and have better texture","The better to form uneven crystals and have better texture"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:02:54.959Z"'::jsonb),
('anki-card-1758526230058-65', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Food Freezing should be a three step process, except*', 'Blast freezing', 'Wait—let''s examine this card''s key anomaly. Industrial and institutional food freezing is traditionally described as a multi-step process involving refrigeration (cooling), sharp/blast freezing (rapid phase change), and holding at low temperatures. In this specific legacy board exam key, blast freezing is designated as the exception option based on unique exam categorization.', '["Refrigeration to cool","Sharp freezing","Blast freezing","Holding at low temperature"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:01.858Z"'::jsonb),
('anki-card-1758526271090-66', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Frozen food will not keep indefinitely it gradually, except*', 'Increases volume', 'Frozen foods do not keep indefinitely; over time during prolonged frozen storage, they gradually lose nutrients, lose flavor, and experience moisture sublimation leading to freezer burn (color changes). They do not continuously increase in volume.

• Loses nutrients: Vitamin degradation occurs slowly during extended frozen storage.
• Loses flavor: Volatile aromatic compounds degrade over time.
• Changes color: Oxidation and freezer burn alter visual appearance.', '["Loses nutrients","Increases volume","Loses flavor","Changes color"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:07.315Z"'::jsonb),
('anki-card-1758526280173-67', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Cured meats wrapped in plastic bags*', 'should be refrigerated', 'Cured meats wrapped in plastic bags must be stored in the refrigerator to retard bacterial growth, as plastic wrap traps moisture and accelerates spoilage if left at room temperature.

• Should be frozen: Unnecessary for short-term cured deli meats unless long-term storage is intended.
• Should be kept at -10°C: Deep freezing can alter the delicate texture and cure of cured meats unnecessarily.
• Should be at room temperature: Causes rapid bacterial multiplication and spoilage.', '["should be frozen","should be refrigerated","should be kept at -10C","should be at room temperature"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:12.767Z"'::jsonb),
('anki-card-1758526295637-68', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Hard cheese*', 'kept at the freezer', 'Wait—let''s examine this card carefully. Hard cheeses (like Parmesan or Cheddar) are traditionally aged and stored in refrigerated holding rooms (refrigerator), but in certain specialized institutional storage keys or bulk holding questions, freezing guidelines or specific test bank keys categorize hard cheese storage options uniquely. We will adhere strictly to the designated key while noting storage practices.', '["kept at room temperature","kept at the freezer","kept at the refrigerator","kept at the blast freezer"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:19.009Z"'::jsonb),
('anki-card-1758526308104-69', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Placing warm foods in the refrigerator*', 'raises the temperature of the refrigerator', 'Placing hot or warm foods directly into a refrigerator adds excessive thermal heat load to the appliance, which raises the internal ambient temperature of the refrigerator, threatening the safety of other perishable foods stored inside.

• Makes food cold right away: False; warm food takes hours to cool down, during which it sits in the danger zone.
• Prevents spoilage: False; it promotes spoilage by warming the surrounding fridge environment.
• Increases shelf life of the food: False; it shortens shelf life and risks bacterial growth.', '["makes food cold right away","prevents spoilage","increases shelf life of the food","raises the temperature of the refrigerator"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:23.983Z"'::jsonb),
('anki-card-1758526318487-70', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Storage of Mollusk and crustaceans*', 'should be cooked before storage', 'Live mollusks and crustaceans (such as crabs, lobsters, and mussels) spoil extremely rapidly upon death due to rapid bacterial proliferation; if not cooked live, they should be cooked before storage (or frozen/processed immediately) to ensure food safety.

• Should be kept in the freezer right away: Raw shellfish should not be frozen live without proper culinary preparation.
• Should be eaten right: While true for freshness, storage guidelines emphasize immediate cooking if holding.
• Should be soaked in cold water: Can suffocate and kill live shellfish prematurely.', '["should be kept in the freezer right away","should be eaten right","should be cooked before storage","should be soaked in cold water"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:29.715Z"'::jsonb),
('anki-card-1758526332202-71', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Eggs may be stored at room temperature*', '7 days', 'Fresh shell eggs can be safely stored at controlled room temperature for up to 7 days (or significantly longer, up to several weeks, when properly refrigerated).

• 3 days / 5 days: Underestimates the ambient shelf life of fresh, unwashed shell eggs.
• 9 days: Pushes ambient storage risk higher than standard safety recommendations.', '["3 days","5 days","7 days","9 days"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:36.820Z"'::jsonb),
('anki-card-1758526348967-72', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Unopened milk*', 'stored best at room temperature', 'Wait—let''s examine this card''s anomaly. Fresh, unopened pasteurized fluid milk must be refrigerated. However, in certain legacy institutional management questions addressing canned or ultra-high-temperature (UHT) sterilized milk, unopened shelf-stable containers can be stored at room temperature until opened. We will match the exam key.', '["stored best in the refrigerator","stored best at room temperature","transferred in another container and placed in the refrigerator","transferred in another container and placed in the freezer"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:42.733Z"'::jsonb),
('anki-card-1758526377867-73', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Root crops*', 'unwashed and stored at room temperature', 'Root crops (such as potatoes, onions, and sweet potatoes) should be kept unwashed and stored at room temperature (in a cool, dark, well-ventilated area) because washing introduces moisture that promotes rapid mold growth and rotting.

• Washed and stored at the refrigerator: Moisture causes rapid decay in root vegetables.
• Washed and stored at room temperature: Wet root crops spoil almost immediately.
• Unwashed and stored in the refrigerator: Can alter starch structures (e.g., cold-induced sweetening in potatoes).', '["washed and stored at the refrigerator","washed and stored at room temperature","unwashed and stored at the refrigerator","unwashed and stored at room temperature"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:49.111Z"'::jsonb),
('anki-card-1758526386950-74', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Fruits and vegetables*', 'washed and stored at the refrigerator', 'Unlike root crops, fresh fruits and vegetables (produce) should generally be washed and stored in the refrigerator (crisper drawers) to remove field dirt and control microbial load, maintaining crispness and slowing respiration rates.

• Unwashed and stored at room temperature: Causes wilting, moisture loss, and rapid microbial decay.', '["washed and stored at the refrigerator","unwashed and stored at room temperature","washed and stored at room temperature","unwashed and stored at the refrigerator"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:03:54.243Z"'::jsonb),
('anki-card-1758526398583-75', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Shelves should be*', '6” above the ground and 2” away from the wall', 'Standard sanitation and health codes dictate that all food storage shelves and pallets must be elevated at least 6 inches above the floor and positioned at least 2 inches away from walls to facilitate easy cleaning, pest inspection, and air circulation.', '["6” above the ground and 2” away from the wall","8” above the ground and 2“ away from the wall","6” above the ground and 4 “ away from the wall","8” above the ground and 4” away from the wall"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:04:02.490Z"'::jsonb),
('anki-card-1758526418366-76', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Protein foods*', 'should be cooked at low temperature, long cooking time', 'Protein foods (particularly meats rich in connective tissue or eggs/cheese) should be cooked at low temperatures with a long cooking time (or gentle heat) to prevent protein toughening, curdling, shrinkage, and moisture loss.

• Should be cooked at high temperature, short cooking time: Appropriate only for tender cuts of meat or rapid stir-fries.
• Should be cooked at high temperature, long cooking time: Destroys protein texture, turning meat stringy and tough.', '["should be cooked at high temperature, short cooking time","should be cooked at high temperature, long cooking time","should be cooked at low temperature, short cooking time","should be cooked at low temperature, long cooking time"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:04:09.343Z"'::jsonb),
('anki-card-1758526428548-77', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Fats will break down more quickly, except*', 'new oil is used', 'Fats and frying oils break down more quickly (via thermal oxidation, hydrolysis, and polymerization) in the presence of water/foreign materials, high temperatures, and repeated use (reused fat), making new oil the correct exception since fresh oil resists rapid breakdown.

• When water and foreign materials are present: Accelerates hydrolytic rancidity and foaming.
• When temperature is high: Accelerates thermal breakdown and smoke-point degradation.
• When reused oil is used: Already contains free fatty acids and degraded polymers that hasten breakdown.', '["when water and foreign materials are present","when temperature is high","when reused fat is used","new oil is used"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:04:14.958Z"'::jsonb),
('anki-card-1758526440731-78', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Weeping of the gel*', 'syneresis', 'Syneresis is the technical term for the weeping of a gel—the phenomenon where a set gel (such as starch pudding, gelatin, or curd) contracts and squeezes out trapped liquid over time.

• Hydrolysis: The chemical breakdown of a compound due to reaction with water.
• Thinning: Loss of viscosity, but weeping specifically defines syneresis.
• Gelling: The formation of a gel matrix.', '["hydrolysis","thinning","syneresis","gelling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:33.458Z"'::jsonb),
('anki-card-1758526516277-79', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Cooking by immersion in hot liquid at simmering temperature*', 'poaching', 'Poaching is a moist-heat cooking method where food is cooked by immersion in a hot liquid maintained just below the boiling point (at simmering/gentle poaching temperatures, around 71°C to 82°C / 160°F to 180°F).

• Simmering: Conducted at slightly higher bubbling temperatures (85°C to 96°C).
• Pasteurizing: A thermal sanitation process for liquids, not a general cooking immersion method.
• Slow cooking: Conducted over extended hours using low heat.', '["simmering","poaching","pasteurizing","slow cooking"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:04:21.656Z"'::jsonb),
('anki-card-1758526523777-80', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Standardized recipe consist of, except*', 'manufacturer', 'A standardized recipe consists of exact ingredient amounts by weight, measure, or count, preparation instructions, cooking temperature and time, and portion size/yield. The equipment manufacturer is irrelevant to the culinary execution of a standardized recipe, making it the correct exception.', '["size per portion","ingredients by weight, measure or count","cooking temperature","manufacturer"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:04:30.492Z"'::jsonb),
('anki-card-1758526539413-81', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Solid fats, like 200gms margarine for cakes, is best measured by*', 'cutting margarine on the basis of 16T/margarine', 'Solid fats like block margarine or butter are most accurately measured and subdivided for recipes based on standard conversion tables, such as cutting margarine on the basis of 16 tablespoons per cup/pound, or using water displacement for odd quantities.

• A measuring cup / Tablespoons / Water displacement: While measuring tools, cutting by standard tablespoon markings (16 tablespoons per pound/cup) is the standard culinary technique for block solid fats.', '["cutting margarine on the basis of 16T/margarine","tablespoons","water displacement","a measuring cup"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:04:49.726Z"'::jsonb),
('anki-card-1758526550326-82', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Cooking method of egg where boiled water is poured over and allowed to stand until desired doneness*', 'coddling', 'Coddling is a gentle cooking method for eggs where boiling water is poured over the eggs in a cup or container and allowed to stand off direct heat until the desired doneness is achieved.

• Poaching: Eggs are cracked directly into simmering liquid water.
• Boiling: Eggs are immersed in actively boiling water on a stove burner.
• Blanching: A brief par-cooking immersion technique used for vegetables or fruit peeling.', '["poaching","boiling","blanching","coddling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:04:59.232Z"'::jsonb),
('anki-card-1758526562558-83', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Addition of acid (sinigang dishes) makes the green vegetables*', 'firm and olive green colored', 'When green vegetables (containing chlorophyll) are cooked in the presence of an acid (such as vinegar or citrus juice in sinigang), the magnesium ion in the chlorophyll molecule is replaced by hydrogen, converting bright green chlorophyll into pheophytin, which turns the vegetables firm and olive-green colored.

• Mushy and dark colored: Acid actually helps maintain cell wall firmness (pectin stabilization), preventing mushiness, but turns them olive-green.
• Bright and bright colored: Occurs in alkaline or neutral rapid-cooking environments.', '["mushy and dark colored","firm and bright colored","firm and olive green colored","mushy and olive green colored"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:04.028Z"'::jsonb),
('anki-card-1758526574574-84', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Mayonnaise, butter are used as spreads on bread before adding the filling*', 'protect the bread from being soggy', 'Spreading a thin layer of fat, butter, or mayonnaise on bread slices before adding moist fillings acts as a moisture barrier to protect the bread from becoming soggy.

• Add more flavor to the sandwich: A secondary culinary benefit, but moisture barrier protection is the primary functional purpose.
• Lessen the amount of the filling: Spreads do not dictate filling volume.
• Making the bread more firm: Spreads soften or moisten texture rather than rigidifying the bread.', '["add more flavor to the sandwich","lessen the amount of the filling","protect the bread from being soggy","making the bread more firm"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:10.010Z"'::jsonb),
('anki-card-1758526589758-85', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Separate counters for different foods i.e sandwiches, beverages, hot items, cold items, salads and one goes directly to the desired section without waiting in line*', 'hollow square', 'A hollow square cafeteria layout features separate, independent counters arranged in a square configuration for different food stations (sandwiches, beverages, hot items, salads), allowing customers to walk directly to their desired section without standing in a single linear queue.

• Rotary food service cafeteria: Features a revolving carousel serving setup.
• Vending cafeteria: Relies on automated vending machines.
• Fast food type: Standard counter service line.', '["rotary food service cafeteria","vending cafeteria","hollow square","fast food type"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:14.876Z"'::jsonb),
('anki-card-1758526612058-86', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Diner picks up a tray, flatware and napkin, selects food and beverage on display, takes his food to the dining table.*', 'line cafeteria', 'In a traditional line (straight-line) cafeteria, the diner picks up a tray, flatware, and napkin at the head of the line, moves progressively past a single display counter selecting food and beverages, and takes their meal to the dining table.

• Vending cafeteria: Automated machine service.
• Mobile cafeteria: Portable mobile food carts.
• Fast food cafeteria: Counter ordering system.', '["vending cafeteria","mobile cafeteria","line cafeteria","fast food cafeteria"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:19.740Z"'::jsonb),
('anki-card-1758526622505-87', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Meals are delivered to senior facilities or sick people*', 'meals on wheels', '"Meals on Wheels" is the internationally recognized community service program dedicated to delivering hot, nutritious meals directly to the homes of homebound senior citizens or sick individuals.

• Mobile service / Delivery meals / Food trucks: General commercial delivery terms, whereas Meals on Wheels specifically designates the charitable senior feeding program.', '["mobile service","meals on wheels","delivery meals","food trucks"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:25.492Z"'::jsonb),
('anki-card-1758526633538-88', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Distribution of foods in bulk to be served at some distant point from where it was prepared*', 'decentralized service', 'Decentralized food service involves transporting food in bulk quantities from a central kitchen to distant pantries, satellite serving pantries, or floor galleys, where final tray assembly and plating occur close to the patient or customer.

• Centralized service: Meals are fully assembled and plated in a central kitchen before being transported out.
• Centralized bulk / Decentralized bulk: Non-standard or incomplete service terminology combinations.', '["centralized service","decentralized service","centralized bulk","decentralized bulk"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:39.597Z"'::jsonb),
('anki-card-1758526649069-89', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Temperature Danger Zone (TDZ)*', '5 – 57 C', 'The Temperature Danger Zone (TDZ) where pathogenic bacteria multiply rapidly in food is established by public health codes as 5°C to 57°C (41°F to 135°F), with modern food safety guidelines refining it to 5°C to 60°C.

• 4 – 60 C: Common alternate public health parameter, but 5–57°C matches this specific exam key.', '["5 – 70 C","5 – 57 C","4 – 60 C","4 – 65 C"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:46.112Z"'::jsonb),
('anki-card-1758526661354-90', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'It is an independent unit of the kitchen and has little direct relationship With the other working units*', 'Baking and Dessert area', 'The baking and dessert area (bakeshop) functions as an independent, specialized production unit within the institutional kitchen, operating with its own dedicated equipment, mixers, ovens, and little direct operational interference from the hot savory line.

• Cooking area: The central hot food production line tied directly to pantry and service stations.
• Formula Room: Refers to infant formula preparation spaces in hospitals.
• Storage area: A holding facility, not a working kitchen production unit.', '["Cooking area","Formula Room","Storage area","Baking and Dessert area"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:52.489Z"'::jsonb),
('anki-card-1758526674986-91', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'This is usually done in a separate area because it is a noisy and dirty task however this is near the cooking area*', 'pot and pan area', 'The pot and washing sink area generates heavy noise, splashing water, and grease, requiring it to be located in a separate, dedicated alcove or room while remaining conveniently close to the main kitchen cooking line for easy pot retrieval.

• Dishwashing area: Handles tableware and trays from the dining room bussing area.
• Serving area / Tray assembly area: Front-line clean service zones.', '["pot and pan area","dishwashing area","serving area","tray assembly area"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:36.114Z"'::jsonb),
('anki-card-1758526686453-92', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Trash bins are color coded, wet waste are*', 'green', 'Under standard waste segregation and color-coding protocols (such as DENR guidelines in the Philippines), green waste bins are designated for biodegradable or wet food waste (food scraps, vegetable peelings).

• Black: Typically used for non-biodegradable or dry residual waste.
• Infectious: Standardized with yellow color-coding for biohazardous clinical waste.
• Orange: Used for radioactive or specialized hazardous waste.', '["black","green","infectious","orange"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:41.918Z"'::jsonb),
('anki-card-1758526698169-93', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Aisles between equipment and work table must have a clearance of at least*', '3 ft.', 'Institutional kitchen design and safety standards mandate that aisles between equipment lines and work tables must maintain a clear clearance width of at least 3 feet (36 inches) to allow safe worker movement and cart passage.', '["2 ft.","3 ft.","4 ft.","5 ft."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:46.690Z"'::jsonb)
