INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758526708552-94', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Work heights are*', '36”-38” for standing', 'Standard ergonomic counter and work table heights in commercial kitchens are designed at 36 to 38 inches for standing tasks to prevent worker fatigue and back strain.', '["36”-38” for standing","32”-34” for standing","37”-39“ for standing","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:52.554Z"'::jsonb),
('anki-card-1758526720535-95', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Manufactured in large quantity from a standard pattern*', 'stock equipment', 'Stock equipment refers to standard commercial kitchen appliances and furniture that are mass-produced in large quantities from a standard manufacturer pattern, making them readily available off-the-shelf.

• Made to order / Custom built: Fabricated specifically to unique architectural dimensions and specifications.
• Displayed equipment: Showroom inventory models.', '["stock equipment","made to order","custom built","displayed equipment"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:05:59.191Z"'::jsonb),
('anki-card-1758526733384-96', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Burners used for simmering and boiling purposes*', 'low pressure', 'Low-pressure gas burners are standardly utilized in institutional kitchen ranges for steady, controlled, continuous simmering and boiling purposes.

• High pressure / Very high pressure / Medium pressure: Used primarily for rapid wok cooking, intense searing, and high-BTU industrial Asian range applications.', '["high pressure","low pressure","medium pressure","very high pressure"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:03.938Z"'::jsonb),
('anki-card-1758526741518-97', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Overhead broilers*', 'salamander', 'A salamander is a specialized commercial overhead broiler used in professional kitchens for browning, melting cheese, roasting, and finishing dishes rapidly under intense radiant heat.

• Griddle: A flat, solid heated metal plate used for grilling burgers, pancakes, and eggs.
• Char broiled / Grille: Surface-level grilling equipment with open grates, not overhead heating units.', '["griddle","salamander","char broiled","grille"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:10.968Z"'::jsonb),
('anki-card-1758526756015-98', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Property that is consumed in use orpartially consumed*', 'expendable', 'In property and inventory management terminology, supplies or property items that are entirely consumed through use or partially consumed and lost in operations are classified as expendable (supplies).

• Dispensable: Not a standard property accounting classification term.
• Non-expendable: Refers to durable capital equipment that retains its physical identity and lasts over long periods (furniture, machinery).', '["dispensable","expendable","non expendable","non-dispensable"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:15.858Z"'::jsonb),
('anki-card-1758526769165-99', NULL, 'anki-deck-1783609224970-1790433139855-7alyx', 'Firmly located but not permanently installed*', 'semi fixed equipment', 'Semi-fixed equipment refers to heavy kitchen appliances and fixtures that are firmly positioned and located in place (often connected to utility lines) but are not permanently built into structural walls, allowing them to be moved during deep cleaning or kitchen reconfigurations.

• Fixed equipment: Permanently built-in structural fixtures.
• Movable equipment: Lightweight, portable carts and small appliances.', '["fixed equipment","semi fixed equipment","movable equipment","semi movable equipment"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.152Z"'::jsonb, '"2026-11-09T05:06:58.201Z"'::jsonb),
('anki-card-1758686735492-0', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following statements about yeasts is true? *', 'Yeasts are commonly used in wine-making.', 'Yeasts (specifically strains of Saccharomyces cerevisiae) are vital unicellular fungi universally utilized in baking, brewing, and wine-making because they efficiently convert sugars (glucose and fructose from grapes) into ethanol (alcohol) and carbon dioxide via anaerobic fermentation.

Yeasts are multi-cellular: False; yeasts are predominantly single-celled (unicellular) microorganisms (though some can form chains or pseudohyphae).

Yeasts are anaerobic microorganisms: False; yeasts are facultative anaerobes—they prefer oxygen for efficient aerobic respiration and energy production when available, shifting to fermentation only when oxygen is absent.

Yeasts cannot tolerate acidic conditions: False; yeasts actually thrive and tolerate acidic environments much better than most competing bacteria, which is why winemaking environments are intentionally kept acidic.', '["Yeasts are multi-cellular.","Yeasts are anaerobic microorganisms.","Yeasts cannot tolerate acidic conditions.","Yeasts are commonly used in wine-making."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:28:49.032Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:28:49.032Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:28:49.032Z"'::jsonb),
('anki-card-1758686746992-1', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The following types of microorganisms can grow inside a can of sardines except: *', 'obligate aerobe', 'An obligate aerobe is a microorganism that requires high amounts of free molecular oxygen to survive and metabolize. Inside a hermetically sealed, vacuum-packed, or heat-processed can of sardines, oxygen is entirely absent or exhausted, making it physically impossible for obligate aerobes to survive or multiply.

Aerotolerant: These organisms do not use oxygen for growth, but they can tolerate its presence and survive in sealed environments.

Obligate anaerobe: These microorganisms are poisoned by oxygen and thrive exclusively in oxygen-free environments like sealed cans (posing severe spore-forming risks such as Clostridium botulinum).

Facultative anaerobe: These adaptable organisms can generate energy using oxygen when present but easily switch to anaerobic fermentation or respiration in oxygen-depleted canned environments.', '["aerotolerant","obligate anaerobe","facultative anaerobe","obligate aerobe"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:10:51.861Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:10:51.861Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:10:51.861Z"'::jsonb),
('anki-card-1758686755909-2', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A cultured milk product made from whole, low-fat, or skim milk that undergoes fermentation. It may contain fruit bits to sweeten its tangy flavor: *', 'yogurt', 'Yogurt is a classic fermented dairy product produced by inoculating whole, low-fat, or skim milk with specific bacterial cultures (Lactobacillus bulgaricus and Streptococcus thermophilus). The resulting fermentation produces lactic acid, giving it a characteristic tangy flavor, and fruit preserves or bits are frequently added to sweeten and balance the tartness.

Butter milk: Traditional buttermilk is the thin liquid byproduct left over after churning butter from cultured cream, though modern commercial buttermilk is cultured sweet milk.

Kefir: Kefir is a fermented, effervescent milk drink made using kefir grains containing a complex mixture of yeasts and bacteria, resulting in a thinner, bubbly texture.

Acidophilus milk: This is sweet milk inoculated specifically with Lactobacillus acidophilus bacteria for specialized probiotic health benefits without the heavy fermentation and curdling typical of yogurt.', '["butter milk","kefir","yogurt","Acidophilus milk"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:35:18.742Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:35:18.742Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:35:18.742Z"'::jsonb),
('anki-card-1758686763725-3', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A person with a foodborne infection has most likely eaten a food containing _____. *', 'live bacteria', 'In food microbiology, it is critical to distinguish between a foodborne infection and a foodborne intoxication. A foodborne infection occurs when a person ingests food containing live, pathogenic bacteria (such as Salmonella, Listeria, or Campylobacter). These live microorganisms then colonize, grow, and multiply inside the host''s intestinal tract, which eventually causes illness.

• Histamine: This is a chemical toxin that forms in certain fish (like tuna or mackerel) when they are improperly chilled, leading to scombroid food poisoning (an intoxication/allergic-type reaction).
• Aflatoxin: This is a toxic compound (mycotoxin) produced by certain molds (Aspergillus species) that grow on agricultural crops like peanuts and corn. Illness is caused by ingesting the toxin, making it an intoxication.
• Staphylococcus aureus toxin: Staphylococcus aureus causes illness by producing a heat-stable enterotoxin in the food before it is eaten. You get sick from the pre-formed toxin (an intoxication), not from the bacteria multiplying in your gut.', '["aflatoxin","histamine","live bacteria","Staphylococcus aureus toxin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-09T13:08:59.118Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-08T13:08:59.118Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:08:59.118Z"'::jsonb),
('anki-card-1758686772675-4', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following is mismatched? *', 'yoghurt-ethanol', 'Yogurt fermentation relies on lactic acid bacteria (Lactobacillus bulgaricus and Streptococcus thermophilus) that convert milk lactose into lactic acid, not ethanol. Ethanol is the primary byproduct produced by yeast during alcoholic fermentation (such as in beer and wine production), making this pairing mismatched.

Pickle-lactic acid: Correctly matched; pickling and fermentation of cucumbers rely on lactic acid bacteria producing lactic acid to preserve the product.

Vinegar-acetic acid: Correctly matched; vinegar is produced when acetic acid bacteria (Acetobacter) convert alcohol into acetic acid.

Beer-ethanol: Correctly matched; brewing beer involves yeast fermenting cereal grains to produce ethanol and carbon dioxide.', '["pickle-lactic acid","vinegar-acetic acid","yoghurt-ethanol","beer-ethano"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:39:15.622Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:39:15.622Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:39:15.622Z"'::jsonb),
('anki-card-1758686792905-5', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The phase in the microbial growth curve that is characterized by very rapid cell growth and highest sensitivity to antimicrobial agents: *', 'log phase', 'During the logarithmic (log) phase, microorganisms divide and multiply exponentially at their maximum possible rate. Because their metabolic processes and cellular machinery are operating at peak speed, they are structurally vulnerable, making them most susceptible and sensitive to antibiotics, heat, sanitizers, and antimicrobial agents.

Lag phase: In this initial adaptation phase, microorganisms are metabolically active synthesizing enzymes, but they are adjusting to their new environment and not yet dividing rapidly, making them relatively resistant.

Stationary phase: Growth slows down and plateaus as nutrient depletion and waste accumulation balance out cell division, increasing microbial resistance due to slower metabolic states.

Death phase: Cells run out of nutrients and die off rapidly as toxic waste builds up, representing a non-growing population.', '["log phase","stationary phase","death phase","lag phase"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:29:57.707Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:29:57.707Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:29:57.707Z"'::jsonb),
('anki-card-1758686801622-6', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Food borne illnesses from the consumption of contaminated eggs and poultry products are typically caused by organisms from which genus?', 'Salmonella', 'Foodborne illnesses linked to the consumption of raw, undercooked, or contaminated eggs and poultry are predominantly caused by bacteria belonging to the genus Salmonella (specifically Salmonella enterica serotypes like Enteritidis), which naturally colonize the intestinal tracts and reproductive organs of poultry.

Clostridium: Bacteria like Clostridium perfringens are commonly associated with improperly cooled meat dishes, gravies, and institutional stews, rather than raw eggs.

Staphylococcus: Staphylococcus aureus is typically transmitted to food via poor personal hygiene (skin, cuts, nasal passages of food handlers) rather than raw poultry reservoirs.

Escherichia: While Escherichia coli strains (like EHEC) are major foodborne pathogens, they are primarily associated with undercooked ground beef, unpasteurized milk, and fecal contamination of water or produce.', '["Clostridium","Salmonella","Staphylococcus","Escherichia"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:55:00.614Z"'::jsonb),
('anki-card-1758686810668-7', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'This group of microorganisms is known to produce neurotoxins that cause paralytic shellfish poisoning: *', 'algae', 'Paralytic shellfish poisoning (PSP) is caused by consuming shellfish that have accumulated potent neurotoxins (such as saxitoxin) produced by microscopic marine dinoflagellates, which are a specialized group of single-celled marine algae (often forming harmful algal blooms known as "red tides").

Fungi: Fungi produce mycotoxins (like aflatoxin in peanuts or grains), but they do not cause marine shellfish poisoning.

Virus: Viruses (like Norovirus or Hepatitis A) cause viral gastroenteritis or liver infections when spread via contaminated water or food, not neurotoxic shellfish poisoning.

Amoeba: Amoebas (like Entamoeba histolytica) cause intestinal amoebiasis, transmitted through contaminated water or food handlers.', '["fungi","algae","virus","amoeba"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:38:20.439Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:38:20.439Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:38:20.439Z"'::jsonb),
('anki-card-1758686818039-8', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Refrigerated temperatures work to preserve food by: *', 'slowing down microbial growth', 'Refrigeration (typically maintained between 0°C to 4°C / 32°F to 40°F) preserves perishable food strictly by chilling the environment, which drastically reduces the metabolic and enzymatic rates of bacteria, thereby slowing down microbial growth and extending safe shelf life.

Killing bacteria: False; standard refrigeration temperatures do not kill bacteria; they only put mesophilic pathogens into a state of suspended animation or very slow reproduction.

Preventing growth of pathogens: False; while it slows them down, certain dangerous psychrotrophic pathogens like Listeria monocytogenes can still slowly grow and multiply even at cold refrigerator temperatures.

Reducing available oxygen: False; refrigeration controls temperature, not atmospheric gas composition inside the storage unit.', '["killing bacteria","slowing down microbial growth","preventing growth of pathogens","reducing available oxygen"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:29:09.241Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:29:09.241Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:29:09.241Z"'::jsonb),
('anki-card-1758686827273-9', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The difference between wine and beer is that wine is derived from ______ while beer is derived from ______. *', 'fruit juice; cereals', 'The fundamental raw ingredient difference between wine and beer lies in their sugar source: wine is produced by fermenting the natural sugars found in fruit juice (most commonly grapes), whereas beer is produced by fermenting the starches converted from malted cereals (such as barley, wheat, or corn).

Cereals; rice: Incorrect; while rice is a cereal used to brew beverages like sake, this combination misidentifies fruit juice as a cereal source.

Cereals; fruit juice: This reverses the correct order, incorrectly placing cereals before fruit juice.

Plant sap; fruit juice: Incorrect; plant sap is used for distinct beverages like palm wine or agave spirits, not standard table wine and beer.', '["fruit juice; cereals","cereals; rice","cereals; fruit juice","plant sap; fruit juice"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:55:27.916Z"'::jsonb),
('anki-card-1758686837954-10', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'This fermented product is produced by the action of both yeast and bacteria. *', 'vinegar', 'The production of vinegar is a classic two-step microbial process that requires both yeast and bacteria. First, yeast ferments sugars into alcohol (ethanol). Second, acetic acid bacteria (Acetobacter) take over, consuming that alcohol and oxidizing it into acetic acid (vinegar).

Yogurt: Produced exclusively by bacterial fermentation (lactic acid bacteria), without any yeast involvement.

Cheese: Produced primarily through lactic acid bacterial cultures and enzymatic coagulation (rennet), though molds are used for specialty varieties (like blue cheese), not yeast-plus-bacteria combinations.

Wine: Produced solely through alcoholic fermentation driven by yeast, with bacteria playing no primary role in standard winemaking.', '["yogurt","vinegar","cheese","wine"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:55:33.483Z"'::jsonb),
('anki-card-1758686848519-11', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following is true during slow freezing? *', 'Larger ice crystals are formed.', 'In food science, the rate of freezing profoundly impacts the structural integrity of the food. During slow freezing (like in a standard home freezer), water molecules have enough time to migrate out of the cells and join together, forming large, jagged extracellular ice crystals. These massive crystals physically puncture and crush the food''s delicate cell walls, which destroys the food''s texture. In contrast, rapid or "quick" freezing (like commercial blast freezing) forms millions of microscopic ice crystals that do not damage the cell walls.', '["Larger ice crystals are formed.","There is less drip upon thawing.","There is more enzyme inactivation.","More microorganisms survive."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-09T13:14:01.320Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-08T13:14:01.320Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:14:01.320Z"'::jsonb),
('anki-card-1758686860036-12', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following is not produced using Saccharomyces sp.? *', 'pickles', 'Saccharomyces is a genus of fungi that includes many species of yeast, most notably Saccharomyces cerevisiae (commonly known as baker''s yeast or brewer''s yeast). This yeast is responsible for alcoholic fermentation (converting sugars into ethanol and carbon dioxide) and leavening.

Pickles, on the other hand, are traditionally produced through lactic acid fermentation. This process relies on lactic acid bacteria (LAB)—such as Lactobacillus, Leuconostoc, and Pediococcus species—not yeast. These bacteria convert sugars in the cucumbers into lactic acid, which gives pickles their characteristic sour flavor and preserves them.', '["pickles","bread","wine","champagne"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:33:45.589Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:33:45.589Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:33:45.589Z"'::jsonb),
('anki-card-1758686875887-13', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The ingredient responsible for color fixation of cured meats: *', 'nitrite', 'In meat processing, sodium nitrite (or nitrate, which reduces to nitrite) is the critical active ingredient responsible for the characteristic bright pink/red color of cured meats like bacon, hotdogs, ham, and tocino. The nitrite reacts with the meat''s natural myoglobin pigment to form nitrosylmyoglobin. When exposed to heat during cooking or smoking, this compound stabilizes into nitrosohemochrome, permanently locking in that distinct "cured pink" color and preventing the meat from turning brown or gray.

• Phosphate: This is added to processed meats to increase water-holding capacity, improving juiciness and yield, but it has no effect on color fixation.
• Ascorbic acid: Vitamin C (or sodium erythorbate) is often added to cured meats as an accelerator. It speeds up the chemical reaction of the nitrite, but it is not the actual compound responsible for the color change itself.
• Salt: While standard sodium chloride is the primary preservative and flavor enhancer in cured meats, it does not fix or alter the meat''s pigment.', '["phosphate","nitrite","ascorbic acid","salt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:36:13.463Z"'::jsonb),
('anki-card-1758686883703-14', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The weight of the entire food product including the packaging material is: *', 'gross weight', 'In food packaging, purchasing, and logistics, gross weight refers to the absolute total weight of a product as it sits on the scale. This includes the actual food item plus all associated packaging, containers, boxes, wrappers, and pallets.

• Net weight: This is the weight of the food product only, excluding the weight of any packaging materials (the tare weight). This is the weight printed on retail food labels so consumers know exactly how much actual food they are buying.
• Drained weight: Used for canned goods packed in liquids (like canned tuna in water or fruit cocktail in syrup). It is the weight of the solid food remaining after the liquid packing medium has been completely drained away.
• Edible weight: (Also known as Edible Portion or EP). This refers to the weight of a raw ingredient after all inedible parts (like bones, peels, seeds, and stems) have been trimmed and discarded.', '["net weight","gross weight","drained weight","edible weight"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:36:42.772Z"'::jsonb),
('anki-card-1758686892184-15', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'It is not an example of a difference test: *', 'Preference test', 'In sensory evaluation, a preference test is classified as an affective test (or consumer acceptance test). Its goal is subjective: to determine which product a consumer actually likes better. It does not measure whether the consumer can objectively detect a specific formulation change, only their personal preference.

Here is why the other options are incorrect, as they are all classic examples of objective difference (discrimination) tests, which simply ask "Is there a perceivable difference?" without asking if the panelist likes the product.', '["Triangle test","Duo-trio test","Paired Comparison","Preference test"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:32:59.848Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:32:59.848Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:32:59.848Z"'::jsonb),
('anki-card-1758686902703-16', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Hedonic scale rating is a tool used in: *', 'Affective test', 'In sensory evaluation, the hedonic scale (typically a 9-point scale ranging from "like extremely" to "dislike extremely") is the primary tool used in affective tests (also known as consumer or acceptance tests). Affective tests are subjective evaluations conducted with untrained consumer panels to determine their preference, overall acceptance, or specific degree of liking for a food product.

• Difference test and Discrimination test: These terms refer to the same category of analytical, objective tests (such as the triangle test or duo-trio test). They are used to determine if a statistically significant sensory difference simply exists between two products, regardless of personal preference or whether the panelist actually likes either sample.
• Descriptive test: This is a highly objective, analytical test utilizing trained expert panels to identify and strictly quantify specific sensory characteristics of a food (e.g., grading the exact intensity of bitterness or crunchiness), rather than evaluating personal liking or acceptance.', '["Difference test","Affective test","Descriptive test","Discrimination test"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T13:50:42.124Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-09T13:50:42.124Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T13:50:42.124Z"'::jsonb),
('anki-card-1758686919216-17', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Blanching of “saluyot” and other green vegetables will result in a: *', 'brighter color', 'When green vegetables like saluyot are blanched briefly in boiling water, the heat expels the layer of air trapped between the plant cells. This optical change allows light to penetrate directly to the chlorophyll pigments, making the green color appear exceptionally vibrant and brighter before heat eventually converts chlorophyll into olive-brown pheophytin if overcooked.', '["darker color","lighter color","lower yield","brighter color"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:56:44.593Z"'::jsonb),
('anki-card-1758686927316-18', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Spoilage microorganisms in jams and jellies: *', 'yeasts & molds', 'Jams and jellies present a hostile environment for most bacteria because of their high sugar concentration (low water activity) and high acidity. However, osmophilic yeasts and molds are uniquely adapted to thrive under these exact stress conditions, often growing on the surface where oxygen is present.

Molds: While molds do grow on jams, yeasts are equally common spoilage agents in high-sugar, acidic preserves, making the combined category the accurate and complete answer.

Lactic acid bacteria: These bacteria require high moisture and specific nutrient profiles, making them unable to compete or multiply in high-sugar environments like jams.

Proteolytic bacteria: These bacteria decompose proteins and require neutral pH and high water activity, rendering them inactive in sugary preserves.', '["molds","lactic acid bacteria","yeasts & molds","proteolytic bacteria"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:57:01.735Z"'::jsonb),
('anki-card-1758686936449-19', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The common name for Taenia saginata is: *', 'beef tapeworm', 'Taenia saginata is the scientific name for the beef tapeworm, a large intestinal parasite transmitted to humans through the consumption of raw or undercooked beef containing infectious cysticerci.

Pinworm: This is Enterobius vermicularis, a small roundworm common in children, not a tapeworm.

Whipworm: This is Trichuris trichiura, a parasitic roundworm affecting the large intestine.

Backpacker’s parasite: This refers to Giardia lamblia (or Giardia duodenalis), a flagellated protozoan parasite causing waterborne gastrointestinal illness.', '["pinworm","whipworm","Backpacker’s parasite","beef tapeworm"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:20:35.775Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:20:35.775Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:20:35.775Z"'::jsonb),
('anki-card-1758686945099-20', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A type of parasite relationship which involves a close association between two organisms (host and parasite) where either one cannot exist independently: *', 'symbiosis', 'Symbiosis (specifically obligate mutualistic symbiosis) broadly describes a close, prolonged biological association between two different organisms where their lives are so interdependent that neither can survive or exist independently. (Note: While classic ecology textbooks distinguish mutualism as mutually beneficial, board exam test banks frequently use "symbiosis" to denote this total structural interdependence).

Mutualism: An ecological interaction where both organisms benefit, but it does not strictly imply absolute inability to exist independently in all contexts.

Commensalism: A relationship where one organism benefits while the other is unaffected (neither helped nor harmed).

Parasitism: A relationship where one organism (the parasite) benefits at the expense of the host.', '["mutualism","symbiosis","commensalism","parasitism"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:39:05.494Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:39:05.494Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:39:05.494Z"'::jsonb),
('anki-card-1758686955949-21', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A food preservation method that involves combining salt, sugar, spices, vinegar, or sodium nitrite to animal foods: *', 'curing', 'Curing is a traditional food preservation and processing method applied to animal foods (meats and fish) by combining preservatives and flavoring agents such as salt, sugar, spices, vinegar, or sodium nitrite to inhibit microbial growth, fix color, and extend shelf life.

Drying: Involves removing moisture via heat or air currents, without the heavy addition of curing salts, sugars, and vinegars.

Irradiation: Uses ionizing radiation (gamma rays or electron beams) to destroy microorganisms without chemical additives.

Fermentation: Relies on the metabolic action of beneficial microorganisms (bacteria or yeasts) converting carbohydrates into acids or alcohol.', '["drying","curing","irradiation","fermentation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:19:58.547Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:19:58.547Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:19:58.547Z"'::jsonb),
('anki-card-1758686964665-22', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A preservation method that encourages growth and multiplication of selected microorganisms in foods: *', 'fermentation', 'In food science and preservation, fermentation is unique because it is the only method that intentionally encourages the growth and multiplication of specific, beneficial microorganisms (such as lactic acid bacteria, yeasts, or molds). These selected microbes consume carbohydrates in the food and produce byproducts like acids, alcohols, or gases. These byproducts create a harsh environment (such as low pH or high alcohol content) that prevents pathogenic and spoilage microorganisms from surviving, thereby preserving the food.

• Drying: This method removes the water (lowers water activity) necessary for microbial survival, aiming to strictly inhibit all microbial growth.
• Irradiation: This process exposes food to ionizing energy (like gamma rays) to damage the DNA of microbes, aiming to actively destroy them.
• Curing: This uses a combination of salt, sugar, and nitrites/nitrates to draw moisture out of the food via osmosis, creating an environment that prevents the growth of spoilage and pathogenic bacteria (such as Clostridium botulinum).', '["drying","curing","irradiation","fermentation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-09T12:10:14.053Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-08T12:10:14.053Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T12:10:14.053Z"'::jsonb),
('anki-card-1758686976799-23', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The pectic substance present in the largest amount in just- ripe fruits is: *', 'pectin', 'In fruit ripening chemistry, insoluble protopectin found in green, unripe fruit breaks down into soluble pectin as the fruit reaches the "just-ripe" stage, which is why just-ripe fruits contain the highest amount of extractable pectin for setting jams and jellies. As the fruit becomes overripe, enzymes further degrade pectin into pectic acid, losing its gelling power.

Protopectin: This is the precursor found abundantly in hard, green, unripe fruits, not just-ripe fruits.

Pectic acid: This is the end-product found in overripe, mushy fruits where gelling capability has completely disappeared.

Pectinic acid: An intermediate stage of partial demethylation, but simple pectin is the principal gelling substance concentrated in just-ripe fruit.', '["pectin","protopectin","pectic acid","pectinic acid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:22:17.358Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:22:17.358Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:22:17.358Z"'::jsonb),
('anki-card-1758686985731-24', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The method best suited to use in determining how products differ on specific sensory characteristics:', 'descriptive', 'In sensory evaluation, descriptive testing uses highly trained panels to identify, measure, and quantify specific sensory attributes (such as hardness, sweetness, chewiness, or aroma notes) to determine exactly how products differ from one another in precise detail.

Hedonic: An affective test measuring how much a consumer likes or dislikes a product.

Affective: General consumer acceptance or preference testing.

Discriminative: Used simply to detect whether a noticeable difference exists, not to profile specific characteristics.', '["hedonic","affective","discriminative","descriptive"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:30:27.029Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:30:27.029Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:30:27.029Z"'::jsonb),
('anki-card-1758686994431-25', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The method to use to quickly determine if the sensory characteristics of two products match is: *', 'discriminative', 'Discriminative testing (such as the triangle test or duo-trio test) is specifically designed to quickly and objectively determine whether any perceptible sensory difference exists between two products, without needing to analyze detailed descriptive characteristics.

Affective: Measures consumer preference and emotional liking, which is broader and subjective.

Focus groups: Qualitative marketing discussions, not rapid sensory matching tests.

Descriptive: Involves extensive training and detailed profiling of multiple attributes, which is slow and complex rather than quick.', '["affective","focus groups","descriptive","discriminative"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:25:40.133Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:25:40.133Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:25:40.133Z"'::jsonb),
('anki-card-1758687003648-26', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'At high temperatures, the rate of enzymatic action decreases because the increased heat ____ *', 'alters the active site of the enzyme.', 'Enzymes are specialized protein molecules folded into precise three-dimensional shapes. When exposed to excessively high temperatures, the thermal kinetic energy breaks the delicate hydrogen bonds and hydrophobic interactions holding the protein structure together. This process, known as denaturation, permanently changes or distorts the geometry of the active site, preventing the substrate from binding and halting catalytic activity.', '["changes the pH of the system.","alters the active site of the enzyme.","neutralizes the acids and bases in the system.","increases the concentration of the enzyme."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:08:27.544Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:08:27.544Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:08:27.544Z"'::jsonb),
('anki-card-1758687012662-27', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A certain enzyme will hydrolyze egg white but not starch. Which statement best explains this observation? *', 'Enzyme molecules are specific in their actions.', 'Enzymes possess a highly specific, lock-and-key or induced-fit active site designed to catalyze only specific chemical bonds and substrates. Because egg white consists of proteins (which require proteolytic enzymes like pepsin or trypsin), the enzyme cannot bind to or hydrolyze starch, which is a complex carbohydrate requiring amylase. This demonstrates that enzyme molecules are specific in their actions.', '["Starch molecules are too large to be hydrolyzed.","Enzyme molecules are specific in their actions.","Egg white acts as a coenzyme for hydrolysis.","Starch is composed of amino acids."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:12:30.398Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:12:30.398Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:12:30.398Z"'::jsonb),
('anki-card-1758687022979-28', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Lycopene is an important antioxidant normally present in high levels in ____. *', 'tomatoes', 'Tomatoes (along with watermelon, pink grapefruit, and guava) are exceptionally rich sources of lycopene, a potent carotenoid pigment and antioxidant responsible for their bright red color, which has been strongly linked to reduced risks of chronic diseases like prostate cancer.

Artichokes: Rich in inulin, cynarin, and silymarin, but not a primary dietary source of lycopene.

Bananas: Primarily composed of starches, sugars, potassium, and vitamin B6, containing virtually no lycopene.

Oranges: Dominated by beta-cryptoxanthin, hesperidin, and vitamin C rather than red carotenoids like lycopene.', '["artichokes","bananas","tomatoes","oranges"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:58:39.592Z"'::jsonb),
('anki-card-1758687038829-29', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'It represents the composite assessment of taste and the blend of odor in the mouth. *', 'flavor', 'In sensory evaluation and food science, flavor is defined as the combined, integrated psychological and physiological perception resulting from the simultaneous stimulation of taste receptors on the tongue (taste) and olfactory receptors in the nasal cavity via retro-nasal breathing (odor/aroma).

Taste: Refers strictly to the basic sensations perceived by the taste buds on the tongue (sweet, salty, sour, bitter, umami).

Odor: Refers strictly to volatile aromatic compounds detected by the olfactory system via ortho-nasal (sniffing) pathways.

Texture: Refers to the physical mechanical and geometrical properties of food perceived by touch in the mouth.', '["taste","flavor","odor","texture"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:37:57.098Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:37:57.098Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:37:57.098Z"'::jsonb),
('anki-card-1758687047012-30', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Textural qualities of a food perceived in the mouth. *', 'mouthfeel', 'Mouthfeel encompasses all the tactile, physical sensations perceived by the tongue, palate, and lining of the mouth during the ingestion of food—including viscosity, grittiness, smoothness, astringency, and temperature.

Texture: A broader physical property of the food structure itself, whereas mouthfeel specifically denotes how that texture is physically experienced inside the oral cavity.

Flavor: The combined perception of taste and smell, distinct from physical tactile sensations.

Odor: Olfactory perception sensed through the nose or nasal passages.', '["mouthfeel","texture","flavor","odor"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:35:40.884Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:35:40.884Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:35:40.884Z"'::jsonb),
('anki-card-1758687053994-31', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Taste sensation that enhances the savory qualities of flavor but does not have a distinct taste itself: *', 'umami', 'Umami (savory or meaty taste, triggered by compounds like monosodium glutamate and certain nucleotides) is a fundamental taste sensation that coats the tongue and deeply enhances the savory qualities and overall flavor profile of foods, even though it possesses a mild, subtle baseline taste profile of its own.

Flavor: The overall composite of taste and smell, not a specific single taste enhancer.

Surimi: A processed comminuted fish paste used to make imitation crab meat, completely unrelated to taste sensations.

Mouthfeel: The tactile physical sensation of food in the mouth, not a taste receptor sensation.', '["flavor","umami","surimi","mouthfeel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:58:56.757Z"'::jsonb),
('anki-card-1758687062460-32', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Type/types of heat transfer used when you roast a chicken in an oven: i. radiation; ii. conduction; iii. convection; iv. Induction *', 'i and iii', 'When roasting a chicken in a conventional oven, the primary methods of transferring heat from the oven to the surface of the food are convection and radiation.

iii. Convection: The heating elements warm the air inside the oven. This hot air circulates around the chicken (either naturally as hot air rises, or mechanically via a fan in a convection oven), continuously transferring heat to the food.

i. Radiation: The hot inner walls of the oven and the glowing heating elements emit continuous infrared heat waves, which travel through the space and are directly absorbed by the exposed surface of the chicken, helping to brown the skin.

(Note: While conduction does occur—heat travels from the hot roasting pan to the bottom of the chicken, and from the outside of the meat to the inside—it is not grouped with radiation and convection in your available options. Therefore, identifying the two primary oven-environment heat transfer methods is the correct path).', '["iii only","i and iii","ii, iii, and iv","all of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-12T17:20:48.368Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-09T17:20:48.368Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:20:48.368Z"'::jsonb),
('anki-card-1758687071027-33', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following is the correct arrangement of sugars according to level of sweetness? *', 'fru>glu>mal>lac', 'The relative sweetness scale of common sugars, ranked from highest to lowest sweetness intensity, places fructose (fru) as the sweetest sugar, followed by sucrose and glucose (glu), maltose (mal), and finally lactose (lac), which is the least sweet. Therefore, the correct descending order is fructose > glucose > maltose > lactose.', '["lac>glu>suc>fru","fru>glu>mal>lac","fru","lac>glu>fru>mal"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:59:16.877Z"'::jsonb),
('anki-card-1758687083193-34', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The property of starch exemplified in the staling of bread. *', 'retrogradation', 'Retrogradation is the process where gelatinized starch molecules (specifically the linear amylose chains) gradually associate, recrystallize, and form a tighter, ordered structure as baked bread cools and ages. This expulsion of trapped water and firming of the crumb structure is the primary chemical mechanism responsible for the staling of bread.

• Gelatinization: The initial heat-induced swelling and melting of starch granules in the presence of water, creating a viscous paste.
• Gelation: The formation of a rigid network or gel upon cooling a gelatinized starch paste.
• Syneresis: The weeping or extrusion of liquid from a gel caused by the excessive tightening of the starch network during retrogradation.', '["gelatinization","gelation","retrogradation","syneresis"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:10:16.017Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:10:16.017Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:10:16.017Z"'::jsonb),
('anki-card-1758687091742-35', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The alkaline fraction of baking powder is: *', 'NaHCO₃', 'In food chemistry, baking powder is a complete leavening system containing both an alkaline (basic) component and an acidic component. The alkaline fraction in all commercial baking powders is sodium bicarbonate (NaHCO₃), commonly known as baking soda. When this alkaline compound is hydrated and reacts with the acidic fraction (like cream of tartar or sodium aluminum sulfate) during mixing and baking, it produces the carbon dioxide gas that makes baked goods rise.

• NA₂CO₃ (Sodium carbonate): This is washing soda. While highly alkaline, it is far too caustic and bitter to be used as the standard leavening agent in food.
• NaOH (Sodium hydroxide): This is lye. It is a dangerously strong base used in soap making and drain cleaners (though very weak solutions are used externally to glaze pretzels). It is absolutely never used as an internal leavening agent.
• H₂CO₃ (Carbonic acid): This is an acid, not an alkali. It is the weak acid formed when carbon dioxide dissolves in water (like in carbonated sodas).', '["NA₂CO₃","NaHCO₃","NaOH","H₂CO₃"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T13:35:46.934Z"'::jsonb),
('anki-card-1758687098142-36', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'This baked product is made from a drop batter: *', 'muffin', 'A muffin is prepared using the muffin method for a drop batter (a relatively thick batter with a high flour-to-liquid ratio of about 2:1), which is viscous enough to be dropped easily from a spoon into baking pans without holding a rigid molded shape.

Pancake: Prepared using a much thinner pour batter that flows freely on a griddle.

Cream puff: Prepared using a cooked choux pastry paste containing whole eggs beaten into a hot flour-fat-water mixture.

Yeast bread: Prepared using a stiff, kneaded dough rather than a batter, characterized by a much higher flour ratio.', '["pancake","cream puff","muffin","yeast bread"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:23:20.023Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:23:20.023Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:23:20.023Z"'::jsonb),
('anki-card-1758687104525-37', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'When doing a sink or swim test for testing egg quality, it assesses: *', 'air cell size', 'The classic "sink or swim" (float) test assesses egg freshness by measuring the volume of the internal air cell. As an egg ages, internal moisture evaporates through the porous shell and is replaced by air, causing the air cell at the blunt end to enlarge. A very fresh egg is dense and filled with moisture, causing it to sink flat to the bottom of a bowl of water; an older egg with a large air cell becomes buoyant and floats to the top.

Yolk position: Evaluated by cracking the egg onto a flat plate to check how centered and firm the yolk is, not by floating it in water.

Albumin thickness: Assessed via the Haugh unit or by observing how thick and gel-like the thick albumen stands when cracked open, not via buoyancy.

Shell porosity: While shell pores allow the evaporation that creates the air cell, the float test directly measures the resulting air volume and buoyancy rather than the microscopic pores themselves.', '["yolk position","air cell size","albumin thickness","shell porosity"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T14:00:15.523Z"'::jsonb),
('anki-card-1758687114658-38', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The temperature at which fat starts to decompose is called: *', 'smoke point', 'In food science and culinary arts, the smoke point is the specific temperature at which a fat or oil begins to chemically break down (decompose). At this temperature, the triglycerides break apart into free fatty acids and glycerol. The glycerol is then further degraded into acrolein, a highly irritating chemical compound that produces visible bluish smoke and gives fried foods a bitter, burnt flavor.

• Flash point: This occurs at a significantly higher temperature than the smoke point. It is the temperature at which the oil produces enough volatile vapors that they can momentarily ignite (or "flash") in the air, but the fire will not sustain itself.
• Fire point (and B. combustion point): These refer to the even higher temperature at which the oil vapors will ignite and continue to burn steadily (a sustained grease fire).', '["smoke point","flash point","fire point","combustion point"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-12T17:32:09.161Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-09T17:32:09.161Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:32:09.161Z"'::jsonb),
('anki-card-1758687121557-39', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'All are fermented products except: *', 'preserves', 'Fruit preserves are made by cooking whole or large pieces of fruit with a high concentration of sugar and acid. The preservation mechanism relies entirely on high osmotic pressure (low water activity) and heat processing rather than microbial fermentation, making it the correct exception among fermented items.

Cheese: A classic fermented dairy product produced by inoculating milk with lactic acid bacteria and coagulating it with rennet.

Butter: Traditionally produced by churning cultured cream that has undergone lactic acid bacterial fermentation.

Miso: A traditional Japanese fermented seasoning made by fermenting soybeans with salt and a Koji fungus (Aspergillus oryzae).', '["cheese","butter","miso","preserves"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T14:00:28.894Z"'::jsonb),
('anki-card-1758687131291-40', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The pectic substance form predominantly present in under-ripened fruits: *', 'protopectin', 'In unripe, green fruits, the pectic substances exist almost entirely as water-insoluble protopectin. As the fruit ripens and softens, enzymes break down protopectin into soluble pectin, and eventually into pectic acid in overripe fruit.

Pectininic acid: An intermediate pectin derivative formed during the breakdown of protopectin, but not the predominant form in hard, under-ripened fruit.

Pectic acid: The end-product found in overripe, mushy fruits where all gelling structure has degraded.

Prepectinic acid: A fictitious biochemical term not recognized in carbohydrate or plant science.', '["pectinic acid","pectic acid","protopectin","prepectinic acid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:35:24.568Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:35:24.568Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:35:24.568Z"'::jsonb),
('anki-card-1758687161205-41', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The compound responsible for the characteristic spoiled fish odor: *', 'trimethylamine', 'The characteristic fishy odor of spoiling seafood is caused by trimethylamine (TMA). It is produced when bacterial enzymes and tissue enzymes degrade trimethylamine oxide (TMAO), a natural osmoregulatory compound found in marine fish, as the fish begins to spoil.', '["trimethylamine","trimethlyamide","tetramethylamine","tetramethylamide"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T14:00:44.349Z"'::jsonb),
('anki-card-1758687168421-42', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'If you want to create a flaky yet tender pie, you would use: *', 'cold butter', 'To achieve a flaky pastry crust, cold butter (cut into small pieces and kept chilled) is essential. As the dough bakes, the water inside the cold butter turns to steam, creating pockets of air that separate the flour layers into flaky flakes, while the fat melts to tenderize the surrounding crumb.

Olive oil: Liquid at room temperature and coats flour proteins too thoroughly, resulting in a crumbly, mealy crust rather than distinct flaky layers.

Corn oil: Like olive oil, liquid vegetable oils lack solid fat pockets necessary to create steam-lifted layers in laminated or cut-in doughs.

Butter at room temperature: Soft or melted butter incorporates fully into the flour mixture, leading to a tender but dense, shortbread-like texture without distinct flakiness.', '["olive oil","corn oil","cold butter","butter at room temperature"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:31:59.582Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:31:59.582Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:31:59.582Z"'::jsonb),
('anki-card-1758687176090-43', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'If you want your cake to be more moist, which of the following ingredients will you add? *', 'honey', 'Honey is rich in natural invert sugars (fructose and glucose) which are exceptionally strong humectants. Because these sugars have a powerful affinity for water molecules, adding honey to a cake recipe helps lock in moisture, extending shelf life and keeping the crumb soft and moist.

Flour: Provides structural gluten and starch networks, which actually absorb moisture and can dry out a baked product if used in excess.

Water: While water adds hydration, it evaporates readily during baking unless bound by humectants, making honey a superior functional ingredient for lasting moisture retention.

Salt: Enhances flavor and tightens the gluten structure, but has a dehydrating osmotic effect rather than acting as a primary moistening agent.', '["flour","water","honey","salt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T14:00:56.341Z"'::jsonb)
