INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758687685949-94', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Local term for “all spice” is: *', 'pimiento', 'In Philippine culinary terminology and HE (Home Economics) textbook translations, pimiento (or pimienta) is often used to refer to allspice. This is derived from the plant''s botanical name, Pimenta dioica, and its Spanish name, Pimienta de Jamaica (Jamaican pepper). While colloquially in modern times "pimiento" is frequently associated with red bell peppers (pimientos), in the context of traditional spice translations on the board exam, it stands for allspice.

• Linga: The local term for sesame seeds, commonly used in making palitaw or various Asian sauces.
• Kolantro: The local term for coriander (the seeds). The fresh leaves of this plant are locally referred to as wansoy (cilantro).
• Laurel: The local term for bay leaf, an indispensable aromatic in Filipino adobo.', '["kolantro","linga","pimiento","laurel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T13:51:11.036Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-09T13:51:11.036Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T13:51:11.036Z"'::jsonb),
('anki-card-1758687693965-95', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A fermented soybean cake but is softer than “tokwa”. *', 'tahure', 'In Philippine culinary terminology, tahure refers to fermented soybean curd (often known in English as fermented bean curd). It is sold as small blocks or cakes preserved in brine, occasionally with red yeast rice or chili. The fermentation process breaks down the proteins, resulting in a texture that is significantly softer, creamier, and more pungent than regular firm tokwa. It is commonly used as a flavor enhancer in dishes like pesang isda (fish stew) or mashed into dipping sauces.

• Tofu: This is the general English term for soybean curd. While it comes in soft varieties, standard tofu is unfermented. Tokwa is simply the local term for the firm variety of tofu.
• Miso: While this is a fermented soybean product, it is processed into a thick paste, not formed into cakes or blocks.
• Taho: This is an unfermented, extremely soft, silken soybean curd typically served warm as a sweet snack with brown sugar syrup (arnibal) and sago pearls. It is not fermented and does not hold a cake-like shape.', '["miso","tahure","taho","tofu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-12T17:33:31.707Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-11-09T17:33:31.707Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:33:31.707Z"'::jsonb),
('anki-card-1758687702313-96', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'If cornstarch is used instead of flour, this produces a sauce that is: *', 'thicker', 'Cornstarch possesses a much higher proportion of pure amylose starch compared to wheat flour (which contains proteins and less concentrated starch per cup). Because of this higher concentration of starch granules, substituting cornstarch for flour weight-for-weight or volume-for-volume yields a noticeably thicker glossy sauce or gravy.', '["thicker","thinner","of the same consistency","watery"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:08:37.818Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:08:37.818Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:08:37.818Z"'::jsonb),
('anki-card-1758687709649-97', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'It is used in chopsuey or “linaga”/”nilaga”: *', 'kutsay', 'Kutsay (garlic chives) is a traditional aromatic herb widely used in local Filipino vegetable dishes like chopsuey or boiled broths such as nilaga to impart a mild, garlic-onion aroma and green garnish.

Katuray: Edible white flowers used in Ilocano pinakbet or salads.

Kinchay: Chinese celery, used for soups and pancit.

Tanglad: Lemon grass, used for grilled or stewed aromatic meats (like tinola or adobo variations).', '["katuray","kinchay","kutsay","tanglad"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:27:35.366Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:27:35.366Z"'::jsonb, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-09T17:27:35.366Z"'::jsonb),
('anki-card-1758687718346-98', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Homogenized milk refers to milk with reduced: *', 'fat particle size', 'Homogenization is a mechanical high-pressure process that forces milk through microscopic nozzles, shattering and reducing the fat particle size (globules) uniformly so they remain permanently suspended in the liquid rather than separating and rising as cream.

Bacterial count: Addressed by pasteurization, not mechanical homogenization.

Total fat content: Homogenization redistributes fat globules but does not change the total chemical fat percentage of the milk.

Protein content: Protein structures remain stable during physical fat droplet breakdown.', '["bacterial count","fat particle size","total fat content","protein content"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T14:26:46.617Z"'::jsonb),
('anki-card-1758687729580-99', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'If cocoa is substituted for chocolate in a chocolate cake recipe, you should:', 'increase the fat', 'Note: This is a classic trick question from local board exam pools. While substituting cocoa powder for solid chocolate usually requires adjusting liquids or fats because cocoa is far more absorbent, the official exam key designates increase the fat to compensate for the missing cocoa butter previously supplied by whole chocolate liquor.', '["increase the sugar","increase the fat","increase the flour","increase the leavening agent"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.929Z"'::jsonb, '"2026-11-08T14:26:56.722Z"'::jsonb),
('anki-card-1758687738096-100', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', '101. A cake recipe has the following ingredients: ½ cup butter; 1 cup milk; 3 cups cake flour; 3 teaspoons baking powder; 1 ½ cups granulated sugar. Butter is not available so that margarine will be used. How much margarine is needed? *', '½ c', 'Margarine can be substituted for butter on a direct 1:1 volume-for-volume ratio in standard baking recipes because both fats contain equivalent proportions of fat emulsions and moisture. Since the original recipe calls for 1/2 cup of butter, exactly 1/2 cup of margarine is needed.', '["1 ½ c","¼ c","1 c","½ c"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:22:21.505Z"'::jsonb),
('anki-card-1758687747562-101', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Left-over meat from Arroz ala Cubana may be restyled to: *', 'omelet', 'Leftover cooked minced or ground meat from Arroz ala Cubana (seasoned ground beef with peas, raisins, and carrots) is easily repurposed and restyled into a savory omelet or tortilla by folding the seasoned meat filling into beaten eggs.

Arroz Valenciana: A complex Spanish-Filipino one-pot rice dish traditionally made with raw or freshly cooked chicken and chorizo, not a direct restyling vehicle for leftover seasoned ground beef.

Hamburger: Requires specific ground meat fat-to-lean ratios and bun pairings, making an egg omelet a more immediate and flexible restyling option for cooked minced meat leftovers.

Fritada: A stewed meat dish prepared from raw cuts simmered with potatoes and tomato sauce, not leftover ground meat.', '["Arroz Valenciana","omelet","hamburger","fritada"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:26:27.362Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:26:27.362Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:26:27.362Z"'::jsonb),
('anki-card-1758687757130-102', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The best location of storing milk, meats, fish, and poultry in a cooling unit is: *', 'at the bottom of the shelves', 'In food safety and sanitation, raw meats, poultry, and fish must always be stored on the bottom shelves of a cooling unit (refrigerator). This is a critical rule designed to prevent cross-contamination; it ensures that blood and raw juices—which may contain dangerous pathogens—cannot drip down onto ready-to-eat foods, produce, or cooked items. Additionally, because heat rises, the bottom shelves are typically the coldest and most temperature-stable area of the refrigerator, making it the ideal environment for highly perishable items like milk and raw proteins.', '["at the back of the door","at the top of the shelves","at the bottom of the shelves","at the middle of the shelves"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T13:50:32.501Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-09T13:50:32.501Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T13:50:32.501Z"'::jsonb),
('anki-card-1758687764995-103', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Two ways recommended in sanitizing foodservice utensils: 1. washing with soap and water; 2. immersion in hot water; 3. by chemical treatment; 4. washing with detergent and water *', '2 & 3', 'Under standard sanitation codes for food establishments, the two approved and recommended sanitizing methods for cleaned foodservice utensils and equipment after washing are immersion in hot water (thermal sanitizing) or chemical treatment (using sanitizing solutions like chlorine, quaternary ammonium, or iodine).

1 & 4: Washing with soap/detergent and water represents the cleaning stage, not the final sanitizing stage.', '["1 & 4","1 & 2","2 & 4","2 & 3"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:34:09.517Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:34:09.517Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:34:09.517Z"'::jsonb),
('anki-card-1758687783444-104', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A type of foodservice system with the advantage of lowering operating costs and wastage: *', 'assembly serve', 'An assembly-serve foodservice system (often called the "kitchen-less kitchen") utilizes fully prepared, convenience, or frozen food items that require only thawing, portioning, heating, and assembling, which drastically lowers operational labor costs, specialized equipment needs, and food wastage.

Ready prepared: Prepares food on-site ahead of time and blast-chills or freezes it in bulk, requiring specialized rethermalization equipment.

Commissary: A centralized mass-production kitchen that distributes food to satellite units, involving large-scale capital investments.

Conventional: Prepares food from scratch on-site daily, carrying higher labor overhead and potential waste if forecasting is inaccurate.', '["ready prepared","commissary","conventional","assembly serve"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:25:39.085Z"'::jsonb),
('anki-card-1758687790927-105', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A standardized recipe for Chicken Pork Adobo has a yield of 25 servings. You need 75 servings in your catering. What will be your adjustment factor? *', '3', 'To calculate the recipe adjustment factor (multiplier), divide the desired yield by the original recipe yield: 75 servings / 25 servings = 3. Every ingredient in the original recipe must be multiplied by 3 to scale it correctly for the catering order.', '["5","3","2","4"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:32:53.313Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:32:53.313Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:32:53.313Z"'::jsonb),
('anki-card-1758687800827-106', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'An ISO 9000 certification of a company means that the company: *', 'complies with minimum standards of quality management', 'An ISO 9000 certification indicates that an organization has implemented and maintains a rigorous quality management system that strictly complies with internationally recognized minimum standards and quality assurance protocols.', '["is a member of the International Standards Organization","complies with minimum standards of quality management","the company is viable","the company is competitive"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:26:14.403Z"'::jsonb),
('anki-card-1758687807942-107', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The Philippine Code on Sanitation: *', 'PD 856', 'Presidential Decree No. 856, promulgated in 1975, is officially known as the Code on Sanitation of the Philippines, establishing comprehensive sanitary standards for food establishments, water supply, waste disposal, and public health.

PD 1286: Not the sanitation code decree.

PD 491: The Nutrition Act of the Philippines, which created the National Nutrition Council (NNC).

PD 568: Relates to other administrative or agricultural decrees.', '["PD 1286","PD 856","PD 491","PD 568"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:10:28.303Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:10:28.303Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:10:28.303Z"'::jsonb),
('anki-card-1758687819391-108', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'An establishment with a par stock of 10 cartons of milk needs to order how many cartons after an inventory showed that 4 cartons are left? *', '6', 'The formula for calculating the required order quantity using par stock is: Order Quantity = Par Stock − Quantity on Hand.

Par Stock = 10 cartons

Quantity on Hand = 4 cartons

Order Quantity = 10 − 4 = 6 cartons.', '["5","6","7","8"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:55:50.435Z"'::jsonb),
('anki-card-1758687829109-109', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The recommended clearance of shelves off the floor in storage rooms is: *', '6”', 'In institutional sanitation and food storage guidelines, all food, ingredients, and storage shelves must be elevated a minimum of 6 inches (15 cm) off the floor to allow proper air circulation, facilitate easy cleaning beneath shelves, and prevent pest infestation or moisture damage.', '["4”","6”","10”","12”"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:30:57.405Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:30:57.405Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:30:57.405Z"'::jsonb),
('anki-card-1758687837291-110', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Based on the Sanitation Code, what is the recommended storage temperature for dairy products? *', '50°C– 70°C', 'In foodservice management and sanitation codes (like ServSafe), the numerical range 50 to 70 is the universal standard for Dry Storage temperatures (50°F to 70°F / 10°C to 21°C). This applies to dry goods, including powdered dairy products, unopened canned milk, and unopened UHT tetra-pak milk.

Here is why the question as written is technically incorrect, but why A is the forced answer:

1. The Unit Error: The options are written in Celsius (°C). Storing any food at 50°C to 70°C (122°F to 158°F) is actually hot holding and would severely spoil, curdle, and ruin dairy products. The author intended Fahrenheit (°F).

2. The Category Error: It is highly likely the original question meant to ask for the storage temperature of dry products, not dairy products.

3. The True Dairy Standard: According to the Sanitation Code, fresh, perishable liquid dairy products must be stored under strict cold refrigeration at 41°F (5°C) or below.', '["50°C– 70°C","80°C – 100°C","100°C – 120°C","130°C – 140°C"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-12T17:13:48.970Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-09T17:13:48.970Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:13:48.970Z"'::jsonb),
('anki-card-1758687851008-111', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'If the delivered supplies are incomplete, the receiving personnel must accomplish what type of form to be submitted to the accounting department? *', 'Credit memo form', 'In foodservice purchasing and accounting, a credit memo (credit memorandum) is the vital financial document issued when a delivery is short-shipped, incomplete, or contains damaged/rejected goods. The receiving clerk uses this form to notify the accounting department that the restaurant should not pay the full original invoice amount, but instead apply a financial credit for the missing items.

• Receiving form: This is merely a log used by the receiving clerk to record what actually arrived at the loading dock. It is not a financial adjustment document.
• Requisition form: This is an internal document used by kitchen staff to request ingredients from the restaurant''s own dry storeroom or walk-in cooler.
• Discrepancy report form: While this might be used internally by management to track vendor performance, the credit memo is the specific, formal document required by accounting to adjust the accounts payable.', '["Receiving form","Credit memo form","Requisition form","Discrepancy report form"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:28:30.843Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:28:30.843Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:28:30.843Z"'::jsonb),
('anki-card-1758687859290-112', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The type of inventory performed when the peso value is computed after a specific period of time: *', 'physical inventory', 'physical inventoryA physical inventory is the literal, manual counting of every single item sitting on the shelves in the storeroom and refrigerators at the end of a specific accounting period (e.g., end of the month). Once the physical count is finished, the quantities are multiplied by their unit purchase price to determine the total peso value of the inventory on hand, which is required to calculate the true Cost of Goods Sold.

• Perpetual inventory: This is a continuous, running paper or digital record of what should be in the storeroom based on daily deliveries and requisitions. It tracks theoretical quantities in real-time, not the actual physical count evaluated at period-end.
• Daily inventory: While high-value items (like expensive meats or liquor) might be counted daily for security, a full peso-value inventory of the entire facility is done periodically, not daily.
• Financial inventory: This is a general business term, but "physical inventory" is the exact standard operational terminology used in foodservice management.', '["perpetual inventory","daily inventory","physical inventory","financial inventory"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:39:43.449Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:39:43.449Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:39:43.449Z"'::jsonb),
('anki-card-1758687868140-113', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'To adjust a standardized recipe to 150 servings using the factor method, the amount of ingredients of a recipe that yields 10 servings must be multiplied by which value? *', '15', 'In foodservice quantity recipe conversion using the factor method, the conversion factor is calculated by dividing the desired yield by the original recipe yield. Therefore, 150 desired servings divided by 10 original servings gives a multiplication factor of 15. Every ingredient in the original recipe must be multiplied by 15.', '["10","15","20","25"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:47:39.918Z"'::jsonb),
('anki-card-1758687887857-114', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Take out counters are classified under which service type? *', 'on-premise portable service', 'Take-out counters and food pickup windows operate within the physical boundaries of the main food facility (on-premise), but the food is packaged and handed over to customers to be carried away or consumed elsewhere, categorizing it under portable service formats.

Off-premise portable service: This refers to catered events, mobile food trucks, or home delivery services where food preparation and consumption occur completely away from the base kitchen facility.

Decentralized service: This describes institutional food systems where bulk food is transported from a central kitchen to distant pantries or ward kitchens for final assembly and service.

Centralized service: This is a system where plates and meals are completely assembled and portioned directly in the main kitchen before being dispatched to the consumer.', '["off-premise portable service","on-premise portable service","decentralized service","centralized service"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:21:49.604Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:21:49.604Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:21:49.604Z"'::jsonb),
('anki-card-1758687901654-115', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'These pests feed not only on foodstuffs but also on non-food items like soap: *', 'German cockroach', 'The German cockroach is notorious for its omnivorous, highly adaptable scavenging habits. In addition to contaminating human food stocks, they readily consume non-food organic household items such as soap, glue, book bindings, leather, and toothpaste.

American cockroach: While large and destructive, they typically prefer damp, decaying organic matter, basements, and sewers rather than household non-food items like soap.

Oriental cockroach: Commonly known as waterbugs, these pests favor extremely damp, cool environments like floor drains and damp basements, feeding primarily on starchy garbage.

Asian cockroach: This species closely resembles the German cockroach in appearance, but it is an outdoor flyer attracted to bright lights and plant material rather than indoor household soaps and non-food goods.', '["American cockroach","Oriental cockroach","German cockroach","Asian cockroach"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:48:04.523Z"'::jsonb),
('anki-card-1758687910138-116', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Gnawed cartons in the storage room indicate the presence of which pest? *', 'rodents', 'Rodents (such as mice and rats) possess continually growing incisor teeth, forcing them to constantly gnaw and chew on hard surfaces—including cardboard packaging, paper bags, and wooden crates—to keep their teeth worn down and to access stored food.

Cockroaches: Cockroaches damage food packaging through rasping mouthparts that leave microscopic scrape marks or thin holes, but they do not produce large, aggressive gnawed carton edges.

House fly: House flies feed exclusively on liquid or semi-liquid organic matter through sponging mouthparts and are physically incapable of gnawing through solid paper cartons.

Fruit fly: Fruit flies feed on fermenting organic debris and overripe fruit, leaving packaging completely intact.', '["cockroaches","rodents","house fly","fruit fly"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:48:12.146Z"'::jsonb),
('anki-card-1758687917404-117', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A “reactive” type of manager: *', 'responds to problems as they arise', 'In organizational behavior and management principles, a reactive manager operates in a "firefighting" mode. They wait for situations, crises, or problems to occur and then react to them as they arise, rather than anticipating them in advance.', '["knows his/her personnel very well","responds to problems as they arise","plans for unforeseen problems","reacts positively to problems"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-12T17:14:09.679Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-09T17:14:09.679Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:14:09.679Z"'::jsonb),
('anki-card-1758687927052-118', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'NSF and UL indicate that an imported equipment complied with certain quality standards. “Kawa” is an example of NSF-certified equipment. *', 'Both sentences are correct.', 'NSF (National Sanitation Foundation) and UL (Underwriters Laboratories) are internationally recognized certification bodies that evaluate and ensure imported and local foodservice equipment complies with rigorous public health, safety, and sanitation standards. Furthermore, in the context of specialized local culinary equipment standards, a "kawa" (a large, heavy-duty wok-like traditional Filipino vessel used for mass cooking) can be manufactured to meet these certified sanitary stainless steel fabrication standards for commercial kitchens.', '["First statement is correct.","Second statement is correct.","Both sentences are correct.","Both sentences are incorrect."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:31:46.876Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:31:46.876Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:31:46.876Z"'::jsonb),
('anki-card-1758687936588-119', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following is an example of a local piece of equipment? *', 'Chinese pressure cooker', 'In the context of Philippine foodservice operations and institutional equipment classification, a "local piece of equipment" generally refers to heavy-duty, commonly utilized cooking vessels that are often manufactured or adapted locally for Asian/Filipino cooking methods (like large-scale boiling and tenderizing meats for broths and stews). The Chinese pressure cooker fits this description as it is a staple in many local commercial kitchens for quickly tenderizing tough cuts of meat (like beef shank for bulalo or pork hocks).

• Split vat fryer: This is highly specialized commercial deep-frying equipment, typically imported and associated with Western-style fast-food chains (for frying fries and chicken separately without flavor transfer).
• Salamander: A specialized, high-heat broiler used in professional (often Western/European style) kitchens to quickly brown the tops of dishes, melt cheese, or toast ingredients. It is not considered a local piece of equipment.
• Rotary oven: A massive, complex, and usually imported piece of commercial baking equipment featuring rotating racks to ensure even baking for high-volume bread production.', '["Split vat fryer","Salamander","Rotary oven","Chinese pressure cooker"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:24:19.632Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:24:19.632Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:24:19.632Z"'::jsonb),
('anki-card-1758687943153-120', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'What is the recommended distance of septic tanks from drinking water supply? *', '50 m', 'The primary purpose of establishing a minimum distance between a septic tank (or leaching field) and a drinking water supply (such as a well) is to prevent cross-contamination. While the baseline national Sanitation Code of the Philippines (PD 856) sets a minimum of 25 meters, many stringent local ordinances, environmental guidelines, and board exam references recommend a more conservative buffer of 50 meters. This wider distance accounts for highly porous soil, sloping topography, and heavy rains, ensuring that harmful pathogens, coliform bacteria, and untreated effluent have absolutely no chance of seeping into the groundwater aquifer.', '["50 m","100 m","60 m","55 m"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:31:22.181Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:31:22.181Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:31:22.181Z"'::jsonb),
('anki-card-1758687954820-121', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following does not contribute to food cost variance? *', 'price increase with increased price of ingredients', 'In foodservice accounting, food cost variance is the gap between your actual food cost (what you actually spent/used) and your theoretical standard food cost (what you should have spent based on the recipes sold). Variance is caused by operational errors, waste, or theft.

If the market price of ingredients goes up, and management properly documents this by adjusting the standard recipe costs and raising the menu prices to match ("price increase with increased price of ingredients"), this is a controlled economic adjustment. It does not cause a variance because the system''s theoretical cost is updated to reflect the new reality.', '["unaccounted complimentary item","price increase with increased price of ingredients","non-compliance to standards","unaccomplished requisition forms"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:27:06.873Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:27:06.873Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:27:06.873Z"'::jsonb),
('anki-card-1758687962968-122', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'What does high profitability mean? *', 'Food items with low raw food cost.', 'In menu engineering, an item''s profitability is determined by its contribution margin (Selling Price minus Raw Food Cost). The contribution margin is the actual cash amount that goes toward paying off overhead and generating pure profit. To achieve a high contribution margin (high profitability), the item must have a low raw food cost relative to its selling price (like pasta or beverage items).

• Food items with high food cost: High food costs eat directly into the gross margin, resulting in low profitability (menu "Dogs").
• High-priced items: A high menu price does not guarantee high profitability if the ingredients to make it are also extremely expensive (e.g., imported steak or lobster). The margin might still be slim.
• Low-priced items: While these might sell at a high volume, the actual cash profit generated per plate is usually very small.', '["Food items with low raw food cost.","Food items with high food cost.","High-priced items.","Low-priced items."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:34:59.971Z"'::jsonb),
('anki-card-1758687969686-123', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Each element in the foodservice system needs to work independently to meet its own objective. The elements are interrelated to meet the overall objective of the system. *', 'Both sentences are correct.', 'In systems theory applied to foodservice management, an organization functions as a dynamic system composed of interdependent parts. Each subsystem or element must maintain its own operational focus and efficiency (working independently to meet its internal objectives, such as a kitchen handling production or accounting managing finance), while remaining tightly interconnected and synchronized to achieve the overarching mission of the entire organization.', '["First statement is correct.","Both sentences are correct.","Second statement is correct.","Both sentences are incorrect."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:49:53.637Z"'::jsonb),
('anki-card-1758687977086-124', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Souffle is a fluffy dish with a hard meringue. The equipment used to harden the meringue is: *', 'salamander', 'A salamander is a specialized commercial kitchen broiler characterized by intense overhead infrared heating elements. It is widely used in professional kitchens for browning the tops of dishes, melting cheese, toasting, and rapidly crisping or hardening a meringue topping on items like baked alaska or savory soufflés.

Rotisserie: This equipment uses a rotating spit to roast meats evenly via surrounding heat, not suitable for top-down surface browning of a delicate soufflé.

Ovenette: This is a small, portable tabletop baking appliance used for basic baking, lacking the direct high-intensity overhead broiling power needed to quickly crisp meringue.

Microwave: This appliance uses dielectric heating (microwaves) to excite water molecules internally, which would instantly deflate, rubberize, or destroy a delicate meringue rather than hardening its surface.', '["salamander","rotisserie","ovenette","microwave"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:50:04.310Z"'::jsonb),
('anki-card-1758687985103-125', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following foodservice system is usually compared to a food factory? *', 'commissary', 'A commissary foodservice system (centralized production kitchen) is frequently compared to a food factory because large quantities of food are mass-produced, processed, packaged, and stored in a central facility before being shipped out to separate, remote satellite service units for final reheating and distribution.

• Conventional: In this system, food is prepared, cooked, and served from the same location with minimal holding time, resembling traditional home-style cooking on a larger scale rather than a factory.
• Assembly serve: This system relies heavily on convenience foods and fully prepared commercial items that require only thawing, portioning, and heating, acting more like an assembly line than a primary manufacturing food factory.
• Ready-prepared system: Food is produced on-site, blast-chilled or frozen, and stored in bulk for future reheating, focusing on inventory flexibility rather than factory-style centralized mass distribution.', '["conventional","assembly serve","commissary","ready-prepared system"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:13:37.723Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:13:37.723Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:13:37.723Z"'::jsonb),
('anki-card-1758688001818-126', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The most ideal water temperature in manual dishwashing: *', '100°F – 120°F', 'For manual dishwashing in a three-compartment sink, the wash water must be maintained at a minimum temperature of 100°F to 120°F (38°C to 49°C). This temperature range is hot enough to effectively melt and dissolve grease and food residues while remaining comfortable and safe for the dishwashing staff''s hands.

120°F – 130°F: While acceptable in some specific commercial wash cycles, water kept consistently at or above this upper threshold can cause discomfort or minor burns during prolonged manual scrubbing without heavy-duty protection.

90°F – 100°F: This temperature range is too cool; fats and greases will congeal rather than dissolve, making manual cleaning inefficient.

80°F – 90°F: This is far too cold for effective manual dishwashing and creates an ideal lukewarm breeding environment for microbial growth in the sink basin.', '["100°F – 120°F","120°F – 130°F","90°F – 100°F","80°F – 90°F"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:26:43.112Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:26:43.112Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:26:43.112Z"'::jsonb),
('anki-card-1758688009968-127', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A cleaning agent that is ideal for glasswares: *', 'detergents', 'Detergents contain surface-active agents (surfactants) that lower the surface tension of water, allowing it to penetrate and lift soils without scratching delicate surfaces. They are the ideal, safe cleaning agents for smooth, non-porous items like glassware and fine china.

Abrasive cleaners: These contain gritty chemical or mineral particles designed to scour away baked-on or stubborn soils, which will permanently scratch, etch, and ruin glass surfaces.

Alkaline cleaners: These are heavy-duty degreasers formulated to strip baked-on grease from stainless steel ovens and fryers; their high pH can cloud or damage glassware over time.

Acid cleaners: These are specialized descalers used to remove mineral buildup, lime deposits, or rust (delime equipment), and are too harsh for routine glassware washing.', '["abrasive cleaners","alkaline cleaners","acid cleaners","detergents"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:37:46.717Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:37:46.717Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:37:46.717Z"'::jsonb),
('anki-card-1758688017883-128', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The ideal solution for chemical sanitizing: *', '50 ppm chlorine', 'According to standard foodservice sanitation guidelines (including ServSafe), the ideal and minimum effective concentration for a chlorine-based chemical sanitizer used on food-contact surfaces is 50 parts per million (ppm).

At 50 ppm (mixed with water between 75°F to 100°F), the chlorine solution effectively destroys pathogenic vegetative bacteria with just 7 seconds of contact time.', '["20 ppm chlorine","30 ppm chlorine","40 ppm chlorine","50 ppm chlorine"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:27:52.115Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:27:52.115Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:27:52.115Z"'::jsonb),
('anki-card-1758688036517-129', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'This type of cockroach is described as being both omnivorous and scavenger. *', 'German cockroach', 'The German cockroach is scientifically and behaviorally characterized as both an aggressive omnivore and a scavenger. They feed on an exceptionally wide variety of human foods, waste, and household organic materials, making them the most common and resilient indoor pest in foodservice facilities.

Oriental cockroach: Often called waterbugs, these pests prefer damp, cool, dark environments like floor drains and basements, focusing primarily on starchy garbage rather than general scavenging.

American cockroach: This is the largest common indoor cockroach species, favoring warm, moist areas like commercial plumbing tunnels and sewers rather than general food-prep scavenging.

Asian cockroach: This species is primarily an outdoor flyer that resembles the German cockroach but avoids indoor environments, being strongly attracted to outdoor lights and vegetation.', '["Oriental cockroach","American cockroach","German cockroach","Asian cockroach"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:50:40.996Z"'::jsonb),
('anki-card-1758688056448-130', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A component of Emotional Quotient that describes the ability of the employee to identify his/her strengths: *', 'Self-awareness', 'In emotional intelligence (EQ) theory, self-awareness is the foundational core competency that describes an individual''s ability to accurately recognize and understand their own emotions, personal triggers, internal states, and inherent strengths and limitations.

Empathy: This EQ component involves the ability to understand, recognize, and sensitively relate to the emotional needs, perspectives, and feelings of other people.

Self-regulation: This refers to the ability to control or redirect disruptive impulses, manage one''s moods, and adapt successfully to changing circumstances.

Social skills: These are interpersonal competencies focused on managing relationships, building effective networks, communicating clearly, and leading teams collaboratively.', '["Empathy","Self-awareness","Self- regulation","Social skills"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:50:48.515Z"'::jsonb),
('anki-card-1758688136461-131', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The recommended finishing of stainless steel for equipment in foodservice establishments is: *', '#4', 'In commercial foodservice equipment fabrication, a #4 finish (a brushed, polished, satin finish with fine parallel polish lines) is the industry gold standard for stainless steel surfaces. It provides an optimal balance of durability, ease of cleaning, corrosion resistance, and a professional aesthetic that hides minor scratches and fingerprints.

#3: This finish is a coarser, rougher polished surface with visible abrasion lines that trap food particles more easily than a #4 finish, making it less ideal for food-contact zones.

#8: This is an ultra-smooth, mirror-like reflective finish. While visually striking, it scratches easily, shows every fingerprint and smudge, and is impractical for heavy-duty commercial kitchen prep counters.

#14: This is not a standard commercial stainless steel mill finish designation used in foodservice equipment manufacturing.', '["#3","#8","#14","#4"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T13:50:55.608Z"'::jsonb),
('anki-card-1758688147494-132', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'According to the Sanitation Code of the Philippines, how many water closet facilities should be provided for disabled persons if the dining area accommodates 150 people? *', '1', 'Under the National Building Code of the Philippines (BP 344 / Accessibility Law) and sanitary code plumbing provisions for public establishments, buildings or dining spaces accommodating up to 150 patrons must provide at least one accessible water closet facility specifically designed, equipped, and designated for persons with disabilities (PWD).

2: Requiring two PWD water closets is mandated for much larger capacities or multi-floor facilities, exceeding the baseline requirement for a 150-capacity dining area.

3: Three accessible water closet stalls are reserved for high-capacity public assembly venues or very large commercial complexes.

None: Providing no PWD facilities is a direct violation of accessibility laws and sanitary codes governing commercial food and dining establishments.', '["1","2","3","none"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:36:31.063Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:36:31.063Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:36:31.063Z"'::jsonb),
('anki-card-1758688159360-133', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'If the total area for a foodservice establishment is 280 sqm, what is the estimated space allocated for the dining area? *', '168 sqm', 'In standard foodservice facility layout and design principles, the dining room is typically allocated approximately 60% (or 0.60) of the total establishment area to ensure optimal customer comfort and operational flow. Multiplying the total area by this standard ratio (280 sqm x 0.60) yields exactly 168 sqm for the dining space.', '["160 sqm","165 sqm","168 sqm","170 sqm"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:24:03.497Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:24:03.497Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:24:03.497Z"'::jsonb),
('anki-card-1758688167893-134', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The type of fire extinguisher that must be used for electrical-based fire: *', 'C', 'Fire extinguishers are categorized by the class of fire they are designed to suppress. Class C fire extinguishers are specifically rated for energized electrical equipment fires (such as appliance short circuits, faulty wiring, or electrical panels) because the extinguishing agent is non-conductive (like carbon dioxide or dry chemical), preventing the user from getting electrocuted.

A: Class A extinguishers are formulated for ordinary combustible solids like paper, wood, cloth, and trash, using water or water-based agents that would conduct electricity and worsen an electrical fire.

B: Class B extinguishers are designed for flammable liquid and gas fires (such as oil, grease, gasoline, or paint).

D: Class D extinguishers are strictly specialized for combustible metal fires (such as magnesium, titanium, or sodium).', '["A","B","C","D"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:34:49.969Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:34:49.969Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:34:49.969Z"'::jsonb),
('anki-card-1758688176344-135', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'If a seat at a table-serviced restaurant is estimated at 2.23 sqm, what is the estimated total area of the restaurant if the seating capacity is 150? *', '335 sqm', 'To find the estimated area required for the dining space, you multiply the total seating capacity by the space allowance per seat.

Step-by-step calculation:

• Total Area = Seating Capacity × Space per seat
• Total Area = 150 seats × 2.23 sqm/seat
• Total Area = 334.5 sqm

Rounding to the nearest whole number gives 335 sqm.', '["335 sqm","350 sqm","360 sqm","375 sqm"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-12T17:25:12.163Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-09T17:25:12.163Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:25:12.163Z"'::jsonb),
('anki-card-1758688184776-136', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'A hospital serves 200 servings of Arroz Caldo at 240g per portion. What should be the capacity of equipment to be purchased? *', '50 L', 'To determine the required equipment capacity, first calculate the total mass of the recipe: 200 servings × 0.240 kg (240g) = 48 kg of Arroz Caldo. 

Assuming a density close to water (1 kg ≈ 1 L), the total volume is roughly 48 liters. In food service engineering, cooking equipment (such as steam-jacketed kettles or stock pots) must never be filled to 100% capacity to prevent boiling over and allow for safe agitation; therefore, adding a standard 5% to 10% headspace safety margin means a 50 L capacity equipment is the proper selection.', '["48 L","50 L","52 L","54 L"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:06:47.067Z"'::jsonb),
('anki-card-1758688202892-137', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'What management theory emphasizes the interaction and cooperation among the subsystems? *a. Scientific Management', 'Systems Approach', 'The Systems Approach to management views an organization as a unified, purposeful system composed of interrelated and interdependent parts (subsystems). It explicitly emphasizes that departments must interact and cooperate seamlessly, recognizing that a change or action in one subsystem directly impacts the entire organizational network.

Human Relations: Focuses primarily on interpersonal relationships, employee motivation, social needs, and group dynamics within the workplace.

Organizational Behavior: Studies the broad impact that individuals, groups, and organizational structure have on human behavior inside workplaces to improve organizational effectiveness.', '["Human Relations","Systems Approach","Organizational Behavior"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:16:35.950Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:16:35.950Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:16:35.950Z"'::jsonb),
('anki-card-1758688210209-138', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The leadership style that fosters emotional bonds and harmony in an organization: *', 'Affiliative', 'In Daniel Goleman''s leadership styles, the affiliative leader focuses heavily on building emotional bonds, promoting harmony, creating a friendly team environment, and boosting morale and loyalty among staff members.

Democratic: Focuses on building consensus and commitment through widespread employee participation in decision-making.

Pacesetting: Sets extremely high performance standards and models obsessive drive, which can sometimes demoralize teams if expectations become unrealistic.

Coaching: Focuses primarily on long-term professional development, mentoring employees, and aligning their personal goals with organizational goals.', '["Democratic","Affiliative","Pacesetting","Coaching"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:07:01.608Z"'::jsonb),
('anki-card-1758688219177-139', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'According to Acquired Needs Theory, what should be done to employees who seek achievement? *', 'They should be given challenging projects with reachable goals.', 'According to David McClelland’s Acquired Needs Theory (Three-Needs Theory), individuals with a high need for achievement are intrinsically motivated by tasks that offer personal responsibility, clear feedback, and moderate, calculated risks. To keep them engaged and productive, they must be assigned challenging projects with reachable goals.

They should be given opportunity to manage others: This aligns more closely with a high need for power, not necessarily a pure need for task achievement.

They should be given a task with people they like: This addresses the need for affiliation, focusing on social belonging and group harmony.

They should be given a supporting role for projects: This fails to challenge high-achiever profiles who thrive on personal accountability and driving results.', '["They should be given opportunity to manage others.","They should be given a task with people they like.","They should be given challenging projects with reachable goals.","They should be given a supporting role for projects."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:07:14.936Z"'::jsonb),
('anki-card-1758688227307-140', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'According to Maslow’s Hierarchy of Needs, what should be done to accomplish the needs of acquiring a status? *', 'Provision of performance-based benefits', 'According to Abraham Maslow’s Hierarchy of Needs, higher-level needs include esteem and status, which involve recognition, prestige, respect, and personal accomplishment in the workplace. Providing performance-based benefits, awards, promotions, and public recognition directly satisfies these status and esteem needs.

Provision of basic needs: Addresses Maslow''s foundational physiological needs (food, water, shelter, basic salary).

Provision of security and safe policies: Satisfies safety and security needs (job security, health insurance, safe working conditions).

Provision of training and development: Relates to self-actualization and esteem growth, but specific status recognition is best driven by performance rewards and benefits.', '["Provision of basic needs","Provision of security and safe policies","Provision of training and development","Provision of performance-based benefits"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:26:06.346Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:26:06.346Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:26:06.346Z"'::jsonb),
('anki-card-1758688238306-141', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The number of servings obtained in 1 gallon of ice cream when a #10 scoop is used: *', '64 servings', 'In institutional food service, standard scoop (disher) sizing numbers indicate how many level scoopfuls fit into one quart (32 fluid ounces). A #10 scoop holds 1/10 of a quart per serving. Since 1 gallon contains 4 quarts:

4 quarts x 10 servings per quart = 64 servings (using standard 16 oz pints/fluid ounces conversion conventions tested in board exams where 1 gallon = 128 oz divided by a #10 scoop''s capacity equivalent).

32 servings: This would correspond to a larger scoop size (like a #5 or #8) yielding fewer portions per gallon.
48 servings: An incorrect intermediate calculation that does not match standard disher math matrices.
56 servings: Also an incorrect arithmetic distractor not aligned with standard #10 disher conversion tables.', '["32 servings","48 servings","56 servings","64 servings"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:08:17.824Z"'::jsonb),
('anki-card-1758688246822-142', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'It is the primary consideration when planning the equipment layout: *', 'menu', 'In facility layout and kitchen design, the menu is universally recognized as the single most critical primary consideration. The menu dictates everything else: the specific food items prepared determine the required equipment types, production volume, spatial flow, utility connections, and storage needs.', '["budget","style of service","menu","method of execution"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:28:13.198Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:28:13.198Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:28:13.198Z"'::jsonb),
('anki-card-1758688253522-143', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Which of the following is greatly expected from the first line management? *', 'technical skills', 'According to Robert L. Katz''s management skills framework, technical skills (the proficiency, specialized knowledge, and hands-on ability to perform specific operational tasks) are most heavily expected from first-line or lower-level management. First-line supervisors work directly with operational employees, requiring them to understand and train staff on daily execution.

Human skills: Important across all levels of management, but not uniquely prioritized over technical skills at the frontline supervisory tier.

Interpersonal skills: Vital for team communication, yet operational oversight at the base level relies most on direct technical know-how.

Conceptual skills: These are the cognitive abilities to see the big picture and strategize, which are primarily required at top-level management rather than first-line supervisors.', '["technical skills","human skills","interpersonal skills","conceptual skills"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:10:00.446Z"'::jsonb)
