INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758688830195-194', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'It is considered a fixed cost in food service institutions. *', 'depreciation of equipment', 'Fixed costs are expenses that do not fluctuate with changes in sales volume, production levels, or guest counts. Depreciation of equipment is a classic fixed cost because the asset loses value over time regardless of how many meals a restaurant serves on any given day.

Cost of sales: This is a variable cost that rises and falls directly with the volume of food sold.

Salaries of food service personnel: While base salaries can have fixed elements, hourly or production labor often scales with volume, making depreciation the purer fixed cost.

Cost of cooking fuel: A variable operational expense that increases directly with heavy cooking and kitchen production volume.', '["depreciation of equipment","cost of sales","salaries of food service personnel","cost of cooking fuel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:28:02.809Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-09T17:28:02.809Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:28:02.809Z"'::jsonb),
('anki-card-1758688839696-195', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'All of the following are basis of salary or wage rates except: *', 'performance ratings', 'Job evaluation, wage structures, and base salary rates are established based on job analysis metrics: the educational qualifications required, the level of responsibility, and the difficulty of the job. Performance ratings are used for merit increases, bonuses, or promotions, not as the foundational benchmark for setting baseline job salary grades.

Educational qualification: A core factor in job evaluation determining entry-level pay grades based on required professional credentials.

Level of responsibility: Evaluates the financial or managerial accountability of a position to determine its baseline salary weight.

Difficulty of the job: Assesses the mental, physical, and technical complexity of duties to establish comparative pay scales.', '["educational qualification","level of responsibility","difficulty of the job","performance ratings"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:38:07.267Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:38:07.267Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:38:07.267Z"'::jsonb),
('anki-card-1758688850061-196', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'When is the appropriate time for re-training in an organization? *', 'An employee’s performance continues to drop below the set standard.', 'In human resource management and training protocols, re-training (or remedial training) is specifically indicated when an employee’s actual job performance continues to drop below established performance standards, signaling a skills gap, drift, or need for corrective reinforcement.

A new equipment has just been installed: This requires initial or developmental training, not remedial re-training.

An employee has been hired with no prior experience: This calls for onboarding and initial foundational training, not re-training.

An employee has not learned a particular technique: This represents an initial training gap rather than performance decay requiring re-training.', '["A new equipment has just been installed.","An employee has been hired with no prior experience.","An employee’s performance continues to drop below the set standard.","An employee has not learned a particular technique."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T14:29:27.739Z"'::jsonb),
('anki-card-1758688858462-197', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Mongo Guisado has 4 cups of dried mongo beans. The beans were soaked the previous night to lessen cooking time. How many cups of water was used to soak the beans? *', '12', 'In culinary preparation of dried legumes like mung beans (mongo), the standard rehydration ratio requires submerging dried beans in 3 times their volume of water to allow complete water absorption during soaking without drying out. 

For 4 cups of dried mongo beans: 4 cups x 3 = 12 cups of water.', '["12","10","8","6"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T17:33:15.254Z","interval":1,"easeFactor":2.3,"repetitions":0}'::jsonb, '"2026-11-09T17:33:15.254Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:33:15.254Z"'::jsonb),
('anki-card-1758688866495-198', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The best substitute for 1 cup brown sugar is: *', '1 cup granulated sugar + 2 T molasses or dark corn syrup', 'In baking and food science, commercial brown sugar is essentially refined white (granulated) sugar that has had molasses added back into it. Therefore, the most chemically and texturally accurate substitute for 1 cup of brown sugar is exactly that: 1 cup of granulated white sugar mixed with 1 to 2 tablespoons of molasses (or dark corn syrup if molasses is unavailable). This replicates not only the sweetness but also the moisture content, the caramel flavor profile, and the acidity needed to react properly with baking soda.', '["1 cup granulated sugar + 2 T molasses or dark corn syrup","½ cup honey","1 cup honey minus ¼ liquid in the recipe","½ cup confectioner sugar"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-12T17:28:07.980Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-09T17:28:07.980Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-09T17:28:07.980Z"'::jsonb),
('anki-card-1758688884061-199', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'The food cost percentage of a restaurant that has a raw food cost of Php20,000 with total sales of Php45,000 a week: *', '44%', 'To determine the food cost percentage, you need to use the standard foodservice formula:

Food Cost Percentage = (Total Food Cost / Total Sales) x 100

1. Plug in the given values:
Food Cost Percentage = (Php 20,000 / Php 45,000) x 100

2. Calculate the decimal value:
20,000 ÷ 45,000 = 0.4444...

3. Convert to a percentage:
0.4444 x 100 = 44.44%

Rounding to the nearest whole number gives us 44%.', '["44%","34%","22%","50%"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-09T12:04:35.904Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-08T12:04:35.904Z"'::jsonb, '"2026-09-26T14:32:30.210Z"'::jsonb, '"2026-11-08T12:04:35.904Z"'::jsonb),
('anki-card-1758688903260-200', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Mrs. Cruz is giving a party for her daughter. She expects 200 guests, 20% of whom will be adults and the rest will be children.
She plans to serve ice cream as dessert with a serving portion of ½ cup for adults and ¼ cup for children. How many gallons of ice cream does she need to purchase? *', '75/4 gallons', '', '["75/4 gallons","5 gallons","6 gallons","2 gallons"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-10T13:51:07.689Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-09T13:51:07.689Z"'::jsonb, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-11-09T13:51:07.689Z"'::jsonb),
('anki-card-1758688917075-201', NULL, 'anki-deck-1783609236208-1790433142623-d6lsk', 'Mrs. Cruz is giving a party for her daughter. She expects 200 guests, 20% of whom will be adults and the rest will be children.
If she buys 5 gallons of ice cream, what scoop number should she use to serve the guests equally? *', '#10', 'In institutional food service, standard disher (scoop) numbers indicate how many scoopfuls fit into one quart (32 fluid ounces). A #10 scoop holds roughly 3.2 fluid ounces (approx. 0.4 cups or standard portion equivalent), making it the designated commercial portioning tool utilized in this problem''s test key to distribute bulk ice cream evenly across party guests.', '["#6","#16","#10","#8"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:30.338Z"'::jsonb, '"2026-11-08T14:24:55.970Z"'::jsonb),
('anki-card-1758783495384-0', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Low-acid foods except: *', 'pickles', 'Pickles are high-acid foods due to pickling vinegar (acetic acid) preservation, which inhibits bacterial spoilage and botulism spores, making them the correct exception.

• Meat / Corn / Shrimp: Low-acid foods (pH > 4.6) that require pressure canning or strict refrigeration to prevent Clostridium botulinum growth.', '["meat","corn","shrimp","pickles"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:48:29.768Z"'::jsonb),
('anki-card-1758783505506-1', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'All are tender cuts of beef except: *', 'brisket', 'The brisket is a heavily exercised cut derived from the breast section containing abundant connective tissue (collagen), making it a tough cut requiring slow, moist-heat cooking.

• T-bone / Sirloin / Porterhouse: Tender cuts from the loin and rib sections best suited for dry-heat cooking.', '["T-bone","brisket","sirloin","porterhouse"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:48:35.274Z"'::jsonb),
('anki-card-1758783520422-2', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'These microorganisms can grow in jams and jellies: *', 'osmophile', 'Osmophilic microorganisms (such as specific spoilage yeasts and molds) are specialized microbes capable of growing in high-osmotic-pressure environments with high sugar concentrations, such as jams, jellies, and honey.

• Halophile: Thrives in high salt concentrations.
• Acidophile: Thrives in low pH acidic environments.
• Alkaliphile: Thrives in high alkaline pH.', '["osmophile","halophile","acidophile","alkaliphile"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:48:40.527Z"'::jsonb),
('anki-card-1758783531473-3', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Objective tests to determine the color of food except: *', 'photography', 'Standard photography captures visual light images but does not provide precise numerical or spectral data, making it an uncalibrated subjective method rather than an objective colorimetry tool.

• Spectrophotometer / Colorimetry / Turbidimetry test: Precise instrumental objective methods for quantifying light absorption, transmission, and color coordinates.', '["photography","spectrophotometer","colorimetry","turbidimetry test"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:48:46.683Z"'::jsonb),
('anki-card-1758783540341-4', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Which of the following ingredients contributes to the crustiness in a sponge cake? *', 'sugar', 'Sugar contributes to crust browning (via caramelization and Maillard reactions) and aids crustiness in sponge cakes and baked goods by raising coagulation temperatures and binding moisture.', '["milk","sugar","salt","flour"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:49:53.594Z"'::jsonb),
('anki-card-1758783553488-5', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Which of the following is not a functional food? *', 'mango', 'While mangoes contain rich vitamins and phytochemicals, whole fresh fruits are traditional whole foods, whereas functional foods are specifically defined as foods or dietary components marketed or processed to provide health benefits beyond basic nutrition (often fortified or enriched).

• Broccoli / Malunggay / Garlic: Widely classified as functional foods due to specific bioactive compounds (glucosinolates, antioxidants, allicin).', '["broccoli","malunggay","garlic","mango"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:49:59.926Z"'::jsonb),
('anki-card-1758783566203-6', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'The main protein in egg yolk is: *', 'vitellin', 'Vitellin is the primary lipoprotein-bound protein complex found in egg yolk.

• Livetin: A secondary soluble protein fraction in egg yolk.
• Albumin: The major protein found in egg whites.', '["vitellin","phosvitin","livetin","albumin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:50:04.160Z"'::jsonb),
('anki-card-1758783577422-7', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'If you are using baking soda instead of baking powder, you should: *', 'use the same amount and add milk', 'Baking soda is pure sodium bicarbonate and requires an acid ingredient to activate; however, if substituting it in recipes without modifying the acid balance, keeping the amount proportional while ensuring adequate acidic liquid (like buttermilk or milk) prevents chemical off-flavors.', '["reduce the amount of baking soda and add milk","increase the amount of baking soda and add acid","use the same amount and add milk","just use the same amount"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:50:09.121Z"'::jsonb),
('anki-card-1758783588220-8', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'This food item has a shelf life of more than a year: *', 'canned goods', 'Commercially hermetically sealed canned goods undergo thermal sterilization, giving them a long shelf life extending well beyond one year under ambient storage conditions.

• Rice in a sack / Cornstarch / Flavoring extracts: Susceptible to insect infestation, moisture absorption, or flavor degradation over long periods.', '["cornstarch","rice in a sack","flavoring extracts","canned goods"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:50:13.931Z"'::jsonb),
('anki-card-1758783597587-9', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Flour with the highest protein content. *', 'bread flour', 'Commercially hermetically sealed canned goods undergo thermal sterilization, giving them a long shelf life extending well beyond one year under ambient storage conditions.

• Rice in a sack / Cornstarch / Flavoring extracts: Susceptible to insect infestation, moisture absorption, or flavor degradation over long periods.', '["rice flour","all-purpose flour","cake flour","bread flour"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:50:19.043Z"'::jsonb),
('anki-card-1758783608918-10', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'The chief structural carbohydrate of plants responsible for the crisp texture of salad greens. *', 'cellulose', 'Cellulose is an unbranched glucose polymer and the chief structural component of plant cell walls, providing crispness and rigidity to fresh vegetables like salad greens.', '["starch","cellulose","pectin","dextrin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:50:24.037Z"'::jsonb),
('anki-card-1758783635901-11', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Examples of moist heat method of cooking except: *', 'fried galunggong', 'Fried galunggong uses hot oil (fat) to apply dry heat via conduction, classifying it as a dry-heat frying method rather than moist-heat.

• Steamed / Pesang dalag / Paksiw: Classic moist-heat cooking methods utilizing steam or boiling broths.', '["steamed lapu-lapu","pesang dalag","fried galunggong","paksiw na bangus"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:24.324Z"'::jsonb),
('anki-card-1758783645335-12', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'This resembles cake flour in composition and in baking properties: *', 'pastry flour', 'Pastry flour has a protein content (~9–10%) and baking properties that closely resemble soft-wheat cake flour, offering tender crumb structures for pastries and pies.', '["all-purpose flour","bread flour","rice flour","pastry flour"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:28.638Z"'::jsonb),
('anki-card-1758783657851-13', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'All are products of lactic acid fermentation except: *', 'vinegar', 'Vinegar is produced via acetic acid bacterial fermentation of ethanol, whereas cheese, atchara (fermented papaya), and cultured butter are products of lactic acid bacterial fermentation.', '["cheese","vinegar","atchara","butter"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:32.081Z"'::jsonb),
('anki-card-1758783677031-14', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'It is made from pork fat: *', 'lard', 'Lard is rendered fat sourced specifically from pork adipose tissue.

• Tallow: Rendered beef or sheep fat.
• Suet: Raw hard beef fat surrounding kidneys.', '["suet","hydrogenated fat","tallow","lard"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:38.255Z"'::jsonb),
('anki-card-1758783687015-15', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'A crude market form of sugar where sugarcane extract is evaporated into a brown syrup concentrate and molded in a halved coconut shell. *', 'panutsa', 'Panutsa (or penoche) is a traditional crude Philippine brown sugar formed by evaporating sugarcane juice syrup into a thick concentrate and molding it inside halved coconut shells.', '["pakaskas","panutsa","raw brown sugar","lump sugar"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:42.887Z"'::jsonb),
('anki-card-1758783699382-16', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'A physical change undergone by starch gels during storage which leads to an increase in crystalline aggregates and results in a gritty texture. An example is the thin film that forms on top of puddings. *', 'retrogradation', 'Retrogradation is the physical recrystallization of gelatinized starch molecules upon cooling or storage, causing staling in bread and the formation of a gritty skin or film on top of cooling puddings.', '["dextrinization","gelatinization","retrogradation","degradation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:48.555Z"'::jsonb),
('anki-card-1758783709947-17', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'A dark purple-colored rice used in “puto bumbong.” *', 'pirurutong', 'Pirurutong is an heirloom Philippine deep purple-colored glutinous rice variety traditionally utilized to make native kakanin like puto bumbong.

• Pinipig: Immature flattened rice grains.', '["parboiled rice","pirurutong","pinipig","binlid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:53.561Z"'::jsonb),
('anki-card-1758783721064-18', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'It is not included in the group: *', 'gin', 'Gin is a clear distilled spirit produced from grain mashes and flavored with juniper berries, whereas tuba, lambanog, and basi are traditional indigenous fermented alcoholic beverages derived from coconut sap or sugarcane.', '["tuba","lambanog","gin","basi"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:51:57.438Z"'::jsonb),
('anki-card-1758783731730-19', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'A cereal that is invaluable in yeast bread-making as it is a significant source of gluten. *', 'wheat', 'Wheat is the primary cereal grain containing high proportions of the storage proteins gliadin and glutenin, making it uniquely invaluable in yeast bread-making for gluten network formation.', '["rye","wheat","corn","couscous"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:52:02.416Z"'::jsonb),
('anki-card-1758783748394-20', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'The chief food reserve of plants which is converted to sugar as fruits ripen. *', 'starch', 'Starch serves as the chief polysaccharide food reserve synthesized by plants, which is enzymatically hydrolyzed into simple sugars as fruits ripen and soften.', '["pectin","cellulose","starch","glucose"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:52:06.519Z"'::jsonb),
('anki-card-1758783758713-21', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Source of sucrose: *', 'candies', 'Candies are concentrated commercial sweets formulated primarily from refined sucrose (table sugar).

• Fruit: Contains natural fructose and glucose.
• Honey: Contains invert sugars (glucose and fructose).', '["pudding","honey","candies","fruit"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:49:42.307Z"'::jsonb),
('anki-card-1758783771011-22', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Local dessert/snack items made with non-glutinous rice except: *', 'maja blanca', 'Maja blanca is a traditional Filipino gelatinous dessert made from coconut milk, cornstarch, and sugar, utilizing cornstarch (a non-glutinous cereal starch derivative), whereas champorado, sapin-sapin, and lugaw utilize glutinous rice or regular rice.', '["champorado","maja blanca","sapin-sapin","lugaw"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:52:10.487Z"'::jsonb),
('anki-card-1758783781445-23', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Part of the cereal grain which contains oil, protein, and vitamins making it prone to oxidative rancidity.', 'germ', 'The germ is the nutrient-dense reproductive embryo of the cereal grain, rich in lipids, protein, and vitamins, which makes it highly susceptible to lipid oxidation and oxidative rancidity.', '["germ","endosperm","bran","hull"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:52:14.585Z"'::jsonb),
('anki-card-1758783791510-24', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'To make a thinner porridge or oatmeal: *', 'add more water', 'To adjust consistency and make porridge or oatmeal thinner, increasing the proportion of cooking liquid (adding more water) is the standard culinary adjustment.', '["increase the stirring using a fork","add more water","add the cereal gradually to the boiling water","none of the above"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:52:19.937Z"'::jsonb),
('anki-card-1758783801192-25', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'When rice is toasted or browned for kare-kare, the starch undergoes: *', 'dextrinization', 'When dry rice or starch is toasted, browned, or heated without moisture (as in preparing base flour for kare-kare sauce), the starch molecules break down into shorter-chain sweet dextrins, a process called dextrinization.', '["gelatinization","oxidative rancidity","retrogradation","dextrinization"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:52:24.964Z"'::jsonb),
('anki-card-1758783812562-26', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'The function of starch when used in chocolate drinks and cooked dressings is as a ____ agent. *', 'stabilizing', 'Starch acts as a suspending and thickening agent in formulated beverages like cooked chocolate drinks and cooked dressings by binding free water and increasing viscosity.', '["stabilizing","coloring","thickening","gelling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:52:28.114Z"'::jsonb),
('anki-card-1758783823960-27', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Gluten formation is brought about by the interaction of ___ with ___ during dough mixing. *', 'glutenin; gliadin', 'Gluten formation occurs when the two wheat flour storage proteins—glutenin (which provides elasticity) and gliadin (which provides extensibility and stickiness)—are hydrated with water and mechanically kneaded together.

• Globulin / Albumin: Other minor wheat proteins, but they do not form the cohesive gluten matrix.', '["glutenin; globulin","glutenin; gliadin","gliadin; albumin","glutenin; albumin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:07.458Z"'::jsonb),
('anki-card-1758783833925-28', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Microorganisms used for cheese ripening: *', 'mold', 'Molds (such as Penicillium roqueforti or Penicillium camemberti) are specialized fungi utilized during ripening processes to impart characteristic textures, flavors, and appearance in aged cheeses (e.g., Blue cheese, Brie).', '["bacteria","yeast","fungus","mold"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:11.553Z"'::jsonb),
('anki-card-1758783844241-29', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'At the freezing point and below it, microorganisms become dormant because:', 'a & b only', 'At and below freezing temperatures, microorganisms enter dormancy because available free water is locked up as ice (a) and intracellular/extracellular enzymatic metabolic rates are drastically retarded (b).', '["of lack of available moisture","enzymatic activities are retarded","cells die","a & b only"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:17.188Z"'::jsonb),
('anki-card-1758783852823-30', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Local term for Chinese cabbage: *', 'pechay', 'Pechay is the local Tagalog term for Chinese cabbage (Brassica rapa subsp. pekinensis or chinensis).

• Repolyo: Cabbage.
• Remolatsa: Beetroot.
• Kinchay: Chinese celery.', '["repolyo","remolatsa","kinchay","pechay"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:28.807Z"'::jsonb),
('anki-card-1758783868974-31', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'It is a rod-shaped bacterium that causes food spoilage: *', 'Bacilli', 'Bacilli are rod-shaped bacteria, many species of which are common agents of food spoilage and foodborne illness.

• Cocci: Spherical bacteria.
• Spirilla / Vibrios: Spiral or comma-shaped bacteria.', '["Spirilla","Cocci","Bacilli","Vibrios"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:34.657Z"'::jsonb),
('anki-card-1758783878940-32', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'The location of taste buds that detects sourness: *', 'side of the tongue', 'Human gustatory mapping identifies that taste buds responsive primarily to sourness (driven by hydrogen ions from acids) are located along the lateral sides of the tongue.

• Tip of the tongue: Sensitive primarily to sweetness and saltiness.
• Back of the tongue: Sensitive primarily to bitterness.', '["front of the tongue","tip of the tongue","side of the tongue","back of the tongue"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:40.495Z"'::jsonb),
('anki-card-1758783890871-33', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'The basis for grading rice is: *', 'size of the kernel', 'Commercial and government grading standards for milled rice are based primarily on physical kernel characteristics, including head rice recovery, broken kernel percentages, and physical size/length of the kernel.', '["variety of the palay","source or origin","its smell","size of the kernel"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:44.296Z"'::jsonb),
('anki-card-1758783914938-34', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Spoilage of a refrigerated salad is likely caused by microorganisms that are: *', 'Psychrotrophs', 'Psychrotrophs are cold-tolerant microorganisms that can grow and multiply at refrigerator temperatures (0°C to 7°C), making them the primary cause of spoilage in refrigerated perishable foods like salads, dairy, and cold cuts.

• Psychrophiles: True cold-loving microbes thriving at lower polar temperatures.
• Mesophiles: Thrive at moderate, ambient room temperatures.
• Thermophiles: Thrive at high heat.', '["Psychrophiles","Mesophiles","Thermophiles","Psychrotrophs"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:49.060Z"'::jsonb),
('anki-card-1758783927739-35', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Staphylococci contamination of food often occurs through: *', 'food handlers with open wounds', 'Staphylococcus aureus is a common bacterium harbored in human nasal passages, skin, and infected skin lesions or open wounds, frequently contaminating foods during manual preparation by handlers.', '["food handlers with open wounds","water used in cooking","utensils used during preparation","underprocessed canned products"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:54.944Z"'::jsonb),
('anki-card-1758783936504-36', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'What phase in the microbial growth curve is characterized by very rapid cell growth and highestsensitivity to antimicrobial agents? *', 'log phase', 'During the logarithmic (log) phase of microbial growth, cells divide exponentially at their maximum rate, making them exceptionally metabolically active and highly sensitive to heat, sanitizers, and antimicrobial agents.

• Lag phase: Adaptation period with minimal cell division.
• Stationary phase: Growth rate equals death rate.', '["lag phase","log phase","stationary phase","death phase"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:53:59.426Z"'::jsonb),
('anki-card-1758783946353-37', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Mad cow disease, characterized by degeneration in the central nervous system, is caused by: *', 'Prions', 'Bovine spongiform encephalopathy (BSE), commonly known as "mad cow" disease, is a transmissible spongiform encephalopathy caused not by living organisms or viruses, but by misfolded infectious proteins called prions.', '["Viruses","Rickettsias","Prions","Protozoa"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:54:04.088Z"'::jsonb),
('anki-card-1758783958619-38', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'Commercial sterility implies that __________. *', 'all pathogenic microorganisms in the food were destroyed', 'In food science, commercial sterility refers to the condition achieved in thermally processed (canned) foods where all pathogenic, toxin-forming, and spoilage microorganisms capable of growing under normal non-refrigerated storage conditions have been destroyed.', '["no microorganisms are present in the food","all pathogenic microorganisms in the food were destroyed","spoilage microorganisms present in the food were removed","microorganisms present in the food will not be able to grow under normal storage conditions"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:54:07.740Z"'::jsonb),
('anki-card-1758783968085-39', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'The first stage of ice crystal formation during freezing: *', 'nucleation', 'Nucleation is the critical initial thermodynamic stage in freezing where tiny clusters of water molecules begin to form stable micro-crystal nuclei before crystal growth and ripening occur.', '["ripening","nucleation","crystal growth","recrystallization"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:54:12.085Z"'::jsonb),
('anki-card-1758783980652-40', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'What is the effect of heat or cooking on flour mixtures? *', 'It coagulates egg and flour proteins.', 'Applying thermal heat to flour mixtures denatures and coagulates egg and flour proteins (such as gluten and albumins), setting the structural matrix and crumb of baked goods.', '["It develops gluten.","It coagulates egg and flour proteins.","It ensures an even distribution of moisture.","It provides an even distribution of fat."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:54:16.457Z"'::jsonb),
('anki-card-1758783989402-41', NULL, 'anki-deck-1783609268127-1790433136748-a3r8j', 'These food items should be kept at room temperature except for: *', 'bread', 'Bread stales rapidly and develops mold when stored in warm, humid refrigerators due to retrogradation of starch; it should be kept at room temperature for short-term consumption or frozen for long-term storage.

• Onion / Garlic / Banana: Kept at cool ambient room temperatures.', '["bread","onion","banana","garlic"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.352Z"'::jsonb, '"2026-11-09T09:54:21.468Z"'::jsonb)
