('anki-card-1758815861029-110', NULL, 'anki-deck-1783609279327-1790433140276-ah6lq', 'The recommended size of place setting for children: *', '45-50 cm', 'Standard institutional dining room layout guidelines recommend a table space allocation (place setting) of 45 to 50 cm width for children to ensure comfortable seating without crowding.', '["35-40 cm","45-50 cm","55-60 cm","65-70 cm"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.872Z"'::jsonb, '"2026-11-09T09:26:23.166Z"'::jsonb),
('anki-card-1758815868314-111', NULL, 'anki-deck-1783609279327-1790433140276-ah6lq', 'A burner is used for surface cooking in a gas range. What is its counterpart in an electric range? *', 'hot plate', 'In commercial and institutional kitchen equipment, a hot plate serves as the electric equivalent of a gas range surface burner.', '["hot plate","burner","electric coil","cooker"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.872Z"'::jsonb, '"2026-11-09T09:26:34.628Z"'::jsonb),
