('anki-card-1758816505166-169', NULL, 'anki-deck-1783609279327-1790433140276-ah6lq', 'Removing the green top or leaves of carrots, radishes, or beets will _____. *', 'increase storage time', 'Removing the green leafy tops (leaves) of root vegetables like carrots, radishes, or beets prevents transpiration and moisture loss, thereby significantly increasing their post-harvest storage lifespan.', '["shorten storage time","increase water content","increase storage time","not affect storage time"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.872Z"'::jsonb, '"2026-11-09T09:40:47.937Z"'::jsonb),
('anki-card-1758816512149-170', NULL, 'anki-deck-1783609279327-1790433140276-ah6lq', 'The Presidential Decree which allows employees to get a 13th month pay. *', 'PD 851', 'Presidential Decree No. 851 (enacted in 1975) is the landmark labor law that mandates employers to pay all rank-and-file employees a 13th-month pay.', '["PD 851","PD 928","PD 525","PD 1364"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.872Z"'::jsonb, '"2026-11-09T09:41:59.092Z"'::jsonb),
('anki-card-1758816520497-171', NULL, 'anki-deck-1783609279327-1790433140276-ah6lq', 'The most sanitary type of food equipment: *', 'stainless steel', 'Stainless steel is the premier material for fabricating commercial food equipment because it is non-porous, corrosion-resistant, durable, and exceptionally sanitary.

