INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1756217610571-35', NULL, 'anki-deck-1783609369423-1790433139853-3jf91', 'Drip is a method of making:', 'coffee', 'In coffee brewing, the drip method, also known as drip coffee or filter coffee, involves pouring hot water over ground coffee beans contained in a filter. The water drips through the coffee grounds and filter into a pot or carafe below, extracting flavor and oils from the coffee grounds as it passes through. This method is popular for its simplicity and ability to produce a clean, flavorful cup of coffee.', '["tea","chocolate","coffee","breakfast certial"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T14:14:47.279Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T14:14:47.279Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T14:14:47.279Z"'::jsonb),
('anki-card-1756217650552-36', NULL, 'anki-deck-1783609369423-1790433139853-3jf91', 'Tequila-based cocktail with lime juice and triple sec.', 'Margarita', 'Margarita typically consists of tequila, lime juice (often freshly squeezed), and triple sec (an orange-flavored liqueur). It is usually served in a glass with a salted rim. The combination of tequila’s agave flavor, tart lime juice, and sweet triple sec creates a balanced and refreshing cocktail.

• Martini: Typically made with gin and vermouth, garnished with an olive or a lemon twist.
• Tequila Sunrise: Made with tequila, orange juice, and grenadine syrup, creating a layered sunrise effect.
• Daiquiri: A classic cocktail made with rum, lime juice, and simple syrup, served straight up or on the rocks.', '["Martini","Tequila sunrise","Daiquiri","Margarita"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:38:21.116Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:38:21.116Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:38:21.116Z"'::jsonb),
('anki-card-1756217699951-37', NULL, 'anki-deck-1783609369423-1790433139853-3jf91', 'Head of the kitchen brigade system.', 'Executive Chef', 'In the traditional kitchen brigade system, which was developed by Georges Auguste Escoffier, the Executive Chef holds the highest authority and responsibility in the kitchen. This role involves overseeing all aspects of the kitchen operations, including menu planning, food preparation, kitchen staff management, and ensuring culinary standards and quality control.

• Garde Manger: The Garde Manger, also known as the pantry chef, is responsible for cold food preparation, such as salads, appetizers, and sometimes desserts.
• Sommelier: A wine steward or wine expert responsible for selecting and serving wines in a restaurant.
• Sous Chef: The second-in-command in the kitchen, assisting the Executive Chef in managing kitchen staff, overseeing food production, and ensuring kitchen operations run smoothly.', '["Garde manger","Sommelier","Executive Chef","Sous Chef"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T13:19:34.724Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T13:19:34.724Z"'::jsonb, '"2026-09-26T14:32:29.891Z"'::jsonb, '"2026-10-14T13:19:34.798Z"'::jsonb),
