INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757931569742-58', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'An individual with IDA should be encouraged to increase his/her intake of which of the following:*', 'red meats', 'Iron Deficiency Anemia (IDA) is best managed by increasing the intake of heme-iron-rich foods, particularly red meats, which offer high bioavailability and enhance non-heme iron absorption.

• dairy products: Low in iron and high dairy calcium can actually inhibit iron absorption.
• pasta: Refined pasta is poor in iron unless heavily fortified.
• cruciferous vegetables: Contain non-heme iron with lower bioavailability and inhibitors like oxalates/phytates.', '["dairy products","pasta","cruciferous vegetables","red meats"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:22:21.877Z"'::jsonb),
('anki-card-1757931580508-59', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', '. What is the usual vitamin A deficiency sign?*', 'night blindness', 'The earliest and most classic clinical deficiency sign of Vitamin A (retinol) is impaired dark adaptation leading to night blindness (nyctalopia), due to its role in forming rhodopsin in retinal rod cells.

• bone pain: Associated with Vitamin D or calcium imbalances.
• bleeding gums: The classic sign of Vitamin C deficiency (scurvy).
• seizures: Associated with electrolyte or Vitamin B6 abnormalities.', '["bone pain","bleeding gums","night blindness","seizures"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:22:29.272Z"'::jsonb),
('anki-card-1757931590657-60', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The need for vitamin E in the diet will increase with an increase in the amount of what other nutrient in the diet?*', 'PUFA', 'Vitamin E is a lipid-soluble antioxidant that protects cell membranes from lipid peroxidation. The dietary requirement for Vitamin E increases proportionally with an increase in dietary polyunsaturated fatty acids (PUFAs) because PUFAs are highly susceptible to free radical oxidation.', '["protein","saturated fatty acids","lipids","PUFA"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:22:34.327Z"'::jsonb),
('anki-card-1757931606774-61', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Vitamin K deficiency is a possible result of*', 'antibiotic therapy', 'Vitamin K is synthesized to a significant extent by normal gut microflora in the large intestine. Prolonged broad-spectrum antibiotic therapy destroys these beneficial gut bacteria, potentially leading to Vitamin K deficiency and impaired blood clotting.

• kidney disease: Affects fluid and electrolyte balance, not primary bacterial Vitamin K synthesis.
• presence of phytates: Impair mineral absorption (zinc, iron, calcium), not Vitamin K.
• low citrus fruits intake: Causes Vitamin C deficiency (scurvy).', '["kidney disease","antibiotic therapy","presence of phytates","low citrus fruits intake"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:22:40.621Z"'::jsonb),
('anki-card-1757931624641-62', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Plant oils are excellent sources of _______ and liver is an excellent source of _______.*', 'vitamin E; vitamin A', 'Plant oils (such as wheat germ, sunflower, and safflower oils) are rich sources of Vitamin E (tocopherols), while animal liver is an exceptionally concentrated source of preformed Vitamin A (retinol).', '["vitamin K; vitamin A","vitamin E; vitamin D","vitamin E; vitamin A","vitamin D; vitamin K"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:22:46.392Z"'::jsonb),
('anki-card-1757931636656-63', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Which of the following people are least likely to need a vitamin/mineral supplement?*', 'male athletes', 'Male athletes typically consume high total caloric intakes to match energy expenditures, naturally providing abundant micronutrients and making them the group least likely to need routine vitamin/mineral supplementation compared to restricted-calorie dieters, pregnant women, or vegans.

• pregnant or breast feeding mothers: High nutrient demands require targeted supplementation (folate, iron).
• vegans: Require Vitamin B12 supplementation and careful monitoring of iron, zinc, and calcium.
• dieters on restricted energy intakes: Low total food volume increases micronutrient deficiency risk.', '["pregnant or breast feeding mothers","vegans","male athletes","dieters on restricted energy intakes"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:22:53.877Z"'::jsonb),
('anki-card-1757931654273-64', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'There are studies that show that sodium and potassium have roles in the regulation of*', 'blood pressure', 'Extensive clinical and epidemiological research (such as the DASH diet studies) demonstrates that dietary sodium and potassium play critical antagonist and synergistic roles in the regulation of blood pressure and vascular tone.

• blood sugar level: Regulated primarily by insulin, glucagon, and carbohydrate metabolism.
• lipid profile: Influenced by dietary fats, fiber, and caloric balance.
• blood composition: Regulated by bone marrow, kidneys, and plasma proteins.', '["blood pressure","blood sugar level","lipid profile","blood composition"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:22:59.805Z"'::jsonb),
('anki-card-1757931666221-65', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The mineral component of methionine, insulin, keratin, and glutathione is*', 'Sulfur', 'Sulfur is an essential mineral component found in the amino acids methionine and cysteine, as well as structural proteins like keratin in hair/skin and antioxidant glutathione.

• Manganese: Cofactor for arginase and mitochondrial enzymes.
• Iodine: Essential component of thyroid hormones (T3 and T4).
• Iron: Central mineral in hemoglobin and cytochromes.', '["Manganese","Iodine","Iron","Sulfur"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:09.566Z"'::jsonb),
('anki-card-1757931676839-66', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The mineral component of vitamin B12 is*', 'Cobalt', 'Vitamin B12 (cobalamin) is uniquely characterized by its chemical structure containing a central corrin ring coordinated with a cobalt atom, giving the vitamin its red color.

• Iron: The central mineral component of heme in hemoglobin and myoglobin.
• Zinc: Found in carbonic anhydrase and numerous other metalloenzymes.
• Copper: Found in ceruloplasmin and cytochrome c oxidase.', '["Iron","Zinc","Copper","Cobalt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:12:53.703Z"'::jsonb),
('anki-card-1757931689871-67', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Best type of exercise for physical conditioning is*', 'aerobic', 'Aerobic exercise (such as sustained swimming, brisk walking, or cycling) requires continuous oxygen delivery to sustain muscular energy production via oxidative phosphorylation, making it the premier type of exercise for cardiovascular and physical conditioning.

• Anaerobic: Involves high-intensity, short-duration bursts (like sprinting or heavy lifting) relying on non-oxidative energy pathways.
• Calisthenics: Bodyweight strength exercises that can have aerobic components but focus primarily on muscular endurance and strength.
• Jogging: A specific form of aerobic exercise, whereas "aerobic" is the broader category encompassing all endurance conditioning.', '["aerobic","anaerobic","calisthenics","jogging"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:11:37.374Z"'::jsonb),
('anki-card-1757931703671-68', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Under normal conditions, the pH of the blood is*', 'slightly basic', 'Under normal physiological conditions, the pH of human arterial blood is tightly regulated between 7.35 and 7.45, making it strictly slightly basic (alkaline).

• Slightly acidic: Incorrect, as a pH below 7.0 defines acidity (acidemia).
• Acidic: Incorrect because an acidic blood pH is life-threatening and termed acidosis.
• Basic: While true that it is basic, "slightly basic" is the precise physiological descriptor for the narrow 7.35–7.45 range.', '["slightly acidic","slightly basic","acidic","basic"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:11:14.713Z"'::jsonb),
('anki-card-1757931714868-69', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Muscular fatigue during strenuous physical exercise is due to the accumulation of*', 'lactic acid', 'During strenuous physical exercise when oxygen supply cannot keep up with cellular demand, muscle cells resort to anaerobic glycolysis, leading to the rapid accumulation of lactic acid (lactate), which causes muscle fatigue and burning sensations.

• Pyruvic acid: Converted into lactic acid under anaerobic conditions rather than accumulating directly as the primary fatigue agent.
• Ammonia: Produced during amino acid catabolism, but lactic acid accumulation is the classic hallmark of muscular fatigue.
• HCl: Hydrochloric acid is produced in the stomach, not in active skeletal muscle tissue.', '["pyruvic acid","ammonia","lactic acid","HCl"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:11:42.666Z"'::jsonb),
('anki-card-1757931731135-70', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Isoniazid, an anti-tuberculosis drug, is an antagonist of*', 'pyridoxine', 'Isoniazid (INH) is a primary anti-tuberculosis medication that acts as a structural antagonist to pyridoxine (Vitamin B6), frequently necessitating concurrent B6 supplementation to prevent peripheral neuropathy.

• Niacin: Affected by other specific drugs, but isoniazid specifically targets pyridoxine metabolism.
• Folic acid: Antagonized by folate pathway inhibitors like methotrexate.
• Biotin: A coenzyme for carboxylation reactions, not targeted by isoniazid.', '["niacin","pyridoxine","folic acid","biotin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:11:48.525Z"'::jsonb),
('anki-card-1757931745666-71', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'As a constituent of thiamine pyrophosphate and thiamine monophosphate, vitamin B1 is involved in themetabolism of*', 'glucose', 'Thiamine pyrophosphate (TPP) serves as an essential coenzyme for key carbohydrate-metabolizing multi-enzyme complexes—such as pyruvate dehydrogenase and alpha-ketoglutarate dehydrogenase—directly linking Vitamin B1 to cellular glucose metabolism and energy production.

• Amino acids: While involved in branched-chain amino acid catabolism, glucose metabolism is the primary pathway linked to thiamine.
• Fatty acids: Fatty acid beta-oxidation relies primarily on pantothenic acid (CoA) and riboflavin/niacin, not thiamine.
• Pentoses: Processed primarily via the pentose phosphate pathway utilizing NADPH.', '["glucose","amino acids","fatty acids","pentoses"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:11:54.340Z"'::jsonb),
('anki-card-1757931762367-72', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The most variable component of total energy requirement is*', 'energy cost of physical activities', 'While basal metabolic needs and the thermic effect of food remain relatively stable and tightly regulated day-to-day, the energy cost of physical activity is the single most variable component of total daily energy expenditure depending on lifestyle, occupation, and exercise habits.', '["basal metabolic needs","energy cost of physical activities","thermic effect of food","respiratory quotient"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:14:00.984Z"'::jsonb),
('anki-card-1757931773367-73', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The total energy of a food per 100 grams whose composition is 2% carbohydrates,18% protein, & 5% fat is*', '125 kcal', 'To calculate total energy (Atwater general factors: carbohydrate = 4 kcal/g, protein = 4 kcal/g, fat = 9 kcal/g):

Carbohydrate: 2g x 4 = 8 kcal

Protein: 18g x 4 = 72 kcal

Fat: 5g x 9 = 45 kcal

Total Energy = 8 + 72 + 45 = 125 kcal per 100 grams.', '["100 kcal","125 kcal","150 kcal","200 kcal"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:15.420Z"'::jsonb),
('anki-card-1757931788048-74', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The immediate source of energy for physical exercise is the*', 'phosphagen system consisting of stored ATP and creatine phosphate', 'The immediate, rapid-fire source of energy for high-intensity physical exercise lasting the first few seconds is the phosphagen system (ATP-PC system), utilizing immediately stored cellular ATP and creatine phosphate without requiring oxygen or glycolysis.

• anaerobic system: Refers to anaerobic glycolysis, which kicks in after the phosphagen stores deplete.
• aerobic system: Requires oxygen and takes longer to ramp up peak ATP output.
• glycogen: Stored carbohydrate fuel utilized by glycolytic pathways.', '["phosphagen system consisting of stored ATP and creatine phosphate","anaerobic system","uerobic system","glycogen"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:21.344Z"'::jsonb),
('anki-card-1757931798531-75', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The immediate need after strenuous exercise or physical activity*', 'fluid', 'The immediate nutritional and physiological priority after completing strenuous exercise or heavy physical activity is fluid replacement to rehydrate and restore blood volume lost via sweating.

• simple carbohydrates: Important for glycogen replenishment, but immediate rehydration takes physiological precedence.
• whey protein: Used for muscle repair, but secondary to immediate rehydration.
• salt: Restored via fluids and foods, but fluid is the primary immediate requirement.', '["fluid","simple carbohydrates","whey protein","salt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:27.624Z"'::jsonb),
('anki-card-1757931810747-76', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The only pentose of physiologic significance is*', 'ribose', 'Ribose is a 5-carbon monosaccharide (pentose) of vital physiological significance because it forms the structural sugar backbone of RNA, ATP, coenzymes (NAD, FAD, CoA), and nucleic acids.

• mannose: A 6-carbon aldohexose sugar.
• arabinose / xylose: Plant pentoses found in hemicellulose and gum structures, not primary human metabolic backbone sugars like ribose.', '["mannose","ribose","arabinose","xylose"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:33.438Z"'::jsonb),
('anki-card-1757931822814-77', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Vitamin D and parathyroid hormone promote*', 'calcium mobilization from the bones', 'Both active Vitamin D (calcitriol) and Parathyroid Hormone (PTH) function synergistically to raise serum calcium levels by promoting calcium mobilization from the bones (bone resorption), increasing renal calcium reabsorption, and enhancing intestinal absorption.

• calcium deposition in bones: Promoted by calcitonin, not PTH and Vitamin D.
• urinary calcium excretion: PTH actually decreases urinary calcium loss while increasing urinary phosphate excretion.
• fecal calcium excretion: Decreased by active Vitamin D via enhanced intestinal absorption.', '["calcium deposition in bones","calcium mobilization from the bones","urinary calcium excretion","fecal calcium excretion"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:39.534Z"'::jsonb),
('anki-card-1757931834697-78', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'The primary function of magnesium in metabolism is as a*', 'coenzyme or enzyme activator', 'Magnesium''s primary biochemical function in metabolism is acting as an essential coenzyme or enzymatic cofactor for over 300 enzymatic reactions, particularly those involving ATP transfer (such as kinases).

• constituent of thyroxine: That is iodine.
• constituent of tissues: While found in bone, its primary metabolic role is catalytic cofactor activity.
• fluid balance regulator: Primarily regulated by sodium, potassium, and chloride.', '["constituent of thyroxine","constituent of tissues","fluid balance regulator","coenzyme or enzyme activator"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:46.102Z"'::jsonb),
('anki-card-1757931850879-79', NULL, 'anki-deck-1783609398838-1790433146200-hye2o', 'Mechanism by which body conserves iron stores*', 'by reusing iron released in the breakdown of red blood cells', 'The human body conserves iron with extraordinary efficiency by reusing iron released from the breakdown of senescent red blood cells by macrophages in the spleen and liver, recycling nearly 90–95% of daily functional iron needs.

• by reducing iron content of hemoglobin: False; hemoglobin maintains a stable iron structure.
• by regulating release of iron in the storage tissues: Controlled by hepcidin, but conservation relies primarily on cellular iron recycling.
• by increasing mucosal absorption of iron: Intestinal absorption is a secondary variable input, whereas internal recycling is the primary conservation mechanism.', '["by reusing iron released in the breakdown of red blood cells","by reducing iron content of hemoglobin","by regulating release of iron in the storage tissues","by increasing mucosal absorption of iron"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.883Z"'::jsonb, '"2026-11-09T03:23:51.588Z"'::jsonb),
('anki-card-1756874170706-0', NULL, 'anki-deck-1783609405436-1790433139823-mldgr', 'Which of the following is not  a characteristic of a good cost control system?', 'Designed to fit all types of food service operations', 'Designed to fit all types of food service operations', '["Provides accurate, detailed, continuous data.","Designed to fit all types of food service operations","Simple to operate","Shows clear separation of duties"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:35:40.426Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756874203418-1', NULL, 'anki-deck-1783609405436-1790433139823-mldgr', 'Which statement is not true about food cost?', 'It is not manageable', 'It is not manageable', '["It is the largest single cost element in foodservice","It is a variable cost","It is subject to price fluctuation","It is not manageable"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:35:40.426Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
