('anki-card-1756875479258-55', NULL, 'anki-deck-1783609405436-1790433139823-mldgr', 'Which statement does not conform with the traditional principles of management?', 'Employees can receive orders from different bosses', 'Employees can receive orders from different bosses.', '["The interest of the organization is more important than those of any individual/group in the organization","Decision making authority should rest at the top level of the organization","The same plan should be followed for a group of activities that have the same goal or objective","Employees can receive orders from different bosses"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:35:40.426Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756875496008-56', NULL, 'anki-deck-1783609405436-1790433139823-mldgr', 'A leader who uses appropriate supportive & directive behaviors based on the situation is called a ___ leader.', 'situational', '', '["transactional","situational","flexible","transformational"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:35:40.426Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
