('anki-card-1756875619052-62', NULL, 'anki-deck-1783609405436-1790433139823-mldgr', 'Authority derived by virtue of one’s position is called _____ authority.', 'formal', '', '["informal","staff","formal","line"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:35:40.426Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
