INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1756879541906-28', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why do eggs whip better at room temperature compared to when they are taken directly from the refrigerator?', 'Because the proteins in room temperature eggs unfold more easily, allowing better foam structure.', 'Whipping creates foams by incorporating air into egg white proteins. At room temperature, lower surface tension and increased kinetic energy allow proteins to unfold (denature) rapidly and encase air bubbles more effectively than cold proteins.', '["Because room temperature eggs contain more air, which helps in foam formation.","Because the proteins in room temperature eggs unfold more easily, allowing better foam structure.","Because refrigeration adds water to the eggs, diluting the proteins needed for foaming.","Because warm eggs are heavier and create more stable peaks when beaten."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:29:16.487Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:29:16.487Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:06.696Z"'::jsonb),
('anki-card-1756879560938-29', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'What is the effect of adding an acid, such as cream of tartar or lemon juice, early in the whipping of egg whites?', 'It delays foaming but produces a more stable foam by strengthening protein structure.', 'Adding an acid (like cream of tartar) lowers the pH of whipped egg whites near their isoelectric point, which increases foam stability and prevents over-coagulation, though it slightly increases the time needed to achieve full volume.', '["It delays foaming but produces a more stable foam by strengthening protein structure.","It immediately increases foam volume but causes the foam to collapse quickly.","It prevents the egg whites from incorporating air, making whipping ineffective.","It reacts with egg white sugars to form a stiff, dry foam."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:36:03.593Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:36:03.593Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:11.945Z"'::jsonb),
('anki-card-1756879575903-30', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why do eggs demonstrate excellent binding capacity in recipes such as meatballs, croquettes, or batters?', 'Because egg proteins coagulate when heated, holding ingredients in a firm structure.', 'The heat-induced coagulation of egg proteins creates a firm thermal gel network that binds disparate ingredients together in mixtures like meatballs, loaves, and batters.', '["Because egg yolks are high in fat, which glues ingredients together.","Because egg whites contain starch that thickens and binds ingredients.","Because eggs contain sugar that caramelizes and locks ingredients in place.","Because egg proteins coagulate when heated, holding ingredients in a firm structure."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:35:54.138Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:35:54.138Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:19.417Z"'::jsonb),
('anki-card-1756879593020-31', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why does evaporated milk whip better when chilled?', 'Fat solidifies, increasing viscosity', 'Chilling evaporated milk lowers the temperature of its suspended fat droplets, causing them to solidify and cluster, which increases overall liquid viscosity and allows the emulsion to trap air when whipped.', '["Water evaporates faster","Fat solidifies, increasing viscosity","Protein denaturation occurs","Sugar crystallizes"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:27:49.762Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:27:49.762Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:25.513Z"'::jsonb),
('anki-card-1756879617985-32', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'What is the main difference between yogurt and buttermilk?', 'Yogurt uses whole or skim milk; buttermilk uses skim milk', 'While both are cultured dairy products, commercial yogurt can be manufactured using whole or skim milk fermented with specific lactic cultures, whereas traditional cultured buttermilk is derived from low-fat or skim milk.', '["Yogurt is fermented; buttermilk is not","Buttermilk has more sugar","Yogurt uses whole or skim milk; buttermilk uses skim milk","Yogurt contains more water"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:25:22.475Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:25:22.475Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:33.921Z"'::jsonb),
('anki-card-1756879635519-33', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'What is the effect of adding sugar too early during cream whipping?', 'Increases whipping time', 'Adding sugar too early in cream whipping increases the density and viscosity of the liquid phase prematurely, dampening mechanical air incorporation and significantly prolonging whipping time.', '["Increases whipping time","Helps stabilize foam","Reduces volume","Prevents curdling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:34:49.933Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:34:49.933Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:38.704Z"'::jsonb),
('anki-card-1756879659100-34', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following is the most critical factor in successfully whipping cream?', 'Cold temperature', 'Keeping cream and equipment thoroughly chilled is critical during whipping because cold temperatures maintain solid milk fat crystals, which stabilize the air-in-fat foam structure.', '["High sugar content","High lactose content","Cold temperature","Low fat content"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:35:41.637Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:35:41.637Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:45.933Z"'::jsonb),
('anki-card-1756879710347-35', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which fat content range is ideal for whipping cream?', '30–36%', 'Heavy whipping cream or whipping cream intended for stable foam production requires a milk fat content ranging between 30% and 36%.', '["10–15%","20–25%","30–36%","40–50%"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:35:33.820Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:35:33.820Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:50.340Z"'::jsonb),
('anki-card-1756879738214-36', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best describes "filled evaporated milk"?', 'Milk with vegetable fat instead of milk fat', '"Filled milk" refers to dairy products where expensive butterfat has been extracted and replaced entirely or partially with cheaper vegetable fats (such as coconut or palm oil).', '["Milk with added sugar","Milk with vegetable fat instead of milk fat","Milk with reduced lactose","Milk enriched with vitamins"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:20:58.036Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:20:58.036Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:54.208Z"'::jsonb),
('anki-card-1756879754213-37', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why is fructose considered the best sugar to prevent crystallization when cooking crystalline candies?', 'It is the hardest common sugar to crystallize, helping control texture.', 'Fructose and invert sugars interfere with sucrose crystal formation, making them highly effective in controlling crystallization and maintaining smoothness in confectionery.', '["It is less sweet than glucose, so it allows higher concentrations in solution.","It caramelizes quickly, preventing crystal formation.","It has the highest molecular weight among sugars, increasing viscosity.","It is the hardest common sugar to crystallize, helping control texture."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:05:48.193Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-07T15:05:48.193Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:39:59.435Z"'::jsonb),
('anki-card-1756879771395-38', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'How does sugar contribute to the tender texture of baked products such as cakes and cookies?', 'By competing with flour for water, slowing gluten development', 'Sugar is highly hygroscopic; in baking formulations, it competes with flour proteins for available water, effectively limiting hydration and slowing gluten network development to ensure a tender crumb.', '["By increasing the protein content of flour","By absorbing excess water from the batter","By competing with flour for water, slowing gluten development","By reacting with baking soda to produce more air"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:22:15.636Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:22:15.636Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:03.713Z"'::jsonb),
('anki-card-1756879787843-39', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following statements best explains why coconut oil is solid at room temperature, unlike most other vegetable oils?', 'It contains mostly medium-chain saturated fatty acids.', 'Unlike most plant oils dominated by long-chain unsaturated fats, coconut oil is uniquely rich in medium-chain saturated fatty acids (such as lauric acid), which raise its melting point and make it solid at room temperature.', '["It is composed mainly of long-chain polyunsaturated fatty acids.","It is high in monoglycerides, which are more stable at room temperature.","It contains mostly medium-chain saturated fatty acids.","It is rich in triglycerides with unsaturated bonds that crystallize easily."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:06:51.363Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-07T15:06:51.363Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:07.601Z"'::jsonb),
('anki-card-1756879802277-40', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which market form of fat is best suited for creaming and baking applications because of its plasticity?', 'Shortening', 'Shortening is formulated specifically to possess broad plasticity—retaining a soft, moldable solid texture across a wide temperature range—making it ideal for creaming and baking.', '["Salad oil","Table fat","Cooking oil","Shortening"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:22:43.821Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:22:43.821Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:11.714Z"'::jsonb),
('anki-card-1756879817891-41', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why is butter typically soft at room temperature compared to beef tallow?', 'It is composed of mostly unsaturated fatty acids.', 'Butter has a higher proportion of short-chain and unsaturated fatty acids compared to hard animal tallows, lowering its melting point so it remains soft at room temperature.', '["It contains smaller fat crystals.","It has undergone winterization.","It is composed of mostly unsaturated fatty acids.","It has a high smoke point."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:07:18.146Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-07T15:07:18.146Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:16.218Z"'::jsonb),
('anki-card-1756879834926-42', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why are lard, butter, margarine, and suet called shortening?', 'It coats flour particles, limiting gluten formation and "shortening" gluten strands.', 'Fats function as "shortenings" because their molecules physically coat flour particles and impede water contact, which restrains gluten development and shortens gluten strands, producing a tender baked texture.', '["It melts quickly at high temperatures, shortening the cooking time.","It increases the shelf life of baked products.","It coats flour particles, limiting gluten formation and \"shortening\" gluten strands.","It causes baked goods to rise faster by shortening proofing time."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:38:10.320Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:38:10.320Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:20.661Z"'::jsonb),
('anki-card-1756879853874-43', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'The correct classification of a bird that has been slaughtered, bled, defeathered, with head and feet removed is:', 'Dressed', 'Poultry classification standards define a "dressed" bird as one that has been slaughtered, bled, and defeathered, with the head, feet, and viscera removed (or partially dressed depending on local grading, though standard dressed poultry includes bleeding, plucking, and removal of feet/head).', '["Whole or Galantina","Dressed","Ready-to-cook","Live"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:26:04.589Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:26:04.589Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:24.826Z"'::jsonb),
('anki-card-1756879906740-44', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'A chef prepares two batches of beef stew—one simmered for 2 hours, and another simmered for only 20 minutes. Based on the effect of cooking duration on flavor, which statement best explains the difference in flavor between the two?', 'The long-cooked stew has deeper flavor because prolonged heat breaks down fat and protein into flavorful compounds.', 'Extended simmering allows slow thermal hydrolysis of connective tissues and breakdown of proteins and fats into savory amino acids and volatile flavor molecules, deepening the overall flavor profile of the stew.', '["The short-cooked stew develops more umami due to faster protein coagulation.","The long-cooked stew has deeper flavor because prolonged heat breaks down fat and protein into flavorful compounds.","The short-cooked stew retains more natural meat flavor due to minimal protein denaturation.","The long-cooked stew loses flavor because the volatile aroma compounds evaporate completely."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:27:36.042Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:27:36.042Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:29.337Z"'::jsonb),
('anki-card-1756879923687-45', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following rice types is most suitable for sticky desserts such as suman or biko?', 'Waxy rice (malagkit), because it has virtually no amylose and becomes sticky when cooked.', 'Waxy rice (malagkit) contains almost 100% amylopectin and virtually zero amylose, causing the grains to bind together and form a sticky, cohesive texture upon cooking, ideal for native desserts.', '["IR 8, because it has high amylose content and remains separate when cooked.","Milagrosa, because it has intermediate amylose content and a soft texture.","Waxy rice (malagkit), because it has virtually no amylose and becomes sticky when cooked.","Basmati, because it is aromatic and elongates on cooking."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:17:36.937Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:17:36.937Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:34.803Z"'::jsonb),
('anki-card-1756879940519-46', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'A student wanted to cook champorado with a thick consistency. She used a 2:1 water-to-rice ratio and added milk and sugar at the beginning of cooking. The final product turned out thick but slightly undercooked. What is the most likely reason for the undercooked texture?', 'Sugar and milk were added too early, delaying gelatinization.', 'Adding sugar and milk at the very beginning of cooking increases osmotic pressure and coats starch granules, restricting water penetration and delaying starch gelatinization, which leaves the rice grains undercooked.', '["She used too much water for champorado.","Sugar and milk were added too early, delaying gelatinization.","The rice was over-agitated during cooking.","She should have used cold water instead of hot water."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:18:17.998Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:18:17.998Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:38.632Z"'::jsonb),
('anki-card-1756879956687-47', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following will result in a fluffy and separate-grained texture when cooking rice?', 'Starting with hot water and using the correct rice-to-water ratio', 'Using the correct water-to-rice ratio and adding rice to boiling water speeds initial starch gelatinization and prevents prolonged water logging, resulting in fluffy, separate grains.', '["Using more water and starting with cold water","Soaking the rice and using hard water","Starting with hot water and using the correct rice-to-water ratio","Stirring rice frequently during cooking"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:21:34.330Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:21:34.330Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:42.958Z"'::jsonb),
('anki-card-1756879971453-48', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Brown rice is considered more nutritious than white rice primarily because:', 'It is milled with only the hull removed, retaining the bran and germ.', 'Brown rice is a whole grain where only the outermost inedible hull is removed, leaving behind the nutrient-dense bran and germ layers that contain higher concentrations of vitamins, minerals, and fiber.', '["It is a processed cereal.","It contains added nutrients.","It is milled with only the hull removed, retaining the bran and germ.","It is highly milled and polished for easy digestion."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:33:32.639Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:33:32.639Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:40:46.322Z"'::jsonb),
('anki-card-1756879992684-49', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following functional properties of starch is most responsible for the firming of custards and pie fillings after cooling?', 'Retrogradation', 'Retrogradation is the process where dissociated amylose molecules in a cooked starch paste realign and associate together into an ordered, crystalline structure as the product cools, responsible for the firming, setting, and staling of custards, gravies, and pie fillings.', '["Viscosity","Gelatinization","Retrogradation","Gel formation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:06:37.005Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-07T15:06:37.005Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:42:33.014Z"'::jsonb),
('anki-card-1756880008751-50', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best explains why waxy starches are preferred in products requiring freeze-thaw stability (e.g., frozen pie fillings)?', 'They swell less during gelatinization', '', '["They contain high amylose content","They are resistant to syneresis due to high amylopectin","They swell less during gelatinization","They retrograde faster"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:06:43.935Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-07T15:06:43.935Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-07T15:06:43.935Z"'::jsonb),
('anki-card-1756880033217-51', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why does continuous stirring during the cooking of starch mixtures lead to a pasty consistency?', 'It breaks down starch granules, releasing more amylose', 'Continuous, vigorous stirring of a gelatinizing starch paste mechanically shears and ruptures the swollen starch granules, freeing encapsulated amylose chains into the liquid medium and altering the smooth viscosity into a sticky, pasty consistency.', '["It enhances retrogradation","It causes over-gelatinization","It breaks down starch granules, releasing more amylose","It prevents starch swelling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:40:46.223Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:40:46.223Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:42:44.072Z"'::jsonb),
('anki-card-1756880052047-52', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'In which food product is starch primarily used for its moisture-retention properties?', 'Bread', 'Starch is incorporated into commercial baked bread formulations primarily for its exceptional water-binding and moisture-retention properties, which prevent staling and keep the crumb soft.', '["Pudding","Bread","Jelly","Peanut butter"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:27:24.379Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:27:24.379Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:45:38.764Z"'::jsonb),
('anki-card-1756880067830-53', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following situations will most likely result in a firmer gel during starch gelatinization?', 'Using milk and eggs with minimal stirring', 'Gentle handling and minimal agitation prevent the mechanical rupture of starch granules while allowing milk proteins and egg colloids to coagulate smoothly with starch, creating a firm, cohesive gel structure.', '["Adding sugar and acid before heating","Cooking with direct heat and stirring continuously","Using milk and eggs with minimal stirring","Using low starch concentration and high agitation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:04:58.648Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-07T15:04:58.648Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:42:48.107Z"'::jsonb),
('anki-card-1756880083064-54', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'A baker notices that her muffins have developed large tunnels and a tough texture. Which factor most likely caused this issue?', 'Overmixing the batter using the muffin method', 'Overmixing muffin batter develops excessive gluten networks in the flour and incorporates too much air into tunnels, resulting in tough, peaked muffins with large interior air tunnels.', '["Using soft wheat flour instead of hard wheat flour","Undermixing the batter during preparation","Overmixing the batter using the muffin method","Using cake flour instead of all-purpose flour"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:39:12.532Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:39:12.532Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:42:52.819Z"'::jsonb),
('anki-card-1756880103597-55', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'A cook preparing popovers follows the correct flour-liquid ratio but ends up with flat and soggy results. Which of the following is the most likely factor affecting the product quality?', 'Incorrect oven temperature or improper placement in the oven', 'Popovers rely entirely on rapid steam generation from high initial oven heat to expand their hollow structure. Incorrect oven temperatures or poor placement prevent proper rapid leavening, yielding flat and soggy results despite correct ingredient ratios.', '["Use of soft wheat flour instead of hard flour","Use of the pastry method instead of the straight dough method","Incorrect oven temperature or improper placement in the oven","Use of stainless steel pans instead of glass pans"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:31:48.760Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:31:48.760Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:42:57.237Z"'::jsonb),
('anki-card-1756880120277-56', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following combinations would most likely delay gluten development in a flour mixture?', 'All-purpose flour, sugar, fat, and lemon juice', 'Sugar competes for water hydration, fat coats flour particles to shorten gluten strands, and acid (lemon juice) lowers pH, all of which act synergistically to inhibit and delay gluten development.', '["Bread flour, water, and yeast","Cake flour, water, and salt","All-purpose flour, sugar, fat, and lemon juice","High-protein flour and vigorous kneading"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:05:54.482Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-07T15:05:54.482Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:01.858Z"'::jsonb),
('anki-card-1756880137612-57', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'In which scenario will yeast activity be compromised, affecting the leavening process of bread?', 'Using active dry yeast at 42°C', 'Active dry yeast is sensitive to excessive thermal stress; temperatures at or above 42°C (108°F) begin to thermally damage and kill the yeast cells, destroying their leavening capacity.', '["Using active dry yeast at 42°C","Using compressed yeast stored at 5°C","Using quick-rising yeast at room temperature","Using active dry yeast in water at 25°C"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:18:59.523Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:18:59.523Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:06.899Z"'::jsonb),
('anki-card-1756880155093-58', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following combinations would most likely result in a dense and poorly risen cake, assuming all other factors are constant?', 'Bread flour, baking soda, no acidic ingredient', 'Baking soda (sodium bicarbonate) requires an acidic ingredient to neutralize it and release carbon dioxide leavening gas. Without acid, baking soda fails to leaven and leaves an unpalatable soapy taste, resulting in a dense, poorly risen product when paired with high-protein bread flour.', '["Bread flour, baking soda, no acidic ingredient","Cake flour, baking soda, lemon juice","All-purpose flour, baking powder, milk","All-purpose flour, baking powder, vinegar"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:23:11.887Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:23:11.887Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:10.584Z"'::jsonb),
('anki-card-1756880170726-59', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best explains why fat is referred to as a "shortening" in flour mixtures?', 'It interrupts gluten formation by coating flour particles.', 'Fats act as "shorteners" because fat molecules physically coat protein and starch particles, blocking water access and physically interrupting the formation of continuous gluten strands, producing a tender crumb.', '["It shortens the baking time of products.","It prevents sugar from dissolving quickly.","It enhances the hydration of starch.","It interrupts gluten formation by coating flour particles."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:19:08.591Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:19:08.591Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:15.463Z"'::jsonb),
('anki-card-1756880190126-60', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best explains the purpose of punching down dough after its initial fermentation in bread making?', 'To expel carbon dioxide, redistribute yeast, and develop gluten elasticity', 'Punching down fermented dough releases trapped carbon dioxide gas, equalizes temperature and nutrients for the yeast cells, and stretches the gluten strands to improve elasticity and grain structure.', '["To kill excess yeast and prevent over-fermentation","To increase the dough’s volume through added air","To enhance crust browning and accelerate proofing","To expel carbon dioxide, redistribute yeast, and develop gluten elasticity"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:24:41.346Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:24:41.346Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:19.319Z"'::jsonb),
('anki-card-1756880205109-61', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'In foam cakes like angel or chiffon cake, why is cream of tartar commonly added to beaten egg whites?', 'To stabilize the foam structure during whipping', 'Cream of tartar is an acid salt that lowers pH, strengthening the protein films around air cells in whipped egg whites to prevent premature collapse and produce a stable foam.', '["To sweeten the batter","To stabilize the foam structure during whipping","To enhance gluten development","To prevent coagulation of egg proteins"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:05:07.382Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-07T15:05:07.382Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:24.233Z"'::jsonb),
('anki-card-1756880221891-62', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why is the folding method essential in making sponge and angel food cakes?', 'Folding helps retain the air incorporated in beaten egg foams, maintaining cake volume.', 'Folding is a gentle, circular cutting-and-turning motion that incorporates whipped egg foams into heavy batters without popping the trapped air bubbles, preserving leavening volume in sponge and angel food cakes.', '["Folding helps retain the air incorporated in beaten egg foams, maintaining cake volume.","Folding reduces fat clumping in the batter.","Folding incorporates more liquid into the batter to improve structure.","Folding dissolves sugar evenly throughout the batter."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:38:21.843Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:38:21.843Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:27.682Z"'::jsonb),
('anki-card-1756880238341-63', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which mixing method for shortened cakes is best for achieving a tender crumb with fine texture and good volume?', 'Conventional Method – because it incorporates air through creaming and alternates dry and liquid ingredients', 'The conventional (creaming) method creams fat and sugar to incorporate microscopic air cells, then alternates dry and liquid additions, yielding a fine, tender crumb and excellent volume in shortened cakes.', '["Muffin Method – because it limits gluten development through minimal mixing","One-Bowl Method – because it uses all-purpose flour and mixes all ingredients quickly","Conventional Method – because it incorporates air through creaming and alternates dry and liquid ingredients","Sponge Method – because it separates eggs and beats whites to a foam before folding"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:17:53.136Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:17:53.136Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:33.570Z"'::jsonb),
('anki-card-1756880255556-64', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best describes the correct mixing sequence for preparing a chiffon cake?', 'Beat egg whites with sugar; mix egg yolks, oil, and liquid with dry ingredients; fold in the beaten egg whites.', 'Chiffon cakes combine conventional batter principles (using oil as a liquid fat) with a meringue foam, requiring yolks, oil, liquid, and flour to be mixed first, followed by gently folding in separately whipped egg-white meringues.', '["Beat egg whites with sugar; mix egg yolks, oil, and liquid with dry ingredients; fold in the beaten egg whites.","Beat egg yolks with sugar; add oil and liquid; beat egg whites separately and mix everything at once.","Mix all dry ingredients; add whole eggs and oil; beat until smooth.","Beat egg whites and yolks together with sugar; add oil and liquid, then stir in dry ingredients."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T15:07:13.020Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-07T15:07:13.020Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:38.958Z"'::jsonb),
('anki-card-1756880271439-65', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following statements best explains why foam cakes are baked in ungreased pans and inverted during cooling?', 'Foam cakes need to cling to the sides of the pan during rising, and inverting prevents collapse while cooling', 'Foam cakes lack fat to provide structural shortening, relying instead on a delicate foam structure that must cling to ungreased pan walls to rise fully. Inverting the pan during cooling prevents the heavy center from collapsing under its own weight.', '["Ungreased pans allow even heat distribution and inverting keeps the crust soft.","Greasing the pan adds moisture, and inverting traps steam.","Ungreased pans create a crusty exterior, and inverting enhances flavor.","Foam cakes need to cling to the sides of the pan during rising, and inverting prevents collapse while cooling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:19:57.456Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:19:57.456Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:42.916Z"'::jsonb),
('anki-card-1756880322637-66', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best explains why cold water is essential when preparing pastry dough?', 'It helps keep fat solid, promoting flakiness', 'Cold water keeps solid fat particles intact within the pastry dough. When baked, these solid fat pockets melt and release steam, creating distinct air pockets that produce a flaky crust texture.', '["It evaporates quickly, helping in leavening","It activates gluten formation for better structure","It helps keep fat solid, promoting flakiness","It adds moisture for a chewy texture"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:32:33.401Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:32:33.401Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:46.986Z"'::jsonb),
('anki-card-1756880340084-67', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which of the following best explains why agar-agar can gel with raw pineapple, while gelatin cannot?', 'Agar-agar is a carbohydrate and is not affected by proteolytic enzymes like bromelin.', 'Raw pineapple contains bromelain, a proteolytic enzyme that breaks down protein-based gels like animal gelatin. Agar-agar is a polysaccharide carbohydrate extracted from seaweed and is completely immune to enzymatic breakdown by bromelain.', '["Agar-agar is a protein that resists enzymatic breakdown.","Agar-agar forms gels at higher temperatures than gelatin.","Agar-agar is a carbohydrate and is not affected by proteolytic enzymes like bromelin.","Agar-agar forms clearer gels, making it more stable with pineapple."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:30:43.256Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:30:43.256Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:51.071Z"'::jsonb),
('anki-card-1756880358035-68', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why is agitation important during the freezing of ice cream?', 'It incorporates air and promotes the formation of small ice crystals', 'Continuous churning (agitation) during ice cream freezing whips air into the mixture (overrun) while constantly breaking up growing ice crystals, ensuring a smooth, creamy texture with small crystals.', '["It prevents sugar from concentrating","It equalizes salt and ice ratios in the mixture","It incorporates air and promotes the formation of small ice crystals","It raises the temperature inside the freezing can"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:39:51.796Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:39:51.796Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:43:56.103Z"'::jsonb),
('anki-card-1756880372749-69', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Both coffee and tea are regarded as stimulating beverages. Which of the following best explains the physiological basis for this classification?', 'They contain caffeine, a central nervous system stimulant that enhances alertness and reduces fatigue', 'Coffee and tea derive their stimulating properties primarily from naturally occurring methylxanthines like caffeine, which acts as a central nervous system stimulant to block adenosine receptors and reduce fatigue.', '["Both contain tannins, which directly stimulate brain activity.","They are brewed from roasted seeds and leaves, which increase metabolism regardless of content.","Their natural sugars provide an immediate energy boost that stimulates the body.","They contain caffeine, a central nervous system stimulant that enhances alertness and reduces fatigue"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:32:49.286Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:32:49.286Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:00.410Z"'::jsonb),
('anki-card-1756880388916-70', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'A roaster aims to create a balanced coffee blend that offers rich aroma, moderate acidity, and a slightly stronger caffeine kick without overpowering bitterness. Which blend composition is most appropriate?', '70% Arabica, 30% Robusta', 'Blending Arabica (prized for superior aroma and acidity) with Robusta (providing body, crema, and a stronger caffeine kick) creates a balanced, robust espresso and coffee profile.', '["100% Arabica","70% Arabica, 30% Robusta","50% Arabica, 50% Liberica","100% Robusta"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:38:45.801Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:38:45.801Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:05.051Z"'::jsonb),
('anki-card-1756880447981-71', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why is cocoa often mixed with sugar before adding to liquids during preparation?', 'To prevent cocoa from forming lumps when mixed with liquid.', 'Natural cocoa powder contains fine particles that clump tightly when exposed to water due to surface tension. Mixing dry cocoa with sugar first separates the particles physically, allowing smooth dispersion into liquids.', '["To enhance the sweetness and chocolate flavor.","To prevent cocoa from forming lumps when mixed with liquid.","To reduce the bitterness of cocoa during boiling.","To allow the sugar to caramelize and thicken the drink."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:40:15.387Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:40:15.387Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:08.823Z"'::jsonb),
('anki-card-1756880464695-72', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'What is the main principle in preparing both tea and coffee?', 'To extract the maximum amount of flavoring substances and minimal bitter tannins.', 'Brewing parameters for tea and coffee are designed to extract desirable volatile aromatic oils and soluble flavors while minimizing the extraction of bitter, astringent tannins.', '["To dissolve all components including oils and tannins for full-bodied taste.","To extract the maximum amount of flavoring substances and minimal bitter tannins.","To always use boiling water for a stronger taste.","To add milk and sugar for balanced flavor."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:32:19.763Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:32:19.763Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:12.827Z"'::jsonb),
('anki-card-1756880481663-73', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Why should a teapot be scalded before brewing tea?', 'To warm the pot and ensure optimal extraction of flavor compounds', 'Scalding the teapot prevents the hot brewing water from dropping in temperature upon contact with cold ceramic walls, ensuring a consistent, optimal brewing temperature for flavor extraction.', '["To sterilize the pot for food safety.","To prevent caffeine from reacting with metal.","To warm the pot and ensure optimal extraction of flavor compounds","To dissolve tannins and reduce bitterness."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:39:58.441Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:39:58.441Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:17.577Z"'::jsonb),
('anki-card-1756880505744-74', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'A recipe calls for 1 tablespoon of coarse salt, but you only have fine salt. What principle should guide your adjustment?', 'Use less fine salt because it is denser and packs more per spoonful', 'Fine table salt grains pack tightly together in a measuring spoon compared to flaky or coarse salt, meaning a spoonful of fine salt contains more sodium chloride by weight and requires downward adjustment.', '["Use the same amount, as salt type doesn’t affect salinity","Use more fine salt to match flavor intensity","Use less fine salt because it is denser and packs more per spoonful","Replace it with soy sauce for similar saltiness"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:24:48.798Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:24:48.798Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:22.754Z"'::jsonb),
('anki-card-1756880523378-75', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'What is the classification of tanglad (lemongrass) and siling labuyo (bird’s eye chili)?', 'Tanglad is an herb, and siling labuyo is a spice because of the plant parts used', 'In culinary classification, leafy green plants used for flavoring (such as tanglad or lemongrass) are classified as herbs, whereas dried seeds, fruits, roots, or pods (such as siling labuyo pepper fruits) are classified as spices.', '["Both are herbs because they are from plants and used for flavor","Tanglad is a spice, and siling labuyo is an herb because it is spicy","Tanglad is an herb, and siling labuyo is a spice because of the plant parts used","Both are spices because they are often used in stews and traditional recipes"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:31:35.665Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:31:35.665Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:27.188Z"'::jsonb),
('anki-card-1756880535476-76', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'Which seasoning would be most appropriate to reduce bitterness in a vegetable stir-fry without masking the natural flavors?', 'Sugar', 'A small amount of sweetness (sugar) acts as a physical flavor balancer that effectively rounds out and masks sharp or bitter notes in vegetable dishes without altering their natural flavor profile.', '["Soy sauce","Sugar","Vinegar","Salt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:18:00.506Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:18:00.506Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:31.842Z"'::jsonb),
('anki-card-1756880552043-77', NULL, 'anki-deck-1783609411469-1790433139866-aqx4l', 'A chef finds that their stew is too salty. Which of the following is the most effective seasoning-related fix without diluting flavor too much?', 'Add vinegar or lemon juice', 'Acidic ingredients (like vinegar or lemon juice) brighten flavors and counteract excess saltiness on the palate by stimulating acid taste receptors, effectively balancing an over-salted dish.', '["Add more salt to mask the taste","Add vinegar or lemon juice","Add a sweet ingredient like honey","Add more water to dilute the salt"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-08T14:41:18.627Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-07T14:41:18.627Z"'::jsonb, '"2026-09-26T14:32:29.986Z"'::jsonb, '"2026-11-09T12:44:35.397Z"'::jsonb)
