INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757825963907-92', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Women with pregnancies complicated with diabetes:', 'Need the same number of calories to support the pregnancy as women without diabetes', 'Pregnant women with pre-existing or gestational diabetes generally need the same number of calories to support a healthy gestational weight gain as pregnant women without diabetes, focusing instead on strict carbohydrate distribution and glycemic control.', '["Need the same number of calories to support the pregnancy as women without diabetes","Need more CHO than healthy women","Need more CHO than women with diabetes who are not pregnant","Should not eat a snack at bedtime"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-11-09T06:49:28.803Z"'::jsonb),
('anki-card-1757825984773-93', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'It is used to promote fluid and sodium excretion to prevent hypertension', 'Diuretics', 'Diuretics (water pills) are pharmacological agents utilized in hypertension management to promote renal fluid and sodium excretion, thereby reducing blood volume and lowering blood pressure.', '["Beta-blockers","Statins","Insulin","Diuretics"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-11-09T06:49:34.288Z"'::jsonb),
('anki-card-1757826011189-94', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'The dumping syndrome:
i. Follows a gastrectomy
ii. Is secondary to CHO overload
iii. Draws fluids in the intestines
iv. Needs a high CHO diet', 'i, ii, iii', 'Dumping syndrome follows a gastric surgery (i), is secondary to a rapid hyperosmolar carbohydrate load (ii), and draws massive extracellular fluid into the intestinal lumen (iii), making statements i, ii, and iii correct.', '["i, iii, iv","i","ii, iii, iv","i, ii, iii"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-11-09T06:49:42.479Z"'::jsonb),
('anki-card-1757826039371-95', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following is not a sign of marasmus?', 'Edema', 'Marasmus is characterized by severe energy deficiency resulting in extreme wasting, emaciation, and weight loss without the hallmark pitting edema seen in Kwashiorkor, making edema the correct exception.', '["Low anthropometric measurement","Severe protein and caloric wasting","Edema","Weight loss"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-11-09T06:49:45.903Z"'::jsonb),
('anki-card-1757826057921-96', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Health care professionals can use all of the following reasons for anthropometric measurements in nutritional assessment
except:', 'To evaluate functional status of organs', 'Anthropometric measurements evaluate body composition, growth, and nutritional status (undernutrition/overnutrition), but cannot directly evaluate internal organ functional status (which requires biochemical panels or imaging).

• To evaluate growth in pregnant women and children / To detect undernutrition and overnutrition / To measure changes in body composition over time: Valid clinical applications of anthropometry.', '["To evaluate growth in pregnant and children","To detect undernutrition and overnutrition","To evaluate functional status of organs","To measure changes in body composition over time"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-11-09T07:15:22.365Z"'::jsonb),
('anki-card-1757826085486-97', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Cytokines are proteins that:', 'Orchestrate the inflammatory response to stress', 'Cytokines are signaling protein molecules released by immune cells that act as key chemical mediators to orchestrate and regulate the systemic inflammatory response to stress and injury.

• Destroy microorganisms: Carried out by phagocytes and antibodies, not cytokines directly.
• Repair damaged tissues: Driven by growth factors and fibroblasts.
• Oppose insulin’s action: Counter-regulatory hormones (cortisol, catecholamines) drive catabolism, whereas cytokines act as signaling regulators.', '["Orchestrate the inflammatory response to stress","Destroy microorganisms","Repair damaged tissues","Oppose insulin’s action and result in the catabolism of protein in skeletal muscle, connective tissue and the gut"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-11-09T07:14:54.998Z"'::jsonb),
('anki-card-1757826104468-98', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'A child with AIDS needs a high calorie and ____ intake:', 'High protein', 'Children with HIV/AIDS experience hypermetabolic wasting, requiring a diet high in calories and high protein to support immune function and tissue repletion.

• Low residue: Prescribed for acute diarrhea or bowel obstructions.
• Megadose vitamins: Unnecessary and potentially toxic; balanced nutritional support is preferred.
• Low fat: Contraindicated unless severe fat malabsorption is present.', '["Low residue","Megadose vitamins","High protein","Low fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-11-09T07:15:01.105Z"'::jsonb),
('anki-card-1757826158366-99', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following hormones is produced in the α-cells of the pancreas?', 'Cortisol', '', '["Growth hormone","Cortisol","Glucagon","Insulin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.725Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757826183865-100', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following carries genetic information?', 'nucleic acid', 'Nucleic acids (DNA and RNA) are the biomolecules specifically structured to store, encode, and carry genetic information across generations.

• Protein: Encoded by genes, but structural/functional in execution.
• Triglyceride / Starch: Energy storage molecules.', '["protein","starch","nucleic acid","triglyceride"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:39:56.076Z"'::jsonb),
('anki-card-1757826200647-101', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following is the most abundant form of stored energy in humans?', 'triglyceride', 'Triglycerides stored in adipose tissue represent the most concentrated, abundant, and primary form of long-term stored energy in humans (yielding roughly 9 kcal/g).', '["protein","starch","nucleic acid","triglyceride"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:40:02.439Z"'::jsonb),
('anki-card-1757826233297-102', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following is a simple sugar?', 'galactose', 'Galactose is a simple monosaccharide (a hexose sugar) that combines with glucose to form lactose.

• Maltose / Sucrose / Lactose: These are disaccharides composed of two monosaccharide units.', '["galactose","maltose","sucrose","lactose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:40:07.127Z"'::jsonb),
('anki-card-1757826250294-103', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is the molecular formula for glucose?', 'C6 H12 O6', 'The molecular chemical formula for the simple hexose monosaccharide glucose is C₆H₁₂O₆.', '["C H3 OH","C6 H12 O6","C O2","C12 H22 O11"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:40:11.113Z"'::jsonb),
('anki-card-1757826265429-104', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following is a non-reducing sugar?', 'sucrose', 'Sucrose (table sugar) is a disaccharide featuring an alpha-D-glucopyranosyl and beta-D-fructofuranosyl unit linked through their anomeric carbons, making it a non-reducing sugar because both reducing ends are tied up in the glycosidic bond.', '["glucose","sucrose","galactose","maltose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:40:16.288Z"'::jsonb),
('anki-card-1757826284394-105', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is an example of a 5-carbon sugar?', 'ribose', 'Ribose is a classic 5-carbon monosaccharide (pentose sugar) that forms the backbone of RNA nucleotides and ATP.', '["ribose","glucose","fructose","sucrose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:40:21.879Z"'::jsonb),
('anki-card-1757826385341-106', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Of what elements are carbohydrates composed?', 'C, H & O', 'Carbohydrates are organic biomolecules composed exclusively of three chemical elements: Carbon, Hydrogen, and Oxygen (with hydrogen and oxygen typically in a 2:1 ratio).', '["C, H & O","C, H & N","C, H, O & N","C, H, O, & S"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:49:50.901Z"'::jsonb),
('anki-card-1757826405072-107', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is a long chain of sugar molecules?', 'Polysaccharide', 'A long chain of sugar monosaccharide molecules linked together by glycosidic bonds is termed a polysaccharide (such as starch, glycogen, or cellulose).', '["Lipid","Polypeptide","Polysaccharide","Protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:49:54.775Z"'::jsonb),
('anki-card-1757826423620-108', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is the principal carbohydrate storage product in animals?', 'Glycogen', 'Glycogen is the principal complex carbohydrate storage polysaccharide in animals and humans, synthesized primarily and stored within the liver and skeletal muscle tissues.

• Cellulose / Starch: Structural and storage polysaccharides found in plants.
• Protein: A nitrogenous macronutrient, not a carbohydrate storage product.', '["Cellulose","Glycogen","Starch","Protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:53:42.253Z"'::jsonb),
('anki-card-1757826440521-109', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Maltose is composed of which two simple sugars?', '2 glucose', 'Maltose (malt sugar) is a disaccharide composed of two linked glucose molecules resulting from the partial hydrolysis of starches.

• 2 fructose / glucose and fructose / glucose and galactose: These alternate combinations yield other disaccharides like sucrose or lactose, not maltose.', '["2 glucose","2 fructose","glucose and fructose","glucose and galactose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:04:33.116Z"'::jsonb),
('anki-card-1757826458587-110', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is the saccharide milk sugar called?', 'lactose', 'Lactose is the primary disaccharide sugar naturally present in milk, composed of glucose and galactose.

• Galactose / Glucose / Dextrose: These are simple monosaccharide building blocks, whereas lactose is the intact milk disaccharide.', '["galactose","glucose","dextrose","lactose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:04:39.470Z"'::jsonb),
('anki-card-1757826478418-111', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What kind of sugars are found in the disaccharide sucrose?', 'glucose and fructose', 'Sucrose (table sugar) is a disaccharide composed of one glucose molecule and one fructose molecule linked together.

• Fructose and galactose / 2 glucose / 2 fructose: These configurations do not form standard table sugar.', '["fructose and galactose","2 glucose","glucose and fructose","2 fructose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:04:45.857Z"'::jsonb),
('anki-card-1757826503818-112', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is the principal carbohydrate storage product in plants?', 'glycogen', '', '["cellulose","glycogen","starch","glucose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757826519750-113', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'How is glucose stored in animals?', 'As glycogen in liver and muscles', 'Carbohydrates are stored in animals and humans in the form of glycogen distributed within the liver and skeletal muscles.

• As dextrose in pancreas: Incorrect; glucose circulates in blood and is not stored as dextrose in pancreatic tissue.
• As protein and cellulite in adipose tissue: Incorrect; adipose tissue stores triglycerides.
• As cellulose in thighs and abdominal cavity: Incorrect; cellulose is exclusively found in plants.', '["As dextrose in pancreas","As protein and cellulite in adipose tissue","As cellulose in thighs and abdominal cavity","As glycogen in liver and muscles"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:05:09.438Z"'::jsonb),
('anki-card-1757826539483-114', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'When digesting a complex carbohydrate, water is added and simple sugars are obtained through which process?', 'hydrolysis', 'When digesting complex carbohydrates into simple sugars, water is consumed to cleave the glycosidic bonds through the chemical process of hydrolysis.

• Dehydration / Condensation: Chemical processes that remove water to build larger polymers.
• Photosynthesis: The plant process converting light energy into chemical glucose.', '["dehydration","hydrolysis","condensation","photosynthesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:05:16.451Z"'::jsonb),
('anki-card-1757826561515-115', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which carbohydrate is a long unbranched chain of beta-glucose molecules, which is indigestible to humans?', 'cellulose', 'Cellulose is a long, unbranched structural polysaccharide composed of beta-1,4-linked glucose molecules that human digestive enzymes cannot break down, serving as dietary fiber.

• Lactose: A digestible milk disaccharide.
• Glycogen: A highly branched alpha-glucose polymer stored in animals.
• Starch: Contains digestible alpha-linkages.', '["cellulose","lactose","glycogen","starch"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:05:23.971Z"'::jsonb),
('anki-card-1757826581098-116', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of these is a pentasaccharide sugar?', 'verbascose', 'Verbascose is a well-known plant-derived pentasaccharide (composed of five monosaccharide units found in legumes).

• Stachyose: A tetrasaccharide containing four units.
• Raffinose: A trisaccharide containing three units.
• Threose: A simple monosaccharide (tetrose).', '["verbascose","stachyose","raffinose","threose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:05:31.372Z"'::jsonb),
('anki-card-1757826607197-117', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What molecules are the building blocks of proteins?', 'amino acids', 'Amino acids serve as the fundamental organic building blocks (monomers) that link together via peptide bonds to form proteins.

• Fatty acids: Building blocks of lipids and fats.
• Sugars: Building blocks of carbohydrates.
• Disaccharides: Double sugars made of two monosaccharides.', '["amino acids","fatty acids","sugars","disaccharides"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:05:39.836Z"'::jsonb),
('anki-card-1757826625046-118', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is the name of 2 amino acids bonded together?', 'dipeptide', 'A molecule formed by exactly 2 amino acids bonded together through a single peptide bond is called a dipeptide.

• Alanine: A specific single amino acid, not a general term for two bonded amino acids.
• Disaccharide: Refers to bonded sugars, not amino acids.
• Protein: Refers to massive polypeptide chains containing many amino acids.', '["alanine","disaccharide","dipeptide","protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:05:47.458Z"'::jsonb),
('anki-card-1757826688075-119', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is the protein found in human hair and finger nails, as well as in hooves, horns, claws and bird beaks?', 'keratin', 'Keratin is a tough, fibrous structural protein found extensively in human hair, fingernails, skin, as well as animal hooves, horns, claws, and bird beaks.

• Cellulite: A descriptive term for subcutaneous fat deposits under the skin.
• Collagen: The primary structural connective tissue protein found in tendons, skin, and bones.
• Glycogen: A carbohydrate storage molecule, not a protein.', '["keratin","cellulite","collagen","glycogen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:05:56.248Z"'::jsonb),
('anki-card-1757829258492-120', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following amino acids is the smallest of all amino acids?', 'glycine', 'Glycine is the simplest and smallest of all 20 standard amino acids, possessing a single hydrogen atom as its side chain (R-group).

• Alanine: Features a methyl group side chain, making it larger than glycine.
• Valine: A bulky branched-chain amino acid.
• Serine: Contains a polar hydroxyl group side chain.', '["alanine","valine","serine","glycine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:06:03.122Z"'::jsonb),
('anki-card-1757829276640-121', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following amino acids can form a special covalent bond called a disulfide bond?', 'cysteine', 'Cysteine is a sulfur-containing amino acid characterized by a reactive thiol (-SH) group that enables it to form strong covalent disulfide bonds (disulfide bridges) critical for stabilizing protein tertiary and quaternary structures.

• Tyrosine: An aromatic amino acid containing a phenolic ring.
• Methionine: Contains a sulfur atom, but does not form covalent disulfide bridges like cysteine.
• Lysine: A basic amino acid with an amino-bearing side chain.', '["tyrosine","methionine","cysteine","lysine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:06:10.314Z"'::jsonb),
('anki-card-1757829296723-122', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following amino acids is an imino acid?', 'tryptophan', '', '["alanine","tryptophan","proline","glutamic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757829314991-123', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following is a basic amino acid with a positive charge?', 'lysine', 'Lysine is a basic, positively charged essential amino acid bearing an amino group on its aliphatic side chain.

• Glutamic acid: An acidic amino acid carrying a negative charge at physiological pH.
• Tryptophan: A neutral, hydrophobic aromatic amino acid.
• Glutamine: A neutral, polar amide amino acid.', '["lysine","glutamic acid","tryptophan","glutamine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:06:24.873Z"'::jsonb),
('anki-card-1757829344622-124', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following amino acids’ side chains is a single methyl group?', 'alanine', 'Alanine is a simple neutral amino acid whose side chain consists solely of a single hydrophobic methyl group (-CH₃).

• Valine: Features an isopropyl side chain.
• Leucine: Features an isobutyl side chain.
• Isoleucine: Features a branched sec-butyl side chain.', '["valine","leucine","isoleucine","alanine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:06:31.582Z"'::jsonb),
('anki-card-1757829363254-125', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following is a branched-chain amino acid?', 'lysine', '', '["alanine","isoleucine","lysine","glutamine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:06:44.568Z"'::jsonb),
('anki-card-1757829383920-126', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'It is widely known that the building blocks of protein are amino acids. What reaction allows several amino acids to join together
to form a protein?', 'condensation reaction', 'Amino acids join together to form polypeptide chains through condensation reactions (dehydration synthesis), where a molecule of water is released as each peptide bond forms.

• Hydrolysis: Breaks chemical bonds by consuming water.
• Evaporation reaction: A physical phase change, not a protein synthesis reaction.
• Hydrogenation: Adds hydrogen across double bonds in fats.', '["hydrolysis","condensation reaction","evaporation reaction","hydrogenation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:06:52.727Z"'::jsonb),
('anki-card-1757829405586-127', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which if the following is a conditionally essential amino acid?', 'tyrosine', 'Tyrosine is classified as a conditionally essential amino acid because the body can synthesize it from the essential amino acid phenylalanine when dietary supplies are adequate.

• Isoleucine / Valine: Strictly essential amino acids.
• Histidine: An essential amino acid (conditionally essential in infants).', '["tyrosine","isoleucine","valine","histidine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:06:59.952Z"'::jsonb),
('anki-card-1757829424785-128', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'When using a Biuret’s test, which macromolecule will produce a positive reaction?', 'protein', 'The Biuret test is a chemical assay used to detect peptide bonds, producing a purple colorimetric positive reaction when proteins or short peptides are present.

• Fat: Tested using Sudan IV or emulsification tests, not Biuret.
• Carbohydrate: Tested using Benedict''s or iodine assays.
• All three: Incorrect; only proteins yield a positive Biuret test.', '["protein","fat","carbohydrate","all three"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:07:07.405Z"'::jsonb),
('anki-card-1757829491465-129', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Using options in Question # 29, which macromolecule’s function include insulation, waterproofing and shock absorption?', '40g protein diet', '', '["Protein-free diet","40g protein diet","20g protein diet","Amino acid supplementation for better protein control"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757829525347-130', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Animal cell membranes are mainly composed of a phospholipid bilayer.  What happens to a triglyceride to form a phospholipid?', 'Loss of one fatty acid and gain of one inorganic phosphate group', 'Phospholipids (the primary constituents of animal cell membranes) are derived from triglycerides through the loss of one fatty acid and the addition of a polar phosphate-containing head group.', '["Gain of two inorganic phosphates","Loss of one fatty acid and gain of one inorganic phosphate group","All three fatty acids replaced by inorganic phosphates","Gain of two organic phosphate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:56:47.693Z"'::jsonb),
('anki-card-1757829543646-131', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'What is the most abundant protein in the human blood plasma?', 'albumin', 'Albumin is a small, highly concentrated globular protein synthesized exclusively by the liver that serves as the most abundant protein in human blood plasma, maintaining colloid osmotic pressure.

• Insulin / Hemoglobin / Prostacyclin: Hormones, intracellular erythrocyte proteins, or lipid signaling molecules present in much lower plasma concentrations.', '["insulin","albumin","hemoglobin","prostacyclin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:15:47.065Z"'::jsonb),
('anki-card-1757829572127-132', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'The enzyme pepsin is not denatured in the stomach despite the very acidic environment attributed to hydrochloric acid (HCl).
How can this be?', 'pepsin is secreted in its precursor form (pepsinogen)', 'The stomach produces proteolytic enzymes safely by secreting them in inactive precursor forms—such as pepsinogen—which undergo autocatalytic cleavage and activation only upon encountering hydrochloric acid in the gastric lumen.', '["pepsin is the only protein-enzyme that functions best in an acidic environment","pepsin is able to resist dentauration by increasing  the pH within the stomach, making it less acidic","pepsin is also digested along with other proteins in the stomach","pepsin is secreted in its precursor form (pepsinogen)"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:56:53.995Z"'::jsonb),
('anki-card-1757829594410-133', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'A bruise, medically known as contusion, is made when a certain external area of the body is hit by something really hard, and
the capillaries in that area collapse.  It first appears on the skin with a violet color. After a few days, it becomes greenish in color.
A few more days after, it appears yellowish in color, until it eventually fades and disappears. What causes this bruise to appear
greenish in color?', 'biliverdin', 'During the breakdown of hemoglobin from collapsed capillaries in a contusion (bruise), heme is first degraded into the green pigment biliverdin, before converting into yellow bilirubin as it heals.

• Hemoglobin: Unoxygenated or degraded hemoglobin causes the initial red-purple hue.
• Bilirubin: Yellow-orange, responsible for the later yellow fading stage of bruising.
• Stercobilin: A brown fecal pigment derived from bilirubin breakdown in the gut.', '["biliverdin","hemoglobin","bilirubin","stercobilin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:07:23.861Z"'::jsonb),
('anki-card-1757829616126-134', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following is not a form of feedback inhibition?', 'Continuous exposure to a delectable aroma of food causes secretion of saliva and movement of the gastrointestinal tract.', 'This scenario describes a feed-forward reflex or physiological response rather than negative feedback inhibition, making it the correct exception.', '["An increase in T3 and T4 stops the release of TSH and TRH from the hypothalamus and pituitary gland.","Continuous exposure to a delectable aroma of food causes secretion of saliva and movement of the gastrointestinal tract.","An elevation of estrogen and progesterone ceases the secretion of FSH and LH by the anterior pituitary gland.","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:57:03.235Z"'::jsonb),
('anki-card-1757829642209-135', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Ammonia is a nitrogenous waste product of protein metabolism, and is harmful especially in high concentrations in the human
body. Urea cycle is a means to detoxify and to prevent the accumulation of amonia in the body by converting it to urea, and
eventually excreted in the urine.  How many moles of nitrogen enter the urea cycle in every turn?', '2', 'In each complete turn of the hepatic urea cycle, 2 moles of nitrogen (one originating from free ammonia and one from aspartate) enter to be detoxified into urea.', '["4","2","1","3"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:57:08.017Z"'::jsonb),
('anki-card-1757829662308-136', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Insulin is a peptide hormone produced in the pancreas by the beta cells.  It aims to lower the glucose (sugar) levels in the blood,
and is normally secreted every after meals.  Their action is to activate the transporters of glucose found on the surface of the
cells, so that the cells can take up glucose from the blood and into the cells.  What glucose transporter is regulated by the action
of insulin?', 'glucose transporter 4 (GLUT 4)', 'Glucose transporter 4 (GLUT4) is the primary insulin-regulated glucose transporter protein expressed predominantly in skeletal muscle and adipose tissue cells.

• Sodium-glucose transporter (SGLT): Handles active sodium-glucose cotransport in the intestines and renal tubules.
• Glucose transporter 2 (GLUT 2): Insulin-independent, found in the liver, pancreas, and kidneys.
• Glucose transporter 5 (GLUT 5): A specialized fructose transporter in the small intestine.', '["glucose transporter 4 (GLUT 4)","sodium-glucose transporter (SGLT)","glucose transporter 2 (GLUT 2)","glucose transporter 5 (GLUT 5)"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:07:38.742Z"'::jsonb),
('anki-card-1757829681858-137', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'It has been known that Vitamin A improves eyesight.  However, this statement is not 100% true.  What makes this claim about
Vitamin A partly false?', 'Rhodopsin (from Vitamin A) is only used to see in the dark, but not when enough light is available', 'Vitamin A''s role in vision relies on rhodopsin in retinal rod cells, which functions primarily for low-light (scotopic/dark) vision, while cone cells handle bright-light color vision, making the blanket claim partially nuanced.

• It is actually Vitamin E that functions for eyesight: Incorrect; Vitamin E is an antioxidant.
• Vitamin A is also good for the skin: True, but does not invalidate the eyesight claim.', '["Rhodopsin (from Vitamin A) is only used to see in the dark, but not when enough light is available","It is actually Vitamin E that functions for the improvement of the eyesight.","Vitamin A is not only good for eyesight, but is also good for the skin.","None of these answers make the statement about Vitamin A partly false."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:07:48.601Z"'::jsonb),
('anki-card-1757829854065-138', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Fiber-rich foods have been an essential part of everyday meals.  Research have shown that regular consumption of fiber or
fiber-rich food can lower the risk of having colon cancer.  What is this fiber made of?', 'cellulose', 'Dietary fiber that supports beneficial gut microbiota and lowers colon cancer risk consists primarily of indigestible plant cell wall polysaccharides such as cellulose.

• Dextrin: Soluble starch breakdown products.
• Chitin: Found in arthropod exoskeletons and fungi, not primary plant dietary fiber.
• Starch: A digestible energy-yielding carbohydrate.', '["dextrin","cellulose","chitin","starch"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:07:56.139Z"'::jsonb),
('anki-card-1757829872450-139', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Non-digestible food ingredients that encourage the growth of beneficial bacteria', 'prebiotic', 'Prebiotics are non-digestible food ingredients (such as inulin and oligosaccharides) that selectively stimulate the favorable growth and activity of beneficial gut bacteria.

• Probiotic: Live beneficial microorganisms themselves, not food ingredients.
• Synbiotic: A combination of both prebiotics and probiotics.', '["prebiotic","probiotic","synbiotic","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:08:06.334Z"'::jsonb),
('anki-card-1757829898780-140', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Cancer has become one of the leading causes of death all over the world. What is the field in medicine that deals with the
biology, diagnosis, and treatment of cancer?', 'oncology', 'Oncology is the specialized medical subspecialty and scientific field dedicated to the biology, diagnosis, prevention, and treatment of cancer and tumors.

• Conchology: The scientific study of mollusk shells.
• Tumorology: A non-standard colloquial term.
• Cytology: The study of individual cellular structure and pathology.', '["conchology","oncology","tumorology","cytology"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:08:15.269Z"'::jsonb),
('anki-card-1757829921729-141', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Secondary messengers are needed by cell ligands  that bind to surface receptors but its action would affect some internal
structures within the cells.  The following ligands require secondary messengers except:', 'steroid hormones', 'Steroid hormones are lipophilic molecules that cross cell membranes directly to bind intracellular receptors, bypassing the need for cell-surface second messenger cascades (unlike peptide hormones or catecholamines).

• Adrenalin: A catecholamine hormone that binds cell-surface receptors and utilizes second messengers (like cAMP).
• Insulin: A peptide hormone binding surface receptor tyrosine kinases requiring intracellular signaling cascades.
• Glucagon: Binds cell-surface G-protein coupled receptors using cAMP as a second messenger.', '["steroid hormones","adrenalin","insulin","glucagon"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:08:22.681Z"'::jsonb)
