INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757829945061-142', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Ceruloplasmin is a type of:', 'metalloprotein', 'Ceruloplasmin is a blue-copper-containing circulating plasma protein, classifying it as a metalloprotein.

• Glycoprotein: While it contains carbohydrate chains, its defining functional classification is metal-binding.
• Phosphoprotein: Contains phosphate groups attached to amino acid residues.
• Lipoprotein: Transports lipids, not copper.', '["glycoprotein","phosphoprotein","metalloprotein","lipoprotein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:08:29.969Z"'::jsonb),
('anki-card-1757829959277-143', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Of what is a triglyceride composed?', 'one glycerol with 3 fatty acids', 'A standard triglyceride molecule is composed of one glycerol backbone esterified with three fatty acid chains.', '["one glycerol with 3 fatty acids","3 glycerides","3 glycerol with a fatty acid","3 fatty acids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T06:57:57.835Z"'::jsonb),
('anki-card-1757829996960-144', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Why is a saturated fat called a “saturated” fat?', 'The fatty acid carbon chain are saturated with hydrogen', 'A saturated fat is termed "saturated" because every available carbon bonding site on its fatty acid hydrocarbon chain is completely saturated with hydrogen atoms (possessing no double bonds).

• Saturated with water / Water added: Fats are hydrophobic and repel water.', '["The fat is saturated with water","The fatty acid carbon chain are saturated with hydrogen","The fatty acid chains can have more water added","They saturate the body fat when eaten"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:08:40.918Z"'::jsonb),
('anki-card-1757830014958-145', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Waxes are:', 'esters of monohydric alcohols and a fatty acids', 'Chemically, waxes are simple lipids defined as esters formed between long-chain monohydric alcohols and long-chain fatty acids.

• Trihydric alcohols: Glycerol is a trihydric alcohol, but waxes are distinct ester complexes.
• Aldehyde or ketone derivatives: Defines monosaccharides (sugars).', '["trihydric alcohols","aldehyde or ketone derivatives of polyhydroxy alcohols","esters of monohydric alcohols and a fatty acids","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:08:49.044Z"'::jsonb),
('anki-card-1757830039157-146', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'An example of a phospholipid is:', 'oxytocin', '', '["pectin","oxytocin","lecithin","cortisone"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1757830054473-147', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Group of lipids that usually predominate in foods and in the body', 'triglycerides', 'Triglycerides represent the dominant class of neutral lipids found in foods and stored as adipose tissue reserves in the human body.

• Cholesterol: A minor sterol fraction compared to bulk neutral fat.
• Phospholipids: Form cell membranes, representing a smaller structural proportion.
• Glycerol: A backbone component of triglycerides, not a predominant lipid group.', '["cholesterol","triglycerides","phospholipids","glycerol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:08:56.911Z"'::jsonb),
('anki-card-1757830069473-148', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'An example of a monounsaturated fatty acid', 'oleic acid', 'Oleic acid is a common 18-carbon monounsaturated fatty acid (MUFA) with a single double bond, abundant in olive oil.

• Linoleic acid / Linolenic acid: Polyunsaturated fatty acids (PUFAs).
• Palmitic acid: A saturated fatty acid.', '["linoleic acid","palmitic acid","linolenic acid","oleic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:17:27.871Z"'::jsonb),
('anki-card-1757830086605-149', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Omega-3 fatty acid', 'linolenic acid', 'Alpha-linolenic acid is an essential 18-carbon omega-3 polyunsaturated fatty acid.

• Linoleic acid: An omega-6 polyunsaturated fatty acid.
• Palmitic / Oleic acid: Saturated or monounsaturated fatty acids.', '["linoleic acid","palmitic acid","linolenic acid","oleic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:17:33.748Z"'::jsonb),
('anki-card-1757834795576-150', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Fatty acids most commonly found in animal fats', 'stearic acid', 'Stearic acid is a saturated 18-carbon fatty acid found abundantly in animal fats (tallow and suet).

• Linoleic acid: A polyunsaturated plant oil component.
• Palmitic / Myristic acid: Shorter chain saturated fats.', '["linoleic acid","palmitic acid","stearic acid","myristic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:17:39.793Z"'::jsonb),
('anki-card-1757834812851-151', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Enzyme that helps in the digestion of fats which is more active in infants than in adults', 'lingual lipase', 'Lingual lipase is an acid-stable enzyme secreted by glands on the tongue that initiates lipid digestion; it is secreted in much higher relative activity in human infants to aid milk fat digestion than in adults.

• Pancreatic lipase / Gastric lipase / Intestinal lipase: Secreted or active across broader adult digestive phases.', '["lingual lipase","pancreatic lipase","gastric lipase","intestinal lipase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:17:44.453Z"'::jsonb),
('anki-card-1757834827950-152', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Precursor of arachidonic acid', 'linoleic acid', 'Linoleic acid is an essential omega-6 polyunsaturated fatty acid that serves as the biological precursor for the synthesis of arachidonic acid and eicosanoids.

• Palmitic / Oleic / Linolenic acid: Saturated, monounsaturated, or omega-3 fatty acid families.', '["linoleic acid","palmitic acid","linolenic acid","oleic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:17:49.885Z"'::jsonb),
('anki-card-1757834850864-153', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Histone is a type of:', 'simple protein', 'Histones are basic simple proteins rich in arginine and lysine that bind tightly to DNA in eukaryotic cell nuclei to form chromatin.

• Conjugated protein: Contains non-protein prosthetic groups.
• Derived protein: Breakdown products of protein denaturation.
• Amino acid: A monomer, not a protein.', '["conjugated protein","derived protein","amino acid","simple protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:09:04.810Z"'::jsonb),
('anki-card-1757834880063-154', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Vitamin A is also called:', 'retinol', 'Vitamin A is chemically known as retinol (along with its active aldehyde and acid derivatives like retinal and retinoic acid).

• Calciferol: Vitamin D.
• Tocopherol: Vitamin E.
• Phylloquinone: Vitamin K.', '["retinol","calciferol","tocopherol","phylloquinone"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:09:11.232Z"'::jsonb),
('anki-card-1757834900196-155', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which vitamin is also called an anti-sterility vitamin?', 'Vitamin E', 'Vitamin E (tocopherols) is historically recognized in reproductive physiology and nutrition literature as the anti-sterility vitamin.

• Vitamin C: Ascorbic acid prevents scurvy.
• Vitamin K: Essential for blood coagulation.
• Vitamin A: Vital for vision and epithelial tissue health.', '["Vitamin C","Vitamin K","Vitamin A","Vitamin E"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:09:17.397Z"'::jsonb),
('anki-card-1757834927680-156', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of these is a saturated fatty acid?', 'Palmitic acid', 'Palmitic acid is a common 16-carbon saturated fatty acid found abundantly in both animal and plant fats.

• Linoleic acid: An essential polyunsaturated omega-6 fatty acid.
• Oleic acid: A monounsaturated omega-9 fatty acid.
• Linolenic acid: An essential polyunsaturated omega-3 fatty acid.', '["Linoleic acid","Oleic acid","Palmitic acid","Linolenic acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:09:23.895Z"'::jsonb),
('anki-card-1757834942111-157', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Antibodies are also called:', 'immunoglobulins', 'Circulating antibodies synthesized by plasma cells are specialized glycoproteins formally known as immunoglobulins.

• Nucleotides: Building blocks of nucleic acids (DNA/RNA).
• Prolamines: A class of plant storage proteins.
• Albumins: Major plasma transport proteins produced by the liver.', '["nucleotides","prolamines","immunoglobulins","albumins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:09:31.090Z"'::jsonb),
('anki-card-1757834979910-158', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'An essential building block of phosphatidic acid and phosphatidylcholine (two phospholipids) is', 'glycerol', 'Glycerol serves as the vital central trihydric alcohol backbone essential for synthesizing phospholipids such as phosphatidic acid and phosphatidylcholine.

• Glucose: A hexose monosaccharide.
• Adenosine: A nucleoside component of ATP and RNA.
• Lysine: A basic amino acid.', '["glycerol","glucose","adenosine","lysine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:09:38.305Z"'::jsonb),
('anki-card-1757835011908-159', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'When fatty acids are added to water, they aggregate to form micelles. What is the most important driving force for aggregation?', 'Reduction of the hydrocarbon surface area exposed to water', 'When amphipathic fatty acids aggregate into micelles in water, the primary thermodynamic driving force is the reduction of the structured water cage surface area exposed to hydrophobic hydrocarbon chains (the hydrophobic effect).

• Hydrogen bonding / London dispersion forces / Ion-dipole interactions: Minor or secondary stabilizing forces compared to the primary hydrophobic effect driving surface area reduction.', '["Hydrogen bonding between the adjacent carboxyl groups","Reduction of the hydrocarbon surface area exposed to water","London dispersion forces between the hydrocarbon chains","Ion-dipole interactions between the carboxyl groups and water"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:10:00.016Z"'::jsonb),
('anki-card-1757835034806-160', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Glycolysis occurs in the:', 'cytosol', 'The complete enzymatic pathway of glycolysis takes place entirely within the aqueous cytosol (cytoplasm) of the cell.

• Mitochondrial matrix: Site of the Krebs cycle and fatty acid beta-oxidation.
• Mitochondrial membrane: Site of oxidative phosphorylation and electron transport chain.', '["mitochondrial matrix","mitochondrial membrane","cytosol","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:10:07.271Z"'::jsonb),
('anki-card-1757835053856-161', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'The rate-limiting step in glycolysis is', 'the phosphorylation of fructose 6-phosphate.', 'The committed, major rate-limiting step of glycolysis is catalyzed by phosphofructokinase-1 (PFK-1), which drives the phosphorylation of fructose-6-phosphate to fructose-1,6-bisphosphate.

• Breakdown of glycogen: Glycogenolysis is an upstream pathway.
• Phosphorylation of glucose: Catalyzed by hexokinase/glucokinase, but not the primary rate-limiting step.
• Isomerization of glucose 6-phosphate: A reversible, non-rate-limiting step.', '["the breakdown of glycogen.","the phosphorylation of glucose.","isomerization of glucose 6-phosphate to fructose 6-phosphate.","the phosphorylation of fructose 6-phosphate."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:10:14.027Z"'::jsonb),
('anki-card-1757835070372-162', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'An enzyme that catalyzes the following reaction:
fructose-6-phosphate  glucose-6-phosphate is a/an', 'isomerase.', 'An enzyme that catalyzes the interconversion of isomers (such as converting glucose-6-phosphate to fructose-6-phosphate) is classified as an isomerase.

• Transferase: Transfers chemical groups between molecules.
• Ligase: Catalyzes the joining of two large molecules using ATP energy.
• Lyase: Cleaves chemical bonds by means other than hydrolysis or oxidation.', '["isomerase.","transferase.","ligase.","lyase."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:10:21.700Z"'::jsonb),
('anki-card-1757835086005-163', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'The major rate-limiting step of the glycolytic pathway is catalyzed by', 'phosphofructokinase-1.', 'Phosphofructokinase-1 (PFK-1) is the primary, major rate-limiting allosteric enzyme controlling the flux of the glycolytic pathway.

• Hexokinase/glucokinase: Catalyzes the initial trapping of glucose, but is not the primary flux-controlling pacemaker.
• Aldolase: Cleaves fructose-1,6-bisphosphate into two 3-carbon sugars.
• Glycerol 6-phosphate dehydrogenase: Involved in shuttle mechanisms, not glycolysis rate-limiting control.', '["hexokinase/glucokinase.","phosphofructokinase-1.","aldolase.","glycerol 6-phosphate dehydrogenase."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:10:29.570Z"'::jsonb),
('anki-card-1757835100371-164', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'During anaerobic glycolysis, there is a net production in the cytosol of lactate and', 'ATP', 'During anaerobic glycolysis in the cytosol, glucose breakdown yields a net production of lactate and chemical energy in the form of ATP.

• NAD+: NAD+ is consumed and regenerated in the process, but ATP is the net chemical energy currency produced.
• NADH: Produced in step 6 and consumed during lactate dehydrogenase reduction.
• CO2: Carbon dioxide is released during aerobic decarboxylation, not anaerobic glycolysis.', '["NAD+","NADH","CO2","ATP"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:10:36.489Z"'::jsonb),
('anki-card-1757835118771-165', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'One (1) glucose molecule will yield how many pyruvate products', '2', 'During glycolysis, one six-carbon glucose molecule is split and fully oxidized into two three-carbon pyruvate molecules.', '["1","3","2","4"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:08.439Z"'::jsonb),
('anki-card-1757835135122-166', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Process by which the body manufactures glucose from proteins or non-carbohydrate sources', 'gluconeogenesis', 'Gluconeogenesis is the metabolic pathway responsible for synthesizing new glucose molecules from non-carbohydrate precursors such as glucogenic amino acids, lactate, and glycerol.

• Glycolysis: The breakdown of glucose into pyruvate.
• Lipolysis: The hydrolysis of stored triglycerides into fatty acids and glycerol.
• Glyconeogenesis: Non-standard terminology.', '["glycolysis","lipolysis","glyconeogenesis","gluconeogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:13.522Z"'::jsonb),
('anki-card-1757835151069-167', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Hormone responsible for stimulating the uptake of glucose into the cells and storage as glycogen in the liver and muscles', 'insulin', 'Insulin is the primary anabolic peptide hormone secreted by pancreatic beta-cells that stimulates cellular glucose uptake and promotes its storage as glycogen in the liver and skeletal muscles.

• Glucagon: Stimulates glycogenolysis and raises blood glucose.
• Epinephrine / Norepinephrine: Stress hormones promoting glycogen breakdown and energy mobilization.', '["insulin","glucagon","epinephrine","norepinephrine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:21.348Z"'::jsonb),
('anki-card-1757835173384-168', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Site of fermentation of undigested residues such as fibers', 'large intestine', 'The large intestine (colon) serves as the primary site of microbial fermentation for undigested food residues and dietary fibers, producing short-chain fatty acids.

• Small intestine: The primary site for enzymatic digestion and macronutrient absorption.
• Stomach: Initiates protein denaturation and initial gastric proteolysis.
• Mouth: Initiates mechanical mastication and salivary amylase carbohydrate digestion.', '["small intestine","stomach","large intestine","mouth"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:26.376Z"'::jsonb),
('anki-card-1757835219649-169', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which of the following artificial sweetener is not allowed for individuals with PKU', 'aspartame', 'The large intestine (colon) serves as the primary site of microbial fermentation for undigested food residues and dietary fibers, producing short-chain fatty acids.

• Small intestine: The primary site for enzymatic digestion and macronutrient absorption.
• Stomach: Initiates protein denaturation and initial gastric proteolysis.
• Mouth: Initiates mechanical mastication and salivary amylase carbohydrate digestion.', '["sucralose","saccharin","acesulfame-K","aspartame"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:30.987Z"'::jsonb),
('anki-card-1757835244549-170', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'An enzyme that is common in both glycolysis and gluconeogenesis:', 'fructose bisphosphatase', 'Fructose-1,6-bisphosphatase is a key regulatory enzyme utilized exclusively in gluconeogenesis to bypass the irreversible PFK-1 step of glycolysis.

• Phosphofructokinase-1 / Glucokinase / Aldolase: Glycolytic enzymes that operate in the forward glycolytic direction, distinct from gluconeogenetic bypass enzymes.', '["phosphofructokinase-1","glucokinase","aldolase","fructose bisphosphatase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:36.968Z"'::jsonb),
('anki-card-1757835259729-171', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which enzyme is activated by direct binding of cAMP to a regulatory subunit?', 'phosphorylase kinase', 'Phosphorylase kinase is activated directly by the binding of cyclic AMP (cAMP) via protein kinase A phosphorylation cascades to regulate glycogen breakdown.

• Adenylate cyclase / Protein kinase A / Protein phosphatase: Involved in upstream signaling or dephosphorylation, but phosphorylase kinase directly drives glycogen phosphorylase activation.', '["adenylate cyclase","protein kinase A","phosphorylase kinase","protein phosphatase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:42.109Z"'::jsonb),
('anki-card-1757835296029-172', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'A pathway/step of carbohydrate metabolism that is stimulated by insulin in muscle, but not in liver:', 'Glucose transport', 'Insulin stimulates glucose transport (via GLUT4 translocation) in skeletal muscle and adipose tissue, whereas hepatic glucose transport via GLUT2 is insulin-independent.

• Glycolysis / Glycogenolysis / Glycogen synthesis: Metabolic pathways regulated by insulin across both hepatic and peripheral muscle tissues.', '["Glycolysis","Glucose transport","Glycogenolysis","Glycogen synthesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:48.464Z"'::jsonb),
('anki-card-1757835316511-173', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'In the digestive tract, disaccharides such as sucrose are hydrolyzed to monosaccharides mainly by enzymes located in the', 'brush border of the small intestine.', 'Disaccharides are hydrolyzed into absorbable monosaccharides by specialized brush-border enzymes (such as sucrase, maltase, and lactase) anchored to the microvilli of the small intestinal enterocytes.

• Saliva / Gastric secretions: Saliva contains amylase for starches, but no disaccharidases; gastric juices contain proteases and lipases.
• Lumen of the small intestine: Digestion here relies on pancreatic enzymes, whereas final disaccharide splitting occurs at the membrane brush border.', '["saliva.","gastric secretions.","lumen of the small intestine.","brush border of the small intestine."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:12:54.219Z"'::jsonb),
('anki-card-1757835331079-174', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'The respiratory quotient (RQ) is defined as', '(liters CO2 produced)/(liters O2 consumed).', 'The Respiratory Quotient (RQ) is formally defined as the volumetric ratio of carbon dioxide produced to oxygen consumed (V̇CO₂ / V̇O₂). 

• (Nitrogen intake)/(nitrogen excreted): Measures nitrogen balance. 
• (Caloric intake)/(fat free body weight): Represents energy intake scaling. 
• (BMR + DIT + activity)/(fat free body weight): Represents total daily energy expenditure parameters.', '["(nitrogen intake)/(nitrogen excreted).","(caloric intake)/(fat free body weight).","(BMR + DIT + activity)/(fat free body weight).","(liters CO2 produced)/(liters O2 consumed)."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:13:19.906Z"'::jsonb),
('anki-card-1757835365474-175', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'An appetite suppressing hormone produced by the adipose tissue', 'leptin', 'Leptin is an adipose-derived hormone that acts on the hypothalamus to suppress appetite and regulate long-term body weight homeostasis.

• Adiponectin: An adipokine enhancing insulin sensitivity.
• Neuropeptide Y: A powerful hypothalamic orexigenic (appetite-stimulating) peptide.
• Lectin: A plant carbohydrate-binding protein, unrelated to appetite hormones.', '["adiponectin","neuropeptide Y","lectin","leptin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:13:26.009Z"'::jsonb),
('anki-card-1757835425539-176', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'The most variable component of energy expenditure is the', 'Physical activity', 'Physical activity is the most highly variable and controllable component of total daily energy expenditure (TDEE).

• BMR (Basal Metabolic Rate): Relatively stable and accounts for the largest baseline proportion of energy expenditure.
• TEF (Thermic Effect of Food): A fixed percentage (approx. 10%) of total caloric intake.', '["BMR","Physical activity","TEF","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:17:54.445Z"'::jsonb),
('anki-card-1757835452856-177', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Measures amount of energy expended by monitoring heat production', 'direct calorimetry', 'Direct calorimetry measures total body energy expenditure by monitoring direct physical heat production and dissipation within an insulated chamber. 

• Indirect calorimetry: Estimates energy expenditure by measuring gas exchange (V̇O₂ and V̇CO₂).', '["direct calorimetry","indirect calorimetry","Both a and b","Neither a nor b"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:18:08.145Z"'::jsonb),
('anki-card-1757835474021-178', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'All of the following is an example of indirect calorimetry EXCEPT:', 'bomb calorimeter', 'A bomb calorimeter measures the gross heat of combustion of food samples directly in a laboratory setting, making it an ex vivo instrument rather than a method of human indirect calorimetry.

• Respirometer / Pulse rate / Doubly-labeled water: Valid indirect or physiological methods used to estimate human energy expenditure.', '["bomb calorimeter","respirometer","pulse rate","doubly-labeled water"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:18:16.693Z"'::jsonb),
('anki-card-1757835522703-179', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'After preparing several lectures, a Biochemistry professor goes to Taco Bell for a late night snack consisting of two burrito
supremos (42 gm protein, 44 gm fat and 86 gm carbohydrate) which he washes down with a 32 oz. Fanta orange soda (120 gm
carbohydrate). The total number of kcal in this snack', '1,388', 'Calculating total calories using Atwater factors (Protein = 4 kcal/g, Fat = 9 kcal/g, Carbohydrate = 4 kcal/g):

Two burrito supremos: 42g protein × 4 = 168 kcal; 44g fat × 9 = 396 kcal; 86g carbohydrate × 4 = 344 kcal. (Subtotal = 908 kcal).

32 oz. Fanta orange soda: 120g carbohydrate × 4 = 480 kcal.

Total = 908 + 480 = 1,388 kcal.', '["1,388","576","1,168","1,598"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:18:26.452Z"'::jsonb),
('anki-card-1757835566484-180', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'In the small intestine:', 'starch is digested by pancreatic amylase into maltose.', 'In the lumen of the small intestine, pancreatic alpha-amylase hydrolyzes complex starches into maltose, maltotriose, and alpha-limit dextrins.

• Cellulose fiber is digested: Human enzymes cannot break down beta-linked cellulose.
• Fat is not hydrolyzed: Dietary fats undergo active pancreatic lipase hydrolysis in the small intestine.
• Protein is hydrolyzed by bile acids: Bile acids emulsify fats, whereas proteases hydrolyze proteins.', '["cellulose fiber is digested into monosaccharides.","starch is digested by pancreatic amylase into maltose.","fat is not hydrolyzed.","protein is hydrolyzed by bile acids into amino acids."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:13:31.445Z"'::jsonb),
('anki-card-1757835583732-181', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Pancreatic juice contains the following enzyme(s)', 'trypsinogen.', 'Pancreatic juice contains inactive zymogens including trypsinogen, chymotrypsinogen, and procarboxylase, which are activated in the intestinal lumen.

• Pepsinogen and Pepsin: Secreted by gastric chief cells in the stomach, not the pancreas.
• Enterokinase: An intestinal brush-border enzyme activating trypsinogen, secreted by enterocytes, not the pancreas.
• Para-pepsinogen II: Gastric mucosal variants.', '["trypsinogen.","pepsinogen and Pepsin.","enterokinase.","para-pepsinogen II and parapepsinogen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:13:38.293Z"'::jsonb),
('anki-card-1757835606549-182', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Which protease (secreted by the pancreas) cleaves proteins on the carboxyl side of aromatic side chains', 'chymotrypsin', 'Chymotrypsin is a pancreatic serine protease that specifically cleaves peptide bonds on the carboxyl side of bulky aromatic amino acid side chains (such as tyrosine, phenylalanine, and tryptophan).

• Carboxypeptidase B: Cleaves basic amino acids (arginine, lysine) from the C-terminal end.
• Pepsin: A gastric protease, not pancreatic.
• Proelastase: Cleaves peptide bonds adjacent to small, hydrophobic amino acids like alanine and glycine.', '["carboxypeptidase B","pepsin","chymotrypsin","proelastase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:13:43.777Z"'::jsonb),
('anki-card-1757835623715-183', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Digestion and absorption of carbohydrate involves all of the following EXCEPT:', 'an acid stable amylase which acts in the stomach', 'Human digestion lacks an acid-stable amylase functioning significantly in the stomach; salivary amylase is rapidly inactivated by gastric hydrochloric acid.

• Disaccharidases in the intestine / Pancreatic alpha amylase / Sodium monosaccharide cotransport system: Valid components of normal carbohydrate digestion and absorption.', '["an acid stable amylase which acts in the stomach","disaccharidases in the intestine","pancreatic alpha amylase","a sodium monosaccharide cotransport system","proelastase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:14:04.081Z"'::jsonb),
('anki-card-1757835672544-184', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'You eat one 57 gram serving of whole wheat spaghetti containing 8 grams protein, 40 grams carbohydrate, 2 grams fat,
and 7 grams fiber. Estimate the energy content in kcal.', '210', 'To calculate energy content using standard Atwater general factors (Protein = 4 kcal/g, Carbohydrate = 4 kcal/g, Fat = 9 kcal/g; fiber is typically excluded or counted at lower fermentable values):

Protein: 8g × 4 = 32 kcal.

Carbohydrate: 40g × 4 = 160 kcal.

Fat: 2g × 9 = 18 kcal.

Total = 32 + 160 + 18 = 210 kcal.', '["200","210","240","400"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:14:13.778Z"'::jsonb),
('anki-card-1757835695244-185', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Most vitamins:', 'are precursors to coenzymes.', 'Most water-soluble vitamins function biologically as essential chemical precursors for active coenzymes required in intermediary metabolism.

• Are synthesized by humans: False; most vitamins cannot be synthesized de novo by humans and must be obtained from the diet.
• Consist of amino acids, fatty acids or sugars: False; vitamins have diverse chemical structures distinct from proteins, fats, or carbohydrates.', '["are precursors to coenzymes.","are synthesized by humans.","consist of amino acids, fatty acids or sugars.","are covalently linked to proteins without modification."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:14:21.885Z"'::jsonb),
('anki-card-1757835727608-186', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Deficiency of this vitamin among pregnant women leads to neural tube defects', 'folate', 'Maternal dietary deficiency of folate (Vitamin B9) during periconception and early pregnancy is strongly linked to neural tube defects such as spina bifida.

• Thiamin / Riboflavin / Niacin: Essential B vitamins associated with Beriberi, ariboflavinosis, and pellagra, respectively.', '["thiamin","riboflavin","niacin","folate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:14:27.115Z"'::jsonb),
('anki-card-1757835757089-187', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Water-soluble vitamin needed for collagen synthesis', 'ascorbic acid', 'Ascorbic acid (Vitamin C) acts as an essential enzymatic cofactor (for prolyl and lysyl hydroxylase) required for proper collagen cross-linking and synthesis.

• Thiamin / Niacin / Folate: Water-soluble B-vitamins serving diverse coenzyme roles independent of collagen synthesis.', '["thiamin","ascorbic acid","niacin","folate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:15:58.527Z"'::jsonb),
('anki-card-1757835774041-188', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'A cofactor (vitamin) that is a carrier of activated CO2 and participates in both gluconeogenesis and fatty acid synthesis is', 'biotin.', 'Biotin functions as a mobile carboxyl-group carrier coenzyme attached to biotin-dependent carboxylases involved in gluconeogenesis, fatty acid synthesis, and amino acid catabolism.

• Lipoamide / Pyridoxal phosphate / Flavin adenine dinucleotide: Serve distinct redox and transferase coenzyme functions.', '["lipoamide.","pyridoxal phosphate.","biotin.","flavin adenine dinucleotide."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:16:02.999Z"'::jsonb),
('anki-card-1757835790422-189', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'A dietary deficiency of the following cofactor can lead to the Wernicke- Korsakoff syndrome.', 'thiamine', 'Dietary deficiency of thiamine (Vitamin B1) impairs cerebral glucose metabolism, leading to Wernicke-Korsakoff syndrome, commonly seen in chronic alcoholism.

• Niacin / Riboflavin / Biotin: Deficiencies cause pellagra, ariboflavinosis, or biotin-responsive dermatitis, not classic Wernicke-Korsakoff encephalopathy.', '["thiamine","niacin","riboflavin","biotin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:16:17.619Z"'::jsonb),
('anki-card-1757835807072-190', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Works closely with insulin to regulate the release of energy from glucose', 'chromium', 'Chromium works synergistically with insulin to enhance receptor binding and regulate cellular glucose uptake and energy release.

• Iodine / Selenium / Fluoride: Trace minerals associated with thyroid function, antioxidant defense, and dental enamel strengthening.', '["iodine","selenium","fluoride","chromium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:16:43.967Z"'::jsonb),
('anki-card-1757835828688-191', NULL, 'anki-deck-1783610400188-1790433145939-pouc6', 'Normal blood osmolality', '300 mOsm', 'Normal physiological serum and blood osmolality ranges between approximately 275 and 295 mOsm/kg, standardized conveniently around 300 mOsm in clinical board exam parameters.', '["200 mOsm","300 mOsm","400 mOsm","500 mOsm"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.865Z"'::jsonb, '"2026-11-09T07:18:42.357Z"'::jsonb)
