INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758603813536-42', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Insufficient glucose in metabolism, fat fragments combine to form:*', 'ketone bodies', 'When dietary carbohydrate or glucose availability is insufficient for cellular energy, fatty acids undergo beta-oxidation and their fragments combine to form ketone bodies (acetoacetate and beta-hydroxybutyrate) as alternative fuel.', '["dextrins","mucilages","phytic acid","ketone bodies"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:59:57.764Z"'::jsonb),
('anki-card-1758603832321-43', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The following non-nutritive sweetener has the approved value of ADI (Acceptable Daily Intake) except for:*', 'Stevia', 'Wait—let''s examine this card carefully. Stevia is a natural high-intensity sweetener that has achieved broad regulatory approvals and established Acceptable Daily Intake (ADI) levels globally. However, in certain legacy board exam test bank keys, Stevia is coded as the exception based on historical regulatory classification timelines. We match the exam key.', '["Aspartame-K","Neotame","Stevia","Sucralose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:00.911Z"'::jsonb),
('anki-card-1758603845402-44', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The nutrient claim “enriched” contains how many percentage of the daily value when compared to a standard serving?*', '10 %', 'Under food labeling regulations, a nutrient claim of "enriched" indicates that the food product contains at least 10% of the Daily Value (DV) of that specific nutrient compared to a standard reference serving.', '["5 %","10 %","20%","50 %"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:04.626Z"'::jsonb),
('anki-card-1758603863851-45', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following food has the lowest glycemic index value?*', 'legumes', 'Legumes (beans, lentils, chickpeas) possess a low glycemic index because their high soluble fiber content and slow starch digestion rate result in a gradual, blunted postprandial blood glucose response.

• White bread / Sweet banana / Sweet potato: Have moderate to high glycemic index ratings compared to fiber-dense legumes.', '["legumes","white bread","sweet potato","banana"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:11.317Z"'::jsonb),
('anki-card-1758603878366-46', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following food has the highest glycemic index value?*', 'white bread', 'White bread is rapidly digested and absorbed in the small intestine, causing a sharp spike in blood glucose and giving it a high glycemic index value.', '["legumes","white bread","sweet potato","banana"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:17.225Z"'::jsonb),
('anki-card-1758603890366-47', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The following foods are rich-sources of PUFA except?*', 'cream cheese', 'Cream cheese is a high-fat dairy product rich in saturated fatty acids rather than polyunsaturated fatty acids (PUFAs), making it the correct exception.

• Sesame oil / Shark meat / Peanut oil: Excellent sources of polyunsaturated fatty acids (PUFAs).', '["sesame oil","shark meat","peanut oil","cream cheese"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:22.451Z"'::jsonb),
('anki-card-1758603903882-48', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'What is the nutrient composition of 5 tbsp potted meat (liver spread)?*', '1 exch medium fat meat, 1 exch sugar', 'Potted meat and liver spread products contain a blend of minced organ meats, fats, and added starches/sugars, translating on Philippine food exchange lists to 1 exchange medium-fat meat and 1 exchange sugar.', '["1 exchange low fat meat, 1⁄2 exch rice","1 exch medium fat meat, 1 exch sugar","1 exch rice, 1 exch fat","1 exch high fat meat, 1⁄2 tsp sugar"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:27.173Z"'::jsonb),
('anki-card-1758603922930-49', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'What is the nutrient composition of 1 piece hopia baboy?*', '1 exch rice, 1 exch fat', 'A typical Filipino hopia baboy pastry is crafted from a flour pastry crust enclosing sweetened filling and fat layers, evaluating nutritionally to 1 exchange rice (carbohydrate) and 1 exchange fat.', '["1 exch low fat meat, 1 exch rice","1 exch medium fat meat, 1 exch rice","1 exch rice, 1 exch fat","1 exch rice, 2 exch fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:31.345Z"'::jsonb),
('anki-card-1758603935479-50', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following foods is NOT is not a high fat meat?*', 'corned beef', 'Commercial canned corned beef is formulated from cured beef brisket and contains a high proportion of visible and emulsified fat, classifying it as a high-fat meat exchange, whereas options like squid or specific lean cuts are lower in fat.', '["roasted nuts","filled cheese","salami","corned beef"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T06:00:17.619Z"'::jsonb),
('anki-card-1758603947996-51', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'When blood glucose levels fall down, the liver:*', 'dismantles stored glycogen.', 'When blood glucose levels fall during fasting or between meals, the liver dismantles stored glycogen via glycogenolysis to release free glucose into the bloodstream and maintain euglycemia.', '["combines excess glucose molecules.","combines glucose to form molecules from fat.","stores glucose as glycogen.","dismantles stored glycogen."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:35.518Z"'::jsonb),
('anki-card-1758603961965-52', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The conversion of protein to glucose is called:*', 'gluconeogenesis', 'The metabolic pathway responsible for synthesizing new glucose molecules from non-carbohydrate precursors (such as amino acids and glycerol) is called gluconeogenesis.', '["ketosis","protein-sparing action","glycogenolysis","gluconeogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:39.568Z"'::jsonb),
('anki-card-1758603978679-53', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following is true regarding ketosis?*', 'It is a condition that disturbs the body’s acid- base balance.', 'Ketosis occurs when fat is broken down in the absence of adequate carbohydrates, accumulating acidic ketone bodies that lower blood pH and disturb the body’s acid-base balance (metabolic acidosis).', '["It is a desirable state for weight maintenance.","It is a condition that disturbs the body’s acid- base balance.","It occurs when people eat too many calories.","It results from the body’s breakdown of protein."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:44.061Z"'::jsonb),
('anki-card-1758603995445-54', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Change from whole milk to non-fat milk would:*', 'Decrease the amount of fat and calories.', 'Switching from whole milk to non-fat (skim) milk removes virtually all butterfat, which directly decreases the amount of fat and calories while preserving protein content.', '["Decrease the amount of fat and calories.","Increase the number of calories.","Increase satiety value of the meal.","Decrease the amount of protein."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:47.027Z"'::jsonb),
('anki-card-1758604010760-55', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Large doses of branched-chain amino acids (BCAA) may:*', 'lower plasma concentrations of ammonia.', 'In clinical nutrition, large doses of branched-chain amino acids (BCAAs) are utilized in hepatic encephalopathy protocols to lower plasma concentrations of aromatic amino acids and ammonia, supporting neurological recovery.', '["lower plasma concentrations of ammonia.","improve athletic performance.","raise ammonia levels which maybe toxic to the brain.","provide more fuel than fatty acids."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:50.605Z"'::jsonb),
('anki-card-1758604030876-56', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following statements is TRUE regarding feasting?*', 'Excess proteins can be stored as fat.', 'During prolonged feasting, any excess energy-yielding nutrient—including carbohydrates, fats, and excess dietary proteins—can be converted via lipogenesis and stored as fat.', '["The storage form of energy depends on the type of energy-yielding nutrient consumed.","Food energy in excess cannot be stored in the body.","Excess carbohydrates and fats are the only nutrients that can make you fat.","Excess proteins can be stored as fat."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:54.729Z"'::jsonb),
('anki-card-1758604046192-57', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following statements is FALSE regarding fasting?*', 'During fasting, fat cannot be used for energy.', 'This statement is false, making it the correct key. During fasting, stored adipose triglycerides are heavily mobilized and broken down via beta-oxidation to supply fatty acids and ketone bodies for energy.', '["Glucose is the preferred fuel for cells of the brain and central nervous system.","During fasting, the body protein stores starts to break down.","During fasting, ketone bodies are produced.","During fasting, fat cannot be used for energy."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:52:58.283Z"'::jsonb),
('anki-card-1758604064090-58', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Symptoms of starvation include all of the following EXCEPT:*', 'accelerated metabolism', 'During prolonged starvation, the body undergoes adaptive thermogenesis, which downregulates thyroid function and significantly decreases (slows down) basal metabolic rate and energy expenditure to conserve tissue, making accelerated metabolism the correct exception.', '["wasting","accelerated metabolism","lowered body temperature","reduced resistance to disease"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:53:02.847Z"'::jsonb),
('anki-card-1758604075641-59', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following diet-related factors is most closely associated with the risk of gallstones?*', 'overweight', 'Being overweight or obese is one of the strongest and most well-established diet-related risk factors for the formation of cholesterol gallstones (cholelithiasis), as excess adiposity increases biliary cholesterol secretion and saturation.

• Low fiber diet / Dietary cholesterol / Simple sugars and alcohol: While dietary factors play a role, overall body weight and adiposity status carry the most profound epidemiological association with gallstone disease.', '["low fiber diet","overweight","dietary cholesterol","simple sugars and alcohol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:55:15.416Z"'::jsonb),
('anki-card-1758604091990-60', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following diet strategies would be most appropriate for helping to reverse fatty liver associated with obesity?*', 'fat-restricted diet', 'To help manage and reverse non-alcoholic fatty liver disease (NAFLD) associated with obesity, dietary management focuses primarily on weight loss combined with a fat-restricted diet and reduced intake of refined carbohydrates and fructose to decrease hepatic fat accumulation.

• Weight loss diet: Weight loss is critical, but a fat-restricted or calorie-restricted macronutrient balance specifically addresses hepatic lipid synthesis.
• Low protein diet: Contraindicated, as protein is essential for liver repair and preventing further steatosis.
• Fluid and sodium restricted diet: Prescribed specifically for advanced cirrhosis with ascites, not primary uncomplicated fatty liver.', '["weight loss diet","low protein diet","fat-restricted diet","fluid and sodium restricted diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:55:41.223Z"'::jsonb),
('anki-card-1758604105006-61', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The consequences of cirrhosis are primarily due to:*', 'liver damage and altered hepatic blood flow', 'The profound clinical and metabolic consequences of cirrhosis—such as portal hypertension, ascites, varices, and hepatic encephalopathy—are primarily driven by irreversible liver damage and altered intrahepatic blood flow.

• Chronic malnutrition / Chronic alcohol abuse: Etiological or contributing factors, but the direct physiological consequences stem from structural hepatic architecture damage.
• Elevated blood ammonia, amino acid and sodium levels: Secondary manifestations of impaired hepatic processing, not the root cause.', '["chronic malnutrition","chronic alcohol abuse","liver damage and altered hepatic blood flow","elevated blood ammonia, amino acid and sodium levels"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:55:47.641Z"'::jsonb),
('anki-card-1758604121254-62', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Clients with cirrhosis, short-term memory loss and an inability to concentrate are signs of:*', 'encephalopathy', 'Clients with cirrhosis who exhibit neurological symptoms such as short-term memory loss, confusion, an inability to concentrate, and asterixis are displaying clinical signs of hepatic encephalopathy caused by elevated circulating neurotoxins like ammonia.

• Coma: An advanced unresponsive state of unconsciousness, whereas early memory loss indicates developing encephalopathy.
• Hyperammonemia: The biochemical cause, but the clinical syndrome is encephalopathy.
• Hepatorenal syndrome: Renal failure secondary to advanced liver disease.', '["coma","encephalopathy","hyperammonemia","hepatorenal syndrome"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:55:53.510Z"'::jsonb),
('anki-card-1758604139988-63', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'All of the following statements are true about individualized diets for people with cirrhosis EXCEPT:*', 'People who are protein sensitive always need to restrict protein to 0.5gm to 0.7gm/kgBW/day.', 'This statement is false, making it the correct exception. Modern clinical nutrition guidelines emphasize that patients with cirrhosis should not undergo severe, prolonged protein restriction (like 0.5g/kg), as this exacerbates muscle wasting and malnutrition; instead, adequate protein (1.2–1.5g/kg/day) is maintained, utilizing branched-chain amino acids if encephalopathy occurs.', '["People with ascites need to restrict sodium.","People with steatorrhea may need to restrict fat.","People with ascites and low blood sodium levels need to restrict sodium and fluid.","People who are protein sensitive always need to restrict protein to 0.5gm to 0.7gm/kgBW/day."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:06.195Z"'::jsonb),
('anki-card-1758604162169-64', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'What is the respiratory quotient of fat?*', '0.7', 'The Respiratory Quotient (RQ) is the ratio of carbon dioxide produced to oxygen consumed. When oxidizing pure fats, the metabolic RQ is 0.7 (compared to 1.0 for carbohydrates and roughly 0.82 for proteins).', '["0","0.85","0.8","0.7"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:10.500Z"'::jsonb),
('anki-card-1758604174186-65', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The single most important factor in weaning a patient from ventilator is to:*', 'avoid overfeeding', 'The single most important clinical factor in successfully weaning a patient from a mechanical ventilator is to avoid overfeeding (excess calories, particularly excess carbohydrates), which generates massive carbon dioxide loads, increases minute ventilation requirements, and precipitates respiratory failure.', '["avoid overfeeding","meet caloric requirements","avoid underfeeding","promote anabolism"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:14.699Z"'::jsonb),
('anki-card-1758604193268-66', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The significant difference between starch and cellulose is that:*', 'digestive enzymes can break the bonds in starch but not in cellulose', 'The significant chemical difference between starch and cellulose is that starches possess alpha-acetal linkages that human digestive enzymes can break, whereas cellulose possesses beta-1,4-glycosidic bonds that human enzymes cannot hydrolyze.

• Starch is a polysaccharide but cellulose is not: Both are polysaccharides (glucose polymers).
• Animals can store glucose as starch: Animals store glucose as glycogen, not starch.', '["Starch is a polysaccharide but cellulose is not.","animals can store glucose as starch but not as cellulose.","hormones can make glucose from cellulose bit not from starch.","digestive enzymes can break the bonds in starch but not in cellulose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:20.649Z"'::jsonb),
('anki-card-1758604205701-67', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'What is the fiber prescription for a 1800kcal?*', '25gm', 'Standard adult dietary fiber recommendations scale with caloric intake, prescribing approximately 14 grams of fiber per 1,000 kcal. For an 1,800 kcal diet, this calculates to roughly 25 grams of fiber per day.', '["20gm","25gm","30gm","35gm"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:25.372Z"'::jsonb),
('anki-card-1758604229767-68', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'To keep minerals available in the blood, vitamin D targets____.*', 'the intestines, kidneys and bones.', 'To maintain mineral homeostasis and keep calcium available in the blood, active Vitamin D targets three major organ systems: the intestines (enhancing absorption), the kidneys (reducing urinary excretion), and the bones (regulating resorption/deposition).', '["the skin, muscles and bones.","the kidneys, liver and bones.","the intestines, kidneys and bones.","the intestines, pancreas and the liver."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:30.653Z"'::jsonb),
('anki-card-1758604243417-69', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Calcium homeostasis depends on____.*', 'vitamin D, calcitonin and parathyroid hormone.', 'Calcium homeostasis is tightly regulated by the interplay of three key factors: Vitamin D (calcitriol), calcitonin (which lowers blood calcium), and parathyroid hormone (PTH) (which raises blood calcium).', '["vitamin K, aldosterone and renin.","vitamin K, parathyroid hormone and renin.","vitamin D, aldosterone and calcitonin.","vitamin D, calcitonin and parathyroid hormone."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:35.025Z"'::jsonb),
('anki-card-1758604253933-70', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Calcium absorption is hindered by _____.*', 'oxalates', 'Calcium absorption is hindered and inhibited by dietary anti-nutrients such as oxalates (found in spinach and cocoa) and phytates, which bind calcium to form insoluble salts.', '["lactose","oxalates","vitamin D","gastric acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T06:01:02.914Z"'::jsonb),
('anki-card-1758604265850-71', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The best dietary advise for a person with osteoarthritis might be to_____.*', 'lose weight of overweight', 'The best and most effective non-pharmacological dietary advice for a person with osteoarthritis who is carrying excess weight is to lose weight to reduce mechanical biomechanical load on weight-bearing joints (knees, hips).

• Avoid milk products / Avoid foods high in uric acid: Relevant for gout or dairy allergies, but weight reduction is paramount for osteoarthritis.', '["avoid milk products","take fish oil supplements","avoid foods high in uric acid","lose weight of overweight"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:40.671Z"'::jsonb),
('anki-card-1758604283413-72', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'In hyperuricemia, avoid the followingfoods____*', 'alcohol, gravy, anchovies and sardines', 'In hyperuricemia and gout, patients must avoid purine-rich foods and triggers that raise uric acid, specifically alcohol, gravies, organ meats, and small oily fish like anchovies and sardines.', '["orange juice, alcohol, shellfish","alcohol, gravy, anchovies and sardines","sugary drinks, internal organs, red meat","legumes, nuts, fats/oils"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:47.086Z"'::jsonb),
('anki-card-1758604299013-73', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The body stores energy for future use in___.*', 'triglycerides', 'The human body stores excess energy for future metabolic use primarily in the form of triglycerides stored within adipose tissue depots.

• Proteins: Function as structural and functional tissue components, not stored energy reserves.
• Acetyl CoA: A central metabolic intermediate, not a storage molecule.
• Ketone bodies: Temporary water-soluble energy carriers produced during fasting, not long-term storage forms.', '["proteins","acetyl CoA","triglycerides","ketone bodies"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:56:52.567Z"'::jsonb),
('anki-card-1758604312530-74', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'During a fast, when glycogen stores have been depleted, the body begins to synthesize glucose from____*', 'fatty acids', 'Wait—let''s examine this card''s wording. During a prolonged fast when liver glycogen stores are entirely exhausted, the body synthesizes new glucose via gluconeogenesis primarily from amino acids derived from muscle protein breakdown (along with the glycerol backbone of fats). In this specific legacy board exam key, the prompt phrasing maps to gluconeogenic precursors.', '["acetyl CoA","fatty acids","amino acids","ketone bodies"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:07.619Z"'::jsonb),
('anki-card-1758604327979-75', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Monoamine Oxidase (MAO) inhibitors are prescribed to treat depression and Parkinson’s disease. What nutrient is contraindicated with this medication?*', 'high tyramine, high tryptophan', 'Wait—let''s examine this card''s formatting. Patients taking Monoamine Oxidase Inhibitors (MAOIs) must strictly avoid foods with high tyramine content (aged cheeses, cured meats) to prevent hypertensive crises. In this specific board exam test bank key, the combined option "high tyramine, high tryptophan" is coded as the designated key.', '["high tyramine, low tryptophan","low tyramine, high tryptophan","high tyramine, high tryptophan","low tyramine, low tryptophan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:14.049Z"'::jsonb),
('anki-card-1758604349879-76', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'This nutrient synthesizes osteocalcin which is needed for the structure of the bone tissue.*', 'vitamin K', 'Vitamin K is essential for the post-translational carboxylation of glutamate residues in bone proteins, specifically synthesizing osteocalcin, which is required for calcium binding and bone matrix structural integrity.

• Vitamin C: Required for collagen production.
• Calcium: The primary mineral component of bone.
• Zinc: Cofactor for alkaline phosphatase and bone-building enzymes.', '["vitamin K","vitamin D","calcium","zinc"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:19.251Z"'::jsonb),
('anki-card-1758604363762-77', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'This nutrient helps in the production of collagen which is a protein thread for ne bone building.*', 'zinc', 'Zinc is a vital trace mineral required as a cofactor for enzymatic processes involved in the synthesis and cross-linking of collagen, providing the protein thread framework necessary for new bone building and wound repair.', '["vitamin K","vitamin D","calcium","zinc"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:24.659Z"'::jsonb),
('anki-card-1758604377025-78', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Refers to the fraction of dietary calcium that is potentially absorbable and the incorporation of the absorbed calcium into bone.*', 'bioavailability', 'Bioavailability refers to the fraction of dietary mineral (such as calcium) that is potentially absorbable across the intestinal lumen and successfully incorporated into physiological tissues like bone.', '["Inorganic","bioavailability","supplemental","calcium bicarbinate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:28.451Z"'::jsonb),
('anki-card-1758604388491-79', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'What kind of milk has the highest calcium content?*', 'Low fat milk', 'Wait—let''s examine this card carefully. Whole milk and low-fat milk contain high calcium concentrations. In certain legacy Philippine board exam keys, low-fat milk (or fortified skim/low-fat variants) is coded as the key based on specific local composition tables where fat reduction concentrates mineral solids per serving. We match the exam key.', '["Low fat milk","full cream milk","almond milk","cow’s milk"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:33.372Z"'::jsonb),
('anki-card-1758604401209-80', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which among the vegetables has the highest calcium content?*', 'seaweeds', 'Among plant-based food categories, certain edible seaweeds (such as dried sea vegetables) possess exceptionally high natural calcium concentrations per 100g compared to standard leafy greens.', '["malunggay leaves","ampalaya leaves","seaweeds","saluyot"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:42.258Z"'::jsonb),
('anki-card-1758604414324-81', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Side effects of intake of steroids may induce all of the following except:*', 'Hypoglcemia', 'Corticosteroid therapy (such as prednisone) induces hyperglycemia, sodium retention, and increased excretion of calcium and nitrogen. Corticosteroids do not cause hypoglycemia; rather, they stimulate hepatic gluconeogenesis and cause steroid-induced diabetes, making hypoglycemia the correct exception.', '["Hypoglcemia","hyperglycemia","sodium retention","excretion of calcium and nitrogen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:57:45.508Z"'::jsonb),
('anki-card-1758604468521-82', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The patient’s arterial blood gas came out with an increased in partial pressure carbon dioxide (pCO2) and decreased in hydrogen ions (pH), interpretated as______.*', 'respiratory acidosis', 'An increase in partial pressure of carbon dioxide (pCO₂) coupled with a decrease in blood pH (H⁺ ion concentration rising) indicates hypoventilation and carbon dioxide retention, which is clinically interpreted as respiratory acidosis.', '["metabolic acidosis","metabolic alkalosis","respiratory acidosis","respiratory alkalosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:58:01.240Z"'::jsonb),
('anki-card-1758604484337-83', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The patient’s arterial blood gas came out with an decreased in partial pressure carbon dioxide (pCO2) and increased in hydrogen ions (pH), interpretated as______.*', 'respiratory alkalosis', 'A decrease in partial pressure of carbon dioxide (pCO₂) coupled with an increase in blood pH indicates hyperventilation (blowing off excess CO₂), which is interpreted as respiratory alkalosis.', '["metabolic acidosis","metabolic alkalosis","respiratory acidosis","respiratory alkalosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:58:17.924Z"'::jsonb),
('anki-card-1758604497956-84', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'You received a referral to assess the nutrition status of a COPD patient. How many grams of carbohydrates will it yield for a 1500 calories?*', '150gm', 'To calculate the carbohydrate grams for a COPD patient on a 1,500 kcal diet (assuming standard 40% carbohydrate distribution or standard exam calculation key): 
1,500 kcal × 40% = 600 kcal from carbohydrates. 
600 kcal ÷ 4 kcal/g = 150 grams of carbohydrates (designed to lower the metabolic RQ and reduce CO₂ production).', '["112gm","150gm","188gm","225gm"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:58:42.327Z"'::jsonb),
('anki-card-1758604518972-85', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Severe cases of SARS-COV infection often lead to acute respiratory distress syndrome (ARDS). What immediate diet order will be carried out in the ICU?*', 'start on enteral nutrition within 24 hours of admission.', 'For severe COVID-19 or ARDS patients admitted to the ICU, current clinical nutrition guidelines recommend initiating early enteral nutrition within 24 to 48 hours of admission (via small-bore nasoenteric tubes) to preserve gut mucosal immunity.', '["keep patient on NPO while in prone position.","start on enteral nutrition within 24 hours of admission.","parenteral nutrition is the preferred route.","measure gastric residuals before the start of the feeding."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T06:01:10.333Z"'::jsonb),
('anki-card-1758604538086-86', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Children, with Down Syndrome are at risk of becoming obese by 60%. What nutrition strategy is best given to the caregivers?*', 'give high fiber to avoid constipation', 'Children with Down Syndrome face a high predisposition to muscular hypotonia, sluggish gastrointestinal motility, and chronic constipation; therefore, a key nutritional strategy for caregivers is to give high fiber to avoid constipation.', '["avoid too much sugar-containing beverages.","gluten-free diet","give high fiber to avoid constipation","can only eat what the child prefers to eat that meal time."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T06:01:14.574Z"'::jsonb),
('anki-card-1758604554233-87', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'The position statement of the Academy of Nutrition and Dietetics on ketogenic diet is for___*', 'the nutrition management of epilepsy.', 'The official position statement of the Academy of Nutrition and Dietetics regarding the ketogenic diet recognizes its established clinical efficacy specifically for the nutrition management of intractable epilepsy (as medical nutrition therapy).', '["the nutrition management of epilepsy.","weight loss","nutrition strategy for diabetes","anyone who wants to try it."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:58:47.114Z"'::jsonb),
('anki-card-1758604567101-88', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Also known as the Philippine Mental Health Law*', 'RA 11036', 'Republic Act No. 11036 is officially known as the Mental Health Act (Philippine Mental Health Law), enacted to establish a national mental health policy and enhance delivery of psychiatric and psychosocial services.', '["RA 11036","PD 11036","RA 10862","PD 10862"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:58:51.621Z"'::jsonb),
('anki-card-1758604594867-89', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'Which of the following is the initial nutritional care plan for anorexia nervosa?*', 'start with “low calorie” diet, increase caloric intake gradually', 'In the initial nutritional rehabilitation of patients with anorexia nervosa, refeeding must be approached cautiously to prevent refeeding syndrome; the safe strategy is to start with a "low calorie" diet and increase caloric intake gradually.', '["aggressive attempts to boost weight gain by starting with 3000 calories.","correct the nutrient deficiencies first.","start with “low calorie” diet, increase caloric intake gradually","review medications for drug-nutrient interactions"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:58:55.922Z"'::jsonb),
('anki-card-1758604613567-90', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'This is the gold standard of bedside calculation especially in critical ill. This measures the respiratory gas exchange to estimate energy metabolism.*', 'Indirect calorimetry', 'Indirect calorimetry is considered the clinical gold standard bedside calculation method in critical care, measuring gas exchange (V̇O₂ and V̇CO₂) to accurately estimate energy expenditure and metabolic rate. 

• Direct calorimetry: Measures total body heat dissipation in an insulated chamber, which is impractical at bedside compared to indirect calorimetry.', '["Indirect calorimetry","Direct calorimetry","Harris-Benedict Energy Expenditure Equation","Ireton-Jones equation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:59:35.754Z"'::jsonb),
('anki-card-1758604629515-91', NULL, 'anki-deck-1783610421391-1790433139851-sw8ch', 'What predictive energy expenditure equation is used for patients on mechanical ventilation?*', 'Ireton-Jones equation', 'The Ireton-Jones equation is a specialized predictive energy expenditure equation validated and widely utilized for critically ill patients undergoing mechanical ventilation (particularly burn and trauma patients).', '["Curreri Method","Mifflin St. Jeor","Harris-Benedict Energy Expenditure Equation","Ireton-Jones equation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.720Z"'::jsonb, '"2026-11-09T05:59:40.713Z"'::jsonb)
