INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758445789524-92', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'What is the macronutrient composition post competition or during the recovery phase?*', '75% CHO, 10% Protein, 15% Fat', 'During intense prolonged competition, muscle glycogen stores are severely depleted, and glycogen synthase activity is acutely upregulated. Consuming 75% of calories as high-glycemic carbohydrates stimulates a robust insulin surge, driving intracellular GLUT4 translocation and accelerating glucose uptake into skeletal muscle cells. Including 10% protein supplies essential amino acids—specifically leucine—to activate the mTORC1 pathway for muscle protein synthesis and further enhance insulin secretion. Restricting dietary fat to 15% is critical because high fat content retards gastric emptying and chyme transit, which slows down the intestinal absorption rate of glucose and amino acids required for rapid recovery.', '["60% CHO, 20% Protein, 20% Fat","65% CHO, 15% Protein, 20% Fat","70% CHO, 10% Protein, 20% Fat","75% CHO, 10% Protein, 15% Fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:43:53.251Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-09T08:43:53.251Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:43:53.251Z"'::jsonb),
('anki-card-1758445803141-93', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'Compute for the carbohydrate requirement of a 65kg tri-athlete.*', '520g to 650g Carbohydrates', 'In sports dietetics, endurance athletes undergoing heavy training blocks—such as triathletes—have exceptionally high daily fuel demands. To fully sustain performance, protect immune health, and keep glycogen stores saturated, standard clinical textbooks and sports organizations recommend a daily carbohydrate intake multiplier of 8 to 10 grams of carbohydrate per kilogram of body weight (8 to 10 g/kg/day).

Lower Bound Target: 65 kg x 8 g/kg = 520 g of carbohydrates
Upper Bound Target: 65 kg x 10 g/kg = 650 g of carbohydrates

• 390g to 780g: This uses a wide-spanning scale of 6 to 12 g/kg. While 6 g/kg can apply to general fitness or lighter training days, the target range for competitive endurance sport preparation specifically centers on the highly dense 8 to 10 g/kg model.', '["520g to 650g Carbohydrates","780g to 845g Carbohydrates","390g to 780g Carbohydrates","420g to 550g Carbohydrates"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:43:47.166Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-09T08:43:47.166Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:43:47.166Z"'::jsonb),
('anki-card-1758445829391-94', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'Compute for the protein requirement of a 55kg boxer.*', '95g to 99g Protein', 'According to the International Society of Sports Nutrition (ISSN) and joint positions by the Academy of Nutrition and Dietetics, athletes involved in intense endurance and strength-based disciplines—like boxing—require a higher daily intake range of 1.2 to 2.0 grams of protein per kilogram of body weight. Combat athletes regularly training at an elite level or cutting weight frequently hit upper targets of 1.8 to 2.0+ g/kg to ensure adequate muscle tissue repair, recovery, and lean mass preservation.

Target Baseline Intake: 55 kg x 1.8 g/kg = 99 g of protein
Lower Bound Target: 55 kg x 1.73 g/kg = 95 g of protein

• 55g to 75g: This range uses a lower calculation factor (1.0 to 1.36 g/kg). While 1.0 g/kg is perfectly fine for a sedentary individual or a recreational gym-goer, it is completely insufficient to maintain nitrogen balance and muscle recovery for a competitive combat sport athlete undergoing strenuous training cycles.', '["95g to 99g Protein","66g to 85g Protein","55 g to 75g Protein","75g to 120g Protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:15:55.743Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T08:15:55.743Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:15:55.848Z"'::jsonb),
('anki-card-1758445845323-95', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'What is the choice of fuel to sustain a high intensity exercise that lasts between 3 to 20 minutes?*', 'Carbohydrate and some fat', 'During high-intensity exercise sustained from 3 to 20 minutes, the predominant energy system transitions from immediate phosphagen pathways to rapid glycogenolysis and glycolysis, which generate ATP rapidly via carbohydrate oxidation. Because this duration exceeds immediate ATP-PCr capacity yet allows sufficient oxygen delivery for mixed-substrate metabolism, aerobic and anaerobic pathways operate simultaneously. Fat oxidation contributes a measurable percentage of total energy expenditure, particularly as the exercise duration extends past 5 minutes and reliance shifts partially toward oxidative phosphorylation.', '["Protein and BCAA","Carbohydrate only","Carbohydrate and protein","Carbohydrate and some fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:40:32.719Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T08:40:32.719Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:40:32.719Z"'::jsonb),
('anki-card-1758445859406-96', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'What is the synthesis of glucose from non-carbohydrate precursors?*', 'Gluconeogenesis', 'Gluconeogenesis literally translates to "the creation of new glucose." It is the metabolic pathway through which the body synthesizes glucose from non-carbohydrate precursors—such as lactate, glycerol, and glucogenic amino acids (like alanine and glutamine).

This process occurs primarily in the liver (and to a lesser extent in the kidneys) during periods of fasting, starvation, low-carbohydrate intake, or intense exercise to maintain critical blood glucose levels and fuel glucose-dependent organs like the brain.

• Glycogenolysis: The biochemical breakdown of stored glycogen into glucose, meaning it uses a carbohydrate source rather than a non-carbohydrate precursor.
• Phosphagen system: An anaerobic energy pathway that uses stored ATP and creatine phosphate to provide immediate energy during short, explosive bursts of exercise, carrying no role in glucose synthesis.
• Lipolysis: The metabolic breakdown of triglycerides (fats) into glycerol and free fatty acids. While the glycerol byproduct can enter gluconeogenesis, lipolysis itself is the breakdown of fat, not the synthesis of glucose.', '["Glycogenolysis","Phosphagen system","Gluconeogenesis","Lipolysis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T15:41:12.363Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T15:41:12.363Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T15:41:12.494Z"'::jsonb),
('anki-card-1758445870672-97', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'The following are adverse effects of protein overload except*', 'Fatigue', 'Fatigue is generally not considered a direct physiological adverse effect of acute protein overload. While low carbohydrate intake (often a byproduct of extreme high-protein dieting) can lead to lethargy or sluggishness from low glycogen stores, the structural overload of protein metabolism itself doesn''t characteristically induce fatigue as a primary metabolic side effect.

• Kidney and liver damage: Processing high loads of protein forces the liver to convert toxic byproducts (like ammonia) into urea, while forcing the kidneys to filter out this massive increase in nitrogenous waste. Over time, this significantly elevates the workload and can precipitate or accelerate kidney and liver strain, particularly in individuals with underlying or pre-existing renal compromise.
• Calcium deficiency: High-protein intake (specifically from animal sources rich in sulfur-containing amino acids) generates a high dietary acid load in body fluids. To buffer this systemic acidity, the body resorbs bone minerals, causing an influx of calcium loss through the urine (hypercalciuria), which can compromise long-term bone density if calcium intake is inadequate.
• Dehydration: The elimination of excess blood urea nitrogen requires a substantial amount of fluid to flush the waste out through the urinary tract. This constant osmotic diuresis rapidly depletes body fluids, leading to subclinical or clinical dehydration if the individual does not aggressively increase their water intake to compensate.', '["Kidney and liver damage","Dehydration","Calcium deficiency","Fatigue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T14:48:37.950Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T14:48:37.950Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T14:48:38.032Z"'::jsonb),
('anki-card-1758445883555-98', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'What type of fluid must be avoided 1 hour before a competition?*', 'Cold milk', 'Fluids high in protein and saturated fats—such as milk—take a significantly longer time to digest and exit the stomach. Consuming milk just one hour before a competition slows gastric emptying and heavily increases the risk of gastrointestinal (GI) distress, abdominal cramps, bloating, and nausea during intense physical activity.

In the hour directly leading up to an athletic event, fluid intake should prioritize rapid gastric clearance and hydration.', '["Cold water","100% fruit juice","Electrolyte drink","Cold milk"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-09T10:14:02.057Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-08T10:14:02.057Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-08T10:14:02.203Z"'::jsonb),
('anki-card-1758445896204-99', NULL, 'anki-deck-1783610430222-1790433140271-gx1a3', 'Which supplement may delay mental fatigue among athletes?*', 'Branched Chain Amino Acid', 'During prolonged or high-intensity endurance exercise, free fatty acid levels in the blood rise, causing a surge in free tryptophan. Tryptophan crosses the blood-brain barrier and converts into serotonin—the neurotransmitter responsible for inducing drowsiness, muscle relaxation, and mental/central fatigue.

Branched-Chain Amino Acids (BCAAs)—which include leucine, isoleucine, and valine—share the exact same transport carrier into the brain as tryptophan. By increasing BCAA concentrations in the bloodstream, these amino acids outcompete and block tryptophan from entering the brain. This effectively limits serotonin production, allowing athletes to maintain mental focus, perceive less exertion, and delay the onset of mental exhaustion during heavy training sessions.', '["Glutamine","Creatine Monohydrate","Probiotics","Branched Chain Amino Acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T08:29:46.266Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-09T08:29:46.266Z"'::jsonb, '"2026-09-26T14:32:29.208Z"'::jsonb, '"2026-10-09T08:29:46.266Z"'::jsonb),
('anki-card-1758440308708-0', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The prevalence of malnutrition among hospitalized patient worldwide is:*', '20 to 50%', 'Globally accepted clinical data from large-scale screening initiatives (such as the nutritionDay worldwide database) establish that 20% to 50% of hospitalized patients suffer from disease-related malnutrition at the time of admission or develop it during their hospital stay.

This wide statistical variance depends heavily on:
1. The specific country or healthcare region.
2. The specific patient population (e.g., intensive care, oncology, or geriatric populations experience much higher rates up to 90%).
3. The individual screening tool or diagnostic criteria used by the facility (such as the NRS-2002, MUST, or GLIM criteria).', '["20 to 48 %","20 to 50%","30 to 50 %","25 to 50 %"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:43.915Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:43.915Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:43.990Z"'::jsonb),
('anki-card-1758440331523-1', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59 year old, female, Chief Executive Officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a BMI (Body mass Index) was admitted in the hospital due to a TIA which stands for*', 'Transient Ischemic Attack', 'Transient Ischemic Attack', '["Mini Stroke","Transient Ischemic Attack","Transient Ischemic Heart Attack","Cerebrovascular Stroke"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-13T11:45:50.148Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-10T11:45:50.148Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758440472182-2', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59-year-old female, Chief Executive Officer of a telecommunications office, whose height is 5’5” and weight is 93 kg was admitted in the hospital due to a Transient Ischemic Attack (TIA).

Using the data on the height and weight, her BMI is:*', '34.1', 'To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).
1. Convert Height to Meters:
	• 5 feet 5 inches = 65 inches
	• 65 inches × 0.0254 = 1.651 meters
2. Calculate Height Squared:
	• 1.651 x 1.651 = 2.7258
3. Calculate BMI:
	• BMI} = 93 / 2.7258 = 34.118 ~ 34.1 kg/m²', '["35","34.5","34.1","35.99"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:49:29.065Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:49:29.065Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:49:29.065Z"'::jsonb),
('anki-card-1758440517464-3', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59 year old, female, Chief Executive Officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a BMI (Body mass Index) was admitted in the hospital due to a TIA which stands for*
JD’s BMI is classified as*', 'Obese Class 1', 'To classify JD''s BMI, we first must compute it using the standard metric formula: BMI = Weight (kg) / Height (m²).

1. Convert Height to Meters:
	• 5 feet 5 inches = 65 inches
	• 65 inches × 0.0254 = 1.651 meters
2. Calculate BMI:
	• BMI = 93 ÷ (1.651)²
	• BMI = 93 ÷ 2.726
	• BMI = 34.12

Under the official WHO BMI Classification Guidelines, the cut-off ranges are as follows:
• Overweight: 25.0 to 29.9
• Obese Class 1: 30.0 to 34.9
• Obese Class 2: 35.0 to 39.9
• Obese Class 3 (Morbid Obesity): 40.0 or higher

Because JD''s calculated BMI is 34.12, it sits firmly inside the 30.0 to 34.9 range, making it Obese Class 1 by global definitions.', '["Overweight","Obese Class 1","Obese Class 2","Morbidly Obese"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T10:07:26.700Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T10:07:26.700Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T10:07:26.795Z"'::jsonb),
('anki-card-1758440553710-4', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Case Scenario: JD, a 59-year-old female Chief Executive Officer of a telecommunications office who is 5’5” tall and weighs 93 kg, was recently admitted to the hospital due to a Transient Ischemic Attack (TIA). Using the NDAP formula, JD’s Recommended Body Weight is*', '57.27 kg', 'The NDAP formula for females is 106 lbs for the first  5 feet (60 inches) of height ± 4 lbs for every inch above or below 5 feet.

1. Calculate the height allowance.
5''5" tall = 106 lbs + (5 inches x 4 lbs/inch) = 126 lbs

2. Convert pounds to kilograms.
126 lbs ÷ 2.2 = 57.27 kg', '["50 kg","65 kg","58.59 kg","57.27 kg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:49:44.800Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:49:44.800Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:49:44.800Z"'::jsonb),
('anki-card-1758440572743-5', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'This nutrition screening tool is validated and used for Elderly patients:*', 'Mini Nutrition Assessment (MNA)', 'Mini Nutrition Assessment (MNA)', '["Subjective Global Assessment","Nutrition Risk Screening 2002","Mini Nutrition Assessment (MNA)","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:17:58.572Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:17:58.572Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758440594460-6', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'How can medications affect the nutritional status of older adults?*', 'all of the above', 'all of the above', '["alter food intake, absorption of nutrients, and excretion","decrease food appetite, taste, and smell","cause gastrointestinal disturbances, such as constipation","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:59:45.581Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:59:45.581Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758440603577-7', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In writing prescriptions, t.i.d means*', 'Three times a day', 'Three times a day', '["Three times a day","Two times a day","twice daily","thrice a week"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T12:10:38.515Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T12:10:38.515Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758440628740-8', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'LR, a 67 year old man who has had depression was prescribed a MAOI (Monoamine Oxidase Inhibitor) the following foods are avoided except:*', 'Green Tea', 'Green tea is the exception among the listed options because it contains minimal to negligible levels of tyramine and is primarily composed of catechins, flavonoids, and caffeine. Unlike fermented, aged, or protein-degraded foods, green tea does not provoke dangerous systemic vasoconstriction when combined with MAOIs.', '["Avocado","Bean curd","Aged Cheese","Green Tea"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:05:11.881Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:05:11.881Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:05:11.982Z"'::jsonb),
('anki-card-1758440670622-9', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Patients taking COUMADIN are advised not to increase or decrease their usual consumption of the following foods, EXCEPT:*', 'Bologna', 'Coumadin works by inhibiting vitamin K-dependent blood clotting factors. Patients are advised to keep their consumption of foods containing Vitamin K or items that alter blood coagulation steady and consistent from week to week. Sudden changes can make the medicine less effective or increase bleeding risks.

Broccoli is high in Vitamin K, while green tea and onions can fluctuate or alter Coumadin''s efficacy. Therefore, patients are told not to drastically increase or decrease their intake of these foods.

Bologna is a processed meat sausage. Meats and processed deli products inherently contain extremely low to negligible amounts of Vitamin K. Altering the amount of bologna in a patient''s daily diet has no clinical impact on their international normalized ratio (INR) values or Coumadin''s blood-thinning behavior, making it the correct exception.', '["Green tea","Bologna","Broccoli","Fried Onions"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:50:47.859Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:50:47.859Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:50:47.859Z"'::jsonb),
('anki-card-1758441427800-10', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Fluoroquinolones (Ciprofloxacin, levofloxacin) must not be taken with the following foods except:*', 'Papaya', 'Fluoroquinolones (such as ciprofloxacin and levofloxacin) are a powerful class of broad-spectrum antibiotic medications. They work by blocking bacterial enzymes, which completely stop bacteria from replicating and repairing their DNA, effectively killing off the infection.

Because fluoroquinolones are highly reactive chemicals, what you put in your stomach at the same time matters immensely. The drug molecules have a strong tendency to attach themselves tightly to divalent minerals like calcium.

Papaya contains no significant minerals or compounds that chelate or alter the breakdown of fluoroquinolone antibiotics, making it safe to eat.

• Dairy Products, Yogurt, and Cottage Cheese: Dairy products are packed with calcium. Calcium binds directly to fluoroquinolones in the gut (a process called chelation). This binding forms an insoluble compound that the body cannot absorb, which severely drops the drug levels and makes the antibiotic ineffective.
• Caffeine: Fluoroquinolones block the liver pathways that break down caffeine. If you consume caffeine while taking these antibiotics, caffeine accumulates in your body, risking severe side effects like a dangerously fast heartbeat, extreme jitteriness, and insomnia.', '["Papaya","Yogurt, Cottage Cheese","Caffeine","Dairy Products"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:49:20.342Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:49:20.342Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:49:20.414Z"'::jsonb),
('anki-card-1758441445101-11', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'JCAHO targeted the following drugs for specific monitoring for in and out patients except*', 'Allopurinol', 'The Joint Commission (formerly JCAHO) establishes strict National Patient Safety Goals tracking high-alert medications that present elevated risks of patient harm if managed improperly.

Allopurinol is designated as the target exception because the question is grouping high-monitoring medications based on their potential to cause a critical, common clinical side effect that dietitians must track: Drug-Induced Hyperglycemia (Spiking Blood Sugar) or severe, immediate metabolic parameter shifts. Allopurinol is a xanthine oxidase inhibitor used to treat gout by lowering uric acid. While it requires kidney tracking, it does not disrupt a patient''s glycemic/blood glucose control mechanics like the other choices do.

Corticosteroids like Dexamethasone severely alter glucose pathways and trigger massive blood sugar spikes, while Sucralfate is a dense aluminum-sucrose complex that physically alters how carbohydrates are absorbed in the gut. Warfarin demands intensive systemic monitoring.', '["Allopurinol","Warfarin","Dexamethasone","Sucralfate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:02.572Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:02.572Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:02.572Z"'::jsonb),
('anki-card-1758441458799-12', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Patients on anti-tuberculosis treatment are at risk of which vitamin deficiency?*', 'Vitamin B 6', 'Patients undergoing standard anti-tuberculosis treatment are at a high risk for developing a Vitamin B6 (Pyridoxine) deficiency.

This deficiency is directly caused by Isoniazid (INH), one of the primary first-line antibiotics used to treat tuberculosis. Isoniazid competes with and blocks Vitamin B6 metabolism in the body and accelerates its excretion through urine.

If Vitamin B6 is not supplemented during anti-TB therapy, the patient can develop severe peripheral neuropathy, which manifests as painful burning, numbness, and tingling sensations in the hands and feet.', '["Vitamin B 1","water soluble vitamins","Vitamin B 6","Vitamin B 12"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:12.142Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:12.142Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:12.142Z"'::jsonb),
('anki-card-1758441479264-13', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'EK, is a 27 year old woman, admitted to the hospital with severe Crohn’s disease and an unintentional weight loss of 20 pounds over the past two months despite a good appetite. Assuming that EK has steatorrhea, what is the most likely cause of her weight loss?*', 'Malabsorption', 'Crohn’s disease is a type of inflammatory bowel disease (IBD) that causes chronic inflammation and ulceration along the gastrointestinal tract, most frequently affecting the ileum (the lower part of the small intestine).

When the small intestine is severely inflamed, it cannot properly absorb nutrients from food into the bloodstream. The presence of steatorrhea (excess fat in the stool) is a classic indicator that fats and fat-soluble vitamins are not being digested or absorbed properly. Even though the patient has a good appetite and is eating well, the body is expelling the nutrients rather than utilizing them, leading to severe, unintentional weight loss due to malabsorption.', '["Obstruction","Malabsorption","Cancer","AIDS"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:42:43.165Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:42:43.165Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:42:43.253Z"'::jsonb),
('anki-card-1758441512948-14', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'PR, a 50-year-old woman with chronic pancreatitis, is hospitalized for surgical evaluation. PR was given pancreatic enzymes and can tolerate food. What diet order should be prescribed at this time?*', 'Low Fat Diet', 'Chronic pancreatitis is the long-term inflammation of the pancreas, which severely damages its ability to produce digestive enzymes—particularly lipase, the enzyme required to break down and absorb dietary fats.

When fat enters the small intestine, it stimulates the pancreas to secrete digestive enzymes. If the pancreas is inflamed, this stimulation causes severe, stabbing abdominal pain and can worsen tissue inflammation. Furthermore, undigested fat causes steatorrhea (foul-smelling, fatty stools) and nutrient malabsorption. A low-fat diet minimizes the workload on the pancreas, controls abdominal pain, and manages malabsorption.

Even though PR is taking supplemental pancreatic enzymes to help digest her food, keeping dietary fat intake low remains the primary nutritional therapy during an inpatient hospitalization or surgical evaluation period.', '["Low Fat Diet","Low Sodium Diet","Low Protein Diet","Low Fiber Diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:18:15.174Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:18:15.174Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:18:15.174Z"'::jsonb),
('anki-card-1758441526281-15', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Patients on long term use of steroids are recommended to take supplements:*', 'Calcium', 'Long-term corticosteroid therapy (such as prednisone) severely impacts bone metabolism and mineral density, putting patients at a very high risk for Steroid-Induced Osteoporosis. Steroids cause bone loss through multiple pathways:

1. They directly block the intestines from absorbing dietary Calcium.
2. They prompt the kidneys to flush out more calcium through urine.
3. They inhibit bone-building cells (osteoblasts) while stimulating bone-resorbing cells (osteoclasts).

To counteract this rapid bone wasting, clinical guidelines recommend that patients on long-term steroid therapy take Calcium and Vitamin D to protect bone integrity and prevent fractures.', '["Calcium","Vitamin D","Vitamin C","Vitamin E"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:08.683Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:08.683Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:08.757Z"'::jsonb),
('anki-card-1758441538629-16', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'HYPERSENSITIVITY REACTION involving the skin and mucous membrane*', 'Stevens Johnson Syndrome', 'Stevens-Johnson Syndrome (SJS) is a rare, life-threatening Type IV (delayed-type) cell-mediated hypersensitivity reaction. It is classically triggered by an adverse reaction to specific medications (like allopurinol, anti-seizure drugs, or antibiotics) or severe infections.

The defining clinical characteristic of SJS is its aggressive, painful destruction of both the skin and mucous membranes. It causes severe, blistering lesions, rash, and epidermal peeling across the skin, alongside excruciating sores in the moist linings of the mouth, throat, eyes, nose, and genitals.

• Lupus Erythematosus: This is a chronic Type III immune-complex autoimmune disease, not primarily a delayed hypersensitivity reaction of the mucocutaneous linings. While it causes a distinctive "butterfly rash" on the face, it lacks the acute, severe blister-peeling mucous membrane destruction seen in SJS.
• Food Sensitivity Reaction: True food allergies are Type I (immediate-type) IgE-mediated reactions that typically manifest as hives (urticaria), swelling (angioedema), or system-wide anaphylaxis within minutes of ingestion. They do not follow the severe multi-mucosal blistering disease spectrum characteristic of SJS.', '["Food Sensitivity reaction","Lupus Erythematosus","Stevens Johnson Syndrome","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:34.033Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:34.033Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:34.033Z"'::jsonb),
('anki-card-1758441549746-17', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following drugs are known to interact with grapefruit juice except:*', 'Metformin', 'Grapefruit juice interacts with medications by blocking the CYP3A4 enzyme in the intestinal tract. This blockage stops the normal breakdown of certain drugs, causing them to build up to dangerous levels in the bloodstream.

Metformin is a first-line medication for type 2 diabetes. The body does not rely on the CYP3A4 pathway to process or metabolize metformin, making it perfectly safe to consume with grapefruit juice without any known interaction.

• Anti-cholesterol drugs: Many common statins (like atorvastatin, simvastatin, and lovastatin) heavily interact with grapefruit juice. High drug levels from this interaction can cause a severe muscle-wasting condition known as rhabdomyolysis.
• Antidepressant/Psychiatric drugs: Several mood and antidepressant medications (such as sertraline, buspirone, and diazepam) are broken down by CYP3A4 and can reach toxic levels if mixed with grapefruit juice.
• Nifedipine: This calcium channel blocker for high blood pressure is notorious for reacting with grapefruit juice. The interaction can dramatically spike blood drug levels, risking dangerously low blood pressure and rapid heart rates.', '["Metformin","Antidepressant drugs","Anti-cholesterol drugs","Nifedipine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:48.342Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:48.342Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:48.342Z"'::jsonb),
('anki-card-1758441567011-18', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are anthropometric measurements for determining nutritional status except;*', 'Creatinine Height Index', 'Anthropometric measurements are non-invasive, physical dimensions taken directly from the human body to evaluate size, shape, and muscle-to-fat composition.

Creatinine Height Index is a biochemical (laboratory) test, not an anthropometric measurement. It requires measuring the 24-hour excretion of creatinine in a patient''s urine sample and comparing it against standard height markers to estimate total skeletal muscle depletion.', '["% Body weight","Triceps Skinfold measurement","Mid Arm muscle Circumference","Creatinine Height Index"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:57:18.082Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:57:18.082Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:57:18.166Z"'::jsonb),
('anki-card-1758441589328-19', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following food groups may be allowed on the MEDICAL KETOGENIC DIET THERAPY for Epilepsy EXCEPT :*', 'Angel cake, peanut butter, Lapid’s Chicaron', 'Angel cake, peanut butter, Lapid’s Chicaron', '["Angel cake, peanut butter, Lapid’s Chicaron","Pili nuts, Asparagus with Bacon strips, Fried Chicken","Lettuce Iceberg Salad with Vinegar dressing, Chicken Inasal, Unsweetened Jello","Cheese Lumpia, Nuts Porridge , Pistachio nuts"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:40:57.219Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:40:57.219Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758441602491-20', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following common beverages have High Caffeine content EXCEPT :*', 'Cola drinks', 'When comparing standard serving sizes of these common beverages, cola drinks contain the lowest amount of caffeine, typically averaging only 20–40 mg per standard serving.

• Brewed Coffee: Contains the highest amount of caffeine, typically averaging 95–150 mg per 8 oz cup.
• Instant Coffee: Contains a high amount of caffeine, typically averaging 60–80 mg per 8 oz cup.
• Leaf Tea: Brewed black or green leaf tea contains a moderate amount of caffeine, typically averaging 30–50 mg per 8 oz cup.', '["Leaf Tea","Instant Coffee","Cola drinks","Brewed coffee"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:47:03.481Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:47:03.481Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:47:03.481Z"'::jsonb),
('anki-card-1758441610942-21', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Chronic Malnutrition is a deficiency in*', 'Calories', 'Chronic energy deficiency forces the body into metabolic conservation by downregulating basal metabolic rate, reducing physical activity, and halting linear growth in pediatric populations. Prolonged caloric deficit causes the endocrine axis to suppress the growth hormone-insulin-like growth factor 1 (IGF-1) cascade, shunting minimal available energy toward vital organ function rather than tissue growth or maintenance.', '["Calories","Protein","Calories and Protein","Marasmic Kwashiorkor"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:20:21.654Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:20:21.654Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:20:21.799Z"'::jsonb),
('anki-card-1758441636857-22', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'A retrospective method of obtaining nutrient intake data, low level of respondent burden, can be self-administered, applicable to use for Pediatric patients 8 years old and above:*', 'food frequency questionnaire', 'Food Frequency Questionnaire is a retrospective method because it asks individuals to look back and report their usual intake patterns over a specified past time frame (e.g., weeks, months, or the past year). It features a low respondent burden because it relies on a simple checklist of pre-defined foods rather than detailed weighing or precise logging. It is easily self-administered and has been clinically validated as appropriate and reliable for pediatric patients starting at 8 years of age and older who have developed the cognitive and reading skills to recall food frequencies independently.', '["Direct food observation","24 food recall","food frequency questionnaire","food record"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:51:55.810Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:51:55.810Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:51:55.810Z"'::jsonb),
('anki-card-1758441653841-23', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'This specific enteral formula is ideal for this patient – 45 year old female, admitted to the Intensive Care Unit for CVD Infarct with left sided hemiparesis, GCS of 7, with abdominal distention and for possible tube feeding:*', 'Semi – elemental', 'When a critically ill patient in the Intensive Care Unit (ICU) presents with an altered level of consciousness (Glasgow Coma Scale score of 7) and abdominal distention, it indicates significant gastrointestinal dysmotility and feeding intolerance.

A semi-elemental (peptide-based) formula contains proteins that are already hydrolyzed into small dipeptides and tripeptides, along with easily absorbable fats like medium-chain triglycerides (MCTs). This pre-digested structure requires minimal enzymatic activity and is absorbed significantly faster and easier by the gut mucosa. Clinical studies prove that using a semi-elemental formula in the ICU under feeding intolerance conditions significantly reduces abdominal distention, lowers gastric residuals, and prevents feeding interruptions compared to standard options.', '["Semi – elemental","Polymeric","High Protein","High Fiber"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:40:41.073Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:40:41.073Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:40:41.212Z"'::jsonb),
('anki-card-1758441668256-24', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'A disease specific enteral formula indicated for patients with liver disease is*', 'Aminoleban EN', 'Aminoleban EN is a specialized, disease-specific enteral formula manufactured by Otsuka. It is meticulously engineered for the nutritional management of patients with liver disease, particularly chronic liver failure, liver cirrhosis, or hepatic encephalopathy.
Its unique clinical formula is heavily enriched with branched-chain amino acids (BCAAs)—including valine, leucine, and isoleucine—while keeping the levels of aromatic amino acids (AAAs) low. This specific ratio helps correct the altered amino acid profile in liver failure, helping prevent or reverse symptoms of hepatic encephalopathy.

	• Juvenaid & Abound: Specialized therapeutic formulas (containing HMB, Arginine, and Glutamine) designed to promote wound healing and tissue repair, not for hepatic failure.
	• Nutribest: A general polymeric formula used for overall nutrition maintenance and macro/micronutrient supplementation.', '["Abound","Juvenaid","Nutribest","Aminoleban EN"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:19:23.919Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:19:23.919Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:19:24.051Z"'::jsonb),
('anki-card-1758441686706-25', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The types of Medical Ketogenic Diet for Epilepsy in Children are the following except:*', 'South Beach Diet', 'There are four primary types of medically supervised dietary therapies used to treat drug-resistant epilepsy in children. These include the Classical Ketogenic Diet, the Modified Atkins Diet (MAD), the Low Glycemic Index Treatment (LGIT), and the Medium-Chain Triglyceride (MCT) diet.

The South Beach Diet is a commercial weight-loss plan focused on lean proteins and healthy fats. Unlike medical ketogenic therapies, it is not designed, structured, or used as a clinical treatment for pediatric epilepsy or seizure control.', '["Classical Ketogenic Diet","Modified Atkins Diet for Epilepsy","South Beach Diet","Low Glycemic Index"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:52:07.112Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:52:07.112Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:52:07.112Z"'::jsonb),
('anki-card-1758441696638-26', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In the Medical chart , the Medical Prefix " phagia " means :*', 'to eat', 'In medical terminology, the suffix (or root element) "-phagia" comes from the Greek word phagein, which means to eat or swallow.
Examples of its use include:
• Dysphagia: Difficulty swallowing or eating.
• Polyphagia: Excessive eating or extreme hunger.
• Aphagia: The inability to swallow.

For the other choices:
• Pain is represented by the suffix -algia or -dynia (e.g., neuralgia).
• Fear of is represented by the suffix -phobia (e.g., hydrophobia).
• Methyl Cellulose is a bulk-forming laxative and unrelated to this medical prefix.', '["fear of","to eat","fear of","pain"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:15:13.591Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:15:13.591Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:15:13.677Z"'::jsonb),
('anki-card-1758441714437-27', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'QA is placed on long-term prednisone treatment. What two complications of high-dose prednisone therapy require nutritional intervention?*', 'weight gain that may lead to obesity', 'When a patient undergoes long-term, high-dose corticosteroid treatment like prednisone, the drug fundamentally alters systemic metabolism, presenting complications that heavily demand structured nutritional intervention.

Prednisone significantly alters hunger and satiety neurological cues, triggering intense appetite stimulation, constant food cravings, and metabolic fat redistribution. This rapid increase in calorie intake, coupled with sodium and fluid retention, leads to rapid weight gain and obesity if left unmanaged, necessitating low-calorie, low-sodium weight control diets.', '["weight gain that may lead to obesity","anorexia that may lead to weight loss","hyperglycemia","hypoglycemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:44:04.546Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:44:04.546Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:44:04.631Z"'::jsonb),
('anki-card-1758441747837-28', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'BF is a 61-year-old female diagnosed with Cancer of the Stomach and has been bedridden for the past one month; Height 5’6’’, Weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 Calories per day. The Attending Physician decided to give her Parenteral Nutrition prior to a contemplated procedure.

Which of the following TNA (Total Nutrient Admixture) is best for this patient?*', 'Nutriflex 1000 in 1250 ml', 'Patient BF is severely malnourished, has lost 10% of her body weight over 3 months, and has been surviving on a starvation-level intake of only 700 Calories per day. When a patient is chronically starved, starting Parenteral Nutrition at a full calorie load (like 1,400 or 1,500 Calories) can trigger fatal electrolyte shifts (hypophosphatemia, hypokalemia, and hypomagnesemia).

Standard safety guidelines dictate that for severely malnourished or starved patients, clinicians must "start low and go slow." Nutritional support should be initiated at a conservative baseline of 15 to 20 kcal/kg of body weight. For a 50 kg patient, this equals an initial daily energy target of roughly 750 to 1,000 Calories.

Nutriflex 1000 in 1250 ml delivers exactly 1,000 Calories in a safe, controlled volume. This makes it the ideal, safe starter formula to initiate her clinical feeding therapy without triggering refeeding syndrome.', '["Nutriflex 1000 in 1250 ml","Nutriflex 1400 in 1875 ml","Nutriflex 1500 in 1250 ml.","Nutriflex 1900 in 2500 ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:52:20.178Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:52:20.178Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:52:20.178Z"'::jsonb),
('anki-card-1758441767886-29', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'BF is a 61-year-old female diagnosed with Cancer of the Stomach and has been bedridden for the past one month; Height 5’6’’, Weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 Calories per day. The Attending Physician decided to give her Parenteral Nutrition prior to a contemplated procedure.

If patient BF in question 29 will transition to an oral diet with oral nutrition supplementation, what enteral feeding formula can be recommended for BF?*', 'Supportan', 'Supportan (manufactured by Fresenius Kabi) is a specialized, disease-specific medical nutrition formula engineered explicitly for cancer patients experiencing or at risk of cancer cachexia (weight loss and muscle wasting). It is high in calories, high in protein, and crucially enriched with EPA (Eicosapentaenoic Acid)—an omega-3 fatty acid that clinically down-regulates the systemic tumor-induced inflammation driving tissue breakdown.

	• Ensure Gold & Ensure Vigor: These are standard polymeric formulas meant for general adult maintenance or age-related muscle loss, not targeted cancer care.
	• Alitraq: This is a specialized elemental/peptide-based formula enriched with glutamine, meant for patients with severely impaired GI tract absorption or trauma, rather than oncology-specific needs.', '["Ensure Vigor","Ensure Gold","Alitraq","Supportan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:45:42.489Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:45:42.489Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:45:42.489Z"'::jsonb),
('anki-card-1758441867713-30', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are Polymeric formula containing except:*', 'Nutrican', 'Nutrican is not a standard polymeric formula. It is a disease-specific, specialized formula meticulously engineered for oncology (cancer) patients. It contains specialized immune-modulating nutrients, specialized high-protein segments, and EPA (omega-3 fatty acids) targeting the prevention of cancer cachexia (muscle wasting) rather than general standard requirements.

Ensure Gold, Nutren Fiber, and Fresubin Fiber are all classic polymeric (standard) enteral formulas. They contain intact, non-hydrolyzed macros (whole proteins, complex carbohydrates, and long-chain fats) designed for patients with normal gastrointestinal digestion and absorptive capacities.', '["Ensure Gold","Nutren Fiber","Fresubin Fiber","Nutrican"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:53:40.035Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:53:40.035Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:53:40.120Z"'::jsonb),
('anki-card-1758441879845-31', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following diet history method reduces error due to reliance on “recall”*', 'Food Diary / record', 'Food Diary / Record is a prospective method. The patient or respondent is instructed to log, weigh, or estimate all food and beverages in real-time at the exact moment they are being consumed. Because the data is documented immediately as the eating event happens, it completely eliminates the reliance on human memory or "recall".

On the other hand, the 24-Hour food recall, Food frequency questionnaire, and generic Nutrient intake records are all retrospective methods. They require the patient to look back in time and mentally reconstruct what they ate over the past day, week, or month. As a result, these three methods are highly vulnerable to severe memory lapses, recall bias, and portion-estimation errors.', '["Nutrient Intake record","Food Diary / record","24 Hour food recall","Food frequency"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:52:38.697Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:52:38.697Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:52:38.697Z"'::jsonb),
('anki-card-1758441891030-32', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Anticipated need for tube feeding will require < 6-8 weeks*', 'nasogastric', 'Enteral feeding access routes are primarily selected based on the anticipated duration of the nutritional support:

• Short-Term Support (< 4–8 Weeks): Non-surgical, transnasal access routes are indicated. The nasogastric (NG) tube is the primary choice for short-term feeding (typically lasting up to 6 to 8 weeks) because it can be placed quickly at the bedside without requiring surgical, endoscopic, or radiological interventions.

Long-Term Support (> 6–8 Weeks): When tube feeding is expected to exceed 6 to 8 weeks, clinicians transition to permanent or semi-permanent enterostomies placed directly through the abdominal wall, such as PEG (Percutaneous Endoscopic Gastrostomy) or JEG (Jejunostomy) tubes, to minimize nasal mucosal irritation and lower the risk of tube displacement.', '["nasogastric","nasojejunostomy","PEG","JEG"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:23:50.471Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:23:50.471Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:23:50.613Z"'::jsonb),
('anki-card-1758441963291-33', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
How many Calories will Mr. RH receive in 24 hours?*', '1386 Calories', 'To find the total amount of calories the patient receives in a 24-hour period, calculate the energy provided across all feedings:

1. Calculate Calories per feeding:
6 scoops × 38.5 Calories per scoop = 231 Calories per feeding
2. Calculate Total Daily Calories:
The prescription states the solution is divided into 6 feedings over the day.
231 Calories per feeding × 6 feedings = 1,386 Calories in 24 hours', '["1200 Calories","1450 Calories","1386 Calories","1500 Calories"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:38:39.083Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:38:39.083Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:38:39.294Z"'::jsonb),
('anki-card-1758441982391-34', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
How many Calories per feeding will Mr. RH consume?*', '231 Calories', '', '["250 Calories","200 calories","234 Calories","231 Calories"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:02:37.194Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:02:37.194Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:02:37.335Z"'::jsonb),
('anki-card-1758442026190-35', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
What is the total dilution per cc of the prescribed diet for Mr. RH?*', '1', 'To find the total dilution (caloric density) per cc of the formula, calculate the calories compared to the water volume:

1. Calculate Calories per feeding:
• 6 scoops x 38.5 Calories per scoop = 231 Calories
2. Determine Total Volume per feeding:
• The 6 scoops are dissolved in 230 mL (cc) of water.
3. Calculate Caloric Density:
• 231 Calories / 230 cc = 1.0 Calorie per cc', '["1","0.9:1","0.5:1","5:1"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:32:27.524Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:32:27.524Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:32:27.617Z"'::jsonb),
('anki-card-1758442041739-36', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'RH, a 70year old female, admitted with a diagnosis of CVD Infarct Left frontal lobe, WEIGHT: 65 kg. HEIGHT 5’4 “ GSC Glasgow Coma Scale 8
The Attending Physician gave a diet prescription TF Ensure 6 scoops in 230 ml water divided into 6 feedings ENSURE 9 grams per scoop = 38.5 Calories 5.16 grams Carbohydrates 1.43 grams protein Fats 1.26 grams per scoop
What is the BMI of Mr. RH?*', '24.6', 'To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).
1. Convert Height to Inches:
	• 5 feet 4 inches = 64 inches
2. Standard Metric Conversion Steps:
	• Precise Conversion: 64 inches × 0.0254 = 1.6256 meters
	• Height Squared = 1.6256 meters x 1.6256 meters = 2.6426
• BMI = 65 kg / 2.6426 = 24.59 ~ 24.6', '["23.4","24.6","25.0","25.1"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:46:45.378Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:46:45.378Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:46:45.378Z"'::jsonb),
('anki-card-1758442055856-37', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'For ATONIC CONSTIPATION, the following are the Medical Nutrition Therapy required except:*', 'Low Fiber, agar – agar', 'A low-fiber diet reduces stool bulk and slows down intestinal transit, which would severely worsen atonic constipation. Agar-agar, while a thickening agent, is a hydrocolloid that acts as a structural soluble fiber; pairing it with "Low Fiber" forms a contradictory and clinically incorrect dietary prescription.', '["Probiotics","Low Fiber, agar – agar","High Fiber, agar – agar","High Fiber, Liberal Fruits"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:16:29.511Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:16:29.511Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:16:29.650Z"'::jsonb),
('anki-card-1758442072738-38', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following foods have Moderate to Low in Tyramine EXCEPT:*', 'Beer and Ale', 'In standard clinical dietetic manuals, beer and ale (especially tap, draft, unpasteurized, or micro-brewed varieties) are classified under the Strictly Avoid / High-Tyramine category. Fermented alcohol contains high concentrations of yeast byproducts that trigger severe monoamine accumulation. Because they belong to the high-risk category, they are the absolute exception to the "moderate-to-low" group listed in the question.

	• Peanuts & Buttermilk: Fresh nuts, commercial peanut butter, and cultured dairy products like buttermilk or sour cream contain small, manageable amounts of tyramine, making them safe to consume in moderate or restricted amounts.
	• Soy sauce: While commercial soy sauce is traditionally high in tyramine, standard commercial food tables allow it in very tiny, limited amounts (such as 1 teaspoon) or classify it beneath the danger threshold compared to unfiltered yeast beverages. Therefore, the examiner isolated Beer and Ale as the primary high-risk danger substance.', '["Beer and Ale","Soy sauce","Buttermilk","Peanuts"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T15:00:49.399Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T15:00:49.399Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T15:00:49.546Z"'::jsonb),
('anki-card-1758442095934-39', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'PL is a 35-year-old male who drinks occasionally (5 bottles of beer two to three times a week) and recently had an Executive Check-up. His uric acid level showed 6.5 mg/dL, and he has complained of pain in the lower knees. Which medical condition could this be?*', 'Gout', 'Gout is a type of inflammatory arthritis triggered by the accumulation of monosodium urate crystals in the joints. While PL''s uric acid level of 6.5 mg/dL sits at the upper end of the normal range (often defined as up to 7.0 mg/dL for men), a patient can experience acute gout flare-ups even with normal serum values during an attack. His significant lifestyle risk factor—drinking 5 bottles of beer multiple times a week—is a primary trigger. Beer is exceptionally rich in purines and contains alcohol, both of which accelerate purine breakdown into uric acid while simultaneously blocking the kidneys from flushing it out, leading to localized joint pain like his knee complaints.', '["Rheumatoid Arthritis","Gout","Osteoarthritis","Leukemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:58:22.160Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:58:22.160Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:58:22.303Z"'::jsonb),
('anki-card-1758442112786-40', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'FODMAPS is indicated for Nutrition Management of IBD, the following examples of FOD MAPS except:*', 'Inulin', 'Inulin is a polymer of fructose molecules linked by beta-(2,1) bonds with a terminal glucose molecule. Human small intestinal enterocytes lack the brush border hydrolase (inulase) required to cleave these beta-linkages, allowing inulin to pass intact into the colon where it undergoes rapid and excessive osmotic fermentation by resident microbiota, producing hydrogen, methane, and carbon dioxide gases that trigger irritable bowel symptoms.', '["Corn syrup","Ice cream","Avocado","Inulin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:34.542Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:34.542Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:34.643Z"'::jsonb),
('anki-card-1758442127501-41', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is a DISEASE SPECIFIC formula which may contains HMB ( Beta Hydroxy Beta Methylbutyrate )*', 'Juvenaid', 'Juvenaid is a disease-specific medical nutrition therapeutic powder manufactured by Abbott. It is specifically formulated to promote wound healing and support lean muscle tissue building in patients experiencing muscle wasting from chronic illnesses (such as HIV/AIDS or cancer cachexia) or recovering from surgery and severe wounds.

Its targeted clinical formula contains HMB (Beta-Hydroxy-Beta-Methylbutyrate), an active metabolite of the branched-chain amino acid leucine that stops muscle protein breakdown and accelerates tissue synthesis, combined with Arginine and Glutamine.

	• Diabetasol: A diabetes-specific formula designed to manage blood sugar levels using slow-release carbohydrates and fiber.
	• Peptamen: A peptide-based elemental formula designed for patients with severely impaired gastrointestinal function and malabsorption.
	• Nutren Optimum: A general, premium nutritional formula containing whey protein, probiotics, and fiber aimed at overall immune support and recovery for the elderly or weak.', '["Nutren Optimum","Peptamen","Juvenaid","Diabetasol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:46:11.585Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:46:11.585Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:46:11.585Z"'::jsonb)
