INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758442146001-42', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Dietary Modification for Diverticulitis is a LOW RESIDUE Diet for the acute phase. Which of the following set of foods can be given to the patient?*', 'Papaya and Siopao', 'Even though papaya is a fruit, ripe papaya contains predominantly soluble fiber and has an incredibly soft, buttery texture that completely breaks down into a smooth liquid in the stomach. In local dietetics, ripe papaya is highly favored in acute GI recovery phases because it is exceptionally easy on the digestive tract and contains papain, a natural enzyme that aids in protein breakdown.

The white bun of a Siopao is made from highly refined bleached wheat flour with its fiber-rich outer bran layers completely milled away. The filling is typically heavily stewed, shredded, and tenderized meat without coarse roughage. This matches the mechanical requirements of a soft, low-residue diet.', '["Evaporated Milk and fita biscuit","Ensure Gold and Fita Biscuit","Papaya and Siopao","Avocado Shake and Fita Biscuit"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:27:34.007Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:27:34.007Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:27:34.160Z"'::jsonb),
('anki-card-1758442168767-43', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Documentation is an important aspect of the Nutrition Care Process. When writing in the patient’s chart about the patient’s actual intake, the acceptable ink color should be*', 'Black ink', 'Black ink provides the highest level of visual contrast, making it easy to read. More importantly, when physical medical charts are scanned, photocopied, or microfilmed for insurance, legal, or archiving purposes, black ink reproduces perfectly without fading or blurring.

While a sign pen may use black ink, standard "sign pens" often use water-based gel or liquid inks that easily smear, bleed through thin charting paper, or run if they accidentally come into contact with fluids (like water or alcohol rubs at a nursing station), which can compromise the integrity of legal medical documents.', '["Blue ink","Black ink","Green Ink","Sign pen with black ink"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:39:18.718Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:39:18.718Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:39:18.857Z"'::jsonb),
('anki-card-1758442187998-44', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The SOAP format is needed when writing the PROGRESS NOTES of Dietitians. The following data can be written in the O format except*', 'Subjective Global Assessment rating = Severely Malnourished', 'The SOAP (Subjective, Objective, Assessment, Plan) formatting structure used by clinical dietitians separates physical data metrics from clinical diagnoses and analytical tools.

The Subjective Global Assessment (SGA) is a formal clinical evaluation tool that requires a dietitian to synthesize multiple variables (such as historical data, physical wasting signs, and clinical symptoms) into a final diagnostic judgment. Because a final classification like "Severely Malnourished" represents an overall clinical interpretation, it must strictly be placed under the Assessment (A) section of the progress notes, not the Objective section.', '["Height, weight, BMI","Hemoglobin, Hematocrit, Total Lymphocyte Count","Subjective Global Assessment rating = Severely Malnourished","Actual Caloric Intake / Actual Protein Intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:54:58.784Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:54:58.784Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:54:58.784Z"'::jsonb),
('anki-card-1758442205080-45', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following parameters are indicators of a patient’s nutritional status, EXCEPT:*', 'Food Diary', 'A food diary is a prospective, self-reported tool filled out by the patient. In clinical nutrition, self-reported food diaries are notoriously prone to severe under-reporting, recall bias, and subjective estimation errors. Therefore, it is classified as a dietary assessment tool rather than a verified, objective indicator of true physical nutritional status.

	• 3-day actual food intake: Unlike a casual food diary, a 3-day actual intake measurement (such as a weighed food record or a hospital-monitored calorie count overseen by medical staff) is a validated, precise indicator of exact energy and macronutrient delivery.
	• CBC and Serum Electrolytes: These are objective, laboratory-verified biochemical markers. A Complete Blood Count directly tracks cellular parameters that signal long-term nutrient deficiencies (like iron or B12 anemia), while serum electrolytes reflect acute fluid-metabolic balances inside the body.', '["CBC (Complete Blood Count)","Serum Electrolytes","Food Diary","3 day actual food intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:53:33.582Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:53:33.582Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:53:33.582Z"'::jsonb),
('anki-card-1758442226830-46', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Total Lymphocyte Count (TLC) is obtained from the results of a CBC and calculated using the formula: (WBC x Lymphocytes %) divided by 100. If the WBC is 9.00 x 10^9/L (9,000 cells/µL) and Lymphocytes are 7%, compute for the Total Lymphocyte Count (TLC).*', '630', 'To compute the Total Lymphocyte Count (TLC) using the specific laboratory math parameters provided in the problem:

1. Express the WBC count in standard units: A WBC reading of 9.00 represents 9,000 cells/µL.
2. Apply the given percentage: The lymphocyte differential is 7%.
3. Run the calculation:
TLC = (9,000 x 7) / 100 = 630 cells/μL', '["630","6.3","6300","63.333"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T12:17:06.126Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T12:17:06.126Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T12:17:06.217Z"'::jsonb),
('anki-card-1758442243944-47', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Adding this component to the Parenteral Solution can help prevent clotting in the subclavian catheter*', 'Vitamin K', 'Vitamin K is routinely added to parenteral nutrition regimens to prevent deficiency-induced coagulopathies, thereby supporting normal hepatic synthesis of clotting factors II, VII, IX, and X and indirectly minimizing catheter-associated thrombotic complications linked to abnormal hemostatic profiles. While continuous heparin infusions were historically added directly to PN bags to prevent catheter lumen thrombosis, current clinical practice guidelines often utilize low-dose or cyclic vitamin K inclusion to sustain adequate clotting homeostasis without inducing systemic bleeding risks or destabilizing the International Normalized Ratio (INR) in patients on anticoagulation therapy.', '["Vitamin K","Heparin","Insulin","Multivitamins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T15:05:53.321Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T15:05:53.321Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T15:05:53.412Z"'::jsonb),
('anki-card-1758442273694-48', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'PROSURE is an enteral formula for the following disease condition except*', 'Decubitus Ulcers', 'ProSure (manufactured by Abbott) is an energy-dense, high-protein enteral formula explicitly enriched with EPA (Eicosapentaenoic Acid), an omega-3 fatty acid. It is scientifically designed to combat tumor-induced inflammation and reverse cachexia (muscle and weight loss) specifically in cancer patients. Decubitus ulcers (bedsores or pressure ulcers) require a different therapeutic nutrient profile—typically high-protein formulas enriched with HMB, Arginine, and Glutamine (such as Juvenaid or Abound) to drive rapid skin and subcutaneous tissue reconstruction.', '["Decubitus Ulcers","Anterior Neck mass","Cancer of the breast","Esophageal cancer"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T15:01:49.840Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T15:01:49.840Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T15:01:49.985Z"'::jsonb),
('anki-card-1758442284744-49', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are complications related to Parenteral Nutrition except*', 'Diarrhea', 'Diarrhea is a classic gastrointestinal complication associated directly with Enteral Nutrition (tube feeding), often triggered by rapid infusion rates, high solution osmolality, or liquid medications. Because Parenteral Nutrition (PN) completely bypasses the gastrointestinal tract and is infused directly into the bloodstream, it does not cause diarrhea.

The remaining options are standard, documented complications of PN:
	• Air embolism & Pneumothorax: These are serious mechanical complications related directly to inserting or maintaining a central venous catheter tip in the superior vena cava.
	• Hypoglycemia: This is a critical metabolic complication that typically occurs if a hyperosmolar PN infusion bag is abruptly stopped or discontinued without being tapered down gradually.', '["Air embolism","Pneumothorax","Diarrhea","Hypoglycemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:54:29.754Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:54:29.754Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:54:29.754Z"'::jsonb),
('anki-card-1758442296192-50', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Monitoring of Metabolic parameters in patients on Parenteral Nutrition is done daily except*', 'Blood Pressure', 'When evaluating the metabolic parameters of a patient on Parenteral Nutrition (PN), clinicians track chemical and laboratory-based values related to how the body processes the heavy load of intravenous dextrose, lipids, proteins, and minerals:

While Blood Pressure is closely monitored as part of the patient''s vital signs or overall clinical tracking, it is classified as a hemodynamic parameter, not a metabolic or laboratory biochemical parameter.

	• Blood levels: General blood chemistry tests (including basic metabolic panels and serum glucose) must be run daily when starting PN to catch immediate metabolic complications.
	• Urine Glucose: Checking urine for glucose (glycosuria) is done daily to quickly screen for a patient''s inability to handle the massive carbohydrate (dextrose) load before full blood lab panels return.
	• Phosphorus and Magnesium: These specific electrolytes must be checked daily during the initial phase of PN to monitor for Refeeding Syndrome, a fatal drop in these minerals triggered as the body moves from a starving state to metabolizing intravenous nutrients.', '["Blood levels","Urine Glucose","Phosphorus and Magnesium","Blood Pressure"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:04.572Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:04.572Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:04.572Z"'::jsonb),
('anki-card-1758442313059-51', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Absorbs water and electrolytes to form feces*', 'colon', 'The large intestine is anatomically divided into sections, with the colon acting as the primary site for the final stages of water and mineral reclamation:

As the liquid remains of digested food pass through the colon, its mucosal walls actively absorb water and electrolytes (such as sodium and potassium) back into the bloodstream. This dehydration process compacts the remaining unabsorbed waste, transforming it into solid feces.

	• Rectum: Functions primarily as a temporary storage chamber for the formed feces until defecation occurs.
	• Anus: The external opening and sphincter muscular control point that regulates the elimination of feces out of the body.
	• Appendix: A small, finger-like pouch attached to the cecum that does not play a significant role in fluid or electrolyte absorption.', '["anus","colon","appendix","rectum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:30.752Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:30.752Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:30.863Z"'::jsonb),
('anki-card-1758442335624-52', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for COLONIC DIVERTICULITIS includes*', 'General Liquid Diet to Soft Diet', 'Colonic diverticulitis is the acute inflammation or infection of the small pouches (diverticula) that line the intestinal wall. During an acute flare-up, the primary clinical goal is bowel rest to give the inflamed colon tissues time to heal.

Nutrition therapy begins by removing all solid foods and fiber to prevent irritating the bowel wall. The patient transitions from a strict clear liquid diet (or NPO) up to a general liquid diet. As symptoms resolve and pain decreases, the diet is slowly advanced to a low-residue, low-fiber soft diet (such as eggs, white pasta, and well-cooked poultry) before gradually introducing high-fiber whole foods during long-term recovery.

	• Purgatives (strong laxatives) and colonic lavage are strictly dangerous during acute diverticulitis because increasing bowel peristalsis risks perforating or rupturing the inflamed colonic pouches.
	• Omeprazole (a proton pump inhibitor for stomach acid) and medications like sedatives or antispasmodics fall under medical/pharmacological treatments, not Nutrition Therapy.', '["Use of sedative, tranquilizers, and anti- spasmodic drugs","General Liquid Diet to Soft Diet","Purgatives and Colonic Lavage","Use of Omeprazole"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:28.987Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:28.987Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:28.987Z"'::jsonb),
('anki-card-1758442373956-53', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for Inflammatory Bowel Disease*', 'High Calorie, High Protein, small frequent feeding, low fiber', 'When managing a patient with Inflammatory Bowel Disease, the nutritional goals focus on healing damaged intestinal tissue, overcoming malabsorption, and minimizing bowel irritation:

• High Calorie & High Protein: Severe intestinal inflammation causes protein-losing enteropathy, tissue damage, and weight loss. Elevated calories and proteins are necessary to rebuild tissues and prevent malnutrition.
• Small, Frequent Feedings: Breaking food intake into smaller, more frequent meals throughout the day reduces the functional workload on an already inflamed gastrointestinal tract, lessening cramps and bloating.
• Low Fiber: During periods of inflammation or flare-ups, dietary fiber must be minimized. High-fiber foods can physically scratch and irritate the raw lining of the colon, accelerating peristalsis and worsening diarrhea, cramping, and nutrient malabsorption.', '["High Calorie, High Protein, small frequent feeding, low fiber","High Calorie, High Protein, small frequent feeding, high fiber","High Calorie, High Protein, small frequent feeding, adequate fluid","High Calorie, High Protein, 3 meals and 3 snacks, high residue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:18:40.401Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:18:40.401Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:18:40.497Z"'::jsonb),
('anki-card-1758442388322-54', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for Appendicitis plays a supportive role when patient is on NPO, before and after surgery. If patient will resume diet, Liquid diets are prescribed*', 'Tea, juice, hard candy, jello', 'When a patient is transitioning off NPO (Nothing by Mouth) status after surgery for appendicitis, the gastrointestinal tract needs time to safely wake up and resume normal function.

The very first step after NPO status is a clear liquid diet. This consists exclusively of transparent fluids that are easily digested, leave absolutely no residue in the intestinal tract, and do not stimulate painful bowel contractions. Tea, fruit juice (without pulp), hard candy, and jello are standard examples of a clear liquid diet.', '["Tea, juice, hard candy, jello","Soft Boiled Egg, Strained Lugao","Ensure 3 scoops three times a day","Ensure 6 scoops three times a day"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:37.815Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:37.815Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:37.815Z"'::jsonb),
('anki-card-1758442413871-55', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Nutrition Therapy for Hemorrhoids includes the following except*', 'Use of Kankunis', 'Kankunis is a commercial herbal tea typically marketed for weight loss and constipation that contains senna or other stimulant laxatives. Stimulant laxatives work by triggering enteric nervous system contractions and altering electrolyte transport in the colon (specifically inhibiting Na+/K+-ATPase and stimulating prostaglandin-cAMP pathways), which induces acute diarrhea and cramping. In hemorrhoidal disease, forceful peristalsis, frequent watery stools, and straining caused by harsh laxatives increase pelvic venous pressure and exacerbate anal mucosal inflammation and thrombosis.', '["8- 10 glasses of fluids per day","Low Fiber","Exclude highly seasoned foods and relishes","Use of Kankunis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:35:33.807Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:35:33.807Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:35:33.952Z"'::jsonb),
('anki-card-1758442451553-56', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'EF, 90 year old female, admitted at the hospital with a Diagnosis of Irritable Bowel Syndrome, with a history of 5 episodes of loose bowel movement, Height 5’ 2” Weight 49.9 kg Serum Albumin 2.8 g/dL (Normal level 3.5 – 5.0 g/dL). Compute for the patient’s BMI, choose the best answer*', 'BMI 20', 'To find the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).

1. Convert Height to Meters:
	• 5 feet 2 inches = 62 inches
	• 62 inches × 0.0254 = 1.575 meters
2. Calculate BMI:
• BMI = 49.9 / 1.575²
• BMI = 49.9 / 2.48
• BMI = 20.12 ~ 20 kg/m²', '["BMI 22","BMI 21","BMI 20","BMI 19"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T09:28:17.717Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T09:28:17.717Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T09:28:17.809Z"'::jsonb),
('anki-card-1758442533449-57', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Related to Case study on # 59, Patient EF latest CBC shows that Hemoglobin 121 g/L, Hematocrit 0.41, White Blood cells (WBC) 12.6, Lymphocytes 0.16%. Compute for her Total Lymphocyte Count*', '2016', 'To compute the Total Lymphocyte Count (TLC), multiply the total White Blood Cell (WBC) count by the percentage of lymphocytes in the differential count:

1. Convert the WBC count: A WBC value of 12.6 in a standard CBC represents 12,600 cells/µL (or 12.6 times 10^9).
2. Convert the percentage: The lymphocyte proportion is 16% (expressed as a decimal, 0.16).
3. Calculate:
TLC = 12,600 x 0.16 = 2,016 cells/µL', '["2016","201.6","016","2017"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:47:18.819Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:47:18.819Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:47:18.819Z"'::jsonb),
('anki-card-1758442561430-58', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following Nutrition-Focused Physical Examination (NFPE) findings reveals possible nutrition-related causes like deficiencies in Iron, Zinc, Biotin, and Protein?*', 'Alopecia', 'In a Nutrition-Focused Physical Examination (NFPE), specialized hair changes serve as excellent indicators of specific micronutrient and macronutrient depletion.

Alopecia describes thin, sparse, patchy, or significant hair loss. Healthy hair follicle replication depends heavily on rapid cellular division. A deficiency in iron, zinc, biotin, or protein halts this process, causing follicles to enter a premature shedding phase, leading directly to thinning and hair loss.

	• Flag sign: Characterized by alternating bands of dark and light pigment, this specific change is caused purely by intermittent protein-calorie malnutrition (Kwashiorkor) affecting melanin synthesis.
	• Lanugo: Fine, soft, downy body hair that develops as an evolutionary response to severe overall calorie starvation (commonly seen in anorexia nervosa) to help conserve body heat.
	• Corkscrew hair: Coiled, tightly wound, swan-necked hairs are a unique structural marker caused exclusively by Vitamin C deficiency (Scurvy).', '["Lanugo","Flag sign (alternating banding of dark and light colors in hair)","Alopecia","Corkscrew hair"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:55:58.398Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:55:58.398Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:55:58.398Z"'::jsonb),
('anki-card-1758442579614-59', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In NFPE, the following determines fluid accumulation in the body except*', 'Skin', 'Under standard AND/ASPEN guidelines for a Nutrition-Focused Physical Exam (NFPE), fluid status is split into different clinical assessment categories:

1. Fluid Accumulation (Edema): When checking specifically for fluid accumulation to satisfy malnutrition criteria, a dietitian looks at distinct, localized anatomical sites where fluid settles due to gravity or pressure. This includes the Lower Body Extremities (ankles, feet, and shin/tibia) for walking patients, the Sacral region (lower back) for bedridden patients, and sometimes the Upper body (e.g., puffiness or fluid retention around the eyelids, face, or hands in generalized anasarca).

2. Skin: While you physically touch the skin during the exam, the skin itself as a category is examined under its own specific domains in an NFPE:
	• Hydration Status: Skin turgor (pinching the skin to check for tenting) determines dehydration, not edema/fluid accumulation.
	• Micronutrient Deficiencies: The skin is inspected for clinical signs of vitamin or mineral issues, such as scaling (essential fatty acids), petechiae/bruising (Vitamin C), or pallor (Iron/Folate).', '["Upper body","Lower Body Extremities","Skin","Sacral"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:54.609Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:54.609Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:54.713Z"'::jsonb),
('anki-card-1758442600529-60', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In NFPE, the following are not included in determining MICRONUTRIENT Deficiency*', 'Triceps, Deltoid, Pectoralis', 'Triceps, Deltoid, Pectoralis', '["Hair, Eyes, Mouth","Lips, Gums, Tongue","Triceps, Deltoid, Pectoralis","Skin, Nails, Gums"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:18:10.085Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:18:10.085Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758442621261-61', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'When writing in the patient’s chart, we use the Progress Notes structured according to the SOAP format. Which of the following statements can be written in the S (Subjective) format?*', '“ Lahat ng kinakain ko parang – walang lasa”', '“ Lahat ng kinakain ko parang – walang lasa”', '["Height , weight , BMI","Complete Blood Count , Serum Cholesterol","“ Lahat ng kinakain ko parang – walang lasa”","SGPT , SGOT"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:46:26.906Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:46:26.906Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758442639710-62', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In the Nutrition Care Process, which of the following is not a Nutrition Intervention?*', 'Did not inform the Attending Physician of the patient’s intake of MX3', 'Did not inform the Attending Physician of the patient’s intake of MX3', '["TF 1800 calories Low Fat Low salt divided into 6 feedings","Patient referral to the Speech Pathologist","Diet Instruction for Type 2 DM","Did not inform the Attending Physician of the patient’s intake of MX3"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T10:14:43.778Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T10:14:43.778Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1758442654493-63', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is a GLUTEN FREE DIET*', 'Camote pudding, Puto, Sago Gulaman', 'A gluten-free diet strictly excludes the protein gluten, which is found natively in grains like wheat, barley, and rye.

The following food items consist of traditional Filipino dishes made from naturally gluten-free root crops and starches:
	• Camote pudding uses sweet potato (camote), a root crop.
	• Puto is traditionally made using fermented ground rice flour (galapong).
	• Sago Gulaman relies on sago pearls (derived from tropical palm stems) and gulaman (agar seaweed jelly), which contain no wheat or grains.

	• Arrowroot itself is gluten-free, but commercial baking of arrowroot biscuits almost always incorporates standard wheat flour to form the structural dough texture.
	• Couscous is not a whole grain; it is small granules made from durum wheat semolina, meaning it is very high in gluten.
	• Muesli is a breakfast mix built primarily around raw, standard rolled oats, which are frequently heavily cross-contaminated with wheat during commercial processing unless certified gluten-free.', '["Muesli with yogurt, nuts, dried fruits","Scrambled Egg and Couscous","Custard, Arrow root biscuit","Camote pudding, Puto, Sago Gulaman"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:57:16.294Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:57:16.294Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:57:16.294Z"'::jsonb),
('anki-card-1758442667909-64', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following foods contain tartrazine except*', 'Coconut jam', 'Tartrazine (also known as FD&C Yellow No. 5 or E102) is a widely used synthetic, lemon-yellow azo food dye derived from petroleum or coal tar. It is added to commercial foods to provide a bright yellow or green color, or to help create creamy, blended under-shades.

Under formal industrial food-identity standards, commercial coconut jam is strictly defined as an emulsion made from coconut milk, sugar, and starch. It is legally categorized as a product that may or may not contain added natural colorings (like pandan leaf juice, annatto, or chlorophyllin) or caramel. Because its natural color profile is white-to-brownish or green (if pandan is used), it does not require synthetic yellow dye formulation. It is therefore categorized by examiners as the primary inherently tartrazine-free food group.

In contrast, mass-manufactured yellow/green colored marshmallows, translucent flavored carbonated beverages (such as yellow energy drinks or citrus sodas), and even commercial baking components like rainbow/colored chocolate chips routinely utilize synthetic FD&C Yellow No. 5 (Tartrazine) to hold stable artificial pigmentation under processing heat and shelf storage.', '["Chocolate chips","Flavored carbonated beverages","Coconut jam","Colored Marshmallow"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:57:46.241Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:57:46.241Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:57:46.241Z"'::jsonb),
('anki-card-1758442687558-65', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In a common bacterium inhabiting the gastrointestinal area around the pyloric valve and is a major determinant of chronic acute gastritis is*', 'Helicobactor Pylori', 'Helicobacter pylori is a spiral-shaped, Gram-negative bacterium that colonizes the protective mucous lining of the human stomach, specifically targeting the pyloric antrum area near the pyloric valve. It produces an enzyme called urease, which neutralizes stomach acid and allows it to survive in the harsh environment. H. pylori infection is the leading, globally recognized cause of chronic and acute gastritis, as well as peptic ulcer disease and gastric cancer.

	• Helicobacter felis and Helicobacter salmonis: These are different species of Helicobacter that primarily infect animals (cats/dogs and fish, respectively) rather than humans.
	• Clostridium difficile: This bacterium inhabits the large intestine (colon), not the stomach, and causes severe antibiotic-associated diarrhea and pseudomembranous colitis.', '["Clostridium difficile","Helicobator Felis","Helicobactor Pylori","H. Salmonis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:30:48.721Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:30:48.721Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:30:48.862Z"'::jsonb),
('anki-card-1758442702490-66', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In the Nutrition Management of Peptic Ulcer, gastric stimulants should be limited except*', 'Evaporated Milk', 'While caffeine, alcohol, and even decaffeinated coffee are powerful, direct chemical triggers that prompt the stomach lining to secrete massive amounts of gastric acid, Evaporated Milk is chemically categorized as a food item rather than a pure gastric stimulant. Although the protein and calcium in milk can cause a delayed rebound acid secretion, traditional dietetic manuals classify it under regular dairy/protein food groups rather than standalone chemical irritants or stimulants.', '["Evaporated Milk","Caffeine","Alcohol","Decaffeinated Coffee"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:58.365Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:58.365Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:58.365Z"'::jsonb),
('anki-card-1758442719723-67', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'For eradication of H. Pylori in the gastrointestinal area, in how many weeks of treatment with an acid suppressing drug and antibiotics will it be*', 'Two weeks', 'The standard first-line treatment for the eradication of Helicobacter pylori involves a combination therapy protocol pairing an acid-suppressing drug (like a Proton Pump Inhibitor) with antibiotics to eliminate the bacteria.

Clinical guidelines generally establish that a duration of treatment corresponding to two weeks provides an effective balance for bacterial eradication rates while managing side effects and antibiotic resistance.', '["Two weeks","20 days","Three weeks","25 days"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:37:32.474Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:37:32.474Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:37:32.474Z"'::jsonb),
('anki-card-1758442733805-68', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following medications are classified as Histamine H2 Receptor Antagonists (H2 Blockers) commonly used to treat peptic ulcers, EXCEPT:*', 'Cetirizine', 'While cetirizine is an antihistamine, it is a selective H1 blocker. H1 receptors are located in the respiratory tract, blood vessels, and immune cells. Therefore, cetirizine is used exclusively to treat allergy symptoms (like hives, runny nose, and itching) and has absolutely zero effect on stomach acid secretion or peptic ulcer healing.

Ranitidine and Cimetidine are classic H2 blockers that block the histamine receptors in the stomach lining to reduce gastric acid production. While Omeprazole is a Proton Pump Inhibitor (PPI) rather than an H2 blocker, it is a primary drug used to treat peptic ulcers, making Cetirizine the absolute standout exception because it has no role in gastrointestinal therapy whatsoever.', '["Cimetidine","Cetirizine","Omeprazole","Ranitidine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:05:57.268Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:05:57.268Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:05:57.351Z"'::jsonb),
('anki-card-1758442749772-69', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'In Nutrition Management of Radiation Enteritis, we provide the following interventions includes the following but not *', 'Avoid oxalate containing foods', 'Restricting dietary oxalates (found in spinach, beets, chocolate, and nuts) is a specific therapeutic intervention used to manage conditions like Calcium Oxalate Kidney Stones or severe fat malabsorption in short bowel syndrome to prevent kidney stones. It is not a standard, primary nutritional intervention for managing acute radiation enteritis damage.

True Interventions
	• Small frequent feedings: This is essential because it reduces the absolute volume workload on the blunted, inflamed intestinal villi at any single time, preventing vomiting, severe dumping, and cramping.
	• MCT for better absorption: Medium-Chain Triglycerides (MCTs) can be directly absorbed by the mucosal cells without requiring bile salts or complex micelle pancreatic breakdown, which is ideal because the intestines lose standard fat absorption capacity during radiation damage.
	• Folate supplementation: Rapidly dividing mucosal cells require intense folate synthesis for DNA repair and healing. Because radiation enteritis compromises the intestinal segments where folate is absorbed, targeted supplementation is highly indicated to prevent deficiency and aid epithelial recovery.', '["Avoid oxalate containing foods","Small frequent feeding","Folate supplementation","MCT for better absorption"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:47:40.865Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:47:40.865Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:47:40.865Z"'::jsonb),
('anki-card-1758442764904-70', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Cathartics are substances that accelerate defecation, while LAXATIVES loosen stools and increase bowel movements, which does not belong to this group of CATARTICS*', 'Methyl Cellulose', '• Osmotic / Saline Agents: Lactulose, Magnesium Sulfate, and Magnesium Hydroxide all function by the same primary mechanism. They act as osmotic (or saline) laxatives. They are poorly absorbed in the intestinal tract and exert osmotic pressure to draw water into the lumen, softening the stool and promoting rapid evacuation.

• Bulk-Forming Agent: Methyl Cellulose operates under a completely different mechanism. It is a bulk-forming agent composed of non-digestible cellulose fibers. It absorbs water inside the bowel to swell, mechanically expanding the fecal mass to naturally stimulate peristalsis.', '["Methyl Cellulose","Magnesium Hydroxide","Magnesium Sulfate","Lactulose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:23.762Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:23.762Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:23.861Z"'::jsonb),
('anki-card-1758442787387-71', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is not true in a LOW RESIDUE DIET?*', 'Rolled Oats, Soft Boiled Egg, gelatin', 'Oatmeal and rolled oats are whole grains that are naturally very high in fiber and roughage. Whole grains leave behind a high amount of undigested material (residue) in the colon, which directly violates the purpose of a low-residue diet.

	• Baked macaroni (made from refined white flour) and angel food cake (a low-fat, plain sponge cake) are classic low-residue staples.
	• Canned or cooked fruits and vegetables without skins or seeds (like peaches in syrup and cooked cucumber) along with eggs are completely allowed.
	• Sports drinks like Gatorade, electrolyte (ionized) drinks, and plain clear water are excellent for maintaining hydration on this diet and leave zero solid residue behind.', '["Peaches in light syrup, cooked cucumber, poached egg,","Ionized drink, Gatorade, Blu water","Baked Macaroni, angel food cake","Rolled Oats, Soft Boiled Egg, gelatin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:30.486Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:30.486Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:30.486Z"'::jsonb),
('anki-card-1758442808251-72', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following is TRUE in a SOFT DIET:*', 'Chicken Nilaga with Asparagus tips and Potato, Cathedral Windows', 'Chicken Nilaga features chicken meat that has been boiled for a long time until its connective tissues completely break down, making it extremely tender and effortless to chew. Cooked potatoes and soft asparagus tips (unlike the tough, fibrous lower stalks) are highly digestible, standard soft-diet vegetables. Cathedral Windows is a traditional Filipino gelatin dessert made of soft, multi-colored agar blocks set in a light, creamy gelatin base. Because gelatin completely melts at body temperature, it is a quintessential soft and light-to-digest menu item.', '["Cooked Asparagus tips, Beef Steak with Onion Rings, Fruit Salad","Pork Sinigang with Kangkong and Radish, Angel Cake","Fish Escabeche with carrots and sayote, Cooked Jackfruit in Light Syrup","Chicken Nilaga with Asparagus tips and Potato, Cathedral Windows"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:58:03.315Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:58:03.315Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:58:03.315Z"'::jsonb),
('anki-card-1758442864516-73', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The semi liquid, partially digested food that travels through the intestinal tract is called:*', 'Chyme', 'Chyme is the medical term used to describe the thick, semi-liquid mass of partially digested food, water, and acidic gastric juices that moves through the gastrointestinal tract.

As you eat, chewed food travels down to the stomach (where it is initially called a bolus). The stomach''s muscular walls dynamically churn and pulverize this food while mixing it with highly acidic hydrochloric acid and enzymes. This chemical and mechanical breakdown liquifies the food into chyme, which is then slowly released through the pyloric valve into the intestines for further digestion and nutrient absorption.

	• Lymph: A clear fluid containing white blood cells that circulates through the lymphatic immune system.
	• Secretin: A hormone secreted by the small intestine that triggers the pancreas to release bicarbonate to neutralize the acidic chyme.
	• Bile: A digestive fluid produced by the liver that emulsifies fats in the small intestine but is not a food mass itself.', '["Bile","lymph","Chyme","secretin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:15:26.413Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:15:26.413Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:15:26.551Z"'::jsonb),
('anki-card-1758442877214-74', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The muscular contractions that move food through the GI tract are called:*', 'peristalsis', 'Peristalsis is a series of radially symmetrical, wave-like smooth muscle contractions and relaxations that automatically propel food, liquids, and waste forward through the entire gastrointestinal tract. It starts in the esophagus when you swallow a bolus of food and continues down through the stomach, small intestine, and large intestine.', '["hydrolysis","sphincters","peristalsis","bowel movements"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:25:38.034Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:25:38.034Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-11-07T14:32:00.423Z"'::jsonb),
('anki-card-1758442890314-75', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The main function of the bile is:*', 'emulsify fats', '', '["emulsify fats","catalyze hydrolysis","slow protein digestion","neutralize stomach acidity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:59:28.644Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:59:28.644Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:59:28.787Z"'::jsonb),
('anki-card-1758442902613-76', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'All blood leaving the GI tract travels first to the:*', 'Liver', 'All blood that flows through the stomach, small intestine, and large intestine picks up absorbed nutrients, water, and toxins. Instead of going straight back to the heart, this nutrient-rich blood is collected into a specialized network of veins called the hepatic portal system.

The portal system routes 100% of this blood directly into the liver first. The liver acts as the body''s primary chemical processing plant—it metabolizes and stores the absorbed nutrients, removes waste products, and neutralizes dangerous drugs or toxins before the blood is safely allowed to return to the heart and circulate throughout the rest of the body.', '["heart","Liver","kidneys","Pancreas"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:21:19.392Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:21:19.392Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:21:19.547Z"'::jsonb),
('anki-card-1758442916262-77', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which nutrients leave the gastrointestinal tract by way of the lymphatic system:*', 'fats and fat soluble vitamins', 'While water-soluble nutrients (like simple sugars, amino acids, water-soluble vitamins, and minerals) are absorbed directly into the bloodstream via the hepatic portal vein, large lipid molecules cannot dissolve in blood:

Products of fat digestion (monoglycerides and long-chain fatty acids) are reassembled inside intestinal cells into transport packets called chylomylomicrons. These large structures, along with fat-soluble vitamins (A, D, E, and K), are too large to pass through the tight walls of regular blood capillaries. Instead, they enter specialized lymphatic vessels in the intestinal villi called lacteals.

The lymphatic system transports these fats through the thoracic duct, emptying them safely into the bloodstream near the heart, completely bypassing the liver initially.', '["water and minerals","proteins and minerals","all vitamins and minerals","fats and fat soluble vitamins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T14:17:53.030Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T14:17:53.030Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T14:17:53.167Z"'::jsonb),
('anki-card-1758442932213-78', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Digestion and absorption are coordinated by the:*', 'hormonal system and the nervous system', 'The complex processes of digestion and absorption require precise coordination to ensure that digestive juices are secreted only when food is present. This homeostatic regulation is managed by two master systems working in tandem:

• The Hormonal (Endocrine) System: Secretes chemical messengers directly into the bloodstream to regulate digestive functions. For example, the hormone gastrin stimulates the stomach to release acid, while secretin and cholecystokinin (CCK) signal the pancreas and gallbladder to release digestive enzymes and bile when food enters the small intestine.
• The Nervous System: Coordinates digestion through the enteric nervous system (the gut''s built-in neural network) and the autonomic nervous system. It regulates the mechanical churning of the stomach, triggers peristalsis to move food along the tract, and responds to the sight, smell, or presence of food by stimulating salivary and gastric secretions.', '["pancreas and kidneys","liver and gallbladder","hormonal system and the nervous system","vascular system and the lymphatic system"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:38.226Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:38.226Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:38.226Z"'::jsonb),
('anki-card-1758442952993-79', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Let us trace the digestion of a peanut butter and banana sandwich on whole-wheat sesame bread through the gastrointestinal (GI) tract. In the mouth, there is chewing and swallowing, but little digestion takes place. Which nutrients are involved in this process?*', 'Carbohydrates and fiber', 'Salivary alpha-amylase is secreted by the parotid and submandibular glands, targeting internal alpha-1,4-glycosidic bonds of starches (found in the whole-wheat bread and banana) to produce dextrins and maltose. Dietary fiber (complex plant polysaccharides such as cellulose, hemicellulose, and pectin found in whole grains, sesame seeds, and banana) is resistant to human endogenous hydrolytic enzymes; thus, fiber undergoes mechanical size reduction via chewing but experiences zero enzymatic degradation in the mouth or stomach.', '["Carbohydrates and protein","Carbohydrates and fats","Carbohydrates and fiber","Carbohydrates and vitamins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:04:48.512Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:04:48.512Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:04:48.621Z"'::jsonb),
('anki-card-1758442971160-80', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Related to the digestion of a Peanut Butter and Banana sandwich, the next process is in the stomach (collecting and churning with some digestion). Which nutrients are involved in this process?*', 'Carbohydrates, protein and fats', 'This continues the step-by-step digestion trace of the peanut butter, banana, and whole-wheat bread sandwich based on Whitney and Rolfes'' Understanding Nutrition. Inside the stomach, the main actions are mechanical churning and gastric acid secretion, which actively process all three macronutrients:

• Protein: Stomach acid (hydrochloric acid) denatures and uncoils the protein strands from the bread and peanut butter. Then, the gastric enzyme pepsin initiates chemical digestion by clipping these large protein strands into smaller peptide pieces.
• Fats: Gastric juice contains gastric lipase (working alongside the lingual lipase swallowed from the mouth), which begins targeting and breaking down some of the surface fats found in the peanut butter.
• Carbohydrates: Although the extreme acidity of the stomach temporarily pauses the action of salivary amylase (which digests starches), the simple fruit sugars and starches from the banana and bread remain a heavy part of the resulting fluid mixture. The stomach continues to physically churn them into a uniform liquid mass known as chyme before passing it into the small intestine.', '["Carbohydrates, Amino Acids, fats","Sugars, starch and fats","Carbohydrates, protein and fats","Sugars, starch, vitamins and minerals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-13T11:46:00.213Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-10T11:46:00.213Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:46:00.213Z"'::jsonb),
('anki-card-1758442986827-81', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'From the stomach, the digestion of Peanut Butter and Banana sandwich will now proceed to the Small Intestines, the following nutrients that are involved in this process are:*', 'Sugar, Starch, Protein, Fats', 'Upon arrival in the small intestine, the blended sandwich mass (chyme) triggers the pancreas and the walls of the small intestine to secrete digestive juices and enzymes. Unlike earlier stages where only specific items are targeted, the small intestine is the primary destination where all major macronutrients are simultaneously broken down and chemically processed for absorption:

• Sugar (from the banana): Traverses the intestinal cells almost immediately on contact.
• Starch (from the bread): Pancreatic amylase continues breaking down the remaining complex carbohydrates into simple sugars.
• Protein (from the peanut butter and bread): Pancreatic proteases (like trypsin and chymotrypsin) break the partially uncoiled proteins into absorbable amino acids.
• Fats (from the peanut butter): Gallbladder bile emulsifies the fats, allowing pancreatic lipase to digest them into fatty acids and glycerol.', '["Sugars from Banana, Starch, fats, vitamins and\nminerals","Sugar, Starch, Protein, Fats","Sugars from Banana, Starch, fats, vitamins and minerals","Sugar, Starch, Fats"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:56:13.113Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:56:13.113Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:56:13.247Z"'::jsonb),
('anki-card-1758443004809-82', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Finally, in the large intestine, the remains of the peanut butter and banana sandwich are processed for reabsorption and elimination. The following substances are absorbed at this stage, EXCEPT:*', 'Insoluble fiber', 'As the remains of the sandwich enter the large intestine, the body absorbs fluids (water) and some minerals (like sodium and potassium) back into the bloodstream. Additionally, the healthy bacteria living in your colon ferment and break down the soluble fibers from the banana and bread into short-chain fatty acids, which the body can partially absorb for energy.

Insoluble fiber (found in the wheat bran, seeds, and nuts) cannot be dissolved in water or significantly broken down by intestinal bacteria. It passes through the large intestine completely intact, acting as roughage to bulk up the stool before being eliminated entirely as feces.', '["Fluids","Some minerals","Soluble fibers","Insoluble fiber"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:58:43.279Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:58:43.279Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:58:43.279Z"'::jsonb),
('anki-card-1758443017341-83', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'For Radiation Enteritis, this diet is best indicated for this condition*', 'Lactose free, Low Fat, Low Fiber', 'Radiation enteritis is an acute or chronic inflammation of the intestinal tract caused by radiation therapy directed at the abdomen or pelvis. The radiation kills rapidly dividing cells, which damages the mucosal lining, blunts the intestinal villi, and destroys the enzymes responsible for standard digestion.

To manage the resulting malabsorption, cramping, and severe diarrhea, the clinical diet must address multiple mechanics simultaneously:

• Lactose-Free: The brush-border enzyme lactase is the first to be destroyed when the intestinal lining is damaged by radiation. Even a small amount of lactose can trigger severe osmotic diarrhea, gas, and painful bloating.
• Low Fat: Because the blunted villi cannot properly absorb lipids, fats will pass unabsorbed into the colon, causing steatorrhea (fatty stools) and worsening fluid loss.
• Low Fiber: The colon must be completely protected from mechanical irritation. Removing abrasive, scratchy insoluble plant fibers prevents bowel stimulation and minimizes painful cramping.', '["High Fiber","Low Fiber, Low Fat","Lactose free, Low Fat, Low Fiber","Low Residue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:53.823Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:53.823Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:53.891Z"'::jsonb),
('anki-card-1758443359374-84', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The following are examples of the Low Fiber Diet except*', 'Oatmeal, Soft Boiled Egg, Gelatin', 'A low-fiber diet requires restricting daily plant fiber intake to ease digestion and rest the gastrointestinal tract. This means replacing whole-grain products with refined starches and avoiding raw or high-fiber foods.

Oatmeal is a whole grain that natively contains high levels of soluble and insoluble fiber. Because whole grains leave a high amount of undigested bulk in the colon, oatmeal is strictly restricted on a standard low-fiber diet plan.', '["Oatmeal, Soft Boiled Egg, Gelatin","White rice, Soft Boiled Egg, Canned peaches","White bread, Scrambled Egg, Strained Juice","White rice, Pork Nilaga, Strained juice"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T11:02:51.294Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T11:02:51.294Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T11:02:51.381Z"'::jsonb),
('anki-card-1758443377540-85', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Insoluble Fiber is indicated for the following conditions except*', 'Gastric Ulcer', 'Insoluble fiber (found in wheat bran, whole grains, and vegetable skins) does not dissolve in water and acts as coarse roughage that speeds up intestinal transit and adds bulk to stools.

An active gastric ulcer is a raw, inflamed sore in the stomach lining. Insoluble fiber is physically abrasive and difficult to break down, which can mechanically scratch and irritate the stomach lining, increasing pain and delayed healing. Therefore, a low-residue/bland diet is indicated for gastric ulcers instead.

• Insoluble fiber is highly indicated for Diverticular Disease to lower colon pressure, Colon and Rectal Cancer to rapidly flush out potential carcinogens, and selected constipation-predominant Irritable Bowel Syndrome types to improve regularity.', '["Gastric Ulcer","Irritable Bowel Syndrome","Diverticular Disease","Colon and Rectal Cancer"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:05:17.387Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-10T12:05:17.387Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:05:17.507Z"'::jsonb),
('anki-card-1758443393690-86', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Which of the following foods contain the highest amount of lactose*', 'Yogurt', 'Commercial yogurts are frequently manufactured with added non-fat dry milk solids to improve texture and mouthfeel, which increases the total carbohydrate and lactose concentration per serving compared to fluid milk. While bacterial fermentation by Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus produces microbial $\beta$-galactosidase that hydrolyzes a portion of the lactose into glucose and galactose, the initial substrate load from concentrated milk solids often results in higher total residual lactose per standard 8-ounce serving than fluid milk.', '["Cottage Cheese","Yogurt","Milk","Sherbet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:01:53.109Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:01:53.109Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:01:53.183Z"'::jsonb),
('anki-card-1758443413040-87', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Treatment of lactose intolerance requires limiting milk intake. The following nutrients must be included in the diet except*', 'Zinc', 'When a patient with lactose intolerance limits their dairy and milk intake, they drastically reduce their consumption of primary micronutrients naturally packed into milk fluid.

While milk does contain a small amount of zinc, zinc is highly abundant across multiple non-dairy food groups, including red meat, poultry, seafood (like shellfish and oysters), legumes, seeds, and fortified grains. Restricting dairy does not place a patient at a high clinical risk for zinc deficiency.

	• Calcium and Vitamin D: Milk is the primary source of bioavailable calcium and fortified Vitamin D in the human diet. Restricting milk directly exposes patients to bone-wasting deficiencies, requiring alternative replacement.
	• Riboflavin: Also known as Vitamin B2, riboflavin is heavily concentrated in fluid milk. Dairy products account for over a quarter of total daily riboflavin intake, making its targeted replacement essential when limiting milk.', '["Riboflavin","Zinc","Vitamin D","Calcium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:59:42.152Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:59:42.152Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:59:42.152Z"'::jsonb),
('anki-card-1758443428805-88', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Prebiotics can stimulate the growth or activity of resident bacteria within the large intestine. Prebiotics can be found in the following foods except*', 'Miso', 'Miso is a traditional Japanese seasoning produced by fermenting soybeans with salt and koji. Because it is a fermented food, miso naturally contains live, active bacterial cultures, which means it is classified as a Probiotic rather than a prebiotic.

Prebiotics are non-digestible, fiber-rich plant carbohydrates or polyphenols that act as structural "food" to nourish your resident gut bacteria.
	• Onions and garlic, along with Asparagus and Japanese artichoke, are exceptionally rich in inulin and fructooligosaccharides (FOS), which are the most clinically recognized prebiotic fibers.
	• Cocoa contains a high concentration of non-absorbable polyphenols (flavonoids), which are officially classified as non-carbohydrate prebiotic candidates because they stimulate the selective growth of beneficial Lactobacillus and Bifidobacterium species in the colon.', '["Asparagus, Japanese Artichoke","Onions, garlic","Miso","Cocoa"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:00:02.037Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:00:02.037Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:00:02.098Z"'::jsonb),
('anki-card-1758443448038-89', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The International Dysphagia Diet Standardisation Initiative (IDDSI) framework provides a common Terminology to describe food textures and drink thickness has how many levels of standards*', '7 levels', 'The correct answer is not explicitly listed among the given options, but mathematically the framework consists of 8 levels (numbered 0 to 7).

The International Dysphagia Diet Standardisation Initiative (IDDSI) framework is structurally designed as a continuous scale spanning 8 distinct levels, using the numbers 0 through 7 to standardize care:
• Levels 0 to 4 are used to classify drinks (Thin, Slightly Thick, Mildly Thick, Moderately Thick, and Extremely Thick).
• Levels 3 to 7 are used to classify foods (Liquidised, Pureed, Minced & Moist, Soft & Bite-Sized, and Regular).', '["4 Levels","5 Levels","6 Levels","7 levels"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T11:48:50.432Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T11:48:50.432Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T11:48:50.432Z"'::jsonb),
('anki-card-1758443474970-90', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'The IDDSI framework describes LEVEL 5 as*', 'Minced and moist', 'The International Dysphagia Diet Standardisation Initiative (IDDSI) framework uses a standardized 8-level system (Levels 0–7) with specific names and color codes to manage texture-modified foods and thickened liquids for individuals with dysphagia:

• Level 5 – Minced & Moist (Orange): This level describes foods that are soft, moist, and finely minced into small pieces no larger than 4mm for adults (the width of a standard fork prong gap). It requires minimal chewing and no biting.

	• Liquidized: Represents Level 3.
	• Pureed: Represents Level 4.
	• Soft and Bite size: Represents Level 6 (pieces no larger than 15mm).', '["Liquidized","Soft and Bite size","Pureed","Minced and moist"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-10T13:27:07.660Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-09T13:27:07.660Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-09T13:27:07.796Z"'::jsonb),
('anki-card-1758443487385-91', NULL, 'anki-deck-1783610437608-1790433140272-t9ges', 'Foods that may increase intestinal gases includes the following but not*', 'Peanuts', 'While legumes like beans and lentils are notorious gas producers, peanuts (despite being botanically classified as legumes) are primarily composed of fats and proteins rather than high amounts of gas-producing fermentable carbohydrates (FODMAPs). Protein- and fat-heavy foods are digested without significant colonic fermentation, making peanuts much less likely to increase intestinal gas.

• Beer: Beer is carbonated, releasing trapped carbon dioxide gas into the digestive tract, and it contains fermentable carbohydrates (from grains like barley/wheat) that gut bacteria break down, producing significant intestinal gas.
• Broccoli and Turnips: Both are cruciferous vegetables. Cruciferous vegetables are famously high in complex fibers and a sugar called raffinose, which humans lack the enzymes to break down. Instead, they ferment heavily in the large intestine, causing a great deal of gas.', '["Broccoli","Turnips","Peanuts","Beer"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-11T12:02:41.340Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-10T12:02:41.340Z"'::jsonb, '"2026-09-26T14:32:29.975Z"'::jsonb, '"2026-10-10T12:02:41.413Z"'::jsonb)
