INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758079226363-44', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The normal glomerular filtration rate is:*', '90-120 ml/min', 'Normal adult Glomerular Filtration Rate (GFR) typically ranges between 90 and 120 mL/min.', '["50-90 ml/min","70-100 ml/min","90-120 ml/min","110-140 ml.min"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:36:41.972Z"'::jsonb),
('anki-card-1758079241346-45', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'When a renal client is retaining sodium and fluid:*', 'Blood pressure will increase', 'When the kidneys fail or experience impaired excretion, sodium and fluid retention expand extracellular fluid volume, directly resulting in increased blood pressure (hypertension).

• Body weight will decrease / Urine output will decrease: Weight increases due to fluid retention, and urine output often drops (oliguria).', '["Body weight will decrease","Blood pressure will increase","Urine output will decrease","A and C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:39:34.122Z"'::jsonb),
('anki-card-1758079257527-46', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'To estimate daily fluid needs of a renal client, add ________ millilitres to the 24 hr urine output.*', '500', 'In clinical renal nutrition calculations, standard daily fluid prescription allowances for oliguric or anuric renal clients are estimated by adding 500 milliliters (representing insensible fluid losses through skin and respiration) to the measured 24-hour urine output volume.', '["200","300","400","500"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:39:38.061Z"'::jsonb),
('anki-card-1758079272677-47', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'An acid ash would be created by:*', 'Corn, cranberries', 'Corn and cranberries contain non-metabolized organic acids (like quinic acid) that yield an acid ash residue upon metabolic oxidation, lowering urinary pH.

• Milk, vegetables, and fruits: Yield alkaline ash residues.', '["Corn, cranberries","Milk","Vegetables","Fruits"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:39:43.703Z"'::jsonb),
('anki-card-1758079285359-48', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Symptoms of nephrosis include:*', 'Albuminuria, hypercholesterolemia', 'Nephrotic syndrome is characterized clinically by massive glomerular permeability leading to heavy proteinuria (albuminuria), severe edema, hypoalbuminemia, and compensatory hypercholesterolemia (dyslipidemia).', '["Dehydration, hypocholesterolemia","Albuminuria, hypercholesterolemia","Edema, hypocholesterolemia","Hypotension, hyperalbuminuria"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:39:47.368Z"'::jsonb),
('anki-card-1758079302791-49', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'When a renal client is retaining sodium and fluids*', 'Blood pressure will increase', 'Fluid and sodium retention expands blood volume, directly elevating blood pressure.', '["Body weight will decrease","Blood pressure will increase","Urine output will decrease","A and C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:39:55.154Z"'::jsonb),
('anki-card-1758079323923-50', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Foods considered part of the fluid allowance in a renal diet include all of the following except:*', 'Vegetable high in water content', 'While high-water vegetables contain moisture naturally, standard dietary renal fluid allowances specifically monitor and restrict liquid items (such as water, broths, ice cream, popsicles, and gelatin) rather than counting intact solid high-water vegetables as discrete liquid volume.', '["Vegetable high in water content","Popsicles","Ice cream","Jello"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:39:59.013Z"'::jsonb),
('anki-card-1758079346224-51', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Bone disease is a frequent complication of chronic renal failure.*', 'True', 'Renal osteodystrophy and metabolic bone disease are frequent, well-documented complications of chronic renal failure driven by calcium-phosphorus imbalances and lack of active Vitamin D.', '["True","False"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:02.586Z"'::jsonb),
('anki-card-1758079365540-52', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Renal failure diets are intentionally low in all of the following except*', 'Calcium', 'Renal diets restrict phosphorus, protein, and sodium, whereas calcium is typically supplemented or maintained at adequate levels rather than restricted, making calcium the correct exception.', '["Phosphorus","Protein","Calcium","Sodium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:06.522Z"'::jsonb),
('anki-card-1758079466002-53', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Aluminium-containing antacids are sometimes given to renal failure clients to:*', 'B and C', 'Phosphate binders (including aluminium- or calcium-based binders) are prescribed in renal failure to bind dietary phosphate in the gastrointestinal tract, thereby decreasing its intestinal absorption and reducing systemic phosphorus loading.', '["Decrease phosphorus intake","Decrease absorption of phosphorus","Bind phosphorus in the GI tract","B and C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:10.425Z"'::jsonb),
('anki-card-1758079479301-54', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Anemia unrelated to iron deficiency may occur in chronic renal failure due to:*', 'Decrease production of erythropoietin', 'Renal anemia is caused primarily by the failing kidneys'' inability to synthesize and secrete adequate quantities of erythropoietin (EPO), the hormone stimulating bone marrow red blood cell production.', '["Decrease production of erythropoietin","Increased synthesis of red blood cells","Increased life span of red blood cells","A and c"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:14.302Z"'::jsonb),
('anki-card-1758079499933-55', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Corticosteroids given after renal transplants can result in all of the following except:*', 'Excessive weight loss', 'Corticosteroids stimulate appetite, induce fluid retention (edema), cause negative nitrogen balance, and impair glucose tolerance, making excessive weight loss incorrect (and thus the correct exception since they typically cause weight gain).', '["Negative nitrogen balance","Edema","Excessive weight loss","Glucose intolerance"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:18.898Z"'::jsonb),
('anki-card-1758079519466-56', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The kidney plays an essential role in which of the following:*', 'Erythropoietin synthesis', 'The kidneys play an essential endocrine role by synthesizing and releasing erythropoietin (EPO) to regulate erythropoiesis.', '["Epinephrine synthesis","Erythropoietin synthesis","Converting vitamin A to its active form","Breaking down red blood cells"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:22.566Z"'::jsonb),
('anki-card-1758079537014-57', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Metabolic changes that occur in renal failure include:*', 'B and C only', 'Renal failure impairs glomerular filtration (GFR drops, not increases), causing nitrogenous waste products to accumulate in the blood, resulting in elevated BUN (B) and increased blood uric acid levels (C).', '["B and C only","GFR increases","BUN increases","Blood uric acid levels increase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:31.737Z"'::jsonb),
('anki-card-1758079556213-58', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Symptoms of Uremia include*', 'B and C', 'Uremia (the buildup of nitrogenous waste products in the blood due to renal failure) manifests with neurological and gastrointestinal symptoms, including an unpleasant metallic taste in the mouth (dysgeusia) and diminished mental alertness/lethargy.', '["Hyperactivity","Unpleasant taste in the mouth","Diminished mental alertness","B and C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:36:48.311Z"'::jsonb),
('anki-card-1758079570630-59', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Objective(s) of dietary management of chronic renal failure include:*', 'B and C', 'The primary clinical objectives of medical nutrition therapy in chronic renal failure are to delay the progression of renal failure (B) and prevent renal osteodystrophy and bone disease (C), rather than maintaining negative nitrogen balance.', '["To maintain negative nitrogen balance","To delay the progression of renal failure","To prevent bone disease","B and C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:36:53.085Z"'::jsonb),
('anki-card-1758079590994-60', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Once a client with chronic renal failure begins dialysis, the protein content of their diet should be:*', 'Increase', 'Once a patient with chronic renal failure initiates maintenance dialysis (hemodialysis or peritoneal dialysis), dialytic amino acid and protein losses occur, requiring an increase in dietary protein allowances compared to pre-dialysis restrictions.', '["Increase","Decrease","Stay the same","Be eliminated"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:35.280Z"'::jsonb),
('anki-card-1758079609343-61', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Which of the following nutrients generally restricted in the diet of a client with renal failure?*', 'Potassium', 'As renal clearance declines, failing kidneys fail to excrete potassium efficiently, leading to hyperkalemia; thus, dietary potassium is generally restricted.', '["Vitamin D","Zinc","Potassium","Vitamin B6"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:39.265Z"'::jsonb),
('anki-card-1758079632106-62', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Renal disease often contributes to which of the following medical condition(s):*', 'A and B', 'Chronic kidney disease impairs endocrine and metabolic functions, directly contributing to renal anemia (A) and renal bone disease (B).', '["Anemia","Bone disease","Hypercalcemia","A and B"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:42.571Z"'::jsonb),
('anki-card-1758079667658-63', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Clients with renal failure usually require supplement of which nutrient(s)?*', 'All of the above', 'Due to dietary restrictions, malabsorption, and renal activation failures, renal failure clients routinely require clinical supplementation of calcium (A), active Vitamin D (B), and water-soluble vitamins like Vitamin B6 (C).', '["Calcium","Vitamin D","Vitamin B6","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:47.068Z"'::jsonb),
('anki-card-1758079706907-64', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Strategies for controlling fluid intake include:*', 'All of the above', 'To manage severe thirst and adhere to strict fluid restrictions, renal patients can use practical strategies like chewing gum, sucking on hard candy, eating frozen ice chips, or gargling with cold mouthwash.', '["Chew gum and Eat ice","Suck on hard candy","Gargle with refrigerated mouthwash","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:51.600Z"'::jsonb),
('anki-card-1758079726639-65', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Acute renal failure is most likely to develop in response to which of the following:*', 'Severe blood loss after trauma', 'Acute renal failure (ARF) is frequently precipitated by acute prerenal insults such as severe hypovolemia, hemorrhage, or trauma that abruptly cut off renal blood perfusion.', '["Atherosclerosis","Severe blood loss after trauma","Hypertension","Diabetes"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:40:59.634Z"'::jsonb),
('anki-card-1758079744737-66', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'A hypercatabolic state complicates acute renal failure because*', 'All of the above', 'Hypercatabolism in acute renal failure accelerates tissue breakdown for energy, elevating blood urea nitrogen, releasing intracellular potassium into the bloodstream, and impairing nutritional intake due to severe illness.', '["Protein is broken down for energy, causing blood urea to rise","Protein is broken down for energy, causing blood potassium to rise","The client usually feels too sick to eat, so consumes too few calories","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:05.081Z"'::jsonb),
('anki-card-1758079759869-67', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The dietary management of nephrotic syndrome includes:*', 'Consuming high levels of protein', 'Nephrotic syndrome is characterized by massive glomerular permeability and severe proteinuria; dietary management requires consuming adequate-to-high levels of high biological value protein to compensate for urinary protein losses while controlling edema.', '["Restricting calories","Consuming high levels of protein","Consuming generous amount of sodium","Consuming foods that reduce serum lipids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:36:56.926Z"'::jsonb),
('anki-card-1758079773153-68', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Sources of water do not include:*', 'Minerals', 'Sources of body water include ingested fluids, moisture in solid foods, and metabolic water produced during cellular oxidation, whereas minerals are inorganic elements and not sources of water.', '["Water itself","Foods","Metabolic reactions","Minerals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:08.583Z"'::jsonb),
('anki-card-1758079799502-69', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Dialysis reduces all of the following symptoms except:*', 'Anemia', 'While dialysis clears circulating uremic toxins, excess fluid, and corrects electrolyte imbalances, it does not correct renal anemia (which requires ongoing recombinant erythropoietin injections and iron supplementation).', '["Uremia","Edema","Hypertension","Anemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:12.822Z"'::jsonb),
('anki-card-1758079814283-70', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Individuals who are not generally considered as candidates for kidney transplants include all of the following except:*', 'Children', 'Children are fully viable and active candidates for pediatric kidney transplants; age extremes or unmanaged life-threatening co-morbidities are historical exclusion factors, making children the correct exception.', '["They are very old","Those with other life-threatening conditions","Children","Those who prefer dialysis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:16.074Z"'::jsonb),
('anki-card-1758079830600-71', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Recent research indicates that the addition of keto acids to a low protein diet increases the rate of renal deterioration.*', 'False', 'Clinical research demonstrates that supplementing keto acids (keto analogues of essential amino acids) alongside very low protein diets helps maintain nutritional status and slows the rate of renal deterioration, making the statement false.', '["True","False"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:20.093Z"'::jsonb),
('anki-card-1758079847649-72', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Once dialysis is initiated protein intake:*', 'Is less restrictive', 'Once hemodialysis or peritoneal dialysis is initiated, dietary protein restrictions are made less restrictive because dialysis actively clears circulating nitrogenous waste products, allowing higher protein intake to prevent wasting.', '["Is less restrictive","Is more restrictive","Remains the same","Emphasizes the addition of non-essential amino acid sources"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:37:00.675Z"'::jsonb),
('anki-card-1758079858650-73', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Acute renal failure is frequently caused by problems that originate outside of the kidney.*', 'True', 'Acute renal failure (ARF) is frequently triggered by prerenal causes originating outside the kidney—such as severe dehydration, hemorrhage, trauma, or circulatory shock—that acutely reduce renal blood flow.', '["True","False"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:37:04.362Z"'::jsonb),
('anki-card-1758079876860-74', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Kidney disease cannot be caused by:*', 'Habitual consumption of water', 'Normal, healthy water consumption does not cause kidney disease; rather, toxic metals, severe trauma, and pathological conditions (or extreme metabolic overloads) cause renal damage.', '["Consumption of toxic metals","Habitual consumption of water","Consumption of a diet habitually high in protein","Trauma"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:26.190Z"'::jsonb),
('anki-card-1758079893963-75', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Kilocalories usually need to be increased in protein-restricted diet because an adequate kilocalorie intake____________________.*', 'Spares protein', 'Providing an adequate, non-protein kilocalorie intake in protein-restricted diets ensures that the body utilizes carbohydrates and fats for energy rather than catabolizing dietary or somatic protein (spares protein).', '["Assists in control of serum potassium","Is necessary to prevent the renal anemia","Controls and prevents osteodystrophy","Spares protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:29.571Z"'::jsonb),
('anki-card-1758079910963-76', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Compared with renal failure patients who are not on dialysis, patients on continuous ambulatory peritoneal dialysis require:*', 'More dietary protein', 'Patients on continuous ambulatory peritoneal dialysis (CAPD) experience ongoing peritoneal protein and amino acid losses across the peritoneal membrane, requiring more dietary protein compared to non-dialysis CKD patients.', '["The same amount of dietary protein","Less dietary protein","More dietary protein","A different kind of protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:33.601Z"'::jsonb),
('anki-card-1758079948511-77', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Which of the following would be a good snack for a patient with acute renal failure who is not on dialysis?*', 'Hard candy', 'For an acute renal failure patient not on dialysis who requires strict restriction of potassium, phosphorus, protein, and fluids, pure sugar hard candy provides safe non-protein calories without mineral or fluid burdens.', '["Hard candy","Cheese","Milk","Oranges"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:37.588Z"'::jsonb),
('anki-card-1758079959911-78', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Some renal patients need to avoid salt substitutes because these often contain:*', 'Potassium', 'Many commercial salt substitutes replace sodium chloride with potassium chloride, which can trigger life-threatening hyperkalemia in renal patients who cannot excrete potassium.', '["Phosphorus","Potassium","Protein","Calcium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:41.265Z"'::jsonb),
('anki-card-1758079987859-79', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The _________intake from food is not monitored in renal patients.*', 'Vitamin D', 'While Vitamin D status is managed clinically via active analogs and serum monitoring, dietary Vitamin D intake from food is typically not monitored or restricted in routine renal meal planning compared to protein, fluid, sodium, and potassium.', '["Vitamin D","Fluid","Protein","Sodium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:46.883Z"'::jsonb),
('anki-card-1758080006476-80', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Which of the following are high in potassium?*', 'Baked potatoes', 'Baked potatoes are exceptionally rich sources of dietary potassium and must be restricted or leached in renal diets. Grapes, cranberry juice, and canned pears are lower-potassium options.', '["Grapes","Cranberry juice","Baked potatoes","Canned pears"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:50.525Z"'::jsonb),
('anki-card-1758080023024-81', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The most important nutritional consideration in treating patients with kidney stones is to:*', 'Increase fluid intake', 'The single most important universal nutritional and medical consideration in preventing and treating all forms of kidney stones (nephrolithiasis) is to increase fluid intake to dilute urinary solutes and prevent crystal precipitation.', '["Limit calcium intake","Restrict all end products of protein metabolism","Restrict all food sources of calcium, oxalic acid, and prunes","Increase fluid intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:37:08.570Z"'::jsonb),
('anki-card-1758080049657-82', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'A patient with Type 1 diabetes presents to the emergency room with dehydration and Kussmaul respirations. Urinalysis reveals ketonuria; lab results show blood glucose of 525 and pCO2 of 59.This patient is experiencing*', 'Metabolic acidocis', 'A patient with Type 1 diabetes presenting with hyperglycemia, ketonuria, dehydration, and Kussmaul respirations (compensatory hyperventilation) is experiencing diabetic ketoacidosis, which manifests as metabolic acidosis.', '["Respiratory acidosis","Respiratory alkalosis","Metabolic acidocis","Metabolic alkalosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:55.659Z"'::jsonb),
('anki-card-1758080065872-83', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'A chronic COPD patient with carbon dioxide retention would have which one of the following acid-base imbalances?*', 'Respiratory acidosis', 'Chronic obstructive pulmonary disease (COPD) patients with chronic carbon dioxide retention experience impaired alveolar ventilation, leading to hypercapnia and respiratory acidosis.', '["Respiratory acidosis","Respiratory alkalosis","Metabolic acidosis","Metabolic alkalosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:41:59.145Z"'::jsonb),
('anki-card-1758080080071-84', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'When pCO2 is 28, bicarbonate is 32, and pH is > 7.45, how do the kidneys compensate to assure acid-base balance?*', 'Excrete bicarbonate', 'When blood pH is elevated (>7.45) with low pCO2 and elevated bicarbonate (respiratory alkalosis), the renal compensatory mechanism acts to excrete bicarbonate ions in the urine while retaining hydrogen ions to normalize pH.', '["Conserve bicarbonate","Conserve sodium ions","Excrete bicarbonate","Conserve carbon dioxide"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:05.895Z"'::jsonb),
('anki-card-1758080108453-85', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Which of the following nutrition measures is most important for the person with acute respiratory failure*', 'A diet prescription that is low in carbohydrate and high in fat than a typical diet following acute stress', 'Acute respiratory failure places patients under severe hypermetabolic stress; nutritional support requires a high kilocalorie, high-protein diet to preserve lean muscle and support weaning from mechanical ventilation without excessive carbohydrate overfeeding (which increases CO2 production).', '["High volumes of fluids pr electrolytes to clean the lungs of fluids","A diet prescription that is low in carbohydrate and high in fat than a typical diet following acute stress","Attention to ensuring an adequate but not excessive energy intake","A high kilocalorie, high protein diet to support wearing from mechanical ventilation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:11.323Z"'::jsonb),
('anki-card-1758080126420-86', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Factors that frequently contribute in wasting the patients with COPD include*', 'Anorexia, medications and respiratory infections', 'Wasting (pulmonary cachexia) in COPD is driven by chronic systemic inflammation, increased work of breathing, anorexia, drug-nutrient side effects, and recurrent respiratory infections.', '["Anorexia, medications and respiratory infections","Dehydration, fat malabsorption and lactose intolerance","Essential fatty acids deficiencies and potassium imbalances","Vitamin K deficiencies, dysphagia and low fiber,low potassium diets"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:16.812Z"'::jsonb),
('anki-card-1758080148302-87', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'A 60 year old male is diagnosed as having acute respiratory failure, and is incubated and placed on a mechanical ventilator. He is  maintained with TPN. The solution used should:*', 'provide half of the non-protein kcal from fat', 'Parenteral nutrition solutions for mechanically ventilated respiratory failure patients should provide roughly half of non-protein calories from lipid emulsions to prevent excessive carbon dioxide production caused by high carbohydrate oxidation rates.', '["be high in glucose","be low in phosphorus","provide half of the non-protein kcal from fat","provide 3.0 grams of protein/ kg per Dayton"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:20.747Z"'::jsonb),
('anki-card-1758080182416-88', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The underlying pathological processes in cardiovascular disease are:*', 'Atherosclerosis and hypertension', 'Atherosclerosis (plaque buildup and arterial stiffening) and hypertension (chronic high blood pressure) serve as the primary foundational pathological processes driving cardiovascular disease.

• Coronary occlusion and obesity: Manifestations or risk factors rather than the overarching underlying pathological processes.', '["Atherosclerosis and hypertension","Coronary occlusion and obesity","Diabetes mellitus and cerebrovascular accidental","Kidney failure and congestive heart failure"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:35:04.442Z"'::jsonb),
('anki-card-1758080197150-89', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The first action a hypertensive patient should take to lower blood pressure is to:*', 'Lose weight if necessary', 'For hypertensive patients, the single most effective initial non-pharmacological lifestyle action to lower blood pressure is achieving and maintaining weight loss if overweight.', '["Restrict fluid to 1500 milliliters per day at","Eliminate saturated fat from the diet","Lose weight if necessary","Limit sodium Intake to 1 gram per day"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:24.052Z"'::jsonb),
('anki-card-1758080275813-90', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'The carriers of cholesterol to the cells for storage are the*', 'Low-density lipoproteins', 'Low-density lipoproteins (LDLs) function as the primary carriers transporting cholesterol from the liver out to peripheral cells for storage and cellular utilization ("bad cholesterol").', '["Chylomicrons","High-density lipoproteins","Low-density lipoproteins","Very low-density lipoproteins"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:29.742Z"'::jsonb),
('anki-card-1758080294410-91', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Monounsaturated fats may help lower blood cholesterol levels. Which of the following are mono unsaturated:*', 'Canola and peanut oils', 'Canola and peanut oils are rich sources of monounsaturated fatty acids (MUFAs).

• Safflower / Soybean / Corn / Sunflower: Rich in polyunsaturated fatty acids (PUFAs).', '["Safflower and soybean oils","Canola and peanut oils","Sunflower seed and cottonseed oils","Olive and corn oils"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:35.303Z"'::jsonb),
('anki-card-1758080309328-92', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Soluble fiber also helps to lower blood cholesterol levels. Which of the following are good sources of soluble fiber?*', 'Oats and legumes', 'Oats, barley, and legumes (beans, lentils) are exceptionally rich sources of viscous soluble fiber, which binds bile acids and helps lower serum cholesterol levels.', '["Broccoli and prunes","Whole-wheat bread and grapes","Green beans and raspberries","Oats and legumes"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:42:40.400Z"'::jsonb),
('anki-card-1758080335029-93', NULL, 'anki-deck-1783610445035-1790433132436-zkpto', 'Omega-3 fatty acids contribute to cardiovascular health by lowering triglyceride levels and reducing platelet aggregation. Good sources of these fatty acids are:*', 'Herring, salmon and tuna', 'Fatty cold-water fish such as herring, salmon, and tuna are exceptionally rich sources of anti-inflammatory omega-3 polyunsaturated fatty acids (EPA and DHA) that lower triglycerides and reduce platelet aggregation.', '["Lobster, bass and oyster","Catfish, shrimp and clams","Perch, walleye and pike","Herring, salmon and tuna"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.398Z"'::jsonb, '"2026-11-09T10:37:12.352Z"'::jsonb)
