INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758969017664-144', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Hormone produced by fat cells that induces insulin resistance. *', 'resistin', 'Resistin is an adipose-derived peptide hormone (adipokine) secreted by fat cells that has been shown in experimental and clinical studies to induce insulin resistance and impair systemic glucose tolerance.

• Leptin: Regulates long-term satiety and energy balance, suppressing appetite.
• Adiponectin: An anti-inflammatory adipokine that improves insulin sensitivity and protects against atherosclerosis.
• Ghrelin: A gastric peptide hormone that stimulates hunger and appetite.', '["leptin","adiponectin","resistin","ghrelin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:44:38.639Z"'::jsonb),
('anki-card-1758969025261-145', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Hormone/s released in the blood in response to stress or body injury leading to increased blood pressure and metabolic rate. *', 'catecholamines', 'During acute physiological stress, trauma, or physical injury, the sympathetic nervous system and adrenal medulla release stress hormones called catecholamines (epinephrine and norepinephrine), which trigger immediate increases in heart rate, blood pressure, and metabolic rate.

• Glucagon: A pancreatic hormone raising blood glucose during fasting, but catecholamines drive the acute stress hemodynamic surge.
• Aldosterone: A mineralocorticoid regulating sodium and water reabsorption in the kidneys.
• Cortisol: A glucocorticoid released during prolonged stress, whereas catecholamines mediate the immediate fight-or-flight response.', '["glucagon","aldosterone","catecholamines","cortisol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:44:44.686Z"'::jsonb),
('anki-card-1758969033131-146', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The immediate treatment provided to a patient with severe burns. *', 'fluid replacement', 'The absolute immediate clinical priority and primary life-saving treatment provided to a patient with severe thermal burns is aggressive fluid replacement (resuscitation) to prevent hypovolemic burn shock and maintain tissue perfusion.

• Micronutrient supplementation: Important during later rehabilitative phases, but secondary to acute fluid resuscitation.
• Parenteral feeding: Initiated after stabilization in hypermetabolic phases, not the immediate acute resuscitation priority.
• Blood transfusion: Administered if hemorrhage or severe anemia is present, but fluid/electrolyte resuscitation comes first.', '["fluid replacement","micronutrient supplementation","parenteral feeding","blood transfusion"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:44:49.668Z"'::jsonb),
('anki-card-1758969042264-147', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The usual primary risk factor for COPD. *', 'cigarette smoking', 'Cigarette smoking is universally recognized as the primary primary risk factor and leading behavioral cause of Chronic Obstructive Pulmonary Disease (COPD), accounting for the vast majority of chronic bronchitis and emphysema cases.

• Exposure to environmental/occupational pollutants: A contributing secondary risk factor, but cigarette smoking is the leading primary cause.
• Alpha-1-antitrypsin deficiency: A rare genetic cause of emphysema, not the most common primary risk factor.
• Frequent respiratory infections: Can exacerbate COPD, but smoking is the principal primary driver.', '["exposure to environmental/occupational pollutants","alpha-1-antitrypsin deficiency","cigarette smoking","frequent respiratory infections"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:44:56.236Z"'::jsonb),
('anki-card-1758969052328-148', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The preferred energy source/s for persons with COPD to bring about a lower RQ. *', 'fat', 'Oxidation of carbohydrates produces a higher Respiratory Quotient (RQ = 1.0) compared to fats (RQ = 0.7). Because patients with COPD suffer from compromised respiratory function and difficulty clearing carbon dioxide, a higher fat and lower carbohydrate diet reduces carbon dioxide production relative to oxygen consumed, lowering the RQ and easing ventilatory workload.

• Carbohydrates: Yield an RQ of 1.0, producing high carbon dioxide loads that stress compromised respiratory patients.
• Both carbohydrates & fats: Excess carbohydrates increase CO2 retention in COPD.
• Protein: Essential for tissue repair, but fat is specifically preferred for lowering the metabolic RQ.', '["carbohydrates","fat","both carbohydrates & fats","protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:01.945Z"'::jsonb),
('anki-card-1758969061628-149', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Persons with GERD can develop the following except: *', 'gastric ulcerption 1', 'Gastroesophageal Reflux Disease (GERD) involves chronic acid reflux that can lead to complications such as Barrett’s esophagus, esophageal strictures, and esophageal ulcers. Gastric ulceration occurs in the stomach rather than being a direct complication of lower esophageal sphincter reflux, making it the correct exception.

• Barrett’s esophagus: A well-established precancerous metaplastic complication of chronic GERD.
• Esophageal ulcer: Caused by corrosive gastric acid eroding the lower esophageal lining.
• Dysphagia: Difficulty swallowing resulting from inflammation or scarring in the esophagus.', '["Barrett’s esophagus","esophageal ulcer","dysphagia","gastric ulcerption 1"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:08.587Z"'::jsonb),
('anki-card-1758969069778-150', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Foods and beverages that increase acid secretion or irritate gastrointestinal lining should be avoided by persons diagnosed with peptic ulcer except for: *', 'sugars & starches', 'Foods that stimulate excessive gastric acid secretion or directly irritate the gastrointestinal mucosal lining (such as alcohol, caffeine, decaffeinated coffee/tea, and chocolates) must be avoided in peptic ulcer disease. Simple sugars and starches do not irritate the mucosal lining or stimulate excess acid secretion like spices, caffeine, and alcohol, making them the correct exception.

• Decaffeinated coffee & tea: Contain compounds that still stimulate gastric acid output.
• Alcohol: A direct gastric mucosal irritant and secretagogue.
• Chocolates: Contain methylxanthines and fat that relax the lower esophageal sphincter and irritate the gut lining.', '["decaffeinated coffee & tea","alcohol","sugars & starches","chocolates"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:15.364Z"'::jsonb),
('anki-card-1758969077592-151', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The body’s most metabolically active organ involved in the processing, storage, and redistribution of nutrients. *', 'liver', 'The liver is the body''s largest and most metabolically active internal organ, playing the central role in processing, interconverting, storing, and redistributing carbohydrates, lipids, and proteins.

• Stomach: Primarily responsible for mechanical churning and initial gastric proteolysis.
• Pancreas: An exocrine and endocrine gland producing digestive enzymes and insulin/glucagon.
• Heart: A muscular pump circulating blood through the vascular system.', '["stomach","liver","pancreas","heart"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:21.917Z"'::jsonb),
('anki-card-1758969089709-152', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Two most common liver disorders that are considered mild and are usually reversible. 1. hepatitis 2. cirrhosis 3. fatty liver 4. Wilson’s disease *', '1 & 3', 'Among liver disorders, hepatitis (1) (viral inflammation) and fatty liver (3) (hepatic steatosis) are considered relatively mild in their early stages and are frequently reversible with lifestyle modification and medical management.

• Cirrhosis: Involves permanent, irreversible fibrous scarring and architectural remodeling of the liver.
• Wilson’s disease: A serious genetic copper-accumulation disorder requiring lifelong management.', '["1 & 2","1 & 3","1 & 4","2 & 4"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:26.875Z"'::jsonb),
('anki-card-1758969099993-153', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Ascites develops in patients with cirrhosis due to: *', 'portal hypertension', 'Ascites (fluid accumulation in the peritoneal cavity) develops in patients with cirrhosis primarily due to portal hypertension (increased blood pressure in the portal venous system) combined with hypoalbuminemia and renal sodium retention.

• Reduced albumin synthesis in the liver: Contributes to lowered plasma oncotic pressure, but portal hypertension is the primary mechanical hemodynamic driver of ascites.
• Elevated serum ammonia levels: Results from hepatic encephalopathy, not fluid ascites formation.', '["sodium & water retention in the kidneys","reduced albumin synthesis in the liver","portal hypertension","elevated serum ammonia levels"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:31.743Z"'::jsonb),
('anki-card-1758969106393-154', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Once ascites develops in patients with cirrhosis, dietary intake of _____ should be limited: *', 'sodium', 'Once ascites develops in patients with cirrhosis, renal sodium and water reabsorption become markedly abnormal, making dietary restriction of sodium the cornerstone medical nutrition therapy to prevent further fluid retention.

• Protein: Restricted only if hepatic encephalopathy is actively present; otherwise adequate protein is required to prevent muscle wasting.
• Sugars / Potassium: Monitored based on blood glucose and diuretic use, but sodium restriction is the absolute priority for ascites.', '["protein","sugars","sodium","potassium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:37.154Z"'::jsonb),
('anki-card-1758969113725-155', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Typical features of Type I diabetes except: *', 'increased risk to abdominal obesity', 'Type 1 diabetes mellitus is characterized by autoimmune destruction of pancreatic beta cells leading to absolute insulin deficiency and dependence on exogenous insulin, making increased risk to abdominal obesity the incorrect characteristic (as Type 1 patients are typically lean at onset, whereas abdominal obesity is a hallmark of Type 2 diabetes).

• Destruction of pancreatic beta cells: True hallmark of Type 1 autoimmune diabetes.
• Absolute insulin deficiency occurs: True; requiring lifelong insulin therapy.
• Increased risk of developing other autoimmune diseases: True; associated with autoimmune thyroiditis, celiac disease, etc.', '["increased risk to abdominal obesity","destruction of pancreatic beta cells","absolute insulin deficiency occurs","increased risk of developing other autoimmune diseases"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:42.773Z"'::jsonb),
('anki-card-1758969123207-156', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The desirable BMI to achieve and maintain by adults in order to ≥prevent CHD.', '18.5 – 24.9', 'The desirable and healthy Body Mass Index (BMI) range for adults to maintain optimal metabolic health and prevent coronary heart disease (CHD) is 18.5 to 24.9 kg/m².

• 18.5: Represents the underweight threshold cutoff.
• 25 – 29.9: Classified as overweight, carrying increased chronic disease risk.
• ≥30: Classified as obesity.', '["18.5","18.5 – 24.9","25 – 29.9","≥30"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:50.422Z"'::jsonb),
('anki-card-1758969129942-157', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The organ most affected in diabetic ketoacidosis (DKA): *', 'pancreas', 'Wait—let''s examine this card''s anomaly. Diabetic Ketoacidosis (DKA) is a life-threatening complication arising from absolute insulin deficiency, resulting in severe hyperglycemia, dehydration, and ketoacidosis, which severely affects systemic metabolism across the liver, blood, and kidneys. In this specific legacy board exam key, pancreas is designated as the primary organ of origin/dysfunction underlying DKA.', '["liver","lungs","kidneys","pancreas"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:45:56.775Z"'::jsonb),
('anki-card-1758969138257-158', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Foods allowed in low purine diet: 1. milk & eggs 2. glandular organs 3. cheese *', '1 & 3', 'A low-purine diet restricts purine-rich foods (like organ meats and seafood) to manage gout and hyperuricemia. Milk and eggs (1) and cheese (3) contain negligible purines and are fully allowed, whereas glandular organs (like liver and kidneys) are strictly restricted.

• 1 & 2: Incorrect because glandular organs are high-purine foods.
• 1, 2, 3: Incorrect because glandular organs must be avoided.', '["1 & 2","1 & 3","1, 2, 3","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:46:02.555Z"'::jsonb),
('anki-card-1758969146591-159', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Source of gluten and should be avoided in gluten-sensitive enteropathy and dermatitis herpetiformis. *', 'wheat, rye, oats, barley', 'Gluten-sensitive enteropathy (celiac disease) and dermatitis herpetiformis require a strict gluten-free diet that eliminates all grains containing the protein gluten: wheat, rye, oats, and barley.

• Rye, oats, rice, barley / Oats, corn, barley, rice: Incorrect because rice and corn are naturally gluten-free grains.', '["rye, oats, rice, barley","wheat, rye, barley, rice","oats, corn, barley, rice","wheat, rye, oats, barley"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:46:08.743Z"'::jsonb),
('anki-card-1758969154406-160', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Storehouse of concentrated bile: *', 'gallbladder', 'The gallbladder is a small pear-shaped organ that stores, concentrates, and releases bile produced by the liver into the small intestine during fat digestion.

• Liver: Synthesizes bile, but does not store it in concentrated form.
• Kidneys: Filter blood and produce urine.
• Pancreas: Secretes digestive enzymes and bicarbonate.', '["liver","gallbladder","kidneys","pancreas"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:58:26.955Z"'::jsonb),
('anki-card-1758969161956-161', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'A side effect of these medications prescribed in CHD is a reduction of cholesterol synthesis in the liver. *', 'statins', 'Statins (HMG-CoA reductase inhibitors) are lipid-lowering medications prescribed in coronary heart disease (CHD) management that work by inhibiting the rate-limiting enzyme in hepatic cholesterol synthesis, thereby reducing endogenous cholesterol production.

• Bile acid sequestrants: Bind bile acids in the intestine to promote their excretion.
• Nicotinic acid: Lowers triglycerides and raises HDL by inhibiting hepatic fatty acid release.
• Fibric acid derivatives (Fibrates): Primarily lower serum triglycerides by activating lipoprotein lipase.', '["bile acid sequestrants","nicotinic acid","statins","fibric acid derivatives"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:46:14.462Z"'::jsonb),
('anki-card-1758969175273-162', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Considered as the most atherogenic dietary risk factors for CHD. 1. cholesterol 2. saturated fat 3. trans-fat 4. MUFA *', '1, 2, 3', 'The most atherogenic dietary risk factors strongly promoting coronary heart disease are dietary cholesterol (1), saturated fat (2), and trans-fats (3), all of which raise atherogenic LDL cholesterol levels. Monounsaturated fatty acids (MUFA, 4) are heart-healthy fats, making 1, 2, 3 the correct combination.', '["1, 2, 4","1, 2, 3","2, 3, 4","1, 3, 4"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:46:19.992Z"'::jsonb),
('anki-card-1758969182423-163', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Modifiable risk factors for CHD except: *', 'increasing age', 'Non-modifiable risk factors for coronary heart disease include increasing age, male gender, and family history of premature heart disease. Age cannot be modified or changed through lifestyle interventions.', '["increasing age","abdominal obesity","physical inactivity","an atherogenic diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:46:26.116Z"'::jsonb),
('anki-card-1758969193738-164', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The following modifiable risk factors are related to one’s diet except: *', 'physical inactivity', 'While physical inactivity is a major modifiable risk factor for CHD, the question specifies modifiable risk factors directly related to one''s diet (such as high LDL, low HDL, and obesity resulting from caloric intake). Physical inactivity is a lifestyle behavior rather than a direct dietary parameter, making it the correct exception.', '["high LDL cholesterol","low HDL cholesterol","obesity","physical inactivity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:46:31.779Z"'::jsonb),
('anki-card-1758969201938-165', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The desirable systolic/diastolic blood pressure level: *', '<120/<80', 'According to standard clinical guidelines, the desirable and optimal blood pressure classification for adults is less than 120 mmHg systolic and less than 80 mmHg diastolic (<120/<80).', '["<120/<80","140 - 159","120 – 139","120/80"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:46:54.939Z"'::jsonb),
('anki-card-1758969208837-166', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'To lose 2 lbs. per week, one must reduce daily calories by: *', '1,000', 'A caloric deficit of approximately 3,500 kcal equals one pound of body weight loss. To achieve a rapid, safe weight loss of 2 pounds per week, one must create a weekly deficit of 7,000 kcal (2 lbs x 3,500 kcal), which requires reducing daily calories by 1,000 kcal per day (1,000 x 7 = 7,000 kcal).

• 500: Results in 1 pound of weight loss per week.
• 750: Results in 1.5 pounds of weight loss per week.
• 1,200: Exceeds standard safe daily deficit targets without medical supervision.', '["500","1,000","750","1,200"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:47:02.627Z"'::jsonb),
('anki-card-1758969216286-167', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'To lose 1 lb. per week, one must reduce daily calories by: *', '500', 'A caloric deficit of approximately 3,500 kcal is required to lose one pound of body fat. To achieve a steady weight loss of 1 lb per week, one must reduce daily caloric intake or increase energy expenditure by 500 kcal per day (500 kcal x 7 days = 3,500 kcal).

• 750: Results in roughly 1.5 lbs of weight loss per week.
• 100: Insufficient deficit to achieve meaningful weekly weight loss.
• 1,000: Results in approximately 2 lbs of weekly weight loss.', '["500","750","100","1,000"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:55:55.698Z"'::jsonb),
('anki-card-1758969226137-168', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'If TCR is 2000 kcal and fat is 900kcal, it is _____ of TCR. *', '45%', 'To calculate the percentage of total caloric requirement (TCR) contributed by fat:

Formula = (Fat Calories ÷ Total Calories) x 100

Given values: Fat calories = 900 kcal; Total calories = 2,000 kcal.

Calculation = (900 ÷ 2,000) x 100 = 45%.', '["45%","50%","60%","70%"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:48:20.263Z"'::jsonb),
('anki-card-1758969234303-169', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'A diet prescription of 1800 calories with a 40g protein restriction and a 70% CHO-30%FAT (of NPC) distribution will provide: *', '287g CHO- 55g FAT', 'To calculate the exact macronutrient grams from an 1800 kcal prescription:

Protein = 40g x 4 kcal/g = 160 kcal.

Non-Protein Calories (NPC) = 1,800 - 160 = 1,640 kcal.

Carbohydrate = 70% of 1,640 kcal = 1,148 kcal ÷ 4 kcal/g = 287g CHO.

Fat = 30% of 1,640 kcal = 492 kcal ÷ 9 kcal/g = 54.67g FAT (rounding to 55g FAT).', '["200g CHO-48g FAT","256g CHO-50g FAT","287g CHO- 55g FAT","305g CHO-62g FAT"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:48:25.953Z"'::jsonb),
('anki-card-1758969242319-170', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'A 2000 calories blenderized formula at 1.5 calories/ml concentration will have a total volume of: *', '1333ml', 'To calculate total fluid volume for an enteral feeding:

Formula = Total Daily Calories ÷ Caloric Density (kcal/ml)

Given values: Total calories = 2,000 kcal; Concentration = 1.5 kcal/ml.

Calculation = 2,000 ÷ 1.5 = 1,333.33 ml (rounding to 1,333 ml).', '["1200ml","1333ml","1000ml","2000ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:48:32.038Z"'::jsonb),
('anki-card-1758969249384-171', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The BMI of a 5’2” individual with an actual weight of 65 kg is: *', '26', 'To calculate Body Mass Index (BMI):

Height in meters: 5 feet 2 inches = 62 inches x 0.0254 = 1.5748 meters.

Formula = Weight (kg) ÷ [Height (m)]²

Calculation = 65 ÷ (1.5748)² = 65 ÷ 2.48 = 26.21 (rounding to 26).', '["20","23","25","26"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:48:38.403Z"'::jsonb),
('anki-card-1758969260035-172', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The addition of 10 grams salt in the diet increases the sodium content by: *', '4g', 'Table salt (sodium chloride, NaCl) is approximately 40% sodium by atomic weight. Therefore, adding 10 grams of table salt to the diet increases total sodium content by: 10g x 0.40 = 4 grams (4,000 mg) of sodium.', '["10g","2g","6g","4g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:48:43.726Z"'::jsonb),
('anki-card-1758969270351-173', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Fat emulsions of 20% concentration contain ____ calories per milliliter. *', '2', 'Intravenous lipid emulsions (such as 20% IV fat emulsions) provide approximately 2.0 kcal per milliliter.', '["2","1","8","9"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:06.556Z"'::jsonb),
('anki-card-1758969279818-174', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Azotemia is detected through the measurement of: *', 'blood urea nitrogen', 'Azotemia (elevated levels of nitrogenous waste products in the blood, such as urea and creatinine) is clinically detected and measured primarily through Blood Urea Nitrogen (BUN) laboratory blood tests.

• Calcium in the blood: Evaluates calcium and bone metabolic status.
• Uric acid in the urine: Evaluates gout risk and purine metabolism.
• Sodium in the spinal fluid: Evaluates neurological and electrolyte status.', '["calcium in the blood","uric acid in the urine","blood urea nitrogen","sodium in the spinal fluid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:11.769Z"'::jsonb),
('anki-card-1758969289701-175', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Tendency to acidosis and ketosis is common among diabetics who are:', 'insulin-dependent', 'Patients with Type 1 (insulin-dependent) diabetes mellitus lack endogenous insulin entirely, rendering them highly prone to rapid lipolysis, hepatic ketogenesis, and life-threatening metabolic acidosis and ketosis (Diabetic Ketoacidosis) if insulin is omitted.

• Non-insulin dependent (Type 2): Retain sufficient baseline insulin to prevent rapid spontaneous ketoacidosis under normal conditions.
• Taking oral hypoglycemics: Typically used by Type 2 patients who maintain endogenous insulin reserve.', '["non-insulin dependent","insulin-dependent","taking oral hypoglycemics","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:17.446Z"'::jsonb),
('anki-card-1758969333466-176', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Deficiency that occurs in a strict milk diet. *', 'Fe', 'Milk is an exceptionally poor source of iron (Fe). An infant or adult maintained exclusively on a strict, unfortified milk diet for an extended period will rapidly develop iron-deficiency anemia.

• Vitamin A / Ca / Na: Milk is a good source of calcium and sodium, and can be fortified with Vitamin A, whereas iron is famously deficient in milk.', '["vitamin A","Ca","Fe","Na"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:23.479Z"'::jsonb),
('anki-card-1758969343782-177', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Defects in lipid metabolism can be due to: *', 'all of the above', 'Defects in lipid metabolism and transport can originate from diverse etiologies, including genetic inborn errors of metabolism (such as familial hypercholesterolemia), endocrinopathies (such as hypothyroidism or uncontrolled diabetes), and specific organ failure (such as liver or renal disease), making "all of the above" correct.', '["inborn error of metabolism","endocrinopathy","specific organ failure","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:28.111Z"'::jsonb),
('anki-card-1758969359664-178', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Recommended amount of tube feeding every 2-3 hours?. *', '200 cc', 'For standard intermittent tube feeding protocols, a volume of approximately 200 cc (mL) given every 2 to 3 hours represents a safe volume to prevent gastric overdistension.

• 50 cc / 100 cc: Too small to meet daily caloric goals efficiently.
• 500 cc: Excessively large bolus volume that would cause severe gastric cramping and aspiration risk.', '["50 cc","100 cc","200 cc","500 cc"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:33.007Z"'::jsonb),
('anki-card-1758969368163-179', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The total volume of a 1600 kcal tube feeding, 1:1 dilution is _____ml. If given every 4 hours, the volume per feeding is _____ml. *', '1,600 ml; 266 ml', 'To calculate tube feeding volume and schedule:

Total formula volume at a 1:1 dilution (1 kcal/ml) for 1,600 kcal = 1,600 ml.

If given every 4 hours across a 24-hour day, there are 6 feedings (24 ÷ 4 = 6).

Volume per feeding = 1,600 ml ÷ 6 feedings = 266.67 ml (rounding to 266 ml).', '["1066 ml; 177 ml","800 ml; 133 ml","1,600 ml; 266 ml","1650 ml; 275 ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:41.444Z"'::jsonb),
('anki-card-1758969376514-180', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The desirable body weight of a 3 year-old child. *', '14 kg', 'Using standard pediatric growth estimation formulas for children (Age in years x 2 + 8, or standard weight-for-age reference standards), a normal 3-year-old child has a desirable reference body weight of approximately 14 kg (ranging around 14–15 kg in standard pediatric board keys).', '["12 kg","13 kg","14 kg","15 kg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:46.357Z"'::jsonb),
('anki-card-1758969383480-181', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The total protein required per day for a 7 year-old child. *', '30g/day', 'According to established pediatric nutrient reference standards (such as the Philippine Dietary Reference Intakes / RENI), the recommended daily protein requirement for a 7-year-old child is approximately 30g/day to support active growth and tissue development.', '["7g/day","18g/day","22 g/day","30g/day"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:50.344Z"'::jsonb),
('anki-card-1758969394046-182', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Smoking, dietary habits, physical activity, and alcohol intake influencing the development of diseases are known as: *', 'risk factors', 'Behaviors and environmental exposures like smoking, poor dietary habits, physical inactivity, and excessive alcohol intake that increase the probability of developing chronic diseases are clinically termed risk factors.

• Chronic causes: A colloquial term, whereas risk factor is the epidemiological standard.
• Non-communicable conditioning factors / Disease descriptors: Non-standard clinical terminology for lifestyle habits.', '["chronic causes","risk factors","non-communicable conditioning factors","disease descriptors"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:57:49.934Z"'::jsonb),
('anki-card-1758969404695-183', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'If there is inadequate glucose in metabolism, fat fragments combine to form: *', 'ketone bodies', 'When dietary carbohydrate or glucose availability is inadequate for cellular energy, fatty acid fragments (acetyl-CoA) cannot enter the Krebs cycle efficiently due to oxaloacetate depletion and instead condense to form ketone bodies (acetoacetate and beta-hydroxybutyrate).

• Lipoproteins: Transport particles for lipids in blood plasma.
• Mucilages: Soluble plant fiber components.
• Micelles: Colloidal lipid digestion aggregates in the gut lumen.', '["lipoproteins","mucilages","ketone bodies","micelles"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:57:55.588Z"'::jsonb),
('anki-card-1758969413592-184', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Nutrition care process is a systematic method that is used to: *', 'meet the nutrient needs of patients', 'The Nutrition Care Process (NCP) is a standardized, systematic problem-solving method designed by the Academy of Nutrition and Dietetics to provide high-quality nutrition care and meet the individualized nutrient needs of patients.', '["identify the nutrient content of foods","conduct nutrition screening","prescribe special diets","meet the nutrient needs of patients"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:58:01.770Z"'::jsonb),
('anki-card-1758969425595-185', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Due to an illness, a patient experiences loss of appetite, difficulty swallowing, and mouth pain. He is at risk of malnutrition brought about by: *', 'reduced food intake', 'Loss of appetite (anorexia), dysphagia (difficulty swallowing), and oral pain directly impair a patient''s ability to eat, placing them at nutritional risk primarily brought about by reduced food intake.

• Increased nutrient losses: Caused by vomiting, diarrhea, or malabsorption, not oral pain.
• Altered metabolism: Associated with systemic hypermetabolic stress states.
• Altered digestion and absorption: Caused by GI structural disorders or enzyme deficiencies.', '["increased nutrient losses","altered metabolism","reduced food intake","altered digestion and absorption"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:58:08.887Z"'::jsonb),
('anki-card-1758969436027-186', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'An undernourished, acutely ill patient started eating after several days of not having an adequate food intake. A blood test that would change most quickly as the patient improves in health and nutritional status is: *', 'retinol-binding protein', 'Retinol-binding protein (RBP) has a very short half-life (approximately 12 hours), making it the most sensitive visceral protein marker that changes and responds most quickly to improvements in clinical health and nutritional status.

• Albumin: Has a long half-life of roughly 14–20 days, changing slowly during acute nutritional repletion.
• Serum electrolytes: Fluctuate rapidly due to hydration and renal status, not specific nutritional repletion markers.
• Transferrin: Has an intermediate half-life of approximately 8–10 days.', '["albumin","serum electrolytes","retinol-binding protein","transferrin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:58:15.411Z"'::jsonb),
('anki-card-1758969445010-187', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Mechanical soft diets are prescribed for individuals with: *', 'difficulty in swallowing and chewing', 'Mechanical soft diets are clinically modified to alter texture (ground, minced, or pureed foods) and are prescribed specifically for patients experiencing difficulty in chewing and swallowing (dysphagia or dental deficits).

• Disorders of the liver, gallbladder, or pancreas: Require low-fat or specialized therapeutic diets.
• Acute inflammation of the GIT: Require low-fiber or clear liquid diets.
• Diarrhea and vomiting: Require low-residue or clear liquid rehydration protocols.', '["disorders of the liver, gallbladder, or pancreas","acute inflammation of the GIT","difficulty in swallowing and chewing","diarrhea and vomiting"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:58:21.697Z"'::jsonb),
('anki-card-1758969453310-188', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Medication-related symptoms that can limit food intake: *', 'persistent nausea & vomiting', 'Medication-related side effects such as persistent nausea and vomiting directly impair gastrointestinal comfort, destroy appetite, and severely limit oral food and nutrient intake.

• Diarrhea: Causes nutrient loss, but nausea and vomiting directly halt intake.
• Insomnia: Affects sleep, but less directly limits eating compared to emesis.
• Sin rash (Skin rash): A dermatological side effect, not a direct feeding limitation.', '["diarrhea","insomnia","sin rash","persistent nausea & vomiting"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:49:56.286Z"'::jsonb),
('anki-card-1758969461225-189', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Osmolality refers to the enteral formula’s: *', 'concentration of molecules and ionic particles', 'Osmolality refers strictly to the total concentration of osmotically active molecules and ionic particles dissolved in a solution (measured in milliosmoles per kilogram, mOsm/kg).

• Energy density: Measures calories per milliliter (kcal/ml).
• Nutrient density: Measures essential nutrients per kilocalorie.
• Degree of dilution: Describes how diluted a formula is, not its precise particle osmolality.', '["energy density","nutrient density","degree of dilution","concentration of molecules and ionic particles"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:02.815Z"'::jsonb),
('anki-card-1758969469226-190', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The number of kilocalories provided by 500 ml of an 8.5% amino acid solution. *', '170', 'To calculate the kilocalories provided by an amino acid solution:

Solution concentration = 8.5% (meaning 8.5 grams of protein per 100 ml).

Total volume = 500 ml.

Total grams of protein = 500 ml x (8.5g ÷ 100 ml) = 42.5 grams.

Energy conversion factor for protein = 4 kcal/g.

Total kilocalories = 42.5g x 4 kcal/g = 170 kcal.', '["60","170","340","500"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:09.169Z"'::jsonb),
('anki-card-1758969480709-191', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Iron is usually excluded from parenteral solutions partly because: *', 'iron can destabilize solutions that include lipid emulsions.', 'Iron is routinely excluded from standard parenteral nutrition solutions primarily because supplemental iron can destabilize complex intravenous solutions, particularly those containing intravenous lipid emulsions, causing coalescence and safety hazards.', '["iron restriction is needed in persons using warfarin therapy.","iron promotes fat deposition in the liver.","iron can destabilize solutions that include lipid emulsions.","iron requirements vary substantially from person to person."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:16.515Z"'::jsonb),
('anki-card-1758969489425-192', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Some gastric surgeries increase the risk of dumping syndrome which may occur within 30 minutes after eating. Symptoms include: *', 'all of the above', 'Gastric surgeries (such as subtotal gastrectomy or Roux-en-Y bypass) accelerate gastric emptying, causing early dumping syndrome within 30 minutes of eating. Symptoms include rapid heartbeat (tachycardia), flushing, sweating, and abdominal cramps, making "all of the above" correct.', '["rapid heart beat","flushing, sweating","abdominal cramps","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:22.116Z"'::jsonb),
('anki-card-1758969497391-193', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The calorie content of a 1 liter, 16% dextrose solution is: *', '545 calories', 'To calculate the calorie content of a dextrose solution:

Concentration = 16% dextrose (meaning 160 grams of dextrose per 1,000 ml / 1 liter).

Energy conversion factor for intravenous dextrose (dextrose monohydrate) = 3.4 kcal/g.

Total calories = 160g x 3.4 kcal/g = 544 kcal (rounding to 545 calories in standard legacy board keys).', '["650 calories","545 calories","640 calories","600 calories"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:26.947Z"'::jsonb)
