INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758969543739-194', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'A partially digestible polysaccharide that is used to test kidney function. *', 'inulin', 'Inulin is a naturally occurring fructose polymer (fructan) that is freely filtered by the renal glomerulus and neither reabsorbed nor secreted by the renal tubules, making it the classic gold-standard substance used in clinical research to measure Glomerular Filtration Rate (GFR) and kidney function.

• Mannosan / Pentosan / Galactogens: Complex polysaccharides, but inulin is the classic clinical renal clearance marker.', '["mannosan","pentosan","inulin","galactogens"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:32.505Z"'::jsonb),
('anki-card-1758969556472-195', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'A decrease in Resting Energy Expenditure (REE) occurs in all conditions except in: *', 'a person with fever', 'Resting Energy Expenditure (REE) decreases during states of starvation, fasting, hypothyroidism, and physical adaptation (obesity). In contrast, a person with fever experiences a hypermetabolic surge that increases REE by roughly 7% per degree Fahrenheit, making fever the correct exception.

• A person who is fasting: Lowers REE as an adaptive mechanism to conserve energy.
• A person with hypothyroidism: Lowers REE due to deficient thyroid hormone levels.
• An obese person: While total mass is high, relative REE per kg can adjust down, but fever explicitly elevates metabolic rate.', '["a person who is fasting","a person with hypothyroidism","a person with fever","an obese person"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:38.827Z"'::jsonb),
('anki-card-1758969567503-196', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'The activity level used in estimating energy requirements for hospital patients on bed rest but mobile: *', '27.5 kcal/kg BW', 'For hospitalized patients who are confined to bed rest but remain mobile or require standard baseline support, standard clinical estimation guidelines frequently utilize 27.5 kcal/kg body weight (or range between 25–30 kcal/kg) to estimate basal and baseline energy requirements.', '["27.5 kcal/kg BW","30 kcal/kg BW","35.0 kcal/kg BW","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:43.319Z"'::jsonb),
('anki-card-1758969577452-197', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'Individuals using MAO inhibitors should limit their intake of: *', 'aged cheeses', 'Patients prescribed Monoamine Oxidase Inhibitors (MAOIs) for depression must strictly avoid foods rich in tyramine—such as aged cheeses, cured meats, and fermented products—because MAOIs block tyramine degradation, leading to life-threatening hypertensive crises.

• Whole milk / Yogurt / Dark green leafy vegetables: Contain little to no tyramine compared to aged, cured, and fermented cheeses.', '["whole milk","yogurt","dark green leafy vegetables","aged cheeses"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T04:50:49.179Z"'::jsonb),
('anki-card-1758969584920-198', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'A metabolic change accompanying acute stress: *', 'muscle protein catabolism', 'Severe acute stress, trauma, or sepsis triggers a hypermetabolic surge of counter-regulatory hormones (cortisol, catecholamines) that accelerates muscle protein catabolism to supply amino acids for acute-phase protein synthesis and gluconeogenesis.

• Reduced health & respiratory rates: Acute stress causes tachycardia and tachypnea (increased rates).
• Elevated immune response: Acute stress triggers systemic inflammation, but immune dysfunction or suppression often accompanies severe catabolic trauma.
• Hypoglycemia: Acute stress typically induces stress-induced hyperglycemia due to glycogenolysis and gluconeogenesis.', '["reduced heart & respiratory rates","muscle protein catabolism","elevated immune response","hypoglycemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:56:04.595Z"'::jsonb),
('anki-card-1758969592686-199', NULL, 'anki-deck-1783610495718-1790433139833-fmjgg', 'All are common complications of parenteral nutrition except: *', 'diarrhea', 'Parenteral nutrition (nutrients delivered intravenously) bypasses the gastrointestinal tract entirely, making diarrhea an uncommon direct complication (though GI atrophy can occur). Common complications include catheter-related infections, hyperglycemia, electrolyte imbalances, and hepatobiliary issues.

• Increased risk to infection: High risk due to central venous catheter access and high dextrose content.
• Gallbladder disease: A common complication of long-term TPN due to lack of enteral stimulation (cholestasis/sludge).
• Fatty liver (hepatic steatosis): Frequently occurs due to overfeeding, excess caloric load, or lipid imbalances.', '["increased risk to infection","diarrhea","gallbladder disease","fatty liver"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.996Z"'::jsonb, '"2026-11-09T03:56:12.125Z"'::jsonb),
('anki-card-1756967911837-0', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Foods allowed in a low purine diet:', 'Milk, cheese, and eggs', 'These foods are generally low in purines and are appropriate choices in a low-purine diet. In contrast, organ meats contain very high amounts of purines and are restricted, particularly for patients with gout or hyperuricemia.', '["Milk, cheese, and eggs","Grandular organs","All of the above","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:00.834Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:00.834Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:00.834Z"'::jsonb),
('anki-card-1756967954542-1', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The enzyme that cleaves aromatic amino acids.', 'Chymotrypsin', 'Chymotrypsin is a pancreatic protease that preferentially cleaves peptide bonds on the carboxyl side of aromatic amino acids, particularly phenylalanine, tyrosine, and tryptophan. This specificity helps break dietary proteins into smaller peptides during intestinal digestion.', '["Chymotrypsin","Pepsin","Carboxypeptidase","Aminopeptidase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:43.709Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:59:43.709Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:43.709Z"'::jsonb),
('anki-card-1756968011507-2', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'It refers to the anabolic formation of triacyglycerol from glycerol and fatty acids.', 'Lipogenesis', 'Lipogenesis refers broadly to the formation and storage of fat, including the synthesis of triacylglycerol (TAG) from glycerol-derived molecules and fatty acids. It occurs primarily when energy intake exceeds immediate energy needs, allowing excess energy to be stored as body fat.', '["Lipogenesis","Fatty acid synthesis","Cholesterol synthesis","Gluconeogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:58:01.255Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:58:01.255Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:58:01.255Z"'::jsonb),
('anki-card-1756968084754-3', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'What is the first feeding for a patient with 1200 kcal, 2:1 diet Rx?', 'No first feeding', 'In the traditional therapeutic-diet terminology used in Philippine dietetics, a 2:1 diet prescription refers to a diet in which the first feeding is omitted. The prescribed 1,200 kcal refers to the total daily energy allowance, but the specific first feeding is determined by the diet pattern/order rather than by simply selecting a liquid food. Thus, “no first feeding” is the intended answer.', '["1/2 evaporated milk diluted in 1/2 cup water","1/2 cup juice diluted in 1/2 cup water","No first feeding","Cannot be determined from the given provided"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:51.030Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:56:51.030Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:51.030Z"'::jsonb),
('anki-card-1756968140553-4', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The conversion of acetyl-CoA into acetoacetic acid, beta-hydroxybutryric acid or acetone is called:', 'Ketogenesis', 'Ketogenesis is the metabolic process in which excess acetyl-CoA, primarily generated from fatty acid oxidation in the liver, is converted into ketone bodies: acetoacetate, β-hydroxybutyrate, and acetone. It becomes more active when carbohydrate availability or insulin action is insufficient, such as during prolonged fasting, starvation, or uncontrolled diabetes.', '["Ketogenesis","Gluconeogenesis","Glycogenolysis","Lipogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:08.139Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:08.139Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:08.139Z"'::jsonb),
('anki-card-1756968184235-5', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Substance found in raw egg white that binds with biotin preventing its absorption:', 'Avidin', 'Avidin is a glycoprotein found in raw egg white that binds very strongly to biotin (vitamin B7), reducing its intestinal absorption. Regular consumption of large amounts of raw egg white can therefore contribute to biotin deficiency. Cooking denatures avidin, greatly reducing its ability to bind biotin, which is why this problem is primarily associated with raw egg whites.', '["Avidin","Albumin","Vitelline","Ovomucin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:56.388Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:56.388Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:56.388Z"'::jsonb),
('anki-card-1756968231479-6', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Keshan disease is a condition characterized by heart enlargement and is caused by deficiency of what nutrient?', 'Selenium', 'Keshan disease is a form of cardiomyopathy associated with severe selenium deficiency, originally described in areas of China with selenium-poor soil. It can cause cardiac enlargement, impaired cardiac function, and potentially heart failure. Selenium is important for antioxidant defense through selenoproteins such as glutathione peroxidases, which help protect tissues from oxidative damage.', '["Selenium","Zinc","Calcium","Potassium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:04.852Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:04.852Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:04.986Z"'::jsonb),
('anki-card-1756968287658-7', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Foods to avoid when preparing a patient for a test for occult blood in the stool:', 'Meat and leafy vegetables', 'For the traditional guaiac-based fecal occult blood test (gFOBT), patients may be instructed to avoid red meat and certain vegetables, particularly those containing peroxidase activity, because they can produce false-positive results. Examples include some leafy and cruciferous vegetables. This dietary restriction is specific to guaiac-based testing; newer fecal immunochemical tests (FIT) detect human hemoglobin and generally do not require these dietary restrictions.', '["Meat and leafy vegetables","Milk and cheese","Acidic fruits","Excessive fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:36.125Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:59:36.125Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:36.125Z"'::jsonb),
('anki-card-1756968329042-8', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following enhances the absorption of zinc?', 'Glutamate', 'Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.', '["Glutamate","Tryptophan","Acetyl CoA","Thiamin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:42.623Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:42.623Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:42.623Z"'::jsonb),
('anki-card-1756968375740-9', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'A patient on tube feeding has a Diet Rx of 2000 Calories, 2:1 dilution; how much is the total fluid.', '1000 ml', 'In the traditional tube-feeding prescription, a 2:1 dilution means 2 kcal for every 1 mL of formula. 

Therefore: 2,000 kcal ÷ 2 kcal/mL = 1,000 mL/day

Thus, the total volume of tube-feeding formula prescribed is 1,000 mL/day.', '["1500 ml","1250 ml","1000 ml","2250 ml"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:42:21.301Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:42:21.301Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:42:21.301Z"'::jsonb),
('anki-card-1756968443387-10', NULL, 'anki-deck-1783610504561-1790433132438-14b68', '__ and__ are the major intracellular and extracellular cations in the body, respectively.', 'Potassium, sodium', 'Potassium (K⁺) is the major cation inside cells (intracellular fluid), while sodium (Na⁺) is the major cation outside cells (extracellular fluid). Their concentration gradients are maintained largely by the sodium-potassium pump (Na⁺/K⁺-ATPase), which is essential for maintaining cell membrane potential, nerve transmission, and muscle contraction.', '["Potassium, sodium","Potassium, phosphate","Sodium, chloride","Sodium, potassium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:12.160Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:12.160Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:12.160Z"'::jsonb),
('anki-card-1756968484184-11', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The body''s normal pH range is:', '7.35-7.45', 'Normal arterial blood pH is maintained at approximately 7.35–7.45, reflecting a slightly alkaline environment. The body tightly regulates pH through the bicarbonate buffer system, lungs, and kidneys.

Values below 7.35 indicate acidemia, while values above 7.45 indicate alkalemia.', '["7.35-7.45","7.45-7.55","7.25-7.35","7.00-7.45"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:14.911Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:39:14.911Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:15.026Z"'::jsonb),
('anki-card-1756968549614-12', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary antioxidants:
I. Manganese
II. Flavonoids
III. Phenolic compounds', 'All of the above', 'All three can contribute to antioxidant defense. Manganese is an essential mineral that is part of the antioxidant enzyme manganese superoxide dismutase (MnSOD), which helps neutralize superoxide radicals in mitochondria. Flavonoids and phenolic compounds are plant-derived phytochemicals that can have antioxidant activity by scavenging reactive species and influencing antioxidant pathways.', '["I only","I and II only","II and III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:09.028Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:09.028Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:09.177Z"'::jsonb),
('anki-card-1756968603646-13', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'This phytochemical, which is usually found in red wines and peanuts, prevents artery-damaging effects of high fat diets.', 'Resveratrol', 'Resveratrol is a polyphenolic compound found in the skin of red grapes and therefore in red wine, as well as in peanuts and some other plants. It has been studied for potential cardiovascular benefits through antioxidant, anti-inflammatory, and endothelial effects. The original wording that it “prevents” artery damage is too absolute; resveratrol is better described as a phytochemical associated with potentially protective cardiovascular effects.', '["Tannis","Phenols","Resveratrol","Isoflavones"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:40.085Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:40.085Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:40.085Z"'::jsonb),
('anki-card-1756968676056-14', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Prolonged calorie undernutrition can cause a 20-30% decrease in BMR. Habitual high energy intake also decrease BMR.', 'Only statement 1 is correct', 'Prolonged energy restriction can reduce basal metabolic rate (BMR) through metabolic adaptation, including reduced thermogenesis and changes in metabolically active tissues and endocrine function. A decrease of approximately 20–30% has been described in severe or prolonged energy restriction. In contrast, habitual high energy intake does not decrease BMR; increased energy intake may increase diet-induced thermogenesis and total energy expenditure.', '["Only statement 1 is correct","Only statement 2 is correct","Both statement are correct","Both statement are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:25.590Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:25.590Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:25.590Z"'::jsonb),
('anki-card-1756968718290-15', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'When a person is stressed, the secretion of the following hormones is increased EXCEPT:', 'Insulin', 'During physiological stress, the body enters a catabolic, hypermetabolic state designed to ensure adequate fuel availability. Glucagon, cortisol, and catecholamines increase and promote glycogenolysis, gluconeogenesis, lipolysis, and mobilization of energy substrates. 

Insulin secretion is generally suppressed or its action is reduced (insulin resistance) during the stress response, helping maintain elevated blood glucose for tissues with high energy demands.', '["Insulin","Glucagon","Cortisol","Catecholamines"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:00.751Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:00.751Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:00.751Z"'::jsonb),
('anki-card-1756968773103-16', NULL, 'anki-deck-1783610504561-1790433132438-14b68', '__ are responsible for cell-mediated immunity while __ are responsible for humoral immunity.', 'T cells, B cells', 'T lymphocytes are primarily responsible for cell-mediated immunity, including direct killing of infected or abnormal cells and coordination of immune responses. B lymphocytes are responsible for humoral immunity through their differentiation into plasma cells that produce antibodies.', '["T cells, B cells","B cells, T cells","Macrophages, B cells","B cells, macrophages"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:15.100Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:15.100Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:15.100Z"'::jsonb),
('anki-card-1756968840367-17', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Electron-carrier molecules that are used in the electron-transport chain to generate additional ATP are:', 'NADH and FADH₂', 'NADH and FADH₂ are reduced electron carriers that transport high-energy electrons to the electron transport chain (ETC) in the inner mitochondrial membrane. As electrons pass through the ETC, the released energy drives proton pumping, creating a proton gradient that powers ATP synthase to produce ATP through oxidative phosphorylation.', '["Glucose and ketone bodies","Pyruvic acid and lactic acid","Acetyl CoA and amino acids","NADH and FADH₂"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:53:40.741Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:53:40.741Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:53:40.741Z"'::jsonb),
('anki-card-1756968894048-18', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'It is secreted by macrophages to active lymphocytes, suppress appetite and induce malaise and fever.', 'Monokines', 'Monokines are signaling proteins historically used to describe cytokines produced by monocytes and macrophages. Examples include interleukin-1 (IL-1) and tumor necrosis factor (TNF), which can promote immune-cell activation and produce systemic effects such as fever, anorexia, and malaise during inflammation.', '["Monokines","Cytokines","Macrokines","Complements"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:52.886Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:52.886Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:52.886Z"'::jsonb),
('anki-card-1756968937628-19', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'These scavenge and engulf foreign bodies and secrete complements and cytokines.', 'Phagocytes', 'Macrophages are specialized phagocytic cells that engulf and digest pathogens, cellular debris, and other foreign material. They also secrete cytokines that regulate inflammation and immune responses and can produce components of the complement system. Macrophages also function as antigen-presenting cells, helping activate adaptive immune responses.', '["Phagocytes","Macropages","T cells","B cells"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:40.857Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:01:40.857Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:40.857Z"'::jsonb),
('anki-card-1756968997193-20', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'All of the following are possible nutritional effects of intestinal resection among cancer patients EXCEPT:', 'Diabetes mellitus', 'Intestinal resection can lead to several gastrointestinal and nutritional complications depending on the site and extent of resection. These include diarrhea from reduced absorptive capacity, hyperoxaluria particularly after significant ileal resection, and blind loop syndrome when abnormal intestinal anatomy or stasis promotes bacterial overgrowth. Diabetes mellitus, however, is not a typical direct nutritional consequence of intestinal resection.', '["Blind loop syndrome","Hyperoxaluria","Diarrhea","Diabetes mellitus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:40:31.571Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:40:31.571Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:40:31.571Z"'::jsonb),
('anki-card-1756969072722-21', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'A general principle in the prevention and management of an inborn error of metabolism if there is accumulation of precursor to toxic levels:', 'Restrict source of precursor', 'When an inborn error of metabolism causes a precursor to accumulate to toxic concentrations because it cannot be adequately metabolized, a key treatment principle is to restrict the dietary source of that precursor. This reduces substrate entering the defective metabolic pathway and helps prevent further accumulation and toxicity. The specific dietary restriction depends on the metabolic disorder—for example, phenylalanine restriction in phenylketonuria (PKU).', '["Provide replacement","Give increased quantities of the vitamin involved","Avoid exposure","Restrict source of precursor"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:50.009Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:01:50.009Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:50.009Z"'::jsonb),
('anki-card-1756969119237-22', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'How much energy can a 1 liter of 5% dextrose solution provide?', '170 kcal', 'A 5% dextrose solution (D5W) contains 5 g dextrose per 100 mL, or 50 g/L. Dextrose provides approximately 3.4 kcal/g when given intravenously.

Therefore: 50 g × 3.4 kcal/g = 170 kcal

Thus, 1 L of 5% dextrose provides approximately 170 kcal', '["170 kcal","100 kcal","150 kcal","200 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:48.705Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:48.705Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:08:48.705Z"'::jsonb),
('anki-card-1756969218317-23', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Hypoparathyroidism can lead to Chvostek''s and Trousseau''s syndrome. Hyperparathyroidism, on the other hand, can cause osteopenia and osteoporosis.', 'both statements are correct', 'Hypoparathyroidism causes decreased parathyroid hormone (PTH), leading to hypocalcemia, which increases neuromuscular excitability and may produce Chvostek’s and Trousseau’s syndrome. In contrast, prolonged hyperparathyroidism increases PTH-mediated bone resorption, which can reduce bone mineral density and contribute to osteopenia and osteoporosis.', '["only statement 1 is correct","only statement 2 is correct","both statements are correct","both statements are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:48.223Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:48.223Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:48.223Z"'::jsonb),
('anki-card-1756969274695-24', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following are disease of the large intestines?', 'All of the above', 'Diverticular disease, irritable bowel syndrome (IBS), and constipation are all disorders involving the large intestine. Diverticular disease involves the formation and/or inflammation of diverticula, typically in the colon. IBS is a disorder of gut-brain interaction characterized by abdominal pain associated with altered bowel habits, while constipation involves infrequent or difficult bowel movements and commonly reflects impaired colonic transit or evacuation.', '["Diverticular disease","Irritable bowel syndrome","Constipation","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:40.217Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:09:40.217Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:09:40.217Z"'::jsonb),
('anki-card-1756969348926-25', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following are included in the nutrition care guidelines for reducing gastroesophageal reflux disease?', 'All of the above', 'Nutrition management of GERD focuses on reducing factors that can worsen reflux symptoms. Large and high-fat meals can delay gastric emptying and may promote reflux. Alcoholic beverages may aggravate symptoms in some individuals, while acidic or highly spiced foods may worsen discomfort, particularly when esophageal irritation is present. Dietary triggers are individualized, so foods that consistently provoke symptoms should be identified and limited.', '["Avoid large, high fat meals","Avoid acidic and highly spiced foods when inflammation exists","Avoid alcoholic beverages","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:48.752Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:48.752Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:48.752Z"'::jsonb),
('anki-card-1756969435406-26', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which is the most important component of the medical nutrition theraphy for patients with celiac disease?', 'All of the above', 'The cornerstone of medical nutrition therapy for celiac disease is a strict, lifelong gluten-free diet. This requires avoiding gluten-containing grains such as wheat, rye, and barley, carefully checking food labels for gluten-containing ingredients or contamination, and using naturally gluten-free alternatives such as rice, corn, and potatoes. Therefore, all three measures are important components of implementing a gluten-free diet.', '["Omit sources of gluten as wheat, rye and barley","Reading labels to check if the product contains gluten","Substitute wheat flour with potato, rice, corn","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:47:46.872Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:47:46.872Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:47:46.872Z"'::jsonb),
('anki-card-1756969541000-27', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Childhood diarrhea plays a significant role in malnutrition. Infections within the intestine can lead to loss of nutrients, damage to the gut mucosa, and impaired nutrient absorption. The WHO and UNICEF guidelines for managing diarrheal diseases in children include which of the following?', 'All of the above', 'Management of acute diarrhea in children emphasizes preventing and treating dehydration with oral rehydration solution (ORS), continuing breastfeeding and age-appropriate feeding to prevent deterioration of nutritional status, and zinc supplementation to reduce the duration and severity of diarrhea and the risk of subsequent episodes. Therefore, all three are key components of recommended management.', '["Fluid replacement","Continued feeding","Zinc supplementation","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:58.600Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:58.600Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:58.600Z"'::jsonb),
('anki-card-1756969641114-28', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is true about anemia?
I. characterized by reduction in the size and quantity of red blood cells
II. result to decreased capacity of the blood to carry oxygen', 'both statement are correct', 'Anemia is defined by a reduction in hemoglobin concentration, hematocrit, or red blood cell mass below the normal range, resulting in reduced oxygen-carrying capacity of the blood. 

Statement I is incorrect because anemia does not necessarily involve a reduction in RBC size. RBC size may be normal (normocytic), small (microcytic), or large (macrocytic), depending on the underlying cause.', '["only statement 1 is correct","only statement 2 is correct","both statement are correct","both statement are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:57:16.931Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:57:16.931Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:57:16.931Z"'::jsonb),
('anki-card-1756969688195-29', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following proteins have an important role in the immune response?', 'Globulins', 'Globulins, particularly gamma globulins (immunoglobulins/antibodies), play an essential role in the immune response. Antibodies recognize and bind specific foreign antigens and help neutralize pathogens or facilitate their elimination. Other globulin proteins also include components involved in immune and inflammatory processes.', '["Fibrinogen","Lipoproteins","Globulins","Albumin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:07.320Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:07.320Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:07.320Z"'::jsonb),
('anki-card-1756969734576-30', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Anemia that is induced by poor blood clotting:', 'Hemorrhagic anemia', 'Hemorrhagic anemia results from excessive blood loss, which can occur when blood clotting is impaired. Poor clotting allows bleeding to continue or become excessive, leading to loss of red blood cells and hemoglobin. Causes may include coagulation disorders, severe vitamin K deficiency, anticoagulant therapy, or other conditions that impair hemostasis. However, technically, poor clotting is a cause of blood loss rather than the defining cause of hemorrhagic anemia.', '["Microcytic anemia","Pernicious anemia","Hemorrhagic anemia","Hemolytic anemia"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:29.887Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:29.887Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:29.887Z"'::jsonb),
('anki-card-1756969777307-31', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Osteomalacia is result of:', 'all of the above', 'Osteomalacia is defective mineralization of bone in adults, most commonly associated with vitamin D deficiency, which can result from inadequate dietary intake or insufficient sunlight exposure. Parathyroid disorders, particularly conditions causing increased PTH activity, can also contribute to impaired bone mineralization through disturbances in calcium and phosphate metabolism. Therefore, all three factors can contribute to osteomalacia.', '["dietary deficiency","inadequate sunlight exposure","parathyroid problems","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:53.484Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:53.484Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:53.484Z"'::jsonb),
('anki-card-1756969876769-32', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Resting energy expenditure is the amount of energy required for the basal metabolic processes and TEF per unit weight per unit time. It is also called resting metabolic rate.', 'only statement 2 is correct', 'REE and RMR are generally used interchangeably to describe the energy expended by the body at rest to maintain essential physiological functions. However, statement 1 is incorrect because REE does not include the thermic effect of food (TEF). 

TEF is a separate component of total daily energy expenditure. Also, REE/RMR is usually expressed as kcal/day or kcal/kg/day, but “per unit weight per unit time” is not part of its defining concept. Commonly used REE or RMR Equations are Mifflin-St Jeor and Harris-Benedict, while TEF = REE + TEF + Activity Energy Expenditure.', '["only statement 1 is correct","only statement 2 is correct","both statements are correct","both statements are incorrect"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:26.963Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:26.963Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:39:27.083Z"'::jsonb),
('anki-card-1756969922900-33', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which is not predisposing factor of gout:', 'low purine intake', 'Low purine intake is a protective factor, not a predisposing factor. A strict low-purine diet decreases the amount of uric acid produced in the body, lowering the risk of developing gout and reducing the frequency of painful flare-ups.

• High fat diet and starvation: High saturated fat diets impair the intestinal and renal excretion of urate. Starvation triggers the production of ketone bodies (like beta-hydroxybutyrate), which directly compete with uric acid for excretion sites in the kidneys, causing uric acid levels to skyrocket.
• Renal disorders: Roughly 90% of gout cases are caused by the kidneys'' inability to adequately excrete uric acid. Chronic kidney disease or renal insufficiency leads to hyperuricemia and crystal deposition.
• Obesity: Being overweight or obese increases the body''s internal production of uric acid while simultaneously reducing how efficiently the kidneys can filter and excrete it.', '["obesity","renal disorders","high fat diet, starvation","low purine intake"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:00:30.240Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:00:30.240Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:00:30.240Z"'::jsonb),
('anki-card-1756969982713-34', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following are dietary management for Wernicke-Korsakoff syndrome EXCEPT:', 'High energy and protein tube feedings', 'Wernicke-Korsakoff syndrome is associated with severe thiamine (vitamin B1) deficiency, commonly in the setting of chronic alcohol use and malnutrition. Management includes prompt thiamine replacement, adequate hydration and nutritional rehabilitation, and alcohol avoidance. However, high-energy/high-protein tube feeding is not a routine specific dietary management measure; enteral feeding is used when oral intake is inadequate or unsafe, and nutrition should be advanced appropriately rather than automatically prescribing high-energy, high-protein tube feeding.', '["Thiamine supplementation","Adequate hydration","Avoidance of alcohol","High energy and protein tube feedings"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:26.291Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:59:26.291Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:26.291Z"'::jsonb),
('anki-card-1756970100038-35', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary management for Myasthenia Gravis:
I. adjusted food consistency depending on tolerance; nutrient-dense; small frequent feeding
II. avoid foods which contain I-dopa
III. limit dietary protein at breakfast and lunch
IV. low glycemic index treatment', 'I only', 'The major nutrition concerns in myasthenia gravis (MG) are fatigue and weakness of the muscles involved in chewing and swallowing, which can increase the risk of inadequate intake and aspiration. Appropriate management includes modifying food texture/consistency according to swallowing ability, choosing nutrient-dense foods, and using small, frequent meals to reduce fatigue during eating. Avoidance of L-dopa, protein restriction at specific meals, and low-glycemic-index treatment are not standard dietary therapies for MG.', '["I only","I and II only","I, II, III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:48:46.098Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:48:46.098Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:48:46.098Z"'::jsonb),
('anki-card-1756970199338-36', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary recommendation for rheumatic fever:
I. high kcal, high protein, high fluids, low fiber
II.high kcal, high protein, Na and fluid controlled, vitamin and mineral supplements
III. high kcal, high protein, fat-restricted', 'II only', 'During acute rheumatic fever, nutrition should support growth, tissue repair, and recovery, so adequate energy and high-quality protein are important. When there is carditis or heart failure, sodium and fluid may need to be restricted to help control edema and fluid overload. Adequate vitamins and minerals should also be provided. There is no routine indication for a low-fiber diet or for fat restriction in rheumatic fever itself.', '["I only","II only","III only","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:41.412Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:41.412Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:41.412Z"'::jsonb),
('anki-card-1756970304232-37', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'An 84 year-old client complains of chronic constipation. To improve bowel function, what could be a possible intervention?', 'increasing fiber intake', 'Increasing dietary fiber, together with adequate fluid intake and appropriate physical activity, is a first-line approach for managing constipation in older adults when there is no contraindication. Fiber increases stool bulk and can improve bowel regularity. Fiber should be increased gradually, with adequate fluid intake, to minimize bloating and discomfort. For an older adult with chronic constipation, the underlying cause and medications should also be assessed.', '["increasing fiber intake","avoidance of binding foods such as cheese and chocolate","monitoring a balance between activity and rest","daily use of laxatives"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:42:35.158Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:42:35.158Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:42:35.158Z"'::jsonb),
('anki-card-1756970349379-38', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'What is the initial therapy for kwashiorkor?', 'fluid balance restoration', 'In severe acute malnutrition such as kwashiorkor, the initial priority is stabilization, particularly correction of life-threatening problems such as hypoglycemia, hypothermia, dehydration, and electrolyte imbalance. Rehydration must be done cautiously, because children with kwashiorkor may have edema and impaired cardiac/renal function, making them vulnerable to fluid overload. Energy and protein rehabilitation are important, but aggressive feeding or protein replacement should not be the first step during the initial stabilization phase.', '["fat replacement","energy replacement","protein replacement","fluid balance restoration"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:20.220Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:20.220Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:20.220Z"'::jsonb),
('anki-card-1756970423344-39', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following are dietary management for anorexia nervosa, EXCEPT:', 'use of food items that promote early satiety', 'Nutrition therapy for anorexia nervosa aims to restore weight and nutritional status while minimizing factors that interfere with adequate intake. Foods that promote early satiety—such as bulky, high-fiber, or large-volume foods—are generally avoided because they can make it difficult for the patient to consume sufficient energy. Instead, small, frequent, energy-dense meals are useful. Cold or room-temperature foods may be better tolerated in some patients, and limiting caffeine can help reduce appetite suppression and excessive stimulation.', '["use of food items that promote early satiety","small frequent feeding","give cold or room temperature foods","less caffeine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:28.303Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:28.303Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:28.303Z"'::jsonb),
('anki-card-1756970501190-40', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is NOT recommended for patients with gastroesophageal reflux disease (GERD)?', 'Increase the interval between meals by skipping meals', 'GERD management emphasizes meal size, meal timing, body position, and individualized trigger-food avoidance rather than deliberately skipping meals. Large meals, especially near bedtime, can worsen reflux, while remaining upright after eating can reduce symptoms. Patients are encouraged to identify foods and beverages that reliably trigger their symptoms rather than unnecessarily eliminating foods. Skipping meals or intentionally prolonging the interval between meals is not a standard GERD intervention.', '["Avoid large meals, particularly close to bedtime","Remain upright for several hours after meals","Identify and limit foods and beverages that consistently trigger symptoms","Increase the interval between meals by skipping meals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:04.496Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:04.496Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:04.496Z"'::jsonb),
('anki-card-1756970541653-41', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'How much sodium does a 1 tsp of salt contain?', '2000 mg', 'One teaspoon of table salt (sodium chloride) contains approximately 2,300 mg of sodium. However, nutrition teaching materials commonly use the approximation of 2,000 mg sodium per teaspoon of salt, which is the value this question is evidently targeting. Since the exact sodium content varies somewhat with the type and packing of salt, 2,000 mg is an approximation rather than an exact chemical value.', '["2000 mg","2500 mg","3000 mg","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:42.279Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:54:42.279Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:42.279Z"'::jsonb),
('anki-card-1756970584751-42', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary management for hepatic coma:', 'high kcal, high protein', 'Current clinical consensus (from guidelines like AASLD, EASL, ESPEN, and ISHEN) rejects routine protein restriction in hepatic encephalopathy and hepatic coma because protein restriction worsens muscle wasting and catabolism without improving mental status. Patients generally require high caloric intake (about 30–40 kcal/kg/day) and adequate-to-high protein intake (about 1.2–1.5 g/kg/day), often favoring vegetable- or dairy-based proteins or branched-chain amino acids (BCAAs).', '["high kcal, zero to low protein","high kcal, high protein","high kcal, adequate protein","adequate kcal and protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:48:30.625Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:48:30.625Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:48:30.625Z"'::jsonb),
('anki-card-1756970652732-43', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'What vitamin should be provided for the dietary management for sideroblastic anemia that is characterized by pale RBC but with normal hemoglobin levels?', 'Vit B6', 'Vitamin B6 (pyridoxine) is an important cofactor in heme synthesis, particularly for the enzyme ALA synthase. Sideroblastic anemia results from impaired heme synthesis, causing iron to accumulate in erythroblast mitochondria and producing characteristic ring sideroblasts in the bone marrow. 

Some forms, particularly pyridoxine-responsive sideroblastic anemia, can respond to vitamin B6 supplementation. However, sideroblastic anemia has multiple causes, so B6 therapy is not appropriate for every case.', '["Vit B6","Vit B12","Vit K","Vit D"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:57:40.609Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:57:40.609Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:57:40.609Z"'::jsonb)
