INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1756970699163-44', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following are dietary management measures for a patient with an ileostomy, EXCEPT:', 'high fiber', 'After an ileostomy, particularly during the initial postoperative period, a low-residue/low-fiber diet is commonly recommended to reduce stool volume and decrease the risk of obstruction. Adequate fluid and electrolyte intake is also important because ileostomy output can result in substantial fluid and sodium losses. Vitamin B12 supplementation may be necessary when the terminal ileum has been resected because this is the primary site of vitamin B12–intrinsic factor absorption. A low-fat diet may also be useful when fat malabsorption is present.', '["vit B12 supplementation","high fiber","low residue","low fat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:36.152Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:36.152Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:36.152Z"'::jsonb),
('anki-card-1756970756562-45', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The science that deals with the progressive movement and alteration of chemical substances within the body:', 'Pharmacokinetics', 'Pharmacokinetics describes what the body does to a drug, including its absorption, distribution, metabolism, and excretion (ADME). It examines how a drug moves through the body and how its concentration changes over time. 

Pharmacodynamics describes what the drug does to the body, including its mechanisms of action and effects on physiological processes. While Pharmacogenomics studies how an individual''s genetic variation influences drug response, including efficacy and adverse effects.', '["Pharmaconutrition","Pharmacodynamics","Pharmacokinetics","Pharmacogenomics"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:29.268Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:29.268Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:29.268Z"'::jsonb),
('anki-card-1756970787459-46', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which drug may bind with phosphorus and reduce its absorption?', 'antacid', 'Some antacids, particularly those containing aluminum or calcium, can bind phosphate in the gastrointestinal tract and form poorly absorbed complexes, thereby reducing phosphorus absorption. This property is also therapeutically used with aluminum- or calcium-based phosphate binders in patients with chronic kidney disease and hyperphosphatemia.', '["antacid","laxative","digitails","amphetamines"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:19.699Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:19.699Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:19.699Z"'::jsonb),
('anki-card-1756970829740-47', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'May interact with phenobarbital through competitive inhibition:', 'Folate', 'Phenobarbital and other anticonvulsants can interfere with folate metabolism and utilization, and long-term anticonvulsant therapy is associated with reduced folate status. Folate supplementation may therefore be needed in patients receiving prolonged therapy. The interaction is commonly described in nutrition/drug-interaction references as an effect of anticonvulsants on folate metabolism, although the exact pharmacokinetic mechanism is more complex than simple competitive inhibition.', '["Vit K","Folate","B vitamins","Vit C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:57.289Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:57.289Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:57.289Z"'::jsonb),
('anki-card-1756970871271-48', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Foods to be restricted in dumping syndrome:', 'simple carbohydrates', 'In dumping syndrome, especially early dumping, rapid delivery of hyperosmolar food from the stomach into the small intestine can cause gastrointestinal and vasomotor symptoms.

Simple carbohydrates and concentrated sugars should be limited because they rapidly increase intestinal osmotic load and glucose absorption, potentially worsening symptoms.

Meals are generally made small and frequent, with adequate protein and moderate fat, and fluids are often consumed between rather than with meals.', '["simple carbohydrates","complex carbohydrates","protein foods","fat sources"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:53.033Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:59:53.033Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:59:53.033Z"'::jsonb),
('anki-card-1756970946269-49', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following food are allowed for patient with celiac disease, EXCEPT:', 'textured vegetable protein', 'Patients with celiac disease must avoid gluten-containing ingredients and products with significant risk of gluten contamination. Plain yogurt, plain popcorn, and eggs are naturally gluten-free. Textured vegetable protein (TVP) is typically made from soy and is naturally gluten-free, but commercial products may contain wheat-derived ingredients or be produced in facilities where cross-contact with gluten can occur. Therefore, patients with celiac disease should check the label and choose a product specifically identified as gluten-free when appropriate.', '["yogurt","textured vegetable protein","popcorn","egg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:14.353Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:56:14.353Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:14.353Z"'::jsonb),
('anki-card-1756970990349-50', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Post bariatric surgery dietary management:', 'all of the above', 'After bariatric surgery, the diet is advanced gradually according to the type of procedure and the patient''s tolerance. Early postoperative management commonly begins with clear liquids, followed by progressively thicker liquids and/or puréed or soft foods before advancing to regular textures. Small, frequent meals are essential because the reduced gastric capacity limits the amount that can be consumed at one time. The exact duration of each stage varies by surgical program, so “one month” for puréed foods should be regarded as a traditional/generalized schedule rather than a universal requirement.', '["clear liquid for the first day","pureed foods for a month","small feeding","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:20.728Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:20.728Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:08:20.728Z"'::jsonb),
('anki-card-1756971033265-51', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following are management of hyperparathyroidism EXCEPT:', 'high calcium', 'In hyperparathyroidism, excessive calcium intake is generally not recommended because elevated parathyroid hormone (PTH) increases bone resorption and can contribute to hypercalcemia, particularly in primary hyperparathyroidism. 

Management focuses on addressing the underlying cause and maintaining appropriate calcium and phosphorus balance. In the traditional nutrition-management context, phosphate restriction/binders, adequate fluid intake, and an acid-ash diet may be included, particularly in renal/secondary hyperparathyroidism.', '["provide phosphate binders","high fluid","acid ash diet","high calcium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:00.593Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:00.593Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:00.593Z"'::jsonb),
('anki-card-1756971092562-52', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is the primary purpose of nutrition screening?', 'identify clients who need complete nutrition assessment', 'Nutrition screening is a rapid process used to identify individuals who are at risk of malnutrition or who may benefit from further nutrition assessment. It is not intended to diagnose or fully characterize nutritional status. Those identified as being at risk are then referred for a comprehensive nutrition assessment, which provides the information needed for nutrition diagnosis and development of an appropriate nutrition intervention and care plan.', '["define nutritional status","identify clients who need complete nutrition assessment","determine nutrient needs","provide a basis for nutrition care plan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:02.971Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:02.971Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:02.971Z"'::jsonb),
('anki-card-1756971139443-53', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following are the domains of nutrition diagnosis, EXCEPT:', 'Biochemical Nutrition Diagnoses', 'The three domains of nutrition diagnosis in the Nutrition Care Process are Intake, Clinical, and Behavioral-Environmental. A nutrition diagnosis identifies a nutrition-related problem that the RND can address through intervention. While the term “Biochemical Nutrition Diagnoses” is one of the classes under the Clinical Nutrition Diagnoses Domain.', '["Biochemical Nutrition Diagnoses","Intake Nutrition Diagnoses","Clinical Nutrition Diagnoses","Behavioral-environmental Nutrition Diagnoses"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:32.738Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:09:32.738Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:22:46.391Z"'::jsonb),
('anki-card-1756971189224-54', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Dietary management for Guillain-Barré syndrome:', 'high energy and protein tube feedings', 'Guillain-Barré syndrome can cause progressive muscle weakness, dysphagia, and respiratory muscle paralysis. Patients with severe disease may be unable to meet their nutritional needs orally and may require enteral nutrition. Adequate energy and protein are important because of increased metabolic demands and the need to preserve lean body mass during prolonged illness and immobility. Tube feeding is appropriate when oral intake is unsafe or inadequate.', '["thiamine supplementation","adequate hydration","avoidance of alcohol","high energy and protein tube feedings"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:42:16.361Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:42:16.361Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:42:16.361Z"'::jsonb),
('anki-card-1756971267321-55', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Method of delivery of EN when the rate is 300 to 400 ml, 20 to 30 minutes, several times/day via gravity drip or syringe, as determined by medical status, feeding route and volume and nutritional goals.', 'intermittent', 'Intermittent enteral feeding provides formula at scheduled intervals, commonly several times throughout the day. Each feeding may be delivered by gravity or syringe over approximately 20–30 minutes, depending on the patient''s medical status, feeding route, volume tolerance, and nutritional requirements. This approach more closely resembles normal meal patterns than continuous feeding.

Bolus → larger amount, relatively fast
Intermittent → scheduled “meals”
Cyclic → continuous, but only part of the day/night
Continuous → nonstop over an extended period', '["bolus","intermittent","cyclic","continuous"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:57:26.945Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:57:26.945Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:57:26.945Z"'::jsonb),
('anki-card-1756971306536-56', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Enternal Nutrition composed of intact CPF:', 'polymeric', 'Polymeric formulas contain intact, whole macronutrients, including intact proteins, carbohydrates, and fats. They are designed for patients with a functioning gastrointestinal tract who can digest and absorb these nutrients adequately. They are the most commonly used type of standard enteral formula.

Intact CPF = Polymeric;
Broken down = Hydrolyzed;
One nutrient at a time = Modular;
Specific disease = Specialty', '["polymeric","modular","hydrolyzed","specialty"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:50:07.644Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:50:07.644Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:50:07.644Z"'::jsonb),
('anki-card-1756971370333-57', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'A compilation in parental nutrition with symptoms showing failure to grow, dermal problems, and poor immune function.', 'Essential Fatty Acid Deficiency', 'Essential fatty acid deficiency (EFAD) can occur in patients receiving parenteral nutrition when adequate essential fatty acids are not provided, particularly with prolonged fat-free PN. Clinical manifestations include poor growth or growth failure, dermatitis and other skin changes, impaired wound healing, and decreased immune function. Linoleic acid deficiency is particularly important because linoleic acid is an essential omega-6 fatty acid.', '["Essential Fatty Acid Deficiency","Metabolic imbalance","Air embolism","Hemothorax"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:55:06.458Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:55:06.458Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:23:29.466Z"'::jsonb),
('anki-card-1756971418497-58', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'High protein is given to burned patients to:', 'replace losses', 'Severe burns cause a marked hypermetabolic and hypercatabolic response, resulting in substantial protein breakdown and nitrogen losses. Protein requirements are therefore increased to replace these losses, support wound healing, immune function, and maintenance of lean body mass. Protein itself is not primarily given as an energy source; adequate carbohydrate and fat are provided to meet energy needs and help spare protein.', '["provide energy reserves","control water retention","replace losses","meet energy requiements"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:38:30.557Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:38:30.557Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:38:30.670Z"'::jsonb),
('anki-card-1756971480578-59', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Parental nutrition can be discontinued when approximately this percentage of estimated energy needs are being met by oral intake, tube feeding or combination of both.', '0.75', 'PN may generally be discontinued when the patient can consistently obtain approximately 60–75% or more of estimated energy and protein requirements through oral and/or enteral intake, provided that nutritional status is stable and intake is expected to remain adequate. In the context of this question, 75% is the best answer.', '["0.5","0,6","0.75","0.8"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:47:39.663Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:47:39.663Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:47:39.663Z"'::jsonb),
('anki-card-1756971528875-60', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Amount of protein equivalent to a gram of nitrogen.', '6.25g', 'On average, protein contains approximately 16% nitrogen.

Therefore: 1 g nitrogen × 6.25 = 6.25 g protein
The factor 6.25 is derived from: 100 ÷ 16 = 6.25

This conversion is commonly used when calculating nitrogen balance, particularly in clinical nutrition and protein assessment.', '["0.16g","6.25g","54g","10g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:02:28.578Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:02:28.578Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:02:28.578Z"'::jsonb),
('anki-card-1756971569155-61', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Compute the calories provided by a 2-L dialysate solution containing 2.5% dextrose.', '170 kcal', 'A 2.5% dextrose solution contains 2.5 g of dextrose per 100 mL.

For 2 L (2,000 mL):
2.5 g/100 mL × 2,000 mL = 50 g dextrose

Dextrose provides approximately 3.4 kcal/g
50 g × 3.4 kcal/g = 170 kcal

Therefore, the dialysate provides approximately 170 kcal.', '["108 kcal","148 kcal","170 kcal","200 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:26.428Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:26.428Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:26.428Z"'::jsonb),
('anki-card-1756971623603-62', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Energy requirement for patients on pre-dialysis.', '35 kcal/kg BW', 'For adults with chronic kidney disease (CKD) who are not yet on dialysis, an energy intake of approximately 30–35 kcal/kg body weight/day has traditionally been recommended, with the exact target individualized according to age, physical activity, body size, nutritional status, and metabolic needs. Thus, among the choices, 35 kcal/kg BW is the best answer.', '["25 kcal/kg BW","30 kcal/kg BW","35 kcal/kg BW","40 kca/kg BW"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:48:38.683Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:48:38.683Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:48:38.683Z"'::jsonb),
('anki-card-1756971670550-63', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following are characteristics of hypothyroidism EXCEPT:', 'none of the above', 'Cold intolerance, bradycardia, and constipation are all classic manifestations of hypothyroidism. Reduced thyroid hormone slows metabolic activity and affects multiple body systems. Patients may also experience fatigue, weight gain, dry skin, and slowed mental and physical activity.', '["cold intolerance","bradycardia","constipation","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:54.987Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:54.987Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:08:54.987Z"'::jsonb),
('anki-card-1756971724482-64', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Patients under MAOI medication should be put in what type of restricted diet?', 'Tyramine-restricted', 'Monoamine oxidase (MAO) normally helps metabolize tyramine in the gastrointestinal tract. MAO inhibition can allow more tyramine to enter the systemic circulation, where it promotes the release of norepinephrine. Excessive tyramine intake while taking traditional, nonselective MAOIs can therefore cause a potentially severe hypertensive reaction, characterized by a rapid increase in blood pressure and associated headache and other symptoms.', '["Tyramine-restricted","Phenylalanine-restricted","BCAA-restricted","Tyrosine-restricted"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:00:42.874Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:00:42.874Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:00:42.874Z"'::jsonb),
('anki-card-1756971771681-65', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Energy recommedantion for patients with stage 3 CKD', '25-35 kcal/kg', 'The current KDOQI 2020 Nutrition in CKD guideline recommends prescribing 25–35 kcal/kg ideal body weight/day for metabolically stable adults with CKD stages 1–5, including Stage 3 CKD. The exact energy prescription should be individualized according to age, sex, physical activity, body composition, weight goals, CKD stage, and concurrent illness or inflammation.', '["15-20 kcal/kg","25-35 kcal/kg","30-40 kcal/kg","<30 kcal/kg"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:11:36.951Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:11:36.951Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:11:36.951Z"'::jsonb),
('anki-card-1756971816762-66', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following medications affect food intake by altering salivary secretions?', 'Phenobarbital', 'Phenobarbital can cause dry mouth (xerostomia) by reducing salivary secretion. Reduced saliva can affect taste, chewing, swallowing, and overall food intake, potentially contributing to decreased appetite or difficulty eating. This is particularly relevant in nutrition assessment because medication-related oral effects can indirectly compromise dietary intake.', '["Digitalis","Amphetamines","Phenobarbital","Methotrexate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-15T11:16:11.261Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-14T11:16:11.261Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:16:11.261Z"'::jsonb),
('anki-card-1756972022336-67', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following goals below is considered a SMART goal?', 'Client to consume 1 oral nutrition supplement per day, 6 of 7 days per week for 1 month', 'A SMART goal should be Specific, Measurable, Achievable, Relevant, and Time-bound.

• Specific: 1 oral nutrition supplement
• Measurable: 1 supplement/day, on 6 of 7 days
• Achievable: A concrete, realistic behavior target that can be monitored
• Relevant: Directly addresses increasing oral nutritional intake
• Time-bound: Within a defined period of 1 month', '["client to consume 1 oral nutrition supplement for 1 month","client to consume oral nutrition supplements 6 of 7 days per week","Client to consume oral nutrition supplements approximately half of the week","Client to consume 1 oral nutrition supplement per day, 6 of 7 days per week for 1 month"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:02:33.376Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:02:33.376Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:02:33.376Z"'::jsonb),
('anki-card-1756972072199-68', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'In planning energy and nutrient requirements of athletes, the following factors are considered EXCEPT:', 'none of the above', 'All three factors—type of activity, duration, and intensity—are important when estimating an athlete''s energy and nutrient requirements.

• Type of activity determines the predominant energy systems and muscle groups involved. Endurance, strength/power, and intermittent sports have different nutritional demands.
• Duration affects total energy expenditure and the amount of carbohydrate, fluid, and electrolytes that may be required.
• Intensity strongly influences energy expenditure and substrate utilization. Higher-intensity exercise generally increases the reliance on carbohydrate as a fuel source.

Other important considerations include body size/composition, training volume, frequency, age, sex, environmental conditions, and the athlete''s goals.', '["type of activity","duration","intensity","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:40:22.196Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:40:22.196Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:40:22.196Z"'::jsonb),
('anki-card-1756972198260-69', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following statements regarding carbohydrates are true EXCEPT:', 'carbohydrate loading is beneficial for athletes doing all type of exercise, both long-term and short term activities', 'It is a strategy specifically designed to maximize muscle glycogen storage for prolonged, endurance-based activities lasting longer than 90 minutes (such as marathons, triathlons, or long-distance cycling). It provides little to no performance benefit for short-term, high-intensity exercises (like sprinting, powerlifting, or short swimming events) because those activities do not exhaust the body’s baseline glycogen reserves.', '["carbohydrates is metabolized up to 3 times faster than fat which allows for faster muscle contractions","carbohydrate loading is beneficial for athletes doing all type of exercise, both long-term and short term activities","complex carbohydrates provide energy at a slow and gradual pace","simple carbohydrates cause a rapid drop in blood sugar"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:51.108Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T11:09:51.108Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:09:51.108Z"'::jsonb),
('anki-card-1756972238292-70', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'How many grams of addition protein daily is needed for muscle building?', '6-7 grams', 'Skeletal muscle hypertrophy is driven by a positive net protein balance, calculated as muscle protein synthesis (MPS) minus muscle protein breakdown (MPB). Achieving a net positive balance requires an elevation in intracellular amino acid availability—specifically essential amino acids (EAAs) like leucine, which activate the mechanistic target of rapamycin complex 1 (mTORC1) via the Sestrin2-GATOR2 pathway. When calculating the incremental dietary protein necessary to construct new contractile proteins (actin and myosin) alongside structural collagen matrices, clinical estimates establish that accumulating structural muscle tissue demands approximately 6 to 7 grams of net daily protein intake above maintenance requirements during active resistance training protocols.', '["6-7 grams","3 grams","0.8g/kg BW","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:24.107Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:49:24.107Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:24.107Z"'::jsonb),
('anki-card-1756972311306-71', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'This nutrient is supplemented with the idea of helping to build muscle and promote growth. Humans synthesize adequate amounts of this nutrient; its functions are with the central nervous system and cell structure.', 'choline', 'Choline is the best answer. Although choline is not technically classified as a vitamin, it is an essential nutrient because endogenous synthesis is not always sufficient to meet physiological needs.

Choline has several important functions, including:
• Cell membrane structure: Choline is a component of phosphatidylcholine and sphingomyelin, important phospholipids in cell membranes.
• Neurotransmission: Choline is the precursor of acetylcholine, an important neurotransmitter involved in memory, muscle control, and other nervous-system functions.
• Lipid transport and metabolism: Choline is required for the synthesis of phosphatidylcholine and lipoproteins and helps prevent abnormal lipid accumulation in the liver.
• Methyl-group metabolism: Choline can be oxidized to betaine, which participates in methyl-group transfer.

Choline has historically been marketed or supplemented in sports settings with claims related to muscle performance, growth, or fat metabolism, but these claims should not be confused with established physiological functions. Evidence does not demonstrate that routine choline supplementation produces significant muscle-building effects in healthy individuals consuming adequate choline.', '["chromium","choline","riboflavin","pyridoxine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:41:27.015Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:41:27.015Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:41:27.015Z"'::jsonb),
('anki-card-1756972407450-72', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following statements are true about food intolerances, except:', 'it causes anaphylactic life-threatening immune reaction', 'The key distinction between food allergy and food intolerance is the underlying mechanism.

Food allergy involves an immune-mediated response to a food protein. An IgE-mediated food allergy can cause anaphylaxis, which is a potentially life-threatening systemic reaction.

Food intolerance, on the other hand, generally refers to adverse reactions to food that do not involve an immune-mediated mechanism. Examples include lactose intolerance due to lactase deficiency and certain reactions resulting from pharmacologic substances in foods or metabolic disorders.

Therefore, food intolerance does not cause anaphylaxis through an immune-mediated food-allergic reaction.', '["food intolerances are more common than true food allergy","it causes anaphylactic life-threatening immune reaction","PKU and G6PD are examples of food intolerances caused by inborn errors of metabolism","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:24.985Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:56:24.985Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:24.985Z"'::jsonb),
('anki-card-1756972473030-73', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The point at which it is impossible to keep moving; corresponds to the time when the reserves of the glycogen in the muscles are depleted:', 'hitting the wall', '“Hitting the wall” is a term commonly used in endurance sports to describe a sudden and profound feeling of fatigue during prolonged exercise, traditionally associated with substantial depletion of muscle glycogen stores. The athlete may experience extreme fatigue, weakness, difficulty maintaining pace, and a strong perception that continuing the exercise is very difficult. It is better understood as a state of severe fatigue associated with low carbohydrate availability, along with other physiological and psychological factors.', '["carbohydrate loading","muscle fatigue","hitting the wall","muscle cramps"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:44:35.707Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:44:35.707Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:44:35.707Z"'::jsonb),
('anki-card-1756972514211-74', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The following are type of motility disease EXCEPT:', 'achylia gastrica', 'Achylia gastrica is not primarily a motility disorder. It refers to marked or complete absence of gastric hydrochloric acid and pepsin secretion, usually associated with gastric gland atrophy or other disorders affecting gastric secretory function.

In contrast, gastric atony and gastrectasia are associated with impaired gastric motility and gastric emptying. Dyspepsia is primarily a symptom syndrome involving upper gastrointestinal discomfort and can be associated with abnormalities of gastric motility, accommodation, or sensation.', '["dyspepsia","gastric atony","gastrectasia","achylia gastrica"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:45:57.467Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:45:57.467Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:45:57.467Z"'::jsonb),
('anki-card-1756972596740-75', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'A disease characterized by atrophy of the intestines due to lack of peptidase to digest the gliadin factors of gluten.', 'Gluten-sensitive enteropathy', 'Gluten-sensitive enteropathy (celiac disease) is an immune-mediated disorder triggered by exposure to gluten in genetically susceptible individuals. Gluten contains gliadin, which contributes to the immune response that damages the small-intestinal mucosa.

The resulting mucosal injury can produce villous atrophy, crypt hyperplasia, and impaired absorptive capacity, leading to malabsorption of nutrients. The disease involves an inappropriate immune response to gluten peptides, particularly in individuals carrying HLA-DQ2 or HLA-DQ8. 

Tissue transglutaminase modifies gluten peptides, enhancing their presentation to T cells and triggering intestinal inflammation.', '["Gluten-sensitive enteropathy","Enteritis","Tropical sprue","Lymphagiectasis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:49:32.680Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:49:32.680Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:49:32.680Z"'::jsonb),
('anki-card-1756972638122-76', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is true for nutritional management of hemorrhoids?', 'high fiber', 'The primary nutrition goal in hemorrhoids is to prevent constipation and straining during defecation. Increasing dietary fiber helps by increasing stool bulk and, particularly when adequate fluid is consumed, improving stool consistency and promoting easier bowel movements.

Current evidence supports increasing dietary fiber intake as an effective conservative intervention for hemorrhoids. Fiber supplementation has been shown to reduce persistent symptoms and bleeding.

For adults, a practical target is generally around 25–30 g of fiber per day, with gradual increases and adequate fluid intake to minimize bloating or discomfort.', '["high calorie","high fiber","low protein","low residue"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:02:42.206Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:02:42.206Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:02:42.206Z"'::jsonb),
('anki-card-1756972693802-77', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The nutrition prescription is included in which step of the NCP?', 'Nutrition intervention', 'The nutrition prescription is part of the Nutrition Intervention step of the Nutrition Care Process. It translates the nutrition diagnosis and assessment findings into a specific plan for addressing the identified nutrition problem.

The nutrition prescription describes the recommended amount and/or type of food, nutrients, or nutrition-related intervention appropriate for the patient. It may include parameters such as energy, protein, fluid, carbohydrate, fat, sodium, or other nutrient requirements, depending on the patient''s condition and nutrition diagnosis. The prescription is developed during intervention, after the nutrition problem has been identified through assessment and diagnosis.', '["Nutrition assessment","Nutrition diagnosis","Nutrition intervention","Nutrition monitoring and evaluation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:00:50.762Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:00:50.762Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:00:50.762Z"'::jsonb),
('anki-card-1756972734067-78', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'A carbohydrate-rich diet may require more of which of the following vitamins?', 'thiamin', 'Thiamin (vitamin B1) is particularly important in carbohydrate metabolism. Its active form, thiamin pyrophosphate (TPP), functions as a coenzyme for several enzymes involved in glucose oxidation, including:

• Pyruvate dehydrogenase
• α-Ketoglutarate dehydrogenase
• Transketolase

Because carbohydrate metabolism increases when carbohydrate intake and utilization are high, an inadequate thiamin supply can become more clinically relevant. Thus, a carbohydrate-rich diet may increase the need for thiamin, particularly when carbohydrate intake is very high and the diet is otherwise nutrient-poor.', '["riboflavin","thiamin","vitamin c","niacin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:20.414Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:54:20.414Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:20.414Z"'::jsonb),
('anki-card-1756972784565-79', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'An athlete who consumes a high-protein diet would have an increased need of which of the following vitamins?', 'vit b6', 'Vitamin B6 is closely involved in amino acid and protein metabolism. Its active coenzyme form, pyridoxal 5′-phosphate (PLP), is required for numerous reactions involving amino acids, including transamination, decarboxylation, and other amino acid transformations.

Therefore, when protein intake and amino acid metabolism increase, the need for vitamin B6 may also increase. This is the classic nutrition relationship tested by this question:

Higher protein intake → increased amino acid metabolism → greater need for vitamin B6.

However, an important modern nuance is that athletes do not automatically require B6 supplementation simply because they consume a high-protein diet. Adequate dietary intake generally meets requirements, and supplementation should not be routinely recommended without evidence of inadequate intake or deficiency.', '["niacin","vit b12","vit b6","vit c"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:56:37.386Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:56:37.386Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:56:37.386Z"'::jsonb),
('anki-card-1756972953741-80', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following statements about folate is/are true?', 'all of the above', 'All three statements describe established roles of folate (vitamin B9), although B requires an important modern clarification regarding cardiovascular disease.

A. Neural tube defects: Folate is essential for DNA and nucleotide synthesis and cell division. Adequate folate before conception and during early pregnancy substantially reduces the risk of neural tube defects (NTDs). This is why folic acid supplementation is recommended for women who could become pregnant.

B. Homocysteine: Folate participates in the remethylation of homocysteine to methionine, a reaction that also requires vitamin B12. Folate deficiency can therefore contribute to elevated plasma homocysteine. Elevated homocysteine is associated epidemiologically with cardiovascular disease; however, lowering homocysteine with folic acid supplementation has not consistently been shown to reduce coronary heart disease events. Thus, the statement is correct regarding the biochemical relationship and association, but it should not be interpreted as proof that folic acid supplementation prevents CHD.

C. Folate and vitamin B12: Folate and vitamin B12 work together in one-carbon metabolism and DNA synthesis. Deficiency of either nutrient can impair DNA synthesis and produce megaloblastic/macrocytic anemia.', '["Folic acid supplementation is recommended for women of childbearing potential because it is necessary for nucleic acid synthesis and may help prevent neural tube defects.","Folate influences plasma homocysteine concentrations, and elevated homocysteine is associated with increased cardiovascular disease risk.","Folate works together with vitamin B12 (cyanocobalamin) in pathways important for preventing megaloblastic anemia.","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:43:46.361Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:43:46.361Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:43:46.361Z"'::jsonb),
('anki-card-1756972997906-81', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following vitamins is considered anti-infective vitamin?', 'Vit A', 'Vitamin A has historically been called the “anti-infective vitamin” because of its important role in maintaining epithelial and mucosal barriers and supporting both innate and adaptive immune function.

Vitamin A helps maintain the integrity and function of epithelial tissues lining the respiratory, gastrointestinal, and genitourinary tracts, which serve as important physical barriers against pathogens. It also contributes to normal immune-cell function and antibody responses.

Vitamin A deficiency can impair immune defenses and increase susceptibility to certain infections, particularly in children. Conversely, vitamin A supplementation has demonstrated benefits in specific populations with deficiency or certain infectious diseases, but routine high-dose supplementation is not recommended for everyone.', '["Vit A","Vit D","Vit E","Vit K"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:47:33.454Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:47:33.454Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:47:33.454Z"'::jsonb),
('anki-card-1756973153099-82', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'During prolonged, high intensity physical activity, the muscle''s consumption of oxygen increases tenfold or more, enhancing the production of damaging free radicals in the body. Which of the following vitamins-mineral combinations would be potent on defending the cell membranes against oxidative stress?', 'Vitamin E, retinol, ascorbate, and selenium', 'This is the best answer because it combines several nutrients with established antioxidant roles:

• Vitamin E (tocopherol) is the major lipid-soluble antioxidant and is particularly important in protecting cell membranes from lipid peroxidation.
• Vitamin C (ascorbate) is a major water-soluble antioxidant and can help regenerate oxidized vitamin E.
• Vitamin A/retinoids have antioxidant-related functions, although the antioxidant activity of vitamin A is less central than that of vitamin E.
• Selenium is an essential component of glutathione peroxidases, antioxidant enzymes that help reduce hydrogen peroxide and lipid hydroperoxides.

Thus, among the choices, this provides the strongest combination of antioxidant nutrients, particularly for membrane protection.', '["Vitamin E, retinol, ascorbate, and selenium","Tocopherol, thiamin, ascorbate, and iron","Ascorbate, retinol, pyridoxal, and selenium","Vitamin C, Vitamin A, Vitamin B6, and zinc"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:59:14.245Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T10:59:14.245Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:32:34.946Z"'::jsonb),
('anki-card-1756973257093-83', NULL, 'anki-deck-1783610504561-1790433132438-14b68', '___ is a systematic head-to-toe examination of patient''s physical appearance and function to help determine nutrtional status by uncovering any signs of malnutrition, nutrient deficiencies or nutrient toxicities.', 'nutrition focused physical assessment', 'Nutrition-Focused Physical Assessment (NFPA) is a systematic physical examination performed by a nutrition professional to identify physical signs and symptoms associated with malnutrition, nutrient deficiencies, excesses, and other nutrition-related conditions.

It is an important component of the Nutrition Assessment step of the Nutrition Care Process. The examination may include observation, palpation, and assessment of areas such as:
• Muscle stores — e.g., temples, clavicles, shoulders, scapulae, interosseous muscles
• Subcutaneous fat stores — e.g., orbital region, triceps, ribs
• Skin, hair, and nails
• Eyes and oral cavity
• Edema and fluid accumulation
• Functional findings, when appropriate

Importantly, NFPA is not used in isolation to diagnose malnutrition. It is integrated with dietary history, anthropometric data, biochemical/medical information, and other relevant findings.', '["body composition analyzer","indirect calorimter","CT-scan with contrast","nutrition focused physical assessment"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:55:59.950Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:55:59.950Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:55:59.950Z"'::jsonb),
('anki-card-1756973304608-84', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Route of access for patients with normal GI function and intact gag reflex.', 'nasogastric tube', 'A nasogastric (NG) tube is an appropriate route for short-term enteral nutrition when the GI tract is functional and the patient has an intact gag/cough reflex and can protect the airway.

An NG tube is inserted through the nose into the stomach, allowing delivery of enteral formula directly into the stomach.

In general, short-term enteral feeding is commonly delivered through a nasogastric or nasoenteric tube, whereas longer-term feeding may require an enterostomy such as a gastrostomy or jejunostomy.', '["enterostomy","multiple lumen tube","gastrotomy tube","nasogastric tube"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:09:23.776Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:09:23.776Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:09:23.776Z"'::jsonb),
('anki-card-1756973351785-85', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'All are consequences of hospital malnutrition except:', 'decrease mortality and morbidity', 'Hospital malnutrition is associated with increased, not decreased, morbidity and mortality.

Disease-related malnutrition can impair immune function, reduce muscle mass and strength, delay tissue repair, and compromise recovery. Consequently, malnourished hospitalized patients are at greater risk of complications, infections, prolonged hospitalization, and poorer clinical outcomes.', '["decrease mortality and morbidity","poor wound healing","higher infection rates","longer hospital and ventilator days"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:07:08.788Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:07:08.788Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:07:08.788Z"'::jsonb),
('anki-card-1756973438869-86', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'The process of providing individualized professional guidance to assisst persons in adjusting their daily food consumption to meet their health needs.', 'Nutrition Counseling', 'Nutrition counseling is the process of providing individualized guidance and support to help a person modify food choices, eating behaviors, and dietary practices to meet specific health or nutrition needs.

It is an important component of nutrition care and involves communication between the nutrition professional and the client. Counseling may address:

• Food selection and meal planning
• Eating patterns and behaviors
• Portion sizes
• Dietary modifications appropriate to health conditions
• Barriers to dietary change
• Strategies for achieving and maintaining behavior change

The emphasis is on individualized guidance and behavior change, rather than simply giving a standardized diet prescription.', '["Nutrition Counseling","Medical Nutrition Therapy","Mechanical Problems","Nutrition Diagnosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:29.530Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:29.530Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:32:59.027Z"'::jsonb),
('anki-card-1756973485549-87', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Designed for patients with impaired ability to ingest nutrient orally but has functioning GIT.', 'enteral nutrition', 'Enteral nutrition (EN) is the preferred method of providing nutrition when the gastrointestinal tract is functional but oral intake is inadequate, unsafe, or impossible.

EN delivers nutrients directly into the gastrointestinal tract, usually through a feeding tube such as a nasogastric, nasoenteric, gastrostomy, or jejunostomy tube.

The principle commonly emphasized in clinical nutrition is: “If the gut works, use it.”

Using the GI tract helps maintain gut integrity and function and is generally preferred over parenteral nutrition when feasible.', '["enteral nutrition","parental nutrition","a and b","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:41:44.591Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:41:44.591Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:41:44.591Z"'::jsonb),
('anki-card-1756973553878-88', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Mr. JGH underwent a gastrectomy and is now on a clear liquid diet. Which of the following beverages will mostly cause dumping syndrome?', '12 oz apple juice', 'Apple juice is the best answer because it provides a relatively high amount of rapidly absorbable carbohydrate (simple sugars) in liquid form. After gastrectomy, the normal reservoir function of the stomach is reduced, allowing hyperosmolar contents, particularly liquids containing concentrated sugars, to enter the small intestine rapidly.

This can contribute to early dumping syndrome, which may produce abdominal cramping, bloating, nausea, diarrhea, tachycardia, flushing, and dizziness shortly after eating or drinking.

The large volume (12 oz ≈ 355 mL) also makes the apple juice a more likely trigger because rapid ingestion of a substantial volume of liquid can promote rapid gastric/small-intestinal delivery.', '["2 cups strained chicken broth","12 oz apple juice","1 cup unsweetened jelly","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:38:15.217Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:38:15.217Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:38:15.217Z"'::jsonb),
('anki-card-1756973607393-89', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'A patient diagnosed with Crohn''s disease and compromised distal ileum will benefit from which diet?', 'Vitamin B12 supplementation', 'The terminal (distal) ileum is the primary site for absorption of vitamin B12–intrinsic factor complexes. Crohn’s disease involving or requiring resection of the terminal ileum can therefore impair vitamin B12 absorption and increase the risk of vitamin B12 deficiency.

Depending on the extent of ileal disease or resection, patients may require vitamin B12 supplementation, sometimes by a parenteral route when adequate oral absorption cannot be relied upon.', '["Vitamin B12 supplementation","Low-calorie diet","Low-protein diet","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:39:21.175Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:39:21.175Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:33:24.152Z"'::jsonb),
('anki-card-1756973664559-90', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following characterized cholelithiasis?', 'Hardened deposits in the gallbladder', 'Cholelithiasis refers to the presence of gallstones (calculi) in the gallbladder. Gallstones form when components of bile, the most commonly cholesterol, but also bilirubin and calcium salts, precipitate and form solid particles.

Gallstones may be asymptomatic or may cause biliary colic when they obstruct the cystic duct. If obstruction occurs elsewhere in the biliary tree, complications can include acute cholecystitis, choledocholithiasis, cholangitis, or gallstone pancreatitis.

The two major types of gallstones are:
• Cholesterol stones — predominant in many populations.
• Pigment stones — composed primarily of calcium bilirubinate and associated with conditions such as chronic hemolysis or biliary infection, depending on the type.', '["Hardened deposits in the pancreas","Hardened deposits in the gallbladder","Scarring of the kidneys","Scarring of the lungs"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:30.157Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:54:30.157Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:30.157Z"'::jsonb),
('anki-card-1756973773337-91', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Mrs. Lobardo will be given an enteral formula with 1.5 kcal/ml at 60 ml x 16 hours. It contains 55 grams of protein per liter. How much kcal and grams of protein will be provided to the patient?', '1440 kcal and 53 g protein', 'Step 1: Determine total volume administered: 60 mL/hour × 16 hours = 960 mL

Step 2: Calculate energy: 960 mL × 1.5 kcal/mL = 1,440 kcal

Step 3: Calculate protein: The formula contains 55 g protein/L.
960 mL = 0.96 L
0.96 L × 55 g/L = 52.8 g ≈ 53 g protein

Therefore: 1,440 kcal + 53 g protein', '["1690 kcal and 58 g protein","1640 kcal and 58 g protein","1580 kcal and 53 g protein","1440 kcal and 53 g protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:10:42.987Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:10:42.987Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:10:42.987Z"'::jsonb),
('anki-card-1756973825883-92', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'A patient is receiving 250 mls of a 20% AA solution and 250 mls of 10% lipid emulsion. What is the total kcal provided?', '475 kcal', 'For PN calculations, the conventional values are:

Amino acids: 4 kcal/g
Dextrose: 3.4 kcal/g
IV lipid emulsion: 10 kcal/g

Protein: 20% AA, 250 mL:
250 mL × 20 g/100 mL = 50 g AA => 50 g × 4 kcal/g = 200 kcal

Lipids: 10% lipid emulsion, 250 mL:
250 mL × 10 g/100 mL = 25 g lipid => 25 g × 10 kcal/g = 250 kcal

Total = 200 + 250 = 450 kcal', '["450 kcal","475 kcal","550 kcal","555 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:54:09.242Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:54:09.242Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:54:09.242Z"'::jsonb),
('anki-card-1756974003292-93', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which among the branched chain amino acid is/are the most important neurotoxic metabolite in MSUD? Which among the branched chain acid is/are required to be supplemented to control the plasma level of the said toxic.', 'leucine;  isoleucine and valine', 'In MSUD, there is deficient activity of the branched-chain α-ketoacid dehydrogenase (BCKDH) complex, which normally metabolizes the branched-chain amino acids (BCAAs):
• Leucine
• Isoleucine
• Valine

Consequently, both the BCAAs and their corresponding branched-chain α-ketoacids accumulate.

Among the three BCAAs, leucine is particularly important in the neurologic toxicity of MSUD. Markedly elevated plasma leucine is associated with cerebral edema and neurological manifestations, including lethargy, abnormal tone, seizures, and encephalopathy.

During nutritional management, dietary leucine is restricted, while isoleucine and valine are supplemented as needed. Providing these two BCAAs helps maintain adequate protein synthesis and prevents their concentrations from falling excessively while leucine intake is restricted. The amounts are carefully monitored according to plasma amino-acid concentrations.

Therefore:
Toxic metabolite of greatest concern → leucine
Supplemented BCAAs → isoleucine + valine', '["isoleucine; leucine and valine","valine; isoleucine and leucine","leucine;  isoleucine and valine","leucine and isoleucine; valine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:31.653Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-14T11:01:31.653Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:31.653Z"'::jsonb)
