INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1756974084821-94', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Compute for the total calories absorbed from 4 exchanges 2 L of 2.5% dialysate solution on a patient undergoing peritoneal dialysis assuming 60% absorption rate. Note: 1 gram dextrose =  3.4 kcal.', '408 kcal', 'Step 1: Calculate the amount of dextrose per 2-L exchange
A 2.5% dextrose solution contains: 2.5 g/100 mL
Since 2 L = 2,000 mL: 2000mL * (2.5 g ÷ 100 mL) = 50 g dextrose

Step 2: Calculate calories per exchange: 50 g * 3.4 kcal/g = 170 kcal

Step 3: Calculate calories from four exchanges: 170 * 4 = 680 kcal

Step 4: Apply the 60% absorption rate: 680 kcal * 0.60 = 408 kcal

Therefore, the patient absorbs approximately 408 kcal/day from the dialysate dextrose.', '["50 kcal","30 kcal","102 kcal","408 kcal"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T10:58:46.799Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T10:58:46.799Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T10:58:46.799Z"'::jsonb),
('anki-card-1756974161017-95', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'How many grams of protein would be a 50kg, metabolically stable, non-dialyzed, adult male patient diagnosed with CKD stage 4 sec to diabetic kidney disease be needing per day?', '40g', 'For a metabolically stable adult with CKD stages 3–5 who is not on dialysis, current KDIGO guidance suggests a protein intake of approximately 0.8 g/kg body weight/day.

For a 50-kg patient: 50 kg * 0.8 g/kg/day = 40 g/day

Therefore, the best answer is 40 g protein/day. The key information in the question is:

CKD Stage 4 → advanced CKD
Not on dialysis → protein needs are not increased for dialysis-related losses
Metabolically stable → the standard CKD protein recommendation applies
50 kg → use body weight for the calculation', '["15g","30g","40g","50g"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:01:15.975Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:01:15.975Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:01:15.975Z"'::jsonb),
('anki-card-1756974219382-96', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Patients with diabtes mellitus who are on long term metformin therpay are at risk what nutrient deficiency?', 'Vit B12', 'Vitamin B12 deficiency is a recognized potential adverse effect of long-term metformin therapy. Metformin can interfere with vitamin B12 absorption, and the risk generally increases with higher doses and longer duration of treatment.

The mechanism is multifactorial and may involve altered intestinal handling of the intrinsic factor–B12 complex, among other effects.

B12 deficiency is clinically important because it can cause:
• Megaloblastic anemia
• Peripheral neuropathy
• Paresthesia and other neurological manifestations
• Cognitive or neuropsychiatric changes in more severe cases

This is particularly relevant in patients with diabetes because B12 deficiency–related neuropathy can potentially be confused with or add to diabetic peripheral neuropathy.

Current diabetes guidance recommends considering periodic assessment of vitamin B12 status in patients taking metformin, particularly when treatment is prolonged or when anemia or neuropathy develops.', '["Vit B1","Vit B3","Vit B9","Vit B12"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:15:39.677Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:15:39.677Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:15:39.677Z"'::jsonb),
('anki-card-1756974272380-97', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'This food label claim refers to a product containing 35 mg of sodium of per serving.', 'Very low in sodium', 'Under U.S. FDA food-labeling definitions, a food may be labeled “very low sodium” when it contains 35 mg or less of sodium per reference amount customarily consumed (RACC) or per labeled serving, depending on the applicable labeling provision.
Therefore, a product containing 35 mg sodium per serving meets the criterion for “very low sodium.”

For comparison, the commonly tested FDA definitions are:
• Claim - Sodium criterion
• Sodium-free / salt-free - <5 mg/serving
• Very low sodium - ≤35 mg/serving
• Low sodium - ≤140 mg/serving
• Reduced sodium - At least 25% less sodium than the reference food', '["No salt added","Sodium-free","Very low in sodium","Reduced sodium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-17T11:08:06.219Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-14T11:08:06.219Z"'::jsonb, '"2026-09-26T14:32:29.748Z"'::jsonb, '"2026-10-14T11:08:06.219Z"'::jsonb),
('card-1791976728420-bj7mw', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following is/are considered severe weight loss? 
I. 5% over a month 
II. 7.5% over 3 months 
III. >5% over 1 month 
IV. >7.5% over 3 months', 'III and IV only', 'In the commonly used ASPEN/Academy malnutrition assessment framework, weight loss thresholds are interpreted according to both magnitude and time period. For the time frames given, >5% in 1 month and >7.5% in 3 months represent significant/severe weight loss thresholds. The key distinction is the “>” (greater than) sign: exactly 5% or exactly 7.5% does not meet a criterion stated as greater than those values.', '["III and IV only","I and II only","All of the above","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, '', '{"dueDate":"2026-10-15T11:34:05.603Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T11:34:05.603Z"'::jsonb, '"2026-10-14T11:18:49.695Z"'::jsonb, '"2026-10-14T11:34:05.732Z"'::jsonb),
('card-1791976790885-dogti', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following dietary patterns is LEAST associated with an increased risk of gout?', 'A diet emphasizing low-fat dairy products and adequate hydration', 'Low-fat dairy intake is generally associated with a lower risk of gout, while adequate hydration supports renal uric acid excretion. In contrast, purine-rich foods, sugar-sweetened beverages (particularly those high in fructose), and fasting/starvation can contribute to hyperuricemia or trigger gout attacks.', '["A diet emphasizing low-fat dairy products and adequate hydration","Frequent consumption of organ meats and shellfish","Regular intake of sugar-sweetened beverages","Prolonged fasting or severe calorie restriction"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, '', '{"dueDate":"2026-10-15T11:34:12.601Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T11:34:12.601Z"'::jsonb, '"2026-10-14T11:19:51.681Z"'::jsonb, '"2026-10-14T11:34:12.720Z"'::jsonb),
('card-1791976862740-w4i69', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'An eating disorder characterized by recurrent episodes of eating excessively followed by compensatory purging, such as self-induced vomiting, is:', 'Bulimia nervosa', 'Bulimia nervosa is characterized by recurrent binge-eating episodes accompanied by inappropriate compensatory behaviors, such as self-induced vomiting, misuse of laxatives or diuretics, fasting, or excessive exercise. Unlike anorexia nervosa, body weight in individuals with bulimia nervosa is often within or above the normal range, although this is not required for diagnosis.', '["Bulimia nervosa","Anorexia nervosa","Binge-eating type","Restricting type"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, '', '{"dueDate":"2026-10-15T11:34:48.261Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T11:34:48.261Z"'::jsonb, '"2026-10-14T11:21:04.325Z"'::jsonb, '"2026-10-14T11:34:48.336Z"'::jsonb),
('card-1791976910130-yc86s', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'In patients with cirrhosis, which dietary strategy is most appropriate to help prevent protein-energy malnutrition?', 'Adequate energy and protein intake with small, frequent meals', 'Patients with cirrhosis are at high risk of protein-energy malnutrition and muscle wasting. Providing adequate energy and protein helps maintain lean body mass and prevent catabolism. Small, frequent meals and a late-evening snack can help reduce prolonged fasting and provide a more continuous supply of energy, particularly because glycogen stores may be reduced in advanced liver disease.', '["Adequate energy and protein intake with small, frequent meals","Prolonged fasting between meals","Routine severe restriction of dietary protein","Elimination of carbohydrate-rich foods"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, '', '{"dueDate":"2026-10-15T11:38:56.964Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T11:38:56.964Z"'::jsonb, '"2026-10-14T11:21:51.119Z"'::jsonb, '"2026-10-14T11:38:57.039Z"'::jsonb),
('card-1791977336600-y7hgk', NULL, 'anki-deck-1783610504561-1790433132438-14b68', 'Which of the following protein intakes is generally appropriate for a resistance-trained individual seeking to support muscle hypertrophy?', 'Approximately 1.4–2.0 g/kg BW/day', 'For individuals who participate in resistance training and are seeking to increase or maintain muscle mass, protein requirements are generally higher than the RDA for sedentary adults. The International Society of Sports Nutrition (ISSN) recommends approximately 1.4–2.0 g protein/kg body weight/day for most exercising individuals.

Protein intake should also be distributed throughout the day rather than consumed in one large dose. Adequate total energy intake and resistance training are equally important because protein alone cannot maximize muscle hypertrophy.

Research also suggests that the increase in muscle-building benefit tends to plateau around ~1.6 g/kg/day for many resistance-trained individuals, although some individuals may benefit from intakes toward the upper end of the range depending on training volume, energy restriction, age, and other factors.', '["Approximately 1.4–2.0 g/kg BW/day","Approximately 0.6–0.8 g/kg BW/day","Approximately 3.0–4.0 g/kg BW/day","Protein intake does not need to increase with resistance training"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, '', '{"dueDate":"2026-10-15T11:39:01.662Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-14T11:39:01.662Z"'::jsonb, '"2026-10-14T11:28:58.035Z"'::jsonb, '"2026-10-14T11:39:01.739Z"'::jsonb),
('anki-card-1757926265045-0', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Mineral which activates arginase which is needed for urea formation', 'manganese', 'Manganese is an essential trace mineral that serves as an essential cofactor activating arginase, the final enzyme in the urea cycle responsible for converting arginine into urea and ornithine for nitrogen excretion.

• Cobalt: A core structural component of Vitamin B12 (cobalamin), not the specific activator for arginase.
• Zinc: Acts as a cofactor for numerous enzymes like carbonic anhydrase and alcohol dehydrogenase, but not arginase.
• Chromium: Enhances insulin action as part of the glucose tolerance factor.', '["manganese","cobalt","zinc","chromium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:03.151Z"'::jsonb),
('anki-card-1757926280992-1', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Mineral which is a part of Glucose Tolerance Factor (GTF) which potentiates the action of insulin?', 'chromium', 'Chromium is an essential trace element that functions as an integral component of the Glucose Tolerance Factor (GTF), which potentiates and amplifies the physiological action of insulin on cell membrane receptors.

• Manganese: Activates enzymes like arginase and glycosyltransferases, but does not form GTF.
• Cobalt: Functions as part of the cobalamin structure, not glucose tolerance factor complexes.
• Zinc: Important for immune function and protein synthesis, distinct from GTF chromium.', '["manganese","cobalt","zinc","chromium"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:08.445Z"'::jsonb),
('anki-card-1757926358273-2', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Hormone released by the thyroid gland to regulate calcium homeostasis', 'Calcitonin', 'Calcitonin is a peptide hormone synthesized and secreted by the parafollicular C-cells of the thyroid gland, acting to lower blood calcium levels by inhibiting osteoclast bone resorption.

• T3 (Triiodothyronine): A primary thyroid hormone regulating basal metabolic rate and cellular oxygen consumption.
• PTH (Parathyroid hormone): Secreted by the parathyroid glands to raise blood calcium levels (the functional antagonist to calcitonin).
• T4 (Thyroxine): The main circulating prohormone secreted by the thyroid gland, converted peripherally to active T3.', '["T3","PTH","T4","Calcitonin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:13.761Z"'::jsonb),
('anki-card-1757926376388-3', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The following are Ketogenic Amino Acids except:', 'None of the above', 'Purely ketogenic amino acids are those that degrade into acetyl-CoA or acetoacetate without yielding precursors for gluconeogenesis. Both Leucine and Lysine are classic examples of strictly ketogenic amino acids, making "None of the above" correct since the listed options are indeed ketogenic.

• Leucine: A strictly ketogenic amino acid that breaks down into acetyl-CoA and acetoacetate.
• Lysine: Another strictly ketogenic amino acid yielding acetyl-CoA.', '["Leucine","Lysine","None of the above","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:22.439Z"'::jsonb),
('anki-card-1757926397904-4', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The ff. are glucogenic amino acids :', 'All of the above', 'Glucogenic amino acids can be converted into glucose via gluconeogenesis. Valine (glucogenic), Isoleucine (both glucogenic and ketogenic), and Threonine (glucogenic) all contribute carbon skeletons to metabolic intermediates like pyruvate or oxaloacetate.

• Valine: A purely glucogenic amino acid yielding propionyl-CoA.
• Isoleucine: A mixed glucogenic and ketogenic amino acid that contributes intermediates to glucose synthesis.
• Threonine: A glucogenic amino acid broken down into succinyl-CoA or pyruvate.', '["Valine","Isoleucine","Threonine","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:28.906Z"'::jsonb),
('anki-card-1757926417935-5', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Hormones which promote satiety except________', 'Ghrelin', 'Ghrelin is a peptide hormone produced primarily by the stomach ("the hunger hormone") that stimulates appetite and promotes food intake, whereas the other options promote satiety or suppress appetite.

• Leptin: A hormone secreted by adipose tissue that signals satiety and suppresses hunger.
• Glucagon-like peptide-1 (GLP-1): An enteric incretin hormone that enhances insulin secretion and promotes satiety.', '["Ghrelin","Leptin","Glucagon 1- peptid","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:37.652Z"'::jsonb),
('anki-card-1757926435218-6', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Hormones which promote glycogenolysis in the liver:', 'Glucagon', 'Glucagon is a pancreatic hormone released during fasting or hypoglycemia that stimulates hepatic glycogenolysis (breakdown of stored glycogen into glucose) and gluconeogenesis to maintain blood glucose levels.

• Thyroxine: Regulates long-term basal metabolic rate rather than acute short-term glycogenolysis.
• Epinephrine: Also promotes glycogenolysis (primarily in muscle and liver during stress), but glucagon is the primary classic metabolic hormone for hepatic glycogen breakdown.', '["Glucagon","thyroxine","Epinephrine","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:43.230Z"'::jsonb),
('anki-card-1757926454683-7', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Energy requiring process that transports nutrients from an area of lower concentration to a higher one', 'Active transport', 'Active transport is an energy-requiring cellular process (utilizing ATP) that moves nutrient molecules across a cell membrane against their electrochemical concentration gradient (from an area of lower concentration to a higher concentration).

• Passive diffusion: Movement of molecules down a concentration gradient without energy expenditure.
• Endocytosis: A cellular engulfment process for large macromolecules, distinct from transmembrane carrier transport.
• Carrier mediated: Can occur via facilitated diffusion (passive) or active transport; active transport specifically denotes the energy-driven uphill movement.', '["Passive diffusion","Active transport","Endocytosis","Carrier mediated"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:48.776Z"'::jsonb),
('anki-card-1757926472800-8', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Proteins are absorbed using this process:', 'Active transport', 'The absorption of small peptide fragments and amino acid breakdown products across the intestinal enterocyte brush border primarily utilizes sodium-dependent active transport mechanisms requiring cellular energy.

• Passive diffusion: Used for small lipid-soluble molecules, not primary protein breakdown products.
• Endocytosis: Used for intact proteins in neonates, but insignificant for adult protein absorption.
• Osmosis: The passive net movement of water molecules across a selectively permeable membrane.', '["Passive diffusion","Active transport","Endocytosis","Osmosis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:55:53.571Z"'::jsonb),
('anki-card-1757926489450-9', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Number of ATP produced by each NADH in malate aspartate shuttle:', '3', 'The malate-aspartate shuttle transfers reducing equivalents (NADH) from the cytosol into the mitochondrial matrix. Because it utilizes the malate dehydrogenase system, each cytoplasmic NADH is coupled with the production of approximately 3 ATP equivalents in the electron transport chain.

• 2: This is the ATP yield associated with the glycerol-3-phosphate shuttle, which transfers electrons to FAD inside the mitochondria rather than NAD+.', '["1","2","3","4"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:54:50.077Z"'::jsonb),
('anki-card-1757926504564-10', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Easy passage of nutrients from area of most concentration to less concentration.', 'Passive diffusion', 'Passive diffusion is the unhindered, spontaneous movement of nutrient molecules down their concentration gradient (from an area of highest concentration to an area of lesser concentration) without requiring carrier proteins or cellular energy.

• Active transport: Moves molecules against a concentration gradient using ATP energy.
• Endocytosis: Involves vesicle formation to engulf large extracellular substances.
• Carrier mediated: Requires specialized transport proteins spanning the plasma membrane.', '["Passive diffusion","Active transport","Endocytosis","Carrier mediated"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:56:48.281Z"'::jsonb),
('anki-card-1757926545013-11', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Production of lactic acid from muscle and converting it to glucose in the liver.', 'Cori Cycle', 'The Cori cycle describes the metabolic pathway in which lactate produced anaerobically by active skeletal muscles is transported to the liver, converted back into glucose via gluconeogenesis, and returned to the muscles to replenish energy reserves.

• Gluconeogenesis: The broader metabolic synthesis of glucose, whereas the specific lactate shuttle loop is the Cori cycle.
• Glycolysis: The breakdown of glucose into pyruvate/lactate, representing only the first half of the cycle.
• Glycogenolysis: The breakdown of stored glycogen into glucose subunits.', '["Gluconeogenesis","Glycolysis","Glyconegenolysis","Cori Cycle"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:56:54.132Z"'::jsonb),
('anki-card-1757926562329-12', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Generates 2 ATP in the absence of oxygen*', 'Glycolysis', 'Glycolysis is the anaerobic breakdown pathway of glucose that operates in the cytoplasm to generate 2 net ATP molecules per glucose molecule in the absence of oxygen.

• Gluconeogenesis: Synthesizes glucose from non-carbohydrate precursors.
• Glyconegenolysis: The breakdown of stored glycogen reserves.
• Glycogenesis: The anabolic synthesis of glycogen polymers.', '["Gluconeogenesis","Glycolysis","Glyconegenolysis","Glycogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:06:19.618Z"'::jsonb),
('anki-card-1757926580845-13', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Taking place in muscle and liver, and supplies energy needs immediately after fasting.*', 'Glycogenolysis', 'Glycogenolysis (glycogen breakdown) takes place in both skeletal muscle and liver tissue, providing rapid glucose availability to meet immediate energy demands during short-term fasting or physical exertion.

• Gluconeogenesis: Synthesizes new glucose from non-carbohydrate sources during extended fasting.
• Glycolysis: Catabolic pathway oxidizing glucose to pyruvate.
• Glycogenesis: The anabolic pathway synthesizing glycogen storage reserves.', '["Glycogenolysis","Gluconeogenesis","Glycolysis","Glycogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:57:09.877Z"'::jsonb),
('anki-card-1757926611192-14', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Provides the sugars needed for synthesis of protein. *', 'Pentose Phosphate Pathway', 'The Pentose Phosphate Pathway (hexose monophosphate shunt) operates in the cytosol to generate NADPH for reductive biosynthesis and ribose-5-phosphate, which serves as the essential sugar backbone for nucleotide and nucleic acid (protein synthesis machinery) building blocks.

• Gluconeogenesis: Synthesizes glucose for systemic energy, not specialized nucleotide sugars.
• Glycolysis: Generates ATP and pyruvate intermediates for energy.
• Glycogenolysis: Mobilizes stored glycogen reserves into free glucose.', '["Gluconeogenesis","Glycolysis","Glyconegenolysis","Pentose Phosphate Pathway"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:57:21.835Z"'::jsonb),
('anki-card-1757926625659-15', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Both a catabolic and anabolic process to produce glucose from lactate, amino acids and glycerol.*', 'Gluconeogenesis', 'Gluconeogenesis is an amphibolic pathway acting as both catabolic (breakdown of protein/amino acid skeletons and glycerol) and anabolic (synthesis of glucose) to produce new glucose from lactate, amino acids, and glycerol during periods of low carbohydrate intake.

• Glycolysis: The breakdown of glucose into pyruvate.
• Glycogenolysis: The breakdown of stored glycogen into glucose.
• Glycogenesis: The synthesis of glycogen from free glucose molecules.', '["Gluconeogenesis","Glycolysis","Glyconegenolysis","Glycogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:57:26.975Z"'::jsonb),
('anki-card-1757926640592-16', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Takes place in the liver and muscle, builds energy reserve. *', 'Glycogenesis', 'Glycogenesis is the anabolic pathway that takes place primarily in the liver and skeletal muscles to convert excess glucose into glycogen polymers, building up energy storage reserves.

• Gluconeogenesis: Synthesizes glucose from non-carbohydrate precursors.
• Glycolysis: Degrades glucose for immediate cellular energy production.
• Glycogenolysis: Degrades stored glycogen to release free glucose into the bloodstream.', '["Gluconeogenesis","Glycolysis","Glyconegenolysis","Glycogenesis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:57:32.551Z"'::jsonb),
('anki-card-1757926659373-17', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Number of food groups that should be present in a meal to reflect diet quality and nutrient adequacy in a diet diversity score', 'None of the above', 'Dietary diversity scores evaluate nutrient adequacy based on standardized food group thresholds depending on the target demographic population, and none of the rigid pairings listed in the distractor options accurately reflect the official dietary diversity indices.

• 4 for infants, 5 for adult women: Inaccurate threshold combination for standard food group score metrics.
• 5 for infants, 4 for women: Reversed and incorrect demographic food group cutoffs.', '["4 for infants, 5 for adult women","5 for infants, 4 for women","None of the above","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:57:46.409Z"'::jsonb),
('anki-card-1757926674873-18', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The ff are true about dietary inflammatory index:', 'None of the above', 'The Dietary Inflammatory Index (DII) assigns scores where pro-inflammatory foods (like refined grains and processed meats) score positively, while anti-inflammatory foods (like spices, fruits, and vegetables) score negatively (anti-inflammatory). Thus, the statements claiming processed foods have high anti-inflammatory scores or spices have low anti-inflammatory scores are false.

• Processed foods have the highest anti-inflammatory index: False; processed foods are typically pro-inflammatory.
• Spices are amongst those with the lowest anti-inflammatory index: False; spices possess potent anti-inflammatory properties (giving them strongly negative, highly anti-inflammatory DII scores).', '["Processed foods have the highest anti-inflammatory index","Spices are amongst those with the lowest anti-inflammatory index","None of the above","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:57:59.178Z"'::jsonb),
('anki-card-1757926695007-19', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The following reactions take place in cytosol except', 'Kreb Cycle', 'The Krebs cycle (citric acid cycle) takes place entirely within the mitochondrial matrix, whereas glycolysis, glycogenesis, and the pentose phosphate pathway occur in the fluid cytosol.

• Glycolysis: Occurs in the cytosol of eukaryotic cells.
• Glycogenesis: Takes place in the cytoplasmic compartment of liver and muscle cells.
• Pentose phosphate pathway: Operates in the cytoplasm.', '["Glycolysis","Kreb Cycle","Glycogenesis","Pentose phosphate pathway"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:58:05.046Z"'::jsonb),
('anki-card-1757926716239-20', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'During Kreb Cycle, this condenses with acetyl CoA to form citrate.', 'Oxaloacetate', 'At the entry point of the Krebs cycle, the 2-carbon Acetyl-CoA condenses with a 4-carbon oxaloacetate molecule via citrate synthase to form the 6-carbon citrate molecule.

• Pyruvate: The end product of glycolysis that undergoes oxidative decarboxylation into Acetyl-CoA before entering the cycle.
• Succinate: An intermediate later in the Krebs cycle formed during succinyl-CoA conversion.', '["Pyruvate","Oxaloacetate","Succinate","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:58:13.274Z"'::jsonb),
('anki-card-1757926738687-21', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The enzyme which converts glucose to glucose 6- phosphate is:', 'Hexokinase', 'Hexokinase (and glucokinase in hepatic tissue) is the regulatory enzyme that catalyzes the irreversible phosphorylation of glucose using ATP to trap it inside the cell as glucose-6-phosphate.

• Phosphoglucomutase: Catalyzes the interconversion of glucose-1-phosphate and glucose-6-phosphate during glycogen metabolism.
• Phosphorylase: Catalyzes the phosphorolytic cleavage of glycogen into glucose-1-phosphate.
• Synthase: An enzyme class that builds larger molecular structures.', '["Phosphoglucomutase","Hexokinase","Phosphorylase","Synthase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:58:46.917Z"'::jsonb),
('anki-card-1757926757170-22', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The enzyme which converts glucose 6-phosphate to glucose is:', 'Phosphatase', 'Glucose-6-phosphatase (a specific hepatic phosphatase enzyme) removes the phosphate group from glucose-6-phosphate, converting it into free glucose so it can be exported from the liver into the bloodstream.

• Phosphorylase: Breaks down glycogen polymers into phosphorylated glucose units.
• Synthase: Synthesizes complex molecules rather than dephosphorylating sugar esters.', '["Phosphatase","Phosphorylase","Synthase","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:58:52.272Z"'::jsonb),
('anki-card-1757926772035-23', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'When we exercise, the oxygen may not reach the muscles fast enough so there is a need for this cycle for quick energy which requires the interaction of muscles and liver', 'Lactic Acid Cycle', 'When strenuous exercise causes muscle oxygen demand to outstrip supply, anaerobic glycolysis generates lactate, which is shuttled to the liver via the Lactic Acid Cycle (Cori Cycle) to be converted back into glucose for immediate energy replenishment.

• Glycolysis: The basic cellular breakdown of glucose, but does not encompass the full muscle-liver shuttle loop.
• Glycogenolysis: The breakdown of glycogen, but does not describe the specific lactate-glucose inter-organ cycle.', '["Glycolysis","Glycogenolysis","Lactic Acid Cycle","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:58:58.401Z"'::jsonb),
('anki-card-1757926787335-24', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Secreted by the adrenal medulla, this hormone triggers catabolic reactions like glycogenolysis to generate energy.', 'Epinephrine', 'Epinephrine (adrenaline) is secreted by the adrenal medulla during acute stress or exertion, binding to adrenergic receptors to stimulate rapid catabolic cascades like hepatic and muscle glycogenolysis for immediate energy mobilization.

• Cortisol: A glucocorticoid steroid hormone promoting long-term gluconeogenesis and protein catabolism during chronic stress.
• Thyroxine: Regulates basal metabolic rate over extended periods.', '["Cortisol","Thyroxine","Epinephrine","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:05.013Z"'::jsonb),
('anki-card-1757926803401-25', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Protein which transports fatty acid in the plasma', 'Albumin', 'Albumin is the most abundant plasma protein synthesized by the liver, serving as a primary circulating carrier protein for free fatty acids, hormones, and bilirubin in the bloodstream.

• Creatinine: A metabolic waste product filtered by the kidneys from muscle metabolism.
• Pepsin: A proteolytic digestive enzyme secreted in the stomach.
• Collagen: The main structural fibrous protein found in connective tissues, skin, and bone.', '["Albumin","Creatinine","Pepsin","Collagen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:10.716Z"'::jsonb),
('anki-card-1757926818115-26', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The following are ketone bodies produced by the liver except:', 'Propionate', 'The three main physiological ketone bodies produced by the liver during fasting or low carbohydrate intake are acetoacetate, beta-hydroxybutyrate, and acetone. Propionate is a short-chain fatty acid produced by colonic fermentation, not a hepatic ketone body.

• Acetone: One of the three primary ketone bodies formed via spontaneous decarboxylation of acetoacetate.
• Acetoacetate: The primary initial ketone body synthesized in hepatic mitochondria from acetyl-CoA.
• Hydroxybutyrate (Beta-hydroxybutyrate): The most abundant circulating ketone body produced in the liver.', '["Acetone","Acetoacetate","hydroxybutyrate","Propionate"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:56:00.231Z"'::jsonb),
('anki-card-1757926831450-27', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The site of protein synthesis', 'Ribosomes', 'Ribosomes (composed of ribosomal RNA and proteins) serve as the primary cellular machinery and site where messenger RNA (mRNA) is translated into polypeptide chains during protein synthesis.

• Smooth Endoplasmic reticulum: Involved in lipid synthesis, calcium storage, and detoxification, lacking ribosomes.
• Cytoplasm: The broader cellular fluid medium, whereas ribosomes are the specific macromolecular synthesis hubs.
• Mitochondria: The organelle responsible for ATP generation via oxidative phosphorylation.', '["Ribosomes","Smooth Endoplasmic reticulum","Cytoplasm","Mitochondria"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:16.131Z"'::jsonb),
('anki-card-1757926852599-28', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Small bodies filled with enzymes surrounded by a single membrane', 'lysozomes', 'Lysosomes are small, membrane-bound cytoplasmic vesicles filled with hydrolytic digestive enzymes that break down cellular debris, waste, and foreign particles.

• Centrioles: Cylindrical organelle structures involved in organizing mitotic spindle fibers during cell division.
• Peroxisomes: Organelles containing oxidative enzymes for breaking down fatty acids and detoxifying hydrogen peroxide.
• Golgi complex: Responsible for modifying, sorting, and packaging proteins for secretion.', '["centrioles","lysozomes","peroxisomes","golgi complex"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:22.991Z"'::jsonb),
('anki-card-1757926869934-29', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'What originates in the brain stem and controls heart rate, blood pressure, breathing, and digestion:', 'All of above', 'The vagus nerve (cranial nerve X) originates in the brainstem, regulates autonomic visceral functions including heart rate, blood pressure, respiration, and gastrointestinal digestion, and forms the primary neural backbone of the bidirectional gut-brain axis.', '["is called the Vagus nerve","It is One of the twelve Cranial nerve","Establishes the link of gut -brain axis.","All of above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:30.066Z"'::jsonb),
('anki-card-1757926890962-30', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Arranged according to increasing digestibility', 'Protein, fats, carbohydrates', 'In terms of physiological digestion and enzymatic breakdown kinetics in the human gastrointestinal tract, simple carbohydrates are digested most rapidly, followed by proteins, with fats taking the longest digestion and gastric emptying time.', '["Carbohydrates, protein and then fats","Protein, fats, carbohydrates","Protein, carbohydrates, fats","Fats, protein, carbohydrates"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:35.531Z"'::jsonb),
('anki-card-1757926913796-31', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Arranged according to decreasing satiety', 'Protein, lipids, carbohydrates', 'Dietary protein triggers the strongest hormonal and physical signals promoting early postprandial fullness and satiety, followed by lipids (fats), with carbohydrates providing the lowest prolonged satiety index per calorie.', '["Lipids, protein, carbohydrates","Carbohydrates, lipids, protein","Lipids, carbohydrates, protein","Protein, lipids, carbohydrates"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:43.785Z"'::jsonb),
('anki-card-1757926931493-32', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Gastrin _____ gastric secretion. It also ____ gastric motility', 'Increases, increases', 'Gastrin is a peptide hormone that increases gastric acid (HCl) secretion from parietal cells and also increases gastric smooth muscle motility to churn and mix food contents in the stomach.', '["Increases, increases","Decreases, increases","Increases, decreases","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:50.041Z"'::jsonb),
('anki-card-1757926947809-33', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Cells which secrete HCl', 'Parietal cells', 'Parietal cells (oxyntic cells) located in the gastric glands of the stomach mucosa secrete hydrochloric acid (HCl) and intrinsic factor, maintaining the acidic environment required for protein digestion and iron absorption.

• Chief cells: Secrete pepsinogen (the inactive precursor of pepsin) and gastric lipase.
• D cells: Secrete somatostatin, a hormone that inhibits gastric acid secretion and endocrine hormone release.
• G cells: Secrete gastrin, the hormone that stimulates parietal cells to release HCl.', '["Chief cells","Parietal cells","D cells","G cells"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:54:56.029Z"'::jsonb),
('anki-card-1757926968576-34', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Stimulate the pancreas to release its digestive enzymes and sodium bicarbonate', 'secretin', 'Secretin is an endocrine hormone released by the duodenal mucosa in response to acidic chyme, stimulating the exocrine pancreas to secrete a watery, bicarbonate-rich fluid to neutralize acid alongside digestive enzymes.

• Polypeptide y (PYY): An enteric hormone that suppresses appetite and slows gastric emptying.
• Cholecystokinin (CCK): Stimulates gallbladder contraction and pancreatic enzyme secretion, whereas secretin specifically triggers pancreatic bicarbonate release.
• Gastrin: Stimulates gastric acid secretion in the stomach.', '["secretin","polypeptide y","cholecystokinin","gastrin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T02:59:55.750Z"'::jsonb),
('anki-card-1757926983526-35', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The end product of nucleotide digestion are', 'Nitrogenous base, sugar and phosphates', 'Nucleotides (the building blocks of nucleic acids) consist of three core chemical components: a nitrogenous base (purine or pyrimidine), a pentose sugar (ribose or deoxyribose), and one or more phosphate groups.', '["Nucleosides, sugar and phosphates","Nucleotides, sugar and phosphates","Nitrogenous base, sugar and phosphates","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:03.067Z"'::jsonb),
('anki-card-1757927004624-36', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Steps of Vitamin D activation', 'Skin, liver, kidney', 'The sequential activation of Vitamin D begins in the skin where ultraviolet light converts 7-dehydrocholesterol to cholecalciferol (Vitamin D3), followed by 25-hydroxylation in the liver, and final 1-alpha-hydroxylation in the kidney to produce the active hormone calcitriol.', '["Skin, liver, kidney","Kidney, liver, skin","Skin, kidney, liver","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:12.027Z"'::jsonb),
('anki-card-1757927020639-37', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Steps of Vitamin D activation', 'None of the above', 'The true chemical sequence of Vitamin D activation proceeds from 7-dehydrocholesterol (in skin) to cholecalciferol, then to 25-hydroxycholecalciferol (in liver), and finally to 1,25-dihydroxycholecalciferol (in kidney). None of the distractor options accurately list this precise biochemical nomenclature.', '["7 dehydrocholesterol, 1,25 dihydroxycholecalciferol, hydroxycholechalciferol","1,25, dihydroxycholecalcifierol, hydroxycholecalciferol, 7 dehydrocholestrol","7 dehydrocholesterol, 25 dihydroxycholecalciferol, 1,25 hydroxycholechalciferol","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:16.895Z"'::jsonb),
('anki-card-1757927035390-38', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Partners with free fatty acids to form Triacylglycerol', 'Glucose', 'During triacylglycerol (triglyceride) synthesis and re-esterification in mucosal cells, free fatty acids require an active glycerol backbone (derived from glucose metabolism via dihydroxyacetone phosphate converted to glycerol-3-phosphate) to pair and form triglycerides.', '["Glucose","Fructose","Galactose","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:22.218Z"'::jsonb),
('anki-card-1757927050389-39', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Oligosaccharide, intermediate of Carbohydrate metabolism, from starch digestion', 'Maltodextrin', 'Maltodextrin is an intermediate oligosaccharide breakdown product derived from the partial enzymatic hydrolysis of dietary starches (amylose and amylopectin) consisting of D-glucose units linked in chains.

• Glucose: A simple 6-carbon monosaccharide, not an oligosaccharide.
• Raffinose: A trisaccharide found in beans (composed of galactose, glucose, and fructose), not a starch breakdown intermediate.
• Fiber: Indigestible plant polysaccharide structures, distinct from digestible starch maltodextrins.', '["Glucose","Maltodextrin","Raffinose","Fiber"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:29.097Z"'::jsonb),
('anki-card-1757927068238-40', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Functions of soluble fiber except:', 'decrease insulin sensitivity', 'Soluble fibers (such as pectins, gums, and mucilages) actually improve and increase insulin sensitivity, slow glucose absorption, bind bile acids, and help lower serum cholesterol, making "decrease insulin sensitivity" the false statement and correct exception.', '["bind bile acids","lower cholesterol","decrease insulin sensitivity","lowers blood glucose"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:33.653Z"'::jsonb)
