INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1757927089103-41', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Examples of fermentable fibers except:', 'Cellulose', 'Cellulose is an insoluble, highly crystalline plant cell wall polysaccharide that is largely non-fermentable by human colonic microflora, whereas pectins, gums, mucilages, and inulin are classic fermentable soluble fibers.

• Pectins: Highly fermentable soluble fibers found in fruits.
• Gums and mucilages: Viscous, readily fermentable soluble fibers.
• Inulin: A fermentable fructan soluble fiber acting as a prebiotic.', '["Cellulose","Pectins","Gums and mucilages","Inulin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:39.397Z"'::jsonb),
('anki-card-1757927118353-42', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'This transports triglycerides from the intestine to the liver', 'Chylomicron', 'Chylomicrons are large lipoprotein transport particles assembled in the intestinal enterocytes that package dietary triglycerides, cholesterol esters, and fat-soluble vitamins to transport them through the lymphatic system and into the bloodstream/liver.

• Very low density lipoprotein (VLDL): Synthesized in the liver to transport endogenous triglycerides to peripheral tissues.
• Low density lipoprotein (LDL): Transports cholesterol from the liver to peripheral tissues.
• High density lipoprotein (HDL): Mediates reverse cholesterol transport from peripheral tissues back to the liver.', '["Very low density lipoprotein","Chylomicron","Low densitiy lipoprotein","High density lipoprotein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:00:45.075Z"'::jsonb),
('anki-card-1757927137934-43', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Short-chain fatty acids (SCFAs)  which are being acclaimed to have a mediational role in the microbiota–gut–brain axis crosstalk:', 'Butyrate, acetate, propionate', 'The three primary short-chain fatty acids (SCFAs) produced by the microbial fermentation of dietary fiber in the human colon are butyrate, acetate, and propionate, which play essential signaling and mediational roles in the microbiota-gut-brain axis.

• Propionate, acetoacetate, butyrate: Incorrect because acetoacetate is a hepatic ketone body, not a primary colonic SCFA.
• Beta hydroxybutyrate, acetoacetate, propionate: Incorrect as beta-hydroxybutyrate and acetoacetate are ketone bodies.', '["Propionate, acetoacetate, butyrate","Butyrate, acetate, propionate","Beta hydroxybutyrate, acetoacetate, propionate","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:01:47.281Z"'::jsonb),
('anki-card-1757927156032-44', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Aromatic amino acids are the ff. except:', 'None of the above', 'Aromatic amino acids contain an aromatic ring in their chemical structure. Tyrosine, phenylalanine, and tryptophan are all well-established aromatic amino acids, making "None of the above" correct because none of the listed options are exceptions.

• Tyrosine: An aromatic amino acid containing a phenol group.
• Phenylalanine: An essential aromatic amino acid featuring a benzene ring.
• Tryptophan: An essential aromatic amino acid containing an indole ring.', '["Tyrosine","Phenylalanine","Tryptophan","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:01:55.929Z"'::jsonb),
('anki-card-1757927172050-45', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Trypsin does the ff. actions:', 'Converts procarboxypeptidase to carboxypeptidase', 'Trypsin is a master pancreatic serine protease that activates various zymogens in the small intestine; specifically, it cleaves and converts inactive procarboxypeptidase into active carboxypeptidase (along with activating trypsinogen itself and chymotrypsinogen).

• Converts chymotrypsinogen to trypsin: Trypsin activates chymotrypsinogen into chymotrypsin, but trypsinogen is autocatalytically or enteropeptidase-activated, making procarboxypeptidase conversion the broader functional key tested here.', '["Converts chymotrypsinogen to trypsin","Converts procarboxypeptidase to carboxypeptidase","None of the above","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:07.436Z"'::jsonb),
('anki-card-1757927188748-46', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'All the statements regarding micelles are false except:', 'they enter the epithelial cells by diffusion', 'Mixed micelles transport insoluble lipid digestion products (fatty acids, monoglycerides, fat-soluble vitamins) across the unstirred water layer to the brush border, where the lipid contents are released and enter the intestinal epithelial cells (enterocytes) primarily via passive and carrier-mediated diffusion.', '["they are very big insoluble droplet","they enter the epithelial cells by diffusion","they are polar molecular molecules","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:13.024Z"'::jsonb),
('anki-card-1757927203081-47', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Protein which is allows tissues to stretch.', 'Elastin', 'Elastin is a highly elastic fibrous extracellular matrix protein found in connective tissues (such as arterial walls, lungs, and skin) that allows tissues and organs to stretch and recoil back to their original shape.

• Collagen: Provides tensile strength and structural rigidity, not primary tissue stretch.
• Myosin: A motor protein responsible for muscle contraction.
• Albumin: A globular plasma protein maintaining oncotic pressure and transporting ligands.', '["Collagen","Myosin","Albumin","Elastin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:19.146Z"'::jsonb),
('anki-card-1757927219346-48', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The following are not Fibrous proteins:', 'none of the above', 'Elastin, fibrin, and collagen are all classic examples of insoluble, structural fibrous proteins (as opposed to soluble globular proteins), making "none of the above" correct since none of them are exceptions to the fibrous protein classification.

• Elastin: A structural fibrous connective tissue protein.
• Fibrin: A fibrous protein involved in blood clot formation.
• Collagen: The quintessential structural fibrous protein of connective tissue.', '["elastin","fibrin","collagen","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:24.593Z"'::jsonb),
('anki-card-1757927254944-49', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Major Proteins found in cereals: Wheat', 'gliadin', 'Gliadin is the primary alcohol-soluble prolamin protein fraction found in wheat (which, along with glutenin, forms gluten).

• Hordein: The major prolamin storage protein found in barley.
• Zein: The major storage protein found in corn (maize).
• Albumin: A water-soluble globular protein fraction, not the major cereal prolamin.', '["hordein","gliadin","zein","albumin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:30.335Z"'::jsonb),
('anki-card-1757927286245-50', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Major Proteins found in cereals: Corn', 'zein', 'Zein is the principal prolamin protein found in corn (maize) endosperm.

• Hordein: The specific storage protein of barley.
• Gliadin: The major wheat gluten protein.
• Albumin: A general water-soluble protein fraction.', '["hordein","gliadin","zein","albumin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:36.967Z"'::jsonb),
('anki-card-1757927330024-51', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Major Proteins found in cereals: Barley', 'hordein', 'Hordein is the characteristic prolamin storage protein found in barley grain.

• Gliadin: Found in wheat.
• Zein: Found in corn.
• Albumin: A general soluble protein type.', '["hordein","gliadin","zein","albumin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:42.144Z"'::jsonb),
('anki-card-1757927358657-52', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Major Proteins found in cereals: Rice', 'glutelin', 'Glutelin (specificallyoryzenin) is the major alkali-soluble storage protein found in rice.

• Hordein: Barley protein.
• Gliadin: Wheat protein.
• Zein: Corn protein.', '["hordein","gliadin","zein","glutelin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:48.331Z"'::jsonb),
('anki-card-1757927377489-53', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The ff. is true about Urea formation:', 'Urea is excreted in the urine', 'Urea is synthesized in the liver via the urea cycle to safely detoxify ammonia, enters the bloodstream, and is subsequently filtered and excreted primarily through the kidneys in urine.

• Ammonia in the blood (which is toxic) combines with glycine to form urea (nontoxic): Incorrect because ammonia combines with carbon dioxide and the amino group of aspartate/carbamoyl phosphate, not glycine.
• It occurs in the kidney: Incorrect because urea synthesis (urea cycle) takes place primarily in the liver, while excretion occurs in the kidney.
• It involves the amino acids histidine: Incorrect; the urea cycle utilizes ornithine, citrulline, arginine, and aspartate.', '["Ammonia in the blood (which is toxic) combines with glycine to form urea (nontoxic)","Urea is excreted in the urine","It occurs in the kidney","It involves the amino acids histidine"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:02:58.304Z"'::jsonb),
('anki-card-1757927394739-54', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'This method compares the amino acid profile of the specific food protein against a standard amino acid profile with the highest possible one', 'PDCAAS', 'The Protein Digestibility-Corrected Amino Acid Score (PDCAAS) evaluates protein quality by comparing the amino acid profile of a specific food protein against a reference standard amino acid scoring pattern, corrected for true fecal digestibility.

• Net Protein Ratio: Measures weight gain relative to protein intake including maintenance requirements.
• Biological Value: Measures the fraction of absorbed nitrogen retained in the body for maintenance and growth.
• Net Protein Utilization: Evaluates the proportion of dietary protein retained relative to total protein consumed.', '["Net Protein Ratio","Biological Value","PDCAAS","Net Protein Utilization"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:03:06.732Z"'::jsonb),
('anki-card-1757927412122-55', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Gain in mass g/ Protein intake g is', 'None of the above', 'The ratio of body mass gain relative to protein intake (Weight Gain / Protein Intake) is known as the Protein Efficiency Ratio (PER), making "None of the above" correct since the listed options (NPU, Amino Acid Score, Biological Value) do not define PER.

• Net Protein Utilization: Measures retained nitrogen relative to intake nitrogen.
• Amino Acid Score: Compares test protein essential amino acid levels against a reference pattern.
• Biological value: Measures retained nitrogen relative to absorbed nitrogen.', '["Net Protein Utilization","Amino Acid Score","Biological value","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:03:15.694Z"'::jsonb),
('anki-card-1757927442487-56', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The ff. are benefits of plant based diets:', 'All of the above', 'Plant-based diets offer robust health benefits including lower overall dietary energy density, higher proportions of unsaturated fats with lower saturated fats, and abundant dietary fiber.', '["Lower energy density","More unsaturated, less saturated fat","More dietary fiber","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:03:24.765Z"'::jsonb),
('anki-card-1757927466268-57', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Nutrients which can be supplemented in vegan diets except', 'vitamin B1', 'Vegan diets exclude all animal products, putting individuals at risk for deficiencies in Vitamin B12 (found exclusively in animal sources), Vitamin D, and iodine (depending on soil/salt intake). Vitamin B1 (thiamin) is widely abundant in unrefined cereal grains, legumes, nuts, and seeds, making it an exception that does not typically require supplementation on a balanced vegan diet.

• Vitamin B12: Essential nutrient requiring strict supplementation in unfortified vegan diets.
• Vitamin D: Often requires supplementation depending on sunlight exposure and fortified foods.
• Iodine: May require supplementation if iodized salt or sea vegetables are lacking.', '["vitamin B12","vitamin D","iodine","vitamin B1"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:03:36.647Z"'::jsonb),
('anki-card-1757927481018-58', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Low carb, low fat, high protein diets may:', 'Promote glucose control', 'Low-carbohydrate, high-protein dietary interventions can improve short-term glycemic parameters and promote blood glucose control by restricting carbohydrate loads, though long-term lipid and renal impacts require clinical monitoring.', '["Increase LDL cholesterol","Promote glucose control","Increase uric acid","None of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:03:53.014Z"'::jsonb),
('anki-card-1757927496901-59', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', '_____ is one benefit of fasting. It removes damaged or dysfunctional parts of a cell and recycles other parts toward cellular repair.', 'autophagy', 'Autophagy is the regulated cellular self-cleaning and recycling mechanism activated during fasting or nutrient deprivation where damaged organelles, misfolded proteins, and dysfunctional cellular components are degraded and repurposed for repair.

• Polyphagia: Medical term for excessive hunger or increased appetite.
• Autophagia: A misspelling/variant term, whereas the official biological term is autophagy.', '["polyphagia","autophagy","autophagia","none of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:03:59.111Z"'::jsonb),
('anki-card-1757927510100-60', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'The ff. are true about arginine and histidine:', 'They are needed when we are young', 'Arginine and histidine are classified as conditionally essential amino acids; they are considered essential during periods of rapid growth and development (infancy and childhood) when the body cannot synthesize them in sufficient quantities, making them specifically needed when young.', '["The body cannot produce them at all","The body cannot make them when they are adults","They are needed when we are young","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:04:07.088Z"'::jsonb),
('anki-card-1757927525231-61', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Number of ATP produced by each NADH in glycerophosphate shuttle', '2', 'The glycerol-3-phosphate shuttle transfers reducing equivalents from cytosolic NADH into the mitochondria by reducing dihydroxyacetone phosphate to glycerol-3-phosphate, yielding approximately 2 ATP equivalents per NADH upon reoxidation by FAD.

• 3: Represents the higher yield of the malate-aspartate shuttle.', '["3","2","1","4"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:04:14.917Z"'::jsonb),
('anki-card-1757927538116-62', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Number of FADH2 produced in Kreb Cycle', '2', 'Each complete turn of the citric acid (Krebs) cycle produces 1 molecule of FADH2 (via the succinate dehydrogenase reaction), which totals 2 molecules of FADH2 per glucose molecule (since 2 Acetyl-CoA molecules enter the cycle).', '["2","6","4","1"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:04:20.554Z"'::jsonb),
('anki-card-1757927553832-63', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Number of NADH produced in Glycolysis', '2', 'During glycolysis (the Embden-Meyerhof pathway), the oxidation of glyceraldehyde-3-phosphate generates 2 molecules of NADH in the cytosol per molecule of glucose processed.', '["1","2","4","3"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:04:24.734Z"'::jsonb),
('anki-card-1757927571896-64', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'Number of NADH produced in (2 cycles) Kreb Cycle', '6', 'Each turn of the Krebs cycle produces 3 molecules of NADH. Since one glucose molecule yields two Acetyl-CoA molecules (requiring two full cycles), the total NADH produced across 2 cycles of the Krebs cycle is 6 molecules.', '["1","3","6","9"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:04:31.734Z"'::jsonb),
('anki-card-1757927595763-65', NULL, 'anki-deck-1783610525132-1790433140279-g2fd9', 'During conversion of Pyruvate to Acetyl Coa, number of ATP produced', '0', 'The oxidative decarboxylation of pyruvate into Acetyl-CoA by the pyruvate dehydrogenase complex yields 1 NADH per pyruvate (2 per glucose), but generates 0 ATP directly via substrate-level phosphorylation at this specific step.', '["0","1","4","3"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:29.690Z"'::jsonb, '"2026-11-09T03:04:36.675Z"'::jsonb),
