('anki-card-1756883364539-16', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganisms that grow in high sugar concentration.', 'osmophile', 'Osmophiles are microorganisms capable of growing in environments characterized by high osmotic pressure and elevated sugar concentrations (such as syrups and honey).', '["cryophile","osmophile","xerophile","halophile"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:22:44.138Z"'::jsonb),
('anki-card-1756883377922-17', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganisms that grow in high salt concentration.', 'halophile', 'Halophiles are salt-tolerant or salt-loving microorganisms capable of thriving in high salt concentrations (e.g., salted fish or brines).', '["cryophile","osmophile","xerophile","halophile"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:22:47.345Z"'::jsonb),
('anki-card-1756883391672-18', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganisms that can grow well at above 45°C.', 'Thermophile', 'Thermophiles are specialized heat-loving microorganisms that thrive and grow optimally at elevated temperatures above 45°C (often up to 55°C–65°C).

