('anki-card-1756883489502-23', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganisms that can grow under both aerobic and anaerobic environments.', 'facultative anaerobe', 'Facultative anaerobes are versatile microorganisms that can generate metabolic energy via aerobic respiration in the presence of oxygen or via fermentation/anaerobic respiration in its absence.', '["aerobe","anaerobe","facultative anaerobe","microaerophile"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:05.021Z"'::jsonb),
('anki-card-1756883507549-24', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Antimicrobial compound found in garlic.', 'Allicin', 'Allicin is a biologically active organosulfur antimicrobial compound formed when garlic is crushed or chopped, possessing potent antibacterial and antifungal properties.

• Cinnamic / Thymol / Eugenol: Plant-derived antimicrobials found in cinnamon, thyme, and cloves, respectively.', '["Cinnamic","Allicin","Thymol","Eugenol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:09.668Z"'::jsonb)
