('anki-card-1756883521815-25', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Saccharomyces carlsbergensis is commonly associated with the production of ____.', 'beer', 'Saccharomyces carlsbergensis is a bottom-fermenting yeast historically classified and utilized in the commercial brewing of lager beers.', '["cheese","wine","beer","soy sauce"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:19.015Z"'::jsonb),
('anki-card-1756883537599-26', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism associated with the production of vinegar.', 'Acetobacter aceti', 'Acetobacter aceti is an aerobic acetic acid bacterium utilized commercially to oxidize ethanol into acetic acid during vinegar production.', '["Acetobacter aceti","Aspergillus oryzae","Penicillium roqueforti","Saccharomyces elipsoides"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:24.257Z"'::jsonb),
('anki-card-1756883551348-27', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism associated with the production of wine.', 'Saccharomyces elipsoides', 'Saccharomyces ellipsoideus (often grouped with Saccharomyces cerevisiae var. ellipsoideus) is the primary fermenting yeast strain traditionally used in winemaking to convert fruit sugars into alcohol.', '["Acetobacter aceti","Aspergillus oryzae","Penicillium roqueforti","Saccharomyces elipsoides"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:28.628Z"'::jsonb),
('anki-card-1756883566946-28', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism associated with the production of cheese.', 'Penicillium roqueforti', 'Penicillium roqueforti is a beneficial mold strain utilized for inoculating and ripening blue-veined cheeses (such as Roquefort and Gorgonzola).', '["Acetobacter aceti","Aspergillus oryzae","Penicillium roqueforti","Saccharomyces elipsoides"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:34.046Z"'::jsonb),
('anki-card-1756883582663-29', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism associated with raw poultry and is resistant to drying.', 'Salmonella', 'Salmonella species are enteric bacterial pathogens commonly associated with raw poultry and eggs, notable for possessing high environmental stress tolerance and resistance to drying.', '["Bacillus cereus","Salmonella","Listeria monocytogenes","Clostridium perfringens"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:38.393Z"'::jsonb),
('anki-card-1756883599395-30', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism associated with chilled minimally processed food.', 'Listeria monocytogenes', 'Listeria monocytogenes is a psychrotrophic foodborne pathogen capable of multiplying slowly at refrigeration temperatures, frequently contaminating chilled, ready-to-eat, and minimally processed foods.', '["Bacillus cereus","Salmonella","Listeria monocytogenes","Clostridium perfringens"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:42.565Z"'::jsonb),
('anki-card-1756883614860-31', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism linked to meat and gravies and grows rapidly in the temperature danger zone.', 'Clostridium perfringens', 'Clostridium perfringens is an anaerobic, spore-forming bacterium that multiplies rapidly in cooked meat dishes and gravies held in the temperature danger zone, causing toxin-mediated food poisoning.', '["Bacillus cereus","Salmonella","Listeria monocytogenes","Clostridium perfringens"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:49.984Z"'::jsonb),
('anki-card-1756883631110-32', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A pathogen that increases the risk of miscarriage in pregnant women.', 'Listeria monocytogenes', 'Listeria monocytogenes poses a severe medical risk to pregnant women, crossing the placental barrier and frequently causing spontaneous abortion, stillbirth, or neonatal meningitis.', '["Bacillus cereus","Salmonella","Listeria monocytogenes","Clostridium perfringens"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:54.281Z"'::jsonb),
('anki-card-1756883646792-33', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Spore-forming bacteria commonly linked to starchy foods.', 'Bacillus cereus', 'Bacillus cereus is a spore-forming, toxin-producing bacterium frequently linked to starchy foods (like cooked rice or pasta) left at room temperature.', '["Bacillus cereus","Salmonella","Listeria monocytogenes","Clostridium perfringens"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:23:58.596Z"'::jsonb),
('anki-card-1756883661609-34', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism commonly linked with incorrectly canned food.', 'Clostridium botulinum', 'Clostridium botulinum is an anaerobic spore-forming bacterium that produces a lethal neurotoxin in low-acid, oxygen-free environments, making it the primary hazard in improperly home-canned foods.', '["Campylobacter jejuni","Clostridium botulinum","Staphylococcus aureus","Vibrio parahaemolyticus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:03.776Z"'::jsonb),
('anki-card-1756883676342-35', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism commonly found in poultry and water.', 'Campylobacter jejuni', 'Campylobacter jejuni is a leading bacterial cause of gastroenteritis commonly harbored in the intestinal tracts of poultry and transmitted via contaminated drinking water and raw poultry products.', '["Campylobacter jejuni","Clostridium botulinum","Staphylococcus aureus","Vibrio parahaemolyticus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:08.839Z"'::jsonb),
('anki-card-1756883693257-36', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism commonly found in human nose, hair, and wounds.', 'Staphylococcus aureus', 'Staphylococcus aureus is a common human pathogen harbored on skin, hair, and nasal passages, frequently introduced into foods via infected cuts or poor hygiene by handlers.', '["Campylobacter jejuni","Clostridium botulinum","Staphylococcus aureus","Vibrio parahaemolyticus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:13.663Z"'::jsonb),
('anki-card-1756883708689-37', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism commonly found in waters where shellfish is harvested.', 'Vibrio parahaemolyticus', 'Vibrio parahaemolyticus is a halophilic marine bacterium naturally occurring in coastal saltwater environments where raw or undercooked shellfish are harvested.', '["Campylobacter jejuni","Clostridium botulinum","Staphylococcus aureus","Vibrio parahaemolyticus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:19.005Z"'::jsonb),
('anki-card-1756883725223-38', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism that produces a neurotoxin.', 'Clostridium botulinum', 'Clostridium botulinum produces botulinum toxin, one of the most potent biological neurotoxins known, blocking neuromuscular transmission and causing flaccid paralysis.', '["Campylobacter jejuni","Clostridium botulinum","Staphylococcus aureus","Vibrio parahaemolyticus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:24.540Z"'::jsonb),
('anki-card-1756883745806-39', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism that produces a heat-stable toxin.', 'Staphylococcus aureus', 'Staphylococcus aureus produces an enterotoxin that is notoriously heat-stable, meaning standard cooking temperatures may kill the bacteria but leave the pre-formed toxin intact to cause food poisoning.', '["Campylobacter jejuni","Clostridium botulinum","Staphylococcus aureus","Vibrio parahaemolyticus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:29.907Z"'::jsonb),
('anki-card-1756883764072-40', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism that is linked to producing shiga-toxin that causes serious damage to the intestine.', 'Escherichia coli O157:H7', 'Escherichia coli O157:H7 is a Shiga toxin-producing E. coli (STEC) strain capable of causing severe hemorrhagic colitis and life-threatening systemic complications like hemolytic uremic syndrome (HUS).', '["Escherichia coli O157:H7","Cronobacter sakazakii","Yersinia enterolitica","Aspergillus flavus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:34.944Z"'::jsonb),
('anki-card-1756883782571-41', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism commonly found in dry food such as infant formula, powdered milk, and starches.', 'Cronobacter sakazakii', 'Cronobacter sakazakii is an opportunistic bacterium adapted to dry conditions, historically linked to severe infections in neonates via contaminated powdered infant formula and dry starches.', '["Escherichia coli O157:H7","Cronobacter sakazakii","Yersinia enterolitica","Aspergillus flavus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:39.968Z"'::jsonb),
('anki-card-1756883796720-42', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism found in soil that is commonly linked to corn, wheat, and peanuts.', 'Aspergillus flavus', 'Aspergillus flavus is a soil-borne mold that contaminates improperly stored field crops like corn, peanuts, and wheat, producing carcinogenic mycotoxins known as aflatoxins.', '["Escherichia coli O157:H7","Cronobacter sakazakii","Yersinia enterolitica","Aspergillus flavus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:45.079Z"'::jsonb),
('anki-card-1756883811037-43', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism found in the gut of animals and commonly linked to undercooked ground meat.', 'Escherichia coli O157:H7', 'Escherichia coli O157:H7 resides in the intestinal tracts of cattle and ruminants, contaminating food supplies primarily through undercooked ground meat and cross-contamination.', '["Escherichia coli O157:H7","Cronobacter sakazakii","Yersinia enterolitica","Aspergillus flavus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:50.226Z"'::jsonb),
('anki-card-1756883827200-44', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganisms that causes bacterial meningitis.', 'Cronobacter sakazakii', 'Cronobacter sakazakii infections in neonates and infants can manifest as severe, life-threatening invasive diseases, including bacteremia and bacterial meningitis.', '["Escherichia coli O157:H7","Cronobacter sakazakii","Yersinia enterolitica","Aspergillus flavus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:24:56.614Z"'::jsonb),
('anki-card-1756883841368-45', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganisms that produces a hepatoxin.', 'Aspergillus flavus', 'Aflatoxins produced by Aspergillus flavus are potent mycotoxins targeting the liver, classifying them as dangerous hepatotoxins and carcinogens.', '["Escherichia coli O157:H7","Cronobacter sakazakii","Yersinia enterolitica","Aspergillus flavus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:25:00.793Z"'::jsonb),
('anki-card-1756883863315-46', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism associated with unpasteurized milk.', 'Yersinia enterolitica', 'Yersinia enterolitica is a psychrotrophic foodborne pathogen frequently associated with unpasteurized milk, contaminated pork, and untreated water.', '["Escherichia coli O157:H7","Cronobacter sakazakii","Yersinia enterolitica","Aspergillus flavus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:25:04.400Z"'::jsonb),
('anki-card-1756883880048-47', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A way of controlling microorganisms by inhibiting DNA replication.', 'irradiation', 'Ionizing radiation (irradiation) controls and destroys microorganisms by penetrating cells and directly damaging or cleaving their DNA, inhibiting replication.', '["irradiation","lowering temperature (cold)","filtration","heat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:25:08.003Z"'::jsonb),
('anki-card-1756883897366-48', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A way of controlling microorganisms by decreasing the rate of chemical reactions.', 'lowering temperature (cold)', 'Lowering environmental temperature (refrigeration or freezing) slows down molecular motion and decreases the rate of biochemical and enzymatic chemical reactions required for microbial metabolism and growth.', '["irradiation","lowering temperature (cold)","filtration","heat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:25:11.931Z"'::jsonb),
('anki-card-1756883911147-49', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A way of controlling microorganisms by separation of microbial contamination by from liquid.', 'filtration', 'Filtration is a physical method used to control and remove microbial contamination by passing liquid through micro-porous membranes without applying heat.

• Irradiation / Lowering temperature / Heat: Alternate methods utilizing radiation, cold, or thermal energy to destroy or inhibit microbes.', '["irradiation","lowering temperature (cold)","filtration","heat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:13.854Z"'::jsonb),
('anki-card-1756883931814-50', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A way of controlling microorganism by denaturation of proteins.', 'heat', 'Thermal processing (heat) kills microorganisms by causing irreversible denaturation of their cellular proteins and enzymes.', '["irradiation","lowering temperature (cold)","filtration","heat"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:16.639Z"'::jsonb),
('anki-card-1756883948613-51', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'It is the creation and maintenance of hygienic and healthful conditions.', 'sanitation', 'Sanitation is defined formally as the creation and maintenance of hygienic, healthful, and clean conditions to protect public health.

• Disinfection / Sterilization: Target specific pathogen elimination levels rather than general hygienic conditions.
• Cleaning: Refers strictly to the removal of visible soil.', '["disinfection","sanitation","cleaning","sterilization"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:21.657Z"'::jsonb),
('anki-card-1756883965328-52', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Example of a physical contaminant.', 'staple wire', 'A staple wire is a foreign object categorized as a physical contamination hazard in food.

• Ant / Mushroom: Biological hazards or natural toxins.
• Chlorine: Chemical hazard.', '["ant","chlorine","staple wire","mushroom"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:28.342Z"'::jsonb),
('anki-card-1756883983544-53', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'All are microorganisms that cause food intoxication, except___.', 'Campylobacter jejuni', 'Campylobacter jejuni causes foodborne infection, whereas the others (Clostridium botulinum, Aspergillus flavus, Staphylococcus aureus) cause foodborne intoxication via pre-formed toxins.', '["Campylobacter jejuni","Clostridium botulinum","Aspergillus flavus","Staphylococcus aureus"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:32.869Z"'::jsonb),
('anki-card-1756883996743-54', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Toxin found in raw egg.', 'avidin', 'Avidin is a natural anti-nutritional protein found in raw egg whites that binds tightly to biotin, rendering it unavailable for absorption.

• Amygdalin: Cyanogenic glycoside found in stone fruit pits.
• Patulin / Ochratoxin: Mycotoxins produced by molds.', '["amygladin","avidin","patulin","ochratoxin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:37.060Z"'::jsonb),
('anki-card-1756884013009-55', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Philippine law that ensures safety and purity of food, drugs and cosmetics made available to the public.', 'RA 3720', 'Republic Act No. 3720 is the foundational Philippine law (Foods, Drugs, Devices, and Cosmetics Act) enacted to ensure the safety and purity of foods, drugs, and cosmetics.

• RA 10611: Food Safety Act of 2013.
• PD 856: Code on Sanitation of the Philippines.', '["RA 10611","RA 3720","PD 856","RA 10817"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:41.746Z"'::jsonb),
('anki-card-1756884035125-56', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Local law that prescribes standards and procedures for drinking water, sanitary permit, healthy certificates, and quality and protection of foods, and structural components.', 'PD 856', 'Presidential Decree No. 856 (Code on Sanitation of the Philippines) prescribes local regulatory standards and procedures for drinking water, sanitary permits, health certificates, and structural food establishment components.', '["RA 10611","RA 3720","PD 856","RA 10817"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:45.950Z"'::jsonb),
('anki-card-1756884053024-57', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Also known as the Food Safety Act of 2013.', 'RA 10611', 'Republic Act No. 10611 is known as the Food Safety Act of 2013, strengthening the food safety regulatory system in the Philippines.', '["RA 10611","RA 3720","PD 856","RA 10817"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:50.113Z"'::jsonb),
('anki-card-1756884070673-58', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'All are mandatory labelling requirements except _____.', 'packaging material', 'Packaging material itself is a structural container component, whereas nutrition information, allergen information, and directions for use are mandatory statutory labeling requirements.', '["nutrition information","allergen information","directions for use","packaging material"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:53.929Z"'::jsonb),
('anki-card-1756884083239-59', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A systematic approach to identification, evaluation, and control of food safety hazards.', 'HACCP', 'Hazard Analysis Critical Control Point (HACCP) is a systematic preventive management approach to identifying, evaluating, and controlling food safety hazards.

• GMP / SSOP: Prerequisite hygiene programs.
• CODEX: International food standards code.', '["GMP","SSOP","CODEX","HACCP"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:26:58.253Z"'::jsonb),
('anki-card-1756884096088-60', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Also known as the Food Code.', 'CODEX', 'The Codex Alimentarius Commission (CODEX) is widely recognized internationally as the global "Food Code" establishing harmonized food standards.', '["GMP","SSOP","CODEX","HACCP"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:02.463Z"'::jsonb),
('anki-card-1756884108689-61', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Set of procedures needed in maintaining the sanitary conditions and practices of food manufacturing.', 'SSOP', 'Sanitation Standard Operating Procedures (SSOP) outline the routine set of procedures required to maintain sanitary conditions in food manufacturing.', '["GMP","SSOP","CODEX","HACCP"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:06.139Z"'::jsonb),
('anki-card-1756884123305-62', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A program to protect food from intentional contamination or adulteration that is behaviorally or ideologically motivated.', 'food defense', 'Food defense refers to programs and measures designed to protect the food supply from intentional contamination or adulteration driven by ideological, behavioral, or terrorist motives.

• Food fraud: Economically motivated adulteration.', '["GMP","food defense","food fraud","CODEX"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:11.034Z"'::jsonb),
('anki-card-1756884140403-63', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Formation of fishy odor is an example of ____ spoilage.', 'biochemical', 'The formation of a fishy odor in seafood is caused by enzymatic or chemical degradation of trimethylamine oxide (TMAO), classifying it as biochemical spoilage.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:15.706Z"'::jsonb),
('anki-card-1756884157119-64', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Maillard browning is an example of ____ spoilage.', 'chemical', 'Maillard browning is a non-enzymatic chemical reaction occurring between reducing sugars and amino acids.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:19.380Z"'::jsonb),
('anki-card-1756884172818-65', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Ripening is an example of ____ spoilage.', 'biochemical', 'Fruit ripening is driven by internal endogenous enzymatic and metabolic shifts, classifying it as biochemical change/spoilage.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:22.871Z"'::jsonb),
('anki-card-1756884189935-66', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Putrefaction is an example of ____ spoilage.', 'microbial', 'Putrefaction is the microbial decomposition and breakdown of proteins by bacteria under anaerobic conditions, resulting in foul-smelling compounds.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:26.923Z"'::jsonb),
('anki-card-1756884203817-67', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Toughening of okra is an example of ____ spoilage.', 'biochemical', 'The structural toughening of vegetables like okra involves internal cellular and enzymatic maturation processes, classifying it as biochemical change.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:30.945Z"'::jsonb),
('anki-card-1756884217550-68', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Browning of apples is an example of ____ spoilage.', 'biochemical', 'Enzymatic browning of apples is catalyzed by polyphenol oxidase reacting with oxygen, making it a biochemical process.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:34.624Z"'::jsonb),
('anki-card-1756884232500-69', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Freezer burn is an example of ____ spoilage.', 'physical', 'Freezer burn is a physical surface desiccation defect caused by moisture sublimation from frozen foods exposed to poor humidity or temperature fluctuations.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:02.393Z"'::jsonb),
('anki-card-1756884247516-70', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Formation of slime is an example of ____ spoilage.', 'microbial', 'The development of surface slime on foods is caused by the heavy multiplication and growth of spoilage microorganisms.', '["chemical","biochemical","physical","microbial"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:38.655Z"'::jsonb),
('anki-card-1756884264714-71', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'The most heat-resistant pathogen found in foods.', 'Clostridium botulinum', 'Clostridium botulinum produces heat-resistant bacterial endospores that represent the most heat-resistant pathogenic hazard encountered in low-acid food canning.', '["Staphylococcus aureus","Escherichia coli","Bacillus cereus","Clostridium botulinum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:43.433Z"'::jsonb),
('anki-card-1756884279231-72', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'All can be processed in a water bath except:', 'bangus in oil', 'Bangus (milkfish) in oil is a low-acid, oil-packed marine product that cannot be processed safely in a simple boiling water bath and requires commercial pressure canning to eliminate botulism risks.

• Papaya pickles / Pineapple chunks / Strawberry jam: High-acid or high-sugar foods safely processed in boiling water baths.', '["papaya pickles","pineapple chunks in sugar syrup","bangus in oil","strawberry jam"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:53.740Z"'::jsonb),
('anki-card-1756884295179-73', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Indicator enzyme for proper milk pasteurization.', 'phosphatase', 'Alkaline phosphatase is the native milk enzyme whose complete inactivation serves as the standard indicator proving that milk pasteurization temperatures and times were successfully achieved.', '["protease","phosphatase","lipase","peptidase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:27:57.086Z"'::jsonb),
('anki-card-1756884309012-74', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Step in canning done to remove air from within and around food.', 'exhausting', 'Exhausting is the thermal canning step where air and dissolved gases are driven out from inside the food and container headspace before sealing.', '["peeling","blanching","exhausting","cooling"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:01.014Z"'::jsonb)
