('anki-card-1756884322013-75', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Technique in can filling where cans are filled with raw or cold food before processing.', 'cold pack', 'Cold pack (raw pack) is the canning technique where raw or cold food items are packed directly into containers prior to thermal processing.', '["open kettle","cold start","hot pack","cold pack"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:07.383Z"'::jsonb),
('anki-card-1756884340177-76', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Microorganism of concern in low temperature preservation.', 'Listeria monocytogenes', 'Listeria monocytogenes is a psychrotrophic pathogen of primary concern in refrigerated and low-temperature food preservation because it survives and multiplies under cold conditions.', '["Listeria monocytogenes","Mycobacterium tuberculosis","Coxiella burnetii","Clostridium botulinum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:11.716Z"'::jsonb),
('anki-card-1756884356560-77', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Type of drying method where products can easily be rehydrated to almost its fresh from.', 'freeze drying', 'Freeze drying (lyophilization) sublimes ice directly from frozen foods under a vacuum, creating porous structures that allow rapid, near-perfect rehydration back to fresh form.', '["cabinet drying","freeze drying","osmotic drying","solar drying"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:16.134Z"'::jsonb),
('anki-card-1756884372426-78', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Drying treatment done to allow the dried products to equilibrate with the conditions of the environment.', 'conditioning', 'Conditioning is the post-drying equalization treatment where dried food batches are stored together so that moisture content distributes uniformly across all pieces.', '["sweating","sulfiting","blanching","conditioning"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:19.933Z"'::jsonb),
('anki-card-1756884388093-79', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Main substrate to produce acetic acid.', 'alcohol', 'Ethanol (alcohol) serves as the primary chemical substrate fermented by acetic acid bacteria (Acetobacter) to produce vinegar.', '["salt","sugar","tartaric acid","alcohol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:23.487Z"'::jsonb),
('anki-card-1756884409924-80', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Ingredient in pickles that is primary added to improve crispness.', 'alum', 'Alum (aluminum potassium sulfate) is traditionally added in small amounts during pickling to firm plant tissues and improve crispness.', '["vinegar","alum","sugar","salt"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:28.213Z"'::jsonb),
('anki-card-1756884425808-81', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A food additive that inhibits mold growth and rope development.', 'propionates', 'Propionates (such as calcium propionate) are chemical food additives used widely in baked goods to inhibit mold growth and prevent bacterial "rope" formation.', '["sorbates","propionates","sulfates","benzoates"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:31.365Z"'::jsonb),
('anki-card-1756884440607-82', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Yeast and mold inhibitors applied to cheeses, pickles, dried fruits, and jams.', 'sorbates', 'Sorbates (such as potassium sorbate) are effective antimicrobial agents used to inhibit yeasts and molds in cheeses, pickles, dried fruits, and jams.', '["sorbates","propionates","sulfates","benzoates"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:35.655Z"'::jsonb),
('anki-card-1756884453639-83', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Glucono delta lactone is an example of a/an _____.', 'acidulant', 'Glucono delta-lactone (GDL) is an organic acid precursor used as an acidulant in tofu manufacturing and baked goods.', '["preservative","emulsifier","acidulant","thickener"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:38.797Z"'::jsonb),
('anki-card-1756884466923-84', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Carageenan is an example of a/an _____.', 'thickener', 'Carrageenan (extracted from red seaweeds) is a hydrocolloid used extensively as a gelling and thickening agent in food processing.', '["preservative","emulsifier","acidulant","thickener"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:42.741Z"'::jsonb),
('anki-card-1756884485405-85', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Lecithin is an example of a/an _____.', 'emulsifier', 'Lecithin is a natural phospholipid acting as an effective surfactant and emulsifying agent.', '["preservative","emulsifier","acidulant","thickener"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:46.924Z"'::jsonb),
('anki-card-1756884500569-86', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Fermented except _____.', 'quickles', '"Quickles" (quick pickles) are produced via fast acid immersion rather than traditional biological fermentation.

• Dill pickles / Kimchi / Sour pickles: Produced via lactic acid fermentation.', '["quickles","dill pickles","kimchi","sour pickles"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:54.722Z"'::jsonb),
('anki-card-1756884518354-87', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Main substrate to produce lactic acid.', 'sugar', 'Fermenting lactic acid bacteria metabolize hexose sugars as their primary substrate to generate lactic acid.', '["salt","sugar","tartaric acid","alcohol"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:28:58.322Z"'::jsonb),
('anki-card-1756884533803-88', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Yogurt is a product of what type of fermentation?', 'lactic acid', 'Yogurt production relies on homofermentative lactic acid bacteria (Lactobacillus bulgaricus and Streptococcus thermophilus) that ferment milk lactose into lactic acid.', '["alcoholic","lactic acid","acetic acid","tartaric acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:38.256Z"'::jsonb),
('anki-card-1756884549285-89', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'All are constituents of jelly except:', 'starch', 'Traditional fruit jellies are structured by a gel network formed strictly from fruit pectin, sugar (sucrose), and acid, whereas starch is not a constitutional ingredient of true fruit jellies.

• Pectin / Sugar / Acid: The three essential biochemical components required to form a stable fruit jelly gel structure.', '["starch","pectin","sugar","acid"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:17:57.359Z"'::jsonb),
('anki-card-1756884564234-90', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Cold point of solid foods is located at the _____.', 'geometric center', 'The geometric center of a solid food container represents the "cold point"—the slowest-heating spot where thermal lethality calculations must be targeted during retorting.', '["top","¼ from the bottom","½ from the bottom","geometric center"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:44.679Z"'::jsonb),
('anki-card-1756884578916-91', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Type of heat transfer occurring inside the can of green peas in brine.', 'convection', 'Heat transfers primarily via convection (fluid circulation and liquid currents) inside liquid-medium canned foods like green peas suspended in brine.

• Conduction: Heat transfer through solid food masses.', '["conduction","convection","microwave","radiation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:51.505Z"'::jsonb),
('anki-card-1756884594717-92', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Compounds in woodsmoke that is known for their bacteriostatic effect.', 'pyroligneous compounds', 'Woodsmoke contains complex mixtures of phenols, organic acids, and pyroligneous compounds that provide characteristic smoke flavors and bacteriostatic preservation effects.', '["pyroligneous compounds","hydrolyzed lignin","burnt biomass","petroleum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:55.170Z"'::jsonb),
('anki-card-1756884614198-93', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A type of can defect characterized by one end may be slightly bulged but will remain flat when slightly pressed.', 'flipper', 'A flipper is a can defect where one end may appear flat or slightly bulged, but springs out and remains flat when tapped or gently pressed.', '["flipper","soft swell","springer","hard swell"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:58.622Z"'::jsonb),
('anki-card-1756884628465-94', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A type of can defect characterized by one end bulged and if pushed, the bulge transfers to the opposite end while the pushed end becomes flat.', 'springer', 'A springer is a can defect where one end is bulged, and pressing it causes the internal pressure to transfer, making the opposite end bulge while the pushed end flattens.', '["flipper","soft swell","springer","hard swell"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:30:03.582Z"'::jsonb),
('anki-card-1756884643664-95', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A type of can defect characterized by one end bulged and if pushed, the bulge springs back.', 'soft swell', 'A soft swell is a can defect where one end is bulged, but when pressed inward, the bulge yields and springs back due to internal gas pressure.', '["flipper","soft swell","springer","hard swell"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:06.316Z"'::jsonb),
('anki-card-1756884656529-96', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A type of can defect characterized by bulge on both ends and cannot be pressed inward by hand due to the internal pressure.', 'hard swell', 'A hard swell is a severe can defect characterized by bulging on both ends that cannot be pressed inward by hand due to high internal gas pressure generated by microbial spoilage.', '["flipper","soft swell","springer","hard swell"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:09.870Z"'::jsonb),
('anki-card-1756884671979-97', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'A type of can spoilage characterized by the development of acidity in food without swelling.', 'flat sour', 'Flat sour spoilage is a bacterial defect in canned foods where thermophilic bacteria produce acid from carbohydrates without generating gas, resulting in souring without can swelling.', '["flipper","flat sour","swell","foreign flavor"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:14.556Z"'::jsonb),
('anki-card-1756884687212-98', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'Also known as cold sterilization.', 'radiation', 'Ionizing radiation (gamma rays, electron beams) destroys microorganisms without raising food temperature significantly, earning it the designation "cold sterilization."', '["pasteurization","low temperature long time","high temperature short time","radiation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:26.345Z"'::jsonb),
('anki-card-1756884703644-99', NULL, 'anki-deck-1783610563139-1790433136793-gn4oo', 'An inert packaging material.', 'glass', 'Glass is considered an inert packaging material because it does not chemically react with food contents or leach compounds under normal storage conditions.', '["glass","plastic","metal","paper"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.526Z"'::jsonb, '"2026-11-09T10:29:30.588Z"'::jsonb),
('anki-card-1758074952987-0', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A number of tools and methods are available for nutrition professionals to use in evaluating dietary intakes of individuals and groups. Included among these are:', 'Dietary guidelines', '', '["Dietary guidelines","Measurements of nutrient density","10 Kumainments","BMI interpretation"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:10:02.990Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:10:02.990Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:10:03.059Z"'::jsonb),
('anki-card-1758074966519-1', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The continuing presence of nutrition-related disease makes it important that health professionals be able to assess nutritional status:', 'to identify who might benefit from nutrition intervention', 'The foundational clinical purpose of a nutritional assessment is to systematically evaluate an individual''s health status to pinpoint specific deficiencies, excesses, or metabolic risks. By collecting this baseline data, healthcare professionals can accurately identify exactly which patients are at risk and determine who will directly benefit from a targeted nutrition intervention or care plan.', '["To monitor and improve the nutritional status of its citizens","to identify who might benefit from nutrition intervention","to prevent the increase risk of morbidity and mortality","To prepare for nutrition researches"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:32:46.591Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:32:46.591Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:32:46.591Z"'::jsonb),
('anki-card-1758074983915-2', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The muscular contractions that move food through the GI tract are called:', 'Peristalsis', 'Peristalsis is a series of radially symmetrical, wave-like smooth muscle contractions and relaxations that automatically propel food, liquids, and waste forward through the entire gastrointestinal tract. It starts in the esophagus when you swallow a bolus of food and continues down through the stomach, small intestine, and large intestine.', '["Hydrolysis","Sphincters","Peristalsis","Bowel movement"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T15:13:09.314Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T15:13:09.314Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T15:13:09.533Z"'::jsonb),
('anki-card-1758075000833-3', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Although the RDAs are a useful standard in evaluating the usual dietary intake of groups and individuals, they cannot provide sufficient information to:', 'Determine the nutritional status of individuals or population groups', 'Recommended Dietary Allowances (RDAs) are quantitative guidelines representing dietary intake estimates designed to meet the nutrient requirements of 97% to 98% of healthy individuals. However, dietary intake alone is insufficient to establish an individual''s or a group''s actual nutritional status.', '["Determine the nutritional status of individuals or population groups","To design nutrition education programs","To enable the government to predict food needs of the population","to be used for planning and assessing diets for healthy people."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T11:48:33.424Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T11:48:33.424Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T11:48:33.652Z"'::jsonb),
('anki-card-1758075013565-4', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The main function of bile is to:', 'Emulsify fats', 'Bile is a fluid produced by the liver and stored in the gallbladder. Its primary role in the digestive system is the physical emulsification of dietary lipids (fats) in the small intestine. Because fats are hydrophobic (water-fearing) and naturally clump into large droplets, pancreatic enzymes cannot easily break them down. Bile acts as a natural biological detergent, breaking these large fat globules apart into millions of tiny droplets. This dramatically increases the surface area, allowing pancreatic lipase enzymes to efficiently bind and digest the fats.

• Catalyse hydrolysis: Hydrolysis (chemical breakdown using water) is catalyzed exclusively by digestive enzymes (like lipase or amylase); bile contains no enzymes.
• Neutralize stomach acidity: While bile is slightly alkaline, the main job of neutralizing highly acidic stomach chyme belongs to sodium bicarbonate secreted by the pancreas.
• Slow protein digestion: Bile does not interact with, slow down, or regulate the digestion of dietary proteins.', '["Emulsify fats","Catalyse hydrolysis","Slow protein digestion","Neutralize stomach acidity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:09:38.667Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:09:38.667Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:09:38.736Z"'::jsonb),
('anki-card-1758075029548-5', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which nutrients seem to protect against age related macular degeneration?', 'zinc and copper', 'The landmark Age-Related Eye Disease Study (AREDS) and AREDS2 clinical trials conducted by the National Eye Institute demonstrated that a specific combination of antioxidants and minerals—including zinc paired with copper alongside vitamins C and E—significantly reduces the risk of advanced age-related macular degeneration (AMD) progression.

High-dose zinc supplementation can competitively block copper absorption in the gastrointestinal tract, leading to a secondary copper deficiency and sideroblastic anemia. Therefore, a small, balanced amount of copper is combined directly with the zinc formulation to protect the patient''s overall health and prevent copper-deficiency complications.', '["zinc and copper","Lecithins","lipoprotein","Amino acids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:13:24.270Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:13:24.270Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:13:24.476Z"'::jsonb),
('anki-card-1758075044313-6', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The dietary recall method:', 'Interviewer ask for the past 24 hours food and beverage consumed', 'A 24-hour dietary recall requires an interviewer to record all foods and beverages ingested over the preceding day.', '["Interviewer ask for the past 24 hours food and beverage consumed","Is quickly administered","Represents the individual’s usual intake","Determines the frequency of consumption of a certain food."]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:39:31.236Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:39:31.236Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:03:34.216Z"'::jsonb),
('anki-card-1758075060864-7', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Anthropometry reflects:', 'Body size', 'The word anthropometry literally translates from Greek roots to mean "human measurement" (anthropos = human, metron = measure). It refers to the physical measurement of the human body''s external dimensions.

Anthropometric measurements—such as height, weight, circumferences (waist/hip), and limb lengths—primarily reflect body size, stature, and physical proportions. It tells you how big or what shape a person''s body structure is.', '["The total body mass","Body composition","Total quantity of fat in the body","Body size"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:39:17.180Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:39:17.180Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:39:17.244Z"'::jsonb),
('anki-card-1758075076228-8', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A better predictor of obesity', 'Skinfold thickness', 'While Body Mass Index (BMI) is the most widely used public health screening tool for weight status, it relies strictly on total weight and height. Because of this, BMI cannot differentiate between lean muscle mass and adipose tissue (fat mass).

Skinfold thickness is a better predictor of obesity (excess adiposity) because it measures the subcutaneous fat layers directly at specific sites on the body. This allows it to provide a more accurate estimation of actual body composition and true body fatness compared to height-and-weight-based calculations.', '["Height and weight tables","Relative weight","Body mass index","Skinfold thickness"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T03:06:19.428Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T03:06:19.428Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T03:06:19.508Z"'::jsonb),
('anki-card-1758075091393-9', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A malnourished patient has just begun to eat after days without significant amounts of food. Which of the following blood tests would change most quickly as the patient’s nutrition status improve?', 'Serum electrolytes', 'When a malnourished patient begins eating, circulating insulin increases in response to dietary carbohydrates. Insulin stimulates the Na+/K+-ATPase pump and cellular uptake of glucose, driving potassium, magnesium, and inorganic phosphate rapidly from the extracellular fluid into the intracellular space. This acute biochemical shift can cause severe hypokalemia, hypomagnesemia, and hypophosphatemia within hours to days of refeeding, making serum electrolytes the fastest-responding blood test compared to slowly synthesized visceral proteins.', '["Albumin","Transferrin","Serum electrolytes","Retinol-binding protein"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:43:22.867Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:43:22.867Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:43:23.076Z"'::jsonb),
('anki-card-1758075110527-10', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Is a device used for determining the weight and height of a patient who can’t stand', 'knee ht caliper', 'When a patient is non-ambulatory, bedridden, or unable to stand straight independently (due to paralysis, frailty, or severe kyphosis), a knee height caliper is the clinical gold standard tool used to estimate stature.

The healthcare professional uses this large sliding caliper to measure the distance from the sole of the heel to the top of the anterior thigh while the knee and ankle are bent at a strict 90-degree angle. The resulting knee height measurement in centimeters is then plugged into specialized mathematical formulas (such as the Chumlea equations) to calculate the patient''s estimated total height and approximate weight.', '["tricep skinfold","knee ht caliper","MAC","claviers ht & wt scale"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:20:22.970Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:20:22.970Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:20:23.035Z"'::jsonb),
('anki-card-1758075147775-11', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A method of measuring body composition which uses electrical current', 'biolectrical impedance', 'Bioelectrical impedance analysis (BIA) calculates total body fat, muscle mass, and water content by sending a weak, painless electrical current through the body. This works because different types of body tissue have varying levels of resistance:

• Lean tissues (like muscle) have high water and electrolyte content, meaning they conduct electricity very easily with low resistance.
• Fat tissue is mostly water-free and acts as an insulator, creating higher resistance (impedance) against the electrical current.', '["biolectrical impedance","ultrasound","X-ray","liposuction"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:34:53.332Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:34:53.332Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:34:53.410Z"'::jsonb),
('anki-card-1758075162206-12', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The health care professional advising an elderly patient with constipation encourages the patient to:', 'Gradually add high-fiber foods to the diet', 'Adding fiber too quickly can cause cramping, gas, and bloating. A gradual increase paired with adequate hydration allows the gastrointestinal tract to adjust smoothly and promotes regular bowel movements.', '["Consume a low-fat diet rich in potassium","Consume a high-protein diet rich in calcium","Gradually add high-fiber foods to the diet","Eliminate gas-forming foods from the diet"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:25:03.232Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:25:03.232Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:00:34.638Z"'::jsonb),
('anki-card-1758075175872-13', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Assessing the nutritional status of hospitalized patients involves:', 'Identifying those at nutritional risk', 'Nutritional screening and assessment aim to rapidly identify hospitalized individuals at high risk for malnutrition complications.', '["Identifying those at nutritional risk","Nutrition support that are reserved for research applications","Estimating energy expenditure","Raising professional awareness of poor patients nutritional status"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:39:21.118Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:39:21.118Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:02:09.381Z"'::jsonb),
('anki-card-1758075192638-14', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'An 8 month old is admitted with steatorrhea and diarrhea with frequent foul smelling bulky stools.
The baby’s mother reports she just introduced cereal in his diet. A probable diagnosis is:', 'gluten enterophathy', 'Gluten enteropathy (commonly known as Celiac disease) is an autoimmune reaction to gluten, a protein found in wheat, barley, and rye. Symptoms typically appear shortly after cereal is introduced into the infant''s diet (usually around 6 to 9 months of age).

The immune response damages the villi of the small intestine, leading to severe malabsorption. This manifests as chronic diarrhea and steatorrhea (excess fat in the stool), which causes the stools to be characteristically bulky, foul-smelling, and greasy.', '["Tropical sprue","regional enteritis","gluten enterophathy","ulcerative colitis"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:37:44.702Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:37:44.702Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:37:44.702Z"'::jsonb),
('anki-card-1758075205287-15', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The nutrition care plan for a patient with GERD would include:', 'avoid eating within 3 hours of retiring', 'Going to bed with a full stomach increases pressure on the lower esophageal sphincter (LES) and allows gastric contents to pool. Combined with the loss of gravity when lying flat, this triggers severe acid reflux. Avoiding food for at least 3 hours before sleeping ensures the stomach has sufficient time to empty, drastically reducing nighttime GERD symptoms.

• Increase dietary fat intake: High-fat foods delay gastric emptying and relax the LES, which significantly worsens reflux.
• Recline immediately after meals: Lying down right after eating eliminates gravity''s helpful downward pull, allowing acid to flow directly up the esophagus.
• Caffeinated products: Caffeine chemically relaxes the smooth muscle of the LES, enabling stomach acid to leak upward easily.', '["recline immediately after meals","increase dietary fat intake","avoid eating within 3 hours of retiring","caffeinated products"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:29:47.912Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:29:47.912Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:29:47.912Z"'::jsonb),
('anki-card-1758075219705-16', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'In critically ill persons or those with burns involving > 10% of body surface are is burned 6, 25 grams of protein is recommended.', 'for every 100 NPC consumed', 'In clinical nutrition, the relationship between carbohydrate/fat energy and protein is managed using the Non-Protein Calorie-to-Nitrogen ratio (NPC:N). This calculation ensures that a critically ill patient is receiving enough non-protein calories to satisfy basic metabolic needs, preventing the body from burning its own protein stores for energy.

• The Conversion Standard: Exactly 6.25 grams of protein yields 1 gram of pure nitrogen.
• The Burn Protocol: For healthy individuals or mildly stressed patients, a standard ratio of 150 non-protein calories for every 1 gram of nitrogen (150:1) is entirely sufficient. However, patients with severe trauma or burns involving >10% of their Total Body Surface Area (TBSA) enter an extreme hypermetabolic state. To support aggressive skin tissue healing, prevent immunoincompetence, and minimize negative nitrogen balance, they require a much denser protein distribution: 1 gram of nitrogen (6.25g protein) for every 100 NPC consumed (a 100:1 ratio).', '["for every 150 NPC consumed","for every 100 NPC consumed","for every 200 NPC consumed","for every 1000 calories consumed"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T15:05:54.940Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T15:05:54.940Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T15:05:55.145Z"'::jsonb),
('anki-card-1758075236204-17', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Is a muscle metabolite excreted in urine used to quantitate muscle mass', 'Creatinine', 'Creatinine is a chemical waste molecule generated continuously by normal skeletal muscle metabolism. It is produced from the breakdown of creatine phosphate, an energy-storage molecule in muscles. Because muscle tissue produces a steady, fixed amount of creatinine every day, measuring the total amount of creatinine excreted in a 24-hour urine collection is directly proportional to a person''s total skeletal muscle mass (lean body mass).

	× BUN: Blood Urea Nitrogen is a waste product of protein breakdown formed in the liver. It spikes heavily with a high-protein meal, dehydration, or kidney failure, making it a poor tool for measuring physical muscle mass.
	× Albumin & Transferrin: These are visceral transport proteins synthesized by the liver. They are used to help assess general protein status or iron transport, but they cannot measure skeletal muscle mass.', '["Albumin","Transferrin","Creatinine","BUN"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:32:35.756Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:32:35.756Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:32:35.756Z"'::jsonb),
('anki-card-1758075250637-18', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Included among the serum proteins used to assess protein nutriture are', 'All of the above', 'Albumin, transferrin, and prealbumin are visceral transport proteins evaluated in clinical nutrition assessments.', '["Albumin","Transferrin","Pre albumin","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T04:58:10.400Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T04:58:10.400Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:02:53.468Z"'::jsonb),
('anki-card-1758075266018-19', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A patient is admitted to the ICU with the foll symptoms and labs: cachexia, ascites, nausea, vomiting, no change in mental status, serum albumin of 2.5 gm/dl and elevated liver function tests. Recommend?', 'Fluid restriction, 2 gms, Na, moderate CHON', 'This clinical picture describes a patient in the ICU with decompensated liver disease (cirrhosis) presenting with ascites (fluid accumulation in the abdomen) and severe hypoalbuminemia (serum albumin of 2.5 g/dL). The key to managing these combined complications guides the macro-nutritional recommendations:
• 2 grams Na & Fluid Restriction: The presence of ascites means the body is severely retaining sodium and water due to portal hypertension and activation of the renin-angiotensin-aldosterone system. Restricting sodium to 2 grams per day and implementing a fluid restriction are the primary medical nutrition therapies (MNT) used to control and decrease abdominal fluid accumulation.
• Moderate CHON (Protein): The patient is exhibiting clear signs of muscle wasting (cachexia), meaning they critically need protein to repair tissue and prevent further wasting. However, because they are critically ill in the ICU with highly elevated liver function tests, protein must be introduced carefully at a moderate level (rather than aggressively high or restricted low) to monitor their clinical tolerance and ensure they do not trigger hepatic encephalopathy, especially since they currently have a normal mental status.', '["High CHON, low kcal, 4 gms Na","Fluid restriction, 2 gms, Na, moderate CHON","Fluid restriction, low CHON, 2 grams Na","High CHON, high sodium, push fluids"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:46:04.288Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:46:04.288Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:46:04.515Z"'::jsonb),
('anki-card-1758075279767-20', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'It is the most widely used screening test for iron-deficiency anemia', 'Hemoglobin', 'Hemoglobin measurement in whole blood is universally recognized as the most common, cost-effective, rapid, and widely accessible screening test for anemia.

Because iron deficiency is the leading cause of anemia worldwide, public health screenings routinely measure hemoglobin levels as a quick proxy to catch potential cases of iron-deficiency anemia. If a patient''s hemoglobin falls below standard thresholds, it triggers clinicians to look closer.

• Ferritin: The definitive diagnostic gold-standard to check total iron stores, but too expensive for mass initial screening.
• Hematocrit: Measures red blood cell volume ratio; less sensitive than direct hemoglobin testing.
• CBC: A full comprehensive panel. While it contains the hemoglobin measurement, hemoglobin itself is the target marker.', '["Hemoglobin","Hematocrit","Ferritin","CBC"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:14:26.113Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:14:26.113Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:14:26.175Z"'::jsonb),
('anki-card-1758075294368-21', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Marasmus develops from:', 'Inadequate protein and energy intake', 'Marasmus is a severe form of protein-energy malnutrition (PEM) resulting from general starvation. It occurs when an individual experiences a chronic, severe deficit in both total calories (energy) and protein across all major macronutrients. This causes the body to exhaustively break down its own subcutaneous fat stores and muscle tissue for survival, leading to a characteristically shriveled and wasted appearance.', '["Too much fat clogging the liver","Megadoses of amino acid supplements","Inadequate protein and energy intake","Excessive fluid intake causing edema"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:40:59.300Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:40:59.300Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T13:40:59.513Z"'::jsonb),
('anki-card-1758075306832-22', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Tests usually performed using an automated chemistry analyzer that are useful in diagnosing and managing disease.*', 'Blood chemistry', 'An automated chemistry analyzer is a specialized laboratory instrument designed to rapidly process blood serum, plasma, or urine samples. It measures the concentrations of various chemical substances in the body—such as electrolytes (sodium, potassium), renal markers (BUN, creatinine), liver enzymes (ALT, AST), and metabolic indicators (glucose, cholesterol). These blood chemistry profiles are vital for diagnosing and managing wide-ranging systemic diseases.', '["Blood chemistry","Ultrasonography","Endoscopy","CT Scan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:09:59.696Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:09:59.696Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:09:59.764Z"'::jsonb),
('anki-card-1758075323966-23', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Process of sending and receiving messages*', 'Communication', 'Communication is the fundamental two-way process of transmitting and receiving information.', '["Collaboration","Communication","Consultation","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:39:02.281Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:39:02.281Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:03:28.335Z"'::jsonb),
('anki-card-1758075336099-24', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The simplest & most practical available method of determining the extent of obesity especially for clinical use:', 'BMI', 'BMI is universally recognized as the simplest and most practical method for determining the extent of obesity in clinical settings. Because it only requires a patient''s height and weight (kg/m²), it is non-invasive, takes seconds to calculate, costs absolutely nothing, and does not require specialized equipment or advanced training.', '["body composition","body fat analysis","BMI","skinfold measurement"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:38:58.051Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:38:58.051Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:38:58.051Z"'::jsonb)
