INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1758076295686-75', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Types of formula that serve as sources of single nutrients are called:', 'Modular', 'Modular enteral formulas are specialized nutritional products that contain single macronutrients (such as isolated protein powders, MCT oil fats, or glucose polymers) allowing clinicians to custom-tailor and supplement a patient''s exact nutritional regimen.

• Blenderized formulas: Contain whole food ingredients blended into liquid form.
• Intact (polymeric) formulas: Contain complete, unhydrolyzed proteins, carbohydrates, and fats for patients with normal digestive function.
• Hydrolyzed formulas: Contain pre-digested, broken-down protein peptides and amino acids for malabsorption.', '["Blenderized","Intact","Hydrolyzed","Modular"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T15:13:16.024Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T15:13:16.024Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:04:16.209Z"'::jsonb),
('anki-card-1758076318153-76', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A formula that approximates the osmolality of normal blood serum', 'B and C', 'Any enteral formula, IV fluid, or parenteral solution that closely mimics or approximates this normal biological range is classified as an isotonic solution. Because it exerts the same osmotic pressure as plasma, it prevents shifting fluid across cell membranes, minimizing gastrointestinal side effects like cramping or diarrhea.

The normal osmolality of human blood serum ranges between 275 and 295 mOsm/kg (clinically rounded to 300 mOsm/L for standard nutrition formulations).

× A hypertonic formula is any enteral nutrition (tube feeding) or intravenous (IV) solution that has a higher concentration of solutes than normal human blood serum.
While normal blood serum sits at approximately 275 to 295 mOsm/kg (clinically rounded to 300 mOsm/L), a hypertonic formula typically carries an osmolality greater than 300 to 400 mOsm/L.', '["Is called hypertonic formula","has an osmolality of approximately 300 millisosmoles per liter","is called an isotonic formula","B and C"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T11:52:03.078Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T11:52:03.078Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T11:52:03.347Z"'::jsonb),
('anki-card-1758076360666-77', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which of the following feeding tube placement sites would be the most appropriate for a client who is expected to be on a tube feeding for less than 4 weeks?', 'nasogastric', 'A nasogastric (NG) tube is explicitly indicated for short-term enteral nutrition expected to last less than 4 weeks. Because it is non-invasive, cost-effective, and can be placed quickly at the bedside without surgical, endoscopic, or radiologic intervention, it is the primary choice for temporary feeding needs.

	• Gastrostomy, Jejunostomy, and a tube enterostomy are invasive, surgically, radiologically, or endoscopically placed access routes. These options are reserved for long-term enteral nutrition support lasting longer than 4 to 6 weeks.', '["Gastrostomy","jejunostomy","nasogastric","tube enterostomy"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T11:17:52.490Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T11:17:52.490Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T11:17:52.673Z"'::jsonb),
('anki-card-1758076389332-78', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Hydrolyzed fromulas', 'should be used only for clients who can’t adequately digest and absorb nutrients', 'Hydrolyzed formulas (also known as elemental or semi-elemental formulas) contain proteins that have been pre-digested or broken down into tiny peptide chains or individual amino acids. Because they are highly broken down, they are reserved strictly for patients with severe gastrointestinal dysfunction—such as short bowel syndrome, severe malabsorption, pancreatic insufficiency, or Crohn''s disease—who cannot process intact nutrients.', '["Are the best type to offer a client","Cost less than standard formula","are less likely than other formulas to cause complications","should be used only for clients who can’t adequately digest and absorb nutrients"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T12:53:10.948Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T12:53:10.948Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T12:53:11.164Z"'::jsonb),
('anki-card-1758076402565-79', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'In what ways can nutrition affect quality of care', 'all of the above', 'Proper clinical nutrition prevents disease, maintains independent functioning, and optimizes both mental and physical health outcomes.', '["It can improve the client’s ability to function independently","It can prevent diseases","It can improve a client’s mental and physical health","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:10:12.193Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:10:12.193Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:00:59.474Z"'::jsonb),
('anki-card-1758076414997-80', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which of the following is not eliminated on a gluten restricted diet', 'rice', 'Rice does not contain the protein gluten. It is completely safe to eat and is one of the most common carbohydrate substitutes used for patients on a gluten-restricted diet.

The Grains to Eliminate:
	• Barley and Wheat are primary sources of gluten and must be strictly eliminated to prevent damage to the small intestine.
	• Oats are typically eliminated or restricted in traditional clinical question banks (often recalled using the acronym BROW: Barley, Rye, Oats, Wheat) due to a remarkably high risk of agricultural cross-contamination with wheat during harvesting and processing.', '["Wheat","rice","barley","Oats"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T11:19:28.655Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T11:19:28.655Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T11:19:28.876Z"'::jsonb),
('anki-card-1758076429379-81', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which of the following foods would you recommend to someone interested in relieving constipation.', 'Legumes', 'Legumes (which include beans, lentils, chickpeas, and peas) are packed with exceptionally high amounts of both soluble and insoluble dietary fiber.
	• Insoluble fiber adds essential roughage and physical bulk to the stool, stimulating the intestinal walls to contract and push waste forward.
	• Soluble fiber absorbs water inside the colon, turning into a gel-like texture that softens hard, dry stools and makes them much easier to pass.', '["Legumes","Milk","Chicken","White bread"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T12:51:49.728Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T12:51:49.728Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T12:51:49.956Z"'::jsonb),
('anki-card-1758076445262-82', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The damage sugar does to teeth relates to:', 'all of the above', 'Dental caries (cavities) develop based on a combination of what you eat, how the food behaves structurally, and how long your teeth are exposed to it:

• The CHO (Carbohydrate) content of the food: Simple carbohydrates (sugars) serve as the primary fuel source for oral bacteria like Streptococcus mutans. These bacteria ferment the carbohydrates, generating an acidic byproduct that drops the pH in your mouth and erodes tooth enamel.
• How sticky the food is: Sticky foods (such as dried fruits, caramels, or crackers) lodge tightly into the pits, fissures, and grooves of the teeth. This physical stickiness prevents saliva from washing the food away, creating a prolonged buffet for cavity-causing bacteria.
• The length of time the food stays in the mouth: The total duration of exposure is critical. Sucking on hard candies, sipping sugary drinks slowly over hours, or having sticky food stuck to your teeth extends the "acid attack" window. Frequent, long-lasting exposure gives bacteria more time to produce acid, making it far more damaging than eating the same amount of sugar all at once.', '["The CHO content of the food","the length of time the food stays in the mouth","how sticky the food is","all of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T05:55:35.303Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T05:55:35.303Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T05:55:35.371Z"'::jsonb),
('anki-card-1758076465078-83', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The main route for excretion of cholesterol from the body is:', 'in the feces', 'The human body cannot break down or degrade the complex sterol rings of cholesterol into smaller energy molecules. Because of this, the liver acts as the primary clearing house for excess cholesterol via a process called reverse cholesterol transport.

The liver eliminates cholesterol through two main pathways that empty into the digestive system:
	1. Converting it directly into bile acids (or bile salts).
	2. Secreting it directly into the bile as unesterified (free) cholesterol.

This bile is sent into the small intestine to assist in fat digestion. While a large percentage of bile salts are recycled, the remaining unabsorbed cholesterol and its metabolites travel down the GI tract and are excreted out of the body in the feces.', '["via the lungs","in the urine","in the feces","through the skin"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:39:36.980Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:39:36.980Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:39:37.052Z"'::jsonb),
('anki-card-1758076479228-84', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A person is in positive nitrogen balance during:', 'growth', 'Growth, pregnancy, and tissue healing are characterized by positive nitrogen balance where protein synthesis exceeds breakdown.', '["Old age","exercise","growth","adulthood"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T13:19:38.239Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T13:19:38.239Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:03:21.164Z"'::jsonb),
('anki-card-1758076497927-85', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Severe marasmus', 'Results in low resistance to disease', 'Severe marasmus is a profound form of protein-energy malnutrition (PEM) caused by chronic starvation. Because the body lacks the vital amino acids and energy required to maintain regular cellular functions, it shuts down non-essential processes. This causes severe atrophy of lymphoid tissues (like the thymus) and sharply reduces the production of white blood cells and antibodies, resulting in dangerously low resistance to infectious diseases.

Other Choices:
	• It dramatically affects "brain development," leading to intellectual disabilities, behavioral changes, and impaired cognitive function.
	• While it is overwhelmingly most common in infants and young children under 5 due to high developmental demands, it can also be found in "adults suffering from extreme famine or wasting diseases."
	• It actually causes "decreased body temperature (hypothermia)". Because these individuals lose virtually all their insulating subcutaneous fat and have a severely depressed basal metabolic rate, their bodies struggle to generate heat.', '["Results in low resistance to disease","Causes increased body temperature","is found only in adults","affects physical development but leaves the brain unaffected"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:37:30.654Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:37:30.654Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:37:30.654Z"'::jsonb),
('anki-card-1758076515027-86', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'What is the primary cause of edema in kwashiorkor', 'Proteins and hormones diminish and fluid leaks out of the blood', 'Kwashiorkor is a severe form of acute malnutrition caused by a profound deficiency in dietary protein. The primary physiological mechanism behind the characteristic bilateral pitting edema (swelling) is the drop in circulating blood proteins:

1. Decreased Albumin Production: Because the body lacks amino acids, the liver cannot synthesize essential plasma proteins, particularly albumin.
2. Loss of Oncotic Pressure: Albumin acts like a "water magnet" inside blood vessels, maintaining colloid osmotic (oncotic) pressure to keep fluid within the intravascular space.
3. Fluid Leakage: When albumin levels drop heavily, this holding pressure collapses. Fluid leaks out of the blood vessels and into the surrounding interstitial tissues, causing swelling in the abdomen (ascites), feet, and face.', '["Proteins and hormones diminish and fluid leaks out of the blood","Lipoprotein synthesis is diminished causing fat to accumulate","Protein is lost from the heart muscle resulting in a weak heartbeat","The kidneys stop excreting fluids and they accumulate in the abdomen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:41:02.685Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-07T07:41:02.685Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:41:02.759Z"'::jsonb),
('anki-card-1758076530209-87', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'A bolus is', 'Portion of food swallowed at one time', 'During the mechanical process of chewing, food is broken down by the teeth and mixed with lubricating saliva inside the oral cavity. The tongue then rolls this softened, cohesive mixture into a smooth mass. This specific mass of food, which is swallowed at one time to travel down the esophagus, is called a bolus.

	• Enzyme that hydrolyzes starch: This describes amylase, an enzyme found in saliva and pancreatic juices that initiates the breakdown of starches.
	• Portion of partially digested food expelled by the stomach into the duodenum: This describes chyme, which is the semi-liquid mixture of partially digested food and gastric juices expelled by the stomach into the duodenum.
	• Sphincter muscle separating the stomach from the small intestine: This describes the pyloric sphincter, the anatomical muscular ring that controls the passage of food from the stomach into the small intestine.', '["Sphincter muscle separating the stomach from the small intestine","Portion of food swallowed at one time","Enzyme that hydrolyzes starch","Portion of partially digested food expelled by the stomach into the duodenum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:34:34.019Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:34:34.019Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:34:34.019Z"'::jsonb),
('anki-card-1758076546691-88', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The enzyme that breaks down starch in the mouth:', 'Salivary amylase', 'Chemical digestion of carbohydrates begins directly in the oral cavity. When food is chewed, the salivary glands secrete saliva containing salivary amylase (historically called ptyalin). This enzyme targets complex, long-chain starches (polysaccharides) and breaks them down via hydrolysis into simpler disaccharide sugars, primarily maltose.

	× Carbohydrates: This is the general macromutrient category that includes starches and sugars, not an enzyme.
	× Gastric protease: Proteases (such as pepsin) break down proteins into amino acids. Gastric protease is active inside the highly acidic environment of the stomach, not the mouth.
	× Lipase: This enzyme is specialized to break down lipids (fats and oils) into fatty acids and glycerol.', '["Carbohydrates","Lipase","gastric protease","Salivary amylase"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T11:39:12.293Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T11:39:12.293Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T11:39:12.506Z"'::jsonb),
('anki-card-1758076560842-89', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The stomach empties into the', 'duodenum', 'Following mechanical and chemical digestion in the stomach—driven by hydrochloric acid and pepsin—the pyloric sphincter regulates the passage of acidic chyme into the duodenum. In the duodenal lumen, Brunner''s glands secrete alkaline mucus, and secretions from the pancreas and gallbladder (delivering bicarbonate, lipases, proteases, and bile acids) enter via the hepatopancreatic ampulla to neutralize gastric acid and initiate the enzymatic breakdown of macronutrients.', '["Ileum","esophagus","jejunum","duodenum"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:38:20.300Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:38:20.300Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:38:20.300Z"'::jsonb),
('anki-card-1758076580440-90', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The major digestive enzyme secreted by the stomach is', 'Pepsin', 'Pepsin is the primary digestive enzyme produced and secreted by the stomach. Specialized cells in the stomach lining called chief cells release it in an inactive form called pepsinogen. The highly acidic hydrochloric acid (HCl) in the stomach then activates it into pepsin, allowing it to begin breaking down dietary proteins into smaller peptide chains.

	× Lipase: While the stomach secretes a small amount of gastric lipase, it plays a minor role. The overwhelming majority of lipid-digesting lipase is produced by the pancreas and active in the small intestine.
	× Disaccharides: This is a type of sugar (like lactose or maltose), not an enzyme. The enzymes that break them down (disaccharidases) are produced in the brush border of the small intestine.
	× Amylase: This starch-digesting enzyme is secreted by the salivary glands and the pancreas. Any salivary amylase swallowed in a food bolus is rapidly inactivated by the strong acid environment of the stomach.', '["Amylase","Pepsin","Lipase","Disaccharides"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:36:59.371Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-07T07:36:59.371Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:36:59.371Z"'::jsonb),
('anki-card-1758076595087-91', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'The foods which would be digested most quickly are', 'Sugar cookies', 'Sugar cookies are predominantly composed of refined flour and simple sugars. Simple sugars require very little chemical processing and are rapidly broken down by enzymes, leading to swift stomach emptying and fast absorption into the bloodstream.

The other options—Peanut butter sandwich and milk, Beef stew, and a Hamburger—contain high amounts of protein and complex fats. Fat is the slowest macronutrient to digest and significantly delays gastric emptying, keeping those foods in the stomach much longer.', '["Sugar cookies","Peanut butter sandwich and milk","Beef stew","Hamburger"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T09:44:22.204Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T09:44:22.204Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T09:44:22.420Z"'::jsonb),
('anki-card-1758076608921-92', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which of the following does not secrete digestive enzymes', 'Esophagus', 'The esophagus is purely a muscular transit tube. Its sole function is to transport food from the mouth to the stomach via rhythmic muscle contractions called peristalsis. It contains mucous glands to lubricate the food passage, but it does not produce or secrete any digestive enzymes.

• Pancreas: Secretes major enzymes like pancreatic lipase, amylase, and proteases into the small intestine.
• Stomach: Secretes gastric juice containing the protein-digesting enzyme pepsin.
• Small intestine: Produces its own brush-border enzymes like maltase, sucrase, and lactase.', '["Small intestine","Pancreas","Esophagus","Stomach"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:18:45.514Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:18:45.514Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:18:45.581Z"'::jsonb),
('anki-card-1758076628088-93', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'When nutrients enter the blood vessels from the small intestine, they are first transported to the:', 'Liver', 'When water-soluble nutrients (like monosaccharides, amino acids, water-soluble vitamins, and minerals) are absorbed through the intestinal mucosa, they enter the capillaries of the mesenteric veins. This blood immediately pools into the hepatic portal vein, which transports the nutrients directly to the liver first. The liver acts as the body''s primary metabolic processing center, filtering toxins, storing nutrients, and regulating their release before they enter general circulation.', '["Liver","kidney","cells of the body","brain"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:17:25.815Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:17:25.815Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:17:25.888Z"'::jsonb),
('anki-card-1758076640752-94', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Nutrients that are digested in the small intestine are:', 'Carbohydrate, fat and protein', 'The small intestine serves as the primary site for the final chemical digestion and absorption of all three major macronutrients:
✓ Carbohydrates: Pancreatic amylase and enzymes along the intestinal brush border break down starches and complex sugars into simple sugars (like glucose).
✓ Fats: Bile from the liver emulsifies fat globules, allowing pancreatic lipase to efficiently break them down into fatty acids and glycerol.
✓ Proteins: While protein digestion begins in the stomach, pancreatic and intestinal enzymes (like trypsin and chymotrypsin) finish breaking down peptides into absorbable amino acids within the small intestine.

× Water and Minerals: These items are absorbed by the body but do not undergo mechanical or enzymatic digestion (breakdown).
× Fiber: Humans lack the digestive enzymes required to break down dietary fiber. Fiber passes through the small intestine largely untouched and travels down to the large intestine.', '["Carbohydrate, fat and protein","Fat, water and fiber","Protein, vitamins and fiber","Water, fiber and minerals"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-07T12:16:00.163Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-06T12:16:00.163Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-06T12:16:00.397Z"'::jsonb),
('anki-card-1758076653736-95', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'You are working with a client who complains of constipation. Which of the following would you recommend?', 'All of the above', 'Managing and preventing constipation effectively relies on a combination of foundational lifestyle and dietary adjustments:

• Drink plenty of water: Adequate hydration is essential to soften stools and prevent the colon from absorbing excess water, making them easier to pass.
• Eat more fiber: Dietary fiber adds bulk and holds fluids, which improves stool shape, weight, and transit through the colon.
• Exercise more: Regular physical activity naturally stimulates blood flow to the abdomen and improves the muscular movements (peristalsis) of the colon to move stool forward.', '["Drink plenty of water","Exercise more","Eat more fiber","All of the above"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:18:31.476Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:18:31.476Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:18:31.545Z"'::jsonb),
('anki-card-1758076673635-96', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Food recording can particularly be valuable for', 'Overweight people', 'Food recording (also known as keeping a food diary or journal) is particularly valuable as a behavioral and therapeutic intervention for overweight people.

Clinical research consistently shows that individuals tracking weight loss goals double their success rates simply by writing down what they eat and drink. Food records address the primary psychological and behavioral challenges of weight management by:

1. Eliminating Mindless Eating: It forces individuals to pause and acknowledge every snack, beverage, or bite.
2. Correcting Perception vs. Reality: Overweight individuals frequently under-report or underestimate their actual caloric intake. Logging food brings accurate awareness to portion sizes and hidden calories.
3. Identifying Emotional Triggers: It highlights behavioral patterns, such as eating out of stress, boredom, or fatigue rather than actual physical hunger.', '["Overweight people","Teenagers","Older adults","Women"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T07:17:11.680Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T07:17:11.680Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T07:17:11.748Z"'::jsonb),
('anki-card-1758076688751-97', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'Which of the following is used in infancy to assess brain development', 'head circumference', 'Head circumference is the standard anthropometric metric monitored in infants to track normal neurological and brain growth.', '["Measure of abdominal girth","fatfold measurement","head circumference","height and weight"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T05:57:12.301Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T05:57:12.301Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-11-09T12:01:54.236Z"'::jsonb),
('anki-card-1758076700433-98', NULL, 'anki-deck-1783610578120-1790433145987-lrcjh', 'In people who are ill, significant weight loss may be masked by:', 'Fluid retention', 'When a person is ill, the body often holds onto extra water in the tissues or body cavities—a condition known as fluid retention or edema. Water is heavy. If a patient is severely sick and actively losing actual fat and muscle mass (tissue wasting), the heavy accumulation of trapped fluid counterbalances that loss on the scale. As a result, their total body weight might appear stable or even look like it is increasing, completely masking the underlying malnutrition and tissue loss.', '["Fluid retention","Dehydration","Abdominal obesity","drug therapy"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-08T06:31:51.254Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-07T06:31:51.254Z"'::jsonb, '"2026-09-26T14:32:29.972Z"'::jsonb, '"2026-10-07T06:31:51.325Z"'::jsonb),
