('anki-card-1756687004033-5', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'The branch of health science that deals with the diagnosis, prevention, and treatment of disease caused by deficiency or excess of nutrients.', 'Clinical nutrition', 'Clinical nutrition', '["Diet therapy","Medical nutrition therapy","Clinical nutrition","Nutrition support"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
