('anki-card-1756687699150-10', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'This is where the healthcare provider enters all patient information or data collected from the patient or caregiver. This information would also include a diet recall and any food allergies that the patient report.', 'Subjective', '', '["Subjective","Objective","Assessment","Plan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756687784096-11', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'This section is based more on physical evidence about the patient. Information in this section would include height, weight, BMI, weight change over a period of time, labs, PMH, medications currently using or any other trending value.', 'Objective', '', '["Subjective","Objective","Assessment","Plan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756687884258-12', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'This is where the Nutrition Diagnosis is made. This diagnosis is referred to by healthcare professionals with a nutrition background, as a PES statement.', 'Assessment', '', '["Subjective","Objective","Assessment","Plan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756687977337-13', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'This is the section where an outline of interventions is made necessary to treat the nutrition problems. Goal are made, short-term and long term, using the SMART goal.', 'Plan', '', '["Subjective","Objective","Assessment","Plan"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756688107297-14', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Composed of protein, carbohydrate, and fat in high molecular weight form and therefore have lower osmolality. These formulas require normal digestive and lipolytic activity.', 'Nutritionally complete (polymeric) formula', 'Nutritionally complete (polymeric) formula', '["Nutritionally complete (polymeric) formula","Chemically defined (elemental) formula","Modular formula","Specialty formula"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756688209709-15', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Have a low residue and use free amino acids or peptides as a protein source. Oligosaccharides or monosaccharides provide the carbohydrate source and most contain medium as well as long chain triglycerides.', 'Chemically defined (elemental) formula', 'Chemically defined (elemental) formula', '["Nutritionally complete (polymeric) formula","Chemically defined (elemental) formula","Modular formula","Specialty formula"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756688274889-16', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Not nutritionally complete because they contain single nutrients such as carbohydrate, fat, or protein. Can be added to standard enteral products.', 'Modular formula', '', '["Nutritionally complete (polymeric) formula","Chemically defined (elemental) formula","Modular formula","Specialty formula"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756688459214-17', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Available for use in patients with a variety of clinical conditions including renal, respiratory, hepatic insufficiency, diabetes, immunocompromised states, and fat or carbohydrate malabsorption.', 'Specialty formula', '', '["Nutritionally complete (polymeric) formula","Chemically defined (elemental) formula","Modular formula","Specialty formula"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756688628922-18', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'The rapid delivery by syringe of 240-400mL of formula every 4 to 6 hours, simulates normal food intake in terms of gallbladder.', 'Bolus feeding', '', '["Bolus feeding","Timed intermittent","Continuous drip","Cyclic administration"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756688700335-19', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Involves the provision of 100-400mL of enteral formula with an interval of 2 to 4 hours. Can be used if there has been no history of malabsorption.', 'Timed intermittent', 'Timed intermittent', '["Bolus feeding","Timed intermittent","Continuous drip","Cyclic administration"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756688840229-20', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Requires infusion of the formula using a pump or gravity drip over a period of 16 to 24.', 'Continuous drip', '', '["Bolus feeding","Timed intermittent","Continuous drip","Cyclic administration"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756688872694-21', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Infuses the formula for 8 to 16, usually overnight, using an infusion pump.', 'Cyclic administration', 'Cyclic administration', '["Bolus feeding","Timed intermittent","Continuous drip","Cyclic administration"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756689106283-22', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'Substance other than food intended for use in diagnosis, cure, mitigation, treatment and prevention of diseases.', 'Drug', '', '["Drug","Drug-nutrient interaction","Food-drug interaction","Pharmacodynamics"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756689164980-23', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'The result of the action between a drug and nutrient that would not happen with the nutrient or the drug alone.', 'Drug-nutrient interaction', 'Drug-nutrient interaction', '["Drug","Drug-nutrient interaction","Food-drug interaction","Pharmacodynamics"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756689209645-24', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'A broad term all includes drug-nutrient interactions and the effect of a medication on nutritional status.', 'Food-drug interaction', 'Food-drug interaction', '["Drug","Drug-nutrient interaction","Food-drug interaction","Pharmacodynamics"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756689286958-25', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'The study of the interaction between drugs and their receptor and the series of events that result in a pharmacologic response.', 'Pharmacodynamics', 'Pharmacodynamics', '["Food-drug interaction","Pharmacodynamics","Pharmacokinetics","Iatrogenic malnutrition"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb)
