('anki-card-1756690869282-49', NULL, 'anki-deck-1783610590872-1790433140273-76rgd', 'What is the main objective of DOH AO 2019-0033?', 'To establish uniform implementation of the Nutrition Care Process (NCP) in hospitals', 'The AO ensures standardized, evidence-based nutrition care through the NCP in all hospital settings.', '["To standardized medical documentation across all hospitals","To establish uniform implementation of the Nutrition Care Process (NCP) in hospitals","To replace the role of dietitians with nutrition nurses","To create a new dietary scoring system"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-02T20:00:00.000Z","interval":1,"easeFactor":2.5,"repetitions":2}'::jsonb, NULL, '"2026-09-26T14:32:29.122Z"'::jsonb, '"2026-11-07T14:32:00.423Z"'::jsonb),
