('anki-card-1756789284657-0', NULL, 'anki-deck-1783610598974-1790433142628-tj9iq', 'Cental body fat distribution, apple-shaped.', 'Android', '', '["Android","Gynoid","Simple","Genetic"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T14:03:10.128Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T14:03:10.128Z"'::jsonb, '"2026-09-26T14:32:29.801Z"'::jsonb, '"2026-10-23T14:03:10.128Z"'::jsonb),
('anki-card-1756789315656-1', NULL, 'anki-deck-1783610598974-1790433142628-tj9iq', 'Lower body fat distribution, pear shaped; known as gynecoid.', 'Gynoid', '', '["Android","Gynoid","Simple","Genetic"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T14:03:15.841Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T14:03:15.841Z"'::jsonb, '"2026-09-26T14:32:29.801Z"'::jsonb, '"2026-10-23T14:03:15.841Z"'::jsonb),
('anki-card-1756789341872-2', NULL, 'anki-deck-1783610598974-1790433142628-tj9iq', 'Due to an imbalance of energy intake and expenditure.', 'Simple', '• Also known as exogenous or primary obesity, simple obesity is caused directly by an imbalance between energy intake (eating too many calories) and energy expenditure (not burning enough calories through physical activity). It is the most common form of weight gain and is not caused by an underlying medical condition, endocrine disorder, or genetic mutation.

• Genetic: This refers to obesity caused primarily by hereditary factors or specific genetic syndromes (like Prader-Willi syndrome), rather than just a simple lifestyle energy imbalance.
• Gynoid & Android: These terms describe fat distribution patterns rather than the root cause of the weight gain. Android refers to "apple-shaped" abdominal fat accumulation (common in men), while Gynoid refers to "pear-shaped" hip and thigh fat accumulation (common in women).', '["Android","Gynoid","Simple","Genetic"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-31T16:26:50.510Z","interval":3,"easeFactor":2.35,"repetitions":2}'::jsonb, '"2026-10-28T16:26:50.510Z"'::jsonb, '"2026-09-26T14:32:29.801Z"'::jsonb, '"2026-10-28T16:26:50.691Z"'::jsonb),
('anki-card-1756789427332-3', NULL, 'anki-deck-1783610598974-1790433142628-tj9iq', 'Ob gene that codes for leptin; the 40% chance of being obese when one parent is obese is responsible for obesities in many cases.', 'Genetic', '', '["Genetic","Hypertrophic","Hyperplastic","Endocrine-related obesities"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:45:10.116Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:45:10.116Z"'::jsonb, '"2026-09-26T14:32:29.801Z"'::jsonb, '"2026-10-23T13:45:10.116Z"'::jsonb),
