('anki-card-1756793384074-64', NULL, 'anki-deck-1783610598974-1790433142628-tj9iq', 'A rare genetic disease. It refers to the accumulation of mucus in the bronchi, pancreas, liver and intestines, causing damage and malfunction of the organs and biliary cirrhosis.', 'Cystic fibrosis', '', '["Pancreatits","Cystic fibrosis","Biliary dyskinesia","Gastricsec Jaundice"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:59:57.123Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:59:57.123Z"'::jsonb, '"2026-09-26T14:32:29.801Z"'::jsonb, '"2026-10-23T13:59:57.123Z"'::jsonb),
