('anki-card-1756794656155-73', NULL, 'anki-deck-1783610598974-1790433142628-tj9iq', 'Refers to a surgical procedure that creates an opening from the ileum to the surface of the abdominal wall to permit drainage of the contents of the small intestine.', 'Ileostomy', '', '["Colostomy","Ileostomy","Jejunoileostomy","Tonsillectomy"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T14:01:58.208Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T14:01:58.208Z"'::jsonb, '"2026-09-26T14:32:29.801Z"'::jsonb, '"2026-10-23T14:01:58.208Z"'::jsonb),
