('anki-card-1756869850919-82', NULL, 'anki-deck-1783610605628-1790433132440-fexke', 'Cover both food allergies and intolerances which can result to distressing symptoms and affecting a person''s quality of life.', 'Adverse reactions to food (ARF)', 'Adverse reactions to food (ARF)', '["Adverse reactions to food (ARF)","Fool allergy","Food intolerance","Antigen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.351Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1756869938982-83', NULL, 'anki-deck-1783610605628-1790433132440-fexke', 'Is an adverse immune-mediated reaction to a food, usually a food protein, glycoprotein, or hapten that the person has been sensitized to, and which, when eaten casues the release of inflammatory mediators or chemicals that act on the body tissues and result in symptoms.', 'Fool allergy', '', '["Adverse reactions to food (ARF)","Fool allergy","Food intolerance","Antigen"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.351Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
