('anki-card-1756870080192-85', NULL, 'anki-deck-1783610605628-1790433132440-fexke', 'Any molecules that will elicit an immune response in the body. When it elicits a hypersensitivity reactions as in allergy, it is called an allergen.', 'Antigen', '', '["Fool allergy","Food intolerance","Antigen","Food sensitivity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.351Z"'::jsonb, '"2026-09-26T14:32:12.431Z"'::jsonb),
('anki-card-1756870120622-86', NULL, 'anki-deck-1783610605628-1790433132440-fexke', 'Used when it is unclear whether the reaction in immunologically related or due to a biochemical or physiological defect.', 'Food sensitivity', 'Food sensitivity', '["Fool allergy","Food intolerance","Antigen","Food sensitivity"]'::jsonb, '["Nutritional Biochemistry"]'::jsonb, NULL, 'hard', 1, '', '{"dueDate":"2026-09-26T14:32:12.431Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-09-26T14:32:28.351Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
