INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1788373469747-4', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 10-year-old child with cystic fibrosis is enrolled in a school feeding program designed to provide one-third of daily recommended nutrient intake. Standard school meals provide approximately 2,060 kcal and 43g protein daily for this age group. Considering the pathophysiology of cystic fibrosis and evidence-based nutrition management, what is the most significant limitation of the current school feeding program for this child?', 'The standard meal energy and protein amounts are insufficient because CF requires two to four times usual recommendations to compensate for malabsorption; additional medical nutrition therapy and enzyme supplementation are necessary', '', '["The standard school meal is adequate; CF management requires only regular medication compliance without nutritional modification","The standard meal energy and protein amounts are insufficient because CF requires two to four times usual recommendations to compensate for malabsorption; additional medical nutrition therapy and enzyme supplementation are necessary","All children with chronic conditions require identical meal modifications; the school should implement the same increased portions for every student","Enzyme supplementation alone will normalize nutrient absorption, so the standard meal amounts are sufficient"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:29:33.575Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:29:33.575Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:29:33.856Z"'::jsonb),
('anki-card-1788373494235-5', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 17-year-old pregnant adolescent presents for nutrition counseling. She is 1.48 m tall, weighs 58 kg pre-pregnancy (BMI 26.5 kg/m²), and is currently at 20 weeks gestation. Her dietary assessment reveals low calcium intake, inadequate protein consumption, and iron-deficiency anemia (Hgb 10.2 g/dL). She reports limited financial resources and attends school intermittently. Based on a comprehensive understanding of adolescent pregnancy risks and her specific circumstances, what is your priority nutrition intervention?', 'Address iron deficiency anemia immediately as it increases risk for prolonged labor and adverse outcomes; simultaneously ensure adequate calcium and protein intake to support both her continued growth and fetal development; provide practical, affordable food guidance considering her resource limitations and school schedule', '', '["Treat iron deficiency anemia as an isolated concern without addressing concurrent calcium and protein needs, as these nutrients do not affect pregnancy outcomes in adolescents","Focus intervention solely on her height and pelvic size as these are the primary determinants of obstetric risk in adolescent pregnancy","Provide standard adult pregnancy nutrition guidelines without modification, since adolescent and adult pregnant individuals have identical nutritional requirements and risk profiles","Address iron deficiency anemia immediately as it increases risk for prolonged labor and adverse outcomes; simultaneously ensure adequate calcium and protein intake to support both her continued growth and fetal development; provide practical, affordable food guidance considering her resource limitations and school schedule"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:30:28.712Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:30:28.712Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:30:29.127Z"'::jsonb),
('anki-card-1788373520954-6', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 13-year-old girl at Tanner Stage 3 presents with irregular menstrual periods and reports consuming approximately 1,200 kcal/day from her diet consisting mainly of salads, diet sodas, and occasional fruits. She expresses dissatisfaction with her body shape despite having a BMI at the 75th percentile. Which developmental and nutritional factors should guide your intervention strategy?', 'Recognize this as a critical period for bone mass accretion and psychosocial development; address both the inadequate energy intake and body image concerns through empowering, non-judgmental counseling that involves her in decision-making while monitoring for progression toward clinical eating disorder', '', '["Recognize this as a critical period for bone mass accretion and psychosocial development; address both the inadequate energy intake and body image concerns through empowering, non-judgmental counseling that involves her in decision-making while monitoring for progression toward clinical eating disorder","Focus only on her current BMI percentile and reassure her that her eating pattern is acceptable since she is not yet overweight","Attribute her irregular menses solely to normal puberty and avoid nutrition intervention, as menstrual irregularity always resolves independently","Support her current 1,200 kcal intake as appropriate for weight maintenance and encourage continued restriction if she continues to express body dissatisfaction"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:37:35.475Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:37:35.475Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:37:35.784Z"'::jsonb),
('anki-card-1788373544875-7', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 15-year-old female presents to your clinic with complaints of fatigue, shortness of breath, and poor academic performance. Her dietary history reveals she follows a strict vegan diet and frequently skips breakfast. Her BMI is within normal range. Based on your nutritional assessment, which micronutrient deficiency is most likely contributing to her symptoms, and what is the primary dietary reason for this deficiency?', 'Iron deficiency anemia due to inadequate intake of heme iron from animal sources combined with poor bioavailability of nonheme iron from plant-based foods, exacerbated by breakfast skipping which reduces overall nutrient intake', '', '["Zinc deficiency, because plant-based sources contain inhibitors that completely prevent zinc absorption","Iron deficiency anemia due to inadequate intake of heme iron from animal sources combined with poor bioavailability of nonheme iron from plant-based foods, exacerbated by breakfast skipping which reduces overall nutrient intake","Calcium deficiency, because dairy products are the primary source of bioavailable calcium","Protein deficiency, because vegans cannot obtain adequate protein from plant sources alone"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:32:47.877Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:32:47.877Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:32:48.656Z"'::jsonb),
('anki-card-1788373570046-8', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'During a nutrition counseling session, a 16-year-old male who is 1.65 m tall and weighs 72 kg (BMI approximately 26.4 kg/m²) reports consuming high amounts of omega-6 fatty acids from snacks and fast foods but minimal omega-3 intake. His parents express concern about his overweight status and sedentary behavior. According to current adolescent nutrition guidelines and considering his developmental stage, what is the most evidence-based approach to address his nutritional and lifestyle concerns?', 'Implement a multifaceted intervention addressing the omega-6 to omega-3 ratio (targeting 4:1), reduce total fat intake to no more than 30% of total energy requirements with saturated fat below 10%, increase physical activity, and involve him in goal-setting to promote autonomy and long-term behavior change', '', '["Prescribe intensive exercise regimens immediately without considering his current sedentary status or psychosocial readiness, as physical activity has no psychological benefits in adolescence","Focus exclusively on total caloric reduction without addressing fat composition, since the type of fat consumed does not affect adolescent health outcomes","Implement a multifaceted intervention addressing the omega-6 to omega-3 ratio (targeting 4:1), reduce total fat intake to no more than 30% of total energy requirements with saturated fat below 10%, increase physical activity, and involve him in goal-setting to promote autonomy and long-term behavior change","Recommend complete elimination of all dietary fats to rapidly reduce his BMI, as all fats contribute equally to weight gain"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:23:09.033Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:23:09.033Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:23:09.398Z"'::jsonb),
('anki-card-1788373593617-9', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'You are counseling a 14-year-old boy who is an endurance athlete with a BMI at the 50th percentile. He reports consuming 83% of his meals from fast food establishments and expresses concern about his energy levels during training. His current energy intake is approximately 2,500 kcal/day. What is the most appropriate nutritional intervention considering his developmental stage, athletic demands, and current eating pattern?', 'Assess his actual energy requirements based on his growth spurt phase and activity intensity; educate him on nutrient-dense alternatives that are convenient, portable, and can be incorporated into his current fast-food pattern rather than complete dietary overhaul', '', '["Focus exclusively on increasing protein intake to 100+ grams per day to maximize muscle mass, as bone health is not a concern for male athletes","Recommend complete elimination of fast food and preparation of home-cooked meals to ensure nutrient density","Assess his actual energy requirements based on his growth spurt phase and activity intensity; educate him on nutrient-dense alternatives that are convenient, portable, and can be incorporated into his current fast-food pattern rather than complete dietary overhaul","Maintain current intake at 2,500 kcal/day since his BMI is normal and energy requirements are the same as non-athletes"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:27:49.175Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:27:49.175Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:27:49.591Z"'::jsonb),
('anki-card-1788373610875-10', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 52-year-old female client in early menopause reports weight gain despite unchanged eating habits and increased fatigue. Which nutritional intervention strategy would best address her underlying physiological changes?', 'Increase calcium and vitamin D intake; maintain protein at 10-15% of calories; encourage regular physical activity', '', '["Focus solely on carbohydrate reduction; avoid protein supplementation","Increase estrogen replacement therapy without dietary modifications","Reduce total caloric intake by 50% and eliminate all dietary fats","Increase calcium and vitamin D intake; maintain protein at 10-15% of calories; encourage regular physical activity"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:28:57.687Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:28:57.687Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:28:58.026Z"'::jsonb),
('anki-card-1788373633197-11', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 45-year-old male client reports decreased appetite, unintentional weight loss, and difficulty swallowing. Based on adult nutrition physiology, which physiological change most likely contributes to these symptoms?', 'Slowed gastric emptying and diminished taste and smell sensations', '', '["Requires immediate pharmacological intervention without dietary modification","Slowed gastric emptying and diminished taste and smell sensations","Elevated estrogen levels causing digestive distress","Increased metabolic rate requiring excessive caloric intake"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:33:07.271Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:33:07.271Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:33:07.675Z"'::jsonb),
('anki-card-1788373655137-12', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 60-year-old client with arthritis reports difficulty shopping and preparing meals, reduced food intake, and declining nutrient absorption. Which factor requires the most immediate nutritional intervention?', 'Functional limitations affecting food access combined with chronic illness reducing nutrient absorption', '', '["Advanced age automatically requires 50% reduction in all nutrient intakes","Arthritis pain is unrelated to nutritional status and requires only pain management","Functional limitations affecting food access combined with chronic illness reducing nutrient absorption","Increased food quantity compensates for impaired absorption in older adults"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:40:51.543Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:40:51.543Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:40:51.827Z"'::jsonb),
('anki-card-1788373679407-13', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 28-year-old female client reports chronic stress, limited time for meal preparation, and reliance on processed snacks. Based on adult nutrition factors, which social-economic factor most directly impacts her nutritional status?', 'Work-life balance demands reduce time for food preparation, leading to nutrient-poor food choices', '', '["Processed foods provide all necessary nutrients if consumed in adequate quantity","Psychological stress increases metabolic rate, eliminating need for dietary counseling","Her age group naturally requires fewer micronutrients than older adults","Work-life balance demands reduce time for food preparation, leading to nutrient-poor food choices"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:39:13.961Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:39:13.961Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:39:14.291Z"'::jsonb),
('anki-card-1788373699913-14', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 38-year-old client with hypertension and obesity reports consuming alcohol daily and minimal physical activity. According to the document, which consequence of this lifestyle pattern poses the greatest nutritional risk?', 'Alcohol provides empty calories while displacing nutrient-dense foods, compounding obesity and CVD risk', '', '["Alcohol provides empty calories while displacing nutrient-dense foods, compounding obesity and CVD risk","Physical inactivity alone causes malabsorption independent of alcohol intake","Alcohol consumption has no documented impact on nutrient absorption","Alcohol contains complete proteins essential for muscle maintenance"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:38:53.713Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:38:53.713Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:38:54.047Z"'::jsonb),
('anki-card-1788373721620-15', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 72-year-old female with hypertension and osteoporosis requires nutritional counseling. Based on age-related physiological changes and her conditions, which dietary recommendation is most appropriate?', 'Increase calcium intake to 800 mg/day and reduce sodium to prevent bone loss and manage blood pressure', '', '["Increase protein to 2.5 g/kg/day to maximize muscle synthesis and prevent sarcopenia","Increase calcium intake to 800 mg/day and reduce sodium to prevent bone loss and manage blood pressure","Recommend vitamin A supplementation above RDA to enhance immune function","Maintain high-calorie intake of 2,500 kcal/day to prevent weight loss and muscle wasting"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:37:17.527Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:37:17.527Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:37:17.890Z"'::jsonb),
('anki-card-1788373744407-16', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'During a nutrition screening, an 80-year-old widow scores 7 on the Nutrition Screening Initiative checklist. She reports eating alone, taking 4 medications daily, and losing 8 pounds in 6 months. What is the most critical next step?', 'Refer for comprehensive nutritional assessment and evaluate for depression and social isolation', '', '["Refer for comprehensive nutritional assessment and evaluate for depression and social isolation","Order laboratory tests for malabsorption and refer to gastroenterology for evaluation","Discontinue all medications and substitute with herbal alternatives to improve appetite","Immediately prescribe high-calorie supplements and increase meal frequency to 5 meals daily"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:40:10.320Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:40:10.320Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:40:11.064Z"'::jsonb),
('anki-card-1788373768245-17', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'An 78-year-old male presents with fatigue and dyspnea. Lab results show low hemoglobin and B₁₂ levels. His stomach biopsy reveals atrophy of gastric mucosa. Which physiological change best explains his condition?', 'Decreased intrinsic factor production impairs B₁₂ absorption in the ileum', '', '["Reduced iron absorption due to decreased stomach acid leads to iron deficiency anemia","Decreased pepsinogen secretion prevents protein breakdown needed for B₁₂ binding","Insufficient dietary B₁₂ intake from limited meat consumption causes pernicious anemia","Decreased intrinsic factor production impairs B₁₂ absorption in the ileum"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:28:22.739Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:28:22.739Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:28:23.028Z"'::jsonb),
('anki-card-1788373790699-18', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'An 82-year-old man with poor dentition, constipation, and decreased taste sensation consumes mainly soft, low-fiber foods. Which physiological factor most significantly contributes to his constipation?', 'Decreased GI motility combined with inadequate fiber and fluid intake', '', '["Hypogeusia and hyposmia reduce appetite, leading to decreased gastric secretions","Limited caloric intake reduces intestinal bulk and slows peristalsis","Decreased GI motility combined with inadequate fiber and fluid intake","Reduced pancreatic enzyme secretion prevents carbohydrate digestion and stool formation"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:39:54.587Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:39:54.587Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:39:55.168Z"'::jsonb),
('anki-card-1788373821334-19', NULL, 'anki-deck-1788373344910-1790433142628-l4qb7', 'A 75-year-old patient on corticosteroids for chronic inflammation reports increased thirst, frequent urination, and muscle weakness. Which nutrient deficiency is most likely contributing to these symptoms?', 'Potassium depletion due to increased urinary excretion from corticosteroid use', '', '["Potassium depletion due to increased urinary excretion from corticosteroid use","Calcium malabsorption from reduced vitamin D activation causes muscle cramps and weakness","Decreased glomerular filtration rate impairs fluid regulation and causes sodium retention","Vitamin C deficiency from increased urinary excretion impairs collagen synthesis"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-24T13:38:29.979Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-23T13:38:29.979Z"'::jsonb, '"2026-09-26T14:32:29.825Z"'::jsonb, '"2026-10-23T13:38:30.639Z"'::jsonb),
('anki-card-1788374153014-0', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'A municipality reported the following nutrition profile:
Stunting: 27%Wasting: 3%Childhood overweight: 9%Adult obesity: 31%Exclusive breastfeeding: 38%Access to safely managed drinking water: 58%The Municipal Mayor proposes allocating almost the entire nutrition budget to supplemental feeding because "children simply need more food." As the Municipal Nutrition Action Officer, what is the most appropriate recommendation?', 'Recommend a comprehensive package that strengthens First 1,000 Days interventions, breastfeeding promotion, WASH, dietary improvement, and food security while targeting supplemental feeding to nutritionally at-risk children.', '', '["Approve the proposal because inadequate food intake is the primary cause of stunting.","Recommend a comprehensive package that strengthens First 1,000 Days interventions, breastfeeding promotion, WASH, dietary improvement, and food security while targeting supplemental feeding to nutritionally at-risk children.","Increase the duration of supplemental feeding from 120 to 180 days.","Allocate most of the budget to obesity prevention because obesity affects more people. e. Divide the budget equally among all nutrition problems."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T15:13:12.558Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-29T15:13:12.558Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:12.756Z"'::jsonb),
('anki-card-1788374176173-1', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'A barangay achieved high attendance during nutrition education sessions. However, household dietary practices remained largely unchanged. Which conclusion is appropriate?', 'Knowledge alone does not guarantee behavior change; environmental, economic, social, and cultural factors should also be addressed.', '', '["Nutrition education should be discontinued.","Knowledge alone does not guarantee behavior change; environmental, economic, social, and cultural factors should also be addressed.","Supplemental feeding should replace nutrition education.","Attendance is the best measure of program effectiveness. e. Families should be required to attend additional lectures."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T15:14:04.524Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-29T15:14:04.524Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:14:04.725Z"'::jsonb),
('anki-card-1788374203522-2', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'Which activity best represents the Nutritionist-Dietitian functioning at the population level?', 'Developing a city-wide strategy to improve exclusive breastfeeding rates.', '', '["Counseling an individual with diabetes regarding meal planning.","Developing a city-wide strategy to improve exclusive breastfeeding rates.","Preparing a therapeutic diet for a hospitalized patient.","Conducting an individualized nutrition assessment."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T15:13:27.776Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-29T15:13:27.776Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:27.972Z"'::jsonb),
('anki-card-1788374229259-3', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'Which activity best demonstrates continuous quality improvement in a community nutrition program?', 'Regularly monitoring program indicators, identifying gaps, implementing corrective actions, and reassessing performance', 'Continuous Quality Improvement (CQI) is an ongoing, systematic process. It relies on data collection, analyzing processes, testing changes, and evaluating outcomes to make a service better. Option C directly outlines this full, cyclical loop.

Other options describe simple administrative, process-oriented tasks or resource acquisitions. While useful, they only represent single outputs or compliance measures; they do not inherently drive a continuous loop of evaluation and performance optimization.', '["Regularly monitoring program indicators, identifying gaps, implementing corrective actions, and reassessing performance","Preparing accomplishment reports on time","Increasing the number of nutrition meetings conducted","Purchasing additional anthropometric equipment annually"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2027-01-22T15:13:35.493Z","interval":85,"easeFactor":2.3,"repetitions":6}'::jsonb, '"2026-10-29T15:13:35.493Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:35.690Z"'::jsonb),
('anki-card-1788374256211-4', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'Which practice best reflects effective partnership management?', 'Clearly defining stakeholder roles, responsibilities, communication mechanisms, and shared objectives before implementation.', '', '["Sharing program information only after implementation.","Clearly defining stakeholder roles, responsibilities, communication mechanisms, and shared objectives before implementation.","Allowing each partner to establish separate monitoring systems.","Limiting meetings to year-end accomplishment reporting."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T15:13:01.014Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-29T15:13:01.014Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:01.212Z"'::jsonb),
('anki-card-1788374277919-5', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'An evaluation showed that mothers understand the importance of exclusive breastfeeding but discontinue breastfeeding early because they return to work soon after giving birth. Which intervention is most appropriate?', 'Address workplace support, family support, and breastfeeding counseling alongside education.', 'The evaluation explicitly shows that the problem is not a lack of knowledge (the mothers already understand the importance). The actual barrier is structural and environmental (returning to work). Therefore, providing more education or simply testing them again will completely fail to solve the problem.

To support working mothers, a successful public health program must move beyond individual education and address the environment. This includes advocating for workplace support (such as lactation breaks and expression rooms), family backing, and practical counseling to manage milk storage while working.', '["Address workplace support, family support, and breastfeeding counseling alongside education.","Require mothers to attend more seminars.","Distribute additional pamphlets.","Increase post-test scores as the primary objective."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2027-01-22T15:13:16.365Z","interval":85,"easeFactor":2.3,"repetitions":6}'::jsonb, '"2026-10-29T15:13:16.365Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:16.566Z"'::jsonb),
('anki-card-1788374298356-6', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'Which outcome best demonstrates that a nutrition education program has been effective?', 'Improved adoption of recommended nutrition practices among participants', '', '["High attendance during the seminar","Improved adoption of recommended nutrition practices among participants","Distribution of all educational materials","Completion of the activity within budget"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T15:13:22.180Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-29T15:13:22.180Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:22.382Z"'::jsonb),
('anki-card-1788374319862-7', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'A municipality has limited funds for nutrition education. Which strategy is most likely to maximize community reach while maintaining consistent messages?', 'Train Barangay Nutrition Scholars and community volunteers to deliver standardized nutrition education in their communities.', '', '["Train Barangay Nutrition Scholars and community volunteers to deliver standardized nutrition education in their communities.","Conduct repeated seminars exclusively at the Municipal Hall.","Distribute nutrition manuals only.","Limit nutrition education to health professionals."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T15:13:59.632Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-29T15:13:59.632Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:59.833Z"'::jsonb),
('anki-card-1788374340368-8', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'Six months after completing a community nutrition education campaign, what is the most appropriate indicator of program success?', 'Percentage of participants demonstrating sustained positive nutrition behaviors related to the campaign objectives', '', '["Number of posters displayed","Percentage of participants demonstrating sustained positive nutrition behaviors related to the campaign objectives","Number of orientation sessions conducted","Amount of educational materials distributed e. Number of facilitators trained"]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-11-01T15:13:49.371Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-29T15:13:49.371Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:49.573Z"'::jsonb),
('anki-card-1788374368303-9', NULL, 'anki-deck-1788374097792-1790433136794-o55bb', 'Following six months of nutrition education, caregivers demonstrated improved knowledge but household dietary diversity showed minimal improvement. Which explanation is most appropriate?', 'Knowledge alone is insufficient; economic, environmental, cultural, and household factors also influence food choices.', 'In public health and community nutrition, a critical distinction is always made between outputs (gaining knowledge) and outcomes (actual behavioral change). A caregiver can perfectly understand the value of a diverse diet, but if the household faces economic barriers (poverty), environmental constraints (lack of market access to fresh produce), or deep-seated cultural preferences, they will not be able to translate that knowledge into practice.', '["Knowledge alone is insufficient; economic, environmental, cultural, and household factors also influence food choices.","Nutrition education should be discontinued.","Participants should be required to attend more lectures.","The educational materials should contain more technical information."]'::jsonb, '["Public Health & Community"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2027-05-12T15:13:32.466Z","interval":195,"easeFactor":2.3,"repetitions":7}'::jsonb, '"2026-10-29T15:13:32.466Z"'::jsonb, '"2026-09-26T14:32:29.069Z"'::jsonb, '"2026-10-29T15:13:32.659Z"'::jsonb),
('anki-card-1788419305781-0', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'It is the science and art of preventing disease, prolonging life, and promoting health through organized community effort.', 'public health', 'Public health has been classically defined as the science and art of preventing disease, prolonging life, and promoting health through the organized efforts of society (Winslow, 1920).', '["public health","public health nutrition","community nutrition","community health"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T13:02:19.326Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T13:02:19.326Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T13:02:19.633Z"'::jsonb),
('anki-card-1788419333731-1', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'It refers to the measurement of indicators of dietary status and nutrition-related health status to identify the possible occurrence, nature, and extent of impaired nutritional status.', 'nutrition assessment', 'Nutrition assessment is the comprehensive evaluation of anthropometric, biochemical, clinical, dietary indicators used to determine whether, and to what extent, malnutrition is present in an individual or population. It is broader and more detailed than screening, which is a rapid, single-indicator method used to identify individuals at risk, and it differs from surveillance, which involves continuous, ongoing data collection used to track trends over time rather than to diagnose status at one point in time.', '["nutrition assessment","nutrition screening","nutrition intervention","nutrition surveillance"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T13:03:42.958Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T13:03:42.958Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T13:03:43.269Z"'::jsonb),
('anki-card-1788419356267-2', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The following are exogenous factors influencing an individual''s food intake except:', 'food beliefs and attitudes', 'Factors that influence food intake are classified as endogenous (internal, physiologic or psychological, arising from within the individual, such as appetite, taste preference, and personal beliefs and attitudes toward food) or exogenous (external, environmental, and social, such as income, culture, religion, food availability, and agro-climatic conditions like soil quality). 

Socioeconomic conditions, religion, and soil condition are external environmental determinants, while food beliefs and attitudes originate from the individual''s own cognition and are therefore endogenous rather than exogenous.', '["food beliefs and attitudes","soil condition","socioeconomic conditions","religion"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:18:35.291Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:18:35.291Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:18:35.712Z"'::jsonb),
('anki-card-1788419416253-3', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'What are the colors of the characters used in the Sangkap Pinoy Seal?
[Image: Diagram]', 'Vitamin A - Yellow, Iron - Green, Iodine - Red', 'The characters/icons underneath the official Sangkap Pinoy Seal (SPS) follow a distinct, standardized color-coding system to denote which micronutrients are added to fortified food products:

• Yellow represents Vitamin A.
• Green represents Iron.
• Red represents Iodine.

These symbols serve as a direct visual guide for shoppers looking to combat micronutrient deficiencies while buying staple foods and processed snacks.', '["Vitamin A - Yellow, Iron - Green, Iodine - Red","Vitamin A - Yellow, Iron - Red, Iodine - Green","Vitamin A - Yellow, Iron - Green, Iodine - Blue","Vitamin A - Green, Iron - Red, Iodine - Yellow"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T13:00:56.557Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T13:00:56.557Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-11-10T01:05:27.982Z"'::jsonb),
('anki-card-1788419443788-4', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Malnutrition in a developing country is reflected in the increased specific death rate of preschoolers due to:', 'measles', 'Malnutrition in a developing country increases the preschool death rate primarily due to infectious diseases such as measles, one of the most contagious diseases (but preventable) diseases in the world.', '["measles","diarrhea","tetanus","dengue"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:51:52.860Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:51:52.860Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:51:53.610Z"'::jsonb),
('anki-card-1788419463428-5', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Who is the current chair of the Professional Regulatory Board of Nutrition and Dietetics?', 'Socorro Ignacio', 'Socorro Ignacio (Dr. Ma. Socorro Endrina-Ignacio), who was appointed as Chairperson of the Professional Regulatory Board of Nutrition and Dietetics under the Professional Regulation Commission (PRC).

• Chairperson: Ma. Socorro E. Ignacio
• Members: Imelda A. Agdeppa and Rhoda Joy R. Buenviaje
• (Note: Virgith B. Buena previously served as the long-time Chairperson prior to recent board reorganization).', '["Imelda Angeles-Agdeppa","Socorro Ignacio","Rhoda Joy Buenviaje","Virgith Buena"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:25:48.629Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:25:48.629Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:25:48.629Z"'::jsonb),
('anki-card-1788419568627-6', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'A study wherein the subjects nor the experimenter knows that treatment is being given until after the experiment is called a:', 'double-blind study', 'A double-blind study is one in which neither the research subjects nor the investigators administering treatment know who is receiving the active intervention versus the control until after data collection is complete, minimizing bias from both participant expectation and researcher influence. 

This differs from a single-blind study, where only the subject (and not the researcher) is unaware of group assignment.', '["double-blind study","placebo control trial","single-blind study","hawthorne study"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:37:33.442Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:37:33.442Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:37:33.442Z"'::jsonb),
('anki-card-1788419604606-7', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Under the 105-Day Expanded Maternity Leave Law, the father may enjoy as much as how many days of paid leave to take care of his child?', '14 days', 'RA 11210: A father may now enjoy as much as 14 days of paid leave to take care of his child, depending on his marital status with the mother.', '["14 days","0 days","3 days","7 days"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:54:42.748Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:54:42.748Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:54:43.098Z"'::jsonb),
('anki-card-1788419629112-8', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'It is the practical measure to assess iodine status.', 'urinary iodine excretion', 'Urinary iodine concentration is the recommended, practical population-level indicator of iodine status because more than 90% of ingested iodine is excreted in urine, making it a direct and cost-effective reflection of recent dietary iodine intake (World Health Organization, UNICEF, & ICCIDD, 2007). 

Serum thyroglobulin, TSH, and thyroxine are useful but more costly, less practical biochemical markers usually reserved for confirmatory or clinical assessment.', '["urinary iodine excretion","serum thyroglobulin","serum thyroid stimulating hormone","serum thyroxine"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:31:01.177Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:31:01.177Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:31:01.513Z"'::jsonb),
('anki-card-1788419656781-9', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'It is a type of Evaluation that assesses program effectiveness in achieving its ultimate goals.', 'Impact', 'In public health and program management frameworks, different levels of evaluation target different stages of a program''s results:

• Impact Evaluation specifically assesses the degree to which a program meets its ultimate, long-term goals (such as a structural reduction in disease morbidity, changes in mortality rates, or permanent environmental shifts).
• Outcome Evaluation measures the intermediate, direct effectiveness of a program in meeting its objectives among the target population, focusing primarily on short-to-medium-term changes in knowledge, attitudes, and specific behaviors.
• Summative Evaluation is a broader umbrella category done at the end of a program to make overall summary judgments about its worth or funding, which includes both outcome and impact parameters.
• Formative Evaluation is conducted during development or early implementation to check feasibility and optimize the program''s design before full rollout.', '["Formative","Impact","Outcome","Summative"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:56:52.489Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:56:52.489Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:56:52.759Z"'::jsonb),
('anki-card-1788419679885-10', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'A newborn infant has adequate reserve of:', 'vitamin A', 'Newborns are typically born with adequate hepatic stores of vitamin A transferred from the mother during gestation.

Vitamin A is efficiently transferred across the placenta toward the end of pregnancy, allowing full-term newborn infants to build up a substantial hepatic (liver) reserve that supports their rapid early development, skin, vision, and immune function.

Under normal nutritional conditions, healthy full-term infants are born with enough stored vitamin A to meet their needs during the initial months of life.

• Vitamin K: This is the most crucial incorrect option. Newborns have minimal to negligible vitamin K reserves at birth because it does not cross the placenta efficiently and their intestinal tracts are sterile. This puts them at immediate risk for Vitamin K Deficiency Bleeding (VKDB), which is why a prophylactic intramuscular vitamin K shot is routinely given within 6 hours of birth.
• Vitamin C: Being a water-soluble vitamin, vitamin C is not stored in significant quantities in fetal or infant tissues. The baby relies entirely on continuous daily intake via breast milk or formula.
• Vitamin E: While some vitamin E is transferred late in pregnancy, plasma levels in newborns are relatively low compared to adult levels, and they do not carry an abundance of "adequate reserve" compared to vitamin A.', '["vitamin A","vitamin C","vitamin K","vitamin E"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:51:46.179Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:51:46.179Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:51:46.778Z"'::jsonb),
('anki-card-1788419706304-11', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'What is the main role of the agricultural sector in nutrition programs?', 'Encourage home production of fruits and vegetables', 'Within multisectoral nutrition programming, the agriculture sector''s principal contribution is nutrition-sensitive agriculture, most notably promoting household and community food production (e.g., backyard and communal vegetable gardens) to directly improve dietary diversity and access to nutrient-dense foods at the household level. 

Food fortification and food research fall primarily under the health/science sectors, while livelihood engagement is a broader poverty-reduction, rather than nutrition-specific, function.', '["Encourage home production of fruits and vegetables","Conduct research on foods rich in nutrients","Fortification of staple foods","Engagement to rural livelihood programs"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:11:52.027Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:11:52.027Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:11:52.514Z"'::jsonb),
('anki-card-1788419736822-12', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'This body type tends to have a larger waist-to-hip ratio where most fat is stored in the midsection. They are at higher risk of metabolic abnormalities.', 'Apple and Android', 'Apple or android type of body.', '["Apple and Android","Apple","Chad","Android"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:37:45.877Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:37:45.877Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:37:45.877Z"'::jsonb),
('anki-card-1788419761060-13', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'All are types of nonprobability sampling except:', 'cluster sampling', 'Convenience, purposive, and quota sampling are nonprobability methods, meaning population units do not have a known or equal chance of selection, and selection is instead guided by accessibility, judgment, or predetermined quotas. 

Cluster sampling, in contrast, is a probability sampling technique in which naturally occurring groups (clusters) are randomly selected, giving every unit in the population a calculable chance of inclusion.', '["cluster sampling","convenience sampling","purposive sampling","quota sampling"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T08:10:19.312Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T08:10:19.312Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-29T08:10:19.640Z"'::jsonb),
('anki-card-1788419783814-14', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The recommended amount of fish and alternatives based on the Pinggang Pinoy is ________.', '½ cup', 'Under the Pinggang Pinoy food exchange guide developed by the DOST Food and Nutrition Research Institute, one serving from the fish and alternatives ("Grow") food group, such as a small piece of fish, a matchbox-sized portion of meat, or an equivalent like shrimp or legumes, corresponds to approximately half a cup, consistent with the food guide''s exchange list of household measures (DOST-FNRI, n.d.).', '["½ cup","¼ cup","⅓ cup","¾ cup"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:57:10.030Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:57:10.030Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:57:10.667Z"'::jsonb),
('anki-card-1788419801856-15', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Which of the following dishes is not included in the three sets of vegetables provided by the May Gulay Project at affordable prices?', 'Dinengdeng', 'The Department of Agriculture''s "May Gulay Project" was launched to ensure a continuous and stable supply of vegetables at affordable prices (traditionally packed and retailed as pre-cut, hygienic half-kilo sets).

The program officially provides three specific sets of pre-packaged vegetable combinations tailored for classic Filipino dishes:
1. Pinakbet
2. Sinigang
3. Chopsuey', '["Pinakbet","Dinengdeng","Sinigang","Chopsuey"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:54:02.372Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:54:02.372Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:54:02.845Z"'::jsonb),
('anki-card-1788419822962-16', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'In this type of planning approach, the programs are dictated by the mandate, thrusts, and concerns of the sector where the program is lodged.', 'Sectoral planning', 'Sectoral planning is an approach in which programs and priorities are determined primarily by the specific mandate and thrust of the government sector or agency implementing them (e.g., health, agriculture, or education) rather than by a shared, cross-sectoral nutrition goal.', '["Sectoral planning","Nutrition-based development planning","Option C","Community nutrition planning"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:27:11.779Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:27:11.779Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:27:12.480Z"'::jsonb),
('anki-card-1788419845500-17', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'This is the human resource strategy of the Philippine Plan of Action for Nutrition.', 'Barangay Nutrition Scholar Program', 'The Barangay Nutrition Scholar (BNS) Program is the human resource development strategy of the PPAN, involving the recruitment, training, deployment, and supervision of volunteer community nutrition workers in every barangay, originally mandated under Presidential Decree No. 1569.

Operation Timbang Plus, Nutriskwela, and the Promote Good Nutrition Program are service-delivery or advocacy programs.', '["Barangay Nutrition Scholar Program","Nutriskwela Community Radio Network Program","Promote Good Nutrition Program","Operation Timbang Plus Program"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:22:55.822Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:22:55.822Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:22:56.197Z"'::jsonb),
('anki-card-1788419864290-18', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Which agency is not a member of the NNC Governing Board?', 'DAR', 'According to the official National Nutrition Council (NNC) Guidelines, the Governing Board is the highest policy-making body on nutrition in the Philippines. It is composed of 10 national government agencies and three representatives from the private sector:

1. Department of Health (DOH) – Chairperson
2. Department of Agriculture (DA) – Vice-Chairperson
3. Department of the Interior and Local Government (DILG) – Vice-Chairperson
4. Department of Budget and Management (DBM)
5. Department of Education (DepEd)
6. Department of Labor and Employment (DOLE)
7. Department of Science and Technology (DOST)
8. Department of Social Welfare and Development (DSWD)
9. Department of Trade and Industry (DTI)
10. National Economic and Development Authority (NEDA)', '["DOST","DAR","DOLE","DBM"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:32:48.462Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:32:48.462Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:32:48.749Z"'::jsonb),
('anki-card-1788419888577-19', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Who is the first director of the National Nutrition Council?', 'Dr. Florentino Solon', 'Dr. Florentino S. Solon, widely regarded as the "Father of Nutrition" in the Philippines, served as the first Executive Director of the National Nutrition Council beginning in 1974, and concurrently founded the Nutrition Center of the Philippines the same year (NNC, 2025).', '["Dr. Florentino Solon","Dr. Juan Salcedo, Jr.","Dr. Coronado Pascual","Dr. Francisco Santos"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:24:52.783Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:24:52.783Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:24:53.253Z"'::jsonb),
('anki-card-1788419910799-20', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The nutrient that is considered most difficult to meet during pregnancy:', 'iron', 'Iron requirements roughly double during pregnancy to support the expansion of maternal blood volume, fetal and placental growth, and stores for the newborn, and this increased demand is very difficult to meet through diet alone, which is why iron-folic acid supplementation is routinely recommended for pregnant women (WHO, 2001). 

Among the macro- and micronutrients needed in pregnancy, iron is consistently identified as the nutrient hardest to obtain in adequate amounts from food sources alone.', '["iron","calcium","protein","vitamin D"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:44:32.977Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:44:32.977Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:44:32.977Z"'::jsonb),
('anki-card-1788419935738-21', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'It is a statement of general thrust of the organization.', 'Mission', 'A mission statement articulates an organization''s general thrust or overarching purpose, why it exists and what it broadly seeks to accomplish, distinct from a vision (the aspirational future state it seeks to achieve), a goal (a broad long-term aim derived from the mission), and an objective (a specific, measurable, time-bound target that operationalizes a goal).', '["Mission","Vision","Objective","Goal"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:37:59.090Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:37:59.090Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:37:59.090Z"'::jsonb),
('anki-card-1788419957943-22', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The national government agency that makes sure that nutrition concerns are integrated in both national and sub-national development plans.', 'DEPDev', 'The Department of Economy, Planning, and Development (DEPDev) created under Republic Act No. 12145 through the reorganization of the former National Economic and Development Authority (NEDA) serves as the primary planning agency responsible for issuing and integrating nutrition and other socioeconomic concerns into the Philippine Development Plan, Regional Development Plans, and related national and sub-national planning instruments (DEPDev, 2025).', '["DEPDev","DBM","DSWD","DILG"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:57:00.831Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:57:00.831Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:57:01.120Z"'::jsonb),
('anki-card-1788419975372-23', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'A level of health care facilities which includes rural health units, chest clinics, and malaria eradication units.', 'primary level', 'Primary level health care facilities serve as the first point of contact between community members and the formal healthcare system. According to the Department of Health (DOH) structural framework, this level manages simple, routine, and specialized community-wide preventive and promotive health programs.

It encompasses:
• Rural Health Units (RHUs) and Barangay Health Stations (BHS)
• Chest clinics (for tuberculosis management and screening)
• Malaria eradication units and other specialized disease surveillance outposts
• Private medical clinics and community health centers

• Tertiary level: Consists of highly specialized national or regional medical centers and teaching hospitals equipped with advanced diagnostic and treatment facilities (e.g., specialized surgeries, intensive care units).
• Secondary level: Consists of smaller, departmentalized hospitals (such as district, provincial, or municipal hospitals) capable of providing basic surgical, pediatric, obstetric, and medical treatments that require hospitalization but not highly specialized equipment.', '["primary level","secondary level","tertiary level","none of the above"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:35:24.379Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:35:24.379Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:35:24.718Z"'::jsonb)
