INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1788420001971-24', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'This measures how fast people are added to the population through births.', 'crude birth rate', 'The crude birth rate, computed as the number of live births per 1,000 population in a given year, measures the overall rate at which a population is being added to through births, without adjusting for age or sex structure. Fertility rate measures births relative to women of reproductive age, and crude birth rate the broader population-growth-through-births indicator being described.', '["crude birth rate","fertility rate","Option C","crude fertility rate"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:29:20.616Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:29:20.616Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:29:21.030Z"'::jsonb),
('anki-card-1788420020027-25', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'What is the acceptable Minimum Diet Diversity?', '5 out of 8 food groups', 'According to the updated World Health Organization (WHO) and UNICEF guidelines (which are officially utilized by the Philippine Statistics Authority (PSA) and the Department of Science and Technology - Food and Nutrition Research Institute (DOST-FNRI) for reporting), Minimum Dietary Diversity (MDD) for infants and young children aged 6–23 months is defined as consuming items from at least 5 out of 8 defined food groups.

The indicator was updated globally to include breast milk as its own distinct eighth group to eliminate measurement disparities between breastfed and non-breastfed children.

The 8 defined food groups are:
1. Breast milk
2. Grains, white/pale starchy roots, tubers, and plantains
3. Legumes (pulses) and nuts
4. Dairy products (milk, infant formula, yogurt, cheese)
5. Flesh foods (meat, fish, poultry, and organ meats)
6. Eggs
7. Vitamin A-rich fruits and vegetables
8. Other fruits and vegetables', '["4 out of 8 food groups","5 out of 8 food groups","4 out of 7 food groups","5 out of 7 food groups"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:30:17.049Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:30:17.049Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:30:17.455Z"'::jsonb),
('anki-card-1788420039800-26', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Which agency leads the implementation of HAPAG (Halina''t Magtanim ng Prutas at Gulay)?', 'DILG', 'The HAPAG (Halina''t Magtanim ng Prutas at Gulay) sa Barangay Project is a community-based agriculture initiative spearheaded and implemented by the DILG pursuant to DILG Memorandum Circular No. 2023-001.

While it is heavily supported by the Department of Agriculture (DA) as a key technical partner supplying seeds, tools, and agricultural training, the DILG serves as the primary leading agency tasked with mandating and overseeing barangays nationwide in establishing their communal food gardens.', '["DA","DILG","DAR","NNC"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:28:08.892Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:28:08.892Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:28:09.639Z"'::jsonb),
('anki-card-1788420062838-27', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Which of the following questions are not answered by monitoring?', 'Were the intervention strategies appropriate to the target population?', 'Monitoring tracks what is happening (activities, inputs, participation numbers). It cannot tell you if the fundamental design or strategy of the intervention was inherently appropriate for that specific cultural or demographic group in the first place. Assessing whether a strategy is "appropriate" is a qualitative judgment that belongs strictly to formative evaluation or process evaluation.

	• Needs met: In basic operational monitoring (like supply-chain or emergency relief monitoring), managers constantly track target outputs to see if immediate operational needs (e.g., "Did everyone get their ration?") are being met.
	• Appropriate for the problem: Operational monitoring can flag immediate mismatches between a program''s activities and the problem on the ground (e.g., if a program provides food but the actual problem is a water shortage, monitoring will immediately show zero uptake).
	• Stakeholder participation: This is a textbook monitoring metric (tracking attendance and engagement levels).', '["Were the needs met?","Were the intervention strategies appropriate to the target population?","What is the level of participation of various stakeholders?","Was the program appropriate for the problem identified?"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T08:10:09.389Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T08:10:09.389Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-29T08:10:09.720Z"'::jsonb),
('anki-card-1788420103817-28', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'How many micronutrients are included in the micronutrient powder?', '15', 'The multiple micronutrient powder (MNP) formulation used in the Philippines and recommended for home fortification of complementary foods for children 6–23 months contains 15 essential vitamins and minerals, including iron, zinc, vitamin A, and iodine, in a single daily sachet (Department of Health, n.d.).', '["15","8","10","12"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:24:39.875Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:24:39.875Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:24:40.130Z"'::jsonb),
('anki-card-1788420124075-29', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Which theory explains aging as the result of chemical and mechanical exhaustion of the cells?', 'Wear-and-tear Theory', 'The Wear-and-Tear Theory (first proposed by Dr. August Weismann in 1882) compares the human body to a machine. It posits that aging is the direct result of continuous use, where cells, tissues, and vital body parts accumulate chronic chemical and mechanical exhaustion over time from internal or external stressors. Once the damage exceeds the body''s natural capacity to repair itself, overall biological function progressively declines.

• Clinker Theory: Focuses on the accumulation of metabolic waste products and chemical byproducts within normal cells, combining elements of mutation and cross-linking.
• Free Radicals Theory: Specifically attributes cellular aging and damage to the destructive nature of unstable, highly reactive molecules with unpaired electrons produced during normal oxygen metabolism.
• Generalized Errors Theory: Argues that aging occurs due to random, progressive transcription or translation mistakes during ribonucleic acid (RNA) and protein synthesis, resulting in faulty cellular structures.', '["Wear-and-tear Theory","Clinker Theory","Free Radicals Theory","Generalized Errors Theory"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:48:44.459Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:48:44.459Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:48:44.750Z"'::jsonb),
('anki-card-1788420148379-30', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'A study will be conducted to test the effects on the fat content of fried chicken using two different frying techniques. What is the appropriate research design to use?', 'experimental research', 'Because the researcher actively manipulates an independent variable (the frying technique) under controlled conditions to measure its effect on a dependent variable (fat content), this is a true experimental design. 

Correlational and observational designs, by contrast, examine naturally occurring relationships or exposures without researcher-controlled manipulation, and a descriptive survey merely characterizes existing conditions without testing a causal intervention.', '["experimental research","descriptive survey","correlational research","observational study"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:38:32.845Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:38:32.845Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:38:33.232Z"'::jsonb),
('anki-card-1788420172715-31', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Ryzza Mae is lactose intolerant. Which Starbucks order is not appropriate to be given to her?', 'Choice C (Oatmilk Cocoa Frappuccino)', 'Oatmilk Cocoa Frappuccino typically contains standard dairy-based chocolate chips/sauce and whipped cream unless requested non-dairy. In individuals with lactose intolerance, consuming dairy solids or milk fat triggers gastrointestinal symptoms.', '["Choice A","Choice B","Choice C (Oatmilk Cocoa Frappuccino)","Choice D"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:54:35.403Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:54:35.403Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:54:35.814Z"'::jsonb),
('anki-card-1788420192040-32', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Based on the latest NNS results, what is the trend of wasting in adolescents?', 'decreasing', 'Decreasing trend for wasting: 2025: 9.6% 2023: 11.5% 2021: 10.9% 2018-2019: 11.5%', '["decreasing","increasing","minimal change","no change"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:48:54.510Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:48:54.510Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:48:54.791Z"'::jsonb),
('anki-card-1788420273314-33', NULL, 'anki-deck-1788419227999-1790433139849-6x509', '<img alt="" src="data:image/webp;base64," style="color: rgb(30, 41, 59); font-weight: 600;"> What is the name of this campaign character of the 10 Kumainments introduced by the NNC?', 'Mang Moi', 'The National Nutrition Council (NNC) introduced Mang Moi (also known as Moises "Mang Moi" Dalisay) as the official campaign character and mascot patterned after the biblical Moses. He serves as the friendly messenger who carries the "10 Kumainments," which are simplified, easy-to-remember nutritional guidelines aimed at helping Filipinos practice healthier eating habits and live active lifestyles.', '["Mang Jose","Mang Tomas","Mang Ted","Mang Moi"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:13:55.502Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:13:55.502Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:13:55.874Z"'::jsonb),
('anki-card-1788420298226-34', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'This award is given to a province, city, or municipality that has shown outstanding nutrition implementation for three consecutive years.', 'CROWN Award', 'The Green Banner Award (or Green Banner Seal of Compliance) is given by the NNC to a city, municipality, or province that demonstrates very satisfactory performance in implementing its local nutrition action plan for a given year. 

An LGU that wins the Green Banner for three consecutive years becomes eligible for the higher Consistent Regional Outstanding Winner in Nutrition (CROWN) award, and sustained performance beyond that can lead to the Nutrition Honor Award, the highest distinction the NNC gives to an LGU.', '["CROWN Award","BNS Award","Nutrition Honor Award","Green Banner Award"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T13:03:33.548Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T13:03:33.548Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T13:03:33.821Z"'::jsonb),
('anki-card-1788420324706-35', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'What is the law that stipulates the provision of allowances and incentives to Barangay Health Workers (BHW)?', 'RA 7883', 'Republic Act No. 7883, the "Barangay Health Workers'' Benefits and Incentives Act of 1995," grants accredited barangay health workers benefits such as hazard allowance, subsistence allowance, and other incentives in recognition of their voluntary community health services (Republic Act No. 7883, 1995). 

• RA 7875: National Health Insurance Act 
• RA 7305: Magna Carta of Public Health Workers 
• RA 7160 is the Local Government Code', '["RA 7883","RA 7160","RA 7875","RA 7305"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T13:01:11.851Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T13:01:11.851Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T13:01:12.697Z"'::jsonb),
('anki-card-1788420349094-36', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'An innovation made by former president FE Marcos with the proclamation of Martial Law, serving to arrogate unto the Chief Executive the lawmaking powers of congress. In the Freedom Constitution of 1986, former president Corazon Aquino recognized its validity unless otherwise repealed.', 'Presidential Decree', 'Presidential Decrees (PDs) were issuances with the force of law used by former President Ferdinand E. Marcos to exercise the legislative powers of Congress during Martial Law, when the regular legislature was effectively supplanted. 

Under the 1986 Freedom Constitution, President Corazon Aquino recognized existing Presidential Decrees, such as PD No. 1569 establishing the Barangay Nutrition Scholar Program, as remaining valid unless subsequently amended or repealed.', '["Presidential Decree","Republic Act","Administrative Order","Letter of Instruction"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:52:09.748Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:52:09.748Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:52:10.100Z"'::jsonb),
('anki-card-1788420370847-37', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'What is also known as the "sickness of the older child when the next child is born"?', 'kwashiorkor', 'The term "kwashiorkor" originates from the Ga language of Ghana and translates roughly to "the sickness of the older child when the next child is born," describing the protein-energy malnutrition that develops in a toddler abruptly weaned from breastmilk after the birth of a younger sibling and shifted to a low-protein, starchy diet.', '["kwashiorkor","stunting","vitamin A deficiency disorder","marasmus"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:30:41.044Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:30:41.044Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:30:41.330Z"'::jsonb),
('anki-card-1788420389938-38', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Computed as the annual number of deaths between 28 days and 1 year divided by the number of live births per year', 'post-neonatal mortality rate', 'The post-neonatal mortality rate specifically measures deaths occurring between 28 days and 1 year of age per number of live births in a year.

• Infant mortality rate: Annual number of deaths in the first year (0–12 months) 
• Neonatal mortality rate: Annual number of deaths within the first 28 days 
• Perinatal mortality rate: Annual number of stillbirths and deaths in the first 7 days', '["post-neonatal mortality rate","infant mortality rate","neonatal mortality rate","perinatal mortality rate"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:19:00.211Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:19:00.211Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:19:00.635Z"'::jsonb),
('anki-card-1788420432801-39', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Having a sense of truthfulness and reliability with regard to the performance of roles and functions', 'integrity', 'Integrity is the value that describes a person''s consistent truthfulness, honesty, and reliability in carrying out their duties and responsibilities. It is distinguished from accountability (being answerable for outcomes and decisions), transparency (openness of processes to scrutiny), and efficiency (achieving results with minimal waste of resources). These are recognized as related but distinct standards of good governance and public service conduct.', '["integrity","efficiency","accountability","transparency"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:26:16.445Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:26:16.445Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:26:16.755Z"'::jsonb),
('anki-card-1788420454720-40', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'It is a comprehensive and integrated package of services and communication on health, nutrition, and environment for children available everyday in various settings (home, school, health facilities, and communities) by government, NGOs, private sectors, and civic organizations.', 'Garantisadong Pambata Program', 'Under Department of Health (DOH) Administrative Order No. 36 s. 2010, the Expanded Garantisadong Pambata (GP) Program was redesigned from a biannual institutional campaign into a comprehensive and integrated package of services and communication on health, nutrition, and environment for children available every day in various settings (such as the home, school, health facilities, and communities).

While it is led by the DOH and National Nutrition Council (NNC), it relies heavily on inter-agency and intersectoral cooperation with other government bodies, NGOs, private sectors, and civic organizations to systematically manage child survival interventions.

• Applied Nutrition Program: A historic nutrition initiative in the Philippines launched in the 1960s and 1970s primarily focused on school food production and feeding, which later evolved into broader national nutrition strategies.
• Healthy Settings Approach: A broader WHO health promotion framework that targets structural environments (e.g., Healthy Cities, Healthy Workplaces, Healthy Schools) but is not a package specifically called out by this child-survival definition.
• Promote Good Nutrition Program: A component under the Philippine Plan of Action for Nutrition (PPAN) primarily focused on social marketing, behavioral change communication (BCC), and nutrition education regarding infant and young child feeding (IYCF).', '["Applied Nutrition Program","Garantisadong Pambata Program","Healthy Settings Approach","Promote Good Nutrition Program"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:40:37.550Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:40:37.550Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:40:37.974Z"'::jsonb),
('anki-card-1788420477313-41', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Compared with cow''s milk, breastmilk contains:', 'less protein and minerals', 'Human breastmilk has a substantially lower protein and mineral (ash) content than cow''s milk.', '["less protein and minerals","more protein and minerals","less lactose and vitamin C","more fat and less carbohydrates"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:52:15.249Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:52:15.249Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:52:15.587Z"'::jsonb),
('anki-card-1788420497165-42', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'A process whereby an individual influences a group of individuals to achieve a common goal and relating with followers and making them change.', 'leadership', 'Leadership is defined as the process by which one individual influences and guides a group toward the achievement of a shared goal, engaging and motivating followers to adopt new behaviors or directions. 

This is broader than advocacy (influencing policy or decision-makers), mobilization (organizing resources or people for a specific action), or nutrition education (imparting knowledge), though leadership often makes use of all three.', '["leadership","advocacy","mobilization","nutrition education"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:30:55.514Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:30:55.514Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:30:55.936Z"'::jsonb),
('anki-card-1788420530499-43', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The extended global nutrition target for exclusive breastfeeding rates by 2030.', '70%', 'As of 2024, nearly half (48%) of infants under six months were exclusively breastfed, bringing the world close to the 50% target set for 2025. 

When WHO and UNICEF proposed extending the 2025 Global Nutrition Targets to 2030. By 2030, that target is to increase the rate of exclusive breastfeeding in the first six months up to at least 60%.', '["70%","50%","40%","90%"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:23:18.292Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:23:18.292Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:23:18.605Z"'::jsonb),
('anki-card-1788420554986-44', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The policy also known as the Universal Health Care (UHC) Act, which aims to provide a comprehensive set of quality and cost-effective, promotive, preventive, curative, rehabilitative, and palliative health services by fostering a whole-of-system, whole-of-government approach, and whole-of-society approach in development, implementation, monitoring, and evaluation of health policies, programs, and plans.', 'RA 11223', 'Republic Act No. 11223, the Universal Health Care Act of 2019, institutionalizes automatic health coverage for all Filipinos and mandates a whole-of-system, whole-of-government, and whole-of-society approach to delivering promotive, preventive, curative, rehabilitative, and palliative health services.', '["RA 11223","RA 11123","RA 11233","RA 12233"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:12:00.590Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:12:00.590Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:12:00.894Z"'::jsonb),
('anki-card-1788420578093-45', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Nutrition PPAs are commonly charged against GAD funds in the LGU. How much of the LGU fund is allotted for Gender and Development?', '5%', 'Pursuant to Section 36(a) of Republic Act No. 9710 (the Magna Carta of Women) and the DILG-NEDA-DBM-PCW Joint Memorandum Circular guidelines, all Local Government Units (LGUs) and national government agencies are legally mandated to allocate at least five percent (5%) of their total annual budget appropriations to support Gender and Development (GAD) plans, programs, and activities.

Because public health nutrition interventions (such as supplemental feeding for pregnant women or addressing maternal and child malnutrition) target specific vulnerable gender groups, nutrition Programs, Projects, and Activities (PPAs) are frequently funded or attributed through this mandatory 5% LGU allocation.', '["10%","5%","3%","1%"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T13:02:13.944Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T13:02:13.944Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T13:02:14.241Z"'::jsonb),
('anki-card-1788420602581-46', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'A community health program seeks to understand why mothers are not practicing recommended complementary feeding. The assessment examines mothers'' knowledge, attitudes, beliefs, available resources, social support, and encouragement from family members and health workers. Which phase of the PRECEDE-PROCEED model is being conducted?', 'Educational and ecological assessment', 'In the PRECEDE-PROCEED model, Phase 3: Educational and Ecological Assessment categorizes the factors that influence a specific health behavior into three distinct groups:
• Predisposing factors: A person''s internal knowledge, attitudes, beliefs, values, and perceptions (e.g., mothers'' knowledge, attitudes, and beliefs about complementary feeding).
• Enabling factors: The availability, accessibility, and affordability of resources or skills needed to perform the behavior (e.g., available resources).
• Reinforcing factors: The feedback, social support, and encouragement from others that either reward or discourage the behavior (e.g., social support and encouragement from family members and health workers).

• Epidemiological assessment (Phase 2): This phase focuses on identifying the specific health problems, distribution of diseases, and health trends within a population (e.g., statistics on malnutrition or stunting rates).
• Social assessment (Phase 1): This phase evaluates the community''s quality of life, subjective concerns, and social problems (e.g., poverty, unemployment, or overall well-being).
• Behavioral and environmental assessment (Phase 2/3 transition): This phase identifies the specific behaviors and external environmental conditions that contribute directly to the health problem (e.g., the actual act of not feeding the child complementary food, or a lack of clean water supply).', '["Social assessment","Educational and ecological assessment","Behavioral and environmental assessment","Epidemiological assessment"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T15:11:10.515Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T15:11:10.515Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-29T15:11:10.712Z"'::jsonb),
('anki-card-1788420633185-47', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'This law institutionalized the national poverty reduction strategy of the Philippine government, providing conditional cash transfers to poor and near-poor households to invest in health, nutrition, and education to break the intergenerational cycle of poverty.', 'RA 11310', 'Republic Act No. 11310, signed on April 17, 2019, is the 4Ps Act. It legally institutionalized the Pantawid Pamilyang Pilipino Program (4Ps).

It legally institutionalized the 4Ps as the national poverty reduction strategy and human capital investment program of the Philippines, ensuring its long-term continuity and funding through the Department of Social Welfare and Development (DSWD).

The program provides monthly human development grants (conditional cash transfers) focusing explicitly on health, nutrition, and education for qualified poor and near-poor households with children aged 0–18 or pregnant members.

• RA 11130: This is the Charter of the City of Carcar (converted into a component city).
• RA 11210: This is the 105-Day Expanded Maternity Leave Law, which is also highly relevant to public health but covers maternal leave benefits.
• RA 11120: This is the Declaration of a National Shrine or specific regional landmark declarations, unrelated to national poverty interventions.', '["RA 11310","RA 11120","RA 11130","RA 11210"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T08:53:42.103Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T08:53:42.103Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-29T08:53:42.288Z"'::jsonb),
('anki-card-1788420654769-48', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The DOH package list for emergencies and disasters refer to the following except:', 'clothing', 'The DOH standard nutrition in emergencies (NiE) package for disaster response focuses on nutrition-specific items (micronutrient supplements, weighing and measuring equipment, and processed or ready-to-use foodstuff for supplementary feeding) rather than clothing, which falls under general relief or social welfare provisions handled by other response agencies (DOH, n.d.).', '["clothing","micronutrient supplements","equipment","ready-to-use food"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:37:11.446Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:37:11.446Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:37:11.446Z"'::jsonb),
('anki-card-1788420679946-49', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'According to the latest NNS results, binge drinking, 58.7% of Filipino adults are binge drinkers. Binge drinking is defined as the excessive consumption of alcoholic beverages, specifically the intake of ___ or more (females) or ____ or more(males) standard drinks in a row by those who reported drinking alcoholic beverages in the past 30 days.', 'four, five', 'The excessive consumption of alcoholic beverages, specifically the intake of four or more (females) or five or more (males) standard drinks in a row by those who reported drinking alcoholic beverages in the past 30 days.', '["four, five","two, three","three, four","five, six"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:49:10.934Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:49:10.934Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:49:11.299Z"'::jsonb),
('anki-card-1788420710828-50', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'You are training BNS on OPT Plus. What topic should you discuss with them first?', 'Role of the BNS, their tasks, and skills needed', 'Standard BNS training protocols begin with orienting new volunteers to their overall role, responsibilities, and the skills they will need, before proceeding to technical tasks such as operating equipment or conducting anthropometric measurement (NNC, n.d.). Establishing this foundational understanding of the BNS''s purpose and duties ensures BNS grasp why the technical skills that follow matter within the Operation Timbang Plus (OPT Plus) activity.', '["Role of the BNS, their tasks, and skills needed","History of the Philippine Nutrition Program","How to do weighing","Parts of a weighing scale"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:18:43.560Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:18:43.560Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:18:43.863Z"'::jsonb),
('anki-card-1788420741695-51', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The minimum monthly income that enables a family of 5 to buy the needed food to meet their nutritional requirements and other non-basic food needs is called:', 'poverty threshold', 'The poverty threshold (or poverty line) is officially defined as the minimum income required by a family or individual to meet their basic food and non-food needs, including the cost of a nutritionally adequate food basket (PSA, n.d.). Families whose income falls below this threshold are classified as poor, making the poverty threshold a key benchmark used in nutrition and socioeconomic planning.', '["poverty threshold","per capita food cost","income elasticity","gross net income"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:52:46.233Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:52:46.233Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:52:46.534Z"'::jsonb),
('anki-card-1788420827915-52', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'What are the four components of PIMAM?
I. Community mobilization and outreach
II. Outpatient department
III. Counseling
IV. Outpatient Therapeutic care
V. Home visit
VI. Inpatient Therapeutic care
VII. Supplementary Feeding Program
VIII. Referral', 'I-IV-VI-VII', 'The four components of the Philippine Integrated Management of Acute Malnutrition (PIMAM) are:

1. I. Community mobilization and outreach
2. IV. Outpatient Therapeutic care (OTC)
3. VI. Inpatient Therapeutic care (ITC)
4. VII. Supplementary Feeding Program (SFP) (also known as Targeted Supplementary Feeding Program / Management of MAM)', '["I-IV-VI-VII","I-II-III-IV","V-VI-VII-VIII","I-III-V-VIII"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:46:46.607Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:46:46.607Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:46:46.980Z"'::jsonb),
('anki-card-1788420852536-53', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Maternal death is the death of a woman while pregnant or within ___ days of termination of pregnancy.', '42', 'The WHO defines maternal death as the death of a woman while pregnant, or within 42 days of the termination of pregnancy, from any cause related to or aggravated by the pregnancy or its management, excluding accidental or incidental causes (WHO, 2019).', '["42","36","40","48"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:37:22.482Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:37:22.482Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:37:22.482Z"'::jsonb),
('anki-card-1788420954016-54', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Arrange in chronological order the stages in developing a planned behavior change in nutrition education.
I. Recognizing the existence of a problem
II. Attempting or trialing the new behavior
III. Integrating the new behavior into daily routine
IV. Realizing that meaningful change is achievable', 'I, IV, II, III', 'Planned behavior change typically follows a sequence beginning with the person recognizing that a problem exists (I), followed by recognizing that a change is actually possible for them (IV), then attempting or trialing the new behavior (II), and finally, integrating that behavior as a lasting part of their routine (III) — a progression consistent with staged models of behavior adoption such as the Diffusion of Innovation and Precaution Adoption Process frameworks.', '["I, IV, II, III","I, II, III, IV","I, III, IV, II","IV, I, II, III"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:31:51.645Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:31:51.645Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:31:52.096Z"'::jsonb),
('anki-card-1788420977420-55', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Based on the latest national nutrition survey, which regions in the Philippines have the highest prevalence of overweight and obesity among adults?', 'NCR, CAR, Central Luzon', 'Compared with the national estimate, the National Capital Region has the highest obesity prevalence with 52.7%, followed by the Cordillera Administrative Region (50.6%) and Central Luzon (49.6%).', '["NCR, CAR, Central Luzon","NCR, BARMM, MIMAROPA","NCR, BARMM, SOCCSKSARGEN","NCR, CALABARZON, MIMAROPA"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:18:10.956Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:18:10.956Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:18:11.331Z"'::jsonb),
('anki-card-1788421022418-56', NULL, 'anki-deck-1788419227999-1790433139849-6x509', '<img alt="" src="data:image/webp;base64,">
Who is this Filipino nutritionist and politician who served as Deputy Minister of Health from 1983 to 1986 during the presidency of Ferdinand Marcos?', 'Dr. Florentino Solon', 'Dr. Florentino S. Solon was a highly influential public health physician and nutritionist widely recognized as the country''s "champion of nutrition". He served as the first Executive Director of both the National Nutrition Council (NNC) and the Nutrition Center of the Philippines (NCP).

In politics, he was appointed by President Ferdinand Marcos Sr. as the Mayor of Cebu City, serving from 1978 until 1983. He resigned from his mayoral post in 1983 when Marcos appointed him to the national level to serve as the Deputy Minister of Health, a role he held until 1986.

Among his structural legacies in nutrition, he pioneered the establishment of specialized malnutrition wards ("malwards"), nutri-huts, nutri-buses, and early food-fortification initiatives like the iron and vitamin A-fortified pan de sal.

• Dr. Francisco Santos: A pioneer agricultural chemist and nutritionist known for his extensive studies on the nutritional values of local Filipino foods and crops.
• Dr. Coronado Pascual: A major public health figure who served as a Director of the Food and Nutrition Research Center (FNRC) and led early coordination attempts through the National Coordinating Council on Food and Nutrition (NCCFN) in 1959.
• Dr. Juan Salcedo, Jr.: A celebrated National Scientist and former Secretary of Health renowned for leading the historic Bataan Rice Enrichment Project which helped eradicate beriberi in the Philippines.', '["Dr. Juan Salcedo, Jr.","Dr. Coronado Pascual","Dr. Francisco Santos","Dr. Florentino Solon"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:59:58.265Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:59:58.265Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:59:58.921Z"'::jsonb),
('anki-card-1788421052318-57', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'The ECCD System Act (RA 12199) that strengthens the country''s ECCD system to address gaps in healthcare, nutrition, early childhood education, safety, security, and social services for children aged five and below. This law also transferred the ECCD Council under which agency?', 'DILG', 'Under the Early Childhood Care and Development (ECCD) System Act (Republic Act No. 12199), the ECCD Council was officially attached to the Department of the Interior and Local Government (DILG).

Previously, under the Early Years Act of 2013 (RA 10410), the ECCD Council was attached to the Department of Education (DepEd). The strategic shift to the DILG was made to strengthen local government unit (LGU) accountability and compliance, ensuring that local communal Day Care and Child Development Centers across every barangay are fully funded, maintained, and operational.

Republic Act No. 12199, the Early Childhood Care and Development (ECCD) System Act signed in May 2025, repealed the earlier Early Years Act of 2013 (RA 10410) and reorganized comprehensive health, nutrition, and early education services for children from conception through age eight, assigning children below five to the ECCD Council and those aged five to eight to the Department of Education (Republic Act No. 12199, 2025).', '["DILG","DepED","DSWD","DOH"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T08:09:50.232Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T08:09:50.232Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-29T08:09:50.567Z"'::jsonb),
('anki-card-1788421080619-58', NULL, 'anki-deck-1788419227999-1790433139849-6x509', '<img alt="" src="data:image/webp;base64," style="font-style: inherit; font-weight: inherit;">
Sa palabas ng ABS-CBN Foundation na Dok Ricky, Pedia ng Barangay, sino ang gumanap na Dok Riki Bautista na katambal ni Dominic Ochoa?', 'Alessandra de Rossi', 'Ang tamang sagot ay Alessandra de Rossi, na gumanap bilang si Dra. Marikina "Dok Riki" Bautista sa "sitcom-mentary" na palabas na Dok Ricky, Pedia ng Barangay.', '["Alessandra de Rossi","Yen Santos","Arci Muñoz","Bella Padilla"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:50:05.466Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:50:05.466Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:50:05.813Z"'::jsonb),
('anki-card-1788421105725-59', NULL, 'anki-deck-1788419227999-1790433139849-6x509', '<img alt="" src="data:image/webp;base64," style="font-style: inherit; font-weight: inherit;">Si Nash Aguas ay bumida sa anong programang pang-nutrisyon na pinalabas ng ABS-CBN?', 'Why Not?', 'Ang Why Not? ay isang edu-infotainment at nutritional television show para sa mga bata na ipinalabas sa ABS-CBN Channel 2 at Knowledge Channel noong 2011. Ito ay pinangunahan nina Nash Aguas (bilang si Bot) at Kelly Nakanishi (bilang si Vi) sa pakikipagtulungan ng National Nutrition Council (NNC) at ABS-CBN Lingkod Kapamilya Foundation, Inc. Layunin ng programa na hikayatin ang mga bata na magkaroon ng masusustansyang gawi sa pagkain sa pamamagitan ng mga nakatutuwang kuwento at parodies tungkol sa mga prutas at gulay.', '["Why Not?","Busog Lusog","Dok Ricky, Pedia ng Barangay?","Bagito"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T13:03:17.407Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T13:03:17.407Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T13:03:17.834Z"'::jsonb),
('anki-card-1788421140019-60', NULL, 'anki-deck-1788419227999-1790433139849-6x509', 'Which is NOT a theme of the Philippine Nutrition Month?', 'Bayan at nutrisyon, alagaan natin ngayon', '• Malnutrisyon: tuklasin at pugsain (1990)
• Buto at ngipin patibayin, gatas ating inumin (1996)
• Kumain nang RIGHT, para maging batang BRIGHT (2006)', '["Bayan at nutrisyon, alagaan natin ngayon","Kumain nang RIGHT, para maging batang BRIGHT","Malnutrisyon: tuklasin at pugsain","Buto at ngipin patibayin, gatas ating inumin"]'::jsonb, '["General Dietetics"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T12:17:31.908Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T12:17:31.908Z"'::jsonb, '"2026-09-26T14:32:30.220Z"'::jsonb, '"2026-10-27T12:17:31.908Z"'::jsonb),
('anki-card-1788423009882-0', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'Lactose is composed of:', 'Glucose and galactose', 'Lactose is a disaccharide composed of glucose and galactose.

• Glucose and fructose form sucrose, not lactose.
• Fructose and galactose do not form lactose.
• Glucose and sucrose are not the two monosaccharides that make up lactose.', '["Glucose and galactose","Glucose and fructose","Glucose and sucrose","Fructose and galactose"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:41:12.170Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:41:12.170Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:41:12.170Z"'::jsonb),
('anki-card-1788423125908-1', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which type of amino acid must be obtained from the diet because the body cannot synthesize it in sufficient amounts?', 'Essential amino acid', 'Essential amino acids cannot be synthesized by the body in adequate amounts and therefore must be supplied by the diet.

Remember the Essential AAs: PVTTIMHALL Phenylalanine Valine Threonine Tryptophan Isoleucine Methionine Histidine Leucine Lysine

• Non-essential amino acids can generally be synthesized by the body.
• Structural amino acid is not the nutritional classification described in the question.
• Neutral amino acid describes a chemical property rather than the nutritional requirement being tested.', '["Essential amino acid","Neutral amino acid","Non-essential amino acid","Structural amino acid"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:40:12.906Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:40:12.906Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:40:12.906Z"'::jsonb),
('anki-card-1788423147596-2', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'All are biological contaminants except:', 'Pesticide residue', 'Biological contaminants are hazards that come from living organisms or their products:
• Paralytic shellfish poisoning — Biological. It is caused by toxins produced by certain marine microorganisms, particularly dinoflagellates.
• Hepatitis A virus — Biological. Viruses are biological contaminants and can be transmitted through contaminated food or water.
• Aflatoxin from molds — Biological. Aflatoxins are toxins produced by certain molds, particularly Aspergillus species.
• Pesticide residue — Chemical, not biological. Pesticides are chemical substances that can remain on or in food.

Remember:
• Biological = bacteria, viruses, parasites, molds, and their toxins
• Chemical = pesticides, cleaning chemicals, heavy metals, etc.', '["Pesticide residue","Paralytic shellfish poisoning","Hepatitis A virus","Aflatoxin from molds"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:32:37.050Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:32:37.050Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:32:37.050Z"'::jsonb),
('anki-card-1788423190457-3', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'A triglyceride is composed primarily of:', 'One glycerol molecule and three fatty acids', 'One glycerol plus three fatty acids describes the basic structure of a triglyceride.

• A triglyceride has a glycerol backbone esterified with three fatty acids.
• Triglycerides are lipids, not compounds made from amino acids and glycerol.
• Glucose is not the backbone of a triglyceride.', '["One glycerol molecule and three fatty acids","Three glycerol molecules and one fatty acid","One glucose molecule and three fatty acids","Three amino acids and one glycerol molecule"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:40:26.360Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:40:26.360Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:40:26.360Z"'::jsonb),
('anki-card-1788423222657-4', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'During dry heating of starch, the formation of shorter-chain products is known as formation of:', 'Dextrins', 'Dextrins are shorter-chain products formed when starch is subjected to dry heat.

• Gluten is a protein complex associated with wheat dough, not a starch breakdown product.
• Casein is the principal protein of milk.
• Pectin is a structural polysaccharide found in plant tissues.', '["Dextrins","Pectin","Gluten","Casein"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:36:17.376Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:36:17.376Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:36:17.376Z"'::jsonb),
('anki-card-1788423256707-5', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which enzyme is associated with the tenderizing activity of figs?', 'Ficain', 'Ficain is a proteolytic enzyme found in figs and can contribute to meat tenderization.

• Papain is associated with papaya.
• Bromelain is associated with pineapple.
• Lactase hydrolyzes lactose and is not the fig enzyme used for meat tenderizing.', '["Ficain","Papain","Bromelain","Lactase"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:31:25.079Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:31:25.079Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:31:25.079Z"'::jsonb),
('anki-card-1788423289524-6', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which type of cooking method is generally most appropriate for a tender cut of meat?', 'Dry-heat cooking', 'Dry-heat methods are generally appropriate for tender cuts because they do not require prolonged moist cooking.

Tender cuts of meat come from muscles that do the least work (such as the loin or rib areas) and contain very little tough connective tissue (collagen).

Because these cuts are already naturally tender, they do not require prolonged cooking to break down tough fibers. Dry-heat cooking methods—such as grilling, broiling, roasting, sautéing, or pan-frying—cook the meat quickly at high temperatures, preserving its natural juices and preventing it from becoming overcooked and dry.', '["Dry-heat cooking","Stewing","Braising","Moist cooking"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:36:45.692Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:36:45.692Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:36:45.692Z"'::jsonb),
('anki-card-1788423318292-7', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'A nonenzymatic browning reaction associated with sugar undergoing heating; prolonged heating above one hundred sixty (>160) degrees Celsius (three hundred twenty (32) degrees Fahrenheit) resulting in dark brown, highly viscous syrup with distinctive taste and odor.', 'Caramelization', 'Caramelization is a type of non-enzymatic browning that involves the thermal decomposition and pyrolysis of sugars alone, completely independent of proteins or amino acids.

Common disaccharides like sucrose (table sugar) and monosaccharides like glucose melt and begin to caramelize rapidly at around 160°C (320°F). Prolonged heating creates complex polymers (caramelans, caramelens, and caramelins) and volatile flavor compounds, transforming clear sugar crystals into a dark, thick, highly aromatic syrup.

• Oxidation is a reaction with oxygen. 
• Maillard Browning is sugar + amino acids, not pure sugar.
• Reduction is the process of simmering or boiling a liquid uncovered so that water evaporates', '["Caramelization","Oxidation","Maillard browning","Reduction"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:37:41.308Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:37:41.308Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:37:41.308Z"'::jsonb),
('anki-card-1788423352226-8', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'Cooking an egg primarily causes its proteins to undergo:', 'Denaturation and coagulation', 'Egg proteins denature and then coagulate during cooking, changing the egg from a fluid to a firmer structure.

• Gelatinization is a starch phenomenon involving starch and water under heat.
• Caramelization is a nonenzymatic browning reaction involving sugars.
• Retrogradation refers primarily to reassociation of starch molecules after gelatinization.', '["Denaturation and coagulation","Gelatinization","Retrogadation","Caramelization"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:40:19.240Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:40:19.240Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:40:19.240Z"'::jsonb),
('anki-card-1788423386950-9', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'Acrolein is associated with:', 'Overheated fats', 'Acrolein can form when fats are overheated, particularly when glycerol components break down.

• Fermented milk is associated with lactic acid fermentation rather than acrolein formation.
• Gelatinized starch results from starch absorbing water and swelling during heating.
• Fresh fruits are not the food phenomenon described by acrolein formation.', '["Overheated fats","Fresh fruits","Fermented milk","Gelatinized starch"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:37:04.421Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:37:04.421Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:37:04.421Z"'::jsonb),
('anki-card-1788423404885-10', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'A menu that repeats according to a planned sequence over a specified period is called a:', 'Cycle menu', 'A cycle menu features a series of menus that repeat in a set pattern (such as weekly, bi-weekly, or monthly) over a designated period.

 This is widely used in institutional settings like schools, hospitals, long-term care facilities, and corporate cafeterias to simplify purchasing, control costs, and maintain dietary variety.

• Du jour menu: A menu "of the day" that changes daily depending on what is fresh or left over.
• Single-use menu: A menu planned and used only once, typically for a special event, holiday banquet, or one-time catered function.
• Static menu: A fixed menu that remains the same every day, commonly found in commercial restaurants.', '["Static menu","Cycle menu","Du jour menu","Single-use menu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:39:44.179Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:39:44.179Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:39:44.179Z"'::jsonb),
('anki-card-1788423421410-11', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'The soul of every foodservice operation.', 'Menu', 'In foodservice management, the menu is universally referred to as the "soul," focal point, or primary control of the entire operation.

It dictates everything that happens in the facility—including purchasing, budget, required equipment, staff skill levels, kitchen layout, and guest satisfaction.', '["Dietitian","Menu","Meal Plan","Income generation"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:34:37.570Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:34:37.570Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:34:37.570Z"'::jsonb),
('anki-card-1788423454492-12', NULL, 'anki-deck-1788422977034-1791992590890-w1g2h', 'Which statement best describes dietary fiber?', 'It consists largely of nondigestible carbohydrate components and related substances', 'Dietary fiber is a broad term for the structural components of plant foods—including polysaccharides like cellulose, hemicellulose, pectins, and non-carbohydrate polymers like lignin.

Unlike sugars and starches, the human digestive system lacks the specific enzymes needed to break down the chemical bonds found in dietary fiber. As a result, it passes through the stomach and small intestine relatively intact.

• It is a form of animal protein: Fiber is exclusively derived from plant foods (fruits, vegetables, grains, legumes, nuts); animal products contain zero dietary fiber.
• It is composed entirely of dietary fat: Fiber belongs to the carbohydrate family of macronutrients, not fats or lipids.
• It is completely digested in the small intestine: Fiber resists enzymatic breakdown in the small intestine completely. Instead, it moves into the large intestine (colon), where it is either partially fermented by beneficial gut bacteria (soluble fiber) or excreted unchanged (insoluble fiber).', '["It is completely digested in the small intestine","It consists largely of nondigestible carbohydrate components and related substances","It is composed entirely of dietary fat","It is a form of animal protein"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 4, '', '{"dueDate":"2026-11-25T02:33:51.064Z","interval":20,"easeFactor":2.5,"repetitions":5}'::jsonb, '"2026-11-05T02:33:51.064Z"'::jsonb, '"2026-10-14T15:43:12.925Z"'::jsonb, '"2026-11-05T02:33:51.064Z"'::jsonb)
