INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('anki-card-1788430431523-3', NULL, 'anki-deck-1788430296776-1790433145942-55yvl', 'A delivery arrives at a foodservice operation. The invoice indicates 20 cases of milk, but the receiver counts only 18 cases. Two cases are also found to have damaged packaging. What should the receiver do FIRST?', 'Document the quantity and condition discrepancy and follow the operation''s receiving procedure.', 'Receiving requires verification of quantity, quality, and condition against purchasing documents. Discrepancies should be documented and handled according to established procedures.', '["Document the quantity and condition discrepancy and follow the operation''s receiving procedure.","Accept all 20 cases and report the discrepancy at the end of the day.","Accept the shipment because the supplier''s invoice is the official record."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T15:40:46.480Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T15:40:46.480Z"'::jsonb, '"2026-09-26T14:32:29.599Z"'::jsonb, '"2026-10-27T15:40:46.480Z"'::jsonb),
('anki-card-1788430453579-4', NULL, 'anki-deck-1788430296776-1790433145942-55yvl', 'During monitoring, a foodservice employee discovers that a batch of cooked ground beef has reached only 65°C, below the established critical limit. What is the MOST appropriate immediate response?', 'Increase the cooking process until the established critical limit is achieved.', 'A deviation from a critical limit requires corrective action. If the food can still safely undergo the control step, it should be processed until the critical limit is achieved.', '["Increase the cooking process until the established critical limit is achieved.","Serve the food because it has already been cooked.","Place the food in refrigeration and serve it tomorrow."]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T15:41:30.406Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T15:41:30.406Z"'::jsonb, '"2026-09-26T14:32:29.599Z"'::jsonb, '"2026-10-27T15:41:30.406Z"'::jsonb),
('anki-card-1788430478816-5', NULL, 'anki-deck-1788430296776-1790433145942-55yvl', 'A foodservice manager discovers that one of the following foods was left unrefrigerated for several hours. Which food has the highest risk for bacterial growth, assuming all were initially free of pathogens?', 'Cooked chicken breast', 'Cooked chicken provides several favorable conditions described by FAT TOM: food, available moisture, nutrients, and a favorable temperature/pH environment. The other foods have characteristics such as low moisture or high salt that inhibit microbial growth.', '["Cooked chicken breast","Peanut butter","Salted dried fish","Pepper"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T15:35:21.916Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T15:35:21.916Z"'::jsonb, '"2026-09-26T14:32:29.599Z"'::jsonb, '"2026-10-27T15:35:21.916Z"'::jsonb),
('anki-card-1788430504953-6', NULL, 'anki-deck-1788430296776-1790433145942-55yvl', 'During HACCP development for a foodservice operation, the team determines that chicken must reach an internal temperature of at least 74°C for the specified cooking process. Which HACCP principle is being applied when this temperature is established as the criterion that separates safe from unsafe processing?', 'Establishing critical limits', 'A critical limit is a measurable criterion that must be met at a CCP to control a significant hazard. Temperature and time are common examples.', '["Establishing critical limits","Conducting a hazard analysis","Identifying critical control points","Establishing critical limits"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T15:41:05.930Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T15:41:05.930Z"'::jsonb, '"2026-09-26T14:32:29.599Z"'::jsonb, '"2026-10-27T15:41:05.930Z"'::jsonb),
('anki-card-1788430529724-7', NULL, 'anki-deck-1788430296776-1790433145942-55yvl', 'A foodservice operation orders 40 kg of ground beef. The specification requires 80% lean meat, delivery at 5°C or below, and packaging free from tears or leakage. The supplier delivers 40 kg of meat at 10°C, but several packages are leaking. Which purchasing principle is MOST directly violated?', 'Right quality', 'Quantity is correct, but temperature and packaging condition fail to meet the established quality specifications.', '["Right quality","Right quantity","Right quality","Right price"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T15:38:15.467Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T15:38:15.467Z"'::jsonb, '"2026-09-26T14:32:29.599Z"'::jsonb, '"2026-10-27T15:38:15.467Z"'::jsonb),
('anki-card-1788430554378-8', NULL, 'anki-deck-1788430296776-1790433145942-55yvl', 'A long-term care facility develops an eight-week menu. During lunch, residents receive the same entrée, vegetable, dessert, and beverage selected by the facility, with no choices offered within any menu category. However, the menu changes from Week 1 to Week 8 and then repeats. Which classification BEST describes the menu?', 'Non-selective cycle menu', 'The menu is non-selective because residents have no choices, and it is a cycle menu because the planned menu repeats after a specified period.', '["Non-selective cycle menu","Selective cycle menu","Non-selective cycle menu","Limited selective menu"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T15:36:57.049Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T15:36:57.049Z"'::jsonb, '"2026-09-26T14:32:29.599Z"'::jsonb, '"2026-10-27T15:36:57.049Z"'::jsonb),
('anki-card-1788430576033-9', NULL, 'anki-deck-1788430296776-1790433145942-55yvl', 'A receiver is given a purchase order that does not contain the quantities ordered. The receiver independently counts, weighs, and inspects every delivered item before comparing the results with the supplier’s invoice and purchase records. Which receiving method is being used?', 'Blind-check receiving', 'In blind receiving, the receiver does not initially see the quantities ordered and must independently determine the quantity and condition of the products before comparison with purchasing documents.', '["Blind-check receiving","Open-check receiving","Blind-check receiving","Invoice receiving"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-28T15:37:39.715Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-27T15:37:39.715Z"'::jsonb, '"2026-09-26T14:32:29.599Z"'::jsonb, '"2026-10-27T15:37:39.715Z"'::jsonb),
('anki-card-1788430933252-0', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'What is the Temperature Danger Zone?', '41 to -140ºF', 'The Temperature Danger Zone represents the environmental range where foodborne pathogenic bacteria (such as Salmonella, E. coli, and Staphylococcus aureus) reproduce most rapidly. Under optimal conditions inside this window, bacterial populations can double in number in as little as 10 to 20 minutes.

To protect public health, regulatory standards mandate keeping cold foods strictly below 41ºF and hot foods above 140ºF (or 135ºF depending on the specific municipal framework) to prevent bacteria from reaching dangerous, illness-causing thresholds.', '["0 to -10ºF","41 to -140ºF","161 – 212ºF","32 – 40ºF"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-30T15:12:52.981Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-27T15:12:52.981Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-27T15:12:53.079Z"'::jsonb),
('anki-card-1788430950542-1', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'Which is the least factor to consider in meal planning?', 'Client''s preference', '', '["Nutritive value","Client''s preference","Food budget and cost","Number and type of clientele"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-30T15:12:40.346Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-27T15:12:40.346Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-27T15:12:40.440Z"'::jsonb),
('anki-card-1788430970615-2', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'The following are the criteria for determining whether a food is spoiled, except:', 'None of the above', 'To classify a food as "unspoiled" or acceptable, it must satisfy all three of the positive benchmarks listed in options A, B, and C. Therefore, none of them are exceptions.', '["None of the above","Freedom from objectable, but not unsafe, contaminants","Freedom from decomposition resulting from enzymatic reactions inherent in the food or reactions between the food and its environment or decomposition from microbial growth","Freedom from physical damage"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-11-25T14:48:44.588Z","interval":27,"easeFactor":2.1,"repetitions":5}'::jsonb, '"2026-10-29T14:48:44.588Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-29T14:48:44.790Z"'::jsonb),
('anki-card-1788430985692-3', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'What is considered the catalyst that drives all food service operational functions?', 'Menu', 'The menu is considered the primary driver, catalyst, and focal point of the entire foodservice operation. It dictates every other function within the system, including:

• Purchasing and Procurement: What raw materials and ingredients need to be ordered.
• Equipment and Space Requirements: The types of ovens, prep stations, or storage needed to prepare the items.
• Manpower and Labor: The skill level and number of staff required for preparation and service.
• Budget and Food Cost: The pricing strategy, financial targets, and cost control measures.', '["Food cost","Manpower","Menu","Materials"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-30T15:12:35.003Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-27T15:12:35.003Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-27T15:12:35.106Z"'::jsonb),
('anki-card-1788431002781-4', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'The following is the purpose of producing quality foods in large volumes, except:', 'Improve aesthetic quality', 'In quantity food production (such as institutional catering or commercial food service), food items must be processed in bulk to feed a large number of people efficiently. While massive industrial production successfully drives safety, flavor modification, and nutrient conservation via standardized operational formulas, it strips away the ability to execute delicate, artistic, or customized plating.

Producing food in massive batches requires prioritizing uniform output speed, thermal safety, and broad scale-stability over intricate visual designs. Because bulk distribution environments (like hospital lines, cafeteria trays, or packaging conveyor belts) inherently limit individual presentation, enhancing or customizing the refined aesthetic beauty of a dish is generally not an achievable technical objective or purpose of mass cooking.', '["Improve aesthetic quality","Develop, enhance, or alter flavor","Minimize quality losses","Destroy harmful microorganisms"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T13:05:42.423Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T13:05:42.423Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-29T13:05:42.606Z"'::jsonb),
('anki-card-1788431026511-5', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'The following is the importance of food safety, except:', 'To reverse the spread of diseases', 'Food safety is a preventive discipline, not a curative treatment. While proper food handling, sanitation, and temperature control work effectively to prevent the transmission of foodborne pathogens, food safety measures alone cannot "reverse" or cure the spread of diseases once a population or individual is infected. Dealing with the active spread or reversal of clinical diseases falls under the scope of medical treatments, epidemiology, pharmaceutical interventions, and clinical healthcare protocols.

• To create and maintain healthful and hygienic conditions for the family: This is a fundamental, domestic goal of everyday food hygiene to protect household health.
• To gain market access: Under national regulations such as the Food Safety Act of 2013 (RA 10611), ensuring rigid food safety compliance is a legal mandatory prerequisite to protect consumer health and facilitate market access for local commercial food products globally and locally.
• To prevent food contamination and food spoilage: This is a primary technical purpose of food safety frameworks—keeping biological, chemical, and physical hazards out of the food supply chain.', '["To create and maintain healthful and hygienic conditions for the family","To prevent food contamination and food spoilage","To reverse the spread of diseases","To gain market access"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T13:05:46.716Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T13:05:46.716Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-29T13:05:46.907Z"'::jsonb),
('anki-card-1788431045360-6', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'What is the right temperature for dry storage?', '60 – 70ºF', 'In foodservice and meal management, dry storage areas are designed to preserve dry staples and canned goods by protecting them from heat and moisture.

Standard foodservice guidelines specify that dry storage temperatures should ideally be maintained between 50ºF and 70ºF (10ºC to 21ºC).

60 – 70ºF fits securely within this recommended parameters. Keeping the room within this temperature range slows chemical reactions, prevents premature food spoilage, and extends the overall shelf life of dry goods.

• 29 to 33ºF: This represents the temperature range used for chilled or super-chilled food storage (such as fresh fish, meat, or poultry holding sections), which is just slightly above or at freezing point.
• 34 – 40ºF: This is the standard operational temperature range for refrigeration / cold storage to prevent bacterial multiplication in perishable commodities.
• 0 to -10ºF: This is the legal threshold required for freezer storage to ensure food remains solidly frozen and safe over long periods.', '["34 – 40ºF","0 to -10ºF","60 – 70ºF","29 to 33ºF"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T13:06:06.624Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T13:06:06.624Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-29T13:06:06.815Z"'::jsonb),
('anki-card-1788431095035-7', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'Compute the percent shrinkage of pork, casim (raw weight: 850 g, cooked weight: 600 g).', '29.41%', 'Percent Shrinkage: (raw weight - cooked weight) / raw weight * 100= (850 g - 600 g) / 850 g * 100 = 29.41%', '["29.41%","25.00%","38.30%","41.67%"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-30T15:13:06.417Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-27T15:13:06.417Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-27T15:13:06.514Z"'::jsonb),
('anki-card-1788431111211-8', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'It is a prediction of food needs for a day or other specific period of time.', 'Forecasting', 'In foodservice and operations management, forecasting is defined as the process of predicting or estimating future food needs for a day or another specific period of time. 

It serves as a data-driven tool to ensure the purchasing department orders the correct volume of ingredients and the kitchen staff prepares the right amount of food, which directly minimizes food waste and prevents overproduction.

• Organizing: The management function focused on assembling resources, assigning tasks, and establishing structure to carry out plans.
• Planning: The broader process of defining objectives and determining the overall courses of action to meet them. While planning is based on a forecast, the act of predicting specific time-bound needs is forecasting itself.
• Managing: The overarching process of directing, controlling, and coordinating an organization or system.', '["Forecasting","Planning","Organizing","Managing"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-30T15:13:21.881Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-27T15:13:21.881Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-27T15:13:21.980Z"'::jsonb),
('anki-card-1788431128986-9', NULL, 'anki-deck-1788430913642-1790433139833-ykmiq', 'It is the process of getting the right product into a facility at the right time and in a form that meets pre-established standards for quantity, quality, and price.', 'Purchasing', 'In foodservice and meal management systems, Purchasing (or procurement) is officially defined as the administrative process of securing the right product, in the right amount, at the right time, from the right supplier, and at the right price. It includes the strategic decision-making involved in establishing product specifications and negotiating market costs prior to the delivery of goods.

• Food Production: The operational stage where raw or prepared ingredients are transformed into finished menu items using various cooking methods.
• Receiving: The specific operation where a facility inspects delivered goods to ensure they match the exact quality, quantity, and price specs previously agreed upon during the purchasing stage. (While Receiving physically "gets" the product into the building, Purchasing is the entire managerial process that orchestrates it).
• Menu planning: The foundational phase where food items are selected and designed on paper based on the nutritional and financial goals of the facility.', '["Menu planning","Food Production","Receiving","Purchasing"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'hard', 5, '', '{"dueDate":"2026-12-05T13:05:18.762Z","interval":37,"easeFactor":2.3,"repetitions":5}'::jsonb, '"2026-10-29T13:05:18.762Z"'::jsonb, '"2026-09-26T14:32:29.654Z"'::jsonb, '"2026-10-29T13:05:18.951Z"'::jsonb),
('anki-card-1788431412824-0', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'Which ingredient refers to the “K” in the abbreviated dish KBL?', 'Kadios', 'KBL in Ilonggo stands for Kadyos, Baboy, Langka, a famous traditional soup or stew from the Western Visayas region of the Philippines.[Image: KBL (Kadyos, Baboy, at Langka) Recipe]', '["Kadios","Kamote","Kamias","Kalamay"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'easy', 5, '', '{"dueDate":"2026-12-16T07:06:05.123Z","interval":53,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:06:05.123Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-11-10T01:05:27.805Z"'::jsonb),
('anki-card-1788431434345-1', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'Which of the following BEST describes the primary goal of meal management?', 'Using resources effectively and efficiently to create meals', 'Planning and managing community nutrition programs', '["Preparing meals using the most expensive ingredients available","Using resources effectively and efficiently to create meals","Increasing the number of dishes served in every meal","Reducing preparation time regardless of nutritional quality"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'medium', 5, '', '{"dueDate":"2026-12-11T07:07:38.438Z","interval":48,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:07:38.438Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-11-08T12:24:43.573Z"'::jsonb),
('anki-card-1788431450436-2', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'A cook wants to minimize nutrient loss when preparing vegetables. Which practice is MOST consistent with the recommendations in the material?', 'Cook vegetables with as little water as possible', '', '["Soak thinly sliced vegetables in water before cooking","Cut vegetables into very small pieces","Cook vegetables with as little water as possible","Discard the cooking water immediately after boiling"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'medium', 5, '', '{"dueDate":"2026-12-03T07:07:29.758Z","interval":40,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:07:29.758Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-10-24T07:07:29.758Z"'::jsonb),
('anki-card-1788431467644-3', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'A meal manager is planning a menu for a household with limited financial resources, limited cooking equipment, and restricted preparation time. Which principle of meal management is MOST relevant?', 'Using available human and non-human resources efficiently', '', '["Maximizing the variety of ingredients regardless of availability","Using available human and non-human resources efficiently","Selecting meals primarily according to social status","Prioritizing aesthetic presentation over nutritional adequacy"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'medium', 5, '', '{"dueDate":"2026-12-08T07:05:28.140Z","interval":45,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:05:28.140Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-10-24T07:05:28.140Z"'::jsonb),
('anki-card-1788431484136-4', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'A meal manager wants to improve the efficiency and safety of movement during food preparation. Which kitchen design concept should be considered?', 'Work triangle', '', '["Food danger zone","Work triangle","Cycle menu","Mise en place"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'medium', 5, '', '{"dueDate":"2026-12-03T07:07:55.705Z","interval":40,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:07:55.705Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-10-24T07:07:55.705Z"'::jsonb),
('anki-card-1788431555320-5', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'Etag is a smoked meat traditionally made and used in cooking in _____.', 'CAR', 'Etag is a smoked meat traditionally made and used in cooking in the Cordillera region of the Philippines. It is usually made from slabs of pork (like belly or neck).[Image: Etag – Pinoy Reads]The meat is cured heavily with salt and then air-dried or smoked over a wood fire for weeks or months. Locals often prefer wood from the alnus tree to give the meat a pleasant, aromatic smoke flavor.', '["CAR","Region II","Region I","Region III"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'easy', 5, '', '{"dueDate":"2026-12-16T07:06:54.286Z","interval":53,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:06:54.286Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-11-10T01:05:27.859Z"'::jsonb),
('anki-card-1788431618901-6', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'Sirkele is a regional iteration of which popular local dish?', 'Dinuguan


Serkele is a hearty, soupy Filipino blood-based stew made with beef innards instead of pork. It originated in Baliwag, Bulacan.

Aling Luring (Leonila Castro-Trinidad) created the recipe in 1972 at her local snack shop. The name comes from the word "circle," describing how the sliced innards curl up while boiling.

[Image: sirkele – Tita S Travels]', '', '["Sisig","Dinuguan","Bopis","Kilawin"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'easy', 4, '', '{"dueDate":"2026-10-08T20:00:00.000Z","interval":22,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-11-10T01:05:27.644Z"'::jsonb),
('anki-card-1788431664461-7', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'The meal concept known as “Banchan” is from which international cuisine', 'Korean', '[Image: Banchan – Curious Foodies]Banchan are small Korean side dishes served in the middle of the table to share alongside cooked rice and soup.', '["Korean","Vietnamese","Japanese","Chinese"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'medium', 5, '', '{"dueDate":"2026-12-06T07:07:20.316Z","interval":43,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:07:20.316Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-11-10T01:05:27.698Z"'::jsonb),
('anki-card-1788431685651-8', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', 'Which situation BEST illustrates the concept of time-temperature abuse in food safety?', 'Leaving potentially hazardous food in the temperature danger zone for an extended period', '', '["Storing raw chicken on the bottom shelf of the refrigerator","Using a separate chopping board for vegetables","Leaving potentially hazardous food in the temperature danger zone for an extended period","Washing a cutting board with hot water and soap after use"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'medium', 5, '', '{"dueDate":"2026-12-06T07:06:16.519Z","interval":43,"easeFactor":2.5,"repetitions":4}'::jsonb, '"2026-10-24T07:06:16.519Z"'::jsonb, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-10-24T07:06:16.519Z"'::jsonb),
('anki-card-1788431809370-9', NULL, 'anki-deck-1788431213230-1790433145985-sfnk4', '[Image: Manchego - Futura Foods]Manchego is a variant of hard cheese that originated from this European country.', 'Spain
Manchego cheese is made in the La Mancha region of Spain from the milk of Manchega sheep.


🇮🇹 Italy: Famous for Parmigiano-Reggiano (the "King of Cheeses") and Pecorino Romano, which is a sharp, salty hard cheese made from sheep''s milk, similar to Manchego.








🇫🇷 France: Famous for Comté and Beaufort, which are rich, nutty hard cheeses made from cow''s milk in the Alpine regions.




🇵🇹 Portugal: Famous for Queijo da Serra da Estrela and Queijo de Azeitão.', '', '["Italy","France","Spain","Portugal"]'::jsonb, '["Food Service Systems"]'::jsonb, NULL, 'medium', 3, '', '{"dueDate":"2026-10-06T20:00:00.000Z","interval":20,"easeFactor":2.5,"repetitions":3}'::jsonb, NULL, '"2026-09-26T14:32:30.503Z"'::jsonb, '"2026-11-10T01:05:27.752Z"'::jsonb),
('card-1794233130997-0', NULL, 'deck-1794233130997-zs17b', 'Continue View Questions The responsibility of ensuring that cooking objectives are consistently achieved rests primarily on the:', 'Foodservice Manager', 'The foodservice manager carries the primary operational responsibility for supervising production staff, establishing workflow controls, and ensuring that quality and cooking objectives are consistently met.

• Diet Clerk: Primarily handles patient meal tally sheets, diet orders, and trayline clerical tracking rather than kitchen production supervision.
• Storekeeper: Manages inventory, receiving, and storage of goods rather than actual kitchen cooking operations.
• Business Owner: Focuses on overarching financial investment and strategic goals rather than daily kitchen cooking oversight.', '["Diet Clerk","Foodservice Manager","Storekeeper","Business Owner"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:47:48.397Z"'::jsonb),
('card-1794233130997-1', NULL, 'deck-1794233130997-zs17b', 'In foodservice operations, food production is best described as:', 'The transformation of raw materials into appealing, safe, and cost-effective meals', 'Food production is fundamentally defined as the managerial and operational process of converting raw food ingredients into finished, safe, attractive, and economical meals for service.

• The purchasing and receiving of food products: Refers to procurement and receiving functions, not production.
• The distribution of meals from the kitchen to consumers: Describes food distribution and service, not the production phase.
• The storage and inventory management of food supplies: Relates to inventory control and dry/cold storage management.', '["The purchasing and receiving of food products","The transformation of raw materials into appealing, safe, and cost-effective meals","The distribution of meals from the kitchen to consumers","The storage and inventory management of food supplies"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:47:56.999Z"'::jsonb),
('card-1794233130997-10', NULL, 'deck-1794233130997-zs17b', 'Which production principle is MOST likely deficient?', 'Standardization, because consistency in quality and portion size depends on uniform production', 'Inconsistent flavor, appearance, and portion sizes point directly to a lack of recipe and procedural standardization.

• Forecasting: Inaccurate forecasting leads to leftovers or shortages, not inconsistent quality per recipe.
• Batch cooking: Smaller batches actually enhance quality control if recipes are standardized.
• Workflow efficiency: Focuses on physical movement and timing rather than recipe execution consistency.', '["Forecasting, because customer satisfaction ultimately depends on accurate demand prediction","Batch cooking, because food prepared in smaller quantities is less likely to vary in quality","Standardization, because consistency in quality and portion size depends on uniform production","Workflow efficiency, because reduced employee movement improves product uniformity"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:52.523Z"'::jsonb),
('card-1794233130997-11', NULL, 'deck-1794233130997-zs17b', 'A hospital foodservice department purchases a new steam-jacketed kettle and convection oven to improve production efficiency. Six months later, productivity has not significantly improved. Which factor was MOST likely overlooked?', 'Equipment selection must be aligned with menu requirements, batch size, and service flow. ', 'Purchasing expensive kitchen equipment fails to improve productivity if the machinery''s capacity, design, and output do not match the specific menu needs and operational workflow of the facility.

• Additional forecasting data should have been collected: Equipment utility depends on matching operational flow, not raw forecasting depth.
• Additional temperature monitoring procedures should have been implemented: Temperature monitoring ensures safety but does not solve equipment-productivity mismatch.
• More frequent sensory evaluations should have been conducted: Sensory testing evaluates food quality rather than operational throughput.', '["Additional forecasting data should have been collected before purchasing the equipment.","Equipment selection must be aligned with menu requirements, batch size, and service flow. ","Additional temperature monitoring procedures should have been implemented.","More frequent sensory evaluations should have been conducted."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:59.572Z"'::jsonb),
('card-1794233130997-12', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager notices that chicken afritada prepared by different cooks varies significantly in flavor, appearance, and portion size. Which operational problem would most likely occur FIRST as a consequence?', 'Decreased customer satisfaction', 'When food quality, appearance, and portions vary unpredictably between cooks, customers experience inconsistent meals, leading directly to lowered satisfaction.

• Increased employee confidence: Inconsistent standards usually generate confusion and frustration among staff.
• Reduced food safety risks: Inconsistent preparation practices can actually increase safety vulnerabilities.
• Improved inventory control: Standardization assists inventory, whereas inconsistent practices disrupt cost accounting.', '["Increased employee confidence","Reduced food safety risks","Decreased customer satisfaction","Improved inventory control"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:12.416Z"'::jsonb),
('card-1794233130997-13', NULL, 'deck-1794233130997-zs17b', 'In recipe standardization, what phase involves testing acceptability and gathering feedback?', 'Product evaluation', 'Product evaluation is the phase in recipe standardization where trained panels or consumers test food acceptability, appearance, and taste.', '["Recipe verification","Product evaluation","Quantity adjustment","Option D"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:18.153Z"'::jsonb),
('card-1794233130997-14', NULL, 'deck-1794233130997-zs17b', 'What is the correct formula for the factor method in recipe adjustment?', 'Desired Yield ÷ Current Yield', 'The mathematical formula for the factor method used in recipe adjustment is Desired Yield divided by Current Yield to determine the conversion multiplier.', '["Desired Yield ÷ Current Yield","Desired Yield x Current Yield","Current Yield ÷ Desired Yield","Current Quantity + Yield Factor"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:22.930Z"'::jsonb),
('card-1794233130997-15', NULL, 'deck-1794233130997-zs17b', 'Which statement BEST differentiates Recipe Verification from Product Evaluation?', 'Recipe Verification confirms recipe accuracy, while Product Evaluation assesses acceptability of', 'Recipe verification checks the mathematical and procedural accuracy of a recipe in the kitchen, whereas product evaluation assesses whether the food meets sensory acceptability standards.', '["Recipe Verification focuses on sensory qualities, while Product Evaluation focuses on yield.","Recipe Verification determines consumer acceptance, while Product Evaluation determines cost.","Recipe Verification confirms recipe accuracy, while Product Evaluation assesses acceptability of","Recipe Verification is performed after quantity adjustment."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:30.305Z"'::jsonb),
('card-1794233130997-16', NULL, 'deck-1794233130997-zs17b', 'What percentage of the total recipe weight is contributed by potatoes?', '30%', 'Based on total recipe component weight calculations, potatoes contribute 30% to the aggregate composition.', '["20%","25%","30%","33%"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:34.546Z"'::jsonb),
('card-1794233130997-17', NULL, 'deck-1794233130997-zs17b', 'A standardized soup recipe yields 40 portions. Demand forecasting indicates that 60 portions will be required tomorrow. What is the recipe adjustment factor?', '1.50', 'Using the factor method formula (Desired Yield ÷ Current Yield): 60 portions ÷ 40 portions = 1.50 conversion factor.', '["1.50","0.67","1.25","2.00"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:40.131Z"'::jsonb),
('card-1794233130997-18', NULL, 'deck-1794233130997-zs17b', 'Which standardized recipe component would BEST assist a newly hired cook in determining whether a prepared product meets the expected appearance, flavor, and texture standards?', 'Quality Standards', 'Quality standards embedded within a standardized recipe provide clear benchmarks for appearance, flavor, and texture, guiding staff in evaluating finished products.

• Recipe Yield: Specifies the total number or volume of portions produced, not sensory criteria.
• Portion Size: Dictates serving dimensions, not aesthetic or flavor profiles.
• Recipe Category: Groups recipes by menu type (e.g., soups, entrees).', '["Recipe Yield","Portion Size","Quality Standards","Recipe Category"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:45.779Z"'::jsonb),
('card-1794233130997-19', NULL, 'deck-1794233130997-zs17b', 'In volume cooking, what tool best helps maintain portion control and cost-efficiency?', 'Scoop or ladle chart', 'A standardized scoop or ladle chart matches specific utensil sizes to portion volumes, ensuring strict portion control and food cost consistency in volume cooking.

• Thermometer: Used to measure internal food temperatures for safety, not volume portions.
• HACCP plan: Focuses on hazard control and food safety points.
• Cycle Menu: Outlines menu offerings across a repeating schedule.', '["Thermometer","Scoop or ladle chart","HACCP plan","Cycle Menu"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:51.369Z"'::jsonb),
('card-1794233130997-2', NULL, 'deck-1794233130997-zs17b', 'Which of the following is NOT identified as an important component of food production in foodservice operations?', 'Foodservice Market Segmentation', 'Foodservice market segmentation is a marketing strategy used to divide a target market into distinct consumer groups, making it the correct exception since it is not an operational component of food production.

• Production Planning: An essential component focusing on scheduling, forecasting, and resource allocation.
• Foodservice Systems: Core structural components governing how food is processed and delivered.
• Quality Control: Vital component ensuring safety, sensory appeal, and consistency during production.', '["Production Planning","Foodservice Systems","Quality Control","Foodservice Market Segmentation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:06.489Z"'::jsonb),
('card-1794233130997-20', NULL, 'deck-1794233130997-zs17b', 'Which organizations jointly developed the Codex Alimentarius through the Codex Alimentarius Commission?', 'FAO and WHO', 'The Codex Alimentarius Commission was jointly established by the Food and Agriculture Organization (FAO) and the World Health Organization (WHO) to develop international food standards.', '["WHO and USDA","FDA and WHO","FAO and FDA","FAO and WHO"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:49:56.002Z"'::jsonb),
('card-1794233130997-21', NULL, 'deck-1794233130997-zs17b', 'Which statement BEST describes the relationship between Good Hygiene Practices (GHP) and HACCP?', 'GHP serves as the foundation upon which HACCP is implemented.', 'Good Hygiene Practices (GHP) and Good Manufacturing Practices (GMP) establish baseline sanitary and operational conditions required before a Hazard Analysis Critical Control Point (HACCP) system can be successfully built.', '["HACCP replaces GHP in foodservice operations.","GHP serves as the foundation upon which HACCP is implemented.","GHP is used only after HACCP verification.","GHP focuses on corrective actions while HACCP focuses on sanitation."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:04.544Z"'::jsonb),
('card-1794233130997-22', NULL, 'deck-1794233130997-zs17b', 'A quality assurance officer identifies the possibility of metal fragments entering a product during slicing operations. Under HACCP, this hazard is classified as:', 'Physical', 'Metal fragments, glass shards, or stones introduced during processing are classified under HACCP as physical hazards.

• Biological: Involves pathogenic bacteria, viruses, or parasites.
• Chemical: Involves sanitizers, heavy metals, or toxic residues.
• Radiological: Relates to radioactive contamination, rare in standard foodservice settings.', '["Biological","Chemical","Physical","Radiological"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:12.598Z"'::jsonb),
('card-1794233130997-23', NULL, 'deck-1794233130997-zs17b', 'During HACCP plan development, the foodservice team identifies cooking as a step where pathogens can be eliminated through proper heat treatment. This step is considered a:', 'Critical Control Point', 'A Critical Control Point (CCP) is a specific operational step where control can be applied to prevent, eliminate, or reduce a food safety hazard to an acceptable level, such as thermal cooking.

• Critical Limit: The measurable boundary (e.g., specific temperature) that must be met at a CCP.
• Monitoring Procedure: The planned sequence of observations or measurements.
• Corrective Action: Procedures followed when a critical limit is breached.', '["Critical Limit","Monitoring Procedure","Corrective Action","Critical Control Point"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:17.738Z"'::jsonb),
('card-1794233130997-24', NULL, 'deck-1794233130997-zs17b', 'A dietitian establishes that chicken must reach an internal temperature of 74Â°C before service. This temperature requirement represents:', 'Critical Limit', 'A critical limit is the prescribed maximum or minimum value (such as heating chicken to an internal temperature of 74°C) that must be controlled at a CCP.', '["Hazard Analysis","Monitoring Procedure","Critical Limit","Critical Control Point"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:22.796Z"'::jsonb),
('card-1794233130997-25', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager requires kitchen staff to record cooking temperatures every hour using calibrated thermometers. Which HACCP principle is being applied?', 'Establish Monitoring Procedures', 'Requiring staff to measure and log cooking temperatures hourly using calibrated thermometers exemplifies establishing monitoring procedures (HACCP Principle 4).', '["Conduct Hazard Analysis","Establish Monitoring Procedures","Establish Verification Procedures","Establish Corrective Actions"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:27.037Z"'::jsonb),
('card-1794233130997-26', NULL, 'deck-1794233130997-zs17b', 'During a routine audit, a tray of cooked ground beef is found to have reached only 60Â°C instead of the required critical limit. The supervisor immediately removes the product from service and recooks it. Which HACCP principle is MOST directly demonstrated?', 'Corrective Action', 'Immediately halting service, removing undercooked beef, and taking steps to re-heat or discard it demonstrates enacting established corrective actions (HACCP Principle 5).', '["Corrective Action","Verification","Hazard Analysis","Documentation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:32.399Z"'::jsonb),
('card-1794233130997-27', NULL, 'deck-1794233130997-zs17b', 'Which of the following documents would provide the STRONGEST evidence that a CCP was consistently maintained during food production?', 'Temperature monitoring records', 'Signed and dated temperature logs provide verifiable, documented audit evidence confirming that critical control points like cooking and holding temperatures were maintained.

• Cycle Menu: Outlines planned meals, bearing no direct data on production safety execution.
• Production schedule: Details prep timing and tasks, not safety parameter measurements.
• Employee duty roster: Shows staff shift assignments, not biological or thermal hazard controls.', '["Temperature monitoring records","Cycle Menu","Production schedule","Employee duty roster"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:37.476Z"'::jsonb),
('card-1794233130997-28', NULL, 'deck-1794233130997-zs17b', 'A foodservice facility wishes to implement the MOST effective long-term pest management strategy. Which action should receive the highest priority?', 'Prevention through sanitation and elimination of food and moisture sources', 'Long-term pest management relies fundamentally on environmental controls—eliminating food debris, standing water, and harborage areas so pests cannot survive or breed.

• Monthly application of pesticides: Treats symptoms of infestation rather than fixing root causes.
• Placement of additional insect traps: Passive mitigation measure that does not stop pest attraction.
• Increasing the frequency of fumigation: Relies on hazardous chemical usage without removing underlying attraction sources.', '["Monthly application of pesticides","Placement of additional insect traps","Prevention through sanitation and elimination of food and moisture sources","Increasing the frequency of fumigation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:44.217Z"'::jsonb),
('card-1794233130997-29', NULL, 'deck-1794233130997-zs17b', 'According to the Integrated Solid Waste Management System hierarchy, which action represents the HIGHEST priority?', 'Source reduction through eliminating single-use materials', 'Under Integrated Solid Waste Management hierarchies, source reduction (preventing waste generation at the onset) holds the absolute highest priority over recycling or disposal.

• Recycling aluminum cans: A lower priority tier compared to avoiding waste generation.
• Sending waste to sanitary landfill: Represents the least desirable disposal option at the bottom of the hierarchy.
• Recovering energy from waste: Secondary waste-to-energy recovery step, below source reduction.', '["Recycling aluminum cans","Sending waste to sanitary landfill","Source reduction through eliminating single-use materials","Recovering energy from waste"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:50.313Z"'::jsonb)
