INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-1794233130997-3', NULL, 'deck-1794233130997-zs17b', 'Which objective of cooking is directly related to reducing the risk of foodborne illness?', 'Destroy harmful organisms', 'The primary food safety objective of cooking is applying thermal energy sufficient to destroy pathogenic microorganisms and reduce foodborne illness risks.

• Minimize quality losses: A culinary objective aimed at preserving texture and nutrients, but secondary to safety.
• Improve digestibility: Alters food structure for easier breakdown, though not the primary safety goal.
• Enhance flavor: Focuses on sensory appeal and palatability.', '["Minimize quality losses","Improve digestibility","Destroy harmful organisms","Enhance flavor"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:11.980Z"'::jsonb),
('card-1794233130997-30', NULL, 'deck-1794233130997-zs17b', 'A hospital prepares all meals in a central kitchen and transports them to patient units for service. Which foodservice distribution system is being used?', 'Centralized Foodservice System', 'A centralized foodservice system prepares food in a main kitchen and immediately transports it for service to nearby or adjacent patient units and dining rooms.', '["Centralized Foodservice System","Ready-Prepared System","Commissary System","Assembly-Serve System"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:50:54.622Z"'::jsonb),
('card-1794233130997-31', NULL, 'deck-1794233130997-zs17b', 'Which advantage is MOST associated with a centralized foodservice system?', 'Better control over food quality and production', 'Centralizing production allows management to maintain tight, direct supervision over recipe standardization, labor efficiency, and overall food quality.

• Better temperature retention upon service: Transporting meals often complicates temperature maintenance compared to decentralized staging.
• Better speed of service: Centralized transport can introduce bottlenecks during peak trayline delivery.
• Better for large facilities especially those with multiple locations: Suited for single large facilities or commissary networks, but decentralized models often handle expansive physical campuses differently.', '["Better control over food quality and production","Better temperature retention upon service","Better speed of service","Better for large facilities especially those with multiple locations"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:51:00.335Z"'::jsonb),
('card-1794233130997-32', NULL, 'deck-1794233130997-zs17b', 'A healthcare facility cooks food, rapidly chills it, stores it under controlled conditions, and reheats it before service. Which foodservice system is described?', 'Ready-Prepared System', 'The ready-prepared (cook-chill or cook-freeze) system cooks food in advance, rapidly chills or freezes it for inventory storage, and reheats it prior to individual service.', '["Conventional System","Commissary System","Decentralized System","Ready-Prepared System"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:51:06.231Z"'::jsonb),
('card-1794233130997-33', NULL, 'deck-1794233130997-zs17b', 'Which factor should receive the HIGHEST priority when transporting hot food from a production kitchen to satellite serving areas?', 'Temperature maintenance', 'When transporting food across facilities, maintaining strict temperature control is paramount to prevent bacterial proliferation within the Danger Zone and ensure food safety.

• Portion size: Controlled during production and plating, less impacted directly by transit mechanics.
• Employee scheduling: Handled at base kitchen and satellite destinations independently.
• Menu variety: Planned beforehand; transit focuses on safe physical delivery.', '["Portion size","Temperature maintenance","Employee scheduling","Menu variety"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:51:13.877Z"'::jsonb),
('card-1794233130997-34', NULL, 'deck-1794233130997-zs17b', 'A school foodservice manager notices that fried foods become soggy before reaching students. Which distribution concern is MOST likely contributing to the problem?', 'Excessive holding time', 'Fried foods lose crispness and become soggy when held too long in closed warming containers due to moisture migration and steam condensation.

• Improper forecasting: Leads to surplus food, but sogginess specifically stems from holding duration.
• Inaccurate inventory records: Affects purchasing and stock levels rather than fried texture.
• Inadequate purchasing procedures: Affects ingredient quality and supply chains, not holding-induced sogginess.', '["Improper forecasting","Excessive holding time","Inaccurate inventory records","Inadequate purchasing procedures"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:51:23.310Z"'::jsonb),
('card-1794233130997-35', NULL, 'deck-1794233130997-zs17b', 'Which of the following BEST explains why preventive maintenance programs are important in foodservice operations?', 'They reduce equipment downtime and costly repairs.', 'Preventive maintenance schedules catch minor mechanical wear early, reducing unexpected equipment breakdowns and expensive emergency service repairs.', '["They eliminate the need for sanitation procedures.","They reduce equipment downtime and costly repairs.","They decrease menu planning requirements.","They replace employee training programs."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:51:52.156Z"'::jsonb),
('card-1794233130997-36', NULL, 'deck-1794233130997-zs17b', 'Which process is defined as the reduction of microorganisms on a cleaned surface to safe levels as determined by public health standards?', 'Sanitizing', 'Sanitizing is the thermal or chemical treatment process that reduces microbial counts on cleaned surfaces to safe public health thresholds.', '["Sterilization","Cleaning","Sanitizing","Maintenance"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:51:57.100Z"'::jsonb),
('card-1794233130997-37', NULL, 'deck-1794233130997-zs17b', 'Cleaning removes visible dirt, food particles, and grease, while sanitizing reduces microorganisms to safe levels. Both are necessary for effective foodservice sanitation. Which among the following are NOT necessary conditions for pest survival:', 'Equipment', 'Equipment is necessary for kitchen operations, but pests require food, moisture, and harborage (shelter) to survive; equipment itself is not a biological survival requirement for pests.', '["Food","Harborage","Equipment","Moisture"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:01.493Z"'::jsonb),
('card-1794233130997-38', NULL, 'deck-1794233130997-zs17b', 'Which action BEST demonstrates an effective facility sanitation program?', 'Conducting sanitation activities according to a scheduled program', 'An effective sanitation program relies on structured master cleaning schedules and routine compliance protocols rather than ad-hoc or reactive cleaning.

• Cleaning equipment only when visibly dirty: Promotes microbial growth and fails proactive sanitation standards.
• Sanitizing food-contact surfaces monthly: Far too infrequent; food-contact surfaces require sanitizing after every use.
• Relying exclusively on third-party inspections: External audits complement, but do not replace, daily internal sanitation management.', '["Cleaning equipment only when visibly dirty","Sanitizing food-contact surfaces monthly","Conducting sanitation activities according to a scheduled program","Relying exclusively on third-party inspections"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:06.760Z"'::jsonb),
('card-1794233130997-39', NULL, 'deck-1794233130997-zs17b', 'Which document serves as the primary model for foodservice sanitation standards?', 'FDA Food Code', 'The FDA Food Code serves as the primary scientific model and regulatory reference document for retail and foodservice sanitation and safety standards in the United States and global adaptations.', '["FDA Food Code","Codex Alimentarius","Hazard Analysis Worksheet","Equipment Maintenance Log"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:11.451Z"'::jsonb),
('card-1794233130997-4', NULL, 'deck-1794233130997-zs17b', 'What principle of quantity food production is being applied?', 'Standardization', 'Standardization ensures that recipes, procedures, and portions remain uniform, yielding predictable quality and cost efficiency in quantity food production.', '["Standardization","Uniformity","Batch Cooking","Assembly and Holding"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:17.928Z"'::jsonb),
('card-1794233130997-40', NULL, 'deck-1794233130997-zs17b', 'Which management function involves determining organizational goals and identifying the most appropriate course of action to achieve them?', 'Planning', 'Planning is the foundational management function of determining organizational objectives and mapping out the best strategies and resource pathways to achieve them.', '["Organizing","Leading","Planning","Controlling"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:18.327Z"'::jsonb),
('card-1794233130997-41', NULL, 'deck-1794233130997-zs17b', 'A newly appointed foodservice manager introduces standardized work procedures, clearly defines authority among supervisors, and assigns employees to highly specialized tasks to improve operational efficiency. Which management theory is MOST consistent with this approach?', 'Classical Theory', 'Classical management theory (associated with scientific management and administrative principles) emphasizes standardized work procedures, hierarchical authority structures, and job specialization to maximize efficiency.', '["Human Relations Theory","Systems Theory","Chaos Theory","Classical Theory"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:21.986Z"'::jsonb),
('card-1794233130997-42', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager develops a weekly production schedule, assigns cooks to specific workstations, and designates a supervisor for each production area to ensure efficient workflow during peak hours. Which management function is BEST illustrated?', 'Organizing', 'Organizing involves structuring work, assigning personnel to specific workstations, establishing reporting relationships, and coordinating workflow for optimal operational flow.', '["Planning","Organizing","Leading","Controlling"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:27.026Z"'::jsonb),
('card-1794233130997-43', NULL, 'deck-1794233130997-zs17b', 'Which management tool identifies the knowledge, skills, abilities, and other qualifications that an individual must possess to perform a specific job effectively?', 'Job Specification', 'A job specification outlines the minimum personal qualifications, knowledge, skills, education, and experience an individual must possess to execute a job successfully.

• Job Analysis: The systematic process of gathering data about a job''s duties and working conditions.
• Job Description: A formal written list of duties, responsibilities, and reporting lines for a position.
• Job Breakdown: Step-by-step instructions on how to execute specific tasks within a job.', '["Job Analysis","Job Description","Job Specification","Job Breakdown"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:33.812Z"'::jsonb),
('card-1794233130997-44', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager has already received several applications for a vacant dietitian position. The manager now reviews application forms, conducts interviews, and administers psychological and health examinations before choosing the successful applicant. Which phase of the employment process is being performed?', 'Selection', 'The selection process involves reviewing applications, conducting interviews, and administering evaluations to choose the most qualified candidate for employment.

• Recruitment: The preceding phase of generating a pool of applicants.
• Orientation: The onboarding process welcoming and introducing new hires to the organization.
• Performance Appraisal: Periodic evaluation of employee job performance post-hire.', '["Recruitment","Orientation","Selection","Performance Appraisal"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:40.571Z"'::jsonb),
('card-1794233130997-45', NULL, 'deck-1794233130997-zs17b', 'Which of the following is the PRIMARY purpose of a job analysis?', 'To determine the duties, responsibilities, working conditions, relationships, and qualifications', 'A job analysis is a systematic investigative tool used to dissect every facet of a role, including tasks, responsibilities, working environments, and required qualifications.', '["To identify the salary and benefits assigned to a position","To determine the duties, responsibilities, working conditions, relationships, and qualifications","To establish an employee''s work schedule and assigned shifts","To evaluate employee performance after hiring"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:45.315Z"'::jsonb),
('card-1794233130997-46', NULL, 'deck-1794233130997-zs17b', 'Which leadership theory views employees primarily as individuals motivated by money, rewards, and efficiency?', 'Scientific Management', 'Scientific management (Taylorism) views workers largely through an economic lens, assuming they are primarily motivated by financial incentives, structured task pacing, and operational efficiency.', '["Scientific Management","Human Relations Theory","Servant Leadership","Contingency Theory"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:49.864Z"'::jsonb),
('card-1794233130997-47', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager notices that an experienced employee has become less motivated despite receiving regular salary increases. To improve motivation, the manager assigns the employee to lead a new quality improvement project and recognizes her contributions during departmental meetings. Which motivational theory BEST explains this management approach?', 'Herzberg''s Two-Factor Theory', 'Herzberg''s Two-Factor (Motivation-Hygiene) theory explains that base salary increases act as hygiene factors that prevent dissatisfaction, whereas fulfilling higher-level needs through increased responsibility, achievement, and recognition (like leading a project) serves as a true motivator.', '["Scientific Management","Herzberg''s Two-Factor Theory","Theory X","Theory Y"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:54.199Z"'::jsonb),
('card-1794233130997-48', NULL, 'deck-1794233130997-zs17b', 'Which theory of motivation proposes that employee motivation is determined by the belief that effort will lead to good performance, good performance will result in rewards, and the rewards are valued by the employee?', 'Expectancy Theory', 'Expectancy theory proposes that employee motivation depends on three cognitive linkages: expectancy (effort leads to performance), instrumentality (performance leads to rewards), and valence (the value the employee places on the reward).', '["Equity Theory","Herzberg''s Motivation-Hygiene Theory","Expectancy Theory","ERG Theory"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:52:58.848Z"'::jsonb),
('card-1794233130997-49', NULL, 'deck-1794233130997-zs17b', 'Which financial record provides information on the value of a business and how effectively its assets have been used to meet the organization’s financial goals?', 'Balance Sheet', 'A balance sheet is a fundamental financial statement summarizing an organization''s assets, liabilities, and equity at a specific point in time, reflecting its financial position and capital utilization.

• Annual Report: A comprehensive yearly corporate publication detailing overall activities and financial health.
• Budget Plan: A financial forecast and operational spending plan for future periods.
• Profit and Loss Statement: Reports revenues, expenses, and net income over a specific operational timeframe.', '["Annual Report","Budget Plan","Profit and Loss Statement","Balance Sheet"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:53:04.506Z"'::jsonb),
('card-1794233130997-5', NULL, 'deck-1794233130997-zs17b', 'The primary purpose of forecasting in quantity food production is to:', 'Prevent under or over production', 'Demand forecasting utilizes historical data and current census to estimate food quantities accurately, preventing both costly overproduction waste and underproduction shortfalls.

• Improve production convenience: Operational convenience is secondary to accurate demand planning.
• Improve cooking strategies: Cooking methods follow recipes rather than being driven directly by forecasting goals.
• Determine employee work schedules: While staffing depends on volume, schedules are a derived outcome rather than the primary forecasting purpose.', '["Improve production convenience","Improve cooking strategies","Prevent under or over production","Determine employee work schedules"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:23.809Z"'::jsonb),
('card-1794233130997-50', NULL, 'deck-1794233130997-zs17b', 'Which accounting element represents the residual interest of the owners in the assets of a business after deducting all liabilities?', 'Owner''s Equity', 'Owner''s Equity represents the residual interest or claim of the owners in the assets of a business after all liabilities have been deducted (Assets - Liabilities = Owner''s Equity).

• Revenue: Represents the total amount of income generated by the sale of goods or services related to the primary operations of a business.
• Expense: Represents the costs incurred by a business in the process of earning revenue.
• Profit: Represents the financial gain calculated as the difference between total revenues and total expenses over a specific period.', '["Revenue","Expense","Owner''s Equity","Profit"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:56:26.806Z"'::jsonb),
('card-1794233130997-51', NULL, 'deck-1794233130997-zs17b', 'A nutrition manager is preparing a financial plan to estimate next year’s revenues, allocate resources, anticipate operating expenses, and guide future organizational activities. Which financial document should the manager prepare?', 'Budget', 'A budget is a financial plan designed to estimate upcoming revenues, allocate resources, anticipate operating expenses, and guide the financial activities of an organization over a future period.

• Income Statement: Reports past financial performance (revenues and expenses) over a completed fiscal period.
• Balance Sheet: Summarizes the assets, liabilities, and owner''s equity at a specific point in time.
• Annual Report: A comprehensive yearly report detailing corporate activities, achievements, and financial health.', '["Income Statement","Budget","Balance Sheet","Annual Report"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:56:34.399Z"'::jsonb),
('card-1794233130997-52', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager wants to determine whether the department earned a profit or incurred a loss during the previous fiscal year. Which financial record should the manager review?', 'Profit and Loss Statement', 'The Profit and Loss Statement (also known as the income statement) summarizes revenues and expenses over a fiscal year to determine whether the business earned a net profit or incurred a net loss.

• Balance Sheet: Displays static financial position (assets, liabilities, equity) rather than operational profit or loss.
• Budget Plan: A financial forecast for future operations, not an evaluation of past results.
• Annual Report: A broad corporate summary rather than a standalone operational accounting ledger for profit tracking.', '["Balance Sheet","Budget Plan","Profit and Loss Statement","Annual Report"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:56:39.251Z"'::jsonb),
('card-1794233130997-53', NULL, 'deck-1794233130997-zs17b', 'Which of the following BEST describes employee training?', 'The systematic process of improving employees'' knowledge, skills, attitudes, and performance', 'Employee training is defined as the systematic educational process designed to enhance workers'' knowledge, operational skills, work attitudes, and overall job performance.

• The process of evaluating an employee''s job performance for promotion purposes: Refers to performance appraisal or evaluation, not training.
• The assignment of employees to positions based on their qualifications: Describes placement or staffing.
• The process of determining salary increases based on work performance: Refers to compensation administration and merit evaluation.', '["The process of evaluating an employee''s job performance for promotion purposes.","The systematic process of improving employees'' knowledge, skills, attitudes, and performance","The assignment of employees to positions based on their qualifications.","The process of determining salary increases based on work performance."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:56:45.725Z"'::jsonb),
('card-1794233130997-54', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager plans to implement a training program for newly hired kitchen staff. Before preparing the training materials and schedule, the manager first determines whether training is necessary and identifies the knowledge and skills employees need to acquire. Which step in developing a training program is being demonstrated?', 'Determine training needs and identify what should be taught.', 'Assessing whether training is required and identifying specific knowledge or skills gaps is the initial diagnostic phase of developing a training program, known as a training needs assessment.

• Establish training goals: Follows the needs assessment once specific skill deficiencies have been identified.
• Develop the training outline and implementation plan: Occurs later in the design phase after learning objectives are set.
• Evaluate employee performance: Refers to post-training or routine performance appraisals.', '["Establish training goals.","Develop the training outline and implementation plan.","Determine training needs and identify what should be taught.","Evaluate employee performance."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:56:52.692Z"'::jsonb),
('card-1794233130997-55', NULL, 'deck-1794233130997-zs17b', 'A supervisor conducts a formal assessment of an employee’s performance to determine competency, identify additional training needs, and evaluate readiness for promotion. What is the PRIMARY purpose of this personnel management activity?', 'To conduct performance evaluation for employee development and management decisions. ', 'Conducting formal performance reviews allows management to assess worker competency, pinpoint areas needing professional development, and inform decisions regarding promotions or salary adjustments.

• To prepare the employee''s job description: Job descriptions are established during job analysis prior to performance reviews.
• To recruit additional employees for the department: Recruitment focuses on sourcing new applicants externally or internally.
• To establish salary grades for newly created positions: Handled via job evaluation and wage administration rather than employee performance reviews.', '["To conduct performance evaluation for employee development and management decisions. ","To prepare the employee''s job description.","To recruit additional employees for the department.","To establish salary grades for newly created positions."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:56:59.051Z"'::jsonb),
('card-1794233130997-56', NULL, 'deck-1794233130997-zs17b', 'Which statement regarding the 13th Month Pay Law is CORRECT?', 'It must be paid on or before December 24 of each year.', 'Under Philippine labor law (Presidential Decree No. 851), the mandatory 13th-month pay must be distributed to qualified rank-and-file employees on or before December 24 of each year.', '["It must be paid on or before December 24 of each year.","It is granted only to managerial employees.","It replaces overtime pay during the Christmas season","It is provided only when the company earns a profit."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:05.878Z"'::jsonb),
('card-1794233130997-57', NULL, 'deck-1794233130997-zs17b', 'A foodservice establishment conducts regular safety training, provides employees with appropriate personal protective equipment (PPE), and implements measures to prevent workplace hazards. Which law is the establishment primarily complying with?', 'Republic Act No. 11058 (Occupational Safety and Health Standards)', 'Republic Act No. 11058 is the landmark Philippine law strengthening compliance with occupational safety and health standards, mandating hazard prevention, safety training, and the provision of appropriate PPE.

• Presidential Decree No. 851: Governs the mandatory 13th-month pay benefit.
• Philippine Labor Code: The broad overarching legal framework for labor relations and employment conditions (Presidential Decree No. 442).
• National Internal Revenue Code: Governs taxation laws in the Philippines.', '["Presidential Decree No. 851","Republic Act No. 11058 (Occupational Safety and Health Standards)","Philippine Labor Code","National Internal Revenue Code"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:12.761Z"'::jsonb),
('card-1794233130997-58', NULL, 'deck-1794233130997-zs17b', 'Which Philippine law grants qualified female employees 105 days of paid maternity leave, with additional leave benefits for solo parents?', 'Republic Act No. 11210', 'Republic Act No. 11210 (the 105-Day Expanded Maternity Leave Law) grants eligible female workers in the public and private sectors 105 days of paid maternity leave, with an additional 15 days for solo mothers.

• Republic Act No. 8187: The Paternity Leave Act of 1996.
• Republic Act No. 11058: The Occupational Safety and Health Standards Act.
• Presidential Decree No. 851: The 13th-Month Pay Law.', '["Republic Act No. 8187","Republic Act No. 11058","Republic Act No. 11210","Presidential Decree No. 851"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:18.360Z"'::jsonb),
('card-1794233130997-59', NULL, 'deck-1794233130997-zs17b', 'Which professional law directs the Professional Regulatory Board of Nutrition and Dietetics to adopt and enforce the Code of Ethics for Registered Nutritionist-Dietitians (RNDs)?', 'Republic Act No. 10862', 'Republic Act No. 10862 (the Nutrition and Dietetics Law of 2016) mandates the Professional Regulatory Board of Nutrition and Dietetics to adopt, promulgate, and enforce the official Code of Ethics for Registered Nutritionist-Dietitians.

• Presidential Decree No. 442: The Labor Code of the Philippines.
• Republic Act No. 11058: Occupational Safety and Health Standards Act.
• Republic Act No. 11210: Expanded Maternity Leave Law.', '["Presidential Decree No. 442","Republic Act No. 10862","Republic Act No. 11058","Republic Act No. 11210"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:25.162Z"'::jsonb),
('card-1794233130997-6', NULL, 'deck-1794233130997-zs17b', 'A university cafeteria observed that despite accurately forecasting customer volume, food waste remained high at the end of service. Upon investigation, management found that most menu items were prepared in their entirety before the start of lunch service. Which intervention would MOST directly address the problem while maintaining product quality?', 'Implement batch cooking throughout the service period', 'Batch cooking—preparing food in smaller, continuous quantities throughout service—directly addresses high waste by ensuring freshness and reducing surplus food left sitting on the line.

• Increase the accuracy of demand forecasting: Even with accurate forecasting, preparing all food at once causes waste if demand shifts or product cools.
• Reduce recipe yields for all menu items: Arbitrarily cutting yields risks running out of food during peak volume.
• Increase holding temperatures to extend product shelf life: Improper holding compromises food quality, safety, and texture rather than reducing waste.', '["Increase the accuracy of demand forecasting","Reduce recipe yields for all menu items","Implement batch cooking throughout the service period","Increase holding temperatures to extend product shelf life"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:29.727Z"'::jsonb),
('card-1794233130997-60', NULL, 'deck-1794233130997-zs17b', 'A Registered Nutritionist-Dietitian is asked by a patient’s employer to disclose the patient’s nutrition assessment and medical nutrition therapy records without the patient’s permission. According to the Code of Ethics, what is the MOST appropriate action?', 'Maintain confidentiality and disclose the information only if authorized by the patient or', 'The RND Code of Ethics strictly upholds patient confidentiality and professional privacy; medical and nutrition records can only be disclosed when authorized directly by the patient or mandated by valid legal court orders.

• Release the information because the employer requested it: Violates patient confidentiality laws and ethical standards.
• Share only the nutrition assessment but withhold the medical records: Breaches patient privacy just as severely as releasing medical records.
• Refuse to document the patient''s nutrition assessment to avoid disclosure: Improper clinical practice; accurate documentation is mandatory, but unauthorized disclosure is prohibited.', '["Release the information because the employer requested it.","Share only the nutrition assessment but withhold the medical records.","Maintain confidentiality and disclose the information only if authorized by the patient or","Refuse to document the patient''s nutrition assessment to avoid disclosure."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:31.637Z"'::jsonb),
('card-1794233130997-61', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager reviews customer satisfaction surveys and compares actual sales with projected sales after implementing a new promotional campaign. Based on the findings, the manager modifies future marketing strategies. Which stage of the Marketing Management Cycle is BEST illustrated?', 'Marketing Evaluation', 'Comparing actual sales and customer feedback against original marketing projections to review effectiveness and guide future adjustments represents the evaluation phase of the marketing cycle.

• Marketing Planning: Involves setting objectives and designing promotional strategies before launch.
• Marketing Execution: The active implementation of the marketing plan and campaigns.
• Product Development: Focuses on creating or modifying food items or service offerings.', '["Marketing Planning","Marketing Execution","Product Development","Marketing Evaluation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:38.877Z"'::jsonb),
('card-1794233130997-62', NULL, 'deck-1794233130997-zs17b', 'After launching a new menu, a restaurant notices that customer awareness remains low despite offering competitive prices and high-quality products. Which element of the marketing mix should the manager prioritize to address this problem?', 'Promotion', 'When products are high-quality and prices are competitive, but consumer awareness remains low, the "Promotion" element of the marketing mix (advertising, public relations, communication) requires immediate prioritization.

• Product: Refers to the physical food item or service characteristics, which are already satisfactory in this scenario.
• Place: Refers to distribution channels and location accessibility.
• Price: Refers to pricing strategy, which is already noted as competitive.', '["Product","Place","Price","Promotion"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:46.708Z"'::jsonb),
('card-1794233130997-63', NULL, 'deck-1794233130997-zs17b', 'A foodservice company completes the implementation of its annual marketing plan. Management then compares actual sales, customer satisfaction, and market share with the original marketing objectives. The findings are subsequently used to revise next year’s marketing strategies. Which sequence of the Marketing Management Cycle is illustrated?', 'Marketing Execution -> Marketing Evaluation -> Feedback to Management', 'The correct operational flow of the marketing cycle starts with executing the plan, evaluating outcomes against goals, and feeding those analytical insights back into management to refine future strategies.', '["Marketing Planning -> Marketing Execution -> Feedback to Management","Marketing Execution -> Marketing Evaluation -> Feedback to Management","Marketing Planning -> Marketing Evaluation -> Marketing Execution","Marketing Execution -> Feedback to Management -> Marketing Evaluation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:53.948Z"'::jsonb),
('card-1794233130997-64', NULL, 'deck-1794233130997-zs17b', 'A hospital foodservice department purchases vegetables based solely on the lowest quoted price. After several deliveries, management notices excessive trimming losses because the produce contains a high proportion of inedible portions. Which purchasing objective was MOST neglected?', 'Obtain the lowest edible portion (EP) cost', 'Purchasing produce solely based on the lowest quoted as-purchased (AP) price without accounting for inedible waste leads to excessive trimming losses, failing to achieve the true lowest edible portion (EP) cost.

• Ensure adequate supply: Focuses on inventory stock levels rather than trimming waste.
• Maintain quality standards: Relates to freshness and grade specifications, though EP cost is the direct casualty here.
• Minimize investment: Pertains to cash flow management rather than waste-adjusted ingredient yield.

Question 66', '["Obtain the lowest edible portion (EP) cost","Ensure adequate supply","Maintain quality standards","Minimize investment"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:57:59.474Z"'::jsonb),
('card-1794233130997-65', NULL, 'deck-1794233130997-zs17b', 'A newly opened institutional foodservice operation serves more than 4,000 meals daily. Management requires suppliers to submit quotations based on detailed product specifications before awarding contracts. Which purchasing style is MOST appropriate?', 'Formal buying method', 'High-volume institutional foodservice operations serving thousands of meals utilize formal competitive bidding (formal buying method), requiring suppliers to submit sealed quotations based on precise written product specifications.

• Informal buying method: Used for small-volume purchases via open market quotes over the phone or in person.
• Standing order: An ongoing agreement for routine daily deliveries of staple items.
• Open market buying: Involves negotiating in the open market on a day-to-day basis, unsuited for rigid institutional scale.', '["Informal buying method","Standing order","Open market buying","Formal buying method"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:06.043Z"'::jsonb),
('card-1794233130997-66', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager notices that canned tomatoes are almost depleted before placing another order, resulting in occasional stockouts. Which component of the purchasing cycle should have prevented this situation?', 'Reorder point', 'The reorder point is the predetermined inventory stock level that signals when a new order must be placed to replenish supplies before existing stock runs out, preventing stockouts.

• Product specification: A detailed description of product quality requirements, not a stock trigger.
• Reorder quantity: The exact amount or size of the order placed, not the timing trigger.
• Economic order quantity (EOQ): A calculated ordering model balancing inventory holding and ordering costs.', '["Product specification","Reorder point","Reorder quantity","Economic order quantity"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:11.422Z"'::jsonb),
('card-1794233130997-67', NULL, 'deck-1794233130997-zs17b', 'Which sequence correctly represents the purchasing cycle used in foodservice operations?', 'Product specification -> Par stock/Reorder point -> Supplier selection -> Order placement -> Receiving', 'The logical purchasing cycle flows sequentially from defining product specifications, monitoring stock triggers (par stock/reorder point), selecting approved suppliers, placing orders, and receiving goods.', '["Product specification -> Supplier selection -> Order placement -> Receiving and storage -> Issuing -> Par","Product specification -> Par stock/Reorder point -> Supplier selection -> Order placement -> Receiving","Supplier selection -> Product specification -> Receiving -> Order placement -> Issuing -> Storage","Product specification -> Order placement -> Supplier selection -> Receiving -> Issuing -> Reorder point"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:16.368Z"'::jsonb),
('card-1794233130997-68', NULL, 'deck-1794233130997-zs17b', 'A manager wants to reduce purchasing costs by ordering ingredients in larger quantities and coordinating deliveries into fewer shipments without compromising operations. Which purchasing guideline is being applied?', 'Optimize delivery and transport', 'Ordering larger quantities and consolidating orders into fewer, coordinated deliveries reduces transport frequency and logistics overhead, optimizing delivery efficiency.

• Assess market conditions: Involves analyzing price trends and supply availability.
• Negotiate with the right suppliers: Focuses on vendor selection and contract terms.
• Maintain quality standards: Relates to enforcing product specifications during receiving.', '["Optimize delivery and transport","Assess market conditions","Negotiate with the right suppliers","Maintain quality standards"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:21.925Z"'::jsonb),
('card-1794233130997-69', NULL, 'deck-1794233130997-zs17b', 'During receiving, a shipment of poultry matches the quantity ordered, but the invoice price is higher than the agreed purchase order. Based on the objectives of receiving, what should the receiving personnel do FIRST?', 'Verify the price against the purchase order before accepting the shipment.', 'The primary objective of receiving control is verifying that delivered goods match purchase orders in terms of quantity, quality, and agreed pricing before signing the invoice.

• Accept the delivery because the quantity is correct: Fails to catch billing discrepancies and price overcharges.
• Store the poultry immediately to maintain food safety: Administrative pricing checks occur in the receiving staging area before transferring items to storage.
• Return the shipment without checking supporting documents: Premature action; pricing discrepancies must be verified against purchase orders first.', '["Verify the price against the purchase order before accepting the shipment.","Accept the delivery because the quantity is correct.","Store the poultry immediately to maintain food safety.","Return the shipment without checking supporting documents."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:27.299Z"'::jsonb),
('card-1794233130997-7', NULL, 'deck-1794233130997-zs17b', 'During a routine inspection, the manager notices that food temperatures are not being documented. Which principle of quantity food production is most likely directly compromised?', 'Time-temperature control', 'Failing to document food temperatures compromises critical time-temperature control parameters necessary to prevent pathogen growth and ensure safety.

• Workflow Efficiency: Relates to physical layout and movement, not temperature documentation.
• Pre-preparation techniques: Involves knife skills and ingredient staging prior to cooking.
• Forecasting: Deals with predicting customer volume rather than recording cooking parameters.', '["Workflow Efficiency","Time-temperature control","Pre-preparation techniques","Forecasting"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:34.661Z"'::jsonb),
('card-1794233130997-70', NULL, 'deck-1794233130997-zs17b', 'Which receiving area design feature MOST directly contributes to accurate verification of delivered food quantities?', 'Accurate weighing scales for incoming products', 'Having calibrated, accurate weighing scales in the receiving area is the most critical physical design feature needed to verify that delivered food weights match invoiced quantities.

• Receiving area located near the front entrance: Facilitates physical access, but does not ensure measurement accuracy.
• Adequate lighting throughout the receiving area: Important for visual inspection, but scales specifically govern quantity verification.
• Mobile shelving for temporary storage: Aids transport within storage logistics rather than receiving quantity checks.', '["Receiving area located near the front entrance","Adequate lighting throughout the receiving area","Accurate weighing scales for incoming products","Mobile shelving for temporary storage"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:34.454Z"'::jsonb),
('card-1794233130997-71', NULL, 'deck-1794233130997-zs17b', 'Which purchasing concept refers to the amount of an item that should be ordered each time the inventory level reaches the reorder point?', 'Reorder quantity', 'The reorder quantity is the specific, predetermined amount of an item ordered every time inventory levels drop down to the established reorder point.

• Par stock: The maximum baseline inventory level maintained at all times.
• Reorder point: The numerical stock trigger indicating when to order.
• Economic order quantity (EOQ): The mathematically calculated optimal order size minimizing total inventory costs.', '["Par stock","Reorder point","Reorder quantity","Economic order quantity (EOQ)"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:40.018Z"'::jsonb),
('card-1794233130997-72', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager notices that several canned goods have expired even though newer deliveries remain unopened. Which inventory control practice would have MOST likely prevented this problem?', 'First-In, First-Out (FIFO)', 'The First-In, First-Out (FIFO) inventory rotation system ensures older stock is used before newer deliveries, preventing items from expiring on shelves.

• Fixed location storage: Assigns specific shelf spaces to items for easy location, but does not enforce rotation order.
• Perpetual inventory: An administrative record-keeping system tracking stock balances, not physical rotation.
• Physical inventory: The periodic physical counting of stock on hand.', '["Fixed location storage","Perpetual inventory","Physical inventory","First-In, First-Out (FIFO)"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:45.878Z"'::jsonb),
('card-1794233130997-73', NULL, 'deck-1794233130997-zs17b', 'Which storage practice BEST minimizes both product spoilage and the risk of cross-contamination?', 'Separating food classes while maintaining appropriate storage temperatures', 'Isolating food categories (e.g., raw meats stored below ready-to-eat foods to prevent cross-contamination) combined with proper refrigeration temperatures is the gold standard for storage safety.

• Grouping all food items according to supplier: Suppliers do not dictate food safety storage segregation rules.
• Storing all products according to purchase date: Useful for rotation, but ignores cross-contamination risks between different food classes.
• Arranging products alphabetically regardless of storage requirements: Violates fundamental food safety and temperature control principles.', '["Grouping all food items according to supplier","Separating food classes while maintaining appropriate storage temperatures","Storing all products according to purchase date","Arranging products alphabetically regardless of storage requirements"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:52.264Z"'::jsonb),
('card-1794233130997-74', NULL, 'deck-1794233130997-zs17b', 'Which inventory record provides a continuous running balance by updating inventory immediately after every receipt and every issue?', 'Perpetual Inventory', 'A perpetual inventory system maintains a continuous, running balance of stock by updating records immediately following every single receipt and every issuance.

• Physical inventory: An intermittent physical count of stock items.
• Daily requisition log: Tracks daily item requests, but does not maintain a continuous running balance across all stock.
• Stock requisition form: An authorization document used to request items from storage.', '["Perpetual Inventory","Physical inventory","Daily requisition log","Stock requisition form"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:58:59.131Z"'::jsonb)
