INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-1794233130997-75', NULL, 'deck-1794233130997-zs17b', 'A storeroom clerk allows kitchen personnel to enter the storage room throughout the day and obtain ingredients without completing requisition forms. Which storage control practice is being violated?', 'Control in issuance', 'Allowing unrestricted access to storage without completing signed requisition forms violates the internal control principle of control in issuance, leading to unaccounted inventory shrinkage.

• Storage sanitation: Relates to cleanliness and pest prevention in the storage facility.
• Product specification: Refers to quality standards set during purchasing.
• Inventory valuation: Refers to the monetary accounting value of stock on hand.', '["Storage sanitation","Control in issuance","Product specification","Inventory valuation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:04.104Z"'::jsonb),
('card-1794233130997-76', NULL, 'deck-1794233130997-zs17b', 'Which storage security measure is MOST effective in reducing unauthorized removal of food supplies?', 'Maintaining lockable storage areas with access limited to authorized personnel', 'Physical security through lockable storage rooms and strict key-holder access control is the single most effective deterrent against unauthorized removal or pilferage of food supplies.

• Increasing the frequency of food deliveries: Affects supply chain logistics, not internal theft prevention.
• Hiding the storeroom area to a very inconvenient and inaccessible location: Impractical for daily culinary operations and workflow efficiency.
• Installing a photo of the owner of the establishment on the storage room: An ineffective administrative measure with no security value.', '["Increasing the frequency of food deliveries","Hiding the storeroom area to a very inconvenient and inaccessible location","Installing a photo of the owner of the establishment on the storage room","Maintaining lockable storage areas with access limited to authorized personnel"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:11.288Z"'::jsonb),
('card-1794233130997-77', NULL, 'deck-1794233130997-zs17b', 'Which of the following is considered the PRIMARY disadvantage of using a perpetual inventory system?', 'It is time-consuming and depends on accurate record keeping.', 'The primary operational drawback of a perpetual inventory system is that it requires meticulous, time-consuming data entry and unwavering staff compliance to record every single receipt and issue accurately.', '["It cannot be used for dry storage items.","It requires frequent replacement of storage equipment.","It is time-consuming and depends on accurate record keeping.","It cannot monitor inventory balances between physical counts."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:17.547Z"'::jsonb),
('card-1794233130997-78', NULL, 'deck-1794233130997-zs17b', 'A foodservice operation stores cleaning chemicals on the same shelf as canned food products to maximize storage space. Which storage requirement is being violated?', 'Separation of toxic and non-food items', 'Storing cleaning chemicals and toxic agents on the same shelves as food products violates critical health codes and safety regulations requiring complete physical separation to prevent accidental chemical contamination.

• Food arrangement: Refers to organizing food categories logically, though toxic separation takes precedence.
• Fixed location storage: Assigns designated shelf locations for inventory organization.
• Inventory record keeping: Relates to bookkeeping and stock ledger management.', '["Food arrangement","Fixed location storage","Separation of toxic and non-food items","Inventory record keeping"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:23.552Z"'::jsonb),
('card-1794233130997-79', NULL, 'deck-1794233130997-zs17b', 'Which inventory management practice BEST supports both inventory accuracy and accountability by documenting every receipt and every issuance of supplies?', 'Maintaining perpetual inventory records using stock report cards or bin cards', 'Using bin cards or stock report cards tied to perpetual inventory records ensures that every transaction is documented instantly, reinforcing dual inventory accuracy and staff accountability.

• Conducting annual physical inventory only: Inadequate for day-to-day stock tracking and loss prevention.
• Purchasing larger quantities to reduce ordering frequency: Increases holding costs and storage congestion.
• Scheduling deliveries during off-peak hours: Optimizes receiving logistics, but does not document issuance accountability.', '["Conducting annual physical inventory only","Purchasing larger quantities to reduce ordering frequency","Scheduling deliveries during off-peak hours","Maintaining perpetual inventory records using stock report cards or bin cards"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:29.919Z"'::jsonb),
('card-1794233130997-8', NULL, 'deck-1794233130997-zs17b', 'Which principle is being implemented?', 'Workflow Efficiency', 'Workflow efficiency optimizes physical movement, equipment layout, and staff traffic patterns to minimize time and energy loss during food production.', '["Workflow Efficiency","Standardization","Centralization","Forecasting"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:39.407Z"'::jsonb),
('card-1794233130997-80', NULL, 'deck-1794233130997-zs17b', 'A foodservice department consistently monitors food, labor, utilities, and equipment expenses while maintaining food quality and customer satisfaction. Which concept BEST describes this management activity?', 'Cost control', 'Cost control is the ongoing managerial process of monitoring, regulating, and optimizing operational expenses (food, labor, utilities, overhead) while preserving high food quality and customer satisfaction.

• Budget forecasting: Projecting future financial performance prior to the operating period.
• Inventory valuation: Determining the monetary worth of inventory items on hand.
• Financial auditing: Independent verification of financial statements and accounting records.', '["Cost control","Budget forecasting","Inventory valuation","Financial auditing"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:36.912Z"'::jsonb),
('card-1794233130997-81', NULL, 'deck-1794233130997-zs17b', 'A manager compares monthly utility expenses and discovers that electricity consumption has increased significantly because refrigeration equipment is left running with doors frequently left open. Which cost-control measure is MOST appropriate?', 'Reinforce proper equipment use and energy-conservation practices among employees.', 'When utility spikes occur due to preventable operational habits (like leaving refrigerator doors open), the immediate managerial corrective action is staff retraining and reinforcing energy conservation.

• Purchase less food: Does not address refrigeration electricity waste.
• Replace all refrigeration units immediately: A drastic, expensive measure unwarranted if equipment is functional and misuse is the root cause.
• Increase menu prices: Shifts operational inefficiency burdens onto customers rather than correcting internal waste.', '["Reinforce proper equipment use and energy-conservation practices among employees.","Purchase less food.","Replace all refrigeration units immediately.","Increase menu prices."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:43.814Z"'::jsonb),
('card-1794233130997-82', NULL, 'deck-1794233130997-zs17b', 'Which statement BEST distinguishes a budget from an income statement?', 'A budget is used to plan future operations, whereas an income statement evaluates past', 'A budget is a forward-looking financial plan used to guide future operations, whereas an income statement is a historical financial report evaluating past operational performance.', '["A budget evaluates past performance, while an income statement plans future operations.","A budget is used to plan future operations, whereas an income statement evaluates past","Both are used exclusively for monitoring labor costs.","Both documents are prepared only after the fiscal year ends."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:51.464Z"'::jsonb),
('card-1794233130997-83', NULL, 'deck-1794233130997-zs17b', 'A foodservice manager prepares next year’s financial plan by estimating revenues, forecasting expenses, allocating departmental resources, and setting expenditure limits. Which is the PRIMARY purpose of this activity?', 'To establish a budget that guides future operations', 'The primary purpose of preparing an annual financial plan detailing expected revenues, expenses, and resource limits is to establish an operational budget that guides future organizational performance.

• To determine the annual profit: Profit is calculated retrospectively on income statements, whereas budgets set targets.
• To prepare the income statement: Income statements reflect actual historical accounting data, not planned projections.
• To compute inventory turnover: Inventory turnover is an operational efficiency ratio derived from inventory and cost of goods sold data.', '["To determine the annual profit","To establish a budget that guides future operations","To prepare the income statement","To compute inventory turnover"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:59:57.636Z"'::jsonb),
('card-1794233130997-84', NULL, 'deck-1794233130997-zs17b', 'Which statement BEST distinguishes operating (overhead) costs from fixed costs in a foodservice operation?', 'Operating costs include utilities, repairs, and cleaning materials, whereas fixed costs include', 'Operating (overhead) costs fluctuate or support daily operational activities (such as utilities, repairs, and cleaning supplies), whereas fixed costs remain constant regardless of short-term production volume changes (such as insurance or rent).', '["Operating costs include rent and insurance, whereas fixed costs include utilities and office supplies.","Operating costs consist only of food purchases, whereas fixed costs consist only of labor expenses.","Operating costs remain constant regardless of production volume, whereas fixed costs vary according","Operating costs include utilities, repairs, and cleaning materials, whereas fixed costs include"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:04.455Z"'::jsonb),
('card-1794233130997-85', NULL, 'deck-1794233130997-zs17b', 'A dietary department consistently exceeds its food cost budget despite purchasing ingredients at competitive prices. An internal review shows that employees frequently prepare more food than is required and discard large amounts of leftovers. Which cost-control function should management strengthen FIRST?', 'Production control', 'When food costs exceed budget despite competitive purchasing prices due to excessive overproduction and leftover waste, management must strengthen production control (forecasting, batch cooking, portion tracking).

• Purchasing control: Purchasing is functioning well since ingredients were acquired at competitive prices.
• Utility cost control: Relates to electricity, water, and gas usage rather than food waste.
• Labor scheduling: Focuses on staffing hours rather than kitchen food overproduction.', '["Purchasing control","Production control","Utility cost control","Labor scheduling"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:10.471Z"'::jsonb),
('card-1794233130997-86', NULL, 'deck-1794233130997-zs17b', 'Which type of cost includes employee salaries, wages, overtime pay, and employee benefits incurred in operating a foodservice department?', 'Labor Cost', 'Labor cost encompasses all financial expenditures associated with human resources, including employee salaries, hourly wages, overtime compensation, and fringe benefits.

• Material Cost: Refers to direct food and ingredient expenses.
• Fixed Cost: Refers to overhead expenses that do not change with output volume (e.g., rent, insurance).
• Operating Cost: A broad term encompassing all day-to-day running expenses beyond direct food and labor.', '["Material Cost","Fixed Cost","Labor Cost","Operating Cost"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:16.201Z"'::jsonb),
('card-1794233130997-87', NULL, 'deck-1794233130997-zs17b', 'Which of the following expenses should be classified as a fixed cost rather than an operating (overhead) cost?', 'Insurance', 'Insurance is a classic fixed cost because the premium amount remains completely unchanged regardless of whether the foodservice facility serves 100 meals or 1,000 meals.

• Cleaning materials: Variable operating supplies that scale with production volume and sanitation needs.
• Electricity: A variable utility expense influenced by equipment operating hours and production volume.
• Telephone expenses: Operating overhead that can fluctuate depending on business activity.', '["Cleaning materials","Electricity","Telephone expenses","Insurance"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:21.269Z"'::jsonb),
('card-1794233130997-88', NULL, 'deck-1794233130997-zs17b', '25. During the monthly financial review, a foodservice manager observes the following: Food costs are within budget. Labor costs exceed the budget because of frequent overtime. Utility expenses are significantly higher than projected. Based on the principles of cost control, what is the MOST appropriate management action?', 'Analyze the causes of the labor and utility variances, implement targeted corrective actions, and', 'Effective cost control requires investigating budget variances (why overtime and utility costs spiked), enacting targeted operational adjustments, and monitoring subsequent performance.', '["Increase menu prices to compensate for higher operating expenses.","Focus corrective measures only on food purchasing because it accounts for the largest portion of the","Reduce food production to offset higher labor and utility costs.","Analyze the causes of the labor and utility variances, implement targeted corrective actions, and"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:28.131Z"'::jsonb),
('card-1794233130997-89', NULL, 'deck-1794233130997-zs17b', 'Which statement BEST distinguishes facility location from facility design?', 'Facility location concerns the placement of the operation relative to customers and suppliers,', 'Facility location refers to macro-site selection (geographic positioning relative to target markets, transport routes, and suppliers), whereas facility design involves interior layout, spatial flow, and equipment arrangement.', '["Facility location focuses on equipment arrangement, whereas facility design determines supplier","Facility location concerns the placement of the operation relative to customers and suppliers,","Facility location determines workflow, whereas facility design determines marketing strategy.","Facility location refers to interior space allocation, whereas facility design refers to site selection only"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:34.484Z"'::jsonb),
('card-1794233130997-9', NULL, 'deck-1794233130997-zs17b', 'Which of the following best demonstrates quality control in quantity food production?', 'Monitoring sensory qualities, temperatures, and hygiene practices throughout production', 'Quality control involves active, ongoing checks of food temperature, sensory characteristics (taste, texture, appearance), and sanitation standards during every phase of production.

• Purchasing ingredients in bulk: Relates to purchasing economics, not quality control.
• Preparing ingredients several days in advance: Can compromise safety and quality if not tightly controlled.
• Transporting food to satellite kitchens: Part of distribution systems rather than direct production quality control.', '["Purchasing ingredients in bulk","Monitoring sensory qualities, temperatures, and hygiene practices throughout production","Preparing ingredients several days in advance","Transporting food to satellite kitchens"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T14:48:45.605Z"'::jsonb),
('card-1794233130997-90', NULL, 'deck-1794233130997-zs17b', 'A restaurant installs self-service kiosks and expands its grab-and-go section because more customers prefer quick meal purchases. Which trend in foodservice design is MOST evident?', 'Changes in dining patterns', 'Installing self-service kiosks and expanding grab-and-go sections reflects adaptation to modern consumer shifts toward speed, convenience, and contactless ordering (changes in dining patterns).

• Environmental sustainability: Focuses on energy-efficient equipment, waste composting, and green building materials.
• Employee-centered design: Focuses on ergonomics, safety, and reducing physical strain for kitchen staff.
• Resource maximization: Focuses on optimizing spatial square footage and minimizing operating waste.', '["Environmental sustainability","Employee-centered design","Changes in dining patterns","Resource maximization"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:41.042Z"'::jsonb),
('card-1794233130997-91', NULL, 'deck-1794233130997-zs17b', 'Which design principle primarily aims to minimize unnecessary movement of employees, food, and equipment?', 'Work flow', 'Work flow refers to the movement of food, ingredients, personnel, and equipment through the production cycle in a logical sequence that minimizes backtracking and wasted motion.

• Traffic flow: Refers specifically to the movement patterns of customers and service staff in dining and serving areas.
• Resource maximization: Focuses on efficient utilization of financial, spatial, and labor assets.
• Energy use: Relates to electrical, gas, and thermal utility efficiency.', '["Traffic flow","Resource maximization","Energy use","Work flow"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:46.978Z"'::jsonb),
('card-1794233130997-92', NULL, 'deck-1794233130997-zs17b', 'A cafeteria redesigns its customer queue to shorten waiting time and increase the number of customers served during lunch. Which design principle is being optimized?', 'Traffic flow', 'Redesigning a customer queue to eliminate bottlenecks and accelerate service speed optimizes customer and staff traffic flow through the cafeteria line.

• Resource maximization: Focuses on general asset utilization rather than queue movement.
• Energy use: Pertains to utility conservation.
• Work flow: Relates primarily to internal kitchen production movement rather than customer dining queues.', '["Traffic flow","Resource maximization","Energy use","Work flow"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:00:55.171Z"'::jsonb),
('card-1794233130997-93', NULL, 'deck-1794233130997-zs17b', 'Security, surveillance, controlled serving, and sabotage prevention are major planning considerations for which type of foodservice operation?', 'Correctional facility', 'Correctional facilities (prisons and detention centers) require rigorous architectural and operational planning centered on physical security, surveillance, controlled meal service, and contraband/sabotage prevention.

• Commercial restaurant: Focuses primarily on customer ambiance, table turnover, and culinary appeal.
• School cafeteria: Focuses on high-speed student serving lines and child nutrition standards.
• Hotel: Focuses on guest hospitality, luxury amenities, and multi-outlet dining flexibility.', '["Commercial restaurant","School cafeteria","Correctional facility","Hotel"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:01:02.396Z"'::jsonb),
('card-1794233130997-94', NULL, 'deck-1794233130997-zs17b', 'Which planning document is BEST described as the architectural plan of space on one floor of a building viewed from above?', 'Floor plan', 'A floor plan is an architectural scale drawing viewed from above that maps out the spatial dimensions, partitions, and layout of rooms on a specific building floor.

• Blueprint: A comprehensive engineering and construction drawing detailing technical specifications.
• Layout design: The general arrangement of equipment and work centers within a space.
• Specifications: Detailed written descriptions of material quality, equipment dimensions, and construction standards.', '["Blueprint","Floor plan","Layout design","Specifications"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:01:08.535Z"'::jsonb),
('card-1794233130997-95', NULL, 'deck-1794233130997-zs17b', 'A company plans to replace one major piece of kitchen equipment and renovate a small preparation area. The project involves only the owner, manager, equipment supplier, and a facilities consultant. According to the reviewer, this project is classified as:', 'Level I', 'Project scope in facility planning is categorized by scale: Level I projects involve minor equipment replacements or small-scale renovations with minimal external consultants; larger structural overhauls fall into Levels II and III.

• Level II: Involves moderate facility modifications and broader operational restructuring.
• Level III: Involves major new facility construction or complete multi-departmental architectural rebuilds.', '["Level I","Level II","Level III","None of the Above"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:01:16.842Z"'::jsonb),
('card-1794233130997-96', NULL, 'deck-1794233130997-zs17b', 'After completing the feasibility study for a proposed foodservice facility, what is the NEXT major step in the planning procedure?', 'Perform menu analysis', 'After a feasibility study confirms a project is viable, the very next major technical step in facility planning is conducting a thorough menu analysis, because the menu dictates equipment requirements, spatial layout, and utility needs.

• Organize the planning team: Typically formed before or concurrently with the initial feasibility study.
• Plan architectural features: Follows menu planning and preliminary layout design.
• Evaluate the budget-cost relationship: Assessed continuously throughout planning, but detailed equipment and space costing depend directly on finalized menu requirements.', '["Organize the planning team","Plan architectural features","Evaluate the budget-cost relationship","Perform menu analysis"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:01:23.184Z"'::jsonb),
('card-1794233130997-97', NULL, 'deck-1794233130997-zs17b', 'A nutrition educator plans to teach food handlers the proper handwashing procedure and prevention of cross- contamination. The session requires learners to observe the correct techniques before performing them. Which teaching aid would be MOST appropriate?', 'Demonstration materials', 'Teaching procedural skills like proper handwashing and cross-contamination prevention requires learners to observe correct techniques visually before practicing, making demonstration materials the most effective instructional aid.

• Recipe cards: Used for standardizing culinary proportions, not teaching physical hygiene technique.
• Pamphlets: Provide static reading material, lacking the visual modeling needed for procedural skills.', '["Recipe cards","Demonstration materials","Pamphlets","Option D"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:01:32.446Z"'::jsonb),
('card-1794233130997-98', NULL, 'deck-1794233130997-zs17b', 'Which educational framework is internationally recognized and commonly used to teach food safety principles through posters, demonstrations, videos, flipcharts, and food handler manuals?', 'WHO Five Keys to Safer Food', 'The World Health Organization (WHO) "Five Keys to Safer Food" is an internationally recognized educational framework utilized globally via posters, videos, flipcharts, and training manuals to teach core food safety hygiene.

• Dietary Reference Intakes (DRIs): Nutrient reference standards, not food safety hygiene frameworks.
• MyPlate Food Guide: A nutritional dietary intake graphic, not a food safety handling curriculum.
• Hazard Analysis and Risk Assessment Framework: Refers to HACCP system design principles rather than general public food handler posters.', '["Dietary Reference Intakes (DRIs)","MyPlate Food Guide","WHO Five Keys to Safer Food","Hazard Analysis and Risk Assessment Framework"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:01:39.085Z"'::jsonb),
('card-1794233130997-99', NULL, 'deck-1794233130997-zs17b', 'A hospital foodservice department implements plate waste monitoring, composting, sustainable procurement, and staff education while ensuring that patients continue to receive nutritionally adequate meals. According to recent foodservice research, what is the PRIMARY objective of these initiatives?', 'Improve environmental sustainability while maintaining nutritional quality and operational', 'Modern institutional foodservice research highlights that sustainability initiatives (composting, plate waste audits, green procurement) must successfully coexist with uncompromised patient nutritional care and operational viability.', '["Reduce labor requirements without affecting meal quality.","Improve environmental sustainability while maintaining nutritional quality and operational","Increase menu variety regardless of operational costs.","Replace conventional foodservice systems with fully automated operations."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:30.997Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:30.997Z"'::jsonb, '"2026-11-09T15:01:44.998Z"'::jsonb),
('card-1794233131145-0', NULL, 'deck-1794233131145-bql1k', 'Refers to the application of NCP for the purposes of disease prevention, treatment, and management', 'Medical nutrition therapy', 'Medical nutrition therapy refers specifically to the application of the Nutrition Care Process (NCP) by registered nutritionists-dietitians for the purpose of disease prevention, treatment, and medical management.

• Diet therapy: A broader or more general term for modifying dietary intake for therapeutic purposes.
• Clinical nutrition: The broader scientific discipline focusing on the nutritional management of patients in a clinical or medical environment.
• Dietetics: The professional discipline and art/science of applying nutritional principles to human health and well-being.', '["Diet therapy","Medical nutrition therapy","Clinical nutrition","Dietetics"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:33:57.698Z"'::jsonb),
('card-1794233131146-1', NULL, 'deck-1794233131145-bql1k', 'Principle of diet therapy which tells that diet should not vary from the individual’s diet', 'Simplification', 'Simplification is the fundamental principle of diet therapy stating that a therapeutic diet should be kept as close to the individual''s normal habitual diet as possible to maximize compliance.

• Individualization: Tailoring a diet plan to fit a patient''s personal preferences, lifestyle, and biochemical status.
• Liberalization: Eliminating unnecessary restrictions to improve dietary intake and patient quality of life.
• Adequacy: Ensuring the diet provides all essential nutrients in sufficient amounts.', '["Liberalization","Individualization","Simplification","Adequacy"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:04.515Z"'::jsonb),
('card-1794233131146-2', NULL, 'deck-1794233131145-bql1k', 'Which of the following is not considered a source of information during nutrition assessment in the hospital setting?', 'None of the above', 'All listed options (referral forms, patient interviews, and consultations with caregivers or family members) are valid and vital sources of information during hospital nutrition assessments.', '["Referral form","Patient interview","Consultation with caregiver and family members","None of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:09.714Z"'::jsonb),
('card-1794233131146-3', NULL, 'deck-1794233131145-bql1k', 'Clear liquid diet consists of clear fluid and juices that provide little residue and are easily absorbed. Foods allowed in a clear liquid diet include:', 'Plain gelatin, black coffee, fat-free broth / bouillon', 'Plain gelatin, black coffee, and fat-free broth are clear liquid items that leave virtually no residue in the gastrointestinal tract and are transparent at room temperature.

• Strained fruit juice, whole milk, plain custard pudding: Contains dairy and milk products, which are strictly excluded from clear liquid diets and belong to full liquids.
• Plain gelatin, milk drinks, strained lugao: Milk drinks and heavier blended items violate clear liquid parameters.
• Melted butter, hard candies, yogurt: Butter and yogurt are high-fat and dairy items not permitted on a clear liquid protocol.', '["Plain gelatin, black coffee, fat-free broth / bouillon","Strained fruit juice, whole milk, plain custard pudding","Plain gelatin, milk drinks, strained lugao","Melted butter, hard candies, yogurt"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:17.131Z"'::jsonb),
('card-1794233131146-4', NULL, 'deck-1794233131145-bql1k', 'Malnutrition that develops as an unintended consequence of medical or surgical management is referred to as; also known as ‘physician-induced malnutrition’', 'Iatrogenic malnutrition', 'Iatrogenic malnutrition is inadvertent protein-energy malnutrition induced as an unintended consequence of hospital medical, diagnostic, or surgical management (physician-induced).

• Comorbidity malnutrition: Malnutrition arising from co-existing chronic disease burdens.
• Drug-induced malnutrition: Specific nutritional deficiencies caused by pharmaceutical interference with nutrient absorption or metabolism.
• Illness-related malnutrition: Malnutrition driven by underlying inflammatory disease states or acute injury.', '["Comorbidity malnutrition","Iatrogenic malnutrition","Drug-induced malnutrition","Illness-related malnutrition"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:23.043Z"'::jsonb),
('card-1794233131147-10', NULL, 'deck-1794233131145-bql1k', 'Step of the NCP that mirrors the Nutrition Assessment and determines the effectiveness of nutritional care provided to patients', 'Nutrition Monitoring and Evaluation', 'Nutrition Monitoring and Evaluation is the final step of the NCP that mirrors assessment and measures whether nutritional care goals and outcomes were successfully achieved.

• Nutrition Reassessment: A component of monitoring, but the step name is Monitoring and Evaluation.
• Nutrition Diagnosis: Identifies and labels the specific nutritional problem (PES statement).
• Nutrition Intervention: The targeted actions taken to resolve the nutrition diagnosis.', '["Nutrition Reassessment","Nutrition Diagnosis","Nutrition Intervention","Nutrition Monitoring and Evaluation"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:57.780Z"'::jsonb),
('card-1794233131147-11', NULL, 'deck-1794233131145-bql1k', 'According to the DOH AO 2019-0033, nutrition screening must be performed by _____ upon admission while the _____ shall refer all cases needing MNT to RNDs.', 'Nurses, Physician on duty', 'Per Department of Health (DOH) Administrative Order standards, nursing personnel perform initial nutrition screening upon hospital admission, and physicians on duty formally refer patients requiring medical nutrition therapy to registered nutritionists-dietitians (RNDs).

• RND, Nutrition Interns: Incorrect role allocation for admission triage.
• Nursing Aide, Nurses: Nursing aides do not hold primary triage responsibility for formal admission screening.
• Physician on duty, Nurses: Reverses the initial screening and referral roles.', '["RND, Nutrition Interns","Nurses, Physician on duty","Nursing Aide, Nurses","Physician on duty, Nurses"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:03.269Z"'::jsonb),
('card-1794233131147-12', NULL, 'deck-1794233131145-bql1k', 'Which of the following conditions is not classified as nutritionally at risk (NAR) under the DOH Guidelines for the Implementation of NCP in Hospitals?', 'Patients with involuntary loss or gain of 5% of usual body weight within 6 months.', 'This option is incorrect under DOH criteria (clinical threshold for significant weight loss is typically 5% within 1 month, 7.5% within 3 months, or 10% within 6 months, making this the correct answer to the "not classified as nutritionally at risk" question).

• Patients with inadequate nutrition intake for greater than 1 week: Classified as nutritionally at risk.
• Patients receiving total enteral nutrition: Classified as nutritionally at risk requiring specialized support.
• Patients with diabetes mellitus: Chronic metabolic disease classified under nutritional risk protocols.', '["Patients with inadequate nutrition intake for greater than 1 week","Patients receiving total enteral nutrition","Patients with diabetes mellitus","Patients with involuntary loss or gain of 5% of usual body weight within 6 months."]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:15.338Z"'::jsonb),
('card-1794233131147-13', NULL, 'deck-1794233131145-bql1k', 'The nutrition diagnosis and its _____ drives the selection of appropriate nutrition intervention.', 'Etiology', 'The etiology is the root cause or underlying pathophysiology (the "E" in the PES statement) that directly drives the selection of appropriate nutrition intervention strategies.

• Problem: The diagnostic label describing the nutritional alteration (the "P").
• Signs and Symptoms: The defining characteristics or data supporting the diagnosis (the "S").
• Reference Values: Standard laboratory or clinical cut-offs used for comparison.', '["Problem","Etiology","Signs and Symptoms","Reference Values"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:21.521Z"'::jsonb),
('card-1794233131147-14', NULL, 'deck-1794233131145-bql1k', 'In the SOAP documentation format, which step outlines the interventions that are necessary to treat the identified nutrition problems?', 'Plan', 'The "P" in the SOAP charting format details the specific medical nutrition therapy interventions, education goals, and follow-up plans required to address identified problems.

• Subjective: Patient-reported symptoms and history.
• Objective: Measurable data such as lab results and anthropometrics.
• Assessment: Clinical evaluation and synthesis of subjective and objective findings.', '["Subjective","Objective","Assessment","Plan"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:28.609Z"'::jsonb),
('card-1794233131147-15', NULL, 'deck-1794233131145-bql1k', 'What is the main difference between the ADIME and SOAP charting methods?', 'ADIME specifically outlines the monitoring and evaluation plan while SOAP does not.', 'The primary structural difference is that ADIME explicitly embeds dedicated steps for Monitoring and Evaluation, whereas SOAP relies on the Plan section.', '["ADIME is used exclusively by physicians, whereas SOAP is intended only for dietitians.","ADIME specifically outlines the monitoring and evaluation plan while SOAP does not.","ADIME focuses only on nutrition assessment, while SOAP includes all stages of patient care.","ADIME is a narrative charting format, whereas SOAP relies solely on numerical data."]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:36.705Z"'::jsonb),
('card-1794233131147-16', NULL, 'deck-1794233131145-bql1k', 'Classification of obesity that is characterized by increase in the size of cells', 'Hypertrophy', 'Hypertrophy is adipose or muscle tissue growth characterized by an increase in the size of existing cells.

• Hyperplasia: Increase in the total number of cells.
• Android: Apple-shaped fat distribution pattern.
• Gynoid: Pear-shaped fat distribution pattern.', '["Hyperplasia","Hypertrophy","Android","Gynoid"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:41.459Z"'::jsonb),
('card-1794233131147-17', NULL, 'deck-1794233131145-bql1k', 'The human body employs physiological adaptations to maintain nutrient balance during periods of inadequate or excessive intake. Which of the following does NOT represent one of these adaptive mechanisms?', 'A decrease in body temperature results in decreased energy expenditure.', 'This statement is false (hence the correct answer to the "does NOT represent" question), because cold exposure or drops in body temperature trigger thermogenesis and shivering, which actually increase energy expenditure to generate heat.', '["Iron absorption from the gastrointestinal tract becomes more efficient when iron stores are depleted.","Excess vitamin C consumed from supplements is eliminated through the urine.","Surplus amounts of certain nutrients, such as iron, calcium, vitamin A, and vitamin B12, may be stored for future use.","A decrease in body temperature results in decreased energy expenditure."]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:49.216Z"'::jsonb),
('card-1794233131147-18', NULL, 'deck-1794233131145-bql1k', 'Hydrochloric acid (HCl) and intrinsic factor (IF) are secreted by which gastric mucosal cell?', 'Parietal cells', 'Parietal cells are gastric mucosal cells responsible for secreting hydrochloric acid (HCl) and intrinsic factor.

• Chief cells: Secrete pepsinogen and gastric lipase.
• G cells: Secrete the hormone gastrin.
• Mucus cells: Secrete protective alkaline mucus.', '["Chief cells","G cells","Parietal cells","Mucus cells"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:35:55.398Z"'::jsonb),
('card-1794233131147-19', NULL, 'deck-1794233131145-bql1k', 'Which condition is characterized by localized cell or tissue death and is associated with acute inflammation?', 'Necrosis', 'Necrosis is pathological, premature cell and tissue death resulting from acute injury, trauma, or ischemia, closely associated with acute inflammation.

• Apoptosis: Programmed, orderly cell death.
• Autolysis: Self-digestion of cells by endogenous enzymes post-mortem or post-injury.
• Gangrene: Extensive necrosis accompanied by bacterial putrefaction.', '["Apoptosis","Autolysis","Gangrene","Necrosis"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:01.050Z"'::jsonb),
('card-1794233131147-20', NULL, 'deck-1794233131145-bql1k', 'Cell adaptation that pertains to abnormal, disordered cell growth in which the cells are structurally changed in size, shape, and appearance from the original cell type.', 'Dysplasia', 'Dysplasia is abnormal, disordered cellular growth and maturation resulting in altered cell size, shape, and internal organization compared to normal tissue.

• Metaplasia: Reversible replacement of one mature cell type by another adult cell type.
• Hyperplasia: Increase in the number of cells in an organ or tissue.
• Hypertrophy: Increase in the physical size of cells.', '["Metaplasia","Dysplasia","Hyperplasia","Hypertrophy"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:06.529Z"'::jsonb),
('card-1794233131147-21', NULL, 'deck-1794233131145-bql1k', 'These nutrients act as anti-oxidant as it fights off oxidative stress, except:', 'Vitamin K', 'Vitamin K functions primarily in blood coagulation and bone metabolism, not as a primary systemic antioxidant.

• Vitamins A, C, and E: Classic antioxidant vitamins that neutralize reactive oxygen species.
• Selenium: An essential trace mineral serving as a co-factor for antioxidant glutathione peroxidase enzymes.
• Zinc: Plays a crucial structural and catalytic antioxidant role in cellular defense mechanisms.', '["Vitamins A, C, and E","Selenium","Zinc","Vitamin K"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:12.582Z"'::jsonb),
('card-1794233131147-22', NULL, 'deck-1794233131145-bql1k', 'Which component of the immune system acts as the first protective barrier against microorganisms?', 'Skin and mucous membrane lining', 'The skin and mucous membrane lining are the physical and chemical surface barriers representing the body''s first line of defense against invading microorganisms.

• Innate immunity: Non-specific internal cellular and chemical defenses.
• Adaptive immunity: Antigen-specific acquired immune responses involving lymphocytes.
• Humoral immunity: Antibody-mediated immunity driven by B cells.', '["Skin and mucous membrane lining","Innate immunity","Adaptive immunity","Humoral immunity"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:18.109Z"'::jsonb),
('card-1794233131147-23', NULL, 'deck-1794233131145-bql1k', 'A type of adaptive immunity that provides defense against intracellular microbes and viruses through the response of specific T cells.', 'Cellular immunity', 'Cellular immunity is an adaptive immune mechanism providing defense against intracellular microbes, viruses, and tumor cells via activated T-lymphocytes.

• Humoral immunity: B-cell and antibody-mediated defense against extracellular pathogens.
• Antigen: Any substance recognized as foreign that provokes an immune response.
• Antibody: Specialized proteins produced by plasma cells to bind specific antigens.', '["Humoral immunity","Cellular immunity","Antigen","Antibody"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:23.451Z"'::jsonb),
('card-1794233131147-24', NULL, 'deck-1794233131145-bql1k', 'Which T-cell subtype is also known as the helper T cell and is primarily affected in HIV infection?', 'CD4+', 'CD4+ are T-helper lymphocyte subtypes that coordinate immune responses and serve as the primary cellular target infected and depleted by HIV.

• CD8+: Cytotoxic T-lymphocytes responsible for destroying infected host cells.
• Regulatory T cell: Modulates immune responses and maintains self-tolerance.
• Memory T cell: Persists long-term after infection to mount rapid secondary responses.', '["CD4+","CD8+","Regulatory T cell","Memory T cell"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:28.545Z"'::jsonb),
('card-1794233131147-25', NULL, 'deck-1794233131145-bql1k', 'An antibody that crosses the placenta and thus responsible for protection of newborn babies', 'IgG', 'IgG is the predominant circulating immunoglobulin subclass capable of actively crossing the human placenta to provide passive systemic immunity to the developing fetus and newborn.

• IgA: Dominant immunoglobulin found in mucosal secretions and breast milk.
• IgD: Primarily acts as an antigen receptor on B-cell surfaces.
• IgE: Involved in immediate hypersensitivity, allergic reactions, and defense against parasites.', '["IgG","IgA","IgD","IgE"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:35.097Z"'::jsonb),
('card-1794233131147-26', NULL, 'deck-1794233131145-bql1k', 'An antibody that protects mucous membranes and may be secreted by breastmilk.', 'IgA', 'IgA is a secretory immunoglobulin specialized in protecting mucosal surfaces (respiratory and GI tracts) and heavily concentrated in human breast milk.

• IgG: Main placental-crossing systemic antibody.
• IgD: Cell-surface B-cell receptor.
• IgE: Mediates allergic hypersensitivity.', '["IgG","IgA","IgD","IgE"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:41.121Z"'::jsonb),
('card-1794233131147-5', NULL, 'deck-1794233131145-bql1k', 'What is considered the gold standard for measuring resting energy expenditure (REE) by determining oxygen consumption (VO₂) and carbon dioxide production (VCO₂)?', 'Indirect calorimetry', 'Indirect calorimetry is considered the clinical gold standard for measuring resting energy expenditure (REE) by quantifying oxygen consumption and carbon dioxide production.

• DEXA Scan: Dual-energy X-ray absorptiometry used primarily to measure bone mineral density and body composition.
• Bioimpedance analysis: Estimates body composition based on electrical conductivity through tissues.
• Handgrip dynamometer: Assesses functional muscle strength rather than energy expenditure.', '["Indirect calorimetry","DEXA Scan","Bioimpedance analysis","Hangrip dynamometer"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:29.085Z"'::jsonb)
