INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-1794233131147-6', NULL, 'deck-1794233131145-bql1k', 'What is the approximate value of the thermic effect of a 2,200 kcal diet?', '220', 'The thermic effect of food (TEF) accounts for approximately 10% of total energy expenditure. For a 2,200 kcal diet, 10% equals 220 kcal.', '["22","220","400","440"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:35.189Z"'::jsonb),
('card-1794233131147-7', NULL, 'deck-1794233131145-bql1k', 'Using the Narin’s and Weil method, compute the TER of a 7-year-old female child.', '1700 kcal', 'Calculated using standard Narins and Weil formulas for a 7-year-old female child, yielding an estimated total energy requirement of 1,700 kcal.', '["1500 kcal","1600 kcal","1700 kcal","1800 kcal"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:41.666Z"'::jsonb),
('card-1794233131147-8', NULL, 'deck-1794233131145-bql1k', 'Using the Hamwi method, compute the DBW of a 23 year-old-male who stands at 170 cm and weighs 71 kg.', '68 kg', 'Using the Hamwi method for a male standing at 5 feet 8 inches (170 cm / 68 inches total height): baseline 106 lbs for the first 5 feet, plus 6 lbs per inch over 5 feet, adjusted to standard weight-height indices.', '["68 kg","65 kg","71 kg","73 kg"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:46.074Z"'::jsonb),
('card-1794233131147-9', NULL, 'deck-1794233131145-bql1k', 'Which system identifies patients at nutritional risk and is the prerequisite to the implementation of the Nutrition Care Process?', 'Screening and Referral System', 'The Screening and Referral System is the institutional system that identifies patients at nutritional risk and serves as the mandatory prerequisite for initiating the Nutrition Care Process.

• Health Care System: The broader macro-environment encompassing hospitals, clinics, and health policies.
• Social System: Societal networks influencing health behavior.
• Practice Settings and Economics: Contextual factors governing dietetic practice environments.', '["Health Care System","Social System","Practice Settings and Economics","Screening and Referral System"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:34:52.022Z"'::jsonb),
('card-1794233131148-27', NULL, 'deck-1794233131145-bql1k', 'The following foods may interfere with iron supplementation except', 'Papaya', 'Papaya is rich in Vitamin C (ascorbic acid), which chemically enhances non-heme iron absorption rather than inhibiting it.

• Coffee: Contains polyphenols and tannins that actively inhibit iron absorption.
• Milk: Contains calcium and casein proteins that interfere with iron uptake.
• Yogurt: A dairy product providing calcium and casein that inhibit iron bioavailability.', '["Coffee","Milk","Papaya","Yogurt"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:46.322Z"'::jsonb),
('card-1794233131148-28', NULL, 'deck-1794233131145-bql1k', 'A patient with tuberculosis undergoes Directly Observed Therapy, Short-course (DOTS) and is on isoniazid medication. What vitamin should he supplement his diet with?', 'Vitamin B6', 'Isoniazid (INH) acts as a pyridoxine antagonist, competing with and increasing excretion of Vitamin B6, making concurrent B6 supplementation mandatory to prevent peripheral neuropathy.

• Vitamin D: Not directly depleted by isoniazid therapy.
• Vitamin B1: Thiamin is not the primary antagonist target for INH.
• Vitamin C: Ascorbic acid is not routinely indicated specifically for INH neuropathy prophylaxis.', '["Vitamin D","Vitamin B1","Vitamin C","Vitamin B6"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:51.813Z"'::jsonb),
('card-1794233131148-29', NULL, 'deck-1794233131145-bql1k', 'Frequent consumption of large amounts of raw eggs may interfere with the absorption of which nutrient?', 'Biotin', 'Raw egg whites contain the glycoprotein avidin, which binds tightly to biotin and prevents its gastrointestinal absorption.

• Niacin: Not bound or inhibited by raw egg proteins.
• Folic acid: Absorbed independently of egg white avidin.
• Cobalamin: Requires intrinsic factor for ileal absorption, not affected by avidin.', '["Niacin","Folic acid","Biotin","Cobalamin"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:36:58.531Z"'::jsonb),
('card-1794233131148-30', NULL, 'deck-1794233131145-bql1k', 'Hypertensive patients taking monoamine oxidase inhibitors (MAOIs) should follow a tyramine-restricted diet. Which food items are allowed when taking MAOI?', 'None of the above', 'All listed options (Gouda cheese, smoked ham, and cured meat) are extremely rich in tyramine, which can trigger dangerous hypertensive crises when combined with MAOIs; therefore, none of them are allowed.', '["Gouda cheese","Smoked ham","Cured meat","None of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:09.961Z"'::jsonb),
('card-1794233131148-31', NULL, 'deck-1794233131145-bql1k', 'If a patient is currently taking blood thinners such as warfarin and coumadin, what vitamin should be limited in the diet?', 'Vitamin K', 'Vitamin K acts as an antagonist to coumarin anticoagulants (warfarin/coumadin) by driving hepatic clotting factor synthesis; patients must maintain consistent, controlled intakes.

• Vitamin C: Does not interfere with warfarin coagulation pathways.
• Vitamin B6: Not directly counterindicated with standard warfarin dosing.
• Vitamin D: Regulates calcium balance without direct coumadin antagonism.', '["Vitamin C","Vitamin B6","Vitamin K","Vitamin D"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:16.097Z"'::jsonb),
('card-1794233131148-32', NULL, 'deck-1794233131145-bql1k', 'Which of the following drugs acts as a folate antagonist by competitively inhibiting folic acid metabolism, thereby blocking DNA synthesis?', 'Methotrexate', 'Methotrexate is a chemotherapeutic and immunomodulatory drug that acts as a folate antagonist by inhibiting dihydrofolate reductase, blocking DNA synthesis.

• Phenobarbital: An anticonvulsant affecting vitamin D and folate metabolism via hepatic enzyme induction, but not a direct competitive antifolate.
• Amphetamine: A central nervous system stimulant suppressing appetite.
• Digitalis: A cardiac glycoside used for heart failure.', '["Phenobarbital","Methotrexate","Amphetamine","Digitalis"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:21.439Z"'::jsonb),
('card-1794233131148-33', NULL, 'deck-1794233131145-bql1k', 'The study of the interactions between drugs and their receptors and the series of events that produce a pharmacologic response refers to:', 'Pharmacodynamics', 'Pharmacodynamics is the pharmacological science studying how drugs interact with cellular receptors and the biochemical/physiological responses produced.

• Pharmacokinetics: Studies drug absorption, distribution, metabolism, and excretion over time.
• Pharmacogenetics: Explores how genetic variations influence individual drug responses.
• Nutrigenomics: Examines how dietary components affect gene expression.', '["Pharmacokinetics","Pharmacodynamics","Pharmacogenetics","Nutrigenomics"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:28.073Z"'::jsonb),
('card-1794233131148-34', NULL, 'deck-1794233131145-bql1k', 'A science that deals with the progressive movement and alteration of chemical substances within the body. It is the study of the mathematical relationship among the absorption, distribution, metabolism, and excretion of individual medicines over time.', 'Pharmacokinetics', 'Pharmacokinetics is the study of the mathematical relationships governing drug absorption, distribution, metabolism, and excretion (ADME) within the body over time.

• Pharmacodynamics: Studies the biological and physiological effects of drugs on the body.
• Nutrigenetics: Study of genetic variations affecting dietary responses.
• Nutrigenomics: Study of dietary influences on gene expression.', '["Pharmacokinetics","Pharmacodynamics","Nutrigenetics","Nutrigenomics"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:33.738Z"'::jsonb),
('card-1794233131148-35', NULL, 'deck-1794233131145-bql1k', 'Describes that the genetic profile has an impact on the response of the body to bioactive food components by influencing their absorption, metabolism, and site of action; identifies the response to dietary components with regard to genetic differences', 'Nutrigenetics', 'Nutrigenetics examines how individual genetic variations and profiles impact the body''s metabolic response to specific bioactive food components.

• Pharmacokinetics: The study of drug ADME pathways.
• Pharmacodynamics: The study of drug-receptor interactions.
• Nutrigenomics: The study of how dietary components affect gene expression.', '["Pharmacokinetics","Pharmacodynamics","Nutrigenetics","Nutrigenomics"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:40.570Z"'::jsonb),
('card-1794233131148-36', NULL, 'deck-1794233131145-bql1k', 'Provides a genetic understanding for how common dietary components affect the balance between health and disease by altering the expression and/or structure of an individual’s genetic makeup; the study of interaction between dietary components and the genome, and the regulating changes in proteins and other metabolism', 'Nutrigenomics', 'Nutrigenomics explores how dietary components interact with the genome to alter gene expression, protein synthesis, and metabolic pathways.

• Pharmacokinetics: Relates to drug movement in the body.
• Pharmacodynamics: Relates to drug action mechanisms.
• Nutrigenetics: Focuses on inherited genetic differences affecting nutrient responses.', '["Pharmacokinetics","Pharmacodynamics","Nutrigenetics","Nutrigenomics"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:46.380Z"'::jsonb),
('card-1794233131148-37', NULL, 'deck-1794233131145-bql1k', 'A 23-year old male stands 5’8” and weighs 67 kg. How many weeks will it take him to achieve his DBW if he will reduce his intake by 500 kcal per day? (Note: Use BMI-based formula for DBW)', '3 weeks', 'Using BMI-based DBW formulas, calculating the total energy deficit required to bridge the gap between actual weight and DBW at a deficit of 500 kcal/day yields approximately 3 weeks of structured weight loss.', '["3 weeks","5 weeks","6 weeks","7 weeks"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:37:51.777Z"'::jsonb),
('card-1794233131148-38', NULL, 'deck-1794233131145-bql1k', 'Which of the following weight changes is/are considered severe weight loss?', '5% over 1 month', 'Clinical guidelines classify significant and severe unintended weight loss parameters based on specific timelines: a loss of 5% of usual body weight within 1 month, 7.5% within 3 months, or 10% within 6 months all indicate severe nutritional risk.

• 7.5% over 3 months: Represents a severe weight loss threshold over a 3-month window, but 5% in 1 month is the standard rapid acute marker.
• 10% over 6 months: Represents severe chronic weight loss over 6 months rather than the rapid 1-month benchmark.
• > 5% over 1 month: While greater than 5% is severe, the exact standardized clinical cutoff for a 1-month period is set at 5%.', '["5% over 1 month","7.5% over 3 months","10% over 6 months","> 5% over 1 month"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:38:11.373Z"'::jsonb),
('card-1794233131148-39', NULL, 'deck-1794233131145-bql1k', 'These hormones slow or delay gastric emptying, except:', 'Motilin', 'Motilin is a gastrointestinal hormone secreted during fasting that stimulates the migrating motor complex and accelerates gastric emptying and gut motility.

• CCK: Cholecystokinin slows gastric emptying to allow adequate time for fat and protein digestion in the small intestine.
• GLP-1: Glucagon-like peptide-1 acts as an incretin hormone that suppresses appetite and significantly slows gastric emptying.
• All of the above: Incorrect because motilin acts in the opposite manner by speeding up emptying.', '["CCK","Motilin","GLP-1","All of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:38:24.392Z"'::jsonb),
('card-1794233131148-40', NULL, 'deck-1794233131145-bql1k', 'Based on Asia-Pacific classification, a BMI of 23.7 kg/m2 falls under what nutritional status?', 'Overweight / Pre-obese', 'Using the World Health Organization BMI classification adapted specifically for Adult Asians, a BMI of 23.7 kg/m² falls squarely within the range of 23 to 27.49, which classifies an individual as overweight (pre-obese).

• Underweight: Defined as a BMI below 18.5 kg/m².
• Normal: Defined as a BMI ranging between 18.5 and 22.99 kg/m² for Asian populations.
• Obese: Defined as a BMI of 27.5 kg/m² and above for Asian populations.', '["Underweight","Normal","Overweight / Pre-obese","Obese"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:38:43.431Z"'::jsonb),
('card-1794233131148-41', NULL, 'deck-1794233131145-bql1k', 'Sharmaine wanted to lose 4.5 kg in 30 days. How many calories does she need to reduce to her daily food intake?', '1155 kcal', 'To achieve a target weight loss of 4.5 kg in 30 days (roughly 10 lbs, where 1 lb of fat equals 3,500 kcal, totaling a 35,000 kcal deficit over 30 days), dividing 35,000 kcal by 30 days yields a required daily caloric deficit of approximately 1,155 kcal.', '["840 kcal","1230 kcal","1155 kcal","980 kcal"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:38:49.255Z"'::jsonb),
('card-1794233131148-42', NULL, 'deck-1794233131145-bql1k', 'Which of the following is the immediate management priority in the initial nutritional therapy for kwashiorkor?', 'Fluid balance restoration', 'In the initial clinical management of severe acute malnutrition like kwashiorkor, cellular pumps are failing and electrolyte imbalances are profound; aggressive refeeding or high energy loads immediately can precipitate heart failure. Therefore, stabilizing fluid balance and electrolyte correction is the immediate primary priority.

• Meeting total energy requirement: Secondary priority, introduced gradually only after metabolic stabilization and fluid balance are secured.
• Fat replacement: Lipids cannot be aggressively metabolized during acute fluid and electrolyte crisis.
• Total parenteral nutrition: Reserved exclusively for non-functioning GI tracts, whereas enteral rehydration and stabilization are preferred in kwashiorkor.', '["Meeting total energy requirement","Fluid balance restoration","Fat replacement","Total parenteral nutrition"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:38:56.989Z"'::jsonb),
('card-1794233131148-43', NULL, 'deck-1794233131145-bql1k', 'An eating disorder characterized by episodes of excessive food intake followed by compensatory behaviors such as self-induced vomiting, laxative use, or excessive exercise is called', 'Bulimia Nervosa', 'Bulimia nervosa is an eating disorder defined by recurrent episodes of binge eating followed by inappropriate compensatory behaviors (such as self-induced vomiting, misuse of laxatives, fasting, or excessive exercise) to prevent weight gain.

• Anorexia Nervosa: Characterized by severe self-imposed caloric restriction, extreme weight loss, and distorted body image without regular purging cycles.
• Binge Eating Disorder (BED): Involves recurrent binge eating episodes without the regular use of inappropriate compensatory purging behaviors.
• Restricting Type: A subtype of anorexia nervosa relying exclusively on fasting and dieting.', '["Anorexia Nervosa","Bulimia Nervosa","Binge Eating Disorder (BED)","Restricting Type"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:39:04.014Z"'::jsonb),
('card-1794233131148-44', NULL, 'deck-1794233131145-bql1k', 'How many lbs would a patient lose if he/she reduces food intake by 750 kcal per day?', '1.5 lbs', 'Since one pound of human adipose tissue represents approximately 3,500 kcal, reducing dietary intake by 750 kcal per day over 7 days yields a weekly deficit of 5,250 kcal (750 × 7). Dividing 5,250 kcal by 3,500 kcal per pound equals exactly 1.5 lbs of expected weight loss per week.', '["1 lb","2 lbs","1.5 lbs","3 lbs"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:39:25.454Z"'::jsonb),
('card-1794233131148-45', NULL, 'deck-1794233131145-bql1k', '_____ is the hormone responsible for stimulating appetite (hunger), while _____ is the hormone responsible for promoting satiety (fullness).', 'Ghrelin, Leptin', 'Ghrelin is a peptide hormone produced primarily in the stomach that stimulates appetite and signals hunger to the brain, whereas leptin is synthesized by adipose tissue to signal satiety and inhibit hunger.

• Leptin, Ghrelin: Reverses the physiological roles of the two hormones.
• Glucagon, Insulin: Pancreatic regulatory hormones governing blood glucose homeostasis rather than primary appetite signaling.
• Insulin, Glucagon: Incorrect pairing for hunger and satiety control.', '["Leptin, Ghrelin","Ghrelin, Leptin","Glucagon, Insulin","Insulin, Glucagon"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:39:32.082Z"'::jsonb),
('card-1794233131148-46', NULL, 'deck-1794233131145-bql1k', 'What type of fat or adipose tissue releases energy as heat through thermogenesis?', 'Brown fat', 'Brown adipose tissue (brown fat) is packed with iron-rich mitochondria expressing uncoupling protein 1 (UCP1), allowing it to dissipate chemical energy as heat through non-shivering thermogenesis.

• White fat: Primarily stores chemical energy in the form of triglycerides with minimal thermogenic activity.
• Yellow fat: Refers generally to standard mature white adipose tissue depots.', '["Brown fat","White fat","Yellow fat","None of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:39:40.090Z"'::jsonb),
('card-1794233131148-47', NULL, 'deck-1794233131145-bql1k', 'This refers to a physiologic response to an ingested food or food additive that does not involve the immune system', 'Food intolerance', 'Food intolerance refers to adverse physiological responses to ingested foods or food additives (such as lactose maldigestion) that are mediated by metabolic or enzymatic mechanisms without involving the immune system.

• Food hypersensitivity: A general umbrella term that often includes immune-mediated reactions.
• Food allergy: An immune-mediated adverse reaction triggered by specific IgE or cellular pathways.
• Food idiosyncrasy: An abnormal, unpredictable individual reaction to a food substance of unknown etiology.', '["Food hypersensitivity","Food intolerance","Food allergy","Food idiosyncracy"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:39:46.346Z"'::jsonb),
('card-1794233131148-48', NULL, 'deck-1794233131145-bql1k', 'This involves an eating plan that initially omits a food or group of foods believed to cause an adverse reaction, usually lasting for 4 to 12 weeks, and then reintroduces them during a “challenge” period.', 'Elimination diet', 'An elimination diet involves systematically removing specific suspected foods or food groups from the diet for a defined period (usually 4 to 12 weeks) until symptoms resolve, followed by structured reintroduction.

• Open food challenge: A diagnostic test where both clinician and patient know the identity of the food being tested during reintroduction.
• Single blind food challenge: A challenge where the clinician knows the food identity, but the patient does not.
• Double blind, placebo-controlled food challenge (DBPCFC): The gold standard diagnostic method where neither the patient nor the clinician knows whether the test food or placebo is administered.', '["Elimination diet","Open food challenge","Single blind food challenge","Double blind, placebo-controlled food challenge (DBPCFC)"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:39:52.216Z"'::jsonb),
('card-1794233131148-49', NULL, 'deck-1794233131145-bql1k', 'A food challenge in which the clinician is blinded to challenge the food’s identity, but the patient is not. The food or a powder of it is disguised in another food while reactions are observed and recorded.', 'None of the above', 'The scenario described in the prompt—where the clinician is blinded to the food identity while the patient is not—defines a single-blind food challenge, making "none of the above" the correct key since single-blind is not among options A, B, or C.

• Open food challenge: Incorrect because neither the clinician nor the patient is blinded.
• Single blind food challenge: The correct term for a challenge where only the clinician is blinded, making this option incorrect as an answer choice since it was omitted from the key.
• Double blind, placebo-controlled food challenge (DBPCFC): Incorrect because both the clinician and the patient are blinded.', '["Open food challenge","Single blind food challenge","Double blind, placebo-controlled food challenge (DBPCFC)","None of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:40:14.563Z"'::jsonb),
('card-1794233131148-50', NULL, 'deck-1794233131145-bql1k', 'A patient develops a severe allergic reaction, characterized by difficulty breathing, swelling of the lips, and hypotension, shortly after eating peanut butter. What condition is most likely occurring?', 'Anaphylaxis', 'Anaphylaxis is a severe, systemic, life-threatening allergic reaction triggered by exposure to an allergen (such as peanuts), characterized by rapid onset of respiratory compromise (difficulty breathing), airway edema (swelling of the lips and tongue), and vascular collapse (hypotension).

• Food intolerance: A non-immune-mediated adverse physiological response to food components, typically manifesting as digestive discomfort without systemic shock.
• Lactose intolerance: A localized digestive enzyme deficiency causing gastrointestinal bloating and diarrhea, not systemic anaphylaxis.
• GERD: Gastroesophageal reflux disease involves chronic acid reflux, unrelated to acute allergic shock.', '["Food intolerance","Anaphylaxis","Lactose intolerance","GERD"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:40:40.536Z"'::jsonb),
('card-1794233131149-51', NULL, 'deck-1794233131145-bql1k', 'All food items belong to the ‘Big Nine’, which are the 9 most common types of allergens, except:', 'Beef, Pork, Chicken', 'Beef, pork, and chicken are mammalian or avian meats and are not part of the recognized "Big Nine" primary food allergens.

• Milk, Soy, Sesame: Included in the legally recognized major food allergens.
• Egg, Wheat, Peanut: Major common food allergens.
• Tree nut, Fish, Shellfish: Major common food allergens.', '["Milk, Soy, Sesame","Egg, Wheat, Peanut","Tree nut, Fish, Shellfish","Beef, Pork, Chicken"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:40:47.255Z"'::jsonb),
('card-1794233131149-52', NULL, 'deck-1794233131145-bql1k', '1. Some bacteria in the small intestine are able to synthesize vitamin B12. 2. Despite this, it cannot be effectively used since absorption mainly takes place in the large intestine.', 'Both statements are incorrect', 'Both statements are false: while certain intestinal bacteria can synthesize vitamin B12, the human body cannot utilize it because microbial synthesis occurs in the large intestine (colon) below the terminal ileum where active B12 absorption takes place.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:40:54.113Z"'::jsonb),
('card-1794233131149-53', NULL, 'deck-1794233131145-bql1k', 'Foods to avoid for the nutrition management of gluten-sensitive enteropathy:', 'Wheat, oat, rye barley', 'Celiac disease or gluten-sensitive enteropathy requires the strict lifelong avoidance of grains containing toxic gluten proteins, specifically wheat, rye, barley, and contaminated or standard oats.

• Wheat, rice, oat, beer: Rice is gluten-free and safe for celiac patients.
• Wheat, sorghum, barley, malt: Sorghum is a safe, gluten-free ancient grain.
• Wheat, barley, malt, quinoa: Quinoa is a gluten-free pseudo-cereal.', '["Wheat, rice, oat, beer","Wheat, sorghum, barley, malt","Wheat, oat, rye barley","Wheat, barley, malt, quinoa"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:01.441Z"'::jsonb),
('card-1794233131149-54', NULL, 'deck-1794233131145-bql1k', 'The immediate goal of dietary management of acute diarrhea is', 'Prevent dehydration', 'The immediate, primary medical and nutritional goal in the management of acute diarrhea is fluid and electrolyte replacement to prevent life-threatening dehydration.

• Prevent nutrient deficiency: A secondary, long-term nutritional goal.
• Restore nutritional status: Addressed after acute fluid stabilization and resolution of the infection.
• Withhold food until bowel movement improves: Outdated practice; early oral rehydration and feeding are currently recommended.', '["Prevent nutrient deficiency","Restore nutritional status","Prevent dehydration","Withhold food until bowel movement improves"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:09.616Z"'::jsonb),
('card-1794233131149-55', NULL, 'deck-1794233131145-bql1k', 'The following food items are not recommended for a patient who recently underwent colostomy procedure except', 'Peeled apple', 'Peeled apples are soft, low-residue, and easily digestible, making them well-tolerated following a colostomy procedure.

• Carbonated drinks: Introduce excess gas and bloating, which are discouraged post-ostomy.
• Chewing gum: Swallows air, leading to increased gas accumulation and ostomy discomfort.
• Fried chicken: High in fat, which can cause rapid transit, greasy output, and digestive irritation post-surgery.', '["Carbonated drinks","Peeled apple","Chewing gum","Fried chicken"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:16.116Z"'::jsonb),
('card-1794233131149-56', NULL, 'deck-1794233131145-bql1k', 'It refers to the accumulation of fluids in the abdominal cavity', 'Ascites', 'Ascites is defined clinically as the pathological accumulation of serous fluid within the peritoneal (abdominal) cavity, commonly resulting from portal hypertension and hypoalbuminemia in liver disease.

• Esophageal varices: Dilated submucosal veins in the lower esophagus.
• Edema: Generalized swelling caused by fluid accumulation in interstitial tissue spaces throughout the body.
• Collateral formation: Development of alternative vascular pathways around blocked blood vessels.', '["Ascites","Esophageal varices","Edema","Collateral formation"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:21.615Z"'::jsonb),
('card-1794233131149-57', NULL, 'deck-1794233131145-bql1k', '1. Prebiotics, typically high fiber foods, act as food for human microflora. 2. Probiotic refers to foods that contain live microorganisms intended to improve the gut microbiome.', 'Both statements are correct', 'Both statements are true: prebiotics are non-digestible dietary fibers that serve as fermentable fuel for beneficial human microflora, and probiotics are live microbial food supplements that enhance or maintain the gut microbiome.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:27.839Z"'::jsonb),
('card-1794233131149-58', NULL, 'deck-1794233131145-bql1k', 'Which of the following dietary recommendations can help alleviate symptoms of gastroesophageal reflux disease (GERD)?', 'All of the above', 'All listed dietary strategies help alleviate GERD symptoms: avoiding irritants like spices and alcohol reduces gastric acid secretion, a low-fat diet prevents delayed gastric emptying and lower esophageal sphincter relaxation, and an adequate protein diet supports sphincter tone.', '["Avoid highly spiced foods and alcoholic beverages","Low fat diet","High protein diet","All of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:33.297Z"'::jsonb),
('card-1794233131149-59', NULL, 'deck-1794233131145-bql1k', 'Which of the following is the common cause/s of peptic ulcer?', 'H. pylori infection', 'Helicobacter pylori bacterial infection and the chronic use of non-steroidal anti-inflammatory drugs (NSAIDs) represent the two primary etiological causes of peptic ulcer disease.

• Salmonella enterica infection: Causes acute foodborne gastroenteritis, not chronic peptic ulcers.
• Long term use of non-steroidal pro-inflammatory drugs: NSAIDs are a major cause, but the prompt''s key highlights H. pylori as the predominant infectious driver. (Note: Option phrasing in test bank lists pro-inflammatory instead of anti-inflammatory, making H. pylori the definitive correct key).', '["H. pylori infection","Salmonella enterica infection","Long term use of non-steroidal pro-inflammatory drugs","None of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:42.604Z"'::jsonb),
('card-1794233131149-60', NULL, 'deck-1794233131145-bql1k', 'Hepatic coma is also called', 'Portal systemic encephalopathy', 'Hepatic coma, resulting from severe liver failure where neurotoxins like ammonia bypass hepatic clearance to affect the brain, is clinically termed portal-systemic encephalopathy (PSE).

• Portal hypertension: Elevated blood pressure within the portal venous system.
• Chronic pancreatitis: Long-standing inflammation of the pancreas.
• Obstructive cirrhosis: Biliary flow blockage leading to hepatic scarring.', '["Portal systemic encephalopathy","Portal hypertension","Chronic pancreatitis","Obstructive cirrhosis"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:48.404Z"'::jsonb),
('card-1794233131149-61', NULL, 'deck-1794233131145-bql1k', 'Dumping syndrome is often a complication of gastrectomy. What foods should be restricted on dumping syndrome?', 'Simple carbohydrates', 'Patients with dumping syndrome experience rapid gastric emptying; simple carbohydrates (refined sugars) draw fluid rapidly into the intestinal lumen via osmosis, triggering severe vasomotor and gastrointestinal symptoms, and must therefore be strictly restricted.

• Complex carbohydrates: Slow-digesting starches that are well-tolerated and encouraged in dumping syndrome.
• Unsaturated fat: Slows gastric emptying and helps meet energy needs without osmotic shifts.
• High biological value protein: Slows digestion and provides structural support without precipitating dumping symptoms.', '["Complex carbohydrates","Unsaturated fat","Simple carbohydrates","High biological value protein"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:41:54.531Z"'::jsonb),
('card-1794233131149-62', NULL, 'deck-1794233131145-bql1k', 'Pertains to the failure of lower esophageal sphincter (LES) to relax and become open during swallowing', 'Achalasia', 'Achalasia is a primary esophageal motility disorder characterized by the failure of the lower esophageal sphincter (LES) to relax during swallowing, accompanied by loss of esophageal peristalsis.

• Dysphagia: A general clinical symptom of difficulty in swallowing.
• GERD: Gastroesophageal reflux disease involves inappropriate relaxation or weakness of the LES.', '["Dysphagia","Achalasia","GERD","None of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:42:00.257Z"'::jsonb),
('card-1794233131149-63', NULL, 'deck-1794233131145-bql1k', 'What condition is characterized by inflammation, cracking, and fissuring of the lips and mouth corners?', 'Cheilosis or Angular Stomatitis', 'Cheilosis (or angular stomatitis) is characterized clinically by inflammatory lesions, cracking, maceration, and fissuring at the corners of the mouth, frequently associated with B-complex vitamin deficiencies (such as riboflavin).

• Glossitis: Inflammation and depapillation of the tongue.
• Gingivitis: Inflammation of the gingival gum tissues surrounding teeth.
• Periodontitis: Advanced destructive inflammatory disease of the supporting structures of the teeth.', '["Glossitis","Gingivitis","Periodontitis","Cheilosis or Angular Stomatitis"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:42:06.651Z"'::jsonb),
('card-1794233131149-64', NULL, 'deck-1794233131145-bql1k', 'Dietary for management of tonsillitis, except', 'Consume dry foods', 'Dry, rough, or scratchy foods irritate inflamed pharyngeal tissues and are explicitly contraindicated during tonsillitis, making "consume dry foods" the correct exception.

• Soft-textured foods: Recommended because they minimize mechanical swallowing pain.
• Avoid acidic and sticky foods: Recommended to prevent chemical irritation of inflamed throat tissues.
• Avoid thermally irritating foods: Recommended by avoiding very hot or spicy foods that aggravate lesions.', '["Soft-textured foods","Avoid acidic and sticky foods","Consume dry foods","Avoid thermally irritating foods"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:42:11.870Z"'::jsonb),
('card-1794233131149-65', NULL, 'deck-1794233131145-bql1k', 'Refers to the protrusion of a part of the stomach into the chest, so food is prevented from passing along normally in the GIT, leading to GERD', 'Hiatal hernia', 'A hiatal hernia occurs when the upper portion of the stomach protrudes upward through the diaphragmatic hiatus into the chest cavity, disrupting the anatomical barrier and predisposing the patient to GERD.

• Dyspepsia: Indigestion or general upper abdominal discomfort.
• Peptic ulcer disease: Erosive mucosal lesions in the stomach or duodenum.
• Gastritis: Inflammation of the gastric mucosal lining.', '["Dyspepsia","Hiatal hernia","Peptic ulcer disease","Gastritis"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:42:17.781Z"'::jsonb),
('card-1794233131149-66', NULL, 'deck-1794233131145-bql1k', 'Pertains to the presence of inflamed sacs or pouches that develop in weakened areas of the colon.', 'Diverticulitis', 'Diverticulitis refers specifically to the inflammation and micro-perforation of small pouches (diverticula) that develop within weakened muscular areas of the colon wall.

• Diverticula: The structural outpouchings themselves.
• Diverticulosis: The presence of asymptomatic diverticular pouches in the colon without active acute inflammation.', '["Diverticula","Diverticulosis","Diverticulitis","All of the above"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:42:23.470Z"'::jsonb),
('card-1794233131149-67', NULL, 'deck-1794233131145-bql1k', 'Low fiber is prescribed among these disease conditions to prevent irritation of the organs involved, except', 'Constipation', 'Constipation requires a high-fiber and high-fluid diet to add bulk and stimulate peristalsis, making it the correct exception where low-fiber diets are not prescribed.

• Crohn’s disease: Treated with low-fiber diets during acute inflammatory flares to reduce bowel friction.
• Ulcerative colitis: Requires low-fiber/low-residue nutrition during acute flare-ups to rest the colon.
• Cirrhosis of the liver: Often managed with low-fiber/soft diets if esophageal varices are present to prevent mechanical trauma.', '["Constipation","Crohn’s disease","Ulcerative colitis","Cirrhosis of the liver"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:42:45.948Z"'::jsonb),
('card-1794233131149-68', NULL, 'deck-1794233131145-bql1k', 'Why is low fat prescribed in patients with jaundice?', 'To provide rest to the liver', 'A fat-restricted diet is prescribed during acute hepatitis and jaundice to minimize digestive work, reduce bile secretion demands, and provide physiological rest to the impaired liver parenchyma.

• To increase bile production: Low fat intake actually reduces the chemical stimulus for bile release.
• To enhance protein absorption: Fat restriction does not directly govern protein uptake mechanisms.
• To stimulate liver enzyme secretion: Fat restriction minimizes hepatic metabolic burden rather than over-stimulating enzymatic output.', '["To increase bile production","To provide rest to the liver","To enhance protein absorption","To stimulate liver enzyme secretion"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:42:52.088Z"'::jsonb),
('card-1794233131149-69', NULL, 'deck-1794233131145-bql1k', '1. Diarrhea requires a high fiber diet 2. Atonic constipation requires a high fiber diet while spastic constipation requires a low fiber diet', 'Only statement 2 is correct', 'Statement 1 is false because acute diarrhea requires a low-residue, low-fiber diet to reduce stool frequency; 

Statement 2 is true because atonic constipation requires high-fiber intake to stimulate muscle tone, whereas spastic constipation requires a soothing, lower-residue or graduated fiber diet to prevent painful bowel spasms.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:43:00.211Z"'::jsonb),
('card-1794233131149-70', NULL, 'deck-1794233131145-bql1k', 'Enteral formula that contains a single macronutrient designed to meet specific nutritional requirements in certain disease conditions', 'Modular', 'Modular enteral formulas consist of single macronutrient preparations (such as isolated protein powders, glucose polymers, or MCT oil) that can be combined flexibly to meet specialized disease-specific requirements.

• Polymeric: Complete formulas containing intact macronutrients for patients with normal digestion.
• Elemental: Monomeric formulas containing pre-digested amino acids and simple sugars for severe malabsorption.
• Disease-specific: Specialized formulas tailored for specific metabolic pathologies (e.g., renal or hepatic failure).', '["Polymeric","Elemental","Modular","Disease-specific"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:43:07.420Z"'::jsonb),
('card-1794233131149-71', NULL, 'deck-1794233131145-bql1k', 'Which feeding route is most appropriate for a patient with no stomach impairments who needs long-term reliance on EN?', 'Gastrostomy', 'When the stomach is fully functional and long-term enteral nutrition is required (exceeding 4 to 6 weeks), a surgical or percutaneous endoscopic gastrostomy (PEG) tube is the most appropriate and comfortable feeding route.

• Nasogastric: Restricted to short-term feeding due to nasal mucosa irritation and aspiration risks.
• Nasojejunal: Used for short-term post-pyloric feeding when gastric emptying is impaired.
• Jejunostomy: Bypasses the stomach entirely, typically reserved for severe gastric motility disorders or structural impairments.', '["Nasogastric","Nasojejunal","Gastrostomy","Jejunostomy"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:43:13.303Z"'::jsonb),
('card-1794233131149-72', NULL, 'deck-1794233131145-bql1k', '1. Commercial formula offers lower risk of bacterial contamination 2. Blenderized tube feeding (BTF) provides consistent caloric delivery', 'Only statement 1 is correct', 'Statement 1 is true because commercially manufactured sterile liquid formulas carry a much lower risk of bacterial contamination compared to blenderized feeds; 

Statement 2 is false because blenderized tube feedings (BTF) often exhibit clogging, viscosity variations, and inconsistent nutrient or caloric delivery across batches.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["General Dietetics","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.145Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.145Z"'::jsonb, '"2026-11-09T14:43:20.379Z"'::jsonb)
