INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-1794233131314-3', NULL, 'deck-1794233131314-dz5ov', 'Which of the following grain parts contain the most starch?', 'Endosperm', 'The endosperm makes up the bulk of cereal grains (roughly 83% of kernel weight) and is packed primarily with starch granules embedded in a protein matrix. The bran and germ contain mostly fiber, vitamins, minerals, and oils.', '["Bran","Hull","Endosperm","Germ"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:21:30.782Z"'::jsonb),
('card-1794233131314-30', NULL, 'deck-1794233131314-dz5ov', 'In this type of quick bread, steam is generated very rapidly in the fluid batter as it is heated in a very hot oven.', 'Popover', 'Popovers are quick breads characterized by high moisture batter placed in a searing hot oven, where water flashes into steam and rapidly expands hollow cavities inside a sturdy egg-protein structure.', '["Cookies","Popover","Muffin","Nut bread"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:07.599Z"'::jsonb),
('card-1794233131314-31', NULL, 'deck-1794233131314-dz5ov', 'The following are functions of fat in breadmaking EXCEPT:', 'Promotes gluten development', 'Fat inhibits and shortens gluten development by coating flour particles and repelling water, making this statement the correct exception to fat''s functions in baking.', '["Stabilization of the walls surrounding gas bubbles","Slow down the staling process","Tenderizes the bread","Promotes gluten development"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:12.271Z"'::jsonb),
('card-1794233131314-32', NULL, 'deck-1794233131314-dz5ov', 'This is the lowest temperature wherein small flames of fire begin to ignite briefly in the oil.', 'Flash point', 'The flash point is the lowest temperature at which vaporized oil from a heated fat source forms an ignitable mixture in air that flashes briefly when a small flame is introduced.', '["Smoke point","Flash point","Fire point","Boiling point"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:16.523Z"'::jsonb),
('card-1794233131314-33', NULL, 'deck-1794233131314-dz5ov', 'Which of the following is TRUE?', 'Oxidative rancidity happens when unsaturated fatty acids undergo a free radical chain reaction in the presence of oxygen, producing small volatile compounds.', 'Oxidative rancidity is an autocatalytic free-radical reaction involving oxygen attack on unsaturated double bonds. Statement B is false because lipases catalyze hydrolytic rancidity, not oxidative rancidity.', '["Oxidative rancidity happens when unsaturated fatty acids undergo a free radical chain reaction in the presence of oxygen, producing small volatile compounds.","The main enzymes that catalyze the reaction that leads to oxidative rancidity are lipases.","Both A and B are true","Both A and B are false"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:22.017Z"'::jsonb),
('card-1794233131314-34', NULL, 'deck-1794233131314-dz5ov', 'In general, lipid oxidation may be reduced by the following EXCEPT:', 'Increasing the temperature', 'Elevating the temperature accelerates chemical reaction rates and free-radical formation, thereby increasing (not reducing) lipid oxidation. Low temperatures, antioxidants (BHA), vacuum packaging, and low water activity reduce oxidation.', '["Use of BHA","Increasing the temperature","Use of vacuum packaging","Lowering the water activity until around 0.3"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:26.405Z"'::jsonb),
('card-1794233131314-35', NULL, 'deck-1794233131314-dz5ov', 'What is the PRIMARY browning reaction when ham is cooked in an oven?', 'Maillard browning', 'Cooking cured ham exposes meat proteins (amino acids) and reducing sugars to heat, driving the non-enzymatic Maillard browning reaction to produce a savory crust and rich brown color.', '["Enzymatic browning","Ascorbic acid browning","Caramelization","Maillard browning"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:30.584Z"'::jsonb),
('card-1794233131314-36', NULL, 'deck-1794233131314-dz5ov', 'The following additives can be used to reduce browning in apple slices except:', 'Carrageenan', 'Carrageenan is a seaweed-derived hydrocolloid thickener/gelling agent with no anti-browning properties. Sodium metabisulfite, citric acid, and ascorbic acid are all active anti-browning agents used to prevent oxidation in cut fruit.', '["Sodium metabisulfite","Citric acid","Ascorbic acid","Carrageenan"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:36.176Z"'::jsonb),
('card-1794233131314-37', NULL, 'deck-1794233131314-dz5ov', 'Which of the following is TRUE?', 'Caramelization is a non-enzymatic reaction', 'Caramelization is strictly a non-enzymatic thermal pyrolytic breakdown of sugars. Statement A is false because caramelization requires higher temperatures than Maillard browning reactions.', '["The required temperature to induce caramelization is less than the temperature required for Maillard browning","Caramelization is a non-enzymatic reaction","Both A and B are true","Both A and B are false"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:40.532Z"'::jsonb),
('card-1794233131314-38', NULL, 'deck-1794233131314-dz5ov', 'The following correctly describes a crystalline candy EXCEPT:', 'They have a higher sugar content than amorphous candies', 'Crystalline candies (like fondant) do not have higher sugar content than amorphous candies (like hard caramels or brittles); in fact, hard amorphous candies are cooked to much higher temperatures and possess extremely high sugar concentrations with no organized crystal structure.', '["It is best formed by slowly cooling the sugar solution to approximately 38-40°C before stirring or  beating","They have organized crystals of sugar throughout","They are cooked at lower temperatures than amorphous candies","They have a higher sugar content than amorphous candies"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:45.477Z"'::jsonb),
('card-1794233131314-39', NULL, 'deck-1794233131314-dz5ov', 'The following are amorphous candies EXCEPT:', 'Fondant', 'Fondant is a classic crystalline candy containing micro-fine, organized sugar crystals suspended in a saturated syrup. Caramels, taffy, and peanut brittle are amorphous (non-crystalline) glassy candies.', '["Caramel","Taffy","Peanut brittle","Fondant"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:50.182Z"'::jsonb),
('card-1794233131314-4', NULL, 'deck-1794233131314-dz5ov', 'This unique type of corn endosperm is made by soaking corn kernels in lye to remove their bran and germ.', 'Hominy', 'Hominy is produced by treating field corn kernels with an alkali solution (such as lye or wood ash water—a process called nixtamalization) to loosen the hull and germ while softening the kernel.

• Farina: Milled wheat endosperm (hot cereal).
• Bulgur: Parboiled, cracked wheat.
• Couscous: Steamed, crushed semolina wheat granules.', '["Farina","Hominy","Bulgur","Couscous"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:21:50.859Z"'::jsonb),
('card-1794233131314-40', NULL, 'deck-1794233131314-dz5ov', 'How does cream of tartar and other acidic ingredients interfere with sugar crystal formation and aggregation?', 'By promoting the inversion of sucrose to give a mixture of sugars', 'Acids hydrolyze sucrose into invert sugar (glucose and fructose). These monosaccharides interfere with sucrose crystal alignment, preventing large sugar crystals from forming and keeping crystalline confections smooth.', '["By increasing the viscosity of the sugar mixture","By coating the sugar crystals preventing them from aggregating","By promoting the inversion of sucrose to give a mixture of sugars","By rapidly evaporating all the water from the sugar mixture, leaving no medium for crystal growth."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:24:54.807Z"'::jsonb),
('card-1794233131314-41', NULL, 'deck-1794233131314-dz5ov', 'Which of the following correctly describes low-methoxyl pectins?', 'It can form gels in the presence of divalent ions', 'Low-methoxyl (LM) pectins possess fewer esterified carboxyl groups and cross-link via ionic bonding with divalent calcium ions (Ca²⁺) to form gels independently of high sugar concentrations.', '["It can form gels in the presence of divalent ions","It needs sugar and acid to form a gel","It contains a high proportion (usually 50-58%) of esterified carboxyl groups","It is a high-molecular weight methylated galacturonic acid polymer found in immature fruits."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:11.236Z"'::jsonb),
('card-1794233131314-42', NULL, 'deck-1794233131314-dz5ov', 'In jelly making, which of the following can happen when the boiling time is too long?', 'Depolymerization of pectin', 'Prolonged boiling breaks down long pectin polymer chains into smaller fragments via acid hydrolysis (depolymerization), destroying their ability to form a stable gel network.', '["Crystallization of sucrose","Depolymerization of pectin","Insufficient production of invert sugar","Reduction of boiling point"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:16.079Z"'::jsonb),
('card-1794233131314-43', NULL, 'deck-1794233131314-dz5ov', 'The following are examples of microbial exudate gums EXCEPT:', 'Gum Arabic', 'Gum Arabic is a natural tree exudate gum (from Acacia species), whereas Xanthan gum, Dextran, and Gellan gum are produced via microbial fermentation (microbial exudates).', '["Xanthan gum","Dextran","Gum Arabic","Gellan gum"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:19.759Z"'::jsonb),
('card-1794233131314-44', NULL, 'deck-1794233131314-dz5ov', 'This seaweed polysaccharide contains mainly D- mannuronic acid and L-guluronic acid. They form gels in the presence of calcium ions and are obtained from brown seaweeds.', 'Alginate', 'Alginates are polysaccharide polymers extracted from brown seaweeds composed of mannuronic and guluronic acid blocks that form thermal-irreversible gels in the presence of calcium ions.', '["Alginate","Agar","Carrageenan","Carboxymethyl cellulose"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:24.698Z"'::jsonb),
('card-1794233131314-45', NULL, 'deck-1794233131314-dz5ov', 'This is a thickened spread containing small, whole fruit or uniform-size pieces in a clear, slightly gelled syrup.', 'Preserve', 'A preserve contains small, whole fruits or uniform pieces suspended in a clear, tenderly gelled syrup base. Jams are crushed fruit pulps, jellies are strained fruit juices, and marmalades contain suspended citrus peel.', '["Jelly","Jam","Preserve","Marmalade"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:28.896Z"'::jsonb),
('card-1794233131314-46', NULL, 'deck-1794233131314-dz5ov', 'The main purpose of blanching is to:', 'Inactivate enzymes', 'The primary commercial and culinary purpose of blanching produce is to thermally inactivate degradative plant enzymes (such as lipoxygenase and peroxidase) that cause off-flavors and nutrient loss.', '["Reduce microbial load","Induce volume changes","Modify starches","Inactivate enzymes"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:33.311Z"'::jsonb),
('card-1794233131314-47', NULL, 'deck-1794233131314-dz5ov', 'This gray-green or olive-green form of chlorophyll is produced when hydrogen ions displace the central magnesium atom in chlorophyll molecules during the heating of vegetables.', 'Pheophytin', 'When green vegetables are heated, plant acids displace the central magnesium ion of chlorophyll, converting it into olive-brown pheophytin.', '["Pheophytin","Chlorophyllin","Pheophorbide","Chlorophyllide"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:38.892Z"'::jsonb),
('card-1794233131314-48', NULL, 'deck-1794233131314-dz5ov', 'Which of the following happens when a base such as sodium bicarbonate is added to chlorophyll-rich vegetables?', 'All of the above', 'Adding alkaline baking soda (base) to green vegetables preserves bright green chlorophyll (via chlorophyllin formation), but the harsh alkalinity simultaneously destroys vitamin C (ascorbic acid) and breaks down plant cell-wall hemicellulose, leading to a mushy texture (all of the above).', '["Production and maintenance of bright green color","Destruction of ascorbic acid","Loss of texture","All of the above"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:44.491Z"'::jsonb),
('card-1794233131314-49', NULL, 'deck-1794233131314-dz5ov', 'This carotenoid class is made up of only hydrocarbons.', 'Carotenes', 'Carotenes are pure hydrocarbon carotenoid pigments containing only carbon and hydrogen atoms (e.g., beta-carotene). Xanthophylls contain oxygen atoms, while tannins and betacyanins belong to completely different chemical families.', '["Tannins","Betacyanins","Carotenes","Xanthophylls"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:25:54.578Z"'::jsonb),
('card-1794233131314-5', NULL, 'deck-1794233131314-dz5ov', 'Which of the following has the highest protein content?', 'Bread flour', 'Bread flour is milled from hard spring wheat and contains the highest protein content (roughly 12–14%) to develop a strong gluten network. Pastry, cake, and all-purpose flours have progressively lower protein concentrations.', '["Cake flour","All-purpose flour","Bread flour","Pastry flour"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:21:56.022Z"'::jsonb),
('card-1794233131314-50', NULL, 'deck-1794233131314-dz5ov', 'These carotenoids can be found in green leaves.', 'Lutein', 'Lutein is a yellow xanthophyll carotenoid found abundantly alongside green chlorophyll pigments in green leafy vegetables (such as spinach and kale).

Chlorophyll is a porphyrin pigment, not a carotenoid. Cryptoxanthin and alpha-carotene are other carotenoid classes found in fruits and yellow-orange vegetables.', '["Chlorophyll","Lutein","Cryptoxanthin","Alpha-carotene"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:05.756Z"'::jsonb),
('card-1794233131314-51', NULL, 'deck-1794233131314-dz5ov', 'Which of the following results in a lighter color of the carotenoid-rich vegetables?', 'Conversion of the trans form of the carotenoid to the cis form', 'Carotenoids naturally exist primarily in the stable, deeply colored trans configuration. When exposed to heat, light, or acid, they isomerize into the cis form, which alters their light absorption and results in a visibly lighter, faded color.', '["Caramelization of the plant sugar","Conversion of the trans form of the carotenoid to the cis form","Exposure to an alkali environment","All of the above"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:09.975Z"'::jsonb),
('card-1794233131314-52', NULL, 'deck-1794233131314-dz5ov', 'These are water-soluble nitrogen-containing pigments that occur exclusively in families of the order Caryophyllales.', 'Betalaines', 'Betalaines are water-soluble nitrogen-containing pigments found exclusively in plant orders belonging to the Caryophyllales (such as beets and amaranth).

Anthocyanins and flavonoids are non-nitrogenous phenolic pigments; porphyrins include chlorophyll and heme compounds.', '["Betalaines","Porphyrins","Anthocyanins","Flavonoids"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:14.895Z"'::jsonb),
('card-1794233131314-53', NULL, 'deck-1794233131314-dz5ov', 'This is a bitter glycoalkaloid that can be toxic at high levels. It is formed when some plants, such as potatoes and onions, are exposed to sunlight, artificial light or fluorescent light.', 'Solanine', 'Solanine is a bitter, toxic glycoalkaloid synthesized by nightshade family plants (like potatoes and onions) when exposed to light, functioning as a natural defense mechanism against pests.', '["Oxalic acid","Solanine","Allicin","Saponins"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:19.125Z"'::jsonb),
('card-1794233131314-54', NULL, 'deck-1794233131314-dz5ov', 'This antinutritive factor is a naturally occurring compound found primarily in seeds, nuts and grains, where it functions as a store of mineral nutrients and inositol to be used during germination. As a negatively charged molecule, it is known to inhibit the absorption of positively charged minerals, most notably zinc.', 'Phytic acid', 'Phytic acid (inositol hexakisphosphate) acts as a mineral storage compound in seeds and grains. Because it carries strong negative charges, it chelates and binds divalent cations (iron, zinc, calcium), inhibiting their intestinal absorption.', '["Saponins","Tannins","Phytic acid","Trypsin Inhibitors"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:24.911Z"'::jsonb),
('card-1794233131314-55', NULL, 'deck-1794233131314-dz5ov', 'The following can reduce the antinutritive factors in a food product EXCEPT:', 'Freezing', 'Freezing preserves food by halting microbial growth and slowing enzymatic activity, but it does not degrade or reduce antinutritive factors like phytates or tannins. Methods like soaking, fermentation, and milling activate endogenous enzymes (phytases) or physically remove hulls to reduce antinutrients.', '["Fermentation","Soaking","Freezing","Milling"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:29.043Z"'::jsonb),
('card-1794233131314-56', NULL, 'deck-1794233131314-dz5ov', 'The strong fishy smell of old fish is due to:', 'Conversion of trimethylamine oxide (TMAO) to trimethylamine (TMA)', 'The distinct pungent, stale "fishy" odor of spoiling marine fish is caused by bacterial and enzymatic reduction of odorless trimethylamine oxide (TMAO) into volatile, foul-smelling trimethylamine (TMA).', '["Conversion of trimethylamine oxide (TMAO) to trimethylamine (TMA)","Production of excess amounts of histamine","Conversion of urea to ammonia","Denaturation of proteins"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:34.029Z"'::jsonb),
('card-1794233131314-57', NULL, 'deck-1794233131314-dz5ov', 'What is the function of resting meat after cooking?', 'To redistribute water expelled during cooking back into the fibers', 'As meat cooks, muscle proteins coagulate and squeeze moisture outward. Allowing cooked meat to rest lets the muscle fibers relax and capillary pressure draw the moisture back inward, preventing juice loss upon slicing.', '["To seal in the flavor of the meat prior to cutting","To redistribute water expelled during cooking back into the fibers","To decrease the toughness of the meat","To denature proteins for flavor development"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:38.710Z"'::jsonb),
('card-1794233131314-58', NULL, 'deck-1794233131314-dz5ov', 'This is the compound formed when myoglobin is exposed excessively to oxygen and the iron converts to the ferric state, causing the meat to become brownish-red.', 'Metmyoglobin', 'When fresh meat myoglobin (Fe²⁺) is exposed to oxygen over time or low oxygen partial pressures, it oxidizes into the ferric (Fe³⁺) state, forming metmyoglobin, which exhibits an unappealing brownish-red color.', '["Oxymyoglobin","Metmyoglobin","Myoglobin","Nitric oxide myoglobin"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:53.607Z"'::jsonb),
('card-1794233131314-59', NULL, 'deck-1794233131314-dz5ov', 'The following are functions of salt in sausage making EXCEPT:', 'Acts as a leavening agent', 'Salt enhances flavor, extracts myofibrillar proteins for binding in sausage emulsions, and inhibits microbial growth. It does not act as a leavening agent (which releases gas to make dough rise).', '["Enhances flavor","Aids in protein extraction for binding","Inhibits microbial growth","Acts as a leavening agent"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:27:59.172Z"'::jsonb),
('card-1794233131314-6', NULL, 'deck-1794233131314-dz5ov', 'The following are hard cheeses EXCEPT:', 'Camembert', 'Camembert is a soft, surface-ripened cheese characterized by a white, edible bloomy rind. Parmesan, Romano, and Provolone are hard or semi-hard aged cheeses with low moisture contents.', '["Parmesan","Provolone","Romano","Camembert"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:21:59.691Z"'::jsonb),
('card-1794233131314-60', NULL, 'deck-1794233131314-dz5ov', 'This phenomenon is caused by moisture loss from the surface of the frozen food due to sublimation as the food is exposed to dry, cold air. This causes discoloration in the surfaces of meat and poultry products and volume changes in vegetables.', 'Freezer burn', 'Freezer burn occurs when moisture from the surface of frozen food sublimes (turns directly from ice to vapor) into dry storage air, leaving dehydrated, spongy, discolored patches.', '["Chilling injury","Case hardening","Freezer burn","Cold shortening"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:03.176Z"'::jsonb),
('card-1794233131314-61', NULL, 'deck-1794233131314-dz5ov', 'Which of the following cold preservation methods produce smaller ice crystals?', 'Rapid freezing', 'Rapid freezing creates massive nucleation sites that simultaneously freeze water into numerous, extremely small ice crystals, preserving food cellular structure better than slow freezing (which forms large, destructive ice crystals).', '["Slow freezing","Repeated freeze-thaw","Lower temperature gradient between food and freezing air","Rapid freezing"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:07.394Z"'::jsonb),
('card-1794233131314-62', NULL, 'deck-1794233131314-dz5ov', 'In the preparation of ice cream, the increase in volume due to air is called the:', 'Overrun', 'Overrun is the volumetric increase in ice cream resulting from the incorporation of air during the freezing and churning process.', '["Pasteurization","Overrun","Emulsification","Gelation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:11.943Z"'::jsonb),
('card-1794233131314-63', NULL, 'deck-1794233131314-dz5ov', 'Using heavy cream instead of low-fat cream will result in:', 'Higher volume whipped cream', 'Heavy cream contains a higher percentage of milk fat (36%+) compared to lower-fat creams; these fat globules form a denser, more stable structural network that traps air efficiently, resulting in higher whipped volume and stability.', '["Thinner whipped cream","Higher volume whipped cream","Both A and B","None of the above"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:17.095Z"'::jsonb),
('card-1794233131314-64', NULL, 'deck-1794233131314-dz5ov', 'The following improves the stability of emulsions EXCEPT:', 'Adding salts to the emulsion', 'Adding high concentrations of ionic salts to an emulsion destabilizes it by screening electrostatic charges and causing droplet aggregation. Increasing continuous phase viscosity, adding gums, and reducing droplet size all improve emulsion stability.', '["Increasing the viscosity if the continuous phase","Adding gums to the emulsion","Reducing the droplet size of the dispersed phase","Adding salts to the emulsion"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:22.084Z"'::jsonb),
('card-1794233131314-65', NULL, 'deck-1794233131314-dz5ov', 'This emulsion instability is characterized by the rising of the dispersed phase at the top of the emulsion.', 'Creaming', 'Creaming is an emulsion instability where lower-density dispersed phase droplets rise and concentrate at the top of the emulsion (like cream separating on unhomogenized milk).', '["Ostwald ripening","Creaming","Coalescence","Flocculation"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:26.097Z"'::jsonb),
('card-1794233131314-66', NULL, 'deck-1794233131314-dz5ov', 'Which of the following techniques is best used for enhancing flavors in low-sodium recipe modifications?', 'Adding fresh herbs and citrus juices', 'Fresh herbs, aromatic spices, and acidic citrus juices brighten food flavor profiles and stimulate taste receptors on the tongue, compensating effectively for reduced sodium levels in modified recipes.', '["Applying salted dry rubs and brines","Adding fresh herbs and citrus juices","Replacement of water with milk","Adding quick-melt cheese"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:30.228Z"'::jsonb),
('card-1794233131314-67', NULL, 'deck-1794233131314-dz5ov', 'To reduce the total fat content of a hot, creamy, mushroom sauce while maintaining mouthfeel and stability, which ingredient is the most effective replacement for light cream?', 'Evaporated milk', 'Evaporated milk has had a large portion of its water content removed via thermal evaporation, concentrating its milk solids and proteins to provide rich viscosity and creamy mouthfeel as a lower-fat alternative to heavy or light cream.', '["Evaporated milk","Nonfat yogurt","Buttermilk","Sour cream"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:34.725Z"'::jsonb),
('card-1794233131314-68', NULL, 'deck-1794233131314-dz5ov', 'This Gram-positive bacterium is non-sporulating, non-motile, catalase-positive, and coagulase-positive, and can grow in environments with low water activity (around 0.85).', 'Staphylococcus aureus', 'Staphylococcus aureus is a Gram-positive, catalase-positive, coagulase-positive bacterium that tolerates lower water activities (down to ~0.85) and salt concentrations, frequently contaminating food via human handling.', '["Clostridium botulinum","Staphylococcus aureus","Salmonella enterica","Escherichia coli"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:42.036Z"'::jsonb),
('card-1794233131314-69', NULL, 'deck-1794233131314-dz5ov', 'This Gram-positive rod-shaped bacterium is known to survive and grow in chilled temperatures, making it a reasonable concern for ready-to-eat refrigerated food.', 'Listeria monocytogenes', 'Listeria monocytogenes is a psychrotrophic, Gram-positive rod capable of surviving and multiplying slowly at refrigerated temperatures, making it a critical pathogen in ready-to-eat cold foods.', '["Vibrio parahaemolyticus","Listeria monocytogenes","Salmonella enterica","Bacillus cereus"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:46.960Z"'::jsonb),
('card-1794233131314-7', NULL, 'deck-1794233131314-dz5ov', 'This sweetener is produced by enzymatically converting some of the glucose derived from cornstarch into fructose using the enzyme glucose isomerase.', 'High fructose corn syrup', 'High fructose corn syrup (HFCS) is manufactured by treating cornstarch with alpha-amylase and glucoamylase to yield glucose, followed by treating it with glucose isomerase to enzymatically convert a portion of the glucose into sweeter fructose.', '["Corn syrup","Molasses","High fructose corn syrup","Invert sugar"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:22:05.337Z"'::jsonb),
('card-1794233131314-70', NULL, 'deck-1794233131314-dz5ov', 'This is a parasitic roundworm associated with eating undercooked pork.', 'Trichinella spiralis', 'Trichinella spiralis is a parasitic nematode roundworm transmitted through the ingestion of encysted larvae in undercooked pork or game meats.', '["Trichinella spiralis","Taenia saginata","Plasmodium falciparum","Giardia duodenalis"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:28:52.463Z"'::jsonb),
('card-1794233131314-71', NULL, 'deck-1794233131314-dz5ov', 'In curing meat, nitrites are added primarily to control the growth of:', 'Clostridium botulinum', 'Nitrites (NO₂⁻) are added during meat curing primarily to inhibit the germination and outgrowth of lethal Clostridium botulinum spores.', '["Campylobacter jejuni","Clostridium botulinum","Clostridium perfringens","Staphylococcus aureus"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:05.847Z"'::jsonb),
('card-1794233131314-72', NULL, 'deck-1794233131314-dz5ov', 'A pink, green or iridescent white egg albumin indicates spoilage due to:', 'Pseudomonas sp.', 'Certain psychrotrophic Pseudomonas species produce water-soluble fluorescent pigments (pyoverdine) that impart a characteristic pink, green, or iridescent discoloration to egg whites during spoilage.', '["Yersenia sp.","Pseudomonas sp.","Bacillus sp.","Salmonella sp."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:12.534Z"'::jsonb),
('card-1794233131314-73', NULL, 'deck-1794233131314-dz5ov', 'Which of the following is the MOST suitable preservation technique for orange juice?', 'Pasteurization', 'Pasteurization is the ideal thermal preservation technique for liquid fruit juices like orange juice, destroying vegetative pathogens and spoilage enzymes while protecting delicate flavor profiles better than harsh commercial sterilization.', '["Pasteurization","Retort Sterilization","Fermentation","Boiling"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:16.236Z"'::jsonb),
('card-1794233131314-74', NULL, 'deck-1794233131314-dz5ov', 'Which of the following correctly describes commercial sterility?', 'The absence of microorganisms capable of growing in the food at normal nonrefrigerated conditions', 'Commercial sterility (achieved in canned goods) means all pathogenic and spoilage microorganisms capable of replicating under normal non-refrigerated shelf storage conditions have been destroyed, though heat-resistant bacterial spores may remain dormant.', '["The absence of all microorganisms in the food","The absence of microorganisms capable of growing in the food at normal nonrefrigerated conditions","The absence of pathogenic microorganisms in food, but not necessarily the spoilage microorganisms","The absence of microorganisms capable of growing in the food at refrigerated conditions"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:22.265Z"'::jsonb)
