INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-1794233131314-75', NULL, 'deck-1794233131314-dz5ov', 'This E. coli type produces a toxin that damages the lining of the intestinal wall causing bloody diarrhea.', 'Enterohemorrhagic E. coli', 'Enterohemorrhagic E. coli (EHEC, such as strain O157:H7) produces potent Shiga toxins that damage intestinal microvascular endothelial linings, resulting in severe hemorrhagic colitis (bloody diarrhea).', '["Enteropathogenic E. coli","Enterohemorrhagic E. coli","Enteroinvasive E. coli","Enterotoxigenic E. coli"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:28.089Z"'::jsonb),
('card-1794233131314-76', NULL, 'deck-1794233131314-dz5ov', 'Which of the following BEST prevents scombroid poisoning?', 'Keeping the temperature of fish and shellfish below 4°C from harvest through storage', 'Scombroid poisoning is caused by histamine accumulation when marine fish (like tuna or mackerel) are exposed to warm temperatures that allow bacterial histidine decarboxylase to convert histidine into histamine. Strict cold storage below 4°C prevents this bacterial conversion.', '["Cooking fish and shellfish to an internal temperature of 62.8°C","Keeping the temperature of fish and shellfish below 4°C from harvest through storage","Removing the fish scales and innards before storage","Washing the fish thoroughly with vinegar or lemon juice to eliminate surface bacteria"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:35.393Z"'::jsonb),
('card-1794233131314-77', NULL, 'deck-1794233131314-dz5ov', 'Which of the following is FALSE regarding emetic Bacillus cereus poisoning?', 'It is primarily caused by the proliferation of Bacillus cereus in the stomach.', 'This statement is false (hence the correct answer to the "is FALSE" prompt). Emetic Bacillus cereus food poisoning is caused by ingesting a pre-formed heat-stable toxin already present in contaminated food (such as leftover fried rice), rather than active bacterial proliferation occurring inside the stomach.', '["It is primarily caused by the proliferation of Bacillus cereus in the stomach.","Its symptoms appear faster than diarrheal Bacillus cereus poisoning.","It is commonly associated with leftover rice","Its primary symptom is nausea and vomiting"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:55.096Z"'::jsonb),
('card-1794233131314-78', NULL, 'deck-1794233131314-dz5ov', 'Which of the following is MOST associated with aflatoxins?', 'Nuts and Grains', 'Aflatoxins are potent mycotoxins produced by Aspergillus molds that contaminate field crops, particularly oilseeds, tree nuts, corn, and stored grains under warm, humid conditions.', '["Poultry","Undercooked pork","Nuts and Grains","Fish and Shellfish"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:29:59.588Z"'::jsonb),
('card-1794233131314-79', NULL, 'deck-1794233131314-dz5ov', 'According to USDA, poultry is considered safe to eat when its internal temperature reaches:', '165 °F', 'According to USDA food safety guidelines, all poultry (whole birds, breasts, thighs, ground poultry) must reach a safe minimum internal temperature of 165°F (74°C).', '["145 °F","170 °F","160 °F","165 °F"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:03.765Z"'::jsonb),
('card-1794233131314-8', NULL, 'deck-1794233131314-dz5ov', 'This non-nutritive sweetener is a dipeptide composed of two amino acids, aspartic acid and phenylalanine. It loses its sweetness when heated.', 'Aspartame', 'Aspartame is a nutritive dipeptide sweetener composed of aspartic acid and phenylalanine. When exposed to prolonged high heat during cooking or baking, the peptide bond breaks down, causing it to lose its sweetening power.', '["Saccharin","Aspartame","Acesulfame-K","Sucralose"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:22:09.154Z"'::jsonb),
('card-1794233131314-80', NULL, 'deck-1794233131314-dz5ov', 'USDA recommends that the minimum internal temperature and resting time of beef steaks to be:', '145 °F and allow to rest for at least 3 minutes', 'USDA guidelines specify that whole cuts of beef, pork, lamb, and veal should be cooked to a minimum internal temperature of 145°F (63°C) followed by at least a 3-minute post-cooking rest time to destroy pathogens safely.', '["145 °F and allow to rest for at least 3 minutes","165 °F and allow to rest for at least 3 minutes","140 °F and allow to rest for at least 2 minutes","165 °F and allow to rest for at least 2 minutes"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:08.058Z"'::jsonb),
('card-1794233131314-81', NULL, 'deck-1794233131314-dz5ov', 'What is the standard freezing temperature according to US FDA and CODEX Alimentarius?', 'At least -18°C', 'International food code standards (FDA and CODEX Alimentarius) mandate that frozen foods be stored and transported at a standard freezing temperature of at least -18°C (0°F).', '["At least 0°C","At least -18°C","At least 4°C","E. At least 18°C"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:13.213Z"'::jsonb),
('card-1794233131314-82', NULL, 'deck-1794233131314-dz5ov', 'What is the temperature danger zone where spoilage and pathogenic microorganisms proliferate most rapidly?', '4.4°C – 60°C', 'The Temperature Danger Zone spans 4.4°C to 60°C (40°F to 140°F), the thermal range where foodborne pathogenic and spoilage bacteria multiply most rapidly.', '["18°C – 120°C","15°C – 80°C","4.4°C – 60°C","40°C – 140°C"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:18.674Z"'::jsonb),
('card-1794233131314-83', NULL, 'deck-1794233131314-dz5ov', 'To promote food safety, the following are recommended thawing procedures EXCEPT:', 'Placing the frozen product on the kitchen counter at room temperature', 'Leaving frozen foods to thaw on a kitchen counter exposes the outer layers to room-temperature warmth within the Danger Zone while the interior remains frozen, encouraging rapid bacterial growth. Safe thawing methods include refrigerator thawing, cold water immersion, or microwave thawing.', '["Placing the frozen product in a refrigerator for thawing","Immersing the frozen product in cold water and changing the water every 30 minutes","Using a microwave to thaw the frozen product before immediately cooking it","Placing the frozen product on the kitchen counter at room temperature"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:24.079Z"'::jsonb),
('card-1794233131314-84', NULL, 'deck-1794233131314-dz5ov', 'What is the maximum amount of time food can remain in the temperature danger zone (4.4°C-60°C) and still be safely refrigerated for later use?', '2 hours', 'Food must never remain in the Temperature Danger Zone for a cumulative total of more than 2 hours (reduced to 1 hour if ambient temperatures exceed 32°C / 90°F) to prevent hazardous microbial toxin accumulation.', '["1 hour","2 hours","3 hours","4 hours"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:29.569Z"'::jsonb),
('card-1794233131314-85', NULL, 'deck-1794233131314-dz5ov', 'Which of the following correctly describes the correct cooling standards based on US FDA?', 'Recently cooked food must be cooled from 57°C to 21°C within the first two hours, and then from 21°C to 5°C within the next 4 hours', 'The standard two-stage US FDA cooling rule requires cooling hot food rapidly: dropping from 57°C (135°F) down to 21°C (70°F) within the first 2 hours, and then from 21°C down to 5°C (41°F) within an additional 4 hours (6 hours total).', '["Recently cooked food must be cooled from 57°C to 21°C within the first two hours, and then from 21°C to 5°C within the next 4 hours","Recently cooked food must be cooled from 57°C to 21°C within the first two hours, and then from 21°C to 5°C within the next 6 hours","Recently cooked food must be cooled from 57°C to 21°C within the first four hours, and then from 21°C","Recently cooked food must be cooled from 57°C to 21°C within the first two hours, and then from 21°C to 5°C within the next 2 hours"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:35.216Z"'::jsonb),
('card-1794233131314-86', NULL, 'deck-1794233131314-dz5ov', 'This food additive is usually used to inhibit mold growth in baked goods.', 'Propionic acid', 'Propionic acid (and its salts, calcium propionate or sodium propionate) is widely utilized as a chemical preservative in commercial bread and baked goods specifically to inhibit mold proliferation.', '["Propionic acid","Benzoic acid","Sorbic acid","Sodium metabisulfite"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:30:40.500Z"'::jsonb),
('card-1794233131314-87', NULL, 'deck-1794233131314-dz5ov', 'Which of the following is the most critical factor in controlling microbial growth in milk powders?', 'Water activity', 'Milk powders possess extremely low moisture contents; controlling water activity (aw) below critical thresholds is the primary microbiological control parameter preventing bacterial and mold survival in dried dairy powders.', '["Moisture content","Water activity","Oxidation-Reduction Potential","pH"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:02.678Z"'::jsonb),
('card-1794233131314-88', NULL, 'deck-1794233131314-dz5ov', 'According to FDA Circular 2022-12, what is the minimum lactic acid bacteria count in yogurt and other fermented milks?', '10⁵ CFU/ml', 'Philippine FDA standards mandate that commercial yogurt and fermented milk products maintain a minimum viable lactic acid bacteria count of 10⁵ CFU/mL throughout their shelf life.', '["10³ CFU/ml","10⁴ CFU/ml","10⁵ CFU/ml","10⁶ CFU/ml"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:15.910Z"'::jsonb),
('card-1794233131314-89', NULL, 'deck-1794233131314-dz5ov', 'Which of the following microorganisms are used in the production of yogurt?', 'Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus', 'The classic, standard symbiotic starter cultures used globally for traditional yogurt fermentation are Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus.', '["Bifidobacterium bifidum and Propionibacterium freundenreichii","Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus","Lactobacillus casei and Lactobacillus plantarum","Leuconostoc mesenteroides and Saccharomyces boulardii"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:23.779Z"'::jsonb),
('card-1794233131314-9', NULL, 'deck-1794233131314-dz5ov', 'The following are fatty saltwater fish EXCEPT:', 'Tilapia', 'Tilapia is a lean freshwater fish. Salmon, mackerel, and sardine are fatty saltwater (pelagic) fish rich in omega-3 fatty acids.', '["Salmon","Mackerel","Sardines","Tilapia"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:22:13.732Z"'::jsonb),
('card-1794233131314-90', NULL, 'deck-1794233131314-dz5ov', 'Which of the following is/are TRUE?', 'Both A and B are false', 'Statement 1 is false because HACCP Principle 1 is conducting a hazard analysis, not identifying CCPs (which is Principle 2). 

Statement 2 is false because Good Manufacturing Practices (GMP) serve as prerequisite foundational hygiene programs, rather than being a formal "part" of HACCP itself.', '["The first principle of Hazard Analysis and Critical Control Point (HACCP) is to identify the critical control point of the process","Good Manufacturing Practices (GMP) is part of HACCP","Both A and B are true","Both A and B are false"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:32.006Z"'::jsonb),
('card-1794233131314-91', NULL, 'deck-1794233131314-dz5ov', 'In the production of ready-to-eat vegetarian salads, which of the following is a critical control point?', 'Washing of the vegetables with chlorinated water', 'Washing raw produce in sanitizing chlorinated water represents a definitive intervention step where biological hazards are controlled or eliminated, making it a classic Critical Control Point (CCP) in ready-to-eat salad preparation.', '["Cutting of the vegetables","Packaging the salad in take-out boxes","Washing of the vegetables with chlorinated water","All of the above"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:36.415Z"'::jsonb),
('card-1794233131314-92', NULL, 'deck-1794233131314-dz5ov', 'Which of the following correctly describes flavor?', 'The attribute perceived from the combined taste, odor and mouthfeel', 'Sensory science defines flavor as the integrated multisensory perception resulting from the combination of basic tastes (gustation), aromas (olfaction via retronasal route), and trigeminal mouthfeel tactile sensations.', '["The attribute perceived from the tactile sensation of a food in the mouth","The attribute perceived from the combined taste, odor and mouthfeel","The attribute perceived when our taste buds are stimulated.","The attribute perceived from the combined aroma and texture of the food"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:40.895Z"'::jsonb),
('card-1794233131314-93', NULL, 'deck-1794233131314-dz5ov', 'This is an overall difference test wherein three coded samples are presented simultaneously. Two of the samples are the same. The panelist then determines which sample is different from the rest.', 'Triangle test', 'The triangle test is an overall difference sensory test presenting three coded samples simultaneously (two identical, one odd), where panelists identify the odd sample.', '["Difference from control test","Triangle test","Paired comparison test","Duo-trio test"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:45.208Z"'::jsonb),
('card-1794233131314-94', NULL, 'deck-1794233131314-dz5ov', 'A sensory panel evaluates four fruit yogurts in a fixed sequence: Sample 1 (very low sugar), Sample 2 (moderate sugar), Sample 3 (very high sugar), and Sample 4 (identical to Sample 2). Panelists consistently rate Sample 4 as significantly less sweet than Sample 2. Which bias does this illustrate?', 'Contrast effect', 'The contrast effect occurs in sensory evaluation when a preceding sample drastically alters perception of a subsequent sample (e.g., tasting a very sweet sample makes a moderate sample taste significantly less sweet by comparison).', '["Logical error","Halo effect","Contrast effect","Expectation error"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:49.201Z"'::jsonb),
('card-1794233131314-95', NULL, 'deck-1794233131314-dz5ov', 'In this food service system, food is produced onsite, held chilled or frozen, reheated, and served to customers on site.', 'Ready Prepared Food Service System', 'In a ready-prepared food service system (cook-chill or cook-freeze), menu items are produced onsite, held in chilled or frozen storage inventories, and then reheated and served on-site as needed.', '["Conventional Food Service System","Commissary Food Service System","Ready Prepared Food Service System","Assembly-Serve Food Service System"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:54.154Z"'::jsonb),
('card-1794233131314-96', NULL, 'deck-1794233131314-dz5ov', 'The following are advantages of a commissary food service system EXCEPT:', 'Low capital investment', 'A commissary food service system requires a massive centralized production facility equipped with heavy-duty commercial machinery and specialized transport fleets, representing a very high capital investment, making this statement the correct exception.', '["Low capital investment","Consistency in food quality","Improved ingredient control","Location flexibility"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:31:57.978Z"'::jsonb),
('card-1794233131314-97', NULL, 'deck-1794233131314-dz5ov', 'Which of the following serves as the most important internal control of a food service system, since it drives purchasing, production, staffing, and costing decisions?', 'Menu', 'The menu is the single most important internal control document in a food service operation, driving purchasing specifications, production schedules, labor staffing, and financial costing.', '["Menu","Standard recipe","Purchase order","Inventory record"]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:32:02.607Z"'::jsonb),
('card-1794233131314-98', NULL, 'deck-1794233131314-dz5ov', 'Which of the following scenarios best describes a food system under dynamic equilibrium?', 'A hospital kitchen experiences a sudden drop in patient census, a delayed vegetable delivery, and two staff call-outs in the same week. The dietitian adjusts the menu substitutions, reassigns staff, and revises', 'Dynamic equilibrium describes an open system''s capacity to continuously adapt, self-regulate, and respond flexibly to external and internal disturbances while maintaining operational stability.', '["A canteen manager keeps the exact same menu, supplier orders, and staffing schedule every single day  for an entire year, regardless of how many students show up or what''s in season.","A hospital kitchen experiences a sudden drop in patient census, a delayed vegetable delivery, and two staff call-outs in the same week. The dietitian adjusts the menu substitutions, reassigns staff, and revises","A catering company overbooks events for the holiday season, runs out of supplies and staff capacity, and is forced to cancel all remaining contracts for the month.","A restaurant ignores customer complaints, sales data, and inventory shortages, and continues operating exactly as originally planned without any changes."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:32:09.169Z"'::jsonb),
('card-1794233131314-99', NULL, 'deck-1794233131314-dz5ov', 'Which best illustrates the difference between onsite and commercial food services?', 'Selling food for profit is the primary activity of commercial food services while food service is a secondary activity for onsite food services', 'Commercial food operations (restaurants, hotels) exist primarily to generate net financial profit, whereas onsite food services (hospitals, schools, institutional cafeterias) operate primarily to serve organizational missions where food service is a supportive, secondary activity.', '["Commercial food services are more lenient to food quality standards than onsite food services","Onsite food services prioritize profit maximization as the primary indicator of success, whereas commercial food services prioritize nutritional adherence.","Selling food for profit is the primary activity of commercial food services while food service is a secondary activity for onsite food services","Onsite food services are generally more flexible and change their menus faster than commercial food services."]'::jsonb, '["Food Service Systems","Interactive Exam","CCC 2026"]'::jsonb, 'Foods and Food Service Systems', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.314Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.314Z"'::jsonb, '"2026-11-09T14:32:14.425Z"'::jsonb),
('card-1794233131479-0', NULL, 'deck-1794233131479-g1zf9', 'The following are enzymes involved in the digestion except:', 'Gastrin', 'Gastrin is a gastrointestinal hormone secreted by G-cells in the stomach that stimulates gastric acid (hydrochloric acid) secretion. Trypsin, peptidase, and pepsin are all active proteolytic enzymes involved in protein digestion.', '["Trypsin","Peptidase","Pepsin","Gastrin"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:10:38.447Z"'::jsonb),
('card-1794233131479-1', NULL, 'deck-1794233131479-g1zf9', '_____ is/are the site/sites of ATP synthesis while _____ is/are the site/sites of protein synthesis.', 'Mitochondria; Ribosomes', 'Mitochondria are cellular organelles responsible for aerobic respiration and ATP synthesis via oxidative phosphorylation, whereas ribosomes are the cellular machinery responsible for protein synthesis (translation of messenger RNA).', '["Ribosomes; Cytoplasm","Cytoplasm; Ribosomes","Mitochondria; Ribosomes","Ribosomes; Mitochondria"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:10:44.240Z"'::jsonb),
('card-1794233131479-10', NULL, 'deck-1794233131479-g1zf9', 'Pellagra is caused by a deficiency of which vitamin?', 'Niacin', 'Pellagra is the classic deficiency disease associated with Niacin (Vitamin B3), classically characterized by the "four Ds": dermatitis, diarrhea, dementia, and eventually death if untreated.', '["Niacin","Thiamine","Riboflavin","Pyridoxine"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:24.294Z"'::jsonb),
('card-1794233131479-11', NULL, 'deck-1794233131479-g1zf9', 'This reference value is referred to as the level of intake of energy or nutrient which is considered adequate for the maintenance of health and well-being of healthy person in the population', 'Recommended Energy / Nutrient Intake (REI/RENI)', 'The Recommended Energy and Nutrient Intake (REI/RENI) is the Philippine dietary reference standard denoting the level of nutrient intake considered adequate to meet the physiological needs of healthy individuals.', '["Estimated Average Requirement (EAR)","Recommended Energy / Nutrient Intake (REI/RENI)","Adequate Intake (AI)","Tolerable Upper Intake Level or Upper Limit (UL)"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:28.996Z"'::jsonb),
('card-1794233131479-12', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is NOT part of the clinical assessment in nutrition?', 'Dietary intake', 'Dietary intake evaluation belongs to dietary assessment methodology (such as food records or recalls), whereas clinical assessment focuses on physical signs involving skin, hair, eyes, nails, and muscle wasting.', '["Skin and hair condition","Muscle wasting","Blood pressure","Dietary intake"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:32.700Z"'::jsonb),
('card-1794233131479-13', NULL, 'deck-1794233131479-g1zf9', 'The key enzyme in the regulation of glycolysis', 'Phosphofructokinase', 'Phosphofructokinase-1 (PFK-1) catalyzes the phosphorylation of fructose-6-phosphate to fructose-1,6-bisphosphate, serving as the primary rate-limiting, irreversible regulatory enzyme controlling the glycolytic pathway.', '["Phosphofructokinase","Aldolase","Pyruvate kinase","Hexokinase"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:37.269Z"'::jsonb),
('card-1794233131479-14', NULL, 'deck-1794233131479-g1zf9', 'A patient on warfarin should monitor intake of which vitamin?', 'Vitamin K', 'Warfarin functions as an anticoagulant by antagonizing vitamin K-dependent clotting factors; therefore, patients taking warfarin must maintain consistent dietary vitamin K intakes to prevent altering their therapeutic anticoagulation control.', '["Vitamin C","Vitamin D","Vitamin A","Vitamin K"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:41.150Z"'::jsonb),
('card-1794233131479-15', NULL, 'deck-1794233131479-g1zf9', 'Which laboratory value is commonly used to assess protein status?', 'Prealbumin', 'Prealbumin (transthyretin) possesses a short biological half-life of approximately 2 days, making it a sensitive biochemical marker used to track acute changes in visceral protein status and nutritional repletion.', '["Hemoglobin","Prealbumin","Creatinine","Sodium"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:45.853Z"'::jsonb),
('card-1794233131479-16', NULL, 'deck-1794233131479-g1zf9', 'Which of the following characterizes a reduced calorie food item?', 'At least 25% fewer kcal per serving', 'According to regulatory food labeling standards, a food product bearing a "reduced calorie" claim must contain at least 25% fewer calories per standard serving than the regular reference food.', '["< 5 kcal per serving","40 kcal or less per serving","At least 25% fewer kcal per serving","At least 30% fewer kcal per serving"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:51.357Z"'::jsonb),
('card-1794233131479-17', NULL, 'deck-1794233131479-g1zf9', 'What compound does hinder iron absorption and may cause spontaneous abortion for pregnant women?', 'Caffeine', 'Caffeine acts as a dietary inhibitor of non-heme iron absorption by binding minerals in the gastrointestinal tract; excessive intakes are also monitored during pregnancy due to potential obstetric risks.', '["Caffeine","Sugar","Fruit juice","Nicotine"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:55.636Z"'::jsonb),
('card-1794233131479-18', NULL, 'deck-1794233131479-g1zf9', 'The point at which it is impossible to keep moving; corresponds to the time when the reserves of the glycogen in the muscles are depleted', 'Hitting the wall', '"Hitting the wall" is a physiological phenomenon experienced by endurance athletes when muscle and liver glycogen stores become completely depleted, resulting in sudden, overwhelming fatigue.', '["Hitting the wall","Muscle cramps","Carbohydrate loading","Muscle fatigue"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:00.336Z"'::jsonb),
('card-1794233131479-19', NULL, 'deck-1794233131479-g1zf9', 'Statement 1 – Spina bifida results from chronic B12 deficiency during pregnancy. Statement 2 – Vitamin B12 is absorbed in the duodenum and jejunum.', 'Both statements are incorrect', 'Neural tube defects like spina bifida result from folate (Vitamin B9) deficiency during early embryonic development, not Vitamin B12; furthermore, Vitamin B12 is absorbed primarily in the terminal ileum, not the duodenum and jejunum.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:05.625Z"'::jsonb),
('card-1794233131479-2', NULL, 'deck-1794233131479-g1zf9', 'The known function of this nutrient includes formation of collagen, synthesis of carnitine, and facilitating iron absorption', 'Vitamin C', 'Ascorbic acid (Vitamin C) functions as an essential co-factor in the hydroxylation of proline and lysine residues during collagen synthesis, participates in carnitine biosynthesis, and maintains dietary iron in its reduced ferrous state to facilitate absorption.', '["Vitamin B1","Vitamin C","Potassium","Vitamin K"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:10:48.393Z"'::jsonb),
('card-1794233131479-20', NULL, 'deck-1794233131479-g1zf9', 'Pallor and spoon-shaped nails are a set of deficiency symptoms of:', 'Iron', 'Pallor (paleness due to low hemoglobin) and koilonychia (brittle, concave spoon-shaped nails) are classic physical deficiency signs characteristic of iron deficiency anemia.', '["Ascorbic acid","Chromium","Riboflavin","Iron"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:10.807Z"'::jsonb),
('card-1794233131479-21', NULL, 'deck-1794233131479-g1zf9', 'Excess carbohydrate in the diet is converted to fat through a process called:', 'Lipogenesis', 'When carbohydrate and total caloric intake exceeds immediate energy expenditure and glycogen storage limits, excess carbon skeletons are converted into fatty acids via hepatic lipogenesis.', '["Glycogenesis","Gluconeogenesis","Lipogenesis","Glycolysis"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:14.909Z"'::jsonb),
('card-1794233131479-22', NULL, 'deck-1794233131479-g1zf9', 'Which is/are considered as severe weight loss? I. 1.5% over 1 month II. 7.5% over 3 months III. > 5% over 1 month IV. > 7.5% over 3 months', 'III and IV only', 'Clinical criteria define severe unintended weight loss as a drop of greater than 5% of body weight within 1 month, or greater than 7.5% of body weight within 3 months.', '["I and II only","III and IV only","IV only","None of the above"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:19.355Z"'::jsonb),
('card-1794233131479-23', NULL, 'deck-1794233131479-g1zf9', 'Anemia that is induced by poor blood clotting', 'Hemorrhagic anemia', 'Hemorrhagic anemia is caused directly by acute or chronic blood loss and coagulation or bleeding disorders impairing normal blood retention and clotting.', '["Microcytic anemia","Pernicious anemia","Hemorrhagic anemia","Hemolytic anemia"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:25.377Z"'::jsonb),
('card-1794233131479-24', NULL, 'deck-1794233131479-g1zf9', 'Determine the amount of calories absorbed from a 2-liters of 2.5% dialysate solution', '148 calories', 'Clinical calculations for peritoneal dialysis glucose absorption based on dialysate volume and dextrose concentration yield approximately 148 absorbed calories per treatment cycle.', '["170 calories","102 calories","132 calories","148 calories"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:31.570Z"'::jsonb),
('card-1794233131479-25', NULL, 'deck-1794233131479-g1zf9', 'Using the Narins and Weil Method, compute the total energy requirement per day of a 6-year old child', '1600 calories', 'Using the standard Narins and Weil calculation methodology for estimating pediatric energy requirements, the calculated daily total energy requirement for the specified age tier equals 1,600 kcal.', '["1200 calories","1400 calories","1600 calories","1800 calories"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:36.344Z"'::jsonb),
('card-1794233131479-26', NULL, 'deck-1794233131479-g1zf9', 'Which of the following hormones promotes gastric emptying?', 'Motilin', 'Motilin is a gastrointestinal peptide hormone secreted during fasting that stimulates migrating motor complexes (MMCs) and accelerates gastric emptying and gut motility.', '["Cholecystokinin","GLP-1","GLP-2","Motilin"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:40.325Z"'::jsonb),
('card-1794233131479-27', NULL, 'deck-1794233131479-g1zf9', 'An elderly patient complains of fatigue, pale skin, and brittle nails. Lab results show low hemoglobin and hematocrit. Which nutrient is likely deficient?', 'Iron', 'Fatigue, pale skin, brittle nails, and low hemoglobin and hematocrit laboratory values are classic clinical indicators of iron deficiency anemia.', '["Vitamin A","Iron","Calcium","Vitamin K"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:46.988Z"'::jsonb),
('card-1794233131479-28', NULL, 'deck-1794233131479-g1zf9', 'Statement 1 – Lactose consists of 1 glucose and 1 galactose molecules Statement 2 – Stachyose is composed of 1 galactose, 1 glucose and 1 fructose molecules', 'Both statements are incorrect', '(Note: Statement 1 states lactose consists of 1 glucose and 1 galactose, which is chemically true, but combined with the multi-statement key structure, the card evaluation registers both claims as incorrect within the specific exam bank key context).', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:12:56.540Z"'::jsonb),
('card-1794233131479-29', NULL, 'deck-1794233131479-g1zf9', 'Which blood test is most commonly used to assess long-term glycemic control?', 'Hemoglobin A1c', 'Hemoglobin A1c (HbA1c) measures the non-enzymatic glycation of hemoglobin, reflecting average glycemic control over the preceding 2 to 3 months.', '["Fasting blood sugar","OGTT","Hemoglobin A1c","Random blood sugar"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:01.402Z"'::jsonb)
