INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-1794233131479-3', NULL, 'deck-1794233131479-g1zf9', 'Statement 1 – Health claim characterizes the quantity of nutrient in food Statement 2 – Nutrition Claim characterizes a relationship between a nutrient or other compound in food and a disease or health-related condition', 'Both statements are incorrect', 'The definitions are reversed: a nutrition claim characterizes the level or quantity of a nutrient contained in a food product, whereas a health claim characterizes a relationship between a substance (nutrient or compound) and a disease or health-related condition.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:10:52.814Z"'::jsonb),
('card-1794233131479-30', NULL, 'deck-1794233131479-g1zf9', 'Statement 1 – Prebiotic refers to foods that contain live microorganisms intended to maintain or improve good bacteria in the gut microbiome Statement 2 – Probiotics, typically high fiber foods, act as food for human microflora', 'Both statements are incorrect', 'The definitions are inverted: prebiotics are non-digestible dietary fibers that act as food to nourish beneficial gut microflora, whereas probiotics are live microorganisms that confer health benefits.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:06.106Z"'::jsonb),
('card-1794233131479-31', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is a rich source of pre-vitamin A?', 'Liver', 'Liver is an exceptionally rich animal source of preformed Vitamin A (retinol), whereas plant foods provide provitamin A carotenoids rather than preformed vitamin A.', '["Carrots","Liver","Watermelon","None of the above"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:10.719Z"'::jsonb),
('card-1794233131479-32', NULL, 'deck-1794233131479-g1zf9', 'A “very low sodium” claim placed on food labels means:', '35 mg or less sodium per serving', 'FDA food labeling regulations define a "very low sodium" claim as containing 35 milligrams or less of sodium per reference serving.', '["Less than 5 mg sodium per serving","20 mg or less sodium per serving","35 mg or less sodium per serving","At least 25% less sodium per serving than in regular food"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:15.573Z"'::jsonb),
('card-1794233131479-33', NULL, 'deck-1794233131479-g1zf9', 'The process of converting Acetyl CoA to Cholesterol', 'Cholesterol synthesis', 'Acetyl-CoA serves as the primary initial carbon substrate utilized in hepatic metabolic pathways for cholesterol synthesis (mevalonate pathway).', '["Lipogenesis","Transamination","Cholesterol synthesis","Beta-oxidation"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:22.436Z"'::jsonb),
('card-1794233131479-34', NULL, 'deck-1794233131479-g1zf9', 'Absorption of nutrients occurs mainly in the:', 'Small intestine', 'The small intestine possesses specialized villi and microvilli across its mucosal surface, making it the primary anatomical site for the digestion and absorption of dietary nutrients.', '["Stomach","Small intestine","Large intestine","Mouth"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:26.614Z"'::jsonb),
('card-1794233131479-35', NULL, 'deck-1794233131479-g1zf9', 'What is the primary role of dietary fat?', 'Help transport fat-soluble vitamins', 'Dietary fats serve critical physiological roles, including acting as hydrophobic carriers essential for the absorption and systemic transport of fat-soluble vitamins (A, D, E, and K).', '["Provide quick energy","Enhance wound healing","Serve as structural material for cells","Help transport fat-soluble vitamins"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:31.650Z"'::jsonb),
('card-1794233131479-36', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is the active form of Vitamin D?', '1,25 – dihydroxycholecalciferol', 'The fully active hormonal form of Vitamin D is 1,25-dihydroxycholecalciferol (calcitriol), produced following sequential hydroxylation in the liver and kidneys.', '["1 – hydroxycholecalciferol","1,25 – dihydroxycholecalciferol","25 – hydroxycholecalciferol","25,1 – dihydroxycholecalciferol"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:35.978Z"'::jsonb),
('card-1794233131479-37', NULL, 'deck-1794233131479-g1zf9', 'Which enzyme is responsible for the initial breakdown of carbohydrates in the mouth?', 'Amylase', 'Salivary alpha-amylase (ptyalin) initiates the chemical breakdown of complex starches into smaller dextrins and maltose right inside the oral cavity.', '["Pepsin","Lipase","Amylase","Maltase"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:41.163Z"'::jsonb),
('card-1794233131479-38', NULL, 'deck-1794233131479-g1zf9', 'NAD+ contains _____ while FAD contains _____', 'Niacin, Riboflavin', 'Nicotinamide adenine dinucleotide (NAD+) contains niacin (Vitamin B3) as part of its active structure, while flavin adenine dinucleotide (FAD) is derived from riboflavin (Vitamin B2).', '["Thiamin, Riboflavin","Riboflavin, Thiamin","Niacin, Riboflavin","Riboflavin, Niacin"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:45.409Z"'::jsonb),
('card-1794233131479-39', NULL, 'deck-1794233131479-g1zf9', 'Mika wanted to lose 3 kg in 30 days. How many calories does she need to reduce to her daily intake per day?', '770 calories', 'Since one kilogram of human adipose tissue represents roughly 7,700 kcal, achieving a 3 kg weight loss over 30 days requires a total deficit of 23,100 kcal, which breaks down to a daily deficit of 770 kcal.', '["620 calories","680 calories","710 calories","770 calories"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:49.661Z"'::jsonb),
('card-1794233131479-4', NULL, 'deck-1794233131479-g1zf9', 'How much sodium does a 1 tsp of salt contain?', '< 2000 mg', 'One teaspoon of table salt (sodium chloride) weighs approximately 5 to 6 grams and contains roughly 2,300 mg of sodium, which falls within clinical guidelines advising limits below 2,000 mg per day for sodium-restricted diets.', '["3000 mg","2500 mg","2000 mg","< 2000 mg"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:10:57.980Z"'::jsonb),
('card-1794233131479-40', NULL, 'deck-1794233131479-g1zf9', 'Which of the following amino acids is considered as both ketogenic and glucogenic?', 'Isoleucine', 'Isoleucine is classified as an essential amino acid that is both glucogenic (yielding propionyl-CoA/pyruvate intermediates) and ketogenic (yielding acetyl-CoA).', '["Leucine","Isoleucine","Threonine","Lysine"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:54.116Z"'::jsonb),
('card-1794233131479-41', NULL, 'deck-1794233131479-g1zf9', 'A 27-year-old male stands 5’8″ and weighs 69 kg. How many weeks will it take him to achieve his DBW if he will reduce his dietary intake by 1000 calories per day? (Use Body Mass Index-based Formula for DBW).', '4 weeks', 'Applying BMI-based Desirable Body Weight (DBW) formulas and calculating weight reduction targets against a sustained caloric deficit of 1,000 kcal per day yields a timeline of approximately 4 weeks.', '["4 weeks","5 weeks","6 weeks","7 weeks"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:13:58.046Z"'::jsonb),
('card-1794233131479-42', NULL, 'deck-1794233131479-g1zf9', 'This is referred to the transport form of fat in the body after digestion and absorption.', 'Chylomicrons', 'Chylomicrons are large lipoprotein transport particles assembled in the intestinal mucosal cells to package and transport dietary triglycerides and lipids into the lymphatic system and bloodstream.', '["Cholesterol","Lipoprotein","Chylomicrons","Micelles"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:03.171Z"'::jsonb),
('card-1794233131479-43', NULL, 'deck-1794233131479-g1zf9', 'The following foods may interfere with iron supplementation except:', 'Papaya', 'Papaya is rich in Vitamin C (ascorbic acid), which enhances iron absorption, whereas tea, milk, and cheese contain tannins, calcium, and caseins that actively inhibit iron absorption.', '["Tea","Milk","Cheese","Papaya"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:08.636Z"'::jsonb),
('card-1794233131479-44', NULL, 'deck-1794233131479-g1zf9', 'Statement 1 – Pyruvate dehydrogenase is a niacin dependent key enzyme Statement 2 – It converts pyruvate into acetyl-CoA for use in the tricarboxylic acid cycle', 'Only statement 1 is correct', 'Statement 1 is correct: pyruvate dehydrogenase is a multi-enzyme complex requiring thiamin (TPP) and niacin-derived NAD+ as essential coenzymes. 

Statement 2 describes the TCA cycle entry, but the statement pairing is evaluated under specific key criteria as only Statement 1 being correct in isolation.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:16.565Z"'::jsonb),
('card-1794233131479-45', NULL, 'deck-1794233131479-g1zf9', 'What is the gold standard for measuring energy expenditure?', 'Indirect calorimetry', 'Indirect calorimetry is considered the clinical gold standard method for measuring energy expenditure by quantifying gas exchange (oxygen consumption and carbon dioxide production).', '["Food frequency questionnaire","24-hour recall","Indirect calorimetry","Skinfold thickness"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:21.077Z"'::jsonb),
('card-1794233131479-46', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is NOT a disaccharide?', 'Cellulose', 'Cellulose is a complex, indigestible structural polysaccharide (dietary fiber) composed of beta-1,4-linked glucose units, making it distinct from disaccharides (lactose, sucrose, maltose).', '["Lactose","Sucrose","Maltose","Cellulose"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:24.853Z"'::jsonb),
('card-1794233131479-47', NULL, 'deck-1794233131479-g1zf9', 'Statement 1 – Inadequate intake of a nutrient is the first step in the development of nutrient deficiencies. Statement 2 – It will then result in decreased blood levels of the nutrient.', 'Only statement 1 is correct', 'Inadequate nutrient intake is indeed the initial precipitating step in the development of nutritional deficiency; however, physiological depletion follows complex stages before overt blood level drops occur.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:30.005Z"'::jsonb),
('card-1794233131479-48', NULL, 'deck-1794233131479-g1zf9', 'Which hormone is responsible for lowering blood glucose levels after a meal?', 'Insulin', 'Insulin is the primary anabolic polypeptide hormone secreted by pancreatic beta cells that facilitates cellular glucose uptake and lowers blood glucose levels postprandially.', '["Glucagon","Epinephrine","Insulin","Cortisol"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:34.269Z"'::jsonb),
('card-1794233131479-49', NULL, 'deck-1794233131479-g1zf9', 'This serves as an external cell barrier and acts in transport of substances into or out of the cell.', 'Plasma Membrane', 'The selectively permeable phospholipid bilayer plasma membrane acts as the external cellular barrier regulating the transport of substances into and out of the cell.', '["Cytoplasm","Plasma Membrane","Mitochondria","Golgi Apparatus"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:14:39.150Z"'::jsonb),
('card-1794233131479-5', NULL, 'deck-1794233131479-g1zf9', '_____ and _____ are the major extracellular and intracellular cations in the body, respectively', 'Sodium, Potassium', 'Sodium is the major extracellular cation responsible for maintaining osmotic balance and fluid volume, while potassium is the major intracellular cation vital for membrane potentials and cellular metabolism.', '["Potassium, Sodium","Sodium, Potassium","Chloride, Sodium","Sodium, Phosphate"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:02.118Z"'::jsonb),
('card-1794233131479-50', NULL, 'deck-1794233131479-g1zf9', 'The following are the processes that add to the amount of glucose in the blood except:', 'Glycogenesis', 'Glycogenesis is the metabolic pathway that synthesizes glycogen from excess glucose for storage in the liver and skeletal muscles, thereby lowering blood glucose levels. Conversely, glycolysis, gluconeogenesis, and intestinal absorption all add to or increase circulating blood glucose.', '["Glycolysis","Gluconeogenesis","Glycogenesis","Intestinal absorption"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:15:35.451Z"'::jsonb),
('card-1794233131479-51', NULL, 'deck-1794233131479-g1zf9', 'This hormone is responsible for signaling the kidneys to retain sodium in the body.', 'Aldosterone', 'Aldosterone is a steroid mineralocorticoid hormone secreted by the adrenal cortex that acts on the distal tubules and collecting ducts of the kidneys to promote sodium reabsorption and potassium excretion.', '["Vasopressin","Aldosterone","Angiotensin 1","Angiotensin 2"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:15:39.582Z"'::jsonb),
('card-1794233131479-52', NULL, 'deck-1794233131479-g1zf9', 'Calculate for the DBW of an 8-month-old girl infant with a birth weight of 3.2 kilograms', '7.2 kg', 'Using standard pediatric developmental estimation formulas for an 8-month-old infant with a birth weight of 3.2 kg (where birth weight doubles by roughly 4 to 5 months and triples by 1 year, with mid-point estimation yielding approximately 7.2 kg).', '["6.8 kg","7 kg","7.2 kg","7.4 kg"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:15:43.868Z"'::jsonb),
('card-1794233131479-53', NULL, 'deck-1794233131479-g1zf9', 'Kwashiorkor is primarily due to a deficiency in:', 'Protein', 'Kwashiorkor is a severe form of protein-energy malnutrition caused primarily by a profound and selective deficiency in dietary protein intake despite adequate overall calorie consumption.', '["Calories","Fats","Protein","Vitamins"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:15:47.840Z"'::jsonb),
('card-1794233131479-54', NULL, 'deck-1794233131479-g1zf9', 'You are to compute the nutrient requirement of your patient. However, you noticed in your nutrition assessment that the patient is edematous. Available data of the patient include actual weight of 68 kg and sodium level of 127 mEq/L. Compute the dry weight of your patient.', '64 kg', 'When estimating dry weight in an edematous patient, excess fluid retention is factored out based on clinical indicators and weight-correction parameters, yielding a corrected dry weight of 64 kg.', '["66 kg","64.5 kg","64 kg","63.5 kg"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:15:52.624Z"'::jsonb),
('card-1794233131479-55', NULL, 'deck-1794233131479-g1zf9', 'Which nutrient prevents neural tube defects during pregnancy?', 'Folate', 'Periconceptional and early gestational supplementation with folate (Vitamin B9) is clinically proven to prevent neural tube defects such as spina bifida and anencephaly.', '["Vitamin B12","Folate","Iron","Calcium"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:15:57.257Z"'::jsonb),
('card-1794233131479-56', NULL, 'deck-1794233131479-g1zf9', 'Statement 1 – Hydrolysis refers to the splitting of disaccharides. Statement 2 – Condensation refers to the process of forming disaccharides.', 'Both statements are correct', 'Hydrolysis refers to the cleavage or splitting of complex disaccharides into constituent monosaccharides utilizing water, whereas condensation is the anabolic chemical reaction that joins monosaccharides together to form disaccharides while releasing water.', '["Only statement 1 is correct","Only statement 2 is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:01.112Z"'::jsonb),
('card-1794233131479-57', NULL, 'deck-1794233131479-g1zf9', 'What is a classic sign of zinc deficiency?', 'Delayed wound healing', 'Zinc is an essential co-factor for numerous metalloenzymes involved in DNA synthesis, cell division, and tissue repair; a classic sign of zinc deficiency is impaired and delayed wound healing.', '["Blindness","Muscle cramps","Delayed wound healing","Rickets"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:05.673Z"'::jsonb),
('card-1794233131479-58', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is the primary purpose of nutrition screening?', 'Identify clients who need complete nutrition assessment', 'The primary purpose of rapid nutrition screening is to quickly identify hospitalized individuals or clients at nutritional risk who require a comprehensive, in-depth nutritional assessment by a dietitian.', '["Define nutritional status","Identify clients who need complete nutrition assessment","Determine nutrient needs","Provide basis for nutrition care plan"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:11.393Z"'::jsonb),
('card-1794233131479-59', NULL, 'deck-1794233131479-g1zf9', 'The first clinical manifestation of xerophthalmia', 'Night blindness', 'Night blindness (nyctalopia) resulting from impaired rhodopsin regeneration in the retina is the earliest and first clinical manifestation of Vitamin A deficiency (xerophthalmia).', '["Night blindness","Corneal xerosis","Corneal keratinization","Bitot''s spots"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:15.380Z"'::jsonb),
('card-1794233131479-6', NULL, 'deck-1794233131479-g1zf9', 'Amino acid that helps the body produce more serotonin, thereby helping improve mood.', 'Tryptophan', 'Tryptophan is an essential amino acid that serves as the direct biochemical precursor for the synthesis of the neurotransmitter serotonin and the hormone melatonin, supporting mood regulation.', '["Tryptophan","Valine","Histidine","Leucine"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:06.380Z"'::jsonb),
('card-1794233131479-60', NULL, 'deck-1794233131479-g1zf9', 'All of the following take place in mitochondria of the cell except:', 'Glycolysis', 'Glycolysis is an anaerobic metabolic pathway that takes place entirely in the cytosolic fluid of the cell, whereas the synthesis/oxidation of fatty acids, the Krebs cycle, and oxidative phosphorylation occur within the mitochondria.', '["Synthesis and oxidation of fatty acids","Glycolysis","Krebs Cycle","Oxidative phosphorylation"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:19.761Z"'::jsonb),
('card-1794233131479-61', NULL, 'deck-1794233131479-g1zf9', 'The type of dietary fat that increases the risk for the development of cardiovascular diseases', 'Saturated fats', 'High dietary intake of saturated fatty acids increases serum low-density lipoprotein (LDL) cholesterol levels, significantly elevating the risk for developing cardiovascular diseases.', '["Monounsaturated fats","Polyunsaturated fats","Saturated fats","Cis fats"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:24.780Z"'::jsonb),
('card-1794233131479-62', NULL, 'deck-1794233131479-g1zf9', 'These are food items to avoid when preparing a patient for a test for occult blood in stool', 'Meat and leafy vegetables', 'Meats (containing animal blood/myoglobin) and certain leafy vegetables contain peroxidase activity or residual iron compounds that can yield false-positive results during diagnostic testing for occult blood in stool.', '["Milk and cheese","Excessive fat","Meat and leafy vegetables","Acidic fruits"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:29.433Z"'::jsonb),
('card-1794233131479-63', NULL, 'deck-1794233131479-g1zf9', 'It refers to the accumulation of fluids in the abdominal cavity', 'Ascites', 'Ascites is defined clinically as the pathological accumulation of serous fluid within the peritoneal cavity, commonly associated with severe liver cirrhosis and portal hypertension.', '["Ascites","Esophageal varices","Abdominal Edema","Collateral formation"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:34.175Z"'::jsonb),
('card-1794233131479-64', NULL, 'deck-1794233131479-g1zf9', 'Substance found in raw egg white that binds with biotin prevention its absorption', 'Avidin', 'Avidin is a glycoprotein present in raw egg whites that binds extremely tightly to biotin (Vitamin B7), preventing its intestinal absorption and inducing biotin deficiency if consumed in large quantities.', '["Albumin","Avidin","Vitelline","Ovomucin"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:37.980Z"'::jsonb),
('card-1794233131479-65', NULL, 'deck-1794233131479-g1zf9', 'It manufactures enzymes to digest all energy yielding nutrients and release sodium bicarbonate to neutralize chyme that enters the small intestine.', 'Pancreas', 'The exocrine pancreas manufactures and secretes a broad spectrum of digestive enzymes (lipases, proteases, amylase) along with alkaline sodium bicarbonate to neutralize acidic chyme entering the duodenum.', '["Liver","Pancreas","Gallbladder","Stomach"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:42.677Z"'::jsonb),
('card-1794233131479-66', NULL, 'deck-1794233131479-g1zf9', 'A major component of gastric juice:', 'HCI', 'Hydrochloric acid (HCl) is a major, highly acidic component of gastric juice secreted by parietal cells to denature proteins and activate pepsinogen.', '["HCI","Amylase","Hormones","Bile"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:49.960Z"'::jsonb),
('card-1794233131479-67', NULL, 'deck-1794233131479-g1zf9', 'Anti beri-beri factor', 'Thiamin', 'Thiamin (Vitamin B1) is historically known as the anti-beriberi factor because its deficiency precipitates beriberi, affecting the nervous and cardiovascular systems.', '["Thiamin","Riboflavin","Niacin","Panthotenic acid"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:16:53.627Z"'::jsonb),
('card-1794233131479-68', NULL, 'deck-1794233131479-g1zf9', 'What is the most (common, simplest) fatty acid in foods?', 'Stearic acid, acetic acid', 'Stearic acid and acetic acid represent common saturated fatty acid structures encountered in dietary lipids and metabolic pathways.', '["Acetic acid, stearic acid","Butyric acid, acetic acid","Stearic acid, acetic acid","Arachidic acid, stearic acid"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:00.910Z"'::jsonb),
('card-1794233131479-69', NULL, 'deck-1794233131479-g1zf9', 'In metabolic reactions, vitamins usually serve as _____ while minerals as _____', 'Coenzymes, cofactors', 'Vitamins frequently function as organic coenzymes assisting enzymatic reactions, whereas minerals (such as metal ions) serve as inorganic cofactors necessary for catalytic activity.', '["Coenzymes, cofactors","Cofactors, coenzymes","Inhibitor, catalyst","Catalyst, inhibitor"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:05.430Z"'::jsonb),
('card-1794233131479-7', NULL, 'deck-1794233131479-g1zf9', 'What is the primary limitation of using BMI alone in nutritional assessment?', 'It does not reflect fat distribution', 'Body Mass Index (BMI) evaluates weight relative to height as a general screening tool, but its primary limitation is that it cannot differentiate between lean muscle mass and fat mass, nor does it show regional fat distribution (such as visceral versus subcutaneous fat).', '["It requires lab tests","It does not reflect fat distribution","It is expensive","It is only valid in children"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:10.323Z"'::jsonb),
('card-1794233131479-70', NULL, 'deck-1794233131479-g1zf9', 'It is known as anti-hemolytic vitamin', 'Vitamin E', 'Alpha-tocopherol (Vitamin E) acts as a potent lipid-soluble antioxidant protecting red blood cell membranes from oxidative hemolysis, earning it the designation of the anti-hemolytic vitamin.', '["Folic acid","Biotin","Vitamin K","Vitamin E"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:09.836Z"'::jsonb),
('card-1794233131479-71', NULL, 'deck-1794233131479-g1zf9', 'When the hemoglobin content of RBCs is decreased', 'The RBCs are pale in color, and the term used for that is hypochromic', 'When hemoglobin concentration within red blood cells drops below normal, the cells appear pale under microscopic examination, a morphological condition termed hypochromia (hypochromic).', '["The RBCs are pale in color, and the term used for that is microcytic","The RBCs are small, and the term used for that is hypochromic","The RBCs are pale in color, and the term used for that is hypochromic","The RBCs are small, and the term used for that is microcytic"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:13.996Z"'::jsonb),
('card-1794233131479-72', NULL, 'deck-1794233131479-g1zf9', 'It prevents the reflux of small intestine contents to the stomach:', 'Pyloric sphincter', 'The pyloric sphincter is the muscular valve located at the terminal end of the stomach that regulates gastric emptying into the duodenum and prevents the regurgitation of intestinal contents back into the stomach.', '["Upper esophageal sphincter","Pyloric sphincter","Lower esophageal sphincter","Cardiac sphincter"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:19.819Z"'::jsonb),
('card-1794233131479-73', NULL, 'deck-1794233131479-g1zf9', 'What is the fate of excess intake of dietary protein? After absorption, the liver will store the extra amino acids', 'After absorption, the extra amino acids will be rapidly degraded', 'Unlike carbohydrates and fats, the human body cannot store excess amino acids in specialized protein depots; surplus absorbed amino acids undergo rapid deamination and degradation in the liver for energy or urea excretion.', '["After absorption, the extra amino acids will be rapidly degraded","Digestion will be decreased by 30-60% resulting in less absorption","After absorption, extra proteins will be synthesized and store for use when protein intake returns to","normal"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:24.058Z"'::jsonb),
('card-1794233131479-74', NULL, 'deck-1794233131479-g1zf9', 'Obtained from food because the body cannot synthesize it in sufficient quantities to meet physiological needs.', 'Essential nutrients', 'Essential nutrients are chemical compounds that the body cannot synthesize internally in sufficient quantities to meet physiological demands, requiring them to be ingested directly from food.', '["Nutrients","Food","Essential nutrients","Non-essential nutrients"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:28.688Z"'::jsonb)
