INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-1794233131479-75', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is not a domain of nutrition assessment?', 'Screening / referral forms', 'Standardized domains of the Nutrition Care Process (NCP) assessment include anthropometric measurements, client history, biochemical data/medical tests, and nutrition-focused physical findings, whereas screening/referral forms serve administrative triage functions rather than clinical assessment domains.', '["Anthropometric measurements","Client history","Screening / referral forms","Biochemical data, medical tests and procedures"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:33.435Z"'::jsonb),
('card-1794233131479-76', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is nottrue about Nutrition Care Process?', 'Provides a framework for generalized care, taking into account the patient / client’s needs and values and using the best evidence available to make decisions to provide dietetics professionals with a framework for critical thinking and decision-making', 'Note: Test bank legacy key exception. The Nutrition Care Process (NCP) provides a framework for individualized and systematic care rather than generalized care, making this option the incorrect statement (hence the correct answer to the "not true" prompt).', '["A systematic approach in providing high quality nutrition care","Adopted from Academy of Nutrition and Dietetics","Provides a framework for generalized care, taking into account the patient / client’s needs and values and using the best evidence available to make decisions to provide dietetics professionals with a framework for critical thinking and decision-making","It has application across all practice areas, including community, hospital, and private practice."]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:42.721Z"'::jsonb),
('card-1794233131479-77', NULL, 'deck-1794233131479-g1zf9', 'It is known as the Nutrition and Dietetics Law of 2016.', 'RA 10862', 'Republic Act No. 10862 is formally known as the Nutrition and Dietetics Law of 2016, which repealed older statutes to professionalize and modernize the practice of nutrition and dietetics in the Philippines.', '["RA 10682","RA 10268","RA 81026","RA 10862"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:48.184Z"'::jsonb),
('card-1794233131479-78', NULL, 'deck-1794233131479-g1zf9', '_____ is the form of Vitamin K found in animal products while _____ is the form of Vitamin K in plants.', 'Menaquinone, Phylloquinone', 'Vitamin K1 (phylloquinone) is synthesized primarily by green plants, whereas Vitamin K2 (menaquinones) is synthesized by bacterial flora and found in animal products and fermented foods.', '["Phylloquinone, Menaquinone","Menaquinone, Phylloquinone","Phylloquinone, Phylloquinone","Menaquinone, Menaquinone"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:51.864Z"'::jsonb),
('card-1794233131479-79', NULL, 'deck-1794233131479-g1zf9', 'The following are the causes of iron deficiency anemia, except:', 'Decreased requirement for athletes and pregnant women', 'Athletes and pregnant women experience increased (not decreased) physiological iron requirements, making a decreased requirement incorrect and thus the correct exception among causes of iron deficiency anemia.', '["Decreased requirement for athletes and pregnant women","Inadequate utilization of ferritin","Increase of coffee and tea intake","Increase of dietary iron intake from plants"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:17:56.818Z"'::jsonb),
('card-1794233131479-8', NULL, 'deck-1794233131479-g1zf9', 'The segment of intestine that absorbs most B-vitamins', 'Jejunum', 'The jejunum is the middle segment of the small intestine and serves as the primary site where the vast majority of water-soluble vitamins, minerals, and macronutrients are absorbed.', '["Duodenum","Jejunum","Ileum","All of the above"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:15.017Z"'::jsonb),
('card-1794233131479-80', NULL, 'deck-1794233131479-g1zf9', 'A class of carbohydrates that is also called “functional foods”', 'Oligosaccharides', 'Certain non-digestible oligosaccharides (such as fructooligosaccharides and galactooligosaccharides) act as prebiotics and are classified functionally as "functional foods" supporting gut health.', '["Sucrose","Oligosaccharides","Fructose","Glucose"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:01.475Z"'::jsonb),
('card-1794233131479-81', NULL, 'deck-1794233131479-g1zf9', 'Fats and carbohydrates are called “protein-sparing” due to which of the following?', 'Their presence reduces the need to utilize protein to provide energy', 'Carbohydrates and fats are termed "protein-sparing" because their preferential oxidation for energy reduces the physiological need for the body to catabolize structural or dietary proteins for caloric fuel.', '["They comprise the major proportion of diets","They prevent storage of protein","Their presence reduces the need to utilize protein to provide energy","Protein is not needed when there are carbohydrates and fats"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:06.310Z"'::jsonb),
('card-1794233131479-82', NULL, 'deck-1794233131479-g1zf9', 'Deficiency of this micronutrient is associated with anencephaly', 'Folic acid', 'Maternal deficiency of folic acid during early embryonic development is strongly associated with severe neural tube defects, including anencephaly and spina bifida.', '["Biotin","Vitamin A","Folic acid","Riboflavin"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:10.820Z"'::jsonb),
('card-1794233131479-83', NULL, 'deck-1794233131479-g1zf9', 'The difference between the nitrogen intake and nitrogen excretion', 'Nitrogen Balance', 'Nitrogen balance is calculated as the quantitative difference between total nitrogen intake (protein consumption) and total nitrogen excretion (urine, feces, sweat, and integumentary loss).', '["Amino acid score","Biologic value","Nitrogen Balance","Protein Digestibility"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:15.395Z"'::jsonb),
('card-1794233131479-84', NULL, 'deck-1794233131479-g1zf9', 'The pancreas’ protein splitting enzymes are:', 'Carboxypeptidase and trypsin', 'Trypsin (an endopeptidase) and carboxypeptidase (an exopeptidase) are major proteolytic enzymes secreted by the pancreas into the small intestine to split dietary proteins into smaller peptides and amino acids.', '["Carboxypeptidase and trypsin","Carboxypeptidase and pancreatic amylase","Trypsin and pancreatic lipase","Carboxypeptidase and pancreatic lipase"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:19.993Z"'::jsonb),
('card-1794233131479-85', NULL, 'deck-1794233131479-g1zf9', 'The transportform oflipid associated with low cholesterol levels.', 'HDL', 'High-density lipoprotein (HDL) is the lipoprotein transport vehicle responsible for reverse cholesterol transport, carrying cholesterol away from peripheral tissues back to the liver ("good cholesterol" associated with lower systemic cholesterol accumulation).', '["LDL","HDL","VLDL","IDL"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:26.081Z"'::jsonb),
('card-1794233131479-86', NULL, 'deck-1794233131479-g1zf9', 'Vitamin B12 is absorbed in:', 'Ileum', 'Vitamin B12 absorption requires intrinsic factor secreted by the stomach, with the absorption of the B12-intrinsic factor complex taking place specifically in the terminal ileum.', '["Duodenum","Jejunum","Ileum","Large intestines"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:30.749Z"'::jsonb),
('card-1794233131479-87', NULL, 'deck-1794233131479-g1zf9', 'This is the function of intestinal microvilli:', 'Absorption of nutrients', 'Intestinal microvilli expand the mucosal surface area of the small intestine enormously to maximize the enzymatic digestion and active/passive absorption of nutrients.', '["Production of hydrochloric acid","Production of bile acids","Production of pancreatic enzymes","Absorption of nutrients"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:34.963Z"'::jsonb),
('card-1794233131479-88', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is the primary function of insoluble fiber?', 'Adds stool bulkiness', 'Insoluble dietary fibers (such as cellulose and lignin) do not dissolve in water; they absorb moisture, accelerate transit time, and add physical bulkiness to stool, promoting regular bowel movements.', '["Inhibits cholesterol absorption","Reduces GI of the meal","Adds stool bulkiness","Provides probiotics"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:46.580Z"'::jsonb),
('card-1794233131479-89', NULL, 'deck-1794233131479-g1zf9', 'Statement 1: Spina bifida results from chronic B12 deficiency during pregnancy. Statement 2: Vitamin B12 is absorbed in the duodenum and jejunum.', 'Both statements are incorrect', 'Both statements are false: neural tube defects arise from folate deficiency (not Vitamin B12), and Vitamin B12 is absorbed in the terminal ileum (not the duodenum and jejunum).', '["Only the first statement is correct","Only the second statement is correct","Both statements are correct","Both statements are incorrect"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:51.783Z"'::jsonb),
('card-1794233131479-9', NULL, 'deck-1794233131479-g1zf9', 'It is a wavelike muscular contraction of the GIT that push its contents along', 'Peristalsis', 'Peristalsis describes rhythmic, wave-like circular and longitudinal smooth muscle contractions that automatically propel digestive contents forward through the gastrointestinal tract.', '["Stomach Action","Peristalsis","Segmentation","Sphincter contractions"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:11:19.267Z"'::jsonb),
('card-1794233131479-90', NULL, 'deck-1794233131479-g1zf9', 'The decomposition of one glucose molecule produces how many molecules of ATP?', '38 molecules of ATP', 'Complete aerobic cellular respiration and oxidation of one molecule of glucose through glycolysis, the Krebs cycle, and oxidative phosphorylation yields a theoretical maximum of 38 molecules of ATP (or 30-32 ATP under modern shuttle calculations).', '["38 molecules of ATP","40 molecules of ATP","46 molecules of ATP","48 molecules of ATP"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:18:58.145Z"'::jsonb),
('card-1794233131479-91', NULL, 'deck-1794233131479-g1zf9', 'This is the site of protein synthesis or translation:', 'Rough Endoplasmic Reticulum', 'The rough endoplasmic reticulum (studded with ribosomes) serves as a primary intracellular site for protein synthesis, folding, and post-translational modification.', '["Rough Endoplasmic Reticulum","Cytosol","Lysosome","Ribosome"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:03.952Z"'::jsonb),
('card-1794233131479-92', NULL, 'deck-1794233131479-g1zf9', 'Which of the following has the highest vit C content?', 'Green pepper', 'Among common food items, fresh green peppers (bell peppers) are exceptionally rich sources of ascorbic acid (Vitamin C), far exceeding milk, eggs, or beef.', '["Milk","Beef","Green pepper","Eggs"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:08.759Z"'::jsonb),
('card-1794233131479-93', NULL, 'deck-1794233131479-g1zf9', 'An assessment domain in the NCP that includes evaluation of physical activity.', 'Food / Nutrition-related history', 'Evaluating lifestyle factors, dietary intake patterns, and physical activity levels falls under the Food / Nutrition-related history domain of the Nutrition Care Process.', '["Nutrition-focused physical findings","Biochemical data, medical tests, and procedures","Food / Nutrition-related history","Client history"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:14.262Z"'::jsonb),
('card-1794233131479-94', NULL, 'deck-1794233131479-g1zf9', 'A patient has a protein requirement of 70 g. How much nitrogen would be needed to suffice that?', '437.5 g', 'Note: Test bank legacy key indexing scaling conventions. Dietary protein contains approximately 16% nitrogen (1 ÷ 0.16 = 6.25). Conversely, calculating total protein mass from nitrogen or evaluating test bank key values yields the indexed legacy figure.', '["437.5 g","11.2 g","280 g","None of the above"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:39.477Z"'::jsonb),
('card-1794233131479-95', NULL, 'deck-1794233131479-g1zf9', 'Which of the following is not an essential amino acid in normal conditions?', 'Glutamine', 'Glutamine is classified as a conditionally essential amino acid because the body can synthesize it endogenously under normal homeostatic conditions, unlike essential amino acids such as threonine, phenylalanine, and tryptophan.', '["Glutamine","Threonine","Phenylalanine","Tryptophan"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:43.830Z"'::jsonb),
('card-1794233131479-96', NULL, 'deck-1794233131479-g1zf9', 'What is the RNI per day for Adult’s fiber according to the PDRI?', '20 – 25 g', 'According to the Philippine Dietary Reference Intakes (PDRI), the recommended daily total dietary fiber intake for healthy adults ranges between 20 and 25 grams.', '["20 – 25 g","25 – 30 g","15 – 20 g","30 – 35 g"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:47.887Z"'::jsonb),
('card-1794233131479-97', NULL, 'deck-1794233131479-g1zf9', '12-carbon fatty acids like lauric acid are classified as:', 'Medium-chain fatty acids', 'Fatty acids containing 6 to 12 carbon atoms (such as lauric acid with 12 carbons, or caprylic/capric acids) are classified chemically as medium-chain fatty acids (MCFAs).', '["Short-chain fatty acids","Medium-chain fatty acids","Long-chain fatty acids","Very long-chain fatty acids"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:51.893Z"'::jsonb),
('card-1794233131479-98', NULL, 'deck-1794233131479-g1zf9', 'Which of the following are the sources of heme iron:', 'Meat', 'Heme iron is found exclusively in animal flesh and muscle tissues (meat, poultry, fish), possessing high bioavailability compared to non-heme plant iron.', '["Meat","Vegetables","Fruits","Mushrooms"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:19:56.891Z"'::jsonb),
('card-1794233131479-99', NULL, 'deck-1794233131479-g1zf9', 'This is the best whole food source of protein content and was initially set as the protein digestibility standard:', 'Egg', 'Whole egg protein possesses an exceptional biological value and amino acid score, making it historically established as the gold standard reference protein and digestibility benchmark in human nutrition science.', '["Casein","Soy","Whey","Egg"]'::jsonb, '["Clinical Nutrition","Interactive Exam","CCC 2026"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 1, '', '{"dueDate":"2026-11-09T14:05:31.479Z","interval":1,"easeFactor":2.5,"repetitions":0}'::jsonb, NULL, '"2026-11-09T14:05:31.479Z"'::jsonb, '"2026-11-09T14:20:00.853Z"'::jsonb),
('card-bio-1', NULL, 'deck-biochem-vitamins', 'Wernicke-Korsakoff syndrome and Beriberi are caused by a severe deficiency of which water-soluble vitamin?', 'Thiamine (Vitamin B1)', 'Thiamine pyrophosphate (TPP) is an essential cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Deficiency impairs cellular aerobic metabolism, leading to dry beriberi (neuropathy), wet beriberi (cardiomegaly/edema), or Wernicke encephalopathy.', '["Thiamine (Vitamin B1)","Riboflavin (Vitamin B2)","Niacin (Vitamin B3)","Pyridoxine (Vitamin B6)"]'::jsonb, '["Vitamins","B1","Deficiency"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:40:49.597Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:40:49.597Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:40:49.688Z"'::jsonb),
('card-bio-2', NULL, 'deck-biochem-vitamins', 'What are the classic "4 Ds" characteristic of severe Pellagra (Niacin / Vitamin B3 deficiency)?', 'Dermatitis, Diarrhea, Dementia, and Death', 'Pellagra presents with the 4 Ds: Photosensitive symmetrical Dermatitis (Casal necklace), Diarrhea, Dementia/delirium, and Death if untreated. 60 mg of dietary tryptophan can synthesize approximately 1 mg of niacin in the liver.', '["Dermatitis, Diarrhea, Dementia, and Death","Dyspnea, Dysphagia, Dysuria, and Dehydration","Dizziness, Depression, Dyspepsia, and Dermatitis","Diplopia, Dysarthria, Dysphagia, and Dysmetria"]'::jsonb, '["Niacin","B3","Pellagra"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:39:05.042Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:39:05.042Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:39:05.119Z"'::jsonb),
('card-bio-3', NULL, 'deck-biochem-vitamins', 'Vitamin C (Ascorbic Acid) is an essential cofactor for which enzymatic reaction during collagen biosynthesis?', 'Hydroxylation of Proline and Lysine residues', 'Ascorbic acid maintains iron in its ferrous (Fe2+) state, serving as a reducing agent for prolyl hydroxylase and lysyl hydroxylase. Without it, defective triple-helix collagen fibers fail to crosslink, leading to Scurvy (fragile capillaries, bleeding gums, impaired wound healing).', '["Hydroxylation of Proline and Lysine residues","Decarboxylation of Glutamate to GABA","Methylation of Homocysteine to Methionine","Transamination of Alanine to Pyruvate"]'::jsonb, '["Vitamin C","Collagen","Enzyme"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:41:27.390Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-12T09:41:27.390Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:41:27.467Z"'::jsonb),
('card-bio-4', NULL, 'deck-biochem-vitamins', 'Where is the Vitamin B12 (Cobalamin) – Intrinsic Factor complex primarily absorbed in the human gastrointestinal tract?', 'Terminal Ileum', 'Dietary B12 binds haptocorrin in saliva/gastric juice, is transferred to gastric parietal cell-secreted Intrinsic Factor (IF) in the duodenum, and the intact B12-IF complex is absorbed via cubam receptors in the Terminal Ileum.', '["Terminal Ileum","Duodenum","Proximal Jejunum","Ascending Colon"]'::jsonb, '["B12","GI","Absorption"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:40:42.833Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:40:42.833Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:40:42.910Z"'::jsonb),
('card-bio-5', NULL, 'deck-biochem-vitamins', 'Which amino acid serves as the biological precursor for endogenous synthesis of Niacin (NAD/NADP)?', 'Tryptophan', 'Tryptophan is converted to nicotinic acid mononucleotide via the kynurenine pathway (requiring Vitamin B6, B2, and iron as cofactors). The conversion ratio is approximately 60 mg of dietary tryptophan = 1 mg of Niacin Equivalent (NE).', '["Tryptophan","Tyrosine","Phenylalanine","Methionine"]'::jsonb, '["Biochemistry","AminoAcids","Niacin"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:41:17.235Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-10-12T09:41:17.235Z"'::jsonb, '"2026-09-23T17:32:05.148Z"'::jsonb, '"2026-10-12T09:41:17.313Z"'::jsonb),
('card-mnt-1', NULL, 'deck-clinical-mnt', 'What is the recommended protein intake for a non-dialysis Chronic Kidney Disease (CKD) patient in Stage 4 (GFR 15–29 mL/min)?', '0.6 to 0.8 g/kg body weight/day', 'For CKD Stages 3–5 (non-dialysis), protein is restricted to 0.6–0.8 g/kg/day to slow renal disease progression and decrease uremic toxin accumulation. Once on hemodialysis, protein requirement increases to 1.2–1.4 g/kg/day due to dialysate losses.', '["0.6 to 0.8 g/kg body weight/day","1.2 to 1.4 g/kg body weight/day","1.5 to 2.0 g/kg body weight/day","0.3 to 0.5 g/kg body weight/day"]'::jsonb, '["CKD","Renal","Protein"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-12T08:58:46.647Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-09T08:58:46.647Z"'::jsonb, '"2026-09-26T14:47:19.752Z"'::jsonb, '"2026-10-09T08:58:46.741Z"'::jsonb),
('card-mnt-2', NULL, 'deck-clinical-mnt', 'What is the maximum osmolarity cutoff for Peripheral Parenteral Nutrition (PPN) infusion to avoid phlebitis?', '900 mOsm/L', 'Peripheral veins can tolerate solutions up to ~900 mOsm/L. Solutions exceeding 900 mOsm/L are hypertonic and must be infused via Central Parenteral Nutrition (CPN / TPN) through a large central vein (e.g., subclavian/jugular) where high blood flow rapidly dilutes the solution.', '["900 mOsm/L","500 mOsm/L","1500 mOsm/L","300 mOsm/L"]'::jsonb, '["Parenteral","Osmolarity","ICU"]'::jsonb, NULL, 'hard', 2, '', '{"dueDate":"2026-10-12T08:58:51.077Z","interval":3,"easeFactor":2.3,"repetitions":2}'::jsonb, '"2026-10-09T08:58:51.077Z"'::jsonb, '"2026-09-26T14:47:19.752Z"'::jsonb, '"2026-10-09T08:58:51.170Z"'::jsonb),
('card-mnt-3', NULL, 'deck-clinical-mnt', 'What is the classic dietary fat to combined carbohydrate + protein ratio used in the Ketogenic Diet for refractory pediatric epilepsy?', '4:1 (or 3:1) ratio', 'The classic ketogenic diet uses a 4:1 ratio of fat (in grams) to combined carbohydrate and protein (in grams), providing ~90% of calories from fat to induce and sustain ketosis, providing ketone bodies (beta-hydroxybutyrate) as the primary cerebral fuel.', '["4:1 (or 3:1) ratio","1:1 ratio","2:1 ratio","5:2 ratio"]'::jsonb, '["Pediatric","Epilepsy","Ketogenic"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-12T08:58:43.667Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-09T08:58:43.667Z"'::jsonb, '"2026-09-26T14:47:19.752Z"'::jsonb, '"2026-10-09T08:58:43.767Z"'::jsonb),
('card-mnt-4', NULL, 'deck-clinical-mnt', 'Which specific storage protein (prolamin) in wheat triggers the autoimmune enteropathy in Celiac Disease?', 'Gliadin', 'Celiac disease is triggered by the ingestion of gluten prolamins: Gliadin in wheat, Secalin in rye, and Hordein in barley. These induce immune-mediated small intestinal mucosal inflammation and villous atrophy.', '["Gliadin","Glutenin","Casein","Zein"]'::jsonb, '["GI","Celiac","Gluten"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-12T08:58:54.785Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-09T08:58:54.785Z"'::jsonb, '"2026-09-26T14:47:19.752Z"'::jsonb, '"2026-10-09T08:58:54.878Z"'::jsonb),
('card-mnt-5', NULL, 'deck-clinical-mnt', 'What sodium limit is recommended in the strict DASH (Dietary Approaches to Stop Hypertension) diet trial?', '1,500 mg/day (Lower limit) or 2,300 mg/day (Standard)', 'The standard DASH diet limits sodium to 2,300 mg/day, while the lower-sodium DASH plan caps sodium at 1,500 mg/day. It emphasizes potassium, calcium, magnesium, fiber, and lean proteins.', '["1,500 mg/day (Lower limit) or 2,300 mg/day (Standard)","500 mg/day","3,500 mg/day","1,000 mg/day max"]'::jsonb, '["Cardiovascular","Hypertension","DASH"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-12T08:58:48.948Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-10-09T08:58:48.948Z"'::jsonb, '"2026-09-26T14:47:19.752Z"'::jsonb, '"2026-10-09T08:58:49.031Z"'::jsonb),
('card-fs-1', NULL, 'deck-foodservice-formulas', 'Using the Hamwi Formula, what is the Ideal Body Weight (IBW) for an adult female who is 5 feet 5 inches tall with a medium frame?', '125 lbs (± 10% for frame size)', 'Hamwi female formula: 100 lbs for the first 5 feet (60 inches) + 5 lbs for every additional inch. For 5 ft 5 in: 100 + (5 × 5) = 125 lbs (range 112.5 – 137.5 lbs).', '["125 lbs (± 10% for frame size)","135 lbs (± 10% for frame size)","115 lbs (± 10% for frame size)","120 lbs (± 10% for frame size)"]'::jsonb, '["Hamwi","IBW","Anthropometrics"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:44:51.392Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:44:51.392Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:44:51.469Z"'::jsonb),
('card-fs-2', NULL, 'deck-foodservice-formulas', 'What is the formula to determine the volume in ounces (fl oz) from a standard portion scoop / dipper number?', '32 ÷ Scoop Number = fluid ounces', 'Scoop/dipper numbers indicate the number of level servings per 1 quart (32 fl oz). For example, a #8 scoop yields 32 ÷ 8 = 4 fl oz (1/2 cup), and a #16 scoop yields 32 ÷ 16 = 2 fl oz (1/4 cup).', '["32 ÷ Scoop Number = fluid ounces","64 ÷ Scoop Number = fluid ounces","16 ÷ Scoop Number = fluid ounces","Scoop Number × 4 = fluid ounces"]'::jsonb, '["FoodService","PortionControl","Scoop"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:45:10.460Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-10-12T09:45:10.460Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:45:10.535Z"'::jsonb),
('card-fs-3', NULL, 'deck-foodservice-formulas', 'If a recipe costs $1.80 per portion to produce and the target Food Cost Percentage is 30%, what is the selling price using the Factor Pricing Method?', '$6.00', 'Markup Factor = 100 ÷ Target Food Cost % = 100 ÷ 30 = 3.333. Selling Price = Raw Food Cost × Markup Factor = $1.80 × 3.333 = $6.00 (Alternatively: $1.80 ÷ 0.30 = $6.00).', '["$6.00","$5.40","$7.20","$4.50"]'::jsonb, '["Pricing","FoodCost","Management"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:43:38.368Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:43:38.368Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:43:38.440Z"'::jsonb),
('card-fs-4', NULL, 'deck-foodservice-formulas', 'What are the physiological fuel values (Atwater General Energy Factors) for Carbohydrates, Protein, Fat, and Alcohol in kcal/gram?', 'Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g', 'Atwater standard energy values account for heat of combustion adjusted for digestibility and urinary nitrogen losses: 4 kcal/g for CHO, 4 kcal/g for PRO, 9 kcal/g for Lipid, and 7 kcal/g for Alcohol.', '["Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g","Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 8 kcal/g | Alcohol: 5 kcal/g","Carb: 3.75 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 9 kcal/g","Carb: 5 kcal/g | Protein: 5 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g"]'::jsonb, '["Atwater","Energy","Macronutrients"]'::jsonb, NULL, 'easy', 2, '', '{"dueDate":"2026-10-13T09:43:59.017Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:43:59.017Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:43:59.094Z"'::jsonb),
('card-fs-5', NULL, 'deck-foodservice-formulas', 'What is the formula for Adjusted Body Weight (ABW) commonly used for obese patients in clinical nutrition calculations?', 'ABW = IBW + 0.25 × (Actual Weight – IBW)', 'In obesity, adipose tissue is approximately 25% metabolically active lean tissue. The ABW formula adds 25% of excess weight above IBW to represent the metabolically active mass.', '["ABW = IBW + 0.25 × (Actual Weight – IBW)","ABW = Actual Weight – 0.50 × IBW","ABW = (Actual Weight + IBW) ÷ 2","ABW = IBW + 0.50 × (Actual Weight – IBW)"]'::jsonb, '["ABW","Clinical","Formulas"]'::jsonb, NULL, 'medium', 2, '', '{"dueDate":"2026-10-13T09:44:05.777Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-10-12T09:44:05.777Z"'::jsonb, '"2026-09-23T17:32:05.181Z"'::jsonb, '"2026-10-12T09:44:05.854Z"'::jsonb),
('card-cphn-2019-1', NULL, 'deck-prc-2019-cphn', 'The section in the program plan that defines the program vision, its significance, program scope, and projected outcome is called', 'program overview', 'The program overview (or executive summary/project prospectus) sets the strategic stage for the entire program plan. It articulates the overarching vision, justifies why the initiative is significant (rationalization based on situational data), defines the operational scope (geographical boundaries, target beneficiaries, timeframe), and outlines the expected long-term outcomes and impacts.', '["A. scheduling","B. methodology","C. recording","D. program overview"]'::jsonb, '["Program Planning","Overview & Scope","Public Health Administration"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Program overview gives the big-picture rationale before detailed operational methodologies and schedules are specified.', '{"dueDate":"2026-11-07T06:00:29.996Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:00:29.996Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:00:29.996Z"'::jsonb),
('card-cphn-2019-10', NULL, 'deck-prc-2019-cphn', 'It refers to any activity, program or project that will contribute to change or improve the nutrition situation.', 'Nutrition intervention', 'A Nutrition Intervention is defined as any purposeful, planned activity, project, or policy designed to improve dietary intake, nutritional status, and health outcomes of an individual or target population.', '["A. Food and nutrition planning","B. Nutrition intervention","C. Food access","D. Food availability"]'::jsonb, '["Nutrition Interventions","Program Planning","Public Health"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Interventions encompass nutrition-specific direct actions (e.g. supplementation, feeding) and nutrition-sensitive structural actions.', '{"dueDate":"2026-11-07T05:42:47.810Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:42:47.810Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:42:47.810Z"'::jsonb),
('card-cphn-2019-100', NULL, 'deck-prc-2019-cphn', 'The researcher want to collect incidence of hypertension in the community. What survey method is to be employed?', 'direct measurement', 'Determining blood pressure status and detecting new cases of hypertension requires direct physiological measurement using standardized, calibrated sphygmomanometers and blood pressure cuffs, as self-reports or interviews are notoriously prone to recall and diagnostic misclassification.', '["A. experimental","B. interview","C. document review","D. direct measurement"]'::jsonb, '["Epidemiology","Survey Methods","Direct Measurement","Hypertension"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Clinical objective diagnoses like hypertension require direct physiological measurement.', '{"dueDate":"2026-11-07T04:51:16.555Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:51:16.555Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:51:16.555Z"'::jsonb),
('card-cphn-2019-101', NULL, 'deck-prc-2019-cphn', 'This is considered as a healthy weight range as per BMI WHO Classification', 'BMI 18.5-24.9', 'Under the WHO International Classification for adult Body Mass Index (BMI): Underweight = < 18.5 kg/m2; Normal / Healthy Weight = 18.5 to 24.9 kg/m2; Overweight = 25.0 to 29.9 kg/m2; Obese = >= 30.0 kg/m2. (Note: Asian cut-offs define normal as 18.5–22.9 kg/m2).', '["A. BMI 18.6-25","B. BMI 25-30","C. BMI 18.5-24.9","D. BMI 16 to < 18.5"]'::jsonb, '["Anthropometry","BMI","WHO Cut-offs","Nutritional Status"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. WHO international normal weight standard = 18.5–24.9 kg/m2.', '{"dueDate":"2026-11-07T06:07:56.694Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:07:56.694Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:07:56.694Z"'::jsonb),
('card-cphn-2019-102', NULL, 'deck-prc-2019-cphn', 'The period characterized by slowing down of growth and body changes occur gradually is ________', 'school age', 'The school-age period (middle childhood, ages 6 to 12 years) is characterized by a latent, steady, and gradual rate of linear growth and weight gain (average 2–3 kg and 5–6 cm per year), in contrast to the rapid acceleration observed in infancy and pubertal adolescence.', '["A. school age","B. infancy","C. young infancy","D. adolescents"]'::jsonb, '["Growth & Development","School-age Child","Growth Velocity"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. School-age childhood = steady, gradual latent growth between the two major growth spurts.', '{"dueDate":"2026-11-07T04:49:38.274Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:49:38.274Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:49:38.274Z"'::jsonb),
('card-cphn-2019-103', NULL, 'deck-prc-2019-cphn', 'The study of the distribution and determinants of health-related states or events in specified populations, and the application of this study to the control of health problems is ________', 'epidemiology', 'This is John M. Last''s definitive and globally recognized definition of Epidemiology, adopted by the WHO, CDC, and public health curricula worldwide.', '["A. cross-sectional","B. cohort","C. epidemiology","D. case control"]'::jsonb, '["Epidemiology","Public Health Definition","Biostatistics"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Margin handwritten note: ''control of disease''. Classic definition of Epidemiology.', '{"dueDate":"2026-11-07T04:40:00.731Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:40:00.731Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:40:00.731Z"'::jsonb),
('card-cphn-2019-104', NULL, 'deck-prc-2019-cphn', 'During pregnancy the major adjustment in energy utilization is a shift in fuel source where ________ is the major fetal fuel.', 'carbohydrates', 'During pregnancy, maternal endocrine changes (placental lactogen, progesterone) induce mild maternal peripheral insulin resistance, sparing glucose for rapid facilitated diffusion across the placenta via GLUT-1 transporters. D-Glucose (carbohydrate) is the primary obligatory metabolic fuel for fetal oxidative metabolism.', '["A. proteins","B. fats","C. carbohydrates","D. iron"]'::jsonb, '["Maternal Nutrition","Fetal Metabolism","Glucose","Pregnancy Physiology"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C. Maternal metabolism shifts to fat oxidation to spare glucose (carbohydrates) for the growing fetus.', '{"dueDate":"2026-11-07T04:53:47.470Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:53:47.470Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:53:47.470Z"'::jsonb),
('card-cphn-2019-105', NULL, 'deck-prc-2019-cphn', 'The integral part of the Philippine Development Plan 2017-2022 which is a results-based plan with SMART results at different levels is the', 'Philippine Plan of Action for Nutrition', 'The Philippine Plan of Action for Nutrition (PPAN 2017–2022) serves as the designated sectoral plan for nutrition integrated directly into the Philippine Development Plan (PDP 2017–2022), framing results-based SMART indicators to accelerate reduction of stunting and wasting.', '["A. Philippine Plan of Action for Nutrition","B. \"Ambisyon 2040\"","C. Health for All Agenda","D. Development Plan of the Philippines"]'::jsonb, '["PPAN","PDP 2017-2022","National Nutrition Planning"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. PPAN 2017-2022 is the results-based nutrition blueprint within the PDP.', '{"dueDate":"2026-11-07T06:28:24.324Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:28:24.324Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:28:24.324Z"'::jsonb)
