INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-cphn-2019-106', NULL, 'deck-prc-2019-cphn', 'What is the act that attempts to bring together the widest possible range of inter-sector allies to raise awareness and participation for the convergence of resources rather than with specific behaviour change?', 'Social mobilization', 'Social Mobilization is defined as a broad-scale participatory process that rallies multiple societal sectors, community organizations, policymakers, and civic allies to pool institutional resources, build public momentum, and create an enabling environment for social change.', '["A. Advocacy","B. Social mobilization","C. Media networks","D. Social marketing"]'::jsonb, '["Social Mobilization","Community Participation","Health Promotion"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Social mobilization engages intersectoral allies and pools resources; social marketing focuses on individual behavior change.', '{"dueDate":"2026-11-07T05:28:45.888Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:28:45.888Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:28:45.888Z"'::jsonb),
('card-cphn-2019-107', NULL, 'deck-prc-2019-cphn', 'The wide variety of activities to "sell" the products, ideas or concepts that involves media and interpersonal channels is ________', 'Promotion', 'In the classic 4 Ps of social marketing (Product, Price, Place, Promotion), Promotion encompasses the diverse range of advertising, public relations, mass media broadcasts, community outreach, and interpersonal communication strategies used to raise awareness and persuade target audiences.', '["A. Price","B. Product","C. Place","D. Promotion"]'::jsonb, '["Social Marketing","Promotion","Nutrition Education"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. The 4 Ps of social marketing: Product, Price, Place, and Promotion.', '{"dueDate":"2026-11-07T05:42:15.789Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:42:15.789Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:42:15.789Z"'::jsonb),
('card-cphn-2019-108', NULL, 'deck-prc-2019-cphn', 'When year was the Food Fortification Law of the Philippines enacted?', '2000', 'Republic Act No. 8976, known as the ''Philippine Food Fortification Act of 2000'', was signed into law on November 7, 2000. It instituted mandatory fortification of staple foods (rice with iron, wheat flour with iron and vitamin A, cooking oil and refined sugar with vitamin A).', '["A. 1999","B. 2001","C. 2000","D. 1998"]'::jsonb, '["Philippine Laws","RA 8976","Food Fortification","Legislation"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. RA 8976 enacted in 2000. Mandates fortification of staples and voluntary Sangkap Pinoy seal.', '{"dueDate":"2026-11-07T06:27:22.050Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:27:22.050Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:27:22.050Z"'::jsonb),
('card-cphn-2019-109', NULL, 'deck-prc-2019-cphn', 'Maternal ________ is associated with babies with low weight (<2500 g) at birth.', 'iron deficiency', 'Maternal iron deficiency and iron-deficiency anemia in pregnancy impair uteroplacental perfusion, oxygenation, and tissue synthesis, significantly increasing the clinical risk of intrauterine growth restriction (IUGR), low birth weight (< 2,500 g), and preterm birth.', '["A. attitude","B. knowledge","C. iron deficiency","D. obesity"]'::jsonb, '["Maternal Nutrition","Iron Deficiency","Low Birth Weight"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Contrast with Item 54: Maternal iron deficiency -> LBW; Maternal obesity -> overweight/macrosomic baby.', '{"dueDate":"2026-11-07T05:44:08.926Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:44:08.926Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:44:08.926Z"'::jsonb),
('card-cphn-2019-11', NULL, 'deck-prc-2019-cphn', 'Which of the following is NOT a major program area of the Philippine Plan of Action for Nutrition for the Year 2011 to 2016?', 'Human resource development', 'Under the PPAN 2011–2016, the core strategic nutrition intervention programs focused on: 1) Infant and Young Child Feeding / Maternal and Child Health, 2) Micronutrient Supplementation, 3) Mandatory and Voluntary Food Fortification, 4) Supplementary Feeding, and 5) Nutrition in Emergencies. Human resource development is an institutional support / enabling mechanism rather than a primary intervention program area.', '["A. Maternal and child health","B. Human resource development","C. Micronutrient supplementation","D. Food fortification"]'::jsonb, '["PPAN","Nutrition Policy","National Nutrition Council"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Distinguish between core nutritional intervention programs (MCH, supplementation, fortification) and general support/capacity building.', '{"dueDate":"2026-11-07T04:55:53.614Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:55:53.614Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:55:53.614Z"'::jsonb),
('card-cphn-2019-110', NULL, 'deck-prc-2019-cphn', 'During the first year, infants increase their height by ________ %.', '50', 'An infant''s average birth length is approximately 50 cm. By 12 months (1 year) of age, the infant reaches an average length of approximately 75 cm. This represents a 25 cm increase, or exactly a 50% increase over birth length.', '["A. 30","B. 20","C. 40","D. 50"]'::jsonb, '["Infant Growth","Growth Velocity","Pediatric Anthropometry"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D. First year linear growth: 50 cm at birth -> 75 cm at 1 year = 50% increase in length. (Weight triples, or increases ~200%).', '{"dueDate":"2026-11-07T04:37:35.400Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:37:35.400Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:37:35.400Z"'::jsonb),
('card-cphn-2019-111', NULL, 'deck-prc-2019-cphn', 'After birth, fetal iron storage diminishes during the period ________ months.', '4 to 6', 'Endogenous neonatal hepatic iron stores established in utero sustain blood volume expansion and tissue growth until 4 to 6 months of age, after which iron stores diminish and dietary complementary foods become imperative.', '["A. 1 to 3","B. 2 to 3","C. 3 to 4","D. 4 to 6"]'::jsonb, '["Infant Nutrition","Iron Stores","Complementary Feeding"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Fetal iron storage diminishes between 4 and 6 months postpartum.', '{"dueDate":"2026-11-07T05:42:05.314Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:42:05.314Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:42:05.314Z"'::jsonb),
('card-cphn-2019-112', NULL, 'deck-prc-2019-cphn', 'Anemia is caused by ________ deficiency/deficiencies. (select the best answer)', 'iron', 'While folate, B12, and protein deficiencies can cause specific forms of anemia, iron deficiency accounts for approximately 50% or more of all anemia cases globally and is the single most prevalent nutritional deficiency worldwide. On the examination paper, option A (iron) is circled as the best answer.', '["A. iron","B. folic","C. protein","D. all of these"]'::jsonb, '["Nutritional Anemia","Iron Deficiency","Micronutrients"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A (iron). Note: Iron is the primary etiology of nutritional anemia; ''select the best answer'' directs to iron.', '{"dueDate":"2026-11-07T05:57:19.087Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:57:19.087Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:57:19.087Z"'::jsonb),
('card-cphn-2019-113', NULL, 'deck-prc-2019-cphn', 'What is the factor in food choices that relates to policies on agricultural subsidies, trade regulations and taxes that enhances individual''s financial capacity to obtain foods?', 'Accessibility', 'Economic access/accessibility refers to whether individuals and households have the purchasing power and financial resources to acquire adequate foods, heavily influenced by fiscal policies, agricultural pricing, subsidies, and trade tariffs. On the exam paper, option B (Accessibility) is circled.', '["A. Marketability","B. Accessibility","C. Affordability","D. Availability"]'::jsonb, '["Food Security","Economic Accessibility","Food Policy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B (Accessibility). Economic accessibility relates directly to purchasing power and food price policies.', '{"dueDate":"2026-11-07T04:45:45.434Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:45:45.434Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:45:45.434Z"'::jsonb),
('card-cphn-2019-114', NULL, 'deck-prc-2019-cphn', 'The products intended to address the nutrients gap that contain one or more dietary ingredients is called ________', 'dietary supplements', 'Dietary Supplements are manufactured products intended to supplement the daily diet and address nutritional gaps, formulated to contain one or more dietary ingredients such as vitamins, minerals, herbs, amino acids, or enzymes in concentrated dosage forms.', '["A. dietary supplements","B. food security","C. foods stability","D. nutrition security"]'::jsonb, '["Dietary Supplements","Public Health Interventions","Nutrition Products"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Dietary supplements bridge nutrient gaps with concentrated vitamins, minerals, or amino acids.', '{"dueDate":"2026-11-07T05:51:02.052Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:51:02.052Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:51:02.052Z"'::jsonb),
('card-cphn-2019-115', NULL, 'deck-prc-2019-cphn', 'The WHO recommendation for daily fruit and vegetable intake is ________ grams.', '400', 'The World Health Organization (WHO) and FAO recommend a minimum consumption of 400 grams (equivalent to five servings of 80 grams each) of fruits and vegetables per day (excluding starchy tubers like potatoes and cassava) to prevent chronic non-communicable diseases.', '["A. 300","B. 600","C. 200","D. 400"]'::jsonb, '["WHO Guidelines","Fruit & Vegetable Intake","NCD Prevention"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. WHO target = minimum 400 grams/day of fruits and vegetables (5 servings).', '{"dueDate":"2026-11-07T06:00:46.606Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:00:46.606Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:00:46.606Z"'::jsonb),
('card-cphn-2019-116', NULL, 'deck-prc-2019-cphn', 'How many indicators are contained in the MDG?', '8', 'The Millennium Development Goals (MDGs, 2000–2015) were structured around 8 overarching Goals. On the examination paper, option C (8) is circled, with a margin note clarifying ''eight goals''. (Technically, the MDG monitoring framework contained 8 goals, 21 targets, and 60 official indicators).', '["A. 18","B. 19","C. 8","D. 9"]'::jsonb, '["MDGs","Global Goals","Public Health Policy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (8). Margin handwritten note: ''eight goals''. The question loosely asks for indicators but options correspond to the 8 MDG goals.', '{"dueDate":"2026-11-07T06:05:57.277Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:05:57.277Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:05:57.277Z"'::jsonb),
('card-cphn-2019-117', NULL, 'deck-prc-2019-cphn', 'Which of the following lays out targets, directions, and priority actions in 2030?', 'Sustainable Development Goals', 'The 2030 Agenda for Sustainable Development, adopted by all UN Member States in 2015, establishes the 17 Sustainable Development Goals (SDGs) with 169 targets to guide global and national priority actions and policies through the year 2030.', '["A. Philippine Development Plan","B. Sustainable Development Goals","C. Sustainable development goals","D. Philippine Plan of Action for Nutrition"]'::jsonb, '["SDGs","2030 Agenda","Global Development Targets"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. The 2030 global development horizon belongs to the UN Sustainable Development Goals.', '{"dueDate":"2026-11-07T05:34:29.933Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:34:29.933Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:34:29.933Z"'::jsonb),
('card-cphn-2019-118', NULL, 'deck-prc-2019-cphn', 'What is the type of monosaccharides that provides energy to the brain?', 'Glucose', 'D-Glucose is the obligate and primary metabolic monosaccharide fuel utilized by the human brain under normal non-fasting physiological conditions, crossing the blood-brain barrier via GLUT-1 transporters to support neuronal oxidative phosphorylation.', '["A. D-fructose","B. Glucose","C. Free sugars","D. Sucrose and D-fructose"]'::jsonb, '["Carbohydrate Metabolism","Brain Energy","Biochemistry","Glucose"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Glucose is the primary fuel for the brain and red blood cells.', '{"dueDate":"2026-11-07T05:43:13.152Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:43:13.152Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:43:13.152Z"'::jsonb),
('card-cphn-2019-119', NULL, 'deck-prc-2019-cphn', 'The Maternal, Neonatal and Child Health and Nutrition guidelines states that the third pre-natal visit of a pregnant woman must be on the ________ weeks.', '32nd', 'Under the DOH Maternal, Neonatal, and Child Health and Nutrition (MNCHN) strategy, pregnant women must receive a minimum of four antenatal care (ANC) visits: 1st visit in 1st trimester (<12 weeks); 2nd visit in 2nd trimester (around 24–28 weeks); 3rd visit in early 3rd trimester (around 32 weeks); and 4th visit in late 3rd trimester (around 36–38 weeks).', '["A. 22nd","B. 26th","C. 18th","D. 32nd"]'::jsonb, '["MNCHN","Antenatal Care","DOH Guidelines","Maternal Health"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D. DOH 4-visit ANC schedule: 1st visit = 1st trimester; 2nd = 2nd trimester (~24-28 wks); 3rd = 32nd week; 4th = 36-38 weeks.', '{"dueDate":"2026-11-07T06:00:19.085Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:00:19.085Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:00:19.085Z"'::jsonb),
('card-cphn-2019-12', NULL, 'deck-prc-2019-cphn', 'The additional daily requirement of folate during pregnancy is', '200', 'According to the Philippine Dietary Reference Intakes (PDRI 2015), the Recommended Energy and Nutrient Intake (RENI) for folate for non-pregnant adult women is 400 mcg DFE/day. Pregnancy requires an additional +200 mcg DFE/day (total 600 mcg DFE/day) to support rapid fetal cell division, uterine enlargement, and prevent neural tube defects (NTDs).', '["A. 175","B. 100","C. 150","D. 200"]'::jsonb, '["PDRI","Maternal Nutrition","Folate","Pregnancy"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Margin handwritten note: ''200 ug. 150ug if lactating''. Non-pregnant RDA: 400 ug; Pregnant: +200 ug (total 600 ug); Lactating: +150 ug (total 550 ug).', '{"dueDate":"2026-11-07T06:26:17.083Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:26:17.083Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:26:17.083Z"'::jsonb),
('card-cphn-2019-120', NULL, 'deck-prc-2019-cphn', 'What is the type of study in which the researcher collects data at one point in time?', 'Cross-sectional', 'A Cross-sectional study (also known as a prevalence study) collects exposure and outcome data from a defined population simultaneously at a single specific point in time, providing a ''snapshot'' of community nutritional status.', '["A. Cross-sectional","B. Observational","C. Experimental","D. Cohort"]'::jsonb, '["Epidemiology","Study Designs","Cross-sectional Study"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Cross-sectional = data collected at a single point in time (prevalence snapshot).', '{"dueDate":"2026-11-07T06:28:08.648Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:28:08.648Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:28:08.648Z"'::jsonb),
('card-cphn-2019-121', NULL, 'deck-prc-2019-cphn', 'A LBW infants may need to catch up ________ fold increase in weight to have optimal growth.', '4', 'Low birth weight (LBW) infants generally require compensatory accelerated growth during infancy, typically reaching a four-fold (4-fold) increase in their initial birth weight by 12 months to achieve appropriate growth percentiles.', '["A. 10","B. 8","C. 14","D. 4"]'::jsonb, '["Infant Growth","Low Birth Weight","Catch-up Growth"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D (4). Reiteration of Item 84 testing the 4-fold weight increase required for LBW catch-up.', '{"dueDate":"2026-11-07T06:25:55.350Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:25:55.350Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:25:55.350Z"'::jsonb),
('card-cphn-2019-122', NULL, 'deck-prc-2019-cphn', 'What is the indicator to assess the severity of Vitamin A deficiency in most age groups in the population?', 'Serum retinol < 0.70 μmol/l', 'According to the World Health Organization (WHO), subclinical Vitamin A Deficiency (VAD) is defined by a serum or plasma retinol concentration of less than 0.70 umol/L (or < 20 ug/dL). A population prevalence of serum retinol < 0.70 umol/L of >= 15% signifies a severe public health problem.', '["A. Serum retinol < 0.70 μmol/l","B. Plasma vitamin A < 80 μmol/l","C. Serum beta catotene < 80 μmol/l","D. Serum retinol >80 μmol/l"]'::jsonb, '["Micronutrient Assessment","Vitamin A Deficiency","Serum Retinol","WHO Cut-offs"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. WHO cutoff: Serum retinol < 0.70 umol/L (< 20 ug/dL) defines Vitamin A deficiency.', '{"dueDate":"2026-11-07T05:31:26.332Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:31:26.332Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:31:26.332Z"'::jsonb),
('card-cphn-2019-123', NULL, 'deck-prc-2019-cphn', 'How many indicators are contained in the Sustainable Development Goals?', '17', 'The United Nations 2030 Agenda consists of 17 Sustainable Development Goals (SDGs). Although the monitoring framework includes 169 targets and 232 official statistical indicators, board exam questions frequently refer to the 17 headline goals.', '["A. 18","B. 19","C. 17","D. 16"]'::jsonb, '["SDGs","Global Goals","UN Agenda 2030"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C (17). Corresponds to the 17 SDG Goals (Goal 2 = Zero Hunger).', '{"dueDate":"2026-11-07T04:48:32.873Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:48:32.873Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:48:32.873Z"'::jsonb),
('card-cphn-2019-124', NULL, 'deck-prc-2019-cphn', 'Food choices at the communal and individual level are influenced by ________', 'all of these', 'Food choices and dietary consumption patterns are determined by a complex interplay of environmental and economic factors, notably physical food availability in the market, geographical accessibility, and economic affordability/purchasing power.', '["A. all of these","B. accessibility","C. availability","D. affordability"]'::jsonb, '["Food Choices","Food Security","Determinants of Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. All three elements (availability, accessibility, affordability) govern community food choices.', '{"dueDate":"2026-11-07T05:05:25.919Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:05:25.919Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:05:25.919Z"'::jsonb),
('card-cphn-2019-125', NULL, 'deck-prc-2019-cphn', 'The addition of a nutrient to a food vehicle commonly consumed by the population to prevent or correct a micronutrient deficiency is ________', 'food fortification', 'Under RA 8976 and WHO/FAO standards, Food Fortification is the addition of essential micronutrients (e.g. vitamin A, iron, iodine) to widely consumed staple foods (food vehicles) to prevent or correct population-wide nutritional deficiencies.', '["A. food enhancers","B. food preparation","C. food fortification","D. food additives"]'::jsonb, '["Food Fortification","RA 8976","Public Health Interventions"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Food Fortification adds micronutrients to staple vehicles to correct population deficiencies.', '{"dueDate":"2026-11-07T06:12:06.819Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:12:06.819Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:12:06.819Z"'::jsonb),
('card-cphn-2019-126', NULL, 'deck-prc-2019-cphn', 'The activities that aim to prevent diseases in populations before they occur is ________', 'Primary Prevention', 'Primary Prevention intervenes before the onset of disease or pathological changes occur, through health promotion, immunization, universal food fortification, clean water/sanitation, and dietary education to eliminate underlying risk factors.', '["A. Preventive health","B. First aid","C. Primary Prevention","D. Early signs"]'::jsonb, '["Levels of Prevention","Primary Prevention","Public Health"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Primary prevention = prevents disease before occurrence; Secondary = early screening/treatment; Tertiary = rehabilitation.', '{"dueDate":"2026-11-07T06:26:29.345Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:26:29.345Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:26:29.345Z"'::jsonb),
('card-cphn-2019-127', NULL, 'deck-prc-2019-cphn', 'During pregnancy the additional daily water requirement is ________ ml.', '300', 'According to the Philippine Dietary Reference Intakes (PDRI 2015) and maternal nutrition guidelines, pregnant women require an additional fluid intake of approximately 300 ml/day (about 1 additional cup/glass of water) to support blood volume expansion, amniotic fluid, and fetal circulation.', '["A. 300","B. 100","C. 200","D. 150"]'::jsonb, '["PDRI","Water Requirements","Maternal Nutrition","Pregnancy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. Pregnancy requires +300 ml/day additional water; Lactation requires +700-1000 ml/day.', '{"dueDate":"2026-11-07T05:45:56.537Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:45:56.537Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:45:56.537Z"'::jsonb),
('card-cphn-2019-128', NULL, 'deck-prc-2019-cphn', 'A concrete definition of the major steps taken by an organization to achieve its mission and vision is termed as ________', 'Goal', 'In strategic management, Goals represent the broad, concrete developmental steps and strategic milestones an organization establishes to translate its vision and mission into operational reality. On the exam paper, option C is marked.', '["A. Vision","B. Mission","C. Goal","D. Objectives"]'::jsonb, '["Program Planning","Goals & Objectives","Strategic Management"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (Goal). Goals define the overarching major steps; objectives provide SMART operational targets.', '{"dueDate":"2026-11-07T06:24:14.718Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:24:14.718Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:24:14.718Z"'::jsonb),
('card-cphn-2019-129', NULL, 'deck-prc-2019-cphn', 'The RENI is intended to meet the nutrient needs of ________ people.', 'healthy', 'Recommended Energy and Nutrient Intakes (RENI / PDRI) are explicitly formulated to meet the physiological requirements of practically all (97.5%) healthy individuals in a given population group. They do not apply to individuals suffering from acute illness, severe malnutrition, or therapeutic metabolic disorders.', '["A. nutrient deficient","B. inactive","C. underweight","D. healthy"]'::jsonb, '["RENI","PDRI","Nutritional Standards","Healthy Populations"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. RENI applies strictly to healthy populations, not diseased or therapeutic clinical states.', '{"dueDate":"2026-11-07T06:05:13.781Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:05:13.781Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:05:13.781Z"'::jsonb),
('card-cphn-2019-13', NULL, 'deck-prc-2019-cphn', 'What is the indicator used to describe age-specific mortality rate, morbidity rates, or infant deaths?', 'Demographic', 'Mortality rates (such as infant mortality rate, neonatal mortality, under-five mortality) and morbidity rates broken down by age cohorts are vital demographic statistics and demographic health indicators used to assess population survival and disease burden.', '["A. Nutrition","B. Socio-economic","C. Health","D. Demographic"]'::jsonb, '["Epidemiology","Demographic Indicators","Vital Statistics"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D (Demographic). While closely tied to public health status, mortality/fertility/migration rates are fundamentally categorized as demographic indicators.', '{"dueDate":"2026-11-07T05:05:14.895Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:05:14.895Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:05:14.895Z"'::jsonb),
('card-cphn-2019-130', NULL, 'deck-prc-2019-cphn', 'What is the measure of detecting early changes in body metabolism & nutrition before the appearance of overt clinical signs?', 'Biochemical', 'Biochemical assessment (measuring serum micronutrients, enzyme activities, or urinary metabolites) detects early subclinical alterations in nutritional status and metabolic pathways prior to clinical manifestations.', '["A. Dietary","B. Clinical","C. Biochemical","D. Anthropometry"]'::jsonb, '["Nutrition Assessment","Biochemical Assessment","Subclinical Deficiencies"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Verbatim repeat of Item 53.', '{"dueDate":"2026-11-07T06:07:31.341Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:07:31.341Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:07:31.341Z"'::jsonb),
('card-cphn-2019-131', NULL, 'deck-prc-2019-cphn', 'The average weight gain during the first trimester of pregnancy is ________ kgs.', '1 to 2.3', 'According to the Institute of Medicine (IOM) and Philippine clinical nutrition guidelines, the expected maternal weight gain for a woman with normal pre-pregnancy BMI during the entire first trimester is approximately 1.0 to 2.0 or 2.3 kg (2.2 to 5.0 lbs).', '["A. 2 to 5.6","B. 1 to 3.3","C. 1 to 2.3","D. 1 to 4.3"]'::jsonb, '["Maternal Nutrition","Gestational Weight Gain","First Trimester"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C. First trimester weight gain is minimal (1 to 2.3 kg); rapid gain occurs in 2nd and 3rd trimesters (~0.4 kg/week).', '{"dueDate":"2026-11-07T06:20:46.796Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:20:46.796Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:20:46.796Z"'::jsonb),
('card-cphn-2019-132', NULL, 'deck-prc-2019-cphn', 'The amino acid essential to infants is ________', 'histidine', 'Histidine is well established in nutritional biochemistry as conditionally indispensable (essential) for infants due to immature endogenous biosynthetic pathways. Dietary histidine is required to maintain positive nitrogen balance and normal linear growth in infancy.', '["A. histidine","B. methionine","C. tryptophan","D. lysine"]'::jsonb, '["Biochemistry","Amino Acids","Infant Nutrition","Histidine"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper: Note that Item 152 repeats this exact question stem, where option D was circled on the candidate''s test paper. Histidine is the classic 9th essential amino acid in infants.', '{"dueDate":"2026-11-07T05:34:03.618Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:34:03.618Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:34:03.618Z"'::jsonb),
('card-cphn-2019-133', NULL, 'deck-prc-2019-cphn', 'The detailed operational plans, including budgets, and goals and targets that are specific, measurable, attainable, relevant and time-bound is ________', 'project', 'In program management terminology, a Project is an operational undertaking characterized by defined SMART goals, specific deliverables, assigned budget, and a fixed operational timeframe. On the exam paper, option B is marked.', '["A. strategy","B. project","C. action plan","D. program"]'::jsonb, '["Program Planning","Project Management","SMART Objectives"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B (project). Notice action plan and project share operational definitions; candidate marked B.', '{"dueDate":"2026-11-07T06:27:10.734Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:27:10.734Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:27:10.734Z"'::jsonb),
('card-cphn-2019-134', NULL, 'deck-prc-2019-cphn', 'The Sustainable Development Goals contains ________ goals and targets.', '17', 'The UN 2030 Agenda for Sustainable Development consists of 17 Sustainable Development Goals (SDGs), underpinned by 169 targets.', '["A. 17","B. 18","C. 19","D. 20"]'::jsonb, '["SDGs","Global Goals","UN Agenda 2030"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Reiteration of Item 123 verifying knowledge of the 17 SDGs.', '{"dueDate":"2026-11-07T05:55:40.075Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:55:40.075Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:55:40.075Z"'::jsonb),
('card-cphn-2019-135', NULL, 'deck-prc-2019-cphn', 'The basic principle in planning that refers to the active participation of everybody in the decision making process is ________', 'involvement', 'The principle of Involvement (or participatory planning) asserts that all stakeholders, community representatives, and program implementers must actively participate in identifying priorities and formulating decisions to ensure local ownership and sustainability.', '["A. balance","B. workability","C. comprehensiveness","D. involvement"]'::jsonb, '["Program Planning","Participation","Principle of Involvement"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Planning principles: Involvement = participatory decision-making; Comprehensiveness = covering all necessary elements; Workability = feasibility.', '{"dueDate":"2026-11-07T05:47:57.436Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:47:57.436Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:47:57.436Z"'::jsonb),
('card-cphn-2019-136', NULL, 'deck-prc-2019-cphn', 'What is the global reference diet for adults that is symbolically represented by half a plate of fruits, vegetables and nuts and the other half consists of primarily whole grains, plant proteins, unsaturated plant oils, modest amounts of meat and dairy, and some added sugars and starchy vegetables?', 'Planetary Diet', 'The EAT-Lancet Commission on Food, Planet, Health (2019) introduced the ''Planetary Health Diet''. It establishes a global reference diet designed to nurture human health and stay within environmental planetary boundaries, characterized by a plate where half is fruits, vegetables, and nuts, and half is whole grains, plant-source proteins, and unsaturated oils.', '["A. My Plate","B. Planetary Diet","C. Philippine Food Pyramid","D. Pinggang Pinoy"]'::jsonb, '["Planetary Health Diet","EAT-Lancet","Global Nutrition","Sustainable Diets"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. The EAT-Lancet Commission 2019 Planetary Diet balances human nutritional adequacy with planetary boundaries.', '{"dueDate":"2026-11-07T06:20:34.347Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:20:34.347Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:20:34.347Z"'::jsonb),
('card-cphn-2019-137', NULL, 'deck-prc-2019-cphn', 'This pertains to a public health nutritionist who has communication skills, ranging from writing professional reports to the development of health and nutrition information based on scientific evidences.', 'Administrator', 'The Public Health Nutrition Administrator leads communication systems, translating scientific evidence into health promotion materials, technical program reports, and multi-sector policy briefs.', '["A. Assessor","B. Administrator","C. Researcher","D. Implementer"]'::jsonb, '["Public Health Roles","Administrator","Communication"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Echoes Item 59 regarding administrative and communication competencies of the Public Health Nutritionist.', '{"dueDate":"2026-11-07T06:07:22.496Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:07:22.496Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:07:22.496Z"'::jsonb),
('card-cphn-2019-138', NULL, 'deck-prc-2019-cphn', 'What activity could be done to help the program planners understand their allies, neutral parties, and opponents in order to decide the most feasible route to accomplish their goals?', 'Stakeholder', 'Stakeholder Analysis (option A, ''Stakeholder'') is the strategic planning tool used to systematically identify individuals and groups, analyze their interests, influence, and stance (allies, neutral parties, or opponents), and formulate effective advocacy and coalition strategies.', '["A. Stakeholder","B. Resource generation","C. Audience","D. Manpower"]'::jsonb, '["Program Planning","Stakeholder Analysis","Advocacy"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Stakeholder analysis categorizes allies, neutrals, and opponents to tailor advocacy pathways.', '{"dueDate":"2026-11-07T06:19:07.448Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:19:07.448Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:19:07.448Z"'::jsonb),
('card-cphn-2019-139', NULL, 'deck-prc-2019-cphn', 'Vitamin ________ is required for growth, epithelial integrity and immunity and essential for the maintenance of visual purple for vision in dim light.', 'Vitamin A', 'Vitamin A (11-cis-retinal) conjugates with the protein opsin in retinal rod cells to form Rhodopsin (''visual purple''), the photoreceptor pigment essential for scotopic (dim light) vision. Vitamin A (retinoic acid) also maintains epithelial tissue integrity and cellular immune defense.', '["A. Calcium","B. Zinc","C. Vitamin A","D. Vitamin C"]'::jsonb, '["Micronutrients","Vitamin A","Rhodopsin","Visual Purple"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Rhodopsin (visual purple) = 11-cis retinal + opsin in rods, mediating dim-light adaptation.', '{"dueDate":"2026-11-07T05:43:23.333Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:43:23.333Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:43:23.333Z"'::jsonb),
('card-cphn-2019-14', NULL, 'deck-prc-2019-cphn', 'Human milk has higher proportion of ________ a protein like lactalbumin which has a soft fluorescent curd in the infant''s stomach.', 'whey', 'Human mature milk contains a whey-to-casein ratio of approximately 60:40 (and up to 80:20 in colostrum), compared to bovine milk which is 20:80. The predominant whey protein is alpha-lactalbumin, which forms a soft, flocculent (curd-like), easily digestible precipitate in the infant stomach.', '["A. glucose","B. lactose","C. whey","D. linoleic acid"]'::jsonb, '["Infant Nutrition","Human Milk","Biochemistry","Whey"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (whey). Human milk is predominantly whey (alpha-lactalbumin), forming soft flocculent curds; bovine milk is predominantly curd/casein.', '{"dueDate":"2026-11-07T05:49:03.302Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:49:03.302Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:49:03.302Z"'::jsonb),
('card-cphn-2019-140', NULL, 'deck-prc-2019-cphn', 'Which of the following contains tabulated data on quantities of different nutrients and energy value per 100g per food item?', 'Food Composition Table', 'The Philippine Food Composition Tables (FCT), developed and maintained by the Food and Nutrition Research Institute (FNRI-DOST), provide standardized analytical data on macro- and micronutrient quantities and caloric density per 100 grams edible portion of Philippine foods.', '["A. Green Banner Award","B. Nutritional Guidelines for Filipinos","C. FIVIMS","D. Food Composition Table"]'::jsonb, '["Food Composition Table","FNRI","Dietary Assessment"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. FCT provides proximate, mineral, and vitamin values per 100 g edible portion.', '{"dueDate":"2026-11-07T05:27:52.300Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:27:52.300Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:27:52.300Z"'::jsonb),
('card-cphn-2019-141', NULL, 'deck-prc-2019-cphn', 'What is the Act on Salt Iodization Nationwide popularly known as ASIN Law?', 'R.A. 8172', 'Republic Act No. 8172, enacted on December 20, 1995, is an ''Act for Salt Iodization Nationwide'' (ASIN Law). It mandates the iodization of all salt for human and animal consumption to eliminate Iodine Deficiency Disorders (IDD) in the Philippines.', '["A. R.A. 8172","B. R. A. 7600","C. P.D. 151","D. R. A. 7883"]'::jsonb, '["Philippine Laws","RA 8172","ASIN Law","Iodine Deficiency"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. RA 8172 = ASIN Law (1995); RA 7600 = Rooming-In/Breastfeeding (1992); RA 7883 = Barangay Health Workers Benefits (1995).', '{"dueDate":"2026-11-07T05:06:08.292Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:06:08.292Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:06:08.292Z"'::jsonb),
('card-cphn-2019-142', NULL, 'deck-prc-2019-cphn', 'Which of the following nutrients supplies oxygen from the lungs to the different parts of the body?', 'Iron', 'Iron is the central metal cofactor of the heme moiety within Hemoglobin, the erythrocyte metalloprotein that coordinates molecular oxygen in the pulmonary alveoli and transports it via systemic circulation to peripheral tissues.', '["A. Iron","B. Vitamin D","C. Proteins","D. Fats"]'::jsonb, '["Micronutrients","Iron","Hemoglobin","Oxygen Transport"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Iron in hemoglobin binds oxygen for systemic tissue transport.', '{"dueDate":"2026-11-07T05:28:06.347Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:28:06.347Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:28:06.347Z"'::jsonb),
('card-cphn-2019-143', NULL, 'deck-prc-2019-cphn', 'How many programs does the Philippine Plan of Action for Nutrition 2017 to 2022 compose of?', '12', 'The Philippine Plan of Action for Nutrition (PPAN 2017–2022) comprises exactly 12 strategic programs: 8 Nutrition-Specific programs, 1 Nutrition-Sensitive program cluster, and 3 Enabling support programs (subdivided into 46 specific projects).', '["A. 46","B. 12","C. 26","D. 14"]'::jsonb, '["PPAN","NNC Programs","Nutrition Policy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Margin handwritten note next to A: ''46 Projects''. PPAN structure: 12 Programs and 46 Projects.', '{"dueDate":"2026-11-07T06:20:23.852Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:20:23.852Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:20:23.852Z"'::jsonb),
('card-cphn-2019-144', NULL, 'deck-prc-2019-cphn', 'The world''s time-bound and quantified targets for addressing extreme poverty in its many dimensions while promoting gender equality, education, environmental sustainability and basic human rights by 2030 is the ________', 'Sustainable development goals', 'The Sustainable Development Goals (SDGs), spearheaded by the United Nations, represent the 15-year global commitment (2015–2030) targeting poverty eradication, reduced inequalities, quality education, universal healthcare, and environmental sustainability.', '["A. MDG","B. Sustainable development goals","C. Philippine Development Plan","D. Philippine Plan of Action for Nutrition"]'::jsonb, '["SDGs","Global Goals","UN Agenda 2030"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. 2030 global horizon = Sustainable Development Goals (SDGs). MDGs covered 2000-2015.', '{"dueDate":"2026-11-07T05:46:13.229Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:46:13.229Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:46:13.229Z"'::jsonb),
('card-cphn-2019-145', NULL, 'deck-prc-2019-cphn', 'Translating the PPAN into a dynamic action plan and program at the grassroot level is called ________', 'Barangay Plan of Action for Nutrition', 'In the Philippine decentralized local governance framework, the Barangay Nutrition Committee (BNC) translates national PPAN priorities into local operational reality via the Barangay Nutrition Action Plan (BNAP / BPAN).', '["A. Barangay Plan of Action for Nutrition","B. Investment Plan","C. Provincial Development plan","D. Strategic plan"]'::jsonb, '["Local Governance","BNAP","Barangay Nutrition","PPAN Localization"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Grassroots (barangay) level translation of PPAN = Barangay Nutrition Action Plan (BNAP/BPAN).', '{"dueDate":"2026-11-07T04:49:51.375Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:49:51.375Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:49:51.375Z"'::jsonb),
('card-cphn-2019-146', NULL, 'deck-prc-2019-cphn', 'What is the process of sharing information using different channels?', 'Communication', 'Communication is the interactive process of generating, transmitting, receiving, and interpreting messages, information, and ideas through various interpersonal, print, electronic, and digital channels.', '["A. Diagnosis","B. Problem solving","C. Communication","D. Planning"]'::jsonb, '["Health Promotion","Communication","Social Marketing"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Basic definition of communication in health promotion and social marketing.', '{"dueDate":"2026-11-07T05:06:15.100Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:06:15.100Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:06:15.100Z"'::jsonb),
('card-cphn-2019-147', NULL, 'deck-prc-2019-cphn', 'The interpretation of data to determine whether a person or groups of people are well nourished or malnourished is called ________', 'nutritional assessment', 'Nutritional Assessment is the systematic process of collecting, interpreting, and integrating anthropometric, biochemical, clinical, and dietary information to determine whether individuals or populations are adequately nourished or malnourished.', '["A. dietary diversity","B. food balance sheet","C. dietary intake","D. nutritional assessment"]'::jsonb, '["Nutrition Assessment","Core Principles","Nutritional Status"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Interpretation of nutritional status data = Nutritional Assessment.', '{"dueDate":"2026-11-07T04:48:49.996Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:48:49.996Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:48:49.996Z"'::jsonb),
('card-cphn-2019-148', NULL, 'deck-prc-2019-cphn', 'Among underfive children, 25% are stunted. What is the severity of stunting using the WHO cut-off?', 'High', 'Under the WHO/UNICEF (2018) revised thresholds for public health significance of stunting among children under 5 years: Very Low = < 2.5%; Low = 2.5 to < 10%; Medium = 10 to < 20%; High = 20 to < 30%; Very High = >= 30%. A prevalence of 25% falls directly into the ''High'' severity category.', '["A. Very high","B. High","C. Low","D. Medium"]'::jsonb, '["WHO Cut-offs","Stunting Prevalence","Public Health Severity"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B (High). Under WHO stunting thresholds, 20% to <30% is High; >=30% is Very High.', '{"dueDate":"2026-11-07T05:29:43.134Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:29:43.134Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:29:43.134Z"'::jsonb),
('card-cphn-2019-149', NULL, 'deck-prc-2019-cphn', 'The type of research that employs systematic reviews of several research results and conduct statistical analysis to arrive at a conclusion is', 'Meta - analysis', 'A Meta-Analysis is a high-level quantitative epidemiological study design that pools and statistically integrates the results from multiple independent primary studies identified through a systematic review to generate a single pooled effect size.', '["A. Controlled","B. Meta - analysis","C. Quantitative","D. Mixed"]'::jsonb, '["Evidence-based Nutrition","Meta-analysis","Research Methodology"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Margin handwritten note: ''merging ng findings ng ibang research and may statistical analysis''. Meta-analysis = statistical synthesis of multiple studies.', '{"dueDate":"2026-11-07T06:10:33.352Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:10:33.352Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:10:33.352Z"'::jsonb),
('card-cphn-2019-15', NULL, 'deck-prc-2019-cphn', 'What is the process of integrating nutrition activities with other programs within the same sector?', 'Intra-sectoral', 'Intra-sectoral coordination/integration involves aligning and coordinating nutrition activities among different departments, divisions, or services within the same sectoral agency (e.g., integrating nutrition counseling within the Maternal, Neonatal, and Child Health program inside the Department of Health). Inter-sectoral involves distinct sectors (Health, Agriculture, Social Welfare, Education).', '["A. Intra-sectoral","B. Program plan","C. Monitoring tool","D. Program objectives"]'::jsonb, '["Program Planning","Coordination","Intra-sectoral"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Intra = within the same sector (e.g. within DOH); Inter = between different sectors (e.g. DOH + DA + DSWD).', '{"dueDate":"2026-11-07T06:05:44.371Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:05:44.371Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:05:44.371Z"'::jsonb),
('card-cphn-2019-150', NULL, 'deck-prc-2019-cphn', 'The program and activities of DOH that aims to reduce childhood illnesses and eliminates micronutrient malnutrition.', 'Garantisadong Pambata', 'Garantisadong Pambata (GP) is the institutionalized DOH national child health campaign conducted semiannually to deliver a comprehensive integrated package: Vitamin A capsules, deworming tablets, routine immunizations, iron drops, and infant feeding promotion to under-five children.', '["A. Pinggang Pinoy","B. Sangkap Pinoy Seal","C. Food fortification","D. Garantisadong Pambata"]'::jsonb, '["Garantisadong Pambata","DOH Programs","Child Survival","Micronutrients"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Garantisadong Pambata delivers the biannual integrated package (Vit A + deworming + immunization).', '{"dueDate":"2026-11-07T06:06:39.713Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:06:39.713Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:06:39.713Z"'::jsonb)
