INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-cphn-2019-151', NULL, 'deck-prc-2019-cphn', 'The 24-hour urinary nitrogen is a recovery biomarker for calcium. This statement is ________', 'false', 'This statement is FALSE. 24-hour urinary nitrogen (UUN) is the gold-standard recovery biomarker for dietary PROTEIN intake (since ~80–90% of nitrogen from catabolized dietary protein is excreted in urine as urea), not calcium.', '["A. false","B. maybe true","C. true","D. sometimes false"]'::jsonb, '["Biomarkers","Urinary Nitrogen","Protein Intake","Nutritional Biochemistry"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A (false). 24-hour urinary nitrogen is the recovery biomarker for dietary protein intake.', '{"dueDate":"2026-11-09T06:10:15.630Z","interval":3,"easeFactor":2.5,"repetitions":2}'::jsonb, '"2026-11-06T06:10:15.630Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:10:15.630Z"'::jsonb),
('card-cphn-2019-152', NULL, 'deck-prc-2019-cphn', 'The amino acid essential to infants is ________', 'histidine', 'On this examination paper, option D (''tryptophan'') is circled. In classical biochemistry, histidine (Option A) is widely recognized as the conditionally essential amino acid specific to infants due to rate-limiting biosynthetic capacity. Note candidate circled D here, while Item 132 featured the same question.', '["histidine","lysine","methionine","tryptophan"]'::jsonb, '["Amino Acids","Infant Nutrition","Biochemistry"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D (tryptophan). Candidate marked D on paper; biochemically, Histidine is the conditionally indispensable amino acid for infant growth.', '{"dueDate":"2026-11-07T05:44:40.613Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:44:40.613Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:44:40.613Z"'::jsonb),
('card-cphn-2019-153', NULL, 'deck-prc-2019-cphn', 'A strategy to encourage food manufacturers to fortify their products with one or more nutrients is called the ________', 'Sangkap Pinoy Seal Program', 'The Sangkap Pinoy Seal Program (SPSP) is a voluntary fortification advocacy initiative developed by the Department of Health (DOH) under RA 8976, granting a recognizable seal of quality to processed food products fortified with essential micronutrients (Vitamin A, Iron, or Iodine).', '["A. Sangkap Pinoy Seal Program","B. food additives","C. food enhancers","D. food security"]'::jsonb, '["Sangkap Pinoy Seal","RA 8976","Food Fortification","DOH"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Sangkap Pinoy Seal Program = voluntary fortification seal for processed foods.', '{"dueDate":"2026-11-07T05:44:53.929Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:44:53.929Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:44:53.929Z"'::jsonb),
('card-cphn-2019-154', NULL, 'deck-prc-2019-cphn', 'This pertains to planned actions that are implemented to improve nutrition and well-being of designated groups.', 'Nutrition interventions', 'Nutrition Interventions are purposefully planned and targeted actions designed to positively modify nutritional intake, eating behavior, physiological status, or environmental determinants in specific high-risk groups.', '["A. Nutrition interventions","B. Public health nutrition","C. Developmental nutrition","D. Food production"]'::jsonb, '["Nutrition Interventions","Program Planning","Public Health Principles"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Echoes Item 10 defining nutrition interventions.', '{"dueDate":"2026-11-07T05:37:31.520Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:37:31.520Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:37:31.520Z"'::jsonb),
('card-cphn-2019-155', NULL, 'deck-prc-2019-cphn', 'What is the collegial body of NNC that is chaired by the Secretary of Health with other member agencies?', 'Governing Board', 'The NNC Governing Board is the apex collegial and multi-sectoral policy-making body for nutrition in the country, chaired by the Secretary of Health and composed of heads of 10 executive departments and 3 private sector representatives.', '["A. Governing Board","B. DOH Board of Trustees","C. DOJ","D. NNC Board of Directors"]'::jsonb, '["NNC Governing Board","National Governance","Nutrition Policy"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Highest nutrition policy body in the Philippines is the NNC Governing Board.', '{"dueDate":"2026-11-07T06:07:05.995Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:07:05.995Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:07:05.995Z"'::jsonb),
('card-cphn-2019-156', NULL, 'deck-prc-2019-cphn', 'During infancy the brain reaches ________ % of its adult size at 12 to 24 months.', '75', 'During the first two years of life (the First 1,000 Days), brain development accelerates dramatically: reaching ~50% of adult brain weight by 6 months, ~60–70% by 12 months, and approximately 75% to 80% by 24 months of age, underpinning the urgency of early nutritional protection against stunting.', '["A. 75","B. 45","C. 65","D. 55"]'::jsonb, '["Brain Development","First 1000 Days","Neurodevelopment","Infancy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. Brain reaches ~75% of adult volume/weight by age 2 (24 months).', '{"dueDate":"2026-11-07T06:02:41.904Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:02:41.904Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:02:41.904Z"'::jsonb),
('card-cphn-2019-157', NULL, 'deck-prc-2019-cphn', 'The President can use this document to set policy while avoiding public debate and opposition and it does not require congressional approval.', 'Presidential Decree', 'Historically during the martial law era (1972–1986), the Philippine President issued Presidential Decrees (PDs) having the full force of national law without congressional debate or approval (e.g. PD 491 creating the NNC). In constitutional republics, Executive Orders direct executive operations without congress. On this exam paper, option A is marked.', '["A. Presidential Decree","B. Republic Act","C. Executive Order","D. Executive Order"]'::jsonb, '["Legal Instruments","Presidential Decrees","Governance"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A (Presidential Decree). Historically, PDs bypassed congress (e.g., PD 491, PD 1569). Executive Orders (C/D) also direct policy without legislative passage.', '{"dueDate":"2026-11-07T06:02:52.531Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:02:52.531Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:02:52.531Z"'::jsonb),
('card-cphn-2019-158', NULL, 'deck-prc-2019-cphn', 'The method/s to assess moderate or severe malnutrition among children is/are ________', 'all of these', 'Comprehensive screening and diagnostic evaluation of acute malnutrition in community and clinical settings integrates Mid-Upper Arm Circumference (MUAC < 115 mm for SAM, 115–<125 mm for MAM), assessment of bilateral pitting edema, and head/growth parameters. On the exam paper, option A (all of these) is marked.', '["A. all of these","B. head circumference","C. measure MUAC","D. presence pitting oedema"]'::jsonb, '["Nutritional Assessment","SAM Management","MUAC","Bilateral Pitting Edema"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. MUAC, bilateral pitting edema, and anthropometric indices collectively identify SAM and MAM.', '{"dueDate":"2026-11-07T06:28:45.018Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:28:45.018Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:28:45.018Z"'::jsonb),
('card-cphn-2019-159', NULL, 'deck-prc-2019-cphn', 'What is the award given to a municipality, city, or province that has shown outstanding performance in implementing its local nutrition action plan in the region?', 'Green Banner Award', 'The Green Banner Award (now Green Banner Seal of Compliance under MELLPI Pro) is conferred annually by Regional Nutrition Evaluation Teams (RNET) and the NNC to LGUs (municipality, city, province) that achieve exemplary performance in nutrition program implementation and significant malnutrition reductions.', '["A. Health Sector Reform Agenda","B. Sustansya Para sa Masa","C. MELLPI","D. Green Banner Award"]'::jsonb, '["NNC Awards","Green Banner Award","MELLPI Pro","LGU Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Green Banner Award = highest regional recognition for exemplary LGU nutrition program performance. MELLPI is the evaluation tool.', '{"dueDate":"2026-11-07T04:56:56.117Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:56:56.117Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:56:56.117Z"'::jsonb),
('card-cphn-2019-16', NULL, 'deck-prc-2019-cphn', 'What is the Executive Order that has regulated the marketing of breast milk substitutes or also known as Milk Code of the Philippines.', 'E.O. 51', 'Executive Order No. 51, signed on October 20, 1986 by President Corazon Aquino, is the ''National Code of Marketing of Breastmilk Substitutes, Breastmilk Supplements and Other Related Products'', commonly known as the Philippine Milk Code. It regulates promotional activities, advertising, and donations of formula milk, feeding bottles, and teats.', '["A. E.O. 51","B. E.O. 31","C. E.O. 234","D. E.O. 81"]'::jsonb, '["Philippine Laws","Milk Code","EO 51","Breastfeeding Policy"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. EO 51 = Philippine Milk Code (1986); RA 7600 = Rooming-In and Breastfeeding Act (1992); RA 10028 = Expanded Breastfeeding Promotion Act (2010).', '{"dueDate":"2026-11-07T05:29:48.600Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:29:48.600Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:29:48.600Z"'::jsonb),
('card-cphn-2019-160', NULL, 'deck-prc-2019-cphn', 'What is the term given to a collection of organizational resources that is geared to accomplish a certain major goal and have limited duration and a defined set of deliverables?', 'Plan', 'In project management terminology, a Project is defined as a temporary endeavor with a defined beginning and end, undertaken to meet specific goals with designated deliverables. On the candidate''s exam paper, option C (''Plan'') is marked. Both concepts are central to public health administration.', '["A. Strategic inputs","B. Project","C. Plan","D. Program"]'::jsonb, '["Program Planning","Project Management","Operational Definitions"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (Plan). In classical PMBOK definition, a temporary endeavor with limited duration and defined deliverables is a Project (B); candidate marked C.', '{"dueDate":"2026-11-07T06:29:25.571Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-06T06:29:25.571Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:29:25.571Z"'::jsonb),
('card-cphn-2019-161', NULL, 'deck-prc-2019-cphn', 'The science and art of applying the principles of nutrition to the planning and preparation of foods, and management of the diet in relation to both health and disease.', 'meal planning and mangement', 'Verbatim duplicate of Item 9. On this question, the candidate marked option D (''meal planning and mangement''), while on Item 9 option A (''dietetics'') was marked.', '["A. dietetics","B. public health","C. nutrition care","D. meal planning and mangement"]'::jsonb, '["Dietetics","Meal Management","Professional Practice"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Identical question stem to Item 9 (where A was marked). Highlights the dual emphasis on Dietetics as a discipline and Meal Planning & Management as an applied art.', '{"dueDate":"2026-11-07T06:26:07.443Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:26:07.443Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:26:07.443Z"'::jsonb),
('card-cphn-2019-162', NULL, 'deck-prc-2019-cphn', 'The nutrient that prevents hemorrhagic disease during pregnancy is vitamin ________', 'K', 'Vitamin K is an obligate cofactor for hepatic gamma-glutamyl carboxylase, which carboxylates glutamic acid residues on prothrombin (Factor II) and clotting factors VII, IX, and X. Maternal vitamin K adequacy and newborn intramuscular prophylactic Vitamin K1 (phytomenadione) prevent Hemorrhagic Disease of the Newborn (Vitamin K Deficiency Bleeding / VKDB).', '["A. D","B. K","C. B complex","D. C"]'::jsonb, '["Micronutrients","Vitamin K","VKDB","Maternal & Child Health"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Vitamin K prevents hemorrhagic disease of the newborn (VKDB) via clotting factor activation.', '{"dueDate":"2026-11-07T04:38:40.598Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:38:40.598Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:38:40.598Z"'::jsonb),
('card-cphn-2019-163', NULL, 'deck-prc-2019-cphn', 'The process of collecting information to determine whether activities are implemented as planned is ________', 'Monitoring', 'Monitoring is the routine, continuous tracking of project activities, inputs, and outputs to assess whether activities are being carried out according to the planned schedule, budget, and operational protocols.', '["A. Evaluation","B. Secondary Prevention","C. Monitoring","D. Risk assessment"]'::jsonb, '["Program Planning","Monitoring","Project Tracking"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Monitoring tracks ongoing implementation against plans; Evaluation measures ultimate results and impact.', '{"dueDate":"2026-11-07T06:28:39.303Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:28:39.303Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:28:39.303Z"'::jsonb),
('card-cphn-2019-164', NULL, 'deck-prc-2019-cphn', 'A combination of two anthropometric measurements is called ________', 'index', 'In anthropometric methodology, an Index is formed by combining two raw measurements (such as weight and height to create weight-for-height) or a measurement with a biological variable (such as height and age to form height-for-age).', '["A. underweight","B. index","C. malnutrition","D. dimensions"]'::jsonb, '["Anthropometry","Indices","Nutritional Assessment"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Measurement + Measurement = Index; Index + Cut-off = Indicator. See Item 71.', '{"dueDate":"2026-11-07T04:59:04.554Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:59:04.554Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:59:04.554Z"'::jsonb),
('card-cphn-2019-165', NULL, 'deck-prc-2019-cphn', 'The long range direction that answers the question of what you must focus on to achieve the vision is ________', 'mission', 'A Mission statement clearly articulates the fundamental focus, core activities, and operational purpose of an organization or program to fulfill its long-term Vision.', '["A. program","B. mission","C. strategic goal","D. policy"]'::jsonb, '["Strategic Planning","Mission & Vision","Management"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Verbatim repeat of Item 47.', '{"dueDate":"2026-11-07T05:59:31.813Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:59:31.813Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:59:31.813Z"'::jsonb),
('card-cphn-2019-166', NULL, 'deck-prc-2019-cphn', 'Situation 1 - Nutrition education and other nutrition interventions are implemented in a community-based approach with core programs and services that involve and engage the community - wide participation. The development and utilization of a documented plan will assist the Nutritionist - Dietitian in developing goals, message, and methods in an effective and cohesive way, resulting in better use of resources and more targeted outcomes.

What is your first step in developing your program plan?', 'Know and identify the problem', 'Situation 1 Question 1: Problem identification / situational assessment is invariably the prerequisite first phase of the program planning cycle. Planners must assess local needs, epidemiologic burden, and root causes before setting targets or formulating strategies.', '["A. Develop the strategies","B. Set the objectives","C. Know and identify the problem","D. Mobilize the community"]'::jsonb, '["Situation 1","Program Planning","Situational Analysis"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Reiteration of Item 8 and Item 32 under Situation 1.', '{"dueDate":"2026-11-07T04:56:33.824Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:56:33.824Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:56:33.824Z"'::jsonb),
('card-cphn-2019-167', NULL, 'deck-prc-2019-cphn', 'Situation 1 - In gathering data, you need to collect qualitative data. What are the commonly used methods for gathering qualitative data?', 'Conduct of key informant interviews, focus groups, and participant observation', 'Situation 1 Question 2: Qualitative data collection methodologies in community nutrition research comprise participatory techniques: Key Informant Interviews (KIIs), Focus Group Discussions (FGDs), direct participant observation, and semi-structured community dialogues.', '["A. Taking clinical signs","B. Getting biochemical markers","C. Taking weight and height","D. Conduct of key informant interviews, focus groups, and participant observation"]'::jsonb, '["Situation 1","Qualitative Methods","KII","FGD","Community Assessment"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Qualitative methods capture beliefs, cultural norms, and contextual nuances through KIIs, FGDs, and observation.', '{"dueDate":"2026-11-07T06:04:06.553Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:04:06.553Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:04:06.553Z"'::jsonb),
('card-cphn-2019-168', NULL, 'deck-prc-2019-cphn', 'Situation 1 - What are the most common methods for collecting quantitative data?', 'Getting biochemical markers', 'Situation 1 Question 3: In epidemiological research, surveys with structured questionnaires and standardized measurements yield numerical, prevalence, and incidence data. On the candidate''s examination paper, option B (''Getting biochemical markers'') is marked as a quantitative laboratory method.', '["A. Surveys and questionnaires revealing measurements in numbers or prevalences","B. Getting biochemical markers","C. Taking clinical signs","D. Data on Behaviour"]'::jsonb, '["Situation 1","Quantitative Methods","Biochemical Markers","Surveys"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Note: Option A represents standard community quantitative surveys; examinee marked B.', '{"dueDate":"2026-11-07T06:19:40.183Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:19:40.183Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:19:40.183Z"'::jsonb),
('card-cphn-2019-169', NULL, 'deck-prc-2019-cphn', 'Situation 1 - What is type of data that offers descriptive information that may capture experience, behavior, opinion, value, feeling, knowledge, sensory response, or observable phenomena?', 'Qualitative', 'Situation 1 Question 4: Qualitative data provides rich descriptive, narrative, and contextual insight into human behavior, cultural beliefs, values, emotions, and motivations that cannot be reduced to simple numerical scores.', '["A. Biochemical","B. Anthropometric","C. Quantitative","D. Qualitative"]'::jsonb, '["Situation 1","Research Methodology","Qualitative Data"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Qualitative data = non-numerical descriptive information exploring experiences and beliefs.', '{"dueDate":"2026-11-07T05:07:18.162Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:07:18.162Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:07:18.162Z"'::jsonb),
('card-cphn-2019-17', NULL, 'deck-prc-2019-cphn', 'Which of the following agencies, as member of the NNC Board, that implements the basic needs program as a safety net provision of Republic Act 8435?', 'DA', 'Republic Act No. 8435 is the Agriculture and Fisheries Modernization Act of 1997 (AFMA). The Department of Agriculture (DA) is the lead implementing agency responsible for modernization, food security, and agricultural safety net provisions, and sits on the NNC Governing Board.', '["A. DOJ","B. DBM","C. DOST","D. DA"]'::jsonb, '["Philippine Laws","RA 8435","DA","NNC Board","Food Security"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D. Margin handwritten note: ''promote industrialization agriculture, fisheries''. RA 8435 = AFMA under DA.', '{"dueDate":"2026-11-07T04:57:16.165Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:57:16.165Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:57:16.165Z"'::jsonb),
('card-cphn-2019-170', NULL, 'deck-prc-2019-cphn', 'Situation 1 - What is the step in your project planning where you answer the bottom-line question: Are we getting better, getting worse, or staying the same?', 'Situational analysis', 'Situation 1 Question 5: Situational Analysis evaluates past and present trends to determine community nutritional trajectory—answering whether the population''s nutritional status is improving, deteriorating, or remaining stagnant compared to historical baselines.', '["A. Identifying methods and materials","B. Drawing conclusions","C. Strategic planning","D. Situational analysis"]'::jsonb, '["Situation 1","Program Planning","Situational Analysis","Trends"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D (top of page 17). Situational analysis establishes current status and directional trajectory.', '{"dueDate":"2026-11-07T06:29:05.517Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:29:05.517Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:29:05.517Z"'::jsonb),
('card-cphn-2019-171', NULL, 'deck-prc-2019-cphn', 'Situation 2 - For the first time, a child was seen as having diarrhea and with weight - for- age z score of 2 SD. His height was also < 2SD. After 3 months he was again brought for consultation and you noticed that he was underweight.

Considering the weight of the child, he is diagnosed as ________', 'normal', 'Situation 2 Question 1: On the child''s initial visit, his weight-for-age Z-score was reported at 2 SD (or within the -2 to +2 SD band). Under WHO Child Growth Standards, a Z-score between -2 SD and +2 SD is classified as Normal weight-for-age.', '["A. obese","B. overweight","C. underweight","D. normal"]'::jsonb, '["Situation 2","Anthropometry","Z-Scores","WHO Child Growth Standards"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D (normal). At visit 1, WFA Z-score within +-2 SD denotes normal weight.', '{"dueDate":"2026-11-07T06:27:36.876Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:27:36.876Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:27:36.876Z"'::jsonb),
('card-cphn-2019-172', NULL, 'deck-prc-2019-cphn', 'Situation 2 - For the first time, a child was seen as having diarrhea and with weight - for- age z score of 2 SD. His height was also < 2SD. After 3 months he was again brought for consultation and you noticed that he was underweight.

What is the indicator of nutritional status of the child on his second visit at 3 months?', 'underweight', 'Situation 2 Question 2: The case vignette explicitly specifies: ''After 3 months he was again brought for consultation and you noticed that he was underweight.'' Thus, the diagnosed indicator on the second visit is Underweight.', '["underweight","A. overweight","B. normal","C. underweight"]'::jsonb, '["Situation 2","Nutritional Status","Underweight","Growth Faltering"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C (underweight). Following prolonged diarrhea and illness, the child progressed to underweight.', '{"dueDate":"2026-11-07T05:43:55.706Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:43:55.706Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:43:55.706Z"'::jsonb),
('card-cphn-2019-173', NULL, 'deck-prc-2019-cphn', 'Situation 2 - For the first time, a child was seen as having diarrhea and with weight - for- age z score of 2 SD. His height was also < 2SD. After 3 months he was again brought for consultation and you noticed that he was underweight.

Considering the height of the child, he is considered as ________', 'stunted', 'Situation 2 Question 3: The vignette states that the child''s height was ''< 2SD'' (meaning height-for-age Z-score < -2 SD). By definition, height-for-age < -2 SD is classified as Stunted (chronic linear growth restriction).', '["stunted","A. somewhat tall","B. normal","C. tall"]'::jsonb, '["Situation 2","Anthropometry","Stunting","Height-for-Age"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Height-for-age < -2 SD indicates stunting.', '{"dueDate":"2026-11-07T06:11:57.325Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:11:57.325Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:11:57.325Z"'::jsonb),
('card-cphn-2019-174', NULL, 'deck-prc-2019-cphn', 'Situation 2 - For the first time, a child was seen as having diarrhea and with weight - for- age z score of 2 SD. His height was also < 2SD. After 3 months he was again brought for consultation and you noticed that he was underweight.

What supplement would best be given to the child on his first visit?', 'Vitamin A and Zinc', 'Situation 2 Question 4: Under the Integrated Management of Childhood Illness (IMCI) and DOH/WHO protocols for acute diarrhea, Oral Zinc supplementation (20 mg elemental zinc daily for 10–14 days, or 10 mg for infants < 6 months) accelerates mucosal regeneration and reduces episode severity. High-dose Vitamin A is administered if due or in cases of persistent diarrhea/deficiency.', '["Vitamin A and Zinc","A. Iron","B. Vitamin A and Zinc","C. Vitamin C"]'::jsonb, '["Situation 2","Diarrhea Management","Zinc","Vitamin A","IMCI"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Zinc (10-20 mg/day x 10-14 days) and Vitamin A are standard adjuncts in pediatric diarrhea management.', '{"dueDate":"2026-11-07T05:37:40.296Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:37:40.296Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:37:40.296Z"'::jsonb),
('card-cphn-2019-175', NULL, 'deck-prc-2019-cphn', 'Situation 2 - For the first time, a child was seen as having diarrhea and with weight - for- age z score of 2 SD. His height was also < 2SD. After 3 months he was again brought for consultation and you noticed that he was underweight.

Underweight is considered as ________ of nutritional status.', 'threshold', 'Situation 2 Question 5: In nutritional epidemiology, underweight is broadly an indicator of nutritional status; on the candidate''s examination paper, option C (''threshold'') is marked, highlighting the statistical cut-off/threshold (-2 SD) that defines the classification.', '["threshold","A. indicator","B. cut-off","C. threshold"]'::jsonb, '["Situation 2","Anthropometry","Indicators & Thresholds"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (threshold). Note: In standard terminology, underweight is an indicator established by a statistical threshold (<-2 SD); examinee circled C.', '{"dueDate":"2026-11-07T06:20:13.223Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:20:13.223Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:20:13.223Z"'::jsonb),
('card-cphn-2019-176', NULL, 'deck-prc-2019-cphn', 'Situation 3 - A Nutritionist-Dietitian was employed at the evacuation center, she observed that children are suffering from SAM and have severe diarrhea. The prevalence of underweight is 20 %, stunting, 29%, but overweight among adults is 20%. Many of the infants aged 8 to 11 months are not breastfed because mothers claim that they do not have breastmilk. Many pregnant women are pale, weak and cannot work for an extended time due to fatigue.

What do you do with the children who are suffering from SAM with severe diarrhea?', 'Refer to hospital for in-patient care and management', 'Situation 3 Question 1: Under the Philippine National Guidelines on the Management of Severe Acute Malnutrition (PIMAM), children with Severe Acute Malnutrition (SAM) complicated by medical conditions such as severe diarrhea, dehydration, persistent vomiting, or systemic infection MUST be immediately referred for In-patient Therapeutic Care (stabilization with F-75 formula and medical resuscitation).', '["A. Call the Nurse or Physician in the RHU","B. Refer to hospital for in-patient care and management","C. Do counselling, feed the child and observe the effects","D. Refer to hospital for out-patient care"]'::jsonb, '["Situation 3","PIMAM","SAM Management","Emergency Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Complicated SAM (SAM + severe diarrhea/dehydration) mandates inpatient hospitalization.', '{"dueDate":"2026-11-07T05:05:55.831Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:05:55.831Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:05:55.831Z"'::jsonb),
('card-cphn-2019-177', NULL, 'deck-prc-2019-cphn', 'Situation 3 - What does the 20% prevalence of underweight among children indicates in terms of its magnitude and severity as a public health problem?', 'High', 'Situation 3 Question 2: WHO population-level classification of public health severity for underweight among children under 5: Low: < 10%; Medium: 10% to 19%; High: 20% to 29%; Very High: >= 30%. At exactly 20%, underweight prevalence is classified as ''High''.', '["A. Medium","B. Low","C. High","D. Very high"]'::jsonb, '["Situation 3","WHO Cut-offs","Underweight Severity","Epidemiology"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (High). WHO underweight severity: 20-29% is High.', '{"dueDate":"2026-11-07T06:25:51.809Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:25:51.809Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:25:51.809Z"'::jsonb),
('card-cphn-2019-178', NULL, 'deck-prc-2019-cphn', 'Situation 3 - What does the 29% prevalence of stunting among children indicates in terms of its magnitude and severity as a public health problem?', 'High', 'Situation 3 Question 3: Under WHO criteria, stunting prevalence between 20% and 29% is classified as ''High'' public health significance (>= 30% is Very High; under the 2018 WHO/UNICEF thresholds, 20 to <30% is High). Thus, 29% indicates High severity.', '["A. Medium","B. Very high","C. High","D. Low"]'::jsonb, '["Situation 3","WHO Cut-offs","Stunting Severity","Public Health Thresholds"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (High). WHO stunting severity: 20-29% = High; >=30% = Very High.', '{"dueDate":"2026-11-07T06:27:00.292Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:27:00.292Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:27:00.292Z"'::jsonb),
('card-cphn-2019-179', NULL, 'deck-prc-2019-cphn', 'Situation 3 - What do you advise to mothers with infants who discontinued breastfeeding?', 'Continue breastfeeding while giving appropriate complementary foods', 'Situation 3 Question 4: For infants 8–11 months in emergencies, health workers must support mothers to relactate and continue frequent breastfeeding while introducing nutrient-dense, hygienic complementary foods, protecting against waterborne infection and death in evacuation centers.', '["A. Give appropriate complementary foods","B. Continue breastfeeding while giving appropriate complementary foods","C. Give infants carbohydrates rich foods to increase energy","D. Give foods to infants from the common pot"]'::jsonb, '["Situation 3","IYCF in Emergencies","Relactation","Complementary Feeding"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Counsel on relactation and continued breastfeeding up to 2 years alongside complementary foods.', '{"dueDate":"2026-11-07T06:01:30.166Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:01:30.166Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:01:30.166Z"'::jsonb),
('card-cphn-2019-18', NULL, 'deck-prc-2019-cphn', 'Define what is evaluation?', 'It measures the extent to which the objectives were met', 'Evaluation is the systematic and objective assessment of an ongoing or completed project, program, or policy. Its purpose is to determine the relevance, fulfillment of objectives, developmental efficiency, effectiveness, impact, and sustainability. Option B describes monitoring.', '["A. It describes the community of interest","B. Collecting data to assess whether activities are implemented as planned","C. It is the process of resource generation","D. It measures the extent to which the objectives were met"]'::jsonb, '["Program Planning","Monitoring & Evaluation","Public Health Management"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Monitoring tracks whether activities are carried out as planned; Evaluation determines whether the planned objectives were actually achieved.', '{"dueDate":"2026-11-07T05:41:11.516Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:41:11.516Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:41:11.516Z"'::jsonb),
('card-cphn-2019-180', NULL, 'deck-prc-2019-cphn', 'The paleness, weakness and easy fatigability among women are clinical signs of ________', 'anemia', 'Pallor (paleness of conjunctivae, palms, and mucosal membranes), chronic fatigue, and general weakness are hallmark clinical manifestations of anemia (reduced circulating hemoglobin and systemic tissue hypoxia).', '["A. vitamin A deficiency","B. goiter","C. anemia","D. vitamin C deficiency"]'::jsonb, '["Clinical Nutrition","Anemia","Iron Deficiency","Symptomatology"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Clinical triad of anemia: paleness, fatigue, and muscular weakness.', '{"dueDate":"2026-11-07T05:46:20.328Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:46:20.328Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:46:20.328Z"'::jsonb),
('card-cphn-2019-181', NULL, 'deck-prc-2019-cphn', 'Situation 4 - Manar is 39 years old, pregnant in her 5th month and has a 10 month old female infant. She went to the health facility for her 1st pre-natal check - up and was endorsed to you by the Registered Nurse for nutrition services.

As RND what do you need to do first?', 'Interview on food intake', 'Situation 4 Question 1: In the Nutrition Care Process (NCP) and clinical triage, the RND conducts a dietary assessment / 24-hour food intake recall (dietary interview) to determine actual nutrient intake, eating patterns, and nutritional risks before counseling or prescribing interventions. On the exam paper, option D is marked.', '["A. Review her personal profile","B. Give iron-folate supplements","C. Counsel her on right foods","D. Interview on food intake"]'::jsonb, '["Situation 4","Nutrition Care Process","Dietary Assessment","Maternal Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Assessment precedes intervention: interview on food intake before providing counseling or supplements.', '{"dueDate":"2026-11-07T06:26:01.264Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:26:01.264Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:26:01.264Z"'::jsonb),
('card-cphn-2019-182', NULL, 'deck-prc-2019-cphn', 'Situation 4 - Manar is 39 years old, pregnant in her 5th month and has a 10 month old female infant. She went to the health facility for her 1st pre-natal check - up and was endorsed to you by the Registered Nurse for nutrition services.

What would be your advice?', 'Advise her to take more foods using household measures referring to pinggang pinoy', 'Situation 4 Question 2: In community nutrition education, pregnant women are guided using practical, familiar household measures (cups, tablespoons, fist sizes) integrated with the visual proportions of Pinggang Pinoy for Pregnant and Lactating Women, ensuring practical compliance.', '["Advise her to take more foods using household measures referring to pinggang pinoy","A. Take more vegetables","B. Advice the weight of foods to be taken using pinggang pinoy","C. Advise her to take more foods using household measures referring to pinggang pinoy"]'::jsonb, '["Situation 4","Nutrition Counseling","Pinggang Pinoy","Household Measures"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Use household measures referring to Pinggang Pinoy for accessible community nutrition counseling.', '{"dueDate":"2026-11-07T05:45:41.200Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:45:41.200Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:45:41.200Z"'::jsonb),
('card-cphn-2019-183', NULL, 'deck-prc-2019-cphn', 'Situation 4 - Manar is 39 years old, pregnant in her 5th month and has a 10 month old female infant. She went to the health facility for her 1st pre-natal check - up and was endorsed to you by the Registered Nurse for nutrition services.

How much additional caloric intake would she achieve?', '300', 'Situation 4 Question 3: Manar is in her 5th month of gestation (2nd trimester). According to the Philippine Dietary Reference Intakes (PDRI 2015), the recommended additional daily energy intake during the second and third trimesters of pregnancy is +300 kcal/day.', '["300","A. 360","B. 400","C. 300"]'::jsonb, '["Situation 4","PDRI","Energy Allowance","Pregnancy"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Margin handwritten note: ''pag 3trim +300 +150''. PDRI 2nd & 3rd trimester pregnancy energy allowance = +300 kcal/day.', '{"dueDate":"2026-11-07T05:33:02.381Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:33:02.381Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:33:02.381Z"'::jsonb),
('card-cphn-2019-184', NULL, 'deck-prc-2019-cphn', 'Situation 4 - Manar is 39 years old, pregnant in her 5th month and has a 10 month old female infant. She went to the health facility for her 1st pre-natal check - up and was endorsed to you by the Registered Nurse for nutrition services.

In consideration with her 10 month old child what would you advice since she is no longer breastfeeding?', 'Give nutritious complimentary foods', 'Situation 4 Question 4: For a 10-month-old older infant who is not breastfed, optimal growth requires providing nutrient-dense, hygienic, varied complementary foods (including animal-source foods, legumes, vegetables, and energy-dense staples) along with adequate clean milk feeds.', '["Give nutritious complimentary foods","A. Subject the child for new born screening","B. Maintain the weight of her infant","C. Feed the child with more caloric foods to gain weight"]'::jsonb, '["Situation 4","Complementary Feeding","Infant Nutrition","IYCF"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Provide nutritious complementary foods suited to older infancy (9-11 months).', '{"dueDate":"2026-11-07T04:56:08.427Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:56:08.427Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:14:09.577Z"'::jsonb),
('card-cphn-2019-185', NULL, 'deck-prc-2019-cphn', 'Situation 4 - Manar is 39 years old, pregnant in her 5th month and has a 10 month old female infant. She went to the health facility for her 1st pre-natal check - up and was endorsed to you by the Registered Nurse for nutrition services.

What would be the recommended energy would she achieve for her 10 month old infant?', '630', 'Situation 4 Question 5: Under the Philippine Dietary Reference Intakes (PDRI), the estimated daily energy requirement for an infant aged 9 to 11 months is approximately 630–700 kcal/day (or ~80 kcal/kg/day). Option A (630 kcal) is the target value.', '["630","A. 630","B. 400","C. 500"]'::jsonb, '["Situation 4","PDRI","Infant Energy Requirements","Pediatric Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. PDRI energy requirement for 9-11 months infant = ~630 kcal/day.', '{"dueDate":"2026-11-07T06:20:04.901Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:20:04.901Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:20:04.901Z"'::jsonb),
('card-cphn-2019-186', NULL, 'deck-prc-2019-cphn', 'Situation 5 - A woman aged 60 years went for check-up at the health center because she was weak. She was found to be suffering from chronic energy deficiency, anemia, endemic goiter and has xerophtalmia.

What is her BMI"?', '<18.5', 'Situation 5 Question 1: Chronic Energy Deficiency (CED) in adults is defined by the WHO and FNRI as a Body Mass Index (BMI) of less than 18.5 kg/m2 (Grade I CED: 17.0–18.4; Grade II: 16.0–16.9; Grade III: < 16.0 kg/m2).', '["A. <18.5","B. <20","C. >18.5 to <20.0","D. >18.5"]'::jsonb, '["Situation 5","Chronic Energy Deficiency","BMI","Adult Undernutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Adult CED = BMI < 18.5 kg/m2.', '{"dueDate":"2026-11-07T05:39:10.075Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:39:10.075Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:39:10.075Z"'::jsonb),
('card-cphn-2019-187', NULL, 'deck-prc-2019-cphn', 'Situation 5 - A woman aged 60 years went for check-up at the health center because she was weak. She was found to be suffering from chronic energy deficiency, anemia, endemic goiter and has xerophtalmia.

What is her haemoglobin level in g/L?', '<120', 'Situation 5 Question 2: According to the World Health Organization (WHO) diagnostic thresholds, anemia in non-pregnant adult women (aged 15+ years) is defined by a blood hemoglobin concentration of less than 120 g/L (or < 12.0 g/dL).', '["<120","A. <120","B. 130","C. 120 to <130"]'::jsonb, '["Situation 5","Anemia Cut-offs","Hemoglobin","WHO Standards"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. WHO cutoff: Anemia in non-pregnant women = Hb < 120 g/L (< 12 g/dL); Men = < 130 g/L; Pregnant women = < 110 g/L.', '{"dueDate":"2026-11-07T06:28:32.569Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:28:32.569Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:28:32.569Z"'::jsonb),
('card-cphn-2019-188', NULL, 'deck-prc-2019-cphn', 'Situation 5 - A woman aged 60 years went for check-up at the health center because she was weak. She was found to be suffering from chronic energy deficiency, anemia, endemic goiter and has xerophtalmia. 

Goiter is a deficiency of ________', 'iodine', 'Situation 5 Question 3: Endemic goiter (hyperplasia and hypertrophy of the thyroid gland) is the classic clinical manifestation of chronic Iodine Deficiency Disorders (IDD), caused by compensatory TSH overstimulation in response to insufficient thyroxine (T4) and triiodothyronine (T3) production.', '["iodine","A. calcium","B. iron","C. phosphorous"]'::jsonb, '["Situation 5","Iodine Deficiency","Goiter","Micronutrients"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Goiter results from chronic iodine deficiency (IDD). Addressed by RA 8172 (ASIN Law).', '{"dueDate":"2026-11-07T05:51:06.891Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:51:06.891Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:51:06.891Z"'::jsonb),
('card-cphn-2019-189', NULL, 'deck-prc-2019-cphn', 'Situation 5 - A woman aged 60 years went for check-up at the health center because she was weak. She was found to be suffering from chronic energy deficiency, anemia, endemic goiter and has xerophtalmia.

Xerophtalmia is a deficiency of ________', 'vitamin A', 'Situation 5 Question 4: Xerophthalmia is the clinical hallmark of severe Vitamin A deficiency (VAD), comprising progressive ocular pathologies: night blindness (nyctalopia), conjunctival xerosis, Bitot''s spots, corneal xerosis, corneal ulceration, and keratomalacia.', '["vitamin A","A. vitamin A","B. vitamin C","C. vitamin D"]'::jsonb, '["Situation 5","Vitamin A Deficiency","Xerophthalmia","Micronutrients"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Xerophthalmia = Vitamin A deficiency eye signs.', '{"dueDate":"2026-11-07T06:05:19.235Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:05:19.235Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:05:19.235Z"'::jsonb),
('card-cphn-2019-19', NULL, 'deck-prc-2019-cphn', 'What is the initial breast secretion produced by the post-partum woman?', 'colostrum', 'Colostrum is the yellowish, viscous pre-milk fluid produced by the mammary glands during late pregnancy and the first 2 to 4 days postpartum. It is uniquely high in secretory immunoglobulin A (sIgA), lactoferrin, white blood cells, and epidermal growth factors, acting as the newborn''s first natural immunization.', '["A. colostrum","B. Galactorrhea","C. Breast milk","D. water"]'::jsonb, '["Infant Feeding","Colostrum","Maternal Nutrition","Immunology"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Colostrum is rich in antibodies (sIgA) and protein, lower in fat and lactose than mature breast milk.', '{"dueDate":"2026-11-07T05:55:20.951Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:55:20.951Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:55:20.951Z"'::jsonb),
('card-cphn-2019-190', NULL, 'deck-prc-2019-cphn', 'Situation 5 - A woman aged 60 years went for check-up at the health center because she was weak. She was found to be suffering from chronic energy deficiency, anemia, endemic goiter and has xerophtalmia.

What is the best food - based advice to increase her haemoglobin level?', 'Increase intake of meat, fish and poultry', 'Situation 5 Question 5: Meat, fish, and poultry contain Heme Iron, which is absorbed at a rate of 15–35% (compared to 2–10% for non-heme iron from plant sources) and contains the ''meat protein factor'' that enhances non-heme iron absorption, making it the most potent food-based strategy to treat iron deficiency anemia.', '["Increase intake of meat, fish and poultry","A. Give vitamin D supplements","B. Take calcium","C. Increase intake of meat, fish and poultry"]'::jsonb, '["Situation 5","Heme Iron","Anemia Management","Food-based Interventions"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Meat, fish, and poultry supply highly bioavailable heme iron and enhance non-heme iron absorption.', '{"dueDate":"2026-11-07T05:59:52.966Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:59:52.966Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:59:52.966Z"'::jsonb),
('card-cphn-2019-191', NULL, 'deck-prc-2019-cphn', 'Situation 6 - A pregnant woman on her 1st trimester went to a health facility for consultation. Her weight was on the 75th percentile. Her haemoglobin level was 11.2g/dl while her blood pressure was 140/90.

The act of measuring physical dimensions and body composition is termed as ________', 'anthropometry', 'Situation 6 Question 1: Anthropometry is defined as the scientific technique of taking standardized physical measurements of the human body''s dimensions, proportions, and gross composition (weight, height/stature, skinfolds, and circumferences).', '["A. body dimensions","B. growth and development","C. anthropometry","D. stature"]'::jsonb, '["Situation 6","Anthropometry","Nutritional Assessment"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Anthropometry = systematic measurement of human physical dimensions.', '{"dueDate":"2026-11-07T04:43:18.725Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:43:18.725Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:43:18.725Z"'::jsonb),
('card-cphn-2019-192', NULL, 'deck-prc-2019-cphn', 'Situation 6 - A pregnant woman on her 1st trimester went to a health facility for consultation. Her weight was on the 75th percentile. Her haemoglobin level was 11.2g/dl while her blood pressure was 140/90.

What is her nutritional status?', 'Nutritionally - at - risk', 'Situation 6 Question 2: In the Philippine DOH Maternal Nutrition guidelines, a pregnant woman with clinical hypertension (BP 140/90 mmHg) and high weight percentiles is formally categorized as ''Nutritionally-at-risk'', requiring specialized clinical and dietary management to prevent preeclampsia and adverse maternal-fetal outcomes.', '["Nutritionally - at - risk","A. Nutritionally - at - risk","B. Overweight","C. Normal"]'::jsonb, '["Situation 6","Nutritionally-at-risk","Maternal Health","Hypertension"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. Presence of hypertension (140/90) and borderline lab values classifies her as Nutritionally-at-risk.', '{"dueDate":"2026-11-07T05:42:22.116Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:42:22.116Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:42:22.116Z"'::jsonb),
('card-cphn-2019-193', NULL, 'deck-prc-2019-cphn', 'Situation 6 - A pregnant woman on her 1st trimester went to a health facility for consultation. Her weight was on the 75th percentile. Her haemoglobin level was 11.2g/dl while her blood pressure was 140/90.

Based on haemoglobin level she is suffering from ________', 'anemia', 'Situation 6 Question 3: On the examination paper, option A (''anemia'') is circled. (Note: In clinical epidemiology, WHO defines anemia in pregnancy as Hb < 11.0 g/dL in 1st/3rd trimesters and < 10.5 g/dL in 2nd trimester; at 11.2 g/dL her hemoglobin is borderline/sub-optimal, and the exam question marks A).', '["anemia","A. anemia","B. carbohydrate deficiency","C. iodine deficiency"]'::jsonb, '["Situation 6","Hemoglobin","Anemia in Pregnancy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A (anemia). Examinee circled A based on the clinical prompt assessing hemoglobin status.', '{"dueDate":"2026-11-07T06:09:34.277Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:09:34.277Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:09:34.277Z"'::jsonb),
('card-cphn-2019-194', NULL, 'deck-prc-2019-cphn', 'Situation 6 - A pregnant woman on her 1st trimester went to a health facility for consultation. Her weight was on the 75th percentile. Her haemoglobin level was 11.2g/dl while her blood pressure was 140/90.

Based on blood pressure she is suffering from ________', 'hypertension', 'Situation 6 Question 4: A blood pressure reading of 140/90 mmHg meets the standard clinical diagnostic criteria for Hypertension (systolic BP >= 140 mmHg and/or diastolic BP >= 90 mmHg). In pregnancy, this requires close evaluation for chronic hypertension vs. gestational hypertensive disorders.', '["hypertension","A. iodine deficiency","B. hypertension","C. anemia"]'::jsonb, '["Situation 6","Hypertension","Clinical Assessment","Maternal Health"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Blood pressure >= 140/90 mmHg is diagnostic of hypertension.', '{"dueDate":"2026-11-07T04:53:11.121Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:53:11.121Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:17:36.812Z"'::jsonb),
('card-cphn-2019-195', NULL, 'deck-prc-2019-cphn', 'Situation 6 - A pregnant woman on her 1st trimester went to a health facility for consultation. Her weight was on the 75th percentile. Her haemoglobin level was 11.2g/dl while her blood pressure was 140/90.

What would be your advice on her current nutritional status?', 'follow your calculated dietary prescription with AMDR', 'Situation 6 Question 5: For a nutritionally-at-risk pregnant client presenting with hypertension and high percentile weight, the RND computes an individualized dietary prescription aligning with the Acceptable Macronutrient Distribution Ranges (AMDR), ensuring balanced distribution of carbohydrates (55-75%), protein (10-15%), and fats (15-30%) with sodium restriction.', '["follow your calculated dietary prescription with AMDR","A. consume more calcium to improve her haemoglobin level","B. consume more vegetables","C. consume more fat and vegetables"]'::jsonb, '["Situation 6","Dietary Prescription","AMDR","Medical Nutrition Therapy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D. Follow calculated individualized dietary prescription with AMDR.', '{"dueDate":"2026-11-07T05:09:32.872Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:09:32.872Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:17:45.951Z"'::jsonb),
('card-cphn-2019-196', NULL, 'deck-prc-2019-cphn', 'Situation 7 - In a community Cee, the number of underfive children is 250.
About 100 children have weight - for - age Z score ≤-2SD; 50 have > 2 SD; 60 had +- SD; about 80 have height -for-age <2SD and 40 had > 2SD.

What is the prevalence of underweight?', '40%', 'Situation 7 Question 1: Underweight is defined by weight-for-age Z-score <= -2 SD. Number of underweight children = 100. Total underfive population = 250. Prevalence = (100 / 250) * 100% = 40.0%.', '["A. 28%","B. 40%","C. 45%","D. 30%"]'::jsonb, '["Situation 7","Prevalence Calculation","Underweight","Epidemiology"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B (40%). Calculation: (100 / 250) * 100 = 40%. Margin note: ''underweight''.', '{"dueDate":"2026-11-07T05:08:48.573Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:08:48.573Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:08:48.573Z"'::jsonb)
