INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-cphn-2019-61', NULL, 'deck-prc-2019-cphn', 'What period after birth does infant receives colostrum from the mother?', 'within 24 hrs', 'Colostrum is secreted immediately following birth and is richest during the first 24 hours postpartum. Timely feeding within 24 hours delivers high concentrations of antibodies, lactoferrin, and oligosaccharides essential for gut protection.', '["A. within 24 hrs","B. first week","C. in 3 days","D. In 5 days"]'::jsonb, '["Infant Nutrition","Colostrum","Early Initiation"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Colostrum is immediately available and transferred during early skin-to-skin suckling within 24 hours.', '{"dueDate":"2026-11-07T05:42:35.776Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:42:35.776Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:42:35.776Z"'::jsonb),
('card-cphn-2019-62', NULL, 'deck-prc-2019-cphn', 'What is that document that outlines the decisions of the government to control malnutrition through the various sectors, indicating the precise objectives, targets and plan of action of each sector over a given time frame?', 'Nutrition policy', 'A National Nutrition Policy (or strategic national nutrition plan such as the PPAN) represents the official multi-sectoral government statement and commitment detailing overarching targets, sectoral responsibilities, and specific strategic frameworks to eliminate malnutrition over a specified timeframe.', '["A. Nutrition policy","B. Program objectives","C. Program plan","D. Monitoring tool"]'::jsonb, '["Nutrition Policy","PPAN","Governance"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. Nutrition Policy sets the binding inter-sectoral government priorities and goals.', '{"dueDate":"2026-11-07T06:03:31.267Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:03:31.267Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:03:31.267Z"'::jsonb),
('card-cphn-2019-63', NULL, 'deck-prc-2019-cphn', 'The birth weight of an infant is dependent on ________', 'maternal nutrition', 'Maternal nutritional status—encompassing pre-pregnancy body mass index, micronutrient stores, and appropriate gestational weight gain throughout pregnancy—is the foremost modifiable determinant of fetal growth and birth weight.', '["A. fat intake of the mother","B. physical activity","C. maternal nutrition","D. paternal nutrition"]'::jsonb, '["Maternal Nutrition","Birth Weight","Fetal Development"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Maternal nutrition directly governs placental nutrient transport and fetal intrauterine accretion.', '{"dueDate":"2026-11-07T04:56:43.960Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:56:43.960Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:56:43.960Z"'::jsonb),
('card-cphn-2019-64', NULL, 'deck-prc-2019-cphn', 'Which of the following agencies, as member of the NNC Board, that implements the research programs as basis for program planning?', 'DOST', 'The Department of Science and Technology (DOST), through its attached research agency the Food and Nutrition Research Institute (FNRI-DOST), conducts the periodic National Nutrition Surveys (Expanded National Nutrition Survey / ENNS), generating empirical scientific data that forms the basis for national nutrition planning.', '["A. DOST","B. DA","C. DBM","D. DOJ"]'::jsonb, '["NNC Board","DOST","FNRI","National Nutrition Surveys"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. DOST/FNRI = research and national nutrition surveys; DA = agriculture/food security; DOH = lead chair agency.', '{"dueDate":"2026-11-07T06:26:52.427Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:26:52.427Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:26:52.427Z"'::jsonb),
('card-cphn-2019-65', NULL, 'deck-prc-2019-cphn', 'What is the basic principle in planning that pertains to specific activities and must all be implemented contributing to the achievement of the objectives?', 'comprehensiveness', 'The planning principle of Comprehensiveness dictates that all relevant intervention components, complementary activities, support systems, and resource requirements are systematically incorporated into the program design so they work synergistically toward achieving the objectives.', '["A. workability","B. comprehensiveness","C. involvement workability","D. balance"]'::jsonb, '["Program Planning","Planning Principles","Comprehensiveness"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Comprehensiveness ensures all interrelated actions required to meet the objectives are included in the plan.', '{"dueDate":"2026-11-07T06:08:51.851Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:08:51.851Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:08:51.851Z"'::jsonb),
('card-cphn-2019-66', NULL, 'deck-prc-2019-cphn', 'What is a marker of suboptimal intrauterine growth and poor maternal nutrition; it increases the risks for poorer outcomes in growth, development and health in both the short and the long term?', 'Low birth weight', 'Low Birth Weight (LBW, defined as birth weight < 2,500 grams) is a primary marker of intrauterine growth restriction (IUGR) and/or preterm birth. LBW significantly elevates infant mortality risk, childhood stunting, and the developmental origins of adult chronic disease (Barker hypothesis).', '["A. Low birth weight","B. Maternal CED","C. Poor intake","D. Poor maternal knowledge"]'::jsonb, '["Low Birth Weight","Maternal Nutrition","Intrauterine Growth"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. LBW (< 2500 g) is the clinical marker of poor intrauterine growth and maternal undernutrition.', '{"dueDate":"2026-11-07T05:09:11.357Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:09:11.357Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:09:11.357Z"'::jsonb),
('card-cphn-2019-67', NULL, 'deck-prc-2019-cphn', 'A birth weight below the 10th percentile for gestational age based on a reference population is ________', 'small for gestational age', 'Small-for-Gestational-Age (SGA) is clinically and epidemiologically defined as a birth weight below the 10th percentile for sex and specific completed weeks of gestational age, distinguishing infants with pathological fetal growth restriction from those born early but appropriately sized.', '["A. underweight","B. good birth outcome","C. low birthweight","D. small for gestational age"]'::jsonb, '["Anthropometry","Small for Gestational Age","Pediatric Assessment"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. SGA = birth weight < 10th percentile for gestational age. Low birth weight = < 2500 g regardless of gestational age.', '{"dueDate":"2026-11-07T05:55:08.411Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:55:08.411Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:55:08.411Z"'::jsonb),
('card-cphn-2019-68', NULL, 'deck-prc-2019-cphn', 'The techniques that enhance learning among older adults is called ________', 'Geragogy', 'Geragogy (or eldergogy) refers specifically to the instructional methodologies and educational strategies tailored to the cognitive, sensory, and psychosocial learning needs of older adults (the elderly). Pedagogy refers to teaching children, and andragogy refers to teaching adults in general.', '["A. None","B. Geragogy","C. Andragogy","D. Pedagogy"]'::jsonb, '["Nutrition Education","Geragogy","Pedagogy & Andragogy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Margin handwritten notes: ''geriatric'' next to Geragogy, ''adult'' next to Andragogy, ''children'' next to Pedagogy.', '{"dueDate":"2026-11-07T04:49:18.665Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:49:18.665Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:49:18.665Z"'::jsonb),
('card-cphn-2019-69', NULL, 'deck-prc-2019-cphn', 'Which of the following is one of the major activities in the identification of the causal causes of the nutritional problems?', 'Identification of the causes of the problem', 'In situational analysis and causal analysis (such as constructing a problem tree), systematically identifying immediate, underlying, and root causes is the core analytical activity that determines why the nutritional problem exists.', '["A. Identification of the causes of the problem","B. In-depth quantitative analysis","C. Who are the malnourished","D. What can be done"]'::jsonb, '["Program Planning","Situational Analysis","Causal Analysis"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Causal analysis diagnoses ''why'' malnutrition occurs in the target population.', '{"dueDate":"2026-11-07T05:41:55.640Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:41:55.640Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:41:55.640Z"'::jsonb),
('card-cphn-2019-7', NULL, 'deck-prc-2019-cphn', 'What is the term used to define a situation in which food security is combined with a clean environment, adequate health services, and appropriate care and feeding practices, to ensure a healthy life for all household members?', 'Nutrition security', 'Nutrition Security extends beyond Food Security (which guarantees availability, accessibility, and affordability of food). Nutrition security integrates food security with sanitary environments, clean water, adequate primary healthcare, and optimal maternal and child caring/feeding practices to ensure physiological nutrient utilization for a healthy life.', '["A. Adequate intake","B. Normal nutrition","C. Nutrition security","D. Nutritional status"]'::jsonb, '["Nutrition Security","Food Security","Public Health Framework"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Food security is necessary but not sufficient for nutrition security; sanitation, health, and care practices are the vital third pillar.', '{"dueDate":"2026-11-07T05:33:49.087Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:33:49.087Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:33:49.087Z"'::jsonb),
('card-cphn-2019-70', NULL, 'deck-prc-2019-cphn', 'What is the measure that reflects body composition such as body fat and lean body mass, and is considered a more accurate indicator than height/weight tables?', 'BMI', 'Body Mass Index (BMI = weight in kg / height in m2) is an anthropometric index of weight adjusted for height that correlates closely with total body fatness and adiposity-related health risks across adult populations, offering a standardized measure superior to simple height-weight tables.', '["A. Weight for age z-score","B. Height for age z-score","C. Underweight","D. BMI"]'::jsonb, '["Nutrition Assessment","BMI","Body Composition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. BMI is the universal screening index for adult nutritional status and adiposity.', '{"dueDate":"2026-11-07T05:43:02.029Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:43:02.029Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:43:02.029Z"'::jsonb),
('card-cphn-2019-71', NULL, 'deck-prc-2019-cphn', 'In anthropometric measurement, a combination of an index and a cut-off is called ________', 'indicator', 'In nutritional epidemiology: A raw measurement is an unadjusted value (e.g., weight); an Index is a combination of two measurements or a measurement and age (e.g., weight-for-height); an Indicator is an index combined with a predefined statistical cut-off point used to classify or estimate prevalence (e.g., WFH < -2 SD defines the indicator of wasting).', '["A. undernutrition","B. indicator","C. index","D. malnutrition"]'::jsonb, '["Anthropometry","Indices vs Indicators","Nutritional Assessment"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Margin handwritten note: ''indicator - index + cut-off''. Measurement -> Index -> Indicator.', '{"dueDate":"2026-11-07T05:32:31.247Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:32:31.247Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:32:31.247Z"'::jsonb),
('card-cphn-2019-72', NULL, 'deck-prc-2019-cphn', 'What is the important nutrient that is needed in protein, RNA, and DNA synthesis, cell division, and differentiation?', 'Zinc', 'Zinc is an essential trace element required as a structural and catalytic component of over 300 metalloenzymes, including RNA polymerases, DNA polymerases, and zinc-finger transcription factors that regulate gene expression, cell division, and cellular differentiation.', '["A. Iodine","B. Sodium","C. Magnesium","D. Zinc"]'::jsonb, '["Micronutrients","Zinc","Biochemistry","Cellular Growth"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Zinc is critical for nucleic acid synthesis, cellular proliferation, wound healing, and immune defense.', '{"dueDate":"2026-11-07T05:38:18.851Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:38:18.851Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:38:18.851Z"'::jsonb),
('card-cphn-2019-73', NULL, 'deck-prc-2019-cphn', 'What is the main category of research in which subjects are looked over or are being watched?', 'Observational', 'Observational research encompasses study designs (cohort, case-control, cross-sectional) wherein investigators passively observe exposures, behaviors, and health outcomes in study participants without introducing clinical interventions or experimental manipulations.', '["A. Experimental","B. Cross-sectional","C. Observational","D. Intervention"]'::jsonb, '["Research Methodology","Epidemiology","Observational Studies"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Observational = observing naturally occurring events; Experimental = actively assigning treatments.', '{"dueDate":"2026-11-07T06:03:44.757Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:03:44.757Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:03:44.757Z"'::jsonb),
('card-cphn-2019-74', NULL, 'deck-prc-2019-cphn', 'The desirable weight gain during pregnancy is ________ kgs.', '16.8', 'Institute of Medicine (IOM) and Philippine maternal guidelines recommend total gestational weight gain based on pre-pregnancy BMI: for underweight women (BMI < 18.5), recommended gain is 12.5 to 18.0 kg (averaging around 16–17 kg). On this exam paper, B (16.8 kg) is marked.', '["A. 14.8","B. 16.8","C. 10.8","D. 15.8"]'::jsonb, '["Maternal Nutrition","Gestational Weight Gain","Pregnancy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B (16.8). Note standard IOM ranges: Underweight: 12.5-18 kg; Normal: 11.5-16 kg; Overweight: 7-11.5 kg; Obese: 5-9 kg.', '{"dueDate":"2026-11-07T06:27:26.369Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:27:26.369Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:27:26.369Z"'::jsonb),
('card-cphn-2019-75', NULL, 'deck-prc-2019-cphn', 'The basal metabolic rate during pregnancy is increased by ________ % by the end of the term.', '20 to 25', 'By the late third trimester of pregnancy, maternal Basal Metabolic Rate (BMR) increases by roughly 20% to 25% due to the metabolic demands of the growing fetus, placental active transport, expanded maternal circulatory volume, and increased uterine and cardiac workload.', '["A. 17 to 19","B. 16 to 18","C. 10 to 15","D. 20 to 25"]'::jsonb, '["Maternal Physiology","Pregnancy","Basal Metabolic Rate"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D (20 to 25). Repeated as Item 79 where option B (20 to 25) was marked.', '{"dueDate":"2026-11-07T05:51:12.697Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:51:12.697Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:51:12.697Z"'::jsonb),
('card-cphn-2019-76', NULL, 'deck-prc-2019-cphn', 'Which of the following are the pillars of the sustainable development goals?', 'All of these', 'The United Nations Sustainable Development Goals (SDG) framework is founded upon three interdependent, mutually reinforcing pillars of sustainable development: Economic Growth/Development, Social Inclusion/Development, and Environmental Protection/Sustainability.', '["A. Environmental goals","B. Social development","C. All of these","D. Economic development"]'::jsonb, '["SDGs","Sustainable Development","Global Health Policy"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. The 3 SDG pillars: Economic, Social, and Environmental dimensions.', '{"dueDate":"2026-11-07T04:49:27.655Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:49:27.655Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:49:27.655Z"'::jsonb),
('card-cphn-2019-77', NULL, 'deck-prc-2019-cphn', 'What is the practice of adding an essential micronutrient in a food to improve the nutritional quality and provide a public health benefit with minimal risk to health.', 'Fortification', 'According to the Codex Alimentarius and WHO/FAO guidelines, Food Fortification is the practice of deliberately increasing the content of an essential micronutrient in a food vehicle to improve nutritional quality and provide a public health benefit with minimal health risk.', '["A. Fortification","B. Legal minimum level","C. Nutritional equivalence","D. Maximum tolerable level"]'::jsonb, '["Food Fortification","RA 8976","Micronutrients"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. In the Philippines, governed by RA 8976 (Food Fortification Act of 2000).', '{"dueDate":"2026-11-07T05:38:28.647Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:38:28.647Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:38:28.647Z"'::jsonb),
('card-cphn-2019-78', NULL, 'deck-prc-2019-cphn', 'The ________ mg daily calcium requirement for adolescents is the same for boys and girls.', '1000', 'According to the Philippine Dietary Reference Intakes (PDRI 2015), the Recommended Energy and Nutrient Intake (RENI) for calcium for adolescents aged 10–18 years is 1000 mg/day for both boys and girls to optimize peak bone mass accretion during pubertal growth.', '["A. 800","B. 700","C. 1100","D. 1000"]'::jsonb, '["PDRI","Calcium","Adolescent Nutrition","Bone Health"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled D. Adolescent calcium requirement in PDRI is 1000 mg/day for both sexes.', '{"dueDate":"2026-11-07T05:36:07.065Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:36:07.065Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:36:07.065Z"'::jsonb),
('card-cphn-2019-79', NULL, 'deck-prc-2019-cphn', 'The basal metabolic rate during pregnancy is increased by ________ % by the end of the term.', '20 to 25', 'Maternal basal metabolic rate rises progressively over gestation, peaking in the third trimester at an elevation of 20% to 25% above pre-pregnancy baseline.', '["A. 16 to 18","B. 20 to 25","C. 17 to 19","D. 10 to 15"]'::jsonb, '["Maternal Physiology","Pregnancy","Basal Metabolic Rate"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled B. Exact duplicate of Item 75 testing third-trimester BMR elevation.', '{"dueDate":"2026-11-07T05:48:09.441Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:48:09.441Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:48:09.441Z"'::jsonb),
('card-cphn-2019-8', NULL, 'deck-prc-2019-cphn', 'As a RND, you are task to develop a program plan. What is the first step in developing your plan?', 'Identify the problem', 'The standard community nutrition program planning cycle always initiates with Situation Analysis / Community Assessment to identify and define the nutritional problems, their magnitude, distribution, and root causes before objectives can be formulated or interventions selected.', '["A. Plan for monitoring and evaluation","B. Develop the strategies","C. Identify the problem","D. Set the goals and objectives"]'::jsonb, '["Program Planning","Planning Cycle","Community Assessment"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Order of program planning: 1) Identify/assess the problem -> 2) Set goals & objectives -> 3) Develop strategies/action plan -> 4) Implement -> 5) Monitor & Evaluate.', '{"dueDate":"2026-11-07T04:57:26.027Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:57:26.027Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:57:26.027Z"'::jsonb),
('card-cphn-2019-80', NULL, 'deck-prc-2019-cphn', 'What is the term used to describe the complex disorder involving an excessive amount of body fat?', 'Obesity', 'Obesity is a complex multifactorial disease characterized by excess adiposity resulting from prolonged positive energy balance, predisposing individuals to cardiovascular, endocrine, and metabolic comorbidities.', '["A. Fat deposit","B. Accumulated fat and energy","C. Obesity","D. Adipose tissue"]'::jsonb, '["Nutrition Assessment","Obesity","WHO Definitions"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Verbatim repeat of Item 46.', '{"dueDate":"2026-11-07T05:56:17.399Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:56:17.399Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:56:17.399Z"'::jsonb),
('card-cphn-2019-81', NULL, 'deck-prc-2019-cphn', 'After birth, fetal iron storage is still sufficient until the period of ________ months.', '4 to 6', 'Full-term healthy newborns possess hepatic iron stores accumulated during late pregnancy that satisfy erythropoiesis and tissue requirements for the first 4 to 6 months of life. Beyond 6 months, iron stores deplete, necessitating iron-rich complementary foods.', '["A. 1 to 3","B. 2 to 3","C. 3 to 4","D. 4 to 6"]'::jsonb, '["Infant Nutrition","Iron Stores","Complementary Feeding"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Fetal iron stores last 4-6 months in term infants (shorter in preterm/LBW infants: 2-3 months).', '{"dueDate":"2026-11-07T06:04:32.403Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:04:32.403Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:04:32.403Z"'::jsonb),
('card-cphn-2019-82', NULL, 'deck-prc-2019-cphn', 'The implementation of planned and systematic activities necessary to ensure that products or services meet quality standards is ________', 'quality assurance', 'Quality Assurance (QA) comprises planned, systematic operational and managerial activities implemented within a quality system to provide adequate confidence that health and nutrition services or products satisfy stated standards.', '["A. action plan","B. guidelines","C. procedures","D. quality assurance"]'::jsonb, '["Quality Assurance","Public Health Administration","Standards"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Quality assurance establishes protocols and compliance checks to maintain quality standards.', '{"dueDate":"2026-11-07T05:47:14.775Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:47:14.775Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:47:14.775Z"'::jsonb),
('card-cphn-2019-83', NULL, 'deck-prc-2019-cphn', 'Serum calcium, are tightly controlled metabolically and are poor reflections of dietary intake or nutritional status. This statement is ________', 'true', 'This statement is TRUE. Serum ionized and total calcium concentrations are maintained within strict homeostatic limits (8.5–10.5 mg/dL) by parathyroid hormone (PTH), calcitonin, and calcitriol acting on bone resorption and renal reabsorption. Consequently, serum calcium levels do not reflect dietary calcium intake or bone mineral density.', '["A. false","B. sometimes false","C. true","D. maybe true"]'::jsonb, '["Biochemical Assessment","Calcium Homeostasis","Biomarkers"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (true). Serum calcium reflects homeostatic endocrine regulation, NOT dietary calcium adequacy.', '{"dueDate":"2026-11-07T06:10:16.155Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:10:16.155Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:10:16.155Z"'::jsonb),
('card-cphn-2019-84', NULL, 'deck-prc-2019-cphn', 'A LBW infant may need to catch up ________ fold increase in weight to have optimal growth.', '4', 'Low birth weight (LBW) infants undergo rapid compensatory catch-up growth during the first year of life, frequently quadrupling (4-fold increase) their birth weight by 12 months to converge toward normal developmental centiles.', '["A. 8","B. 14","C. 4","D. 10"]'::jsonb, '["Infant Growth","Low Birth Weight","Catch-up Growth"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C (4). Notice duplicate item appears as Item 121 where option D (4) was marked.', '{"dueDate":"2026-11-07T05:47:26.070Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:47:26.070Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:47:26.070Z"'::jsonb),
('card-cphn-2019-85', NULL, 'deck-prc-2019-cphn', 'Which of these refers to the set of interrelated projects that presents personnel, facilities, budget, equipment and supplies and other items directed to accomplish specific goals and objectives?', 'Program', 'A Program is an organized portfolio of interrelated projects and ongoing activities coordinated with institutional resources (personnel, budget, facilities, equipment) to achieve broad, long-range strategic goals and objectives.', '["A. Policy","B. Program","C. Project","D. Plan"]'::jsonb, '["Program Planning","Program vs Project","Administration"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Hierarchy: Policy -> Plan -> Program -> Project -> Activity.', '{"dueDate":"2026-11-07T06:26:41.059Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:26:41.059Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:26:41.059Z"'::jsonb),
('card-cphn-2019-86', NULL, 'deck-prc-2019-cphn', 'The average increase in height of infants during the first year of life is ________ cm.', '21 to 24', 'During the first year of life, an infant''s length increases substantially from an average birth length of ~50 cm to ~74–75 cm, representing an increment of approximately 24 to 25 cm. On the examination paper, option A (21 to 24 cm) is marked.', '["A. 21 to 24","B. 15 to 20","C. 10 to 15","D. 25 to 30"]'::jsonb, '["Infant Growth","Anthropometry","Growth Velocity"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. Margin handwritten notes: ''pag 1 yr - hanggang 24 cm'', ''pag 2 yrs - 12 cm'', ''pag 3 yrs - 8 cm'', ''4-8 yrs - 5 to 6 cm''.', '{"dueDate":"2026-11-07T06:24:08.857Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:24:08.857Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:24:08.857Z"'::jsonb),
('card-cphn-2019-87', NULL, 'deck-prc-2019-cphn', 'In statistics, the number that occurs most often within a set of number is called the ________', 'mode', 'In descriptive statistics, the Mode is the measure of central tendency defined as the value or category that appears with the greatest frequency in a distribution.', '["A. median","B. mode","C. average","D. mean"]'::jsonb, '["Biostatistics","Central Tendency","Mode"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Mean = arithmetic average; Median = middle value (50th percentile); Mode = most frequent value.', '{"dueDate":"2026-11-07T06:09:10.942Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:09:10.942Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:09:10.942Z"'::jsonb),
('card-cphn-2019-88', NULL, 'deck-prc-2019-cphn', 'The document that details for implementation of the action plan; specific projects are defined is called ________', 'action plan', 'An Action Plan is an operational document that outlines the specific tasks, timelines, responsibilities, resource allocations, and operational procedures necessary to implement strategic objectives and programs.', '["A. project","B. action plan","C. strategy","D. program"]'::jsonb, '["Program Planning","Action Plan","Implementation"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Action plans translate high-level strategies into actionable operational schedules.', '{"dueDate":"2026-11-07T05:35:47.609Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:35:47.609Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:35:47.609Z"'::jsonb),
('card-cphn-2019-89', NULL, 'deck-prc-2019-cphn', 'The proportion for breastfed and non-breastfed children 6 to 23 months who receives solid, semi-solid, or soft foods consumed at the minimum number of times per day.', 'minimum meal frequency', 'Minimum Meal Frequency (MMF) is a core WHO/UNICEF IYCF indicator measuring the proportion of breastfed and non-breastfed children 6–23 months who receive solid, semi-solid, or soft foods (plus milk feeds for non-breastfed) at or above minimum age-specific frequencies (2 times for 6-8 mos, 3 times for 9-23 mos breastfed; 4 times for non-breastfed).', '["A. dietary diversity ratio","B. weight - for - age index","C. height - for - age index","D. minimum meal frequency"]'::jsonb, '["IYCF Indicators","Minimum Meal Frequency","WHO Standards"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. MMF measures feeding frequency/quantity; MDD measures dietary quality/diversity.', '{"dueDate":"2026-11-07T06:19:13.580Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:19:13.580Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:19:13.580Z"'::jsonb),
('card-cphn-2019-9', NULL, 'deck-prc-2019-cphn', 'The science and art of applying the principles of nutrition to the planning and preparation of foods, and management of the diet in relation to both health and disease is', 'dietetics', 'Under Republic Act No. 10862 (Nutrition and Dietetics Law of 2016) and classical professional definitions, Dietetics is the science and art of applying the principles of food and nutrition to the health and wellness of individuals and groups, disease prevention, and dietary management in illness.', '["A. dietetics","B. public health","C. meal planning and mangement","D. nutrition care"]'::jsonb, '["Dietetics","Professional Practice","RA 10862"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Note: Item 161 in this same exam repeats this exact question stem, where option D was circled on the candidate''s test paper.', '{"dueDate":"2026-11-07T06:27:18.563Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:27:18.563Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:27:18.563Z"'::jsonb),
('card-cphn-2019-90', NULL, 'deck-prc-2019-cphn', 'The condition when "all people, at all times, have physical, social and economic access to sufficient, safe and nutritious food which meets their dietary needs and food preferences for an active and healthy life" is termed as ________ security.', 'food', 'This is the universal definition of Food Security adopted at the 1996 World Food Summit by the Food and Agriculture Organization (FAO). It rests on four pillars: availability, access, utilization, and stability.', '["A. economic","B. food","C. nutrition","D. social"]'::jsonb, '["Food Security","FAO Definitions","Public Health Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. FAO 1996 World Food Summit definition of Food Security.', '{"dueDate":"2026-11-07T04:49:05.275Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:49:05.275Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:49:05.275Z"'::jsonb),
('card-cphn-2019-91', NULL, 'deck-prc-2019-cphn', 'What is the term given when planning is done at the national level?', 'Macro level planning', 'Macro-level planning refers to high-level strategic, policy, and budgetary planning conducted at the central or national level (e.g., national development plans, PPAN), whereas micro-level planning occurs at local, municipal, or community levels.', '["A. Macro level planning","B. Joint planning","C. Joint planning","D. Micro level planning"]'::jsonb, '["Program Planning","Macro-level Planning","National Policy"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. Macro-level = national/central; Meso-level = regional/provincial; Micro-level = community/barangay.', '{"dueDate":"2026-11-07T05:28:30.196Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:28:30.196Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:28:30.196Z"'::jsonb),
('card-cphn-2019-92', NULL, 'deck-prc-2019-cphn', 'STATISTICS is the science of conducting studies to.......', 'collect, organize, summarize, analyze, and draw conclusions from data', 'Statistics is formally defined as the scientific discipline concerned with designing studies, and collecting, organizing, presenting, analyzing, and drawing valid inferences and conclusions from numerical data.', '["A. monitor, study, and report on a subject.","B. solve a system of equations","C. hypothesize, experiment, and form conclusions","D. collect, organize, summarize, analyze, and draw conclusions from data"]'::jsonb, '["Biostatistics","Statistics Definition","Research Methodology"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Standard comprehensive textbook definition of statistics.', '{"dueDate":"2026-11-07T04:53:34.334Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:53:34.334Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:53:34.334Z"'::jsonb),
('card-cphn-2019-93', NULL, 'deck-prc-2019-cphn', 'The NNC Governing Board has ________ members who are the Secretaries of different government agencies.', '10', 'Under Executive Order No. 234 and Executive Order No. 472, the National Nutrition Council (NNC) Governing Board includes the heads/Secretaries of 10 key government departments: DOH (Chair), DA (Vice Chair), DILG (Vice Chair), DepEd, DSWD, DOST, DBM, NEDA, DTI, and DOLE, alongside 3 private sector representatives.', '["A. 10","B. 6","C. 8","D. 12"]'::jsonb, '["NNC Governing Board","National Governance","Nutrition Policy"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled A. NNC Governing Board contains 10 Department Secretaries as government agency members.', '{"dueDate":"2026-11-07T06:05:04.466Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T06:05:04.466Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:05:04.466Z"'::jsonb),
('card-cphn-2019-94', NULL, 'deck-prc-2019-cphn', 'What are the interventions that address the underlying determinants of foetal and child nutrition and development?', 'Nutrition sensitive', 'According to the Lancet Commission on Maternal and Child Nutrition and the PPAN: Nutrition-sensitive interventions address the underlying determinants of malnutrition (food security, agriculture, safe water, sanitation, female education, social safety nets); Nutrition-specific interventions address immediate causes (adequate food intake, disease control, micronutrient feeding).', '["A. Burden of nutrition","B. Nutrition sensitive","C. Global interventions","D. Nutrition-specific"]'::jsonb, '["PPAN","Nutrition Sensitive","Lancet Framework","Determinants of Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled B. Margin handwritten note next to D: ''immediate cause''. Nutrition-sensitive = underlying determinants; Nutrition-specific = immediate determinants.', '{"dueDate":"2026-11-07T05:38:41.393Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:38:41.393Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:38:41.393Z"'::jsonb),
('card-cphn-2019-95', NULL, 'deck-prc-2019-cphn', 'What is the daily fluid intake (in ml) of an infant weighing 1000 grams?', '800 to 850', 'In neonatal fluid calculation questions from PRC board examinations, option D (800 to 850 ml or scaled volume per body weight category) is marked on the test paper.', '["A. 900 to 950","B. 1900 to 1950","C. 1000 to 1850","D. 800 to 850"]'::jsonb, '["Pediatric Nutrition","Neonatal Fluids","Preterm Infant Care"]'::jsonb, 'Community and Public Health Nutrition', 'hard', 2, 'Exam paper circled D (800 to 850). Note: Preterm infant maintenance fluid protocols require meticulous titration based on daily weight and renal status.', '{"dueDate":"2026-11-07T05:32:23.590Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:32:23.590Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:32:23.590Z"'::jsonb),
('card-cphn-2019-96', NULL, 'deck-prc-2019-cphn', 'That which inhibits intracellular viral replication is called', 'interferon', 'Interferons (IFN-alpha, IFN-beta, IFN-gamma) are cytokine glycoproteins synthesized and secreted by virus-infected cells. They bind to neighboring cell surface receptors, inducing an antiviral state and activating protein kinase R (PKR) and 2'',5''-oligoadenylate synthetase, which directly degrades viral RNA and inhibits intracellular viral protein translation.', '["A. macrophages","B. lactoferrin","C. interferon","D. lysozymes"]'::jsonb, '["Immunology","Biochemistry","Interferon","Host Defense"]'::jsonb, 'Community and Public Health Nutrition', 'medium', 2, 'Exam paper circled C. Interferons inhibit intracellular viral replication; lactoferrin sequesters iron; lysozyme lyses bacterial peptidoglycan walls.', '{"dueDate":"2026-11-07T05:35:59.461Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:35:59.461Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:35:59.461Z"'::jsonb),
('card-cphn-2019-97', NULL, 'deck-prc-2019-cphn', 'The adolescent growth spurt in boys begins between the ages of ________ years.', '12 and 16', 'The adolescent pubertal growth spurt in boys typically commences between ages 12 and 14 years, peaking between 14 and 16 years (Tanner stage 3–4), which is approximately two years later than in girls (who spurt between ages 10 and 14).', '["A. 7 and 8","B. 8 and 9","C. 9 and 10","D. 12 and 16"]'::jsonb, '["Adolescent Nutrition","Pubertal Growth Spurt","Growth Velocity"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled D. Boys spurt later (12-16 years) and gain greater lean body mass than girls.', '{"dueDate":"2026-11-07T04:54:31.309Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:54:31.309Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:54:31.309Z"'::jsonb),
('card-cphn-2019-98', NULL, 'deck-prc-2019-cphn', 'It pertains to targeted activities in individuals or groups with early signs of disease to prevent progression', 'Early Intervention', 'Early Intervention (corresponding to secondary prevention in public health) involves detecting early, subclinical, or initial pathological signs and delivering prompt targeted clinical and nutritional therapies to halt disease progression and prevent permanent complications.', '["A. Medical assessment","B. Biochemical assessment","C. Early Intervention","D. Nutrition assessment"]'::jsonb, '["Levels of Prevention","Early Intervention","Public Health Nutrition"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled C. Early Intervention = secondary prevention halting progression of identified early signs.', '{"dueDate":"2026-11-07T05:45:06.138Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T05:45:06.138Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T05:45:06.138Z"'::jsonb),
('card-cphn-2019-99', NULL, 'deck-prc-2019-cphn', 'What is the R.A. that was enacted and is known as the "Kalusugan at Nutrisyon ng Mag-Nanay Act"?', '11148', 'Republic Act No. 11148, enacted on November 29, 2018, is officially known as the ''Kalusugan at Nutrisyon ng Mag-Nanay Act''. It scales up maternal and child nutrition programs across the First 1,000 Days of life (from conception up to the child''s second birthday) to end stunting and malnutrition.', '["A. 11148","B. 11418","C. 10048","D. 11481"]'::jsonb, '["Philippine Laws","RA 11148","First 1000 Days","Maternal & Child Health"]'::jsonb, 'Community and Public Health Nutrition', 'easy', 2, 'Exam paper circled A. RA 11148 = Kalusugan at Nutrisyon ng Mag-Nanay Act (First 1,000 Days Law). Landmark legislation in Philippine nutrition.', '{"dueDate":"2026-11-07T06:19:18.444Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T06:19:18.444Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T06:19:18.444Z"'::jsonb),
('card-ffss-2021-1', NULL, 'deck-prc-2021-ffss', 'Garlic, onions and shallots are examples of ___.', 'bulbs', 'Garlic, onions, and shallots are bulbs (underground storage structures consisting of a stem surrounded by fleshy leaves). Sweet potato and cassava are examples of roots and tubers.', '["roots and tubers","shoots","seeds","bulbs"]'::jsonb, '["PRC-2021","FFSS","Plant Foods","Vegetable Classification"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 1. Margin note: Sweet potato = roots & tubers.', '{"dueDate":"2026-11-06T17:30:15.797Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:30:15.797Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:30:15.797Z"'::jsonb),
('card-ffss-2021-10', NULL, 'deck-prc-2021-ffss', 'Where is the best location of a school cafeteria?', 'First floor', 'A first/ground floor location ensures straightforward access for heavy delivery trucks, direct receiving dock connection, efficient trash removal, and safe, barrier-free student access.', '["Adjacent to the auditorium","First floor","Near the principal''s office","At the last floor"]'::jsonb, '["PRC-2021","FFSS","Facility Planning","Layout & Design"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 10. Facility layout and receiving logistics.', '{"dueDate":"2026-11-06T17:28:31.744Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:28:31.744Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:28:31.744Z"'::jsonb),
('card-ffss-2021-100', NULL, 'deck-prc-2021-ffss', 'Identify a wild berry which can be found in the Philippines.', 'Mulberry', 'Mulberries (genus Morus) and Philippine wild raspberries (sampinit / Rubus rosifolius) grow readily in the Philippine highlands. Acai and Maqui are South American; Atis is a sugar apple (custard fruit).', '["Atis","Acai","Mulberry","Maqui"]'::jsonb, '["PRC-2021","FFSS","Philippine Fruits","Botany"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 100. Local berry flora: Mulberry / Sampinit.', '{"dueDate":"2026-11-07T04:13:01.316Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:13:01.316Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:13:01.316Z"'::jsonb),
('card-ffss-2021-101', NULL, 'deck-prc-2021-ffss', 'The desirable pink color in cured meat is due to:', 'Nitroso myoglobin', 'When nitrite is added to curing brine, it converts to nitric oxide and binds to reduced myoglobin to form nitrosomyoglobin, which converts into stable pink nitrosohemochrome upon heating.', '["Metmyoglobin","Oxymyoglobin","Hemoglobin","Nitroso myoglobin"]'::jsonb, '["PRC-2021","FFSS","Meat Science","Food Chemistry"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 101. Cured meat pigment = Nitrosomyoglobin.', '{"dueDate":"2026-11-06T17:07:55.635Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:07:55.635Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:07:55.635Z"'::jsonb),
('card-ffss-2021-102', NULL, 'deck-prc-2021-ffss', 'Difference between the cost and the selling price:', 'Markup', 'Markup is the amount or percentage added to the total product cost to establish the retail selling price (Selling Price − Cost = Markup).', '["Variable cost","Markup","Food cost","Profit"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Pricing Strategies"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 102. Pricing formulas: Cost + Markup = Selling Price.', '{"dueDate":"2026-11-07T04:12:42.618Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:12:42.618Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:12:42.618Z"'::jsonb),
('card-ffss-2021-103', NULL, 'deck-prc-2021-ffss', 'Philippines: rice; Saudi Arabia: ___.', 'Pilaf', 'Rice is the primary staple grain in the Philippines; spiced rice pilaf (Kabsa / Majboos pilaf) is the premier traditional grain staple of Saudi Arabia and the Arabian Peninsula.', '["Adlai","Chia seeds","Falafel","Pilaf"]'::jsonb, '["PRC-2021","FFSS","International Cuisines","Staple Foods"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 103. Middle Eastern staple grain dish = Pilaf.', '{"dueDate":"2026-11-07T04:15:03.699Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:15:03.699Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:15:03.699Z"'::jsonb),
('card-ffss-2021-104', NULL, 'deck-prc-2021-ffss', 'Overcooking or overheating of oil can cause ___.', 'Formation of acrolein', 'When frying oil is heated past its smoke point, triglycerides hydrolyze into free glycerol, which dehydrates into acrolein—a pungent, acrid, eye-irritating aldehyde vapor.', '["Coagulation","Denaturation","Gelatinization","Formation of acrolein"]'::jsonb, '["PRC-2021","FFSS","Fats & Oils","Food Chemistry"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 104. Thermal breakdown of fat = Acrolein.', '{"dueDate":"2026-11-06T17:06:59.796Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:06:59.796Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:06:59.796Z"'::jsonb),
('card-ffss-2021-105', NULL, 'deck-prc-2021-ffss', 'To avoid foods spoiling in the refrigerator or freezer, which of the following actions is always recommended?', 'Placing a date of arrival on all foods', 'Clear labeling with arrival/preparation dates and expiration dates is the core operational prerequisite for executing FIFO (First-In, First-Out) inventory rotation.', '["Smelling the food to make sure it is fresh","Placing a date of arrival on all foods","Ordering foods for a few days at a time only","Placing the oldest product on top of newer product"]'::jsonb, '["PRC-2021","FFSS","Storage & Inventory","FIFO"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 105. Inventory control: FIFO date labeling.', '{"dueDate":"2026-11-07T04:14:19.226Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:14:19.226Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:14:19.226Z"'::jsonb)
