INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-ffss-2021-106', NULL, 'deck-prc-2021-ffss', '1 cup fresh milk: ___; 1 cup of low fat milk: ___.', '170 kcal; 125 kcal', 'Under the Philippine Food Exchange Lists (PEL): 1 exchange of Whole Milk provides 12g CHO, 8g PRO, 10g FAT = 170 kcal; Low Fat Milk provides 12g CHO, 8g PRO, 5g FAT = 125 kcal.', '["100 kcal; 80 kcal","125 kcal; 80 kcal","100 kcal; 40 kcal","170 kcal; 125 kcal"]'::jsonb, '["PRC-2021","FFSS","Food Exchange Lists","Nutrition Math"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 106. PEL values: Whole milk = 170 kcal, Low fat = 125 kcal.', '{"dueDate":"2026-11-06T17:33:46.428Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:33:46.428Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:33:46.428Z"'::jsonb),
('card-ffss-2021-107', NULL, 'deck-prc-2021-ffss', 'Identify the ESSENTIAL amino acids.', 'Threonin, tryptophan, valine', 'Threonine, Tryptophan, and Valine are essential amino acids that humans cannot synthesize de novo. Alanine, aspartic acid, and proline are non-essential.', '["Proline, serine, tyrosine","Threonin, tryptophan, valine","Alanine, arginine, asparagine","Aspartic acid, cysteine, glutamic acid"]'::jsonb, '["PRC-2021","FFSS","Biochemistry","Amino Acids"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 107. Essential amino acid list.', '{"dueDate":"2026-11-06T17:36:35.118Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:36:35.118Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:36:35.118Z"'::jsonb),
('card-ffss-2021-108', NULL, 'deck-prc-2021-ffss', 'Broken mayonnaise is due to ___.', 'Too rapid addition of oil', 'Mayonnaise requires oil to be incorporated drop by drop initially into the egg yolk emulsion; pouring oil too rapidly overwhelms the lecithin interfacial tension and causes phase separation (broken sauce).', '["Too much baking soda","Too rapid addition of oil","Too much addition of sugar","Too much addition of egg"]'::jsonb, '["PRC-2021","FFSS","Emulsions","Culinary Science"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 108. Emulsion failure: Rapid oil addition.', '{"dueDate":"2026-11-06T16:59:33.948Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:59:33.948Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:59:33.948Z"'::jsonb),
('card-ffss-2021-109', NULL, 'deck-prc-2021-ffss', 'Beth is a graduate of BS Nursing in one province in the Philippines. She was appointed by the City Mayor to occupy the position of a Nutritionist-Dietitian in an LGU. As there is an ND Law, what should the mayor do?', 'Comply with the law and replace Beth''s position with an RND', 'Republic Act No. 10862 strictly mandates that only Registered Nutritionist-Dietitians (RND) holding valid Professional Identification Cards issued by the PRC can hold Nutritionist-Dietitian plantillas.', '["Give a copy of the ND law to Beth and let her decide","Wait until Beth resigns or retires and get an RND","Ask the HR in the city health office to explain the law to Beth","Comply with the law and replace Beth''s position with an RND"]'::jsonb, '["PRC-2021","FFSS","RA 10862","Professional Ethics"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 109. RA 10862 legal staffing mandate.', '{"dueDate":"2026-11-07T04:03:54.260Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:03:54.260Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:03:54.260Z"'::jsonb),
('card-ffss-2021-11', NULL, 'deck-prc-2021-ffss', 'A 550g organic kale costs Php300 per kg. The edible portion is 70%. What is the EP price of organic kale per kg?', 'Php 165', 'For 550g purchased at Php300/kg, AP cost = 0.550 kg × Php300 = Php165. The purchased cost of the 550g bunch is Php 165.', '["Php 150","Php 131","Php 115.5","Php 165"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Food Purchasing"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 11. Margin calculation: 550g / 1000g × 300 = Php 165.', '{"dueDate":"2026-11-07T04:16:57.308Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-06T04:16:57.308Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:16:57.308Z"'::jsonb),
('card-ffss-2021-110', NULL, 'deck-prc-2021-ffss', 'Eggs can be stored at room temperature up to ___.', '7 days', 'At ambient tropical room temperature (25°C–30°C), table eggs deteriorate rapidly and maintain acceptable culinary and microbiological freshness for a maximum of 7 days before significant quality loss.', '["2 months","14 days","7 days","1 month"]'::jsonb, '["PRC-2021","FFSS","Food Storage","Egg Cookery"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 110. Egg shelf-life at room temp = 7 days.', '{"dueDate":"2026-11-06T17:25:34.002Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:25:34.002Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:25:34.002Z"'::jsonb),
('card-ffss-2021-111', NULL, 'deck-prc-2021-ffss', 'Which food processing method has been linked to cancer in laboratory animals?', 'Smoke curing', 'Traditional wood smoke curing deposits polycyclic aromatic hydrocarbons (PAHs), such as benzo[a]pyrene, which are well-documented carcinogens and mutagens.', '["Freeze-drying","Smoke curing","Irradiation","Pickling"]'::jsonb, '["PRC-2021","FFSS","Food Processing","Toxicology"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 111. Smoke curing PAH carcinogens.', '{"dueDate":"2026-11-06T17:23:17.439Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:23:17.439Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:23:17.439Z"'::jsonb),
('card-ffss-2021-112', NULL, 'deck-prc-2021-ffss', 'Which of the list below is a soluble fiber?', 'Pectin', 'Pectin is a water-soluble dietary fiber found in plant cell walls and intercellular cement that forms viscous gels. Cellulose, hemicellulose, and lignin are insoluble fibers.', '["Hemicellulose","Cellulose","Pectin","Lignin"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Dietary Fiber"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 112. Dietary fiber classification: Pectin is soluble.', '{"dueDate":"2026-11-07T04:05:00.725Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:05:00.725Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:05:00.725Z"'::jsonb),
('card-ffss-2021-113', NULL, 'deck-prc-2021-ffss', 'Gluten can be extracted from dough made from flour and water by ___.', 'rinsing with water', 'Washing and kneading dough under a gentle stream of cold water washes away water-soluble starches and albumins, leaving an elastic, cohesive mass of gluten (gliadin and glutenin).', '["baking","adding sugar","adding salt","rinsing with water"]'::jsonb, '["PRC-2021","FFSS","Cereal & Flour","Gluten Extraction"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 113. Gluten extraction by water washing.', '{"dueDate":"2026-11-07T04:16:04.143Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:16:04.143Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:16:04.143Z"'::jsonb),
('card-ffss-2021-114', NULL, 'deck-prc-2021-ffss', 'All the following foods are good sources of niacin EXCEPT ___.', 'baked potato', 'Tuna, chicken breast, and mushrooms are rich sources of preformed niacin. A baked potato provides small amounts of niacin but is primarily a carbohydrate staple.', '["tuna","baked potato","chicken","mushrooms"]'::jsonb, '["PRC-2021","FFSS","Food Composition","Vitamins"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 114. Niacin sources.', '{"dueDate":"2026-11-06T17:07:26.890Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:07:26.890Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:07:26.890Z"'::jsonb),
('card-ffss-2021-115', NULL, 'deck-prc-2021-ffss', 'Which is the size of a placeplate (charger plate)?', '12"', 'A standard placeplate (service charger plate) measures 11 to 12 inches in diameter. Dinner plates are 10 inches, salad/soup plates 8–9 inches, and bread-and-butter plates 6 inches.', '["10\"","12\"","9\"","6\""]'::jsonb, '["PRC-2021","FFSS","Table Service","Dining Room Operations"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 115. Table setting chinaware dimensions: Placeplate = 12".', '{"dueDate":"2026-11-06T17:20:29.052Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:20:29.052Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:20:29.052Z"'::jsonb),
('card-ffss-2021-116', NULL, 'deck-prc-2021-ffss', 'A leadership style that requires that decisions are made by a group and is based on all members working together until an agreement is met:', 'Consensus', 'Consensus leadership involves collaborative problem-solving where all group members voice concerns and negotiate until a collective agreement supported by all is reached.', '["Decision made with a consultant","Consensus","Autocratic","Vote by the majority"]'::jsonb, '["PRC-2021","FFSS","Foodservice Management","Leadership"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 116. Leadership styles: Consensus.', '{"dueDate":"2026-11-07T04:16:23.763Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:16:23.763Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:16:23.763Z"'::jsonb),
('card-ffss-2021-117', NULL, 'deck-prc-2021-ffss', 'Which of the following does NOT influence cooking time of meat?', 'temperature of meat', 'Standard culinary theory emphasizes that cooking method/temperature, thickness/cut size, and meat connective tissue density directly determine cooking duration.', '["cooking temperature","size of the cut","temperature of meat","type of meat (pork, chicken, beef)"]'::jsonb, '["PRC-2021","FFSS","Meat Cookery","Culinary Arts"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 117. Meat cookery parameters.', '{"dueDate":"2026-11-06T17:02:46.125Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:02:46.125Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:02:46.125Z"'::jsonb),
('card-ffss-2021-118', NULL, 'deck-prc-2021-ffss', 'According to the ND Law, all successful candidates in the licensure examination shall ___ prior to the practice of nutrition and dietetics.', 'Take the oath of profession', 'Under RA 10862, all successful board examinees are legally required to take the professional oath before the PRC Board of Nutrition and Dietetics prior to entering professional practice.', '["Read the ND law","Apply for Phil health and SSS","Prepare curriculum vitae","Take the oath of profession"]'::jsonb, '["PRC-2021","FFSS","RA 10862","PRC Licensure"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 118. RA 10862 oath of profession.', '{"dueDate":"2026-11-06T16:57:11.316Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:57:11.316Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:57:11.316Z"'::jsonb),
('card-ffss-2021-119', NULL, 'deck-prc-2021-ffss', 'The government agency with the primary responsibility of ensuring the food safety of consumers:', 'FDA', 'Under the Food Safety Act of 2013 (RA 10611), the Food and Drug Administration (FDA) of the Department of Health is responsible for the safety of processed and prepackaged food products.', '["FNRI","DA","HACCP","FDA"]'::jsonb, '["PRC-2021","FFSS","Food Laws","RA 10611"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 119. Primary agency for processed food safety = FDA.', '{"dueDate":"2026-11-06T17:07:08.142Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:07:08.142Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:07:08.142Z"'::jsonb),
('card-ffss-2021-12', NULL, 'deck-prc-2021-ffss', 'Which is NOT correct in arranging food on a plate?', 'Plate should appear overload.', 'Overloading a plate creates an unappealing, messy appearance; aesthetic plating requires balance, focal points, and adequate rim space.', '["Rims must be free from drips.","Sauce is poured over the meat or served separately in a sauceboat.","Hot food should always served on a hot plate.","Plate should appear overload."]'::jsonb, '["PRC-2021","FFSS","Meal Presentation","Culinary Arts"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 12. Principles of aesthetic food presentation.', '{"dueDate":"2026-11-07T04:10:43.305Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:10:43.305Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:10:43.305Z"'::jsonb),
('card-ffss-2021-120', NULL, 'deck-prc-2021-ffss', 'The following activities require temperature control EXCEPT ___.', 'menu planning', 'Storage, thawing, cooking, holding, and receiving are physical critical control points requiring strict thermometer verification. Menu planning is an administrative paper task.', '["storage","menu planning","thawing of ingredients","receiving"]'::jsonb, '["PRC-2021","FFSS","HACCP","Food Safety"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 120. HACCP critical control points vs administrative planning.', '{"dueDate":"2026-11-07T04:10:31.961Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:10:31.961Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:10:31.961Z"'::jsonb),
('card-ffss-2021-121', NULL, 'deck-prc-2021-ffss', 'Identify the proper size of a soup plate.', '9"', 'Standard chinaware dimensions: A soup plate (or deep rim soup bowl) is typically 9 inches in diameter. Placeplates are 12", dinner plates 10", and bread/butter plates 6".', '["12\"","9\"","6\"","10\""]'::jsonb, '["PRC-2021","FFSS","Table Setting","Foodservice Equipment"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 121. Chinaware: Soup plate = 9 inches.', '{"dueDate":"2026-11-07T04:10:51.582Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:10:51.582Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:10:51.582Z"'::jsonb),
('card-ffss-2021-122', NULL, 'deck-prc-2021-ffss', 'In order to make a perfect jelly, there should be a right combination of ___.', 'sugar, acid and pectin', 'The jelly triad requires precise equilibrium: 60–65% sugar, 0.5–1.0% high-methoxyl pectin, and a pH of 3.0–3.4 (acid) to form a stable pectin-sugar-acid gel network.', '["sugar, pectin and pulp","fruit juice, salt and acid","sugar, vinegar and milk","sugar, acid and pectin"]'::jsonb, '["PRC-2021","FFSS","Food Preservation","Jelly Making"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 122. Jelly triad: Pectin + Acid + Sugar.', '{"dueDate":"2026-11-06T17:31:53.909Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:31:53.909Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:31:53.909Z"'::jsonb),
('card-ffss-2021-123', NULL, 'deck-prc-2021-ffss', 'Which is TRUE about pasteurized milk?', 'Heat is applied to at least 61-65 C for at least 30 minutes', 'Batch/vat pasteurization (LTLT - Low Temperature Long Time) heats milk to 62.8°C–65°C (145°F) for at least 30 minutes to destroy all pathogenic vegetative bacteria (such as Mycobacterium tuberculosis).', '["Milk is treated under high pressure to reduce size of fat globules","Milk is untreated","Ultra high temperature is applied","Heat is applied to at least 61-65 C for at least 30 minutes"]'::jsonb, '["PRC-2021","FFSS","Dairy","Pasteurization"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 123. Vat pasteurization: 61-65 C for 30 min.', '{"dueDate":"2026-11-06T16:36:58.959Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:36:58.959Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:36:58.959Z"'::jsonb),
('card-ffss-2021-124', NULL, 'deck-prc-2021-ffss', 'To facilitate the receiving of goods, it is desirable to locate the receiving area near the ___.', 'delivery door', 'The receiving area must be placed adjacent to the exterior delivery door/dock so delivery trucks can offload shipments directly with minimal cross-traffic and temperature exposure.', '["storage area","delivery door","dining area","wash area"]'::jsonb, '["PRC-2021","FFSS","Facility Planning","Layout & Design"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 124. Receiving dock placement.', '{"dueDate":"2026-11-07T04:12:21.832Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:12:21.832Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:12:21.832Z"'::jsonb),
('card-ffss-2021-125', NULL, 'deck-prc-2021-ffss', 'If the cost per portion of lamb shawarma with cheese is Php 20 with a 20% food cost, what would be the selling price?', 'Php 100', 'Selling Price = Raw Food Cost ÷ Food Cost Percentage = Php 20 ÷ 0.20 = Php 100.00.', '["Php 75","Php 100","Php 125","Php 50"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Pricing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 125. Margin calculation: 20 / 0.20 = Php 100.', '{"dueDate":"2026-11-06T17:03:09.406Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:03:09.406Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:03:09.406Z"'::jsonb),
('card-ffss-2021-126', NULL, 'deck-prc-2021-ffss', 'Which of the following practices in the food service business promotes care for the environment?', 'Proper waste segregation and disposal', 'Ecological solid waste management (segregation into biodegradable, recyclable, and residual waste) minimizes landfill contamination and promotes environmental sustainability in foodservice.', '["Proper waste segregation and disposal","Serving unlimited rice to customers","Promoting Filipino cuisine to foreigners","Proper dishwashing of utensils"]'::jsonb, '["PRC-2021","FFSS","Waste Management","Foodservice Administration"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 126. Environmental sustainability in foodservice.', '{"dueDate":"2026-11-06T17:19:33.292Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:19:33.292Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:19:33.292Z"'::jsonb),
('card-ffss-2021-127', NULL, 'deck-prc-2021-ffss', 'Which enzyme CANNOT tenderize meat?', 'Glucose oxidase', 'Papain (papaya), bromelain (pineapple), and ficin (figs) are proteolytic enzymes that tenderize meat. Glucose oxidase is an enzyme used in desugaring eggs to prevent Maillard browning during drying.', '["Bromelain","Glucose oxidase","Ficin","Papain"]'::jsonb, '["PRC-2021","FFSS","Enzymes","Meat Science"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 127. Plant proteases: Bromelain, Papain, Ficin. Glucose oxidase is not a protease.', '{"dueDate":"2026-11-07T04:10:03.655Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:10:03.655Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:10:03.655Z"'::jsonb),
('card-ffss-2021-128', NULL, 'deck-prc-2021-ffss', 'Which is responsible for the tough and fibrous inner core in carrots?', 'Lignin', 'Lignin is a complex non-carbohydrate polymer deposited in woody plant vascular bundles (xylem core of carrots) that does not soften significantly during cooking.', '["Beta carotene","Cellulose","Hemicellulose","Lignin"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Plant Anatomy"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 128. Woody plant core = Lignin.', '{"dueDate":"2026-11-07T04:12:37.962Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:12:37.962Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:12:37.962Z"'::jsonb),
('card-ffss-2021-129', NULL, 'deck-prc-2021-ffss', 'What is an example of unethical practice?', 'Favoring a supplier which provides an expensive gift to you.', 'Accepting personal gifts or kickbacks in exchange for awarding procurement contracts is a severe breach of professional purchasing ethics and represents a direct conflict of interest.', '["Seeking approval from a director before purchasing expensive office equipment.","Favoring a supplier which provides an expensive gift to you.","Asking for a solicitation for prizes in the office Christmas party","Informing your HR on your other sources of income aside from your regular job."]'::jsonb, '["PRC-2021","FFSS","Ethics","Purchasing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 129. Purchasing ethics and anti-kickback codes.', '{"dueDate":"2026-11-07T04:02:53.613Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:02:53.613Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:02:53.613Z"'::jsonb),
('card-ffss-2021-13', NULL, 'deck-prc-2021-ffss', 'Process of assigning job activities and authority to a specific employee within the organization:', 'Delegation', 'Delegation is the process of assigning responsibility and necessary authority to subordinates to accomplish designated tasks.', '["Job analysis","Promotion","Job description","Delegation"]'::jsonb, '["PRC-2021","FFSS","Management","Human Resources"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 13. Management principles.', '{"dueDate":"2026-11-06T17:25:27.392Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:25:27.392Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:25:27.392Z"'::jsonb),
('card-ffss-2021-130', NULL, 'deck-prc-2021-ffss', 'Thames University offers dishes in their canteen which are repeatedly offered every 30 days. From time to time, the canteen concessionaire also offers menus which are in season. Which type of menu is this?', 'Cycle', 'A cycle menu is a carefully planned sequence of menus repeated over a specified time interval (e.g., a 30-day or 4-week cycle).', '["Market","Cycle","Hybrid","Static"]'::jsonb, '["PRC-2021","FFSS","Menu Planning","Foodservice Operations"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 130. Menu types: Cycle menu = rotated over a specific period.', '{"dueDate":"2026-11-06T16:48:36.627Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:48:36.627Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:48:36.627Z"'::jsonb),
('card-ffss-2021-131', NULL, 'deck-prc-2021-ffss', 'Annatto extract is added in food to enhance natural colors. This additive acts as ___.', 'Color additive', 'Annatto (atsuete) is a natural carotenoid-based food coloring additive containing bixin and norbixin that imparts a vibrant yellow-orange color to foods.', '["Flavor enhancer","Emulsifier","Humectant","Color additive"]'::jsonb, '["PRC-2021","FFSS","Food Additives","Colorants"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 131. Annatto = natural color additive.', '{"dueDate":"2026-11-06T17:34:21.268Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:34:21.268Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:34:21.268Z"'::jsonb),
('card-ffss-2021-132', NULL, 'deck-prc-2021-ffss', 'Dante is a purchasing officer at First Fruits company. The bidding was opened for new equipment. Supplier A provided the lowest bid. Supplier B provided a slightly higher bid but offered Dante a free trip to Hong Kong. Which supplier would Dante choose?', 'Supplier A as it offers the lowest bid and Supplier B''s practice is against the code of integrity.', 'Professional purchasing integrity requires objective evaluation based on lowest responsive bid and specifications; accepting personal travel incentives violates business ethics and company procurement rules.', '["Supplier B as it offers a free trip promo.","Supplier A as it offers the lowest bid and Supplier B''s practice is against the code of integrity.","Supplier B as it fosters a good relationship with the client","Get one item from Supplier A and the rest from Supplier B."]'::jsonb, '["PRC-2021","FFSS","Ethics","Purchasing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 132. Procurement ethics and anti-bribery standards.', '{"dueDate":"2026-11-06T17:12:01.107Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:12:01.107Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:12:01.107Z"'::jsonb),
('card-ffss-2021-133', NULL, 'deck-prc-2021-ffss', 'What is the age of meat if the color is pink?', 'Very young', 'Young animal muscle (such as milk-fed veal from young calves under 3 months) contains minimal myoglobin concentration, producing a pale delicate pink meat color.', '["Very mature","Mature","Nearing maturity","Very young"]'::jsonb, '["PRC-2021","FFSS","Meat Science","Food Quality"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 133. Meat color and age: Pink = very young / veal.', '{"dueDate":"2026-11-06T17:12:43.294Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:12:43.294Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:12:43.294Z"'::jsonb),
('card-ffss-2021-134', NULL, 'deck-prc-2021-ffss', 'Select which is NOT correct about carbon footprint.', 'indicates the amount of organic ingredients in the menu', 'A carbon footprint quantifies total greenhouse gas emissions (in CO2 equivalents) generated across the life cycle of food. It does not measure or indicate organic ingredient percentages.', '["estimates the climate change impact in producing food","measures the impact on the environment","measures the amount of greenhouse gases emitted","indicates the amount of organic ingredients in the menu"]'::jsonb, '["PRC-2021","FFSS","Sustainability","Environmental Health"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 134. Carbon footprint definition.', '{"dueDate":"2026-11-06T16:55:57.279Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:55:57.279Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:55:57.279Z"'::jsonb),
('card-ffss-2021-135', NULL, 'deck-prc-2021-ffss', 'A management function that involves inspecting the work that is done, ensuring the standards are met and monitoring that the work is done as planned:', 'Controlling', 'Controlling is the managerial process of setting performance standards, measuring ongoing performance against those standards, and taking corrective actions when deviations occur.', '["Bargaining","Democratic","Controlling","Evaluation"]'::jsonb, '["PRC-2021","FFSS","Management","Operations"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 135. Management functions: Controlling.', '{"dueDate":"2026-11-06T16:49:21.224Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:49:21.224Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:49:21.224Z"'::jsonb),
('card-ffss-2021-136', NULL, 'deck-prc-2021-ffss', 'The similarity of dressed and drawn chicken is that ___.', 'Both were defeathered', 'Dressed poultry is slaughtered, bled, and defeathered (head, feet, and viscera intact). Drawn poultry is dressed poultry with the visceral organs and entrails removed. Both are defeathered.', '["There is no difference","Both visceral organs were removed","The two forms are ready-to-cook","Both were defeathered"]'::jsonb, '["PRC-2021","FFSS","Poultry","Market Forms"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 136. Dressed vs Drawn poultry market forms.', '{"dueDate":"2026-11-06T17:28:48.383Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:28:48.383Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:28:48.383Z"'::jsonb),
('card-ffss-2021-137', NULL, 'deck-prc-2021-ffss', 'What ingredient can be an extender for Chicken Adobo to have more yield?', 'Potatoes', 'Starchy vegetables like cubed potatoes absorb adobo braising juices and bulk up dish volume cost-effectively without altering the quintessential savory-vinegar adobo profile.', '["Potatoes","Malunggay","Corn starch","Noodles"]'::jsonb, '["PRC-2021","FFSS","Food Preparation","Philippine Cookery"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 137. Recipe extenders: Potato in adobo.', '{"dueDate":"2026-11-06T16:48:18.992Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:48:18.992Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:48:18.992Z"'::jsonb),
('card-ffss-2021-138', NULL, 'deck-prc-2021-ffss', 'Which enzyme causes fruit to ripen?', 'Pectinase', 'Pectinase enzymes (such as polygalacturonase and pectin methylesterase) break down insoluble protopectin into soluble pectin, softening plant cell walls during ripening.', '["Bromelain","Papain","Amylase","Pectinase"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Post-Harvest Physiology"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 138. Fruit softening enzyme = Pectinase.', '{"dueDate":"2026-11-06T16:33:52.200Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:33:52.200Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:33:52.200Z"'::jsonb),
('card-ffss-2021-139', NULL, 'deck-prc-2021-ffss', 'Which is an example of an incomplete protein?', 'Gelatin', 'Gelatin is derived from collagen and completely lacks tryptophan, an essential amino acid, making it an incomplete protein with low biological value.', '["Egg","Meat","Milk","Gelatin"]'::jsonb, '["PRC-2021","FFSS","Proteins","Nutrition Science"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 139. Incomplete animal protein = Gelatin (lacks Trp).', '{"dueDate":"2026-11-06T17:33:20.832Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:33:20.832Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:33:20.832Z"'::jsonb),
('card-ffss-2021-14', NULL, 'deck-prc-2021-ffss', 'Meat of a mature sheep is ___.', 'Mutton', 'Mutton is the meat of adult sheep (older than 1 year). Lamb is from sheep under 1 year, and veal is from young calves.', '["Bull","Game","Mutton","Veal"]'::jsonb, '["PRC-2021","FFSS","Meat Cookery","Food Standards"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 14. Meat classification.', '{"dueDate":"2026-11-06T17:12:32.699Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:12:32.699Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:12:32.699Z"'::jsonb),
('card-ffss-2021-140', NULL, 'deck-prc-2021-ffss', 'In a conventional food service flow diagram, which is situated in the central area?', 'Main cooking unit', 'The main cooking/hot production bank is typically situated at the operational center of the kitchen layout to provide shortest transit paths to receiving/prep on one side and service/plating on the other.', '["Storage area","Pre-preparation","Salad station","Main cooking unit"]'::jsonb, '["PRC-2021","FFSS","Facility Planning","Layout & Design"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 140. Kitchen layout workflow: Cooking unit in center.', '{"dueDate":"2026-11-06T17:33:41.310Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:33:41.310Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:33:41.310Z"'::jsonb),
('card-ffss-2021-141', NULL, 'deck-prc-2021-ffss', 'Pilaf: Middle East; ___: Spain', 'Paella', 'Paella is the iconic saffron-scented national rice dish of Spain. Nasi goreng is Indonesian, and Basmati is an Indian long-grain rice variety.', '["Nasi Goreng","Rice","Paella","Basmati"]'::jsonb, '["PRC-2021","FFSS","International Cuisines","Culinary Geography"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 141. National rice specialties: Paella = Spain.', '{"dueDate":"2026-11-06T16:37:19.632Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:37:19.632Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:37:19.632Z"'::jsonb),
('card-ffss-2021-142', NULL, 'deck-prc-2021-ffss', 'What is the ideal number of members when you have consumer panel test?', '50 or more', 'Consumer acceptance panels require large cohorts of untrained consumers (typically 50 to 100+ panelists) to achieve statistical significance for product market acceptance.', '["12-15","30","5-10","50 or more"]'::jsonb, '["PRC-2021","FFSS","Sensory Evaluation","Product Development"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 142. Sensory testing panels: Consumer panels require 50+ members.', '{"dueDate":"2026-11-06T16:56:14.237Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:56:14.237Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:56:14.237Z"'::jsonb),
('card-ffss-2021-143', NULL, 'deck-prc-2021-ffss', 'A leadership style based on the "majority rules", in which decisions are made by the group rather than a manager alone:', 'Democratic', 'Democratic (participative) leadership encourages employees to participate in decision-making and relies on group discussion, voting, and majority decisions.', '["People Power","Controlling","Vox Populi, Vox Dei","Democratic"]'::jsonb, '["PRC-2021","FFSS","Leadership","Management"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 143. Democratic leadership.', '{"dueDate":"2026-11-06T17:04:25.367Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:04:25.367Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:04:25.367Z"'::jsonb),
('card-ffss-2021-144', NULL, 'deck-prc-2021-ffss', 'The following agencies are responsible in ensuring the safety of our food products EXCEPT FOR:', 'Commission on Population', 'The DA (primary agricultural food safety), DOH, and FDA (processed foods) are official regulatory agencies under RA 10611. The Commission on Population (POPCOM) handles population and family planning.', '["Department of Agriculture","Department of Health","Commission on Population","Food and Drug Administration"]'::jsonb, '["PRC-2021","FFSS","Food Safety Act","Government Agencies"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 144. Food safety regulatory bodies under RA 10611.', '{"dueDate":"2026-11-06T17:31:06.662Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:31:06.662Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:31:06.662Z"'::jsonb),
('card-ffss-2021-145', NULL, 'deck-prc-2021-ffss', 'India: Roti; France: ___.', 'Baguette', 'Roti is the traditional daily staple flatbread of India; the Baguette is the traditional daily staple bread of France.', '["Consomme","Pita","Baguette","Antipasto"]'::jsonb, '["PRC-2021","FFSS","Baking","International Cuisines"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 145. International staple breads.', '{"dueDate":"2026-11-07T04:13:21.628Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:13:21.628Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:13:21.628Z"'::jsonb),
('card-ffss-2021-146', NULL, 'deck-prc-2021-ffss', 'The minimum temperature for sterilization for a certain length of time is ___.', '100°C', 'Sterilization in food thermal processing requires achieving temperatures at least at or above 100°C (boiling point) for acid foods, or 121°C in retorts for low-acid foods.', '["50°C","100°C","100°F","0°C"]'::jsonb, '["PRC-2021","FFSS","Thermal Processing","Sterilization"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 146. Thermal processing thresholds.', '{"dueDate":"2026-11-07T04:09:01.871Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:09:01.871Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:09:01.871Z"'::jsonb),
('card-ffss-2021-147', NULL, 'deck-prc-2021-ffss', 'Rona, a product formulator, would like to assess consumers'' preference of five ice cream variants from "most like" to "least like". Which is the appropriate sensory evaluation method to use?', 'Ranking test', 'A ranking test asks panelists to arrange 3 or more coded samples in ordinal sequence according to degree of liking, sweetness, or preference.', '["Ranking test","Descriptive test","Paired comparison","Triangle test"]'::jsonb, '["PRC-2021","FFSS","Sensory Evaluation","Quality Assessment"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 147. Sensory evaluation: Ranking test.', '{"dueDate":"2026-11-07T04:08:23.608Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:08:23.608Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:08:23.608Z"'::jsonb),
('card-ffss-2021-148', NULL, 'deck-prc-2021-ffss', 'Green tea, grapes and wine are high in phytonutrients called ___.', 'Polyphenols', 'Polyphenols (including epigallocatechin gallate in green tea, and resveratrol and anthocyanins in grapes and red wine) are potent antioxidant phytochemicals.', '["Isoflavones","Terpenes","Polyphenols","Indoles"]'::jsonb, '["PRC-2021","FFSS","Phytochemicals","Nutrition Science"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 148. Polyphenols in tea, grapes, and wine.', '{"dueDate":"2026-11-07T04:17:03.765Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-06T04:17:03.765Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:17:03.765Z"'::jsonb),
('card-ffss-2021-149', NULL, 'deck-prc-2021-ffss', 'How many teaspoons are there in 1 tablespoon?', '3 tsps.', 'Standard culinary and pharmaceutical liquid measure: 1 tablespoon = 3 teaspoons = 15 mL = 1/2 fluid ounce.', '["5 tsps.","10 tsps.","3 tsps.","6 tsps."]'::jsonb, '["PRC-2021","FFSS","Weights & Measures","Kitchen Math"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 149. Kitchen conversions: 1 tbsp = 3 tsp.', '{"dueDate":"2026-11-06T16:51:49.667Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:51:49.667Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:51:49.667Z"'::jsonb),
('card-ffss-2021-15', NULL, 'deck-prc-2021-ffss', 'What do you call a white flour resulting from removal of at least 25% of the bran and shorts during milling?', 'Refined flour', 'Refined white flour is produced after milling away the protective bran and germ fractions (at least 25% of the grain), leaving pure starchy endosperm.', '["Reduced flour","Cake flour","Refined flour","Bread flour"]'::jsonb, '["PRC-2021","FFSS","Cereal & Starch","Food Technology"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 15. Cereal milling standards.', '{"dueDate":"2026-11-07T04:16:30.134Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:16:30.134Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:16:30.134Z"'::jsonb),
('card-ffss-2021-150', NULL, 'deck-prc-2021-ffss', 'Krizzia is counselling Ralstein, an obese patient depressed about body image wanting major lifestyle changes. Krizzia''s initial objective in the interviewing process should be to:', 'Establish rapport with Ralstein by getting to know her better before discussing anything', 'Establishing initial trust, unconditional positive regard, and emotional rapport is the essential first phase of therapeutic nutrition counselling before gathering technical diet recalls.', '["Discuss the role of a nutritionist-dietitian and set expectation of the professional fee","Determine the 24-hr food recall and anthropometric measurements","Establish rapport with Ralstein by getting to know her better before discussing anything","Determine food preferences and current medications Ralstein is taking in."]'::jsonb, '["PRC-2021","FFSS","Counseling","Dietitian Practice"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 150. Nutrition counselling initial objective: Build rapport.', '{"dueDate":"2026-11-06T16:59:18.746Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:59:18.746Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:59:18.746Z"'::jsonb)
