INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-ffss-2021-151', NULL, 'deck-prc-2021-ffss', 'Dante is a medical representative from a nutraceutical company who visited Krizzia in the office. Identify an UNACCEPTABLE practice:', 'Krizzia is requesting Dante for a sponsorship to her mom''s party', 'Soliciting personal sponsorships, gifts, or financial benefits for family events from commercial pharmaceutical/nutraceutical representatives is a direct violation of professional healthcare ethics.', '["Dante explains the benefits of the newly launched product to Krizzia","Dante inviting Krizzia to attend a launch of their new product in a five-star hotel","Krizzia is receiving samples of nutraceuticals for distribution to her patients","Krizzia is requesting Dante for a sponsorship to her mom''s party"]'::jsonb, '["PRC-2021","FFSS","Ethics","Professional Standards"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 151. Professional ethics and conflict of interest.', '{"dueDate":"2026-11-07T04:07:30.680Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:07:30.680Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:07:30.680Z"'::jsonb),
('card-ffss-2021-152', NULL, 'deck-prc-2021-ffss', 'Identify an example of a conflict of interest in dietary practice:', 'Krizzia sells her own products to the patients aside from the company''s products', 'Selling personal proprietary products directly to clinic patients creates financial self-dealing that compromises clinical objectivity and breaches fiduciary duty to the patient.', '["Krizzia listens to Dante''s product presentation when there is no patient","Krizzia sells her own products to the patients aside from the company''s products","Ralstein mentions her travel business to Krizzia and offers her some promos","Krizzia invests in the company''s cooperative for regular employees"]'::jsonb, '["PRC-2021","FFSS","Ethics","Dietitian Practice"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 152. Conflict of interest definition.', '{"dueDate":"2026-11-06T17:36:02.141Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:36:02.141Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:36:02.141Z"'::jsonb),
('card-ffss-2021-153', NULL, 'deck-prc-2021-ffss', 'Melanie launched a new liquor chocolate cake in her bakeshop and would like to assess acceptability of the new product among consumers. Which activity should Melanie perform?', 'Sensory evaluation', 'Sensory evaluation through consumer acceptance and hedonic testing is the scientific discipline used to evoke, measure, analyze, and interpret human sensory responses to new food products.', '["Issue management","Product development","Risk assessment","Sensory evaluation"]'::jsonb, '["PRC-2021","FFSS","Sensory Evaluation","Bakery Operations"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 153. Sensory evaluation for acceptability.', '{"dueDate":"2026-11-06T17:06:47.227Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:06:47.227Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:06:47.227Z"'::jsonb),
('card-ffss-2021-154', NULL, 'deck-prc-2021-ffss', 'What is the sensory characteristic corresponding to the size and color of the cake?', 'Appearance', 'Visual appearance encompasses color, size, shape, surface sheen, crumb structure, and physical geometry evaluated by sight.', '["Texture","Appearance","Aroma","Flavor"]'::jsonb, '["PRC-2021","FFSS","Sensory Evaluation","Food Quality"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 154. Sensory attributes: Appearance.', '{"dueDate":"2026-11-06T16:37:48.468Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:37:48.468Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:37:48.468Z"'::jsonb),
('card-ffss-2021-155', NULL, 'deck-prc-2021-ffss', 'Which sensory characteristic is measured through sniffing the cake?', 'Aroma', 'Aroma refers specifically to volatile odorant molecules detected through the olfactory epithelium via direct sniffing (orthonasal olfaction).', '["Texture","Aroma","Flavor","Appearance"]'::jsonb, '["PRC-2021","FFSS","Sensory Evaluation","Olfaction"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 155. Olfactory sensation = Aroma.', '{"dueDate":"2026-11-06T16:58:02.804Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:58:02.804Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:58:02.804Z"'::jsonb),
('card-ffss-2021-156', NULL, 'deck-prc-2021-ffss', 'A supplier delivered fresh meats and seafood to Lea one morning. Which of the following items shall she reject?', 'Bangus with sunken eyes', 'Fresh fish must have clear, bulging eyes and bright red gills; sunken, dull, cloudy eyes are a clear physical indicator of post-mortem spoilage and bacterial breakdown.', '["Chicken received at 3 degrees celsius","Goat with firm flesh","Beef with bright red color","Bangus with sunken eyes"]'::jsonb, '["PRC-2021","FFSS","Receiving","Fish & Seafood"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 156. Fresh fish receiving criteria: Reject sunken eyes.', '{"dueDate":"2026-11-06T17:31:24.199Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:31:24.199Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:31:24.199Z"'::jsonb),
('card-ffss-2021-157', NULL, 'deck-prc-2021-ffss', 'Lea prefers to purchase more items which have longer shelf life. Which of the items below have the longest shelf life?', 'Rice', 'Dry polished white rice has a water activity below 0.65 and can be stored safely in dry conditions for 1 to 2+ years without spoiling, far exceeding perishable fresh produce and milk.', '["Onion","Rice","Fresh milk","Potato"]'::jsonb, '["PRC-2021","FFSS","Food Storage","Shelf Life"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 157. Dry goods shelf-life: Rice has longest shelf life.', '{"dueDate":"2026-11-06T16:34:58.109Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:34:58.109Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:34:58.109Z"'::jsonb),
('card-ffss-2021-158', NULL, 'deck-prc-2021-ffss', 'Which of the food items is prone to having molds?', 'Bread', 'Bread has high moisture (Aw ~0.95), neutral pH, and exposure to airborne mold spores during cooling and slicing, making it highly susceptible to Rhizopus stolonifer (black bread mold).', '["Bread","Canned pineapple","Sardines","Rice"]'::jsonb, '["PRC-2021","FFSS","Food Spoilage","Microbiology"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 158. Mold spoilage in bakery goods: Bread.', '{"dueDate":"2026-11-06T17:08:27.541Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:08:27.541Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:08:27.541Z"'::jsonb),
('card-ffss-2021-159', NULL, 'deck-prc-2021-ffss', 'Meals served inside the aircraft came from the central kitchen. This type of foodservice system is ___.', 'Commissary', 'In a commissary foodservice system, centralized food procurement and large-scale bulk production occur in a central kitchen, and prepared meals are distributed to satellite service sites (like airline flights).', '["Cook/chill","Commissary","Assembly serve","Conventional"]'::jsonb, '["PRC-2021","FFSS","Foodservice Systems","Commissary"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 159. Airline catering = Commissary system.', '{"dueDate":"2026-11-06T16:49:57.608Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:49:57.608Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:49:57.608Z"'::jsonb),
('card-ffss-2021-16', NULL, 'deck-prc-2021-ffss', 'Anthocyanins: ___; Anthonxanthins: ___.', 'Red; white', 'Anthocyanins produce red, purple, and blue pigments (e.g., berries, red cabbage), while anthoxanthins produce white, ivory, and light yellow pigments (e.g., cauliflower, potato).', '["Yellow; red","Yellow; purple","Red; white","White; purple"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Plant Pigments"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 16. Plant pigments: Anthocyanin = red; Anthoxanthin = white/cream.', '{"dueDate":"2026-11-06T16:34:17.814Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:34:17.814Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:34:17.814Z"'::jsonb),
('card-ffss-2021-160', NULL, 'deck-prc-2021-ffss', 'The rice which is served in this Middle Eastern flight airline is ___.', 'Pilaf', 'Pilaf (such as Basmati rice pilaf cooked with whole spices and broth) is the signature rice preparation served across Middle Eastern aviation and catering routes.', '["Paella","Pilaf","Caviar","Nasi goreng"]'::jsonb, '["PRC-2021","FFSS","Airline Catering","Middle Eastern Cuisine"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 160. Middle Eastern rice = Pilaf.', '{"dueDate":"2026-11-07T04:06:40.582Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:06:40.582Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:06:40.582Z"'::jsonb),
('card-ffss-2021-161', NULL, 'deck-prc-2021-ffss', 'The dessert which is served in this Middle Eastern flight airline is ___.', 'Baklava', 'Baklava is the classic rich Middle Eastern pastry made of layers of filo dough filled with chopped nuts and sweetened with honey or spiced syrup.', '["Oreo ice cream","Baked Alaska","Baklava","Leche flan"]'::jsonb, '["PRC-2021","FFSS","International Cuisines","Pastry"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 161. Middle Eastern dessert = Baklava.', '{"dueDate":"2026-11-06T17:33:12.766Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:33:12.766Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:33:12.766Z"'::jsonb),
('card-ffss-2021-162', NULL, 'deck-prc-2021-ffss', 'Identify which refers to food items that are individually priced:', 'Ala Carte', 'An A la Carte menu prices each food item individually, allowing diners to select and pay for individual dishes separately according to preference.', '["Semi ala-carte","Du Jour","Ala Carte","Table d'' Hote"]'::jsonb, '["PRC-2021","FFSS","Menu Planning","Foodservice Terminology"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 162. Menu pricing: A la Carte = individually priced.', '{"dueDate":"2026-11-06T17:04:14.405Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:04:14.405Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:04:14.405Z"'::jsonb),
('card-ffss-2021-163', NULL, 'deck-prc-2021-ffss', 'Which one refers to food items grouped together at a single price?', 'Table d'' Hote', 'Table d''Hote (or prix fixe) offers a complete multi-course meal (appetizer, entree, dessert) grouped together at a single fixed set price.', '["Semi ala-carte","Du Jour","Table d'' Hote","Ala Carte"]'::jsonb, '["PRC-2021","FFSS","Menu Planning","Pricing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 163. Table d''Hote = fixed bundle price.', '{"dueDate":"2026-11-06T16:53:24.005Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:53:24.005Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:53:24.005Z"'::jsonb),
('card-ffss-2021-164', NULL, 'deck-prc-2021-ffss', 'This also means "menu of the day":', 'Du Jour', 'Du Jour is French for ''of the day'' (e.g., Soup du Jour), designating seasonal dishes or daily specials featured only on that particular day.', '["Du Jour","Semi ala-carte","Table d'' Hote","Ala Carte"]'::jsonb, '["PRC-2021","FFSS","Menu Terminology","Culinary French"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 164. Du Jour = of the day.', '{"dueDate":"2026-11-06T17:08:33.818Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:08:33.818Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:08:33.818Z"'::jsonb),
('card-ffss-2021-165', NULL, 'deck-prc-2021-ffss', 'Heidi is a school nutrition consultant in a high school canteen with around 3,000 students. Heidi developed a standard recipe of Chicken Pastel which yields 20 portions. What will be the recipe conversion factor to serve lunch for the 3,000 students?', '150', 'Recipe Conversion Factor (RCF) = Desired Yield ÷ Current Recipe Yield = 3,000 servings ÷ 20 servings = 150.', '["60","150","6","20"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Recipe Conversion"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 165. Margin calculation: 3000 / 20 = 150.', '{"dueDate":"2026-11-07T04:06:54.605Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:06:54.605Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:06:54.605Z"'::jsonb),
('card-ffss-2021-166', NULL, 'deck-prc-2021-ffss', 'If the total food cost for the standard recipe (yielding 20 portions) is Php 287.11, what is the total food cost per serving?', 'Php 14.36', 'Food Cost per Serving = Total Recipe Food Cost ÷ Number of Portions = Php 287.11 ÷ 20 = Php 14.3555 ≈ Php 14.36.', '["Php 10.45","Php 28.72","Php 14.36","Php 209"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Portion Costing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 166. Margin calculation: 287.11 / 20 = 14.36.', '{"dueDate":"2026-11-06T17:08:12.325Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:08:12.325Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:08:12.325Z"'::jsonb),
('card-ffss-2021-167', NULL, 'deck-prc-2021-ffss', 'What will be the recommended selling price for the Chicken Pastel portion (cost Php 14.36) using the standard markup factor of 2.0 (50% food cost)?', 'Php 28.72', 'Selling Price = Food Cost per Portion × Markup Factor = Php 14.36 × 2.0 = Php 28.72 (or Php 14.36 ÷ 0.50 = Php 28.72).', '["Php 50","Php 21.54","Php 43","Php 28.72"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Pricing Strategies"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 167. Margin calculation: 14.36 × 2 = Php 28.72.', '{"dueDate":"2026-11-07T04:06:11.660Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:06:11.660Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:06:11.660Z"'::jsonb),
('card-ffss-2021-168', NULL, 'deck-prc-2021-ffss', 'Noel will buy a jam. He would choose a fruit preserve which is ___.', 'Made from ground or mashed cooked fruit', 'Jam is prepared from crushed, mashed, or ground whole fruit cooked with sugar until thickened. (Jelly is from strained juice; Marmalade contains suspended citrus peel slices).', '["From dehydrated fruits with water","Made from the juice of cooked fruit with added sugar","Made from ground or mashed cooked fruit","From juice with thin slices of fruit, especially citrus fruits"]'::jsonb, '["PRC-2021","FFSS","Food Preservation","Fruit Preserves"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 168. Preserves definitions: Jam = crushed/mashed fruit; Jelly = juice; Marmalade = citrus peel.', '{"dueDate":"2026-11-06T17:25:51.336Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:25:51.336Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:25:51.336Z"'::jsonb),
('card-ffss-2021-169', NULL, 'deck-prc-2021-ffss', 'Noel also purchased fresh fruits like apple, banana, grapes and mulberries. Which of these is best kept at room temperature to avoid chilling injury?', 'Banana', 'Bananas are tropical climacteric fruits that suffer chilling injury (skin blackening due to polyphenol oxidase and loss of aroma) when stored below 13°C (55°F); they must be held at room temperature.', '["Apple","Banana","Mulberries","Grapes"]'::jsonb, '["PRC-2021","FFSS","Post-Harvest Physiology","Storage"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 169. Chilling injury in tropical fruits: Bananas.', '{"dueDate":"2026-11-06T17:33:32.641Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:33:32.641Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:33:32.641Z"'::jsonb),
('card-ffss-2021-17', NULL, 'deck-prc-2021-ffss', 'Cinnamon is from ___.', 'Bark', 'Cinnamon is harvested from the inner dried bark of Cinnamomum trees (such as Cinnamomum zeylanicum or verum).', '["Leaves","Buds and flowers","Bark","Roots and tubers"]'::jsonb, '["PRC-2021","FFSS","Spices & Herbs","Food Science"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 17. Botanical source: Sri Lankan cinnamon tree bark.', '{"dueDate":"2026-11-07T04:04:00.032Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:04:00.032Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:04:00.032Z"'::jsonb),
('card-ffss-2021-170', NULL, 'deck-prc-2021-ffss', 'When preparing the fruit spread, which of the ingredients are critical to be in correct balance?', 'Pectin, sugar and acid', 'The jelly/jam gel network is governed by the equilibrium between pectin polymer chains, sugar (which dehydrates pectin molecules), and acid (which neutralizes negative charges to allow junction zone bonding).', '["Water, sugar and acid","Water, pectin and oil","Sugar, salt and acid","Pectin, sugar and acid"]'::jsonb, '["PRC-2021","FFSS","Food Preservation","Gel Formation"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 170. Margin notes: Pectin + Acid + Sugar triad.', '{"dueDate":"2026-11-06T16:49:47.161Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:49:47.161Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:49:47.161Z"'::jsonb),
('card-ffss-2021-171', NULL, 'deck-prc-2021-ffss', 'If the standard recipe requires 1 kg of chicken which yields 10 servings, how many kilos of chicken will be purchased for 70 regular cafeteria customers?', '7kg', 'Quantity required = (70 servings ÷ 10 servings per kg) × 1 kg = 7 kg.', '["20kg","7kg","11kg","15kg"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Food Purchasing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 171. Margin calculation: 70 / 10 = 7 kg.', '{"dueDate":"2026-11-06T17:23:30.657Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:23:30.657Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:23:30.657Z"'::jsonb),
('card-ffss-2021-172', NULL, 'deck-prc-2021-ffss', 'If the total food cost per serving is Php 16.76, what will be the selling price using the 50% food cost factor?', 'Php 33.52', 'Selling Price = Food Cost per Portion ÷ Food Cost Percentage = Php 16.76 ÷ 0.50 = Php 33.52.', '["Php 22.14","Php 33.52","Php 25.14","Php 16.76"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Pricing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 172. Margin calculation: 16.76 / 0.50 = Php 33.52.', '{"dueDate":"2026-11-07T04:05:59.164Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:05:59.164Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:05:59.164Z"'::jsonb),
('card-ffss-2021-173', NULL, 'deck-prc-2021-ffss', 'What is the total food cost of the entire standardized recipe for 20 portions (food cost per serving Php 16.76)?', 'Php 335.2', 'Total Recipe Cost = 20 portions × Php 16.76 per portion = Php 335.20.', '["Php 67.04","Php 335.2","Php 250.14","Php 167.61"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Recipe Costing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 173. 20 × 16.76 = Php 335.20.', '{"dueDate":"2026-11-07T04:04:19.053Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:04:19.053Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:04:19.053Z"'::jsonb),
('card-ffss-2021-174', NULL, 'deck-prc-2021-ffss', 'The Castillo family organized a formal thanksgiving dinner for Commissioner Craig in Rockwell. What is the MOST appropriate table service for this formal state occasion?', 'Russian', 'Russian service (Service a la Russe) is the most formal style of dining service: all food is prepared and garnished in the kitchen, portioned onto platters, and served directly to seated guests by waitstaff using serving spoons and forks.', '["Compromise","English","Russian","American"]'::jsonb, '["PRC-2021","FFSS","Table Service","Banquet Operations"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 174. Formal table service styles: Russian service.', '{"dueDate":"2026-11-07T04:15:38.131Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:15:38.131Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:15:38.131Z"'::jsonb),
('card-ffss-2021-175', NULL, 'deck-prc-2021-ffss', 'Who should the waiter serve first during the formal dinner?', 'Commissioner Craig', 'In traditional dining etiquette and diplomatic protocol, the guest of honor (Commissioner Craig) is always served first, followed by female guests, and finally the hosts.', '["Mother Vilma","Father Johnny","Commissioner Craig","The son Chim"]'::jsonb, '["PRC-2021","FFSS","Table Service","Dining Etiquette"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 175. Guest of honor protocol in dining service.', '{"dueDate":"2026-11-06T17:30:09.982Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:30:09.982Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:30:09.982Z"'::jsonb),
('card-ffss-2021-176', NULL, 'deck-prc-2021-ffss', 'Which of the following acts of a waiter is INAPPROPRIATE based on the principles of table setting and dining service?', 'Wine glasses were almost filled near the brim.', 'Wine glasses should never be filled to the brim; red wine glasses are poured only 1/3 to 1/2 full to allow space for swirling, aeration, and volatile aroma release.', '["All beverages were removed from the right of the guests.","Wine glasses were almost filled near the brim.","All food were placed and removed from the left of the guests","Dinner knife is placed to the right of the plate."]'::jsonb, '["PRC-2021","FFSS","Beverage Service","Dining Etiquette"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 176. Wine service protocol: Fill max 1/2, never to brim.', '{"dueDate":"2026-11-06T17:30:02.096Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:30:02.096Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:30:02.096Z"'::jsonb),
('card-ffss-2021-177', NULL, 'deck-prc-2021-ffss', 'Aling Baby runs a university cafeteria. She never runs out of dishes to offer in her food stall for the entire month as she has ___.', 'Cycle menu', 'A monthly cycle menu rotates a carefully planned variety of dishes over 30 days, preventing customer monotony and simplifying bulk purchasing and preparation schedules.', '["Ala Carte","Du Jour","Cycle menu","Table D'' Hote"]'::jsonb, '["PRC-2021","FFSS","Menu Planning","Cafeteria Operations"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 177. Institutional menu planning: Cycle menu.', '{"dueDate":"2026-11-06T16:50:30.660Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:50:30.660Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:50:30.660Z"'::jsonb),
('card-ffss-2021-178', NULL, 'deck-prc-2021-ffss', 'Mongo is always being offered every Friday in the cafeteria. This regular daily feature is called ___.', 'Du Jour', 'A special dish featured consistently on a specific recurring day of the week functions as a daily special / specialty of the day (Du Jour).', '["Cycle Menu","Du Jour","Table D'' Hote","Ala Carte"]'::jsonb, '["PRC-2021","FFSS","Menu Planning","Menu Terminology"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 178. Menu terms: Du Jour special.', '{"dueDate":"2026-11-07T04:08:09.906Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:08:09.906Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:08:09.906Z"'::jsonb),
('card-ffss-2021-179', NULL, 'deck-prc-2021-ffss', 'A standard school cafeteria is an example of ___ operation.', 'Conventional', 'School cafeterias typically operate on a conventional foodservice model where raw ingredients are purchased, prepared, cooked, and served to students on the same premises.', '["Assembly Serve","Commissary","Cook Chill","Conventional"]'::jsonb, '["PRC-2021","FFSS","Foodservice Systems","Operational Models"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 179. Conventional foodservice operations.', '{"dueDate":"2026-11-06T17:26:01.918Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:26:01.918Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:26:01.918Z"'::jsonb),
('card-ffss-2021-18', NULL, 'deck-prc-2021-ffss', 'The "A" in FATTOM, an acronym used to describe the conditions in microbial growth, means ___.', 'acidity', 'FATTOM: Food, Acidity (pH 4.6–7.5), Time, Temperature (4°C–60°C), Oxygen, and Moisture (Aw ≥ 0.85).', '["alkalinity","agent","acidity","anti-bacterial"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Food Safety"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 18. FATTOM conditions for bacterial growth.', '{"dueDate":"2026-11-06T17:36:08.815Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:36:08.815Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:36:08.815Z"'::jsonb),
('card-ffss-2021-180', NULL, 'deck-prc-2021-ffss', 'The three-compartment sink should be placed in ___ area.', 'Dishwashing', 'The three-compartment sink (Wash with detergent at 110°F, Rinse in clean water, Sanitize in 171°F water or chemical sanitizer) is the core fixture of manual warewashing in the dishwashing/scullery area.', '["Dining","Dishwashing","Cooking","Receiving"]'::jsonb, '["PRC-2021","FFSS","Sanitation","Dishwashing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 180. Three-compartment sink location.', '{"dueDate":"2026-11-06T16:49:34.315Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:49:34.315Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:49:34.315Z"'::jsonb),
('card-ffss-2021-181', NULL, 'deck-prc-2021-ffss', 'The exhaust hood with filter should be placed in ___ area.', 'Cooking', 'Ventilation and exhaust hoods with grease filters must be positioned directly above thermal cooking equipment (ranges, fryers, griddles) to capture grease vapors, smoke, steam, and heat.', '["Serving","Cooking","Dishwashing","Storage"]'::jsonb, '["PRC-2021","FFSS","Facility Planning","Equipment"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 181. Ventilation hood placement.', '{"dueDate":"2026-11-06T17:07:49.858Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:07:49.858Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:07:49.858Z"'::jsonb),
('card-ffss-2021-182', NULL, 'deck-prc-2021-ffss', 'The architect considered the standard clearance width of the main traffic aisle which is ___.', '5ft', 'In commercial kitchen and cafeteria facility layout, the main traffic aisle through which mobile carts and two-way personnel traffic move requires a minimum clearance of 5 feet (60 inches). Single-cook work aisles require 3 feet.', '["3ft","7ft","14ft","5ft"]'::jsonb, '["PRC-2021","FFSS","Facility Planning","Kitchen Dimensions"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 182. Aisle spacing: Main traffic aisle = 5 ft; cook aisle = 3 ft.', '{"dueDate":"2026-11-07T04:13:51.438Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:13:51.438Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:13:51.438Z"'::jsonb),
('card-ffss-2021-183', NULL, 'deck-prc-2021-ffss', 'Bona, the owner, would like to test which of her two Strawberry smoothies'' formulation is better. What test can she conduct?', 'Paired comparison', 'Paired comparison sensory testing presents panelists with two coded samples simultaneously to evaluate which sample has greater attribute intensity (e.g., sweetness) or overall preference.', '["Cohort","Duo-trio test","Focus group discussion","Paired comparison"]'::jsonb, '["PRC-2021","FFSS","Sensory Evaluation","Product Testing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 183. Sensory testing: Paired comparison between 2 samples.', '{"dueDate":"2026-11-06T17:32:03.450Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:32:03.450Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:32:03.450Z"'::jsonb),
('card-ffss-2021-184', NULL, 'deck-prc-2021-ffss', 'The cafe is operating on a 35% food cost. If the raw food cost of an Apple Carrot smoothie is Php 50, what will be the selling price?', 'Php 145', 'Selling Price = Raw Food Cost ÷ Food Cost Percentage = Php 50 ÷ 0.35 = Php 142.86, rounded to the nearest standard menu price of Php 145.00.', '["Php 85","Php 125","Php 145","Php 100"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Pricing"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 184. Margin calculation: 50 / 0.35 = 142.86 -> Php 145.', '{"dueDate":"2026-11-07T04:07:49.312Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:07:49.312Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:07:49.312Z"'::jsonb),
('card-ffss-2021-185', NULL, 'deck-prc-2021-ffss', 'The architect considered the standard clearance width for a single worker station aisle:', '3ft', 'For a single kitchen workstation aisle where only one cook operates, the minimum recommended safe passage width is 3 feet (36 inches).', '["1ft","2ft","5ft","3ft"]'::jsonb, '["PRC-2021","FFSS","Facility Planning","Ergonomics"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 185. Single worker aisle = 3 feet.', '{"dueDate":"2026-11-06T16:52:54.423Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:52:54.423Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:52:54.423Z"'::jsonb),
('card-ffss-2021-186', NULL, 'deck-prc-2021-ffss', 'Carlos prepares broccoli and spinach juice. Adding lemon juice in it will change the color to ___.', 'olive green', 'Chlorophyll pigments in green vegetables are acid-labile; the hydrogen ions from lemon juice displace the central magnesium atom in chlorophyll, converting it into dull olive-brown pheophytin.', '["no effect","little effect","olive green","purple"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Pigments"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 186. Chlorophyll + Acid = Pheophytin (olive green).', '{"dueDate":"2026-11-06T17:34:04.216Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:34:04.216Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:34:04.216Z"'::jsonb),
('card-ffss-2021-187', NULL, 'deck-prc-2021-ffss', 'Adding lemon juice in carrot juice will have ___.', 'bright yellow', 'Carotenoid pigments are fat-soluble and exceptionally stable across varying pH levels, but mild acidification in fresh juices clarifies the suspension and yields a bright yellow-orange tone.', '["bright yellow","no effect on the color","dark effect on color","little effect on the color"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Carotenoids"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 187. Carotenoid stability in acid.', '{"dueDate":"2026-11-07T04:15:16.927Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:15:16.927Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:15:16.927Z"'::jsonb),
('card-ffss-2021-188', NULL, 'deck-prc-2021-ffss', 'Adding lemon juice in beetroot juice will have ___.', 'bright red color', 'Betalain pigments in beetroot (specifically red betacyanins) shift to a vibrant, intense bright red/purplish-red hue in acidic environments (pH 4–5).', '["bright red color","no effect on the color","pink color","dark blue color"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Betalains"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 188. Betalains in acid = Bright red.', '{"dueDate":"2026-11-06T17:28:24.867Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:28:24.867Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:28:24.867Z"'::jsonb),
('card-ffss-2021-189', NULL, 'deck-prc-2021-ffss', 'Skygazer offers Kalderetang Kambing which is "menu for the day" or also called ___.', 'Du Jour', '''Menu for the day'' is designated as Du Jour (or Menu du Jour) in French culinary dining service nomenclature.', '["Extensive Menu","Du Jour","California Menu","Ala carte"]'::jsonb, '["PRC-2021","FFSS","Menu Terminology","Culinary French"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 189. Menu du Jour.', '{"dueDate":"2026-11-06T17:23:00.067Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:23:00.067Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:23:00.067Z"'::jsonb),
('card-ffss-2021-19', NULL, 'deck-prc-2021-ffss', 'These are non-digestible food substances that stimulate the growth of good bacteria in the gut.', 'Prebiotics', 'Prebiotics are non-digestible dietary fibers (e.g., fructooligosaccharides, inulin) that nourish and stimulate the proliferation of beneficial probiotic bacteria.', '["Probiotics","Functional food","Phytochemicals","Prebiotics"]'::jsonb, '["PRC-2021","FFSS","Nutraceuticals","Digestion"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 19. Prebiotics = non-digestible fiber food for bacteria; Probiotics = live beneficial organisms.', '{"dueDate":"2026-11-07T04:08:35.935Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:08:35.935Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:08:35.935Z"'::jsonb),
('card-ffss-2021-190', NULL, 'deck-prc-2021-ffss', 'The total raw food cost of Kalderetang Kambing yielding 20 portions is Php 1,000. To keep the raw food cost at 40%, the selling price per portion should be ___.', 'Php 125', 'Cost per portion = Php 1,000 ÷ 20 = Php 50. Selling price = Php 50 ÷ 0.40 = Php 125.00.', '["Php 75","Php 100","Php 125","Php 50"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Pricing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 190. Margin calculation: 1000/20 = 50; 50 / 0.40 = Php 125.', '{"dueDate":"2026-11-06T17:03:01.735Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:03:01.735Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:03:01.735Z"'::jsonb),
('card-ffss-2021-191', NULL, 'deck-prc-2021-ffss', 'The most economical and effective way to promote a newly opened neighborhood restaurant is through ___.', 'social media', 'Social media digital marketing provides the lowest cost per impression, viral visual reach, geo-targeted audience promotion, and interactive consumer engagement.', '["Word of mouth","flyers and coupon","social media","newspaper and radio"]'::jsonb, '["PRC-2021","FFSS","Foodservice Marketing","Promotion"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 191. Contemporary foodservice marketing.', '{"dueDate":"2026-11-07T04:13:15.305Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:13:15.305Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:13:15.305Z"'::jsonb),
('card-ffss-2021-192', NULL, 'deck-prc-2021-ffss', 'Wilma''s catering is responsible for providing meals for a wedding where the couple are strict vegetarians. Which of the following dishes was NOT accepted by the couple?', 'Broccoli in oyster sauce', 'Traditional oyster sauce is prepared by condensing oyster broth extracted from bivalve mollusks (animal origin), making it strictly forbidden for vegetarians.', '["Spinach lasagna","Eggplant parmigiana","Broccoli in oyster sauce","French beans with hummus dip"]'::jsonb, '["PRC-2021","FFSS","Menu Planning","Vegetarianism"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 192. Vegetarian menu planning: Oyster sauce is animal-derived.', '{"dueDate":"2026-11-07T04:14:35.167Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:14:35.167Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:14:35.167Z"'::jsonb),
('card-ffss-2021-193', NULL, 'deck-prc-2021-ffss', 'A buko pandan recipe requires 12 cups of quick-cooking tapioca. Tapioca is purchased in cases of 24 boxes (each box weighs 1kg). Each case costs Php 1,500. If each cup weighs 200g, what is the recipe cost for tapioca?', 'Php 150', 'Weight needed = 12 cups × 200g = 2,400g = 2.4 kg. 1 case contains 24 boxes × 1 kg = 24 kg, costing Php 1,500. Cost per kg = Php 1,500 ÷ 24 kg = Php 62.50/kg. Recipe cost = 2.4 kg × Php 62.50 = Php 150.00.', '["Php 125","Php 150","Php 90","Php 2400"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Purchasing Math"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 193. Margin calculation: 12×200=2400g=2.4kg; 1500/24=62.5; 2.4×62.5 = Php 150.', '{"dueDate":"2026-11-07T04:00:36.232Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:00:36.232Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:00:36.232Z"'::jsonb),
('card-ffss-2021-194', NULL, 'deck-prc-2021-ffss', 'What kind of soup can be served during the vegetarian wedding dinner?', 'Cream of mushroom', 'Cream of mushroom prepared with mushrooms, vegetable broth, and dairy cream is suitable for lacto-vegetarians. Fish balls, crab, and traditional Tom Yum (shrimp broth/fish sauce) contain seafood.', '["Fish ball noodle soup","Tom Yum","Crab and corn","Cream of mushroom"]'::jsonb, '["PRC-2021","FFSS","Menu Planning","Vegetarianism"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 194. Vegetarian soup selections.', '{"dueDate":"2026-11-06T16:55:27.977Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:55:27.977Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:55:27.977Z"'::jsonb),
('card-ffss-2021-195', NULL, 'deck-prc-2021-ffss', 'Which is NOT mandatory to be declared on prepackaged food container labels under Philippine FDA labeling standards?', 'Wise Eat logo', 'Mandatory Philippine FDA food labeling rules require product name, ingredient list, net contents, manufacturer details, and nutrition facts. Commercial marketing logos (like ''Wise Eat'') are purely optional branding.', '["Nutritive value","Wise Eat logo","List of Ingredients","Net content"]'::jsonb, '["PRC-2021","FFSS","Food Laws","Labeling Requirements"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 195. FDA mandatory labeling requirements.', '{"dueDate":"2026-11-07T04:09:13.212Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:09:13.212Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:09:13.212Z"'::jsonb),
('card-ffss-2021-196', NULL, 'deck-prc-2021-ffss', 'If a food product contains 15g of carbohydrates, 5g of fats and 10g of protein, how much is the total energy value?', '145 kcal', 'Atwater energy factors: (15g CHO × 4 kcal) + (10g PRO × 4 kcal) + (5g FAT × 9 kcal) = 60 + 40 + 45 = 145 kcal.', '["120 kcal","30 kcal","145 kcal","200 kcal"]'::jsonb, '["PRC-2021","FFSS","Nutrition Math","Atwater Factors"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 196. Margin calculation: 15×4=60, 10×4=40, 5×9=45 -> 145 kcal.', '{"dueDate":"2026-11-06T17:26:27.947Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:26:27.947Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:26:27.947Z"'::jsonb)
