INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-ffss-2021-197', NULL, 'deck-prc-2021-ffss', 'The FDA evaluator would exempt this product from nutrition labelling:', 'Ketchup with less than 10 cm surface area', 'Under Codex and FDA labeling regulations, single-serve condiment packets and small packages with a total printable surface area under 10 cm² are exempt from mandatory nutrition facts panels due to space limitations.', '["soft drinks in can","Milk for infants less than 2 years of age","Pre-packaged cup cake","Ketchup with less than 10 cm surface area"]'::jsonb, '["PRC-2021","FFSS","Food Labeling","FDA Regulations"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 197. Packaging area < 10 cm² exemption.', '{"dueDate":"2026-11-07T04:05:25.946Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:05:25.946Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:05:25.946Z"'::jsonb),
('card-ffss-2021-198', NULL, 'deck-prc-2021-ffss', 'A standard university cafeteria is classified as ___ foodservice system.', 'Conventional', 'University cafeterias traditionally operate conventional systems with complete kitchen equipment where raw food is cooked on-site and held hot for immediate cafeteria counter service.', '["Assembly served","Commissary","Ready prepared","Conventional"]'::jsonb, '["PRC-2021","FFSS","Foodservice Systems","Cafeteria Operations"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 198. Cafeteria foodservice system classification.', '{"dueDate":"2026-11-06T17:29:26.275Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:29:26.275Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:29:26.275Z"'::jsonb),
('card-ffss-2021-199', NULL, 'deck-prc-2021-ffss', 'Fast foods such as McDonald''s, Jollibee and KFC utilize standardized pre-portioned bulk commissary items and rapid finishing on-site, falling under ___.', 'Assembly served', 'Modern quick-service chains rely heavily on assembly-serve (or commissary-assembly) principles where pre-breaded patties, portioned sauces, and par-fried items are delivered frozen and quickly assembled/finished with minimal culinary skill.', '["Commissary","Ready prepared","Conventional","Assembly served"]'::jsonb, '["PRC-2021","FFSS","Foodservice Systems","Quick Service"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 199. Fast food systems: Assembly served.', '{"dueDate":"2026-11-07T04:17:16.366Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-06T04:17:16.366Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:17:16.366Z"'::jsonb),
('card-ffss-2021-2', NULL, 'deck-prc-2021-ffss', 'Overboiling of egg will result to ___.', 'Coagulation', 'Excessive heat causes overcoagulation of egg white and yolk proteins, causing syneresis and the formation of a dark grayish-green ferrous sulfide ring at the yolk-white interface.', '["Formation of acrolein","Coagulation","Gelatinization","Rancidity"]'::jsonb, '["PRC-2021","FFSS","Egg Cookery","Protein Reactions"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 2. Margin notes: Acrolein = overheating fat; Gelatinization = cereal/starch; Rancidity = spoilage in oil.', '{"dueDate":"2026-11-06T17:29:34.040Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:29:34.040Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:29:34.040Z"'::jsonb),
('card-ffss-2021-20', NULL, 'deck-prc-2021-ffss', 'It is an organism able to grow at high temperature.', 'Thermophiles', 'Thermophiles thrive in hot temperatures, typically between 45°C and 80°C (113°F–176°F). Psychrotrophs grow at cold temperatures (0°C–7°C).', '["Virus","Psychrotrophs","Thermophiles","Bacteria"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Temperature Classification"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 20. Microbial temperature classifications.', '{"dueDate":"2026-11-07T04:00:41.515Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:00:41.515Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:00:41.515Z"'::jsonb),
('card-ffss-2021-200', NULL, 'deck-prc-2021-ffss', 'Sandwiches and chilled meals displayed in the glass chillers of 7-Eleven, AlfaMart, and Ministop are all examples of ___ foodservice items.', 'Ready prepared', 'Ready-prepared foodservice items are cooked in advance, rapidly chilled (cook-chill) or frozen, and stored under cold refrigeration for extended shelf-life before purchase and microwave reheating by consumers.', '["Ready prepared","Conventional","Commissary","Assembly served"]'::jsonb, '["PRC-2021","FFSS","Foodservice Systems","Cook-Chill"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 200. Convenience store chiller meals: Ready-prepared / Cook-chill.', '{"dueDate":"2026-11-07T04:16:52.229Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:16:52.229Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:16:52.229Z"'::jsonb),
('card-ffss-2021-21', NULL, 'deck-prc-2021-ffss', 'This occurs during the first five minutes of baking due to the acceleration of fermentation due to the heat, causing the rise of the dough.', 'Oven spring', 'Oven spring is the sudden rapid expansion of dough during early baking, driven by thermal expansion of trapped carbon dioxide and accelerated yeast activity before thermal death.', '["Gelatinization","Punching","Proofing","Oven spring"]'::jsonb, '["PRC-2021","FFSS","Baking","Yeast Fermentation"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 21. Baking dynamics.', '{"dueDate":"2026-11-06T17:25:04.280Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:25:04.280Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:25:04.280Z"'::jsonb),
('card-ffss-2021-22', NULL, 'deck-prc-2021-ffss', 'Identify the dishes which are popular in Mindanao Region.', 'Bas-uy, Linat-an and Paklay', 'Bas-uy (liver soup), Linat-an (boiled pork bone soup), and Paklay (spiced pork/beef innards) are widely known regional specialties of Mindanao and Central/Southern Visayas.', '["Sinigang na Kanduli, Sisig and Bringhe","Laing, Tinuktok and Sinanglay","Apan-apan, Chicken Binakol and Utan","Bas-uy, Linat-an and Paklay"]'::jsonb, '["PRC-2021","FFSS","Regional Cuisines","Philippine Culture"]'::jsonb, 'Foods and Food Service Systems', 'hard', 2, 'PRC NDLE Oct 2021 Set B, Item 22. Philippine regional cuisine mapping.', '{"dueDate":"2026-11-06T16:59:08.870Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:59:08.870Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:59:08.870Z"'::jsonb),
('card-ffss-2021-23', NULL, 'deck-prc-2021-ffss', 'Food is hot filled into the container then sealed under aseptic conditions and processed immediately is called ___.', 'Hot pack method', 'In the hot pack method, heated food is packed hot into jars or cans, driving out air and ensuring quicker heat penetration during final canning/retort processing.', '["Open kettle","Hot pack method","Cold pack method","Pasteurization"]'::jsonb, '["PRC-2021","FFSS","Food Preservation","Canning"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 23. Canning methods: Hot pack vs Raw/Cold pack.', '{"dueDate":"2026-11-07T04:14:45.949Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:14:45.949Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:14:45.949Z"'::jsonb),
('card-ffss-2021-24', NULL, 'deck-prc-2021-ffss', 'The browning of baked products is due to ___.', 'Maillard reaction', 'Maillard browning occurs when amino acids and reducing sugars interact under dry heat, creating golden-brown pigments (melanoidins) and pleasant roasted flavors.', '["chymosin","enzymatic browning","buffering","Maillard reaction"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Baking"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 24. Non-enzymatic browning.', '{"dueDate":"2026-11-06T17:32:40.319Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:32:40.319Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:32:40.319Z"'::jsonb),
('card-ffss-2021-25', NULL, 'deck-prc-2021-ffss', 'What is a right of employees concerning vacation leaves, working hours and holidays?', 'Right to be paid accordingly', 'Under the Labor Code of the Philippines, employees have statutory entitlements to proper payment for work performed, statutory holiday premiums, and approved service incentive leaves.', '["Right to be paid accordingly","Right to a meal allowance","Right for emergency allowance","Minimum wage"]'::jsonb, '["PRC-2021","FFSS","Foodservice Management","Labor Code"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 25. Labor law rights.', '{"dueDate":"2026-11-06T16:35:18.183Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:35:18.183Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:35:18.183Z"'::jsonb),
('card-ffss-2021-26', NULL, 'deck-prc-2021-ffss', 'Which government agency is responsible in licensing, monitoring, and regulating the food products being sold in the market?', 'Food and Drug Administration', 'The Food and Drug Administration (FDA) of the Philippines regulates and licenses processed foods, drugs, and cosmetics under Republic Act No. 9711.', '["Food and Nutrition Research Institute","Bureau of Food and Fisheries","Bureau of Food and Drugs","Food and Drug Administration"]'::jsonb, '["PRC-2021","FFSS","Food Laws","Regulatory Agencies"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 26. Regulatory agencies: FDA.', '{"dueDate":"2026-11-06T17:07:34.939Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:07:34.939Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:07:34.939Z"'::jsonb),
('card-ffss-2021-27', NULL, 'deck-prc-2021-ffss', 'Which is a type of food spoilage that includes enzymatic reactions in living things as influenced by temperature, moisture, pH and the nutrients present?', 'Biochemical spoilage', 'Biochemical spoilage (autolysis) involves the action of natural enzymes already present within animal or plant tissues after harvest or slaughter.', '["Spoilage by microorganisms","Biochemical spoilage","Chemical deterioration","Physical deterioration"]'::jsonb, '["PRC-2021","FFSS","Food Spoilage","Enzymology"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 27. Food deterioration types: biochemical / autolysis.', '{"dueDate":"2026-11-07T04:16:10.736Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:16:10.736Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:16:10.736Z"'::jsonb),
('card-ffss-2021-28', NULL, 'deck-prc-2021-ffss', 'The labor cost for a certain dish is Php20 per hour. If it takes 45 minutes to make the dish, what is the labor cost for this particular dish?', 'Php15', 'Labor cost = Hourly rate × (45 / 60 hours) = Php 20 × 0.75 = Php 15.00.', '["Php 10","Php15","Php45","Php20"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","Labor Costing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 28. Margin formula: 20 × (45/60) = 15.', '{"dueDate":"2026-11-06T17:29:17.178Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:29:17.178Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:29:17.178Z"'::jsonb),
('card-ffss-2021-29', NULL, 'deck-prc-2021-ffss', 'The enzyme which is important for cheese production is ___.', 'renin', 'Renin (chymosin / rennet) hydrolyzes the Phe105-Met106 peptide bond in kappa-casein, causing milk proteins to coagulate into curd.', '["papain","renin","bromelain","polyphenol oxidase"]'::jsonb, '["PRC-2021","FFSS","Dairy Processing","Enzymes"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 29. Cheese making enzymes: Renin / Chymosin.', '{"dueDate":"2026-11-06T16:59:24.549Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:59:24.549Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:59:24.549Z"'::jsonb),
('card-ffss-2021-3', NULL, 'deck-prc-2021-ffss', 'What condition favors the growth of Clostridium botulinum?', 'Absence of air and low acidic environment', 'Clostridium botulinum is an obligate anaerobe that thrives in low-acid conditions (pH > 4.6) in the absence of oxygen, producing a potent neurotoxin.', '["At very high temperature","Absence of air and low acidic environment","At freezing temperature","Presence of air and high acidic environment"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Food Safety"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 3. Anaerobic, low-acid canning hazard.', '{"dueDate":"2026-11-06T16:37:09.281Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:37:09.281Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:37:09.281Z"'::jsonb),
('card-ffss-2021-30', NULL, 'deck-prc-2021-ffss', 'The softest cheese among the following is ___.', 'Brie', 'Brie is a soft-ripened cheese containing over 50% moisture, making it much softer than semi-hard (Gouda, Edam) and hard (Cheddar) cheeses.', '["Gouda","Edam","Brie","Cheddar"]'::jsonb, '["PRC-2021","FFSS","Dairy","Food Classification"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 30. Cheese moisture classifications: Brie is soft cheese.', '{"dueDate":"2026-11-06T17:32:33.363Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:32:33.363Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:32:33.363Z"'::jsonb),
('card-ffss-2021-31', NULL, 'deck-prc-2021-ffss', 'Choose a form of disaccharide usually used in the production of beer.', 'Maltose', 'Maltose (malt sugar, consisting of two alpha-D-glucose molecules) is generated during the malting and mashing of barley grains and is fermented by yeast into ethanol in brewing.', '["Sucrose","Lactose","Maltose","Glucose"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Fermentation"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 31. Beer fermentation: Maltose from malted barley.', '{"dueDate":"2026-11-06T17:00:34.227Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:00:34.227Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:00:34.227Z"'::jsonb),
('card-ffss-2021-32', NULL, 'deck-prc-2021-ffss', 'Essential amino acids are ___.', 'histidine, isoleucine, leucine', 'The 9 essential amino acids that must be supplied by diet are Histidine, Isoleucine, Leucine, Lysine, Methionine, Phenylalanine, Threonine, Tryptophan, and Valine (mnemonic: PVT TIM HLL).', '["aspartic acid, cysteine, glutamic acid","alanine, arginine, asparagine","histidine, isoleucine, leucine","proline, serine, tyrosine"]'::jsonb, '["PRC-2021","FFSS","Nutrition Science","Amino Acids"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 32. Mnemonic: PVT TIM HLL.', '{"dueDate":"2026-11-06T16:59:53.144Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:59:53.144Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:59:53.144Z"'::jsonb),
('card-ffss-2021-33', NULL, 'deck-prc-2021-ffss', 'Which is NOT true about Churros?', 'It is a baked pastry.', 'Churros are piped choux-like dough that is deep-fried (not baked) in hot oil and traditionally served dusted with sugar/cinnamon alongside thick hot dipping chocolate.', '["It is like fried donut.","A Spanish cuisine","It is a baked pastry.","It is served with chocolate."]'::jsonb, '["PRC-2021","FFSS","Culinary Arts","Pastry & Baking"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 33. Deep-fried choux dough from Spain.', '{"dueDate":"2026-11-06T16:48:44.145Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:48:44.145Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:48:44.145Z"'::jsonb),
('card-ffss-2021-34', NULL, 'deck-prc-2021-ffss', 'During a review of customer feedback survey, Michelle, RND, noted a pattern of dissatisfaction with the consistency of the quality of the beef caldereta. The most likely cause for the problem would be ___.', 'the quality of the beef used not consistent with the specifications.', 'Inconsistent meat cuts, connective tissue tenderness, and fat marbling from unstandardized purchasing specifications cause variable meat texture and toughness across batches.', '["diners are unaware of the true taste of beef caldereta.","the quality of the beef used not consistent with the specifications.","the waiters are not using the appropriate size dishes when plating the dish","the cooks are not using the standardized recipe."]'::jsonb, '["PRC-2021","FFSS","Quality Control","Standardization"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 34. Quality control and purchasing specifications.', '{"dueDate":"2026-11-07T04:12:30.710Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:12:30.710Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:12:30.710Z"'::jsonb),
('card-ffss-2021-35', NULL, 'deck-prc-2021-ffss', 'What dish can be made to utilize leftover steamed kangkong from the last family dinner?', 'Utan', 'Utan (Visayan vegetable soup) readily incorporates leftover steamed leafy greens like kangkong. Baye-baye is a sweet rice delicacy; dinakdakan and sisig are grilled pork offal dishes.', '["Utan","Baye baye","Dinakdakan","Sisig"]'::jsonb, '["PRC-2021","FFSS","Food Preparation","Leftovers Management"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 35. Menu planning and leftovers utilization.', '{"dueDate":"2026-11-06T16:34:03.736Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:34:03.736Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:34:03.736Z"'::jsonb),
('card-ffss-2021-36', NULL, 'deck-prc-2021-ffss', 'The "F" in FATTOM, an acronym used to describe the conditions in microbial growth, means ___.', 'Food', 'The ''F'' in FATTOM stands for Food (specifically nutrients like proteins and carbohydrates that bacteria feed on).', '["Fasting","Food","Fahrenheit","Fat"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Food Safety"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 36. FATTOM conditions.', '{"dueDate":"2026-11-07T04:08:30.068Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:08:30.068Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:08:30.068Z"'::jsonb),
('card-ffss-2021-37', NULL, 'deck-prc-2021-ffss', 'Which kind of damage results from dehydration of a frozen breaded chicken patty due to extreme cold?', 'Freezer burn', 'Freezer burn is the dehydration and oxidation that occurs when frozen food is improperly wrapped, causing moisture sublimation and dry, bleached, spongy surfaces.', '["Crystallization","Freezer burn","Caking","Contamination due to excessive additives"]'::jsonb, '["PRC-2021","FFSS","Food Storage","Freezing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 37. Sublimation in frozen storage.', '{"dueDate":"2026-11-06T16:33:40.017Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:33:40.017Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:33:40.017Z"'::jsonb),
('card-ffss-2021-38', NULL, 'deck-prc-2021-ffss', 'How do you call the bacteria which can be found in powdered infant formula which can cause meningitis?', 'Enterobacter sakazakii', 'Enterobacter sakazakii (now Cronobacter sakazakii) is a pathogen known to contaminate powdered infant formula, causing severe neonatal necrotizing enterocolitis, sepsis, and meningitis.', '["Staphylococcus aureus","Clostridium botulinum","Bacillus cereus","Enterobacter sakazakii"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Infant Feeding"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 38. Cronobacter / Enterobacter sakazakii infant hazard.', '{"dueDate":"2026-11-06T17:02:15.970Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:02:15.970Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:02:15.970Z"'::jsonb),
('card-ffss-2021-39', NULL, 'deck-prc-2021-ffss', 'What will happen to sugar if it is heated above 160 degrees C?', 'Caramelization', 'Caramelization is the thermal decomposition of sucrose and other carbohydrates when dry heated to around 160°C–180°C, producing golden-brown color and buttery nutty flavors.', '["Burnt fat","Caramelization","Denaturation","Crystallization"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Sugar Cookery"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 39. Thermal breakdown of sugar = Caramelization.', '{"dueDate":"2026-11-06T17:32:26.330Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:32:26.330Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:32:26.330Z"'::jsonb),
('card-ffss-2021-4', NULL, 'deck-prc-2021-ffss', 'Which of the following milk products has the longest shelf life?', 'UHT Milk', 'Ultra-High Temperature (UHT) milk is commercially sterilized at 135–150°C and aseptically packaged, giving it a stable shelf life of 6 to 9 months at room temperature without refrigeration.', '["Fresh Milk","Evaporated milk","Condensed milk","UHT Milk"]'::jsonb, '["PRC-2021","FFSS","Dairy","Food Preservation"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 4. UHT aseptic packaging guarantees longest commercial shelf life at ambient temperature.', '{"dueDate":"2026-11-07T04:05:09.634Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:05:09.634Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:05:09.634Z"'::jsonb),
('card-ffss-2021-40', NULL, 'deck-prc-2021-ffss', 'Which department is NOT involved in the receiving process in hospital''s foodservice?', 'HR', 'Receiving involves the Dietary department (inspecting specifications), Purchasing (matching purchase orders), and Accounting (invoice/invoice tracking). Human Resources manages personnel, not daily delivery logistics.', '["Dietary","Accounting","Purchasing","HR"]'::jsonb, '["PRC-2021","FFSS","Foodservice Administration","Receiving"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 40. Foodservice department roles in receiving.', '{"dueDate":"2026-11-06T17:00:27.806Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:00:27.806Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:00:27.806Z"'::jsonb),
('card-ffss-2021-41', NULL, 'deck-prc-2021-ffss', 'The muscle pigment is called ___.', 'Myoglobin', 'Myoglobin is the primary iron- and oxygen-binding hemoprotein found in skeletal muscle tissues responsible for meat color. Hemoglobin is in red blood cells.', '["Hemoglobin","Nitroso myoglobin","Myoglobin","Nitrosohemochrome"]'::jsonb, '["PRC-2021","FFSS","Meat Science","Food Chemistry"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 41. Muscle pigment = Myoglobin.', '{"dueDate":"2026-11-06T17:33:51.641Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:33:51.641Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:33:51.641Z"'::jsonb),
('card-ffss-2021-42', NULL, 'deck-prc-2021-ffss', 'Select the BEST way to manage leftovers from the morning buffet at the hotel.', 'Sell leftovers at the employees'' cafeteria at low cost', 'Selling wholesome surplus buffet foods immediately in the employee cafeteria at subsidized rates recovers costs safely while avoiding customer food-safety liabilities of re-serving on buffets.', '["Serve the same food to the diners for lunch and dinner","Sell leftovers at the employees'' cafeteria at low cost","Freeze the leftover and serve the following day","Let the employees take out all the leftovers everyday"]'::jsonb, '["PRC-2021","FFSS","Food Waste Management","Foodservice Operations"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 42. Hotel buffet leftover management protocols.', '{"dueDate":"2026-11-06T17:35:46.503Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:35:46.503Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:35:46.503Z"'::jsonb),
('card-ffss-2021-43', NULL, 'deck-prc-2021-ffss', 'Which is true about passing the licensure examination for ND based on the ND law in 2016?', 'Must have a general average of 75% with no rating below 50% in any subjects', 'Under Republic Act No. 10862 (Nutrition and Dietetics Law of 2016), a candidate must obtain a General Weighted Average of at least 75%, with no grade below 50% in any given examination subject.', '["Must have a general average of 70% with no rating below 70% in any subjects","Must have a general average of 75% with no rating below 70% in any subjects","Must obtain at least 80% general average in all of the subjects","Must have a general average of 75% with no rating below 50% in any subjects"]'::jsonb, '["PRC-2021","FFSS","RA 10862","PRC Board Exam Rules"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 43. RA 10862 passing criteria: GWA >= 75%, no sub < 50%.', '{"dueDate":"2026-11-06T17:08:21.412Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:08:21.412Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:08:21.412Z"'::jsonb),
('card-ffss-2021-44', NULL, 'deck-prc-2021-ffss', 'Identify the thread-like noodles which made from cassava and wheat flour.', 'Miswa', 'Miswa is an extremely thin, thread-like salted Chinese-style noodle made from wheat flour and cassava/corn starch. (Sotanghon is made from mung bean starch; Canton is egg noodle).', '["Instant noodles","Miswa","Sotanghon","Canton"]'::jsonb, '["PRC-2021","FFSS","Philippine Foods","Noodle Classification"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 44. Miswa = thread-like wheat/cassava noodles.', '{"dueDate":"2026-11-06T16:58:51.409Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:58:51.409Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:58:51.409Z"'::jsonb),
('card-ffss-2021-45', NULL, 'deck-prc-2021-ffss', 'Lutong Bahay canteen is operating in Makati. All the food preparation is done in the area. It also accommodates short orders like pancit and tapsilog. This foodservice system is ___.', 'conventional', 'In a conventional foodservice system, ingredients are assembled and all food preparation and cooking are performed on-site immediately prior to service or short-order preparation.', '["ready-prepared","commissary","conventional","assembly serve"]'::jsonb, '["PRC-2021","FFSS","Foodservice Systems","Operational Models"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 45. Foodservice systems: Conventional = cook and serve on premises.', '{"dueDate":"2026-11-06T16:50:22.611Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:50:22.611Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:50:22.611Z"'::jsonb),
('card-ffss-2021-46', NULL, 'deck-prc-2021-ffss', 'Which of the following foods are responsible for most allergic reactions?', 'Egg, milk, peanuts', 'The ''Big 8'' major food allergens responsible for over 90% of allergic reactions include milk, eggs, peanuts, tree nuts, wheat, soy, fish, and crustacean shellfish.', '["Eggplant, tofu, soybeans","Chicken, beans, eggplant","Garlic, onion, pork","Egg, milk, peanuts"]'::jsonb, '["PRC-2021","FFSS","Food Safety","Allergens"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 46. Major food allergens (Big 8).', '{"dueDate":"2026-11-06T16:53:49.250Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:53:49.250Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:53:49.250Z"'::jsonb),
('card-ffss-2021-47', NULL, 'deck-prc-2021-ffss', 'What is the most cost-efficient way of scouting for an applicant for a mid-level to high-level position?', 'via Linkedin', 'LinkedIn provides targeted professional searches, resume viewing, and credential verification at lower cost and higher precision than general newspapers or broad job fairs.', '["via Linkedin","Publishing a position in newspaper","via Twitter","Conducting a job fair"]'::jsonb, '["PRC-2021","FFSS","Human Resources","Recruitment"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 47. Recruitment methods for management.', '{"dueDate":"2026-11-06T16:36:20.187Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:36:20.187Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:36:20.187Z"'::jsonb),
('card-ffss-2021-48', NULL, 'deck-prc-2021-ffss', 'Laing and Binagol are both dishes made from gabi leaves and coconut milk. Laing is a dish from Bicol while Binagol is from ___.', 'Eastern Visayas', 'Binagol is a sweet regional delicacy of Eastern Visayas (Leyte and Samar) made from mashed taro (talyan/gabi), coconut milk, condensed milk, and sugar packed into a coconut shell (bagol).', '["Batanes","Ilocos","Southern Tagalog","Eastern Visayas"]'::jsonb, '["PRC-2021","FFSS","Regional Cuisines","Philippine Culture"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 48. Binagol = Leyte/Samar (Eastern Visayas).', '{"dueDate":"2026-11-06T16:34:33.790Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:34:33.790Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:34:33.790Z"'::jsonb),
('card-ffss-2021-49', NULL, 'deck-prc-2021-ffss', 'Which is NOT a characteristic of a fresh egg?', 'Unporous shell', 'Eggshells naturally have 7,000 to 17,000 tiny porous openings that allow respiratory gas and moisture exchange; an ''unporous shell'' does not exist in nature.', '["Well concentrated egg yolk","Firm albumen","No germ spot","Unporous shell"]'::jsonb, '["PRC-2021","FFSS","Egg Cookery","Food Quality"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 49. Fresh egg quality: shells are always porous.', '{"dueDate":"2026-11-06T17:20:49.246Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:20:49.246Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:20:49.246Z"'::jsonb),
('card-ffss-2021-5', NULL, 'deck-prc-2021-ffss', 'This food additive is added in salad dressings to allow smooth mixture of ingredients without separation. Examples of this additive are soy lecithin and egg yolks.', 'Emulsifiers', 'Emulsifiers (like lecithin) possess both hydrophilic and lipophilic ends, stabilizing immiscible oil-and-water emulsions in dressings and sauces.', '["Humectants","Emulsifiers","Leavening agents","pH control agents"]'::jsonb, '["PRC-2021","FFSS","Food Additives","Emulsions"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 5. Emulsifiers prevent oil and water separation.', '{"dueDate":"2026-11-06T17:28:15.916Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:28:15.916Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:28:15.916Z"'::jsonb),
('card-ffss-2021-50', NULL, 'deck-prc-2021-ffss', 'How many pints are there in 1 quart?', '2 pints', 'Standard culinary volume conversions: 1 quart = 2 pints = 4 cups = 32 fluid ounces.', '["4 pints","2 pints","6 pints","8 pints"]'::jsonb, '["PRC-2021","FFSS","Weights & Measures","Kitchen Math"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 50. 1 quart = 2 pints.', '{"dueDate":"2026-11-06T17:06:55.346Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:06:55.346Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:06:55.346Z"'::jsonb),
('card-ffss-2021-51', NULL, 'deck-prc-2021-ffss', 'The three categories of food contaminants are best described as:', 'Chemical, Biological, and Physical Hazards', 'Standard HACCP and food safety classification groups all contaminants into Biological hazards (microorganisms), Chemical hazards (cleaning chemicals, toxins), and Physical hazards (glass, metal, bones).', '["Chemical, Customer, and Staff Hazards","External, Internal, and Customer Hazards","Chemical, Biological, and Physical Hazards","Human, Microbial, and Viral Hazards"]'::jsonb, '["PRC-2021","FFSS","Food Safety","HACCP"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 51. Three HACCP hazard pillars.', '{"dueDate":"2026-11-06T17:22:54.812Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:22:54.812Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:22:54.812Z"'::jsonb),
('card-ffss-2021-52', NULL, 'deck-prc-2021-ffss', 'Substances in plant-based foods with physiologically active compounds that have functional benefits are called ___.', 'Phytochemicals', 'Phytochemicals are naturally occurring biologically active chemical compounds found in plants (e.g., polyphenols, carotenoids, flavonoids) that provide health benefits and disease protection.', '["Probiotics","Phytochemicals","Functional food","Prebiotics"]'::jsonb, '["PRC-2021","FFSS","Nutraceuticals","Food Chemistry"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 52. Plant bioactives = Phytochemicals.', '{"dueDate":"2026-11-07T04:15:45.584Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:15:45.584Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:15:45.584Z"'::jsonb),
('card-ffss-2021-53', NULL, 'deck-prc-2021-ffss', 'The mother sauce of all white sauces is called ___.', 'Bechamel', 'Bechamel is one of the classic French grand mother sauces made by thickening warm milk with a white roux (equal parts butter and flour). Espagnole is brown sauce.', '["Roux","Espagnole","Consomme","Bechamel"]'::jsonb, '["PRC-2021","FFSS","Culinary Arts","Sauces"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 53. Classic French mother sauces: Bechamel = white sauce.', '{"dueDate":"2026-11-06T17:34:45.370Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:34:45.370Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:34:45.370Z"'::jsonb),
('card-ffss-2021-54', NULL, 'deck-prc-2021-ffss', 'This is a paste that is used to make hummus.', 'Tahini', 'Tahini is a smooth, rich paste made from toasted ground sesame seeds, a mandatory base ingredient blended with chickpeas, lemon, and garlic to make authentic hummus.', '["Yogurt","Bean curd","Tahini","Baba Ghanoush"]'::jsonb, '["PRC-2021","FFSS","Middle Eastern Cuisine","Culinary Arts"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 54. Tahini = sesame paste.', '{"dueDate":"2026-11-07T04:13:30.818Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:13:30.818Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:13:30.818Z"'::jsonb),
('card-ffss-2021-55', NULL, 'deck-prc-2021-ffss', 'Oxidative rancidity happens in foods that have ___.', 'High in unsaturated fat', 'Oxidative rancidity occurs when oxygen attacks double bonds of unsaturated fatty acids (polyunsaturated fats), forming lipid hydroperoxides that break down into foul-smelling aldehydes and ketones.', '["High in saturated fat","High in moisture content","High in protein content","High in unsaturated fat"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Lipids"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 55. Oxidation targets unsaturated double bonds.', '{"dueDate":"2026-11-06T17:02:25.719Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:02:25.719Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:02:25.719Z"'::jsonb),
('card-ffss-2021-56', NULL, 'deck-prc-2021-ffss', 'When one person or department purchases for every department, it is called ___.', 'Centralized', 'Centralized purchasing designates a single purchasing manager or procurement department to handle all purchasing across every department in the organization, maximizing volume discounts.', '["Open market","Centralized","E-commerce","Bidding"]'::jsonb, '["PRC-2021","FFSS","Purchasing","Foodservice Administration"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 56. Centralized purchasing structure.', '{"dueDate":"2026-11-06T16:56:39.378Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:56:39.378Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:56:39.378Z"'::jsonb),
('card-ffss-2021-57', NULL, 'deck-prc-2021-ffss', 'If you open sealed bids and place the order with the lowest bid, you are using which buying method?', 'Competitive bid', 'Competitive formal bidding requires vendors to submit sealed quotations based on tight specifications, which are opened publicly at a designated date to select the lowest qualified bidder.', '["Open market","Informal bid","Competitive bid","E-commerce"]'::jsonb, '["PRC-2021","FFSS","Purchasing","Procurement"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 57. Purchasing methods: Competitive sealed bidding.', '{"dueDate":"2026-11-06T17:31:40.962Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:31:40.962Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:31:40.962Z"'::jsonb),
('card-ffss-2021-58', NULL, 'deck-prc-2021-ffss', 'Which of the following factors would be MOST important to determine the food cost per serving for fruits and vegetables?', 'Edible portion', 'Fruits and vegetables produce variable trim, peeling, and seed losses. The Edible Portion (EP) weight and EP yield percentage determine the true raw ingredient cost per portion.', '["Maturity and availability","Edible portion","Budget allocation","Size and shape"]'::jsonb, '["PRC-2021","FFSS","Costing & Calculation","EP/AP Yield"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 58. Edible Portion (EP) determines true serving cost.', '{"dueDate":"2026-11-06T17:12:11.595Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:12:11.595Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:12:11.595Z"'::jsonb),
('card-ffss-2021-59', NULL, 'deck-prc-2021-ffss', 'Rigor mortis is an example of ___ spoilage.', 'Biochemical', 'Rigor mortis is an endogenous biochemical process resulting from post-mortem anaerobic glycolysis, lactic acid buildup, ATP depletion, and irreversible actin-myosin cross-linking.', '["Physical","Biochemical","Chemical","Microorganism-caused"]'::jsonb, '["PRC-2021","FFSS","Meat Science","Food Chemistry"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 59. Post-mortem biochemical muscle changes.', '{"dueDate":"2026-11-06T17:34:13.867Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:34:13.867Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:34:13.867Z"'::jsonb),
('card-ffss-2021-6', NULL, 'deck-prc-2021-ffss', 'How do you ensure tenderness of a thick crust pizza?', 'Apply oil or soft fats on the crust before cooking', 'Applying fats or oil coats gluten strands and locks in internal dough moisture, ensuring the thick crust stays tender, pliable, and soft rather than excessively dry and brittle.', '["Lower the temperature and slow cook","Apply oil or soft fats on the crust before cooking","Add more vegetables as toppings after cooking","Add more pineapple as toppings during cooking"]'::jsonb, '["PRC-2021","FFSS","Baking","Food Preparation"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 6. Fats shorten gluten strands to promote tenderness.', '{"dueDate":"2026-11-07T04:16:15.772Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:16:15.772Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:16:15.772Z"'::jsonb),
('card-ffss-2021-60', NULL, 'deck-prc-2021-ffss', 'A cold soup in Spanish cuisine which contains cucumber, peppers, tomatoes, oils, vinegar, and bread:', 'Gazpacho', 'Gazpacho is an Andalusian Spanish cold soup made of blended raw ripe tomatoes, sweet bell peppers, cucumber, garlic, stale bread, olive oil, and sherry vinegar.', '["Cold Sopas","Paella","Gazpacho","Vichyssoise"]'::jsonb, '["PRC-2021","FFSS","Culinary Arts","International Cuisines"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 60. Gazpacho = cold Spanish tomato-cucumber soup.', '{"dueDate":"2026-11-07T04:03:09.076Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:03:09.076Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:03:09.076Z"'::jsonb)
