INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-ffss-2021-61', NULL, 'deck-prc-2021-ffss', 'Aspergillus niger: ___; Sarcina lutea: ___.', 'Black; yellow', 'Aspergillus niger produces characteristic black mold colonies, while Sarcina lutea (Micrococcus luteus) produces bright yellow pigment colonies.', '["Brown; yellow","Brown; red","Black; yellow","Red; yellow"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Microbial Spoilage"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 61. Microbial pigmentation: A. niger = black; S. lutea = yellow.', '{"dueDate":"2026-11-06T17:07:07.074Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:07:07.074Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:07:07.074Z"'::jsonb),
('card-ffss-2021-62', NULL, 'deck-prc-2021-ffss', 'What will you add to marshmallow to retain the moisture?', 'Humectant', 'Humectants (such as sorbitol, glycerol, or invert sugar) are hygroscopic substances incorporated into confections to bind water and retain moisture, preventing staling and drying.', '["Leavening agent","Humectant","Nutrients","Flavor enhancer"]'::jsonb, '["PRC-2021","FFSS","Food Additives","Confectionery"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 62. Humectants retain moisture in confections.', '{"dueDate":"2026-11-06T17:35:28.236Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:35:28.236Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:35:28.236Z"'::jsonb),
('card-ffss-2021-63', NULL, 'deck-prc-2021-ffss', 'Which of the following is NOT a beef?', 'Game', 'Game refers to hunted wild birds or non-domesticated mammals (like venison, pheasant, wild boar). Cow, heifer, and stag are bovine cattle classes.', '["Cow","Heifer","Game","Stag"]'::jsonb, '["PRC-2021","FFSS","Meat Science","Classification"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 63. Bovine classifications vs Game.', '{"dueDate":"2026-11-07T04:04:32.150Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:04:32.150Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:04:32.150Z"'::jsonb),
('card-ffss-2021-64', NULL, 'deck-prc-2021-ffss', 'Which is the second step in undertaking a research study in Foodservice?', 'State goals and objectives', 'In standard research methodology: Step 1 is selecting/determining the research topic, followed immediately by Step 2: identifying the problem and stating specific goals and objectives.', '["Determine a research topic","Prepare a conceptual framework","State goals and objectives","Define scope and limitations"]'::jsonb, '["PRC-2021","FFSS","Research Methodology","Foodservice Administration"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 64. Research steps: 1=topic, 2=goals/objectives.', '{"dueDate":"2026-11-06T17:36:23.563Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:36:23.563Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:36:23.563Z"'::jsonb),
('card-ffss-2021-65', NULL, 'deck-prc-2021-ffss', 'Foods that are decomposed or produced in unsanitary conditions are considered ___.', 'Adulterated Foods', 'Under the Food, Drug, and Cosmetic Act, a food is deemed ''adulterated'' if it consists in whole or in part of any filthy, putrid, or decomposed substance, or if it was prepared under unsanitary conditions.', '["Potable","Adulterated Foods","Gourmet","Potentially Hazardous Foods"]'::jsonb, '["PRC-2021","FFSS","Food Laws","Food Safety"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 65. Legal definition of Adulterated Food.', '{"dueDate":"2026-11-07T04:15:10.216Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:15:10.216Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:15:10.216Z"'::jsonb),
('card-ffss-2021-66', NULL, 'deck-prc-2021-ffss', 'A bacon spread has a serving size of 30 g. What is the equivalent household measurement?', '2 tablespoons', 'In standard Philippine dietary food exchange lists and household measurements, 1 tablespoon of semi-solid spread or condiment is approximately 15 grams; hence 30 grams = 2 tablespoons.', '["1 tablespoon","1 teaspoon","2 teaspoons","2 tablespoons"]'::jsonb, '["PRC-2021","FFSS","Weights & Measures","Food Exchange List"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 66. 1 tbsp = 15g; 2 tbsp = 30g.', '{"dueDate":"2026-11-07T04:07:57.635Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:07:57.635Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:07:57.635Z"'::jsonb),
('card-ffss-2021-67', NULL, 'deck-prc-2021-ffss', 'If the original yield of a macaroni salad recipe is 2.5 kg and you need only 1.5 kg to serve your guests, what will be the conversion factor of each ingredient to be used in the recipe?', '0.6', 'Recipe Conversion Factor (RCF) = Desired Yield ÷ Original Yield = 1.5 kg ÷ 2.5 kg = 0.60.', '["0.5","0.75","0.6","2"]'::jsonb, '["PRC-2021","FFSS","Recipe Standardization","Kitchen Math"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 67. Margin calculation: 1.5 / 2.5 = 0.60.', '{"dueDate":"2026-11-06T16:52:15.079Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:52:15.079Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:52:15.079Z"'::jsonb),
('card-ffss-2021-68', NULL, 'deck-prc-2021-ffss', 'This is NOT a sandwich.', 'Creole', 'Creole refers to a regional cultural style of cuisine originating in Louisiana. Canape (open-faced), Clubhouse (multi-decker), and Banh Mi (Vietnamese baguette) are all distinct sandwiches.', '["Canape","Clubhouse","Bahn mi","Creole"]'::jsonb, '["PRC-2021","FFSS","Culinary Arts","Menu Terms"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 68. Sandwich taxonomy.', '{"dueDate":"2026-11-06T17:20:24.038Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:20:24.038Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:20:24.038Z"'::jsonb),
('card-ffss-2021-69', NULL, 'deck-prc-2021-ffss', 'Samgyeopsal in Korea basically refers to ___.', 'Grilled pork belly', 'Samgyeopsal literally translates to ''three-layered meat'' in Korean, specifically referring to thick slices of pork belly cooked on a tabletop grill.', '["Kimchi","Shabu shabu","Grilled pork belly","Spicy appetizer made of cabbage"]'::jsonb, '["PRC-2021","FFSS","International Cuisines","Asian Cookery"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 69. Korean culinary terminology.', '{"dueDate":"2026-11-06T17:28:37.325Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:28:37.325Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:28:37.325Z"'::jsonb),
('card-ffss-2021-7', NULL, 'deck-prc-2021-ffss', 'If Ilocos has pinakbet, Central Visayas has ___.', 'Utan', 'Utan Bisaya is the iconic indigenous vegetable soup of Central Visayas, equivalent to Northern Luzon''s Pinakbet. (Paklay is an offal stew; Sinanglay is a Bicol dish).', '["Chicken Inasal","Sinanglay","Utan","Paklay"]'::jsonb, '["PRC-2021","FFSS","Regional Cuisines","Philippine Foods"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 7. Utan = Visayan vegetable soup; Sinanglay = Bicol.', '{"dueDate":"2026-11-07T04:17:09.485Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-06T04:17:09.485Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:17:09.485Z"'::jsonb),
('card-ffss-2021-70', NULL, 'deck-prc-2021-ffss', 'The cause of an outbreak of a foodborne illness was traced to unpasteurized milk; symptoms included fever, nausea, headache. The likely source is ___.', 'Listeria monocytogenes', 'Listeria monocytogenes is a psychrotrophic pathogen commonly transmitted via raw, unpasteurized milk and soft cheeses, causing listeriosis with fever, headaches, and bacteremia.', '["Clostridium botulinum","Bacillus aureus","Vibrio vulnificus","Listeria monocytogenes"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Foodborne Illness"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 70. Unpasteurized dairy hazard = Listeria monocytogenes.', '{"dueDate":"2026-11-06T16:55:46.727Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:55:46.727Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:55:46.727Z"'::jsonb),
('card-ffss-2021-71', NULL, 'deck-prc-2021-ffss', 'Which statement is TRUE about incomplete protein?', 'Incomplete protein will support maintenance but not growth', 'Incomplete proteins lack one or more essential amino acids in sufficient amounts; they can sustain tissue maintenance and turnover, but cannot support cellular growth and repair on their own.', '["Both animal meat and plants contain incomplete protein","Incomplete protein will support both maintenance and growth","Incomplete protein will support maintenance but not growth","Animal meat is a source of incomplete protein"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Proteins"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 71. Protein quality and biological value.', '{"dueDate":"2026-11-06T17:03:24.183Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:03:24.183Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:03:24.183Z"'::jsonb),
('card-ffss-2021-72', NULL, 'deck-prc-2021-ffss', 'Gabriel was invited to attend See Wong''s birthday party in a restaurant which serves international cuisines. Identify the country of origin of Canape (small open-faced sandwich on toast):', 'France', 'Canape is a classic French hors d''oeuvre consisting of a small, decorative base of bread or toast topped with savory spreads and garnishes.', '["Puerto Rico","France","Dominican Republic","Malaysia"]'::jsonb, '["PRC-2021","FFSS","Culinary Arts","International Cuisines"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 72. French culinary terms.', '{"dueDate":"2026-11-06T17:20:41.556Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:20:41.556Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:20:41.556Z"'::jsonb),
('card-ffss-2021-73', NULL, 'deck-prc-2021-ffss', 'Which is the PRIMARY cause of food borne illness?', 'Bacteria', 'Bacteria (such as Salmonella, Campylobacter, S. aureus, and E. coli) are the leading cause of bacterial foodborne intoxications and infections worldwide.', '["Viruses","Bacteria","Parasites","Protozoa"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Food Safety"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 73. Primary cause of foodborne illness.', '{"dueDate":"2026-11-06T16:35:07.185Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:35:07.185Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:35:07.185Z"'::jsonb),
('card-ffss-2021-74', NULL, 'deck-prc-2021-ffss', 'Acidic food: ___; Non-acidic food: ___.', 'Pickles; Buko water', 'Pickles have high acetic acid content (pH < 4.6, acidic), whereas fresh coconut (buko) water is near neutral (pH 5.5–6.2, low-acid / non-acidic).', '["Orange; mushroom","Apple; Egg white","Pickles; Buko water","Buko water; mushroom"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","pH"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 74. Food pH classifications.', '{"dueDate":"2026-11-06T17:28:53.929Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:28:53.929Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:28:53.929Z"'::jsonb),
('card-ffss-2021-75', NULL, 'deck-prc-2021-ffss', 'In food preservation, the main goal is to lengthen generation time of microorganisms and as much as possible to lengthen lag phase and phase of positive acceleration. Choose one of the ways this can be done:', 'Damaging the microorganisms through cooling', 'Low temperature refrigeration and chilling slows down microbial enzymatic activity, prolonging the lag phase and increasing bacterial generation doubling time.', '["Preserving the microorganisms for fermentation","Preserving the microorganisms to lengthen expiry date","Damaging the microorganisms through cooling","Damaging the microorganisms through heating"]'::jsonb, '["PRC-2021","FFSS","Food Preservation","Microbial Kinetics"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 75. Preservative mechanisms of chilling.', '{"dueDate":"2026-11-07T04:14:26.559Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:14:26.559Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:14:26.559Z"'::jsonb),
('card-ffss-2021-76', NULL, 'deck-prc-2021-ffss', 'Identify the bacteria which can be found in rice and other starchy foods.', 'Bacillus cereus', 'Bacillus cereus spore-formers survive boiling and produce an emetic toxin (cereulide) when cooked rice or starchy foods are left at room temperature (Fried Rice Syndrome).', '["Clostridium perfringens","Campylobacter botulinum","Salmonella sp","Bacillus cereus"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Foodborne Illness"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 76. Fried rice syndrome = Bacillus cereus.', '{"dueDate":"2026-11-06T17:24:56.982Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:24:56.982Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:24:56.982Z"'::jsonb),
('card-ffss-2021-77', NULL, 'deck-prc-2021-ffss', 'Which is the appropriate description of a functional food?', 'It provides health benefits beyond basic nutrition', 'Functional foods are defined as whole, fortified, enriched, or enhanced foods that provide documented physiological health benefits or reduce disease risk beyond providing basic nutritional requirements.', '["It stimulates growth of good bacteria in the gut.","It should be taken when a patient is under medication.","It is packed with vitamins and minerals.","It provides health benefits beyond basic nutrition"]'::jsonb, '["PRC-2021","FFSS","Functional Foods","Nutrition Concepts"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 77. Definition of Functional Food.', '{"dueDate":"2026-11-06T17:04:33.663Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:04:33.663Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:04:33.663Z"'::jsonb),
('card-ffss-2021-78', NULL, 'deck-prc-2021-ffss', 'What is the effect of adding alcohol in cheese while cooking?', 'It prevents overheating.', 'In cheese preparations (such as Swiss fondue made with white wine/kirsch), the alcohol and tartaric acid lower the boiling point and blend with proteins to prevent tough, stringy curdling from overheating.', '["It will create Edam cheese.","It prevents overheating.","It will increase fat content.","Cheese will ferment right away."]'::jsonb, '["PRC-2021","FFSS","Dairy Cookery","Food Chemistry"]'::jsonb, 'Foods and Food Service Systems', 'hard', 2, 'PRC NDLE Oct 2021 Set B, Item 78. Culinary chemistry of cheese cookery.', '{"dueDate":"2026-11-07T04:13:37.421Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:13:37.421Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:13:37.421Z"'::jsonb),
('card-ffss-2021-79', NULL, 'deck-prc-2021-ffss', 'What is the smoke point temperature for fats?', 'Above 350 degrees F', 'Deep frying fats should possess a high smoke point, typically starting above 350°F (177°C) to 400°F (204°C), before glycerol decomposes into irritating acrolein fumes.', '["Above 350 degrees F","Above 500 degrees F","Above 442 degrees F","Above 525 degrees F"]'::jsonb, '["PRC-2021","FFSS","Fats & Oils","Deep Frying"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 79. Frying fats smoke point threshold.', '{"dueDate":"2026-11-06T16:35:27.230Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:35:27.230Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:35:27.230Z"'::jsonb),
('card-ffss-2021-8', NULL, 'deck-prc-2021-ffss', 'What will happen if warm foods are readily stored in the refrigerator?', 'Temperature of the ref will rise', 'Warm foods emit heat that overtaxes the cooling unit and raises internal refrigerator temperature above 4°C (40°F), placing nearby items into the Temperature Danger Zone.', '["Dry food items in the ref will have moist","Ref will readily have rust","Temperature of the ref will rise","Other foods in the ref will get spoiled"]'::jsonb, '["PRC-2021","FFSS","Food Safety","Refrigeration"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 8. Direct thermodynamic effect = ref temperature rises.', '{"dueDate":"2026-11-06T17:23:39.349Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:23:39.349Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:23:39.349Z"'::jsonb),
('card-ffss-2021-80', NULL, 'deck-prc-2021-ffss', 'Which is the most flavorful part of pork due to the layers of fats in between muscles?', 'Belly fat', 'Pork belly (liempo) features distinct alternating layers of intramuscular fat (marbling) and muscle tissue, making it the most succulent and flavorful cut.', '["Shoulder","Belly fat","Ribs","Kasim"]'::jsonb, '["PRC-2021","FFSS","Meat Science","Cuts of Pork"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 80. Liempo / Pork belly fat layers.', '{"dueDate":"2026-11-06T17:21:48.996Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:21:48.996Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:21:48.996Z"'::jsonb),
('card-ffss-2021-81', NULL, 'deck-prc-2021-ffss', 'Which is NOT a required benefit of an employee?', 'Midyear bonus', 'Midyear bonus is a discretionary company perk unless stipulated in a Collective Bargaining Agreement (CBA). 13th-month pay, statutory SSS/PhilHealth/Pag-IBIG, and 5 days Service Incentive Leave are mandatory by Philippine law.', '["Vacation leave","Midyear bonus","13th month pay","SSS, Phil health, Pag Ibig"]'::jsonb, '["PRC-2021","FFSS","Foodservice Administration","Labor Law"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 81. Philippine Labor law benefits.', '{"dueDate":"2026-11-06T17:23:06.622Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:23:06.622Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:23:06.622Z"'::jsonb),
('card-ffss-2021-82', NULL, 'deck-prc-2021-ffss', 'How do you call the poisonous toxins which can be found in peanut, tree nuts, corn and copra?', 'Aflatoxins', 'Aflatoxins are potent hepatocarcinogenic mycotoxins produced by the molds Aspergillus flavus and Aspergillus parasiticus, frequently contaminating improperly dried peanuts, corn, and copra.', '["Tetrodotoxin","Histamine","Aflatoxins","Plant toxins"]'::jsonb, '["PRC-2021","FFSS","Toxicology","Food Safety"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 82. Mycotoxins in peanuts/corn = Aflatoxins.', '{"dueDate":"2026-11-06T17:21:22.651Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:21:22.651Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:21:22.651Z"'::jsonb),
('card-ffss-2021-83', NULL, 'deck-prc-2021-ffss', 'Which is the commission that formulates internationally accepted food safety standards to protect the public and ensure fair trade practices?', 'Codex Alimentarius', 'The Codex Alimentarius Commission (CAC), established jointly by FAO and WHO, establishes international food codes, standards, and guidelines for consumer health protection and fair food trade.', '["Department of Health","Codex Alimentarius","US FDA","Commission on Population"]'::jsonb, '["PRC-2021","FFSS","Food Standards","Codex Alimentarius"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 83. International food standards body.', '{"dueDate":"2026-11-06T16:36:27.682Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:36:27.682Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:36:27.682Z"'::jsonb),
('card-ffss-2021-84', NULL, 'deck-prc-2021-ffss', 'If a broiler is 7-12-week-old chicken, fryer is ___.', '14-20 weeks', 'In poultry market classification, broilers are young tender birds (under 12 weeks), fryers are slightly older (14–20 weeks), and roasters are typically 5–10 months old.', '["3-5 months","10 months","14-20 weeks","11 months"]'::jsonb, '["PRC-2021","FFSS","Poultry","Food Standards"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 84. Poultry age classes.', '{"dueDate":"2026-11-06T17:21:04.247Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:21:04.247Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:21:04.247Z"'::jsonb),
('card-ffss-2021-85', NULL, 'deck-prc-2021-ffss', 'Which additive would add sweetness, act as a stabilizer and thickener, and retain moistness in a muffin?', 'Sorbitol', 'Sorbitol is a polyol (sugar alcohol) that imparts sweetness, functions as a humectant to retain moisture, and increases batter viscosity without crystallizing.', '["Sodium acetate","Sodium bicarbonate","Sorbitol","Saccharin"]'::jsonb, '["PRC-2021","FFSS","Food Additives","Baking"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 85. Sorbitol functions as humectant & polyol.', '{"dueDate":"2026-11-06T16:35:41.688Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:35:41.688Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:35:41.688Z"'::jsonb),
('card-ffss-2021-86', NULL, 'deck-prc-2021-ffss', 'Being non-flammable, asbestos is good for ___.', 'Roofing material', 'Due to its high heat resistance and non-combustible properties, asbestos was historically used as an industrial building and roofing fireproofing material.', '["Kitchen tabletops","Cleaning agent for kitchen","Office chair","Roofing material"]'::jsonb, '["PRC-2021","FFSS","Facility Planning","Safety"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 86. Fireproofing material = roofing.', '{"dueDate":"2026-11-06T17:15:08.272Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:15:08.272Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:15:08.272Z"'::jsonb),
('card-ffss-2021-87', NULL, 'deck-prc-2021-ffss', 'Which countries are known for pastries?', 'Scandinavian', 'Scandinavian countries (Denmark, Sweden, Norway) are world-renowned for their laminated yeast dough pastries (such as Danish pastries / wienerbrød).', '["Scandinavian","South Africa","India","Mediterranean"]'::jsonb, '["PRC-2021","FFSS","Baking & Pastry","Culinary History"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 87. Pastry origins: Danish / Scandinavian.', '{"dueDate":"2026-11-06T16:53:59.846Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:53:59.846Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:53:59.846Z"'::jsonb),
('card-ffss-2021-88', NULL, 'deck-prc-2021-ffss', 'Which costs will most likely be evaluated first after a budget reduction announcement?', 'Labor', 'Labor is the largest controllable operational expense in foodservice (often 30–40% of total revenue); when budget reductions occur, management evaluates scheduling and overtime first.', '["General nonfood supplies","Equipment and maintenance","Labor","Food"]'::jsonb, '["PRC-2021","FFSS","Cost Control","Foodservice Administration"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 88. Controllable cost management.', '{"dueDate":"2026-11-06T17:04:44.991Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:04:44.991Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:04:44.991Z"'::jsonb),
('card-ffss-2021-89', NULL, 'deck-prc-2021-ffss', 'Which of the following are conjugated proteins?', 'Nucleoprotein, mucoprotein and lipoprotein', 'Conjugated proteins consist of simple amino acid chains combined with a non-protein prosthetic group (e.g., nucleic acids in nucleoproteins, carbohydrates in mucoproteins, lipids in lipoproteins).', '["Albumin, nucleoproteins and peptones","Albumin, globulin and glutelin","Nucleoprotein, mucoprotein and lipoprotein","Proteans, metaproteins and peptides"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Proteins"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 89. Protein classification: Conjugated proteins.', '{"dueDate":"2026-11-06T16:35:52.173Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:35:52.173Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:35:52.173Z"'::jsonb),
('card-ffss-2021-9', NULL, 'deck-prc-2021-ffss', 'Sasa is setting up a food business in her province. She is applying for her business permit in the municipal office. In order to fast track release of her business certificate, she offered to give Php 10,000 to one staff in the office. This incident is an example of ___.', 'Bribery', 'Bribery is the direct offering or giving of money or anything of value to influence a public official or employee in the performance of official duties.', '["Corruption","Theft","Bribery","Influencing"]'::jsonb, '["PRC-2021","FFSS","Ethics","Foodservice Administration"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 9. Code of Ethics and legal definitions.', '{"dueDate":"2026-11-06T17:01:46.829Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:01:46.829Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:01:46.829Z"'::jsonb),
('card-ffss-2021-90', NULL, 'deck-prc-2021-ffss', 'Which milk has almost all of its fat removed?', 'Skim', 'Skim milk (non-fat milk) has had virtually all milkfat removed via centrifugal separation, containing less than 0.5% (typically < 0.1%) butterfat.', '["25% less fat milk","Skim","Evaporated","Whole"]'::jsonb, '["PRC-2021","FFSS","Dairy","Food Standards"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 90. Milk processing: Skim = non-fat.', '{"dueDate":"2026-11-06T17:20:56.505Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:20:56.505Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:20:56.505Z"'::jsonb),
('card-ffss-2021-91', NULL, 'deck-prc-2021-ffss', 'What organisms can cause spoilage to food inside the refrigerator?', 'Psychrotrophs', 'Psychrotrophs (such as Pseudomonas, Listeria, and molds) are cold-tolerant organisms capable of proliferating at refrigeration temperatures (0°C–7°C).', '["Acidophiles","Psychrotrophs","Thermophiles","Protozoa"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Refrigeration"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 91. Refrigerated spoilage organisms.', '{"dueDate":"2026-11-07T04:03:01.893Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:03:01.893Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:03:01.893Z"'::jsonb),
('card-ffss-2021-92', NULL, 'deck-prc-2021-ffss', 'Chicken curry is NOT a popular dish in ___.', 'Germany', 'Curry is a foundational staple dish across South and Southeast Asia (India, Thailand, Indonesia). While Germany has currywurst (sausage with spiced ketchup), chicken curry is not traditional German cuisine.', '["Indonesia","India","Germany","Thailand"]'::jsonb, '["PRC-2021","FFSS","International Cuisines","Culinary Geography"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 92. International culinary traditions.', '{"dueDate":"2026-11-06T16:55:38.223Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:55:38.223Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:55:38.223Z"'::jsonb),
('card-ffss-2021-93', NULL, 'deck-prc-2021-ffss', 'Why are molds not the common microorganisms in heated canned products?', 'Easily destroyed by heat', 'Molds and their vegetative spores are heat-sensitive and are rapidly inactivated at temperatures well below standard thermal canning regimes (60°C–80°C).', '["Facultative","Resistant to cans","Easily destroyed by heat","Endospores"]'::jsonb, '["PRC-2021","FFSS","Food Preservation","Thermal Processing"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 93. Thermal death of molds in canning.', '{"dueDate":"2026-11-06T17:00:07.226Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:00:07.226Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:00:07.226Z"'::jsonb),
('card-ffss-2021-94', NULL, 'deck-prc-2021-ffss', 'Lycopene: ___; Carotene: ___.', 'Tomatoes, carrots', 'Lycopene is the primary red carotenoid found in tomatoes, watermelon, and pink guava; beta-carotene is the prominent orange carotenoid in carrots, pumpkins, and sweet potatoes.', '["Tomatoes, peppers","Pineapple, carrots","Corn, peppers","Tomatoes, carrots"]'::jsonb, '["PRC-2021","FFSS","Food Chemistry","Pigments"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 94. Plant pigments: Lycopene = tomato; Carotene = carrot.', '{"dueDate":"2026-11-06T16:57:56.318Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T16:57:56.318Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T16:57:56.318Z"'::jsonb),
('card-ffss-2021-95', NULL, 'deck-prc-2021-ffss', 'All the items below are suitable for freezing EXCEPT:', 'Mayonnaise', 'Mayonnaise is a delicate emulsion of oil in water stabilized by egg yolk; freezing crystallizes water and causes emulsion breakdown, resulting in unpalatable oil separation.', '["Fruit puree","Fish","Mayonnaise","Meat"]'::jsonb, '["PRC-2021","FFSS","Freezing","Food Stability"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 95. Emulsion breakdown during freezing.', '{"dueDate":"2026-11-07T04:05:35.670Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-06T04:05:35.670Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:05:35.670Z"'::jsonb),
('card-ffss-2021-96', NULL, 'deck-prc-2021-ffss', 'Large group of people experience acute gastroenteritis 4 to 6 hours after eating custard pie. Which bacteria are MOST likely the culprit?', 'Staphylococcus aureus', 'Staphylococcus aureus produces heat-stable enterotoxins in high-protein, creamy foods (like custards and cream pastries). It has a uniquely rapid incubation period of 1 to 6 hours causing sudden vomiting and diarrhea.', '["Vibrio parahaemolyticus","Listeria monocytogenes","Campylobacter jejuni","Staphylococcus aureus"]'::jsonb, '["PRC-2021","FFSS","Microbiology","Foodborne Intoxication"]'::jsonb, 'Foods and Food Service Systems', 'medium', 2, 'PRC NDLE Oct 2021 Set B, Item 96. Rapid 1-6 hr incubation in custards = S. aureus.', '{"dueDate":"2026-11-07T04:15:27.094Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-06T04:15:27.094Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-06T04:15:27.094Z"'::jsonb),
('card-ffss-2021-97', NULL, 'deck-prc-2021-ffss', 'Identify the people/populations that experience the most serious consequences of foodborne illnesses.', 'Immunocompromised individuals', 'Individuals with compromised immune systems (chemotherapy patients, organ transplant recipients, HIV/AIDS) have diminished cellular defense mechanisms and experience the highest rates of systemic bacteremia and mortality.', '["Women of childbearing age","Teenagers","Immunocompromised individuals","Young adults"]'::jsonb, '["PRC-2021","FFSS","Food Safety","Public Health"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 97. High-risk populations.', '{"dueDate":"2026-11-06T17:32:18.301Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:32:18.301Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:32:18.301Z"'::jsonb),
('card-ffss-2021-98', NULL, 'deck-prc-2021-ffss', 'What do you call the noodles in Thailand?', 'Pad Thai', 'Pad Thai is Thailand''s national stir-fried rice noodle dish. Bibimbap, Bulgogi, and Japchae are iconic dishes of South Korea.', '["Pad Thai","Bibimbap","Bulgogi","Japchae"]'::jsonb, '["PRC-2021","FFSS","International Cuisines","Southeast Asia"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 98. Thai cuisine.', '{"dueDate":"2026-11-06T17:28:59.646Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:28:59.646Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:28:59.646Z"'::jsonb),
('card-ffss-2021-99', NULL, 'deck-prc-2021-ffss', 'A management function that involves developing mission statements, setting goals and outlining steps needed to meet those goals:', 'Planning', 'Planning is the primary foundational management function that defines organizational objectives, visions, strategies, and blueprints for achieving desired outcomes.', '["Controlling","Planning","Entrepreneurship","Organizing"]'::jsonb, '["PRC-2021","FFSS","Management","Leadership"]'::jsonb, 'Foods and Food Service Systems', 'easy', 2, 'PRC NDLE Oct 2021 Set B, Item 99. Foundational management functions: Planning.', '{"dueDate":"2026-11-06T17:32:56.094Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T17:32:56.094Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T17:32:56.094Z"'::jsonb),
('card-nbcd-2021-1', NULL, 'deck-prc-2021-nbcd', 'Diet-related components that may be protective against CHD include all of the following, EXCEPT:', 'D. vitamin K', 'Cardioprotective dietary components include antioxidant nutrients like Vitamin E (which inhibits LDL oxidation), soluble fiber (which binds bile acids and lowers serum total and LDL cholesterol), and B-vitamins such as folate, B6, and B12 (which lower circulating homocysteine, an independent vascular risk factor). Vitamin K functions primarily in hepatic synthesis of blood clotting factors (II, VII, IX, X) and bone mineralization (osteocalcin carboxylation), and is not classified as a CHD-protective nutrient.', '["A. antioxidant nutrients, particularly vit. E","B. fiber","C. B vitamins, particularly folate","D. vitamin K"]'::jsonb, '["Cardiovascular Nutrition","Heart Disease","Vitamins","Lipids"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Vitamin K. Margin: CHD protective nutrients include Vit E (antioxidant), fiber (bile binding), folate (homocysteine reduction).', '{"dueDate":"2026-11-06T11:32:36.854Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:32:36.854Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:32:36.854Z"'::jsonb),
('card-nbcd-2021-10', NULL, 'deck-prc-2021-nbcd', 'The term that describes the volume of formula that remains in the stomach from a previous feeding is:', 'A. gastric residual', 'Gastric Residual Volume (GRV) is the amount of unabsorbed enteral formula and secretions aspirated from the stomach via an enteral feeding tube before administering the next bolus or during continuous feeding to monitor gastric emptying and tolerance.', '["A. gastric residual","B. intermittent feeding","C. residue","D. osmolar load"]'::jsonb, '["Enteral Nutrition","Nutrition Support","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. gastric residual. Monitored in enteral nutrition support to prevent aspiration.', '{"dueDate":"2026-11-06T15:08:20.164Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:08:20.164Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:08:20.164Z"'::jsonb),
('card-nbcd-2021-100', NULL, 'deck-prc-2021-nbcd', 'Using the PEL as basis, approximately how many grams of protein will this meal provide?
- 3/4 cup rice
- 3 exchanges of fried chicken breast
- 1 cup salad greens with vinegar as dressing
- 1 exchange banana', 'C. 28 gm', 'Calculation using the Philippine Food Exchange Lists (PEL):
1. Rice: 1 exchange = 1/2 cup cooked rice = 2 g protein. Thus, 3/4 cup cooked rice = 1.5 exchanges * 2 g = 3 g protein.
2. Chicken breast: 1 exchange of lean/medium meat = 8 g protein. 3 exchanges * 8 g = 24 g protein.
3. Salad greens: 1 cup raw leafy vegetables = 1 exchange Vegetable Group A/B = 1 g protein.
4. Banana: 1 exchange Fruit = 0 g protein.
Total Protein = 3 g (rice) + 24 g (chicken) + 1 g (greens) + 0 g (fruit) = 28 gm.', '["A. 32 gm","B. 30 gm","C. 28 gm","D. 24 gm"]'::jsonb, '["PEL","Food Exchange System","Calculations","Protein"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. 28 gm. Margin calculation: 3g (1.5 ex rice) + 24g (3 ex meat) + 1g (1 ex veg) = 28 gm.', '{"dueDate":"2026-11-06T15:05:47.641Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:05:47.641Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:05:47.641Z"'::jsonb),
('card-nbcd-2021-101', NULL, 'deck-prc-2021-nbcd', 'Plain, cool water is the best fluid for everyday active people because it _____.', 'B. rapidly leaves the digestive tract to enter the tissues and cool the body', 'Cool or chilled water (around 10-15°C / 50-59°F) empties from the stomach significantly faster than warm fluids or concentrated hypertonic beverages, promoting rapid intestinal absorption to restore plasma volume while helping lower core body temperature during physical activity.', '["A. leaves the digestive tract slowly","B. rapidly leaves the digestive tract to enter the tissues and cool the body","C. tastes good","D. provides carbohydrate"]'::jsonb, '["Sports Nutrition","Hydration","Fluid Balance","Gastric Emptying"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. rapidly leaves the digestive tract to enter the tissues and cool the body.', '{"dueDate":"2026-11-06T13:35:38.158Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:35:38.158Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:35:38.158Z"'::jsonb),
('card-nbcd-2021-102', NULL, 'deck-prc-2021-nbcd', 'Example of medication-related symptoms that will most likely and significantly limit food intake include _____.', 'D. persistent nausea and vomiting', 'Severe, persistent nausea and vomiting directly incapacitate the patient''s physiological ability to consume, tolerate, and retain oral food and liquids, leading to acute hypovolemia, electrolyte disturbances, and rapid nutritional decline.', '["A. nasal congestion and cough","B. skin rash and ringing in the ear","C. insomnia and photosensitivity","D. persistent nausea and vomiting"]'::jsonb, '["Pharmacology","Drug-Nutrient Interactions","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. persistent nausea and vomiting. Major drug-induced nutrition impact symptom.', '{"dueDate":"2026-11-06T13:20:33.378Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:20:33.378Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:20:33.378Z"'::jsonb),
('card-nbcd-2021-103', NULL, 'deck-prc-2021-nbcd', 'Diet management for Congestive Heart Failure include the following interventions. Which one is prohibited because it can provoke cardiac arrythmia?', 'B. No caffeine, no alcohol', 'Excessive caffeine (a central nervous system and cardiac beta-adrenergic stimulant) and heavy alcohol intake can precipitate tachyarrhythmias, atrial fibrillation (''holiday heart syndrome''), and myocardial depression in patients with compromised cardiac function and heart failure.', '["A. Take small but frequent meals","B. No caffeine, no alcohol","C. Optimize nutrition status","D. Restrict sodium"]'::jsonb, '["Cardiovascular Nutrition","Heart Failure","Arrhythmia","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. No caffeine, no alcohol. Caffeine and alcohol provoke cardiac arrhythmias.', '{"dueDate":"2026-11-06T15:00:33.577Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:00:33.577Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:00:33.577Z"'::jsonb),
('card-nbcd-2021-104', NULL, 'deck-prc-2021-nbcd', 'Much of these nutrients is the LEAST affected during stress _____.', 'B. vitamin E', 'During acute metabolic stress (sepsis, trauma, burns), hypermetabolism causes profound alterations in glucose turnover (hyperglycemia), amino acid mobilization (accelerated muscle proteolysis), and fluid/electrolyte balance. Fat-soluble Vitamin E has extensive adipose and hepatic stores and its turnover is least acutely altered during acute stress.', '["A. glucose","B. vitamin E","C. water","D. amino acids"]'::jsonb, '["Critical Care","Metabolic Stress","Nutrient Metabolism","Vitamin E"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. vitamin E. Water, glucose, and amino acid fluxes are massively affected during stress.', '{"dueDate":"2026-11-06T14:43:56.987Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:43:56.987Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:43:56.987Z"'::jsonb),
('card-nbcd-2021-105', NULL, 'deck-prc-2021-nbcd', 'Fluid balance is an aspect of the homeostasis of organisms which the concentration of electrolytes are kept at a healthy level. The state of body fluid volume balance is _____.', 'B. euvolemia', 'Euvolemia refers to the optimal, physiologically normal circulating blood and extracellular fluid volume in the human body, balancing fluid intake and excretory outputs.', '["A. hypovolemia","B. euvolemia","C. hypernatremia","D. hypervolemia"]'::jsonb, '["Fluid Balance","Physiology","Terminology","Homeostasis"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. euvolemia. Normal body fluid volume status.', '{"dueDate":"2026-11-06T12:58:17.709Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:58:17.709Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:58:17.709Z"'::jsonb)
