INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-nbcd-2021-106', NULL, 'deck-prc-2021-nbcd', 'Which of the following describes fat soluble vitamins?', 'A. Can be stored in the liver and fatty tissues and can reach toxic levels.', 'Fat-soluble vitamins (A, D, E, and K) are absorbed along with dietary lipids via mixed micelles and chylomicrons and are stored extensively in hepatic tissue and adipose reserves. Because they are not readily excreted in urine, excessive chronic intakes can accumulate to toxic levels (hypervitaminosis A or D).', '["A. Can be stored in the liver and fatty tissues and can reach toxic levels.","B. It includes Vit A and Vit. C","C. Can''t be stored to any great extent so must be consumed daily.","D. Toxic levels can be reached by consuming citrus fruits and vegetables."]'::jsonb, '["Nutritional Biochemistry","Fat-Soluble Vitamins","Toxicity","Storage"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Can be stored in the liver and fatty tissues and can reach toxic levels.', '{"dueDate":"2026-11-06T13:20:17.913Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:20:17.913Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:20:17.913Z"'::jsonb),
('card-nbcd-2021-107', NULL, 'deck-prc-2021-nbcd', 'Patients with calcium oxalate stones may benefit from diet that restrict:', 'A. oxalate and sodium', 'In calcium oxalate nephrolithiasis, high sodium intake reduces renal tubular reabsorption of calcium, causing hypercalciuria, while excessive dietary oxalate increases urinary oxalate concentration. Restricting oxalate-rich foods (spinach, rhubarb, beets, chocolate, nuts) and maintaining low sodium (<2,000 mg/day) with normal dietary calcium intake (which binds oxalate in the gut) prevents stone recurrence.', '["A. oxalate and sodium","B. calcium and phophorous","C. calcium and potassium","D. protein and methionine"]'::jsonb, '["Renal Nutrition","Nephrolithiasis","Oxalate","Sodium","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. oxalate and sodium. Note: Calcium should NOT be restricted; restrict oxalate and sodium.', '{"dueDate":"2026-11-06T15:05:04.954Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:05:04.954Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:05:04.954Z"'::jsonb),
('card-nbcd-2021-108', NULL, 'deck-prc-2021-nbcd', 'The hormone that moves milk through the mammary gland?', 'B. Oxytocin', 'Oxytocin, secreted by the posterior pituitary, stimulates the contraction of myoepithelial cells surrounding the mammary alveoli to eject milk into the lactiferous ducts (''let-down reflex'' or milk ejection). In contrast, prolactin stimulates milk production/synthesis.', '["A. Progesteron","B. Oxytocin","C. Prolactin","D. Estrogen"]'::jsonb, '["Lactation","Endocrine","Hormones","Maternal Nutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Oxytocin. Oxytocin = milk ejection/let-down; Prolactin = milk production.', '{"dueDate":"2026-11-06T14:51:28.140Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:51:28.140Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:51:28.140Z"'::jsonb),
('card-nbcd-2021-109', NULL, 'deck-prc-2021-nbcd', 'In celiac disease, a fraction of the protein gluten in wheat and corresponding protein fractions in barley, oats and rye:', 'B. acts as toxic substance and called the intestinal villi to lose their absorptive capacity', 'In Celiac Disease (gluten-sensitive enteropathy), proline- and glutamine-rich prolamin peptides (gliadin in wheat, secalin in rye, hordein in barley) trigger an autoimmune inflammatory reaction in the lamina propria, causing intraepithelial lymphocytosis, crypt hyperplasia, and severe villous atrophy with loss of absorptive surface area.', '["A. are clearly marked on food labels when they are used in food products","B. acts as toxic substance and called the intestinal villi to lose their absorptive capacity","C. allow oxalate to be absorbed and contribute to higher incidence of oxalate kidney stones","D. blinds fats and calcium so that they cannot be absorbed"]'::jsonb, '["Gastrointestinal","Celiac Disease","Gluten","Pathophysiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. acts as toxic substance and called the intestinal villi to lose their absorptive capacity.', '{"dueDate":"2026-11-06T11:57:33.356Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:57:33.356Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:57:33.356Z"'::jsonb),
('card-nbcd-2021-11', NULL, 'deck-prc-2021-nbcd', 'What is the best nutritional assessment you as an ND utilize when diagnosing a food allergy?', 'B. Have a patient keep a 1 week food/symptom record', 'A comprehensive prospective 1-to-2 week food and symptom diary recording exact foods, ingredients, cooking methods, quantities, timing of ingestion, and precise onset and nature of symptoms is the gold standard dietary assessment tool used by dietitians before structuring targeted elimination diets.', '["A. Exclude foods with severe reactions only, but allow small quatities of foods with minor reactions","B. Have a patient keep a 1 week food/symptom record","C. Obtain a \"reported\" detailed food symptom record","D. Exclude foods causing a reaction"]'::jsonb, '["Food Allergy","Nutrition Assessment","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Have a patient keep a 1 week food/symptom record. Diagnostic baseline for food allergies.', '{"dueDate":"2026-11-06T15:13:27.668Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:27.668Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:27.668Z"'::jsonb),
('card-nbcd-2021-110', NULL, 'deck-prc-2021-nbcd', 'One of the typical treatment symptoms of food allergies is;', 'D. elimination of the allergen', 'The only definitive, primary management and therapy for confirmed IgE- or non-IgE-mediated food allergies is strict, lifelong elimination of the culprit food allergen from the patient''s diet.', '["A. the use of penicillin","B. a skin test","C. avoiding all fruit","D. elimination of the allergen"]'::jsonb, '["Food Allergy","Elimination Diet","Clinical Dietetics","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. elimination of the allergen. Strict avoidance/elimination is the cornerstone of food allergy therapy.', '{"dueDate":"2026-11-06T14:33:53.901Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:33:53.901Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:33:53.901Z"'::jsonb),
('card-nbcd-2021-111', NULL, 'deck-prc-2021-nbcd', 'Which fat-soluble vitamin if lacking, can cause impaired vision in reduced light?', 'C. Retinol', 'Vitamin A (retinol/retinal) combines with the protein opsin in retinal rod cells to form rhodopsin (visual purple), the light-sensitive visual pigment responsible for vision in dim light. Vitamin A deficiency impairs rhodopsin regeneration, causing nyctalopia (night blindness).', '["A. Riboflavin","B. Cholecalciferol","C. Retinol","D. Ascorbic acid"]'::jsonb, '["Nutritional Biochemistry","Vitamin A","Retinol","Visual Cycle"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Retinol. Margin note: ''ADEK''. Retinal forms rhodopsin for scotopic (dim light) vision.', '{"dueDate":"2026-11-06T12:01:41.070Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:01:41.070Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:01:41.070Z"'::jsonb),
('card-nbcd-2021-112', NULL, 'deck-prc-2021-nbcd', 'Heat syndrome results when the body''s production of heat increases at a faster rate than the body''s ability to dissipate heat loss. Which of the following is the type of heat syndrome in its most severe from?', 'D. Heat stroke', 'Heat stroke is the most severe and life-threatening heat-related medical emergency. It is characterized by thermoregulatory failure resulting in a core body temperature > 40°C (104°F), central nervous system dysfunction (delirium, convulsions, coma), and multiorgan failure.', '["A. Heat exhaustion","B. Heat Cramps","C. Hypothermia","D. Heat stroke","D. Heat stroke"]'::jsonb, '["Sports Nutrition","Thermoregulation","Heat Illness","Emergency"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Heat stroke. Life-threatening heat illness with core temp > 40°C and CNS dysfunction.', '{"dueDate":"2026-11-06T11:28:15.185Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:28:15.185Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:28:15.185Z"'::jsonb),
('card-nbcd-2021-113', NULL, 'deck-prc-2021-nbcd', 'When monitoring for food allergy, which outcome should be measured?', 'D. reduction of food related reactions', 'In the Nutrition Care Process (NCP) for food allergies, the primary clinical outcome measure to monitor and evaluate is the reduction or complete cessation of adverse food-related allergic reactions following allergen elimination.', '["A. patient satisfaction with counseling","B. level of knowledges about causes of food allergies","C. frequency of patient failure to comply with instruction","D. reduction of food related reactions"]'::jsonb, '["Food Allergy","Nutrition Monitoring and Evaluation","NCP"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. reduction of food related reactions. Primary clinical efficacy outcome in allergy management.', '{"dueDate":"2026-11-06T13:23:39.457Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:23:39.457Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:23:39.457Z"'::jsonb),
('card-nbcd-2021-114', NULL, 'deck-prc-2021-nbcd', 'Because its nitrogenous wastes contribute to uremia, the following nutrient may be restricted in diets of renal clients', 'A. Protein', 'Dietary protein catabolism generates nitrogenous metabolic end-products, including urea, creatinine, uric acid, guanidines, and phenolic compounds. In non-dialyzed chronic kidney disease, dietary protein is controlled/restricted (0.6–0.8 g/kg/day) to decrease nitrogenous waste accumulation, relieve uremic symptoms, and slow renal progression.', '["A. Protein","B. Vitamin A","C. Saturated fat","D. Carbohydrate"]'::jsonb, '["Renal Nutrition","CKD","Protein Restriction","Uremia","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Protein. Nitrogenous waste products from protein catabolism drive uremic toxicity.', '{"dueDate":"2026-11-06T12:55:18.748Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:55:18.748Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:55:18.748Z"'::jsonb),
('card-nbcd-2021-115', NULL, 'deck-prc-2021-nbcd', 'Which of these exchanges does not contain protein?', 'A. Fat', 'In the Food Exchange Lists (PEL), 1 Fat exchange contains 0 g Carbohydrate, 0 g Protein, and 5 g Fat (45 kcal). In contrast, Low-fat milk provides 8 g protein, Vegetable provides 1 g (Group A) or 2 g (Group B) protein, and Bread/Rice provides 2 g protein per exchange.', '["A. Fat","B. Low fat milk","C. Vegetable","D. Bread"]'::jsonb, '["PEL","Food Exchange System","Macronutrients","Meal Planning"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Fat. Fat exchange = 0g CHO, 0g PRO, 5g FAT (45 kcal).', '{"dueDate":"2026-11-06T12:52:34.356Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:52:34.356Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:52:34.356Z"'::jsonb),
('card-nbcd-2021-116', NULL, 'deck-prc-2021-nbcd', 'Giving cytotoxic chemotherapeutic agents produces all of the following nutrition impact symptoms, EXCEPT:', 'D. hypotension', 'Cytotoxic antineoplastic drugs rapidly damage rapidly dividing epithelial cells, producing signature nutrition impact symptoms: nausea, vomiting, profound anorexia, dysgeusia, oral mucositis, and diarrhea. Hypotension is a cardiovascular/hemodynamic sign rather than a classic direct nutrition impact symptom.', '["A. diarrhea","B. anorexia","C. nausea","D. hypotension"]'::jsonb, '["Oncology Nutrition","Chemotherapy","Nutrition Impact Symptoms","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. hypotension. Nutrition impact symptoms directly interfere with dietary intake and digestion.', '{"dueDate":"2026-11-06T15:13:24.476Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:24.476Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:24.476Z"'::jsonb),
('card-nbcd-2021-117', NULL, 'deck-prc-2021-nbcd', 'Which of the following is a function of the kidney?
I. Formation of the plasma protein
II. Regulates the blood pressure
III. Stimulates the red blood cell production
IV. Activates Vitamin D', 'B. II, III & IV', 'The kidneys regulate blood pressure via the renin-angiotensin-aldosterone system (II), stimulate erythropoiesis by synthesizing erythropoietin (III), and perform the final 1-alpha-hydroxylation of 25(OH)D to active calcitriol (IV). Synthesis of plasma proteins (albumin, fibrinogen, transferrin) is performed by the liver, not the kidneys (I is incorrect).', '["A. II & IV","B. II, III & IV","C. I, II & IV","D. I, II & III"]'::jsonb, '["Renal Physiology","Kidney Functions","Erythropoietin","Vitamin D"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. II, III & IV. Renal functions: BP regulation (renin), RBC production (EPO), Vit D activation (calcitriol).', '{"dueDate":"2026-11-06T15:04:49.176Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:04:49.176Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:04:49.176Z"'::jsonb),
('card-nbcd-2021-118', NULL, 'deck-prc-2021-nbcd', 'Which of the following list of symptoms are systemic?', 'D. Headache, irritability, arrythmia, low BP', 'Systemic symptoms affect multiple body systems simultaneously or involve widespread neuro-hemodynamic responses. Headache, neuro-irritability, cardiac arrhythmias, and arterial hypotension represent generalized cardiovascular and systemic manifestations, whereas the other options are organ-specific (respiratory, GI, cutaneous).', '["A. wheezing, sneezing, congestion","B. Swollen throat, gas/bloating, malabsorption","C. Rash, hiccups, itchiness","D. Headache, irritability, arrythmia, low BP"]'::jsonb, '["Clinical Assessment","Symptomatology","Systemic Symptoms"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. Headache, irritability, arrythmia, low BP. Systemic hemodynamic and neurological manifestations.', '{"dueDate":"2026-11-06T14:28:16.288Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:28:16.288Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:28:16.288Z"'::jsonb),
('card-nbcd-2021-119', NULL, 'deck-prc-2021-nbcd', 'One specific indication of enteral nutrition is:', 'C. anorexia', 'Enteral nutrition support is indicated when a patient has a functioning, accessible gastrointestinal tract but cannot or will not consume adequate oral nutrition (such as in severe prolonged anorexia nervosa, hypercatabolic cancer anorexia, or neurological dysphagia). Small bowel obstruction, severe intractable diarrhea, and active upper GI bleeding are absolute contraindications to enteral feeding.', '["A. small bowel obstruction","B. intractable diarrhea","C. anorexia","D. upper gastrointestinal bleed"]'::jsonb, '["Enteral Nutrition","Indications","Contraindications","Nutrition Support"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. anorexia. Gut works? Use it! A, B, and D are absolute contraindications to enteral nutrition.', '{"dueDate":"2026-11-06T13:00:29.975Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:00:29.975Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:00:29.975Z"'::jsonb),
('card-nbcd-2021-12', NULL, 'deck-prc-2021-nbcd', 'What is the catabolic enzyme which can utilize peroxide in the production of substrates accompanied by water production?', 'C. Catalase', 'Catalase is a heme-containing antioxidant enzyme present in peroxisomes that catalyzes the decomposition of toxic hydrogen peroxide into water and molecular oxygen (2 H2O2 -> 2 H2O + O2), protecting cells against oxidative stress.', '["A. Amylase","B. Lipase","C. Catalase","D. Lactase"]'::jsonb, '["Nutritional Biochemistry","Enzymes","Antioxidants"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Catalase. Peroxisomal enzyme converting H2O2 to water and oxygen.', '{"dueDate":"2026-11-06T15:12:25.170Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:12:25.170Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:12:25.170Z"'::jsonb),
('card-nbcd-2021-120', NULL, 'deck-prc-2021-nbcd', 'Diet management for Dumping Syndrome includes:
I. Small meals spread out throughout the day
II. High protein, moderate fat foods are recommended
III. Small amount of simple sugar may be taken as tolerated
IV. Use of fiber supplement to reduce upper GI transit time and decrease glucose absorption', 'D. I, II and III', 'Dumping syndrome MNT emphasizes: (I) small, frequent meals spread over 5–6 feedings, (II) high protein and moderate fat to slow gastric emptying and sustain satiety, and (III) strictly limiting concentrated simple sugars (taking only small tolerated amounts). Regarding IV: Soluble fiber *increases* (delays) upper GI transit time rather than reducing it.', '["A. I, II, III and IV","B. I, III and IV","C. II, III and IV","D. I, II and III"]'::jsonb, '["Gastrointestinal","Dumping Syndrome","Gastrectomy","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. I, II and III. Dumping syndrome: small frequent meals, high protein, moderate fat, restricted sweets.', '{"dueDate":"2026-11-06T15:12:17.639Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:12:17.639Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:12:17.639Z"'::jsonb),
('card-nbcd-2021-121', NULL, 'deck-prc-2021-nbcd', 'Some RND''s have been successful using the following approaches to make their interaction with difficult clients easier. Which will work BEST?
I. Giving assignment prior to next session.
II. Requesting for return demo after instruction was given.
III. Summarize the patient''s main concern and offer feedback of what you heard.
IV. Give a strong impression that your instructions should be followed.', 'C. I, II, and III', 'Effective client-centered counseling uses active listening (summarizing concerns and reflective feedback - III), behavioral assignments/homework (I), and return demonstration/teach-back to verify competence (II). Authoritarian demands (IV - ''give a strong impression that instructions must be followed'') provoke resistance and damage therapeutic rapport.', '["A. II, III, and IV","B. I, II, III, and IV","C. I, II, and III","D. I, II, and IV"]'::jsonb, '["Nutrition Counseling","Communication Skills","Client Rapport"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. I, II, and III. Reflective listening, teach-back, and self-monitoring assignments build rapport.', '{"dueDate":"2026-11-06T15:00:10.729Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:00:10.729Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:00:10.729Z"'::jsonb),
('card-nbcd-2021-122', NULL, 'deck-prc-2021-nbcd', 'Which is responsible for regulating the acidic environment in the stomach?
I. Gastrin
II. Nerve receptor
III. Secretin
IV. Hydrochloric Acid', 'A. I, II and III', 'Gastric acid secretion is tightly regulated by: Gastrin (I, secreted by antral G-cells, strongly stimulates parietal acid secretion), Neural receptors (II, vagal cholinergic and histamine H2 receptors), and Secretin (III, released by duodenal S-cells in response to acid, inhibits gastrin release and parietal cell acid secretion while stimulating pancreatic bicarbonate). Hydrochloric acid (IV) is the secretory product itself, not a regulatory controller.', '["A. I, II and III","B. I and II","C. I and IV","D. II, III and IV"]'::jsonb, '["Gastrointestinal","Physiology","Gastric Acid","Regulation"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. I, II and III. Regulators of acid secretion: Gastrin (+), Vagal/ACh/Histamine (+), Secretin (-).', '{"dueDate":"2026-11-06T15:01:08.163Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:01:08.163Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:01:08.163Z"'::jsonb),
('card-nbcd-2021-123', NULL, 'deck-prc-2021-nbcd', 'The difference between cis and trans fatty acid is the _____.', 'C. configuration of the double bond', 'Cis and trans fatty acid isomers differ in the spatial geometric configuration of hydrogen atoms across the carbon-carbon double bond. In cis configuration, hydrogen atoms are on the same side, creating a kink/bend in the hydrocarbon chain. In trans configuration, hydrogen atoms are on opposite sides, producing a linear, rigid conformation similar to saturated fatty acids.', '["A. location of their first double","B. number of their double bonds","C. configuration of the double bond","D. length of their carbon chain"]'::jsonb, '["Nutritional Biochemistry","Lipids","Fatty Acids","Isomerism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. configuration of the double bond. Cis = same side (kinked); Trans = opposite sides (straight).', '{"dueDate":"2026-11-06T14:48:32.481Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:48:32.481Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:48:32.481Z"'::jsonb),
('card-nbcd-2021-124', NULL, 'deck-prc-2021-nbcd', 'A Sports ND is usually consulted for tips to boost performance before a game. Which of the following should NOT be a part of your advice?', 'C. It''s alright to try new foods on race or game day.', 'A cardinal, non-negotiable rule in sports nutrition is ''never try anything new on competition or game day.'' Introducing unfamiliar foods, supplements, or high-fiber foods immediately prior to an athletic event risks sudden severe gastrointestinal upset, diarrhea, nausea, and cramping.', '["A. Carbohydrate is very important as the body needs it to fuel the working muscle.","B. Protein is important for building and repair of muscle tissues.","C. It''s alright to try new foods on race or game day.","D. Give fluid prescription on how much to drink before, during and after a game."]'::jsonb, '["Sports Nutrition","Pre-event Nutrition","Athletes","Clinical Advice"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. It''s alright to try new foods on race or game day. Golden rule in sports nutrition: Never experiment on race day.', '{"dueDate":"2026-11-06T12:42:54.869Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:42:54.869Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:42:54.869Z"'::jsonb),
('card-nbcd-2021-125', NULL, 'deck-prc-2021-nbcd', 'A patient is MOST likely to experience nausea, vomiting, bloating, increased flatus after suddenly changing from low to high dietary intake of:', 'D. fiber', 'Abruptly increasing dietary fiber intake without a gradual step-up and without adequate fluid intake causes undigested polysaccharides to enter the colon rapidly, where anaerobic colonic bacteria undergo rapid fermentation, generating large volumes of hydrogen, methane, and carbon dioxide gases (bloating, cramping, and flatus).', '["A. carbohydrate","B. water","C. protein","D. fiber"]'::jsonb, '["Gastrointestinal","Fiber","Adverse Effects","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. fiber. Rapid escalation of dietary fiber causes severe gas and abdominal distension.', '{"dueDate":"2026-11-06T15:10:06.129Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:10:06.129Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:10:06.129Z"'::jsonb),
('card-nbcd-2021-126', NULL, 'deck-prc-2021-nbcd', 'Dr. Santos referred his hypertensive pt for diet counseling with a prescription for a low sodium diet. How many mg of sodium is allowed on this diet?', 'D. 2,000 mg', 'In standard clinical dietetics and hospital diet manuals, a standard ''low sodium diet'' (or mild/moderate sodium restriction) prescribes 2,000 mg of sodium daily (equivalent to approximately 5 grams of table salt). Strict sodium diets (500-1,000 mg) are rarely prescribed due to poor palatability and risk of hyponatremia.', '["A. 1,500 mg","B. 500 mg","C. 1,000 mg","D. 2,000 mg"]'::jsonb, '["Cardiovascular Nutrition","Hypertension","Sodium","Diet Orders"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. 2,000 mg (C. 1,000 mg also noted for moderate restriction; 2,000 mg is standard clinical target).', '{"dueDate":"2026-11-06T15:11:31.976Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:11:31.976Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:11:31.976Z"'::jsonb),
('card-nbcd-2021-127', NULL, 'deck-prc-2021-nbcd', 'Refeeding syndrome causes dangerous fluctuations in:', 'D. electrolytes', 'Refeeding syndrome is characterized by rapid, life-threatening shifts in serum electrolytes—principally acute hypophosphatemia, hypokalemia, and hypomagnesemia—triggered by carbohydrate re-introduction and insulin release driving electrolytes into cells for glucose phosphorylation and protein synthesis.', '["A. liver enzymes","B. triglycerides","C. ketone bodies","D. electrolytes"]'::jsonb, '["Refeeding Syndrome","Critical Care","Electrolytes","Nutrition Support"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. electrolytes. Critical electrolyte shifts (PO4, K, Mg) cause cardiac arrhythmias.', '{"dueDate":"2026-11-06T14:48:18.775Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:48:18.775Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:48:18.775Z"'::jsonb),
('card-nbcd-2021-128', NULL, 'deck-prc-2021-nbcd', 'Which of these are the functions of the kidney?
I. Formation of plasma protein
II. Regulates blood pressure
III. Stimulates red blood cell production
IV. Activates Vit. D', 'D. II, III and IV', 'The kidneys regulate blood pressure via renin secretion (II), stimulate bone marrow red blood cell synthesis via erythropoietin production (III), and convert 25-hydroxyvitamin D into active 1,25-dihydroxyvitamin D via 1-alpha-hydroxylase (IV). Synthesis of plasma proteins (such as albumin) is carried out by hepatocytes in the liver.', '["A. I, II and IV","B. I, III and IV","C. I, II and III","D. II, III and IV"]'::jsonb, '["Renal Physiology","Kidney Functions","Endocrine"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. II, III and IV (Exam duplicate of Q117).', '{"dueDate":"2026-11-06T14:34:51.583Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:34:51.583Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:34:51.583Z"'::jsonb),
('card-nbcd-2021-129', NULL, 'deck-prc-2021-nbcd', 'An albumin of 1.8 g/dL is indicative of _____.', 'A. severe depletion', 'Serum albumin clinical visceral protein depletion categories:
- Normal: 3.5 to 5.0 g/dL
- Mild depletion: 2.8 to 3.5 g/dL
- Moderate depletion: 2.1 to 2.7 g/dL
- Severe depletion: < 2.1 g/dL.
Therefore, a serum albumin level of 1.8 g/dL indicates severe visceral protein depletion.', '["A. severe depletion","B. mild depletion","C. dehydration","D. moderate depletion"]'::jsonb, '["Nutrition Assessment","Laboratory Values","Albumin","Malnutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. severe depletion. Margin note: Normal >3.5, Mild 2.8-3.5, Mod 2.1-2.7, Severe <2.1 g/dL.', '{"dueDate":"2026-11-06T12:43:24.563Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:43:24.563Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:43:24.563Z"'::jsonb),
('card-nbcd-2021-13', NULL, 'deck-prc-2021-nbcd', 'Long-term management of diverticular disease includes a:', 'C. high-fiber diet', 'Long-term maintenance of diverticular disease (diverticulosis) requires a high-fiber diet (25 to 35 g/day or more) along with generous fluid intake to increase stool volume, soften feces, and decrease intraluminal colonic pressure, thereby preventing diverticulitis flares. Note that low fiber is only used during acute diverticulitis.', '["A. high-fiber diet, lactose-free diet","B. low-fiber diet that omits foods with seeds","C. high-fiber diet","D. low-fiber, lactose free diet"]'::jsonb, '["Gastrointestinal","Diverticular Disease","Fiber","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. high-fiber diet. Diverticulosis = High fiber; Diverticulitis (acute inflammation) = Low residue/low fiber or bowel rest.', '{"dueDate":"2026-11-06T15:05:32.902Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:05:32.902Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:05:32.902Z"'::jsonb),
('card-nbcd-2021-130', NULL, 'deck-prc-2021-nbcd', 'Vitamin is recognized as "sunshine vitamin" and can be synthesized by the skin is _____.', 'B. Vitamin D', 'Vitamin D is universally designated the ''sunshine vitamin'' because 7-dehydrocholesterol stored in the epidermal layer of the skin is photochemically converted to previtamin D3 upon solar ultraviolet B (UVB) irradiation, which then isomerizes to cholecalciferol (Vitamin D3).', '["A. Vitamin E","B. Vitamin D","C. Vitamin A","D. Vitamin K"]'::jsonb, '["Nutritional Biochemistry","Vitamin D","Sunlight","Vitamins"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Vitamin D. Photochemical cutaneous synthesis via UVB exposure.', '{"dueDate":"2026-11-06T11:42:56.212Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:42:56.212Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:42:56.212Z"'::jsonb),
('card-nbcd-2021-131', NULL, 'deck-prc-2021-nbcd', 'Which of the following is the RDA protein intake for maintenance of patients receiving hemodialysis?', 'D. 1 - 1.2 g/kg', 'According to KDOQI and KDIGO clinical practice guidelines for chronic kidney disease on maintenance hemodialysis, the recommended daily dietary protein allowance is 1.2 g/kg standard body weight/day (or 1.0–1.2 g/kg/day, with >=50% high biological value) to compensate for free amino acid and peptide losses into the dialysate and hypercatabolism.', '["A. 0.6 - 0.8 g/kg","B. 1.3 - 1.5 g/kg","C. 0.9 - 1.1 g/kg","D. 1 - 1.2 g/kg"]'::jsonb, '["Renal Nutrition","Hemodialysis","Protein Requirements","KDOQI","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. 1 - 1.2 g/kg (KDIGO standard: 1.2 g/kg/day for hemodialysis).', '{"dueDate":"2026-11-06T13:35:53.442Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:35:53.442Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:35:53.442Z"'::jsonb),
('card-nbcd-2021-132', NULL, 'deck-prc-2021-nbcd', 'Branched chain amino acid are emphasized in enteral formulas for patients with hepatic failure because they;', 'C. are not metabolized in the liver but in the fat and muscle', 'Branched-chain amino acids (BCAAs: leucine, isoleucine, valine) bypass primary hepatic metabolism due to lack of hepatic BCAA aminotransferase, and are metabolized extrahepatically in skeletal muscle and adipose tissue. Providing BCAAs normalizes the plasma Fischer ratio (BCAA to aromatic amino acids: phenylalanine, tyrosine, tryptophan), competitive crossing of the blood-brain barrier, and improves hepatic encephalopathy.', '["A. are more digestable","B. do not produce ammonia","C. are not metabolized in the liver but in the fat and muscle","D. are the essential amino acids"]'::jsonb, '["Hepatic Nutrition","BCAA","Hepatic Encephalopathy","Enteral Nutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. are not metabolized in the liver but in the fat and muscle. Extrahepatic muscle oxidation.', '{"dueDate":"2026-11-06T13:36:27.447Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:36:27.447Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:36:27.447Z"'::jsonb),
('card-nbcd-2021-133', NULL, 'deck-prc-2021-nbcd', 'Isoniazid, a drug used in the treatment of tuberculosis, is an agonist of _____.', 'B. Vitamin B6', 'Isoniazid (INH), a primary antitubercular agent, acts as a structural antagonist of Vitamin B6 (pyridoxine). It binds pyridoxal-5-phosphate (PLP) to form an inactive hydrazone complex excreted in urine, and inhibits pyridoxal kinase, precipitating clinical peripheral neuropathy unless prophylactic pyridoxine (25–50 mg/day) is administered.', '["A. Vitamin B2","B. Vitamin B6","C. Vitamin B1","D. Vitamin B12"]'::jsonb, '["Pharmacology","Drug-Nutrient Interactions","Vitamin B6","Tuberculosis"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Vitamin B6. Classical drug-nutrient interaction: INH causes Vitamin B6 deficiency neuropathy.', '{"dueDate":"2026-11-06T13:16:01.607Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:16:01.607Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:16:01.607Z"'::jsonb),
('card-nbcd-2021-134', NULL, 'deck-prc-2021-nbcd', 'During metabolism, released energy is captured and transferred by _____.', 'B. Adenosine Triphosphate', 'Adenosine Triphosphate (ATP) is the universal cellular energy currency. Free energy liberated during the exergonic oxidation of macronutrients is conserved in the high-energy phosphoanhydride bonds of ATP and transferred to drive endergonic physiological work (muscle contraction, active transport, biosyntheses).', '["A. Pyruvate","B. Adenosine Triphosphate","C. Acetyl CoA","D. enzymes"]'::jsonb, '["Nutritional Biochemistry","Bioenergetics","ATP","Metabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Adenosine Triphosphate (ATP). Universal chemical energy currency.', '{"dueDate":"2026-11-06T15:04:13.814Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:04:13.814Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:04:13.814Z"'::jsonb),
('card-nbcd-2021-135', NULL, 'deck-prc-2021-nbcd', 'A sensible weight reducing program includes _____.', 'B. diet, exercise and behavior modification', 'The gold standard, evidence-based triad for sustainable long-term weight reduction and maintenance consists of: (1) a nutritionally balanced, hypocaloric diet, (2) regular aerobic and resistance exercise, and (3) cognitive-behavioral lifestyle modification (self-monitoring, stimulus control, cognitive restructuring).', '["A. drugs that will lead to rapid weight loss","B. diet, exercise and behavior modification","C. use formula diets to ensure appropriate calorie intake","D. use of herbal preparations as an adjunct to diet"]'::jsonb, '["Weight Management","Obesity","Behavior Modification","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. diet, exercise and behavior modification. The evidence-based triad of weight management.', '{"dueDate":"2026-11-06T11:50:37.421Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:50:37.421Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:50:37.421Z"'::jsonb),
('card-nbcd-2021-136', NULL, 'deck-prc-2021-nbcd', 'When monitoring for food allergy, which outcome should be measured?', 'A. Reduction of food related reactions', 'In the Nutrition Care Process (NCP) for food allergy management, the definitive clinical outcome indicator is the documented reduction, alleviation, or total prevention of adverse allergic clinical manifestations.', '["A. Reduction of food related reactions","B. level of knowledge about causes of food allergies","C. Patient satisfaction with counseling","D. Frequency of patient failure to comply with instructions"]'::jsonb, '["Food Allergy","Nutrition Monitoring and Evaluation","NCP"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Reduction of food related reactions (Exam duplicate of Q113).', '{"dueDate":"2026-11-06T13:08:57.724Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:08:57.724Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:08:57.724Z"'::jsonb),
('card-nbcd-2021-137', NULL, 'deck-prc-2021-nbcd', 'Which of the following increase disease risk?', 'B. Central body fat', 'Central (abdominal/visceral) adiposity (android fat distribution) is metabolically active and secretes free fatty acids, pro-inflammatory adipokines (TNF-alpha, IL-6), and resistin into the portal system, strongly predisposing to insulin resistance, type 2 diabetes, dyslipidemia, systemic hypertension, and cardiovascular disease.', '["A. BMI of 19 - 21","B. Central body fat","C. Lower body fat","D. BMI of 22 - 25"]'::jsonb, '["Nutritional Assessment","Anthropometry","Visceral Fat","Cardiometabolic Risk"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Central body fat. Android visceral adiposity poses high metabolic and cardiovascular risk.', '{"dueDate":"2026-11-06T15:10:25.889Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:10:25.889Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:10:25.889Z"'::jsonb),
('card-nbcd-2021-138', NULL, 'deck-prc-2021-nbcd', 'Exercise is beneficial in weight management because it _____.
I. helps regulate appetite
II. decreases BMR
III. reduces stress related eating habit
IV. increases the "set point" for fat deposit', 'D. I and III', 'Regular exercise assists weight management by modulating hunger hormones (ghrelin suppression, PYY elevation) to help regulate appetite (I), preserving lean muscle mass to prevent drops in metabolic rate, and serving as a healthy emotional coping strategy to curb stress-induced emotional overeating (III). Exercise increases (not decreases) metabolic rate and lowers (not increases) the set-point.', '["A. II and IV","B. I and IV","C. II and III","D. I and III"]'::jsonb, '["Weight Management","Exercise Physiology","Appetite Regulation"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. I and III. Exercise suppresses stress eating and assists appetite regulation.', '{"dueDate":"2026-11-06T11:47:10.316Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:47:10.316Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:47:10.316Z"'::jsonb),
('card-nbcd-2021-139', NULL, 'deck-prc-2021-nbcd', 'Called the "feasting hormone" because its release is enhanced by a high glucose level.', 'A. Insulin', 'Insulin is known as the ''feasting hormone'' (or hormone of abundance) because postprandial elevations in blood glucose and amino acids stimulate its secretion from pancreatic beta cells, promoting nutrient storage pathways (glycogenesis, lipogenesis, and protein translation) while inhibiting catabolic pathways.', '["A. Insulin","B. Glucagon","C. Thyroxin","D. Epinephrine"]'::jsonb, '["Nutritional Biochemistry","Endocrine","Insulin","Hormones"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Insulin. Anabolic hormone of the fed/feasting state.', '{"dueDate":"2026-11-06T13:00:21.694Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:00:21.694Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:00:21.694Z"'::jsonb),
('card-nbcd-2021-14', NULL, 'deck-prc-2021-nbcd', 'The cells that secrete the HCL in the body.', 'A. Parietal', 'Parietal (oxyntic) cells located in the gastric glands of the stomach fundus and corpus secrete hydrochloric acid (HCl) and intrinsic factor. Chief cells secrete pepsinogen; G-cells secrete the hormone gastrin.', '["A. Parietal","B. G-cells","C. Somatic","D. Chief cells"]'::jsonb, '["Physiology","Gastrointestinal","Digestion","Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Parietal. Parietal = HCl + Intrinsic Factor; Chief = Pepsinogen; G-cells = Gastrin.', '{"dueDate":"2026-11-06T13:17:39.726Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:17:39.726Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:17:39.726Z"'::jsonb),
('card-nbcd-2021-140', NULL, 'deck-prc-2021-nbcd', 'Which one of the following statements about ascorbic acid is INCORRECT?', 'A. Its requirement varies with caloric intake.', 'Ascorbic acid (Vitamin C) requirement does NOT vary with caloric intake; its RDA is established based on neutrophil saturation and antioxidant protection. (In contrast, thiamin, riboflavin, and niacin scale with caloric intake). Ascorbic acid reduces ferric iron to absorbable ferrous iron (B), is rapidly oxidized in the presence of Cu2+ and Fe3+ (C), and its degradation pathway produces oxalate (D).', '["A. Its requirement varies with caloric intake.","B. It facilitates the absorption of dietary iron.","C. It is readily oxidized by divalent metal ions.","D. It is metabolized in part of oxalate, which can form an insoluble salt calcium."]'::jsonb, '["Nutritional Biochemistry","Vitamin C","Ascorbic Acid","Iron Absorption"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. Its requirement varies with caloric intake (INCORRECT statement). B-vitamins scale with calories, not Vitamin C.', '{"dueDate":"2026-11-06T12:38:55.374Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:38:55.374Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:38:55.374Z"'::jsonb),
('card-nbcd-2021-141', NULL, 'deck-prc-2021-nbcd', 'A person watching TV reaches for a snack during a commercial break in response to:', 'A. External cues', 'Eating prompted by environmental stimuli—such as TV food commercials, the sight or smell of food, or habitual sedentary activities—is governed by external cues rather than internal physiological hunger sensations (appetite vs. physiological hunger).', '["A. External cues","B. Stress arousal","C. Satiety factor","D. Hunger signal"]'::jsonb, '["Behavior Modification","Appetite","External Cues","Nutrition Counseling"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. External cues (D was crossed to A). Environmental stimuli trigger non-hunger eating.', '{"dueDate":"2026-11-06T15:06:01.148Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:06:01.148Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:06:01.148Z"'::jsonb),
('card-nbcd-2021-142', NULL, 'deck-prc-2021-nbcd', 'When expressed as a percentage of body weight, at what level of dehydration does performance level notably decrease?', 'C. 3%', 'Body water deficits of 2% to 3% of body weight significantly impair aerobic athletic performance, muscular endurance, cognitive processing, and core thermoregulation, increasing cardiovascular strain and perceived exertion.', '["A. 5%","B. 1%","C. 3%","D. 10%"]'::jsonb, '["Sports Nutrition","Dehydration","Fluid Balance","Thermoregulation"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. 3%. Dehydration threshold for significant functional/performance impairment.', '{"dueDate":"2026-11-06T15:13:31.834Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:31.834Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:31.834Z"'::jsonb),
('card-nbcd-2021-143', NULL, 'deck-prc-2021-nbcd', 'Mr. P wants to lose weight and has a BMI of 30 and a waist circumference of 41. Initially Nutritionist Dietitian should advise Mr. P to _____.', 'A. Self-monitor and write down his food intake and physical activity', 'Self-monitoring (keeping a detailed, real-time food and physical activity log) is the most effective initial behavioral assessment and intervention tool in weight management counseling. It establishes baseline caloric patterns, increases self-awareness, and identifies dietary triggers before prescribing specific caloric deficits.', '["A. Self-monitor and write down his food intake and physical activity","B. Ask his doctor for a medication to assist in weight reduction","C. see a physician for consultation","D. follow a 1200 calorie diet"]'::jsonb, '["Weight Management","Nutrition Counseling","Self-Monitoring","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Self-monitor and write down his food intake and physical activity. Foundation of behavioral weight counseling.', '{"dueDate":"2026-11-06T14:40:23.692Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:40:23.692Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:40:23.692Z"'::jsonb),
('card-nbcd-2021-144', NULL, 'deck-prc-2021-nbcd', 'Which of the hormones is responsible for promoting appetite?', 'B. Grehlin', 'Ghrelin is a 28-amino acid peptide hormone secreted primarily by oxyntic endocrine cells of the gastric fundus that acts on the arcuate nucleus of the hypothalamus (NPY/AgRP neurons) to stimulate appetite and meal initiation (''the hunger hormone''). Leptin and PYY suppress appetite.', '["A. Insulin","B. Grehlin","C. Peptide YY","D. Leptin"]'::jsonb, '["Nutritional Biochemistry","Ghrelin","Appetite Regulation","Hormones"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Grehlin. Principal orexigenic (appetite-stimulating) peptide hormone.', '{"dueDate":"2026-11-06T13:18:29.488Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:18:29.488Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:18:29.488Z"'::jsonb),
('card-nbcd-2021-145', NULL, 'deck-prc-2021-nbcd', 'One of the typical symptoms of food allergies is _____.', 'D. hives', 'Acute IgE-mediated hypersensitivity reactions trigger mast cell and basophil degranulation with release of histamine and leukotrienes, causing rapid cutaneous manifestations—most classically urticaria (hives), pruritus, and angioedema.', '["A. colitis","B. diabetes mellitus","C. atherosclerosis","D. hives"]'::jsonb, '["Food Allergy","Immunology","Symptoms","Histamine"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. hives. Cutaneous manifestation (urticaria) of IgE-mediated allergy.', '{"dueDate":"2026-11-06T14:30:52.355Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:30:52.355Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:30:52.355Z"'::jsonb),
('card-nbcd-2021-146', NULL, 'deck-prc-2021-nbcd', 'Clinical sign/s of edema is/are _____.', 'A. puffy, swollen condition', 'Edema is an abnormal expansion of the interstitial fluid volume manifesting clinically as palpable puffiness, swelling, tightness of the skin, and pitting on pressure in dependent extremities (pedal edema) or generalized anasarca.', '["A. puffy, swollen condition","B. change in hair color","C. extreme wasting and wrinkled skin","D. severe emaciation"]'::jsonb, '["Nutrition Assessment","NFPE","Edema","Fluid Balance"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. puffy, swollen condition. Physical manifestation of interstitial fluid retention.', '{"dueDate":"2026-11-06T13:22:41.883Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:22:41.883Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:22:41.883Z"'::jsonb),
('card-nbcd-2021-147', NULL, 'deck-prc-2021-nbcd', 'In patients with moderate renal insufficiency, restriction of which of the following dietary constituents slows the progression of chronic renal failure?', 'A. Protein and phosphorus', 'In moderate chronic kidney disease (Stages 3–4), dietary protein restriction (0.6–0.8 g/kg/day) reduces glomerular hyperfiltration and blunts intraglomerular capillary hypertension, while dietary phosphorus restriction (800–1,000 mg/day) prevents hyperphosphatemia, secondary hyperparathyroidism, FGF-23 elevation, and renal osteodystrophy/vascular calcification.', '["A. Protein and phosphorus","B. Protein and sodium","C. Carbohydrate and calcium","D. Carbohydrate and potassium"]'::jsonb, '["Renal Nutrition","CKD","Protein Restriction","Phosphorus","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. Protein and phosphorus (B crossed to A). Key dietary restrictions to slow CKD progression.', '{"dueDate":"2026-11-06T15:08:43.102Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:08:43.102Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:08:43.102Z"'::jsonb),
('card-nbcd-2021-148', NULL, 'deck-prc-2021-nbcd', 'Other name for dextrose, grape sugar and blood sugar.', 'D. Glucose', 'D-glucose is commonly referred to as dextrose (due to its dextrorotatory optical activity), grape sugar (because of its abundance in ripe grapes), and blood sugar (as it is the primary circulating hexose monosaccharide in human blood).', '["A. Maltose","B. Fructose","C. Sucrose","D. Glucose"]'::jsonb, '["Nutritional Biochemistry","Carbohydrates","Monosaccharides","Glucose"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Glucose. Synonyms: Dextrose, grape sugar, physiological blood sugar.', '{"dueDate":"2026-11-06T14:34:13.575Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:34:13.575Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:34:13.575Z"'::jsonb),
('card-nbcd-2021-149', NULL, 'deck-prc-2021-nbcd', 'Which of the following is a function of a phytochemical?', 'C. Slow down tumor growth.', 'Bioactive phytochemicals (e.g., curcumin, resveratrol, epigallocatechin gallate, sulforaphane) exert potent antineoplastic effects by suppressing oncogenic signaling pathways, inhibiting tumor angiogenesis, arresting malignant cell cycles, and inducing apoptosis.', '["A. Decrease blood lipid value.","B. Diminish activity of certain enzymes.","C. Slow down tumor growth.","D. Decrease inflammation."]'::jsonb, '["Phytochemicals","Oncology Nutrition","Bioactives"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. Slow down tumor growth (anti-cancer/anti-tumorigenic properties).', '{"dueDate":"2026-11-06T14:51:24.005Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:51:24.005Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:51:24.005Z"'::jsonb),
('card-nbcd-2021-15', NULL, 'deck-prc-2021-nbcd', 'Sudden hyperglycemia in a person who has consistently maintained good blood glucose control can be precipitated by _____.', 'A. infection or illness', 'Acute infection, trauma, or systemic illness triggers a massive surge of stress and counter-regulatory hormones (epinephrine, cortisol, glucagon, growth hormone) and inflammatory cytokines. These hormones induce peripheral insulin resistance and stimulate hepatic glycogenolysis and gluconeogenesis, precipitating acute severe hyperglycemia.', '["A. infection or illness","B. conditions that lower levels of counter-regulatory hormones","C. chronic alcohol ingestion","D. undertreatment of hypoglycemia"]'::jsonb, '["Diabetes Mellitus","Endocrine","MNT","Pathophysiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. infection or illness. Infection induces counter-regulatory hormones causing acute glycemic spikes.', '{"dueDate":"2026-11-06T15:04:42.222Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:04:42.222Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:04:42.222Z"'::jsonb),
('card-nbcd-2021-150', NULL, 'deck-prc-2021-nbcd', 'An allergy is a hypersensitivity to a/an:', 'D. allergen', 'An allergy is an immunologically mediated hypersensitivity reaction directed against a specific environmental or dietary substance known as an allergen (a specific antigen, usually an intact glycoprotein, capable of inducing IgE production and hypersensitivity).', '["A. antibodies","B. T cells","C. antigen","D. allergen"]'::jsonb, '["Food Allergy","Immunology","Definitions"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. allergen. Definition of allergic hypersensitivity.', '{"dueDate":"2026-11-06T11:50:10.824Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:50:10.824Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:50:10.824Z"'::jsonb)
