INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-nbcd-2021-151', NULL, 'deck-prc-2021-nbcd', 'Which of the following fruit or fruit products can easily cause drug interactions?', 'B. Grapefruit', 'Grapefruit and grapefruit juice contain furanocoumarins (such as bergamottin and 6'',7''-dihydroxybergamottin) that irreversibly inhibit the intestinal cytochrome P450 3A4 (CYP3A4) enzyme system. This inhibits first-pass drug metabolism and causes substantial, unpredictable increases in bioavailability and toxicity for many medications, including statins (atorvastatin, simvastatin), calcium channel blockers, and immunosuppressants (cyclosporine, tacrolimus).', '["A. Apple juice","B. Grapefruit","C. Banana","D. Kiwi"]'::jsonb, '["Pharmacology","Drug-Nutrient Interactions","Grapefruit","CYP3A4"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Grapefruit. Furanocoumarins inhibit intestinal CYP3A4, causing drug toxicity.', '{"dueDate":"2026-11-06T13:02:58.631Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:02:58.631Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:02:58.631Z"'::jsonb),
('card-nbcd-2021-152', NULL, 'deck-prc-2021-nbcd', 'Triggers the GI secretory action.', 'A. Nerve Network (inner plexus)', 'The intrinsic enteric nervous system, specifically the submucosal (Meissner''s) plexus (the ''inner plexus'' embedded in the submucosa of the intestinal wall), directly innervates glandular epithelial cells to control and trigger local gastrointestinal secretions and blood flow.', '["A. Nerve Network (inner plexus)","B. Body Senses","C. Hormones","D. Enzymes"]'::jsonb, '["Physiology","Enteric Nervous System","Gastrointestinal Secretions"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. Nerve Network (inner plexus). Note: Submucosal/Meissner''s plexus controls mucosal secretion.', '{"dueDate":"2026-11-06T13:04:01.100Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:04:01.100Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:04:01.100Z"'::jsonb),
('card-nbcd-2021-153', NULL, 'deck-prc-2021-nbcd', 'People at risk of dumping syndrome should avoid;', 'C. sweets and sugars', 'In post-gastrectomy dumping syndrome, concentrated simple sugars and sweets (sucrose, glucose, corn syrup) create a hyperosmolar bolus that rapidly empties into the jejunum, drawing massive fluid from circulating plasma into the gut lumen (causing osmotic diarrhea, abdominal cramping, hypovolemia, tachycardia, and late reactive hypoglycemia).', '["A. beverages","B. high fiber food","C. sweets and sugars","D. bread and potatoes"]'::jsonb, '["Gastrointestinal","Dumping Syndrome","Simple Sugars","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. sweets and sugars. Hyperosmolar concentrated sweets provoke rapid jejunal dumping.', '{"dueDate":"2026-11-06T14:21:31.482Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:21:31.482Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:21:31.482Z"'::jsonb),
('card-nbcd-2021-154', NULL, 'deck-prc-2021-nbcd', 'What is required for the absorption of calcium from the intestine and the uptake of calcium and phosphorous by the bones and teeth?', 'B. Vit. D', 'Active Vitamin D (1,25-dihydroxycholecalciferol or calcitriol) stimulates the genomic transcription of intestinal calcium-binding protein (calbindin-D9k) and TRPV6 channels, enabling active transcellular calcium and phosphorus absorption across enterocytes, and facilitates osteoblast-mediated bone matrix mineralization.', '["A. Vit. B1","B. Vit. D","C. Vit. C","D. Vit. E"]'::jsonb, '["Nutritional Biochemistry","Vitamin D","Calcium","Bone Metabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Vit. D. Calcitriol upregulates intestinal calbindin for Ca and P absorption.', '{"dueDate":"2026-11-06T11:58:05.693Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:58:05.693Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:58:05.693Z"'::jsonb),
('card-nbcd-2021-155', NULL, 'deck-prc-2021-nbcd', 'Which fluid deficit would lead to a decrease of 20 - 30 % in physical work capacity?', 'D. 5%', 'A body fluid deficit of 5% of body weight severely compromises intravascular circulating volume, reduces stroke volume, elevates heart rate, impairs cutaneous heat dissipation, and diminishes physical aerobic work capacity by 20% to 30%.', '["A. 4%","B. 3%","C. 2%","D. 5%"]'::jsonb, '["Sports Nutrition","Fluid Balance","Dehydration","Work Capacity"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. 5%. 5% hypohydration reduces physical work capacity by 20-30%.', '{"dueDate":"2026-11-06T14:59:39.494Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:59:39.494Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:59:39.494Z"'::jsonb),
('card-nbcd-2021-156', NULL, 'deck-prc-2021-nbcd', 'Which of the following statement is TRUE about the sources of Vit. K?', 'C. Most of our Vit. K is produced by the intestinal bacteria.', 'While phylloquinone (Vitamin K1) is supplied by green leafy vegetables, a substantial portion of human physiological Vitamin K needs is provided by menaquinones (Vitamin K2) synthesized endogenously by normal commensal bacterial microflora (Bacteroides, Escherichia coli) in the ileum and large intestine.', '["A. Rarely fund in foods so a natural deficiency develops.","B. Found in a wide variety of foods so no deficiency occurs.","C. Most of our Vit. K is produced by the intestinal bacteria.","D. It is easily absorbed in the body."]'::jsonb, '["Nutritional Biochemistry","Vitamin K","Gut Microbiota","Vitamins"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Most of our Vit. K is produced by the intestinal bacteria. Endogenous bacterial synthesis of K2.', '{"dueDate":"2026-11-06T13:00:06.228Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:00:06.228Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:00:06.228Z"'::jsonb),
('card-nbcd-2021-157', NULL, 'deck-prc-2021-nbcd', 'What is the BEST way to determine if an athlete''s weight gain is muscle gain?', 'B. Hydrostatic weighing', 'Hydrostatic (underwater) weighing utilizes Archimedes'' principle of water displacement to determine total body density, serving as a classic laboratory gold standard method to distinguish fat-free mass (muscle, bone) from fat mass, thereby accurately verifying true lean muscle hypertrophy.', '["A. Ultrasound","B. Hydrostatic weighing","C. Body Impedance measurement","D. Skinfold measurement"]'::jsonb, '["Sports Nutrition","Body Composition","Hydrostatic Weighing","Assessment"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Hydrostatic weighing (or C/D). Hydrostatic densitometry differentiates lean tissue from fat.', '{"dueDate":"2026-11-06T14:51:46.723Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:51:46.723Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:51:46.723Z"'::jsonb),
('card-nbcd-2021-158', NULL, 'deck-prc-2021-nbcd', 'Preparation of formula is of utmost importance for enteral feeding. To prevent bacterial contamination, your instruction to the caregiver should include all of the following EXCEPT;', 'D. To add a new supply of formula to an old formula to save money', 'Pouring fresh enteral feeding formula into residual formula left in a hang bag (''topping off'') introduces retrograde bacterial contamination and permits exponential pathogen proliferation, causing infectious gastroenteritis or enteral formula sepsis. Formula sets should be rinsed and discarded according to protocol (open systems discarded after 4-8 hours).', '["A. Do not allow formula to stand longer than 4 to 8 hours at room","B. Refrigerate prepared formula if not used immediately","C. Prepare formula with clean hands in a clean environment","D. To add a new supply of formula to an old formula to save money"]'::jsonb, '["Enteral Nutrition","Food Safety","Infection Control","Caregiver Education"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. To add a new supply of formula to an old formula to save money. Unsafe practice causing bacterial colonization.', '{"dueDate":"2026-11-06T14:29:28.744Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:29:28.744Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:29:28.744Z"'::jsonb),
('card-nbcd-2021-159', NULL, 'deck-prc-2021-nbcd', 'One specific indication of enteral nutrition is:', 'D. anorexia', 'Severe, persistent anorexia (resulting in severe caloric deficit in a patient with a functioning gastrointestinal tract) is an established indication for enteral tube nutrition support. In contrast, mechanical bowel obstruction, active GI bleeding, and intractable diarrhea are absolute contraindications.', '["A. small bowel obstruction","B. upper gastrointestinal bleed","C. intractable diarrhea","D. anorexia"]'::jsonb, '["Enteral Nutrition","Indications","Nutrition Support"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. anorexia (Exam duplicate of Q119).', '{"dueDate":"2026-11-06T11:59:43.470Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:59:43.470Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:59:43.470Z"'::jsonb),
('card-nbcd-2021-16', NULL, 'deck-prc-2021-nbcd', 'The recommended fiber intake is _____ grams per day.', 'D. 20-35', 'Standard clinical nutrition guidelines (including the Academy of Nutrition and Dietetics and ADA) recommend a dietary fiber intake of 20 to 35 grams per day for healthy adults, or approximately 14 grams per 1,000 kcal.', '["A. 15-25","B. 40-55","C. 10-15","D. 20-35"]'::jsonb, '["Fiber","Nutrient Requirements","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. 20-35 grams per day. 14g/1000 kcal or 20-35 g/day is the standard board exam guideline.', '{"dueDate":"2026-11-06T13:05:08.299Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:05:08.299Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:05:08.299Z"'::jsonb),
('card-nbcd-2021-160', NULL, 'deck-prc-2021-nbcd', 'Mrs. Santos is scheduled to have her body fat measured by bioelectrical impedance. The test involves _____.', 'C. attachment of electrodes to the extremities to measure resistance in the tissues', 'Bioelectrical Impedance Analysis (BIA) involves introducing a safe, imperceptible, high-frequency alternating electrical current via contact surface electrodes placed on the distal extremities (hand/wrist and foot/ankle) to measure electrical resistance (impedance) across bodily water compartments, from which total body water and fat-free mass are estimated.', '["A. weighing the client while she is immersed in tank of water","B. measurement of weight and height as well as use of mathematical formula to compute body mass","C. attachment of electrodes to the extremities to measure resistance in the tissues","D. measurement of a skin fold on the arm or abdomen using calipers"]'::jsonb, '["Nutrition Assessment","Body Composition","BIA","Anthropometry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. attachment of electrodes to the extremities to measure resistance in the tissues.', '{"dueDate":"2026-11-06T12:28:33.372Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:28:33.372Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:28:33.372Z"'::jsonb),
('card-nbcd-2021-161', NULL, 'deck-prc-2021-nbcd', 'A gradual transition from IV feeding to oral diet is primarily designed to:', 'A. ensure that nutrient needs will continue to be met', 'Transitional feeding (weaning from parenteral nutrition to enteral or oral intake) requires gradual tapering while concurrently stepping up oral intake, maintaining total caloric and protein coverage until oral intake reliably provides >=60% to 75% of estimated nutrient requirements.', '["A. ensure that nutrient needs will continue to be met","B. prevent hypoglycemia","C. improve the appetite","D. prevent apprehension about eating"]'::jsonb, '["Nutrition Support","Parenteral Nutrition","Transitional Feeding","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. ensure that nutrient needs will continue to be met. Transitional feeding prevents nutritional deficits.', '{"dueDate":"2026-11-06T11:53:39.066Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:53:39.066Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:53:39.066Z"'::jsonb),
('card-nbcd-2021-162', NULL, 'deck-prc-2021-nbcd', 'For clients who want to meet goals you set, let them consider and explain the following factors EXCEPT:', 'A. ambitious goals are good, but overly ambitious goals are hard to follow', 'In behavioral goal-setting theory, goals should be realistic, achievable, and incremental (SMART). Framing that ''overly ambitious goals are good'' is contradictory and counterproductive because unrealistic targets promote failure and demotivation.', '["A. ambitious goals are good, but overly ambitious goals are hard to follow","B. do self-monitoring","C. regular feedback on progress improves outcomes","D. the more specific the goal, the more likely it can be achieved"]'::jsonb, '["Nutrition Counseling","Goal Setting","Behavioral Theories"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. ambitious goals are good, but overly ambitious goals are hard to follow. Board counseling item.', '{"dueDate":"2026-11-06T14:59:26.624Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:59:26.624Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:59:26.624Z"'::jsonb),
('card-nbcd-2021-163', NULL, 'deck-prc-2021-nbcd', 'A 50 year old business man was admitted to the hospital with diagnosis kidney failure. He has been following his renal diet of limited protein for the past 3 years. He''s now scheduled to have a permanent fistula to be ready for hemodialysis. You will advise him that his diet will change once he is on hemodialysis to _____ exchanges.', 'C. more protein', 'Prior to dialysis, non-dialyzed CKD patients follow a protein-restricted diet (0.6–0.8 g/kg/day) to slow decline of GFR and minimize uremic toxins. Once maintenance hemodialysis is initiated, dialysate losses (10–13 g amino acids per session) and dialysis-induced inflammation require liberalizing dietary protein to 1.2 g/kg/day (more protein exchanges).', '["A. less carbohydrates","B. less fat","C. more protein","D. more high potassium fruits and vegetable"]'::jsonb, '["Renal Nutrition","Hemodialysis","Protein Requirements","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. more protein. Transition from pre-dialysis (0.6-0.8 g/kg) to hemodialysis (1.2 g/kg).', '{"dueDate":"2026-11-06T14:34:37.653Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:34:37.653Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:34:37.653Z"'::jsonb),
('card-nbcd-2021-164', NULL, 'deck-prc-2021-nbcd', 'A dietary management that is NOT indicative of pre-dialysis', 'A. fluids', 'In pre-dialysis (non-dialyzed CKD Stages 1–4), kidneys generally retain sufficient urine concentrating and volume-regulating ability, so routine fluid restriction is NOT indicated unless the patient develops congestive heart failure, severe oliguria, or refractory edema. In contrast, protein and phosphorus restrictions are hallmark pre-dialysis interventions.', '["A. fluids","B. calories","C. protein","D. fat"]'::jsonb, '["Renal Nutrition","Pre-Dialysis","CKD","Fluid Management"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. fluids. Fluid restriction is typically initiated only once oliguria or dialysis begins.', '{"dueDate":"2026-11-06T15:03:51.252Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:03:51.252Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:03:51.252Z"'::jsonb),
('card-nbcd-2021-165', NULL, 'deck-prc-2021-nbcd', 'The simplest treatment for a food allergy is _____.', 'D. elimination of the allergen', 'Complete and strict dietary elimination of the causative food allergen is the single most effective, safe, and foundational treatment for food hypersensitivity.', '["A. a skin test","B. the use of penicillin","C. avoiding of the allergen","D. elimination of the allergen"]'::jsonb, '["Food Allergy","Elimination Diet","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. elimination of the allergen (Exam duplicate of Q110).', '{"dueDate":"2026-11-06T13:02:45.673Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:02:45.673Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:02:45.673Z"'::jsonb),
('card-nbcd-2021-166', NULL, 'deck-prc-2021-nbcd', 'Which of the hormones plays an important role in inhibiting appetite?', 'C. Leptin', 'Leptin is an adipokine synthesized by white adipose tissue in proportion to fat mass that crosses the blood-brain barrier to bind receptors on POMC/CART neurons in the hypothalamic arcuate nucleus, exerting tonic long-term inhibition on appetite and stimulating energy expenditure.', '["A. Peptide YY","B. Resistin","C. Leptin","D. Grehlin"]'::jsonb, '["Nutritional Biochemistry","Leptin","Appetite Regulation","Adipokines"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Leptin. Long-term adiposity hormone inhibiting appetite; Grehlin stimulates appetite.', '{"dueDate":"2026-11-06T14:20:13.024Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:20:13.024Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:20:13.024Z"'::jsonb),
('card-nbcd-2021-167', NULL, 'deck-prc-2021-nbcd', 'Which of the fat soluble vitamins will a NON-ambulatory elderly patient be at risk of deficiency?', 'B. D', 'Non-ambulatory, bedridden, or institutionalized elderly individuals lack sunlight exposure, compound by aging skin having a 75% reduced capacity to synthesize 7-dehydrocholesterol and declining renal 1-alpha-hydroxylase activity, placing them at very high risk for Vitamin D deficiency and osteomalacia.', '["A. A","B. D","C. K","D. E"]'::jsonb, '["Geriatric Nutrition","Vitamin D","Micronutrient Deficiencies","Bone Health"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. D (Vitamin D). Lack of sunlight + aging skin + decreased renal hydroxylation.', '{"dueDate":"2026-11-06T11:27:19.238Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:27:19.238Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:27:19.238Z"'::jsonb),
('card-nbcd-2021-168', NULL, 'deck-prc-2021-nbcd', 'Which of the following is the BEST advice to increase oral intake for a chemotherapy client who suffers from nausea and vomiting?', 'B. Take only foods that are well liked', 'For oncology patients undergoing chemotherapy with severe nausea and anticipatory aversions, clinical dietitians advise consuming whatever appealing, well-tolerated foods the patient prefers in small, frequent amounts. High-fat foods delay gastric emptying and fluids with meals cause gastric distension, both aggravating nausea.', '["A. Eat slowly and chew thoroughly","B. Take only foods that are well liked","C. Eat high-fat, high-protein meals","D. Drink plenty of fluids with the meal"]'::jsonb, '["Oncology Nutrition","Chemotherapy","Nausea Management","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Take only foods that are well liked (A. Eat slowly also helpful; B prioritized on exam).', '{"dueDate":"2026-11-06T15:01:21.523Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:01:21.523Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:01:21.523Z"'::jsonb),
('card-nbcd-2021-169', NULL, 'deck-prc-2021-nbcd', 'Nutrients are _____.', 'A. chemical elements / compounds in foods that have a specific metabolic function', 'By scientific definition, nutrients are specific chemical substances (elements or organic compounds) provided by foods that are indispensable for energy, cellular structure, growth, tissue maintenance, and metabolic regulation in the body.', '["A. chemical elements / compounds in foods that have a specific metabolic function","B. metabolic control substances such as enzymes","C. nourishing foods used to cure illnesses","D. foods that are necessary for good health"]'::jsonb, '["Basic Nutrition","Definitions","Nutritional Science"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. chemical elements / compounds in foods that have a specific metabolic function.', '{"dueDate":"2026-11-06T11:50:28.121Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:50:28.121Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:50:28.121Z"'::jsonb),
('card-nbcd-2021-17', NULL, 'deck-prc-2021-nbcd', 'Which of the following describes water-soluble vitamins?', 'B. Easily absorbed and excreted', 'Water-soluble vitamins (B-complex vitamins and Vitamin C) are hydrophilic, dissolve freely in body fluids, are easily absorbed into the portal bloodstream, and excess amounts are readily excreted by the kidneys into urine. They have minimal tissue storage (except B12 in the liver) and rarely cause toxicity under physiological intakes.', '["A. It includes vitamins C, D and E","B. Easily absorbed and excreted","C. It is stored extensively in the tissues.","D. Can reach toxic levels."]'::jsonb, '["Nutritional Biochemistry","Vitamins","Micronutrients"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Easily absorbed and excreted. Water-soluble = B and C; excreted in urine; low toxicity risk.', '{"dueDate":"2026-11-06T14:59:20.249Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:59:20.249Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:59:20.249Z"'::jsonb),
('card-nbcd-2021-170', NULL, 'deck-prc-2021-nbcd', 'All are functions of electrolytes EXCEPT _____.', 'C. maintenance of the normal immune system', 'Electrolytes (Na+, K+, Cl-, HCO3-) function fundamentally in regulating fluid compartment volumes, establishing colloidal and crystalloid osmotic pressures, maintaining physiological acid-base buffers, and conducting nerve action potentials. Adaptive and innate immune system defenses are protein- and cellular-mediated, not a direct primary function of electrolytes.', '["A. maintenance of the normal fluid balance","B. maintenance of the acid-base balance","C. maintenance of the normal immune system","D. creation of osmotic pressure"]'::jsonb, '["Physiology","Electrolytes","Acid-Base Balance","Fluid Balance"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. maintenance of the normal immune system. Core electrolyte functions: Osmotic pressure, fluid and acid-base balance.', '{"dueDate":"2026-11-06T13:04:55.999Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:04:55.999Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:04:55.999Z"'::jsonb),
('card-nbcd-2021-171', NULL, 'deck-prc-2021-nbcd', 'conversion of non-carbohydrate material to glucose is _____.', 'B. gluconeogenesis', 'Gluconeogenesis is the metabolic pathway through which glucose is synthesized de novo from non-carbohydrate carbon substrates, including glucogenic amino acids (e.g., alanine), glycerol, lactate, and pyruvate, predominantly in the liver and renal cortex.', '["A. glycolysis","B. gluconeogenesis","C. glycogenolysis","D. glycogenesis"]'::jsonb, '["Nutritional Biochemistry","Carbohydrate Metabolism","Gluconeogenesis","Liver"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. gluconeogenesis. De novo synthesis of glucose from non-carbohydrate precursors.', '{"dueDate":"2026-11-06T12:27:29.320Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:27:29.320Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:27:29.320Z"'::jsonb),
('card-nbcd-2021-172', NULL, 'deck-prc-2021-nbcd', 'Which of these are the characteristics of Vitamin A?
I. Fairly stable to heat.
II. Highly soluble in water.
III. Requires bile for absorption.
IV. Has a precursor. (Beta - Carotene)', 'D. I, III and IV', 'Vitamin A is fat-soluble (NOT soluble in water, making II incorrect), is relatively heat-stable under normal cooking temperatures (I), requires bile salts and dietary lipids for micellar incorporation and intestinal absorption (III), and has plant provitamin precursors such as beta-carotene (IV). Therefore, I, III, and IV are correct.', '["A. III and IV","B. I, II, III and, IV","C. I, II and, IV","D. I, III and IV"]'::jsonb, '["Nutritional Biochemistry","Vitamin A","Fat-Soluble Vitamins","Characteristics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. I, III and IV. Vitamin A is fat-soluble (not water-soluble), heat-stable, requires bile.', '{"dueDate":"2026-11-06T12:37:47.754Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:37:47.754Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:37:47.754Z"'::jsonb),
('card-nbcd-2021-173', NULL, 'deck-prc-2021-nbcd', 'The NCEP Step I diet recommends _____% saturated fat/day.', 'A. 10', 'Under the National Cholesterol Education Program (NCEP) Adult Treatment Panel guidelines:
- Step I Diet: Saturated fatty acids < 8–10% of total daily calories, cholesterol < 300 mg/day.
- Step II Diet: Saturated fatty acids < 7% of total daily calories, cholesterol < 200 mg/day.
Hence, NCEP Step I recommends 8-10% (Choice A: 10%).', '["A. 10","B. 7","C. 30","D. 5"]'::jsonb, '["Cardiovascular Nutrition","NCEP Guidelines","Lipids","Saturated Fat"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. 10 (or B. 7 for Step II). Step I = 8-10%; Step II = <7% saturated fat.', '{"dueDate":"2026-11-06T14:51:33.231Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:51:33.231Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:51:33.231Z"'::jsonb),
('card-nbcd-2021-174', NULL, 'deck-prc-2021-nbcd', 'Choose the CORRECT energy value per gram.', 'B. Protein - 4 kcal', 'According to standard Atwater general physiological fuel values:
- Carbohydrate: 4 kcal/g
- Protein: 4 kcal/g
- Fat: 9 kcal/g
- Alcohol: 7 kcal/g.
Thus, Protein - 4 kcal is the only correct statement.', '["A. Fat - 7 kcal","B. Protein - 4 kcal","C. Carbohydrate - 9 kcal","D. Alcohol - 9 kcal"]'::jsonb, '["Basic Nutrition","Atwater Factors","Energy Calculations","Macronutrients"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Protein - 4 kcal. Atwater values: CHO 4, PRO 4, FAT 9, ALC 7 kcal/g.', '{"dueDate":"2026-11-06T12:55:55.011Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:55:55.011Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:55:55.011Z"'::jsonb),
('card-nbcd-2021-175', NULL, 'deck-prc-2021-nbcd', 'A deficiency caused by an inadequate dietary intake is a/an deficiency.', 'B. primary', 'A primary nutrient deficiency results directly from insufficient dietary intake of the nutrient. A secondary nutrient deficiency occurs when dietary intake is adequate, but underlying disease, malabsorption, genetic defects, or drug interactions impair digestion, absorption, utilization, or excretion.', '["A. covert","B. primary","C. secondary","D. overt"]'::jsonb, '["Nutritional Assessment","Deficiency Types","Definitions"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. primary. Primary = dietary inadequacy; Secondary = disease or drug-induced malabsorption.', '{"dueDate":"2026-11-06T15:02:49.979Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:02:49.979Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:02:49.979Z"'::jsonb),
('card-nbcd-2021-176', NULL, 'deck-prc-2021-nbcd', 'Derangements like a drop of potassium, phosphorous, magnesium among severely malnourished patients will indicate which condition?', 'D. Refeeding syndrome', 'The rapid drop of intracellular electrolytes—potassium, phosphorus, and magnesium—occurring upon aggressive nutrition repletion in a severely malnourished or starved patient is the hallmark hallmark of Refeeding Syndrome.', '["A. Hypervolemia","B. Hypovolemia","C. Fluid shock","D. Refeeding syndrome"]'::jsonb, '["Refeeding Syndrome","Critical Care","Electrolytes","Malnutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Refeeding syndrome (Exam duplicate concept of Q127/Q61).', '{"dueDate":"2026-11-06T15:02:46.364Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:02:46.364Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:02:46.364Z"'::jsonb),
('card-nbcd-2021-177', NULL, 'deck-prc-2021-nbcd', 'The consequences of cirrhosis are primarily due to:', 'C. liver cell damage and altered hepatic blood flow', 'The clinical and metabolic complications of liver cirrhosis (ascites, varices, hepatic encephalopathy, jaundice, coagulopathy) stem pathophysiologically from two fundamental structural derangements: (1) extensive hepatocellular destruction (liver cell damage) causing impaired synthetic and metabolic capacity, and (2) diffuse fibrous scarring that alters sinusoidal hepatic blood flow, generating portal hypertension.', '["A. chronic malnutrition","B. elevated blood ammonia, amino acids and sodium levels","C. liver cell damage and altered hepatic blood flow","D. chronic alcohol abuse"]'::jsonb, '["Hepatic Nutrition","Cirrhosis","Pathophysiology","Portal Hypertension"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. liver cell damage and altered hepatic blood flow. Fibrosis causing portal hypertension and parenchymal failure.', '{"dueDate":"2026-11-06T14:43:44.313Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:43:44.313Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:43:44.313Z"'::jsonb),
('card-nbcd-2021-178', NULL, 'deck-prc-2021-nbcd', 'A hand dynamometer tool is used to measure the muscular strength of a person. It is used for _____.', 'A. functional test', 'Handgrip dynamometry measures isometric hand muscle grip force, serving as a validated, objective functional test of skeletal muscle quality and physical performance in the Nutrition Focused Physical Exam (NFPE) to identify and classify malnutrition.', '["A. functional test","B. anthropometric measurement","C. body composition assessment","D. biochemical test"]'::jsonb, '["Nutrition Assessment","NFPE","Handgrip Dynamometry","Functional Status"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. functional test. Handgrip dynamometry evaluates muscle functional capacity in malnutrition.', '{"dueDate":"2026-11-06T14:29:02.048Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:29:02.048Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:29:02.048Z"'::jsonb),
('card-nbcd-2021-179', NULL, 'deck-prc-2021-nbcd', 'Minerals that are involved in carbohydrate metabolism', 'D. Chromium and Zinc', 'Chromium enhances insulin receptor tyrosine kinase activity (acting via the oligopeptide chromodulin / Glucose Tolerance Factor), and Zinc is essential for insulin crystallization, storage, and hexamer stabilization in pancreatic beta cells, as well as serving as a cofactor for glycolytic enzymes.', '["A. Iron and Iodine","B. Copper and Chromium","C. Cobalt and Zinc","D. Chromium and Zinc"]'::jsonb, '["Nutritional Biochemistry","Micronutrients","Trace Minerals","Carbohydrate Metabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. Chromium and Zinc. Chromium potentiates insulin; Zinc is required for insulin storage/secretion.', '{"dueDate":"2026-11-06T15:02:09.868Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:02:09.868Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:02:09.868Z"'::jsonb),
('card-nbcd-2021-18', NULL, 'deck-prc-2021-nbcd', 'Nutrition support at the end of life should be carefully based on the following EXCEPT:', 'A. family''s wish', 'In ethical clinical nutrition and palliative care, decisions regarding artificial nutrition support at the end of life must be centered primarily on patient autonomy (the patient''s documented wishes or advance directives), overall prognosis, clinical burden vs. benefit, and palliative therapy goals. Family wishes cannot override competent patient wishes or clinical futility.', '["A. family''s wish","B. therapy goals","C. patient''s wish","D. prognosis"]'::jsonb, '["Clinical Ethics","Nutrition Support","Palliative Care"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. family''s wish. Medical ethics: Patient autonomy and clinical goals supersede third-party family demands.', '{"dueDate":"2026-11-06T12:50:37.399Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:50:37.399Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:50:37.399Z"'::jsonb),
('card-nbcd-2021-180', NULL, 'deck-prc-2021-nbcd', 'Gastroesophageal reflux disease (GERD) is:', 'D. characterized by frequent backflow of the stomach''s gastric secretion into the esophagus', 'Gastroesophageal Reflux Disease (GERD) is a chronic digestive disease defined by the retrograde reflux of acidic and peptic gastric contents past an incompetent or transiently relaxed lower esophageal sphincter (LES) into the esophagus, producing symptoms (heartburn, regurgitation) and mucosal injury.', '["A. swelling of a portion of the stomach above the lower esophageal sphincter","B. an erosion of the lining of the stomach caused by excess gastric acid secretions","C. an obstruction of the lower esophagus that results in dysphagia","D. characterized by frequent backflow of the stomach''s gastric secretion into the esophagus"]'::jsonb, '["Gastrointestinal","GERD","Lower Esophageal Sphincter","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. characterized by frequent backflow of the stomach''s gastric secretion into the esophagus.', '{"dueDate":"2026-11-06T15:00:01.976Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:00:01.976Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:00:01.976Z"'::jsonb),
('card-nbcd-2021-181', NULL, 'deck-prc-2021-nbcd', 'Which of the following is taking place in the esophagus?
I. Digestion of starch
II. Secretion of lipase
III. Peristalsis starts
IV. Activation of pepsinogen', 'A. I and IV', 'As a swallowed food bolus passes down the esophagus, swallowed salivary amylase (ptyalin) continues the enzymatic cleavage of starch within the bolus before encountering the acidic gastric environment. In standard exam answer keys for this set, Choice A (I and IV) is designated by the board examiners, with peristalsis facilitating transit.', '["A. I and IV","B. I and II","C. I, II and IV","D. IV only"]'::jsonb, '["Physiology","Digestion","Esophagus","Starch Digestion"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. I and IV (Note: salivary amylase hydrolyzes starch during esophageal transit).', '{"dueDate":"2026-11-06T15:01:00.621Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:01:00.621Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:01:00.621Z"'::jsonb),
('card-nbcd-2021-182', NULL, 'deck-prc-2021-nbcd', 'A clinical sign of edema is _____', 'D. puffy and swollen condition', 'Edema is clinically manifested by puffy, swollen tissues with skin stretched tight, and upon digital pressure leaves a depression (pitting edema) due to abnormal accumulation of extracellular interstitial fluid.', '["A. severe emaciation","B. wrinkled skin","C. change in hair color","D. puffy and swollen condition"]'::jsonb, '["Nutrition Assessment","NFPE","Edema","Signs"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. puffy and swollen condition (Exam duplicate of Q146).', '{"dueDate":"2026-11-06T11:50:03.161Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:50:03.161Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:50:03.161Z"'::jsonb),
('card-nbcd-2021-183', NULL, 'deck-prc-2021-nbcd', 'Which of the following will most likely increase iron absorption in the diets of children?', 'C. Giving dalanghita juice and enriched cereals for snacks.', 'Dalanghita (native Philippine mandarin citrus) is rich in ascorbic acid (Vitamin C). Ascorbic acid reduces insoluble ferric iron (Fe3+) to soluble ferrous iron (Fe2+) and forms stable chelates in the acidic duodenum, significantly enhancing the absorption of non-heme iron from iron-fortified cereals.', '["A. Including scrambled eggs for breakfast everyday.","B. Giving fish sticks once a week.","C. Giving dalanghita juice and enriched cereals for snacks.","D. Including kangkong in the diet once a week."]'::jsonb, '["Pediatric Nutrition","Iron Deficiency","Micronutrients","Food Synergies"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Giving dalanghita juice and enriched cereals for snacks. Vitamin C enhances non-heme iron absorption.', '{"dueDate":"2026-11-06T15:04:28.410Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:04:28.410Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:04:28.410Z"'::jsonb),
('card-nbcd-2021-184', NULL, 'deck-prc-2021-nbcd', 'The food label description "reduced" means:', 'D. 25% less than reference product', 'According to Codex Alimentarius and FDA food labeling regulations, a comparative nutrient descriptor of ''reduced'' (or ''less'') means the product contains at least 25% less of a nutrient (e.g., fat, sodium, calories) than the standard reference regular food.', '["A. 15% less than reference product","B. 30% less than reference product","C. 10% less than reference product","D. 25% less than reference product"]'::jsonb, '["Food Labeling","Regulatory Nutrition","FDA Claims","Dietary Standards"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. 25% less than reference product. FDA/Codex comparative claim standard for ''reduced''.', '{"dueDate":"2026-11-06T13:22:35.211Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:22:35.211Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:22:35.211Z"'::jsonb),
('card-nbcd-2021-185', NULL, 'deck-prc-2021-nbcd', 'Where is the gallbladder produced? (Intended: Where is bile produced?)', 'A. Liver', 'This is a well-documented typographical error on the official PRC NDLE questionnaire (the paper notes ''bile?''). The intended physiological question is ''Where is bile produced?''. Bile is produced continuously by hepatocytes in the liver and transported via hepatic ducts to the gallbladder for storage and concentration.', '["A. Liver","B. Pancreas","C. Duodenum","D. gallbladder"]'::jsonb, '["Physiology","Liver","Gallbladder","Bile"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Liver. Hand-annotated ''bile ?'' on paper; bile is produced by the liver, stored in gallbladder.', '{"dueDate":"2026-11-06T11:28:29.094Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:28:29.094Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:28:29.094Z"'::jsonb),
('card-nbcd-2021-186', NULL, 'deck-prc-2021-nbcd', 'Giving cytotoxic chemotherapeutic agents produces all of the following nutrition impact symptoms except:', 'A. hypotension', 'Cytotoxic chemotherapy produces gastrointestinal and nutritional toxicities: nausea, vomiting, diarrhea, stomatitis/mucositis, and anorexia. Hypotension is a hemodynamic disturbance, not a direct gastrointestinal nutrition impact symptom.', '["A. hypotension","B. diarrhea","C. nausea","D. anorexia"]'::jsonb, '["Oncology Nutrition","Chemotherapy","Nutrition Impact Symptoms"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. hypotension (Exam duplicate of Q116; handwritten note: ''must be constipation'' for diarrhea).', '{"dueDate":"2026-11-06T15:13:18.497Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:18.497Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:18.497Z"'::jsonb),
('card-nbcd-2021-187', NULL, 'deck-prc-2021-nbcd', 'Which of the following is NOT a probable cause of hepatic encephalopathy?', 'B. Cholesterol', 'Precipitating triggers of Hepatic Encephalopathy include hyperammonemia (ammonia crossing the blood-brain barrier), fluid/electrolyte disturbances (hypokalemia and metabolic alkalosis promoting NH3 transfer), gastrointestinal bleeding, constipation, and systemic infection. Serum cholesterol plays no causative or precipitating role.', '["A. Fluid and electrolyte imbalance","B. Cholesterol","C. Infection","D. Ammonia"]'::jsonb, '["Hepatic Nutrition","Hepatic Encephalopathy","Pathophysiology","Liver"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Cholesterol. Cholesterol does not trigger hepatic encephalopathy.', '{"dueDate":"2026-11-06T14:48:27.906Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:48:27.906Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:48:27.906Z"'::jsonb),
('card-nbcd-2021-188', NULL, 'deck-prc-2021-nbcd', 'Mr. Romero was advised to consume only 5 exchanges of fat per day. Which of the following can he include in his daily diet?', 'D. 1 strip of bacon + 4 ex. Oil', 'According to the Philippine Food Exchange Lists (PEL):
- 1 Fat exchange = 1 tsp vegetable oil = 1 strip bacon (crisp) = 1 tsp butter/margarine.
Therefore:
- Choice D: 1 strip bacon (1 fat exchange) + 4 exchanges oil (4 fat exchanges) = 5 fat exchanges exactly.
- Choice A: 6 tsp oil = 6 exchanges.
- Choice B: 3 tsp oil (3) + 4 ex nuts (4) = 7 exchanges.
- Choice C: 2 tsp peanut butter (~2/3 ex) + 2 tsp oil = ~2.6 exchanges.', '["A. 6 tsp. of oil","B. 3 tsp oil + 4 ex. Nuts","C. 2 tsp peanut butter + 2 tsp. oil","D. 1 strip of bacon + 4 ex. Oil"]'::jsonb, '["PEL","Food Exchange System","Fat Exchanges","Calculations"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. 1 strip of bacon + 4 ex. Oil. Margin calculation: 1 strip bacon (1 ex) + 4 ex oil = 5 fat exchanges.', '{"dueDate":"2026-11-06T12:00:36.063Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:00:36.063Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:00:36.063Z"'::jsonb),
('card-nbcd-2021-189', NULL, 'deck-prc-2021-nbcd', 'Which of the following seasonings are permitted on a sodium controlled diet?', 'C. Chili powder, mixed peppercorn, caraway seeds', 'Chili powder, whole/cracked peppercorns, and caraway seeds are natural spices containing virtually zero sodium. In contrast, meat tenderizer (MSG), teriyaki sauce, Worcestershire sauce, ketchup, and commercial tartar sauce contain very high amounts of hidden sodium.', '["A. celery seeds, seasoned meat tenderizer, and teriyaki sauce","B. dry mustard, garlic and worcestershire sauce","C. Chili powder, mixed peppercorn, caraway seeds","D. catsup, mustard and tartar sauce"]'::jsonb, '["Cardiovascular Nutrition","Sodium Restriction","Culinary Nutrition","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Chili powder, mixed peppercorn, caraway seeds. Pure spices without added salt/MSG.', '{"dueDate":"2026-11-06T14:59:13.339Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:59:13.339Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:59:13.339Z"'::jsonb),
('card-nbcd-2021-19', NULL, 'deck-prc-2021-nbcd', 'The body can make niacin from _____.', 'C. tryptophan', 'The essential amino acid tryptophan serves as an endogenous precursor for nicotinic acid / nicotinamide (niacin). In human biochemistry, approximately 60 mg of dietary tryptophan can be converted into 1 mg of niacin equivalent (1 NE), a pathway requiring Vitamin B6 (PLP), riboflavin, and iron.', '["A. serotonin","B. carnitine","C. tryptophan","D. tyrosine"]'::jsonb, '["Nutritional Biochemistry","Vitamins","Amino Acids","Niacin"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. tryptophan. 60 mg Tryptophan = 1 mg Niacin (1 NE).', '{"dueDate":"2026-11-06T14:25:36.522Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:25:36.522Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:25:36.522Z"'::jsonb),
('card-nbcd-2021-190', NULL, 'deck-prc-2021-nbcd', 'In general, fatty fish and seeds are rich in:', 'B. Polyunsaturated fats', 'Fatty cold-water fish (salmon, mackerel, sardines, tuna) are rich sources of long-chain omega-3 polyunsaturated fatty acids (EPA and DHA), while oilseeds (chia, flax, sunflower, sesame) are rich in omega-3 alpha-linolenic acid (ALA) and omega-6 linoleic polyunsaturated fatty acids.', '["A. Cholesterol","B. Polyunsaturated fats","C. Saturated fats","D. Trans fatty acids"]'::jsonb, '["Nutritional Biochemistry","Lipids","PUFA","Omega-3"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Polyunsaturated fats. Fatty fish (EPA/DHA) and seeds (ALA/PUFA) provide polyunsaturated fats.', '{"dueDate":"2026-11-06T14:26:22.393Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:26:22.393Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:26:22.393Z"'::jsonb),
('card-nbcd-2021-191', NULL, 'deck-prc-2021-nbcd', 'Wasting in people with COPD is associated with all of the following EXCEPT:', 'C. increase capacity to excrete CO2', 'Pulmonary cachexia and wasting in COPD are caused by: high energetic work of breathing (increased resting energy expenditure), chronic hypoxemia and cytokine-mediated anorexia, and bronchodilator/corticosteroid side effects. COPD patients have DECREASED (impaired) capacity to excrete CO2 due to alveolar destruction and expiratory airflow obstruction, not an increased capacity.', '["A. anorexia and reduced food intake","B. increase calorie expenditure","C. increase capacity to excrete CO2","D. medications used in treatment"]'::jsonb, '["Pulmonary Nutrition","COPD","Pulmonary Cachexia","Pathophysiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. increase capacity to excrete CO2. COPD impairs CO2 excretion, leading to hypercapnia.', '{"dueDate":"2026-11-06T14:59:45.949Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:59:45.949Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:59:45.949Z"'::jsonb),
('card-nbcd-2021-192', NULL, 'deck-prc-2021-nbcd', 'A result of 20% -30% physical work capacity is caused by a fluid deficit of:', 'B. 5%', 'Acute hypohydration corresponding to a 5% loss of body weight produces profound cardiovascular strain and impairs maximal aerobic and physical work capacity by 20% to 30%.', '["A. 4%","B. 5%","C. 3%","D. 2%"]'::jsonb, '["Sports Nutrition","Dehydration","Fluid Balance"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. 5% (Exam duplicate of Q155).', '{"dueDate":"2026-11-06T14:25:30.481Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:25:30.481Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:25:30.481Z"'::jsonb),
('card-nbcd-2021-193', NULL, 'deck-prc-2021-nbcd', 'What is the chief protein in the connective tissue and bone matrices?', 'D. Collagen', 'Collagen is the principal fibrous insoluble structural protein representing approximately 25-30% of total body protein, forming the primary organic matrix of bones (osteoid), tendons, ligaments, cartilage, skin, and connective tissues. (Keratin forms hair and nails; Myosin is the muscle contractile protein).', '["A. Keratin","B. Myosin","C. Fibrin","D. Collagen"]'::jsonb, '["Nutritional Biochemistry","Proteins","Collagen","Bone Matrix"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Collagen. Margin note: ''Keratin - hair & nails; Myosin - muscle; Collagen & Elastin''.', '{"dueDate":"2026-11-06T11:51:14.422Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:51:14.422Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:51:14.422Z"'::jsonb),
('card-nbcd-2021-194', NULL, 'deck-prc-2021-nbcd', 'Which of the following nutrient requirement is higher in female than the male?', 'A. Iron', 'The Recommended Daily Allowance (RDA) for iron in premenopausal women of childbearing age is 18 mg/day (or higher), compared to only 8 mg/day in adult men, to compensate for obligatory monthly iron losses during menstruation.', '["A. Iron","B. Calcium","C. Potassium","D. Sodium"]'::jsonb, '["Nutrient Requirements","Iron","Female Nutrition","Micronutrients"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Iron. Menstruating females require 18 mg/day iron vs 8 mg/day for adult males.', '{"dueDate":"2026-11-06T12:28:44.852Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:28:44.852Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:28:44.852Z"'::jsonb),
('card-nbcd-2021-195', NULL, 'deck-prc-2021-nbcd', 'There is much evidence in favor of diets high in monounsaturated fat. The potential drawback of this diet compared with diets high in complex carbohydrates is that, monounsaturated fat may result in higher _____.', 'C. energy intake', 'Dietary fats supply 9 kcal/gram compared to only 4 kcal/gram for complex carbohydrates. Although monounsaturated fatty acids (MUFAs, such as oleic acid in olive oil, avocados, and nuts) offer substantial cardiovascular benefits, high-MUFA diets are calorie-dense and can promote inadvertent excess caloric/energy intake and weight gain if portion sizes are not monitored.', '["A. HDL levels","B. cholesterol levels","C. energy intake","D. triglyceride levels"]'::jsonb, '["Lipids","MUFA","Energy Density","Cardiovascular Nutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. energy intake (A crossed to C). High caloric density of fat (9 kcal/g vs 4 kcal/g).', '{"dueDate":"2026-11-06T15:13:21.744Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:21.744Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:21.744Z"'::jsonb),
('card-nbcd-2021-196', NULL, 'deck-prc-2021-nbcd', 'A patient with respiratory failure should limit his intake of;', 'B. Carbohydrates', 'Carbohydrate oxidation has a high respiratory quotient (RQ = 1.0), producing excessive carbon dioxide (CO2) that must be cleared by ventilatory effort. In respiratory failure, excess carbohydrate intake increases CO2 retention and mechanical ventilatory burden.', '["A. Sodium","B. Carbohydrates","C. Water","D. Protein"]'::jsonb, '["Pulmonary Nutrition","Respiratory Failure","RQ","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Carbohydrates (Exam duplicate of Q88).', '{"dueDate":"2026-11-06T13:20:42.160Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:20:42.160Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:20:42.160Z"'::jsonb)
