INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-nbcd-2021-197', NULL, 'deck-prc-2021-nbcd', 'If alcohol is consumed by a person with diabetes, it should be computed as part of _____ exchange.', 'C. fat', 'In the diabetes meal planning and food exchange system, alcohol (which provides 7 kcal/g and is metabolized primarily by hepatic oxidation into acetate/acetyl-CoA similar to fatty acids) is calculated as part of the Fat exchange list (e.g., 1 standard alcoholic drink = 2 Fat exchanges = ~90–100 kcal) so that essential carbohydrate exchanges are not omitted, which could precipitate hypoglycemia.', '["A. Carbohydrate","B. sugar","C. fat","D. protein"]'::jsonb, '["Diabetes Mellitus","Food Exchange System","Alcohol","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. fat. In diabetic exchange systems, 1 alcoholic drink is counted as 2 fat exchanges.', '{"dueDate":"2026-11-06T14:21:44.934Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:21:44.934Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:21:44.934Z"'::jsonb),
('card-nbcd-2021-198', NULL, 'deck-prc-2021-nbcd', 'Which type of fiber binds bile and therefore reduces one''s risk of atherosclerosis', 'B. soluble fiber', 'Soluble, gel-forming dietary fibers (pectin, gums, mucilages, beta-glucan) bind bile acids in the lumen of the small intestine and excrete them in the feces, forcing the liver to deplete hepatic cholesterol to synthesize new bile acids, thereby lowering atherogenic serum LDL-cholesterol.', '["A. dietary fiber","B. soluble fiber","C. insoluble fiber","D. total fiber"]'::jsonb, '["Fiber","Cardiovascular Nutrition","Cholesterol","Bile Acids"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. soluble fiber (Exam duplicate of Q99).', '{"dueDate":"2026-11-06T13:17:07.752Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:17:07.752Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:17:07.752Z"'::jsonb),
('card-nbcd-2021-199', NULL, 'deck-prc-2021-nbcd', 'A trace mineral which helps maintain glucose homeostasis.', 'B. Chromium', 'Trivalent Chromium (Cr3+) is an essential trace mineral that enhances the physiological action of insulin by binding to the low-molecular-weight chromium-binding substance (chromodulin), amplifying insulin receptor tyrosine kinase signaling to maintain normal glucose homeostasis.', '["A. Zinc","B. Chromium","C. Selenium","D. Manganese"]'::jsonb, '["Nutritional Biochemistry","Chromium","Trace Minerals","Glucose Homeostasis"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Chromium. Chromium potentiates insulin activity via chromodulin/GTF.', '{"dueDate":"2026-11-06T15:00:47.647Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:00:47.647Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:00:47.647Z"'::jsonb),
('card-nbcd-2021-2', NULL, 'deck-prc-2021-nbcd', 'Characteristics of objectives must be:
I. Specific and patient centered
II. Time bound
III. Realistic
IV. Measurable', 'B. I, II, III and IV', 'In Medical Nutrition Therapy and nutrition counseling, goal-setting follows the SMART framework: Specific, Measurable, Attainable/Realistic, Relevant/Patient-centered, and Time-bound. Thus, all Roman numerals I, II, III, and IV are essential characteristics of sound clinical objectives.', '["A. I, III and IV","B. I, II, III and IV","C. II and IV","D. I, II and III"]'::jsonb, '["Nutrition Care Process","Nutrition Counseling","Goal Setting"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B (I, II, III and IV). SMART criteria in clinical nutrition care plans.', '{"dueDate":"2026-11-06T11:57:49.437Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:57:49.437Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:57:49.437Z"'::jsonb),
('card-nbcd-2021-20', NULL, 'deck-prc-2021-nbcd', 'Sucrase, maltase and lactase are secreted by the _____.', 'D. intestinal mucosa', 'Disaccharidases—sucrase, maltase, and lactase—are brush-border enzymes embedded in the microvillar membrane of enterocytes in the small intestinal mucosa, where they hydrolyze disaccharides into monosaccharides for absorption.', '["A. gastric mucosa","B. pancreas","C. salivary glands","D. intestinal mucosa"]'::jsonb, '["Nutritional Biochemistry","Gastrointestinal","Enzymes","Carbohydrates"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. intestinal mucosa. Arrow drawn from gastric mucosa to intestinal mucosa.', '{"dueDate":"2026-11-06T13:23:23.253Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:23:23.253Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:23:23.253Z"'::jsonb),
('card-nbcd-2021-200', NULL, 'deck-prc-2021-nbcd', 'The order of the three segments of the small intestines are _____.', 'B. duodenum, jejunum and ileum', 'From the pylorus of the stomach to the ileocecal valve of the large intestine, the anatomical sequence of the three small intestinal segments is: duodenum -> jejunum -> ileum.', '["A. ileum, duodenum, and jejunum","B. duodenum, jejunum and ileum","C. duodenum, ileum and jejunum","D. jejunum, duodenum and ileum"]'::jsonb, '["Anatomy","Gastrointestinal","Small Intestine"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. duodenum, jejunum and ileum. Anatomical sequence of the small intestine.', '{"dueDate":"2026-11-06T14:38:13.652Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:38:13.652Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:38:13.652Z"'::jsonb),
('card-nbcd-2021-21', NULL, 'deck-prc-2021-nbcd', 'Absorption is the same as _____.', 'C. assimilation', 'Assimilation refers to the uptake and absorption of digested nutrient molecules across the intestinal mucosal barrier into the bloodstream or lymph, followed by their incorporation into living body cells and tissues.', '["A. ingestion","B. anabolism","C. assimilation","D. digest"]'::jsonb, '["Physiology","Digestion","Absorption"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. assimilation. Physiology definition: Absorption/assimilation is uptake into systemic circulation/cells.', '{"dueDate":"2026-11-06T14:39:41.278Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:39:41.278Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:39:41.278Z"'::jsonb),
('card-nbcd-2021-22', NULL, 'deck-prc-2021-nbcd', 'Diet recommendations for the nephrotic syndrome includes _____.', 'B. sodium restrictions', 'Nephrotic syndrome is characterized by heavy proteinuria, profound hypoalbuminemia, hyperlipidemia, and severe edema. Sodium restriction (1 to 2 g/day, or 2 to 3 g salt) is essential to manage edema and hypertension. Dietary protein is maintained at normal levels (0.8–1.0 g/kg/day); high-protein intakes (>1.2 g/kg) are contraindicated because they accelerate glomerular hyperfiltration and worsen renal damage.', '["A. protein intakes that are less than the RENI","B. sodium restrictions","C. no diet restrictions","D. 1.5 - 2 gm/KBW allowance for protein"]'::jsonb, '["Renal Nutrition","Nephrotic Syndrome","Sodium","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. sodium restrictions. Nephrotic syndrome: Normal protein (0.8-1.0 g/kg) + Sodium restriction for edema.', '{"dueDate":"2026-11-06T11:49:38.495Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:49:38.495Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:49:38.495Z"'::jsonb),
('card-nbcd-2021-23', NULL, 'deck-prc-2021-nbcd', 'Anti-cancer properties of phytochemicals include the following, EXCEPT;', 'B. deactivation of detoxification system of the liver', 'Phytochemicals (such as isothiocyanates, sulforaphane, indoles, and polyphenols) exert anti-cancer effects by INDUCING and activating Phase II hepatic detoxification enzymes, scavenging reactive oxygen species (ROS), inhibiting tumor cell proliferation and angiogenesis, and inducing apoptosis. They do not deactivate hepatic detoxification systems.', '["A. inhibition of tumor growth","B. deactivation of detoxification system of the liver","C. blocking of the metabolic pathway that can lead to carcinogenesis","D. protection against cellular damage"]'::jsonb, '["Oncology Nutrition","Phytochemicals","Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Phytochemicals induce/activate detoxification enzymes, not deactivate them.', '{"dueDate":"2026-11-06T14:49:20.159Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:49:20.159Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:49:20.159Z"'::jsonb),
('card-nbcd-2021-24', NULL, 'deck-prc-2021-nbcd', 'The diet principle that provides all the essential nutrients in sufficient amount to support health is _____.', 'A. adequacy', 'Dietary adequacy is the foundational diet-planning principle ensuring that a diet supplies sufficient energy and all essential nutrients to meet the physiological requirements of healthy individuals.', '["A. adequacy","B. moderation","C. balance","D. variety"]'::jsonb, '["Diet Planning","Basic Nutrition","Principles"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. adequacy. Adequacy = providing sufficient essential nutrients and energy.', '{"dueDate":"2026-11-06T15:09:07.043Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:09:07.043Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:09:07.043Z"'::jsonb),
('card-nbcd-2021-25', NULL, 'deck-prc-2021-nbcd', 'There are lots of variants to vegetarianism. The very strict variant is vegan while the least strict is _____.', 'D. semi-vegetarian', 'A semi-vegetarian (flexitarian) diet is the least restrictive vegetarian variant because it focuses primarily on plant-based foods while occasionally incorporating poultry, fish, seafood, dairy, and eggs. Veganism strictly excludes all animal products and byproducts.', '["A. lacto-ovo","B. pesco","C. lacto","D. semi-vegetarian"]'::jsonb, '["Vegetarianism","Diet Patterns","Basic Nutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. semi-vegetarian. Vegan = most strict; Semi-vegetarian/flexitarian = least strict.', '{"dueDate":"2026-11-06T15:04:06.257Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:04:06.257Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:04:06.257Z"'::jsonb),
('card-nbcd-2021-26', NULL, 'deck-prc-2021-nbcd', 'Increasing motivation through reinforcement is:', 'C. Achieved by encouraging desirable behavior, while discouraging undesirable behavior', 'In operant conditioning and behavioral counseling, reinforcement is used systematically to strengthen and maintain target healthy behaviors (positive reinforcement) while withholding reinforcement or applying corrective boundaries to extinguish maladaptive lifestyle habits.', '["A. discourage by health professional","B. not effective","C. Achieved by encouraging desirable behavior, while discouraging undesirable behavior","D. only effective in producing short-term results"]'::jsonb, '["Nutrition Counseling","Behavior Modification","Psychology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Achieved by encouraging desirable behavior, while discouraging undesirable behavior.', '{"dueDate":"2026-11-06T11:47:19.289Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:47:19.289Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:47:19.289Z"'::jsonb),
('card-nbcd-2021-27', NULL, 'deck-prc-2021-nbcd', 'Dietary fibers are useful in preventing hypercholesterolemia because they:', 'A. bind cholesterol containing bile acids which are eventually excreted', 'Soluble viscous dietary fibers (pectin, beta-glucan, psyllium, gums) bind bile acids in the small intestine, interrupting enterohepatic circulation and causing bile acids to be excreted in feces. The liver is consequently forced to synthesize new bile acids from endogenous hepatic cholesterol pools, upregulating LDL receptors and lowering circulating serum cholesterol.', '["A. bind cholesterol containing bile acids which are eventually excreted","B. produce HDL cholesterol","C. are carriers of omega-3 fatty acids","D. are anti-oxidants"]'::jsonb, '["Fiber","Lipids","Cholesterol","Cardiovascular Nutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. bind cholesterol containing bile acids which are eventually excreted.', '{"dueDate":"2026-11-06T13:01:44.522Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:01:44.522Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:01:44.522Z"'::jsonb),
('card-nbcd-2021-28', NULL, 'deck-prc-2021-nbcd', 'Which of these fruits is a good source of Vitamin A?', 'B. Papaya', 'Papaya is an excellent tropical fruit source of provitamin A carotenoids (notably beta-carotene and beta-cryptoxanthin), which are enzymatically cleaved into retinal and retinol in enterocytes.', '["A. Chico","B. Papaya","C. Pineapple","D. Melon"]'::jsonb, '["Vitamins","Vitamin A","Food Sources","Carotenoids"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: Papaya (Option B/C depending on labeling). Papaya is rich in beta-carotene.', '{"dueDate":"2026-11-06T15:11:35.996Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:11:35.996Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:11:35.996Z"'::jsonb),
('card-nbcd-2021-29', NULL, 'deck-prc-2021-nbcd', 'Which theory of counseling did you use in the following scenario: You were asked to counsel a single-parent of a two-year old due to excessive temper tantrums at meal-times. Determine which model theory for healthy eating behavior at meal-times and sharing parenting tips of this age group would be beneficial?', 'B. Social Learning Theory', 'Albert Bandura''s Social Learning Theory (Social Cognitive Theory) emphasizes that behaviors are acquired and modified through observational learning, modeling, reciprocal determinism, and social interactions. In pediatric feeding counseling, parental role-modeling and shared peer-group learning reinforce healthy mealtime behaviors.', '["A. Rewards Compensation Theory","B. Social Learning Theory","C. Stages of Change","D. Cognitive-behavioral Theory"]'::jsonb, '["Nutrition Counseling","Behavioral Theories","Pediatrics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Social Learning Theory. Bandura''s theory emphasizes modeling and observational learning.', '{"dueDate":"2026-11-06T15:02:15.786Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:02:15.786Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:02:15.786Z"'::jsonb),
('card-nbcd-2021-3', NULL, 'deck-prc-2021-nbcd', 'The serving portion of each food on any given list provide the same amount of:', 'A. energy', 'In the Food Exchange Lists (Exchange System / PEL), foods are grouped into lists based on similarity in macronutrient composition (carbohydrates, proteins, fats). Consequently, any serving portion within a given exchange list yields approximately the same amount of energy (calories).', '["A. energy","B. minerals","C. vitamins","D. satiety"]'::jsonb, '["Food Exchange System","Meal Planning","PEL"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. energy. Margin: Exchange system groups foods by equivalent macronutrients and caloric energy.', '{"dueDate":"2026-11-06T15:04:54.314Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:04:54.314Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:04:54.314Z"'::jsonb),
('card-nbcd-2021-30', NULL, 'deck-prc-2021-nbcd', 'Mouth sores in people with HIV infection are most frequently due to:', 'B. oral infections', 'Due to impaired cell-mediated immunity (CD4+ T-lymphocyte depletion), patients with HIV/AIDS frequently suffer from opportunistic oral infections, most commonly oral candidiasis (thrush, Candida albicans), herpes simplex virus (HSV) stomatitis, oral hairy leukoplakia, and aphthous ulcers.', '["A. malabsorption","B. oral infections","C. food","D. dehydration"]'::jsonb, '["HIV/AIDS","Infectious Disease","MNT","Oral Health"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. oral infections. Opportunistic candidiasis and HSV stomatitis cause HIV mouth sores.', '{"dueDate":"2026-11-06T15:05:27.120Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:05:27.120Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:05:27.120Z"'::jsonb),
('card-nbcd-2021-31', NULL, 'deck-prc-2021-nbcd', 'An obese child client is on your Weight Loss Program. After the initial interview, you found out that she doesn''t eat vegetables and fruits, is fond of processed foods, loves cakes and ice cream. Establishing rapport is the first thing you do. Mention the award/reward will be given to encourage the child to cooperate. Which theory of counseling is used in this kind of scenario?', 'D. Rewards Compensation Theory', 'Using contingency management, positive incentives, and reward systems to motivate and reinforce dietary compliance and lifestyle modifications in children falls under rewards compensation / reinforcement theory.', '["A. Social Learning Theory","B. Cognitive-behavior Theory (CBT)","C. Stages of Change","D. Rewards Compensation Theory"]'::jsonb, '["Pediatric Nutrition","Obesity","Counseling Theories"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. Rewards Compensation Theory. Operant conditioning utilizing external rewards for compliance.', '{"dueDate":"2026-11-06T14:59:35.286Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:59:35.286Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:59:35.286Z"'::jsonb),
('card-nbcd-2021-32', NULL, 'deck-prc-2021-nbcd', 'Essential fatty acids includes:', 'D. Linoleic and linolenic acid', 'Linoleic acid (18:2 n-6) and alpha-linolenic acid (18:3 n-3) are the two true essential fatty acids in human nutrition because mammalian cells lack delta-12 and delta-15 desaturase enzymes required to introduce double bonds beyond carbon 9 from the carboxyl terminal.', '["A. Stearic and oleic acid","B. Oleic and Linoleic acid","C. Palmitic and linolenic","D. Linoleic and linolenic acid"]'::jsonb, '["Nutritional Biochemistry","Fatty Acids","Lipids","EFA"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Linoleic and linolenic acid. Essential fatty acids: Omega-6 (Linoleic) and Omega-3 (Alpha-linolenic).', '{"dueDate":"2026-11-06T12:52:44.888Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:52:44.888Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:52:44.888Z"'::jsonb),
('card-nbcd-2021-33', NULL, 'deck-prc-2021-nbcd', 'Choose an accurate non-invasive test seen in dehydrated patients.', 'D. Dark colored urine', 'Urine color assessment (using validated urine color charts) is an immediate, accurate, bedside non-invasive indicator of hydration status. Dark, concentrated amber urine reflects elevated urine specific gravity and osmolality caused by maximal renal water reabsorption under ADH stimulation in dehydration.', '["A. Decreased electrolytes","B. Pinch Test","C. Elevated BUN and Creatinine","D. Dark colored urine"]'::jsonb, '["Nutrition Assessment","Dehydration","Fluid Balance","NFPE"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Dark colored urine. Non-invasive clinical physical sign of volume depletion.', '{"dueDate":"2026-11-06T14:48:23.137Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:48:23.137Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:48:23.137Z"'::jsonb),
('card-nbcd-2021-34', NULL, 'deck-prc-2021-nbcd', 'JM is a 10 years old boy, diagnosed with Nephrotic Syndrome. His laboratory test results show that his sodium level is low, and his potassium level is borderline. What is the primary manifestation of Nephrotic Syndrome?', 'D. Proteinuria', 'The primary and initiating pathophysiological hallmark of Nephrotic Syndrome is heavy glomerular proteinuria (>3.5 g/24 hr in adults or >40 mg/m2/hr in children) caused by loss of glomerular podocyte charge and size selectivity. This massive protein leak triggers hypoalbuminemia, decreased oncotic pressure, and third-spacing edema.', '["A. Hypoalbuminemia","B. Hyperlipidemia","C. Edema","D. Proteinuria"]'::jsonb, '["Renal Nutrition","Nephrotic Syndrome","Pediatrics","Pathophysiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. Proteinuria (and C. Edema highlighted). Primary initiating lesion is proteinuria.', '{"dueDate":"2026-11-06T15:10:15.294Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:10:15.294Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:10:15.294Z"'::jsonb),
('card-nbcd-2021-35', NULL, 'deck-prc-2021-nbcd', 'Vitamins whose requirements are dependent on a person''s energy intake.', 'C. Thiamin and Riboflavin', 'Thiamin (B1), Riboflavin (B2), and Niacin (B3) serve as indispensable coenzymes in cellular energy metabolism (TPP, FMN/FAD, and NAD/NADP in glycolysis, Krebs cycle, and electron transport chain). Their recommended daily allowances are directly calculated per 1,000 kcal of total energy intake.', '["A. Thiamin and Folate","B. Thiamin and Biotin","C. Thiamin and Riboflavin","D. Thiamin and Niacin"]'::jsonb, '["Nutritional Biochemistry","B-Vitamins","Energy Metabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Thiamin and Riboflavin. B1, B2, and B3 coenzymes scale directly with total caloric expenditure.', '{"dueDate":"2026-11-06T13:14:07.259Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:14:07.259Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:14:07.259Z"'::jsonb),
('card-nbcd-2021-36', NULL, 'deck-prc-2021-nbcd', 'Which of the following is NOT a component of bile?', 'B. Sodium bicarbonate', 'Hepatic bile consists primarily of bile salts (conjugated bile acids), phospholipids (principally phosphatidylcholine/lecithin), cholesterol, and bile pigments (bilirubin glucuronide). Sodium bicarbonate is predominantly secreted by pancreatic ductal cells in response to secretin to neutralize acidic gastric chyme in the duodenum, not a major constituent of gallbladder bile.', '["A. Bilirubin","B. Sodium bicarbonate","C. Lecithin","D. Cholesterol"]'::jsonb, '["Gastrointestinal","Physiology","Bile","Digestion"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Sodium bicarbonate. Bile = bile acids, cholesterol, lecithin, bilirubin. Bicarbonate = pancreatic juice.', '{"dueDate":"2026-11-06T15:02:21.698Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:02:21.698Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:02:21.698Z"'::jsonb),
('card-nbcd-2021-37', NULL, 'deck-prc-2021-nbcd', 'Digestion and absorption are coordinated by the _____.', 'A. hormonal and nervous system', 'Gastrointestinal motility, secretomotor functions, and absorptive capacities are coordinated via neuroendocrine feedback mechanisms: the enteric and autonomic nervous systems (vagal parasympathetic and sympathetic innervation) and peptide gastrointestinal hormones (gastrin, secretin, cholecystokinin, GIP, GLP-1).', '["A. hormonal and nervous system","B. vascular and lymphatic system","C. pancreas and kidney","D. liver and gallbladder"]'::jsonb, '["Physiology","Gastrointestinal","Neuroendocrine","Digestion"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. hormonal and nervous system. Gut-brain axis and neuroendocrine regulation.', '{"dueDate":"2026-11-06T14:43:48.829Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:43:48.829Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:43:48.829Z"'::jsonb),
('card-nbcd-2021-38', NULL, 'deck-prc-2021-nbcd', 'What is function of the pyloric sphincter?', 'C. Regulates the flow of partially digested food into the small intestine', 'The pyloric sphincter is the smooth muscle band separating the gastric pylorus from the duodenal bulb that acts as a dynamic valve, regulating and metering the rate at which acidic, partially digested chyme empties into the duodenum.', '["A. Holds food in the stomach long enough for it to be liquified","B. Prevents the small intestines from backing up to the stomach","C. Regulates the flow of partially digested food into the small intestine","D. Holds food in the stomach long enough for it to be liquified"]'::jsonb, '["Physiology","Gastrointestinal","Stomach","Pylorus"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Regulates the flow of partially digested food into the small intestine.', '{"dueDate":"2026-11-06T13:04:29.145Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:04:29.145Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:04:29.145Z"'::jsonb),
('card-nbcd-2021-39', NULL, 'deck-prc-2021-nbcd', 'Diverticulosis is a condition associated with:', 'C. low-fiber diet', 'Chronic low-fiber intake results in small-caliber, hard stools that require high segmental intracolonic pressures to propel during peristalsis. Over decades, this excessive pressure herniates colonic mucosa through weakened areas of the muscular circular layer, forming diverticula.', '["A. inadequate exercise","B. intestinal surgery","C. low-fiber diet","D. a high-fiber diet"]'::jsonb, '["Gastrointestinal","Diverticulosis","Fiber","Etiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. low-fiber diet. Etiology of diverticulosis: chronic low-fiber intake causing high intracolonic pressure.', '{"dueDate":"2026-11-06T15:13:48.062Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:48.062Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:48.062Z"'::jsonb),
('card-nbcd-2021-4', NULL, 'deck-prc-2021-nbcd', 'The situation following or resulting from a behavior is called the:', 'A. Consequences', 'In behavioral modification and cognitive-behavioral theory, the ABC framework consists of Antecedents (stimuli, triggers, or cues occurring prior to behavior), Behavior (the action itself), and Consequences (the events, responses, or outcomes that follow and reinforce or extinguish the behavior).', '["A. Consequences","B. Behavior","C. Activity","D. Antecedent"]'::jsonb, '["Behavior Modification","Nutrition Counseling","Psychology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Consequences. ABC Model: Antecedent -> Behavior -> Consequence.', '{"dueDate":"2026-11-06T12:59:51.398Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:59:51.398Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:59:51.398Z"'::jsonb),
('card-nbcd-2021-40', NULL, 'deck-prc-2021-nbcd', 'What is the energy producer of the cell?', 'C. Mitochondria', 'Mitochondria are the powerhouses of eukaryotic cells, housing the citric acid cycle (TCA cycle), fatty acid beta-oxidation, and the electron transport chain coupled with ATP synthase for oxidative phosphorylation.', '["A. Nucleus","B. Ribosomes","C. Mitochondria","D. Cytoplasm"]'::jsonb, '["Cell Biology","Nutritional Biochemistry","Mitochondria","ATP"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Mitochondria. Site of oxidative phosphorylation and cellular ATP production.', '{"dueDate":"2026-11-06T15:01:26.644Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:01:26.644Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:01:26.644Z"'::jsonb),
('card-nbcd-2021-41', NULL, 'deck-prc-2021-nbcd', 'What is a primary concern a clinical dietitian has when managing oncology patient?', 'C. Malnutrition', 'Cancer-related malnutrition and cancer anorexia-cachexia syndrome affect up to 80% of oncology patients and directly impair tolerance to chemotherapy and radiation, increase postoperative complications, degrade functional performance, and contribute directly to mortality.', '["A. Mortality","B. Morbidity","C. Malnutrition","D. Longevity"]'::jsonb, '["Oncology Nutrition","Malnutrition","Cancer Cachexia","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Malnutrition. Primary MNT target in oncology: preventing and managing cancer-induced malnutrition/cachexia.', '{"dueDate":"2026-11-06T13:13:52.689Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:13:52.689Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:13:52.689Z"'::jsonb),
('card-nbcd-2021-42', NULL, 'deck-prc-2021-nbcd', 'The fluid mixed with the patients blood during dialysis is called:', 'D. dialyzate', 'Dialysate is the sterile aqueous fluid containing balanced electrolytes (sodium, bicarbonate, calcium, potassium) and glucose that flows through the dialyzer counter-current to blood to facilitate solute diffusion and fluid ultrafiltration. (The dialyzer is the artificial kidney cartridge).', '["A. urine","B. serum","C. dialyzer","D. dialyzate"]'::jsonb, '["Renal Nutrition","Dialysis","MNT","Clinical Terms"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. dialyzate. Dialyzer = artificial filter machine; Dialysate = fluid solution.', '{"dueDate":"2026-11-06T11:49:11.742Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:49:11.742Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:49:11.742Z"'::jsonb),
('card-nbcd-2021-43', NULL, 'deck-prc-2021-nbcd', 'Which of the following symptom is Respiratory?', 'C. wheezing, sneezing, congestion', 'Wheezing (bronchospasm), sneezing (rhinitis), and airway congestion are classical respiratory signs and symptoms resulting from mucosal inflammation, allergic hypersensitivity, or respiratory disease.', '["A. headache, irritability, arrythmia","B. swollen throat, gas, malabsorption","C. wheezing, sneezing, congestion","D. rash, itchiness"]'::jsonb, '["Clinical Assessment","Respiratory","Allergy","Symptomatology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. wheezing, sneezing, congestion. Classic respiratory signs in allergy assessment.', '{"dueDate":"2026-11-06T11:52:19.647Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:52:19.647Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:52:19.647Z"'::jsonb),
('card-nbcd-2021-44', NULL, 'deck-prc-2021-nbcd', 'Which of these should be monitored regularly among patients on dialysis?
I. Weight
II. Blood pressure
III. Urine output
IV. Body fat', 'C. I, II and III', 'Dialysis patients must monitor dry weight daily (to track interdialytic fluid weight gain), blood pressure (to identify hypertension from fluid overload or hypotension from rapid ultrafiltration), and residual urine output (to adjust fluid allowances). Routine body fat percentage is not measured on a frequent/daily basis.', '["A. I and IV","B. II and III","C. I, II and III","D. I, II, III and IV"]'::jsonb, '["Renal Nutrition","Dialysis","Fluid Balance","Monitoring"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C (I, II and III). Key monitoring parameters in hemodialysis and peritoneal dialysis.', '{"dueDate":"2026-11-06T12:47:31.482Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:47:31.482Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:47:31.482Z"'::jsonb),
('card-nbcd-2021-45', NULL, 'deck-prc-2021-nbcd', 'The glycerol portion of fat is used by the liver for _____.', 'A. triglyceride synthesis', 'Glycerol released from lipolysis is phosphorylated by hepatic glycerol kinase to glycerol-3-phosphate, which serves as the direct carbohydrate backbone for triglyceride synthesis (re-esterification) or is oxidized to dihydroxyacetone phosphate (DHAP) for glycolysis or gluconeogenesis.', '["A. triglyceride synthesis","B. ketones","C. acetyl CoA","D. amino acid"]'::jsonb, '["Nutritional Biochemistry","Lipid Metabolism","Liver","Gluconeogenesis"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. triglyceride synthesis. Glycerol-3-phosphate is re-esterified into triglycerides in hepatocytes.', '{"dueDate":"2026-11-06T11:58:48.122Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:58:48.122Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:58:48.122Z"'::jsonb),
('card-nbcd-2021-46', NULL, 'deck-prc-2021-nbcd', 'All nutrients needed by the body follows this statement.', 'C. Are supplied by a variety of foods in many different combinations.', 'A central tenet of human nutrition is that no single natural food supplies all essential nutrients in optimal quantities; a diverse variety of foods from different food groups consumed in varied combinations is required to achieve complete nutritional adequacy.', '["A. Have a variety of functions and uses in the body.","B. Must follow specific food combinations.","C. Are supplied by a variety of foods in many different combinations.","D. It must be obtained through vitamin and mineral supplementation"]'::jsonb, '["Basic Nutrition","Dietary Principles","Nutritional Science"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Are supplied by a variety of foods in many different combinations.', '{"dueDate":"2026-11-06T14:18:30.764Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:18:30.764Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:18:30.764Z"'::jsonb),
('card-nbcd-2021-47', NULL, 'deck-prc-2021-nbcd', 'Two factors that contribute to the maintenance of basal metabolic rate are:', 'D. heartbeat and body temperature', 'Basal metabolic rate (BMR) represents the obligatory energetic cost of sustaining basic vegetative life at complete physical and emotional rest, which includes involuntary cardiac muscle contraction (heartbeat), respiratory work, brain cellular metabolism, and maintenance of core body temperature.', '["A. heartbeat and running","B. body temperature and walking","C. walking and running","D. heartbeat and body temperature"]'::jsonb, '["Energy Metabolism","BMR","Physiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. heartbeat and body temperature. Involuntary vegetative metabolic demands.', '{"dueDate":"2026-11-06T14:39:49.094Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:39:49.094Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:39:49.094Z"'::jsonb),
('card-nbcd-2021-48', NULL, 'deck-prc-2021-nbcd', 'The need for Vit. B1 increases in the following conditions, EXCEPT', 'C. Increase fat consumption', 'Thiamin pyrophosphate (TPP) is an essential coenzyme for enzymes of carbohydrate metabolism (pyruvate dehydrogenase, transketolase). Increased carbohydrate/calorie intake, pregnancy, and alcohol use elevate thiamin requirements. Conversely, fats have a ''thiamin-sparing effect'' because fatty acid beta-oxidation does not require TPP, so increased fat consumption does not increase thiamin needs.', '["A. During pregnancy and lactation","B. Increased alcohol consumption","C. Increase fat consumption","D. Increased calorie intake"]'::jsonb, '["Nutritional Biochemistry","Thiamin","Vitamins","Energy Metabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. Increase fat consumption. Fat metabolism spares thiamin; high carb intake increases B1 demand.', '{"dueDate":"2026-11-06T13:21:18.089Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:21:18.089Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:21:18.089Z"'::jsonb),
('card-nbcd-2021-49', NULL, 'deck-prc-2021-nbcd', 'Lily was diagnosed with hyperkalemia. Which of the following statements will you use to explain to Lily the bad affects of high serum potassium level?', 'C. This can cause cardiac arrest and may be fatal', 'Severe hyperkalemia (serum potassium > 6.0–6.5 mEq/L) causes partial depolarization of the cardiac muscle cell membrane resting potential, leading to peaked T waves, conduction blocks, ventricular fibrillation, and fatal diastolic cardiac arrest.', '["A. It will lead to arthritis","B. Antagonists action of calcium and causes bone demineralization","C. This can cause cardiac arrest and may be fatal","D. It will induce extreme thirst"]'::jsonb, '["Renal Nutrition","Electrolytes","Potassium","Pathophysiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. This can cause cardiac arrest and may be fatal. Critical electrolyte toxicity in clinical practice.', '{"dueDate":"2026-11-06T14:42:10.186Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:42:10.186Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:42:10.186Z"'::jsonb),
('card-nbcd-2021-5', NULL, 'deck-prc-2021-nbcd', 'Which strategy is safe for increasing the energy intake of people on fat-restricted diets?', 'D. provide additional fat in the form of MCT oil', 'Medium-chain triglycerides (MCTs, C6-C12) do not require micellar emulsification by bile salts or hydrolysis by pancreatic lipase. They are rapidly absorbed directly into enterocytes and transported via the portal venous circulation directly to the liver. This makes MCT oil safe and calorie-dense (8.3 kcal/g) for patients with severe fat malabsorption or pancreatitis on fat-restricted diets.', '["A. gradually add fat as tolerance permits","B. provide fat with enzymes replacements","C. increase high calorie foods","D. provide additional fat in the form of MCT oil"]'::jsonb, '["Fat Malabsorption","MNT","Lipids","Enteral Nutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. Provide additional fat in the form of MCT oil. MCT oil bypasses lymphatic chylomicron transport.', '{"dueDate":"2026-11-06T12:25:12.130Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:25:12.130Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:25:12.130Z"'::jsonb),
('card-nbcd-2021-50', NULL, 'deck-prc-2021-nbcd', 'Why is it important to regulate the release of chyme into the duodenum?', 'D. Duodenum is small and cannot accommodate too much chyme.', 'Controlled gastric emptying through the pyloric sphincter is essential because the duodenum has a limited intraluminal volume and buffering capacity. Rapid entry of hypertonic, acidic gastric chyme causes duodenal distension, fluid shifts, cramping, and vasomotor dumping syndrome.', '["A. Only small amounts of juice can be secreted to digest chyme.","B. Stomach needs to have chyme all the time.","C. Small intestine has limited mucous coating to protect from acids.","D. Duodenum is small and cannot accommodate too much chyme."]'::jsonb, '["Physiology","Gastrointestinal","Stomach","Duodenum"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. Duodenum is small and cannot accommodate too much chyme. (Option C also notes acid vulnerability).', '{"dueDate":"2026-11-06T15:11:26.483Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:11:26.483Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:11:26.483Z"'::jsonb),
('card-nbcd-2021-51', NULL, 'deck-prc-2021-nbcd', 'Organs that detoxifies alcohol. Other drugs and poisons, prepares waste products for excretion.', 'A. Liver', 'The liver is the principal metabolic and detoxifying organ of the body. Hepatocytes express alcohol dehydrogenase (ADH), aldehyde dehydrogenase (ALDH), and the microsomal ethanol oxidizing system (CYP2E1) to metabolize ethanol, as well as Phase I and Phase II cytochrome P450 enzyme complexes to neutralize xenobiotics, drugs, and poisons for biliary or urinary elimination.', '["A. Liver","B. Heart","C. Kidney","D. Lungs"]'::jsonb, '["Nutritional Biochemistry","Liver","Metabolism","Toxicology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Liver. Primary site of drug biotransformation and alcohol oxidation.', '{"dueDate":"2026-11-06T13:17:51.167Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:17:51.167Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:17:51.167Z"'::jsonb),
('card-nbcd-2021-52', NULL, 'deck-prc-2021-nbcd', 'What is the maximum amount of alcohol a man with diabetes can take per day?', 'A. 2 drinks', 'According to the American Diabetes Association (ADA) and clinical nutrition guidelines, if adult patients with diabetes choose to drink alcohol, intake should be limited to a maximum of 2 standard drinks per day for men and 1 standard drink per day for women, always consumed with food to prevent delayed nocturnal hypoglycemia.', '["A. 2 drinks","B. 1 drinks","C. 3 drinks","D. 4 drinks"]'::jsonb, '["Diabetes Mellitus","Alcohol","MNT","Dietary Guidelines"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. 2 drinks (exam paper had duplicate choices: A. 2 drinks, B. 1 drinks; D was marked 1 drink, corrected to A. 2 drinks for men).', '{"dueDate":"2026-11-06T12:42:39.210Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:42:39.210Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:42:39.210Z"'::jsonb),
('card-nbcd-2021-53', NULL, 'deck-prc-2021-nbcd', 'Vitamin E acts as a _____ of free radicals.', 'C. scavenger', 'Alpha-tocopherol (Vitamin E) is a lipid-soluble chain-breaking antioxidant that functions as a scavenger of free radicals (specifically peroxyl radicals), intercepting lipid peroxidation chain reactions in cellular membranes and circulating lipoproteins.', '["A. promoter","B. carrier","C. scavenger","D. synthesizer"]'::jsonb, '["Nutritional Biochemistry","Vitamin E","Antioxidants","Lipids"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. scavenger. Lipophilic antioxidant chain-breaking scavenger.', '{"dueDate":"2026-11-06T12:00:49.062Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:00:49.062Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:00:49.062Z"'::jsonb),
('card-nbcd-2021-54', NULL, 'deck-prc-2021-nbcd', 'Major organ where intermediary metabolism takes place.', 'C. Liver', 'The liver is the central clearinghouse and master organ of intermediary metabolism, carrying out glycogenesis, glycogenolysis, gluconeogenesis, lipogenesis, fatty acid oxidation, ketogenesis, transamination, deamination, and the urea cycle.', '["A. Lungs","B. Kidney","C. Liver","D. Pancreas"]'::jsonb, '["Nutritional Biochemistry","Liver","Intermediary Metabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Liver. Metabolic hub for carbohydrate, lipid, and protein intermediary pathways.', '{"dueDate":"2026-11-06T11:53:31.051Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:53:31.051Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:53:31.051Z"'::jsonb),
('card-nbcd-2021-55', NULL, 'deck-prc-2021-nbcd', 'You are counseling a person with Type 1 Diabetes who intends to do regular exercise. Which of the following advise should you EMPHASIZE?', 'Monitor if possible, blood glucose before, during and after exercise.', 'For individuals with Type 1 Diabetes engaging in physical activity, self-monitoring of blood glucose (SMBG) before, during, and after exercise is the most critical foundation. It provides the empirical data necessary to detect impending exercise-induced hypoglycemia or hyperglycemia, allowing precise carbohydrate supplementation and insulin dosage adjustments.', '["He must know the symptoms of hypoglycemia for precautionary measure.","Take additional carbohydrate as snack before exercise.","Adjust insulin dosage accordingly.","Monitor if possible, blood glucose before, during and after exercise."]'::jsonb, '["Diabetes Mellitus","Type 1 Diabetes","Exercise Nutrition","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. Monitor if possible, blood glucose before, during and after exercise.', '{"dueDate":"2026-11-06T15:05:15.895Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:05:15.895Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:05:15.895Z"'::jsonb),
('card-nbcd-2021-56', NULL, 'deck-prc-2021-nbcd', 'Diet therapy for people with delayed gastric emptying most often includes;', 'B. low-fiber, low fat foods', 'In gastroparesis (delayed gastric emptying), dietary fat is restricted because it stimulates cholecystokinin (CCK) secretion, which physiologically inhibits gastric motility. Dietary fiber (especially viscous/insoluble fibers) is restricted to avoid delayed emptying and reduce the risk of phytobezoar formation. Meals should also be small, frequent, and semi-liquid or puréed.', '["A. formulas provided by tube","B. low-fiber, low fat foods","C. very low residue foods","D. high fiber foods given in frequent small meals"]'::jsonb, '["Gastrointestinal","Gastroparesis","MNT","Diet Therapy"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. low-fiber, low fat foods. Gastroparesis MNT: Low fat + low fiber + frequent small meals.', '{"dueDate":"2026-11-06T11:58:31.893Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:58:31.893Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:58:31.893Z"'::jsonb),
('card-nbcd-2021-57', NULL, 'deck-prc-2021-nbcd', 'Which of these water-soluble vitamins will increase with energy intake?', 'C. Niacin', 'Niacin (along with thiamin and riboflavin) functions directly as an electron carrier (NAD+/NADH and NADP+/NADPH) across all fuel catabolic pathways. Because higher caloric intake demands greater flux through glycolysis, the citric acid cycle, and oxidative phosphorylation, niacin requirements scale directly with total caloric expenditure.', '["A. Folic acid","B. Ascorbic acid","C. Niacin","D. Pantothenic acid"]'::jsonb, '["Nutritional Biochemistry","Niacin","B-Vitamins","Energy Metabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Niacin. B1, B2, and B3 requirements correlate directly with energy intake.', '{"dueDate":"2026-11-06T13:18:08.754Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:18:08.754Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:18:08.754Z"'::jsonb),
('card-nbcd-2021-58', NULL, 'deck-prc-2021-nbcd', 'It is an examination and a fundamental component of nutrition assessment that will show signs of malnutrition, can test grip strength to assess physical function. Hands on training is required.', 'C. Nutrition Focused Physical Examination', 'The Nutrition Focused Physical Examination (NFPE) is a systematic head-to-toe clinical assessment conducted by registered nutritionist-dietitians to identify physical signs of malnutrition, subcutaneous fat loss, muscle mass wasting, fluid accumulation (edema/ascites), micronutrient deficiencies, and functional status via handgrip dynamometry.', '["A. Laboratory examination","B. Physical Exam","C. Nutrition Focused Physical Examination","D. Stress test"]'::jsonb, '["Nutrition Assessment","NFPE","Malnutrition","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Nutrition Focused Physical Examination (NFPE). Hands-on physical and functional assessment.', '{"dueDate":"2026-11-06T13:06:42.203Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:06:42.203Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:06:42.203Z"'::jsonb),
('card-nbcd-2021-59', NULL, 'deck-prc-2021-nbcd', 'A 10 year-old boy weighs 120 lbs, 5 ft tall, BMI = 23, placing him above the 95th percentile for weight-for-age, so he is _____.', 'C. overweight', 'According to pediatric growth charts, a child with BMI >= 95th percentile for age and sex is classified as obese (or overweight/obese in older terminology). Between the 85th and <95th percentile is overweight, and <5th percentile is underweight. In the PRC exam key, choice C (overweight) is designated.', '["A. of a short stature","B. underweight","C. overweight","D. of normal age"]'::jsonb, '["Pediatric Nutrition","Growth Charts","BMI","Obesity Assessment"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. overweight. BMI >= 95th percentile in pediatrics denotes obesity/overweight.', '{"dueDate":"2026-11-06T14:43:02.417Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:43:02.417Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:43:02.417Z"'::jsonb),
('card-nbcd-2021-6', NULL, 'deck-prc-2021-nbcd', 'Which is considered as fuel for the gut?', 'A. Glutamine', 'Glutamine is the principal, preferred oxidative fuel source for rapidly dividing enterocytes of the small intestine and colonocytes, as well as mucosal lymphocytes. It is critical for maintaining intestinal mucosal barrier integrity and preventing bacterial translocation during physiologic stress.', '["A. Glutamine","B. Arginine","C. Lysine","D. Histidine"]'::jsonb, '["Nutritional Biochemistry","Amino Acids","Gastrointestinal","Critical Care"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Glutamine. Margin: Fuel of enterocytes = Glutamine; Fuel of colonocytes = Short-chain fatty acids (butyrate).', '{"dueDate":"2026-11-06T14:30:41.983Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:30:41.983Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:30:41.983Z"'::jsonb),
('card-nbcd-2021-60', NULL, 'deck-prc-2021-nbcd', 'Which of the following medical nutritionals contains partially digested?', 'C. amino acids', 'Elemental (monomeric) and semi-elemental (oligomeric/peptide-based) enteral medical nutritional formulas contain predigested or partially digested macronutrients—specifically free amino acids or small peptides, simple carbohydrates, and minimal fats (MCTs)—designed for patients with compromised digestive or absorptive capacity.', '["A. modular","B. disease-specific","C. amino acids","D. polymeric"]'::jsonb, '["Enteral Nutrition","Formulas","Elemental Diets","Nutrition Support"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: C. amino acids. Elemental formulas feature free amino acids/peptides.', '{"dueDate":"2026-11-06T15:06:05.615Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:06:05.615Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:06:05.615Z"'::jsonb)
