INSERT INTO public.flashcards (id, user_id, deck_id, front, back, rationale, options, tags, ndle_subject, difficulty, leitner_box, user_notes, sm2, last_reviewed_at, created_at, updated_at) VALUES
('card-nbcd-2021-61', NULL, 'deck-prc-2021-nbcd', 'Which of the following is NOT a clinical consequence of refeeding syndrome?', 'D. hypervolemia', 'The hallmark biochemical derangements of refeeding syndrome are acute, severe intracellular electrolyte shifts causing profound HYPOphosphatemia, HYPOkalemia, and HYPOmagnesemia. While sodium and fluid retention occur due to insulin''s antinatriuretic action on renal tubules, ''hypervolemia'' is not the signature defining intracellular electrolyte depletion.', '["A. hypokalemia","B. hypophosphatemia","C. hypomagnesemia","D. hypervolemia"]'::jsonb, '["Refeeding Syndrome","Critical Care","Electrolytes","Nutrition Support"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'hard', 2, 'Exam marked: D. hypervolemia. Hallmark triad of refeeding syndrome: Hypophosphatemia, hypokalemia, hypomagnesemia.', '{"dueDate":"2026-11-06T14:26:39.785Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:26:39.785Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:26:39.785Z"'::jsonb),
('card-nbcd-2021-62', NULL, 'deck-prc-2021-nbcd', 'Exchange choices for 2 oz. meat
I. 2 oz fish fillet
II. 1 cup mongo
III. 2 oz. chicken
IV. 1 glass milk', 'D. I and III', 'In the Philippine Food Exchange Lists (PEL), 1 meat exchange is equivalent to 1 oz (30 grams) of cooked meat, poultry, or fish. Therefore, 2 oz of fish fillet (I) and 2 oz of chicken (III) each provide exactly 2 meat exchanges. Cooked mongo is classified under legumes/vegetables, and milk is classified under the milk exchange list.', '["A. I, II, III and IV","B. I, III and IV","C. I, II, and III","D. I and III"]'::jsonb, '["Food Exchange System","PEL","Meat Exchanges","Meal Planning"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. I and III. 1 meat exchange = 1 oz cooked meat/fish (8g PRO, 1-7g FAT).', '{"dueDate":"2026-11-06T12:54:02.461Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:54:02.461Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:54:02.461Z"'::jsonb),
('card-nbcd-2021-63', NULL, 'deck-prc-2021-nbcd', 'Adverse food and drug interactions are more likely to occur if:', 'D. the person taking the medication is malnourished', 'Malnutrition causes hypoalbuminemia, which reduces plasma protein-binding capacity for highly bound acidic drugs, resulting in higher circulating fractions of free active drug and potential toxicity. Furthermore, severe malnutrition impairs hepatic cytochrome P450 drug-metabolizing enzymes and renal excretion.', '["A. all organ systems are fully functional","B. one medication or herb is taken exclusively","C. medications and dietary supplements are taken for a few days","D. the person taking the medication is malnourished"]'::jsonb, '["Pharmacology","Drug-Nutrient Interactions","Malnutrition"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. the person taking the medication is malnourished. Hypoalbuminemia increases free pharmacologically active drug levels.', '{"dueDate":"2026-11-06T15:03:39.988Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:03:39.988Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:03:39.988Z"'::jsonb),
('card-nbcd-2021-64', NULL, 'deck-prc-2021-nbcd', 'With the ND Law of 2016, the mandate is for the profession to go into Accredited Integrated Profession Organization. As mandated, the AIPO should qualify in the requirements EXCEPT:', 'B. members may be less in number than the other ND organization provided, it has members who can lead the organization to greater heights through alignment with international practices', 'Under Republic Act No. 10862 (Nutrition and Dietetics Law of 2016) and PRC regulations, the designated Accredited Integrated Professional Organization (AIPO, such as NDAP) must represent the largest single registered membership of RNDs across the country. It cannot have fewer members than other rival organizations.', '["A. it will be the umbrella organization of the other associations that have RNDs as members","B. members may be less in number than the other ND organization provided, it has members who can lead the organization to greater heights through alignment with international practices","C. new CBL that will address the updated requirement of PRC","D. professional organization should be composed of RND members only"]'::jsonb, '["Ethics and Jurisprudence","RA 10862","PRC Regulations","Professional Practice"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. RA 10862 requires the AIPO to represent the national majority of registered practitioners.', '{"dueDate":"2026-11-06T15:02:33.323Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:02:33.323Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:02:33.323Z"'::jsonb),
('card-nbcd-2021-65', NULL, 'deck-prc-2021-nbcd', 'An important Vitamin that is also considered a hormone. To help prescribe the right dose for supplementation, it is important to request for a quantitative test.', 'A. Vitamin D', 'Vitamin D is synthesized endogenously in the skin from 7-dehydrocholesterol via ultraviolet B sunlight and converted to 1,25-dihydroxyvitamin D (calcitriol), which acts through nuclear receptors to regulate gene transcription. Serum 25-hydroxyvitamin D [25(OH)D] is the standard quantitative laboratory biomarker used to assess status and dose therapeutic supplementation.', '["A. Vitamin D","B. Vitamin A","C. Vitamin C","D. Vitamin E"]'::jsonb, '["Nutritional Biochemistry","Vitamin D","Hormones","Micronutrients"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Vitamin D. Calcitriol acts as a secosteroid hormone; measured via serum 25(OH)D.', '{"dueDate":"2026-11-06T12:37:54.146Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:37:54.146Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:37:54.146Z"'::jsonb),
('card-nbcd-2021-66', NULL, 'deck-prc-2021-nbcd', 'A diet principle that refers to consuming different foods from within each of the food groups on a regular basis.', 'D. Variety', 'Variety (or diversity) refers to choosing a wide array of different foods both between and within each of the basic food groups on a regular basis, which ensures intake of diverse nutrients and non-nutrient bioactive phytochemicals.', '["A. Adequacy","B. Moderation","C. Balance","D. Variety"]'::jsonb, '["Diet Planning","Basic Nutrition","Principles"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Variety. Consuming different foods within each food group.', '{"dueDate":"2026-11-06T13:02:38.442Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:02:38.442Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:02:38.442Z"'::jsonb),
('card-nbcd-2021-67', NULL, 'deck-prc-2021-nbcd', 'The Prochaska Cycle of change where a person would sustain change occurs is:', 'C. Maintenance', 'In Prochaska and DiClemente''s Transtheoretical Model (Stages of Change), the Maintenance stage is defined as sustaining the newly adopted behavior and lifestyle modifications for six months or longer, actively working to prevent relapse.', '["A. Termination","B. Action","C. Maintenance","D. Contemplation"]'::jsonb, '["Nutrition Counseling","Stages of Change","Behavioral Theories"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Maintenance. Transtheoretical Model: Sustaining behavior change >= 6 months.', '{"dueDate":"2026-11-06T13:21:47.966Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:21:47.966Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:21:47.966Z"'::jsonb),
('card-nbcd-2021-68', NULL, 'deck-prc-2021-nbcd', 'Herbs and spices:', 'B. may be used in sodium restricted diet', 'Pure natural culinary herbs and spices (such as garlic, basil, oregano, thyme, cinnamon, cumin, and black pepper) are naturally very low in sodium. They are strongly recommended in sodium-restricted diets to enhance aroma and flavor, compensating for reduced salt and improving diet adherence.', '["A. should be avoided in sodium restricted diet","B. may be used in sodium restricted diet","C. may increase sodium content of the food","D. should be used only in mild sodium restricted diet"]'::jsonb, '["Cardiovascular Nutrition","Sodium Restriction","Culinary Nutrition","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. may be used in sodium restricted diet. Safe natural seasonings for hypertension and CHF.', '{"dueDate":"2026-11-06T11:44:38.619Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:44:38.619Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:44:38.619Z"'::jsonb),
('card-nbcd-2021-69', NULL, 'deck-prc-2021-nbcd', 'Which strategy is safe for increasing the energy intake of people on fat-restricted diets?', 'B. Provide additional fat in the form of MCT oil or MCT powder', 'For patients with fat malabsorption (such as in chronic pancreatitis, cystic fibrosis, or biliary obstruction), Medium-Chain Triglycerides (MCT oil or powder) provide 8.3 kcal/g and are absorbed directly into enterocytes without requiring bile salt micellization or pancreatic lipase digestion, avoiding steatorrhea.', '["A. Gradually add fat as tolerance permits","B. Provide additional fat in the form of MCT oil or MCT powder","C. Increase high calorie foods","D. Provide fat with enzyme replacement"]'::jsonb, '["Fat Malabsorption","MCT Oil","Enteral Nutrition","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B / D (Exam duplicate of Q5). MCT oil is the safe caloric supplement in fat restriction.', '{"dueDate":"2026-11-06T14:30:15.848Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:30:15.848Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:30:15.848Z"'::jsonb),
('card-nbcd-2021-7', NULL, 'deck-prc-2021-nbcd', 'Nutrition concerns most commonly associated with chronic gastritis include:', 'B. malnutrition and pernicious anemia', 'Chronic atrophic gastritis (especially autoimmune Type A gastritis targeting parietal cells) causes progressive loss of gastric acid (achlorhydria) and intrinsic factor secretion. Lack of intrinsic factor prevents Vitamin B12 absorption in the terminal ileum, culminating in pernicious anemia. Chronic dyspepsia, anorexia, and malabsorption also contribute to generalized malnutrition.', '["A. dehydration and electrolyte imbalance","B. malnutrition and pernicious anemia","C. delayed gastric emptying and pernicious anemia","D. iron-deficiency anemia and protein malabsorption"]'::jsonb, '["Gastrointestinal","Gastritis","Anemia","Vitamins"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. malnutrition and pernicious anemia. Note: Loss of parietal cells -> decreased intrinsic factor -> pernicious anemia.', '{"dueDate":"2026-11-06T15:08:52.005Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:08:52.005Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:08:52.005Z"'::jsonb),
('card-nbcd-2021-70', NULL, 'deck-prc-2021-nbcd', 'Your client is a marathon runner. Your advice will focus on how to decrease the risk of exercise-related GI problems which is to _____.', 'D. avoid dairy products prior to exercise', 'Exercise-related gastrointestinal distress (''runner''s gut'', ischemia, bloating, diarrhea) is frequently exacerbated by lactose (found in dairy), concentrated fructose solutions, insoluble fiber, and high-fat foods consumed prior to endurance events. Eliminating dairy products and low-lactose alternatives prior to running prevents osmotic shifts and cramping.', '["A. consume high fructose beverage an hour prior, to enhance blood glucose levels","B. avoid fluids before and during exercise to avoid cramps","C. consume high-fiber foods an hour prior to exercise to slow CHO absorption and maximize blood glucose during exercise","D. avoid dairy products prior to exercise"]'::jsonb, '["Sports Nutrition","Endurance Athletes","Gastrointestinal","Exercise"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. avoid dairy products prior to exercise. Dairy/lactose before endurance running triggers GI cramping.', '{"dueDate":"2026-11-06T15:09:14.900Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:09:14.900Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:09:14.900Z"'::jsonb),
('card-nbcd-2021-71', NULL, 'deck-prc-2021-nbcd', 'Which of this is NOT needed to digest protein?', 'B. Bile acid', 'Bile acids are amphipathic molecules synthesized in the liver that emulsify dietary lipids and form mixed micelles for fat absorption; they have no direct enzymatic or catalytic function in protein digestion. Trypsin, pepsin (activated by HCl), and secretin (which stimulates pancreatic bicarbonate to create an alkaline pH for pancreatic endopeptidases) are all involved in protein digestion.', '["A. Trypsin","B. Bile acid","C. Secretin","D. Hydrochloric acid"]'::jsonb, '["Nutritional Biochemistry","Protein Digestion","Physiology","Enzymes"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Bile acid. Bile acids emulsify lipids, playing no enzymatic role in proteolysis.', '{"dueDate":"2026-11-06T15:13:36.997Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:36.997Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:36.997Z"'::jsonb),
('card-nbcd-2021-72', NULL, 'deck-prc-2021-nbcd', 'After an ileostomy, the most serious concern is that:', 'D. incompletely digested foods may cause obstruction', 'Because an ileostomy bypasses the colon and terminates in a narrow stoma on the abdominal wall, poorly chewed, stringy, or fibrous foods (such as celery, corn kernels, popcorn, nuts, seeds, coconut, tough meat fibers) can easily lodge in the narrow lumen of the stoma, causing a mechanical bowel obstruction.', '["A. the diet is so restrictive to meet nutrient needs","B. fluid restriction prevents patients from drinking beverage freely","C. water disposal causes frequent daily interruption","D. incompletely digested foods may cause obstruction"]'::jsonb, '["Gastrointestinal","Ileostomy","Surgical Nutrition","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: D. incompletely digested foods may cause obstruction. High-fiber/stringy foods risk stomal obstruction.', '{"dueDate":"2026-11-06T13:06:54.340Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:06:54.340Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:06:54.340Z"'::jsonb),
('card-nbcd-2021-73', NULL, 'deck-prc-2021-nbcd', 'Two activities that contribute to the basal metabolic rate are:', 'A. Maintenance of heartbeat and body temperature', 'Basal metabolic rate (BMR) measures energy expenditure at rest in a post-absorptive, thermoneutral state. Heart contraction (circulatory work) and core thermoregulation are two classic autonomic physiological components sustaining BMR.', '["A. Maintenance of heartbeat and body temperature","B. Maintenance of body temperature and walking","C. Walking and Running","D. Maintenance of heartbeat and running"]'::jsonb, '["Energy Metabolism","BMR","Physiology"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Maintenance of heartbeat and body temperature.', '{"dueDate":"2026-11-06T12:26:49.163Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:26:49.163Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:26:49.163Z"'::jsonb),
('card-nbcd-2021-74', NULL, 'deck-prc-2021-nbcd', 'If your patient is breathing rapidly, his body is attempting to:', 'B. get rid of excess CO2', 'Rapid, deep respirations (tachypnea or Kussmaul respirations) represent respiratory compensation for metabolic acidosis. By hyperventilating, the lungs blow off volatile carbon dioxide (CO2), driving the carbonic acid reaction to the left (H+ + HCO3- <-> H2CO3 <-> CO2 + H2O), thereby lowering hydrogen ion concentration and raising arterial blood pH.', '["A. retain CO2","B. get rid of excess CO2","C. produce more carbonic acid","D. improve the buffering ability of the bicarbonate"]'::jsonb, '["Acid-Base Balance","Pathophysiology","Respiratory","Biochemistry"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. get rid of excess CO2. Hyperventilation blows off CO2 to correct acidosis.', '{"dueDate":"2026-11-06T15:13:51.900Z","interval":1,"easeFactor":2.1,"repetitions":1}'::jsonb, '"2026-11-05T15:13:51.900Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:13:51.900Z"'::jsonb),
('card-nbcd-2021-75', NULL, 'deck-prc-2021-nbcd', 'Who is most at risk for gestational diabetes?', 'D. BMI > 30 with history of GDM', 'Pre-gravid obesity (BMI > 30 kg/m2) coupled with a personal history of gestational diabetes mellitus (GDM) represents the single greatest risk profile for developing GDM in subsequent pregnancies due to underlying peripheral insulin resistance.', '["A. BMI < 30","B. Conception within 10 months of last pregnancy","C. Age younger than 25 but overweight","D. BMI > 30 with history of GDM"]'::jsonb, '["Maternal Nutrition","Gestational Diabetes","Risk Assessment"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. BMI > 30 with history of GDM. Major established risk factors for GDM.', '{"dueDate":"2026-11-06T12:55:47.937Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:55:47.937Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:55:47.937Z"'::jsonb),
('card-nbcd-2021-76', NULL, 'deck-prc-2021-nbcd', 'Nutrient that is MOST commonly malabsorbed.', 'B. Lipids', 'Lipid (fat) digestion and absorption is the most physiologically complex digestive process, requiring gastric lipase, biliary emulsification, pancreatic lipase-colipase, mixed micelle formation, mucosal re-esterification, and lymphatic chylomicron assembly. Consequently, gastrointestinal disorders (pancreatitis, liver cirrhosis, mucosal atrophy, mucosal resections) most readily manifest as fat malabsorption (steatorrhea).', '["A. Protein","B. Lipids","C. Vitamins","D. Carbohydrate"]'::jsonb, '["Gastrointestinal","Malabsorption","Lipids","Steatorrhea"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Lipids. Fat is the most vulnerable and commonly malabsorbed macronutrient.', '{"dueDate":"2026-11-06T13:17:19.236Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:17:19.236Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:17:19.236Z"'::jsonb),
('card-nbcd-2021-77', NULL, 'deck-prc-2021-nbcd', 'Which statements BEST describes the dialysis process?', 'C. The diffusion of blood across a semipermeable membrane which is then cleansed.', 'Dialysis is an extracorporeal renal replacement therapy based on the biophysical principles of diffusion (solute movement down a concentration gradient across a semipermeable membrane) and ultrafiltration (fluid movement across a pressure gradient), cleansing the blood of uremic toxins and excess fluid.', '["A. The filtering of toxicities in the urine.","B. The removal of urine in the bladder.","C. The diffusion of blood across a semipermeable membrane which is then cleansed.","D. The removal of toxicities in the human body."]'::jsonb, '["Renal Nutrition","Dialysis","Pathophysiology","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. The diffusion of blood across a semipermeable membrane which is then cleansed.', '{"dueDate":"2026-11-06T14:20:03.035Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:20:03.035Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:20:03.035Z"'::jsonb),
('card-nbcd-2021-78', NULL, 'deck-prc-2021-nbcd', 'Trauma a deeply distressing experience can place a patient in a/an _____ state.', 'D. hypermetabolic', 'Major physical trauma, burns, and severe critical illness trigger an acute neuroendocrine stress response (flow phase) mediated by catecholamines, cortisol, glucagon, and pro-inflammatory cytokines (IL-1, IL-6, TNF-alpha), resulting in marked hypermetabolism, accelerated proteolysis, and negative nitrogen balance.', '["A. anabolic","B. hypometabolic","C. hypothermic","D. hypermetabolic"]'::jsonb, '["Critical Care","Metabolic Stress","Trauma","Hypermetabolism"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. hypermetabolic. Metabolic stress flow phase: hypermetabolism and hypercatabolism.', '{"dueDate":"2026-11-06T13:09:09.623Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:09:09.623Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:09:09.623Z"'::jsonb),
('card-nbcd-2021-79', NULL, 'deck-prc-2021-nbcd', 'It is the rate and the extent to which a vitamin is absorbed and use in the body.', 'A. Bioavailability', 'Bioavailability is defined in nutritional biochemistry and pharmacology as the proportion of an ingested nutrient or active compound that is digested, absorbed across the gastrointestinal tract, and reaches systemic circulation to be utilized for physiological functions.', '["A. Bioavailability","B. Pharmacological effect","C. Physiologic effect","D. Intrinsic factor"]'::jsonb, '["Nutritional Biochemistry","Bioavailability","Absorption"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Bioavailability. Definition of nutrient bioavailability.', '{"dueDate":"2026-11-06T15:05:42.450Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:05:42.450Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:05:42.450Z"'::jsonb),
('card-nbcd-2021-8', NULL, 'deck-prc-2021-nbcd', 'A sodium-restricted diet may be ordered for clients with _____.', 'D. congestive heart failure', 'In Congestive Heart Failure (CHF), decreased cardiac output triggers renal hypoperfusion and compensatory activation of the renin-angiotensin-aldosterone system (RAAS), promoting massive sodium and fluid retention (pulmonary congestion and peripheral edema). Sodium restriction (typically 2,000 mg/day) is a cornerstone of MNT to prevent hypervolemia.', '["A. angina pectoris","B. atherosclerosis","C. lipidemia","D. congestive heart failure"]'::jsonb, '["Cardiovascular Nutrition","Heart Failure","Sodium","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. congestive heart failure. Margin note connects sodium restriction to edema and CHF management.', '{"dueDate":"2026-11-06T15:01:32.256Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:01:32.256Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:01:32.256Z"'::jsonb),
('card-nbcd-2021-80', NULL, 'deck-prc-2021-nbcd', 'A common disorder characterized by a disturbance the motility of the GI tract with symptoms that frequently occur shortly after a person eats is called:', 'B. irritable bowel syndrome', 'Irritable Bowel Syndrome (IBS) is a functional gastrointestinal disorder of the brain-gut axis characterized by visceral hypersensitivity, altered gut motility, and recurrent abdominal pain or bloating frequently exacerbated postprandially (after eating).', '["A. diverticular disease","B. irritable bowel syndrome","C. constipation","D. diarrhea"]'::jsonb, '["Gastrointestinal","IBS","Motility Disorders","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. irritable bowel syndrome. Functional motility disorder with postprandial exacerbations.', '{"dueDate":"2026-11-06T14:38:44.048Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:38:44.048Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:38:44.048Z"'::jsonb),
('card-nbcd-2021-81', NULL, 'deck-prc-2021-nbcd', 'When you make a teaching plan for your counseling session, which of the following will create a learning situation that will secure attention and interest. Stimulate learning readiness.', 'B. Approach', 'In instructional design and health education planning, the ''Approach'' (or anticipatory set/introduction) is designed specifically to capture the client''s attention, pique personal curiosity, relate new material to prior experiences, and stimulate psychological readiness to learn.', '["A. Aim","B. Approach","C. Assignment","D. Application"]'::jsonb, '["Nutrition Education","Counseling Plans","Teaching Strategies"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. Approach (D. Application was also circled, but B represents engaging readiness/attention).', '{"dueDate":"2026-11-06T13:00:55.990Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:00:55.990Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:00:55.990Z"'::jsonb),
('card-nbcd-2021-82', NULL, 'deck-prc-2021-nbcd', 'A serious primary problem resulting from prolonged vomiting from chemotherapy relates to:', 'D. fluid and electrolyte balance', 'Prolonged emesis leads to massive loss of gastric hydrochloric acid, water, potassium, and sodium. The immediate life-threatening physiological complications are dehydration, hypovolemia, hypokalemia, and metabolic alkalosis, disrupting fluid and electrolyte homeostasis.', '["A. nitrogen balance","B. glucose balance","C. calcium balance","D. fluid and electrolyte balance"]'::jsonb, '["Oncology Nutrition","Fluid Balance","Electrolytes","Chemotherapy"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. fluid and electrolyte balance. Emesis causes severe volume depletion and hypokalemic alkalosis.', '{"dueDate":"2026-11-06T13:03:13.163Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:03:13.163Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:03:13.163Z"'::jsonb),
('card-nbcd-2021-83', NULL, 'deck-prc-2021-nbcd', 'Cancer primary treatment goals for nutrition intervention include:
I. Preventing or reversing nutrient deficiencies
II. Preserving lean body mass
III. Minimizing and managing nutrition impact symptoms and side effects
IV. Maximizing quality of life', 'B. I, II, III & IV', 'According to ESPEN and ASPEN oncology nutrition guidelines, comprehensive MNT goals for cancer patients encompass: (I) preventing and reversing nutrient deficiencies, (II) preserving skeletal muscle and lean body mass, (III) minimizing nutrition impact symptoms (nausea, mucositis, dysgeusia), and (IV) maintaining functional status and quality of life.', '["A. II, III & IV","B. I, II, III & IV","C. I, II & III","D. I, III & IV"]'::jsonb, '["Oncology Nutrition","Cancer Goals","MNT","Clinical Dietetics"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B (I, II, III & IV). All 4 are core oncology nutrition goals.', '{"dueDate":"2026-11-06T12:57:27.316Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:57:27.316Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:57:27.316Z"'::jsonb),
('card-nbcd-2021-84', NULL, 'deck-prc-2021-nbcd', 'Mary had a poor appetite for several days. Strategies that may be used to improve your client''s food intake may include any of the following EXCEPT;', 'D. feed the client by tube', 'Initial dietary strategies to stimulate and improve oral food intake in anorexia include: meal assistance, serving palatable and easy-to-chew foods, small frequent energy-dense meals, and oral nutritional supplements. Tube feeding is an invasive enteral therapy indicated only when voluntary oral intake remains inadequate (<50-60%) over prolonged periods, not an oral intake strategy.', '["A. assist the client during meals","B. serve food that are easy to eat","C. provide energy and nutrient-dense foods","D. feed the client by tube"]'::jsonb, '["Clinical Dietetics","Oral Intake","Anorexia","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. feed the client by tube. Tube feeding is invasive enteral support, not an oral strategy.', '{"dueDate":"2026-11-06T14:59:54.505Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T14:59:54.505Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:59:54.505Z"'::jsonb),
('card-nbcd-2021-85', NULL, 'deck-prc-2021-nbcd', 'Which is NOT part of the clinical RNDs task?', 'A. Food service menu planning', 'Clinical Registered Nutritionist-Dietitians (RNDs) are responsible for individual patient clinical care: nutritional assessment, NCP diagnosis, nutrition intervention, medical record charting (ADIME format), and inpatient/discharge nutrition counseling. Large-scale institutional food service menu planning is an administrative/food service management task.', '["A. Food service menu planning","B. Discharge counseling","C. Charting","D. Nutrition Intervention"]'::jsonb, '["Clinical Dietetics","Scope of Practice","RND Roles","Professional Practice"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Food service menu planning. Clinical RND focuses on patient-centered care and NCP.', '{"dueDate":"2026-11-06T15:05:19.448Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:05:19.448Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:05:19.448Z"'::jsonb),
('card-nbcd-2021-86', NULL, 'deck-prc-2021-nbcd', 'Azotemia is detected through the measurement of _____.', 'D. Blood urea nitrogen', 'Azotemia is an abnormal clinical and biochemical elevation of nitrogenous waste products in the blood, primarily diagnosed and monitored by measuring Blood Urea Nitrogen (BUN) and serum creatinine.', '["A. Sodium in the spinal fluid","B. Uric acid in urine","C. Calcium in the blood","D. Blood urea nitrogen"]'::jsonb, '["Renal Nutrition","Laboratory Assessment","Azotemia","BUN"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Blood urea nitrogen. Azotemia = elevated BUN and nitrogenous wastes.', '{"dueDate":"2026-11-06T12:53:12.708Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:53:12.708Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:53:12.708Z"'::jsonb),
('card-nbcd-2021-87', NULL, 'deck-prc-2021-nbcd', 'The middle segment of the small intestine?', 'D. Jejunum', 'Anatomically, the small intestine comprises three contiguous segments: the duodenum (first/proximal, ~25 cm), the jejunum (middle, ~2.5 m), and the ileum (distal, ~3.5 m).', '["A. Sigmoid","B. Ileum","C. Duodenum","D. Jejunum"]'::jsonb, '["Anatomy","Gastrointestinal","Small Intestine"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: D. Jejunum. Small bowel order: Duodenum -> Jejunum -> Ileum.', '{"dueDate":"2026-11-06T11:53:47.143Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:53:47.143Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:53:47.143Z"'::jsonb),
('card-nbcd-2021-88', NULL, 'deck-prc-2021-nbcd', 'Your patient are doing discharge counseling with respiratory failure, your instruction should be to limit his intake of;', 'A. Carbohydrates', 'In respiratory failure and chronic obstructive pulmonary disease (COPD), carbohydrate oxidation yields a Respiratory Quotient (RQ) of 1.0 (RQ = VCO2 / VO2), producing significantly more carbon dioxide per mole of oxygen consumed than fat oxidation (RQ = 0.7). Excess dietary carbohydrates increase ventilatory demand and CO2 retention, exacerbating hypercapnic respiratory failure.', '["A. Carbohydrates","B. protein","C. sodium","D. water"]'::jsonb, '["Pulmonary Nutrition","Respiratory Failure","RQ","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. Carbohydrates. High CHO increases CO2 production (RQ = 1.0).', '{"dueDate":"2026-11-06T14:41:43.076Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:41:43.076Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:41:43.076Z"'::jsonb),
('card-nbcd-2021-89', NULL, 'deck-prc-2021-nbcd', 'The primary goal of medical nutrition therapy in diabetes is to _____.', 'C. maintain near-normal blood glucose levels', 'While cardiovascular risk reduction and weight management are vital components of comprehensive diabetes management, the primary and central therapeutic goal of MNT in diabetes is to achieve and maintain near-normal blood glucose levels (glycemic control, HbA1c < 7.0%) to prevent acute ketoacidosis/hypoglycemia and long-term microvascular and macrovascular complications.', '["A. encourage weight loss","B. control blood lipids and blood pressure","C. maintain near-normal blood glucose levels","D. support health and well-being"]'::jsonb, '["Diabetes Mellitus","MNT Goals","Glycemic Control"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. maintain near-normal blood glucose levels. Primary glycemic objective in diabetes MNT.', '{"dueDate":"2026-11-06T13:06:02.588Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T13:06:02.588Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T13:06:02.588Z"'::jsonb),
('card-nbcd-2021-9', NULL, 'deck-prc-2021-nbcd', 'Which of the following will you advise a patient who is suffering from peptic ulcer?
I. No smoking
II. Avoid taking aspirin
III. Diet should be caffeine free
IV. Take a liberal bland diet', 'A. I, II, III and IV', 'Comprehensive MNT and lifestyle advice for Peptic Ulcer Disease (PUD) includes: smoking cessation (nicotine impairs mucosal blood flow and bicarbonate secretion), eliminating aspirin/NSAIDs (which inhibit protective prostaglandin synthesis), avoiding caffeine and decaffeinated coffee (which stimulate gastric acid secretion), and following a liberalized bland diet omitting individual trigger foods and gastric irritants.', '["A. I, II, III and IV","B. IV only","C. II, III and IV","D. I, II and III"]'::jsonb, '["Gastrointestinal","Peptic Ulcer","MNT","Diet Therapy"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A (I, II, III and IV). All four interventions protect gastric mucosal integrity.', '{"dueDate":"2026-11-06T15:06:51.223Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:06:51.223Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:06:51.223Z"'::jsonb),
('card-nbcd-2021-90', NULL, 'deck-prc-2021-nbcd', 'The patient with chronic pancreatitis benefits from the following diet-related advice:', 'A. use enzyme replacements to improve fat absorption', 'Chronic pancreatitis leads to progressive loss of pancreatic exocrine tissue, causing lipase deficiency and severe steatorrhea. Pancreatic Enzyme Replacement Therapy (PERT) taken concurrently with all meals and snacks restores lipid digestion, improves nutrient absorption, and relieves abdominal pain and diarrhea. Note: Alcohol must be strictly eliminated, not moderately restricted.', '["A. use enzyme replacements to improve fat absorption","B. follow a very low fat diet","C. eat three meals a day and avoid snacks","D. moderately restrict alcohol"]'::jsonb, '["Gastrointestinal","Pancreatitis","PERT","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: A. use enzyme replacements to improve fat absorption. PERT is the cornerstone of chronic pancreatitis MNT.', '{"dueDate":"2026-11-06T14:32:56.353Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:32:56.353Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:32:56.353Z"'::jsonb),
('card-nbcd-2021-91', NULL, 'deck-prc-2021-nbcd', 'Which are the symptoms of respiratory problem?', 'C. Wheezing, sneezing and congestion', 'Wheezing (bronchial narrowing/spasm), sneezing (upper airway rhinitis), and respiratory congestion are hallmark clinical manifestations of respiratory illness or respiratory-involved systemic allergic reactions.', '["A. Headache, irritability, low BP","B. Rash, redness and itchiness","C. Wheezing, sneezing and congestion","D. Swollen throat, bloating and malabsorption"]'::jsonb, '["Clinical Assessment","Respiratory","Symptoms"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Wheezing, sneezing and congestion. Respiratory clinical symptoms.', '{"dueDate":"2026-11-06T11:43:55.158Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:43:55.158Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:43:55.158Z"'::jsonb),
('card-nbcd-2021-92', NULL, 'deck-prc-2021-nbcd', 'Which of the following represents a potential affect of infection on nutritional status?', 'B. Protein catabolism', 'Systemic infection stimulates inflammatory cytokines (IL-1, IL-6, TNF-alpha) and glucocorticoids, accelerating skeletal muscle proteolysis (protein catabolism) to mobilize amino acids for hepatic acute-phase protein synthesis and gluconeogenesis, producing negative nitrogen balance.', '["A. Increased intestinal absorption","B. Protein catabolism","C. Reduced energy expenditure","D. Appetite stimulation"]'::jsonb, '["Nutritional Biochemistry","Metabolic Stress","Infection","Proteolysis"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Protein catabolism. Infection triggers cytokine-mediated muscle catabolism.', '{"dueDate":"2026-11-06T15:02:03.326Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:02:03.326Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:02:03.326Z"'::jsonb),
('card-nbcd-2021-93', NULL, 'deck-prc-2021-nbcd', 'For the person undergoing a liver transplant:', 'B. attention to nutrients before a transplant improves chances of recovery', 'Malnutrition is present in up to 80-90% of end-stage liver disease patients awaiting transplantation and is an independent predictor of operative morbidity, prolonged mechanical ventilation, sepsis, and post-transplant mortality. Pre-transplant nutrition intervention significantly enhances graft survival and surgical recovery.', '["A. enteral nutrition is contraindicated following the transplant","B. attention to nutrients before a transplant improves chances of recovery","C. provided adequate nutrition is given following a transplant, nutrition status before surgery has little impact on recovery","D. immunosuppressant drugs seldom alter nutrient needs"]'::jsonb, '["Hepatic Nutrition","Transplantation","Surgical Nutrition","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'medium', 2, 'Exam marked: B. attention to nutrients before a transplant improves chances of recovery.', '{"dueDate":"2026-11-06T14:43:33.022Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:43:33.022Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:43:33.022Z"'::jsonb),
('card-nbcd-2021-94', NULL, 'deck-prc-2021-nbcd', 'Ammonia is detoxified when the liver converts it to _____.', 'B. urea', 'Free neurotoxic ammonia (NH3/NH4+) produced by amino acid deamination and colonic bacterial ureases is transported to the liver, where hepatocytes convert it into non-toxic, water-soluble urea via the hepatic urea cycle (ornithine cycle) for ultimate renal clearance.', '["A. nitrogen","B. urea","C. creatinine","D. ketones"]'::jsonb, '["Nutritional Biochemistry","Urea Cycle","Ammonia","Liver"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. urea. Hepatic urea cycle detoxifies ammonia to urea.', '{"dueDate":"2026-11-06T11:44:21.156Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T11:44:21.156Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T11:44:21.156Z"'::jsonb),
('card-nbcd-2021-95', NULL, 'deck-prc-2021-nbcd', 'Which of the following results fall within the normal blood glucose levels?', 'B. 70 - 100 mg/dL', 'According to the American Diabetes Association (ADA) diagnostic guidelines, normal fasting plasma glucose is defined as 70 to 99 mg/dL (or 70 to 100 mg/dL). Fasting glucose from 100 to 125 mg/dL is categorized as impaired fasting glucose (prediabetes), and >= 126 mg/dL indicates diabetes mellitus.', '["A. 80 - 110 mg/dL","B. 70 - 100 mg/dL","C. 70 - 90 mg/dL","D. 70 - 110 mg/dL"]'::jsonb, '["Diabetes Mellitus","Laboratory Values","Diagnostic Criteria"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. 70 - 100 mg/dL. Standard clinical normal fasting plasma glucose range.', '{"dueDate":"2026-11-06T12:47:52.635Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:47:52.635Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:47:52.635Z"'::jsonb),
('card-nbcd-2021-96', NULL, 'deck-prc-2021-nbcd', 'Ammonia is detoxified when the liver converts it to:', 'A. Urea', 'Free ammonia is metabolized exclusively via the hepatic ornithine-urea cycle into neutral, water-soluble urea, which enters systemic circulation and is filtered by renal glomeruli.', '["A. Urea","B. Nitrogen","C. Ketones","D. Creatinine"]'::jsonb, '["Nutritional Biochemistry","Urea Cycle","Ammonia"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: A. Urea (Exam paper duplicate of Q94).', '{"dueDate":"2026-11-06T12:27:05.988Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:27:05.988Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:27:05.988Z"'::jsonb),
('card-nbcd-2021-97', NULL, 'deck-prc-2021-nbcd', 'When renal tissue has been destroyed to a point at which it can no longer filter the blood, the following occurs _____.', 'B. Uremia', 'When end-stage renal disease (ESRD) develops and the glomerular filtration rate falls profoundly, kidneys can no longer clear nitrogenous wastes, electrolytes, and water. This profound intoxication of tissues and organs by accumulated nitrogenous waste products is termed uremia (uremic syndrome).', '["A. Nephrolithiasis","B. Uremia","C. Nephrosclerosis","D. Nephritis"]'::jsonb, '["Renal Nutrition","CKD","ESRD","Uremia"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: B. Uremia. End-stage toxemia due to loss of renal excretory function.', '{"dueDate":"2026-11-06T15:00:42.117Z","interval":1,"easeFactor":2.3,"repetitions":1}'::jsonb, '"2026-11-05T15:00:42.117Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T15:00:42.117Z"'::jsonb),
('card-nbcd-2021-98', NULL, 'deck-prc-2021-nbcd', 'Which of the following uses advance scientific techniques to alter and ideally improve characteristics of plants, animals and other forms of life?', 'C. Biotechnology', 'Biotechnology is the broad, encompassing scientific discipline that applies cellular and biomolecular processes (including recombinant DNA technology, genetic modification, and cloning) to improve agricultural crops, food crops, and medicinal organisms.', '["A. GRAS","B. Hydrophonics","C. Biotechnology","D. Genetic Engineering"]'::jsonb, '["Food Science","Biotechnology","Agriculture"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Biotechnology. Broad umbrella term for molecular biological alteration.', '{"dueDate":"2026-11-06T14:22:19.196Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T14:22:19.196Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T14:22:19.196Z"'::jsonb),
('card-nbcd-2021-99', NULL, 'deck-prc-2021-nbcd', 'Which type of fiber binds bile and therefore reduces one''s risk of atherosclerosis?', 'C. Soluble fiber', 'Soluble viscous fiber (such as beta-glucan from oats, pectin from citrus fruits, and psyllium) forms viscous gels in the intestinal lumen that bind bile acids and dietary cholesterol, preventing micellar reabsorption and stimulating hepatic conversion of cholesterol into bile acids, reducing serum atherogenic LDL cholesterol.', '["A. Dietary fiber","B. Total fiber","C. Soluble fiber","D. Insoluble fiber"]'::jsonb, '["Fiber","Cardiovascular Nutrition","Lipids","MNT"]'::jsonb, 'Nutritional Biochemistry and Clinical Dietetics', 'easy', 2, 'Exam marked: C. Soluble fiber. Soluble fiber binds bile acids to lower LDL and cardiovascular risk.', '{"dueDate":"2026-11-06T12:49:06.720Z","interval":1,"easeFactor":2.5,"repetitions":1}'::jsonb, '"2026-11-05T12:49:06.720Z"'::jsonb, '"2026-11-05T05:07:44.124Z"'::jsonb, '"2026-11-05T12:49:06.720Z"'::jsonb)
