INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:which combination represents the essential fatty acids?:::linoleic acid and α-linolenic acid', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which combination represents the essential fatty acids?', 'Linoleic acid and α-linolenic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ EPA and DHA: Conditionally essential / semi-essential omega-3s that can be synthesized endogenously from α-linolenic acid (ALA), though conversion efficiency is limited.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Linoleic acid and α-linolenic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ EPA and DHA: Conditionally essential / semi-essential omega-3s that can be synthesized endogenously from α-linolenic acid (ALA), though conversion efficiency is limited.\n❌ Arachidonic acid and EPA: Arachidonic acid is conditionally essential (synthesized from linoleic acid), and EPA is derived from ALA; neither are primary essential precursors.\n❌ Oleic acid and palmitic acid: Oleic acid (omega-9 MUFA) and palmitic acid (SFA) are fully synthesized endogenously via acetyl-CoA and Δ9 desaturase.","whyWrongChoices":"❌ EPA and DHA: Conditionally essential / semi-essential omega-3s that can be synthesized endogenously from α-linolenic acid (ALA), though conversion efficiency is limited.\n❌ Arachidonic acid and EPA: Arachidonic acid is conditionally essential (synthesized from linoleic acid), and EPA is derived from ALA; neither are primary essential precursors.\n❌ Oleic acid and palmitic acid: Oleic acid (omega-9 MUFA) and palmitic acid (SFA) are fully synthesized endogenously via acetyl-CoA and Δ9 desaturase."}'::jsonb),
('mc:which combination represents the essential fatty acids?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which combination represents the essential fatty acids?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ EPA and DHA: Conditionally essential / semi-essential omega-3s that can be synthesized endogenously from α-linolenic acid (ALA), though conversion efficiency is limited.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Linoleic acid and α-linolenic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ EPA and DHA: Conditionally essential / semi-essential omega-3s that can be synthesized endogenously from α-linolenic acid (ALA), though conversion efficiency is limited.\n❌ Arachidonic acid and EPA: Arachidonic acid is conditionally essential (synthesized from linoleic acid), and EPA is derived from ALA; neither are primary essential precursors.\n❌ Oleic acid and palmitic acid: Oleic acid (omega-9 MUFA) and palmitic acid (SFA) are fully synthesized endogenously via acetyl-CoA and Δ9 desaturase.","whyWrongChoices":"❌ EPA and DHA: Conditionally essential / semi-essential omega-3s that can be synthesized endogenously from α-linolenic acid (ALA), though conversion efficiency is limited.\n❌ Arachidonic acid and EPA: Arachidonic acid is conditionally essential (synthesized from linoleic acid), and EPA is derived from ALA; neither are primary essential precursors.\n❌ Oleic acid and palmitic acid: Oleic acid (omega-9 MUFA) and palmitic acid (SFA) are fully synthesized endogenously via acetyl-CoA and Δ9 desaturase."}'::jsonb),
('mc:during prolonged fasting, which metabolic process becomes increasingly important as insulin decreases and glucagon increases?:::ketogenesis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'during prolonged fasting, which metabolic process becomes increasingly important as insulin decreases and glucagon increases?', 'Ketogenesis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During prolonged fasting, your body''s stored liver glycogen is completely depleted (usually within 24 hours). As insulin levels fall dramatically and glucagon rises, adipose tissue breaks down fat into free fatty acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During prolonged fasting, your body''s stored liver glycogen is completely depleted (usually within 24 hours). As insulin levels fall dramatically and glucagon rises, adipose tissue breaks down fat into free fatty acids.\n\nThe liver takes up these fatty acids and undergoes a process called ketogenesis to produce ketone bodies (acetoacetate and beta-hydroxybutyrate). These ketone bodies cross the blood-brain barrier and serve as a vital alternative fuel source for the brain and muscles, effectively preserving muscle mass by minimizing the need for protein breakdown.\n\n❌ Glycogenesis: Glycogen synthesis is an anabolic process stimulated by insulin in the well-fed state; inhibited during fasting.\n❌ Lipogenesis: De novo fatty acid synthesis requires high insulin and excess energy; shut off when glucagon levels rise.\n❌ Protein synthesis: Anabolic tissue building promoted by insulin and amino acid availability; replaced by proteolysis/autophagy in prolonged starvation.","whyWrongChoices":"During prolonged fasting, your body''s stored liver glycogen is completely depleted (usually within 24 hours). As insulin levels fall dramatically and glucagon rises, adipose tissue breaks down fat into free fatty acids.\n\nThe liver takes up these fatty acids and undergoes a process called ketogenesis to produce ketone bodies (acetoacetate and beta-hydroxybutyrate). These ketone bodies cross the blood-brain barrier and serve as a vital alternative fuel source for the brain and muscles, effectively preserving muscle mass by minimizing the need for protein breakdown.\n\n❌ Glycogenesis: Glycogen synthesis is an anabolic process stimulated by insulin in the well-fed state; inhibited during fasting.\n❌ Lipogenesis: De novo fatty acid synthesis requires high insulin and excess energy; shut off when glucagon levels rise.\n❌ Protein synthesis: Anabolic tissue building promoted by insulin and amino acid availability; replaced by proteolysis/autophagy in prolonged starvation."}'::jsonb),
('mc:during prolonged fasting, which metabolic process becomes increasingly important as insulin decreases and glucagon increases?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'during prolonged fasting, which metabolic process becomes increasingly important as insulin decreases and glucagon increases?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During prolonged fasting, your body''s stored liver glycogen is completely depleted (usually within 24 hours). As insulin levels fall dramatically and glucagon rises, adipose tissue breaks down fat into free fatty acids.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ketogenesis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During prolonged fasting, your body''s stored liver glycogen is completely depleted (usually within 24 hours). As insulin levels fall dramatically and glucagon rises, adipose tissue breaks down fat into free fatty acids.\n\nThe liver takes up these fatty acids and undergoes a process called ketogenesis to produce ketone bodies (acetoacetate and beta-hydroxybutyrate). These ketone bodies cross the blood-brain barrier and serve as a vital alternative fuel source for the brain and muscles, effectively preserving muscle mass by minimizing the need for protein breakdown.\n\n❌ Glycogenesis: Glycogen synthesis is an anabolic process stimulated by insulin in the well-fed state; inhibited during fasting.\n❌ Lipogenesis: De novo fatty acid synthesis requires high insulin and excess energy; shut off when glucagon levels rise.\n❌ Protein synthesis: Anabolic tissue building promoted by insulin and amino acid availability; replaced by proteolysis/autophagy in prolonged starvation.","whyWrongChoices":"During prolonged fasting, your body''s stored liver glycogen is completely depleted (usually within 24 hours). As insulin levels fall dramatically and glucagon rises, adipose tissue breaks down fat into free fatty acids.\n\nThe liver takes up these fatty acids and undergoes a process called ketogenesis to produce ketone bodies (acetoacetate and beta-hydroxybutyrate). These ketone bodies cross the blood-brain barrier and serve as a vital alternative fuel source for the brain and muscles, effectively preserving muscle mass by minimizing the need for protein breakdown.\n\n❌ Glycogenesis: Glycogen synthesis is an anabolic process stimulated by insulin in the well-fed state; inhibited during fasting.\n❌ Lipogenesis: De novo fatty acid synthesis requires high insulin and excess energy; shut off when glucagon levels rise.\n❌ Protein synthesis: Anabolic tissue building promoted by insulin and amino acid availability; replaced by proteolysis/autophagy in prolonged starvation."}'::jsonb),
('mc:the following statements are true regarding polysaccharides except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following statements are true regarding polysaccharides except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Amylose is actually a linear, unbranched chain of glucose units linked together by a-1,4-glycosidic bonds. Because it is unbranched, it naturally twists into a helical/spiral shape.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Amylose is made up of continuous, branched chains.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Amylose is actually a linear, unbranched chain of glucose units linked together by a-1,4-glycosidic bonds. Because it is unbranched, it naturally twists into a helical/spiral shape.","whyWrongChoices":"Alternative options: They are polymers of glucose., Amylopectin has α-1,6 bonds., Glycogen is similar to amylopectin but is more highly branched"}'::jsonb),
('mc:which transporter is primarily responsible for intestinal absorption of fructose?:::glut5', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which transporter is primarily responsible for intestinal absorption of fructose?', 'GLUT5', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ SGLT1: Sodium-glucose cotransporter 1; actively transports glucose and galactose across the apical membrane, not fructose.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"GLUT5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ SGLT1: Sodium-glucose cotransporter 1; actively transports glucose and galactose across the apical membrane, not fructose.\n❌ GLUT2: Basolateral transporter that exports glucose, galactose, and fructose out of enterocytes into portal circulation (can translocate apically only during high-sugar surges).\n❌ GLUT4: Insulin-dependent glucose transporter found primarily in skeletal muscle and adipose tissue; absent from the intestinal brush border.","whyWrongChoices":"❌ SGLT1: Sodium-glucose cotransporter 1; actively transports glucose and galactose across the apical membrane, not fructose.\n❌ GLUT2: Basolateral transporter that exports glucose, galactose, and fructose out of enterocytes into portal circulation (can translocate apically only during high-sugar surges).\n❌ GLUT4: Insulin-dependent glucose transporter found primarily in skeletal muscle and adipose tissue; absent from the intestinal brush border."}'::jsonb),
('mc:which transporter is primarily responsible for intestinal absorption of fructose?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which transporter is primarily responsible for intestinal absorption of fructose?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"❌ SGLT1: Sodium-glucose cotransporter 1; actively transports glucose and galactose across the apical membrane, not fructose.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"GLUT5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"❌ SGLT1: Sodium-glucose cotransporter 1; actively transports glucose and galactose across the apical membrane, not fructose.\n❌ GLUT2: Basolateral transporter that exports glucose, galactose, and fructose out of enterocytes into portal circulation (can translocate apically only during high-sugar surges).\n❌ GLUT4: Insulin-dependent glucose transporter found primarily in skeletal muscle and adipose tissue; absent from the intestinal brush border.","whyWrongChoices":"❌ SGLT1: Sodium-glucose cotransporter 1; actively transports glucose and galactose across the apical membrane, not fructose.\n❌ GLUT2: Basolateral transporter that exports glucose, galactose, and fructose out of enterocytes into portal circulation (can translocate apically only during high-sugar surges).\n❌ GLUT4: Insulin-dependent glucose transporter found primarily in skeletal muscle and adipose tissue; absent from the intestinal brush border."}'::jsonb),
('mc:a patient receiving long-term isoniazid develops peripheral neuropathy. which nutrient deficiency should be suspected?:::vitamin b6', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a patient receiving long-term isoniazid develops peripheral neuropathy. which nutrient deficiency should be suspected?', 'Vitamin B6', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Isoniazid is a hydrazine derivative that is structurally similar to pyridoxine. It causes vitamin B6 deficiency through two primary mechanisms: (1) it chemically binds to pyridoxal and pyridoxal-5''-phosphate (PLP) to form inactive isoniazid-pyridoxal hydrazone complexes that are rapidly excreted in the urine, and (2) it competitively inhibits pyridoxal kinase, the enzyme responsible for phosphorylating pyridoxine into bioactive PLP. Because PLP is an obligate coenzyme for glutamic acid decarboxylase (which converts glutamate to GABA) and for enzymes involved in sphingolipid and myelin sheath synthesis, severe depletion produces peripheral axonal degeneration and neuropathy. Prophylactic administration of pyridoxine (25 to 50 mg daily) is routinely indicated for high-risk patients receiving INH.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vitamin B6\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Isoniazid is a hydrazine derivative that is structurally similar to pyridoxine. It causes vitamin B6 deficiency through two primary mechanisms: (1) it chemically binds to pyridoxal and pyridoxal-5''-phosphate (PLP) to form inactive isoniazid-pyridoxal hydrazone complexes that are rapidly excreted in the urine, and (2) it competitively inhibits pyridoxal kinase, the enzyme responsible for phosphorylating pyridoxine into bioactive PLP. Because PLP is an obligate coenzyme for glutamic acid decarboxylase (which converts glutamate to GABA) and for enzymes involved in sphingolipid and myelin sheath synthesis, severe depletion produces peripheral axonal degeneration and neuropathy. Prophylactic administration of pyridoxine (25 to 50 mg daily) is routinely indicated for high-risk patients receiving INH.\n\nIsoniazid forms an inactive hydrazone complex with pyridoxal phosphate (PLP) and accelerates its urinary excretion, leading to secondary pyridoxine deficiency and peripheral neuropathy.\n❌ Vitamin B1: Thiamine deficiency causes beriberi (wet/dry) or Wernicke-Korsakoff syndrome, characteristically tied to alcohol use or poor intake.\n❌ Vitamin B12: Cobalamin deficiency causes subacute combined degeneration of the spinal cord (SCD) and megaloblastic anemia, typically due to lack of intrinsic factor or ileal disease.\n❌ Vitamin C: Ascorbic acid deficiency results in scurvy (petechiae, bleeding gums, impaired collagen synthesis).","whyWrongChoices":"Isoniazid is a hydrazine derivative that is structurally similar to pyridoxine. It causes vitamin B6 deficiency through two primary mechanisms: (1) it chemically binds to pyridoxal and pyridoxal-5''-phosphate (PLP) to form inactive isoniazid-pyridoxal hydrazone complexes that are rapidly excreted in the urine, and (2) it competitively inhibits pyridoxal kinase, the enzyme responsible for phosphorylating pyridoxine into bioactive PLP. Because PLP is an obligate coenzyme for glutamic acid decarboxylase (which converts glutamate to GABA) and for enzymes involved in sphingolipid and myelin sheath synthesis, severe depletion produces peripheral axonal degeneration and neuropathy. Prophylactic administration of pyridoxine (25 to 50 mg daily) is routinely indicated for high-risk patients receiving INH.\n\nIsoniazid forms an inactive hydrazone complex with pyridoxal phosphate (PLP) and accelerates its urinary excretion, leading to secondary pyridoxine deficiency and peripheral neuropathy.\n❌ Vitamin B1: Thiamine deficiency causes beriberi (wet/dry) or Wernicke-Korsakoff syndrome, characteristically tied to alcohol use or poor intake.\n❌ Vitamin B12: Cobalamin deficiency causes subacute combined degeneration of the spinal cord (SCD) and megaloblastic anemia, typically due to lack of intrinsic factor or ileal disease.\n❌ Vitamin C: Ascorbic acid deficiency results in scurvy (petechiae, bleeding gums, impaired collagen synthesis)."}'::jsonb),
