INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:the hormone responsible for stimulating the uptake of glucose into the cells and its storage as glycogen in the liver and muscles::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the hormone responsible for stimulating the uptake of glucose into the cells and its storage as glycogen in the liver and muscles:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This anabolic hormone is secreted by the beta cells of the pancreas in response to high blood sugar levels (such as after eating). It lowers blood glucose by stimulating its uptake into cells (via GLUT-4 translocation) and promoting glycogenesis—the storage of excess glucose as glycogen in the liver and skeletal muscles.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"insulin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This anabolic hormone is secreted by the beta cells of the pancreas in response to high blood sugar levels (such as after eating). It lowers blood glucose by stimulating its uptake into cells (via GLUT-4 translocation) and promoting glycogenesis—the storage of excess glucose as glycogen in the liver and skeletal muscles.\n\n• Glucagon: Produced by the alpha cells of the pancreas, glucagon has the exact opposite effect. It is released during fasting or low blood sugar states to trigger the liver to break glycogen back down into glucose (glycogenolysis).\n• Epinephrine & Norepinephrine: Known as catecholamines, these stress hormones stimulate the breakdown of glycogen to rapidly elevate blood glucose levels for immediate energy during a fight-or-flight response.","whyWrongChoices":"Alternative options: glucagon, epinephrine, norepinephrine"}'::jsonb),
('mc:the coenzyme needed to convert pyruvate to acetyl coa::::tpp', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the coenzyme needed to convert pyruvate to acetyl coa:', 'TPP', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The conversion of pyruvate to acetyl-CoA is an oxidative decarboxylation reaction. Thiamine pyrophosphate, or TPP (derived from Vitamin B₁), serves as the coenzyme for E1 (pyruvate dehydrogenase), where it directly attacks and cleaves the carbonyl carbon of pyruvate, releasing carbon dioxide (decarboxylation). While NAD⁺ and FAD are also part of the 5-coenzyme complex (alongside Lipoic acid and CoA-SH), TPP is uniquely required as the initial binding and decarboxylating coenzyme.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"TPP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The conversion of pyruvate to acetyl-CoA is an oxidative decarboxylation reaction. Thiamine pyrophosphate, or TPP (derived from Vitamin B₁), serves as the coenzyme for E1 (pyruvate dehydrogenase), where it directly attacks and cleaves the carbonyl carbon of pyruvate, releasing carbon dioxide (decarboxylation). While NAD⁺ and FAD are also part of the 5-coenzyme complex (alongside Lipoic acid and CoA-SH), TPP is uniquely required as the initial binding and decarboxylating coenzyme.\n\n• NAD: While NAD⁺ is required by the PDH complex (for the E3 subunit), its specific role is to act as the final electron acceptor to reset the system, producing NADH.\n• FAD: FAD is an intermediate electron carrier within the E3 subunit of the complex that transfers its electrons to NAD⁺.\n• PLP: Pyridoxal Phosphate (derived from Vitamin B₆) is not involved in this pathway at all. It is primarily the essential coenzyme for transamination and decarboxylation reactions in amino acid metabolism.","whyWrongChoices":"Alternative options: FAD, NAD, PLP"}'::jsonb),
('mc:the coenzyme needed to convert pyruvate to acetyl coa::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the coenzyme needed to convert pyruvate to acetyl coa:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The conversion of pyruvate to acetyl-CoA is an oxidative decarboxylation reaction. Thiamine pyrophosphate, or TPP (derived from Vitamin B₁), serves as the coenzyme for E1 (pyruvate dehydrogenase), where it directly attacks and cleaves the carbonyl carbon of pyruvate, releasing carbon dioxide (decarboxylation). While NAD⁺ and FAD are also part of the 5-coenzyme complex (alongside Lipoic acid and CoA-SH), TPP is uniquely required as the initial binding and decarboxylating coenzyme.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"TPP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The conversion of pyruvate to acetyl-CoA is an oxidative decarboxylation reaction. Thiamine pyrophosphate, or TPP (derived from Vitamin B₁), serves as the coenzyme for E1 (pyruvate dehydrogenase), where it directly attacks and cleaves the carbonyl carbon of pyruvate, releasing carbon dioxide (decarboxylation). While NAD⁺ and FAD are also part of the 5-coenzyme complex (alongside Lipoic acid and CoA-SH), TPP is uniquely required as the initial binding and decarboxylating coenzyme.\n\n• NAD: While NAD⁺ is required by the PDH complex (for the E3 subunit), its specific role is to act as the final electron acceptor to reset the system, producing NADH.\n• FAD: FAD is an intermediate electron carrier within the E3 subunit of the complex that transfers its electrons to NAD⁺.\n• PLP: Pyridoxal Phosphate (derived from Vitamin B₆) is not involved in this pathway at all. It is primarily the essential coenzyme for transamination and decarboxylation reactions in amino acid metabolism.","whyWrongChoices":"Alternative options: FAD, NAD, PLP"}'::jsonb),
('mc:the two simple sugars that make up maltose::::2 glucose', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the two simple sugars that make up maltose:', '2 glucose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Also known as malt sugar, this disaccharide is formed by a covalent bond between two glucose molecules (specifically an α(1→4) glycosidic linkage). It is commonly produced during the digestion of starch by amylase.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 glucose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Also known as malt sugar, this disaccharide is formed by a covalent bond between two glucose molecules (specifically an α(1→4) glycosidic linkage). It is commonly produced during the digestion of starch by amylase.\n\n• Glucose and Fructose: These two sugars combine to form sucrose (table sugar).\n• Glucose and Galactose: These two sugars combine to form lactose (milk sugar).","whyWrongChoices":"Alternative options: 2 fructose, glucose and fructose, glucose and galactose"}'::jsonb),
('mc:the principal carbohydrate stored in plants is::::starch', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the principal carbohydrate stored in plants is:', 'starch', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Starch is a complex polysaccharide made of alpha-glucose monomers linked together. Plants produce excess glucose through photosynthesis and string thousands of these molecules together to form starch grains inside their cells. This serves as their primary, long-term chemical energy reserve for periods when sunlight is unavailable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"starch\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Starch is a complex polysaccharide made of alpha-glucose monomers linked together. Plants produce excess glucose through photosynthesis and string thousands of these molecules together to form starch grains inside their cells. This serves as their primary, long-term chemical energy reserve for periods when sunlight is unavailable.\n\nPlant starch is uniquely composed of a mixture of two distinct polymers: amylose (a linear, unbranched helical chain) and amylopectin (a highly branched chain).","whyWrongChoices":"Alternative options: cellulose, glycogen, glucose"}'::jsonb),
('mc:the principal carbohydrate stored in plants is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the principal carbohydrate stored in plants is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Starch is a complex polysaccharide made of alpha-glucose monomers linked together. Plants produce excess glucose through photosynthesis and string thousands of these molecules together to form starch grains inside their cells. This serves as their primary, long-term chemical energy reserve for periods when sunlight is unavailable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"starch\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Starch is a complex polysaccharide made of alpha-glucose monomers linked together. Plants produce excess glucose through photosynthesis and string thousands of these molecules together to form starch grains inside their cells. This serves as their primary, long-term chemical energy reserve for periods when sunlight is unavailable.\n\nPlant starch is uniquely composed of a mixture of two distinct polymers: amylose (a linear, unbranched helical chain) and amylopectin (a highly branched chain).","whyWrongChoices":"Alternative options: cellulose, glycogen, glucose"}'::jsonb),
('mc:the protein found in human hair and fingernails as well as animal hooves, horns, and claws.:::keratin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the protein found in human hair and fingernails as well as animal hooves, horns, and claws.', 'keratin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Keratin is a tough, fibrous structural protein that forms the primary component of human hair, fingernails, and the outer layer of skin, as well as animal hooves, horns, claws, and feathers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"keratin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Keratin is a tough, fibrous structural protein that forms the primary component of human hair, fingernails, and the outer layer of skin, as well as animal hooves, horns, claws, and feathers.\n\n• Collagen is another structural protein, but it is found primarily in connective tissues like skin, bones, tendons, and cartilage.\n• Cellulite is not a protein; it is a term used to describe the appearance of dimpled flesh caused by subcutaneous fat deposits.\n• Glycogen is a polysaccharide (a complex carbohydrate), not a protein, used by animals to store glucose.","whyWrongChoices":"Alternative options: cellulite, collagen, glycogen"}'::jsonb),
('mc:semolina flour is made from:::durum wheat', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'semolina flour is made from', 'Durum wheat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Semolina is a coarse flour made from durum wheat and is commonly used for pasta and some other wheat products.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Durum wheat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Semolina is a coarse flour made from durum wheat and is commonly used for pasta and some other wheat products.","whyWrongChoices":"Alternative options: Cassava starch, Rootcrop starch, Millet"}'::jsonb),
('mc:the protein found in human hair and fingernails as well as animal hooves, horns, and claws.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the protein found in human hair and fingernails as well as animal hooves, horns, and claws.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Keratin is a tough, fibrous structural protein that forms the primary component of human hair, fingernails, and the outer layer of skin, as well as animal hooves, horns, claws, and feathers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"keratin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Keratin is a tough, fibrous structural protein that forms the primary component of human hair, fingernails, and the outer layer of skin, as well as animal hooves, horns, claws, and feathers.\n\n• Collagen is another structural protein, but it is found primarily in connective tissues like skin, bones, tendons, and cartilage.\n• Cellulite is not a protein; it is a term used to describe the appearance of dimpled flesh caused by subcutaneous fat deposits.\n• Glycogen is a polysaccharide (a complex carbohydrate), not a protein, used by animals to store glucose.","whyWrongChoices":"Alternative options: cellulite, collagen, glycogen"}'::jsonb),
('mc:pancreatic juice contains the following enzyme/s::::trypsinogen', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pancreatic juice contains the following enzyme/s:', 'trypsinogen', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The pancreas synthesizes and secretes its protein-digesting enzymes in an inactive proenzyme (zymogen) form to prevent the enzymes from digesting the pancreas itself. Trypsinogen is secreted directly into the pancreatic juice. Once it arrives in the small intestine, it is activated into its working form, trypsin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"trypsinogen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The pancreas synthesizes and secretes its protein-digesting enzymes in an inactive proenzyme (zymogen) form to prevent the enzymes from digesting the pancreas itself. Trypsinogen is secreted directly into the pancreatic juice. Once it arrives in the small intestine, it is activated into its working form, trypsin.\n\n• Pepsinogen and pepsin are strictly found in gastric juice secreted by the stomach, not the pancreas.\n• Enterokinase (also called enteropeptidase) is a brush-border enzyme produced by the mucosal lining of the small intestine. Its entire job is to sit in the intestine and activate the incoming trypsinogen.","whyWrongChoices":"Alternative options: pepsinogen & pepsin, enterokinase, chymotrypsin"}'::jsonb),
('mc:pancreatic juice contains the following enzyme/s::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pancreatic juice contains the following enzyme/s:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The pancreas synthesizes and secretes its protein-digesting enzymes in an inactive proenzyme (zymogen) form to prevent the enzymes from digesting the pancreas itself. Trypsinogen is secreted directly into the pancreatic juice. Once it arrives in the small intestine, it is activated into its working form, trypsin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"trypsinogen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The pancreas synthesizes and secretes its protein-digesting enzymes in an inactive proenzyme (zymogen) form to prevent the enzymes from digesting the pancreas itself. Trypsinogen is secreted directly into the pancreatic juice. Once it arrives in the small intestine, it is activated into its working form, trypsin.\n\n• Pepsinogen and pepsin are strictly found in gastric juice secreted by the stomach, not the pancreas.\n• Enterokinase (also called enteropeptidase) is a brush-border enzyme produced by the mucosal lining of the small intestine. Its entire job is to sit in the intestine and activate the incoming trypsinogen.","whyWrongChoices":"Alternative options: pepsinogen & pepsin, enterokinase, chymotrypsin"}'::jsonb),
('mc:a cofactor that is a carrier of activated co2 and participates in both gluconeogenesis and fatty acid synthesis is::::biotin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a cofactor that is a carrier of activated co2 and participates in both gluconeogenesis and fatty acid synthesis is:', 'biotin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biotin (Vitamin B₇) functions as a specialized covalent cofactor for carboxylase enzymes, acting specifically as a carrier of activated carbon dioxide (CO₂).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biotin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biotin (Vitamin B₇) functions as a specialized covalent cofactor for carboxylase enzymes, acting specifically as a carrier of activated carbon dioxide (CO₂).\nIt plays a vital dual role in both of the specified metabolic pathways:\n\n• Gluconeogenesis: It serves as a cofactor for pyruvate carboxylase, which adds CO₂ to pyruvate to form oxaloacetate.\n• Fatty Acid Synthesis: It serves as a cofactor for acetyl-CoA carboxylase, which adds CO₂ to acetyl-CoA to form malonyl-CoA (the rate-limiting step of fatty acid synthesis).\n\n• Pantothenic acid (Vitamin B₅) is the precursor for Coenzyme A (CoA), which carries activated acyl groups, not CO₂.\n• Pyridoxal phosphate (PLP / Vitamin B₆) participates primarily in amino acid metabolism (such as transamination and decarboxylation reactions).\n• Flavin adenine dinucleotide (FAD / Vitamin B₂) functions as an electron carrier in oxidation-reduction (redox) reactions.","whyWrongChoices":"Alternative options: pyridoxal phosphate, flavin adenine dinucleotide, pantothenic acid"}'::jsonb),
('mc:the form of vitamin a needed in the synthesis of rhodopsin or the visual purple.:::retinal', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the form of vitamin a needed in the synthesis of rhodopsin or the visual purple.', 'retinal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Retinal (specifically in its 11-cis-retinal configuration) is the aldehyde form of vitamin A. It serves as the precise, light-absorbing chromophore that physically binds to the protein opsin to synthesize rhodopsin (visual purple) in the rod cells of the retina.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"retinal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Retinal (specifically in its 11-cis-retinal configuration) is the aldehyde form of vitamin A. It serves as the precise, light-absorbing chromophore that physically binds to the protein opsin to synthesize rhodopsin (visual purple) in the rod cells of the retina.","whyWrongChoices":"Alternative options: retinol, retinoic acid, beta-carotene"}'::jsonb),
('mc:a cofactor that is a carrier of activated co2 and participates in both gluconeogenesis and fatty acid synthesis is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a cofactor that is a carrier of activated co2 and participates in both gluconeogenesis and fatty acid synthesis is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Biotin (Vitamin B₇) functions as a specialized covalent cofactor for carboxylase enzymes, acting specifically as a carrier of activated carbon dioxide (CO₂).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"biotin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Biotin (Vitamin B₇) functions as a specialized covalent cofactor for carboxylase enzymes, acting specifically as a carrier of activated carbon dioxide (CO₂).\nIt plays a vital dual role in both of the specified metabolic pathways:\n\n• Gluconeogenesis: It serves as a cofactor for pyruvate carboxylase, which adds CO₂ to pyruvate to form oxaloacetate.\n• Fatty Acid Synthesis: It serves as a cofactor for acetyl-CoA carboxylase, which adds CO₂ to acetyl-CoA to form malonyl-CoA (the rate-limiting step of fatty acid synthesis).\n\n• Pantothenic acid (Vitamin B₅) is the precursor for Coenzyme A (CoA), which carries activated acyl groups, not CO₂.\n• Pyridoxal phosphate (PLP / Vitamin B₆) participates primarily in amino acid metabolism (such as transamination and decarboxylation reactions).\n• Flavin adenine dinucleotide (FAD / Vitamin B₂) functions as an electron carrier in oxidation-reduction (redox) reactions.","whyWrongChoices":"Alternative options: pyridoxal phosphate, flavin adenine dinucleotide, pantothenic acid"}'::jsonb),
('mc:it is defined as the psychological desire to find and eat food.:::appetite', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is defined as the psychological desire to find and eat food.', 'appetite', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Appetite is explicitly defined as the psychological desire to find and eat food. It is often triggered or stimulated by external cues, such as the sight, smell, or thought of food, even when the body does not physically need energy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"appetite\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Appetite is explicitly defined as the psychological desire to find and eat food. It is often triggered or stimulated by external cues, such as the sight, smell, or thought of food, even when the body does not physically need energy.\n\nUnlike appetite, hunger is the physiological (physical) drive or need for food. It is triggered by internal biological signals, such as an empty stomach, contractions, or drops in blood glucose levels.\n\n• Satiety: This refers to the state or feeling of fullness and satisfaction that occurs after eating, which inhibits the desire to eat until the next meal.\n• Palatability: This refers to how pleasurable or appealing a specific food tastes, smells, or feels in the mouth, which influences food selection but is not the desire itself.","whyWrongChoices":"Alternative options: hunger, satiety, palatability"}'::jsonb),
('mc:all are feeding problems prevalent in adolescence except::::gagging', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'all are feeding problems prevalent in adolescence except:', 'Gagging', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gagging is a feeding problem prevalent among preschool children.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gagging\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gagging is a feeding problem prevalent among preschool children.","whyWrongChoices":"Alternative options: Snacking, Non-traditional eating patterns, Meal skipping"}'::jsonb),
('mc:it is defined as the psychological desire to find and eat food.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is defined as the psychological desire to find and eat food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Appetite is explicitly defined as the psychological desire to find and eat food. It is often triggered or stimulated by external cues, such as the sight, smell, or thought of food, even when the body does not physically need energy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"appetite\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Appetite is explicitly defined as the psychological desire to find and eat food. It is often triggered or stimulated by external cues, such as the sight, smell, or thought of food, even when the body does not physically need energy.\n\nUnlike appetite, hunger is the physiological (physical) drive or need for food. It is triggered by internal biological signals, such as an empty stomach, contractions, or drops in blood glucose levels.\n\n• Satiety: This refers to the state or feeling of fullness and satisfaction that occurs after eating, which inhibits the desire to eat until the next meal.\n• Palatability: This refers to how pleasurable or appealing a specific food tastes, smells, or feels in the mouth, which influences food selection but is not the desire itself.","whyWrongChoices":"Alternative options: hunger, satiety, palatability"}'::jsonb),
('mc:which of the following is not a function of the kidneys?:::it activates vitamin a', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is not a function of the kidneys?', 'it activates vitamin A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The kidneys activate Vitamin D (converting it into calcitriol), not Vitamin A. Vitamin A is primarily stored and metabolized by the liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"it activates vitamin A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The kidneys activate Vitamin D (converting it into calcitriol), not Vitamin A. Vitamin A is primarily stored and metabolized by the liver.\n\n• Waste Elimination: The kidneys filter blood to remove metabolic waste products like urea, uric acid, and creatinine via urine.\n• Red Blood Cell Production: The kidneys release a hormone called erythropoietin (EPO), which stimulates the bone marrow to produce red blood cells.\n• Blood Pressure Regulation: The kidneys regulate blood pressure by managing fluid balance and releasing the enzyme renin as part of the renin-angiotensin-aldosterone system (RAAS).","whyWrongChoices":"Alternative options: it eliminates metabolic waste products, it regulates blood pressure, it aids in red blood cell production"}'::jsonb),
('mc:which of the following is not a function of the kidneys?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is not a function of the kidneys?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The kidneys activate Vitamin D (converting it into calcitriol), not Vitamin A. Vitamin A is primarily stored and metabolized by the liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"it activates vitamin A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The kidneys activate Vitamin D (converting it into calcitriol), not Vitamin A. Vitamin A is primarily stored and metabolized by the liver.\n\n• Waste Elimination: The kidneys filter blood to remove metabolic waste products like urea, uric acid, and creatinine via urine.\n• Red Blood Cell Production: The kidneys release a hormone called erythropoietin (EPO), which stimulates the bone marrow to produce red blood cells.\n• Blood Pressure Regulation: The kidneys regulate blood pressure by managing fluid balance and releasing the enzyme renin as part of the renin-angiotensin-aldosterone system (RAAS).","whyWrongChoices":"Alternative options: it eliminates metabolic waste products, it regulates blood pressure, it aids in red blood cell production"}'::jsonb),
('mc:carbohydrate digestion starts in the and is completed in the .:::mouth; small intestines', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'carbohydrate digestion starts in the and is completed in the .', 'mouth; small intestines', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Starts in the mouth: Carbohydrate digestion begins in the mouth, where mechanical chewing combines with the chemical action of salivary amylase to break down large starches into smaller sugars.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"mouth; small intestines\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Starts in the mouth: Carbohydrate digestion begins in the mouth, where mechanical chewing combines with the chemical action of salivary amylase to break down large starches into smaller sugars.\n\n• Completed in the small intestines: The process stops temporarily in the highly acidic stomach but is completed in the small intestine. Here, pancreatic amylase and brush border enzymes finish breaking down carbohydrates into basic sugars like glucose for absorption.","whyWrongChoices":"Alternative options: stomach; small intestines, mouth; large intestines, small intestines; large intestines"}'::jsonb),
('mc:carbohydrate digestion starts in the and is completed in the .:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'carbohydrate digestion starts in the and is completed in the .', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Starts in the mouth: Carbohydrate digestion begins in the mouth, where mechanical chewing combines with the chemical action of salivary amylase to break down large starches into smaller sugars.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"mouth; small intestines\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Starts in the mouth: Carbohydrate digestion begins in the mouth, where mechanical chewing combines with the chemical action of salivary amylase to break down large starches into smaller sugars.\n\n• Completed in the small intestines: The process stops temporarily in the highly acidic stomach but is completed in the small intestine. Here, pancreatic amylase and brush border enzymes finish breaking down carbohydrates into basic sugars like glucose for absorption.","whyWrongChoices":"Alternative options: stomach; small intestines, mouth; large intestines, small intestines; large intestines"}'::jsonb),
('mc:in an end-stage uremic patient, which of the following dietary management would you recommend for the patient’s maintenance regimen?:::40 grams protein diet', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in an end-stage uremic patient, which of the following dietary management would you recommend for the patient’s maintenance regimen?', '40 grams protein diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"End-stage renal disease (ESRD) results in the accumulation of nitrogenous waste products (urea, creatinine, uric acid) due to failing glomerular filtration. While non-dialyzed uremic patients require strict low-protein diets (0.6 to 0.8 g/kg/day) to delay uremic symptoms, patients on maintenance dialysis require higher protein intakes to counteract intradialytic amino acid losses and persistent catabolism induced by the dialysis procedure itself. A tailored moderate protein level, such as 40 grams or higher depending on body weight (with at least 50% high biological value proteins containing essential amino acids), ensures positive nitrogen balance, prevents visceral protein depletion, and limits the accumulation of uremic toxins between treatments.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"40 grams protein diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"End-stage renal disease (ESRD) results in the accumulation of nitrogenous waste products (urea, creatinine, uric acid) due to failing glomerular filtration. While non-dialyzed uremic patients require strict low-protein diets (0.6 to 0.8 g/kg/day) to delay uremic symptoms, patients on maintenance dialysis require higher protein intakes to counteract intradialytic amino acid losses and persistent catabolism induced by the dialysis procedure itself. A tailored moderate protein level, such as 40 grams or higher depending on body weight (with at least 50% high biological value proteins containing essential amino acids), ensures positive nitrogen balance, prevents visceral protein depletion, and limits the accumulation of uremic toxins between treatments.","whyWrongChoices":"Alternative options: protein-free diet, 20 grams protein diet, amino acid supplementation for better protein control"}'::jsonb),
('mc:in an end-stage uremic patient, which of the following dietary management would you recommend for the patient’s maintenance regimen?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in an end-stage uremic patient, which of the following dietary management would you recommend for the patient’s maintenance regimen?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"End-stage renal disease (ESRD) results in the accumulation of nitrogenous waste products (urea, creatinine, uric acid) due to failing glomerular filtration. While non-dialyzed uremic patients require strict low-protein diets (0.6 to 0.8 g/kg/day) to delay uremic symptoms, patients on maintenance dialysis require higher protein intakes to counteract intradialytic amino acid losses and persistent catabolism induced by the dialysis procedure itself. A tailored moderate protein level, such as 40 grams or higher depending on body weight (with at least 50% high biological value proteins containing essential amino acids), ensures positive nitrogen balance, prevents visceral protein depletion, and limits the accumulation of uremic toxins between treatments.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"40 grams protein diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"End-stage renal disease (ESRD) results in the accumulation of nitrogenous waste products (urea, creatinine, uric acid) due to failing glomerular filtration. While non-dialyzed uremic patients require strict low-protein diets (0.6 to 0.8 g/kg/day) to delay uremic symptoms, patients on maintenance dialysis require higher protein intakes to counteract intradialytic amino acid losses and persistent catabolism induced by the dialysis procedure itself. A tailored moderate protein level, such as 40 grams or higher depending on body weight (with at least 50% high biological value proteins containing essential amino acids), ensures positive nitrogen balance, prevents visceral protein depletion, and limits the accumulation of uremic toxins between treatments.","whyWrongChoices":"Alternative options: protein-free diet, 20 grams protein diet, amino acid supplementation for better protein control"}'::jsonb),
('mc:an npo diet is indicated prior to surgery to::::prevent vomiting', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an npo diet is indicated prior to surgery to:', 'prevent vomiting', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• The Risk of Anesthesia: General anesthesia relaxes the body''s protective airway reflexes, including the gag and cough reflexes, and relaxes the lower esophageal sphincter.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"prevent vomiting\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• The Risk of Anesthesia: General anesthesia relaxes the body''s protective airway reflexes, including the gag and cough reflexes, and relaxes the lower esophageal sphincter.\n• Prevention of Aspiration: If a patient has food or fluid in their stomach during surgery, they are at a very high risk of vomiting or experiencing passive regurgitation while unconscious. Because their airway reflexes are suppressed, the acidic stomach contents can easily enter the lungs (pulmonary aspiration), leading to severe aspiration pneumonia, chemical pneumonitis, or airway obstruction. Going NPO (Nothing by Mouth) ensures the stomach is empty and safe prior to the procedure.","whyWrongChoices":"Alternative options: avoid dehydration, reduce bowel movement, none of the above"}'::jsonb),
('mc:an npo diet is indicated prior to surgery to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an npo diet is indicated prior to surgery to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• The Risk of Anesthesia: General anesthesia relaxes the body''s protective airway reflexes, including the gag and cough reflexes, and relaxes the lower esophageal sphincter.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"prevent vomiting\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• The Risk of Anesthesia: General anesthesia relaxes the body''s protective airway reflexes, including the gag and cough reflexes, and relaxes the lower esophageal sphincter.\n• Prevention of Aspiration: If a patient has food or fluid in their stomach during surgery, they are at a very high risk of vomiting or experiencing passive regurgitation while unconscious. Because their airway reflexes are suppressed, the acidic stomach contents can easily enter the lungs (pulmonary aspiration), leading to severe aspiration pneumonia, chemical pneumonitis, or airway obstruction. Going NPO (Nothing by Mouth) ensures the stomach is empty and safe prior to the procedure.","whyWrongChoices":"Alternative options: avoid dehydration, reduce bowel movement, none of the above"}'::jsonb),
('mc:a malabsorption problem brought about by shorter and less number of intestinal villi::::non-tropical sprue', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a malabsorption problem brought about by shorter and less number of intestinal villi:', 'non-tropical sprue', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Non-tropical sprue (commonly known as celiac disease or gluten-sensitive enteropathy) is an autoimmune disorder triggered by ingesting gluten. The immune system mistakenly attacks the lining of the small intestine, leading to severe inflammation, crypt hyperplasia, and structural damage characterized by the shortening, flattening, and reduction in the number of intestinal villi (villous atrophy). Since villi are responsible for expanding the surface area of the gut, their damage drastically impairs nutrient absorption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"non-tropical sprue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Non-tropical sprue (commonly known as celiac disease or gluten-sensitive enteropathy) is an autoimmune disorder triggered by ingesting gluten. The immune system mistakenly attacks the lining of the small intestine, leading to severe inflammation, crypt hyperplasia, and structural damage characterized by the shortening, flattening, and reduction in the number of intestinal villi (villous atrophy). Since villi are responsible for expanding the surface area of the gut, their damage drastically impairs nutrient absorption.","whyWrongChoices":"Alternative options: ulcerative colitis, tropical sprue, short gut syndrome"}'::jsonb),
('mc:a malabsorption problem brought about by shorter and less number of intestinal villi::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a malabsorption problem brought about by shorter and less number of intestinal villi:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Non-tropical sprue (commonly known as celiac disease or gluten-sensitive enteropathy) is an autoimmune disorder triggered by ingesting gluten. The immune system mistakenly attacks the lining of the small intestine, leading to severe inflammation, crypt hyperplasia, and structural damage characterized by the shortening, flattening, and reduction in the number of intestinal villi (villous atrophy). Since villi are responsible for expanding the surface area of the gut, their damage drastically impairs nutrient absorption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"non-tropical sprue\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Non-tropical sprue (commonly known as celiac disease or gluten-sensitive enteropathy) is an autoimmune disorder triggered by ingesting gluten. The immune system mistakenly attacks the lining of the small intestine, leading to severe inflammation, crypt hyperplasia, and structural damage characterized by the shortening, flattening, and reduction in the number of intestinal villi (villous atrophy). Since villi are responsible for expanding the surface area of the gut, their damage drastically impairs nutrient absorption.","whyWrongChoices":"Alternative options: ulcerative colitis, tropical sprue, short gut syndrome"}'::jsonb),
('mc:the form of vitamin a needed in the synthesis of rhodopsin or the visual purple.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the form of vitamin a needed in the synthesis of rhodopsin or the visual purple.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Retinal (specifically in its 11-cis-retinal configuration) is the aldehyde form of vitamin A. It serves as the precise, light-absorbing chromophore that physically binds to the protein opsin to synthesize rhodopsin (visual purple) in the rod cells of the retina.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"retinal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Retinal (specifically in its 11-cis-retinal configuration) is the aldehyde form of vitamin A. It serves as the precise, light-absorbing chromophore that physically binds to the protein opsin to synthesize rhodopsin (visual purple) in the rod cells of the retina.","whyWrongChoices":"Alternative options: retinol, retinoic acid, beta-carotene"}'::jsonb),
('mc:considered “neutral foods” when following either an alkaline ash or an acid ash diet::::butter, candy, sugar', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'considered “neutral foods” when following either an alkaline ash or an acid ash diet:', 'butter, candy, sugar', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Foods that are primarily composed of pure fats, oils, or refined sugars leave behind no mineral residue that can alter urinary pH. Therefore, butter, cooking oils, margarine, plain candies, and table sugar are classified as strictly neutral. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"butter, candy, sugar\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Foods that are primarily composed of pure fats, oils, or refined sugars leave behind no mineral residue that can alter urinary pH. Therefore, butter, cooking oils, margarine, plain candies, and table sugar are classified as strictly neutral. \n\n• Acid Ash Foods: Foods high in protein, phosphorus, and sulfur leave behind an acidic residue. This includes meat, fish, poultry, eggs, and whole grains.\n• Alkaline Ash Foods: Foods rich in minerals like magnesium, potassium, and calcium leave behind an alkaline residue. This includes almost all fruits and vegetables (even acidic ones like lemons, because the organic citric acid is fully oxidized into water and CO₂, leaving alkaline minerals behind).","whyWrongChoices":"Alternative options: fruits and vegetables, whole grains and eggs, meat, fish, poultry"}'::jsonb),
('mc:considered “neutral foods” when following either an alkaline ash or an acid ash diet::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'considered “neutral foods” when following either an alkaline ash or an acid ash diet:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Foods that are primarily composed of pure fats, oils, or refined sugars leave behind no mineral residue that can alter urinary pH. Therefore, butter, cooking oils, margarine, plain candies, and table sugar are classified as strictly neutral. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"butter, candy, sugar\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Foods that are primarily composed of pure fats, oils, or refined sugars leave behind no mineral residue that can alter urinary pH. Therefore, butter, cooking oils, margarine, plain candies, and table sugar are classified as strictly neutral. \n\n• Acid Ash Foods: Foods high in protein, phosphorus, and sulfur leave behind an acidic residue. This includes meat, fish, poultry, eggs, and whole grains.\n• Alkaline Ash Foods: Foods rich in minerals like magnesium, potassium, and calcium leave behind an alkaline residue. This includes almost all fruits and vegetables (even acidic ones like lemons, because the organic citric acid is fully oxidized into water and CO₂, leaving alkaline minerals behind).","whyWrongChoices":"Alternative options: fruits and vegetables, whole grains and eggs, meat, fish, poultry"}'::jsonb),
('mc:refer to the following information. based on the fel, the diet of a burn patient contains the following meal pattern for lunch: 90g fried chicken; 160g rice; 45g sauteed squash; 250g fresh milk; and 103g ripe mango. how much is the protein content of the meal?:::37 g', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refer to the following information. based on the fel, the diet of a burn patient contains the following meal pattern for lunch: 90g fried chicken; 160g rice; 45g sauteed squash; 250g fresh milk; and 103g ripe mango. how much is the protein content of the meal?', '37 g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• 90g Fried Chicken: 90 grams divided by 30 grams per exchange equals 3 exchanges. 3 exchanges multiplied by 8 grams of protein equals 24 grams of protein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"37 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• 90g Fried Chicken: 90 grams divided by 30 grams per exchange equals 3 exchanges. 3 exchanges multiplied by 8 grams of protein equals 24 grams of protein.\n• 160g Rice: 160 grams divided by 80 grams per exchange equals 2 exchanges. 2 exchanges multiplied by 2 grams of protein equals 4 grams of protein.\n• 45g Sauteed Squash: 45 grams equals exactly 1 exchange of vegetable. 1 exchange multiplied by 1 gram of protein equals 1 gram of protein.\n• 250g Fresh Milk: 250 grams equals 1 exchange of milk. 1 exchange multiplied by 8 grams of protein equals 8 grams of protein.\n• 103g Ripe Mango: 1 exchange of fruit equals 0 grams of protein.\n\nTotal Calculation:\n24 grams (Chicken) + 4 grams (Rice) + 1 gram (Squash) + 8 grams (Milk) + 0 grams (Mango) = 37 grams of protein","whyWrongChoices":"Alternative options: 36 g, 35 g, 45 g"}'::jsonb),
('mc:refer to the following information. based on the fel, the diet of a burn patient contains the following meal pattern for lunch: 90g fried chicken; 160g rice; 45g sauteed squash; 250g fresh milk; and 103g ripe mango. how much is the protein content of the meal?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refer to the following information. based on the fel, the diet of a burn patient contains the following meal pattern for lunch: 90g fried chicken; 160g rice; 45g sauteed squash; 250g fresh milk; and 103g ripe mango. how much is the protein content of the meal?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• 90g Fried Chicken: 90 grams divided by 30 grams per exchange equals 3 exchanges. 3 exchanges multiplied by 8 grams of protein equals 24 grams of protein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"37 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• 90g Fried Chicken: 90 grams divided by 30 grams per exchange equals 3 exchanges. 3 exchanges multiplied by 8 grams of protein equals 24 grams of protein.\n• 160g Rice: 160 grams divided by 80 grams per exchange equals 2 exchanges. 2 exchanges multiplied by 2 grams of protein equals 4 grams of protein.\n• 45g Sauteed Squash: 45 grams equals exactly 1 exchange of vegetable. 1 exchange multiplied by 1 gram of protein equals 1 gram of protein.\n• 250g Fresh Milk: 250 grams equals 1 exchange of milk. 1 exchange multiplied by 8 grams of protein equals 8 grams of protein.\n• 103g Ripe Mango: 1 exchange of fruit equals 0 grams of protein.\n\nTotal Calculation:\n24 grams (Chicken) + 4 grams (Rice) + 1 gram (Squash) + 8 grams (Milk) + 0 grams (Mango) = 37 grams of protein","whyWrongChoices":"Alternative options: 36 g, 35 g, 45 g"}'::jsonb),
('mc:how much sodium is 3 grams of salt?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'how much sodium is 3 grams of salt?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Table salt (sodium chloride) consists of approximately 40% sodium and 60% chloride.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1,200\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Table salt (sodium chloride) consists of approximately 40% sodium and 60% chloride.\n\nTo find the amount of sodium in 3 grams of salt:\n• Convert 3 grams of salt to milligrams: 3 grams = 3,000 milligrams.\n• Calculate the sodium portion: 3,000 milligrams multiplied by 0.40 = 1,200 milligrams of sodium.","whyWrongChoices":"Alternative options: 1,400, 1,600, 1,800"}'::jsonb),
('mc:in the small intestines::::starch is digested by pancreatic amylase into maltose', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in the small intestines:', 'starch is digested by pancreatic amylase into maltose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While starch digestion begins in the mouth via salivary amylase, it is halted in the highly acidic stomach. Once the food enters the small intestine (specifically the duodenum), the pancreas secretes pancreatic amylase. This powerful enzyme breaks down remaining complex starches and polysaccharides into the disaccharide maltose and other short glucose polymers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"starch is digested by pancreatic amylase into maltose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While starch digestion begins in the mouth via salivary amylase, it is halted in the highly acidic stomach. Once the food enters the small intestine (specifically the duodenum), the pancreas secretes pancreatic amylase. This powerful enzyme breaks down remaining complex starches and polysaccharides into the disaccharide maltose and other short glucose polymers.","whyWrongChoices":"Alternative options: cellulose fiber is digested into monosaccharides, fat is not hydrolyzed, protein is hydrolyzed by bile acids into amino acids"}'::jsonb),
('mc:in the small intestines::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in the small intestines:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While starch digestion begins in the mouth via salivary amylase, it is halted in the highly acidic stomach. Once the food enters the small intestine (specifically the duodenum), the pancreas secretes pancreatic amylase. This powerful enzyme breaks down remaining complex starches and polysaccharides into the disaccharide maltose and other short glucose polymers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"starch is digested by pancreatic amylase into maltose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While starch digestion begins in the mouth via salivary amylase, it is halted in the highly acidic stomach. Once the food enters the small intestine (specifically the duodenum), the pancreas secretes pancreatic amylase. This powerful enzyme breaks down remaining complex starches and polysaccharides into the disaccharide maltose and other short glucose polymers.","whyWrongChoices":"Alternative options: cellulose fiber is digested into monosaccharides, fat is not hydrolyzed, protein is hydrolyzed by bile acids into amino acids"}'::jsonb),
('mc:a type of copd in which the lungs lose their elasticity and the client has difficulty breathing.:::emphysema', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a type of copd in which the lungs lose their elasticity and the client has difficulty breathing.', 'emphysema', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Emphysema is a major form of Chronic Obstructive Pulmonary Disease (COPD) characterized by the permanent destruction of the alveolar walls and pulmonary capillaries. This architectural destruction leads to a severe loss of lung elasticity. Without elastic recoil, the small airways collapse during exhalation, trapping air inside the lungs (hyperinflation) and making it deeply difficult for the patient to breathe.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"emphysema\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Emphysema is a major form of Chronic Obstructive Pulmonary Disease (COPD) characterized by the permanent destruction of the alveolar walls and pulmonary capillaries. This architectural destruction leads to a severe loss of lung elasticity. Without elastic recoil, the small airways collapse during exhalation, trapping air inside the lungs (hyperinflation) and making it deeply difficult for the patient to breathe.\n\n• Bronchitis: Chronic bronchitis is characterized by chronic inflammation, swelling, and narrowing of the lining of the bronchial airways. Its primary presentation is a persistent, productive cough driven by severe mucus hypersecretion rather than a structural loss of lung tissue elasticity.","whyWrongChoices":"Alternative options: bronchitis, both a & b, none of the above"}'::jsonb),
('mc:which of the following is a branched-chain amino acid?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is a branched-chain amino acid?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"There are exactly three branched-chain amino acids (BCAAs) among the standard amino acids: leucine, isoleucine, and valine. They are named for their unique, branching aliphatic hydrocarbon side-chain molecular structure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"isoleucine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"There are exactly three branched-chain amino acids (BCAAs) among the standard amino acids: leucine, isoleucine, and valine. They are named for their unique, branching aliphatic hydrocarbon side-chain molecular structure.","whyWrongChoices":"Alternative options: alanine, lysine, glutamine"}'::jsonb),
('mc:a type of copd in which the lungs lose their elasticity and the client has difficulty breathing.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a type of copd in which the lungs lose their elasticity and the client has difficulty breathing.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Emphysema is a major form of Chronic Obstructive Pulmonary Disease (COPD) characterized by the permanent destruction of the alveolar walls and pulmonary capillaries. This architectural destruction leads to a severe loss of lung elasticity. Without elastic recoil, the small airways collapse during exhalation, trapping air inside the lungs (hyperinflation) and making it deeply difficult for the patient to breathe.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"emphysema\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Emphysema is a major form of Chronic Obstructive Pulmonary Disease (COPD) characterized by the permanent destruction of the alveolar walls and pulmonary capillaries. This architectural destruction leads to a severe loss of lung elasticity. Without elastic recoil, the small airways collapse during exhalation, trapping air inside the lungs (hyperinflation) and making it deeply difficult for the patient to breathe.\n\n• Bronchitis: Chronic bronchitis is characterized by chronic inflammation, swelling, and narrowing of the lining of the bronchial airways. Its primary presentation is a persistent, productive cough driven by severe mucus hypersecretion rather than a structural loss of lung tissue elasticity.","whyWrongChoices":"Alternative options: bronchitis, both a & b, none of the above"}'::jsonb),
('mc:tube feedings can be discontinued gradually when::::the client is able to eat foods or drink formula in sufficient amounts', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'tube feedings can be discontinued gradually when:', 'the client is able to eat foods or drink formula in sufficient amounts', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Discontinuing a tube feeding (enteral nutrition) is a step-by-step process. Clinicians typically look for the patient to meet at least two-thirds (60% to 66%) of their daily caloric and fluid needs via oral intake (eating solid food or drinking nutrition shakes) before completely pulling or stopping the tube feeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the client is able to eat foods or drink formula in sufficient amounts\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Discontinuing a tube feeding (enteral nutrition) is a step-by-step process. Clinicians typically look for the patient to meet at least two-thirds (60% to 66%) of their daily caloric and fluid needs via oral intake (eating solid food or drinking nutrition shakes) before completely pulling or stopping the tube feeding.","whyWrongChoices":"Alternative options: as soon as the medical condition resolves, planning for discharge begins, the client experiences hunger"}'::jsonb),
('mc:tube feedings can be discontinued gradually when::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'tube feedings can be discontinued gradually when:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Discontinuing a tube feeding (enteral nutrition) is a step-by-step process. Clinicians typically look for the patient to meet at least two-thirds (60% to 66%) of their daily caloric and fluid needs via oral intake (eating solid food or drinking nutrition shakes) before completely pulling or stopping the tube feeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the client is able to eat foods or drink formula in sufficient amounts\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Discontinuing a tube feeding (enteral nutrition) is a step-by-step process. Clinicians typically look for the patient to meet at least two-thirds (60% to 66%) of their daily caloric and fluid needs via oral intake (eating solid food or drinking nutrition shakes) before completely pulling or stopping the tube feeding.","whyWrongChoices":"Alternative options: as soon as the medical condition resolves, planning for discharge begins, the client experiences hunger"}'::jsonb),
('mc:the amount of kcal/kbw for bulimic patients on a weight maintenance diet::::25 kcal/kdbw', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the amount of kcal/kbw for bulimic patients on a weight maintenance diet:', '25 kcal/KDBW', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Research demonstrates that patients with bulimia nervosa who are in a weight-stable or weight-maintenance phase often have a significantly depressed metabolic rate. This is primarily caused by a history of chronic, severe energy restriction, chaotic eating cycles, and purging behaviors.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"25 kcal/KDBW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Research demonstrates that patients with bulimia nervosa who are in a weight-stable or weight-maintenance phase often have a significantly depressed metabolic rate. This is primarily caused by a history of chronic, severe energy restriction, chaotic eating cycles, and purging behaviors.\n\nWhile a typical healthy, sedentary adult requires approximately 30 kcal/kg/day for weight maintenance, clinical evaluations show that weight-stable bulimic patients require fewer calories—typically averaging around 22 to 25 kcal per kilogram of body weight to maintain their weight.","whyWrongChoices":"Alternative options: 20 kcal/KDBW, 35 kcal/KDBW, 30 kcal/KDBW"}'::jsonb),
('mc:the amount of kcal/kbw for bulimic patients on a weight maintenance diet::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the amount of kcal/kbw for bulimic patients on a weight maintenance diet:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Research demonstrates that patients with bulimia nervosa who are in a weight-stable or weight-maintenance phase often have a significantly depressed metabolic rate. This is primarily caused by a history of chronic, severe energy restriction, chaotic eating cycles, and purging behaviors.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"25 kcal/KDBW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Research demonstrates that patients with bulimia nervosa who are in a weight-stable or weight-maintenance phase often have a significantly depressed metabolic rate. This is primarily caused by a history of chronic, severe energy restriction, chaotic eating cycles, and purging behaviors.\n\nWhile a typical healthy, sedentary adult requires approximately 30 kcal/kg/day for weight maintenance, clinical evaluations show that weight-stable bulimic patients require fewer calories—typically averaging around 22 to 25 kcal per kilogram of body weight to maintain their weight.","whyWrongChoices":"Alternative options: 20 kcal/KDBW, 35 kcal/KDBW, 30 kcal/KDBW"}'::jsonb),
('mc:a patient with a bmi of 42 will benefit from which diet prescription?:::1200 kcal, 55% kcal from cho, fat restricted', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a patient with a bmi of 42 will benefit from which diet prescription?', '1200 kcal, 55% kcal from CHO, fat restricted', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In traditional dietetic practice, a 1200 kcal diet is considered the gold-standard baseline weight-reduction diet for adults. It is widely recognized as the lowest safe calorie level that an individual can consume while still being able to meet all their essential vitamin and mineral requirements without mandatory medical supplementation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1200 kcal, 55% kcal from CHO, fat restricted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In traditional dietetic practice, a 1200 kcal diet is considered the gold-standard baseline weight-reduction diet for adults. It is widely recognized as the lowest safe calorie level that an individual can consume while still being able to meet all their essential vitamin and mineral requirements without mandatory medical supplementation.\n\n\"Fat Restricted\" over Percentage Targets: Classic medical diet prescriptions for severe obesity prioritize explicit qualitative restrictions like \"fat restricted\" or \"low fat\" rather than precise percentage numbers. Because fat is the most calorie-dense macronutrient (9 kcal per gram), strictly restricting visible fats, fried foods, and high-fat items is the most direct clinical method used to ensure the patient adheres to a low-calorie limit.\n\nMacronutrient Balance: Keeping carbohydrates at 55% ensures the patient receives enough complex carbohydrates to maintain energy levels and prevent ketosis, while the remaining calories are split between protein and minimal essential fats.","whyWrongChoices":"Alternative options: 800 kcal, 55% kcal from CHO, 25% from fat, 1000 kcal, 55% kcal from CHO, 12% from protein, 1300 kcal, 55% kcal from CHO, 25% from fat"}'::jsonb),
('mc:a patient with a bmi of 42 will benefit from which diet prescription?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a patient with a bmi of 42 will benefit from which diet prescription?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In traditional dietetic practice, a 1200 kcal diet is considered the gold-standard baseline weight-reduction diet for adults. It is widely recognized as the lowest safe calorie level that an individual can consume while still being able to meet all their essential vitamin and mineral requirements without mandatory medical supplementation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1200 kcal, 55% kcal from CHO, fat restricted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In traditional dietetic practice, a 1200 kcal diet is considered the gold-standard baseline weight-reduction diet for adults. It is widely recognized as the lowest safe calorie level that an individual can consume while still being able to meet all their essential vitamin and mineral requirements without mandatory medical supplementation.\n\n\"Fat Restricted\" over Percentage Targets: Classic medical diet prescriptions for severe obesity prioritize explicit qualitative restrictions like \"fat restricted\" or \"low fat\" rather than precise percentage numbers. Because fat is the most calorie-dense macronutrient (9 kcal per gram), strictly restricting visible fats, fried foods, and high-fat items is the most direct clinical method used to ensure the patient adheres to a low-calorie limit.\n\nMacronutrient Balance: Keeping carbohydrates at 55% ensures the patient receives enough complex carbohydrates to maintain energy levels and prevent ketosis, while the remaining calories are split between protein and minimal essential fats.","whyWrongChoices":"Alternative options: 800 kcal, 55% kcal from CHO, 25% from fat, 1000 kcal, 55% kcal from CHO, 12% from protein, 1300 kcal, 55% kcal from CHO, 25% from fat"}'::jsonb),
('mc:a series of proteins that serve as electron “carriers”::::oxidative phosphorylation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a series of proteins that serve as electron “carriers”:', 'oxidative phosphorylation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question describes the Electron Transport Chain (ETC), which consists of a series of protein complexes embedded in the inner mitochondrial membrane. These proteins act as sequential \"carriers,\" passing electrons down a chain to establish a proton gradient that ultimately drives the synthesis of ATP.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oxidative phosphorylation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question describes the Electron Transport Chain (ETC), which consists of a series of protein complexes embedded in the inner mitochondrial membrane. These proteins act as sequential \"carriers,\" passing electrons down a chain to establish a proton gradient that ultimately drives the synthesis of ATP.\n\nIn standard multiple-choice configurations, the Electron Transport Chain is grouped under the overarching stage of oxidative phosphorylation.\n\n• Adenosine triphosphate (ATP): This is the final high-energy chemical product generated by cellular respiration, not a structural protein chain.\n• Gluconeogenesis: This is a metabolic pathway by which the liver manufactures glucose from non-carbohydrate precursors during periods of fasting.\n• Tricarboxylic acid cycle (Krebs Cycle): This is a series of enzymatic reactions in the mitochondrial matrix that oxidizes acetyl-CoA to produce the temporary electron-carrier molecules (NADH and FADH₂), but the physical chain of carrier proteins itself resides in the next step.","whyWrongChoices":"Alternative options: gluconeogenesis, adenosine triphosphate, tricarboxylic acid cycle"}'::jsonb),
('mc:a series of proteins that serve as electron “carriers”::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a series of proteins that serve as electron “carriers”:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question describes the Electron Transport Chain (ETC), which consists of a series of protein complexes embedded in the inner mitochondrial membrane. These proteins act as sequential \"carriers,\" passing electrons down a chain to establish a proton gradient that ultimately drives the synthesis of ATP.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oxidative phosphorylation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question describes the Electron Transport Chain (ETC), which consists of a series of protein complexes embedded in the inner mitochondrial membrane. These proteins act as sequential \"carriers,\" passing electrons down a chain to establish a proton gradient that ultimately drives the synthesis of ATP.\n\nIn standard multiple-choice configurations, the Electron Transport Chain is grouped under the overarching stage of oxidative phosphorylation.\n\n• Adenosine triphosphate (ATP): This is the final high-energy chemical product generated by cellular respiration, not a structural protein chain.\n• Gluconeogenesis: This is a metabolic pathway by which the liver manufactures glucose from non-carbohydrate precursors during periods of fasting.\n• Tricarboxylic acid cycle (Krebs Cycle): This is a series of enzymatic reactions in the mitochondrial matrix that oxidizes acetyl-CoA to produce the temporary electron-carrier molecules (NADH and FADH₂), but the physical chain of carrier proteins itself resides in the next step.","whyWrongChoices":"Alternative options: gluconeogenesis, adenosine triphosphate, tricarboxylic acid cycle"}'::jsonb),
('mc:it is referred to as preformed vitamin a::::retinol', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is referred to as preformed vitamin a:', 'retinol', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This refers to the active, \"ready-to-use\" form of vitamin A that is found naturally in animal-derived foods (such as liver, eggs, and dairy). Retinol (along with its storage form, retinyl esters) is the specific compound widely designated as \"preformed vitamin A\" in nutritional science.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"retinol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This refers to the active, \"ready-to-use\" form of vitamin A that is found naturally in animal-derived foods (such as liver, eggs, and dairy). Retinol (along with its storage form, retinyl esters) is the specific compound widely designated as \"preformed vitamin A\" in nutritional science.\n\nOnce inside the body, retinol can be converted into retinal (essential for vision) and then further oxidized into retinoic acid (essential for gene regulation). While these are active retinoids, retinol is the primary preformed dietary source.\n\nMeanwhile, Beta-carotene is a plant pigment classified as provitamin A. It is a precursor that the body must first chemically cleave and convert into active vitamin A before it can be used.","whyWrongChoices":"Alternative options: retinoic acid, beta-carotene, retinal"}'::jsonb),
('mc:it is referred to as preformed vitamin a::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is referred to as preformed vitamin a:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This refers to the active, \"ready-to-use\" form of vitamin A that is found naturally in animal-derived foods (such as liver, eggs, and dairy). Retinol (along with its storage form, retinyl esters) is the specific compound widely designated as \"preformed vitamin A\" in nutritional science.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"retinol\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This refers to the active, \"ready-to-use\" form of vitamin A that is found naturally in animal-derived foods (such as liver, eggs, and dairy). Retinol (along with its storage form, retinyl esters) is the specific compound widely designated as \"preformed vitamin A\" in nutritional science.\n\nOnce inside the body, retinol can be converted into retinal (essential for vision) and then further oxidized into retinoic acid (essential for gene regulation). While these are active retinoids, retinol is the primary preformed dietary source.\n\nMeanwhile, Beta-carotene is a plant pigment classified as provitamin A. It is a precursor that the body must first chemically cleave and convert into active vitamin A before it can be used.","whyWrongChoices":"Alternative options: retinoic acid, beta-carotene, retinal"}'::jsonb),
('mc:preferred source of energy in copd::::fats', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'preferred source of energy in copd:', 'fats', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients with Chronic Obstructive Pulmonary Disease (COPD) struggle to exhale carbon dioxide (CO₂). Fats are the preferred energy source because they have a low Respiratory Quotient (around 0.7). This means that when the body metabolizes fats for energy, it produces less CO₂ per molecule of oxygen consumed compared to other macronutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"fats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients with Chronic Obstructive Pulmonary Disease (COPD) struggle to exhale carbon dioxide (CO₂). Fats are the preferred energy source because they have a low Respiratory Quotient (around 0.7). This means that when the body metabolizes fats for energy, it produces less CO₂ per molecule of oxygen consumed compared to other macronutrients.\n\nMeanwhile, Carbohydrates have an RQ of 1.0, meaning they produce the highest amount of CO₂ waste when broken down. This places an extra load on already compromised lungs, leading to respiratory distress.\n\nA high-fat, low-carbohydrate diet helps reduce the overall burden on a COPD patient''s respiratory system while still providing adequate calories to fight tissue wasting.","whyWrongChoices":"Alternative options: protein, carbohydrates, all of the above"}'::jsonb),
('mc:preferred source of energy in copd::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'preferred source of energy in copd:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Patients with Chronic Obstructive Pulmonary Disease (COPD) struggle to exhale carbon dioxide (CO₂). Fats are the preferred energy source because they have a low Respiratory Quotient (around 0.7). This means that when the body metabolizes fats for energy, it produces less CO₂ per molecule of oxygen consumed compared to other macronutrients.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"fats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Patients with Chronic Obstructive Pulmonary Disease (COPD) struggle to exhale carbon dioxide (CO₂). Fats are the preferred energy source because they have a low Respiratory Quotient (around 0.7). This means that when the body metabolizes fats for energy, it produces less CO₂ per molecule of oxygen consumed compared to other macronutrients.\n\nMeanwhile, Carbohydrates have an RQ of 1.0, meaning they produce the highest amount of CO₂ waste when broken down. This places an extra load on already compromised lungs, leading to respiratory distress.\n\nA high-fat, low-carbohydrate diet helps reduce the overall burden on a COPD patient''s respiratory system while still providing adequate calories to fight tissue wasting.","whyWrongChoices":"Alternative options: protein, carbohydrates, all of the above"}'::jsonb)
