INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:a cholesterol level of 240 mg/dl needs treatment with::::diet, exercise, & drugs', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a cholesterol level of 240 mg/dl needs treatment with:', 'diet, exercise, & drugs', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diet, exercise, & drugs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.\n\nOnce total cholesterol hits the high threshold (240 mg/dL), guidelines recommend a multi-pronged medical intervention:\n• Diet & Exercise: Initial and continuing therapeutic lifestyle changes—such as reducing saturated and trans fats, increasing dietary fiber, and initiating regular cardio—form the baseline of managing lipid profiles.\n• Drugs: Because a level of 240 mg/dL significantly elevates the risk for coronary heart disease, stroke, and atherosclerosis, lifestyle changes alone are often insufficient. Pharmacological intervention (most commonly statins) is prescribed in tandem to inhibit hepatic cholesterol production and aggressively pull down circulating lipid levels.","whyWrongChoices":"Alternative options: diet, drugs, diet and drugs"}'::jsonb),
('mc:a cholesterol level of 240 mg/dl needs treatment with::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a cholesterol level of 240 mg/dl needs treatment with:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diet, exercise, & drugs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In adults, a total cholesterol level below 200 mg/dL is desirable. A level between 200 and 239 mg/dL is considered borderline high, and a level of 240 mg/dL or higher is officially classified as high.\n\nOnce total cholesterol hits the high threshold (240 mg/dL), guidelines recommend a multi-pronged medical intervention:\n• Diet & Exercise: Initial and continuing therapeutic lifestyle changes—such as reducing saturated and trans fats, increasing dietary fiber, and initiating regular cardio—form the baseline of managing lipid profiles.\n• Drugs: Because a level of 240 mg/dL significantly elevates the risk for coronary heart disease, stroke, and atherosclerosis, lifestyle changes alone are often insufficient. Pharmacological intervention (most commonly statins) is prescribed in tandem to inhibit hepatic cholesterol production and aggressively pull down circulating lipid levels.","whyWrongChoices":"Alternative options: diet, drugs, diet and drugs"}'::jsonb),
('mc:the most practical type of storage in small stores is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the most practical type of storage in small stores is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Reach-in units are used to store food products at point-of-use or used in central storage units in small operations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Reach-in chiller\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Reach-in units are used to store food products at point-of-use or used in central storage units in small operations.","whyWrongChoices":"Alternative options: Blast chiller, Walk-in chiller, Chest freezer"}'::jsonb),
('mc:the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.:::provitamin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.', 'provitamin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"provitamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).\n\n\t• Preformed vitamin: This describes a vitamin that is already in its fully active, biological state when ingested (such as retinol in animal products) and requires no internal conversion.\n\t• Vitamer: Vitamers are the multiple structural variations or chemical forms of a single vitamin that all possess similar vitamin activity (e.g., pyridoxine, pyridoxal, and pyridoxamine are all vitamers of Vitamin B₆).\n\t• Antivitamin: A chemical compound that actively blocks, inhibits, or destroys the biological action of a vitamin.","whyWrongChoices":"Alternative options: antivitamin, vitamer, preformed vitamin"}'::jsonb),
('mc:the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the form of vitamin that has no vitamin activity unless it is converted to its biologically active form in the body.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"provitamin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A provitamin is an inactive biochemical precursor that lacks direct vitamin activity when consumed. It requires specific chemical modification or enzymatic cleavage inside the human body to transform into its biologically active, functional form. A classic example is beta-carotene, a provitamin that the body cleaves into active Vitamin A (retinol).\n\n\t• Preformed vitamin: This describes a vitamin that is already in its fully active, biological state when ingested (such as retinol in animal products) and requires no internal conversion.\n\t• Vitamer: Vitamers are the multiple structural variations or chemical forms of a single vitamin that all possess similar vitamin activity (e.g., pyridoxine, pyridoxal, and pyridoxamine are all vitamers of Vitamin B₆).\n\t• Antivitamin: A chemical compound that actively blocks, inhibits, or destroys the biological action of a vitamin.","whyWrongChoices":"Alternative options: antivitamin, vitamer, preformed vitamin"}'::jsonb),
('mc:the following statements are true regarding polysaccharides except::::amylose is made up of continuous, branched chains.', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following statements are true regarding polysaccharides except:', 'Amylose is made up of continuous, branched chains.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Amylose is actually a linear, unbranched chain of glucose units linked together by a-1,4-glycosidic bonds. Because it is unbranched, it naturally twists into a helical/spiral shape.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Amylose is made up of continuous, branched chains.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Amylose is actually a linear, unbranched chain of glucose units linked together by a-1,4-glycosidic bonds. Because it is unbranched, it naturally twists into a helical/spiral shape.","whyWrongChoices":"Alternative options: They are polymers of glucose., Amylopectin has α-1,6 bonds., Glycogen is similar to amylopectin but is more highly branched"}'::jsonb),
('mc:glycolysis occurs in the::::cytoplasm', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'glycolysis occurs in the:', 'cytoplasm', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cytoplasm\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.\n\nThis location is specific because all ten of the soluble enzymes required to catalyze the step-by-step breakdown of glucose are located freely within the cytoplasmic fluid.\n\n• Mitochondrial matrix: This is the internal fluid space of the mitochondria where the Krebs cycle (TCA cycle) and pyruvate oxidation happen.\n• Mitochondrial membrane: The inner mitochondrial membrane houses the proteins for the electron transport chain and oxidative phosphorylation.","whyWrongChoices":"Alternative options: mitochondrial matrix, mitochondrial membrane, none of the above"}'::jsonb),
('mc:glycolysis occurs in the::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'glycolysis occurs in the:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cytoplasm\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glycolysis is the universal metabolic pathway that breaks down one molecule of glucose into two molecules of pyruvate. It takes place entirely within the cytoplasm (specifically the cytosol) of the cell.\n\nThis location is specific because all ten of the soluble enzymes required to catalyze the step-by-step breakdown of glucose are located freely within the cytoplasmic fluid.\n\n• Mitochondrial matrix: This is the internal fluid space of the mitochondria where the Krebs cycle (TCA cycle) and pyruvate oxidation happen.\n• Mitochondrial membrane: The inner mitochondrial membrane houses the proteins for the electron transport chain and oxidative phosphorylation.","whyWrongChoices":"Alternative options: mitochondrial matrix, mitochondrial membrane, none of the above"}'::jsonb),
('mc:it refers to a vietnamese baguette sandwich.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it refers to a vietnamese baguette sandwich.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bánh mì is the Vietnamese baguette sandwich.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bahn mi\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bánh mì is the Vietnamese baguette sandwich.\n\nGỏi cuốn are fresh spring rolls, nước chấm is a dipping sauce, and phở is a noodle soup.","whyWrongChoices":"Alternative options: Goi cuon, Nuoc cham, Pho"}'::jsonb),
('mc:this amino acid can form a special covalent bond called a disulfide bond.:::cysteine', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this amino acid can form a special covalent bond called a disulfide bond.', 'cysteine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cysteine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.\n\n• Methionine: While methionine is the only other standard amino acid that contains sulfur, its sulfur atom is bound to a methyl group (a thioether group, -C-S-C-). Because it lacks a free, reactive -SH group, methionine cannot form disulfide bonds.\n• Lysine and Tyrosine: Neither of these amino acids contains sulfur in their side chains. Lysine contains an amino group, and tyrosine contains a phenolic hydroxyl group.","whyWrongChoices":"Alternative options: tyrosine, methionine, lysine"}'::jsonb),
('mc:this amino acid can form a special covalent bond called a disulfide bond.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this amino acid can form a special covalent bond called a disulfide bond.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"cysteine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cysteine contains a highly reactive sulfhydryl group (-SH) (also known as a thiol group) on its side chain. When two cysteine residues come close to each other within a protein structure, their sulfhydryl groups can undergo an oxidation reaction. This reaction joins the two sulfur atoms together, forming a strong covalent disulfide bond (S-S), which plays a critical role in stabilizing a protein''s three-dimensional structure.\n\n• Methionine: While methionine is the only other standard amino acid that contains sulfur, its sulfur atom is bound to a methyl group (a thioether group, -C-S-C-). Because it lacks a free, reactive -SH group, methionine cannot form disulfide bonds.\n• Lysine and Tyrosine: Neither of these amino acids contains sulfur in their side chains. Lysine contains an amino group, and tyrosine contains a phenolic hydroxyl group.","whyWrongChoices":"Alternative options: tyrosine, methionine, lysine"}'::jsonb),
('mc:under pd 856, the minimum kitchen size for a 40 m² dining area is (m²)::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'under pd 856, the minimum kitchen size for a 40 m² dining area is (m²):', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Rule: The kitchen area must be at least 1/4 (25%) of the total dining area, but it cannot fall below a baseline minimum of 9.30 m² (100 sq. ft.).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Rule: The kitchen area must be at least 1/4 (25%) of the total dining area, but it cannot fall below a baseline minimum of 9.30 m² (100 sq. ft.).\n\nCalculated Kitchen Area = 40 m² x 0.25 = 10 m²","whyWrongChoices":"Alternative options: 5, 15, 20"}'::jsonb),
('mc:ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?:::2', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?', '2', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.\n\n• Molar Mass: 60.06 g/mol\n• Atom Count: A single molecule contains 1 Carbon, 1 Oxygen, 2 Nitrogens, and 4 Hydrogens (8 total atoms).","whyWrongChoices":"Alternative options: 4, 1, 3"}'::jsonb),
('mc:refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best level of fat?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refer to the case below: a 35-year-old diabetic teacher went to the nutrition clinic for counseling. she is 5’4” tall andweighs 86 kg. she enrolled in a gymnasium and tried taking special slimming teas but she onlyexperienced hypoglycemia. she never lost a pound, instead gained weight. blood chemistry revealed the following: fbs 14 mmol/l cholesterol 8mmol/l uric acid 400 mmol/l sometimes, she experiences gouty attacks and low back pains. what would be the best level of fat?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This patient presents with multiple critical metabolic disorders—poorly controlled diabetes, obesity, hyperuricemia (gout), and severe hypercholesterolemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"15 -20% of TER\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This patient presents with multiple critical metabolic disorders—poorly controlled diabetes, obesity, hyperuricemia (gout), and severe hypercholesterolemia.\n\nIn standard board exam matrices, when a diabetic patient presents with elevated blood cholesterol levels, clinical guidelines prioritize managing cardiovascular risk. Restricting fat intake to a lower proportion of Total Energy Requirement (TER) assists in reducing saturated fat and dietary cholesterol. This therapeutic restriction helps address circulating blood lipids and manage obesity, while carbohydrate quality is managed separately to stabilize blood sugar.","whyWrongChoices":"Alternative options: 25- 35% of TER, 30-35% of TER, 20-25% of TER"}'::jsonb),
('mc:ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'ammonia is a nitrogenous waste product of protein metabolism that is harmful especially in high concentrations in the human body. urea cycle is a means to detoxify and to prevent the accumulation of ammonia in the body by converting it to urea which is eventually excreted in the urine. how many moles of nitrogen enter the urea cycle in every turn?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A single molecule of urea has the chemical formula CO(NH₂)₂. As you can see from its structure, every single molecule of urea contains exactly two atoms of nitrogen. Therefore, for every complete turn of the urea cycle that creates one molecule of urea, exactly 2 moles of nitrogen must enter the cycle.\n\n• Molar Mass: 60.06 g/mol\n• Atom Count: A single molecule contains 1 Carbon, 1 Oxygen, 2 Nitrogens, and 4 Hydrogens (8 total atoms).","whyWrongChoices":"Alternative options: 4, 1, 3"}'::jsonb),
