INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:the following are recommendations to address obesity during adolescence except::::psychotherapy', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are recommendations to address obesity during adolescence except:', 'Psychotherapy', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Psychotherapy - this recommendation is for other professional.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Psychotherapy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Psychotherapy - this recommendation is for other professional.","whyWrongChoices":"Alternative options: Increased physical activity and exercise, Dietary change, Food use retraining"}'::jsonb),
('mc:a simple iv solution is most appropriate for::::people who are well-nourished and are expected to eat in a few days', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a simple iv solution is most appropriate for:', 'people who are well-nourished and are expected to eat in a few days', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A simple IV solution (such as standard Normal Saline or D5W) contains only water, basic electrolytes, and sometimes a minimal amount of dextrose for basic cellular energy. It provides zero protein, zero fat, and very few calories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"people who are well-nourished and are expected to eat in a few days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A simple IV solution (such as standard Normal Saline or D5W) contains only water, basic electrolytes, and sometimes a minimal amount of dextrose for basic cellular energy. It provides zero protein, zero fat, and very few calories.\n\nBecause it lacks any real nutritional substance, a simple IV is only meant for short-term hydration and electrolyte maintenance in patients who already have good nutritional reserves and will return to eating solid food very quickly.\n\nMeanwhile, patients who are malnourished, have high metabolic nutrient demands, or cannot eat for prolonged periods require complex Parenteral Nutrition (TPN/PPN). TPN is an advanced, customized chemical cocktail delivering concentrated amino acids, lipids, vitamins, and minerals directly into the bloodstream to keep a starving patient alive.","whyWrongChoices":"Alternative options: people who have high nutrient needs, people who cannot eat for long periods of time, people who are malnourished"}'::jsonb),
('mc:a simple iv solution is most appropriate for::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a simple iv solution is most appropriate for:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A simple IV solution (such as standard Normal Saline or D5W) contains only water, basic electrolytes, and sometimes a minimal amount of dextrose for basic cellular energy. It provides zero protein, zero fat, and very few calories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"people who are well-nourished and are expected to eat in a few days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A simple IV solution (such as standard Normal Saline or D5W) contains only water, basic electrolytes, and sometimes a minimal amount of dextrose for basic cellular energy. It provides zero protein, zero fat, and very few calories.\n\nBecause it lacks any real nutritional substance, a simple IV is only meant for short-term hydration and electrolyte maintenance in patients who already have good nutritional reserves and will return to eating solid food very quickly.\n\nMeanwhile, patients who are malnourished, have high metabolic nutrient demands, or cannot eat for prolonged periods require complex Parenteral Nutrition (TPN/PPN). TPN is an advanced, customized chemical cocktail delivering concentrated amino acids, lipids, vitamins, and minerals directly into the bloodstream to keep a starving patient alive.","whyWrongChoices":"Alternative options: people who have high nutrient needs, people who cannot eat for long periods of time, people who are malnourished"}'::jsonb),
('mc:the best food to give when a patient has a blood sugar of 60mg.:::1 tbsp sugar', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the best food to give when a patient has a blood sugar of 60mg.', '1 tbsp sugar', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A blood sugar level of 60 mg/dL indicates hypoglycemia (low blood sugar), which is defined as any value under 70 mg/dL. To properly treat this, clinical guidelines recommend the \"Rule of 15\": consume 15 grams of fast-acting, simple carbohydrates, wait 15 minutes, and recheck the blood sugar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1 tbsp sugar\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A blood sugar level of 60 mg/dL indicates hypoglycemia (low blood sugar), which is defined as any value under 70 mg/dL. To properly treat this, clinical guidelines recommend the \"Rule of 15\": consume 15 grams of fast-acting, simple carbohydrates, wait 15 minutes, and recheck the blood sugar.\n\n• 1/3 cup fruit juice: A 1/3 cup serving is only about 10 grams, which under-treats an adult.\n• 5 glucose tablets: Standard glucose tablets usually contain 4 grams of carbohydrates each. Taking 5 tablets (20 grams) over-treats a mild low, which can cause a sharp rebound spike.\n• 1 tsp honey: One teaspoon is only 5 grams.","whyWrongChoices":"Alternative options: 1 tsp honey, 1/3 cup fruit juice, 5 glucose tablets"}'::jsonb),
('mc:the best food to give when a patient has a blood sugar of 60mg.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the best food to give when a patient has a blood sugar of 60mg.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A blood sugar level of 60 mg/dL indicates hypoglycemia (low blood sugar), which is defined as any value under 70 mg/dL. To properly treat this, clinical guidelines recommend the \"Rule of 15\": consume 15 grams of fast-acting, simple carbohydrates, wait 15 minutes, and recheck the blood sugar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1 tbsp sugar\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A blood sugar level of 60 mg/dL indicates hypoglycemia (low blood sugar), which is defined as any value under 70 mg/dL. To properly treat this, clinical guidelines recommend the \"Rule of 15\": consume 15 grams of fast-acting, simple carbohydrates, wait 15 minutes, and recheck the blood sugar.\n\n• 1/3 cup fruit juice: A 1/3 cup serving is only about 10 grams, which under-treats an adult.\n• 5 glucose tablets: Standard glucose tablets usually contain 4 grams of carbohydrates each. Taking 5 tablets (20 grams) over-treats a mild low, which can cause a sharp rebound spike.\n• 1 tsp honey: One teaspoon is only 5 grams.","whyWrongChoices":"Alternative options: 1 tsp honey, 1/3 cup fruit juice, 5 glucose tablets"}'::jsonb),
('mc:also known as ergocalciferol and cholecalciferol, respectively.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'also known as ergocalciferol and cholecalciferol, respectively.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin D2 is a form of Vitamin D-fortified products. Vitamin D3 is a form of Vitamin D found in animal products.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit D2, Vit D3\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin D2 is a form of Vitamin D-fortified products. Vitamin D3 is a form of Vitamin D found in animal products.","whyWrongChoices":"Alternative options: Vit D1, Vit D2, Vit D1, Vit D3, Vit D3, Vit D2"}'::jsonb),
('mc:refer to the following information: a 25-year old female office clerk consulted at an out-patient clinic for dizziness and headache. she is 5’4” and weighs 70 kg. her bp is 150/80 mmhg. this is her first consultation. which of the following foods would you recommend?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refer to the following information: a 25-year old female office clerk consulted at an out-patient clinic for dizziness and headache. she is 5’4” and weighs 70 kg. her bp is 150/80 mmhg. this is her first consultation. which of the following foods would you recommend?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The patient’s blood pressure is 150/80 mmHg, which classifies as Stage 2 Hypertension (specifically elevated systolic pressure). A primary nutritional intervention for managing high blood pressure is a low-sodium, heart-healthy diet rich in potassium and fiber (similar to the DASH diet approach).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"rice, pan de sal, camote tops, fish\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The patient’s blood pressure is 150/80 mmHg, which classifies as Stage 2 Hypertension (specifically elevated systolic pressure). A primary nutritional intervention for managing high blood pressure is a low-sodium, heart-healthy diet rich in potassium and fiber (similar to the DASH diet approach).\n\t• Fresh Fish: Provides a lean, high-quality source of protein that is naturally low in sodium and rich in heart-healthy omega-3 fatty acids.\n\t• Camote Tops (Sweet Potato Leaves): A local powerhouse vegetable that is highly concentrated in potassium. Potassium actively works to lower blood pressure by helping the kidneys excrete excess sodium and relaxing blood vessel walls.\n\t• Rice & Pan de Sal: Serve as staple carbohydrates. While traditional pan de sal contains a small amount of salt, the meal as a whole is overwhelmingly comprised of fresh, unprocessed items.\n\nThe remaining options contain heavily processed, canned, or cured foods (ham, corned beef, pork and beans) that are loaded with hidden sodium, which can acutely worsen hypertension by causing fluid retention and increasing blood vessel pressure:","whyWrongChoices":"Alternative options: pan de sal, rice, cottage cheese, corned beef, ampalaya, pork and beans, carrots, banana, rice, milk, ham, eggs, rice"}'::jsonb),
('mc:the nutritionist-dietitian must closely monitor the client with nephrotic syndrome for deficiencies of which vitamin?:::d', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the nutritionist-dietitian must closely monitor the client with nephrotic syndrome for deficiencies of which vitamin?', 'D', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nephrotic syndrome is characterized by heavy proteinuria (>3.5 g/day), which leads to the urinary excretion of low-molecular-weight plasma proteins, including the 58-kDa vitamin D-binding protein (DBP). Because the majority of circulating 25-hydroxyvitamin D [25(OH)D] and 1,25-dihydroxyvitamin D [1,25(OH)2D] are bound to DBP, their continuous loss in the urine depletes total body stores. Furthermore, impaired renal parenchyma and chronic inflammation decrease the activity of 1alpha-hydroxylase, reducing the conversion of 25(OH)D to its active hormonal form, 1,25-dihydroxyvitamin D, thereby disrupting calcium homeostasis and secondary bone mineralization.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"D\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nephrotic syndrome is characterized by heavy proteinuria (>3.5 g/day), which leads to the urinary excretion of low-molecular-weight plasma proteins, including the 58-kDa vitamin D-binding protein (DBP). Because the majority of circulating 25-hydroxyvitamin D [25(OH)D] and 1,25-dihydroxyvitamin D [1,25(OH)2D] are bound to DBP, their continuous loss in the urine depletes total body stores. Furthermore, impaired renal parenchyma and chronic inflammation decrease the activity of 1alpha-hydroxylase, reducing the conversion of 25(OH)D to its active hormonal form, 1,25-dihydroxyvitamin D, thereby disrupting calcium homeostasis and secondary bone mineralization.","whyWrongChoices":"Alternative options: A, B₆, K"}'::jsonb),
('mc:the nutritionist-dietitian must closely monitor the client with nephrotic syndrome for deficiencies of which vitamin?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the nutritionist-dietitian must closely monitor the client with nephrotic syndrome for deficiencies of which vitamin?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nephrotic syndrome is characterized by heavy proteinuria (>3.5 g/day), which leads to the urinary excretion of low-molecular-weight plasma proteins, including the 58-kDa vitamin D-binding protein (DBP). Because the majority of circulating 25-hydroxyvitamin D [25(OH)D] and 1,25-dihydroxyvitamin D [1,25(OH)2D] are bound to DBP, their continuous loss in the urine depletes total body stores. Furthermore, impaired renal parenchyma and chronic inflammation decrease the activity of 1alpha-hydroxylase, reducing the conversion of 25(OH)D to its active hormonal form, 1,25-dihydroxyvitamin D, thereby disrupting calcium homeostasis and secondary bone mineralization.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"D\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nephrotic syndrome is characterized by heavy proteinuria (>3.5 g/day), which leads to the urinary excretion of low-molecular-weight plasma proteins, including the 58-kDa vitamin D-binding protein (DBP). Because the majority of circulating 25-hydroxyvitamin D [25(OH)D] and 1,25-dihydroxyvitamin D [1,25(OH)2D] are bound to DBP, their continuous loss in the urine depletes total body stores. Furthermore, impaired renal parenchyma and chronic inflammation decrease the activity of 1alpha-hydroxylase, reducing the conversion of 25(OH)D to its active hormonal form, 1,25-dihydroxyvitamin D, thereby disrupting calcium homeostasis and secondary bone mineralization.","whyWrongChoices":"Alternative options: A, B₆, K"}'::jsonb),
('mc:aside from table salt, a low sodium diet limits the use of::::processed foods', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'aside from table salt, a low sodium diet limits the use of:', 'processed foods', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aside from table salt, processed and ultra-processed foods are the single largest source of sodium in the modern diet. Manufacturers add massive amounts of sodium to packaged meals, canned soups, cured meats, and snacks for preservation and flavor enhancement. A low-sodium diet strictly mandates limiting these items.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"processed foods\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aside from table salt, processed and ultra-processed foods are the single largest source of sodium in the modern diet. Manufacturers add massive amounts of sodium to packaged meals, canned soups, cured meats, and snacks for preservation and flavor enhancement. A low-sodium diet strictly mandates limiting these items.","whyWrongChoices":"Alternative options: fried foods, dialyzed milk, all of the above"}'::jsonb),
('mc:aside from table salt, a low sodium diet limits the use of::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'aside from table salt, a low sodium diet limits the use of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aside from table salt, processed and ultra-processed foods are the single largest source of sodium in the modern diet. Manufacturers add massive amounts of sodium to packaged meals, canned soups, cured meats, and snacks for preservation and flavor enhancement. A low-sodium diet strictly mandates limiting these items.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"processed foods\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aside from table salt, processed and ultra-processed foods are the single largest source of sodium in the modern diet. Manufacturers add massive amounts of sodium to packaged meals, canned soups, cured meats, and snacks for preservation and flavor enhancement. A low-sodium diet strictly mandates limiting these items.","whyWrongChoices":"Alternative options: fried foods, dialyzed milk, all of the above"}'::jsonb),
('mc:a ketogenic diet is characterized as::::high fat, low cho', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a ketogenic diet is characterized as:', 'high fat, low CHO', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A classic ketogenic diet is structured to shift the body''s primary metabolic fuel source from glucose to fat. To induce this state of ketosis, the diet must dramatically restrict carbohydrates (CHO) and replace those calories with dietary fat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high fat, low CHO\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A classic ketogenic diet is structured to shift the body''s primary metabolic fuel source from glucose to fat. To induce this state of ketosis, the diet must dramatically restrict carbohydrates (CHO) and replace those calories with dietary fat.\n\nThe standard ketogenic diet typically derives approximately 70% to 80% of daily calories from fat, 15% to 20% from protein, and only 5% to 10% from carbohydrates.","whyWrongChoices":"Alternative options: low fat, high CHO, high protein, low CHO, high protein, low fat"}'::jsonb),
('mc:a ketogenic diet is characterized as::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a ketogenic diet is characterized as:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A classic ketogenic diet is structured to shift the body''s primary metabolic fuel source from glucose to fat. To induce this state of ketosis, the diet must dramatically restrict carbohydrates (CHO) and replace those calories with dietary fat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high fat, low CHO\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A classic ketogenic diet is structured to shift the body''s primary metabolic fuel source from glucose to fat. To induce this state of ketosis, the diet must dramatically restrict carbohydrates (CHO) and replace those calories with dietary fat.\n\nThe standard ketogenic diet typically derives approximately 70% to 80% of daily calories from fat, 15% to 20% from protein, and only 5% to 10% from carbohydrates.","whyWrongChoices":"Alternative options: low fat, high CHO, high protein, low CHO, high protein, low fat"}'::jsonb),
('mc:characterized by low grade fever, body tissue wasting, and dry cough.:::tuberculosis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'characterized by low grade fever, body tissue wasting, and dry cough.', 'tuberculosis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This infectious disease is caused by the bacterium Mycobacterium tuberculosis. The classic symptoms of pulmonary TB include a lingering low-grade fever (often spiking in the afternoon or evening), dry cough (which may start dry before becoming productive or producing blood), and severe body tissue wasting (traditionally referred to as \"consumption\" due to profound, unintended weight loss and muscle atrophy).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"tuberculosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This infectious disease is caused by the bacterium Mycobacterium tuberculosis. The classic symptoms of pulmonary TB include a lingering low-grade fever (often spiking in the afternoon or evening), dry cough (which may start dry before becoming productive or producing blood), and severe body tissue wasting (traditionally referred to as \"consumption\" due to profound, unintended weight loss and muscle atrophy).\n\n\t• COPD: Characterized primarily by a chronic productive cough (with mucus), wheezing, and progressive shortness of breath, rather than a presenting low-grade fever.\n\t• AIDS: While it causes wasting and fever, it is a complex systemic syndrome of immune failure that manifests through a wide variety of opportunistic infections rather than a localized dry cough complex.\n\t• Cholecystitis: This is an acute or chronic inflammation of the gallbladder that presents with sharp upper abdominal pain, nausea, and potentially a high fever, rather than chronic respiratory symptoms or progressive body wasting.","whyWrongChoices":"Alternative options: COPD, AIDS, cholecystitis"}'::jsonb),
('mc:characterized by low grade fever, body tissue wasting, and dry cough.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'characterized by low grade fever, body tissue wasting, and dry cough.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"This infectious disease is caused by the bacterium Mycobacterium tuberculosis. The classic symptoms of pulmonary TB include a lingering low-grade fever (often spiking in the afternoon or evening), dry cough (which may start dry before becoming productive or producing blood), and severe body tissue wasting (traditionally referred to as \"consumption\" due to profound, unintended weight loss and muscle atrophy).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"tuberculosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"This infectious disease is caused by the bacterium Mycobacterium tuberculosis. The classic symptoms of pulmonary TB include a lingering low-grade fever (often spiking in the afternoon or evening), dry cough (which may start dry before becoming productive or producing blood), and severe body tissue wasting (traditionally referred to as \"consumption\" due to profound, unintended weight loss and muscle atrophy).\n\n\t• COPD: Characterized primarily by a chronic productive cough (with mucus), wheezing, and progressive shortness of breath, rather than a presenting low-grade fever.\n\t• AIDS: While it causes wasting and fever, it is a complex systemic syndrome of immune failure that manifests through a wide variety of opportunistic infections rather than a localized dry cough complex.\n\t• Cholecystitis: This is an acute or chronic inflammation of the gallbladder that presents with sharp upper abdominal pain, nausea, and potentially a high fever, rather than chronic respiratory symptoms or progressive body wasting.","whyWrongChoices":"Alternative options: COPD, AIDS, cholecystitis"}'::jsonb),
('mc:severely malnourished children must be rehabilitated at the shortest time possible. choose the diet for a malnourished child with diarrhea who has just been admitted in the hospital.:::regular foods plus a liquid preparation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'severely malnourished children must be rehabilitated at the shortest time possible. choose the diet for a malnourished child with diarrhea who has just been admitted in the hospital.', 'regular foods plus a liquid preparation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In severe acute malnutrition (SAM) with diarrhea, mucosal atrophy, brush border enzyme depletion (lactase, sucrase), and impaired sodium-glucose cotransporter (SGLT-1) function demand cautious, low-osmolarity oral rehydration and specialized starter formulas (F-75 transitioning rapidly to F-100) combined with soft, regular foods to restore enterocyte integrity, provide adequate macronutrients for catch-up growth, and prevent villous atrophy without worsening osmotic diarrhea.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"regular foods plus a liquid preparation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In severe acute malnutrition (SAM) with diarrhea, mucosal atrophy, brush border enzyme depletion (lactase, sucrase), and impaired sodium-glucose cotransporter (SGLT-1) function demand cautious, low-osmolarity oral rehydration and specialized starter formulas (F-75 transitioning rapidly to F-100) combined with soft, regular foods to restore enterocyte integrity, provide adequate macronutrients for catch-up growth, and prevent villous atrophy without worsening osmotic diarrhea.","whyWrongChoices":"Alternative options: liquid diet high in calories and protein, BRAT, regular diet consisting of foods liked and disliked"}'::jsonb),
