('mc:management philosophy combining principles of quality assurance, participative management, and quality work life::::total quality management', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'management philosophy combining principles of quality assurance, participative management, and quality work life:', 'Total Quality Management', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"TQM is a system of management based on the principle that every staff member must be committed to maintaining high standards of work in every aspect of a company''s operations towards attaining customer satisfaction.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Total Quality Management\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"TQM is a system of management based on the principle that every staff member must be committed to maintaining high standards of work in every aspect of a company''s operations towards attaining customer satisfaction.","whyWrongChoices":"Alternative options: Theory X, Theory Y, Theory Z"}'::jsonb),
('mc:three work centers found on two opposite counters.:::galley', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'three work centers found on two opposite counters.', 'Galley', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galley\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.\n\n• L-Shaped: Uses two adjacent perpendicular walls to form an \"L\" shape. Typically places two work centers on one wall and the third on the adjoining wall.\n• U-Shaped: Features three continuous walls of cabinetry and counters forming a \"U\" shape. Distributes one work center per wall (e.g., sink on the back wall, stove and fridge on opposite side walls).\n• Island: Features a standard perimeter layout (like an L-shape or single wall) with an independent, freestanding counter in the middle.","whyWrongChoices":"Alternative options: L-shaped, U-shaped, Island"}'::jsonb),
('mc:three work centers found on two opposite counters.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'three work centers found on two opposite counters.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galley\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Two Wall or Galley - 1.2m space for drawers on opposite sides; sink and range are on the same side. It features two parallel counters facing each other. Places the three main work centers across from each other in a compact space.\n\n• L-Shaped: Uses two adjacent perpendicular walls to form an \"L\" shape. Typically places two work centers on one wall and the third on the adjoining wall.\n• U-Shaped: Features three continuous walls of cabinetry and counters forming a \"U\" shape. Distributes one work center per wall (e.g., sink on the back wall, stove and fridge on opposite side walls).\n• Island: Features a standard perimeter layout (like an L-shape or single wall) with an independent, freestanding counter in the middle.","whyWrongChoices":"Alternative options: L-shaped, U-shaped, Island"}'::jsonb),
