('mc:iso standard of ensuring efficient, safe, and cleaner product and services::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'iso standard of ensuring efficient, safe, and cleaner product and services:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The ISO 22000 is the comprehensive and internationally recognized standard for management systems in the food industry. With certification according to ISO 22000:2018 you guarantee the quality and safety of food along the entire production chain. From primary producers to transport companies, subcontractors, food manufacturers and retail.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"22000\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The ISO 22000 is the comprehensive and internationally recognized standard for management systems in the food industry. With certification according to ISO 22000:2018 you guarantee the quality and safety of food along the entire production chain. From primary producers to transport companies, subcontractors, food manufacturers and retail.","whyWrongChoices":"Alternative options: 9000, 1400, 2001"}'::jsonb),
('mc:the cost incurred by an operation that includes rent, depreciation, utlities, etc.:::operating cost', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the cost incurred by an operation that includes rent, depreciation, utlities, etc.', 'Operating cost', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Operating or overhead costs are costs other than food and labor. This includes utilities, repairs and maintenance, cleaning materials, rent, depreciation, taxes, insurance, etc.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Operating cost\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Operating or overhead costs are costs other than food and labor. This includes utilities, repairs and maintenance, cleaning materials, rent, depreciation, taxes, insurance, etc.","whyWrongChoices":"Alternative options: Labor cost, Fixed cost, Food cost"}'::jsonb),
