('mc:also known as vitamin h.:::biotin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'also known as vitamin h.', 'Biotin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vitamin H is another name for biotin, which is also known as vitamin B7. The \"H\" comes from the German words \"Haar und Haut,\" which mean hair and skin. It helps maintain healthy hair, skin, and nails.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biotin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vitamin H is another name for biotin, which is also known as vitamin B7. The \"H\" comes from the German words \"Haar und Haut,\" which mean hair and skin. It helps maintain healthy hair, skin, and nails.\n\nBiotin is also known as Vitamin B7, Coenzyme R, Bios I, and anti-egg white injury factor.","whyWrongChoices":"Alternative options: Riboflavin, Anti-vitamins, Carnitine"}'::jsonb),
('mc:german global online food delivery marketplace that allows customers to directly order meals online or via mobile.:::foodpanda', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'german global online food delivery marketplace that allows customers to directly order meals online or via mobile.', 'Foodpanda', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Foodpanda is an online food and grocery delivery platform brand owned by Delivery Hero, which is headquartered in Berlin, Germany and operates with 20 brands in about 50 countries across four continents. The Foodpanda brand, currently used in Asia, Bulgaria and Romania, was acquired by Delivery Hero in December 2016.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Foodpanda\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Foodpanda is an online food and grocery delivery platform brand owned by Delivery Hero, which is headquartered in Berlin, Germany and operates with 20 brands in about 50 countries across four continents. The Foodpanda brand, currently used in Asia, Bulgaria and Romania, was acquired by Delivery Hero in December 2016.\n\n• Honestbee was an online grocery and food delivery service based in Singapore.\n• Munchpunch is a food discovery and restaurant directory website based in the Philippines.\n• AmazonFresh is a grocery delivery service owned by the American tech giant Amazon.","whyWrongChoices":"Alternative options: Honestbee, Munchpunch"}'::jsonb),
('mc:german global online food delivery marketplace that allows customers to directly order meals online or via mobile.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'german global online food delivery marketplace that allows customers to directly order meals online or via mobile.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Foodpanda is an online food and grocery delivery platform brand owned by Delivery Hero, which is headquartered in Berlin, Germany and operates with 20 brands in about 50 countries across four continents. The Foodpanda brand, currently used in Asia, Bulgaria and Romania, was acquired by Delivery Hero in December 2016.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Foodpanda\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Foodpanda is an online food and grocery delivery platform brand owned by Delivery Hero, which is headquartered in Berlin, Germany and operates with 20 brands in about 50 countries across four continents. The Foodpanda brand, currently used in Asia, Bulgaria and Romania, was acquired by Delivery Hero in December 2016.\n\n• Honestbee was an online grocery and food delivery service based in Singapore.\n• Munchpunch is a food discovery and restaurant directory website based in the Philippines.\n• AmazonFresh is a grocery delivery service owned by the American tech giant Amazon.","whyWrongChoices":"Alternative options: Honestbee, Munchpunch"}'::jsonb),
('mc:decision-making guides that are written to ensure that all actions taken by organization members are consistent with the organization''s strategy and objectives.:::policies', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'decision-making guides that are written to ensure that all actions taken by organization members are consistent with the organization''s strategy and objectives.', 'Policies', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In organizational management and foodservice planning, policies function as comprehensive, high-level decision-making guides. Rather than telling employees exactly what to do step-by-step, they establish a reliable boundaries framework. This ensures that every independent decision or action made by staff members stays completely aligned with the company’s broad strategy, vision, and core objectives.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Policies\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In organizational management and foodservice planning, policies function as comprehensive, high-level decision-making guides. Rather than telling employees exactly what to do step-by-step, they establish a reliable boundaries framework. This ensures that every independent decision or action made by staff members stays completely aligned with the company’s broad strategy, vision, and core objectives.\n\n• Rules: These are strict, specific, and inflexible directives that dictate exactly what must or must not be done in a given situation (e.g., \"No smoking in the kitchen\"). They leave zero room for individual decision-making or managerial discretion.\n• Operating plans: These are short-term, detailed tactical blueprints that outline specific tasks, timelines, schedules, and budgets to execute operations over a precise period (such as weekly or monthly outputs).\n• Standing plans: This is a broad, overarching category of plans designed to be used repeatedly for recurring organizational activities. Standing plans include policies, procedures, and rules collectively, making it too broad of a classification to serve as the definition for a targeted decision-making guide.","whyWrongChoices":"Alternative options: Rules, Standing plans, Operating plans"}'::jsonb),
('mc:decision-making guides that are written to ensure that all actions taken by organization members are consistent with the organization''s strategy and objectives.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'decision-making guides that are written to ensure that all actions taken by organization members are consistent with the organization''s strategy and objectives.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In organizational management and foodservice planning, policies function as comprehensive, high-level decision-making guides. Rather than telling employees exactly what to do step-by-step, they establish a reliable boundaries framework. This ensures that every independent decision or action made by staff members stays completely aligned with the company’s broad strategy, vision, and core objectives.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Policies\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In organizational management and foodservice planning, policies function as comprehensive, high-level decision-making guides. Rather than telling employees exactly what to do step-by-step, they establish a reliable boundaries framework. This ensures that every independent decision or action made by staff members stays completely aligned with the company’s broad strategy, vision, and core objectives.\n\n• Rules: These are strict, specific, and inflexible directives that dictate exactly what must or must not be done in a given situation (e.g., \"No smoking in the kitchen\"). They leave zero room for individual decision-making or managerial discretion.\n• Operating plans: These are short-term, detailed tactical blueprints that outline specific tasks, timelines, schedules, and budgets to execute operations over a precise period (such as weekly or monthly outputs).\n• Standing plans: This is a broad, overarching category of plans designed to be used repeatedly for recurring organizational activities. Standing plans include policies, procedures, and rules collectively, making it too broad of a classification to serve as the definition for a targeted decision-making guide.","whyWrongChoices":"Alternative options: Rules, Standing plans, Operating plans"}'::jsonb),
('mc:limiting amino acid in rice::::lysine', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'limiting amino acid in rice:', 'Lysine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lysine, the main limiting essential amino acid in cereals, restricts the absorption and utilization of other amino acids and proteins, which leads to nutrient deficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lysine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lysine, the main limiting essential amino acid in cereals, restricts the absorption and utilization of other amino acids and proteins, which leads to nutrient deficiency.","whyWrongChoices":"Alternative options: Tryptophan, Methionine, Tyrosine"}'::jsonb),
