('mc:the first symptom of vitamin a deficiency affecting vision.:::nyctalopia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the first symptom of vitamin a deficiency affecting vision.', 'Nyctalopia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nyctalopia is also called as night blindness. Manifestations of Vitamin A deficiency include eye defects including nyctalopia as the first symptom affecting vision.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nyctalopia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nyctalopia is also called as night blindness. Manifestations of Vitamin A deficiency include eye defects including nyctalopia as the first symptom affecting vision.","whyWrongChoices":"Alternative options: Conjunctivitis, Corneal Xerosis"}'::jsonb),
('mc:the first symptom of vitamin a deficiency affecting vision.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the first symptom of vitamin a deficiency affecting vision.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nyctalopia is also called as night blindness. Manifestations of Vitamin A deficiency include eye defects including nyctalopia as the first symptom affecting vision.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nyctalopia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nyctalopia is also called as night blindness. Manifestations of Vitamin A deficiency include eye defects including nyctalopia as the first symptom affecting vision.","whyWrongChoices":"Alternative options: Conjunctivitis, Corneal Xerosis"}'::jsonb),
('mc:deficiency of this vitamin is associated with alopecia or baldness.:::biotin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'deficiency of this vitamin is associated with alopecia or baldness.', 'Biotin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Alopecia is linked with deficiency in biotin (Vitamin B7)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biotin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Alopecia is linked with deficiency in biotin (Vitamin B7)","whyWrongChoices":"Alternative options: Riboflavin, Pantothenic acid, Folate"}'::jsonb),
('mc:is the most abundant cation outside the cell while is the most abundant anion inside the cell.:::sodium, phosphate', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'is the most abundant cation outside the cell while is the most abundant anion inside the cell.', 'Sodium, Phosphate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sodium (Na⁺) is the principal, most abundant cation (positively charged ion) found in the extracellular fluid. It plays a dominant role in regulating osmotic pressure, fluid balance, and blood volume.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sodium, Phosphate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sodium (Na⁺) is the principal, most abundant cation (positively charged ion) found in the extracellular fluid. It plays a dominant role in regulating osmotic pressure, fluid balance, and blood volume.\n\nWhile Potassium (K⁺) is the most abundant cation inside the cell, Phosphate (primarily as HPO₄²⁻) is the most abundant anion (negatively charged ion) inside the intracellular fluid. It is vital for cellular energy production (ATP synthesis), DNA/RNA structure, and functioning as an intracellular acid-base buffer.\n\n🔴 Chloride: most abundant ''anion outside'' the cell\n🔴 Potassium: most abundant ''cation inside'' the cell","whyWrongChoices":"Alternative options: Sodium, Chloride, Potassium, Chloride, Potassium, Phosphate"}'::jsonb),
('mc:is the most abundant cation outside the cell while is the most abundant anion inside the cell.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'is the most abundant cation outside the cell while is the most abundant anion inside the cell.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Sodium (Na⁺) is the principal, most abundant cation (positively charged ion) found in the extracellular fluid. It plays a dominant role in regulating osmotic pressure, fluid balance, and blood volume.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sodium, Phosphate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Sodium (Na⁺) is the principal, most abundant cation (positively charged ion) found in the extracellular fluid. It plays a dominant role in regulating osmotic pressure, fluid balance, and blood volume.\n\nWhile Potassium (K⁺) is the most abundant cation inside the cell, Phosphate (primarily as HPO₄²⁻) is the most abundant anion (negatively charged ion) inside the intracellular fluid. It is vital for cellular energy production (ATP synthesis), DNA/RNA structure, and functioning as an intracellular acid-base buffer.\n\n🔴 Chloride: most abundant ''anion outside'' the cell\n🔴 Potassium: most abundant ''cation inside'' the cell","whyWrongChoices":"Alternative options: Sodium, Chloride, Potassium, Chloride, Potassium, Phosphate"}'::jsonb),
('mc:a pellagra-preventive (p-p) factor.:::niacin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a pellagra-preventive (p-p) factor.', 'Niacin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Severe niacin deficiency could lead to Pellagra, which is characterized by dementia, diarrhea, dermatitis, and death.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Niacin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Severe niacin deficiency could lead to Pellagra, which is characterized by dementia, diarrhea, dermatitis, and death.","whyWrongChoices":"Alternative options: Thiamin, Riboflavin"}'::jsonb),
