INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:amount of protein equivalent to a gram of nitrogen.:::6.25g', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'amount of protein equivalent to a gram of nitrogen.', '6.25g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On average, protein contains approximately 16% nitrogen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.25g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On average, protein contains approximately 16% nitrogen.\n\nTherefore: 1 g nitrogen × 6.25 = 6.25 g protein\nThe factor 6.25 is derived from: 100 ÷ 16 = 6.25\n\nThis conversion is commonly used when calculating nitrogen balance, particularly in clinical nutrition and protein assessment.","whyWrongChoices":"Alternative options: 0.16g, 54g, 10g"}'::jsonb),
('mc:what does the mid-upper arm muscle (mamc) estimate?:::a and b', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what does the mid-upper arm muscle (mamc) estimate?', 'A and B', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:\nMAMC = MUAC - (π * TSF)\n\nIt serves as a critical indicator in nutritional assessments because:\n• Skeletal Muscle Reserves: Because the arm consists primarily of bone, muscle, and a surrounding layer of subcutaneous fat, subtracting the fat thickness (via the triceps skinfold) isolates the muscle component. This directly gauges the body''s skeletal muscle reserves.\n• Lean Body Mass: In clinical malnutrition states (such as marasmus or chronic disease cachexia), the body breaks down its skeletal muscle tissue to use for energy. Therefore, measuring MAMC provides a reliable proxy estimate of a patient''s overall lean body mass.\n\nWhy \"Fat reserve\" is incorrect:\nThe Triceps Skinfold (TSF) thickness alone is what isolates and estimates subcutaneous fat reserves. MAMC specifically subtracts the fat to look only at muscle tissue.","whyWrongChoices":"Alternative options: The amount of lean body mass, Skeletal muscle reserves, Fat reserve"}'::jsonb),
('mc:limiting amino acid in rice::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'limiting amino acid in rice:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lysine, the main limiting essential amino acid in cereals, restricts the absorption and utilization of other amino acids and proteins, which leads to nutrient deficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lysine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lysine, the main limiting essential amino acid in cereals, restricts the absorption and utilization of other amino acids and proteins, which leads to nutrient deficiency.","whyWrongChoices":"Alternative options: Tryptophan, Methionine, Tyrosine"}'::jsonb),
('mc:what does the mid-upper arm muscle (mamc) estimate?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what does the mid-upper arm muscle (mamc) estimate?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Mid-upper arm muscle circumference (MAMC) is an anthropometric calculation derived mathematically by combining the Mid-Upper Arm Circumference (MUAC) and the Triceps Skinfold (TSF) thickness through the following formula:\nMAMC = MUAC - (π * TSF)\n\nIt serves as a critical indicator in nutritional assessments because:\n• Skeletal Muscle Reserves: Because the arm consists primarily of bone, muscle, and a surrounding layer of subcutaneous fat, subtracting the fat thickness (via the triceps skinfold) isolates the muscle component. This directly gauges the body''s skeletal muscle reserves.\n• Lean Body Mass: In clinical malnutrition states (such as marasmus or chronic disease cachexia), the body breaks down its skeletal muscle tissue to use for energy. Therefore, measuring MAMC provides a reliable proxy estimate of a patient''s overall lean body mass.\n\nWhy \"Fat reserve\" is incorrect:\nThe Triceps Skinfold (TSF) thickness alone is what isolates and estimates subcutaneous fat reserves. MAMC specifically subtracts the fat to look only at muscle tissue.","whyWrongChoices":"Alternative options: The amount of lean body mass, Skeletal muscle reserves, Fat reserve"}'::jsonb),
('mc:food records are usually collected for what period of time?:::1-7 days', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'food records are usually collected for what period of time?', '1-7 days', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1-7 days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","whyWrongChoices":"Alternative options: 1 day, 3-4 days, 2 weeks"}'::jsonb),
('mc:food records are usually collected for what period of time?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'food records are usually collected for what period of time?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1-7 days\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard nutritional assessment methodology, a formal, comprehensive food record (or weighed food diary) has historically been collected over a 7-day period. Tracking a full 7-day week accounts for day-to-day intake variations and ensures that both weekdays and weekend eating behaviors are fully represented.","whyWrongChoices":"Alternative options: 1 day, 3-4 days, 2 weeks"}'::jsonb),
('mc:what do waist-to-hip circumference ratios measure?:::intra-abdominal fat and subcutaneous fat', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what do waist-to-hip circumference ratios measure?', 'Intra-abdominal fat and subcutaneous fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Intra-abdominal fat and subcutaneous fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).\n\nBecause it gauges your midsection width, the ratio serves as an accessible proxy marker for tracking accumulated intra-abdominal fat (visceral fat that envelopes your internal organs) alongside abdominal subcutaneous fat (fat stored directly beneath the skin). An elevated ratio indicates central obesity, which heavily correlates with metabolic and cardiovascular diseases.","whyWrongChoices":"Alternative options: Fat-free mass, Protein-energy malnutrition, Skeletal mass"}'::jsonb),
('mc:what do waist-to-hip circumference ratios measure?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what do waist-to-hip circumference ratios measure?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Intra-abdominal fat and subcutaneous fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Waist-to-hip ratio (WHR) is an anthropometric index calculated by dividing your waist circumference by your hip circumference. It is primarily used to map out body fat distribution patterns (such as identifying \"apple-shaped\" vs. \"pear-shaped\" body types).\n\nBecause it gauges your midsection width, the ratio serves as an accessible proxy marker for tracking accumulated intra-abdominal fat (visceral fat that envelopes your internal organs) alongside abdominal subcutaneous fat (fat stored directly beneath the skin). An elevated ratio indicates central obesity, which heavily correlates with metabolic and cardiovascular diseases.","whyWrongChoices":"Alternative options: Fat-free mass, Protein-energy malnutrition, Skeletal mass"}'::jsonb),
('mc:deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?:::zinc', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?', 'Zinc', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zinc\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.\n• Increased risk of infection: Zinc deficiency impairs cell-mediated immunity and mucosal barriers, making children highly susceptible to severe infections like diarrhea and pneumonia.\n• Growth failure & Delayed sexual maturity: Zinc plays an indispensable structural role in growth hormone function and gonadotropin secretion. Severe deficiency directly arrests linear skeletal growth (causing stunting or growth failure) and leads to hypogonadism or delayed sexual development in adolescents.\n\n• Calcium: Primary deficiencies lead to rickets in children and osteomalacia in adults, characterized by poor bone mineralization rather than delayed sexual maturity.\n• Iodine: Deficiency causes goiter and hypothyroidism, and severe prenatal deficiency leads to cretinism (profound intellectual disability and physical stunting), but it is not typically grouped under this specific childhood triad.\n• Riboflavin (Vitamin B2): Deficiency manifests as ariboflavinosis, which presents with cheilosis (cracked lips), angular stomatitis (cracks at the corners of the mouth), and glossitis (magenta tongue).","whyWrongChoices":"Alternative options: Iodine, Riboflavin, Calcium"}'::jsonb),
('mc:deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'deficiency of which nutrient is associated with increased risk of infection in children, growth failure throughout childhood and delayed sexual maturity?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Zinc\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Zinc deficiency is classically characterized by this specific triad of symptoms in children. Zinc is a critical trace mineral essential for cellular metabolism, DNA synthesis, and immune system function.\n• Increased risk of infection: Zinc deficiency impairs cell-mediated immunity and mucosal barriers, making children highly susceptible to severe infections like diarrhea and pneumonia.\n• Growth failure & Delayed sexual maturity: Zinc plays an indispensable structural role in growth hormone function and gonadotropin secretion. Severe deficiency directly arrests linear skeletal growth (causing stunting or growth failure) and leads to hypogonadism or delayed sexual development in adolescents.\n\n• Calcium: Primary deficiencies lead to rickets in children and osteomalacia in adults, characterized by poor bone mineralization rather than delayed sexual maturity.\n• Iodine: Deficiency causes goiter and hypothyroidism, and severe prenatal deficiency leads to cretinism (profound intellectual disability and physical stunting), but it is not typically grouped under this specific childhood triad.\n• Riboflavin (Vitamin B2): Deficiency manifests as ariboflavinosis, which presents with cheilosis (cracked lips), angular stomatitis (cracks at the corners of the mouth), and glossitis (magenta tongue).","whyWrongChoices":"Alternative options: Iodine, Riboflavin, Calcium"}'::jsonb),
('mc:amount of protein equivalent to a gram of nitrogen.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'amount of protein equivalent to a gram of nitrogen.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On average, protein contains approximately 16% nitrogen.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.25g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On average, protein contains approximately 16% nitrogen.\n\nTherefore: 1 g nitrogen × 6.25 = 6.25 g protein\nThe factor 6.25 is derived from: 100 ÷ 16 = 6.25\n\nThis conversion is commonly used when calculating nitrogen balance, particularly in clinical nutrition and protein assessment.","whyWrongChoices":"Alternative options: 0.16g, 54g, 10g"}'::jsonb),
('mc:the estimated risk of hiv transimission from mother to child during breastfeeding is?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the estimated risk of hiv transimission from mother to child during breastfeeding is?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the absence of any maternal or infant antiretroviral therapy (ART) interventions, the estimated risk of vertical HIV transmission specifically attributable to breastfeeding ranges between 5% and 20%.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5-20%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the absence of any maternal or infant antiretroviral therapy (ART) interventions, the estimated risk of vertical HIV transmission specifically attributable to breastfeeding ranges between 5% and 20%.\n\nThe Overall Risk Breakdown (Without Intervention):\n\n• Gestation and Labor/Delivery: 15% to 30% risk.\n• Breastfeeding: Additional 5% to 20% risk (which heavily depends on the duration of breastfeeding, as prolonged mixed feeding over 2 years can double the acquisition risk closer to 20%).\n• Total Combined Risk: 15% to 45%.","whyWrongChoices":"Alternative options: 5-10%, 10-15%, 15-25%"}'::jsonb),
('mc:which of the following characterizes that the cause precedes the effect or outcome in a study?:::temporal relationship', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following characterizes that the cause precedes the effect or outcome in a study?', 'Temporal relationship', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Temporal relationship dictates that the exposure or proposed independent variable must occur first in time before the development of the disease or outcome. In the rules of causal inference (such as the Bradford Hill Criteria), this is the most fundamental and absolute requirement to prove that one variable causes another.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Temporal relationship\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Temporal relationship dictates that the exposure or proposed independent variable must occur first in time before the development of the disease or outcome. In the rules of causal inference (such as the Bradford Hill Criteria), this is the most fundamental and absolute requirement to prove that one variable causes another.\n\n• Precision: Refers to the reproducibility and exactness of a specific measurement under unchanged conditions.\n• Internal validity: The degree to which a study successfully rules out alternative explanations (confounders) for the results. While temporal precedence is a crucial requirement to establish internal validity for a causal claim, the specific concept of \"time ordering\" itself is defined as temporality.\n• External validity: The extent to which the final results of a study can be generalized or applied to other settings, populations, or times.","whyWrongChoices":"Alternative options: Internal validity, External validity, Precision"}'::jsonb),
('mc:which of the following is not plagiarism?:::re-drawing the rct process, it not original or specific', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is not plagiarism?', 'Re-drawing the RCT process, it not original or specific', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Re-drawing the RCT process, it not original or specific\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Re-drawing a generic, standard Randomized Controlled Trial (RCT) flow diagram or process does not constitute plagiarism. The standard components of an RCT process (e.g., enrollment, allocation, intervention, follow-up, and analysis) are considered a universally accepted methodology and common scientific framework rather than a unique, specific text or an individual''s proprietary intellectual property.","whyWrongChoices":"Alternative options: Transcribing or modifying text from any printed material (encylopedias, books, magazines, newspapers), Using another student''s work and claiming it as your own, Using photographs, video or audio without permission"}'::jsonb),
