INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:which of the following enhances the absorption of zinc?:::glutamate', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following enhances the absorption of zinc?', 'Glutamate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glutamate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glutamate and other amino acids can enhance zinc absorption by forming soluble complexes with zinc and facilitating its uptake in the small intestine. In contrast, substances such as phytate strongly inhibit zinc absorption by binding zinc and forming poorly absorbed complexes.","whyWrongChoices":"Alternative options: Tryptophan, Acetyl CoA, Thiamin"}'::jsonb),
('mc:what is the major maternal fuel source during pregnancy?:::fat', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the major maternal fuel source during pregnancy?', 'Fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.\n\n• The Sparing Mechanism: Driven by placental hormones like Human Placental Lactogen (hPL), the mother develops a localized insulin resistance. This resistance decreases the mother''s own peripheral utilization of glucose.\n• The Primary Fuel: To compensate and sustain her own metabolic needs, the mother accelerates lipolysis (the breakdown of fat stores). This allows her tissues to rely heavily on fat (free fatty acids and ketones) as her primary personal fuel source, effectively \"sparing\" the sugar for fetal growth.","whyWrongChoices":"Alternative options: Sugar, Protein, Glycogen"}'::jsonb),
('mc:what is the major maternal fuel source during pregnancy?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the major maternal fuel source during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While the fetus relies almost exclusively on maternal glucose (carbohydrates) for its energy needs, the mother''s body undergoes a dramatic metabolic shift during pregnancy—particularly in the second half of gestation—to preserve that glucose for the rapidly growing baby.\n\n• The Sparing Mechanism: Driven by placental hormones like Human Placental Lactogen (hPL), the mother develops a localized insulin resistance. This resistance decreases the mother''s own peripheral utilization of glucose.\n• The Primary Fuel: To compensate and sustain her own metabolic needs, the mother accelerates lipolysis (the breakdown of fat stores). This allows her tissues to rely heavily on fat (free fatty acids and ketones) as her primary personal fuel source, effectively \"sparing\" the sugar for fetal growth.","whyWrongChoices":"Alternative options: Sugar, Protein, Glycogen"}'::jsonb),
('mc:in promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in zumba session because they are fond of dancing.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in promotion of a healthy lifestyle, which behavior change theory/model is best to use if the community members are eager to participate in zumba session because they are fond of dancing.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already \"fond of dancing\" and \"eager to participate,\" they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Self-determination Theory\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Self-determination Theory (SDT) focuses primarily on human motivation and the distinction between autonomous motivation and controlled motivation. When individuals are already \"fond of dancing\" and \"eager to participate,\" they are displaying intrinsic motivation—they want to perform the activity for the inherent enjoyment, fun, and satisfaction of the activity itself. SDT is the ideal framework here because it leverages and nurtures that existing internal drive by supporting basic psychological needs (autonomy, competence, and relatedness) to foster long-term adherence.\n\n• Precaution Adoption Process Model (PAPM): This is a stage theory best used for tracking how people move from being completely unaware of a health hazard to taking a precautionary action. It does not focus on enjoyable physical activities.\n• Health Belief Model (HBM): This model relies on a person’s perception of a health threat (susceptibility/severity) and balancing the benefits against the barriers of a preventative action. It is most useful for things like screening or vaccination compliance, not lifestyle activities done out of pure enjoyment.\n• Theory of Planned Behavior (TPB): This theory posits that behavior is driven by intentions, which are shaped by attitudes, social pressures (subjective norms), and perceived behavioral control. It would be the choice if the question emphasized that the community members are joining because their friends or family think it is a good idea.","whyWrongChoices":"Alternative options: Precaution Adoption Process Model, Health Belief Model, Theory of Planned Behavior"}'::jsonb),
('mc:percent increase of total blood volume during pregnancy?:::33', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'percent increase of total blood volume during pregnancy?', '33', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"33\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).\n\n1. Plasma Volume Increase: During pregnancy, blood plasma (the liquid portion) expands by approximately 45% to 50%.\n2. Red Blood Cell Mass Increase: Red blood cells only expand by about 20% to 30% (if the mother has adequate iron stores).\n3. The Total Net Blood Volume Increase: Because total blood volume is a weighted combination of these two components (Plasma + RBCs), the net average expansion across the entire duration of a typical healthy pregnancy equates to roughly one-third of the pre-pregnancy baseline, which mathematically maps directly to 33%.","whyWrongChoices":"Alternative options: 50, 18, 25"}'::jsonb),
('mc:percent increase of total blood volume during pregnancy?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'percent increase of total blood volume during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"33\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While clinical textbooks often state a general maximum increase of \"up to 50%\" for maternal fluid expansion overall, precise metabolic and board-style questions evaluate the exact fractional mathematical relationship between the two main components of blood: Plasma and Red Blood Cells (RBCs).\n\n1. Plasma Volume Increase: During pregnancy, blood plasma (the liquid portion) expands by approximately 45% to 50%.\n2. Red Blood Cell Mass Increase: Red blood cells only expand by about 20% to 30% (if the mother has adequate iron stores).\n3. The Total Net Blood Volume Increase: Because total blood volume is a weighted combination of these two components (Plasma + RBCs), the net average expansion across the entire duration of a typical healthy pregnancy equates to roughly one-third of the pre-pregnancy baseline, which mathematically maps directly to 33%.","whyWrongChoices":"Alternative options: 50, 18, 25"}'::jsonb),
('mc:under the mandatory food fortification program, cooking oil is fortified with::::vit a', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'under the mandatory food fortification program, cooking oil is fortified with:', 'Vit A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"See RA 8976 (Philippine Food Fortification Act of 2000):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"See RA 8976 (Philippine Food Fortification Act of 2000):\n\nA. Vitamin A – oil, sugar\nB. Iron – rice\nC. Iodine - salt\nD. Vitamin A and iron - wheat flour","whyWrongChoices":"Alternative options: Iron, Iodine, Vit A and Iron"}'::jsonb),
('mc:the goal of nutrition education::::to change behavior', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the goal of nutrition education:', 'To change behavior', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To change behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.\n\nPrograms that only focus on data transfer fail if they do not fix bad habits. Effective nutrition education is specifically designed to act as a motivational tool that translates knowledge into the continuous, voluntary adoption of healthy eating patterns and long-term dietary behavior changes.","whyWrongChoices":"Alternative options: To increase knowledge, To improve practices, To promote health"}'::jsonb),
('mc:the goal of nutrition education::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the goal of nutrition education:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To change behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While nutrition education naturally transfers information and increases awareness, global health frameworks (such as the FAO and USDA) explicitly state that the ultimate goal of nutrition education is to change behavior.\n\nPrograms that only focus on data transfer fail if they do not fix bad habits. Effective nutrition education is specifically designed to act as a motivational tool that translates knowledge into the continuous, voluntary adoption of healthy eating patterns and long-term dietary behavior changes.","whyWrongChoices":"Alternative options: To increase knowledge, To improve practices, To promote health"}'::jsonb),
('mc:an element of behavior change which pertains to the capacity of individual to perform a recommended response.:::self-efficacy', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an element of behavior change which pertains to the capacity of individual to perform a recommended response.', 'Self-efficacy', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Self-efficacy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.\n\n• Attitude: This refers to an individual''s positive or negative evaluations, feelings, or beliefs about a specific behavior, rather than their physical or mental capacity to perform it.\n• Reactance: This is a psychological resistance or negative reaction that occurs when individuals feel their personal freedom or choices are being threatened or restricted.\n• Cues to action: These are internal or external triggers (such as a doctor''s advice, a reminder app, or a family illness) that prompt a person to take action.","whyWrongChoices":"Alternative options: Attitude, Cues to action, Reactance"}'::jsonb),
('mc:an element of behavior change which pertains to the capacity of individual to perform a recommended response.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an element of behavior change which pertains to the capacity of individual to perform a recommended response.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Self-efficacy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In health education and behavioral change models (such as the Health Belief Model and Social Cognitive Theory), self-efficacy is defined as an individual''s belief in their own capability to successfully execute a specific behavior or perform a recommended health response.\n\n• Attitude: This refers to an individual''s positive or negative evaluations, feelings, or beliefs about a specific behavior, rather than their physical or mental capacity to perform it.\n• Reactance: This is a psychological resistance or negative reaction that occurs when individuals feel their personal freedom or choices are being threatened or restricted.\n• Cues to action: These are internal or external triggers (such as a doctor''s advice, a reminder app, or a family illness) that prompt a person to take action.","whyWrongChoices":"Alternative options: Attitude, Cues to action, Reactance"}'::jsonb),
('mc:who is the chair of provincial nutrition committee?:::governor', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'who is the chair of provincial nutrition committee?', 'Governor', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Governor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At every level of the local government unit (LGU) framework in the Philippines, the Local Chief Executive serves as the default chairperson of the local nutrition committee:\n\n• Provincial Level: Chaired by the Governor.\n• City / Municipal Level: Chaired by the Mayor.\n• Barangay Level: Chaired by the Barangay Captain (Punong Barangay).\n\nThe Provincial Nutrition Action Officer (PNAO) operates under the leadership of the Governor to handle the day-to-day operations, implementation, and coordination of the province''s nutrition programs.","whyWrongChoices":"Alternative options: Provincial Nutrition Action Officer, Barangay Captain, Mayor"}'::jsonb),
('mc:which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?:::theory of planned behavior', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?', 'Theory of Planned Behavior', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Theory of Planned Behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:\n\n1. Attitude toward the behavior: The community members'' personal belief that they will benefit from the nutrition program.\n2. Subjective Norms: The perceived social pressure from their environment, specifically because their friends think it is also a good idea.\n3. Perceived Behavioral Control: Their perceived ease or ability to execute the behavior, which fosters their readiness to get involved.\n\n• Self-determination Theory: Focuses heavily on the internal spectrum of motivation (intrinsic vs. extrinsic), which would be the primary choice if the question emphasized doing the activity out of pure, inherent enjoyment.\n• Precaution Adoption Process Model: This is a sequential stage-of-readiness model used to trace how an individual moves from complete unawareness to taking a specific health precaution.\n• Health Belief Model: While it includes \"perceived benefits\", it relies heavily on an individual''s evaluation of a health threat (perceived susceptibility and severity of an illness), which is not the primary focus or motivator described in this scenario.","whyWrongChoices":"Alternative options: Precaution Adoption Process Model, Health Belief Model, Self-determination Theory"}'::jsonb),
('mc:which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which behavior change theory/model is best to use if the community members are interested to be involved in the nutrition programs because they believe that they will benefit from the program and their friends think it is also a good idea?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Theory of Planned Behavior\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Theory of Planned Behavior (TPB) posits that an individual''s decision to engage in a specific behavior is driven directly by their behavioral intention. This intention is uniquely determined by three core constructs that match this scenario perfectly:\n\n1. Attitude toward the behavior: The community members'' personal belief that they will benefit from the nutrition program.\n2. Subjective Norms: The perceived social pressure from their environment, specifically because their friends think it is also a good idea.\n3. Perceived Behavioral Control: Their perceived ease or ability to execute the behavior, which fosters their readiness to get involved.\n\n• Self-determination Theory: Focuses heavily on the internal spectrum of motivation (intrinsic vs. extrinsic), which would be the primary choice if the question emphasized doing the activity out of pure, inherent enjoyment.\n• Precaution Adoption Process Model: This is a sequential stage-of-readiness model used to trace how an individual moves from complete unawareness to taking a specific health precaution.\n• Health Belief Model: While it includes \"perceived benefits\", it relies heavily on an individual''s evaluation of a health threat (perceived susceptibility and severity of an illness), which is not the primary focus or motivator described in this scenario.","whyWrongChoices":"Alternative options: Precaution Adoption Process Model, Health Belief Model, Self-determination Theory"}'::jsonb),
('mc:which communication model is to support action?:::diffusion of innovation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which communication model is to support action?', 'Diffusion of Innovation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diffusion of Innovation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.\n\nIt focuses heavily on how information is packaged and delivered via specific communication channels over time to move groups from initial awareness directly into concrete adoption and action.\n\n• Social cognitive theory / Self-efficacy model: These focus primarily on the cognitive determinants of a behavior—specifically how an individual''s confidence in their own ability (self-efficacy) and their social environment influence their personal behavior.\n• Transtheoretical model: This is a stage theory that maps out an individual''s motivational readiness to change behavior (from Precontemplation to Maintenance) rather than functioning primarily as an operational communication model to drive group action.","whyWrongChoices":"Alternative options: Transtheoretical model, Self-efficacy model, Social cognitive theory"}'::jsonb),
('mc:which communication model is to support action?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which communication model is to support action?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diffusion of Innovation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diffusion of Innovation is recognized within health promotion, nutrition education, and community communication frameworks as a model designed to support action. It provides a systematic approach for rolling out and communicating new behaviors, ideas, or practices so that they are actively adopted and sustained across a population or community.\n\nIt focuses heavily on how information is packaged and delivered via specific communication channels over time to move groups from initial awareness directly into concrete adoption and action.\n\n• Social cognitive theory / Self-efficacy model: These focus primarily on the cognitive determinants of a behavior—specifically how an individual''s confidence in their own ability (self-efficacy) and their social environment influence their personal behavior.\n• Transtheoretical model: This is a stage theory that maps out an individual''s motivational readiness to change behavior (from Precontemplation to Maintenance) rather than functioning primarily as an operational communication model to drive group action.","whyWrongChoices":"Alternative options: Transtheoretical model, Self-efficacy model, Social cognitive theory"}'::jsonb),
('mc:a nutrition education method that includes bench conferences.:::group discussion', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a nutrition education method that includes bench conferences.', 'Group discussion', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Group discussion\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.\n\nA bench conference occurs when a health worker or nutritionist gathers a small cluster of mothers, caregivers, or patients who are sitting together on a bench waiting for their turn in a rural health unit or clinic.\n\n• Rather than structured one-on-one counseling behind closed doors, the educator utilizes this shared waiting space to initiate a small group interaction.\n• Because it encourages the individuals sitting together to exchange ideas, ask questions, and learn from each other''s experiences under the guidance of the facilitator, it is classified academically under Group discussion methods.","whyWrongChoices":"Alternative options: Nutrition counseling, Mass media, Social marketing"}'::jsonb),
('mc:a nutrition education method that includes bench conferences.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a nutrition education method that includes bench conferences.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Group discussion\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In community and public health nutrition in the Philippines (such as field protocols followed by Barangay Nutrition Scholars), nutrition education methods are rigidly classified into distinct operational categories.\n\nA bench conference occurs when a health worker or nutritionist gathers a small cluster of mothers, caregivers, or patients who are sitting together on a bench waiting for their turn in a rural health unit or clinic.\n\n• Rather than structured one-on-one counseling behind closed doors, the educator utilizes this shared waiting space to initiate a small group interaction.\n• Because it encourages the individuals sitting together to exchange ideas, ask questions, and learn from each other''s experiences under the guidance of the facilitator, it is classified academically under Group discussion methods.","whyWrongChoices":"Alternative options: Nutrition counseling, Mass media, Social marketing"}'::jsonb),
('mc:which province is a priority area in the ppan 2023-2028?:::basilan', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which province is a priority area in the ppan 2023-2028?', 'Basilan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Basilan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Philippine Plan of Action for Nutrition (PPAN) 2023-2028 identifies 34 high-priority provinces across the country. These priority areas are selected by the National Nutrition Council (NNC) based on a high magnitude of child stunting (undernutrition) and severe household food poverty thresholds.\n\nBasilan is officially classified as a high-priority province, ranking 9th overall nationwide on the target list for intensive nutrition interventions and financial support.\n\nThe Top 10 highest priority provinces targeted for intensive, multi-sectoral nutrition interventions are:\n1. Leyte\n2. Sulu\n3. Negros Occidental\n4. Negros Oriental\n5. Samar\n6. Lanao del Norte\n7. Masbate\n8. Palawan\n9. Basilan\n10. Cebu\n\nKey Broad Facts on the 34 Priority Areas:\n• The Rest of the Top 16: Immediately following the top ten are Camarines Sur, Quezon, Zamboanga del Norte, Zamboanga del Sur, Maguindanao, and Bukidnon.\n• Convergent Strategy: Government programs like the Tutok Kainan Dietary Supplementation Program prioritize these specific locations to provide nutritional support during the critical First 1,000 Days of child development.","whyWrongChoices":"Alternative options: Batangas, Batanes, Benguet"}'::jsonb),
('mc:what is the first step in conducting a training?:::needs assessment', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the first step in conducting a training?', 'Needs assessment', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Needs assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.\n\nThe Training Process Order:\n\n1. Needs assessment (Identify the gaps)\n2. Identification of training objectives (Define what success looks like based on the gaps)\n3. Preparation for training design / Planning (Outline methods, timelines, and content)\n4. Implementation (Conducting the training)\n5. Evaluation (Measuring the training''s effectiveness)","whyWrongChoices":"Alternative options: Planning for the training, Preparation for training design, Identification of training objectives"}'::jsonb),
('mc:what is the first step in conducting a training?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the first step in conducting a training?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Needs assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In the systematic training cycle (often outlined in Human Resources and instructional design frameworks like the ADDIE model), Needs assessment (or Training Needs Analysis/TNA) is always the first step. Before you can plan, design, or set objectives, you must first identify the current performance or skill gaps to determine if training is actually necessary, what specific issues need to be resolved, and who requires the training.\n\nThe Training Process Order:\n\n1. Needs assessment (Identify the gaps)\n2. Identification of training objectives (Define what success looks like based on the gaps)\n3. Preparation for training design / Planning (Outline methods, timelines, and content)\n4. Implementation (Conducting the training)\n5. Evaluation (Measuring the training''s effectiveness)","whyWrongChoices":"Alternative options: Planning for the training, Preparation for training design, Identification of training objectives"}'::jsonb),
('mc:which is an example of non-verbal communication?:::tone of voice', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is an example of non-verbal communication?', 'Tone of voice', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tone of voice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","whyWrongChoices":"Alternative options: Maps, Traffic signals, Reports"}'::jsonb),
('mc:which is an example of non-verbal communication?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is an example of non-verbal communication?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tone of voice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tone of voice (technically known as paralinguistics or paralanguage) is a principal form of non-verbal communication. While the spoken words themselves represent the verbal message, how those words are delivered—including the pitch, volume, speed, inflection, and tone—functions separate from actual language to convey underlying emotions, attitudes, and meanings. For example, saying \"I''m fine\" with a sarcastic or trembling tone completely modifies the message''s meaning without altering the words used.","whyWrongChoices":"Alternative options: Maps, Traffic signals, Reports"}'::jsonb),
