INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:a 28-year-old pregnant woman reports nausea and vomiting, with:::at risk for malnutrition', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a 28-year-old pregnant woman reports nausea and vomiting, with', 'At risk for malnutrition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Reduced intake plus physical findings of muscle wasting indicate she is at risk and needs close monitoring/intervention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"At risk for malnutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Reduced intake plus physical findings of muscle wasting indicate she is at risk and needs close monitoring/intervention.","whyWrongChoices":"Alternative options: Adequate intake, no problem, Option C, Normal pregnancy symptoms only"}'::jsonb),
('mc:the following are the domains of nutrition diagnosis, except::::biochemical nutrition diagnoses', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are the domains of nutrition diagnosis, except:', 'Biochemical Nutrition Diagnoses', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The three domains of nutrition diagnosis in the Nutrition Care Process are Intake, Clinical, and Behavioral-Environmental. A nutrition diagnosis identifies a nutrition-related problem that the RND can address through intervention. While the term “Biochemical Nutrition Diagnoses” is one of the classes under the Clinical Nutrition Diagnoses Domain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biochemical Nutrition Diagnoses\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The three domains of nutrition diagnosis in the Nutrition Care Process are Intake, Clinical, and Behavioral-Environmental. A nutrition diagnosis identifies a nutrition-related problem that the RND can address through intervention. While the term “Biochemical Nutrition Diagnoses” is one of the classes under the Clinical Nutrition Diagnoses Domain.","whyWrongChoices":"Alternative options: Intake Nutrition Diagnoses, Clinical Nutrition Diagnoses, Behavioral-environmental Nutrition Diagnoses"}'::jsonb),
('mc:the following are the domains of nutrition diagnosis, except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are the domains of nutrition diagnosis, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The three domains of nutrition diagnosis in the Nutrition Care Process are Intake, Clinical, and Behavioral-Environmental. A nutrition diagnosis identifies a nutrition-related problem that the RND can address through intervention. While the term “Biochemical Nutrition Diagnoses” is one of the classes under the Clinical Nutrition Diagnoses Domain.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biochemical Nutrition Diagnoses\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The three domains of nutrition diagnosis in the Nutrition Care Process are Intake, Clinical, and Behavioral-Environmental. A nutrition diagnosis identifies a nutrition-related problem that the RND can address through intervention. While the term “Biochemical Nutrition Diagnoses” is one of the classes under the Clinical Nutrition Diagnoses Domain.","whyWrongChoices":"Alternative options: Intake Nutrition Diagnoses, Clinical Nutrition Diagnoses, Behavioral-environmental Nutrition Diagnoses"}'::jsonb),
('mc:dietary management for guillain-barré syndrome::::high energy and protein tube feedings', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary management for guillain-barré syndrome:', 'high energy and protein tube feedings', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Guillain-Barré syndrome can cause progressive muscle weakness, dysphagia, and respiratory muscle paralysis. Patients with severe disease may be unable to meet their nutritional needs orally and may require enteral nutrition. Adequate energy and protein are important because of increased metabolic demands and the need to preserve lean body mass during prolonged illness and immobility. Tube feeding is appropriate when oral intake is unsafe or inadequate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high energy and protein tube feedings\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Guillain-Barré syndrome can cause progressive muscle weakness, dysphagia, and respiratory muscle paralysis. Patients with severe disease may be unable to meet their nutritional needs orally and may require enteral nutrition. Adequate energy and protein are important because of increased metabolic demands and the need to preserve lean body mass during prolonged illness and immobility. Tube feeding is appropriate when oral intake is unsafe or inadequate.","whyWrongChoices":"Alternative options: thiamine supplementation, adequate hydration, avoidance of alcohol"}'::jsonb),
('mc:dietary management for guillain-barré syndrome::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary management for guillain-barré syndrome:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Guillain-Barré syndrome can cause progressive muscle weakness, dysphagia, and respiratory muscle paralysis. Patients with severe disease may be unable to meet their nutritional needs orally and may require enteral nutrition. Adequate energy and protein are important because of increased metabolic demands and the need to preserve lean body mass during prolonged illness and immobility. Tube feeding is appropriate when oral intake is unsafe or inadequate.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"high energy and protein tube feedings\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Guillain-Barré syndrome can cause progressive muscle weakness, dysphagia, and respiratory muscle paralysis. Patients with severe disease may be unable to meet their nutritional needs orally and may require enteral nutrition. Adequate energy and protein are important because of increased metabolic demands and the need to preserve lean body mass during prolonged illness and immobility. Tube feeding is appropriate when oral intake is unsafe or inadequate.","whyWrongChoices":"Alternative options: thiamine supplementation, adequate hydration, avoidance of alcohol"}'::jsonb),
('mc:parental nutrition can be discontinued when approximately this percentage of estimated energy needs are being met by oral intake, tube feeding or combination of both.:::0.75', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'parental nutrition can be discontinued when approximately this percentage of estimated energy needs are being met by oral intake, tube feeding or combination of both.', '0.75', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"PN may generally be discontinued when the patient can consistently obtain approximately 60–75% or more of estimated energy and protein requirements through oral and/or enteral intake, provided that nutritional status is stable and intake is expected to remain adequate. In the context of this question, 75% is the best answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.75\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"PN may generally be discontinued when the patient can consistently obtain approximately 60–75% or more of estimated energy and protein requirements through oral and/or enteral intake, provided that nutritional status is stable and intake is expected to remain adequate. In the context of this question, 75% is the best answer.","whyWrongChoices":"Alternative options: 0.5, 0,6, 0.8"}'::jsonb),
('mc:parental nutrition can be discontinued when approximately this percentage of estimated energy needs are being met by oral intake, tube feeding or combination of both.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'parental nutrition can be discontinued when approximately this percentage of estimated energy needs are being met by oral intake, tube feeding or combination of both.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"PN may generally be discontinued when the patient can consistently obtain approximately 60–75% or more of estimated energy and protein requirements through oral and/or enteral intake, provided that nutritional status is stable and intake is expected to remain adequate. In the context of this question, 75% is the best answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.75\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"PN may generally be discontinued when the patient can consistently obtain approximately 60–75% or more of estimated energy and protein requirements through oral and/or enteral intake, provided that nutritional status is stable and intake is expected to remain adequate. In the context of this question, 75% is the best answer.","whyWrongChoices":"Alternative options: 0.5, 0,6, 0.8"}'::jsonb),
('mc:method of delivery of en when the rate is 300 to 400 ml, 20 to 30 minutes, several times/day via gravity drip or syringe, as determined by medical status, feeding route and volume and nutritional goals.:::intermittent', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'method of delivery of en when the rate is 300 to 400 ml, 20 to 30 minutes, several times/day via gravity drip or syringe, as determined by medical status, feeding route and volume and nutritional goals.', 'intermittent', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Intermittent enteral feeding provides formula at scheduled intervals, commonly several times throughout the day. Each feeding may be delivered by gravity or syringe over approximately 20–30 minutes, depending on the patient''s medical status, feeding route, volume tolerance, and nutritional requirements. This approach more closely resembles normal meal patterns than continuous feeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"intermittent\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Intermittent enteral feeding provides formula at scheduled intervals, commonly several times throughout the day. Each feeding may be delivered by gravity or syringe over approximately 20–30 minutes, depending on the patient''s medical status, feeding route, volume tolerance, and nutritional requirements. This approach more closely resembles normal meal patterns than continuous feeding.\n\nBolus → larger amount, relatively fast\nIntermittent → scheduled “meals”\nCyclic → continuous, but only part of the day/night\nContinuous → nonstop over an extended period","whyWrongChoices":"Alternative options: bolus, cyclic, continuous"}'::jsonb),
('mc:method of delivery of en when the rate is 300 to 400 ml, 20 to 30 minutes, several times/day via gravity drip or syringe, as determined by medical status, feeding route and volume and nutritional goals.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'method of delivery of en when the rate is 300 to 400 ml, 20 to 30 minutes, several times/day via gravity drip or syringe, as determined by medical status, feeding route and volume and nutritional goals.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Intermittent enteral feeding provides formula at scheduled intervals, commonly several times throughout the day. Each feeding may be delivered by gravity or syringe over approximately 20–30 minutes, depending on the patient''s medical status, feeding route, volume tolerance, and nutritional requirements. This approach more closely resembles normal meal patterns than continuous feeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"intermittent\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Intermittent enteral feeding provides formula at scheduled intervals, commonly several times throughout the day. Each feeding may be delivered by gravity or syringe over approximately 20–30 minutes, depending on the patient''s medical status, feeding route, volume tolerance, and nutritional requirements. This approach more closely resembles normal meal patterns than continuous feeding.\n\nBolus → larger amount, relatively fast\nIntermittent → scheduled “meals”\nCyclic → continuous, but only part of the day/night\nContinuous → nonstop over an extended period","whyWrongChoices":"Alternative options: bolus, cyclic, continuous"}'::jsonb),
('mc:enternal nutrition composed of intact cpf::::polymeric', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'enternal nutrition composed of intact cpf:', 'polymeric', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Polymeric formulas contain intact, whole macronutrients, including intact proteins, carbohydrates, and fats. They are designed for patients with a functioning gastrointestinal tract who can digest and absorb these nutrients adequately. They are the most commonly used type of standard enteral formula.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"polymeric\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Polymeric formulas contain intact, whole macronutrients, including intact proteins, carbohydrates, and fats. They are designed for patients with a functioning gastrointestinal tract who can digest and absorb these nutrients adequately. They are the most commonly used type of standard enteral formula.\n\nIntact CPF = Polymeric;\nBroken down = Hydrolyzed;\nOne nutrient at a time = Modular;\nSpecific disease = Specialty","whyWrongChoices":"Alternative options: modular, hydrolyzed, specialty"}'::jsonb),
('mc:enternal nutrition composed of intact cpf::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'enternal nutrition composed of intact cpf:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Polymeric formulas contain intact, whole macronutrients, including intact proteins, carbohydrates, and fats. They are designed for patients with a functioning gastrointestinal tract who can digest and absorb these nutrients adequately. They are the most commonly used type of standard enteral formula.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"polymeric\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Polymeric formulas contain intact, whole macronutrients, including intact proteins, carbohydrates, and fats. They are designed for patients with a functioning gastrointestinal tract who can digest and absorb these nutrients adequately. They are the most commonly used type of standard enteral formula.\n\nIntact CPF = Polymeric;\nBroken down = Hydrolyzed;\nOne nutrient at a time = Modular;\nSpecific disease = Specialty","whyWrongChoices":"Alternative options: modular, hydrolyzed, specialty"}'::jsonb),
('mc:energy requirement for patients on pre-dialysis.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'energy requirement for patients on pre-dialysis.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For adults with chronic kidney disease (CKD) who are not yet on dialysis, an energy intake of approximately 30–35 kcal/kg body weight/day has traditionally been recommended, with the exact target individualized according to age, physical activity, body size, nutritional status, and metabolic needs. Thus, among the choices, 35 kcal/kg BW is the best answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"35 kcal/kg BW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For adults with chronic kidney disease (CKD) who are not yet on dialysis, an energy intake of approximately 30–35 kcal/kg body weight/day has traditionally been recommended, with the exact target individualized according to age, physical activity, body size, nutritional status, and metabolic needs. Thus, among the choices, 35 kcal/kg BW is the best answer.","whyWrongChoices":"Alternative options: 25 kcal/kg BW, 30 kcal/kg BW, 40 kca/kg BW"}'::jsonb),
('mc:a compilation in parental nutrition with symptoms showing failure to grow, dermal problems, and poor immune function.:::essential fatty acid deficiency', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a compilation in parental nutrition with symptoms showing failure to grow, dermal problems, and poor immune function.', 'Essential Fatty Acid Deficiency', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Essential fatty acid deficiency (EFAD) can occur in patients receiving parenteral nutrition when adequate essential fatty acids are not provided, particularly with prolonged fat-free PN. Clinical manifestations include poor growth or growth failure, dermatitis and other skin changes, impaired wound healing, and decreased immune function. Linoleic acid deficiency is particularly important because linoleic acid is an essential omega-6 fatty acid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Essential Fatty Acid Deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Essential fatty acid deficiency (EFAD) can occur in patients receiving parenteral nutrition when adequate essential fatty acids are not provided, particularly with prolonged fat-free PN. Clinical manifestations include poor growth or growth failure, dermatitis and other skin changes, impaired wound healing, and decreased immune function. Linoleic acid deficiency is particularly important because linoleic acid is an essential omega-6 fatty acid.","whyWrongChoices":"Alternative options: Metabolic imbalance, Air embolism, Hemothorax"}'::jsonb),
('mc:a compilation in parental nutrition with symptoms showing failure to grow, dermal problems, and poor immune function.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a compilation in parental nutrition with symptoms showing failure to grow, dermal problems, and poor immune function.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Essential fatty acid deficiency (EFAD) can occur in patients receiving parenteral nutrition when adequate essential fatty acids are not provided, particularly with prolonged fat-free PN. Clinical manifestations include poor growth or growth failure, dermatitis and other skin changes, impaired wound healing, and decreased immune function. Linoleic acid deficiency is particularly important because linoleic acid is an essential omega-6 fatty acid.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Essential Fatty Acid Deficiency\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Essential fatty acid deficiency (EFAD) can occur in patients receiving parenteral nutrition when adequate essential fatty acids are not provided, particularly with prolonged fat-free PN. Clinical manifestations include poor growth or growth failure, dermatitis and other skin changes, impaired wound healing, and decreased immune function. Linoleic acid deficiency is particularly important because linoleic acid is an essential omega-6 fatty acid.","whyWrongChoices":"Alternative options: Metabolic imbalance, Air embolism, Hemothorax"}'::jsonb),
('mc:high protein is given to burned patients to::::replace losses', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'high protein is given to burned patients to:', 'replace losses', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Severe burns cause a marked hypermetabolic and hypercatabolic response, resulting in substantial protein breakdown and nitrogen losses. Protein requirements are therefore increased to replace these losses, support wound healing, immune function, and maintenance of lean body mass. Protein itself is not primarily given as an energy source; adequate carbohydrate and fat are provided to meet energy needs and help spare protein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"replace losses\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Severe burns cause a marked hypermetabolic and hypercatabolic response, resulting in substantial protein breakdown and nitrogen losses. Protein requirements are therefore increased to replace these losses, support wound healing, immune function, and maintenance of lean body mass. Protein itself is not primarily given as an energy source; adequate carbohydrate and fat are provided to meet energy needs and help spare protein.","whyWrongChoices":"Alternative options: provide energy reserves, control water retention, meet energy requiements"}'::jsonb),
('mc:high protein is given to burned patients to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'high protein is given to burned patients to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Severe burns cause a marked hypermetabolic and hypercatabolic response, resulting in substantial protein breakdown and nitrogen losses. Protein requirements are therefore increased to replace these losses, support wound healing, immune function, and maintenance of lean body mass. Protein itself is not primarily given as an energy source; adequate carbohydrate and fat are provided to meet energy needs and help spare protein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"replace losses\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Severe burns cause a marked hypermetabolic and hypercatabolic response, resulting in substantial protein breakdown and nitrogen losses. Protein requirements are therefore increased to replace these losses, support wound healing, immune function, and maintenance of lean body mass. Protein itself is not primarily given as an energy source; adequate carbohydrate and fat are provided to meet energy needs and help spare protein.","whyWrongChoices":"Alternative options: provide energy reserves, control water retention, meet energy requiements"}'::jsonb),
('mc:the following are characteristics of hypothyroidism except::::none of the above', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are characteristics of hypothyroidism except:', 'none of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cold intolerance, bradycardia, and constipation are all classic manifestations of hypothyroidism. Reduced thyroid hormone slows metabolic activity and affects multiple body systems. Patients may also experience fatigue, weight gain, dry skin, and slowed mental and physical activity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"none of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cold intolerance, bradycardia, and constipation are all classic manifestations of hypothyroidism. Reduced thyroid hormone slows metabolic activity and affects multiple body systems. Patients may also experience fatigue, weight gain, dry skin, and slowed mental and physical activity.","whyWrongChoices":"Alternative options: cold intolerance, bradycardia, constipation"}'::jsonb),
('mc:energy requirement for patients on pre-dialysis.:::35 kcal/kg bw', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'energy requirement for patients on pre-dialysis.', '35 kcal/kg BW', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For adults with chronic kidney disease (CKD) who are not yet on dialysis, an energy intake of approximately 30–35 kcal/kg body weight/day has traditionally been recommended, with the exact target individualized according to age, physical activity, body size, nutritional status, and metabolic needs. Thus, among the choices, 35 kcal/kg BW is the best answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"35 kcal/kg BW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For adults with chronic kidney disease (CKD) who are not yet on dialysis, an energy intake of approximately 30–35 kcal/kg body weight/day has traditionally been recommended, with the exact target individualized according to age, physical activity, body size, nutritional status, and metabolic needs. Thus, among the choices, 35 kcal/kg BW is the best answer.","whyWrongChoices":"Alternative options: 25 kcal/kg BW, 30 kcal/kg BW, 40 kca/kg BW"}'::jsonb),
('mc:a 28-year-old pregnant woman reports nausea and vomiting, with:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a 28-year-old pregnant woman reports nausea and vomiting, with', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Reduced intake plus physical findings of muscle wasting indicate she is at risk and needs close monitoring/intervention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"At risk for malnutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Reduced intake plus physical findings of muscle wasting indicate she is at risk and needs close monitoring/intervention.","whyWrongChoices":"Alternative options: Adequate intake, no problem, Option C, Normal pregnancy symptoms only"}'::jsonb),
('mc:patients under maoi medication should be put in what type of restricted diet?:::tyramine-restricted', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'patients under maoi medication should be put in what type of restricted diet?', 'Tyramine-restricted', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Monoamine oxidase (MAO) normally helps metabolize tyramine in the gastrointestinal tract. MAO inhibition can allow more tyramine to enter the systemic circulation, where it promotes the release of norepinephrine. Excessive tyramine intake while taking traditional, nonselective MAOIs can therefore cause a potentially severe hypertensive reaction, characterized by a rapid increase in blood pressure and associated headache and other symptoms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tyramine-restricted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Monoamine oxidase (MAO) normally helps metabolize tyramine in the gastrointestinal tract. MAO inhibition can allow more tyramine to enter the systemic circulation, where it promotes the release of norepinephrine. Excessive tyramine intake while taking traditional, nonselective MAOIs can therefore cause a potentially severe hypertensive reaction, characterized by a rapid increase in blood pressure and associated headache and other symptoms.","whyWrongChoices":"Alternative options: Phenylalanine-restricted, BCAA-restricted, Tyrosine-restricted"}'::jsonb),
('mc:patients under maoi medication should be put in what type of restricted diet?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'patients under maoi medication should be put in what type of restricted diet?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Monoamine oxidase (MAO) normally helps metabolize tyramine in the gastrointestinal tract. MAO inhibition can allow more tyramine to enter the systemic circulation, where it promotes the release of norepinephrine. Excessive tyramine intake while taking traditional, nonselective MAOIs can therefore cause a potentially severe hypertensive reaction, characterized by a rapid increase in blood pressure and associated headache and other symptoms.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tyramine-restricted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Monoamine oxidase (MAO) normally helps metabolize tyramine in the gastrointestinal tract. MAO inhibition can allow more tyramine to enter the systemic circulation, where it promotes the release of norepinephrine. Excessive tyramine intake while taking traditional, nonselective MAOIs can therefore cause a potentially severe hypertensive reaction, characterized by a rapid increase in blood pressure and associated headache and other symptoms.","whyWrongChoices":"Alternative options: Phenylalanine-restricted, BCAA-restricted, Tyrosine-restricted"}'::jsonb),
('mc:energy recommedantion for patients with stage 3 ckd:::25-35 kcal/kg', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'energy recommedantion for patients with stage 3 ckd', '25-35 kcal/kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The current KDOQI 2020 Nutrition in CKD guideline recommends prescribing 25–35 kcal/kg ideal body weight/day for metabolically stable adults with CKD stages 1–5, including Stage 3 CKD. The exact energy prescription should be individualized according to age, sex, physical activity, body composition, weight goals, CKD stage, and concurrent illness or inflammation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"25-35 kcal/kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The current KDOQI 2020 Nutrition in CKD guideline recommends prescribing 25–35 kcal/kg ideal body weight/day for metabolically stable adults with CKD stages 1–5, including Stage 3 CKD. The exact energy prescription should be individualized according to age, sex, physical activity, body composition, weight goals, CKD stage, and concurrent illness or inflammation.","whyWrongChoices":"Alternative options: 15-20 kcal/kg, 30-40 kcal/kg, <30 kcal/kg"}'::jsonb),
('mc:energy recommedantion for patients with stage 3 ckd:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'energy recommedantion for patients with stage 3 ckd', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The current KDOQI 2020 Nutrition in CKD guideline recommends prescribing 25–35 kcal/kg ideal body weight/day for metabolically stable adults with CKD stages 1–5, including Stage 3 CKD. The exact energy prescription should be individualized according to age, sex, physical activity, body composition, weight goals, CKD stage, and concurrent illness or inflammation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"25-35 kcal/kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The current KDOQI 2020 Nutrition in CKD guideline recommends prescribing 25–35 kcal/kg ideal body weight/day for metabolically stable adults with CKD stages 1–5, including Stage 3 CKD. The exact energy prescription should be individualized according to age, sex, physical activity, body composition, weight goals, CKD stage, and concurrent illness or inflammation.","whyWrongChoices":"Alternative options: 15-20 kcal/kg, 30-40 kcal/kg, <30 kcal/kg"}'::jsonb),
('mc:which of the following medications affect food intake by altering salivary secretions?:::phenobarbital', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following medications affect food intake by altering salivary secretions?', 'Phenobarbital', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phenobarbital can cause dry mouth (xerostomia) by reducing salivary secretion. Reduced saliva can affect taste, chewing, swallowing, and overall food intake, potentially contributing to decreased appetite or difficulty eating. This is particularly relevant in nutrition assessment because medication-related oral effects can indirectly compromise dietary intake.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Phenobarbital\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phenobarbital can cause dry mouth (xerostomia) by reducing salivary secretion. Reduced saliva can affect taste, chewing, swallowing, and overall food intake, potentially contributing to decreased appetite or difficulty eating. This is particularly relevant in nutrition assessment because medication-related oral effects can indirectly compromise dietary intake.","whyWrongChoices":"Alternative options: Digitalis, Amphetamines, Methotrexate"}'::jsonb),
