INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:microorganism commonly associated with fecal contamination::::e. coli', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'microorganism commonly associated with fecal contamination:', 'e. coli', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"E. coli is a type of bacteria that naturally resides in the intestines of humans and animals. While most strains of E. coli are harmless, certain pathogenic strains, such as E. coli O157:H7, can cause foodborne illness when ingested through contaminated food or water. Fecal contamination of food or water sources can introduce these harmful strains, leading to outbreaks of foodborne illnesses.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"e. coli\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"E. coli is a type of bacteria that naturally resides in the intestines of humans and animals. While most strains of E. coli are harmless, certain pathogenic strains, such as E. coli O157:H7, can cause foodborne illness when ingested through contaminated food or water. Fecal contamination of food or water sources can introduce these harmful strains, leading to outbreaks of foodborne illnesses.\n\n• Campylobacter jejuni: A bacterium commonly associated with foodborne illness from consumption of contaminated poultry, unpasteurized milk, and contaminated water.\n• Bacillus cereus: A bacterium that can cause food poisoning through the production of toxins in improperly stored or cooked foods, particularly rice and other starchy foods.\n• Trichinella spiralis: A parasitic worm that causes trichinellosis (trichinosis) when raw or undercooked meat containing encysted larvae is consumed.","whyWrongChoices":"Alternative options: campylobacter jejuni, bacillus cereus, trichinella spiralis"}'::jsonb),
('mc:microorganism commonly associated with fecal contamination::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'microorganism commonly associated with fecal contamination:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"E. coli is a type of bacteria that naturally resides in the intestines of humans and animals. While most strains of E. coli are harmless, certain pathogenic strains, such as E. coli O157:H7, can cause foodborne illness when ingested through contaminated food or water. Fecal contamination of food or water sources can introduce these harmful strains, leading to outbreaks of foodborne illnesses.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"e. coli\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"E. coli is a type of bacteria that naturally resides in the intestines of humans and animals. While most strains of E. coli are harmless, certain pathogenic strains, such as E. coli O157:H7, can cause foodborne illness when ingested through contaminated food or water. Fecal contamination of food or water sources can introduce these harmful strains, leading to outbreaks of foodborne illnesses.\n\n• Campylobacter jejuni: A bacterium commonly associated with foodborne illness from consumption of contaminated poultry, unpasteurized milk, and contaminated water.\n• Bacillus cereus: A bacterium that can cause food poisoning through the production of toxins in improperly stored or cooked foods, particularly rice and other starchy foods.\n• Trichinella spiralis: A parasitic worm that causes trichinellosis (trichinosis) when raw or undercooked meat containing encysted larvae is consumed.","whyWrongChoices":"Alternative options: campylobacter jejuni, bacillus cereus, trichinella spiralis"}'::jsonb),
('mc:a bacterium commonly associated with foodborne illness from consumption of contaminated poultry, unpasteurized milk and contaminated water.:::campylobacter jejuni', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a bacterium commonly associated with foodborne illness from consumption of contaminated poultry, unpasteurized milk and contaminated water.', 'campylobacter jejuni', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• E. coli: A bacteria that naturally resides in the intestines of humans and animals. While most strains of E. coli are harmless, certain pathogenic strains, such as E. coli O157:H7, can cause foodborne illness when ingested through contaminated food or water. Fecal contamination of food or water sources can introduce these harmful strains, leading to outbreaks of foodborne illnesses.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"campylobacter jejuni\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• E. coli: A bacteria that naturally resides in the intestines of humans and animals. While most strains of E. coli are harmless, certain pathogenic strains, such as E. coli O157:H7, can cause foodborne illness when ingested through contaminated food or water. Fecal contamination of food or water sources can introduce these harmful strains, leading to outbreaks of foodborne illnesses.\n• Bacillus cereus: A bacterium that can cause food poisoning through the production of toxins in improperly stored or cooked foods, particularly rice and other starchy foods.\n• Trichinella spiralis: A parasitic worm that causes trichinellosis (trichinosis) when raw or undercooked meat containing encysted larvae is consumed.","whyWrongChoices":"Alternative options: e. coli, bacillus cereus, trichinella spiralis"}'::jsonb),
('mc:type of organization applicable to a growing organization, with diversified responsibilities, in need of coordinators and specialists to assist.:::line and staff type', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'type of organization applicable to a growing organization, with diversified responsibilities, in need of coordinators and specialists to assist.', 'line and staff type', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Line and staff type of organization combines elements of both line and staff functions. In addition to the direct line of authority (line functions), it includes specialized support and advisory roles (staff functions) such as specialists, coordinators, and support staff to assist the line managers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"line and staff type\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Line and staff type of organization combines elements of both line and staff functions. In addition to the direct line of authority (line functions), it includes specialized support and advisory roles (staff functions) such as specialists, coordinators, and support staff to assist the line managers.\n\n• Line type: In a line organization, authority flows in a direct line from top to bottom, with each employee reporting to one supervisor. It is suitable for small organizations with simple structures and clear chains of command.\n• Functional type: This refers to organizations where employees are grouped by their specialty areas or functions (e.g., marketing, finance, operations). It is common in larger organizations where efficiency and specialization are key.\n• Line and functional type: This is not a standard organizational type. It may refer to a hybrid structure that combines line functions with functional departments.","whyWrongChoices":"Alternative options: line type, functional type, line and functional type"}'::jsonb),
