INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:pasteurization is applied in processing foods that are generally::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pasteurization is applied in processing foods that are generally:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pasteurization is a process of heat treatment that aims to reduce the microbial load in food products without significantly affecting their taste or nutritional value. It is commonly used for acidic foods such as fruit juices, dairy products (like milk and yogurt), and certain sauces. The heat treatment destroys harmful bacteria and extends the shelf life of the product, making it safer for consumption.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"acidic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pasteurization is a process of heat treatment that aims to reduce the microbial load in food products without significantly affecting their taste or nutritional value. It is commonly used for acidic foods such as fruit juices, dairy products (like milk and yogurt), and certain sauces. The heat treatment destroys harmful bacteria and extends the shelf life of the product, making it safer for consumption.","whyWrongChoices":"Alternative options: salty, basic, spicy"}'::jsonb),
('mc:in curing, the desirable pink color is due to:::nitrosomyoglobin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in curing, the desirable pink color is due to', 'nitrosomyoglobin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nitrosomyoglobin is formed when myoglobin (a protein in meat) reacts with nitric oxide (NO) during curing or processing. It is responsible for the stable pink color in cured meats like ham or bacon.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nitrosomyoglobin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nitrosomyoglobin is formed when myoglobin (a protein in meat) reacts with nitric oxide (NO) during curing or processing. It is responsible for the stable pink color in cured meats like ham or bacon.\n\n• Hemoglobin: A protein in red blood cells that carries oxygen, but it is not directly responsible for the pink color in cured meat.\n• Oxymyoglobin: A pigment in meat that gives it a bright red color when freshly cut and exposed to oxygen.\n• Metmyoglobin: A brown pigment that forms when oxymyoglobin loses its oxygen molecule, causing meat to appear brown rather than pink.","whyWrongChoices":"Alternative options: hemoglobin, oxymyoglobin, metmyoglobin"}'::jsonb),
('mc:in curing, the desirable pink color is due to:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in curing, the desirable pink color is due to', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nitrosomyoglobin is formed when myoglobin (a protein in meat) reacts with nitric oxide (NO) during curing or processing. It is responsible for the stable pink color in cured meats like ham or bacon.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"nitrosomyoglobin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nitrosomyoglobin is formed when myoglobin (a protein in meat) reacts with nitric oxide (NO) during curing or processing. It is responsible for the stable pink color in cured meats like ham or bacon.\n\n• Hemoglobin: A protein in red blood cells that carries oxygen, but it is not directly responsible for the pink color in cured meat.\n• Oxymyoglobin: A pigment in meat that gives it a bright red color when freshly cut and exposed to oxygen.\n• Metmyoglobin: A brown pigment that forms when oxymyoglobin loses its oxygen molecule, causing meat to appear brown rather than pink.","whyWrongChoices":"Alternative options: hemoglobin, oxymyoglobin, metmyoglobin"}'::jsonb),
('mc:the increase in loaf volume during baking is called::::oven spring', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the increase in loaf volume during baking is called:', 'oven spring', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The increase in loaf volume during baking is called oven spring. This phenomenon occurs when the dough rapidly expands in the oven due to the heat, which causes the gases trapped in the dough to expand and the yeast to produce more gas before it is killed by the heat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oven spring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The increase in loaf volume during baking is called oven spring. This phenomenon occurs when the dough rapidly expands in the oven due to the heat, which causes the gases trapped in the dough to expand and the yeast to produce more gas before it is killed by the heat.\n\n• Bloat refers to excessive expansion of dough due to over-fermentation\n• Loaf blow-up occurs when the dough rises too quickly, often leading to an uneven texture \n• Proofing is the controlled process of allowing dough to rise before baking to develop flavor and texture","whyWrongChoices":"Alternative options: bloat, loaf blow-up, proofing"}'::jsonb),
('mc:the increase in loaf volume during baking is called::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the increase in loaf volume during baking is called:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The increase in loaf volume during baking is called oven spring. This phenomenon occurs when the dough rapidly expands in the oven due to the heat, which causes the gases trapped in the dough to expand and the yeast to produce more gas before it is killed by the heat.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"oven spring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The increase in loaf volume during baking is called oven spring. This phenomenon occurs when the dough rapidly expands in the oven due to the heat, which causes the gases trapped in the dough to expand and the yeast to produce more gas before it is killed by the heat.\n\n• Bloat refers to excessive expansion of dough due to over-fermentation\n• Loaf blow-up occurs when the dough rises too quickly, often leading to an uneven texture \n• Proofing is the controlled process of allowing dough to rise before baking to develop flavor and texture","whyWrongChoices":"Alternative options: bloat, loaf blow-up, proofing"}'::jsonb),
('mc:salad dressing made of mayonnaise, chopped capers, and gherkins::::tartar', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'salad dressing made of mayonnaise, chopped capers, and gherkins:', 'tartar', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tartar is a sauce traditionally made with mayonnaise or aioli, chopped pickles (gherkins or capers), and sometimes additional herbs or spices.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"tartar\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tartar is a sauce traditionally made with mayonnaise or aioli, chopped pickles (gherkins or capers), and sometimes additional herbs or spices.\n\n• Ranch: A creamy dressing typically made with buttermilk or sour cream, mayonnaise, and various herbs and spices.\n• Thousand Island: A dressing that typically includes mayonnaise, ketchup or tomato paste, and sweet pickle relish, among other ingredients.\n• Aioli: A Mediterranean sauce made with garlic, olive oil, and often egg yolks, similar to mayonnaise but with a garlic flavor.","whyWrongChoices":"Alternative options: ranch, thousand island, aioli"}'::jsonb),
('mc:salad dressing made of mayonnaise, chopped capers, and gherkins::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'salad dressing made of mayonnaise, chopped capers, and gherkins:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tartar is a sauce traditionally made with mayonnaise or aioli, chopped pickles (gherkins or capers), and sometimes additional herbs or spices.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"tartar\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tartar is a sauce traditionally made with mayonnaise or aioli, chopped pickles (gherkins or capers), and sometimes additional herbs or spices.\n\n• Ranch: A creamy dressing typically made with buttermilk or sour cream, mayonnaise, and various herbs and spices.\n• Thousand Island: A dressing that typically includes mayonnaise, ketchup or tomato paste, and sweet pickle relish, among other ingredients.\n• Aioli: A Mediterranean sauce made with garlic, olive oil, and often egg yolks, similar to mayonnaise but with a garlic flavor.","whyWrongChoices":"Alternative options: ranch, thousand island, aioli"}'::jsonb),
('mc:egg noodles made from flour, duck eggs, salt, and soda:::pancit canton', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'egg noodles made from flour, duck eggs, salt, and soda', 'pancit canton', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pancit canton is a type of egg noodle commonly used in Filipino cuisine. It is characterized by its yellow color due to the addition of duck eggs and its slightly chewy texture. The ingredients listed (flour, duck eggs, salt, and soda) are consistent with those used in making pancit canton.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pancit canton\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pancit canton is a type of egg noodle commonly used in Filipino cuisine. It is characterized by its yellow color due to the addition of duck eggs and its slightly chewy texture. The ingredients listed (flour, duck eggs, salt, and soda) are consistent with those used in making pancit canton.\n\n• Sotanghon noodles, also known as cellophane or glass noodles, are made from mung bean starch. They are transparent when cooked and are not made from flour, duck eggs, salt, or soda.\n• Miswa noodles are thin, salted wheat noodles often used in soups.\n• Instant noodles are pre-cooked, While they can be made from wheat flour, they do not typically include duck eggs and soda in their preparation.","whyWrongChoices":"Alternative options: sotanghon, miswa, instant noodles"}'::jsonb),
('mc:egg noodles made from flour, duck eggs, salt, and soda:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'egg noodles made from flour, duck eggs, salt, and soda', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pancit canton is a type of egg noodle commonly used in Filipino cuisine. It is characterized by its yellow color due to the addition of duck eggs and its slightly chewy texture. The ingredients listed (flour, duck eggs, salt, and soda) are consistent with those used in making pancit canton.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pancit canton\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pancit canton is a type of egg noodle commonly used in Filipino cuisine. It is characterized by its yellow color due to the addition of duck eggs and its slightly chewy texture. The ingredients listed (flour, duck eggs, salt, and soda) are consistent with those used in making pancit canton.\n\n• Sotanghon noodles, also known as cellophane or glass noodles, are made from mung bean starch. They are transparent when cooked and are not made from flour, duck eggs, salt, or soda.\n• Miswa noodles are thin, salted wheat noodles often used in soups.\n• Instant noodles are pre-cooked, While they can be made from wheat flour, they do not typically include duck eggs and soda in their preparation.","whyWrongChoices":"Alternative options: sotanghon, miswa, instant noodles"}'::jsonb),
('mc:the father of canning is::::nicholas appert', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the father of canning is:', 'Nicholas Appert', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nicholas Appert, a French chef and confectioner, is credited with developing the method of preserving food by sealing it in sterilized containers. His work in the late 18th and early 19th centuries led to the discovery that food could be preserved by heat treatment to kill bacteria and other microorganisms, thereby preventing spoilage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nicholas Appert\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nicholas Appert, a French chef and confectioner, is credited with developing the method of preserving food by sealing it in sterilized containers. His work in the late 18th and early 19th centuries led to the discovery that food could be preserved by heat treatment to kill bacteria and other microorganisms, thereby preventing spoilage.\n\n• Louis Appert, often confused with Nicholas Appert, was actually his son who helped to commercialize and refine his father’s methods.\n• Louis Pasteur, on the other hand, made significant contributions to microbiology and food preservation techniques, particularly pasteurization, which involves heating liquids to kill pathogens and extend shelf life. However, he is not directly associated with canning.","whyWrongChoices":"Alternative options: Louis Appert, Louis Pasteur, Nicholas Pasteur"}'::jsonb),
('mc:the father of canning is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the father of canning is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nicholas Appert, a French chef and confectioner, is credited with developing the method of preserving food by sealing it in sterilized containers. His work in the late 18th and early 19th centuries led to the discovery that food could be preserved by heat treatment to kill bacteria and other microorganisms, thereby preventing spoilage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nicholas Appert\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nicholas Appert, a French chef and confectioner, is credited with developing the method of preserving food by sealing it in sterilized containers. His work in the late 18th and early 19th centuries led to the discovery that food could be preserved by heat treatment to kill bacteria and other microorganisms, thereby preventing spoilage.\n\n• Louis Appert, often confused with Nicholas Appert, was actually his son who helped to commercialize and refine his father’s methods.\n• Louis Pasteur, on the other hand, made significant contributions to microbiology and food preservation techniques, particularly pasteurization, which involves heating liquids to kill pathogens and extend shelf life. However, he is not directly associated with canning.","whyWrongChoices":"Alternative options: Louis Appert, Louis Pasteur, Nicholas Pasteur"}'::jsonb),
('mc:a dark purple-colored rice used in puto bumbong::::pirurutong', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a dark purple-colored rice used in puto bumbong:', 'Pirurutong', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pirurutong rice is a type of glutinous rice that has a distinct purple hue due to its natural pigmentation. It is traditionally used in Filipino cuisine, particularly in dishes like Puto Bumbong, which is a type of steamed rice cake typically served during Christmas season in the Philippines. The purple color of Pirurutong adds a unique visual appeal and subtle flavor to the dish.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pirurutong\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pirurutong rice is a type of glutinous rice that has a distinct purple hue due to its natural pigmentation. It is traditionally used in Filipino cuisine, particularly in dishes like Puto Bumbong, which is a type of steamed rice cake typically served during Christmas season in the Philippines. The purple color of Pirurutong adds a unique visual appeal and subtle flavor to the dish.\n\n• Pinipig: Rice grains that are pounded flat and used in various Filipino desserts.\n• Wagwag: A term sometimes used for dried, pounded rice.\n• Gindara: A type of fish (sablefish or black cod), not rice.","whyWrongChoices":"Alternative options: Pinipig, Wagwag, Gindara"}'::jsonb),
('mc:dietary management for fatty liver::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary management for fatty liver:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Underweight patients with hepatic steatosis or steatohepatitis (such as alcoholic liver disease or advanced cirrhosis with severe muscle wasting) experience accelerated hepatic gluconeogenesis, glycogen depletion, and protein catabolism. A high-protein diet (1.2 to 1.5 g/kg/day) provides essential amino acids required for hepatic export protein synthesis (albumin, clotting factors), decreases skeletal muscle proteolysis, and prevents hepatic encephalopathy by maintaining visceral nitrogen balance. High kilocalories (35 to 40 kcal/kg/day) ensure positive energy balance, shifting metabolism away from endogenous fat mobilization and skeletal muscle breakdown while sparing dietary protein for tissue synthesis rather than oxidation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High protein, high kcal for underweight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Underweight patients with hepatic steatosis or steatohepatitis (such as alcoholic liver disease or advanced cirrhosis with severe muscle wasting) experience accelerated hepatic gluconeogenesis, glycogen depletion, and protein catabolism. A high-protein diet (1.2 to 1.5 g/kg/day) provides essential amino acids required for hepatic export protein synthesis (albumin, clotting factors), decreases skeletal muscle proteolysis, and prevents hepatic encephalopathy by maintaining visceral nitrogen balance. High kilocalories (35 to 40 kcal/kg/day) ensure positive energy balance, shifting metabolism away from endogenous fat mobilization and skeletal muscle breakdown while sparing dietary protein for tissue synthesis rather than oxidation.","whyWrongChoices":"Alternative options: Low protein, low kcal for obese, High carbohydrates, IVF"}'::jsonb),
('mc:a dark purple-colored rice used in puto bumbong::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a dark purple-colored rice used in puto bumbong:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pirurutong rice is a type of glutinous rice that has a distinct purple hue due to its natural pigmentation. It is traditionally used in Filipino cuisine, particularly in dishes like Puto Bumbong, which is a type of steamed rice cake typically served during Christmas season in the Philippines. The purple color of Pirurutong adds a unique visual appeal and subtle flavor to the dish.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pirurutong\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pirurutong rice is a type of glutinous rice that has a distinct purple hue due to its natural pigmentation. It is traditionally used in Filipino cuisine, particularly in dishes like Puto Bumbong, which is a type of steamed rice cake typically served during Christmas season in the Philippines. The purple color of Pirurutong adds a unique visual appeal and subtle flavor to the dish.\n\n• Pinipig: Rice grains that are pounded flat and used in various Filipino desserts.\n• Wagwag: A term sometimes used for dried, pounded rice.\n• Gindara: A type of fish (sablefish or black cod), not rice.","whyWrongChoices":"Alternative options: Pinipig, Wagwag, Gindara"}'::jsonb),
('mc:strong flavoured vegetables like cabbage and radish should be cooked in an uncovered cooking vessel to:::allow volatilization of sulfur compounds', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'strong flavoured vegetables like cabbage and radish should be cooked in an uncovered cooking vessel to', 'allow volatilization of sulfur compounds', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cabbage and radish contain sulfur compounds that can impart a strong odor when cooked. Cooking these vegetables uncovered allows the sulfur compounds to volatilize and escape into the air, reducing their strong odor and improving the overall flavor of the dish.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"allow volatilization of sulfur compounds\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cabbage and radish contain sulfur compounds that can impart a strong odor when cooked. Cooking these vegetables uncovered allows the sulfur compounds to volatilize and escape into the air, reducing their strong odor and improving the overall flavor of the dish.","whyWrongChoices":"Alternative options: retain best flavor, attain best texture, conserve nutrients"}'::jsonb),
('mc:strong flavoured vegetables like cabbage and radish should be cooked in an uncovered cooking vessel to:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'strong flavoured vegetables like cabbage and radish should be cooked in an uncovered cooking vessel to', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Cabbage and radish contain sulfur compounds that can impart a strong odor when cooked. Cooking these vegetables uncovered allows the sulfur compounds to volatilize and escape into the air, reducing their strong odor and improving the overall flavor of the dish.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"allow volatilization of sulfur compounds\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Cabbage and radish contain sulfur compounds that can impart a strong odor when cooked. Cooking these vegetables uncovered allows the sulfur compounds to volatilize and escape into the air, reducing their strong odor and improving the overall flavor of the dish.","whyWrongChoices":"Alternative options: retain best flavor, attain best texture, conserve nutrients"}'::jsonb),
('mc:sentence a. hydrogenation prevents oxidative rancidity. sentence b. oxidative rancidity is more prone in oils with high saturated fatty acids:::sentence a is correct.', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. hydrogenation prevents oxidative rancidity. sentence b. oxidative rancidity is more prone in oils with high saturated fatty acids', 'Sentence A is correct.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hydrogenation can help in reducing oxidative rancidity by converting unsaturated fats, which are more prone to oxidation, into more stable saturated fats. This makes the statement correct to an extent since hydrogenated fats are less likely to undergo oxidative rancidity compared to their unsaturated counterparts.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence A is correct.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hydrogenation can help in reducing oxidative rancidity by converting unsaturated fats, which are more prone to oxidation, into more stable saturated fats. This makes the statement correct to an extent since hydrogenated fats are less likely to undergo oxidative rancidity compared to their unsaturated counterparts.\n\nThis statement is incorrect because oxidative rancidity primarily affects oils high in unsaturated fatty acids, not saturated fatty acids. Saturated fats are more stable and less likely to oxidize.","whyWrongChoices":"Alternative options: Sentence B is correct., Both sentences are correct., Both sentences are incorrect."}'::jsonb),
('mc:sentence a. hydrogenation prevents oxidative rancidity. sentence b. oxidative rancidity is more prone in oils with high saturated fatty acids:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. hydrogenation prevents oxidative rancidity. sentence b. oxidative rancidity is more prone in oils with high saturated fatty acids', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hydrogenation can help in reducing oxidative rancidity by converting unsaturated fats, which are more prone to oxidation, into more stable saturated fats. This makes the statement correct to an extent since hydrogenated fats are less likely to undergo oxidative rancidity compared to their unsaturated counterparts.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence A is correct.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hydrogenation can help in reducing oxidative rancidity by converting unsaturated fats, which are more prone to oxidation, into more stable saturated fats. This makes the statement correct to an extent since hydrogenated fats are less likely to undergo oxidative rancidity compared to their unsaturated counterparts.\n\nThis statement is incorrect because oxidative rancidity primarily affects oils high in unsaturated fatty acids, not saturated fatty acids. Saturated fats are more stable and less likely to oxidize.","whyWrongChoices":"Alternative options: Sentence B is correct., Both sentences are correct., Both sentences are incorrect."}'::jsonb),
('mc:genus with species capable of oxidizing ethanol to acetic acid:::acetobacter', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'genus with species capable of oxidizing ethanol to acetic acid', 'Acetobacter', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Acetobacter is a genus of acetic acid bacteria known for its ability to convert ethanol into acetic acid through the process of oxidation. This characteristic is utilized in the production of vinegar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Acetobacter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Acetobacter is a genus of acetic acid bacteria known for its ability to convert ethanol into acetic acid through the process of oxidation. This characteristic is utilized in the production of vinegar.\n\n• Lactococcus is a genus of bacteria that plays a crucial role in dairy fermentation processes. These bacteria are lactic acid bacteria, meaning they convert lactose (milk sugar) into lactic acid. This acidification process is essential in the production of various dairy products, such as cheese, buttermilk, and sour cream, as it helps to develop the flavor, texture, and preservation of these foods.\n\n• Escherichia is a genus of bacteria that includes several species, with Escherichia coli (commonly known as E. coli) being the most well-known. E. coli is a diverse group of bacteria found in the intestines of humans and animals. While many strains of E. coli are harmless and play a role in maintaining gut health, some strains can cause foodborne illnesses, leading to symptoms like diarrhea, abdominal pain, and, in severe cases, kidney failure.\n\n• Saccharomyces is a genus of yeast that is widely used in baking, brewing, and fermentation processes. The most well-known species is Saccharomyces cerevisiae, commonly referred to as baker’s yeast or brewer’s yeast.","whyWrongChoices":"Alternative options: Escherichia, Lactococcus, Saccharomyces"}'::jsonb),
('mc:genus with species capable of oxidizing ethanol to acetic acid:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'genus with species capable of oxidizing ethanol to acetic acid', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Acetobacter is a genus of acetic acid bacteria known for its ability to convert ethanol into acetic acid through the process of oxidation. This characteristic is utilized in the production of vinegar.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Acetobacter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Acetobacter is a genus of acetic acid bacteria known for its ability to convert ethanol into acetic acid through the process of oxidation. This characteristic is utilized in the production of vinegar.\n\n• Lactococcus is a genus of bacteria that plays a crucial role in dairy fermentation processes. These bacteria are lactic acid bacteria, meaning they convert lactose (milk sugar) into lactic acid. This acidification process is essential in the production of various dairy products, such as cheese, buttermilk, and sour cream, as it helps to develop the flavor, texture, and preservation of these foods.\n\n• Escherichia is a genus of bacteria that includes several species, with Escherichia coli (commonly known as E. coli) being the most well-known. E. coli is a diverse group of bacteria found in the intestines of humans and animals. While many strains of E. coli are harmless and play a role in maintaining gut health, some strains can cause foodborne illnesses, leading to symptoms like diarrhea, abdominal pain, and, in severe cases, kidney failure.\n\n• Saccharomyces is a genus of yeast that is widely used in baking, brewing, and fermentation processes. The most well-known species is Saccharomyces cerevisiae, commonly referred to as baker’s yeast or brewer’s yeast.","whyWrongChoices":"Alternative options: Escherichia, Lactococcus, Saccharomyces"}'::jsonb),
('mc:if the current yield of a recipe is 8 servings and the desired yield is 20 servings, what is the recipe conversion factor?:::2.5', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'if the current yield of a recipe is 8 servings and the desired yield is 20 servings, what is the recipe conversion factor?', '2.5', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Conversion factor = Desired yield/Current","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2.5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Conversion factor = Desired yield/Current\n= 20 servings / 8 servings\n= 2.5","whyWrongChoices":"Alternative options: 2, 3, 4"}'::jsonb),
('mc:if the current yield of a recipe is 8 servings and the desired yield is 20 servings, what is the recipe conversion factor?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'if the current yield of a recipe is 8 servings and the desired yield is 20 servings, what is the recipe conversion factor?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Conversion factor = Desired yield/Current","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2.5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Conversion factor = Desired yield/Current\n= 20 servings / 8 servings\n= 2.5","whyWrongChoices":"Alternative options: 2, 3, 4"}'::jsonb),
('mc:a process of checking the interior quality of eggs:::candling', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a process of checking the interior quality of eggs', 'candling', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Candling involves passing an egg over a bright light source to examine its interior. This process helps to assess the quality of the egg, including the size of the air cell, the condition of the yolk, and the presence of any defects or abnormalities inside the shell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"candling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Candling involves passing an egg over a bright light source to examine its interior. This process helps to assess the quality of the egg, including the size of the air cell, the condition of the yolk, and the presence of any defects or abnormalities inside the shell.\n\n• Grading is the process of evaluating eggs based on their quality, size, and appearance. This includes factors like the freshness, cleanliness, and strength of the eggshell, but it does not specifically focus on checking the interior quality.\n• Sorting refers to the process of organizing eggs by size or grade, but it does not specifically assess the interior quality of the eggs.","whyWrongChoices":"Alternative options: grading, sorting, none of the above"}'::jsonb),
('mc:a process of checking the interior quality of eggs:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a process of checking the interior quality of eggs', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Candling involves passing an egg over a bright light source to examine its interior. This process helps to assess the quality of the egg, including the size of the air cell, the condition of the yolk, and the presence of any defects or abnormalities inside the shell.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"candling\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Candling involves passing an egg over a bright light source to examine its interior. This process helps to assess the quality of the egg, including the size of the air cell, the condition of the yolk, and the presence of any defects or abnormalities inside the shell.\n\n• Grading is the process of evaluating eggs based on their quality, size, and appearance. This includes factors like the freshness, cleanliness, and strength of the eggshell, but it does not specifically focus on checking the interior quality.\n• Sorting refers to the process of organizing eggs by size or grade, but it does not specifically assess the interior quality of the eggs.","whyWrongChoices":"Alternative options: grading, sorting, none of the above"}'::jsonb),
('mc:sentence a. crustacean releases the pigment astaxanthin which gives its orange color when cooked. sentence b. this is due to the breakdown of the ovoverdine-asthaxanthin complex during cooking.:::both sentences are correct.', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. crustacean releases the pigment astaxanthin which gives its orange color when cooked. sentence b. this is due to the breakdown of the ovoverdine-asthaxanthin complex during cooking.', 'Both sentences are correct.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Color change in crustaceans from natural dark blue green color to an attractive orange color is due to the release of an orange pigment astaxanthin from ovoverdine, a protein, when heated.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Color change in crustaceans from natural dark blue green color to an attractive orange color is due to the release of an orange pigment astaxanthin from ovoverdine, a protein, when heated.","whyWrongChoices":"Alternative options: Sentence A is correct., Sentence B is correct., Both sentences are incorrect."}'::jsonb),
('mc:sentence a. crustacean releases the pigment astaxanthin which gives its orange color when cooked. sentence b. this is due to the breakdown of the ovoverdine-asthaxanthin complex during cooking.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. crustacean releases the pigment astaxanthin which gives its orange color when cooked. sentence b. this is due to the breakdown of the ovoverdine-asthaxanthin complex during cooking.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Color change in crustaceans from natural dark blue green color to an attractive orange color is due to the release of an orange pigment astaxanthin from ovoverdine, a protein, when heated.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are correct.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Color change in crustaceans from natural dark blue green color to an attractive orange color is due to the release of an orange pigment astaxanthin from ovoverdine, a protein, when heated.","whyWrongChoices":"Alternative options: Sentence A is correct., Sentence B is correct., Both sentences are incorrect."}'::jsonb),
('mc:sentence a. shortening impedes gluten development by hydrolysis. sentence b. impeding gluten development would result in flaky products.:::sentence b is correct.', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. shortening impedes gluten development by hydrolysis. sentence b. impeding gluten development would result in flaky products.', 'Sentence B is correct.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hydrolysis is a chemical process in which a compound is broken down by reacting with water.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence B is correct.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hydrolysis is a chemical process in which a compound is broken down by reacting with water.\n\nSentence A is incorrect. Shortening (typically fats like butter or vegetable shortening) does not impede gluten development by hydrolysis. Instead, fats in dough or batter interfere with gluten formation by coating the gluten proteins and preventing them from forming strong bonds. This interference is not due to hydrolysis but rather to physical interactions.\n\nSentence B is correct. When gluten development is limited, the resulting dough has less elasticity and structure, producing a tender, flaky texture. This is particularly desirable in products such as pie crust, pastry crust, biscuits\n\nFlakiness in baked goods like pastries is typically achieved by creating layers of fat and dough, such as in laminated doughs or pie crusts, not by impeding gluten development.","whyWrongChoices":"Alternative options: Sentence A is correct., Both sentences are correct., Both sentences are incorrect."}'::jsonb),
('mc:sentence a. shortening impedes gluten development by hydrolysis. sentence b. impeding gluten development would result in flaky products.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. shortening impedes gluten development by hydrolysis. sentence b. impeding gluten development would result in flaky products.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hydrolysis is a chemical process in which a compound is broken down by reacting with water.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence B is correct.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hydrolysis is a chemical process in which a compound is broken down by reacting with water.\n\nSentence A is incorrect. Shortening (typically fats like butter or vegetable shortening) does not impede gluten development by hydrolysis. Instead, fats in dough or batter interfere with gluten formation by coating the gluten proteins and preventing them from forming strong bonds. This interference is not due to hydrolysis but rather to physical interactions.\n\nSentence B is correct. When gluten development is limited, the resulting dough has less elasticity and structure, producing a tender, flaky texture. This is particularly desirable in products such as pie crust, pastry crust, biscuits\n\nFlakiness in baked goods like pastries is typically achieved by creating layers of fat and dough, such as in laminated doughs or pie crusts, not by impeding gluten development.","whyWrongChoices":"Alternative options: Sentence A is correct., Both sentences are correct., Both sentences are incorrect."}'::jsonb),
('mc:dietary management for fatty liver::::high protein, high kcal for underweight', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary management for fatty liver:', 'High protein, high kcal for underweight', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Underweight patients with hepatic steatosis or steatohepatitis (such as alcoholic liver disease or advanced cirrhosis with severe muscle wasting) experience accelerated hepatic gluconeogenesis, glycogen depletion, and protein catabolism. A high-protein diet (1.2 to 1.5 g/kg/day) provides essential amino acids required for hepatic export protein synthesis (albumin, clotting factors), decreases skeletal muscle proteolysis, and prevents hepatic encephalopathy by maintaining visceral nitrogen balance. High kilocalories (35 to 40 kcal/kg/day) ensure positive energy balance, shifting metabolism away from endogenous fat mobilization and skeletal muscle breakdown while sparing dietary protein for tissue synthesis rather than oxidation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High protein, high kcal for underweight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Underweight patients with hepatic steatosis or steatohepatitis (such as alcoholic liver disease or advanced cirrhosis with severe muscle wasting) experience accelerated hepatic gluconeogenesis, glycogen depletion, and protein catabolism. A high-protein diet (1.2 to 1.5 g/kg/day) provides essential amino acids required for hepatic export protein synthesis (albumin, clotting factors), decreases skeletal muscle proteolysis, and prevents hepatic encephalopathy by maintaining visceral nitrogen balance. High kilocalories (35 to 40 kcal/kg/day) ensure positive energy balance, shifting metabolism away from endogenous fat mobilization and skeletal muscle breakdown while sparing dietary protein for tissue synthesis rather than oxidation.","whyWrongChoices":"Alternative options: Low protein, low kcal for obese, High carbohydrates, IVF"}'::jsonb),
('mc:also called portal systematic encephalopathy::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'also called portal systematic encephalopathy:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Portal-systemic encephalopathy (PSE) and hepatic encephalopathy are a spectrum of central nervous system dysfunctions caused by liver failure or shunting. Historically and in clinical question banks, hepatic coma (or coma hepaticum) is used interchangeably to describe its severe, final stage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hepatic coma\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Portal-systemic encephalopathy (PSE) and hepatic encephalopathy are a spectrum of central nervous system dysfunctions caused by liver failure or shunting. Historically and in clinical question banks, hepatic coma (or coma hepaticum) is used interchangeably to describe its severe, final stage.","whyWrongChoices":"Alternative options: Obstructive cirrhosis, Portal hypertension, Pancreatitis"}'::jsonb),
('mc:nutrition management for burns: i. high calorie ii. high protein iii. sodium controlled iv. fluid controlled:::all of the above', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'nutrition management for burns: i. high calorie ii. high protein iii. sodium controlled iv. fluid controlled', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• I. High Calorie: Burn injuries trigger a massive hypermetabolic and catabolic state. Energy expenditure can double depending on the severity, requiring a high-calorie intake (predominantly from carbohydrates) to prevent significant weight and muscle tissue loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• I. High Calorie: Burn injuries trigger a massive hypermetabolic and catabolic state. Energy expenditure can double depending on the severity, requiring a high-calorie intake (predominantly from carbohydrates) to prevent significant weight and muscle tissue loss.\n• II. High Protein: Large amounts of nitrogen and protein are lost through burn wounds. Aggressive high-protein delivery (often 1.5–2.0 g/kg/day or more) is essential to promote tissue repair, wound healing, and maintain lean mass.\n• III. Sodium Controlled & IV. Fluid Controlled: While early-stage burn shock resuscitation demands large amounts of fluids and sodium, the downstream nutritional management phase shifts toward precision. In this phase, fluids and sodium are meticulously monitored, calculated, and controlled to prevent fluid overload, pulmonary edema, and severe electrolyte imbalances (like hypernatremia) while maintaining hemodynamic stability.","whyWrongChoices":"Alternative options: I and II only, I, II, III only, I, II, IV only"}'::jsonb),
('mc:nutrition management for burns: i. high calorie ii. high protein iii. sodium controlled iv. fluid controlled:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'nutrition management for burns: i. high calorie ii. high protein iii. sodium controlled iv. fluid controlled', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• I. High Calorie: Burn injuries trigger a massive hypermetabolic and catabolic state. Energy expenditure can double depending on the severity, requiring a high-calorie intake (predominantly from carbohydrates) to prevent significant weight and muscle tissue loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• I. High Calorie: Burn injuries trigger a massive hypermetabolic and catabolic state. Energy expenditure can double depending on the severity, requiring a high-calorie intake (predominantly from carbohydrates) to prevent significant weight and muscle tissue loss.\n• II. High Protein: Large amounts of nitrogen and protein are lost through burn wounds. Aggressive high-protein delivery (often 1.5–2.0 g/kg/day or more) is essential to promote tissue repair, wound healing, and maintain lean mass.\n• III. Sodium Controlled & IV. Fluid Controlled: While early-stage burn shock resuscitation demands large amounts of fluids and sodium, the downstream nutritional management phase shifts toward precision. In this phase, fluids and sodium are meticulously monitored, calculated, and controlled to prevent fluid overload, pulmonary edema, and severe electrolyte imbalances (like hypernatremia) while maintaining hemodynamic stability.","whyWrongChoices":"Alternative options: I and II only, I, II, III only, I, II, IV only"}'::jsonb),
('mc:an anemia pertaining to anemia induced by easy damage of the rbcs?:::hemolytic anemia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an anemia pertaining to anemia induced by easy damage of the rbcs?', 'Hemolytic anemia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemolytic anemia occurs when red blood cells (RBCs) are destroyed or broken down faster than the bone marrow can produce new ones. This premature destruction (hemolysis) can be caused by intrinsic defects inside the RBCs that make them weak, or external factors like autoimmune attacks, toxins, and infections that damage the cell membrane.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemolytic anemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemolytic anemia occurs when red blood cells (RBCs) are destroyed or broken down faster than the bone marrow can produce new ones. This premature destruction (hemolysis) can be caused by intrinsic defects inside the RBCs that make them weak, or external factors like autoimmune attacks, toxins, and infections that damage the cell membrane.\n\n\t• Microcytic anemia describes RBCs that are abnormally small in size, most commonly due to iron deficiency.\n\t• Hemorrhagic anemia is caused by excessive external or internal blood loss (bleeding), not cellular damage.\n\t• Pernicious anemia is a specific type of vitamin B12 deficiency anemia caused by a lack of intrinsic factor needed for absorption.","whyWrongChoices":"Alternative options: Microcytic anemia, Pernicious anemia, Hemorrhagic anemia"}'::jsonb),
('mc:an anemia pertaining to anemia induced by easy damage of the rbcs?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an anemia pertaining to anemia induced by easy damage of the rbcs?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemolytic anemia occurs when red blood cells (RBCs) are destroyed or broken down faster than the bone marrow can produce new ones. This premature destruction (hemolysis) can be caused by intrinsic defects inside the RBCs that make them weak, or external factors like autoimmune attacks, toxins, and infections that damage the cell membrane.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemolytic anemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemolytic anemia occurs when red blood cells (RBCs) are destroyed or broken down faster than the bone marrow can produce new ones. This premature destruction (hemolysis) can be caused by intrinsic defects inside the RBCs that make them weak, or external factors like autoimmune attacks, toxins, and infections that damage the cell membrane.\n\n\t• Microcytic anemia describes RBCs that are abnormally small in size, most commonly due to iron deficiency.\n\t• Hemorrhagic anemia is caused by excessive external or internal blood loss (bleeding), not cellular damage.\n\t• Pernicious anemia is a specific type of vitamin B12 deficiency anemia caused by a lack of intrinsic factor needed for absorption.","whyWrongChoices":"Alternative options: Microcytic anemia, Pernicious anemia, Hemorrhagic anemia"}'::jsonb),
('mc:which of the following biochemical measures of nutritonal status is most likely associated with over nutrition?:::serum ldl', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following biochemical measures of nutritonal status is most likely associated with over nutrition?', 'Serum LDL', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Serum LDL (low-density lipoprotein or \"bad\" cholesterol) reflects fat and lipid metabolism. Elevated levels are commonly driven by a chronic overnutrition of saturated fats, trans fats, and excess calories, making it a key biochemical indicator for overnutrition and cardiovascular risk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Serum LDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Serum LDL (low-density lipoprotein or \"bad\" cholesterol) reflects fat and lipid metabolism. Elevated levels are commonly driven by a chronic overnutrition of saturated fats, trans fats, and excess calories, making it a key biochemical indicator for overnutrition and cardiovascular risk.\n\nThe Other Options (Malnutrition/Under-nutrition):\n\t• Nitrogen balance (B) measures protein intake versus excretion and is typically used to monitor protein catabolism or adequacy.\n\t• Hemoglobin and hematocrit (C) screen for anemias caused by dietary deficiencies (like iron, folate, or B12).\n\t• Serum albumin (D) is a standard marker used to evaluate protein-calorie malnutrition or visceral protein depletion.","whyWrongChoices":"Alternative options: Hemoglobin and hematocrit, Nitrogen balance, Serum albumin"}'::jsonb),
('mc:which of the following biochemical measures of nutritonal status is most likely associated with over nutrition?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following biochemical measures of nutritonal status is most likely associated with over nutrition?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Serum LDL (low-density lipoprotein or \"bad\" cholesterol) reflects fat and lipid metabolism. Elevated levels are commonly driven by a chronic overnutrition of saturated fats, trans fats, and excess calories, making it a key biochemical indicator for overnutrition and cardiovascular risk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Serum LDL\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Serum LDL (low-density lipoprotein or \"bad\" cholesterol) reflects fat and lipid metabolism. Elevated levels are commonly driven by a chronic overnutrition of saturated fats, trans fats, and excess calories, making it a key biochemical indicator for overnutrition and cardiovascular risk.\n\nThe Other Options (Malnutrition/Under-nutrition):\n\t• Nitrogen balance (B) measures protein intake versus excretion and is typically used to monitor protein catabolism or adequacy.\n\t• Hemoglobin and hematocrit (C) screen for anemias caused by dietary deficiencies (like iron, folate, or B12).\n\t• Serum albumin (D) is a standard marker used to evaluate protein-calorie malnutrition or visceral protein depletion.","whyWrongChoices":"Alternative options: Hemoglobin and hematocrit, Nitrogen balance, Serum albumin"}'::jsonb),
('mc:a term used to describe the surgical removal of the gallbladder, inflammation of the gallbladder.:::cholecystectomy, cholecystitis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a term used to describe the surgical removal of the gallbladder, inflammation of the gallbladder.', 'Cholecystectomy, Cholecystitis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• The Root: Cholecyst- refers to the gallbladder.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cholecystectomy, Cholecystitis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• The Root: Cholecyst- refers to the gallbladder.\n• Surgical Removal: The suffix -ectomy means surgical excision or removal. Therefore, cholecystectomy is the removal of the gallbladder.\n• Inflammation: The suffix -itis means inflammation. Therefore, cholecystitis is inflammation of the gallbladder.\n\nWhy the Other Options Do Not Fit\n• Hemorrhoidectomy is the removal of hemorrhoids; cholelithiasis is the presence of gallstones.\n• Jejunoileostomy is a surgical opening between the jejunum and ileum; cholecystolithiasis specifically means stones inside the gallbladder.\n• Colostomy is a surgical opening into the colon; choledocholithiasis means stones inside the common bile duct.","whyWrongChoices":"Alternative options: Colostomy, Choledocholithiasis, Jejunoileostomy, Cholecystolithiasis, Hermorrhoidectomy,Cholelithiasis"}'::jsonb),
('mc:a term used to describe the surgical removal of the gallbladder, inflammation of the gallbladder.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a term used to describe the surgical removal of the gallbladder, inflammation of the gallbladder.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• The Root: Cholecyst- refers to the gallbladder.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cholecystectomy, Cholecystitis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• The Root: Cholecyst- refers to the gallbladder.\n• Surgical Removal: The suffix -ectomy means surgical excision or removal. Therefore, cholecystectomy is the removal of the gallbladder.\n• Inflammation: The suffix -itis means inflammation. Therefore, cholecystitis is inflammation of the gallbladder.\n\nWhy the Other Options Do Not Fit\n• Hemorrhoidectomy is the removal of hemorrhoids; cholelithiasis is the presence of gallstones.\n• Jejunoileostomy is a surgical opening between the jejunum and ileum; cholecystolithiasis specifically means stones inside the gallbladder.\n• Colostomy is a surgical opening into the colon; choledocholithiasis means stones inside the common bile duct.","whyWrongChoices":"Alternative options: Colostomy, Choledocholithiasis, Jejunoileostomy, Cholecystolithiasis, Hermorrhoidectomy,Cholelithiasis"}'::jsonb),
('mc:an instrument used to measure skinfold thickness:::lange', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an instrument used to measure skinfold thickness', 'Lange', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Lange caliper is a specific instrument designed and validated for measuring skinfold thickness at standardized body sites to estimate subcutaneous body fat. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lange\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Lange caliper is a specific instrument designed and validated for measuring skinfold thickness at standardized body sites to estimate subcutaneous body fat. \n\nBiceps, subscapular, and midaxillary are names of specific skinfold measurement sites on the body.","whyWrongChoices":"Alternative options: Biceps, Subscapular, Midaxillary"}'::jsonb),
('mc:it refers to the provision of nutrients both orally and via tube directly into the git.:::enteral nutrition', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it refers to the provision of nutrients both orally and via tube directly into the git.', 'Enteral nutrition', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral nutrition is the broader term used when nutrients are delivered directly into the gastrointestinal tract (GIT). This includes both standard oral food intake (consuming regular foods or oral supplements) and tube feeding (delivering liquid formula via nasogastric, gastrostomy, or jejunostomy tubes).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Enteral nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral nutrition is the broader term used when nutrients are delivered directly into the gastrointestinal tract (GIT). This includes both standard oral food intake (consuming regular foods or oral supplements) and tube feeding (delivering liquid formula via nasogastric, gastrostomy, or jejunostomy tubes).\n\n\t• Parenteral nutrition bypasses the GI tract entirely, delivering nutrients directly into a central or peripheral vein.\n\t• Nutrition intervention is a broad step in the Nutrition Care Process that encompasses any planned action to resolve a nutrition-related problem (e.g., diet education, counseling, or supplement provision).\n\t• Refeeding syndrome is a dangerous metabolic complication that can occur when restarting nutrition in severely malnourished individuals.","whyWrongChoices":"Alternative options: Nutrition intervention, Parental nutrition, Refeeding syndrom"}'::jsonb),
('mc:it refers to the provision of nutrients both orally and via tube directly into the git.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it refers to the provision of nutrients both orally and via tube directly into the git.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Enteral nutrition is the broader term used when nutrients are delivered directly into the gastrointestinal tract (GIT). This includes both standard oral food intake (consuming regular foods or oral supplements) and tube feeding (delivering liquid formula via nasogastric, gastrostomy, or jejunostomy tubes).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Enteral nutrition\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Enteral nutrition is the broader term used when nutrients are delivered directly into the gastrointestinal tract (GIT). This includes both standard oral food intake (consuming regular foods or oral supplements) and tube feeding (delivering liquid formula via nasogastric, gastrostomy, or jejunostomy tubes).\n\n\t• Parenteral nutrition bypasses the GI tract entirely, delivering nutrients directly into a central or peripheral vein.\n\t• Nutrition intervention is a broad step in the Nutrition Care Process that encompasses any planned action to resolve a nutrition-related problem (e.g., diet education, counseling, or supplement provision).\n\t• Refeeding syndrome is a dangerous metabolic complication that can occur when restarting nutrition in severely malnourished individuals.","whyWrongChoices":"Alternative options: Nutrition intervention, Parental nutrition, Refeeding syndrom"}'::jsonb),
('mc:classification obesity characterized by increase in the number of fat cells::::hyperplastic', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'classification obesity characterized by increase in the number of fat cells:', 'Hyperplastic', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Hyperplastic Obesity: This is characterized by an increase in the total number of fat cells (adipocytes). It typically develops during childhood and adolescence when body growth occurs, making long-term weight management more challenging because the absolute number of cells does not decrease with weight loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperplastic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Hyperplastic Obesity: This is characterized by an increase in the total number of fat cells (adipocytes). It typically develops during childhood and adolescence when body growth occurs, making long-term weight management more challenging because the absolute number of cells does not decrease with weight loss.\n• Hypertrophic Obesity: This is characterized by an increase in the size of the existing fat cells. This pattern is more common in adult-onset obesity, where the cells expand to store excess lipids.\n• Android & Gynoid: These describe the anatomical distribution of fat rather than cellular characteristics. Android refers to \"apple-shaped\" abdominal fat distribution (common in males), while Gynoid refers to \"pear-shaped\" hip and thigh fat distribution (common in females).","whyWrongChoices":"Alternative options: Android, Hypertropic, Gynoid"}'::jsonb),
('mc:classification obesity characterized by increase in the number of fat cells::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'classification obesity characterized by increase in the number of fat cells:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Hyperplastic Obesity: This is characterized by an increase in the total number of fat cells (adipocytes). It typically develops during childhood and adolescence when body growth occurs, making long-term weight management more challenging because the absolute number of cells does not decrease with weight loss.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperplastic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Hyperplastic Obesity: This is characterized by an increase in the total number of fat cells (adipocytes). It typically develops during childhood and adolescence when body growth occurs, making long-term weight management more challenging because the absolute number of cells does not decrease with weight loss.\n• Hypertrophic Obesity: This is characterized by an increase in the size of the existing fat cells. This pattern is more common in adult-onset obesity, where the cells expand to store excess lipids.\n• Android & Gynoid: These describe the anatomical distribution of fat rather than cellular characteristics. Android refers to \"apple-shaped\" abdominal fat distribution (common in males), while Gynoid refers to \"pear-shaped\" hip and thigh fat distribution (common in females).","whyWrongChoices":"Alternative options: Android, Hypertropic, Gynoid"}'::jsonb),
('mc:dietary management for hepatitis::::high kcal, high protein, high carbohydrate, low fat', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary management for hepatitis:', 'High kcal, high protein, high carbohydrate, low fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Medical nutrition therapy (MNT) for acute and chronic hepatitis focuses on supporting liver cell regeneration, preventing tissue catabolism, and easing digestive stress:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High kcal, high protein, high carbohydrate, low fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Medical nutrition therapy (MNT) for acute and chronic hepatitis focuses on supporting liver cell regeneration, preventing tissue catabolism, and easing digestive stress:\n• High Kilocalorie (kcal) & High Carbohydrate: The liver''s ability to store glycogen and maintain blood glucose levels is impaired during inflammation. A high-calorie, carbohydrate-rich diet supplies the necessary energy, preserves muscle mass, and keeps glycogen stores replenished.\n• High Protein: Protein provides the necessary amino acids needed to heal, repair, and regenerate damaged liver parenchyma. (Note: Protein is only restricted if the patient develops advanced hepatic encephalopathy where the liver can no longer clear ammonia).\n• Low Fat: Because the inflamed liver struggles to produce and flow bile normally, fat digestion and metabolism are severely compromised. Restricting dietary fat minimizes symptoms like nausea, vomiting, abdominal pain, and steatorrhea (fatty stools).\n• Why Fluids Are Not Restricted: Fluid restriction is not an intervention for hepatitis. It is typically reserved for downstream complications of advanced liver disease, such as ascites or severe fluid retention in end-stage cirrhosis.","whyWrongChoices":"Alternative options: High kcal, low protein, high carbohydrate, low fat, High kcal, low protein, high carbohydrate, fluid restricted, High kcal, high protein, high carbohydrate, fluid restricted"}'::jsonb),
('mc:dietary management for hepatitis::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary management for hepatitis:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Medical nutrition therapy (MNT) for acute and chronic hepatitis focuses on supporting liver cell regeneration, preventing tissue catabolism, and easing digestive stress:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High kcal, high protein, high carbohydrate, low fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Medical nutrition therapy (MNT) for acute and chronic hepatitis focuses on supporting liver cell regeneration, preventing tissue catabolism, and easing digestive stress:\n• High Kilocalorie (kcal) & High Carbohydrate: The liver''s ability to store glycogen and maintain blood glucose levels is impaired during inflammation. A high-calorie, carbohydrate-rich diet supplies the necessary energy, preserves muscle mass, and keeps glycogen stores replenished.\n• High Protein: Protein provides the necessary amino acids needed to heal, repair, and regenerate damaged liver parenchyma. (Note: Protein is only restricted if the patient develops advanced hepatic encephalopathy where the liver can no longer clear ammonia).\n• Low Fat: Because the inflamed liver struggles to produce and flow bile normally, fat digestion and metabolism are severely compromised. Restricting dietary fat minimizes symptoms like nausea, vomiting, abdominal pain, and steatorrhea (fatty stools).\n• Why Fluids Are Not Restricted: Fluid restriction is not an intervention for hepatitis. It is typically reserved for downstream complications of advanced liver disease, such as ascites or severe fluid retention in end-stage cirrhosis.","whyWrongChoices":"Alternative options: High kcal, low protein, high carbohydrate, low fat, High kcal, low protein, high carbohydrate, fluid restricted, High kcal, high protein, high carbohydrate, fluid restricted"}'::jsonb),
('mc:dietary recommendation for patient with liver cirrhosis::::high kcal, high protein, high carbohydrate, low fat', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary recommendation for patient with liver cirrhosis:', 'High kcal, high protein, high carbohydrate, low fat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Medical nutrition therapy (MNT) for stable liver cirrhosis focus heavily on combatting severe tissue wasting (malnutrition) while protecting remaining hepatic function:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High kcal, high protein, high carbohydrate, low fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Medical nutrition therapy (MNT) for stable liver cirrhosis focus heavily on combatting severe tissue wasting (malnutrition) while protecting remaining hepatic function:\n\n• High Kilocalorie (kcal) & High Carbohydrate: Patients with cirrhosis suffer from profound muscle wasting and rapid depletion of glycogen stores. A high-calorie, carbohydrate-rich diet prevents the breakdown of muscle tissue for energy.\n• High Protein: Historically, protein was restricted out of fear it would cause hepatic encephalopathy. Modern clinical guidelines heavily contradict this; cirrhosis patients require an aggressive high-protein intake (typically 1.2–1.5 g/kg/day) to promote cellular repair, maintain lean body mass, and correct hypoalbuminemia. (Protein is only restricted or modified to branched-chain amino acids if the patient exhibits severe, refractory hepatic encephalopathy).\n• Low Fat: Fat absorption is frequently compromised due to impaired bile synthesis or secretion. Restricting dietary fat minimizes unpleasant digestive symptoms like steatorrhea, abdominal bloating, and nausea.","whyWrongChoices":"Alternative options: High kcal, low protein, high carbohydrate, low fat, High kcal, high protein, high carbohydrate, low fiber, High kcal, low protein, high carbohydrate, high fiber"}'::jsonb),
('mc:dietary recommendation for patient with liver cirrhosis::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary recommendation for patient with liver cirrhosis:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Medical nutrition therapy (MNT) for stable liver cirrhosis focus heavily on combatting severe tissue wasting (malnutrition) while protecting remaining hepatic function:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"High kcal, high protein, high carbohydrate, low fat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Medical nutrition therapy (MNT) for stable liver cirrhosis focus heavily on combatting severe tissue wasting (malnutrition) while protecting remaining hepatic function:\n\n• High Kilocalorie (kcal) & High Carbohydrate: Patients with cirrhosis suffer from profound muscle wasting and rapid depletion of glycogen stores. A high-calorie, carbohydrate-rich diet prevents the breakdown of muscle tissue for energy.\n• High Protein: Historically, protein was restricted out of fear it would cause hepatic encephalopathy. Modern clinical guidelines heavily contradict this; cirrhosis patients require an aggressive high-protein intake (typically 1.2–1.5 g/kg/day) to promote cellular repair, maintain lean body mass, and correct hypoalbuminemia. (Protein is only restricted or modified to branched-chain amino acids if the patient exhibits severe, refractory hepatic encephalopathy).\n• Low Fat: Fat absorption is frequently compromised due to impaired bile synthesis or secretion. Restricting dietary fat minimizes unpleasant digestive symptoms like steatorrhea, abdominal bloating, and nausea.","whyWrongChoices":"Alternative options: High kcal, low protein, high carbohydrate, low fat, High kcal, high protein, high carbohydrate, low fiber, High kcal, low protein, high carbohydrate, high fiber"}'::jsonb),
('mc:amount of calorie to reduce per day to effect weight loss of 1.5 lbs per week::::750 kcal', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'amount of calorie to reduce per day to effect weight loss of 1.5 lbs per week:', '750 kcal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• 500 kcal: This deficit results in a weight loss of 1 lb per week.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"750 kcal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• 500 kcal: This deficit results in a weight loss of 1 lb per week.\n• 1,000 kcal: This deficit results in a weight loss of 2 lbs per week.","whyWrongChoices":"Alternative options: 500 kcal, 1000 kcal, 100 kcal"}'::jsonb),
('mc:alcohol induced cirrhosis::::laennec''s cirrhosis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'alcohol induced cirrhosis:', 'Laennec''s cirrhosis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Laennec''s cirrhosis (historically named after the French physician René Laennec) is the specific medical term traditionally used to classify alcohol-induced liver cirrhosis. It develops over many years of chronic, heavy alcohol exposure, moving through phases of fatty liver infiltration (steatosis) and alcoholic hepatitis before replacing functional liver architecture with fine, uniform fibrous nodules and scar tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Laennec''s cirrhosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Laennec''s cirrhosis (historically named after the French physician René Laennec) is the specific medical term traditionally used to classify alcohol-induced liver cirrhosis. It develops over many years of chronic, heavy alcohol exposure, moving through phases of fatty liver infiltration (steatosis) and alcoholic hepatitis before replacing functional liver architecture with fine, uniform fibrous nodules and scar tissue.\n\n\t• Biliary cirrhosis stems from the destruction or long-term chronic obstruction of the bile ducts within the liver.\n\t• Obstructive cirrhosis is a mechanical description of biliary pathway blockages rather than a formal classification for alcohol abuse.\n\t• Cardiac cirrhosis is triggered by chronic, severe right-sided heart failure causing structural liver congestion.","whyWrongChoices":"Alternative options: Cardiac cirrhosis, Biliary cirrhosis, Obstructive cirrhosis"}'::jsonb),
('mc:alcohol induced cirrhosis::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'alcohol induced cirrhosis:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Laennec''s cirrhosis (historically named after the French physician René Laennec) is the specific medical term traditionally used to classify alcohol-induced liver cirrhosis. It develops over many years of chronic, heavy alcohol exposure, moving through phases of fatty liver infiltration (steatosis) and alcoholic hepatitis before replacing functional liver architecture with fine, uniform fibrous nodules and scar tissue.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Laennec''s cirrhosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Laennec''s cirrhosis (historically named after the French physician René Laennec) is the specific medical term traditionally used to classify alcohol-induced liver cirrhosis. It develops over many years of chronic, heavy alcohol exposure, moving through phases of fatty liver infiltration (steatosis) and alcoholic hepatitis before replacing functional liver architecture with fine, uniform fibrous nodules and scar tissue.\n\n\t• Biliary cirrhosis stems from the destruction or long-term chronic obstruction of the bile ducts within the liver.\n\t• Obstructive cirrhosis is a mechanical description of biliary pathway blockages rather than a formal classification for alcohol abuse.\n\t• Cardiac cirrhosis is triggered by chronic, severe right-sided heart failure causing structural liver congestion.","whyWrongChoices":"Alternative options: Cardiac cirrhosis, Biliary cirrhosis, Obstructive cirrhosis"}'::jsonb)
