INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:gastric secretory disturbances: no free or combined hci:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'gastric secretory disturbances: no free or combined hci', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When stomach acid is secreted, some of it remains unattached (free HCl), while some of it binds to proteins or organic matter in the stomach (combined HCl).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Achylia gastrica\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When stomach acid is secreted, some of it remains unattached (free HCl), while some of it binds to proteins or organic matter in the stomach (combined HCl).\n\nIn a patient classified with Achlorhydria under this specific grading system, they fail to produce free HCl, but some minimal traces of bound/combined acid may still be detected.\n\nAchylia Gastrica represents a complete shutdown of the secretory glands, meaning absolutely zero free or combined HCl can be found.\n\n• Achlorhydria: Defined strictly as the absence of free hydrochloric acid only.\n• Achylia Gastrica: Defined explicitly as the absence of both free and combined hydrochloric acid (alongside the absence of gastric enzymes like pepsin).\n• Hypochlorhydria: This indicates low or deficient stomach acid, but some free or combined HCl is still actively produced.\n• Hyperchlorhydria: This is the opposite condition—an excessive or elevated amount of gastric acid production.","whyWrongChoices":"Alternative options: Hyperchlorhydria, Hypochlorhydria, Achlorhydria"}'::jsonb),
('mc:refers to the high secretion of gastric juice.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the high secretion of gastric juice.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyperchlorhydria is the medical term for the abnormally high or excessive secretion of gastric juice and hydrochloric acid (HCl) by the parietal cells in the stomach lining.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperchlorhydria\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyperchlorhydria is the medical term for the abnormally high or excessive secretion of gastric juice and hydrochloric acid (HCl) by the parietal cells in the stomach lining.\n\nThis excess of highly acidic gastric juice lowers the stomach pH significantly. In clinical nutrition and dietetics, identifying hyperchlorhydria is crucial because this constant overproduction of digestive juices can irritate the stomach lining, leading directly to conditions like gastritis, acid reflux, or peptic ulcers if left unmanaged.\n\n• Peptic ulcer: A physical sore or lesion that forms on the lining of the stomach or duodenum. While it is frequently caused by long-term hyperchlorhydria, it is the structural damage itself rather than the secretion process.\n• Gastrosucchorrhea: An older, highly specific term for continuous gastric juice flow even when fasting, but it is not the standard clinical benchmark term used on board exams.\n• Gastritis: The broad medical term for the inflammation of the stomach wall lining, which can be triggered by excess acid, infection, or alcohol use.","whyWrongChoices":"Alternative options: Peptic ulcer, Gastritis, Gastrosucchorrhea"}'::jsonb),
('mc:pertains to the overflow of gastric juices.:::gastrosucchorrhea', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertains to the overflow of gastric juices.', 'Gastrosucchorrhea', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In medical nutrition and traditional gastrointestinal pathology frameworks, gastrosucchorrhea (historically known as Reichmann''s disease) is explicitly defined as the excessive secretion or overflow of gastric juices.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastrosucchorrhea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In medical nutrition and traditional gastrointestinal pathology frameworks, gastrosucchorrhea (historically known as Reichmann''s disease) is explicitly defined as the excessive secretion or overflow of gastric juices.\n\nUnder these textbook guidelines, it is traditionally managed with a high-fat diet because fats trigger the release of enterogastrones (like cholecystokinin), which naturally slow down stomach emptying and inhibit gastric acid secretions.\n\n• Gastritis: Refers strictly to the inflammation or irritation of the stomach lining.\n• Peptic ulcer: Refers to open sores or lesions that develop on the lining of the stomach or duodenum.\n• Hyperchlorhydria: Refers specifically to an excess concentration of hydrochloric acid in the gastric juice, but not necessarily the overall excessive overflow/volume of total secretions.","whyWrongChoices":"Alternative options: Peptic ulcer, Gastritis, Hyperchlorhydria"}'::jsonb),
('mc:pertains to the overflow of gastric juices.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertains to the overflow of gastric juices.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In medical nutrition and traditional gastrointestinal pathology frameworks, gastrosucchorrhea (historically known as Reichmann''s disease) is explicitly defined as the excessive secretion or overflow of gastric juices.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastrosucchorrhea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In medical nutrition and traditional gastrointestinal pathology frameworks, gastrosucchorrhea (historically known as Reichmann''s disease) is explicitly defined as the excessive secretion or overflow of gastric juices.\n\nUnder these textbook guidelines, it is traditionally managed with a high-fat diet because fats trigger the release of enterogastrones (like cholecystokinin), which naturally slow down stomach emptying and inhibit gastric acid secretions.\n\n• Gastritis: Refers strictly to the inflammation or irritation of the stomach lining.\n• Peptic ulcer: Refers to open sores or lesions that develop on the lining of the stomach or duodenum.\n• Hyperchlorhydria: Refers specifically to an excess concentration of hydrochloric acid in the gastric juice, but not necessarily the overall excessive overflow/volume of total secretions.","whyWrongChoices":"Alternative options: Peptic ulcer, Gastritis, Hyperchlorhydria"}'::jsonb),
('mc:gastric secretory disturbances: no free or combined hci:::achylia gastrica', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'gastric secretory disturbances: no free or combined hci', 'Achylia gastrica', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When stomach acid is secreted, some of it remains unattached (free HCl), while some of it binds to proteins or organic matter in the stomach (combined HCl).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Achylia gastrica\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When stomach acid is secreted, some of it remains unattached (free HCl), while some of it binds to proteins or organic matter in the stomach (combined HCl).\n\nIn a patient classified with Achlorhydria under this specific grading system, they fail to produce free HCl, but some minimal traces of bound/combined acid may still be detected.\n\nAchylia Gastrica represents a complete shutdown of the secretory glands, meaning absolutely zero free or combined HCl can be found.\n\n• Achlorhydria: Defined strictly as the absence of free hydrochloric acid only.\n• Achylia Gastrica: Defined explicitly as the absence of both free and combined hydrochloric acid (alongside the absence of gastric enzymes like pepsin).\n• Hypochlorhydria: This indicates low or deficient stomach acid, but some free or combined HCl is still actively produced.\n• Hyperchlorhydria: This is the opposite condition—an excessive or elevated amount of gastric acid production.","whyWrongChoices":"Alternative options: Hyperchlorhydria, Hypochlorhydria, Achlorhydria"}'::jsonb),
('mc:refers to the protrusion of the stomach into the chest through the esophageal hiatus of the diaphragm.:::hiatal hernia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the protrusion of the stomach into the chest through the esophageal hiatus of the diaphragm.', 'Hiatal hernia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A hiatal hernia occurs when the upper part of the stomach pushes upward through the esophageal hiatus (the small opening in the diaphragm where the esophagus passes through) and enters the chest cavity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hiatal hernia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A hiatal hernia occurs when the upper part of the stomach pushes upward through the esophageal hiatus (the small opening in the diaphragm where the esophagus passes through) and enters the chest cavity.\n\nThis structural displacement frequently leads to gastroesophageal reflux disease (GERD), heartburn, and chest discomfort because it disrupts the normal anti-reflux barrier.\n\n• Tropical sprue: A chronic diarrheal illness found in tropical regions that causes malabsorption in the small intestine.\n• Celiac disease: An autoimmune reaction to eating gluten that damages the lining of the small intestine.\n• Dyspepsia: A general medical term for indigestion or upper abdominal discomfort, not a physical structural protrusion.","whyWrongChoices":"Alternative options: Dyspepsia, Celiac disease, Tropical sprue"}'::jsonb),
('mc:refers to the protrusion of the stomach into the chest through the esophageal hiatus of the diaphragm.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the protrusion of the stomach into the chest through the esophageal hiatus of the diaphragm.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A hiatal hernia occurs when the upper part of the stomach pushes upward through the esophageal hiatus (the small opening in the diaphragm where the esophagus passes through) and enters the chest cavity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hiatal hernia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A hiatal hernia occurs when the upper part of the stomach pushes upward through the esophageal hiatus (the small opening in the diaphragm where the esophagus passes through) and enters the chest cavity.\n\nThis structural displacement frequently leads to gastroesophageal reflux disease (GERD), heartburn, and chest discomfort because it disrupts the normal anti-reflux barrier.\n\n• Tropical sprue: A chronic diarrheal illness found in tropical regions that causes malabsorption in the small intestine.\n• Celiac disease: An autoimmune reaction to eating gluten that damages the lining of the small intestine.\n• Dyspepsia: A general medical term for indigestion or upper abdominal discomfort, not a physical structural protrusion.","whyWrongChoices":"Alternative options: Dyspepsia, Celiac disease, Tropical sprue"}'::jsonb),
('mc:the lack of gastric tone, delayed emptying time caused by other diseases and emotional disturbance.:::gastric atony', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the lack of gastric tone, delayed emptying time caused by other diseases and emotional disturbance.', 'Gastric atony', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastric atony (clinically known today as gastroparesis) translates literally to a complete lack of muscle tone or strength (a- meaning without, -tony meaning tone) in the stomach wall.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastric atony\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastric atony (clinically known today as gastroparesis) translates literally to a complete lack of muscle tone or strength (a- meaning without, -tony meaning tone) in the stomach wall.\n\nBecause the stomach muscles lose their normal tone, they cannot generate the coordinated rhythmic waves (peristalsis) needed to crush and move food along. This leads directly to a severely delayed gastric emptying time in the complete absence of a physical blockage.\n\nThis loss of neuro-muscular tone is highly documented as an indirect complication caused by other diseases (most famously nervous system damage from long-standing diabetes or major surgeries) as well as acute emotional disturbances or high stress, which trigger the sympathetic nervous system to aggressively shut down normal gut motility.\n\n• Dyspepsia: The broad, medical term for general indigestion or an upset stomach. While delayed emptying causes dyspeptic symptoms (like bloating and early fullness), dyspepsia is a descriptive symptom classification rather than the underlying muscular tone condition.\n• Gastrectasia: The pathological dilatation or extreme stretching of the stomach walls caused by a physical, mechanical blockage trapping food at the exit valve (such as pyloric stenosis from a tumor or severe scar tissue formation).\n• Hiatal hernia: A structural anatomical defect where a portion of the upper stomach physically slides or pushes upward through the opening in the diaphragm into the chest cavity.","whyWrongChoices":"Alternative options: Hiatal hernia, Gastrectasia, Dyspepsia"}'::jsonb),
('mc:the lack of gastric tone, delayed emptying time caused by other diseases and emotional disturbance.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the lack of gastric tone, delayed emptying time caused by other diseases and emotional disturbance.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastric atony (clinically known today as gastroparesis) translates literally to a complete lack of muscle tone or strength (a- meaning without, -tony meaning tone) in the stomach wall.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastric atony\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastric atony (clinically known today as gastroparesis) translates literally to a complete lack of muscle tone or strength (a- meaning without, -tony meaning tone) in the stomach wall.\n\nBecause the stomach muscles lose their normal tone, they cannot generate the coordinated rhythmic waves (peristalsis) needed to crush and move food along. This leads directly to a severely delayed gastric emptying time in the complete absence of a physical blockage.\n\nThis loss of neuro-muscular tone is highly documented as an indirect complication caused by other diseases (most famously nervous system damage from long-standing diabetes or major surgeries) as well as acute emotional disturbances or high stress, which trigger the sympathetic nervous system to aggressively shut down normal gut motility.\n\n• Dyspepsia: The broad, medical term for general indigestion or an upset stomach. While delayed emptying causes dyspeptic symptoms (like bloating and early fullness), dyspepsia is a descriptive symptom classification rather than the underlying muscular tone condition.\n• Gastrectasia: The pathological dilatation or extreme stretching of the stomach walls caused by a physical, mechanical blockage trapping food at the exit valve (such as pyloric stenosis from a tumor or severe scar tissue formation).\n• Hiatal hernia: A structural anatomical defect where a portion of the upper stomach physically slides or pushes upward through the opening in the diaphragm into the chest cavity.","whyWrongChoices":"Alternative options: Hiatal hernia, Gastrectasia, Dyspepsia"}'::jsonb),
('mc:refers to the stenosis of the pylorus which prevents complete emptying, fermentation of contents and dilatation of the stomach caused by ulcer or scar formation, adhesions or cancer.:::gastrectasia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the stenosis of the pylorus which prevents complete emptying, fermentation of contents and dilatation of the stomach caused by ulcer or scar formation, adhesions or cancer.', 'Gastrectasia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastrectasia (derived from the Greek words gaster meaning stomach, and ektasis meaning stretching or extension) is the medical term explicitly defined as the pathological dilatation or distension of the stomach.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastrectasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastrectasia (derived from the Greek words gaster meaning stomach, and ektasis meaning stretching or extension) is the medical term explicitly defined as the pathological dilatation or distension of the stomach.\n\nWhen a patient develops a structural obstruction like pyloric stenosis (narrowing of the stomach''s exit valve) due to chronic ulcers, scar tissue, adhesions, or stomach cancer, food cannot pass normally into the small intestine. This trapped food undergoes stagnation and bacterial fermentation, building up massive amounts of gas and organic acids. The resulting pressure forces the muscular walls of the stomach to over-stretch, leading directly to the profound clinical presentation of gastrectasia.\n\n• Gastric atony: This refers to a total loss of normal muscular tone and contractions (peristalsis) in the stomach wall, typically caused by neurological damage (like diabetic gastroparesis) rather than a physical structural stenosis at the pylorus.\n• Dyspepsia: The broad, generic clinical term for indigestion or an upset stomach. While it shares symptoms like bloating or nausea, it is a symptomatic classification rather than a severe structural dilatation defect.\n• Hiatal hernia: A structural defect where a portion of the upper stomach pushes upward through the diaphragm into the chest cavity, unrelated to pyloric obstruction or internal fermentation loops.","whyWrongChoices":"Alternative options: Hiatal hernia, Gastric atony, Dyspepsia"}'::jsonb),
('mc:refers to the stenosis of the pylorus which prevents complete emptying, fermentation of contents and dilatation of the stomach caused by ulcer or scar formation, adhesions or cancer.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the stenosis of the pylorus which prevents complete emptying, fermentation of contents and dilatation of the stomach caused by ulcer or scar formation, adhesions or cancer.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastrectasia (derived from the Greek words gaster meaning stomach, and ektasis meaning stretching or extension) is the medical term explicitly defined as the pathological dilatation or distension of the stomach.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastrectasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastrectasia (derived from the Greek words gaster meaning stomach, and ektasis meaning stretching or extension) is the medical term explicitly defined as the pathological dilatation or distension of the stomach.\n\nWhen a patient develops a structural obstruction like pyloric stenosis (narrowing of the stomach''s exit valve) due to chronic ulcers, scar tissue, adhesions, or stomach cancer, food cannot pass normally into the small intestine. This trapped food undergoes stagnation and bacterial fermentation, building up massive amounts of gas and organic acids. The resulting pressure forces the muscular walls of the stomach to over-stretch, leading directly to the profound clinical presentation of gastrectasia.\n\n• Gastric atony: This refers to a total loss of normal muscular tone and contractions (peristalsis) in the stomach wall, typically caused by neurological damage (like diabetic gastroparesis) rather than a physical structural stenosis at the pylorus.\n• Dyspepsia: The broad, generic clinical term for indigestion or an upset stomach. While it shares symptoms like bloating or nausea, it is a symptomatic classification rather than a severe structural dilatation defect.\n• Hiatal hernia: A structural defect where a portion of the upper stomach pushes upward through the diaphragm into the chest cavity, unrelated to pyloric obstruction or internal fermentation loops.","whyWrongChoices":"Alternative options: Hiatal hernia, Gastric atony, Dyspepsia"}'::jsonb),
('mc:a condition of discomfort in the digestive tract that can be physical or psychological in origin; known as indigestion.:::dyspepsia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a condition of discomfort in the digestive tract that can be physical or psychological in origin; known as indigestion.', 'Dyspepsia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dyspepsia is the formal medical term for indigestion. It describes a broad state of functional discomfort centered in the upper digestive tract.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dyspepsia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dyspepsia is the formal medical term for indigestion. It describes a broad state of functional discomfort centered in the upper digestive tract.\n\nDyspepsia is highly unique because it can stem from physical/organic causes (such as peptic ulcers, gastritis, or medication side effects) or entirely psychological origins (such as chronic emotional stress, anxiety, or depression that alters gut motility via the brain-gut axis). Its hallmark symptoms include upper abdominal pain, early fullness during meals, uncomfortable bloating, and nausea.\n\n• Hiatal hernia: A structural, physical defect where the upper portion of the stomach pushes upward through the diaphragm into the chest cavity.\n• Gastric atony: A specific physiological condition characterized by a severe loss of muscular tone in the stomach wall, leading to delayed gastric emptying (gastroparesis).\n• Gastrectasia: The severe pathological stretching or distension of the stomach walls, caused by a physical, mechanical obstruction at the pylorus.","whyWrongChoices":"Alternative options: Hiatal hernia, Gastric atony, Gastrectasia"}'::jsonb),
('mc:a condition of discomfort in the digestive tract that can be physical or psychological in origin; known as indigestion.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a condition of discomfort in the digestive tract that can be physical or psychological in origin; known as indigestion.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Dyspepsia is the formal medical term for indigestion. It describes a broad state of functional discomfort centered in the upper digestive tract.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dyspepsia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Dyspepsia is the formal medical term for indigestion. It describes a broad state of functional discomfort centered in the upper digestive tract.\n\nDyspepsia is highly unique because it can stem from physical/organic causes (such as peptic ulcers, gastritis, or medication side effects) or entirely psychological origins (such as chronic emotional stress, anxiety, or depression that alters gut motility via the brain-gut axis). Its hallmark symptoms include upper abdominal pain, early fullness during meals, uncomfortable bloating, and nausea.\n\n• Hiatal hernia: A structural, physical defect where the upper portion of the stomach pushes upward through the diaphragm into the chest cavity.\n• Gastric atony: A specific physiological condition characterized by a severe loss of muscular tone in the stomach wall, leading to delayed gastric emptying (gastroparesis).\n• Gastrectasia: The severe pathological stretching or distension of the stomach walls, caused by a physical, mechanical obstruction at the pylorus.","whyWrongChoices":"Alternative options: Hiatal hernia, Gastric atony, Gastrectasia"}'::jsonb),
('mc:refers to the fibrosis of the bowel wall due to radiation exposure characterized by diarrhea and malabsorption.:::enteritis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the fibrosis of the bowel wall due to radiation exposure characterized by diarrhea and malabsorption.', 'Enteritis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Radiation enteritis is a functional and structural injury to the small or large intestines caused by receiving radiotherapy (typically for pelvic or abdominal cancers).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Enteritis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Radiation enteritis is a functional and structural injury to the small or large intestines caused by receiving radiotherapy (typically for pelvic or abdominal cancers).\n\nWhile the acute phase involves immediate mucosal inflammation, the chronic or delayed phase is pathologically characterized by progressive submucosal intestinal wall fibrosis and vascular sclerosis. This thickens and stiffens the bowel wall, directly disrupting its ability to absorb nutrients and pump waste properly—leading to chronic diarrhea and severe malabsorption.\n\nNote on Exam Keys: Because standard nutrition and diet therapy board exams use multiple-choice pools derived from older foundational references, this condition is sometimes grouped under its generic localized term (Enteritis) or a textbook typo entry, but clinically and contextually, it represents radiation enteropathy/enteritis.\n\n• Tropical sprue: A chronic diarrheal illness characterized by malabsorption and small bowel structural changes, but it is endemic to tropical regions and caused by a persistent bacterial infection, completely unrelated to radiation exposure.\n• Lymphangiectasis: A rare gastrointestinal disorder characterized by pathologically dilated intestinal lymphatic vessels, which blocks lymph drainage and causes protein-losing enteropathy.\n• Celiac disease: An autoimmune digestive disorder where consuming gluten (a protein found in wheat, rye, and barley) triggers immune-mediated damage to the villi of the small intestine, not caused by radiation therapy.","whyWrongChoices":"Alternative options: Celiac disease, Tropical sprue, Lymphangiectasis"}'::jsonb),
('mc:refers to the fibrosis of the bowel wall due to radiation exposure characterized by diarrhea and malabsorption.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the fibrosis of the bowel wall due to radiation exposure characterized by diarrhea and malabsorption.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Radiation enteritis is a functional and structural injury to the small or large intestines caused by receiving radiotherapy (typically for pelvic or abdominal cancers).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Enteritis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Radiation enteritis is a functional and structural injury to the small or large intestines caused by receiving radiotherapy (typically for pelvic or abdominal cancers).\n\nWhile the acute phase involves immediate mucosal inflammation, the chronic or delayed phase is pathologically characterized by progressive submucosal intestinal wall fibrosis and vascular sclerosis. This thickens and stiffens the bowel wall, directly disrupting its ability to absorb nutrients and pump waste properly—leading to chronic diarrhea and severe malabsorption.\n\nNote on Exam Keys: Because standard nutrition and diet therapy board exams use multiple-choice pools derived from older foundational references, this condition is sometimes grouped under its generic localized term (Enteritis) or a textbook typo entry, but clinically and contextually, it represents radiation enteropathy/enteritis.\n\n• Tropical sprue: A chronic diarrheal illness characterized by malabsorption and small bowel structural changes, but it is endemic to tropical regions and caused by a persistent bacterial infection, completely unrelated to radiation exposure.\n• Lymphangiectasis: A rare gastrointestinal disorder characterized by pathologically dilated intestinal lymphatic vessels, which blocks lymph drainage and causes protein-losing enteropathy.\n• Celiac disease: An autoimmune digestive disorder where consuming gluten (a protein found in wheat, rye, and barley) triggers immune-mediated damage to the villi of the small intestine, not caused by radiation therapy.","whyWrongChoices":"Alternative options: Celiac disease, Tropical sprue, Lymphangiectasis"}'::jsonb),
('mc:refers to the congenital malformation of the lymphatic system causing losses of protein, diarrhea, and steatorrhea due to malabsorption.:::lymphangiectasia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the congenital malformation of the lymphatic system causing losses of protein, diarrhea, and steatorrhea due to malabsorption.', 'Lymphangiectasia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Intestinal lymphangiectasia is a rare protein-losing enteropathy characterized by the abnormal dilation or congenital malformation of the small intestine''s lymphatic vessels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lymphangiectasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Intestinal lymphangiectasia is a rare protein-losing enteropathy characterized by the abnormal dilation or congenital malformation of the small intestine''s lymphatic vessels.\n\nBecause normal lymphatic drainage is blocked or impaired, protein-rich lymph leaks directly into the intestinal cavity. This obstruction causes severe malabsorption of dietary fats, leading to steatorrhea (fatty stools), diarrhea, and significant losses of plasma proteins like albumin.\n\nIn clinical dietetics, this condition is traditionally managed with a low-fat diet supplemented with Medium-Chain Triglycerides (MCTs). MCTs bypass the damaged lymphatic system and are absorbed directly into the portal vein, reducing the pressure and leakage within the lymph vessels.\n\n• Tropical sprue: An acquired infectious or bacterial overgrowth syndrome found in tropical regions that primarily causes malabsorption of Vitamin B₁₂ and folate.\n• Enteritis: A general medical term indicating inflammation of the small intestine, which can be caused by infections, radiation, or allergies.\n• Celiac disease: An autoimmune disorder triggered by eating gluten that damages the mucosal villi of the small intestine.","whyWrongChoices":"Alternative options: Celiac disease, Tropical sprue, Enteritis"}'::jsonb),
('mc:refers to the congenital malformation of the lymphatic system causing losses of protein, diarrhea, and steatorrhea due to malabsorption.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the congenital malformation of the lymphatic system causing losses of protein, diarrhea, and steatorrhea due to malabsorption.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Intestinal lymphangiectasia is a rare protein-losing enteropathy characterized by the abnormal dilation or congenital malformation of the small intestine''s lymphatic vessels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lymphangiectasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Intestinal lymphangiectasia is a rare protein-losing enteropathy characterized by the abnormal dilation or congenital malformation of the small intestine''s lymphatic vessels.\n\nBecause normal lymphatic drainage is blocked or impaired, protein-rich lymph leaks directly into the intestinal cavity. This obstruction causes severe malabsorption of dietary fats, leading to steatorrhea (fatty stools), diarrhea, and significant losses of plasma proteins like albumin.\n\nIn clinical dietetics, this condition is traditionally managed with a low-fat diet supplemented with Medium-Chain Triglycerides (MCTs). MCTs bypass the damaged lymphatic system and are absorbed directly into the portal vein, reducing the pressure and leakage within the lymph vessels.\n\n• Tropical sprue: An acquired infectious or bacterial overgrowth syndrome found in tropical regions that primarily causes malabsorption of Vitamin B₁₂ and folate.\n• Enteritis: A general medical term indicating inflammation of the small intestine, which can be caused by infections, radiation, or allergies.\n• Celiac disease: An autoimmune disorder triggered by eating gluten that damages the mucosal villi of the small intestine.","whyWrongChoices":"Alternative options: Celiac disease, Tropical sprue, Enteritis"}'::jsonb),
('mc:are sacs or pouches that develop on weakened areas of the intestinal wall.:::diverticula', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'are sacs or pouches that develop on weakened areas of the intestinal wall.', 'Diverticula', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diverticula (singular: diverticulum) is the specific anatomical term for the sacs or pouches themselves. They form when the inner layers of the intestinal wall push outward through weakened spots in the surrounding muscular layer, most commonly in the colon (large intestine).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diverticula\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diverticula (singular: diverticulum) is the specific anatomical term for the sacs or pouches themselves. They form when the inner layers of the intestinal wall push outward through weakened spots in the surrounding muscular layer, most commonly in the colon (large intestine).\n\n• Diverticulosis: This is the clinical condition of having these pouches present in the intestines. It describes the overall asymptomatic state of the disease rather than the individual physical pouches themselves.\n• Diverticulitis: This refers specifically to the medical complication where these pouches become inflamed or infected, leading to symptoms like severe abdominal pain, fever, and nausea.\n• Peptic ulcer: An open sore or lesion that develops on the protective lining of the stomach or duodenum, completely unrelated to structural pouches forming on the intestinal wall.","whyWrongChoices":"Alternative options: Diverticulosis, Diverticulitis, Clinical option 4"}'::jsonb),
('mc:are sacs or pouches that develop on weakened areas of the intestinal wall.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'are sacs or pouches that develop on weakened areas of the intestinal wall.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Diverticula (singular: diverticulum) is the specific anatomical term for the sacs or pouches themselves. They form when the inner layers of the intestinal wall push outward through weakened spots in the surrounding muscular layer, most commonly in the colon (large intestine).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Diverticula\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Diverticula (singular: diverticulum) is the specific anatomical term for the sacs or pouches themselves. They form when the inner layers of the intestinal wall push outward through weakened spots in the surrounding muscular layer, most commonly in the colon (large intestine).\n\n• Diverticulosis: This is the clinical condition of having these pouches present in the intestines. It describes the overall asymptomatic state of the disease rather than the individual physical pouches themselves.\n• Diverticulitis: This refers specifically to the medical complication where these pouches become inflamed or infected, leading to symptoms like severe abdominal pain, fever, and nausea.\n• Peptic ulcer: An open sore or lesion that develops on the protective lining of the stomach or duodenum, completely unrelated to structural pouches forming on the intestinal wall.","whyWrongChoices":"Alternative options: Diverticulosis, Diverticulitis, Clinical option 4"}'::jsonb),
('mc:pertains to the chronic inflammation and ulceration of the large intestines'' mucosa characterized by rectal bleeding, fever, malnutrition, and diarrhea with pain and spasm.:::ulcerative colitis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertains to the chronic inflammation and ulceration of the large intestines'' mucosa characterized by rectal bleeding, fever, malnutrition, and diarrhea with pain and spasm.', 'Ulcerative colitis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ulcerative colitis is an inflammatory bowel disease (IBD) that is strictly limited to the large intestine (colon and rectum).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ulcerative colitis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ulcerative colitis is an inflammatory bowel disease (IBD) that is strictly limited to the large intestine (colon and rectum).\n\nIt affects only the innermost lining, which is the mucosa and submucosa.\n\nBecause it originates in the rectum and spreads continuously upward through the colon, it is uniquely characterized by frequent bouts of bloody diarrhea (rectal bleeding), abdominal pain and spasm (tenesmus), fever, and severe malnutrition due to chronic nutrient and fluid loss.\n\n• Appendicitis: An acute inflammation of the appendix, typically presenting with sharp, sudden pain in the lower right abdomen and fever, rather than chronic mucosal ulceration and ongoing rectal bleeding.\n• Hemorrhoids: Swollen, inflamed veins in the rectum and anus that can cause bright red rectal bleeding and localized pain, but they do not cause chronic mucosal large intestinal inflammation, fever, or malnutrition.\n• Crohn''s disease: While also an inflammatory bowel disease that causes diarrhea, pain, and malnutrition, Crohn''s disease is characterized by transmural inflammation (affecting all layers of the bowel wall) and can occur anywhere along the entire gastrointestinal tract (from mouth to anus) in a patchy, \"skip-lesion\" pattern, rather than being restricted to the large intestine''s mucosa.","whyWrongChoices":"Alternative options: Crohn''s disease, Appendicitis, Hemorrhoids"}'::jsonb),
('mc:pertains to the chronic inflammation and ulceration of the large intestines'' mucosa characterized by rectal bleeding, fever, malnutrition, and diarrhea with pain and spasm.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertains to the chronic inflammation and ulceration of the large intestines'' mucosa characterized by rectal bleeding, fever, malnutrition, and diarrhea with pain and spasm.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ulcerative colitis is an inflammatory bowel disease (IBD) that is strictly limited to the large intestine (colon and rectum).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ulcerative colitis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ulcerative colitis is an inflammatory bowel disease (IBD) that is strictly limited to the large intestine (colon and rectum).\n\nIt affects only the innermost lining, which is the mucosa and submucosa.\n\nBecause it originates in the rectum and spreads continuously upward through the colon, it is uniquely characterized by frequent bouts of bloody diarrhea (rectal bleeding), abdominal pain and spasm (tenesmus), fever, and severe malnutrition due to chronic nutrient and fluid loss.\n\n• Appendicitis: An acute inflammation of the appendix, typically presenting with sharp, sudden pain in the lower right abdomen and fever, rather than chronic mucosal ulceration and ongoing rectal bleeding.\n• Hemorrhoids: Swollen, inflamed veins in the rectum and anus that can cause bright red rectal bleeding and localized pain, but they do not cause chronic mucosal large intestinal inflammation, fever, or malnutrition.\n• Crohn''s disease: While also an inflammatory bowel disease that causes diarrhea, pain, and malnutrition, Crohn''s disease is characterized by transmural inflammation (affecting all layers of the bowel wall) and can occur anywhere along the entire gastrointestinal tract (from mouth to anus) in a patchy, \"skip-lesion\" pattern, rather than being restricted to the large intestine''s mucosa.","whyWrongChoices":"Alternative options: Crohn''s disease, Appendicitis, Hemorrhoids"}'::jsonb),
('mc:refers to the crack-like ulcers accompany inflammation commonly affects the ileum and colon.:::crohn''s disease', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the crack-like ulcers accompany inflammation commonly affects the ileum and colon.', 'Crohn''s disease', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In medical and clinical nutrition board exams, the distinct phrase \"crack-like ulcers accompanying inflammation\" is the hallmark description of the linear, deep mucosal fissures that form in Crohn''s disease. Because Crohn''s causes transmural inflammation (penetrating all layers of the intestinal wall), these ulcers slice deeply into the tissue, creating a classic macroscopic \"cobblestone\" appearance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Crohn''s disease\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In medical and clinical nutrition board exams, the distinct phrase \"crack-like ulcers accompanying inflammation\" is the hallmark description of the linear, deep mucosal fissures that form in Crohn''s disease. Because Crohn''s causes transmural inflammation (penetrating all layers of the intestinal wall), these ulcers slice deeply into the tissue, creating a classic macroscopic \"cobblestone\" appearance.\n\nCrohn''s disease can affect any part of the gastrointestinal tract from the mouth to the anus, but it most commonly affects the ileum (the terminal small intestine) and the colon (large intestine).\n\n• Ulcerative colitis: While it is also an inflammatory bowel disease (IBD) that causes ulceration, it causes shallow, continuous sores confined strictly to the innermost mucosal lining of the colon and rectum, rather than deep, crack-like structural fissures.\n• Appendicitis: An acute inflammation of the appendix pouch, presenting with sharp pain and swelling rather than widespread chronic linear ulcerations across the ileum and colon.\n• Hemorrhoids: Swollen, distended veins in the lower rectum and anus, completely unrelated to intestinal track wall inflammation or mucosal ulcers.","whyWrongChoices":"Alternative options: Ulcerative colitis, Appendicitis, Hemorrhoids"}'::jsonb),
('mc:refers to the crack-like ulcers accompany inflammation commonly affects the ileum and colon.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the crack-like ulcers accompany inflammation commonly affects the ileum and colon.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In medical and clinical nutrition board exams, the distinct phrase \"crack-like ulcers accompanying inflammation\" is the hallmark description of the linear, deep mucosal fissures that form in Crohn''s disease. Because Crohn''s causes transmural inflammation (penetrating all layers of the intestinal wall), these ulcers slice deeply into the tissue, creating a classic macroscopic \"cobblestone\" appearance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Crohn''s disease\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In medical and clinical nutrition board exams, the distinct phrase \"crack-like ulcers accompanying inflammation\" is the hallmark description of the linear, deep mucosal fissures that form in Crohn''s disease. Because Crohn''s causes transmural inflammation (penetrating all layers of the intestinal wall), these ulcers slice deeply into the tissue, creating a classic macroscopic \"cobblestone\" appearance.\n\nCrohn''s disease can affect any part of the gastrointestinal tract from the mouth to the anus, but it most commonly affects the ileum (the terminal small intestine) and the colon (large intestine).\n\n• Ulcerative colitis: While it is also an inflammatory bowel disease (IBD) that causes ulceration, it causes shallow, continuous sores confined strictly to the innermost mucosal lining of the colon and rectum, rather than deep, crack-like structural fissures.\n• Appendicitis: An acute inflammation of the appendix pouch, presenting with sharp pain and swelling rather than widespread chronic linear ulcerations across the ileum and colon.\n• Hemorrhoids: Swollen, distended veins in the lower rectum and anus, completely unrelated to intestinal track wall inflammation or mucosal ulcers.","whyWrongChoices":"Alternative options: Ulcerative colitis, Appendicitis, Hemorrhoids"}'::jsonb),
('mc:pertains to the proliferation microorganisms because of reduction of gastric secretions and other protective mechanisms.:::bacterial overgrowth', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertains to the proliferation microorganisms because of reduction of gastric secretions and other protective mechanisms.', 'Bacterial overgrowth', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastric acid (hydrochloric acid) is one of the body''s primary chemical defense barriers. It sterilizes swallowed food and keeps the upper gastrointestinal tract relatively free of microbes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bacterial overgrowth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastric acid (hydrochloric acid) is one of the body''s primary chemical defense barriers. It sterilizes swallowed food and keeps the upper gastrointestinal tract relatively free of microbes.\n\nWhen gastric secretions are reduced (hypochlorhydria or achlorhydria)—often due to aging, chronic gastritis, or the long-term use of acid-reducing medications like proton pump inhibitors—this chemical shield fails. Oral and colonic microbes penetrate the proximal gut and multiply unchecked, resulting in bacterial overgrowth (such as Small Intestinal Bacterial Overgrowth, or SIBO). This causes microvilli damage, nutrient malabsorption, and gas production.\n\n• Irritable bowel syndrome (IBS): A functional gastrointestinal disorder marked by abdominal pain, cramping, bloating, and altered bowel habits, but it is defined by visceral hypersensitivity and motility issues rather than being caused by a drop in stomach acid.\n• Hemorrhoids: Swollen, inflamed veins located around the anus or lower rectum, completely unrelated to gastric juices or microbial populations.\n• Appendicitis: An acute inflammation of the appendix, typically caused by a physical blockage (such as a fecalith) trapping mucus inside the pouch, not by an upper-stomach acid reduction.","whyWrongChoices":"Alternative options: Appendicitis, Hemorrhoids, Irritable bowel syndrome"}'::jsonb),
('mc:in preparing for program planning and management, the first step is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in preparing for program planning and management, the first step is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Establishing the group responsible for leading the planning process is the necessary first step before any assessment, goal-setting, or plan preparation can occur. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Identifications/mobilization of LNC or planning core group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Establishing the group responsible for leading the planning process is the necessary first step before any assessment, goal-setting, or plan preparation can occur. \n\nAssessment or diagnostic analysis, setting goals and objectives, and preparing the plan of operation are all important subsequent steps, but they require an organized planning group to already be in place to carry them out.","whyWrongChoices":"Alternative options: Assessment or Diagnostic Analysis, Setting of goals and objectives, Preparation of plan of operation"}'::jsonb),
('mc:also called portal systematic encephalopathy, liver malfunction characterized by confusion, apathy and neurological dysfunction.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'also called portal systematic encephalopathy, liver malfunction characterized by confusion, apathy and neurological dysfunction.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In traditional nutrition, diet therapy, and nursing board exams, Hepatic coma is used interchangeably with Portal-Systemic Encephalopathy (PSE) and Hepatic Encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hepatic coma\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In traditional nutrition, diet therapy, and nursing board exams, Hepatic coma is used interchangeably with Portal-Systemic Encephalopathy (PSE) and Hepatic Encephalopathy.\n\nThis condition represents a complex neuropsychiatric syndrome caused by severe liver malfunction. When the liver fails to detoxify blood from the digestive tract, toxic compounds—principally ammonia—bypass the liver, cross the blood-brain barrier, and accumulate in brain tissue. This triggers progressive neurotoxicity characterized by confusion, apathy, personality changes, slurred speech, and involuntary tremors (asterixis), which can ultimately progress to a deep coma.","whyWrongChoices":"Alternative options: Fatty liver, Hepatitis, Cirrhosis"}'::jsonb),
('mc:pertains to the proliferation microorganisms because of reduction of gastric secretions and other protective mechanisms.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertains to the proliferation microorganisms because of reduction of gastric secretions and other protective mechanisms.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gastric acid (hydrochloric acid) is one of the body''s primary chemical defense barriers. It sterilizes swallowed food and keeps the upper gastrointestinal tract relatively free of microbes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bacterial overgrowth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gastric acid (hydrochloric acid) is one of the body''s primary chemical defense barriers. It sterilizes swallowed food and keeps the upper gastrointestinal tract relatively free of microbes.\n\nWhen gastric secretions are reduced (hypochlorhydria or achlorhydria)—often due to aging, chronic gastritis, or the long-term use of acid-reducing medications like proton pump inhibitors—this chemical shield fails. Oral and colonic microbes penetrate the proximal gut and multiply unchecked, resulting in bacterial overgrowth (such as Small Intestinal Bacterial Overgrowth, or SIBO). This causes microvilli damage, nutrient malabsorption, and gas production.\n\n• Irritable bowel syndrome (IBS): A functional gastrointestinal disorder marked by abdominal pain, cramping, bloating, and altered bowel habits, but it is defined by visceral hypersensitivity and motility issues rather than being caused by a drop in stomach acid.\n• Hemorrhoids: Swollen, inflamed veins located around the anus or lower rectum, completely unrelated to gastric juices or microbial populations.\n• Appendicitis: An acute inflammation of the appendix, typically caused by a physical blockage (such as a fecalith) trapping mucus inside the pouch, not by an upper-stomach acid reduction.","whyWrongChoices":"Alternative options: Appendicitis, Hemorrhoids, Irritable bowel syndrome"}'::jsonb),
('mc:refers to the failure of the liver to metabolize fat due to inflammation, hepatic injury or poor fat transport; insulin resistance.:::fatty liver', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the failure of the liver to metabolize fat due to inflammation, hepatic injury or poor fat transport; insulin resistance.', 'Fatty liver', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fatty liver (clinically known as steatosis or metabolic dysfunction-associated steatotic liver disease/MASLD) is the pathologically defined condition where the liver fails to properly metabolize and export lipids. This results in an abnormal accumulation of triglycerides inside more than 5% of the liver cells (hepatocytes).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fatty liver\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fatty liver (clinically known as steatosis or metabolic dysfunction-associated steatotic liver disease/MASLD) is the pathologically defined condition where the liver fails to properly metabolize and export lipids. This results in an abnormal accumulation of triglycerides inside more than 5% of the liver cells (hepatocytes).\n\nThe prompt describes the classic metabolic pathways that cause this buildup:\n\t• Insulin resistance: When cells become resistant to insulin, adipose tissue aggressively breaks down stored fats, flooding the liver with free fatty acids.\n\t• Hepatic injury or poor fat transport: If the liver cells are damaged, they cannot synthesize the essential apoproteins needed to package these lipids into VLDL particles for export. This traps the fat inside the liver tissue, leading directly to a fatty liver.\n\n• Hepatitis: This refers strictly to the inflammation of the liver tissue (often caused by viruses or toxins). While prolonged fatty liver can progress into inflammatory steatohepatitis (NASH/MASH), fatty liver is the specific metabolic stage where fat accumulates.\n• Hepatic coma: An end-stage neuropsychiatric complication (portal-systemic encephalopathy) where toxic ammonia builds up in the brain, causing confusion and unconsciousness, completely distinct from early fat transport failures.\n• Cirrhosis: The final, irreversible stage of chronic liver disease characterized by extensive fibrosis (scarring) and the destruction of normal liver architecture, rather than the initial accumulation of fat.","whyWrongChoices":"Alternative options: Hepatitis, Cirrhosis, Hepatic coma"}'::jsonb),
('mc:refers to the failure of the liver to metabolize fat due to inflammation, hepatic injury or poor fat transport; insulin resistance.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the failure of the liver to metabolize fat due to inflammation, hepatic injury or poor fat transport; insulin resistance.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fatty liver (clinically known as steatosis or metabolic dysfunction-associated steatotic liver disease/MASLD) is the pathologically defined condition where the liver fails to properly metabolize and export lipids. This results in an abnormal accumulation of triglycerides inside more than 5% of the liver cells (hepatocytes).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fatty liver\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fatty liver (clinically known as steatosis or metabolic dysfunction-associated steatotic liver disease/MASLD) is the pathologically defined condition where the liver fails to properly metabolize and export lipids. This results in an abnormal accumulation of triglycerides inside more than 5% of the liver cells (hepatocytes).\n\nThe prompt describes the classic metabolic pathways that cause this buildup:\n\t• Insulin resistance: When cells become resistant to insulin, adipose tissue aggressively breaks down stored fats, flooding the liver with free fatty acids.\n\t• Hepatic injury or poor fat transport: If the liver cells are damaged, they cannot synthesize the essential apoproteins needed to package these lipids into VLDL particles for export. This traps the fat inside the liver tissue, leading directly to a fatty liver.\n\n• Hepatitis: This refers strictly to the inflammation of the liver tissue (often caused by viruses or toxins). While prolonged fatty liver can progress into inflammatory steatohepatitis (NASH/MASH), fatty liver is the specific metabolic stage where fat accumulates.\n• Hepatic coma: An end-stage neuropsychiatric complication (portal-systemic encephalopathy) where toxic ammonia builds up in the brain, causing confusion and unconsciousness, completely distinct from early fat transport failures.\n• Cirrhosis: The final, irreversible stage of chronic liver disease characterized by extensive fibrosis (scarring) and the destruction of normal liver architecture, rather than the initial accumulation of fat.","whyWrongChoices":"Alternative options: Hepatitis, Cirrhosis, Hepatic coma"}'::jsonb),
('mc:also called portal systematic encephalopathy, liver malfunction characterized by confusion, apathy and neurological dysfunction.:::hepatic coma', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'also called portal systematic encephalopathy, liver malfunction characterized by confusion, apathy and neurological dysfunction.', 'Hepatic coma', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In traditional nutrition, diet therapy, and nursing board exams, Hepatic coma is used interchangeably with Portal-Systemic Encephalopathy (PSE) and Hepatic Encephalopathy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hepatic coma\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In traditional nutrition, diet therapy, and nursing board exams, Hepatic coma is used interchangeably with Portal-Systemic Encephalopathy (PSE) and Hepatic Encephalopathy.\n\nThis condition represents a complex neuropsychiatric syndrome caused by severe liver malfunction. When the liver fails to detoxify blood from the digestive tract, toxic compounds—principally ammonia—bypass the liver, cross the blood-brain barrier, and accumulate in brain tissue. This triggers progressive neurotoxicity characterized by confusion, apathy, personality changes, slurred speech, and involuntary tremors (asterixis), which can ultimately progress to a deep coma.","whyWrongChoices":"Alternative options: Fatty liver, Hepatitis, Cirrhosis"}'::jsonb),
('mc:increased blood pressure due to obstructed blood flow to the liver.:::portal hypertension', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'increased blood pressure due to obstructed blood flow to the liver.', 'Portal hypertension', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The portal vein carries blood from the digestive organs to the liver. When structural damage (like cirrhosis or scarring) blocks or obstructs normal blood flow through the liver, pressure builds backward into the portal venous system. This localized increase in blood pressure is clinically defined as portal hypertension.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Portal hypertension\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The portal vein carries blood from the digestive organs to the liver. When structural damage (like cirrhosis or scarring) blocks or obstructs normal blood flow through the liver, pressure builds backward into the portal venous system. This localized increase in blood pressure is clinically defined as portal hypertension.\n\nComplications caused by portal hypertension:\n\n• Collateral formation: The development of alternative, bypass blood vessels that the body creates to divert blood away from the high-pressure portal system.\n• Esophageal varices: Enlarged, fragile veins in the lower esophagus that balloon outward because of the backed-up pressure from portal hypertension. These are highly prone to rupturing and causing life-threatening bleeding.\n• Ascites: The accumulation of fluid in the peritoneal cavity of the abdomen, caused by a combination of high portal pressure leaking fluid and low blood albumin levels.","whyWrongChoices":"Alternative options: Ascites, Esophageal varices, Collateral formation"}'::jsonb),
('mc:increased blood pressure due to obstructed blood flow to the liver.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'increased blood pressure due to obstructed blood flow to the liver.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The portal vein carries blood from the digestive organs to the liver. When structural damage (like cirrhosis or scarring) blocks or obstructs normal blood flow through the liver, pressure builds backward into the portal venous system. This localized increase in blood pressure is clinically defined as portal hypertension.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Portal hypertension\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The portal vein carries blood from the digestive organs to the liver. When structural damage (like cirrhosis or scarring) blocks or obstructs normal blood flow through the liver, pressure builds backward into the portal venous system. This localized increase in blood pressure is clinically defined as portal hypertension.\n\nComplications caused by portal hypertension:\n\n• Collateral formation: The development of alternative, bypass blood vessels that the body creates to divert blood away from the high-pressure portal system.\n• Esophageal varices: Enlarged, fragile veins in the lower esophagus that balloon outward because of the backed-up pressure from portal hypertension. These are highly prone to rupturing and causing life-threatening bleeding.\n• Ascites: The accumulation of fluid in the peritoneal cavity of the abdomen, caused by a combination of high portal pressure leaking fluid and low blood albumin levels.","whyWrongChoices":"Alternative options: Ascites, Esophageal varices, Collateral formation"}'::jsonb),
('mc:pertain to the distended blood vessels due to obstruction.:::esophageal varices', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertain to the distended blood vessels due to obstruction.', 'Esophageal varices', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Esophageal varices are clinically defined as abnormally distended, dilated, or swollen blood vessels (varicose veins) located in the mucosal lining of the lower esophagus.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Esophageal varices\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Esophageal varices are clinically defined as abnormally distended, dilated, or swollen blood vessels (varicose veins) located in the mucosal lining of the lower esophagus.\n\nWhen blood flow through the portal vein is obstructed (most commonly due to liver cirrhosis), it forces blood to back up into smaller, fragile secondary veins. Under this intense pressure, these small blood vessels stretch and balloon outward, creating the physical distensions known as varices, which are highly prone to rupturing and causing life-threatening bleeding.\n\n• Portal hypertension: This is the underlying hemodynamic state or condition of high blood pressure within the portal venous system, rather than the name of the distended blood vessels themselves.\n• Ascites: The pathological accumulation of free fluid within the peritoneal cavity of the abdomen, caused by high vascular pressure leaking fluids.\n• Collateral formation: The broad anatomical process or mechanism of opening alternative bypass networks around a blockage, rather than the name of the specific swollen vessels that result from it.","whyWrongChoices":"Alternative options: Portal hypertension, Ascites, Collateral formation"}'::jsonb),
('mc:pertain to the distended blood vessels due to obstruction.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'pertain to the distended blood vessels due to obstruction.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Esophageal varices are clinically defined as abnormally distended, dilated, or swollen blood vessels (varicose veins) located in the mucosal lining of the lower esophagus.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Esophageal varices\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Esophageal varices are clinically defined as abnormally distended, dilated, or swollen blood vessels (varicose veins) located in the mucosal lining of the lower esophagus.\n\nWhen blood flow through the portal vein is obstructed (most commonly due to liver cirrhosis), it forces blood to back up into smaller, fragile secondary veins. Under this intense pressure, these small blood vessels stretch and balloon outward, creating the physical distensions known as varices, which are highly prone to rupturing and causing life-threatening bleeding.\n\n• Portal hypertension: This is the underlying hemodynamic state or condition of high blood pressure within the portal venous system, rather than the name of the distended blood vessels themselves.\n• Ascites: The pathological accumulation of free fluid within the peritoneal cavity of the abdomen, caused by high vascular pressure leaking fluids.\n• Collateral formation: The broad anatomical process or mechanism of opening alternative bypass networks around a blockage, rather than the name of the specific swollen vessels that result from it.","whyWrongChoices":"Alternative options: Portal hypertension, Ascites, Collateral formation"}'::jsonb),
('mc:refers to blood vessels that develop when the blood flow to the liver is obstructed.:::collateral formation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to blood vessels that develop when the blood flow to the liver is obstructed.', 'Collateral formation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When normal blood flow through the liver is obstructed (such as from scarring in liver cirrhosis), pressure spikes within the portal vein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Collateral formation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When normal blood flow through the liver is obstructed (such as from scarring in liver cirrhosis), pressure spikes within the portal vein.\n\nTo adapt to this high pressure, the body automatically creates or opens up alternative, secondary blood vessels. This development of bypass networks to route blood around the blockage and back toward the heart is called collateral formation or collateral circulation.\n\n• Esophageal varices: These are the actual enlarged, swollen veins that develop in the lower esophagus as a direct result of collateral formation. While they are vessels, \"collateral formation\" is the precise term for the overall process of developing these bypass tracts.\n• Ascites: The accumulation of fluid within the peritoneal cavity of the abdomen, caused by high portal pressure and a lack of blood proteins.\n• Hyperammonemia: A dangerous biochemical buildup of ammonia in the blood, which happens when the liver is too damaged to convert ammonia into urea.","whyWrongChoices":"Alternative options: Ascites, Esophageal varices, Hyperammonemia"}'::jsonb),
('mc:refers to blood vessels that develop when the blood flow to the liver is obstructed.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to blood vessels that develop when the blood flow to the liver is obstructed.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When normal blood flow through the liver is obstructed (such as from scarring in liver cirrhosis), pressure spikes within the portal vein.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Collateral formation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When normal blood flow through the liver is obstructed (such as from scarring in liver cirrhosis), pressure spikes within the portal vein.\n\nTo adapt to this high pressure, the body automatically creates or opens up alternative, secondary blood vessels. This development of bypass networks to route blood around the blockage and back toward the heart is called collateral formation or collateral circulation.\n\n• Esophageal varices: These are the actual enlarged, swollen veins that develop in the lower esophagus as a direct result of collateral formation. While they are vessels, \"collateral formation\" is the precise term for the overall process of developing these bypass tracts.\n• Ascites: The accumulation of fluid within the peritoneal cavity of the abdomen, caused by high portal pressure and a lack of blood proteins.\n• Hyperammonemia: A dangerous biochemical buildup of ammonia in the blood, which happens when the liver is too damaged to convert ammonia into urea.","whyWrongChoices":"Alternative options: Ascites, Esophageal varices, Hyperammonemia"}'::jsonb),
('mc:drugs that slow the heart rate and increase strength of cardiac contraction; used in treatment of congestive heart failure (chf) and arrhythmias. digoxin is an example.:::digitalis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'drugs that slow the heart rate and increase strength of cardiac contraction; used in treatment of congestive heart failure (chf) and arrhythmias. digoxin is an example.', 'Digitalis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Digitalis works by reversibly inhibiting the sodium-potassium ATPase pump in myocardial cells. This inhibition directly causes:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Digitalis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Digitalis works by reversibly inhibiting the sodium-potassium ATPase pump in myocardial cells. This inhibition directly causes:\n\t• Increased Contractile Strength (Positive Inotropy): It triggers a rise in intracellular calcium, which heavily strengthens the force of cardiac contractions, helping an enlarged, failing heart pump blood efficiently.\n\t• Slower Heart Rate (Negative Chronotropy): It increases vagal tone and slows electrical conduction through the atrioventricular (AV) node. This safely slows down a rapid heart rate, making it highly effective for treating chronic atrial fibrillation and congestive heart failure (CHF).\n\n• Tissue plasminogen activator (tPA): A thrombolytic \"clot-busting\" agent used in emergencies to dissolve blood clots during an acute ischemic stroke or heart attack; it has no effect on heartbeat strength or rate.\n• Nitroglycerin: A potent vasodilator used to relieve angina pectoris (chest pain) by widening the coronary arteries to improve blood flow, rather than changing the mechanical strength of myocardial contractions.\n• Calcium-channel blockers: These medications relax blood vessels and lower blood pressure. While they can slow down the heart rate, they actually decrease the strength of heart contractions (negative inotrope), which is the exact opposite of what is described.","whyWrongChoices":"Alternative options: Calcium-channel blockers, Nitroglycerin, Tissue plasminogen activator"}'::jsonb),
('mc:drugs that slow the heart rate and increase strength of cardiac contraction; used in treatment of congestive heart failure (chf) and arrhythmias. digoxin is an example.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'drugs that slow the heart rate and increase strength of cardiac contraction; used in treatment of congestive heart failure (chf) and arrhythmias. digoxin is an example.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Digitalis works by reversibly inhibiting the sodium-potassium ATPase pump in myocardial cells. This inhibition directly causes:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Digitalis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Digitalis works by reversibly inhibiting the sodium-potassium ATPase pump in myocardial cells. This inhibition directly causes:\n\t• Increased Contractile Strength (Positive Inotropy): It triggers a rise in intracellular calcium, which heavily strengthens the force of cardiac contractions, helping an enlarged, failing heart pump blood efficiently.\n\t• Slower Heart Rate (Negative Chronotropy): It increases vagal tone and slows electrical conduction through the atrioventricular (AV) node. This safely slows down a rapid heart rate, making it highly effective for treating chronic atrial fibrillation and congestive heart failure (CHF).\n\n• Tissue plasminogen activator (tPA): A thrombolytic \"clot-busting\" agent used in emergencies to dissolve blood clots during an acute ischemic stroke or heart attack; it has no effect on heartbeat strength or rate.\n• Nitroglycerin: A potent vasodilator used to relieve angina pectoris (chest pain) by widening the coronary arteries to improve blood flow, rather than changing the mechanical strength of myocardial contractions.\n• Calcium-channel blockers: These medications relax blood vessels and lower blood pressure. While they can slow down the heart rate, they actually decrease the strength of heart contractions (negative inotrope), which is the exact opposite of what is described.","whyWrongChoices":"Alternative options: Calcium-channel blockers, Nitroglycerin, Tissue plasminogen activator"}'::jsonb),
('mc:due to an imbalance of energy intake and expenditure.:::simple', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'due to an imbalance of energy intake and expenditure.', 'Simple', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Also known as exogenous or primary obesity, simple obesity is caused directly by an imbalance between energy intake (eating too many calories) and energy expenditure (not burning enough calories through physical activity). It is the most common form of weight gain and is not caused by an underlying medical condition, endocrine disorder, or genetic mutation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Simple\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Also known as exogenous or primary obesity, simple obesity is caused directly by an imbalance between energy intake (eating too many calories) and energy expenditure (not burning enough calories through physical activity). It is the most common form of weight gain and is not caused by an underlying medical condition, endocrine disorder, or genetic mutation.\n\n• Genetic: This refers to obesity caused primarily by hereditary factors or specific genetic syndromes (like Prader-Willi syndrome), rather than just a simple lifestyle energy imbalance.\n• Gynoid & Android: These terms describe fat distribution patterns rather than the root cause of the weight gain. Android refers to \"apple-shaped\" abdominal fat accumulation (common in men), while Gynoid refers to \"pear-shaped\" hip and thigh fat accumulation (common in women).","whyWrongChoices":"Alternative options: Android, Gynoid, Genetic"}'::jsonb),
('mc:due to an imbalance of energy intake and expenditure.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'due to an imbalance of energy intake and expenditure.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"• Also known as exogenous or primary obesity, simple obesity is caused directly by an imbalance between energy intake (eating too many calories) and energy expenditure (not burning enough calories through physical activity). It is the most common form of weight gain and is not caused by an underlying medical condition, endocrine disorder, or genetic mutation.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Simple\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"• Also known as exogenous or primary obesity, simple obesity is caused directly by an imbalance between energy intake (eating too many calories) and energy expenditure (not burning enough calories through physical activity). It is the most common form of weight gain and is not caused by an underlying medical condition, endocrine disorder, or genetic mutation.\n\n• Genetic: This refers to obesity caused primarily by hereditary factors or specific genetic syndromes (like Prader-Willi syndrome), rather than just a simple lifestyle energy imbalance.\n• Gynoid & Android: These terms describe fat distribution patterns rather than the root cause of the weight gain. Android refers to \"apple-shaped\" abdominal fat accumulation (common in men), while Gynoid refers to \"pear-shaped\" hip and thigh fat accumulation (common in women).","whyWrongChoices":"Alternative options: Android, Gynoid, Genetic"}'::jsonb),
('mc:when there is weakened movement; lazy bowel:::atonic', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'when there is weakened movement; lazy bowel', 'Atonic', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical nutrition and gastrointestinal frameworks (specifically within Medical Nutrition Therapy (MNT) for GI disorders), atonic constipation is explicitly defined as a condition characterized by weakened movement or a \"lazy bowel\".","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Atonic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical nutrition and gastrointestinal frameworks (specifically within Medical Nutrition Therapy (MNT) for GI disorders), atonic constipation is explicitly defined as a condition characterized by weakened movement or a \"lazy bowel\".\n\nThis occurs when the intestinal walls lose their normal muscular tone (atony) and elasticity, leading to weak peristaltic contractions. Because the rhythmic squeeze is diminished, waste moves too slowly through the large intestine, resulting in slow-transit constipation.\n\nIn dietetics, atonic/lazy bowel is traditionally treated by increasing dietary fiber and fluid intake alongside light physical exercise to naturally stimulate peristalsis and restore tone.\n\n• Spastic: Refers to hypertonicity where the intestinal muscles contract too much or undergo spasms, leading to narrow, small, or ribbon-like stools (often associated with Irritable Bowel Syndrome or IBS). It is managed with a low-residue/high-soluble fiber approach rather than aggressive roughage.\n• Jejunoileostomy: A surgical procedure creating a bypass between the jejunum and the ileum, historically used for severe obesity or treating specific intestinal conditions.\n• Cholecystectomy: The surgical removal of the gallbladder.","whyWrongChoices":"Alternative options: Spastic, Clinical option 3, Clinical option 4"}'::jsonb),
('mc:when there is weakened movement; lazy bowel:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'when there is weakened movement; lazy bowel', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In clinical nutrition and gastrointestinal frameworks (specifically within Medical Nutrition Therapy (MNT) for GI disorders), atonic constipation is explicitly defined as a condition characterized by weakened movement or a \"lazy bowel\".","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Atonic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In clinical nutrition and gastrointestinal frameworks (specifically within Medical Nutrition Therapy (MNT) for GI disorders), atonic constipation is explicitly defined as a condition characterized by weakened movement or a \"lazy bowel\".\n\nThis occurs when the intestinal walls lose their normal muscular tone (atony) and elasticity, leading to weak peristaltic contractions. Because the rhythmic squeeze is diminished, waste moves too slowly through the large intestine, resulting in slow-transit constipation.\n\nIn dietetics, atonic/lazy bowel is traditionally treated by increasing dietary fiber and fluid intake alongside light physical exercise to naturally stimulate peristalsis and restore tone.\n\n• Spastic: Refers to hypertonicity where the intestinal muscles contract too much or undergo spasms, leading to narrow, small, or ribbon-like stools (often associated with Irritable Bowel Syndrome or IBS). It is managed with a low-residue/high-soluble fiber approach rather than aggressive roughage.\n• Jejunoileostomy: A surgical procedure creating a bypass between the jejunum and the ileum, historically used for severe obesity or treating specific intestinal conditions.\n• Cholecystectomy: The surgical removal of the gallbladder.","whyWrongChoices":"Alternative options: Spastic, Clinical option 3, Clinical option 4"}'::jsonb),
('mc:the folllowing are hormones of lactation except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the folllowing are hormones of lactation except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Insulin is associated with glucose metabolism and diabetes.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Insulin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Insulin is associated with glucose metabolism and diabetes.\n\n• Prolactin - stimulates milk synthesis\n• Estrogen - contributes to mammary gland development\n• Oxytocin - triggers the milk ejection (let-down) reflex","whyWrongChoices":"Alternative options: Prolactin, Estrogen, Oxytocin"}'::jsonb),
('mc:refers to drug that dilate coronary blood vessels, thus increasing the flow of oxygenated blood to myocardium; used to relieve or prevent angina pectoris.:::nitroglycerin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to drug that dilate coronary blood vessels, thus increasing the flow of oxygenated blood to myocardium; used to relieve or prevent angina pectoris.', 'Nitroglycerin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nitroglycerin is a potent vasodilator. Once administered, it is converted into nitric oxide, which relaxes the smooth muscle walls of blood vessels. This action dilates the coronary arteries, allowing a rapid surge of oxygenated blood to reach the oxygen-deprived heart muscle (myocardium).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nitroglycerin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nitroglycerin is a potent vasodilator. Once administered, it is converted into nitric oxide, which relaxes the smooth muscle walls of blood vessels. This action dilates the coronary arteries, allowing a rapid surge of oxygenated blood to reach the oxygen-deprived heart muscle (myocardium).\n\nBy widening systemic veins and arteries, it decreases the workload on the heart and reduces preload, making it the classic, first-line drug of choice used to immediately relieve or prevent acute attacks of angina pectoris (chest pain).\n\n• Calcium-channel blockers: While these medications also help manage angina and hypertension by relaxing blood vessels and lowering heart rate, they work by blocking calcium ions from entering muscle cells. They are typically used for long-term maintenance rather than serving as the definitive, rapid-relief anti-anginal agent.\n• Tissue plasminogen activator (tPA): A powerful \"clot-busting\" thrombolytic drug used in emergencies to dissolve blood clots during an active ischemic stroke or myocardial infarction (heart attack). It does not function as a simple coronary vasodilator for angina.\n• Digitalis (Digoxin): A cardiac glycoside used to treat heart failure and certain arrhythmias. It works by increasing the strength or force of heart contractions and slowing the heart rate, rather than directly dilating the coronary vessels to treat angina.","whyWrongChoices":"Alternative options: Calcium-channel blockers, Digitalis, Tissue plasminogen activator"}'::jsonb),
('mc:refers to drug that dilate coronary blood vessels, thus increasing the flow of oxygenated blood to myocardium; used to relieve or prevent angina pectoris.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to drug that dilate coronary blood vessels, thus increasing the flow of oxygenated blood to myocardium; used to relieve or prevent angina pectoris.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nitroglycerin is a potent vasodilator. Once administered, it is converted into nitric oxide, which relaxes the smooth muscle walls of blood vessels. This action dilates the coronary arteries, allowing a rapid surge of oxygenated blood to reach the oxygen-deprived heart muscle (myocardium).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nitroglycerin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nitroglycerin is a potent vasodilator. Once administered, it is converted into nitric oxide, which relaxes the smooth muscle walls of blood vessels. This action dilates the coronary arteries, allowing a rapid surge of oxygenated blood to reach the oxygen-deprived heart muscle (myocardium).\n\nBy widening systemic veins and arteries, it decreases the workload on the heart and reduces preload, making it the classic, first-line drug of choice used to immediately relieve or prevent acute attacks of angina pectoris (chest pain).\n\n• Calcium-channel blockers: While these medications also help manage angina and hypertension by relaxing blood vessels and lowering heart rate, they work by blocking calcium ions from entering muscle cells. They are typically used for long-term maintenance rather than serving as the definitive, rapid-relief anti-anginal agent.\n• Tissue plasminogen activator (tPA): A powerful \"clot-busting\" thrombolytic drug used in emergencies to dissolve blood clots during an active ischemic stroke or myocardial infarction (heart attack). It does not function as a simple coronary vasodilator for angina.\n• Digitalis (Digoxin): A cardiac glycoside used to treat heart failure and certain arrhythmias. It works by increasing the strength or force of heart contractions and slowing the heart rate, rather than directly dilating the coronary vessels to treat angina.","whyWrongChoices":"Alternative options: Calcium-channel blockers, Digitalis, Tissue plasminogen activator"}'::jsonb),
('mc:streptokinase are drugs that are able to dissolve blood clots, which may be blocking coronary arteries.:::tissue plasminogen activator', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'streptokinase are drugs that are able to dissolve blood clots, which may be blocking coronary arteries.', 'Tissue plasminogen activator', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question refers to streptokinase, which belongs to a class of medications called thrombolytic agents or \"clot busters\".","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tissue plasminogen activator\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question refers to streptokinase, which belongs to a class of medications called thrombolytic agents or \"clot busters\".\n\nBoth streptokinase and tissue plasminogen activator (tPA) function by converting plasminogen into plasmin. Plasmin is the primary enzyme responsible for breaking down fibrin networks, effectively dissolving acute blood clots that block the coronary arteries during a myocardial infarction (heart attack).\n\n• Digitalis: A cardiac glycoside that increases the force of heart contractions (positive inotrope) and slows the heart rate, primarily used for heart failure and atrial fibrillation.\n• Nitroglycerin: A powerful vasodilator that relaxes and widens blood vessels to improve blood flow and relieve chest pain (angina), but it cannot dissolve an existing clot.\n• Calcium-channel blockers: Anti-hypertensive and anti-anginal medications that relax blood vessels and lower the heart''s workload by disrupting calcium movement into muscle cells.","whyWrongChoices":"Alternative options: Calcium-channel blockers, Digitalis, Nitroglycerin"}'::jsonb),
('mc:streptokinase are drugs that are able to dissolve blood clots, which may be blocking coronary arteries.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'streptokinase are drugs that are able to dissolve blood clots, which may be blocking coronary arteries.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question refers to streptokinase, which belongs to a class of medications called thrombolytic agents or \"clot busters\".","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tissue plasminogen activator\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question refers to streptokinase, which belongs to a class of medications called thrombolytic agents or \"clot busters\".\n\nBoth streptokinase and tissue plasminogen activator (tPA) function by converting plasminogen into plasmin. Plasmin is the primary enzyme responsible for breaking down fibrin networks, effectively dissolving acute blood clots that block the coronary arteries during a myocardial infarction (heart attack).\n\n• Digitalis: A cardiac glycoside that increases the force of heart contractions (positive inotrope) and slows the heart rate, primarily used for heart failure and atrial fibrillation.\n• Nitroglycerin: A powerful vasodilator that relaxes and widens blood vessels to improve blood flow and relieve chest pain (angina), but it cannot dissolve an existing clot.\n• Calcium-channel blockers: Anti-hypertensive and anti-anginal medications that relax blood vessels and lower the heart''s workload by disrupting calcium movement into muscle cells.","whyWrongChoices":"Alternative options: Calcium-channel blockers, Digitalis, Nitroglycerin"}'::jsonb),
('mc:refers to the failure of the left ventricle to pump effectively; characterized by dyspnea/orthopnea, pulmonary edema, and fatigability.:::congestive heart failure', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the failure of the left ventricle to pump effectively; characterized by dyspnea/orthopnea, pulmonary edema, and fatigability.', 'Congestive Heart Failure', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Congestive Heart Failure (CHF) happens when the heart muscle—specifically the left ventricle—weakens or stiffens and fails to pump blood out to the body effectively.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Congestive Heart Failure\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Congestive Heart Failure (CHF) happens when the heart muscle—specifically the left ventricle—weakens or stiffens and fails to pump blood out to the body effectively.\n\nBecause the left ventricle cannot clear the blood it receives, fluid backs up into the lungs. This creates the classic clinical symptoms listed in the prompt:\n\t• Dyspnea/Orthopnea: Severe shortness of breath, especially when lying down flat (orthopnea), forcing patients to sleep propped up on pillows.\n\t• Pulmonary Edema: Fluid pooling directly inside the air sacs of the lungs.\n\t• Fatigability: Overwhelming fatigue because organs and working muscles are starved of oxygenated blood.\n\n• Coronary Artery Disease: The narrowing or blockage of the arteries that supply blood directly to the heart muscle, usually caused by plaque buildup. While it is a leading cause of heart failure, it is the structural artery block rather than the pump failure itself.\n• Myocardial Infarction: A heart attack. This is an acute, sudden event where blood flow to a section of the heart muscle is completely cut off, causing tissue death.\n• Achlorhydria: A completely unrelated gastrointestinal condition characterized by the total absence of hydrochloric acid in the stomach juices.","whyWrongChoices":"Alternative options: Myocardial Infarction, Coronary Artery Disease, Clinical option 4"}'::jsonb),
('mc:refers to the failure of the left ventricle to pump effectively; characterized by dyspnea/orthopnea, pulmonary edema, and fatigability.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'refers to the failure of the left ventricle to pump effectively; characterized by dyspnea/orthopnea, pulmonary edema, and fatigability.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Congestive Heart Failure (CHF) happens when the heart muscle—specifically the left ventricle—weakens or stiffens and fails to pump blood out to the body effectively.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Congestive Heart Failure\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Congestive Heart Failure (CHF) happens when the heart muscle—specifically the left ventricle—weakens or stiffens and fails to pump blood out to the body effectively.\n\nBecause the left ventricle cannot clear the blood it receives, fluid backs up into the lungs. This creates the classic clinical symptoms listed in the prompt:\n\t• Dyspnea/Orthopnea: Severe shortness of breath, especially when lying down flat (orthopnea), forcing patients to sleep propped up on pillows.\n\t• Pulmonary Edema: Fluid pooling directly inside the air sacs of the lungs.\n\t• Fatigability: Overwhelming fatigue because organs and working muscles are starved of oxygenated blood.\n\n• Coronary Artery Disease: The narrowing or blockage of the arteries that supply blood directly to the heart muscle, usually caused by plaque buildup. While it is a leading cause of heart failure, it is the structural artery block rather than the pump failure itself.\n• Myocardial Infarction: A heart attack. This is an acute, sudden event where blood flow to a section of the heart muscle is completely cut off, causing tissue death.\n• Achlorhydria: A completely unrelated gastrointestinal condition characterized by the total absence of hydrochloric acid in the stomach juices.","whyWrongChoices":"Alternative options: Myocardial Infarction, Coronary Artery Disease, Clinical option 4"}'::jsonb),
('mc:the gradual thickening of the arteries of the walls due to the information of plaques.:::atherosclerosis', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the gradual thickening of the arteries of the walls due to the information of plaques.', 'Atherosclerosis', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Atherosclerosis (derived from the Greek words athere meaning gruel or paste, and sclerosis meaning hardness) is the precise medical term for the gradual thickening, narrowing, and hardening of the arterial walls due to the formation of fibrofatty plaques (atheromas).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Atherosclerosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Atherosclerosis (derived from the Greek words athere meaning gruel or paste, and sclerosis meaning hardness) is the precise medical term for the gradual thickening, narrowing, and hardening of the arterial walls due to the formation of fibrofatty plaques (atheromas).\n\nIt begins when the inner lining of an artery (the endothelium) is damaged by factors like high blood pressure or smoking. This triggers a chronic inflammatory response where low-density lipoproteins (LDL) accumulate, become oxidized, and are swallowed by immune cells to form \"foam cells.\" Over time, this mixture of cholesterol, cellular waste, and scar tissue calcifies into a rigid plaque that restricts blood flow.\n\n• Hypertension: High blood pressure. While it causes chronic mechanical stress that damages vessel walls and drastically accelerates plaque formation, it is a hemodynamic measurement rather than the physical plaque architecture itself.\n• Cerebrovascular accident (CVA): A stroke. This is a severe, acute clinical outcome or event that happens when a blood vessel supplying the brain either ruptures or becomes completely blocked by a piece of plaque that broke free.\n• Coronary heart disease (CHD): A specific structural disease category that refers to the narrowing of the blood vessels feeding the heart muscle. While CHD is almost exclusively caused by atherosclerosis, atherosclerosis is the overarching universal process that can happen in arteries anywhere in the body (such as the brain, legs, or kidneys) [0.1].","whyWrongChoices":"Alternative options: Hypertension, Coronary heart disease, Cerebrovascular accident"}'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:the gradual thickening of the arteries of the walls due to the information of plaques.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the gradual thickening of the arteries of the walls due to the information of plaques.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Atherosclerosis (derived from the Greek words athere meaning gruel or paste, and sclerosis meaning hardness) is the precise medical term for the gradual thickening, narrowing, and hardening of the arterial walls due to the formation of fibrofatty plaques (atheromas).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Atherosclerosis\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Atherosclerosis (derived from the Greek words athere meaning gruel or paste, and sclerosis meaning hardness) is the precise medical term for the gradual thickening, narrowing, and hardening of the arterial walls due to the formation of fibrofatty plaques (atheromas).\n\nIt begins when the inner lining of an artery (the endothelium) is damaged by factors like high blood pressure or smoking. This triggers a chronic inflammatory response where low-density lipoproteins (LDL) accumulate, become oxidized, and are swallowed by immune cells to form \"foam cells.\" Over time, this mixture of cholesterol, cellular waste, and scar tissue calcifies into a rigid plaque that restricts blood flow.\n\n• Hypertension: High blood pressure. While it causes chronic mechanical stress that damages vessel walls and drastically accelerates plaque formation, it is a hemodynamic measurement rather than the physical plaque architecture itself.\n• Cerebrovascular accident (CVA): A stroke. This is a severe, acute clinical outcome or event that happens when a blood vessel supplying the brain either ruptures or becomes completely blocked by a piece of plaque that broke free.\n• Coronary heart disease (CHD): A specific structural disease category that refers to the narrowing of the blood vessels feeding the heart muscle. While CHD is almost exclusively caused by atherosclerosis, atherosclerosis is the overarching universal process that can happen in arteries anywhere in the body (such as the brain, legs, or kidneys) [0.1].","whyWrongChoices":"Alternative options: Hypertension, Coronary heart disease, Cerebrovascular accident"}'::jsonb),
('mc:this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.:::ipc', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.', 'IPC', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"IPC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). \n\n• EWS refers to an Early Warning System, which focuses on early detection of deteriorating conditions. \n• OPT, Operation Timbang, is a child weighing activity, unrelated to food insecurity classification. \n• SFP, Supplementary Feeding Program, is an intervention, not a classification tool.","whyWrongChoices":"Alternative options: EWS, OPT, SFP"}'::jsonb),
('mc:this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this pertains to a set of tools and procedures to classify the nature and severity of food insecurity.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"IPC\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"IPC (Integrated Food Security Phase Classification) is a globally standardized system specifically designed to classify the nature and severity of food insecurity into distinct phases (from minimal to famine). \n\n• EWS refers to an Early Warning System, which focuses on early detection of deteriorating conditions. \n• OPT, Operation Timbang, is a child weighing activity, unrelated to food insecurity classification. \n• SFP, Supplementary Feeding Program, is an intervention, not a classification tool.","whyWrongChoices":"Alternative options: EWS, OPT, SFP"}'::jsonb),
('mc:this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.:::ews', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.', 'EWS', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"EWS\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. \n\nEWS and IPC work together in practice, but EWS is specifically the local, trigger-based detection mechanism.","whyWrongChoices":"Alternative options: IPC, OPT, SFP"}'::jsonb),
('mc:this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this refers to a city or municipal-based nutrition surveillance system for detecting, at an early stage, an impending deterioration of food security situation based on agreed food and nutrition-related indicators and corresponding cut-offs or trigger levels.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"EWS\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is EWS (Early Warning System), which is specifically designed at the LGU level to detect early signs of impending food security deterioration using agreed indicators and trigger levels. \n\nEWS and IPC work together in practice, but EWS is specifically the local, trigger-based detection mechanism.","whyWrongChoices":"Alternative options: IPC, OPT, SFP"}'::jsonb),
('mc:aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.:::pgn', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.', 'PGN', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PGN\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.\n\n• AHMP (Accelerated Hunger-Mitigation Program) is the overarching mother program addressing hunger and food security.\n• IYCF (Infant and Young Child Feeding) represents the specific set of optimal guidelines and target behaviors (like exclusive breastfeeding and appropriate complementary feeding) that the PGN promotes to mothers and caregivers.","whyWrongChoices":"Alternative options: NGF, IYCF, AHMP"}'::jsonb),
('mc:aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'aims to improve the nutrition knowledge, attitudes, and practices of families to increase demand for adequate, nutritious, and safe food.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"PGN\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"PGN (Promote Good Nutrition) is a key component of the Philippines'' Accelerated Hunger-Mitigation Program (AHMP). It is strategically designed to improve the nutrition-related knowledge, attitudes, and behaviors of families to cultivate a sustainable demand for adequate, healthy, and safe food.\n\n• AHMP (Accelerated Hunger-Mitigation Program) is the overarching mother program addressing hunger and food security.\n• IYCF (Infant and Young Child Feeding) represents the specific set of optimal guidelines and target behaviors (like exclusive breastfeeding and appropriate complementary feeding) that the PGN promotes to mothers and caregivers.","whyWrongChoices":"Alternative options: NGF, IYCF, AHMP"}'::jsonb),
('mc:what is the primary purpose of nutrition survey in research?:::to determine the prevelance of specific nutrient deficiencies in a population', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the primary purpose of nutrition survey in research?', 'To determine the prevelance of specific nutrient deficiencies in a population', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To determine the prevelance of specific nutrient deficiencies in a population\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.\n\nChoices A, C, and D describe purposes that a survey-type methodology could theoretically serve, but they are more specialized or unrelated to the core mission of nutrition surveys. Nutrition surveys generate the prevalence data that inform national policy and program planning.","whyWrongChoices":"Alternative options: To assess the effectiveness of a new weight loss drug, To compare the nutritional content of different brands of cereal, To evaluate the impact of a marketing campaign on consumer food choices"}'::jsonb),
('mc:what is the primary purpose of nutrition survey in research?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the primary purpose of nutrition survey in research?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To determine the prevelance of specific nutrient deficiencies in a population\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The best answer is to determine the prevalence of specific nutrient deficiencies in a population, which is the classic, defining purpose of a population-based nutrition survey such as the National Nutrition Survey.\n\nChoices A, C, and D describe purposes that a survey-type methodology could theoretically serve, but they are more specialized or unrelated to the core mission of nutrition surveys. Nutrition surveys generate the prevalence data that inform national policy and program planning.","whyWrongChoices":"Alternative options: To assess the effectiveness of a new weight loss drug, To compare the nutritional content of different brands of cereal, To evaluate the impact of a marketing campaign on consumer food choices"}'::jsonb),
('mc:when was the first nutrition survey released?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'when was the first nutrition survey released?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The first nutrition survey results were released in 1910 during the American Regime, which primarily focused on investigating beriberi and its links to eating polished white rice.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1910\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The first nutrition survey results were released in 1910 during the American Regime, which primarily focused on investigating beriberi and its links to eating polished white rice.","whyWrongChoices":"Alternative options: 1920, 1930, 1940"}'::jsonb),
('mc:which of the following conditions accounts for the most non-communicable disease worldwide?:::cardiovascular disease', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following conditions accounts for the most non-communicable disease worldwide?', 'Cardiovascular disease', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to official global statistics from the World Health Organization (WHO), Non-Communicable Diseases (NCDs) are responsible for approximately 74% of all deaths worldwide.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Cardiovascular disease\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to official global statistics from the World Health Organization (WHO), Non-Communicable Diseases (NCDs) are responsible for approximately 74% of all deaths worldwide.\n\nAmong these conditions, cardiovascular diseases (CVDs) are the absolute leading cause of mortality and morbidity globally:\n• Cardiovascular Diseases (CVDs): Account for the vast majority of NCD deaths, causing roughly 17.9 to 19 million deaths annually (primarily driven by ischemic heart disease and strokes).\n• Cancers: Follow as the second largest group, accounting for around 9 to 10 million deaths each year.\n• Chronic Respiratory Diseases: Account for approximately 3.9 to 4 million annual deaths.\n• Diabetes: Accounts for roughly 1.6 to 2 million deaths annually.\n\nTogether, these four groups make up over 80% of all premature NCD-related mortality worldwide.","whyWrongChoices":"Alternative options: Breast cancer, Diabetes, Respiratory disease"}'::jsonb),
('mc:the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to:::a large majority of individual in a particular age or gender group', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to', 'A large majority of individual in a particular age or gender group', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A large majority of individual in a particular age or gender group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.\n\nEstimated Average Requirement (EAR), which is set at the median requirement covering only half of a group, not the UL. The UL is therefore a ceiling for safe habitual intake and not a recommended target intake.","whyWrongChoices":"Alternative options: Half the individuals in a particular age or gender group, Everyone in a particular age or gender group, None of the above"}'::jsonb),
('mc:the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the tolerable upper intake level (ul) is the largest daily nutrient intake shown to harbor no adverse side effects to', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A large majority of individual in a particular age or gender group\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The reason the Tolerable Upper Intake Level (UL), or Upper Tolerable Limit, applies to a large majority (almost all) of individuals in a specific group but not absolutely everyone, is due to the inherent biological variability in the human population and the conservative methodology used to establish the UL.\n\nEstimated Average Requirement (EAR), which is set at the median requirement covering only half of a group, not the UL. The UL is therefore a ceiling for safe habitual intake and not a recommended target intake.","whyWrongChoices":"Alternative options: Half the individuals in a particular age or gender group, Everyone in a particular age or gender group, None of the above"}'::jsonb),
('mc:based on the acceptable macronutrient distribution ranges (amdr), energy from fat as a percentage of total energy for adults should be within the range?:::15-30%', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'based on the acceptable macronutrient distribution ranges (amdr), energy from fat as a percentage of total energy for adults should be within the range?', '15-30%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct range is 15-30% of total energy based on the Philippine Dietary Reference Intakes (PDRI) AMDR for fat in adults.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"15-30%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct range is 15-30% of total energy based on the Philippine Dietary Reference Intakes (PDRI) AMDR for fat in adults.\n\nCarbohydrate: 55-75%\nProtein: 10-15%\nFat: 15-30%","whyWrongChoices":"Alternative options: <10%, 10-20%, 35-50%"}'::jsonb),
