INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:it is the study of assessment of diet and its relationship to disease etiology in the populations.:::nutritional epidemiology', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is the study of assessment of diet and its relationship to disease etiology in the populations.', 'Nutritional epidemiology', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutritional epidemiology\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.\n\n• \"Food and nutrition research\" is a broader, generic term not specific to disease etiology. \n• \"Food and nutrition epidemiology\" and \"food epidemiology\" are not the standard, recognized terms used in the field.","whyWrongChoices":"Alternative options: Food and nutrition research, Food and nutrition epidemiology, Food epidemiology"}'::jsonb),
('mc:it is the study of assessment of diet and its relationship to disease etiology in the populations.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is the study of assessment of diet and its relationship to disease etiology in the populations.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutritional epidemiology\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutritional epidemiology specifically studies dietary patterns and nutrient intake in relation to disease occurrence at the population level.\n\n• \"Food and nutrition research\" is a broader, generic term not specific to disease etiology. \n• \"Food and nutrition epidemiology\" and \"food epidemiology\" are not the standard, recognized terms used in the field.","whyWrongChoices":"Alternative options: Food and nutrition research, Food and nutrition epidemiology, Food epidemiology"}'::jsonb),
