('mc:which is true about cell growth?:::hyperplasia is characterized by the increase in number of cells through cell division', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is true about cell growth?', 'Hyperplasia is characterized by the increase in number of cells through cell division', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyperplasia is characterized by an increase in the number of cells through cell division. Choice B is false because it describes hypertrophy is actually the increase in the SIZE of existing cells, not their number.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperplasia is characterized by the increase in number of cells through cell division\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyperplasia is characterized by an increase in the number of cells through cell division. Choice B is false because it describes hypertrophy is actually the increase in the SIZE of existing cells, not their number.","whyWrongChoices":"Alternative options: Hypertrophy is characterized by the increase in number of cells through cell division, A and B are both TRUE, A and B are both FALSE"}'::jsonb),
