('mc:psychological eating disorder that is also known as "george and purge":::bulimia nervosa', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'psychological eating disorder that is also known as "george and purge"', 'Bulimia nervosa', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bulimia nervosa - cycles of binging (overeating) followed by compensatory behaviors (e.g., purging, excessive exercise).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Bulimia nervosa\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bulimia nervosa - cycles of binging (overeating) followed by compensatory behaviors (e.g., purging, excessive exercise).\n\n• Anorexia nervosa - restriction leading to dangerously low body weight due to fear of fatness.\n• Binge eating - recurring episodes of uncontrolled eating (binging) without compensatory behaviors.\n• Pica - persistent consumption of non-food items (e.g., dirt, paint, paper).","whyWrongChoices":"Alternative options: Anorexia nervosa, Binge eating, Pica"}'::jsonb),
('mc:which is true about physiologic maturity?:::achieved when full genetic body size is attained', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is true about physiologic maturity?', 'Achieved when full genetic body size is attained', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that physiologic maturity is achieved when full genetic body size (adult stature/proportions) is attained, marking the endpoint of the growth process. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Achieved when full genetic body size is attained\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that physiologic maturity is achieved when full genetic body size (adult stature/proportions) is attained, marking the endpoint of the growth process. \n\nChoice B is incorrect because continuous organ and tissue growth is actually characteristic of the growing, immature state, not of maturity itself, which represents growth''s completion.","whyWrongChoices":"Alternative options: Achieved with continuous organ and tissue growth, All of the above, None of the above"}'::jsonb),
('mc:which is true about physiologic maturity?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is true about physiologic maturity?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that physiologic maturity is achieved when full genetic body size (adult stature/proportions) is attained, marking the endpoint of the growth process. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Achieved when full genetic body size is attained\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that physiologic maturity is achieved when full genetic body size (adult stature/proportions) is attained, marking the endpoint of the growth process. \n\nChoice B is incorrect because continuous organ and tissue growth is actually characteristic of the growing, immature state, not of maturity itself, which represents growth''s completion.","whyWrongChoices":"Alternative options: Achieved with continuous organ and tissue growth, All of the above, None of the above"}'::jsonb),
('mc:it refers to the person''s unique pattern of living::::lifestyle', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it refers to the person''s unique pattern of living:', 'Lifestyle', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lifestyle - Total way of living","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lifestyle\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lifestyle - Total way of living\n\n• Health - state of complete physical, mental, and social well-being\n• Wellness - Active pursuit of optimal health through conscious choice\n• Behavior - Individual actions or reactions","whyWrongChoices":"Alternative options: Health, Wellness, Behavior"}'::jsonb)
