('mc:this theory of ageing attributes aging to chemical and mechanical exhaustion of cells:::wear-and-tear theory', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this theory of ageing attributes aging to chemical and mechanical exhaustion of cells', 'Wear-and-tear theory', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wear-and-tear theory - Mechanical Deterioration","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Wear-and-tear theory\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wear-and-tear theory - Mechanical Deterioration\n\n• Clinker theory - Accumulated Waste\n• Somatic mutation theory - DNA Damage Accumulation\n• Cross-linkage theory - Molecular Rigidity/Stiffening","whyWrongChoices":"Alternative options: Clinker theory, Somatic mutation theory, Cross-linkage theory"}'::jsonb),
