('mc:which country made the first specific commitment on the un decade of action on nutrition?:::brazil', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which country made the first specific commitment on the un decade of action on nutrition?', 'Brazil', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On May 22, 2017, Brazil became the first country to make SMART commitments as part of the United Nations (UN) Decade of Action on Nutrition 2016–2025. Ricardo Barros, Minister of Health of Brazil, made the announcement at the UN in Geneva, on the first day of the Seventieth World Health Assembly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Brazil\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On May 22, 2017, Brazil became the first country to make SMART commitments as part of the United Nations (UN) Decade of Action on Nutrition 2016–2025. Ricardo Barros, Minister of Health of Brazil, made the announcement at the UN in Geneva, on the first day of the Seventieth World Health Assembly.\n\nBrazil’s 3 commitments, to be achieved by 2019, are as follows:\n• Stop the growth in the adult obesity rate (which currently stands at 20.8%)\n• Reduce by at least 30% consumption of sugar-sweetened beverages among adults\n• Increase by at least 17.8% the proportion of adults who regularly eat fruit and vegetables\n\nBrazil outlined specific policy measures it will take to achieve these goals. These include fiscal measures (tax reductions, subsidies) to reduce the price of fresh foods, microcredit loans to family farmers, and cash transfers to poor families so that they can buy fresh produce.\n\nSee reference here: https://www.who.int/news/item/22-05-2017-brazil-first-country-to-make-specific-commitments-in-un-decade-of-action-on-nutrition","whyWrongChoices":"Alternative options: Norway, France, Ecuador"}'::jsonb),
('mc:which country made the first specific commitment on the un decade of action on nutrition?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which country made the first specific commitment on the un decade of action on nutrition?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"On May 22, 2017, Brazil became the first country to make SMART commitments as part of the United Nations (UN) Decade of Action on Nutrition 2016–2025. Ricardo Barros, Minister of Health of Brazil, made the announcement at the UN in Geneva, on the first day of the Seventieth World Health Assembly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Brazil\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"On May 22, 2017, Brazil became the first country to make SMART commitments as part of the United Nations (UN) Decade of Action on Nutrition 2016–2025. Ricardo Barros, Minister of Health of Brazil, made the announcement at the UN in Geneva, on the first day of the Seventieth World Health Assembly.\n\nBrazil’s 3 commitments, to be achieved by 2019, are as follows:\n• Stop the growth in the adult obesity rate (which currently stands at 20.8%)\n• Reduce by at least 30% consumption of sugar-sweetened beverages among adults\n• Increase by at least 17.8% the proportion of adults who regularly eat fruit and vegetables\n\nBrazil outlined specific policy measures it will take to achieve these goals. These include fiscal measures (tax reductions, subsidies) to reduce the price of fresh foods, microcredit loans to family farmers, and cash transfers to poor families so that they can buy fresh produce.\n\nSee reference here: https://www.who.int/news/item/22-05-2017-brazil-first-country-to-make-specific-commitments-in-un-decade-of-action-on-nutrition","whyWrongChoices":"Alternative options: Norway, France, Ecuador"}'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.:::2', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.', '2', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.\n\n• SDG 1: No Poverty - End poverty in all its forms everywhere.\n• SDG 3: Good Health and Well-being - Ensure healthy lives and promote well-being for all at all ages.\n• SDG 4: Quality Education - Ensure inclusive and equitable quality education and promote lifelong learning opportunities for all.","whyWrongChoices":"Alternative options: 1, 3, 4"}'::jsonb),
('mc:this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this sustainable development goal affirms to end hunger, achieve food security and improved nutrition, and promote sustainable agriculture.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"SDG 2: Zero Hunger aims to end hunger, achieve food security, and promote sustainable agriculture.\n\n• SDG 1: No Poverty - End poverty in all its forms everywhere.\n• SDG 3: Good Health and Well-being - Ensure healthy lives and promote well-being for all at all ages.\n• SDG 4: Quality Education - Ensure inclusive and equitable quality education and promote lifelong learning opportunities for all.","whyWrongChoices":"Alternative options: 1, 3, 4"}'::jsonb),
('mc:in what year was the first international conference on nutrition held?:::1992', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in what year was the first international conference on nutrition held?', '1992', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1992\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.\n\nThe International Conference on Nutrition was held in Rome, from 5 to 11 December 1992. The Conference was not seen as an end in itself but rather as a step in the continuing process to strengthen commitment and the action necessary to prevent and alleviate nutrition problems. Enthusiasm has been generated in many countries for the implementation of plans which must now begin. Through increased awareness of the extent and seriousness of nutrition- and diet-related problems, the process leading to the Conference resulted in the public and private sectors'' increased willingness to work together to tackle them.","whyWrongChoices":"Alternative options: 1996, 2002, 2014"}'::jsonb),
('mc:in what year was the first international conference on nutrition held?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in what year was the first international conference on nutrition held?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1992\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In early 1989, at the fifteenth session of the Subcommittee on Nutrition of the United Nations Administrative Committee on Coordination (ACC/SCN), an international conference on nutrition was proposed. Subsequently the Executive Board, at its eighty-fifth session in January 1990, endorsed the proposal that WHO and FAO should jointly convene such a conference in close collaboration with other United Nations agencies and with concerned multilateral, bilateral and nongovernmental organizations.\n\nThe International Conference on Nutrition was held in Rome, from 5 to 11 December 1992. The Conference was not seen as an end in itself but rather as a step in the continuing process to strengthen commitment and the action necessary to prevent and alleviate nutrition problems. Enthusiasm has been generated in many countries for the implementation of plans which must now begin. Through increased awareness of the extent and seriousness of nutrition- and diet-related problems, the process leading to the Conference resulted in the public and private sectors'' increased willingness to work together to tackle them.","whyWrongChoices":"Alternative options: 1996, 2002, 2014"}'::jsonb),
('mc:the 2025 global nutrition targets include reduction in childhood::::wasting', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the 2025 global nutrition targets include reduction in childhood:', 'Wasting', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wasting is one of the six original WHO Global Nutrition Targets for 2025. The six original 2025 targets cover stunting, wasting, overweight, anemia, low birth weight, and exclusive breastfeeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Wasting\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wasting is one of the six original WHO Global Nutrition Targets for 2025. The six original 2025 targets cover stunting, wasting, overweight, anemia, low birth weight, and exclusive breastfeeding.\n\n• Target 1: 40% reduction in the number of children under five years of age who are stunted\n• Target 2: 50% reduction in anaemia in women of reproductive age.\n• Target 3: 30% reduction in low birth weight\n• Target 6: Reduce and maintain wasting in children under five years of age to less than 5%.\n\nMeanwhile, targets 4 and 5, which are close to being met in 2025, have been revised to raise ambition:\n• Target 4: Childhood overweight: The ambition of the target has been strengthened from the original target of maintaining the 2012 prevalence to reducing overweight among children under five to below 5% by 2030.\n• Target 5: Exclusive breastfeeding: To accelerate progress, the target has been increased from the original up to 50% of infants exclusively breastfed during the first six months of life by 2025 to up to 60% by 2030.\n\nSee reference here: https://www.who.int/teams/nutrition-and-food-safety/global-targets-2030","whyWrongChoices":"Alternative options: Anemia, Iodine Deficiency, Underweight"}'::jsonb),
('mc:under the mandatory food fortification program, refined sugar is fortified with::::vit a', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'under the mandatory food fortification program, refined sugar is fortified with:', 'Vit A', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"See RA 8976 (Philippine Food Fortification Act of 2000):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vit A\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"See RA 8976 (Philippine Food Fortification Act of 2000):\n\nA. Vitamin A – oil, sugar\nB. Iron – rice\nC. Iodine - salt\nD. Vitamin A and iron - wheat flour","whyWrongChoices":"Alternative options: Iron, Iodine, Vit A and Iron"}'::jsonb),
('mc:the 2025 global nutrition targets include reduction in childhood::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the 2025 global nutrition targets include reduction in childhood:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Wasting is one of the six original WHO Global Nutrition Targets for 2025. The six original 2025 targets cover stunting, wasting, overweight, anemia, low birth weight, and exclusive breastfeeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Wasting\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Wasting is one of the six original WHO Global Nutrition Targets for 2025. The six original 2025 targets cover stunting, wasting, overweight, anemia, low birth weight, and exclusive breastfeeding.\n\n• Target 1: 40% reduction in the number of children under five years of age who are stunted\n• Target 2: 50% reduction in anaemia in women of reproductive age.\n• Target 3: 30% reduction in low birth weight\n• Target 6: Reduce and maintain wasting in children under five years of age to less than 5%.\n\nMeanwhile, targets 4 and 5, which are close to being met in 2025, have been revised to raise ambition:\n• Target 4: Childhood overweight: The ambition of the target has been strengthened from the original target of maintaining the 2012 prevalence to reducing overweight among children under five to below 5% by 2030.\n• Target 5: Exclusive breastfeeding: To accelerate progress, the target has been increased from the original up to 50% of infants exclusively breastfed during the first six months of life by 2025 to up to 60% by 2030.\n\nSee reference here: https://www.who.int/teams/nutrition-and-food-safety/global-targets-2030","whyWrongChoices":"Alternative options: Anemia, Iodine Deficiency, Underweight"}'::jsonb),
('mc:a high sodium consumption equivalent to grams salt/day contributes to high blood pressure.:::5', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a high sodium consumption equivalent to grams salt/day contributes to high blood pressure.', '5', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"WHO recommends a reduction in sodium intake to reduce blood pressure and risk of cardiovascular disease, stroke and coronary heart disease in adults (strong recommendation). WHO recommends a reduction to <2 g/day sodium (5 g/day salt)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"WHO recommends a reduction in sodium intake to reduce blood pressure and risk of cardiovascular disease, stroke and coronary heart disease in adults (strong recommendation). WHO recommends a reduction to <2 g/day sodium (5 g/day salt)\nin adults (strong recommendation).\n\nSee reference here:\nGuideline: Sodium intake for adults and children (2012): https://iris.who.int/server/api/core/bitstreams/d0f9feb5-ed78-44d1-9e06-533a93352012/content","whyWrongChoices":"Alternative options: 2, 6.5"}'::jsonb),
('mc:a high sodium consumption equivalent to grams salt/day contributes to high blood pressure.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a high sodium consumption equivalent to grams salt/day contributes to high blood pressure.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"WHO recommends a reduction in sodium intake to reduce blood pressure and risk of cardiovascular disease, stroke and coronary heart disease in adults (strong recommendation). WHO recommends a reduction to <2 g/day sodium (5 g/day salt)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"WHO recommends a reduction in sodium intake to reduce blood pressure and risk of cardiovascular disease, stroke and coronary heart disease in adults (strong recommendation). WHO recommends a reduction to <2 g/day sodium (5 g/day salt)\nin adults (strong recommendation).\n\nSee reference here:\nGuideline: Sodium intake for adults and children (2012): https://iris.who.int/server/api/core/bitstreams/d0f9feb5-ed78-44d1-9e06-533a93352012/content","whyWrongChoices":"Alternative options: 2, 6.5"}'::jsonb),
('mc:newborns weighing 2000 g or less at birth should be provided with kangaroo mother care as possible.:::close to continuous', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'newborns weighing 2000 g or less at birth should be provided with kangaroo mother care as possible.', 'Close to continuous', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The WHO publication Kangaroo Mother Care: A Practical Guide recommends initiation of short KMC sessions when the baby starts to recover, even if the baby still requires medical treatment such as intravenous fluids or oxygen. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Close to continuous\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The WHO publication Kangaroo Mother Care: A Practical Guide recommends initiation of short KMC sessions when the baby starts to recover, even if the baby still requires medical treatment such as intravenous fluids or oxygen. \n\nIt also recommends that continuous KMC should be initiated only after the baby is stable, meaning that the baby must be breathing spontaneously without additional oxygen. For the routine care of newborns weighing 2.0 kg or less at birth, the “WHO recommendations on interventions to improve preterm birth outcomes” recommend KMC, which should be initiated in health-care facilities as soon as the newborns are clinically stable. \n\nThese babies should be provided with as close to continuous KMC as possible. Currently, there is no recommendation for KMC for unstable neonates weighing less than 2.0 kg at birth.\n\nSee references here:\n\nKangaroo mother care: Implementation strategy for scale-up adaptable to different country contexts (WHO, 2023): https://iris.who.int/server/api/core/bitstreams/71660bad-f029-4d9e-a2a4-63d8c59a8ce1/content\n\nWHO Immediate KMC Study Group (2020). Impact of continuous Kangaroo Mother Care initiated immediately after birth (iKMC) on survival of newborns with birth weight between 1.0 to < 1.8 kg: study protocol for a randomized controlled trial. Trials, 21(1), 280. https://doi.org/10.1186/s13063-020-4101-1","whyWrongChoices":"Alternative options: Continuous, Close, Continuous to close"}'::jsonb),
('mc:newborns weighing 2000 g or less at birth should be provided with kangaroo mother care as possible.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'newborns weighing 2000 g or less at birth should be provided with kangaroo mother care as possible.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The WHO publication Kangaroo Mother Care: A Practical Guide recommends initiation of short KMC sessions when the baby starts to recover, even if the baby still requires medical treatment such as intravenous fluids or oxygen. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Close to continuous\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The WHO publication Kangaroo Mother Care: A Practical Guide recommends initiation of short KMC sessions when the baby starts to recover, even if the baby still requires medical treatment such as intravenous fluids or oxygen. \n\nIt also recommends that continuous KMC should be initiated only after the baby is stable, meaning that the baby must be breathing spontaneously without additional oxygen. For the routine care of newborns weighing 2.0 kg or less at birth, the “WHO recommendations on interventions to improve preterm birth outcomes” recommend KMC, which should be initiated in health-care facilities as soon as the newborns are clinically stable. \n\nThese babies should be provided with as close to continuous KMC as possible. Currently, there is no recommendation for KMC for unstable neonates weighing less than 2.0 kg at birth.\n\nSee references here:\n\nKangaroo mother care: Implementation strategy for scale-up adaptable to different country contexts (WHO, 2023): https://iris.who.int/server/api/core/bitstreams/71660bad-f029-4d9e-a2a4-63d8c59a8ce1/content\n\nWHO Immediate KMC Study Group (2020). Impact of continuous Kangaroo Mother Care initiated immediately after birth (iKMC) on survival of newborns with birth weight between 1.0 to < 1.8 kg: study protocol for a randomized controlled trial. Trials, 21(1), 280. https://doi.org/10.1186/s13063-020-4101-1","whyWrongChoices":"Alternative options: Continuous, Close, Continuous to close"}'::jsonb),
('mc:what is stated in the 5th nutritional guidelines for filipinos:::consume milk, milk product, and other calcium-rich foods, such as small fish and shellfish, every day for healthy bones and teeth', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is stated in the 5th nutritional guidelines for filipinos', 'Consume milk, milk product, and other calcium-rich foods, such as small fish and shellfish, every day for healthy bones and teeth', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Formulated by the Food and Nutrition Research Institute (FNRI-DOST), the 10 messages (popularly popularized as the 10 Kumainments) are chronologically ordered as follows:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Consume milk, milk product, and other calcium-rich foods, such as small fish and shellfish, every day for healthy bones and teeth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Formulated by the Food and Nutrition Research Institute (FNRI-DOST), the 10 messages (popularly popularized as the 10 Kumainments) are chronologically ordered as follows:\n\n1. 1st Guideline: Eat a variety of foods everyday to get the nutrients needed by the body.\n2. 2nd Guideline: Breastfeed infants exclusively from birth up to 6 months, then give appropriate complementary foods.\n3. 3rd Guideline: Eat more vegetables and fruits every day.\n4. 4th Guideline: Consume fish, lean meat, poultry, egg, dried beans or nuts daily.\n5. 5th Guideline: Consume milk, milk products, and other calcium-rich foods.\n6. 6th Guideline: Consume safe foods and water to prevent diarrhea.\n7. 7th Guideline: Use iodized salt to prevent Iodine Deficiency Disorders.\n8. 8th Guideline: Limit intake of salty, fried, fatty, and sugar-rich foods.\n9. 9th Guideline: Attain normal body weight through proper diet and moderate physical activity.\n10. 10th Guideline: Be physically active, make healthy food choices, manage stress, avoid alcoholic beverages, and do not smoke.","whyWrongChoices":"Alternative options: Use iodized salt to prevent Iodine Deficiency Disorders, Eat more vegetables and fruits every day to get essential vitamins, minerals, and fiber for regulation of body processes., Limit intake of salty, fried, fatty, and sugar-rich foods to prevent cardiovascular disease"}'::jsonb),
('mc:what is stated in the 5th nutritional guidelines for filipinos:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is stated in the 5th nutritional guidelines for filipinos', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Formulated by the Food and Nutrition Research Institute (FNRI-DOST), the 10 messages (popularly popularized as the 10 Kumainments) are chronologically ordered as follows:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Consume milk, milk product, and other calcium-rich foods, such as small fish and shellfish, every day for healthy bones and teeth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Formulated by the Food and Nutrition Research Institute (FNRI-DOST), the 10 messages (popularly popularized as the 10 Kumainments) are chronologically ordered as follows:\n\n1. 1st Guideline: Eat a variety of foods everyday to get the nutrients needed by the body.\n2. 2nd Guideline: Breastfeed infants exclusively from birth up to 6 months, then give appropriate complementary foods.\n3. 3rd Guideline: Eat more vegetables and fruits every day.\n4. 4th Guideline: Consume fish, lean meat, poultry, egg, dried beans or nuts daily.\n5. 5th Guideline: Consume milk, milk products, and other calcium-rich foods.\n6. 6th Guideline: Consume safe foods and water to prevent diarrhea.\n7. 7th Guideline: Use iodized salt to prevent Iodine Deficiency Disorders.\n8. 8th Guideline: Limit intake of salty, fried, fatty, and sugar-rich foods.\n9. 9th Guideline: Attain normal body weight through proper diet and moderate physical activity.\n10. 10th Guideline: Be physically active, make healthy food choices, manage stress, avoid alcoholic beverages, and do not smoke.","whyWrongChoices":"Alternative options: Use iodized salt to prevent Iodine Deficiency Disorders, Eat more vegetables and fruits every day to get essential vitamins, minerals, and fiber for regulation of body processes., Limit intake of salty, fried, fatty, and sugar-rich foods to prevent cardiovascular disease"}'::jsonb),
('mc:the current nutritional guildelines for filipinos was approved and adopted in what year?:::2012', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the current nutritional guildelines for filipinos was approved and adopted in what year?', '2012', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Official name: Nutritional guidelines for Filipinos (Filipino: Mga Gabay sa Wastong Nutrisyon Para sa Pilipino).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2012\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Official name: Nutritional guidelines for Filipinos (Filipino: Mga Gabay sa Wastong Nutrisyon Para sa Pilipino).\n\nPublication year: The Philippines published its first dietary guidelines in 1990. They were revised in 2000 and again in 2012.\n\nProcess and stakeholders\nThe Food and Nutrition Research Institute – Department of Science and Technology (FNRI-DOST) initiated and chaired the inter-agency and multidisciplinary Technical Working Group on the 2012 guidelines.\n\nThe guidelines were approved by the National Nutrition Council. The communication and dissemination is spearheaded by the National Nutrition Council and endorsed by various government agencies.\n\nSee reference here: https://www.fao.org/nutrition/education/food-dietary-guidelines/regions/countries/philippines/en/","whyWrongChoices":"Alternative options: 2000, 2006, 2018"}'::jsonb),
('mc:the current nutritional guildelines for filipinos was approved and adopted in what year?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the current nutritional guildelines for filipinos was approved and adopted in what year?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Official name: Nutritional guidelines for Filipinos (Filipino: Mga Gabay sa Wastong Nutrisyon Para sa Pilipino).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2012\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Official name: Nutritional guidelines for Filipinos (Filipino: Mga Gabay sa Wastong Nutrisyon Para sa Pilipino).\n\nPublication year: The Philippines published its first dietary guidelines in 1990. They were revised in 2000 and again in 2012.\n\nProcess and stakeholders\nThe Food and Nutrition Research Institute – Department of Science and Technology (FNRI-DOST) initiated and chaired the inter-agency and multidisciplinary Technical Working Group on the 2012 guidelines.\n\nThe guidelines were approved by the National Nutrition Council. The communication and dissemination is spearheaded by the National Nutrition Council and endorsed by various government agencies.\n\nSee reference here: https://www.fao.org/nutrition/education/food-dietary-guidelines/regions/countries/philippines/en/","whyWrongChoices":"Alternative options: 2000, 2006, 2018"}'::jsonb),
('mc:under the mandatory food fortification program, rice is fortified with:::iron', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'under the mandatory food fortification program, rice is fortified with', 'Iron', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"See RA 8976 (Philippine Food Fortification Act of 2000):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"See RA 8976 (Philippine Food Fortification Act of 2000):\n\nA. Vitamin A - oil\nB. Iron – rice\nC. Iodine - salt\nD. Vitamin A and iron - wheat flour","whyWrongChoices":"Alternative options: Vit A, Iodine, Vit A and Iron"}'::jsonb),
('mc:which age group is the target in operation timbang plus:::0-59 months', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which age group is the target in operation timbang plus', '0-59 months', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Operation Timbang (OPT) Plus is the regular child growth assessment of all children 0-59 months old conducted annually in all barangays in the country to identify and locate families with malnourished preschool children and determine the overall nutrition situation in the area. It also involves planning, follow-up, and data quality check.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0-59 months\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Operation Timbang (OPT) Plus is the regular child growth assessment of all children 0-59 months old conducted annually in all barangays in the country to identify and locate families with malnourished preschool children and determine the overall nutrition situation in the area. It also involves planning, follow-up, and data quality check.\n\nSee reference here: https://nnc.gov.ph/plans-and-programs/philippine-nutrition-surveillance-system-pnss/operation-timbang-plus-otp/","whyWrongChoices":"Alternative options: 0-11 months, 0-23 months, 0-35 months"}'::jsonb),
('mc:which age group is the target in operation timbang plus:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which age group is the target in operation timbang plus', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Operation Timbang (OPT) Plus is the regular child growth assessment of all children 0-59 months old conducted annually in all barangays in the country to identify and locate families with malnourished preschool children and determine the overall nutrition situation in the area. It also involves planning, follow-up, and data quality check.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0-59 months\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Operation Timbang (OPT) Plus is the regular child growth assessment of all children 0-59 months old conducted annually in all barangays in the country to identify and locate families with malnourished preschool children and determine the overall nutrition situation in the area. It also involves planning, follow-up, and data quality check.\n\nSee reference here: https://nnc.gov.ph/plans-and-programs/philippine-nutrition-surveillance-system-pnss/operation-timbang-plus-otp/","whyWrongChoices":"Alternative options: 0-11 months, 0-23 months, 0-35 months"}'::jsonb),
('mc:who is not a member of the operation timbang plus team?:::mayor', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'who is not a member of the operation timbang plus team?', 'Mayor', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is the Mayor, who serves in a broader local governance and oversight role as chair of the local nutrition committee. BHW, BNS, and DCW are all members of the OPT Plus team.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Mayor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is the Mayor, who serves in a broader local governance and oversight role as chair of the local nutrition committee. BHW, BNS, and DCW are all members of the OPT Plus team.\n\nSee reference here: https://nnc.gov.ph/plans-and-programs/philippine-nutrition-surveillance-system-pnss/operation-timbang-plus-otp/","whyWrongChoices":"Alternative options: Barangay health worker, Barangay nutrition scholar, Day care worker"}'::jsonb),
('mc:who is not a member of the operation timbang plus team?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'who is not a member of the operation timbang plus team?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is the Mayor, who serves in a broader local governance and oversight role as chair of the local nutrition committee. BHW, BNS, and DCW are all members of the OPT Plus team.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Mayor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is the Mayor, who serves in a broader local governance and oversight role as chair of the local nutrition committee. BHW, BNS, and DCW are all members of the OPT Plus team.\n\nSee reference here: https://nnc.gov.ph/plans-and-programs/philippine-nutrition-surveillance-system-pnss/operation-timbang-plus-otp/","whyWrongChoices":"Alternative options: Barangay health worker, Barangay nutrition scholar, Day care worker"}'::jsonb),
('mc:this program involves the provision of pharmaceutical preparations of vitamins and minerals.:::micronutrient supplementation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this program involves the provision of pharmaceutical preparations of vitamins and minerals.', 'Micronutrient Supplementation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Micronutrient supplementation, defined specifically as providing vitamins and minerals in pharmaceutical form (such as capsules, syrups, or tablets) directly to individuals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micronutrient Supplementation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Micronutrient supplementation, defined specifically as providing vitamins and minerals in pharmaceutical form (such as capsules, syrups, or tablets) directly to individuals.\n\nFood fortification instead adds nutrients to commonly consumed foods during processing. Livelihood assistance and food production are indirect, food-security-oriented interventions.","whyWrongChoices":"Alternative options: Food Fortification, Livelihood Assistance, Food Production"}'::jsonb),
('mc:an instrument used to measure skinfold thickness:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an instrument used to measure skinfold thickness', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Lange caliper is a specific instrument designed and validated for measuring skinfold thickness at standardized body sites to estimate subcutaneous body fat. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lange\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Lange caliper is a specific instrument designed and validated for measuring skinfold thickness at standardized body sites to estimate subcutaneous body fat. \n\nBiceps, subscapular, and midaxillary are names of specific skinfold measurement sites on the body.","whyWrongChoices":"Alternative options: Biceps, Subscapular, Midaxillary"}'::jsonb),
('mc:this program involves the provision of pharmaceutical preparations of vitamins and minerals.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this program involves the provision of pharmaceutical preparations of vitamins and minerals.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Micronutrient supplementation, defined specifically as providing vitamins and minerals in pharmaceutical form (such as capsules, syrups, or tablets) directly to individuals.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micronutrient Supplementation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Micronutrient supplementation, defined specifically as providing vitamins and minerals in pharmaceutical form (such as capsules, syrups, or tablets) directly to individuals.\n\nFood fortification instead adds nutrients to commonly consumed foods during processing. Livelihood assistance and food production are indirect, food-security-oriented interventions.","whyWrongChoices":"Alternative options: Food Fortification, Livelihood Assistance, Food Production"}'::jsonb),
('mc:this relates to the process by which the nutritional quality of food crops is improved through agronomic practices, conventional plant breeding, or modern biotechnology.:::biofortification', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this relates to the process by which the nutritional quality of food crops is improved through agronomic practices, conventional plant breeding, or modern biotechnology.', 'Biofortification', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is biofortification, specifically defined by improving the nutrient content of crops themselves through agricultural or breeding methods (such as Golden Rice enriched with vitamin A precursor).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biofortification\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is biofortification, specifically defined by improving the nutrient content of crops themselves through agricultural or breeding methods (such as Golden Rice enriched with vitamin A precursor).\n\nSee reference here: https://www.who.int/tools/elena/bbc/biofortification","whyWrongChoices":"Alternative options: Mandatory fortification, Voluntary fortification, Food fortification"}'::jsonb),
('mc:this relates to the process by which the nutritional quality of food crops is improved through agronomic practices, conventional plant breeding, or modern biotechnology.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this relates to the process by which the nutritional quality of food crops is improved through agronomic practices, conventional plant breeding, or modern biotechnology.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is biofortification, specifically defined by improving the nutrient content of crops themselves through agricultural or breeding methods (such as Golden Rice enriched with vitamin A precursor).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Biofortification\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is biofortification, specifically defined by improving the nutrient content of crops themselves through agricultural or breeding methods (such as Golden Rice enriched with vitamin A precursor).\n\nSee reference here: https://www.who.int/tools/elena/bbc/biofortification","whyWrongChoices":"Alternative options: Mandatory fortification, Voluntary fortification, Food fortification"}'::jsonb),
('mc:is an information-sharing type of activity that provides nutrition information to 10-12 participating mothers who are seated in a circular position:::pabasa sa nutrisyon', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'is an information-sharing type of activity that provides nutrition information to 10-12 participating mothers who are seated in a circular position', 'Pabasa sa nutrisyon', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pabasa sa Nutrisyon (PSN) is an information-sharing nutrition education initiative developed by the Nutrition Center of the Philippines (NCP). It is traditionally formatted as a community course where small groups of around 10 to 12 target mothers or caregivers sit in a circular arrangement to comfortably read, learn from standard nutritional guidelines, and share personal child-rearing experiences.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pabasa sa nutrisyon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pabasa sa Nutrisyon (PSN) is an information-sharing nutrition education initiative developed by the Nutrition Center of the Philippines (NCP). It is traditionally formatted as a community course where small groups of around 10 to 12 target mothers or caregivers sit in a circular arrangement to comfortably read, learn from standard nutritional guidelines, and share personal child-rearing experiences.\n\n• Nutribus - 1980’s Nutrition Education using a bus.\n• TCP - Teacher Child Parent Approach - The Teacher-Child-Parent approach to nutrition is a collaborative strategy where teachers, parents, and other community members work together to promote and improve children''s nutrition through consistent education and support\n• Kumare - (Kalusugan para Umunlad si Mare) is a maternal health program designed to improve the delivery of much-needed iron supplements to pregnant women. This approach increases the number of prenatal visits, the number of iron tablets consumed, and improved hemoglobin levels. The intervention is anchored on training and re-orientation of health workers by giving them more responsibility for the mothers in their catchment area.","whyWrongChoices":"Alternative options: Nutribus, TCP, Kumare"}'::jsonb),
('mc:is an information-sharing type of activity that provides nutrition information to 10-12 participating mothers who are seated in a circular position:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'is an information-sharing type of activity that provides nutrition information to 10-12 participating mothers who are seated in a circular position', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pabasa sa Nutrisyon (PSN) is an information-sharing nutrition education initiative developed by the Nutrition Center of the Philippines (NCP). It is traditionally formatted as a community course where small groups of around 10 to 12 target mothers or caregivers sit in a circular arrangement to comfortably read, learn from standard nutritional guidelines, and share personal child-rearing experiences.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pabasa sa nutrisyon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pabasa sa Nutrisyon (PSN) is an information-sharing nutrition education initiative developed by the Nutrition Center of the Philippines (NCP). It is traditionally formatted as a community course where small groups of around 10 to 12 target mothers or caregivers sit in a circular arrangement to comfortably read, learn from standard nutritional guidelines, and share personal child-rearing experiences.\n\n• Nutribus - 1980’s Nutrition Education using a bus.\n• TCP - Teacher Child Parent Approach - The Teacher-Child-Parent approach to nutrition is a collaborative strategy where teachers, parents, and other community members work together to promote and improve children''s nutrition through consistent education and support\n• Kumare - (Kalusugan para Umunlad si Mare) is a maternal health program designed to improve the delivery of much-needed iron supplements to pregnant women. This approach increases the number of prenatal visits, the number of iron tablets consumed, and improved hemoglobin levels. The intervention is anchored on training and re-orientation of health workers by giving them more responsibility for the mothers in their catchment area.","whyWrongChoices":"Alternative options: Nutribus, TCP, Kumare"}'::jsonb),
('mc:which is a livelihood assistance program?:::lingap sa mahirap', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is a livelihood assistance program?', 'Lingap sa mahirap', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lingap sa Mahirap: A historical, comprehensive poverty alleviation fund introduced during the Estrada administration targeting the 100 poorest families in every province and city to deliver integrated social welfare packages.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lingap sa mahirap\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lingap sa Mahirap: A historical, comprehensive poverty alleviation fund introduced during the Estrada administration targeting the 100 poorest families in every province and city to deliver integrated social welfare packages.\n\n• Tindahan Natin Program (TNP): This is a national government initiative implemented by the Department of Social Welfare and Development (DSWD). It serves as a livelihood assistance and job generation project alongside working as a targeted food price subsidy. It provides micro-financing and starter capital for low-income individuals, barangay councils, or community groups to set up small grocery stores (tindahan) that sell low-priced, quality food items like NFA rice and noodles.\n• Ginintuang Masaganang Ani: An overarching agricultural modernization program run by the Department of Agriculture (DA) focused on boosting crop productivity, farm technology, and national food sufficiency.\n• Sustansya para sa Masa: A multi-sectoral national movement launched to combat malnutrition through public food fortification strategies, such as adding Vitamin A to localized products.","whyWrongChoices":"Alternative options: Ginintuang masaganang ani, Sustansya para sa masa, Tindahan natin"}'::jsonb),
('mc:which is a livelihood assistance program?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is a livelihood assistance program?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lingap sa Mahirap: A historical, comprehensive poverty alleviation fund introduced during the Estrada administration targeting the 100 poorest families in every province and city to deliver integrated social welfare packages.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lingap sa mahirap\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lingap sa Mahirap: A historical, comprehensive poverty alleviation fund introduced during the Estrada administration targeting the 100 poorest families in every province and city to deliver integrated social welfare packages.\n\n• Tindahan Natin Program (TNP): This is a national government initiative implemented by the Department of Social Welfare and Development (DSWD). It serves as a livelihood assistance and job generation project alongside working as a targeted food price subsidy. It provides micro-financing and starter capital for low-income individuals, barangay councils, or community groups to set up small grocery stores (tindahan) that sell low-priced, quality food items like NFA rice and noodles.\n• Ginintuang Masaganang Ani: An overarching agricultural modernization program run by the Department of Agriculture (DA) focused on boosting crop productivity, farm technology, and national food sufficiency.\n• Sustansya para sa Masa: A multi-sectoral national movement launched to combat malnutrition through public food fortification strategies, such as adding Vitamin A to localized products.","whyWrongChoices":"Alternative options: Ginintuang masaganang ani, Sustansya para sa masa, Tindahan natin"}'::jsonb),
('mc:what is/are the priority foods source/s during the early emergency period?:::water and calories', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is/are the priority foods source/s during the early emergency period?', 'Water and Calories', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Water and calories are the two most immediately life-sustaining priorities in the very early phase of an emergency response. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Water and Calories\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Water and calories are the two most immediately life-sustaining priorities in the very early phase of an emergency response. \n\n• Water alone is insufficient because caloric/energy needs are also urgently critical for survival. \n• Adding protein and further adding fat reflect priorities that become important slightly later, as the emergency response matures beyond the immediate survival phase into more complete dietary support.","whyWrongChoices":"Alternative options: Water, Water, Calories, and Protein, Water, Calores, Protein, and Fat"}'::jsonb),
('mc:what is/are the priority foods source/s during the early emergency period?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is/are the priority foods source/s during the early emergency period?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Water and calories are the two most immediately life-sustaining priorities in the very early phase of an emergency response. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Water and Calories\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Water and calories are the two most immediately life-sustaining priorities in the very early phase of an emergency response. \n\n• Water alone is insufficient because caloric/energy needs are also urgently critical for survival. \n• Adding protein and further adding fat reflect priorities that become important slightly later, as the emergency response matures beyond the immediate survival phase into more complete dietary support.","whyWrongChoices":"Alternative options: Water, Water, Calories, and Protein, Water, Calores, Protein, and Fat"}'::jsonb),
('mc:which cmam component treats children with sam with poor appetite or medical complications?:::inpatient care', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which cmam component treats children with sam with poor appetite or medical complications?', 'Inpatient care', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Inpatient care, which is specifically designated within the Community-based Management of Acute Malnutrition (CMAM) framework for children with severe acute malnutrition (SAM) who present with poor appetite (failed appetite test) or medical complications requiring more intensive, facility-based treatment. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inpatient care\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Inpatient care, which is specifically designated within the Community-based Management of Acute Malnutrition (CMAM) framework for children with severe acute malnutrition (SAM) who present with poor appetite (failed appetite test) or medical complications requiring more intensive, facility-based treatment. \n\n• Outpatient care is instead used for SAM children who pass the appetite test and have no medical complications, allowing home-based management with ready-to-use therapeutic food.\n• Home care and community care are not standard, formally defined CMAM components matching this specific clinical criterion.","whyWrongChoices":"Alternative options: Outpatient care, Home care, Community care"}'::jsonb),
('mc:which cmam component treats children with sam with poor appetite or medical complications?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which cmam component treats children with sam with poor appetite or medical complications?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Inpatient care, which is specifically designated within the Community-based Management of Acute Malnutrition (CMAM) framework for children with severe acute malnutrition (SAM) who present with poor appetite (failed appetite test) or medical complications requiring more intensive, facility-based treatment. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inpatient care\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Inpatient care, which is specifically designated within the Community-based Management of Acute Malnutrition (CMAM) framework for children with severe acute malnutrition (SAM) who present with poor appetite (failed appetite test) or medical complications requiring more intensive, facility-based treatment. \n\n• Outpatient care is instead used for SAM children who pass the appetite test and have no medical complications, allowing home-based management with ready-to-use therapeutic food.\n• Home care and community care are not standard, formally defined CMAM components matching this specific clinical criterion.","whyWrongChoices":"Alternative options: Outpatient care, Home care, Community care"}'::jsonb),
('mc:characterized mainly by a program already prepared by a group external to a community or environment. it may also mean top-down approach which is characterized mainly by the formulation of a plan at a higher level (e.g. national level), for implementation at a lower level (e.g. municipality or barangay).:::pre-determined planning', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'characterized mainly by a program already prepared by a group external to a community or environment. it may also mean top-down approach which is characterized mainly by the formulation of a plan at a higher level (e.g. national level), for implementation at a lower level (e.g. municipality or barangay).', 'Pre-Determined planning', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pre-determined planning is defined as a top-down approach where plans are formulated at a higher level (e.g., national) for implementation at a lower level (e.g., barangay), without the community''s initial input into design. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pre-Determined planning\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pre-determined planning is defined as a top-down approach where plans are formulated at a higher level (e.g., national) for implementation at a lower level (e.g., barangay), without the community''s initial input into design. \n\n• Self-determined planning instead involves the community itself formulating its own plan. \n• Joint planning involves collaboration between external and community stakeholders together. \n• Strategic planning refers to a broader planning methodology focused on long-term goal-setting.","whyWrongChoices":"Alternative options: Self-Determined planning, Joint planning, Strategic planning"}'::jsonb),
('mc:characterized mainly by a program already prepared by a group external to a community or environment. it may also mean top-down approach which is characterized mainly by the formulation of a plan at a higher level (e.g. national level), for implementation at a lower level (e.g. municipality or barangay).:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'characterized mainly by a program already prepared by a group external to a community or environment. it may also mean top-down approach which is characterized mainly by the formulation of a plan at a higher level (e.g. national level), for implementation at a lower level (e.g. municipality or barangay).', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Pre-determined planning is defined as a top-down approach where plans are formulated at a higher level (e.g., national) for implementation at a lower level (e.g., barangay), without the community''s initial input into design. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pre-Determined planning\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Pre-determined planning is defined as a top-down approach where plans are formulated at a higher level (e.g., national) for implementation at a lower level (e.g., barangay), without the community''s initial input into design. \n\n• Self-determined planning instead involves the community itself formulating its own plan. \n• Joint planning involves collaboration between external and community stakeholders together. \n• Strategic planning refers to a broader planning methodology focused on long-term goal-setting.","whyWrongChoices":"Alternative options: Self-Determined planning, Joint planning, Strategic planning"}'::jsonb),
('mc:the following are characteristics of nutrition-oriented development planning except::::malnutrition is merely a problem of food consumption and availability', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are characteristics of nutrition-oriented development planning except:', 'Malnutrition is merely a problem of food consumption and availability', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition-oriented development planning explicitly recognizes malnutrition as a complex, multi-causal problem, not one reducible to just food consumption/availability alone. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Malnutrition is merely a problem of food consumption and availability\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition-oriented development planning explicitly recognizes malnutrition as a complex, multi-causal problem, not one reducible to just food consumption/availability alone. \n\nNutrition being included as an objective integrated into development planning, diagnostic analysis used to identify causes, and nutrition actions applied across local/national and sectoral plans are all genuine, defining characteristics of this planning approach.","whyWrongChoices":"Alternative options: Nutrition is included as an objective and integrated into development planning, Diagnostic analysis is used in identifying cause of malnutrition, Nutrition actions are applied in local and national levels; and in sectoral development plans"}'::jsonb),
('mc:the aim of work design is to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the aim of work design is to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Work design aims to develop jobs and methods that improve productivity and employee satisfaction while supporting efficient, safe work.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"increase productivity and employee satisfaction\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Work design aims to develop jobs and methods that improve productivity and employee satisfaction while supporting efficient, safe work.","whyWrongChoices":"Alternative options: provide efficient and effective work methods, provide safe and healthy work environment, design a staff of fit people"}'::jsonb),
('mc:the following are characteristics of nutrition-oriented development planning except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are characteristics of nutrition-oriented development planning except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition-oriented development planning explicitly recognizes malnutrition as a complex, multi-causal problem, not one reducible to just food consumption/availability alone. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Malnutrition is merely a problem of food consumption and availability\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition-oriented development planning explicitly recognizes malnutrition as a complex, multi-causal problem, not one reducible to just food consumption/availability alone. \n\nNutrition being included as an objective integrated into development planning, diagnostic analysis used to identify causes, and nutrition actions applied across local/national and sectoral plans are all genuine, defining characteristics of this planning approach.","whyWrongChoices":"Alternative options: Nutrition is included as an objective and integrated into development planning, Diagnostic analysis is used in identifying cause of malnutrition, Nutrition actions are applied in local and national levels; and in sectoral development plans"}'::jsonb),
('mc:mechanism for planning, implementing, monitoring, evaluating, and coordinating the local plans of action for nutrition at the province, city/municipality, and barangay levels.:::local nutrition committees', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'mechanism for planning, implementing, monitoring, evaluating, and coordinating the local plans of action for nutrition at the province, city/municipality, and barangay levels.', 'Local Nutrition Committees', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Local Nutrition Committees (LNCs) serve as multi-function coordinating role across all local government levels in the Philippines, chaired by the respective local chief executive, and the basic functional unit of the nutrition program implementation and management.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Local Nutrition Committees\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Local Nutrition Committees (LNCs) serve as multi-function coordinating role across all local government levels in the Philippines, chaired by the respective local chief executive, and the basic functional unit of the nutrition program implementation and management.\n\nSee more here: https://nnc.gov.ph/mindanao-region/lnc-the-basic-functional-unit-of-the-nutrition-program/","whyWrongChoices":"Alternative options: Local Nutrition Action Officers, Local Development Coordinators, Local Development Planning Team"}'::jsonb),
('mc:mechanism for planning, implementing, monitoring, evaluating, and coordinating the local plans of action for nutrition at the province, city/municipality, and barangay levels.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'mechanism for planning, implementing, monitoring, evaluating, and coordinating the local plans of action for nutrition at the province, city/municipality, and barangay levels.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Local Nutrition Committees (LNCs) serve as multi-function coordinating role across all local government levels in the Philippines, chaired by the respective local chief executive, and the basic functional unit of the nutrition program implementation and management.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Local Nutrition Committees\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Local Nutrition Committees (LNCs) serve as multi-function coordinating role across all local government levels in the Philippines, chaired by the respective local chief executive, and the basic functional unit of the nutrition program implementation and management.\n\nSee more here: https://nnc.gov.ph/mindanao-region/lnc-the-basic-functional-unit-of-the-nutrition-program/","whyWrongChoices":"Alternative options: Local Nutrition Action Officers, Local Development Coordinators, Local Development Planning Team"}'::jsonb),
('mc:local nutrition committees are chaired by the following local chief executives, except::::congressmen', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'local nutrition committees are chaired by the following local chief executives, except:', 'Congressmen', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Congressmen are national legislative officials, not local chief executives, and therefore do not chair Local Nutrition Committees. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Congressmen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Congressmen are national legislative officials, not local chief executives, and therefore do not chair Local Nutrition Committees. \n\nBarangay Captains, Mayors, and Governors are all local chief executives who chair LNCs at their respective barangay, city/municipal, and provincial levels.","whyWrongChoices":"Alternative options: Barangay Captains, Mayors, Governors"}'::jsonb),
('mc:local nutrition committees are chaired by the following local chief executives, except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'local nutrition committees are chaired by the following local chief executives, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Congressmen are national legislative officials, not local chief executives, and therefore do not chair Local Nutrition Committees. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Congressmen\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Congressmen are national legislative officials, not local chief executives, and therefore do not chair Local Nutrition Committees. \n\nBarangay Captains, Mayors, and Governors are all local chief executives who chair LNCs at their respective barangay, city/municipal, and provincial levels.","whyWrongChoices":"Alternative options: Barangay Captains, Mayors, Governors"}'::jsonb),
('mc:local nutrition action plans (lnap) serves as the mechanism to achieve nutrition goals at the city/municipal/provincial level. it should be harmonized in the local development system and plans, except::::environmental impact assessment', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'local nutrition action plans (lnap) serves as the mechanism to achieve nutrition goals at the city/municipal/provincial level. it should be harmonized in the local development system and plans, except:', 'Environmental Impact Assessment', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Environmental Impact Assessment is a project-specific environmental review process, not one of the standard local development planning documents that the Local Nutrition Action Plan (LNAP) is meant to be harmonized with. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Environmental Impact Assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Environmental Impact Assessment is a project-specific environmental review process, not one of the standard local development planning documents that the Local Nutrition Action Plan (LNAP) is meant to be harmonized with. \n\nThe Comprehensive Land Use Plan, Executive Legislative Agenda, and Comprehensive Development Plan are all standard local government planning documents that the LNAP should align with to ensure nutrition is mainstreamed into broader development planning and budgeting processes.","whyWrongChoices":"Alternative options: Comprehensive Land Use Plan, Executive Legislative Agenda, Comprehensive Development Plan"}'::jsonb),
('mc:local nutrition action plans (lnap) serves as the mechanism to achieve nutrition goals at the city/municipal/provincial level. it should be harmonized in the local development system and plans, except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'local nutrition action plans (lnap) serves as the mechanism to achieve nutrition goals at the city/municipal/provincial level. it should be harmonized in the local development system and plans, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Environmental Impact Assessment is a project-specific environmental review process, not one of the standard local development planning documents that the Local Nutrition Action Plan (LNAP) is meant to be harmonized with. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Environmental Impact Assessment\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Environmental Impact Assessment is a project-specific environmental review process, not one of the standard local development planning documents that the Local Nutrition Action Plan (LNAP) is meant to be harmonized with. \n\nThe Comprehensive Land Use Plan, Executive Legislative Agenda, and Comprehensive Development Plan are all standard local government planning documents that the LNAP should align with to ensure nutrition is mainstreamed into broader development planning and budgeting processes.","whyWrongChoices":"Alternative options: Comprehensive Land Use Plan, Executive Legislative Agenda, Comprehensive Development Plan"}'::jsonb),
('mc:focal persons for nutrition at the local levels are::::bns, cnao, mnao, pnao', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'focal persons for nutrition at the local levels are:', 'BNS, CNAO, MNAO, PNAO', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Regional nutrition focal points/officers serve national/sub-national levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"BNS, CNAO, MNAO, PNAO\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Regional nutrition focal points/officers serve national/sub-national levels.\n\n• BNS, CNAO, MNAO, PNAO, RNAO - national level\n• BNS, CNAO, MNAO, PNAO, RNPC - national level\n• BNS, CNPC, MNPC, PNPC, RNPC - national level","whyWrongChoices":"Alternative options: BNS, CNAO, MNAO, PNAO, RNAO, BNS, CNAO, MNAO, PNAO, RNPC, BNS, CPNC, MNPC, PNPC, RNPC"}'::jsonb),
('mc:focal persons for nutrition at the local levels are::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'focal persons for nutrition at the local levels are:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Regional nutrition focal points/officers serve national/sub-national levels.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"BNS, CNAO, MNAO, PNAO\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Regional nutrition focal points/officers serve national/sub-national levels.\n\n• BNS, CNAO, MNAO, PNAO, RNAO - national level\n• BNS, CNAO, MNAO, PNAO, RNPC - national level\n• BNS, CNPC, MNPC, PNPC, RNPC - national level","whyWrongChoices":"Alternative options: BNS, CNAO, MNAO, PNAO, RNAO, BNS, CNAO, MNAO, PNAO, RNPC, BNS, CPNC, MNPC, PNPC, RNPC"}'::jsonb),
('mc:a method of delivering goods and/or services to a selected group of individuals or households rather than to every individual or household in the population.:::targeting', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a method of delivering goods and/or services to a selected group of individuals or households rather than to every individual or household in the population.', 'Targeting', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Targeting is defined as directing program benefits to a specifically selected subgroup rather than universally to the entire population. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Targeting\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Targeting is defined as directing program benefits to a specifically selected subgroup rather than universally to the entire population. \n\n• Prioritizing of beneficiaries is a related but broader concept describing the ranking of need, not the delivery mechanism. \n• Sampling refers to a research/survey selection method, not a program service delivery approach. \n• Identification and selection of clients is part of the targeting process but does not capture the full definition of the delivery method as precisely as \"targeting\" does.","whyWrongChoices":"Alternative options: Prioritizing of beneficiaries, Sampling, Identification and selection of clients"}'::jsonb),
('mc:a method of delivering goods and/or services to a selected group of individuals or households rather than to every individual or household in the population.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a method of delivering goods and/or services to a selected group of individuals or households rather than to every individual or household in the population.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Targeting is defined as directing program benefits to a specifically selected subgroup rather than universally to the entire population. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Targeting\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Targeting is defined as directing program benefits to a specifically selected subgroup rather than universally to the entire population. \n\n• Prioritizing of beneficiaries is a related but broader concept describing the ranking of need, not the delivery mechanism. \n• Sampling refers to a research/survey selection method, not a program service delivery approach. \n• Identification and selection of clients is part of the targeting process but does not capture the full definition of the delivery method as precisely as \"targeting\" does.","whyWrongChoices":"Alternative options: Prioritizing of beneficiaries, Sampling, Identification and selection of clients"}'::jsonb),
('mc:depends on decision-making structures at the community level to allocate program goods or services effectively according to the criteria as defined in the program objectives.:::community-based', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'depends on decision-making structures at the community level to allocate program goods or services effectively according to the criteria as defined in the program objectives.', 'Community-based', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Community-based uses local knowledge and consensus (e.g., councils) to select beneficiaries.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Community-based\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Community-based uses local knowledge and consensus (e.g., councils) to select beneficiaries.\n\n• Administrative - uses official records and pre-determined criteria (e.g., income data, public registries).\n• Self-targeting - uses program design (e.g., low-quality food, hard labor requirement) to make the benefit unattractive","whyWrongChoices":"Alternative options: Administrative, Self-targeting, Market-based"}'::jsonb),
('mc:depends on decision-making structures at the community level to allocate program goods or services effectively according to the criteria as defined in the program objectives.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'depends on decision-making structures at the community level to allocate program goods or services effectively according to the criteria as defined in the program objectives.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Community-based uses local knowledge and consensus (e.g., councils) to select beneficiaries.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Community-based\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Community-based uses local knowledge and consensus (e.g., councils) to select beneficiaries.\n\n• Administrative - uses official records and pre-determined criteria (e.g., income data, public registries).\n• Self-targeting - uses program design (e.g., low-quality food, hard labor requirement) to make the benefit unattractive","whyWrongChoices":"Alternative options: Administrative, Self-targeting, Market-based"}'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.:::monitoring', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.', 'Monitoring', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Monitoring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.\n\n• Systematic Assessment of Progress (SAP) - structured, periodic check to see if short-term goals are being met and whether the project logic remains sound\n• Evaluation - determining relevance, effectiveness, impact, and efficiency of the project, often periodic or end-of-cycle\n• Sustainability - ensuring benefits continue after the program''s funding or external support ends","whyWrongChoices":"Alternative options: Systematic Assessment of Progress, Evaluation, Sustainability"}'::jsonb),
('mc:it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is the regular and periodical follow-up of the implementation of planned activities and progress to determine whether steps in the strategy are followed and whether program objectives by phase or activity are attained as planned.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Monitoring\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Monitoring is tracking progress and resource use against plans, usually ongoing and internal.\n\n• Systematic Assessment of Progress (SAP) - structured, periodic check to see if short-term goals are being met and whether the project logic remains sound\n• Evaluation - determining relevance, effectiveness, impact, and efficiency of the project, often periodic or end-of-cycle\n• Sustainability - ensuring benefits continue after the program''s funding or external support ends","whyWrongChoices":"Alternative options: Systematic Assessment of Progress, Evaluation, Sustainability"}'::jsonb),
('mc:information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives:::indicators', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives', 'Indicators', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Indicators\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.\n\n• Data - raw, unorganized facts and figures\n• Records - stored, organized sets of data about a specific entity\n• Criteria - standards or principles used to judge, classify, or make a decision (e.g., age, income level).","whyWrongChoices":"Alternative options: Data, Records, Criteria"}'::jsonb),
('mc:information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'information which is used to measure changes which occur during course of program it allows one to monitor the progress of the program or it is a measure of progress towards meeting a program''s objectives', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Indicators\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Indicators are specific, measurable values that show the status or progress toward a desired result or goal.\n\n• Data - raw, unorganized facts and figures\n• Records - stored, organized sets of data about a specific entity\n• Criteria - standards or principles used to judge, classify, or make a decision (e.g., age, income level).","whyWrongChoices":"Alternative options: Data, Records, Criteria"}'::jsonb),
('mc:it refers to the changes in the condition of the target population which generally reflect the primary objectives of the project or program, e.g. percent improvement in the prevalence of stunting in the municipality.:::impact indicator', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it refers to the changes in the condition of the target population which generally reflect the primary objectives of the project or program, e.g. percent improvement in the prevalence of stunting in the municipality.', 'Impact indicator', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Impact indicator - measures long-term, ultimate changes in well-being or the environment (e.g., reduced mortality rates, national poverty reduction)","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Impact indicator\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Impact indicator - measures long-term, ultimate changes in well-being or the environment (e.g., reduced mortality rates, national poverty reduction)\n\n• Input indicator - measures resources put into a program (e.g., funds spent, staff hired)\n• Output indicator - measures direct, tangible results of program activities (e.g., training sessions held, meals served)\n• Outcome indicator - measures changes in behavior, knowledge, or condition achieved by the target group (e.g., improved hygiene practices, increased enrollment)","whyWrongChoices":"Alternative options: Input indicator, Output indicator, Outcome indicator"}'::jsonb),
