('mc:it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.:::process evaluation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.', 'Process evaluation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Process evaluation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).\n\n• Ex-ante evaluation - assessing potential before program starts (feasibility, relevance).\n• Ex-post evaluation - assessing actual results/impact after program ends (overall success).\n• Result evaluation - assessing what the program achieved (outcomes, effects, and impact).","whyWrongChoices":"Alternative options: Ex-ante evaluation, Ex-post evaluation, Result evaluation"}'::jsonb),
('mc:it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it shows how inputs or resources invested in the project are transformed through a series of sequential processes into outputs; helpful in monitoring ongoing projects or activities.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Process evaluation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Process evaluation - assessing how the program was implemented and managed (efficiency, quality).\n\n• Ex-ante evaluation - assessing potential before program starts (feasibility, relevance).\n• Ex-post evaluation - assessing actual results/impact after program ends (overall success).\n• Result evaluation - assessing what the program achieved (outcomes, effects, and impact).","whyWrongChoices":"Alternative options: Ex-ante evaluation, Ex-post evaluation, Result evaluation"}'::jsonb),
('mc:in process evaluation, the following questions will be addressed, except::::what will be the result of this project?', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in process evaluation, the following questions will be addressed, except:', 'What will be the result of this project?', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The question \"what will be the result of this project?\" belongs to result evaluation, which focuses on outcomes and impact, not process evaluation, which focuses on implementation quality and efficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"What will be the result of this project?\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The question \"what will be the result of this project?\" belongs to result evaluation, which focuses on outcomes and impact, not process evaluation, which focuses on implementation quality and efficiency.","whyWrongChoices":"Alternative options: Are we doing our job well?, What can we be improved upon in the project?, Are we spending resources properly?"}'::jsonb),
