('mc:interventions that address the immediate causes of malnutrition.:::nutrition-specific interventions', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'interventions that address the immediate causes of malnutrition.', 'Nutrition-Specific Interventions', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition-specific interventions address the immediate, direct causes of malnutrition at the individual level (e.g., micronutrient supplementation, breastfeeding promotion, treatment of acute malnutrition).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition-Specific Interventions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition-specific interventions address the immediate, direct causes of malnutrition at the individual level (e.g., micronutrient supplementation, breastfeeding promotion, treatment of acute malnutrition).\n\n• Nutrition-sensitive interventions instead address the underlying causes of malnutrition, such as food security, health services access, and caregiving practices, operating at a different causal level. \n• \"Nutrition and Development Interventions\" and \"Nutrition-in-Development Interventions\" are not standard, recognized terms in this classification framework.","whyWrongChoices":"Alternative options: Nutrition-Sensitive Interventions, Nutrition and Development Interventions, Nutrition-in-Development Interventions"}'::jsonb),
('mc:a measure of years in perfect health lost::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a measure of years in perfect health lost:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"DALY - Disability-Adjusted Life Year (Burden of Disease): Measures the total healthy life years lost (YLL + YLD).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"DALY\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"DALY - Disability-Adjusted Life Year (Burden of Disease): Measures the total healthy life years lost (YLL + YLD).\n\n• YLL - Years of Life Lost (Mortality): Measures the number of years lost due to premature death.\n• YLD - Years Lived with Disability (Morbidity): Measures the number of years lived in less than full health due to illness or injury.\n• QALY - Quality-Adjusted Life Year (Health Economics): Measures the value of a year of life adjusted by its quality or utility.","whyWrongChoices":"Alternative options: YLL, YLD, QALY"}'::jsonb),
('mc:interventions that address the immediate causes of malnutrition.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'interventions that address the immediate causes of malnutrition.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nutrition-specific interventions address the immediate, direct causes of malnutrition at the individual level (e.g., micronutrient supplementation, breastfeeding promotion, treatment of acute malnutrition).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nutrition-Specific Interventions\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nutrition-specific interventions address the immediate, direct causes of malnutrition at the individual level (e.g., micronutrient supplementation, breastfeeding promotion, treatment of acute malnutrition).\n\n• Nutrition-sensitive interventions instead address the underlying causes of malnutrition, such as food security, health services access, and caregiving practices, operating at a different causal level. \n• \"Nutrition and Development Interventions\" and \"Nutrition-in-Development Interventions\" are not standard, recognized terms in this classification framework.","whyWrongChoices":"Alternative options: Nutrition-Sensitive Interventions, Nutrition and Development Interventions, Nutrition-in-Development Interventions"}'::jsonb),
('mc:in 1976, letter of instruction 441 directed the department of local government and community development (now called dilg) to establish in every region, province, city, municipality to implement nutrition action plans.:::functional nutrition committees', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in 1976, letter of instruction 441 directed the department of local government and community development (now called dilg) to establish in every region, province, city, municipality to implement nutrition action plans.', 'Functional nutrition committees', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Functional nutrition committees, which LOI 441 specifically mandated be established at every administrative level to implement nutrition action plans, laying early institutional groundwork for what would later become the Local Nutrition Committees.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Functional nutrition committees\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Functional nutrition committees, which LOI 441 specifically mandated be established at every administrative level to implement nutrition action plans, laying early institutional groundwork for what would later become the Local Nutrition Committees.","whyWrongChoices":"Alternative options: Functional nutrition councils, Functional nutrition coordinating system, Functional nutrition management system"}'::jsonb),
