INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:which group of laws is related to each other: i. ra 10862 - pd 2862 - ra 6760 ii. eo 51 - ra 7600 - a.o. no. 2007-0026 iii. eo 94 - eo 128 - eo 352 iv. pd 491 - eo 234 - a.o. 88 - eo 472 v. a.o. no. 2019-0033 - a.o. no. 2016-0020 vi. ra 8976 - ra 8172 - department memorandum no. 2012-0113 vii. a.o. #2015-0055 - a.o. #2010-00015 - a.o. #2009-0025 - a.o. #2007-0045 - a.o. #2005-0014:::all of the above', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which group of laws is related to each other: i. ra 10862 - pd 2862 - ra 6760 ii. eo 51 - ra 7600 - a.o. no. 2007-0026 iii. eo 94 - eo 128 - eo 352 iv. pd 491 - eo 234 - a.o. 88 - eo 472 v. a.o. no. 2019-0033 - a.o. no. 2016-0020 vi. ra 8976 - ra 8172 - department memorandum no. 2012-0113 vii. a.o. #2015-0055 - a.o. #2010-00015 - a.o. #2009-0025 - a.o. #2007-0045 - a.o. #2005-0014', 'All of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"I. RA 10862 – PD 2862 – RA 6760 - RND laws","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"I. RA 10862 – PD 2862 – RA 6760 - RND laws\nII. EO 51 (1987) - RA 7600 (1992) - A.O. No. 2007-0026 - Breastfeeding laws\nIII. EO 94 (1947) - EO 128 (1987) - EO 352 (1996) - FNRI\nIV. PD 491 – EO 234 (1987) – AO 88 (1988) - EO 472 (1996) - NNC\nV. A.O. No. 2019-0033 - A.O. No. 2016-0020 - NCP\nVI. RA 8976 – RA 8172 - Department Memorandum No. 2012-0113 - Fortification\nVII. AO # 2015-0055 - AO # 2010-00015 - AO # 2009-0025 - AO # 2007-0045 – AO # 2005-0014 - Maternal and Child Health","whyWrongChoices":"Alternative options: I, III, VII, II, IV, VI, None of the above"}'::jsonb),
('mc:which group of laws is related to each other: i. ra 10862 - pd 2862 - ra 6760 ii. eo 51 - ra 7600 - a.o. no. 2007-0026 iii. eo 94 - eo 128 - eo 352 iv. pd 491 - eo 234 - a.o. 88 - eo 472 v. a.o. no. 2019-0033 - a.o. no. 2016-0020 vi. ra 8976 - ra 8172 - department memorandum no. 2012-0113 vii. a.o. #2015-0055 - a.o. #2010-00015 - a.o. #2009-0025 - a.o. #2007-0045 - a.o. #2005-0014:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which group of laws is related to each other: i. ra 10862 - pd 2862 - ra 6760 ii. eo 51 - ra 7600 - a.o. no. 2007-0026 iii. eo 94 - eo 128 - eo 352 iv. pd 491 - eo 234 - a.o. 88 - eo 472 v. a.o. no. 2019-0033 - a.o. no. 2016-0020 vi. ra 8976 - ra 8172 - department memorandum no. 2012-0113 vii. a.o. #2015-0055 - a.o. #2010-00015 - a.o. #2009-0025 - a.o. #2007-0045 - a.o. #2005-0014', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"I. RA 10862 – PD 2862 – RA 6760 - RND laws","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"All of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"I. RA 10862 – PD 2862 – RA 6760 - RND laws\nII. EO 51 (1987) - RA 7600 (1992) - A.O. No. 2007-0026 - Breastfeeding laws\nIII. EO 94 (1947) - EO 128 (1987) - EO 352 (1996) - FNRI\nIV. PD 491 – EO 234 (1987) – AO 88 (1988) - EO 472 (1996) - NNC\nV. A.O. No. 2019-0033 - A.O. No. 2016-0020 - NCP\nVI. RA 8976 – RA 8172 - Department Memorandum No. 2012-0113 - Fortification\nVII. AO # 2015-0055 - AO # 2010-00015 - AO # 2009-0025 - AO # 2007-0045 – AO # 2005-0014 - Maternal and Child Health","whyWrongChoices":"Alternative options: I, III, VII, II, IV, VI, None of the above"}'::jsonb),
('mc:a community health center provides comprehensive services including primary care, dental care, and a public health nutritionist. a patient with recently diagnosed pre-diabetes is referred by their primary care physician to the nutritionist for a consultation. in the scenario, what type of healthcare delivery model does this best represent, and what is the primary benefit for the patient?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a community health center provides comprehensive services including primary care, dental care, and a public health nutritionist. a patient with recently diagnosed pre-diabetes is referred by their primary care physician to the nutritionist for a consultation. in the scenario, what type of healthcare delivery model does this best represent, and what is the primary benefit for the patient?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that this represents an Integrated Healthcare System, whose primary benefit is coordinated care and streamlined communication between the physician and nutritionist within the same facility/system. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Model: Integrated Healthcare System. Benefit: Coordinated care and communication between the physician and nutritionist are streamlined.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that this represents an Integrated Healthcare System, whose primary benefit is coordinated care and streamlined communication between the physician and nutritionist within the same facility/system. \n\n• Fee-for-service describes a payment model emphasizing provider choice, unrelated to the coordinated, in-house referral pathway described. \n• Specialized healthcare system would emphasize focused expert care in one narrow area, not the coordinated, multi-service nature of the scenario. \n• Direct primary care describes a flat-fee payment model for physician access, unrelated to the multidisciplinary, coordinated referral pattern described.","whyWrongChoices":"Alternative options: Model: Fee-for-Service. Benefit: The patient has a wide choice of providers., Model: Specialized Healthcare System. Benefit: The patient receives highly focused care from an expert in one specific area., Model: Direct Primary Care. Benefit: The patient pays a flat monthly fee for unlimited access to the physician."}'::jsonb),
('mc:a public health nutritionist is invited to participate in a hospital-based team that manages the care of patients recently discharged from a cardia unit. the team includes a cardiologist, a registered nurse, a physical therapist, and a social worker. what term best described this type of collaborative effort, and what is its main objective?:::term: interdisciplinary team. objective: to provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals.', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a public health nutritionist is invited to participate in a hospital-based team that manages the care of patients recently discharged from a cardia unit. the team includes a cardiologist, a registered nurse, a physical therapist, and a social worker. what term best described this type of collaborative effort, and what is its main objective?', 'Term: Interdisciplinary Team. Objective: To provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals.', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that this is an Interdisciplinary Team, whose objective is to provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals, integrating their different disciplinary approaches into a coherent, unified methodology.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Term: Interdisciplinary Team. Objective: To provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that this is an Interdisciplinary Team, whose objective is to provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals, integrating their different disciplinary approaches into a coherent, unified methodology.","whyWrongChoices":"Alternative options: Term: Multidisciplinary Team. Objective: To provide comprehensive, coordinated care by having different professionals work independently on different aspects of the patient''s recovery., Term: Ad Hoc Team. Objective: To address a specific, short-term patient need, such as a single consultation, before the patient''s discharge., Term: Transdisciplinary Team. Objective: To cross-train team members so they can perform tasks outside of their primary professional roles to increase efficiency."}'::jsonb),
('mc:a public health nutritionist is invited to participate in a hospital-based team that manages the care of patients recently discharged from a cardia unit. the team includes a cardiologist, a registered nurse, a physical therapist, and a social worker. what term best described this type of collaborative effort, and what is its main objective?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a public health nutritionist is invited to participate in a hospital-based team that manages the care of patients recently discharged from a cardia unit. the team includes a cardiologist, a registered nurse, a physical therapist, and a social worker. what term best described this type of collaborative effort, and what is its main objective?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that this is an Interdisciplinary Team, whose objective is to provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals, integrating their different disciplinary approaches into a coherent, unified methodology.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Term: Interdisciplinary Team. Objective: To provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals.\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that this is an Interdisciplinary Team, whose objective is to provide a holistic, integrated care plan by having team members work together and communicate about shared patient goals, integrating their different disciplinary approaches into a coherent, unified methodology.","whyWrongChoices":"Alternative options: Term: Multidisciplinary Team. Objective: To provide comprehensive, coordinated care by having different professionals work independently on different aspects of the patient''s recovery., Term: Ad Hoc Team. Objective: To address a specific, short-term patient need, such as a single consultation, before the patient''s discharge., Term: Transdisciplinary Team. Objective: To cross-train team members so they can perform tasks outside of their primary professional roles to increase efficiency."}'::jsonb),
('mc:a public health nutritionist is developing a new community-based infant feeding program. which of the following quality assurance (qa) procedures is most critical for ensuring the program''s long term effectiveness and sustainability, beyond a single evaluation cycle?:::establishing a continuous improvement (cqi) process that involves regular feedback loops from stakeholders and data-driven adjustments to program activities', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a public health nutritionist is developing a new community-based infant feeding program. which of the following quality assurance (qa) procedures is most critical for ensuring the program''s long term effectiveness and sustainability, beyond a single evaluation cycle?', 'Establishing a continuous improvement (CQI) process that involves regular feedback loops from stakeholders and data-driven adjustments to program activities', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is establishing a continuous quality improvement (CQI) process involving regular feedback loops from stakeholders and data-driven adjustments to program activities, because CQI is specifically designed as an ongoing, cyclical process that sustains program quality and effectiveness well beyond any single evaluation point. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Establishing a continuous improvement (CQI) process that involves regular feedback loops from stakeholders and data-driven adjustments to program activities\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is establishing a continuous quality improvement (CQI) process involving regular feedback loops from stakeholders and data-driven adjustments to program activities, because CQI is specifically designed as an ongoing, cyclical process that sustains program quality and effectiveness well beyond any single evaluation point. \n\n• A one-time pre-post knowledge test captures only a single snapshot of educational outcomes, not ongoing sustainability. \n• A randomized controlled trial is a rigorous but typically one-time comparative research design, not an ongoing quality assurance mechanism. \n• An annual peer review provides periodic, but not truly continuous, quality checking and lacks the responsive feedback-loop mechanism central to CQI.","whyWrongChoices":"Alternative options: Conducting a pre-post knowledge test for all program participants to measure educational outcomes, Implementing a randomized trial to compare the new program''s outcomes against a standard intervention, Performing an annual peer review of all materials and educational handouts to ensure scientific accuracy"}'::jsonb),
('mc:a public health nutritionist is developing a new community-based infant feeding program. which of the following quality assurance (qa) procedures is most critical for ensuring the program''s long term effectiveness and sustainability, beyond a single evaluation cycle?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a public health nutritionist is developing a new community-based infant feeding program. which of the following quality assurance (qa) procedures is most critical for ensuring the program''s long term effectiveness and sustainability, beyond a single evaluation cycle?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is establishing a continuous quality improvement (CQI) process involving regular feedback loops from stakeholders and data-driven adjustments to program activities, because CQI is specifically designed as an ongoing, cyclical process that sustains program quality and effectiveness well beyond any single evaluation point. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Establishing a continuous improvement (CQI) process that involves regular feedback loops from stakeholders and data-driven adjustments to program activities\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is establishing a continuous quality improvement (CQI) process involving regular feedback loops from stakeholders and data-driven adjustments to program activities, because CQI is specifically designed as an ongoing, cyclical process that sustains program quality and effectiveness well beyond any single evaluation point. \n\n• A one-time pre-post knowledge test captures only a single snapshot of educational outcomes, not ongoing sustainability. \n• A randomized controlled trial is a rigorous but typically one-time comparative research design, not an ongoing quality assurance mechanism. \n• An annual peer review provides periodic, but not truly continuous, quality checking and lacks the responsive feedback-loop mechanism central to CQI.","whyWrongChoices":"Alternative options: Conducting a pre-post knowledge test for all program participants to measure educational outcomes, Implementing a randomized trial to compare the new program''s outcomes against a standard intervention, Performing an annual peer review of all materials and educational handouts to ensure scientific accuracy"}'::jsonb),
('mc:which of the following conditions lead to contraindication to breastfeeding?:::galactosemia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following conditions lead to contraindication to breastfeeding?', 'Galactosemia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Galactosemia - the infant''s body cannot process the galactose, it rapidly builds up in the blood and tissues, becoming toxic.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galactosemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Galactosemia - the infant''s body cannot process the galactose, it rapidly builds up in the blood and tissues, becoming toxic.\n\nBecause lactose—the primary sugar in human breast milk—breaks down into glucose and galactose, breastfeeding a baby with this condition causes toxic levels of galactose to accumulate in their body.\n\nIf breast milk is not immediately replaced with a lactose-free formula, it can rapidly lead to life-threatening complications, including liver failure, severe brain damage, cataracts, and shock.","whyWrongChoices":"Alternative options: Multiple births, Hemorrhagic disease of the newborn, Diarrhea"}'::jsonb),
('mc:which of the following conditions lead to contraindication to breastfeeding?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following conditions lead to contraindication to breastfeeding?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Galactosemia - the infant''s body cannot process the galactose, it rapidly builds up in the blood and tissues, becoming toxic.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Galactosemia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Galactosemia - the infant''s body cannot process the galactose, it rapidly builds up in the blood and tissues, becoming toxic.\n\nBecause lactose—the primary sugar in human breast milk—breaks down into glucose and galactose, breastfeeding a baby with this condition causes toxic levels of galactose to accumulate in their body.\n\nIf breast milk is not immediately replaced with a lactose-free formula, it can rapidly lead to life-threatening complications, including liver failure, severe brain damage, cataracts, and shock.","whyWrongChoices":"Alternative options: Multiple births, Hemorrhagic disease of the newborn, Diarrhea"}'::jsonb),
('mc:what is the who recommendation for physical activity among adolescents?:::at least an average of 60 minutes per day of moderate to vigorous intensity across the week', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the who recommendation for physical activity among adolescents?', 'At least an average of 60 minutes per day of moderate to vigorous intensity across the week', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"It is recommended that children and adolescents should do at least an average of 60 minutes per day of moderate-to-vigorous-intensity, mostly aerobic, physical activity, across the week. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"At least an average of 60 minutes per day of moderate to vigorous intensity across the week\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"It is recommended that children and adolescents should do at least an average of 60 minutes per day of moderate-to-vigorous-intensity, mostly aerobic, physical activity, across the week. \n\nVigorous-intensity aerobic activities, as well as those that strengthen muscle and bone, should be incorporated at least 3 days a week.\n\nAdults should do at least 150–300 minutes of moderate-intensity aerobic physical activity; or at least 75–150 minutes of vigorous-intensity aerobic physical activity; or an equivalent combination of moderate- and vigorous-intensity activity throughout the week, for substantial health benefits.\n\nSee reference here:\n\nWHO guidelines on physical activity and sedentary behaviour (2020): https://iris.who.int/server/api/core/bitstreams/faa83413-d89e-4be9-bb01-b24671aef7ca/content","whyWrongChoices":"Alternative options: At least an average of 30 minutes per day of moderate to vigorous intensity across the week, At least 75 minutes per day of moderate to vigorous intensity across the week, At least 150 minutes per day of moderate to vigorous intensity across the week"}'::jsonb),
('mc:what is the who recommendation for physical activity among adolescents?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the who recommendation for physical activity among adolescents?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"It is recommended that children and adolescents should do at least an average of 60 minutes per day of moderate-to-vigorous-intensity, mostly aerobic, physical activity, across the week. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"At least an average of 60 minutes per day of moderate to vigorous intensity across the week\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"It is recommended that children and adolescents should do at least an average of 60 minutes per day of moderate-to-vigorous-intensity, mostly aerobic, physical activity, across the week. \n\nVigorous-intensity aerobic activities, as well as those that strengthen muscle and bone, should be incorporated at least 3 days a week.\n\nAdults should do at least 150–300 minutes of moderate-intensity aerobic physical activity; or at least 75–150 minutes of vigorous-intensity aerobic physical activity; or an equivalent combination of moderate- and vigorous-intensity activity throughout the week, for substantial health benefits.\n\nSee reference here:\n\nWHO guidelines on physical activity and sedentary behaviour (2020): https://iris.who.int/server/api/core/bitstreams/faa83413-d89e-4be9-bb01-b24671aef7ca/content","whyWrongChoices":"Alternative options: At least an average of 30 minutes per day of moderate to vigorous intensity across the week, At least 75 minutes per day of moderate to vigorous intensity across the week, At least 150 minutes per day of moderate to vigorous intensity across the week"}'::jsonb),
('mc:the who recommends reducing the intake of free sugars to less than in both adults and children:::less than 10% of total energy intake', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the who recommends reducing the intake of free sugars to less than in both adults and children', 'less than 10% of total energy intake', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The World Health Organization’s new Guideline: Sugars intake for adults and","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"less than 10% of total energy intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The World Health Organization’s new Guideline: Sugars intake for adults and\nchildren recommends reduced intake of free sugars throughout the life course.\nIn both adults and children, the intake of free sugars should be reduced to less\nthan 10% of total energy intake. A further reduction to below 5% of total energy\nintake would provide additional health benefits.\n\nSee reference here:\n\nInformation note about intake of sugars recommended\nin the WHO guideline for adults and children (2015): https://iris.who.int/server/api/core/bitstreams/e14490d6-dba9-4994-aeef-0a2abb73d09c/content","whyWrongChoices":"Alternative options: less than 5% of total energy intake, less than 15% of total energy intake, less than 20% of total energy intake"}'::jsonb),
('mc:the who recommends reducing the intake of free sugars to less than in both adults and children:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the who recommends reducing the intake of free sugars to less than in both adults and children', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The World Health Organization’s new Guideline: Sugars intake for adults and","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"less than 10% of total energy intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The World Health Organization’s new Guideline: Sugars intake for adults and\nchildren recommends reduced intake of free sugars throughout the life course.\nIn both adults and children, the intake of free sugars should be reduced to less\nthan 10% of total energy intake. A further reduction to below 5% of total energy\nintake would provide additional health benefits.\n\nSee reference here:\n\nInformation note about intake of sugars recommended\nin the WHO guideline for adults and children (2015): https://iris.who.int/server/api/core/bitstreams/e14490d6-dba9-4994-aeef-0a2abb73d09c/content","whyWrongChoices":"Alternative options: less than 5% of total energy intake, less than 15% of total energy intake, less than 20% of total energy intake"}'::jsonb),
('mc:delayed umbilical cord clamping not earlier than is recommended for improved maternal and infant health and nutrition outcomes.:::1 minute after birth', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'delayed umbilical cord clamping not earlier than is recommended for improved maternal and infant health and nutrition outcomes.', '1 minute after birth', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In newly born term or preterm babies who do not require positive-pressure ventilation, the cord should not be clamped earlier than 1 min after birth (strong recommendation).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1 minute after birth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In newly born term or preterm babies who do not require positive-pressure ventilation, the cord should not be clamped earlier than 1 min after birth (strong recommendation).\n\nSee references here:\n\nWHO Guideline: delayed umbilical cord clamping for improved maternal and infant health and nutrition\nOutcomes (2014): https://iris.who.int/server/api/core/bitstreams/cd57d2bf-b6be-4712-b23a-bad509587b7b/content\n\nWHO Guidelines on Basic Newborn Resuscitation (2012): https://iris.who.int/server/api/core/bitstreams/e348f5c5-6841-409f-8b13-cf58e4da03e0/content","whyWrongChoices":"Alternative options: 2 minutes after birth, 3 minutes after birth, 4 minutes after birth"}'::jsonb),
('mc:delayed umbilical cord clamping not earlier than is recommended for improved maternal and infant health and nutrition outcomes.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'delayed umbilical cord clamping not earlier than is recommended for improved maternal and infant health and nutrition outcomes.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In newly born term or preterm babies who do not require positive-pressure ventilation, the cord should not be clamped earlier than 1 min after birth (strong recommendation).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1 minute after birth\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In newly born term or preterm babies who do not require positive-pressure ventilation, the cord should not be clamped earlier than 1 min after birth (strong recommendation).\n\nSee references here:\n\nWHO Guideline: delayed umbilical cord clamping for improved maternal and infant health and nutrition\nOutcomes (2014): https://iris.who.int/server/api/core/bitstreams/cd57d2bf-b6be-4712-b23a-bad509587b7b/content\n\nWHO Guidelines on Basic Newborn Resuscitation (2012): https://iris.who.int/server/api/core/bitstreams/e348f5c5-6841-409f-8b13-cf58e4da03e0/content","whyWrongChoices":"Alternative options: 2 minutes after birth, 3 minutes after birth, 4 minutes after birth"}'::jsonb),
('mc:what is the main advantage of using randomized controlled trial (rct) in nutrition research?:::it enables researchers to control for confounding variables', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the main advantage of using randomized controlled trial (rct) in nutrition research?', 'It enables researchers to control for confounding variables', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is: randomization allows researchers to control for confounding variables, both known and unknown.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It enables researchers to control for confounding variables\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is: randomization allows researchers to control for confounding variables, both known and unknown.\n\n• Choice A is incorrect because RCTs are typically better suited for shorter-term interventions, not long-term dietary pattern studies, which favor cohort designs.\n• Choice C is false because RCTs are generally more expensive and time-consuming than observational designs. \n• Choice D overstates the claim; RCTs are the gold standard for causal inference but are not the \"only way\" to study nutrient-health relationships, since other designs also contribute evidence. The RCT''s defining strength is its ability to minimize both measured and unmeasured confounding through random allocation.","whyWrongChoices":"Alternative options: It allows for the study of long-term dietary patterns, It is less expensive and time-consuming than other study designs, It is the only way to study the effects of specific nutrients on health"}'::jsonb),
('mc:the %ibw of a person who weighs 185 pounds and has a desirable body weight of 150 pounds is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the %ibw of a person who weighs 185 pounds and has a desirable body weight of 150 pounds is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"1. The Formula: Percent Desirable/Ideal Body Weight (%IBW) is calculated by dividing a person''s current weight by their desirable weight, then multiplying by 100:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"123%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"1. The Formula: Percent Desirable/Ideal Body Weight (%IBW) is calculated by dividing a person''s current weight by their desirable weight, then multiplying by 100:\n• Percent Ideal Body Weight (%IBW) = (Current Weight / Desirable Weight) x 100\n\n2. Plug in the numbers:\n• Step 1: 185 lbs / 150 lbs = 1.2333\n• Step 2: 1.2333 x 100 = 123.33%\nRounding to the nearest whole number gives 123%.","whyWrongChoices":"Alternative options: 23%, 50%, 150%"}'::jsonb),
('mc:what is the main advantage of using randomized controlled trial (rct) in nutrition research?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the main advantage of using randomized controlled trial (rct) in nutrition research?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is: randomization allows researchers to control for confounding variables, both known and unknown.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"It enables researchers to control for confounding variables\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is: randomization allows researchers to control for confounding variables, both known and unknown.\n\n• Choice A is incorrect because RCTs are typically better suited for shorter-term interventions, not long-term dietary pattern studies, which favor cohort designs.\n• Choice C is false because RCTs are generally more expensive and time-consuming than observational designs. \n• Choice D overstates the claim; RCTs are the gold standard for causal inference but are not the \"only way\" to study nutrient-health relationships, since other designs also contribute evidence. The RCT''s defining strength is its ability to minimize both measured and unmeasured confounding through random allocation.","whyWrongChoices":"Alternative options: It allows for the study of long-term dietary patterns, It is less expensive and time-consuming than other study designs, It is the only way to study the effects of specific nutrients on health"}'::jsonb),
('mc:which of the following is not a common method used to assess dietary intake in nutrition research?:::randomized controlled trial (rct)', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is not a common method used to assess dietary intake in nutrition research?', 'Randomized controlled trial (RCT)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"RCT is a study design not a dietary assessment method.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Randomized controlled trial (RCT)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"RCT is a study design not a dietary assessment method.","whyWrongChoices":"Alternative options: Diet record, 24-hour recall, Food frequency questionnaire (FFQ)"}'::jsonb),
('mc:which of the following is not a common method used to assess dietary intake in nutrition research?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is not a common method used to assess dietary intake in nutrition research?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"RCT is a study design not a dietary assessment method.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Randomized controlled trial (RCT)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"RCT is a study design not a dietary assessment method.","whyWrongChoices":"Alternative options: Diet record, 24-hour recall, Food frequency questionnaire (FFQ)"}'::jsonb),
('mc:in nutrition research, what is the primary reason for using random sampling techniques?:::to ensure every member of the population has an equal chance of selection', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in nutrition research, what is the primary reason for using random sampling techniques?', 'To ensure every member of the population has an equal chance of selection', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that random sampling ensures every member of the population has an equal chance of selection, allowing findings from the sample to be validly generalized to the broader population. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To ensure every member of the population has an equal chance of selection\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that random sampling ensures every member of the population has an equal chance of selection, allowing findings from the sample to be validly generalized to the broader population. \n\n• Choice A (saving time/resources) may be a secondary practical benefit but is not the primary scientific rationale. \n• Choice C (researcher convenience) actually describes convenience sampling, a non-random, less rigorous method. \n• Choice D (targeting specific dietary habits) describes purposive, non-random sampling, which serves a different research purpose.","whyWrongChoices":"Alternative options: To save time and resources, To make the study more convenient for the researcher, To specifically target individuals with certain dietary habits"}'::jsonb),
('mc:in nutrition research, what is the primary reason for using random sampling techniques?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in nutrition research, what is the primary reason for using random sampling techniques?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The correct answer is that random sampling ensures every member of the population has an equal chance of selection, allowing findings from the sample to be validly generalized to the broader population. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"To ensure every member of the population has an equal chance of selection\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The correct answer is that random sampling ensures every member of the population has an equal chance of selection, allowing findings from the sample to be validly generalized to the broader population. \n\n• Choice A (saving time/resources) may be a secondary practical benefit but is not the primary scientific rationale. \n• Choice C (researcher convenience) actually describes convenience sampling, a non-random, less rigorous method. \n• Choice D (targeting specific dietary habits) describes purposive, non-random sampling, which serves a different research purpose.","whyWrongChoices":"Alternative options: To save time and resources, To make the study more convenient for the researcher, To specifically target individuals with certain dietary habits"}'::jsonb),
('mc:although the rdas are a useful standard in evaluating the usual dietary intake of groups and individuals, they cannot provide sufficient information to::::determine the nutritional status of individuals or population groups', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'although the rdas are a useful standard in evaluating the usual dietary intake of groups and individuals, they cannot provide sufficient information to:', 'Determine the nutritional status of individuals or population groups', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Recommended Dietary Allowances (RDAs) are quantitative guidelines representing dietary intake estimates designed to meet the nutrient requirements of 97% to 98% of healthy individuals. However, dietary intake alone is insufficient to establish an individual''s or a group''s actual nutritional status.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Determine the nutritional status of individuals or population groups\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Recommended Dietary Allowances (RDAs) are quantitative guidelines representing dietary intake estimates designed to meet the nutrient requirements of 97% to 98% of healthy individuals. However, dietary intake alone is insufficient to establish an individual''s or a group''s actual nutritional status.","whyWrongChoices":"Alternative options: To design nutrition education programs, To enable the government to predict food needs of the population, to be used for planning and assessing diets for healthy people."}'::jsonb),
('mc:although the rdas are a useful standard in evaluating the usual dietary intake of groups and individuals, they cannot provide sufficient information to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'although the rdas are a useful standard in evaluating the usual dietary intake of groups and individuals, they cannot provide sufficient information to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Recommended Dietary Allowances (RDAs) are quantitative guidelines representing dietary intake estimates designed to meet the nutrient requirements of 97% to 98% of healthy individuals. However, dietary intake alone is insufficient to establish an individual''s or a group''s actual nutritional status.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Determine the nutritional status of individuals or population groups\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Recommended Dietary Allowances (RDAs) are quantitative guidelines representing dietary intake estimates designed to meet the nutrient requirements of 97% to 98% of healthy individuals. However, dietary intake alone is insufficient to establish an individual''s or a group''s actual nutritional status.","whyWrongChoices":"Alternative options: To design nutrition education programs, To enable the government to predict food needs of the population, to be used for planning and assessing diets for healthy people."}'::jsonb),
('mc:it is the most widely used screening test for iron-deficiency anemia:::hemoglobin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is the most widely used screening test for iron-deficiency anemia', 'Hemoglobin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemoglobin measurement in whole blood is universally recognized as the most common, cost-effective, rapid, and widely accessible screening test for anemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemoglobin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemoglobin measurement in whole blood is universally recognized as the most common, cost-effective, rapid, and widely accessible screening test for anemia.\n\nBecause iron deficiency is the leading cause of anemia worldwide, public health screenings routinely measure hemoglobin levels as a quick proxy to catch potential cases of iron-deficiency anemia. If a patient''s hemoglobin falls below standard thresholds, it triggers clinicians to look closer.\n\n• Ferritin: The definitive diagnostic gold-standard to check total iron stores, but too expensive for mass initial screening.\n• Hematocrit: Measures red blood cell volume ratio; less sensitive than direct hemoglobin testing.\n• CBC: A full comprehensive panel. While it contains the hemoglobin measurement, hemoglobin itself is the target marker.","whyWrongChoices":"Alternative options: Hematocrit, Ferritin, CBC"}'::jsonb),
('mc:it is the most widely used screening test for iron-deficiency anemia:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is the most widely used screening test for iron-deficiency anemia', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemoglobin measurement in whole blood is universally recognized as the most common, cost-effective, rapid, and widely accessible screening test for anemia.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemoglobin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemoglobin measurement in whole blood is universally recognized as the most common, cost-effective, rapid, and widely accessible screening test for anemia.\n\nBecause iron deficiency is the leading cause of anemia worldwide, public health screenings routinely measure hemoglobin levels as a quick proxy to catch potential cases of iron-deficiency anemia. If a patient''s hemoglobin falls below standard thresholds, it triggers clinicians to look closer.\n\n• Ferritin: The definitive diagnostic gold-standard to check total iron stores, but too expensive for mass initial screening.\n• Hematocrit: Measures red blood cell volume ratio; less sensitive than direct hemoglobin testing.\n• CBC: A full comprehensive panel. While it contains the hemoglobin measurement, hemoglobin itself is the target marker.","whyWrongChoices":"Alternative options: Hematocrit, Ferritin, CBC"}'::jsonb),
('mc:bf is a 61-year-old female diagnosed with cancer of the stomach and has been bedridden for the past one month; height 5’6’’, weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 calories per day. the attending physician decided to give her parenteral nutrition prior to a contemplated procedure. if patient bf in question 29 will transition to an oral diet with oral nutrition supplementation, what enteral feeding formula can be recommended for bf?:::supportan', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'bf is a 61-year-old female diagnosed with cancer of the stomach and has been bedridden for the past one month; height 5’6’’, weight: 50 kg, with a history of 10% weight loss for the past 3 months, has been consuming mostly liquid and semi foods amounting to 700 calories per day. the attending physician decided to give her parenteral nutrition prior to a contemplated procedure. if patient bf in question 29 will transition to an oral diet with oral nutrition supplementation, what enteral feeding formula can be recommended for bf?', 'Supportan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Supportan (manufactured by Fresenius Kabi) is a specialized, disease-specific medical nutrition formula engineered explicitly for cancer patients experiencing or at risk of cancer cachexia (weight loss and muscle wasting). It is high in calories, high in protein, and crucially enriched with EPA (Eicosapentaenoic Acid)—an omega-3 fatty acid that clinically down-regulates the systemic tumor-induced inflammation driving tissue breakdown.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Supportan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Supportan (manufactured by Fresenius Kabi) is a specialized, disease-specific medical nutrition formula engineered explicitly for cancer patients experiencing or at risk of cancer cachexia (weight loss and muscle wasting). It is high in calories, high in protein, and crucially enriched with EPA (Eicosapentaenoic Acid)—an omega-3 fatty acid that clinically down-regulates the systemic tumor-induced inflammation driving tissue breakdown.\n\n\t• Ensure Gold & Ensure Vigor: These are standard polymeric formulas meant for general adult maintenance or age-related muscle loss, not targeted cancer care.\n\t• Alitraq: This is a specialized elemental/peptide-based formula enriched with glutamine, meant for patients with severely impaired GI tract absorption or trauma, rather than oncology-specific needs.","whyWrongChoices":"Alternative options: Ensure Vigor, Ensure Gold, Alitraq"}'::jsonb),
('mc:marasmus develops from::::inadequate protein and energy intake', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'marasmus develops from:', 'Inadequate protein and energy intake', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Marasmus is a severe form of protein-energy malnutrition (PEM) resulting from general starvation. It occurs when an individual experiences a chronic, severe deficit in both total calories (energy) and protein across all major macronutrients. This causes the body to exhaustively break down its own subcutaneous fat stores and muscle tissue for survival, leading to a characteristically shriveled and wasted appearance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inadequate protein and energy intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Marasmus is a severe form of protein-energy malnutrition (PEM) resulting from general starvation. It occurs when an individual experiences a chronic, severe deficit in both total calories (energy) and protein across all major macronutrients. This causes the body to exhaustively break down its own subcutaneous fat stores and muscle tissue for survival, leading to a characteristically shriveled and wasted appearance.","whyWrongChoices":"Alternative options: Too much fat clogging the liver, Megadoses of amino acid supplements, Excessive fluid intake causing edema"}'::jsonb),
('mc:marasmus develops from::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'marasmus develops from:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Marasmus is a severe form of protein-energy malnutrition (PEM) resulting from general starvation. It occurs when an individual experiences a chronic, severe deficit in both total calories (energy) and protein across all major macronutrients. This causes the body to exhaustively break down its own subcutaneous fat stores and muscle tissue for survival, leading to a characteristically shriveled and wasted appearance.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Inadequate protein and energy intake\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Marasmus is a severe form of protein-energy malnutrition (PEM) resulting from general starvation. It occurs when an individual experiences a chronic, severe deficit in both total calories (energy) and protein across all major macronutrients. This causes the body to exhaustively break down its own subcutaneous fat stores and muscle tissue for survival, leading to a characteristically shriveled and wasted appearance.","whyWrongChoices":"Alternative options: Too much fat clogging the liver, Megadoses of amino acid supplements, Excessive fluid intake causing edema"}'::jsonb),
('mc:tests usually performed using an automated chemistry analyzer that are useful in diagnosing and managing disease.:::blood chemistry', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'tests usually performed using an automated chemistry analyzer that are useful in diagnosing and managing disease.', 'Blood chemistry', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An automated chemistry analyzer is a specialized laboratory instrument designed to rapidly process blood serum, plasma, or urine samples. It measures the concentrations of various chemical substances in the body—such as electrolytes (sodium, potassium), renal markers (BUN, creatinine), liver enzymes (ALT, AST), and metabolic indicators (glucose, cholesterol). These blood chemistry profiles are vital for diagnosing and managing wide-ranging systemic diseases.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Blood chemistry\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An automated chemistry analyzer is a specialized laboratory instrument designed to rapidly process blood serum, plasma, or urine samples. It measures the concentrations of various chemical substances in the body—such as electrolytes (sodium, potassium), renal markers (BUN, creatinine), liver enzymes (ALT, AST), and metabolic indicators (glucose, cholesterol). These blood chemistry profiles are vital for diagnosing and managing wide-ranging systemic diseases.","whyWrongChoices":"Alternative options: Ultrasonography, Endoscopy, CT Scan"}'::jsonb),
('mc:tests usually performed using an automated chemistry analyzer that are useful in diagnosing and managing disease.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'tests usually performed using an automated chemistry analyzer that are useful in diagnosing and managing disease.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An automated chemistry analyzer is a specialized laboratory instrument designed to rapidly process blood serum, plasma, or urine samples. It measures the concentrations of various chemical substances in the body—such as electrolytes (sodium, potassium), renal markers (BUN, creatinine), liver enzymes (ALT, AST), and metabolic indicators (glucose, cholesterol). These blood chemistry profiles are vital for diagnosing and managing wide-ranging systemic diseases.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Blood chemistry\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An automated chemistry analyzer is a specialized laboratory instrument designed to rapidly process blood serum, plasma, or urine samples. It measures the concentrations of various chemical substances in the body—such as electrolytes (sodium, potassium), renal markers (BUN, creatinine), liver enzymes (ALT, AST), and metabolic indicators (glucose, cholesterol). These blood chemistry profiles are vital for diagnosing and managing wide-ranging systemic diseases.","whyWrongChoices":"Alternative options: Ultrasonography, Endoscopy, CT Scan"}'::jsonb),
('mc:is a muscle metabolite excreted in urine used to quantitate muscle mass:::creatinine', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'is a muscle metabolite excreted in urine used to quantitate muscle mass', 'Creatinine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Creatinine is a chemical waste molecule generated continuously by normal skeletal muscle metabolism. It is produced from the breakdown of creatine phosphate, an energy-storage molecule in muscles. Because muscle tissue produces a steady, fixed amount of creatinine every day, measuring the total amount of creatinine excreted in a 24-hour urine collection is directly proportional to a person''s total skeletal muscle mass (lean body mass).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Creatinine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Creatinine is a chemical waste molecule generated continuously by normal skeletal muscle metabolism. It is produced from the breakdown of creatine phosphate, an energy-storage molecule in muscles. Because muscle tissue produces a steady, fixed amount of creatinine every day, measuring the total amount of creatinine excreted in a 24-hour urine collection is directly proportional to a person''s total skeletal muscle mass (lean body mass).\n\n\t× BUN: Blood Urea Nitrogen is a waste product of protein breakdown formed in the liver. It spikes heavily with a high-protein meal, dehydration, or kidney failure, making it a poor tool for measuring physical muscle mass.\n\t× Albumin & Transferrin: These are visceral transport proteins synthesized by the liver. They are used to help assess general protein status or iron transport, but they cannot measure skeletal muscle mass.","whyWrongChoices":"Alternative options: Albumin, Transferrin, BUN"}'::jsonb),
('mc:the simplest & most practical available method of determining the extent of obesity especially for clinical use::::bmi', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the simplest & most practical available method of determining the extent of obesity especially for clinical use:', 'BMI', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"BMI is universally recognized as the simplest and most practical method for determining the extent of obesity in clinical settings. Because it only requires a patient''s height and weight (kg/m²), it is non-invasive, takes seconds to calculate, costs absolutely nothing, and does not require specialized equipment or advanced training.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"BMI\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"BMI is universally recognized as the simplest and most practical method for determining the extent of obesity in clinical settings. Because it only requires a patient''s height and weight (kg/m²), it is non-invasive, takes seconds to calculate, costs absolutely nothing, and does not require specialized equipment or advanced training.","whyWrongChoices":"Alternative options: body composition, body fat analysis, skinfold measurement"}'::jsonb),
