INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:symptoms of irritable bowel syndrome most often include:::constipation, diarrhea and flatulence', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'symptoms of irritable bowel syndrome most often include', 'Constipation, Diarrhea and flatulence', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Irritable Bowel Syndrome (IBS) is a common functional gastrointestinal disorder characterized by abnormal gut motility and visceral hypersensitivity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Constipation, Diarrhea and flatulence\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Irritable Bowel Syndrome (IBS) is a common functional gastrointestinal disorder characterized by abnormal gut motility and visceral hypersensitivity.\n\nThe hallmark clinical features of IBS include chronic abdominal pain or cramping paired with significant changes in bowel habits, which typically alternate between diarrhea and constipation (often classified clinically as IBS-D, IBS-C, or IBS-M for mixed types). Excessive gas production (flatulence) and bloating are also universal symptoms caused by altered fermentation profiles in the gut.","whyWrongChoices":"Alternative options: Nausea and Vomiting, Weight loss and Malnutrition, Strong odors and Obstructions"}'::jsonb),
('mc:symptoms of irritable bowel syndrome most often include:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'symptoms of irritable bowel syndrome most often include', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Irritable Bowel Syndrome (IBS) is a common functional gastrointestinal disorder characterized by abnormal gut motility and visceral hypersensitivity.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Constipation, Diarrhea and flatulence\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Irritable Bowel Syndrome (IBS) is a common functional gastrointestinal disorder characterized by abnormal gut motility and visceral hypersensitivity.\n\nThe hallmark clinical features of IBS include chronic abdominal pain or cramping paired with significant changes in bowel habits, which typically alternate between diarrhea and constipation (often classified clinically as IBS-D, IBS-C, or IBS-M for mixed types). Excessive gas production (flatulence) and bloating are also universal symptoms caused by altered fermentation profiles in the gut.","whyWrongChoices":"Alternative options: Nausea and Vomiting, Weight loss and Malnutrition, Strong odors and Obstructions"}'::jsonb),
('mc:foods discouraged for patients with gastritis or active ulcers include those that:::irritate the gastric mucosa', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'foods discouraged for patients with gastritis or active ulcers include those that', 'irritate the gastric mucosa', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For patients with gastritis or active peptic ulcers, nutrition therapy focuses on promoting tissue healing and preventing further irritation to the delicate stomach lining.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"irritate the gastric mucosa\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For patients with gastritis or active peptic ulcers, nutrition therapy focuses on promoting tissue healing and preventing further irritation to the delicate stomach lining.\n\nPatients must strictly avoid foods that cause direct chemical, mechanical, or thermal irritation to the gastric mucosa, as well as substances that stimulate excessive gastric acid secretion. This includes highly spicy foods (like chili powder and hot peppers), caffeine, alcohol, and extremely acidic foods.","whyWrongChoices":"Alternative options: are high in fiber, are easy to swallow, contain simple sugars"}'::jsonb),
('mc:foods discouraged for patients with gastritis or active ulcers include those that:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'foods discouraged for patients with gastritis or active ulcers include those that', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For patients with gastritis or active peptic ulcers, nutrition therapy focuses on promoting tissue healing and preventing further irritation to the delicate stomach lining.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"irritate the gastric mucosa\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For patients with gastritis or active peptic ulcers, nutrition therapy focuses on promoting tissue healing and preventing further irritation to the delicate stomach lining.\n\nPatients must strictly avoid foods that cause direct chemical, mechanical, or thermal irritation to the gastric mucosa, as well as substances that stimulate excessive gastric acid secretion. This includes highly spicy foods (like chili powder and hot peppers), caffeine, alcohol, and extremely acidic foods.","whyWrongChoices":"Alternative options: are high in fiber, are easy to swallow, contain simple sugars"}'::jsonb),
('mc:the prevalence of malnutrition among hospitalized patient worldwide is::::20 to 50%', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the prevalence of malnutrition among hospitalized patient worldwide is:', '20 to 50%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Globally accepted clinical data from large-scale screening initiatives (such as the nutritionDay worldwide database) establish that 20% to 50% of hospitalized patients suffer from disease-related malnutrition at the time of admission or develop it during their hospital stay.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"20 to 50%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Globally accepted clinical data from large-scale screening initiatives (such as the nutritionDay worldwide database) establish that 20% to 50% of hospitalized patients suffer from disease-related malnutrition at the time of admission or develop it during their hospital stay.\n\nThis wide statistical variance depends heavily on:\n1. The specific country or healthcare region.\n2. The specific patient population (e.g., intensive care, oncology, or geriatric populations experience much higher rates up to 90%).\n3. The individual screening tool or diagnostic criteria used by the facility (such as the NRS-2002, MUST, or GLIM criteria).","whyWrongChoices":"Alternative options: 20 to 48 %, 30 to 50 %, 25 to 50 %"}'::jsonb),
('mc:the prevalence of malnutrition among hospitalized patient worldwide is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the prevalence of malnutrition among hospitalized patient worldwide is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Globally accepted clinical data from large-scale screening initiatives (such as the nutritionDay worldwide database) establish that 20% to 50% of hospitalized patients suffer from disease-related malnutrition at the time of admission or develop it during their hospital stay.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"20 to 50%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Globally accepted clinical data from large-scale screening initiatives (such as the nutritionDay worldwide database) establish that 20% to 50% of hospitalized patients suffer from disease-related malnutrition at the time of admission or develop it during their hospital stay.\n\nThis wide statistical variance depends heavily on:\n1. The specific country or healthcare region.\n2. The specific patient population (e.g., intensive care, oncology, or geriatric populations experience much higher rates up to 90%).\n3. The individual screening tool or diagnostic criteria used by the facility (such as the NRS-2002, MUST, or GLIM criteria).","whyWrongChoices":"Alternative options: 20 to 48 %, 30 to 50 %, 25 to 50 %"}'::jsonb),
('mc:for radiation enteritis, this diet is best indicated for this condition:::lactose free, low fat, low fiber', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'for radiation enteritis, this diet is best indicated for this condition', 'Lactose free, Low Fat, Low Fiber', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Radiation enteritis is an acute or chronic inflammation of the intestinal tract caused by radiation therapy directed at the abdomen or pelvis. The radiation kills rapidly dividing cells, which damages the mucosal lining, blunts the intestinal villi, and destroys the enzymes responsible for standard digestion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lactose free, Low Fat, Low Fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Radiation enteritis is an acute or chronic inflammation of the intestinal tract caused by radiation therapy directed at the abdomen or pelvis. The radiation kills rapidly dividing cells, which damages the mucosal lining, blunts the intestinal villi, and destroys the enzymes responsible for standard digestion.\n\nTo manage the resulting malabsorption, cramping, and severe diarrhea, the clinical diet must address multiple mechanics simultaneously:\n\n• Lactose-Free: The brush-border enzyme lactase is the first to be destroyed when the intestinal lining is damaged by radiation. Even a small amount of lactose can trigger severe osmotic diarrhea, gas, and painful bloating.\n• Low Fat: Because the blunted villi cannot properly absorb lipids, fats will pass unabsorbed into the colon, causing steatorrhea (fatty stools) and worsening fluid loss.\n• Low Fiber: The colon must be completely protected from mechanical irritation. Removing abrasive, scratchy insoluble plant fibers prevents bowel stimulation and minimizes painful cramping.","whyWrongChoices":"Alternative options: High Fiber, Low Fiber, Low Fat, Low Residue"}'::jsonb),
('mc:for radiation enteritis, this diet is best indicated for this condition:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'for radiation enteritis, this diet is best indicated for this condition', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Radiation enteritis is an acute or chronic inflammation of the intestinal tract caused by radiation therapy directed at the abdomen or pelvis. The radiation kills rapidly dividing cells, which damages the mucosal lining, blunts the intestinal villi, and destroys the enzymes responsible for standard digestion.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lactose free, Low Fat, Low Fiber\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Radiation enteritis is an acute or chronic inflammation of the intestinal tract caused by radiation therapy directed at the abdomen or pelvis. The radiation kills rapidly dividing cells, which damages the mucosal lining, blunts the intestinal villi, and destroys the enzymes responsible for standard digestion.\n\nTo manage the resulting malabsorption, cramping, and severe diarrhea, the clinical diet must address multiple mechanics simultaneously:\n\n• Lactose-Free: The brush-border enzyme lactase is the first to be destroyed when the intestinal lining is damaged by radiation. Even a small amount of lactose can trigger severe osmotic diarrhea, gas, and painful bloating.\n• Low Fat: Because the blunted villi cannot properly absorb lipids, fats will pass unabsorbed into the colon, causing steatorrhea (fatty stools) and worsening fluid loss.\n• Low Fiber: The colon must be completely protected from mechanical irritation. Removing abrasive, scratchy insoluble plant fibers prevents bowel stimulation and minimizes painful cramping.","whyWrongChoices":"Alternative options: High Fiber, Low Fiber, Low Fat, Low Residue"}'::jsonb),
('mc:the following are examples of the low fiber diet except:::oatmeal, soft boiled egg, gelatin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are examples of the low fiber diet except', 'Oatmeal, Soft Boiled Egg, Gelatin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A low-fiber diet requires restricting daily plant fiber intake to ease digestion and rest the gastrointestinal tract. This means replacing whole-grain products with refined starches and avoiding raw or high-fiber foods.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oatmeal, Soft Boiled Egg, Gelatin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A low-fiber diet requires restricting daily plant fiber intake to ease digestion and rest the gastrointestinal tract. This means replacing whole-grain products with refined starches and avoiding raw or high-fiber foods.\n\nOatmeal is a whole grain that natively contains high levels of soluble and insoluble fiber. Because whole grains leave a high amount of undigested bulk in the colon, oatmeal is strictly restricted on a standard low-fiber diet plan.","whyWrongChoices":"Alternative options: White rice, Soft Boiled Egg, Canned peaches, White bread, Scrambled Egg, Strained Juice, White rice, Pork Nilaga, Strained juice"}'::jsonb),
('mc:the following are examples of the low fiber diet except:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are examples of the low fiber diet except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A low-fiber diet requires restricting daily plant fiber intake to ease digestion and rest the gastrointestinal tract. This means replacing whole-grain products with refined starches and avoiding raw or high-fiber foods.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oatmeal, Soft Boiled Egg, Gelatin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A low-fiber diet requires restricting daily plant fiber intake to ease digestion and rest the gastrointestinal tract. This means replacing whole-grain products with refined starches and avoiding raw or high-fiber foods.\n\nOatmeal is a whole grain that natively contains high levels of soluble and insoluble fiber. Because whole grains leave a high amount of undigested bulk in the colon, oatmeal is strictly restricted on a standard low-fiber diet plan.","whyWrongChoices":"Alternative options: White rice, Soft Boiled Egg, Canned peaches, White bread, Scrambled Egg, Strained Juice, White rice, Pork Nilaga, Strained juice"}'::jsonb),
('mc:insoluble fiber is indicated for the following conditions except:::gastric ulcer', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'insoluble fiber is indicated for the following conditions except', 'Gastric Ulcer', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Insoluble fiber (found in wheat bran, whole grains, and vegetable skins) does not dissolve in water and acts as coarse roughage that speeds up intestinal transit and adds bulk to stools.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastric Ulcer\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Insoluble fiber (found in wheat bran, whole grains, and vegetable skins) does not dissolve in water and acts as coarse roughage that speeds up intestinal transit and adds bulk to stools.\n\nAn active gastric ulcer is a raw, inflamed sore in the stomach lining. Insoluble fiber is physically abrasive and difficult to break down, which can mechanically scratch and irritate the stomach lining, increasing pain and delayed healing. Therefore, a low-residue/bland diet is indicated for gastric ulcers instead.\n\n• Insoluble fiber is highly indicated for Diverticular Disease to lower colon pressure, Colon and Rectal Cancer to rapidly flush out potential carcinogens, and selected constipation-predominant Irritable Bowel Syndrome types to improve regularity.","whyWrongChoices":"Alternative options: Irritable Bowel Syndrome, Diverticular Disease, Colon and Rectal Cancer"}'::jsonb),
('mc:insoluble fiber is indicated for the following conditions except:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'insoluble fiber is indicated for the following conditions except', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Insoluble fiber (found in wheat bran, whole grains, and vegetable skins) does not dissolve in water and acts as coarse roughage that speeds up intestinal transit and adds bulk to stools.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Gastric Ulcer\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Insoluble fiber (found in wheat bran, whole grains, and vegetable skins) does not dissolve in water and acts as coarse roughage that speeds up intestinal transit and adds bulk to stools.\n\nAn active gastric ulcer is a raw, inflamed sore in the stomach lining. Insoluble fiber is physically abrasive and difficult to break down, which can mechanically scratch and irritate the stomach lining, increasing pain and delayed healing. Therefore, a low-residue/bland diet is indicated for gastric ulcers instead.\n\n• Insoluble fiber is highly indicated for Diverticular Disease to lower colon pressure, Colon and Rectal Cancer to rapidly flush out potential carcinogens, and selected constipation-predominant Irritable Bowel Syndrome types to improve regularity.","whyWrongChoices":"Alternative options: Irritable Bowel Syndrome, Diverticular Disease, Colon and Rectal Cancer"}'::jsonb),
('mc:lr, a 67 year old man who has had depression was prescribed a maoi (monoamine oxidase inhibitor) the following foods are avoided except::::green tea', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'lr, a 67 year old man who has had depression was prescribed a maoi (monoamine oxidase inhibitor) the following foods are avoided except:', 'Green Tea', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Green tea is the exception among the listed options because it contains minimal to negligible levels of tyramine and is primarily composed of catechins, flavonoids, and caffeine. Unlike fermented, aged, or protein-degraded foods, green tea does not provoke dangerous systemic vasoconstriction when combined with MAOIs.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Green Tea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Green tea is the exception among the listed options because it contains minimal to negligible levels of tyramine and is primarily composed of catechins, flavonoids, and caffeine. Unlike fermented, aged, or protein-degraded foods, green tea does not provoke dangerous systemic vasoconstriction when combined with MAOIs.","whyWrongChoices":"Alternative options: Avocado, Bean curd, Aged Cheese"}'::jsonb),
('mc:which of the following foods contain the highest amount of lactose:::yogurt', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following foods contain the highest amount of lactose', 'Yogurt', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Commercial yogurts are frequently manufactured with added non-fat dry milk solids to improve texture and mouthfeel, which increases the total carbohydrate and lactose concentration per serving compared to fluid milk. While bacterial fermentation by Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus produces microbial $\\beta$-galactosidase that hydrolyzes a portion of the lactose into glucose and galactose, the initial substrate load from concentrated milk solids often results in higher total residual lactose per standard 8-ounce serving than fluid milk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Yogurt\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Commercial yogurts are frequently manufactured with added non-fat dry milk solids to improve texture and mouthfeel, which increases the total carbohydrate and lactose concentration per serving compared to fluid milk. While bacterial fermentation by Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus produces microbial $\\beta$-galactosidase that hydrolyzes a portion of the lactose into glucose and galactose, the initial substrate load from concentrated milk solids often results in higher total residual lactose per standard 8-ounce serving than fluid milk.","whyWrongChoices":"Alternative options: Cottage Cheese, Milk, Sherbet"}'::jsonb),
('mc:which of the following foods contain the highest amount of lactose:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following foods contain the highest amount of lactose', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Commercial yogurts are frequently manufactured with added non-fat dry milk solids to improve texture and mouthfeel, which increases the total carbohydrate and lactose concentration per serving compared to fluid milk. While bacterial fermentation by Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus produces microbial $\\beta$-galactosidase that hydrolyzes a portion of the lactose into glucose and galactose, the initial substrate load from concentrated milk solids often results in higher total residual lactose per standard 8-ounce serving than fluid milk.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Yogurt\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Commercial yogurts are frequently manufactured with added non-fat dry milk solids to improve texture and mouthfeel, which increases the total carbohydrate and lactose concentration per serving compared to fluid milk. While bacterial fermentation by Lactobacillus delbrueckii subsp. bulgaricus and Streptococcus thermophilus produces microbial $\\beta$-galactosidase that hydrolyzes a portion of the lactose into glucose and galactose, the initial substrate load from concentrated milk solids often results in higher total residual lactose per standard 8-ounce serving than fluid milk.","whyWrongChoices":"Alternative options: Cottage Cheese, Milk, Sherbet"}'::jsonb),
('mc:case scenario: jd, a 59-year-old female, chief executive officer of a telecommunications office, whose height is 5’5” and weight is 93 kg was admitted in the hospital due to a transient ischemic attack (tia). using the data on the height and weight, her bmi is::::34.1', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'case scenario: jd, a 59-year-old female, chief executive officer of a telecommunications office, whose height is 5’5” and weight is 93 kg was admitted in the hospital due to a transient ischemic attack (tia). using the data on the height and weight, her bmi is:', '34.1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"34.1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).\n1. Convert Height to Meters:\n\t• 5 feet 5 inches = 65 inches\n\t• 65 inches × 0.0254 = 1.651 meters\n2. Calculate Height Squared:\n\t• 1.651 x 1.651 = 2.7258\n3. Calculate BMI:\n\t• BMI} = 93 / 2.7258 = 34.118 ~ 34.1 kg/m²","whyWrongChoices":"Alternative options: 35, 34.5, 35.99"}'::jsonb),
('mc:case scenario: jd, a 59-year-old female, chief executive officer of a telecommunications office, whose height is 5’5” and weight is 93 kg was admitted in the hospital due to a transient ischemic attack (tia). using the data on the height and weight, her bmi is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'case scenario: jd, a 59-year-old female, chief executive officer of a telecommunications office, whose height is 5’5” and weight is 93 kg was admitted in the hospital due to a transient ischemic attack (tia). using the data on the height and weight, her bmi is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"34.1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the Body Mass Index (BMI), use the standard formula: BMI = Weight (kg) / Height (m²).\n1. Convert Height to Meters:\n\t• 5 feet 5 inches = 65 inches\n\t• 65 inches × 0.0254 = 1.651 meters\n2. Calculate Height Squared:\n\t• 1.651 x 1.651 = 2.7258\n3. Calculate BMI:\n\t• BMI} = 93 / 2.7258 = 34.118 ~ 34.1 kg/m²","whyWrongChoices":"Alternative options: 35, 34.5, 35.99"}'::jsonb),
('mc:the following are the criteria for determining whether a food is spoiled, except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are the criteria for determining whether a food is spoiled, except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To classify a food as \"unspoiled\" or acceptable, it must satisfy all three of the positive benchmarks listed in options A, B, and C. Therefore, none of them are exceptions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To classify a food as \"unspoiled\" or acceptable, it must satisfy all three of the positive benchmarks listed in options A, B, and C. Therefore, none of them are exceptions.","whyWrongChoices":"Alternative options: Freedom from objectable, but not unsafe, contaminants, Freedom from decomposition resulting from enzymatic reactions inherent in the food or reactions between the food and its environment or decomposition from microbial growth, Freedom from physical damage"}'::jsonb),
('mc:case scenario: jd, a 59 year old, female, chief executive officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a bmi (body mass index) was admitted in the hospital due to a tia which stands for jd’s bmi is classified as:::obese class 1', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'case scenario: jd, a 59 year old, female, chief executive officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a bmi (body mass index) was admitted in the hospital due to a tia which stands for jd’s bmi is classified as', 'Obese Class 1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To classify JD''s BMI, we first must compute it using the standard metric formula: BMI = Weight (kg) / Height (m²).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Obese Class 1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To classify JD''s BMI, we first must compute it using the standard metric formula: BMI = Weight (kg) / Height (m²).\n\n1. Convert Height to Meters:\n\t• 5 feet 5 inches = 65 inches\n\t• 65 inches × 0.0254 = 1.651 meters\n2. Calculate BMI:\n\t• BMI = 93 ÷ (1.651)²\n\t• BMI = 93 ÷ 2.726\n\t• BMI = 34.12\n\nUnder the official WHO BMI Classification Guidelines, the cut-off ranges are as follows:\n• Overweight: 25.0 to 29.9\n• Obese Class 1: 30.0 to 34.9\n• Obese Class 2: 35.0 to 39.9\n• Obese Class 3 (Morbid Obesity): 40.0 or higher\n\nBecause JD''s calculated BMI is 34.12, it sits firmly inside the 30.0 to 34.9 range, making it Obese Class 1 by global definitions.","whyWrongChoices":"Alternative options: Overweight, Obese Class 2, Morbidly Obese"}'::jsonb),
('mc:case scenario: jd, a 59 year old, female, chief executive officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a bmi (body mass index) was admitted in the hospital due to a tia which stands for jd’s bmi is classified as:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'case scenario: jd, a 59 year old, female, chief executive officer of a telecommunications office whose height is 5’5” and weight of 93 kg has a bmi (body mass index) was admitted in the hospital due to a tia which stands for jd’s bmi is classified as', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To classify JD''s BMI, we first must compute it using the standard metric formula: BMI = Weight (kg) / Height (m²).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Obese Class 1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To classify JD''s BMI, we first must compute it using the standard metric formula: BMI = Weight (kg) / Height (m²).\n\n1. Convert Height to Meters:\n\t• 5 feet 5 inches = 65 inches\n\t• 65 inches × 0.0254 = 1.651 meters\n2. Calculate BMI:\n\t• BMI = 93 ÷ (1.651)²\n\t• BMI = 93 ÷ 2.726\n\t• BMI = 34.12\n\nUnder the official WHO BMI Classification Guidelines, the cut-off ranges are as follows:\n• Overweight: 25.0 to 29.9\n• Obese Class 1: 30.0 to 34.9\n• Obese Class 2: 35.0 to 39.9\n• Obese Class 3 (Morbid Obesity): 40.0 or higher\n\nBecause JD''s calculated BMI is 34.12, it sits firmly inside the 30.0 to 34.9 range, making it Obese Class 1 by global definitions.","whyWrongChoices":"Alternative options: Overweight, Obese Class 2, Morbidly Obese"}'::jsonb),
('mc:case scenario: jd, a 59-year-old female chief executive officer of a telecommunications office who is 5’5” tall and weighs 93 kg, was recently admitted to the hospital due to a transient ischemic attack (tia). using the ndap formula, jd’s recommended body weight is:::57.27 kg', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'case scenario: jd, a 59-year-old female chief executive officer of a telecommunications office who is 5’5” tall and weighs 93 kg, was recently admitted to the hospital due to a transient ischemic attack (tia). using the ndap formula, jd’s recommended body weight is', '57.27 kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The NDAP formula for females is 106 lbs for the first  5 feet (60 inches) of height ± 4 lbs for every inch above or below 5 feet.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"57.27 kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The NDAP formula for females is 106 lbs for the first  5 feet (60 inches) of height ± 4 lbs for every inch above or below 5 feet.\n\n1. Calculate the height allowance.\n5''5\" tall = 106 lbs + (5 inches x 4 lbs/inch) = 126 lbs\n\n2. Convert pounds to kilograms.\n126 lbs ÷ 2.2 = 57.27 kg","whyWrongChoices":"Alternative options: 50 kg, 65 kg, 58.59 kg"}'::jsonb),
