('mc:sentence a. gelatin is soluble in cold water sentence b. gelatin is immediately poured in boiling water during cooking.:::both sentences are incorrect', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. gelatin is soluble in cold water sentence b. gelatin is immediately poured in boiling water during cooking.', 'Both sentences are incorrect', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Gelatin absorbs cold water and blooms but is not truly dissolved simply by cold water. It should also not be immediately boiled; excessive heat can reduce its gelling strength.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Both sentences are incorrect\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Gelatin absorbs cold water and blooms but is not truly dissolved simply by cold water. It should also not be immediately boiled; excessive heat can reduce its gelling strength.","whyWrongChoices":"Alternative options: Sentence A is correct, Sentence B is correct, Both sentences are correct"}'::jsonb),
('mc:sentence a. fish contains aflatoxin which causes food intoxication. sentence b. aflatoxin is a neurotoxin.:::sentence b is correct', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sentence a. fish contains aflatoxin which causes food intoxication. sentence b. aflatoxin is a neurotoxin.', 'Sentence B is correct', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fish does not normally contain aflatoxin; aflatoxins are mycotoxins produced mainly by certain molds in susceptible commodities (Mycotoxin, elaborated by Aspergillus flavus) ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Sentence B is correct\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fish does not normally contain aflatoxin; aflatoxins are mycotoxins produced mainly by certain molds in susceptible commodities (Mycotoxin, elaborated by Aspergillus flavus) \n\nAflatoxins, particularly Aflatoxin B1, cause neurotoxicity by crossing the blood-brain barrier, triggering severe oxidative stress, and inducing brain cell death.","whyWrongChoices":"Alternative options: Sentence A is correct, Both sentences are correct, Both sentences are incorrect"}'::jsonb),
