('mc:example of fringe benefit:::christmas bonus', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'example of fringe benefit', 'Christmas bonus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Christmas bonus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.\n\nWhile regular pay covers your standard work hours, monetary perks like a Christmas bonus, profit sharing, gym memberships, or rice allowances are classic examples of fringe or de minimis benefits. Under Philippine labor and tax laws, discretionary year-end bonuses and small-value perks given for employee wellness or holiday celebrations fall directly into this category.","whyWrongChoices":"Alternative options: Promotion, Dayoff, Holiday off"}'::jsonb),
('mc:example of fringe benefit:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'example of fringe benefit', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Christmas bonus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A fringe benefit is any form of extra compensation provided by an employer to an employee supplemental to their regular basic salary or wages. They are designed to improve job satisfaction, motivation, and employee retention.\n\nWhile regular pay covers your standard work hours, monetary perks like a Christmas bonus, profit sharing, gym memberships, or rice allowances are classic examples of fringe or de minimis benefits. Under Philippine labor and tax laws, discretionary year-end bonuses and small-value perks given for employee wellness or holiday celebrations fall directly into this category.","whyWrongChoices":"Alternative options: Promotion, Dayoff, Holiday off"}'::jsonb),
('mc:type of menu usually used in schools, hospitals, and institutions is called::::none of the above', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'type of menu usually used in schools, hospitals, and institutions is called:', 'None of the above', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Schools, hospitals, and institutional facilities primarily use a cycle menu (or cyclic menu).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"None of the above\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Schools, hospitals, and institutional facilities primarily use a cycle menu (or cyclic menu).","whyWrongChoices":"Alternative options: Table d'' Hote, Single use, Du jour"}'::jsonb),
