('mc:a no.2 can of fruit juice contains:::2 ¼ cups', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a no.2 can of fruit juice contains', '2 ¼ cups', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard Food Service and Institutional Management measurements, a No. 2 can has the following characteristics:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 ¼ cups\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard Food Service and Institutional Management measurements, a No. 2 can has the following characteristics:\n• Weight/Volume: Approximately 20 ounces (1 lb 4 oz)\n• Volume in Cups: Approximately 2 ½ cups (2.5 cups)\n• Average Servings: Offers about 5 servings of 4 ounces each.\n\nOther Common Can Sizes for Comparison:\n\n• No. 1 can: Contains about 1⅓ cups\n• No. 2 ½ can: Contains about 3 ½ cups\n• No. 3 can: Contains about 4 to 5 ¾ cups (often used for single-strength juices)\n• No. 10 can: Contains about 12 to 13 cups (the massive institutional standard can)","whyWrongChoices":"Alternative options: 1 cup, 1 gallon, 2 gallons"}'::jsonb),
('mc:a no.2 can of fruit juice contains:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a no.2 can of fruit juice contains', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In standard Food Service and Institutional Management measurements, a No. 2 can has the following characteristics:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 ¼ cups\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In standard Food Service and Institutional Management measurements, a No. 2 can has the following characteristics:\n• Weight/Volume: Approximately 20 ounces (1 lb 4 oz)\n• Volume in Cups: Approximately 2 ½ cups (2.5 cups)\n• Average Servings: Offers about 5 servings of 4 ounces each.\n\nOther Common Can Sizes for Comparison:\n\n• No. 1 can: Contains about 1⅓ cups\n• No. 2 ½ can: Contains about 3 ½ cups\n• No. 3 can: Contains about 4 to 5 ¾ cups (often used for single-strength juices)\n• No. 10 can: Contains about 12 to 13 cups (the massive institutional standard can)","whyWrongChoices":"Alternative options: 1 cup, 1 gallon, 2 gallons"}'::jsonb),
('mc:appropriate storage temperature for ripe fruits (except bananas).:::50ºf', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'appropriate storage temperature for ripe fruits (except bananas).', '50ºF', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"50ºF (approx. 10ºC) falls perfectly into the \"cool storage\" range (40–55°F) used to slow down the respiration and ripening process of many ripe, perishable fruits without causing chilling injuries or freezing.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"50ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"50ºF (approx. 10ºC) falls perfectly into the \"cool storage\" range (40–55°F) used to slow down the respiration and ripening process of many ripe, perishable fruits without causing chilling injuries or freezing.\n\n20ºF is well below freezing and would destroy the cellular structure of the fruit, ruining its texture.\n\n50ºC (122ºF) is extremely hot and would cook the fruit, leading to rapid decay.\n\nRoom temperature accelerates spoiling and rot once a fruit is already fully ripe.","whyWrongChoices":"Alternative options: 20ºF, 50ºC, Roomtemperature"}'::jsonb),
('mc:appropriate storage temperature for ripe fruits (except bananas).:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'appropriate storage temperature for ripe fruits (except bananas).', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"50ºF (approx. 10ºC) falls perfectly into the \"cool storage\" range (40–55°F) used to slow down the respiration and ripening process of many ripe, perishable fruits without causing chilling injuries or freezing.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"50ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"50ºF (approx. 10ºC) falls perfectly into the \"cool storage\" range (40–55°F) used to slow down the respiration and ripening process of many ripe, perishable fruits without causing chilling injuries or freezing.\n\n20ºF is well below freezing and would destroy the cellular structure of the fruit, ruining its texture.\n\n50ºC (122ºF) is extremely hot and would cook the fruit, leading to rapid decay.\n\nRoom temperature accelerates spoiling and rot once a fruit is already fully ripe.","whyWrongChoices":"Alternative options: 20ºF, 50ºC, Roomtemperature"}'::jsonb),
('mc:minimum internal cooking temperature of pork chop:::145ºf', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'minimum internal cooking temperature of pork chop', '145ºF', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the USDA Safe Minimum Internal Temperature Chart, fresh whole muscle cuts of pork—including pork chops, pork roasts, and pork loins—must be cooked to a minimum internal temperature of 145°F (63°C).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"145ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the USDA Safe Minimum Internal Temperature Chart, fresh whole muscle cuts of pork—including pork chops, pork roasts, and pork loins—must be cooked to a minimum internal temperature of 145°F (63°C).\n\nTo safely hit this baseline, you must also allow the meat to rest for at least 3 minutes after removing it from the heat source. During this resting period, the internal temperature remains constant or continues to rise slightly, destroying harmful foodborne pathogens while keeping the meat juicy and tender.\n\n• 155ºF: This is the standard minimum internal cooking temperature for ground meats (such as ground pork, ground beef, or sausage) under regulatory food safety frameworks like ServSafe. Ground meats require a higher temperature because the grinding process distributes surface bacteria throughout the meat.\n• 165ºF: This is the required safety threshold for all poultry (chicken, turkey, duck), stuffed meats, and reheated leftovers.\n• 170ºF: This is an older, outdated standard for pork. Cooking modern, lean pork to 170°F results in a dry, tough, and overcooked piece of meat.","whyWrongChoices":"Alternative options: 170ºF, 155ºF, 165ºF"}'::jsonb),
('mc:in the satellite food production system,:::food procurement and pre-preparation are centralized, but final preparation and service are decentralized', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in the satellite food production system,', 'Food procurement and pre-preparation are
 centralized, but final preparation and service
 are decentralized', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All bulk food procurement, inventory storage, and primary pre-preparation (and often major cooking) are handled entirely at a single, heavily equipped central facility.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food procurement and pre-preparation are\n centralized, but final preparation and service\n are decentralized\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All bulk food procurement, inventory storage, and primary pre-preparation (and often major cooking) are handled entirely at a single, heavily equipped central facility.\n\nThe prepared or semi-prepared menu items are then systematically transported to separate, remote satellite units (such as individual schools, hospitals, or smaller branches). These decentralized satellite sites handle the final preparation (like rethermalizing or portioning) and immediate service to the consumers.","whyWrongChoices":"Alternative options: All the centers are decentralized, Food is prepared and then frozen until needed, Food procurement and pre-preparation are centralized, but final preparation and service are decentralized"}'::jsonb),
('mc:minimum internal cooking temperature of pork chop:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'minimum internal cooking temperature of pork chop', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the USDA Safe Minimum Internal Temperature Chart, fresh whole muscle cuts of pork—including pork chops, pork roasts, and pork loins—must be cooked to a minimum internal temperature of 145°F (63°C).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"145ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the USDA Safe Minimum Internal Temperature Chart, fresh whole muscle cuts of pork—including pork chops, pork roasts, and pork loins—must be cooked to a minimum internal temperature of 145°F (63°C).\n\nTo safely hit this baseline, you must also allow the meat to rest for at least 3 minutes after removing it from the heat source. During this resting period, the internal temperature remains constant or continues to rise slightly, destroying harmful foodborne pathogens while keeping the meat juicy and tender.\n\n• 155ºF: This is the standard minimum internal cooking temperature for ground meats (such as ground pork, ground beef, or sausage) under regulatory food safety frameworks like ServSafe. Ground meats require a higher temperature because the grinding process distributes surface bacteria throughout the meat.\n• 165ºF: This is the required safety threshold for all poultry (chicken, turkey, duck), stuffed meats, and reheated leftovers.\n• 170ºF: This is an older, outdated standard for pork. Cooking modern, lean pork to 170°F results in a dry, tough, and overcooked piece of meat.","whyWrongChoices":"Alternative options: 170ºF, 155ºF, 165ºF"}'::jsonb),
('mc:minimum internal cooking temperature of salmon:::145ºf', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'minimum internal cooking temperature of salmon', '145ºF', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Salmon: 145°F (63°C) or cook until the flesh is opaque and flakes easily with a fork.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"145ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Salmon: 145°F (63°C) or cook until the flesh is opaque and flakes easily with a fork.\n\n• 165ºF: The safe baseline for all poultry (chicken, turkey) and leftovers.\n• 155ºF: The standard food safety threshold often taught for ground meats (like pork or beef) under regional food codes before the general public safety chart rounds it to 160°F.\n• 170ºF: The internal temperature indicator for completely well-done beef or game meat.","whyWrongChoices":"Alternative options: 170ºF, 155ºF, 165ºF"}'::jsonb),
('mc:minimum internal cooking temperature of salmon:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'minimum internal cooking temperature of salmon', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Salmon: 145°F (63°C) or cook until the flesh is opaque and flakes easily with a fork.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"145ºF\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Salmon: 145°F (63°C) or cook until the flesh is opaque and flakes easily with a fork.\n\n• 165ºF: The safe baseline for all poultry (chicken, turkey) and leftovers.\n• 155ºF: The standard food safety threshold often taught for ground meats (like pork or beef) under regional food codes before the general public safety chart rounds it to 160°F.\n• 170ºF: The internal temperature indicator for completely well-done beef or game meat.","whyWrongChoices":"Alternative options: 170ºF, 155ºF, 165ºF"}'::jsonb),
('mc:the total raw food cost of a recipe yielding 50 serving portions is ₱200. to keep raw food costs at 40%, the selling price per portion should be::::₱10.00', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the total raw food cost of a recipe yielding 50 serving portions is ₱200. to keep raw food costs at 40%, the selling price per portion should be:', '₱10.00', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food cost per serving is ₱200 ÷ 50 = ₱4. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"₱10.00\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food cost per serving is ₱200 ÷ 50 = ₱4. \n\nIf ₱4 represents 40% of selling price, selling price = ₱4 ÷ 0.40 = ₱10.","whyWrongChoices":"Alternative options: ₱4.00, ₱8.00, ₱80.00"}'::jsonb),
('mc:the total raw food cost of a recipe yielding 50 serving portions is ₱200. to keep raw food costs at 40%, the selling price per portion should be::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the total raw food cost of a recipe yielding 50 serving portions is ₱200. to keep raw food costs at 40%, the selling price per portion should be:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Food cost per serving is ₱200 ÷ 50 = ₱4. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"₱10.00\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Food cost per serving is ₱200 ÷ 50 = ₱4. \n\nIf ₱4 represents 40% of selling price, selling price = ₱4 ÷ 0.40 = ₱10.","whyWrongChoices":"Alternative options: ₱4.00, ₱8.00, ₱80.00"}'::jsonb),
('mc:this equipment is useful when food production and service areas are on separate floors.:::dumbwaiter', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this equipment is useful when food production and service areas are on separate floors.', 'Dumbwaiter', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A dumbwaiter is a small, specialized freight elevator or lift system designed to transport food, dishes, and kitchen supplies vertically between multiple floors of a building.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dumbwaiter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A dumbwaiter is a small, specialized freight elevator or lift system designed to transport food, dishes, and kitchen supplies vertically between multiple floors of a building.\n\nIn hospitality, hospitals, and multi-story restaurant settings, the main food production kitchen is often located in the basement or ground floor, while the service or dining areas are located on upper levels. A dumbwaiter allows hot meals to be quickly and safely dispatched to service stations on separate floors without relying on staff manually carrying heavy trays up and down stairs or taking up passenger elevators.\n\n• Hood: A kitchen exhaust ventilation canopy positioned directly above cooking equipment to remove steam, smoke, heat, and airborne grease.\n• Doilies: Small, decorative, ornamental mats made of paper, lace, or fabric used in food presentation (such as being placed on a saucer beneath a coffee cup or a dessert bowl).\n• Bain-marie: A specialized water bath system or hot well table used to hold, warm, or gently cook hot foods at a stable temperature in production or buffet service lines. It does not move food across different floors.","whyWrongChoices":"Alternative options: Doilies, Hood, Bainmarie"}'::jsonb),
('mc:this equipment is useful when food production and service areas are on separate floors.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'this equipment is useful when food production and service areas are on separate floors.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A dumbwaiter is a small, specialized freight elevator or lift system designed to transport food, dishes, and kitchen supplies vertically between multiple floors of a building.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Dumbwaiter\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A dumbwaiter is a small, specialized freight elevator or lift system designed to transport food, dishes, and kitchen supplies vertically between multiple floors of a building.\n\nIn hospitality, hospitals, and multi-story restaurant settings, the main food production kitchen is often located in the basement or ground floor, while the service or dining areas are located on upper levels. A dumbwaiter allows hot meals to be quickly and safely dispatched to service stations on separate floors without relying on staff manually carrying heavy trays up and down stairs or taking up passenger elevators.\n\n• Hood: A kitchen exhaust ventilation canopy positioned directly above cooking equipment to remove steam, smoke, heat, and airborne grease.\n• Doilies: Small, decorative, ornamental mats made of paper, lace, or fabric used in food presentation (such as being placed on a saucer beneath a coffee cup or a dessert bowl).\n• Bain-marie: A specialized water bath system or hot well table used to hold, warm, or gently cook hot foods at a stable temperature in production or buffet service lines. It does not move food across different floors.","whyWrongChoices":"Alternative options: Doilies, Hood, Bainmarie"}'::jsonb),
('mc:bacteria commonly found in shellfish from contaminated water that can cause gastroenteritis or primary septicemia among patients with cirrhosis or diabetes.:::vibrio vulnificus', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'bacteria commonly found in shellfish from contaminated water that can cause gastroenteritis or primary septicemia among patients with cirrhosis or diabetes.', 'Vibrio vulnificus', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vibrio vulnificus is a halophilic (salt-loving), Gram-negative bacterium naturally found in warm coastal and brackish waters. It frequently contaminates filter-feeding shellfish like oysters and clams.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vibrio vulnificus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vibrio vulnificus is a halophilic (salt-loving), Gram-negative bacterium naturally found in warm coastal and brackish waters. It frequently contaminates filter-feeding shellfish like oysters and clams.\n\nWhile it can cause mild gastroenteritis in healthy individuals, it poses an extreme danger to individuals with underlying health conditions—especially liver cirrhosis, chronic liver disease, or diabetes.\n\nIn these high-risk patients, eating contaminated raw/undercooked seafood can allow the bacteria to cross the intestinal wall into the bloodstream. This triggers primary septicemia (blood poisoning), which progresses rapidly into septic shock, severe blistering skin lesions (hemorrhagic bullae), and multiorgan failure. It carries a staggering mortality rate of over 50%.\n\n• Listeria monocytogenes: Known for contaminating deli meats, unpasteurized milk, and soft cheeses. While it causes severe illness in pregnant women, newborns, and immunocompromised individuals (listeriosis), it is not a hallmark cause of primary shellfish-borne septicemia in cirrhotic patients.\n• Shigella spp: A bacterium primarily transmitted via the fecal-oral route through contaminated food or water. It causes bacillary dysentery (severe diarrhea with blood/mucus) but does not typically present as marine-acquired septicemia.\n• Hepatitis A: A virus (not a bacterium) that can be contracted from shellfish harvested from sewage-polluted waters. It causes acute liver inflammation (infectious hepatitis) rather than bacterial gastroenteritis or rapid septic shock.","whyWrongChoices":"Alternative options: Shigella spp, Hepatitis A, Listeria monocytogenes"}'::jsonb),
('mc:bacteria commonly found in shellfish from contaminated water that can cause gastroenteritis or primary septicemia among patients with cirrhosis or diabetes.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'bacteria commonly found in shellfish from contaminated water that can cause gastroenteritis or primary septicemia among patients with cirrhosis or diabetes.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Vibrio vulnificus is a halophilic (salt-loving), Gram-negative bacterium naturally found in warm coastal and brackish waters. It frequently contaminates filter-feeding shellfish like oysters and clams.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Vibrio vulnificus\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Vibrio vulnificus is a halophilic (salt-loving), Gram-negative bacterium naturally found in warm coastal and brackish waters. It frequently contaminates filter-feeding shellfish like oysters and clams.\n\nWhile it can cause mild gastroenteritis in healthy individuals, it poses an extreme danger to individuals with underlying health conditions—especially liver cirrhosis, chronic liver disease, or diabetes.\n\nIn these high-risk patients, eating contaminated raw/undercooked seafood can allow the bacteria to cross the intestinal wall into the bloodstream. This triggers primary septicemia (blood poisoning), which progresses rapidly into septic shock, severe blistering skin lesions (hemorrhagic bullae), and multiorgan failure. It carries a staggering mortality rate of over 50%.\n\n• Listeria monocytogenes: Known for contaminating deli meats, unpasteurized milk, and soft cheeses. While it causes severe illness in pregnant women, newborns, and immunocompromised individuals (listeriosis), it is not a hallmark cause of primary shellfish-borne septicemia in cirrhotic patients.\n• Shigella spp: A bacterium primarily transmitted via the fecal-oral route through contaminated food or water. It causes bacillary dysentery (severe diarrhea with blood/mucus) but does not typically present as marine-acquired septicemia.\n• Hepatitis A: A virus (not a bacterium) that can be contracted from shellfish harvested from sewage-polluted waters. It causes acute liver inflammation (infectious hepatitis) rather than bacterial gastroenteritis or rapid septic shock.","whyWrongChoices":"Alternative options: Shigella spp, Hepatitis A, Listeria monocytogenes"}'::jsonb),
('mc:in the satellite food production system,:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'in the satellite food production system,', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"All bulk food procurement, inventory storage, and primary pre-preparation (and often major cooking) are handled entirely at a single, heavily equipped central facility.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Food procurement and pre-preparation are\n centralized, but final preparation and service\n are decentralized\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"All bulk food procurement, inventory storage, and primary pre-preparation (and often major cooking) are handled entirely at a single, heavily equipped central facility.\n\nThe prepared or semi-prepared menu items are then systematically transported to separate, remote satellite units (such as individual schools, hospitals, or smaller branches). These decentralized satellite sites handle the final preparation (like rethermalizing or portioning) and immediate service to the consumers.","whyWrongChoices":"Alternative options: All the centers are decentralized, Food is prepared and then frozen until needed, Food procurement and pre-preparation are centralized, but final preparation and service are decentralized"}'::jsonb),
('mc:when fish fillet is on the menu, you need fish that will be::::deboned and sliced', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'when fish fillet is on the menu, you need fish that will be:', 'deboned and sliced', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Fish fillets should be boneless and cut into appropriate portions or slices because a fillet is a boneless section of fish flesh.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"deboned and sliced\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Fish fillets should be boneless and cut into appropriate portions or slices because a fillet is a boneless section of fish flesh.","whyWrongChoices":"Alternative options: served whole, flaked, stuffed"}'::jsonb)
