INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:a recommended dietary allowance (rda) represents the::::average amount of a nutrient considered adequate to meet the nutrient needs of all healthy people', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a recommended dietary allowance (rda) represents the:', 'Average amount of a nutrient considered adequate to meet the nutrient needs of all healthy people', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Recommended Dietary Allowance (RDA) is the average daily nutrient intake level that is sufficient to meet the nutrient requirements of nearly all (97–98%) healthy individuals in a particular age, sex, and life-stage group. It is primarily used as a goal for planning nutritionally adequate diets for individuals. Importantly, the RDA is not literally enough for 100% of people, because individual nutrient requirements vary. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Average amount of a nutrient considered adequate to meet the nutrient needs of all healthy people\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Recommended Dietary Allowance (RDA) is the average daily nutrient intake level that is sufficient to meet the nutrient requirements of nearly all (97–98%) healthy individuals in a particular age, sex, and life-stage group. It is primarily used as a goal for planning nutritionally adequate diets for individuals. Importantly, the RDA is not literally enough for 100% of people, because individual nutrient requirements vary. \n\nThe RDA is derived from the Estimated Average Requirement (EAR). When the requirement distribution is approximately normal, the RDA is generally set at the EAR plus two standard deviations, thereby covering the requirements of approximately 97–98% of healthy individuals. In clinical and community nutrition practice, RDAs are useful for planning diets, while the EAR is generally more appropriate for assessing the adequacy of nutrient intakes in groups.","whyWrongChoices":"Alternative options: Highest amount of a nutrient that appears safe for most healthy people, Average amount of a nutrient that will maintain a specific biochemical or physiological function in half of the population, Lowest amount of a nutrient considered adequate to meet the nutrient needs of all healthy people"}'::jsonb),
('mc:when the body''s glycogen stores become depleted during fasting, the body will synthesize glucose primarily from::::glucogenic amino acid', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'when the body''s glycogen stores become depleted during fasting, the body will synthesize glucose primarily from:', 'Glucogenic amino acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When the body''s liver glycogen stores are completely depleted during an extended fast (typically after 12 to 24 hours), blood glucose levels must be strictly maintained to supply glucose-dependent organs like the brain. The liver shifts completely to gluconeogenesis—the de novo creation of glucose from non-carbohydrate precursors.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucogenic amino acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When the body''s liver glycogen stores are completely depleted during an extended fast (typically after 12 to 24 hours), blood glucose levels must be strictly maintained to supply glucose-dependent organs like the brain. The liver shifts completely to gluconeogenesis—the de novo creation of glucose from non-carbohydrate precursors.\n\nMuscle tissue is broken down via proteolysis, releasing amino acids into the bloodstream. Glucogenic amino acids (such as alanine and glutamine) are transported to the liver, where their carbon skeletons are converted into pyruvate or TCA cycle intermediates, directly fueling the pathway to synthesize new glucose.\n\n• Fatty acids: Even though adipose tissue releases abundant free fatty acids during fasting, the catabolism of even-chain fatty acids produces acetyl-CoA. In humans, acetyl-CoA cannot be converted into pyruvate because the pyruvate dehydrogenase reaction is irreversible, meaning fatty acids cannot be used to synthesize glucose. (Note: Only the tiny glycerol backbone of a triglyceride can enter gluconeogenesis, not the fatty acid chains themselves).\n• Ketone bodies: Ketone bodies (such as acetoacetate and beta-hydroxybutyrate) are synthesized from fatty acid-derived acetyl-CoA in the liver. They serve as an alternative fuel source for the brain and heart during starvation to conserve protein, but they cannot be chemically reversed back into glucose.\n• Cholesterol: Cholesterol is a structural component of cell membranes and a precursor for steroid hormones and bile acids, but it plays absolutely no role in energy production or glucose synthesis.","whyWrongChoices":"Alternative options: Fatty acid, Ketone bodies, Cholesterol"}'::jsonb),
('mc:when the body''s glycogen stores become depleted during fasting, the body will synthesize glucose primarily from::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'when the body''s glycogen stores become depleted during fasting, the body will synthesize glucose primarily from:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When the body''s liver glycogen stores are completely depleted during an extended fast (typically after 12 to 24 hours), blood glucose levels must be strictly maintained to supply glucose-dependent organs like the brain. The liver shifts completely to gluconeogenesis—the de novo creation of glucose from non-carbohydrate precursors.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucogenic amino acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When the body''s liver glycogen stores are completely depleted during an extended fast (typically after 12 to 24 hours), blood glucose levels must be strictly maintained to supply glucose-dependent organs like the brain. The liver shifts completely to gluconeogenesis—the de novo creation of glucose from non-carbohydrate precursors.\n\nMuscle tissue is broken down via proteolysis, releasing amino acids into the bloodstream. Glucogenic amino acids (such as alanine and glutamine) are transported to the liver, where their carbon skeletons are converted into pyruvate or TCA cycle intermediates, directly fueling the pathway to synthesize new glucose.\n\n• Fatty acids: Even though adipose tissue releases abundant free fatty acids during fasting, the catabolism of even-chain fatty acids produces acetyl-CoA. In humans, acetyl-CoA cannot be converted into pyruvate because the pyruvate dehydrogenase reaction is irreversible, meaning fatty acids cannot be used to synthesize glucose. (Note: Only the tiny glycerol backbone of a triglyceride can enter gluconeogenesis, not the fatty acid chains themselves).\n• Ketone bodies: Ketone bodies (such as acetoacetate and beta-hydroxybutyrate) are synthesized from fatty acid-derived acetyl-CoA in the liver. They serve as an alternative fuel source for the brain and heart during starvation to conserve protein, but they cannot be chemically reversed back into glucose.\n• Cholesterol: Cholesterol is a structural component of cell membranes and a precursor for steroid hormones and bile acids, but it plays absolutely no role in energy production or glucose synthesis.","whyWrongChoices":"Alternative options: Fatty acid, Ketone bodies, Cholesterol"}'::jsonb),
('mc:role of villi and microvilli in the small intestine is to::::increase the surface area for nutrient absorption', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'role of villi and microvilli in the small intestine is to:', 'Increase the surface area for nutrient absorption', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The villi and microvilli are specialized structures lining the small intestine that greatly increase the surface area available for nutrient absorption. Villi are finger-like projections of the intestinal mucosa, while microvilli are microscopic projections of the apical membrane of enterocytes that form the brush border. Together, they maximize contact between digested nutrients and absorptive epithelial cells, making the small intestine highly efficient at nutrient absorption. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Increase the surface area for nutrient absorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The villi and microvilli are specialized structures lining the small intestine that greatly increase the surface area available for nutrient absorption. Villi are finger-like projections of the intestinal mucosa, while microvilli are microscopic projections of the apical membrane of enterocytes that form the brush border. Together, they maximize contact between digested nutrients and absorptive epithelial cells, making the small intestine highly efficient at nutrient absorption. \n\nThe villi also contain blood capillaries and a central lymphatic vessel called a lacteal. Water-soluble nutrients such as glucose and amino acids generally enter the blood capillaries, whereas most dietary lipids are incorporated into chylomicrons and enter the lymphatic system through the lacteals. This structural organization is important in understanding why the small intestine is the principal site of nutrient absorption.","whyWrongChoices":"Alternative options: Produce all the enzymes needed for digestion, Slow down the movement of food, Secrete water in the chyme"}'::jsonb),
('mc:role of villi and microvilli in the small intestine is to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'role of villi and microvilli in the small intestine is to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The villi and microvilli are specialized structures lining the small intestine that greatly increase the surface area available for nutrient absorption. Villi are finger-like projections of the intestinal mucosa, while microvilli are microscopic projections of the apical membrane of enterocytes that form the brush border. Together, they maximize contact between digested nutrients and absorptive epithelial cells, making the small intestine highly efficient at nutrient absorption. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Increase the surface area for nutrient absorption\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The villi and microvilli are specialized structures lining the small intestine that greatly increase the surface area available for nutrient absorption. Villi are finger-like projections of the intestinal mucosa, while microvilli are microscopic projections of the apical membrane of enterocytes that form the brush border. Together, they maximize contact between digested nutrients and absorptive epithelial cells, making the small intestine highly efficient at nutrient absorption. \n\nThe villi also contain blood capillaries and a central lymphatic vessel called a lacteal. Water-soluble nutrients such as glucose and amino acids generally enter the blood capillaries, whereas most dietary lipids are incorporated into chylomicrons and enter the lymphatic system through the lacteals. This structural organization is important in understanding why the small intestine is the principal site of nutrient absorption.","whyWrongChoices":"Alternative options: Produce all the enzymes needed for digestion, Slow down the movement of food, Secrete water in the chyme"}'::jsonb),
('mc:positive nitrogen balance can be observed during::::pregnancy', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'positive nitrogen balance can be observed during:', 'Pregnancy', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nitrogen balance reflects the relationship between nitrogen intake, primarily from dietary protein, and nitrogen losses, mainly through urinary nitrogen excretion. Positive nitrogen balance occurs when nitrogen intake exceeds nitrogen losses, indicating that the body is retaining protein and synthesizing new tissue. This occurs during periods of growth and tissue building, including pregnancy, childhood, adolescence, and recovery from severe nutritional depletion. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pregnancy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nitrogen balance reflects the relationship between nitrogen intake, primarily from dietary protein, and nitrogen losses, mainly through urinary nitrogen excretion. Positive nitrogen balance occurs when nitrogen intake exceeds nitrogen losses, indicating that the body is retaining protein and synthesizing new tissue. This occurs during periods of growth and tissue building, including pregnancy, childhood, adolescence, and recovery from severe nutritional depletion. \n\nDuring pregnancy, positive nitrogen balance supports the synthesis of maternal tissues and the growth of the fetus, placenta, and maternal blood volume and other tissues. In contrast, fever, surgery, and shock are generally associated with physiological stress that increases protein catabolism and nitrogen losses, resulting in negative nitrogen balance, particularly when the stress response is significant or prolonged.","whyWrongChoices":"Alternative options: Fever, Surgery, Shock"}'::jsonb),
('mc:positive nitrogen balance can be observed during::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'positive nitrogen balance can be observed during:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Nitrogen balance reflects the relationship between nitrogen intake, primarily from dietary protein, and nitrogen losses, mainly through urinary nitrogen excretion. Positive nitrogen balance occurs when nitrogen intake exceeds nitrogen losses, indicating that the body is retaining protein and synthesizing new tissue. This occurs during periods of growth and tissue building, including pregnancy, childhood, adolescence, and recovery from severe nutritional depletion. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pregnancy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Nitrogen balance reflects the relationship between nitrogen intake, primarily from dietary protein, and nitrogen losses, mainly through urinary nitrogen excretion. Positive nitrogen balance occurs when nitrogen intake exceeds nitrogen losses, indicating that the body is retaining protein and synthesizing new tissue. This occurs during periods of growth and tissue building, including pregnancy, childhood, adolescence, and recovery from severe nutritional depletion. \n\nDuring pregnancy, positive nitrogen balance supports the synthesis of maternal tissues and the growth of the fetus, placenta, and maternal blood volume and other tissues. In contrast, fever, surgery, and shock are generally associated with physiological stress that increases protein catabolism and nitrogen losses, resulting in negative nitrogen balance, particularly when the stress response is significant or prolonged.","whyWrongChoices":"Alternative options: Fever, Surgery, Shock"}'::jsonb),
('mc:vessels where the exchange of oxygen, nutrients and waste products take place.:::capillaries', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'vessels where the exchange of oxygen, nutrients and waste products take place.', 'Capillaries', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Capillaries are the smallest and most numerous blood vessels in the human body, serving as the functional \"transfer stations\" connecting arterioles to venules.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Capillaries\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Capillaries are the smallest and most numerous blood vessels in the human body, serving as the functional \"transfer stations\" connecting arterioles to venules.\n\nUnlike thick, muscular arteries or larger veins, the walls of capillaries are only one cell layer thick, composed entirely of a single layer of endothelial cells. This extremely thin barrier allows oxygen, glucose, amino acids, and vital hormones to readily pass from the bloodstream out into the surrounding body tissues via passive diffusion.\n\nAt the exact same time, cellular metabolic waste products (like carbon dioxide and urea) pass in the opposite direction—from the tissue cells back into the capillary lumen—so they can be safely transported away for filtration and excretion.\n\n• Veins: Veins have relatively thick walls with one-way valves designed exclusively to carry deoxygenated blood under low pressure back up toward the heart. Their thick structural layers prevent any direct transfer of oxygen or nutrients.\n• Arteries: Arteries have highly elastic, thick, muscular walls built to withstand the high-pressure surges of oxygenated blood being pumped directly away from the heart. Their dense structure completely prevents the diffusion of gases or nutrients.","whyWrongChoices":"Alternative options: Veins, Arteries, Veins and capillaries"}'::jsonb),
('mc:vessels where the exchange of oxygen, nutrients and waste products take place.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'vessels where the exchange of oxygen, nutrients and waste products take place.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Capillaries are the smallest and most numerous blood vessels in the human body, serving as the functional \"transfer stations\" connecting arterioles to venules.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Capillaries\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Capillaries are the smallest and most numerous blood vessels in the human body, serving as the functional \"transfer stations\" connecting arterioles to venules.\n\nUnlike thick, muscular arteries or larger veins, the walls of capillaries are only one cell layer thick, composed entirely of a single layer of endothelial cells. This extremely thin barrier allows oxygen, glucose, amino acids, and vital hormones to readily pass from the bloodstream out into the surrounding body tissues via passive diffusion.\n\nAt the exact same time, cellular metabolic waste products (like carbon dioxide and urea) pass in the opposite direction—from the tissue cells back into the capillary lumen—so they can be safely transported away for filtration and excretion.\n\n• Veins: Veins have relatively thick walls with one-way valves designed exclusively to carry deoxygenated blood under low pressure back up toward the heart. Their thick structural layers prevent any direct transfer of oxygen or nutrients.\n• Arteries: Arteries have highly elastic, thick, muscular walls built to withstand the high-pressure surges of oxygenated blood being pumped directly away from the heart. Their dense structure completely prevents the diffusion of gases or nutrients.","whyWrongChoices":"Alternative options: Veins, Arteries, Veins and capillaries"}'::jsonb),
('mc:during aerobic respiration, the decomposition of one glucose molecule produces::::38 molecules of atp', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'during aerobic respiration, the decomposition of one glucose molecule produces:', '38 molecules of ATP', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Using the traditional biochemical calculation commonly taught in nutrition and NDLE review materials, the complete aerobic oxidation of one glucose molecule produces a maximum of 38 ATP. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"38 molecules of ATP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Using the traditional biochemical calculation commonly taught in nutrition and NDLE review materials, the complete aerobic oxidation of one glucose molecule produces a maximum of 38 ATP. \n\nThis calculation assigns 3 ATP per NADH and 2 ATP per FADH₂. Glycolysis produces 2 ATP and 2 NADH; pyruvate oxidation produces 2 NADH; and the TCA cycle produces 2 ATP (or GTP), 6 NADH, and 2 FADH₂. Altogether, this gives 38 ATP per glucose under the traditional accounting system.","whyWrongChoices":"Alternative options: 40 molecules of ATP, 46 molecules of ATP, 48 molecules of ATP"}'::jsonb),
('mc:a mechanical soft diet includes::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a mechanical soft diet includes:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A mechanical soft diet consists of foods that are soft in texture and easy to chew and swallow, with modification of the texture achieved through methods such as chopping, grinding, mashing, or cooking foods until tender. The goal is to reduce the mechanical effort required to chew food while still allowing a broader variety of foods than a full-liquid or pureed diet. Depending on the patient''s needs, foods from a regular diet can be modified to achieve the appropriate texture. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"easy to chew foods, including foods in the regular diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A mechanical soft diet consists of foods that are soft in texture and easy to chew and swallow, with modification of the texture achieved through methods such as chopping, grinding, mashing, or cooking foods until tender. The goal is to reduce the mechanical effort required to chew food while still allowing a broader variety of foods than a full-liquid or pureed diet. Depending on the patient''s needs, foods from a regular diet can be modified to achieve the appropriate texture. \n\nA mechanical soft diet is therefore primarily defined by texture and ease of chewing, not by whether foods are liquid or low in fiber. It may be prescribed for patients with difficulty chewing because of dental problems, oral surgery, weakness, or other conditions affecting chewing. The specific texture should always be matched to the patient''s swallowing ability because a mechanical soft diet is not automatically appropriate for someone with dysphagia.","whyWrongChoices":"Alternative options: soft foods, liquid foods, low fiber foods"}'::jsonb),
('mc:the second stage of carbohydrate metabolism which takes place in the mitochondria and requires oxygen.:::oxidative decarboxylation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the second stage of carbohydrate metabolism which takes place in the mitochondria and requires oxygen.', 'Oxidative decarboxylation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In nutritional biochemistry and board examination frameworks, aerobic carbohydrate catabolism is traditionally classified into sequential stages:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oxidative decarboxylation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In nutritional biochemistry and board examination frameworks, aerobic carbohydrate catabolism is traditionally classified into sequential stages:\n\t1. Stage 1: Glycolysis (anaerobic process taking place entirely in the cytoplasm).\n\t2. Stage 2: Oxidative decarboxylation (the transition phase moving into the Krebs cycle/TCA cycle).\n\t3. Stage 3: Oxidative phosphorylation via the Electron Transport Chain (ETC).\n\nOnce glycolysis yields pyruvate in the cytosol, the pyruvate is actively transported into the mitochondria. Here, the pyruvate dehydrogenase complex carries out oxidative decarboxylation, converting pyruvate into Acetyl-CoA while stripping away carbon dioxide and generating NADH. Because this pathway feeds directly into the aerobic respiration chain, it strictly requires oxygen to proceed.\n\n• Glycolysis: This is the first stage of carbohydrate breakdown. It takes place in the anaerobic environment of the fluid cytoplasm (cytosol), meaning it does not require oxygen or mitochondrial machinery to function.\n• Hexose monophosphate shunt: Also known as the Pentose Phosphate Pathway (PPP), this is an alternative pathway parallel to glycolysis used to generate NADPH and ribose 5-phosphate. It does not serve as the primary second stage of energy-yielding glucose metabolism.\n• Oxidative phosphorylation: This is the final (third) stage of cellular respiration where the vast majority of ATP is structurally synthesized by ATP synthase along the inner mitochondrial membrane.","whyWrongChoices":"Alternative options: Oxidative phosphorylation, Hexose manophasphate shunt, Glycolysis"}'::jsonb),
('mc:the second stage of carbohydrate metabolism which takes place in the mitochondria and requires oxygen.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the second stage of carbohydrate metabolism which takes place in the mitochondria and requires oxygen.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In nutritional biochemistry and board examination frameworks, aerobic carbohydrate catabolism is traditionally classified into sequential stages:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Oxidative decarboxylation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In nutritional biochemistry and board examination frameworks, aerobic carbohydrate catabolism is traditionally classified into sequential stages:\n\t1. Stage 1: Glycolysis (anaerobic process taking place entirely in the cytoplasm).\n\t2. Stage 2: Oxidative decarboxylation (the transition phase moving into the Krebs cycle/TCA cycle).\n\t3. Stage 3: Oxidative phosphorylation via the Electron Transport Chain (ETC).\n\nOnce glycolysis yields pyruvate in the cytosol, the pyruvate is actively transported into the mitochondria. Here, the pyruvate dehydrogenase complex carries out oxidative decarboxylation, converting pyruvate into Acetyl-CoA while stripping away carbon dioxide and generating NADH. Because this pathway feeds directly into the aerobic respiration chain, it strictly requires oxygen to proceed.\n\n• Glycolysis: This is the first stage of carbohydrate breakdown. It takes place in the anaerobic environment of the fluid cytoplasm (cytosol), meaning it does not require oxygen or mitochondrial machinery to function.\n• Hexose monophosphate shunt: Also known as the Pentose Phosphate Pathway (PPP), this is an alternative pathway parallel to glycolysis used to generate NADPH and ribose 5-phosphate. It does not serve as the primary second stage of energy-yielding glucose metabolism.\n• Oxidative phosphorylation: This is the final (third) stage of cellular respiration where the vast majority of ATP is structurally synthesized by ATP synthase along the inner mitochondrial membrane.","whyWrongChoices":"Alternative options: Oxidative phosphorylation, Hexose manophasphate shunt, Glycolysis"}'::jsonb),
('mc:end products of the anaerobic phase of glucose metabolism:::pyruvate and lactic acid', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'end products of the anaerobic phase of glucose metabolism', 'Pyruvate and lactic acid', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The anaerobic phase of glucose metabolism refers primarily to glycolysis, which occurs in the cytoplasm and does not require oxygen directly. Glycolysis converts one molecule of glucose into two molecules of pyruvate, producing a net gain of 2 ATP and 2 NADH. When oxygen availability is limited or when glycolytic flux exceeds mitochondrial oxidative capacity, pyruvate can be reduced to lactate by lactate dehydrogenase. This regenerates NAD⁺, allowing glycolysis to continue producing ATP.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pyruvate and lactic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The anaerobic phase of glucose metabolism refers primarily to glycolysis, which occurs in the cytoplasm and does not require oxygen directly. Glycolysis converts one molecule of glucose into two molecules of pyruvate, producing a net gain of 2 ATP and 2 NADH. When oxygen availability is limited or when glycolytic flux exceeds mitochondrial oxidative capacity, pyruvate can be reduced to lactate by lactate dehydrogenase. This regenerates NAD⁺, allowing glycolysis to continue producing ATP.","whyWrongChoices":"Alternative options: Acetyl CoA, Carbon dioxide and water, All of the above"}'::jsonb),
('mc:end products of the anaerobic phase of glucose metabolism:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'end products of the anaerobic phase of glucose metabolism', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The anaerobic phase of glucose metabolism refers primarily to glycolysis, which occurs in the cytoplasm and does not require oxygen directly. Glycolysis converts one molecule of glucose into two molecules of pyruvate, producing a net gain of 2 ATP and 2 NADH. When oxygen availability is limited or when glycolytic flux exceeds mitochondrial oxidative capacity, pyruvate can be reduced to lactate by lactate dehydrogenase. This regenerates NAD⁺, allowing glycolysis to continue producing ATP.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pyruvate and lactic acid\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The anaerobic phase of glucose metabolism refers primarily to glycolysis, which occurs in the cytoplasm and does not require oxygen directly. Glycolysis converts one molecule of glucose into two molecules of pyruvate, producing a net gain of 2 ATP and 2 NADH. When oxygen availability is limited or when glycolytic flux exceeds mitochondrial oxidative capacity, pyruvate can be reduced to lactate by lactate dehydrogenase. This regenerates NAD⁺, allowing glycolysis to continue producing ATP.","whyWrongChoices":"Alternative options: Acetyl CoA, Carbon dioxide and water, All of the above"}'::jsonb),
('mc:all contain carbohydrates except::::lean meat', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'all contain carbohydrates except:', 'Lean meat', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Carbohydrates are found in a wide range of foods, particularly plant foods and certain dairy products. Wheat bread contains starch, while ripe fruits contain naturally occurring sugars such as glucose and fructose. Pasteurized milk also contains carbohydrate in the form of lactose, the naturally occurring sugar in milk. Pasteurization does not remove or substantially eliminate the lactose in milk. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lean meat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Carbohydrates are found in a wide range of foods, particularly plant foods and certain dairy products. Wheat bread contains starch, while ripe fruits contain naturally occurring sugars such as glucose and fructose. Pasteurized milk also contains carbohydrate in the form of lactose, the naturally occurring sugar in milk. Pasteurization does not remove or substantially eliminate the lactose in milk. \n\nLean meat, in contrast, contains primarily protein and fat and provides essentially no carbohydrate. Although very small amounts of carbohydrate-related compounds may be present in animal tissues, meat is generally classified as a negligible-carbohydrate food for nutrition and dietary planning purposes.","whyWrongChoices":"Alternative options: Wheat bread, Ripe fruit, Pasteurized milk"}'::jsonb),
('mc:all contain carbohydrates except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'all contain carbohydrates except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Carbohydrates are found in a wide range of foods, particularly plant foods and certain dairy products. Wheat bread contains starch, while ripe fruits contain naturally occurring sugars such as glucose and fructose. Pasteurized milk also contains carbohydrate in the form of lactose, the naturally occurring sugar in milk. Pasteurization does not remove or substantially eliminate the lactose in milk. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lean meat\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Carbohydrates are found in a wide range of foods, particularly plant foods and certain dairy products. Wheat bread contains starch, while ripe fruits contain naturally occurring sugars such as glucose and fructose. Pasteurized milk also contains carbohydrate in the form of lactose, the naturally occurring sugar in milk. Pasteurization does not remove or substantially eliminate the lactose in milk. \n\nLean meat, in contrast, contains primarily protein and fat and provides essentially no carbohydrate. Although very small amounts of carbohydrate-related compounds may be present in animal tissues, meat is generally classified as a negligible-carbohydrate food for nutrition and dietary planning purposes.","whyWrongChoices":"Alternative options: Wheat bread, Ripe fruit, Pasteurized milk"}'::jsonb),
('mc:nutritional management when a patient experiences vomiting:::withhold food until vomiting subsides', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'nutritional management when a patient experiences vomiting', 'Withhold food until vomiting subsides', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During active vomiting, the immediate nutritional priority is to allow the gastrointestinal tract to rest while preventing dehydration. Food is generally withheld temporarily until vomiting subsides, after which oral intake can be gradually resumed as tolerated. Once the patient can tolerate fluids, small, frequent amounts of fluid are preferred rather than large volumes at one time. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Withhold food until vomiting subsides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During active vomiting, the immediate nutritional priority is to allow the gastrointestinal tract to rest while preventing dehydration. Food is generally withheld temporarily until vomiting subsides, after which oral intake can be gradually resumed as tolerated. Once the patient can tolerate fluids, small, frequent amounts of fluid are preferred rather than large volumes at one time. \n\nOral rehydration solutions may be particularly useful when fluid and electrolyte losses are significant. After vomiting has stopped, food should be reintroduced gradually, usually beginning with small portions and advancing according to tolerance. Large amounts of fluid with meals can worsen fullness and nausea, while hot, strongly scented, greasy, or spicy foods may be poorly tolerated. Cold or room-temperature foods may sometimes be better tolerated because they have less odor.","whyWrongChoices":"Alternative options: Liberal fluid intake during meals, All of the above, Serve hot soup"}'::jsonb),
('mc:nutritional management when a patient experiences vomiting:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'nutritional management when a patient experiences vomiting', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During active vomiting, the immediate nutritional priority is to allow the gastrointestinal tract to rest while preventing dehydration. Food is generally withheld temporarily until vomiting subsides, after which oral intake can be gradually resumed as tolerated. Once the patient can tolerate fluids, small, frequent amounts of fluid are preferred rather than large volumes at one time. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Withhold food until vomiting subsides\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During active vomiting, the immediate nutritional priority is to allow the gastrointestinal tract to rest while preventing dehydration. Food is generally withheld temporarily until vomiting subsides, after which oral intake can be gradually resumed as tolerated. Once the patient can tolerate fluids, small, frequent amounts of fluid are preferred rather than large volumes at one time. \n\nOral rehydration solutions may be particularly useful when fluid and electrolyte losses are significant. After vomiting has stopped, food should be reintroduced gradually, usually beginning with small portions and advancing according to tolerance. Large amounts of fluid with meals can worsen fullness and nausea, while hot, strongly scented, greasy, or spicy foods may be poorly tolerated. Cold or room-temperature foods may sometimes be better tolerated because they have less odor.","whyWrongChoices":"Alternative options: Liberal fluid intake during meals, All of the above, Serve hot soup"}'::jsonb),
('mc:which of the following is/are not true about dietary management of diabetes mellitus? i. the type of carbohydrate is more important than the total amount of carbohydrates ii. the total amount of carbohydrate consumed is more important than the source of carbohydrate iii. people with diabetes mellitus can eat candies and other sugary foods.:::i only', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is/are not true about dietary management of diabetes mellitus? i. the type of carbohydrate is more important than the total amount of carbohydrates ii. the total amount of carbohydrate consumed is more important than the source of carbohydrate iii. people with diabetes mellitus can eat candies and other sugary foods.', 'I only', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement I is NOT true because, in diabetes management, the total amount of carbohydrate consumed is a major determinant of postprandial blood glucose, particularly when considering carbohydrate counting and matching carbohydrate intake with insulin or other glucose-lowering therapy. The type and quality of carbohydrate are also important because fiber content, degree of processing, and food composition can affect the glycemic response, but carbohydrate type is not generally considered more important than the total amount consumed. Thus, saying that type is more important than total amount is an inaccurate statement. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"I only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement I is NOT true because, in diabetes management, the total amount of carbohydrate consumed is a major determinant of postprandial blood glucose, particularly when considering carbohydrate counting and matching carbohydrate intake with insulin or other glucose-lowering therapy. The type and quality of carbohydrate are also important because fiber content, degree of processing, and food composition can affect the glycemic response, but carbohydrate type is not generally considered more important than the total amount consumed. Thus, saying that type is more important than total amount is an inaccurate statement. \n\nStatement II is considered true in the context of the fundamental principle of carbohydrate management: the amount of carbohydrate consumed has a substantial and predictable effect on blood glucose. This does not mean that carbohydrate source is unimportant; whole grains, legumes, vegetables, fruits, and other minimally processed carbohydrate-rich foods are generally preferred over highly refined foods and foods high in added sugars because of their fiber and nutrient content. \n\nStatement III is also true because people with diabetes do not have to completely eliminate candies and other sugary foods. These can be incorporated occasionally into an individualized meal plan, provided that carbohydrate and overall energy intake are appropriately managed.","whyWrongChoices":"Alternative options: III only, Both II & III, Both I & II"}'::jsonb),
('mc:which of the following is/are not true about dietary management of diabetes mellitus? i. the type of carbohydrate is more important than the total amount of carbohydrates ii. the total amount of carbohydrate consumed is more important than the source of carbohydrate iii. people with diabetes mellitus can eat candies and other sugary foods.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is/are not true about dietary management of diabetes mellitus? i. the type of carbohydrate is more important than the total amount of carbohydrates ii. the total amount of carbohydrate consumed is more important than the source of carbohydrate iii. people with diabetes mellitus can eat candies and other sugary foods.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Statement I is NOT true because, in diabetes management, the total amount of carbohydrate consumed is a major determinant of postprandial blood glucose, particularly when considering carbohydrate counting and matching carbohydrate intake with insulin or other glucose-lowering therapy. The type and quality of carbohydrate are also important because fiber content, degree of processing, and food composition can affect the glycemic response, but carbohydrate type is not generally considered more important than the total amount consumed. Thus, saying that type is more important than total amount is an inaccurate statement. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"I only\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Statement I is NOT true because, in diabetes management, the total amount of carbohydrate consumed is a major determinant of postprandial blood glucose, particularly when considering carbohydrate counting and matching carbohydrate intake with insulin or other glucose-lowering therapy. The type and quality of carbohydrate are also important because fiber content, degree of processing, and food composition can affect the glycemic response, but carbohydrate type is not generally considered more important than the total amount consumed. Thus, saying that type is more important than total amount is an inaccurate statement. \n\nStatement II is considered true in the context of the fundamental principle of carbohydrate management: the amount of carbohydrate consumed has a substantial and predictable effect on blood glucose. This does not mean that carbohydrate source is unimportant; whole grains, legumes, vegetables, fruits, and other minimally processed carbohydrate-rich foods are generally preferred over highly refined foods and foods high in added sugars because of their fiber and nutrient content. \n\nStatement III is also true because people with diabetes do not have to completely eliminate candies and other sugary foods. These can be incorporated occasionally into an individualized meal plan, provided that carbohydrate and overall energy intake are appropriately managed.","whyWrongChoices":"Alternative options: III only, Both II & III, Both I & II"}'::jsonb),
('mc:consistent carbohydrate diet means::::the amount of carbohydrate consumed and the timing of meals and snacks are consistent', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'consistent carbohydrate diet means:', 'The amount of carbohydrate consumed and the timing of meals and snacks are consistent', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A consistent carbohydrate diet is a meal-planning approach commonly used in the management of diabetes mellitus. Rather than eliminating carbohydrates, the goal is to maintain a relatively consistent amount of carbohydrate at meals and snacks from day to day, while keeping meal timing regular. This helps minimize fluctuations in blood glucose levels and improves the effectiveness of diabetes medications, particularly insulin and insulin secretagogues. The emphasis is on consistency, not on consuming a fixed amount of carbohydrates for every individual.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The amount of carbohydrate consumed and the timing of meals and snacks are consistent\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A consistent carbohydrate diet is a meal-planning approach commonly used in the management of diabetes mellitus. Rather than eliminating carbohydrates, the goal is to maintain a relatively consistent amount of carbohydrate at meals and snacks from day to day, while keeping meal timing regular. This helps minimize fluctuations in blood glucose levels and improves the effectiveness of diabetes medications, particularly insulin and insulin secretagogues. The emphasis is on consistency, not on consuming a fixed amount of carbohydrates for every individual.","whyWrongChoices":"Alternative options: The type and amount of carbohydrate in the diet must be consistent as well as the timing of meals and snacks, In case of hypoglycemia, 15 grams of carbohydrates are given every 15 minutes to achieve consistent blood sugar level, 45 to 75 grams of carbohydrates are given at each meal to maintain normal blood sugar level"}'::jsonb),
('mc:consistent carbohydrate diet means::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'consistent carbohydrate diet means:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A consistent carbohydrate diet is a meal-planning approach commonly used in the management of diabetes mellitus. Rather than eliminating carbohydrates, the goal is to maintain a relatively consistent amount of carbohydrate at meals and snacks from day to day, while keeping meal timing regular. This helps minimize fluctuations in blood glucose levels and improves the effectiveness of diabetes medications, particularly insulin and insulin secretagogues. The emphasis is on consistency, not on consuming a fixed amount of carbohydrates for every individual.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The amount of carbohydrate consumed and the timing of meals and snacks are consistent\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A consistent carbohydrate diet is a meal-planning approach commonly used in the management of diabetes mellitus. Rather than eliminating carbohydrates, the goal is to maintain a relatively consistent amount of carbohydrate at meals and snacks from day to day, while keeping meal timing regular. This helps minimize fluctuations in blood glucose levels and improves the effectiveness of diabetes medications, particularly insulin and insulin secretagogues. The emphasis is on consistency, not on consuming a fixed amount of carbohydrates for every individual.","whyWrongChoices":"Alternative options: The type and amount of carbohydrate in the diet must be consistent as well as the timing of meals and snacks, In case of hypoglycemia, 15 grams of carbohydrates are given every 15 minutes to achieve consistent blood sugar level, 45 to 75 grams of carbohydrates are given at each meal to maintain normal blood sugar level"}'::jsonb),
('mc:during aerobic respiration, the decomposition of one glucose molecule produces::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'during aerobic respiration, the decomposition of one glucose molecule produces:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Using the traditional biochemical calculation commonly taught in nutrition and NDLE review materials, the complete aerobic oxidation of one glucose molecule produces a maximum of 38 ATP. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"38 molecules of ATP\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Using the traditional biochemical calculation commonly taught in nutrition and NDLE review materials, the complete aerobic oxidation of one glucose molecule produces a maximum of 38 ATP. \n\nThis calculation assigns 3 ATP per NADH and 2 ATP per FADH₂. Glycolysis produces 2 ATP and 2 NADH; pyruvate oxidation produces 2 NADH; and the TCA cycle produces 2 ATP (or GTP), 6 NADH, and 2 FADH₂. Altogether, this gives 38 ATP per glucose under the traditional accounting system.","whyWrongChoices":"Alternative options: 40 molecules of ATP, 46 molecules of ATP, 48 molecules of ATP"}'::jsonb),
('mc:during glycolysis and tca, glucose is first broken down into , then , and finally for use in the body.:::pyruvate, acetyl coa, energy', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'during glycolysis and tca, glucose is first broken down into , then , and finally for use in the body.', 'pyruvate, acetyl CoA, energy', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During glucose oxidation, glycolysis first converts glucose into pyruvate in the cytoplasm. Each glucose molecule produces two molecules of pyruvate. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pyruvate, acetyl CoA, energy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During glucose oxidation, glycolysis first converts glucose into pyruvate in the cytoplasm. Each glucose molecule produces two molecules of pyruvate. \n\nUnder aerobic conditions, pyruvate enters the mitochondria and undergoes oxidative decarboxylation, producing acetyl-CoA. Acetyl-CoA then enters the tricarboxylic acid (TCA) cycle, where its carbon atoms are progressively oxidized and energy is captured primarily in the form of NADH and FADH₂. The reduced electron carriers generated during glycolysis, pyruvate oxidation, and the TCA cycle subsequently donate electrons to the electron transport chain, driving oxidative phosphorylation and the production of ATP. \n\nThus, the simplified sequence tested by this question is glucose → pyruvate → acetyl-CoA → energy (ATP).","whyWrongChoices":"Alternative options: amino acids, acetyl CoA, energy, acetyl CoA, pyruvate, energy, glycerol, pyruvate, energy"}'::jsonb),
('mc:during glycolysis and tca, glucose is first broken down into , then , and finally for use in the body.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'during glycolysis and tca, glucose is first broken down into , then , and finally for use in the body.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During glucose oxidation, glycolysis first converts glucose into pyruvate in the cytoplasm. Each glucose molecule produces two molecules of pyruvate. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"pyruvate, acetyl CoA, energy\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During glucose oxidation, glycolysis first converts glucose into pyruvate in the cytoplasm. Each glucose molecule produces two molecules of pyruvate. \n\nUnder aerobic conditions, pyruvate enters the mitochondria and undergoes oxidative decarboxylation, producing acetyl-CoA. Acetyl-CoA then enters the tricarboxylic acid (TCA) cycle, where its carbon atoms are progressively oxidized and energy is captured primarily in the form of NADH and FADH₂. The reduced electron carriers generated during glycolysis, pyruvate oxidation, and the TCA cycle subsequently donate electrons to the electron transport chain, driving oxidative phosphorylation and the production of ATP. \n\nThus, the simplified sequence tested by this question is glucose → pyruvate → acetyl-CoA → energy (ATP).","whyWrongChoices":"Alternative options: amino acids, acetyl CoA, energy, acetyl CoA, pyruvate, energy, glycerol, pyruvate, energy"}'::jsonb),
('mc:what is the fate of excess intake of dietary protein?:::after absorption, the extra amino acids will be rapidly degraded', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the fate of excess intake of dietary protein?', 'After absorption, the extra amino acids will be rapidly degraded', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Unlike carbohydrates and fats, the body does not have a specialized storage depot for excess amino acids or dietary protein. After dietary protein is digested and absorbed, amino acids enter the body''s amino acid pool and are used for protein synthesis and other metabolic functions. When amino acid availability exceeds the body''s immediate needs for protein synthesis and other required compounds, the excess amino acids are deaminated. Their nitrogen is converted primarily to urea in the liver and excreted in the urine, while their carbon skeletons can be used for energy or converted into glucose, ketone bodies, or other metabolites. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"After absorption, the extra amino acids will be rapidly degraded\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Unlike carbohydrates and fats, the body does not have a specialized storage depot for excess amino acids or dietary protein. After dietary protein is digested and absorbed, amino acids enter the body''s amino acid pool and are used for protein synthesis and other metabolic functions. When amino acid availability exceeds the body''s immediate needs for protein synthesis and other required compounds, the excess amino acids are deaminated. Their nitrogen is converted primarily to urea in the liver and excreted in the urine, while their carbon skeletons can be used for energy or converted into glucose, ketone bodies, or other metabolites. \n\nTherefore, consuming more protein than needed does not result in the body storing the extra protein as protein for later use. The body continually regulates amino acid metabolism according to physiological needs. Excess energy from protein can ultimately contribute to energy storage as body fat if overall energy intake exceeds expenditure, but this occurs after amino acid catabolism, not through storage of excess dietary protein as a protein reserve.","whyWrongChoices":"Alternative options: After absorption, the liver will store the extra amino acids, Digestion will be decreased by 30-60% resulting in less absorption, After absorption, extra proteins will be synthesized and stored for use when protein intake returns to normal"}'::jsonb),
('mc:what is the fate of excess intake of dietary protein?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the fate of excess intake of dietary protein?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Unlike carbohydrates and fats, the body does not have a specialized storage depot for excess amino acids or dietary protein. After dietary protein is digested and absorbed, amino acids enter the body''s amino acid pool and are used for protein synthesis and other metabolic functions. When amino acid availability exceeds the body''s immediate needs for protein synthesis and other required compounds, the excess amino acids are deaminated. Their nitrogen is converted primarily to urea in the liver and excreted in the urine, while their carbon skeletons can be used for energy or converted into glucose, ketone bodies, or other metabolites. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"After absorption, the extra amino acids will be rapidly degraded\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Unlike carbohydrates and fats, the body does not have a specialized storage depot for excess amino acids or dietary protein. After dietary protein is digested and absorbed, amino acids enter the body''s amino acid pool and are used for protein synthesis and other metabolic functions. When amino acid availability exceeds the body''s immediate needs for protein synthesis and other required compounds, the excess amino acids are deaminated. Their nitrogen is converted primarily to urea in the liver and excreted in the urine, while their carbon skeletons can be used for energy or converted into glucose, ketone bodies, or other metabolites. \n\nTherefore, consuming more protein than needed does not result in the body storing the extra protein as protein for later use. The body continually regulates amino acid metabolism according to physiological needs. Excess energy from protein can ultimately contribute to energy storage as body fat if overall energy intake exceeds expenditure, but this occurs after amino acid catabolism, not through storage of excess dietary protein as a protein reserve.","whyWrongChoices":"Alternative options: After absorption, the liver will store the extra amino acids, Digestion will be decreased by 30-60% resulting in less absorption, After absorption, extra proteins will be synthesized and stored for use when protein intake returns to normal"}'::jsonb),
('mc:which of the following is not one of the five classical french mother sauces?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is not one of the five classical french mother sauces?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The five classical French mother sauces codified by chef Auguste Escoffier:Bechamel, Veloute, Espagnole, Tomato, Hollandaise","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Marinara\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The five classical French mother sauces codified by chef Auguste Escoffier:Bechamel, Veloute, Espagnole, Tomato, Hollandaise\n\nThese foundational recipes use a liquid combined with a thickening agent (like a roux or emulsion) to create dozens of secondary \"daughter\" sauces.","whyWrongChoices":"Alternative options: Hollandaise, Velouté, Béchamel"}'::jsonb),
('mc:essential amino acids except::::glutamine', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'essential amino acids except:', 'Glutamine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Histidine, leucine, and lysine are essential amino acids, meaning they cannot be synthesized by the human body in sufficient amounts to meet physiological needs and therefore must be obtained from the diet. Histidine is particularly important for growth and tissue repair, leucine is a branched-chain amino acid that plays an important role in stimulating muscle protein synthesis, and lysine is involved in protein synthesis and several other metabolic functions. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glutamine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Histidine, leucine, and lysine are essential amino acids, meaning they cannot be synthesized by the human body in sufficient amounts to meet physiological needs and therefore must be obtained from the diet. Histidine is particularly important for growth and tissue repair, leucine is a branched-chain amino acid that plays an important role in stimulating muscle protein synthesis, and lysine is involved in protein synthesis and several other metabolic functions. \n\nGlutamine is classified as a nonessential amino acid under normal physiological conditions because the body can synthesize it from glutamate and ammonia. However, during severe illness, trauma, burns, or other metabolic stress, glutamine requirements may increase substantially and endogenous synthesis may not meet demand. It is therefore often described as conditionally essential in certain clinical situations.","whyWrongChoices":"Alternative options: Histidine, Leucine, Lysine"}'::jsonb),
('mc:essential amino acids except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'essential amino acids except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Histidine, leucine, and lysine are essential amino acids, meaning they cannot be synthesized by the human body in sufficient amounts to meet physiological needs and therefore must be obtained from the diet. Histidine is particularly important for growth and tissue repair, leucine is a branched-chain amino acid that plays an important role in stimulating muscle protein synthesis, and lysine is involved in protein synthesis and several other metabolic functions. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glutamine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Histidine, leucine, and lysine are essential amino acids, meaning they cannot be synthesized by the human body in sufficient amounts to meet physiological needs and therefore must be obtained from the diet. Histidine is particularly important for growth and tissue repair, leucine is a branched-chain amino acid that plays an important role in stimulating muscle protein synthesis, and lysine is involved in protein synthesis and several other metabolic functions. \n\nGlutamine is classified as a nonessential amino acid under normal physiological conditions because the body can synthesize it from glutamate and ammonia. However, during severe illness, trauma, burns, or other metabolic stress, glutamine requirements may increase substantially and endogenous synthesis may not meet demand. It is therefore often described as conditionally essential in certain clinical situations.","whyWrongChoices":"Alternative options: Histidine, Leucine, Lysine"}'::jsonb),
('mc:electron-carrier molecules that are used in the electron-transport chain to generate additional atp are::::nadh and fadh2', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'electron-carrier molecules that are used in the electron-transport chain to generate additional atp are:', 'NADH and FADH2', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"NADH and FADH₂ are reduced electron carriers generated during several stages of cellular respiration, including glycolysis, pyruvate oxidation, and the TCA cycle. They carry high-energy electrons to the electron transport chain (ETC) located in the inner mitochondrial membrane. As electrons move through the ETC, the released energy is used to pump protons across the membrane, creating a proton gradient that drives ATP synthesis through ATP synthase. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"NADH and FADH2\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"NADH and FADH₂ are reduced electron carriers generated during several stages of cellular respiration, including glycolysis, pyruvate oxidation, and the TCA cycle. They carry high-energy electrons to the electron transport chain (ETC) located in the inner mitochondrial membrane. As electrons move through the ETC, the released energy is used to pump protons across the membrane, creating a proton gradient that drives ATP synthesis through ATP synthase. \n\nNADH donates electrons to Complex I, whereas FADH₂ donates electrons through Complex II. Because FADH₂ enters the ETC downstream of Complex I, it generally results in the production of less ATP than NADH. Modern estimates are approximately 2.5 ATP per NADH and 1.5 ATP per FADH₂, although the exact ATP yield can vary depending on cellular conditions and the pathway used to transfer cytosolic reducing equivalents into the mitochondria.","whyWrongChoices":"Alternative options: Glucose and ketone bodies, Acetyl-CoA and amino acids, Pyruvic acid and lactic acid"}'::jsonb),
('mc:a 20% intravenous fat emulsion provides approximately how many kilocalories per 100 ml?:::200', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a 20% intravenous fat emulsion provides approximately how many kilocalories per 100 ml?', '200', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A 20% intravenous lipid emulsion (ILE) contains approximately 20 g of lipid per 100 mL and is conventionally estimated to provide 2 kcal/mL, or approximately 200 kcal per 100 mL. This is the value commonly used when calculating the energy contribution of IV lipid emulsions in parenteral nutrition. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"200\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A 20% intravenous lipid emulsion (ILE) contains approximately 20 g of lipid per 100 mL and is conventionally estimated to provide 2 kcal/mL, or approximately 200 kcal per 100 mL. This is the value commonly used when calculating the energy contribution of IV lipid emulsions in parenteral nutrition. \n\nA 10% ILE provides approximately 1.1 kcal/mL, while a 20% ILE provides approximately 2 kcal/mL. The distinction is important because the caloric value assigned to IV lipid emulsions is not calculated simply by multiplying grams of lipid by 9 kcal/g, as would commonly be done for dietary fat. \n\nCommercial IV lipid emulsions contain triglycerides along with emulsifying agents and other components, and their labeled caloric contribution is based on the formulation. For PN calculations, therefore, use the manufacturer/standard clinical kcal/mL value for the specific lipid emulsion.","whyWrongChoices":"Alternative options: 110, 180, 20"}'::jsonb),
('mc:a 20% intravenous fat emulsion provides approximately how many kilocalories per 100 ml?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a 20% intravenous fat emulsion provides approximately how many kilocalories per 100 ml?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A 20% intravenous lipid emulsion (ILE) contains approximately 20 g of lipid per 100 mL and is conventionally estimated to provide 2 kcal/mL, or approximately 200 kcal per 100 mL. This is the value commonly used when calculating the energy contribution of IV lipid emulsions in parenteral nutrition. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"200\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A 20% intravenous lipid emulsion (ILE) contains approximately 20 g of lipid per 100 mL and is conventionally estimated to provide 2 kcal/mL, or approximately 200 kcal per 100 mL. This is the value commonly used when calculating the energy contribution of IV lipid emulsions in parenteral nutrition. \n\nA 10% ILE provides approximately 1.1 kcal/mL, while a 20% ILE provides approximately 2 kcal/mL. The distinction is important because the caloric value assigned to IV lipid emulsions is not calculated simply by multiplying grams of lipid by 9 kcal/g, as would commonly be done for dietary fat. \n\nCommercial IV lipid emulsions contain triglycerides along with emulsifying agents and other components, and their labeled caloric contribution is based on the formulation. For PN calculations, therefore, use the manufacturer/standard clinical kcal/mL value for the specific lipid emulsion.","whyWrongChoices":"Alternative options: 110, 180, 20"}'::jsonb),
('mc:which of the following contain the least amount of dietary fiber?:::well-milled rice', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following contain the least amount of dietary fiber?', 'Well-milled rice', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Well-milled rice contains the least dietary fiber among the choices because the milling process removes the outer layers of the rice grain, including much of the bran and germ, where dietary fiber is concentrated. As a result, well-milled or highly polished white rice contains substantially less fiber than less-refined grains and many plant foods. This makes well-milled rice a low-fiber carbohydrate source. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Well-milled rice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Well-milled rice contains the least dietary fiber among the choices because the milling process removes the outer layers of the rice grain, including much of the bran and germ, where dietary fiber is concentrated. As a result, well-milled or highly polished white rice contains substantially less fiber than less-refined grains and many plant foods. This makes well-milled rice a low-fiber carbohydrate source. \n\nIn comparison, sinigwelas (Java plum), yellow camote (sweet potato), and lakatan (banana) are plant foods that retain their cellular structures and therefore provide dietary fiber. Their exact fiber content varies with variety, maturity, preparation, and serving size, but they generally provide more dietary fiber than well-milled rice. For NDLE purposes, the key concept is that refining and milling grains removes fiber-rich outer layers.","whyWrongChoices":"Alternative options: Sinigwelas, Yellow camote, Lakatan"}'::jsonb),
('mc:which of the following contain the least amount of dietary fiber?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following contain the least amount of dietary fiber?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Well-milled rice contains the least dietary fiber among the choices because the milling process removes the outer layers of the rice grain, including much of the bran and germ, where dietary fiber is concentrated. As a result, well-milled or highly polished white rice contains substantially less fiber than less-refined grains and many plant foods. This makes well-milled rice a low-fiber carbohydrate source. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Well-milled rice\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Well-milled rice contains the least dietary fiber among the choices because the milling process removes the outer layers of the rice grain, including much of the bran and germ, where dietary fiber is concentrated. As a result, well-milled or highly polished white rice contains substantially less fiber than less-refined grains and many plant foods. This makes well-milled rice a low-fiber carbohydrate source. \n\nIn comparison, sinigwelas (Java plum), yellow camote (sweet potato), and lakatan (banana) are plant foods that retain their cellular structures and therefore provide dietary fiber. Their exact fiber content varies with variety, maturity, preparation, and serving size, but they generally provide more dietary fiber than well-milled rice. For NDLE purposes, the key concept is that refining and milling grains removes fiber-rich outer layers.","whyWrongChoices":"Alternative options: Sinigwelas, Yellow camote, Lakatan"}'::jsonb),
('mc:the following inhibit the absorption of iron except::::fructose', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following inhibit the absorption of iron except:', 'Fructose', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Iron absorption is influenced by both the chemical form of iron and components of the meal. Nonheme iron, the major form found in plant foods and fortified foods, is particularly affected by dietary factors. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fructose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Iron absorption is influenced by both the chemical form of iron and components of the meal. Nonheme iron, the major form found in plant foods and fortified foods, is particularly affected by dietary factors. \n\nCoffee and tea can substantially reduce nonheme iron absorption because they contain polyphenolic compounds that bind iron and reduce its bioavailability. Soy products may also reduce nonheme iron absorption because of compounds such as phytate, although the magnitude of the effect depends on the food and overall dietary pattern. \n\nFructose, in contrast, does not inhibit iron absorption and may actually enhance nonheme iron absorption under certain conditions. It has been associated with improved iron absorption, although its effect is less prominent than that of vitamin C.","whyWrongChoices":"Alternative options: Soy products (if major dietary protein is from soy), Coffee, Tea"}'::jsonb),
('mc:the following inhibit the absorption of iron except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following inhibit the absorption of iron except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Iron absorption is influenced by both the chemical form of iron and components of the meal. Nonheme iron, the major form found in plant foods and fortified foods, is particularly affected by dietary factors. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Fructose\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Iron absorption is influenced by both the chemical form of iron and components of the meal. Nonheme iron, the major form found in plant foods and fortified foods, is particularly affected by dietary factors. \n\nCoffee and tea can substantially reduce nonheme iron absorption because they contain polyphenolic compounds that bind iron and reduce its bioavailability. Soy products may also reduce nonheme iron absorption because of compounds such as phytate, although the magnitude of the effect depends on the food and overall dietary pattern. \n\nFructose, in contrast, does not inhibit iron absorption and may actually enhance nonheme iron absorption under certain conditions. It has been associated with improved iron absorption, although its effect is less prominent than that of vitamin C.","whyWrongChoices":"Alternative options: Soy products (if major dietary protein is from soy), Coffee, Tea"}'::jsonb),
('mc:which of the following meats has the lowest kilocalories from fat per serving?:::chicken leg', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following meats has the lowest kilocalories from fat per serving?', 'Chicken leg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Among these choices, chicken leg generally provides the lowest amount of fat-derived energy per standard serving when compared with pork pata, chicken wings, and Vienna sausage. Chicken leg is a relatively nutrient-dense source of protein, although its fat content varies depending on whether the skin is consumed and the specific cut and preparation method. Removing the skin substantially reduces its fat and total energy content. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chicken leg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Among these choices, chicken leg generally provides the lowest amount of fat-derived energy per standard serving when compared with pork pata, chicken wings, and Vienna sausage. Chicken leg is a relatively nutrient-dense source of protein, although its fat content varies depending on whether the skin is consumed and the specific cut and preparation method. Removing the skin substantially reduces its fat and total energy content. \n\nPork pata and chicken wings tend to contain more fat per edible serving, while Vienna sausage is a processed meat product that commonly contains a relatively high proportion of fat. For nutrition assessment and meal planning, it is important to consider the edible portion, preparation method, skin, and processing because these can substantially alter the fat and energy content of meat products.","whyWrongChoices":"Alternative options: Pork pata, Chicken wings, Vienna sausage"}'::jsonb),
('mc:which of the following meats has the lowest kilocalories from fat per serving?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following meats has the lowest kilocalories from fat per serving?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Among these choices, chicken leg generally provides the lowest amount of fat-derived energy per standard serving when compared with pork pata, chicken wings, and Vienna sausage. Chicken leg is a relatively nutrient-dense source of protein, although its fat content varies depending on whether the skin is consumed and the specific cut and preparation method. Removing the skin substantially reduces its fat and total energy content. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chicken leg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Among these choices, chicken leg generally provides the lowest amount of fat-derived energy per standard serving when compared with pork pata, chicken wings, and Vienna sausage. Chicken leg is a relatively nutrient-dense source of protein, although its fat content varies depending on whether the skin is consumed and the specific cut and preparation method. Removing the skin substantially reduces its fat and total energy content. \n\nPork pata and chicken wings tend to contain more fat per edible serving, while Vienna sausage is a processed meat product that commonly contains a relatively high proportion of fat. For nutrition assessment and meal planning, it is important to consider the edible portion, preparation method, skin, and processing because these can substantially alter the fat and energy content of meat products.","whyWrongChoices":"Alternative options: Pork pata, Chicken wings, Vienna sausage"}'::jsonb),
('mc:sodium equivalent of the low sodium diet?:::less than 2g sodium/day', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sodium equivalent of the low sodium diet?', 'Less than 2g sodium/day', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A low-sodium diet generally limits sodium intake to approximately 2,000 mg/day or less, particularly in clinical nutrition for conditions such as hypertension, heart failure, and certain renal or hepatic disorders. Sodium restriction reduces sodium and water retention and may help control blood pressure and fluid balance. Importantly, the exact sodium prescription should be individualized according to the patient''s diagnosis, clinical status, and current guidelines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Less than 2g sodium/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A low-sodium diet generally limits sodium intake to approximately 2,000 mg/day or less, particularly in clinical nutrition for conditions such as hypertension, heart failure, and certain renal or hepatic disorders. Sodium restriction reduces sodium and water retention and may help control blood pressure and fluid balance. Importantly, the exact sodium prescription should be individualized according to the patient''s diagnosis, clinical status, and current guidelines.","whyWrongChoices":"Alternative options: 1 to 3g sodium/day, 2g sodium/day, No added salt"}'::jsonb),
('mc:which enzyme is associated with the tenderizing activity of figs?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which enzyme is associated with the tenderizing activity of figs?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ficain is a proteolytic enzyme found in figs and can contribute to meat tenderization.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Ficain\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ficain is a proteolytic enzyme found in figs and can contribute to meat tenderization.\n\n• Papain is associated with papaya.\n• Bromelain is associated with pineapple.\n• Lactase hydrolyzes lactose and is not the fig enzyme used for meat tenderizing.","whyWrongChoices":"Alternative options: Papain, Bromelain, Lactase"}'::jsonb),
('mc:sodium equivalent of the low sodium diet?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'sodium equivalent of the low sodium diet?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A low-sodium diet generally limits sodium intake to approximately 2,000 mg/day or less, particularly in clinical nutrition for conditions such as hypertension, heart failure, and certain renal or hepatic disorders. Sodium restriction reduces sodium and water retention and may help control blood pressure and fluid balance. Importantly, the exact sodium prescription should be individualized according to the patient''s diagnosis, clinical status, and current guidelines.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Less than 2g sodium/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A low-sodium diet generally limits sodium intake to approximately 2,000 mg/day or less, particularly in clinical nutrition for conditions such as hypertension, heart failure, and certain renal or hepatic disorders. Sodium restriction reduces sodium and water retention and may help control blood pressure and fluid balance. Importantly, the exact sodium prescription should be individualized according to the patient''s diagnosis, clinical status, and current guidelines.","whyWrongChoices":"Alternative options: 1 to 3g sodium/day, 2g sodium/day, No added salt"}'::jsonb),
('mc:using the tannhauser’s method, a 5’6” person has an ideal body weight of::::61 kg', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'using the tannhauser’s method, a 5’6” person has an ideal body weight of:', '61 kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"61 kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation\n\nTannhauser''s Method (widely used in the Philippines to estimate Desirable Body Weight or DBW) utilizes the following formula:\nDBW (kg) = (Height in cm - 100) - [10% x (Height in cm - 100)]\n\n1. Convert height to centimeters:\n• 5 feet 6 inches = 66 inches\n• 66 inches x 2.54 cm/inch = 167.64 cm\n\n2. Calculate initial DBW baseline:\n• 167.64 - 100 = 67.64 kg\n\n3. Deduct 10% for the Filipino/Asian frame adjustment:\n• 10% of 67.64 = 6.764 kg\n• 67.64 kg - 6.764 kg = 60.876 kg\n\nRounding 60.876 kg to the nearest whole number gives 61 kg.","whyWrongChoices":"Alternative options: 58 kg, 72 kg, None of the above"}'::jsonb),
('mc:using the tannhauser’s method, a 5’6” person has an ideal body weight of::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'using the tannhauser’s method, a 5’6” person has an ideal body weight of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Step-by-Step Calculation","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"61 kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Step-by-Step Calculation\n\nTannhauser''s Method (widely used in the Philippines to estimate Desirable Body Weight or DBW) utilizes the following formula:\nDBW (kg) = (Height in cm - 100) - [10% x (Height in cm - 100)]\n\n1. Convert height to centimeters:\n• 5 feet 6 inches = 66 inches\n• 66 inches x 2.54 cm/inch = 167.64 cm\n\n2. Calculate initial DBW baseline:\n• 167.64 - 100 = 67.64 kg\n\n3. Deduct 10% for the Filipino/Asian frame adjustment:\n• 10% of 67.64 = 6.764 kg\n• 67.64 kg - 6.764 kg = 60.876 kg\n\nRounding 60.876 kg to the nearest whole number gives 61 kg.","whyWrongChoices":"Alternative options: 58 kg, 72 kg, None of the above"}'::jsonb),
('mc:the desirable body weight of a 4-year-old girl is::::16 kg', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the desirable body weight of a 4-year-old girl is:', '16 kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For children 1–6 years of age, a commonly taught formula for estimating expected or desirable body weight is Weight (kg) = (age in years × 2) + 8. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"16 kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For children 1–6 years of age, a commonly taught formula for estimating expected or desirable body weight is Weight (kg) = (age in years × 2) + 8. \n\nFor a 4-year-old child, the calculation is therefore (4 × 2) + 8 = 16 kg. Thus, the answer is 16 kg. This is a quick estimation formula commonly used in nutrition education and examination settings.","whyWrongChoices":"Alternative options: 12 kg, 14.5 kg, 20 kg"}'::jsonb),
('mc:the desirable body weight of a 4-year-old girl is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the desirable body weight of a 4-year-old girl is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For children 1–6 years of age, a commonly taught formula for estimating expected or desirable body weight is Weight (kg) = (age in years × 2) + 8. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"16 kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For children 1–6 years of age, a commonly taught formula for estimating expected or desirable body weight is Weight (kg) = (age in years × 2) + 8. \n\nFor a 4-year-old child, the calculation is therefore (4 × 2) + 8 = 16 kg. Thus, the answer is 16 kg. This is a quick estimation formula commonly used in nutrition education and examination settings.","whyWrongChoices":"Alternative options: 12 kg, 14.5 kg, 20 kg"}'::jsonb),
('mc:a mechanical soft diet includes::::easy to chew foods, including foods in the regular diet', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a mechanical soft diet includes:', 'easy to chew foods, including foods in the regular diet', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"A mechanical soft diet consists of foods that are soft in texture and easy to chew and swallow, with modification of the texture achieved through methods such as chopping, grinding, mashing, or cooking foods until tender. The goal is to reduce the mechanical effort required to chew food while still allowing a broader variety of foods than a full-liquid or pureed diet. Depending on the patient''s needs, foods from a regular diet can be modified to achieve the appropriate texture. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"easy to chew foods, including foods in the regular diet\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"A mechanical soft diet consists of foods that are soft in texture and easy to chew and swallow, with modification of the texture achieved through methods such as chopping, grinding, mashing, or cooking foods until tender. The goal is to reduce the mechanical effort required to chew food while still allowing a broader variety of foods than a full-liquid or pureed diet. Depending on the patient''s needs, foods from a regular diet can be modified to achieve the appropriate texture. \n\nA mechanical soft diet is therefore primarily defined by texture and ease of chewing, not by whether foods are liquid or low in fiber. It may be prescribed for patients with difficulty chewing because of dental problems, oral surgery, weakness, or other conditions affecting chewing. The specific texture should always be matched to the patient''s swallowing ability because a mechanical soft diet is not automatically appropriate for someone with dysphagia.","whyWrongChoices":"Alternative options: soft foods, liquid foods, low fiber foods"}'::jsonb),
('mc:a diabetic patient with hba1c test result of 10% is indicative of glucose control.:::poor', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a diabetic patient with hba1c test result of 10% is indicative of glucose control.', 'Poor', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An HbA1c of 10% indicates poor glycemic control and reflects substantially elevated average blood glucose over approximately the preceding 2–3 months. HbA1c measures the percentage of hemoglobin that has glucose attached to it (glycated hemoglobin). The higher the average blood glucose concentration, the greater the proportion of glycated hemoglobin. An HbA1c of 10% corresponds to an estimated average glucose (eAG) of approximately 240 mg/dL (13.3 mmol/L). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Poor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An HbA1c of 10% indicates poor glycemic control and reflects substantially elevated average blood glucose over approximately the preceding 2–3 months. HbA1c measures the percentage of hemoglobin that has glucose attached to it (glycated hemoglobin). The higher the average blood glucose concentration, the greater the proportion of glycated hemoglobin. An HbA1c of 10% corresponds to an estimated average glucose (eAG) of approximately 240 mg/dL (13.3 mmol/L). \n\nFor most nonpregnant adults with diabetes, the commonly recommended treatment goal is an HbA1c of <7%, although targets should be individualized according to age, comorbidities, hypoglycemia risk, life expectancy, and patient preferences.","whyWrongChoices":"Alternative options: Good, Fair, Moderate"}'::jsonb),
('mc:a diabetic patient with hba1c test result of 10% is indicative of glucose control.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a diabetic patient with hba1c test result of 10% is indicative of glucose control.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"An HbA1c of 10% indicates poor glycemic control and reflects substantially elevated average blood glucose over approximately the preceding 2–3 months. HbA1c measures the percentage of hemoglobin that has glucose attached to it (glycated hemoglobin). The higher the average blood glucose concentration, the greater the proportion of glycated hemoglobin. An HbA1c of 10% corresponds to an estimated average glucose (eAG) of approximately 240 mg/dL (13.3 mmol/L). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Poor\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"An HbA1c of 10% indicates poor glycemic control and reflects substantially elevated average blood glucose over approximately the preceding 2–3 months. HbA1c measures the percentage of hemoglobin that has glucose attached to it (glycated hemoglobin). The higher the average blood glucose concentration, the greater the proportion of glycated hemoglobin. An HbA1c of 10% corresponds to an estimated average glucose (eAG) of approximately 240 mg/dL (13.3 mmol/L). \n\nFor most nonpregnant adults with diabetes, the commonly recommended treatment goal is an HbA1c of <7%, although targets should be individualized according to age, comorbidities, hypoglycemia risk, life expectancy, and patient preferences.","whyWrongChoices":"Alternative options: Good, Fair, Moderate"}'::jsonb)
