INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:milk substitute given for patient with phenylketonuria:::phenex-1', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'milk substitute given for patient with phenylketonuria', 'Phenex-1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phenylketonuria (PKU) is an autosomal recessive inborn error of metabolism caused by deficiency of the enzyme phenylalanine hydroxylase (PAH). As a result, phenylalanine cannot be adequately converted to tyrosine, leading to the accumulation of phenylalanine in the blood and brain. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Phenex-1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phenylketonuria (PKU) is an autosomal recessive inborn error of metabolism caused by deficiency of the enzyme phenylalanine hydroxylase (PAH). As a result, phenylalanine cannot be adequately converted to tyrosine, leading to the accumulation of phenylalanine in the blood and brain. \n\nPhenex-1 is one such formula designed specifically for infants with PKU, providing essential amino acids (except phenylalanine), vitamins, minerals, and energy to support normal growth and development.","whyWrongChoices":"Alternative options: Lonalac, Soyalac, Probana"}'::jsonb),
('mc:milk substitute given for patient with phenylketonuria:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'milk substitute given for patient with phenylketonuria', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Phenylketonuria (PKU) is an autosomal recessive inborn error of metabolism caused by deficiency of the enzyme phenylalanine hydroxylase (PAH). As a result, phenylalanine cannot be adequately converted to tyrosine, leading to the accumulation of phenylalanine in the blood and brain. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Phenex-1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Phenylketonuria (PKU) is an autosomal recessive inborn error of metabolism caused by deficiency of the enzyme phenylalanine hydroxylase (PAH). As a result, phenylalanine cannot be adequately converted to tyrosine, leading to the accumulation of phenylalanine in the blood and brain. \n\nPhenex-1 is one such formula designed specifically for infants with PKU, providing essential amino acids (except phenylalanine), vitamins, minerals, and energy to support normal growth and development.","whyWrongChoices":"Alternative options: Lonalac, Soyalac, Probana"}'::jsonb),
('mc:a low phosphorous diet contains less than mg phosphorous:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a low phosphorous diet contains less than mg phosphorous', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For traditional renal diet-therapy teaching, a low-phosphorus diet is generally defined as providing less than 800–1,000 mg phosphorus per day, with the exact prescription individualized according to renal function, serum phosphorus, dietary protein requirements, and dialysis status. Therefore, among the choices given, less than 1,000 mg/day is the best answer.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1000 mg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For traditional renal diet-therapy teaching, a low-phosphorus diet is generally defined as providing less than 800–1,000 mg phosphorus per day, with the exact prescription individualized according to renal function, serum phosphorus, dietary protein requirements, and dialysis status. Therefore, among the choices given, less than 1,000 mg/day is the best answer.","whyWrongChoices":"Alternative options: 1200 mg, 1400 mg, 1600 mg"}'::jsonb),
('mc:designed to maximize post-workout refueling of muscle glycogen; promote greater recovery of muscle energy and muscle protein resynthesis than carbohydrate drinks.:::recovery drinks', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'designed to maximize post-workout refueling of muscle glycogen; promote greater recovery of muscle energy and muscle protein resynthesis than carbohydrate drinks.', 'Recovery drinks', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Recovery drinks are specifically formulated with a specific carbohydrate-to-protein ratio (typically 3:1 or 4:1). The targeted dose of fast-acting carbohydrates quickly replenishes depleted muscle glycogen stores after intense exercise.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Recovery drinks\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Recovery drinks are specifically formulated with a specific carbohydrate-to-protein ratio (typically 3:1 or 4:1). The targeted dose of fast-acting carbohydrates quickly replenishes depleted muscle glycogen stores after intense exercise.\n\nResearch shows that adding protein to a post-workout carbohydrate drink stimulates greater glycogen resynthesis than carbohydrates alone, as the combination triggers a more robust insulin response (which drives glucose into muscle cells).\n\nWhile traditional sports drinks only provide carbohydrates and electrolytes to maintain hydration and energy during exercise, recovery drinks deliver essential amino acids (from protein) to repair muscle tissue damage and kickstart protein synthesis after exercise.","whyWrongChoices":"Alternative options: Sports drinks, Protein shakes, Energy bars"}'::jsonb),
('mc:designed to maximize post-workout refueling of muscle glycogen; promote greater recovery of muscle energy and muscle protein resynthesis than carbohydrate drinks.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'designed to maximize post-workout refueling of muscle glycogen; promote greater recovery of muscle energy and muscle protein resynthesis than carbohydrate drinks.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Recovery drinks are specifically formulated with a specific carbohydrate-to-protein ratio (typically 3:1 or 4:1). The targeted dose of fast-acting carbohydrates quickly replenishes depleted muscle glycogen stores after intense exercise.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Recovery drinks\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Recovery drinks are specifically formulated with a specific carbohydrate-to-protein ratio (typically 3:1 or 4:1). The targeted dose of fast-acting carbohydrates quickly replenishes depleted muscle glycogen stores after intense exercise.\n\nResearch shows that adding protein to a post-workout carbohydrate drink stimulates greater glycogen resynthesis than carbohydrates alone, as the combination triggers a more robust insulin response (which drives glucose into muscle cells).\n\nWhile traditional sports drinks only provide carbohydrates and electrolytes to maintain hydration and energy during exercise, recovery drinks deliver essential amino acids (from protein) to repair muscle tissue damage and kickstart protein synthesis after exercise.","whyWrongChoices":"Alternative options: Sports drinks, Protein shakes, Energy bars"}'::jsonb),
('mc:the complex formed when bile salts combine with lipid material to facilitate digestion:::micelle', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the complex formed when bile salts combine with lipid material to facilitate digestion', 'Micelle', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Micelles are small, water-soluble complexes formed in the lumen of the small intestine when bile salts combine with the products of lipid digestion, including free fatty acids, monoglycerides, cholesterol, phospholipids, and fat-soluble vitamins (A, D, E, and K). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micelle\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Micelles are small, water-soluble complexes formed in the lumen of the small intestine when bile salts combine with the products of lipid digestion, including free fatty acids, monoglycerides, cholesterol, phospholipids, and fat-soluble vitamins (A, D, E, and K). \n\nThe primary function of micelles is to transport these lipid digestion products across the watery environment of the intestinal lumen to the brush border of enterocytes, where they are absorbed. Without bile salts and micelle formation, lipid absorption would be markedly impaired, particularly that of long-chain fatty acids and fat-soluble vitamins. \n\nFor the NDLE, distinguish micelles from chylomicrons. Micelles are involved in intestinal absorption, whereas chylomicrons are responsible for transporting absorbed dietary lipids from the intestine to the circulation.","whyWrongChoices":"Alternative options: Chylomicron, HDL, LDL"}'::jsonb),
('mc:the complex formed when bile salts combine with lipid material to facilitate digestion:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the complex formed when bile salts combine with lipid material to facilitate digestion', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Micelles are small, water-soluble complexes formed in the lumen of the small intestine when bile salts combine with the products of lipid digestion, including free fatty acids, monoglycerides, cholesterol, phospholipids, and fat-soluble vitamins (A, D, E, and K). ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Micelle\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Micelles are small, water-soluble complexes formed in the lumen of the small intestine when bile salts combine with the products of lipid digestion, including free fatty acids, monoglycerides, cholesterol, phospholipids, and fat-soluble vitamins (A, D, E, and K). \n\nThe primary function of micelles is to transport these lipid digestion products across the watery environment of the intestinal lumen to the brush border of enterocytes, where they are absorbed. Without bile salts and micelle formation, lipid absorption would be markedly impaired, particularly that of long-chain fatty acids and fat-soluble vitamins. \n\nFor the NDLE, distinguish micelles from chylomicrons. Micelles are involved in intestinal absorption, whereas chylomicrons are responsible for transporting absorbed dietary lipids from the intestine to the circulation.","whyWrongChoices":"Alternative options: Chylomicron, HDL, LDL"}'::jsonb),
('mc:the conservative management of chronic kidney disease which is characterized by progressive and irreversible destruction of nephrons consists of::::diet and drugs', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the conservative management of chronic kidney disease which is characterized by progressive and irreversible destruction of nephrons consists of:', 'diet and drugs', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Conservative management of chronic kidney disease (CKD) aims to slow disease progression, manage complications, and maintain quality of life without renal replacement therapy. It includes appropriate dietary management and pharmacologic treatment, along with control of blood pressure, diabetes, cardiovascular risk factors, electrolyte and acid-base abnormalities, anemia, and other complications. Nutrition therapy may involve individualized adjustments to protein, sodium, potassium, phosphorus, and energy intake depending on the CKD stage and laboratory findings. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diet and drugs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Conservative management of chronic kidney disease (CKD) aims to slow disease progression, manage complications, and maintain quality of life without renal replacement therapy. It includes appropriate dietary management and pharmacologic treatment, along with control of blood pressure, diabetes, cardiovascular risk factors, electrolyte and acid-base abnormalities, anemia, and other complications. Nutrition therapy may involve individualized adjustments to protein, sodium, potassium, phosphorus, and energy intake depending on the CKD stage and laboratory findings. \n\nDialysis and kidney transplantation are forms of kidney replacement therapy, not conservative management. Importantly, conservative management is not simply “diet only”; medications and comprehensive medical management are integral.","whyWrongChoices":"Alternative options: diet only, dialysis, kidney transplant"}'::jsonb),
('mc:the conservative management of chronic kidney disease which is characterized by progressive and irreversible destruction of nephrons consists of::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the conservative management of chronic kidney disease which is characterized by progressive and irreversible destruction of nephrons consists of:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Conservative management of chronic kidney disease (CKD) aims to slow disease progression, manage complications, and maintain quality of life without renal replacement therapy. It includes appropriate dietary management and pharmacologic treatment, along with control of blood pressure, diabetes, cardiovascular risk factors, electrolyte and acid-base abnormalities, anemia, and other complications. Nutrition therapy may involve individualized adjustments to protein, sodium, potassium, phosphorus, and energy intake depending on the CKD stage and laboratory findings. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"diet and drugs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Conservative management of chronic kidney disease (CKD) aims to slow disease progression, manage complications, and maintain quality of life without renal replacement therapy. It includes appropriate dietary management and pharmacologic treatment, along with control of blood pressure, diabetes, cardiovascular risk factors, electrolyte and acid-base abnormalities, anemia, and other complications. Nutrition therapy may involve individualized adjustments to protein, sodium, potassium, phosphorus, and energy intake depending on the CKD stage and laboratory findings. \n\nDialysis and kidney transplantation are forms of kidney replacement therapy, not conservative management. Importantly, conservative management is not simply “diet only”; medications and comprehensive medical management are integral.","whyWrongChoices":"Alternative options: diet only, dialysis, kidney transplant"}'::jsonb),
('mc:cho 900 kcal is % of ter 1500 kcal.:::60%', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'cho 900 kcal is % of ter 1500 kcal.', '60%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To determine the percentage of total energy provided by carbohydrate:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"60%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To determine the percentage of total energy provided by carbohydrate:\n % of TER = [(kcal from CHO) ÷ TER] * 100 = (900 kcal ÷ 1500) * 100 = 60% \n\nTherefore, carbohydrate provides 60% of the TER. This type of calculation is commonly used when evaluating whether a patient''s macronutrient distribution meets the prescribed nutrition plan.","whyWrongChoices":"Alternative options: 40%, 50%, 70%"}'::jsonb),
('mc:cho 900 kcal is % of ter 1500 kcal.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'cho 900 kcal is % of ter 1500 kcal.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To determine the percentage of total energy provided by carbohydrate:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"60%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To determine the percentage of total energy provided by carbohydrate:\n % of TER = [(kcal from CHO) ÷ TER] * 100 = (900 kcal ÷ 1500) * 100 = 60% \n\nTherefore, carbohydrate provides 60% of the TER. This type of calculation is commonly used when evaluating whether a patient''s macronutrient distribution meets the prescribed nutrition plan.","whyWrongChoices":"Alternative options: 40%, 50%, 70%"}'::jsonb),
('mc:the normal protein requirement of a filipino adult.:::1g/kdbw', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the normal protein requirement of a filipino adult.', '1g/KDBW', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For Philippine nutrition assessment and meal planning, the commonly used reference for the protein requirement of a healthy Filipino adult is approximately 1.0–1.1 g/kg body weight per day, depending on the reference and individual circumstances.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1g/KDBW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For Philippine nutrition assessment and meal planning, the commonly used reference for the protein requirement of a healthy Filipino adult is approximately 1.0–1.1 g/kg body weight per day, depending on the reference and individual circumstances.\n\nProtein needs are not identical for everyone. Requirements may increase during pregnancy, lactation, older age, intense physical activity, illness, trauma, and other conditions associated with increased protein needs. For clinical nutrition, the appropriate weight basis and protein target should be individualized.","whyWrongChoices":"Alternative options: 5g/KDBW, 2g/KDBW, 3g/KDBW"}'::jsonb),
('mc:the normal protein requirement of a filipino adult.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the normal protein requirement of a filipino adult.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For Philippine nutrition assessment and meal planning, the commonly used reference for the protein requirement of a healthy Filipino adult is approximately 1.0–1.1 g/kg body weight per day, depending on the reference and individual circumstances.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1g/KDBW\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For Philippine nutrition assessment and meal planning, the commonly used reference for the protein requirement of a healthy Filipino adult is approximately 1.0–1.1 g/kg body weight per day, depending on the reference and individual circumstances.\n\nProtein needs are not identical for everyone. Requirements may increase during pregnancy, lactation, older age, intense physical activity, illness, trauma, and other conditions associated with increased protein needs. For clinical nutrition, the appropriate weight basis and protein target should be individualized.","whyWrongChoices":"Alternative options: 5g/KDBW, 2g/KDBW, 3g/KDBW"}'::jsonb),
('mc:a primary feature of emphysema is::::destruction of the walls separating the alveoli', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a primary feature of emphysema is:', 'destruction of the walls separating the alveoli', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Emphysema is a form of COPD characterized by abnormal and permanent enlargement of airspaces distal to the terminal bronchioles, accompanied by destruction of alveolar walls and loss of the normal elastic recoil of the lungs. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"destruction of the walls separating the alveoli\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Emphysema is a form of COPD characterized by abnormal and permanent enlargement of airspaces distal to the terminal bronchioles, accompanied by destruction of alveolar walls and loss of the normal elastic recoil of the lungs. \n\nDestruction of the alveolar walls reduces the surface area available for gas exchange and causes neighboring alveoli to merge into larger, less efficient air spaces. Loss of elastic recoil also contributes to air trapping and difficulty exhaling, particularly during forced expiration.\n\nThis distinguishes emphysema from chronic bronchitis, in which chronic airway inflammation and excessive mucus production are more prominent features.","whyWrongChoices":"Alternative options: obstruction within the bronchi, obstruction within the bronchioles, excessive lung elasticity"}'::jsonb),
('mc:a primary feature of emphysema is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a primary feature of emphysema is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Emphysema is a form of COPD characterized by abnormal and permanent enlargement of airspaces distal to the terminal bronchioles, accompanied by destruction of alveolar walls and loss of the normal elastic recoil of the lungs. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"destruction of the walls separating the alveoli\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Emphysema is a form of COPD characterized by abnormal and permanent enlargement of airspaces distal to the terminal bronchioles, accompanied by destruction of alveolar walls and loss of the normal elastic recoil of the lungs. \n\nDestruction of the alveolar walls reduces the surface area available for gas exchange and causes neighboring alveoli to merge into larger, less efficient air spaces. Loss of elastic recoil also contributes to air trapping and difficulty exhaling, particularly during forced expiration.\n\nThis distinguishes emphysema from chronic bronchitis, in which chronic airway inflammation and excessive mucus production are more prominent features.","whyWrongChoices":"Alternative options: obstruction within the bronchi, obstruction within the bronchioles, excessive lung elasticity"}'::jsonb),
('mc:a physician ordered 1500 kcal tube feeding formula, 1.5:1 dilution every 4 hours. the volume per feeding is::::167 ml/feed', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a physician ordered 1500 kcal tube feeding formula, 1.5:1 dilution every 4 hours. the volume per feeding is:', '167 mL/feed', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"First, determine the total volume of formula required: (1500 kcal ÷ 1.5 kcal/mL) = 1000 mL ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"167 mL/feed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"First, determine the total volume of formula required: (1500 kcal ÷ 1.5 kcal/mL) = 1000 mL \n\nSince feeding is given every 4 hours, the patient receives: 24 ÷ 4 = 6 feedings / day \n\nTherefore: 1000 mL ÷ 6 = 166.7 mL / feed \nRounded to the nearest whole number: 167 ml / feed","whyWrongChoices":"Alternative options: 250 mL/feed, 150 mL/feed, 300 mL/feed"}'::jsonb),
('mc:a physician ordered 1500 kcal tube feeding formula, 1.5:1 dilution every 4 hours. the volume per feeding is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a physician ordered 1500 kcal tube feeding formula, 1.5:1 dilution every 4 hours. the volume per feeding is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"First, determine the total volume of formula required: (1500 kcal ÷ 1.5 kcal/mL) = 1000 mL ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"167 mL/feed\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"First, determine the total volume of formula required: (1500 kcal ÷ 1.5 kcal/mL) = 1000 mL \n\nSince feeding is given every 4 hours, the patient receives: 24 ÷ 4 = 6 feedings / day \n\nTherefore: 1000 mL ÷ 6 = 166.7 mL / feed \nRounded to the nearest whole number: 167 ml / feed","whyWrongChoices":"Alternative options: 250 mL/feed, 150 mL/feed, 300 mL/feed"}'::jsonb),
('mc:a bmi of 23 kg/m² according to the asia-pacific classification is considered::::overweight', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a bmi of 23 kg/m² according to the asia-pacific classification is considered:', 'Overweight', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Asia-Pacific BMI classification uses lower BMI cutoffs for overweight and obesity compared with the standard WHO classification because Asian populations may have a higher risk of type 2 diabetes and cardiovascular disease at lower BMI values. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Overweight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Asia-Pacific BMI classification uses lower BMI cutoffs for overweight and obesity compared with the standard WHO classification because Asian populations may have a higher risk of type 2 diabetes and cardiovascular disease at lower BMI values. \n\nUnder the Asia-Pacific classification: \n• <18.5 kg/m² → Underweight \n• 18.5–22.9 kg/m² → Normal \n• 23.0–24.9 kg/m² → Overweight \n• 25.0–29.9 kg/m² → Obese I \n• ≥30.0 kg/m² → Obese II \n\nTherefore, a BMI of 23 kg/m² is classified as overweight.","whyWrongChoices":"Alternative options: Normal, Obese, None of the above"}'::jsonb),
('mc:a bmi of 23 kg/m² according to the asia-pacific classification is considered::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a bmi of 23 kg/m² according to the asia-pacific classification is considered:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Asia-Pacific BMI classification uses lower BMI cutoffs for overweight and obesity compared with the standard WHO classification because Asian populations may have a higher risk of type 2 diabetes and cardiovascular disease at lower BMI values. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Overweight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Asia-Pacific BMI classification uses lower BMI cutoffs for overweight and obesity compared with the standard WHO classification because Asian populations may have a higher risk of type 2 diabetes and cardiovascular disease at lower BMI values. \n\nUnder the Asia-Pacific classification: \n• <18.5 kg/m² → Underweight \n• 18.5–22.9 kg/m² → Normal \n• 23.0–24.9 kg/m² → Overweight \n• 25.0–29.9 kg/m² → Obese I \n• ≥30.0 kg/m² → Obese II \n\nTherefore, a BMI of 23 kg/m² is classified as overweight.","whyWrongChoices":"Alternative options: Normal, Obese, None of the above"}'::jsonb),
('mc:a diet prescription of 1800 kcal with distribution of c 60% p 15% f 25% will provide::::c 270 g, p 70 g, f 50 g', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a diet prescription of 1800 kcal with distribution of c 60% p 15% f 25% will provide:', 'C 270 g, P 70 g, F 50 g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the grams of each macronutrient: ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"C 270 g, P 70 g, F 50 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the grams of each macronutrient: \n\n1. Carbohydrate \nCarbohydrate provides 4 kcal/g: \nCHO: 60% → 1,080 kcal ÷ 4 = 270 g \n\n2. Protein \nProtein provides 4 kcal/g:\nProtein: 15% → 270 kcal ÷ 4 = 67.5 g → 70 g \nUsing the rounding convention applied in this question, 67.5 g is rounded to 70 g. \n\n3. Fat \nFat provides 9 kcal/g: \nFat: 25% → 450 kcal ÷ 9 = 50 g \n\nTherefore, the prescribed diet provides approximately 270 g carbohydrate, 70 g protein, and 50 g fat.","whyWrongChoices":"Alternative options: C 275 g, P 67.5g, F 50 g, C 275 g, P 70 g, F 50 g, C 270 g, P 70 g, F 55 g"}'::jsonb),
('mc:a diet prescription of 1800 kcal with distribution of c 60% p 15% f 25% will provide::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a diet prescription of 1800 kcal with distribution of c 60% p 15% f 25% will provide:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"To calculate the grams of each macronutrient: ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"C 270 g, P 70 g, F 50 g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"To calculate the grams of each macronutrient: \n\n1. Carbohydrate \nCarbohydrate provides 4 kcal/g: \nCHO: 60% → 1,080 kcal ÷ 4 = 270 g \n\n2. Protein \nProtein provides 4 kcal/g:\nProtein: 15% → 270 kcal ÷ 4 = 67.5 g → 70 g \nUsing the rounding convention applied in this question, 67.5 g is rounded to 70 g. \n\n3. Fat \nFat provides 9 kcal/g: \nFat: 25% → 450 kcal ÷ 9 = 50 g \n\nTherefore, the prescribed diet provides approximately 270 g carbohydrate, 70 g protein, and 50 g fat.","whyWrongChoices":"Alternative options: C 275 g, P 67.5g, F 50 g, C 275 g, P 70 g, F 50 g, C 270 g, P 70 g, F 55 g"}'::jsonb),
('mc:the average respiratory quotient of a mixed diet::::0.85', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the average respiratory quotient of a mixed diet:', '0.85', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The respiratory quotient (RQ) is the ratio of carbon dioxide produced to oxygen consumed during metabolism: RQ = VCO₂ / VO₂. The RQ differs according to the macronutrient being oxidized. Carbohydrate has an RQ of 1.0, protein approximately 0.8, and fat approximately 0.7. Because a typical mixed diet supplies a combination of carbohydrate, protein, and fat, its average RQ is approximately 0.8–0.85, with 0.85 being the conventional value used in nutrition and indirect calorimetry questions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.85\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The respiratory quotient (RQ) is the ratio of carbon dioxide produced to oxygen consumed during metabolism: RQ = VCO₂ / VO₂. The RQ differs according to the macronutrient being oxidized. Carbohydrate has an RQ of 1.0, protein approximately 0.8, and fat approximately 0.7. Because a typical mixed diet supplies a combination of carbohydrate, protein, and fat, its average RQ is approximately 0.8–0.85, with 0.85 being the conventional value used in nutrition and indirect calorimetry questions.","whyWrongChoices":"Alternative options: 0.65, 0.75, 0.95"}'::jsonb),
('mc:the average respiratory quotient of a mixed diet::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the average respiratory quotient of a mixed diet:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The respiratory quotient (RQ) is the ratio of carbon dioxide produced to oxygen consumed during metabolism: RQ = VCO₂ / VO₂. The RQ differs according to the macronutrient being oxidized. Carbohydrate has an RQ of 1.0, protein approximately 0.8, and fat approximately 0.7. Because a typical mixed diet supplies a combination of carbohydrate, protein, and fat, its average RQ is approximately 0.8–0.85, with 0.85 being the conventional value used in nutrition and indirect calorimetry questions.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.85\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The respiratory quotient (RQ) is the ratio of carbon dioxide produced to oxygen consumed during metabolism: RQ = VCO₂ / VO₂. The RQ differs according to the macronutrient being oxidized. Carbohydrate has an RQ of 1.0, protein approximately 0.8, and fat approximately 0.7. Because a typical mixed diet supplies a combination of carbohydrate, protein, and fat, its average RQ is approximately 0.8–0.85, with 0.85 being the conventional value used in nutrition and indirect calorimetry questions.","whyWrongChoices":"Alternative options: 0.65, 0.75, 0.95"}'::jsonb),
('mc:dietary fibers are useful in preventing hypercholesterolemia because they::::bind cholesterol containing bile acids which are eventually excreted', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary fibers are useful in preventing hypercholesterolemia because they:', 'bind cholesterol containing bile acids which are eventually excreted', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Certain soluble, viscous dietary fibers can help lower blood LDL cholesterol by increasing the excretion of bile acids and cholesterol in the feces. The liver must use circulating cholesterol to synthesize new bile acids, thereby increasing hepatic demand for cholesterol and contributing to lower LDL cholesterol concentrations. Examples of cholesterol-lowering soluble fibers include β-glucan from oats and barley, psyllium, and some fibers from legumes. The original wording is somewhat simplified because fiber does not literally “bind cholesterol-containing bile acids” in every case; increased bile acid excretion and fermentation-related mechanisms both contribute.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bind cholesterol containing bile acids which are eventually excreted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Certain soluble, viscous dietary fibers can help lower blood LDL cholesterol by increasing the excretion of bile acids and cholesterol in the feces. The liver must use circulating cholesterol to synthesize new bile acids, thereby increasing hepatic demand for cholesterol and contributing to lower LDL cholesterol concentrations. Examples of cholesterol-lowering soluble fibers include β-glucan from oats and barley, psyllium, and some fibers from legumes. The original wording is somewhat simplified because fiber does not literally “bind cholesterol-containing bile acids” in every case; increased bile acid excretion and fermentation-related mechanisms both contribute.","whyWrongChoices":"Alternative options: produce HDL cholesterol, are antioxidants, carriers of omega 3-fatty acids"}'::jsonb),
('mc:dietary fibers are useful in preventing hypercholesterolemia because they::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'dietary fibers are useful in preventing hypercholesterolemia because they:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Certain soluble, viscous dietary fibers can help lower blood LDL cholesterol by increasing the excretion of bile acids and cholesterol in the feces. The liver must use circulating cholesterol to synthesize new bile acids, thereby increasing hepatic demand for cholesterol and contributing to lower LDL cholesterol concentrations. Examples of cholesterol-lowering soluble fibers include β-glucan from oats and barley, psyllium, and some fibers from legumes. The original wording is somewhat simplified because fiber does not literally “bind cholesterol-containing bile acids” in every case; increased bile acid excretion and fermentation-related mechanisms both contribute.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"bind cholesterol containing bile acids which are eventually excreted\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Certain soluble, viscous dietary fibers can help lower blood LDL cholesterol by increasing the excretion of bile acids and cholesterol in the feces. The liver must use circulating cholesterol to synthesize new bile acids, thereby increasing hepatic demand for cholesterol and contributing to lower LDL cholesterol concentrations. Examples of cholesterol-lowering soluble fibers include β-glucan from oats and barley, psyllium, and some fibers from legumes. The original wording is somewhat simplified because fiber does not literally “bind cholesterol-containing bile acids” in every case; increased bile acid excretion and fermentation-related mechanisms both contribute.","whyWrongChoices":"Alternative options: produce HDL cholesterol, are antioxidants, carriers of omega 3-fatty acids"}'::jsonb),
('mc:drinking coffee or tea together with an iron-rich meal primarily decreases the absorption of which type of iron?:::non-heme iron', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'drinking coffee or tea together with an iron-rich meal primarily decreases the absorption of which type of iron?', 'Non-heme iron', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Coffee and tea contain polyphenols and tannins that form insoluble complexes with non-heme iron, substantially reducing its intestinal absorption. The inhibitory effect is greatest when these beverages are consumed with or shortly after meals. Heme iron, derived from animal foods, is absorbed through a different mechanism and is much less affected by dietary inhibitors. Vitamin C can counteract this inhibition by reducing ferric iron (Fe³⁺) to the more absorbable ferrous form (Fe²⁺).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Non-heme iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Coffee and tea contain polyphenols and tannins that form insoluble complexes with non-heme iron, substantially reducing its intestinal absorption. The inhibitory effect is greatest when these beverages are consumed with or shortly after meals. Heme iron, derived from animal foods, is absorbed through a different mechanism and is much less affected by dietary inhibitors. Vitamin C can counteract this inhibition by reducing ferric iron (Fe³⁺) to the more absorbable ferrous form (Fe²⁺).","whyWrongChoices":"Alternative options: Heme iron, Ferritin-bound iron, Both heme and non-heme iron equally"}'::jsonb),
('mc:drinking coffee or tea together with an iron-rich meal primarily decreases the absorption of which type of iron?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'drinking coffee or tea together with an iron-rich meal primarily decreases the absorption of which type of iron?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Coffee and tea contain polyphenols and tannins that form insoluble complexes with non-heme iron, substantially reducing its intestinal absorption. The inhibitory effect is greatest when these beverages are consumed with or shortly after meals. Heme iron, derived from animal foods, is absorbed through a different mechanism and is much less affected by dietary inhibitors. Vitamin C can counteract this inhibition by reducing ferric iron (Fe³⁺) to the more absorbable ferrous form (Fe²⁺).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Non-heme iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Coffee and tea contain polyphenols and tannins that form insoluble complexes with non-heme iron, substantially reducing its intestinal absorption. The inhibitory effect is greatest when these beverages are consumed with or shortly after meals. Heme iron, derived from animal foods, is absorbed through a different mechanism and is much less affected by dietary inhibitors. Vitamin C can counteract this inhibition by reducing ferric iron (Fe³⁺) to the more absorbable ferrous form (Fe²⁺).","whyWrongChoices":"Alternative options: Heme iron, Ferritin-bound iron, Both heme and non-heme iron equally"}'::jsonb),
('mc:which of the following describes the maximum amount of bone tissue attained after skeletal development is completed and serves as an important determinant of bone health in adulthood?:::peak bone mass', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following describes the maximum amount of bone tissue attained after skeletal development is completed and serves as an important determinant of bone health in adulthood?', 'Peak Bone Mass', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Peak bone mass (PBM) is the maximum amount of bone tissue accumulated by an individual at the end of skeletal maturation, usually achieved during the late teens to early 30s, depending on the skeletal site, sex, genetics, and lifestyle factors. It represents the highest level of bone strength attained before the gradual age-related decline in bone mass begins. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Peak Bone Mass\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Peak bone mass (PBM) is the maximum amount of bone tissue accumulated by an individual at the end of skeletal maturation, usually achieved during the late teens to early 30s, depending on the skeletal site, sex, genetics, and lifestyle factors. It represents the highest level of bone strength attained before the gradual age-related decline in bone mass begins. \n\nPeak bone mass is influenced by several factors, including: \n• Genetics (the strongest determinant) \n• Adequate calcium and vitamin D intake \n• Regular weight-bearing and resistance exercise \n• Hormonal status (especially estrogen and testosterone) \n• Adequate protein intake \n• Avoidance of smoking and excessive alcohol consumption\n\nA higher peak bone mass reduces the risk of osteopenia, osteoporosis, and fragility fractures later in life. Therefore, childhood, adolescence, and young adulthood are considered critical periods for optimizing bone health.","whyWrongChoices":"Alternative options: Bone mineral content, Bone mineral density, Bone mass"}'::jsonb),
('mc:which lipoprotein is primarily responsible for transporting dietary triglycerides from the intestine to peripheral tissues?:::chylomicrons', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which lipoprotein is primarily responsible for transporting dietary triglycerides from the intestine to peripheral tissues?', 'Chylomicrons', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chylomicrons are the largest and least dense lipoproteins. They are synthesized in the intestinal mucosal cells after dietary fat absorption and transport exogenous triglycerides, cholesterol, fat-soluble vitamins, and phospholipids through the lymphatic system before entering the bloodstream. Lipoprotein lipase (LPL), activated by apolipoprotein C-II, hydrolyzes triglycerides in chylomicrons, releasing free fatty acids for uptake by adipose tissue and skeletal muscle. The remaining chylomicron remnants are taken up by the liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chylomicrons\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chylomicrons are the largest and least dense lipoproteins. They are synthesized in the intestinal mucosal cells after dietary fat absorption and transport exogenous triglycerides, cholesterol, fat-soluble vitamins, and phospholipids through the lymphatic system before entering the bloodstream. Lipoprotein lipase (LPL), activated by apolipoprotein C-II, hydrolyzes triglycerides in chylomicrons, releasing free fatty acids for uptake by adipose tissue and skeletal muscle. The remaining chylomicron remnants are taken up by the liver.","whyWrongChoices":"Alternative options: HDL, LDL, VLDL"}'::jsonb),
('mc:which lipoprotein is primarily responsible for transporting dietary triglycerides from the intestine to peripheral tissues?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which lipoprotein is primarily responsible for transporting dietary triglycerides from the intestine to peripheral tissues?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Chylomicrons are the largest and least dense lipoproteins. They are synthesized in the intestinal mucosal cells after dietary fat absorption and transport exogenous triglycerides, cholesterol, fat-soluble vitamins, and phospholipids through the lymphatic system before entering the bloodstream. Lipoprotein lipase (LPL), activated by apolipoprotein C-II, hydrolyzes triglycerides in chylomicrons, releasing free fatty acids for uptake by adipose tissue and skeletal muscle. The remaining chylomicron remnants are taken up by the liver.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chylomicrons\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Chylomicrons are the largest and least dense lipoproteins. They are synthesized in the intestinal mucosal cells after dietary fat absorption and transport exogenous triglycerides, cholesterol, fat-soluble vitamins, and phospholipids through the lymphatic system before entering the bloodstream. Lipoprotein lipase (LPL), activated by apolipoprotein C-II, hydrolyzes triglycerides in chylomicrons, releasing free fatty acids for uptake by adipose tissue and skeletal muscle. The remaining chylomicron remnants are taken up by the liver.","whyWrongChoices":"Alternative options: HDL, LDL, VLDL"}'::jsonb),
('mc:which enzyme is responsible for hydrolyzing triglycerides in circulating chylomicrons and vldl?:::lipoprotein lipase', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which enzyme is responsible for hydrolyzing triglycerides in circulating chylomicrons and vldl?', 'Lipoprotein lipase', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lipoprotein lipase (LPL) is an extracellular enzyme attached to the capillary endothelium of adipose tissue, skeletal muscle, and cardiac muscle. It hydrolyzes triglycerides contained in circulating chylomicrons and VLDL into free fatty acids and glycerol. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lipoprotein lipase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lipoprotein lipase (LPL) is an extracellular enzyme attached to the capillary endothelium of adipose tissue, skeletal muscle, and cardiac muscle. It hydrolyzes triglycerides contained in circulating chylomicrons and VLDL into free fatty acids and glycerol. \n\nThe released fatty acids are either: \n• Stored as triglycerides in adipose tissue, or \n• Oxidized by muscle tissue for energy. \n\nLPL activity is stimulated by apolipoprotein C-II, making Apo C-II an essential cofactor for normal triglyceride metabolism.","whyWrongChoices":"Alternative options: Hormone-sensitive lipase, Pancreatic lipase, Hepatic lipase"}'::jsonb),
('mc:which enzyme is responsible for hydrolyzing triglycerides in circulating chylomicrons and vldl?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which enzyme is responsible for hydrolyzing triglycerides in circulating chylomicrons and vldl?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Lipoprotein lipase (LPL) is an extracellular enzyme attached to the capillary endothelium of adipose tissue, skeletal muscle, and cardiac muscle. It hydrolyzes triglycerides contained in circulating chylomicrons and VLDL into free fatty acids and glycerol. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Lipoprotein lipase\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Lipoprotein lipase (LPL) is an extracellular enzyme attached to the capillary endothelium of adipose tissue, skeletal muscle, and cardiac muscle. It hydrolyzes triglycerides contained in circulating chylomicrons and VLDL into free fatty acids and glycerol. \n\nThe released fatty acids are either: \n• Stored as triglycerides in adipose tissue, or \n• Oxidized by muscle tissue for energy. \n\nLPL activity is stimulated by apolipoprotein C-II, making Apo C-II an essential cofactor for normal triglyceride metabolism.","whyWrongChoices":"Alternative options: Hormone-sensitive lipase, Pancreatic lipase, Hepatic lipase"}'::jsonb),
('mc:which of the following hormones primarily stimulates glycogen breakdown in the liver during fasting?:::glucagon', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following hormones primarily stimulates glycogen breakdown in the liver during fasting?', 'Glucagon', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glucagon is a peptide hormone secreted by the pancreatic α-cells in response to declining blood glucose concentrations. Its primary role is to maintain euglycemia during the post-absorptive state by stimulating hepatic glucose production. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucagon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glucagon is a peptide hormone secreted by the pancreatic α-cells in response to declining blood glucose concentrations. Its primary role is to maintain euglycemia during the post-absorptive state by stimulating hepatic glucose production. \n\nThe major metabolic actions of glucagon include: \n• Glycogenolysis – breakdown of liver glycogen into glucose.\n• Gluconeogenesis – synthesis of glucose from non-carbohydrate precursors such as lactate, glycerol, and glucogenic amino acids. \n• Lipolysis – indirectly promotes mobilization of fatty acids from adipose tissue. \n• Ketogenesis – enhances ketone body formation during prolonged fasting. It is important to note that skeletal muscle lacks glucagon receptors. \n\nTherefore, glucagon promotes glycogenolysis primarily in the liver, whereas muscle glycogen breakdown is stimulated mainly by epinephrine and muscle contraction.","whyWrongChoices":"Alternative options: Insulin, Leptin, Aldosterone"}'::jsonb),
('mc:which of the following hormones primarily stimulates glycogen breakdown in the liver during fasting?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following hormones primarily stimulates glycogen breakdown in the liver during fasting?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Glucagon is a peptide hormone secreted by the pancreatic α-cells in response to declining blood glucose concentrations. Its primary role is to maintain euglycemia during the post-absorptive state by stimulating hepatic glucose production. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Glucagon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Glucagon is a peptide hormone secreted by the pancreatic α-cells in response to declining blood glucose concentrations. Its primary role is to maintain euglycemia during the post-absorptive state by stimulating hepatic glucose production. \n\nThe major metabolic actions of glucagon include: \n• Glycogenolysis – breakdown of liver glycogen into glucose.\n• Gluconeogenesis – synthesis of glucose from non-carbohydrate precursors such as lactate, glycerol, and glucogenic amino acids. \n• Lipolysis – indirectly promotes mobilization of fatty acids from adipose tissue. \n• Ketogenesis – enhances ketone body formation during prolonged fasting. It is important to note that skeletal muscle lacks glucagon receptors. \n\nTherefore, glucagon promotes glycogenolysis primarily in the liver, whereas muscle glycogen breakdown is stimulated mainly by epinephrine and muscle contraction.","whyWrongChoices":"Alternative options: Insulin, Leptin, Aldosterone"}'::jsonb),
('mc:which of the following best describes the primary function of bile salts in lipid digestion?:::emulsify dietary fats and facilitate micelle formation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following best describes the primary function of bile salts in lipid digestion?', 'Emulsify dietary fats and facilitate micelle formation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bile salts are amphipathic molecules synthesized from cholesterol in the liver and stored in the gallbladder. Upon ingestion of dietary fat, they are released into the duodenum where they perform two major functions: ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Emulsify dietary fats and facilitate micelle formation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bile salts are amphipathic molecules synthesized from cholesterol in the liver and stored in the gallbladder. Upon ingestion of dietary fat, they are released into the duodenum where they perform two major functions: \n\n• Emulsification – breaking large fat globules into smaller droplets, thereby increasing the surface area available for pancreatic lipase. \n• Micelle formation – surrounding fatty acids, monoglycerides, cholesterol, and fat-soluble vitamins to facilitate their transport to the intestinal brush border for absorption. \n\nBile salts themselves do not digest fats; rather, they enhance the efficiency of pancreatic lipase and promote lipid absorption.","whyWrongChoices":"Alternative options: Hydrolyze triglycerides into fatty acids, Digest proteins in the stomach, Activate pancreatic amylase"}'::jsonb),
('mc:which of the following best describes the primary function of bile salts in lipid digestion?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following best describes the primary function of bile salts in lipid digestion?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Bile salts are amphipathic molecules synthesized from cholesterol in the liver and stored in the gallbladder. Upon ingestion of dietary fat, they are released into the duodenum where they perform two major functions: ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Emulsify dietary fats and facilitate micelle formation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Bile salts are amphipathic molecules synthesized from cholesterol in the liver and stored in the gallbladder. Upon ingestion of dietary fat, they are released into the duodenum where they perform two major functions: \n\n• Emulsification – breaking large fat globules into smaller droplets, thereby increasing the surface area available for pancreatic lipase. \n• Micelle formation – surrounding fatty acids, monoglycerides, cholesterol, and fat-soluble vitamins to facilitate their transport to the intestinal brush border for absorption. \n\nBile salts themselves do not digest fats; rather, they enhance the efficiency of pancreatic lipase and promote lipid absorption.","whyWrongChoices":"Alternative options: Hydrolyze triglycerides into fatty acids, Digest proteins in the stomach, Activate pancreatic amylase"}'::jsonb),
('mc:which of the following describes the maximum amount of bone tissue attained after skeletal development is completed and serves as an important determinant of bone health in adulthood?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following describes the maximum amount of bone tissue attained after skeletal development is completed and serves as an important determinant of bone health in adulthood?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Peak bone mass (PBM) is the maximum amount of bone tissue accumulated by an individual at the end of skeletal maturation, usually achieved during the late teens to early 30s, depending on the skeletal site, sex, genetics, and lifestyle factors. It represents the highest level of bone strength attained before the gradual age-related decline in bone mass begins. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Peak Bone Mass\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Peak bone mass (PBM) is the maximum amount of bone tissue accumulated by an individual at the end of skeletal maturation, usually achieved during the late teens to early 30s, depending on the skeletal site, sex, genetics, and lifestyle factors. It represents the highest level of bone strength attained before the gradual age-related decline in bone mass begins. \n\nPeak bone mass is influenced by several factors, including: \n• Genetics (the strongest determinant) \n• Adequate calcium and vitamin D intake \n• Regular weight-bearing and resistance exercise \n• Hormonal status (especially estrogen and testosterone) \n• Adequate protein intake \n• Avoidance of smoking and excessive alcohol consumption\n\nA higher peak bone mass reduces the risk of osteopenia, osteoporosis, and fragility fractures later in life. Therefore, childhood, adolescence, and young adulthood are considered critical periods for optimizing bone health.","whyWrongChoices":"Alternative options: Bone mineral content, Bone mineral density, Bone mass"}'::jsonb),
('mc:protein recommendation for adults with pressure injuries or significant wounds to promote wound healing::::1.5 – 2 g/kg', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'protein recommendation for adults with pressure injuries or significant wounds to promote wound healing:', '1.5 – 2 g/kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Protein is one of the most important nutrients for wound healing, as it is required for collagen synthesis, fibroblast proliferation, angiogenesis, immune function, and tissue repair. Inadequate protein intake delays wound healing, impairs immune responses, and increases the risk of wound infection and chronic non-healing wounds. Patients with pressure injuries, surgical wounds, burns, traumatic injuries, or chronic ulcers generally have increased protein requirements because of the increased metabolic demands associated with tissue repair. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1.5 – 2 g/kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Protein is one of the most important nutrients for wound healing, as it is required for collagen synthesis, fibroblast proliferation, angiogenesis, immune function, and tissue repair. Inadequate protein intake delays wound healing, impairs immune responses, and increases the risk of wound infection and chronic non-healing wounds. Patients with pressure injuries, surgical wounds, burns, traumatic injuries, or chronic ulcers generally have increased protein requirements because of the increased metabolic demands associated with tissue repair. \n\nCurrent clinical nutrition guidelines recommend approximately 1.25–1.5 g/kg/day of protein for most patients with pressure injuries and up to 1.5–2.0 g/kg/day for individuals with extensive wounds, burns, or severe catabolic conditions, provided renal function is adequate.","whyWrongChoices":"Alternative options: 20-25% of TER, 15-20% of TER, 50% of TER"}'::jsonb),
('mc:protein recommendation for adults with pressure injuries or significant wounds to promote wound healing::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'protein recommendation for adults with pressure injuries or significant wounds to promote wound healing:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Protein is one of the most important nutrients for wound healing, as it is required for collagen synthesis, fibroblast proliferation, angiogenesis, immune function, and tissue repair. Inadequate protein intake delays wound healing, impairs immune responses, and increases the risk of wound infection and chronic non-healing wounds. Patients with pressure injuries, surgical wounds, burns, traumatic injuries, or chronic ulcers generally have increased protein requirements because of the increased metabolic demands associated with tissue repair. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1.5 – 2 g/kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Protein is one of the most important nutrients for wound healing, as it is required for collagen synthesis, fibroblast proliferation, angiogenesis, immune function, and tissue repair. Inadequate protein intake delays wound healing, impairs immune responses, and increases the risk of wound infection and chronic non-healing wounds. Patients with pressure injuries, surgical wounds, burns, traumatic injuries, or chronic ulcers generally have increased protein requirements because of the increased metabolic demands associated with tissue repair. \n\nCurrent clinical nutrition guidelines recommend approximately 1.25–1.5 g/kg/day of protein for most patients with pressure injuries and up to 1.5–2.0 g/kg/day for individuals with extensive wounds, burns, or severe catabolic conditions, provided renal function is adequate.","whyWrongChoices":"Alternative options: 20-25% of TER, 15-20% of TER, 50% of TER"}'::jsonb),
('mc:which equation is currently recommended by kdigo for estimating glomerular filtration rate (egfr) in adults?:::ckd-epi 2021 equation', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which equation is currently recommended by kdigo for estimating glomerular filtration rate (egfr) in adults?', 'CKD-EPI 2021 equation', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Kidney Disease: Improving Global Outcomes (KDIGO) 2024 Clinical Practice Guideline recommends using the 2021 Chronic Kidney Disease Epidemiology Collaboration (CKD-EPI) creatinine equation as the preferred equation for estimating glomerular filtration rate (eGFR) in adults. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"CKD-EPI 2021 equation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Kidney Disease: Improving Global Outcomes (KDIGO) 2024 Clinical Practice Guideline recommends using the 2021 Chronic Kidney Disease Epidemiology Collaboration (CKD-EPI) creatinine equation as the preferred equation for estimating glomerular filtration rate (eGFR) in adults. \n\nThe CKD-EPI 2021 equation: \n• Estimates kidney function using serum creatinine, age, and sex \n• Removes the race coefficient that was included in earlier equations \n• Provides more equitable assessment across different populations \n• Generally demonstrates better accuracy than the older MDRD equation, particularly at higher GFR values \n\nEstimated GFR is essential for: \n• Diagnosing chronic kidney disease (CKD) \n• Staging CKD \n• Monitoring disease progression \n• Guiding medication dosing \n• Planning nutrition therapy","whyWrongChoices":"Alternative options: Cockcroft–Gault equation, MDRD equation, Jelliffe equation"}'::jsonb),
('mc:what are the physiological fuel values (atwater general energy factors) for carbohydrates, protein, fat, and alcohol in kcal/gram?:::carb: 4 kcal/g | protein: 4 kcal/g | fat: 9 kcal/g | alcohol: 7 kcal/g', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what are the physiological fuel values (atwater general energy factors) for carbohydrates, protein, fat, and alcohol in kcal/gram?', 'Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Atwater standard energy values account for heat of combustion adjusted for digestibility and urinary nitrogen losses: 4 kcal/g for CHO, 4 kcal/g for PRO, 9 kcal/g for Lipid, and 7 kcal/g for Alcohol.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Atwater standard energy values account for heat of combustion adjusted for digestibility and urinary nitrogen losses: 4 kcal/g for CHO, 4 kcal/g for PRO, 9 kcal/g for Lipid, and 7 kcal/g for Alcohol.","whyWrongChoices":"Alternative options: Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 8 kcal/g | Alcohol: 5 kcal/g, Carb: 3.75 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 9 kcal/g, Carb: 5 kcal/g | Protein: 5 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g"}'::jsonb),
('mc:which equation is currently recommended by kdigo for estimating glomerular filtration rate (egfr) in adults?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which equation is currently recommended by kdigo for estimating glomerular filtration rate (egfr) in adults?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The Kidney Disease: Improving Global Outcomes (KDIGO) 2024 Clinical Practice Guideline recommends using the 2021 Chronic Kidney Disease Epidemiology Collaboration (CKD-EPI) creatinine equation as the preferred equation for estimating glomerular filtration rate (eGFR) in adults. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"CKD-EPI 2021 equation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The Kidney Disease: Improving Global Outcomes (KDIGO) 2024 Clinical Practice Guideline recommends using the 2021 Chronic Kidney Disease Epidemiology Collaboration (CKD-EPI) creatinine equation as the preferred equation for estimating glomerular filtration rate (eGFR) in adults. \n\nThe CKD-EPI 2021 equation: \n• Estimates kidney function using serum creatinine, age, and sex \n• Removes the race coefficient that was included in earlier equations \n• Provides more equitable assessment across different populations \n• Generally demonstrates better accuracy than the older MDRD equation, particularly at higher GFR values \n\nEstimated GFR is essential for: \n• Diagnosing chronic kidney disease (CKD) \n• Staging CKD \n• Monitoring disease progression \n• Guiding medication dosing \n• Planning nutrition therapy","whyWrongChoices":"Alternative options: Cockcroft–Gault equation, MDRD equation, Jelliffe equation"}'::jsonb),
('mc:which medication is most strongly associated with folate deficiency during long-term therapy?:::methotrexate', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which medication is most strongly associated with folate deficiency during long-term therapy?', 'Methotrexate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Methotrexate is an antimetabolite that competitively inhibits dihydrofolate reductase (DHFR), the enzyme responsible for converting dihydrofolate into tetrahydrofolate, the biologically active form of folate. This inhibition impairs the synthesis of purines and thymidylate, ultimately reducing DNA and RNA synthesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Methotrexate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Methotrexate is an antimetabolite that competitively inhibits dihydrofolate reductase (DHFR), the enzyme responsible for converting dihydrofolate into tetrahydrofolate, the biologically active form of folate. This inhibition impairs the synthesis of purines and thymidylate, ultimately reducing DNA and RNA synthesis.\n\nBecause rapidly dividing cells rely heavily on folate-dependent DNA synthesis, long-term methotrexate therapy may lead to: \n• Folate deficiency \n• Megaloblastic anemia \n• Oral mucositis \n• Glossitis \n• Gastrointestinal disturbances\n• Elevated homocysteine levels \n\nMethotrexate is widely used in the treatment of: \n• Rheumatoid arthritis \n• Psoriasis \n• Certain cancers \n• Other autoimmune diseases \n\nTo reduce adverse effects while preserving therapeutic efficacy, patients receiving low-dose methotrexate for autoimmune diseases are commonly prescribed folic acid supplementation, usually on days when methotrexate is not taken or according to the physician''s protocol.","whyWrongChoices":"Alternative options: Digoxin, Omeprazole, Metformin"}'::jsonb),
('mc:which medication is most strongly associated with folate deficiency during long-term therapy?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which medication is most strongly associated with folate deficiency during long-term therapy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Methotrexate is an antimetabolite that competitively inhibits dihydrofolate reductase (DHFR), the enzyme responsible for converting dihydrofolate into tetrahydrofolate, the biologically active form of folate. This inhibition impairs the synthesis of purines and thymidylate, ultimately reducing DNA and RNA synthesis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Methotrexate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Methotrexate is an antimetabolite that competitively inhibits dihydrofolate reductase (DHFR), the enzyme responsible for converting dihydrofolate into tetrahydrofolate, the biologically active form of folate. This inhibition impairs the synthesis of purines and thymidylate, ultimately reducing DNA and RNA synthesis.\n\nBecause rapidly dividing cells rely heavily on folate-dependent DNA synthesis, long-term methotrexate therapy may lead to: \n• Folate deficiency \n• Megaloblastic anemia \n• Oral mucositis \n• Glossitis \n• Gastrointestinal disturbances\n• Elevated homocysteine levels \n\nMethotrexate is widely used in the treatment of: \n• Rheumatoid arthritis \n• Psoriasis \n• Certain cancers \n• Other autoimmune diseases \n\nTo reduce adverse effects while preserving therapeutic efficacy, patients receiving low-dose methotrexate for autoimmune diseases are commonly prescribed folic acid supplementation, usually on days when methotrexate is not taken or according to the physician''s protocol.","whyWrongChoices":"Alternative options: Digoxin, Omeprazole, Metformin"}'::jsonb),
('mc:what is the formula for adjusted body weight (abw) commonly used for obese patients in clinical nutrition calculations?:::abw = ibw + 0.25 × (actual weight – ibw)', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the formula for adjusted body weight (abw) commonly used for obese patients in clinical nutrition calculations?', 'ABW = IBW + 0.25 × (Actual Weight – IBW)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In obesity, adipose tissue is approximately 25% metabolically active lean tissue. The ABW formula adds 25% of excess weight above IBW to represent the metabolically active mass.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ABW = IBW + 0.25 × (Actual Weight – IBW)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In obesity, adipose tissue is approximately 25% metabolically active lean tissue. The ABW formula adds 25% of excess weight above IBW to represent the metabolically active mass.","whyWrongChoices":"Alternative options: ABW = Actual Weight – 0.50 × IBW, ABW = (Actual Weight + IBW) ÷ 2, ABW = IBW + 0.50 × (Actual Weight – IBW)"}'::jsonb),
('mc:what is the formula for adjusted body weight (abw) commonly used for obese patients in clinical nutrition calculations?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the formula for adjusted body weight (abw) commonly used for obese patients in clinical nutrition calculations?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In obesity, adipose tissue is approximately 25% metabolically active lean tissue. The ABW formula adds 25% of excess weight above IBW to represent the metabolically active mass.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"ABW = IBW + 0.25 × (Actual Weight – IBW)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In obesity, adipose tissue is approximately 25% metabolically active lean tissue. The ABW formula adds 25% of excess weight above IBW to represent the metabolically active mass.","whyWrongChoices":"Alternative options: ABW = Actual Weight – 0.50 × IBW, ABW = (Actual Weight + IBW) ÷ 2, ABW = IBW + 0.50 × (Actual Weight – IBW)"}'::jsonb),
('mc:what are the physiological fuel values (atwater general energy factors) for carbohydrates, protein, fat, and alcohol in kcal/gram?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what are the physiological fuel values (atwater general energy factors) for carbohydrates, protein, fat, and alcohol in kcal/gram?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Atwater standard energy values account for heat of combustion adjusted for digestibility and urinary nitrogen losses: 4 kcal/g for CHO, 4 kcal/g for PRO, 9 kcal/g for Lipid, and 7 kcal/g for Alcohol.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Atwater standard energy values account for heat of combustion adjusted for digestibility and urinary nitrogen losses: 4 kcal/g for CHO, 4 kcal/g for PRO, 9 kcal/g for Lipid, and 7 kcal/g for Alcohol.","whyWrongChoices":"Alternative options: Carb: 4 kcal/g | Protein: 4 kcal/g | Fat: 8 kcal/g | Alcohol: 5 kcal/g, Carb: 3.75 kcal/g | Protein: 4 kcal/g | Fat: 9 kcal/g | Alcohol: 9 kcal/g, Carb: 5 kcal/g | Protein: 5 kcal/g | Fat: 9 kcal/g | Alcohol: 7 kcal/g"}'::jsonb),
('mc:using the hamwi formula, what is the ideal body weight (ibw) for an adult female who is 5 feet 5 inches tall with a medium frame?:::125 lbs (± 10% for frame size)', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'using the hamwi formula, what is the ideal body weight (ibw) for an adult female who is 5 feet 5 inches tall with a medium frame?', '125 lbs (± 10% for frame size)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hamwi female formula: 100 lbs for the first 5 feet (60 inches) + 5 lbs for every additional inch. For 5 ft 5 in: 100 + (5 × 5) = 125 lbs (range 112.5 – 137.5 lbs).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"125 lbs (± 10% for frame size)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hamwi female formula: 100 lbs for the first 5 feet (60 inches) + 5 lbs for every additional inch. For 5 ft 5 in: 100 + (5 × 5) = 125 lbs (range 112.5 – 137.5 lbs).","whyWrongChoices":"Alternative options: 135 lbs (± 10% for frame size), 115 lbs (± 10% for frame size), 120 lbs (± 10% for frame size)"}'::jsonb),
('mc:using the hamwi formula, what is the ideal body weight (ibw) for an adult female who is 5 feet 5 inches tall with a medium frame?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'using the hamwi formula, what is the ideal body weight (ibw) for an adult female who is 5 feet 5 inches tall with a medium frame?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hamwi female formula: 100 lbs for the first 5 feet (60 inches) + 5 lbs for every additional inch. For 5 ft 5 in: 100 + (5 × 5) = 125 lbs (range 112.5 – 137.5 lbs).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"125 lbs (± 10% for frame size)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hamwi female formula: 100 lbs for the first 5 feet (60 inches) + 5 lbs for every additional inch. For 5 ft 5 in: 100 + (5 × 5) = 125 lbs (range 112.5 – 137.5 lbs).","whyWrongChoices":"Alternative options: 135 lbs (± 10% for frame size), 115 lbs (± 10% for frame size), 120 lbs (± 10% for frame size)"}'::jsonb),
('mc:what is the formula to determine the volume in ounces (fl oz) from a standard portion scoop / dipper number?:::32 ÷ scoop number = fluid ounces', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the formula to determine the volume in ounces (fl oz) from a standard portion scoop / dipper number?', '32 ÷ Scoop Number = fluid ounces', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Scoop/dipper numbers indicate the number of level servings per 1 quart (32 fl oz). For example, a #8 scoop yields 32 ÷ 8 = 4 fl oz (1/2 cup), and a #16 scoop yields 32 ÷ 16 = 2 fl oz (1/4 cup).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"32 ÷ Scoop Number = fluid ounces\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Scoop/dipper numbers indicate the number of level servings per 1 quart (32 fl oz). For example, a #8 scoop yields 32 ÷ 8 = 4 fl oz (1/2 cup), and a #16 scoop yields 32 ÷ 16 = 2 fl oz (1/4 cup).","whyWrongChoices":"Alternative options: 64 ÷ Scoop Number = fluid ounces, 16 ÷ Scoop Number = fluid ounces, Scoop Number × 4 = fluid ounces"}'::jsonb)
