('mc:which amino acid serves as the biological precursor for endogenous synthesis of niacin (nad/nadp)?:::tryptophan', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which amino acid serves as the biological precursor for endogenous synthesis of niacin (nad/nadp)?', 'Tryptophan', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tryptophan is converted to nicotinic acid mononucleotide via the kynurenine pathway (requiring Vitamin B6, B2, and iron as cofactors). The conversion ratio is approximately 60 mg of dietary tryptophan = 1 mg of Niacin Equivalent (NE).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tryptophan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tryptophan is converted to nicotinic acid mononucleotide via the kynurenine pathway (requiring Vitamin B6, B2, and iron as cofactors). The conversion ratio is approximately 60 mg of dietary tryptophan = 1 mg of Niacin Equivalent (NE).","whyWrongChoices":"Alternative options: Tyrosine, Phenylalanine, Methionine"}'::jsonb),
('mc:which amino acid serves as the biological precursor for endogenous synthesis of niacin (nad/nadp)?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which amino acid serves as the biological precursor for endogenous synthesis of niacin (nad/nadp)?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Tryptophan is converted to nicotinic acid mononucleotide via the kynurenine pathway (requiring Vitamin B6, B2, and iron as cofactors). The conversion ratio is approximately 60 mg of dietary tryptophan = 1 mg of Niacin Equivalent (NE).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Tryptophan\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Tryptophan is converted to nicotinic acid mononucleotide via the kynurenine pathway (requiring Vitamin B6, B2, and iron as cofactors). The conversion ratio is approximately 60 mg of dietary tryptophan = 1 mg of Niacin Equivalent (NE).","whyWrongChoices":"Alternative options: Tyrosine, Phenylalanine, Methionine"}'::jsonb),
('mc:what is the classic dietary fat to combined carbohydrate + protein ratio used in the ketogenic diet for refractory pediatric epilepsy?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the classic dietary fat to combined carbohydrate + protein ratio used in the ketogenic diet for refractory pediatric epilepsy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The classic ketogenic diet uses a 4:1 ratio of fat (in grams) to combined carbohydrate and protein (in grams), providing ~90% of calories from fat to induce and sustain ketosis, providing ketone bodies (beta-hydroxybutyrate) as the primary cerebral fuel.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4:1 (or 3:1) ratio\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The classic ketogenic diet uses a 4:1 ratio of fat (in grams) to combined carbohydrate and protein (in grams), providing ~90% of calories from fat to induce and sustain ketosis, providing ketone bodies (beta-hydroxybutyrate) as the primary cerebral fuel.","whyWrongChoices":"Alternative options: 1:1 ratio, 2:1 ratio, 5:2 ratio"}'::jsonb),
('mc:what is the recommended protein intake for a non-dialysis chronic kidney disease (ckd) patient in stage 4 (gfr 15–29 ml/min)?:::0.6 to 0.8 g/kg body weight/day', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the recommended protein intake for a non-dialysis chronic kidney disease (ckd) patient in stage 4 (gfr 15–29 ml/min)?', '0.6 to 0.8 g/kg body weight/day', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For CKD Stages 3–5 (non-dialysis), protein is restricted to 0.6–0.8 g/kg/day to slow renal disease progression and decrease uremic toxin accumulation. Once on hemodialysis, protein requirement increases to 1.2–1.4 g/kg/day due to dialysate losses.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.6 to 0.8 g/kg body weight/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For CKD Stages 3–5 (non-dialysis), protein is restricted to 0.6–0.8 g/kg/day to slow renal disease progression and decrease uremic toxin accumulation. Once on hemodialysis, protein requirement increases to 1.2–1.4 g/kg/day due to dialysate losses.","whyWrongChoices":"Alternative options: 1.2 to 1.4 g/kg body weight/day, 1.5 to 2.0 g/kg body weight/day, 0.3 to 0.5 g/kg body weight/day"}'::jsonb),
('mc:what is the recommended protein intake for a non-dialysis chronic kidney disease (ckd) patient in stage 4 (gfr 15–29 ml/min)?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the recommended protein intake for a non-dialysis chronic kidney disease (ckd) patient in stage 4 (gfr 15–29 ml/min)?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For CKD Stages 3–5 (non-dialysis), protein is restricted to 0.6–0.8 g/kg/day to slow renal disease progression and decrease uremic toxin accumulation. Once on hemodialysis, protein requirement increases to 1.2–1.4 g/kg/day due to dialysate losses.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0.6 to 0.8 g/kg body weight/day\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For CKD Stages 3–5 (non-dialysis), protein is restricted to 0.6–0.8 g/kg/day to slow renal disease progression and decrease uremic toxin accumulation. Once on hemodialysis, protein requirement increases to 1.2–1.4 g/kg/day due to dialysate losses.","whyWrongChoices":"Alternative options: 1.2 to 1.4 g/kg body weight/day, 1.5 to 2.0 g/kg body weight/day, 0.3 to 0.5 g/kg body weight/day"}'::jsonb),
('mc:what is the maximum osmolarity cutoff for peripheral parenteral nutrition (ppn) infusion to avoid phlebitis?:::900 mosm/l', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the maximum osmolarity cutoff for peripheral parenteral nutrition (ppn) infusion to avoid phlebitis?', '900 mOsm/L', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Peripheral veins can tolerate solutions up to ~900 mOsm/L. Solutions exceeding 900 mOsm/L are hypertonic and must be infused via Central Parenteral Nutrition (CPN / TPN) through a large central vein (e.g., subclavian/jugular) where high blood flow rapidly dilutes the solution.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"900 mOsm/L\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Peripheral veins can tolerate solutions up to ~900 mOsm/L. Solutions exceeding 900 mOsm/L are hypertonic and must be infused via Central Parenteral Nutrition (CPN / TPN) through a large central vein (e.g., subclavian/jugular) where high blood flow rapidly dilutes the solution.","whyWrongChoices":"Alternative options: 500 mOsm/L, 1500 mOsm/L, 300 mOsm/L"}'::jsonb),
('mc:what is the maximum osmolarity cutoff for peripheral parenteral nutrition (ppn) infusion to avoid phlebitis?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the maximum osmolarity cutoff for peripheral parenteral nutrition (ppn) infusion to avoid phlebitis?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Peripheral veins can tolerate solutions up to ~900 mOsm/L. Solutions exceeding 900 mOsm/L are hypertonic and must be infused via Central Parenteral Nutrition (CPN / TPN) through a large central vein (e.g., subclavian/jugular) where high blood flow rapidly dilutes the solution.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"900 mOsm/L\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Peripheral veins can tolerate solutions up to ~900 mOsm/L. Solutions exceeding 900 mOsm/L are hypertonic and must be infused via Central Parenteral Nutrition (CPN / TPN) through a large central vein (e.g., subclavian/jugular) where high blood flow rapidly dilutes the solution.","whyWrongChoices":"Alternative options: 500 mOsm/L, 1500 mOsm/L, 300 mOsm/L"}'::jsonb),
('mc:what is the classic dietary fat to combined carbohydrate + protein ratio used in the ketogenic diet for refractory pediatric epilepsy?:::4:1 (or 3:1) ratio', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the classic dietary fat to combined carbohydrate + protein ratio used in the ketogenic diet for refractory pediatric epilepsy?', '4:1 (or 3:1) ratio', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The classic ketogenic diet uses a 4:1 ratio of fat (in grams) to combined carbohydrate and protein (in grams), providing ~90% of calories from fat to induce and sustain ketosis, providing ketone bodies (beta-hydroxybutyrate) as the primary cerebral fuel.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"4:1 (or 3:1) ratio\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The classic ketogenic diet uses a 4:1 ratio of fat (in grams) to combined carbohydrate and protein (in grams), providing ~90% of calories from fat to induce and sustain ketosis, providing ketone bodies (beta-hydroxybutyrate) as the primary cerebral fuel.","whyWrongChoices":"Alternative options: 1:1 ratio, 2:1 ratio, 5:2 ratio"}'::jsonb),
('mc:what sodium limit is recommended in the strict dash (dietary approaches to stop hypertension) diet trial?:::1,500 mg/day (lower limit) or 2,300 mg/day (standard)', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what sodium limit is recommended in the strict dash (dietary approaches to stop hypertension) diet trial?', '1,500 mg/day (Lower limit) or 2,300 mg/day (Standard)', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The standard DASH diet limits sodium to 2,300 mg/day, while the lower-sodium DASH plan caps sodium at 1,500 mg/day. It emphasizes potassium, calcium, magnesium, fiber, and lean proteins.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1,500 mg/day (Lower limit) or 2,300 mg/day (Standard)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The standard DASH diet limits sodium to 2,300 mg/day, while the lower-sodium DASH plan caps sodium at 1,500 mg/day. It emphasizes potassium, calcium, magnesium, fiber, and lean proteins.","whyWrongChoices":"Alternative options: 500 mg/day, 3,500 mg/day, 1,000 mg/day max"}'::jsonb),
('mc:what sodium limit is recommended in the strict dash (dietary approaches to stop hypertension) diet trial?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what sodium limit is recommended in the strict dash (dietary approaches to stop hypertension) diet trial?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The standard DASH diet limits sodium to 2,300 mg/day, while the lower-sodium DASH plan caps sodium at 1,500 mg/day. It emphasizes potassium, calcium, magnesium, fiber, and lean proteins.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1,500 mg/day (Lower limit) or 2,300 mg/day (Standard)\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The standard DASH diet limits sodium to 2,300 mg/day, while the lower-sodium DASH plan caps sodium at 1,500 mg/day. It emphasizes potassium, calcium, magnesium, fiber, and lean proteins.","whyWrongChoices":"Alternative options: 500 mg/day, 3,500 mg/day, 1,000 mg/day max"}'::jsonb),
('mc:development which starts in the central axis and progresses towards the extremities:::proximodistal', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'development which starts in the central axis and progresses towards the extremities', 'Proximodistal', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In human growth and development, the proximodistal pattern dictates that physical development and motor control progress from the center of the body outward toward the extremities (periphery). For example, a developing fetus grows its torso and shoulder buds before its arms, hands, and fingers. Similarly, an infant gains muscle control over their trunk and arms before they master the fine motor control of their fingers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Proximodistal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In human growth and development, the proximodistal pattern dictates that physical development and motor control progress from the center of the body outward toward the extremities (periphery). For example, a developing fetus grows its torso and shoulder buds before its arms, hands, and fingers. Similarly, an infant gains muscle control over their trunk and arms before they master the fine motor control of their fingers.\n\n• Cephalocaudal: This describes development that moves from head-to-toe. A fetus''s head develops much faster than its lower body, and an infant learns to hold their head up before they learn to sit up or walk.\n• Hypertrophy and Hyperplasia: These are specific cellular growth mechanisms (increase in cell size and cell number, respectively) rather than directional paths of physical development.","whyWrongChoices":"Alternative options: Cephalocaudal, Hyperplasia, Hypertropy"}'::jsonb),
('mc:development which starts in the central axis and progresses towards the extremities:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'development which starts in the central axis and progresses towards the extremities', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In human growth and development, the proximodistal pattern dictates that physical development and motor control progress from the center of the body outward toward the extremities (periphery). For example, a developing fetus grows its torso and shoulder buds before its arms, hands, and fingers. Similarly, an infant gains muscle control over their trunk and arms before they master the fine motor control of their fingers.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Proximodistal\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In human growth and development, the proximodistal pattern dictates that physical development and motor control progress from the center of the body outward toward the extremities (periphery). For example, a developing fetus grows its torso and shoulder buds before its arms, hands, and fingers. Similarly, an infant gains muscle control over their trunk and arms before they master the fine motor control of their fingers.\n\n• Cephalocaudal: This describes development that moves from head-to-toe. A fetus''s head develops much faster than its lower body, and an infant learns to hold their head up before they learn to sit up or walk.\n• Hypertrophy and Hyperplasia: These are specific cellular growth mechanisms (increase in cell size and cell number, respectively) rather than directional paths of physical development.","whyWrongChoices":"Alternative options: Cephalocaudal, Hyperplasia, Hypertropy"}'::jsonb),
('mc:what is the estimated weight of the amniotic fluid of a pregnant woman?:::2 lbs', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the estimated weight of the amniotic fluid of a pregnant woman?', '2 lbs', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When breaking down the component weight gain of a full-term pregnancy using clinical reference values (totaling 12.5 kg or ~27.5 lbs), the components weigh out as follows:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 lbs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When breaking down the component weight gain of a full-term pregnancy using clinical reference values (totaling 12.5 kg or ~27.5 lbs), the components weigh out as follows:\n\n• Amniotic Fluid: ~1.8 lbs (0.80 kg) — which rounds to 2 lbs\n• Baby (Fetus): ~7.5 lbs (3.40 kg) — note: this is likely where the answer key confused \"7 lbs\"\n• Maternal Fat Stores: ~7.4 lbs (3.35 kg)\n• Extracellular Extravascular Fluid: ~3.3 lbs (1.48 kg)\n• Blood Volume: ~3.2 lbs (1.45 kg)\n• Maternal Tissue: ~3.0 lbs (1.38 kg)\n• Placenta: ~1.4 lbs (0.65 kg)","whyWrongChoices":"Alternative options: 5 lbs, 10.5 lbs, 7 lbs"}'::jsonb),
('mc:a specialized organ formed during pregnancy which functions in removing fetal waste products:::placenta', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a specialized organ formed during pregnancy which functions in removing fetal waste products', 'Placenta', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The placenta is a highly specialized, temporary organ that forms inside the uterus exclusively during pregnancy. It establishes an interface between the maternal and fetal circulatory systems without letting their blood mix directly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Placenta\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The placenta is a highly specialized, temporary organ that forms inside the uterus exclusively during pregnancy. It establishes an interface between the maternal and fetal circulatory systems without letting their blood mix directly.\n\nDeoxygenated blood carrying metabolic waste products from the fetus (such as carbon dioxide, urea, and creatinine) travels to the placenta. The placenta filters these waste materials out of the fetal bloodstream and transfers them into the mother''s blood, where her kidneys and lungs excrete them. Essentially, the placenta acts as the temporary lungs, liver, and kidneys for the baby until birth.\n\n• Umbilical cord: This functions purely as a transport passageway or biological conduit. It contains blood vessels that physically carry waste to the placenta, but the cord itself does not process, filter, or remove the waste.\n• Amniotic sac: This is the fluid-filled \"bag of waters\" that surrounds, cushions, and thermally protects the fetus, but it plays no role in chemical waste extraction.\n• Uterus: This is the permanent muscular maternal organ that houses and protects the growing embryo and placenta, but it is not the actual specialized organ managing nutrient and waste exchange.","whyWrongChoices":"Alternative options: Amniotic sac, Umbilical cord, Uterus"}'::jsonb),
('mc:a specialized organ formed during pregnancy which functions in removing fetal waste products:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a specialized organ formed during pregnancy which functions in removing fetal waste products', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The placenta is a highly specialized, temporary organ that forms inside the uterus exclusively during pregnancy. It establishes an interface between the maternal and fetal circulatory systems without letting their blood mix directly.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Placenta\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The placenta is a highly specialized, temporary organ that forms inside the uterus exclusively during pregnancy. It establishes an interface between the maternal and fetal circulatory systems without letting their blood mix directly.\n\nDeoxygenated blood carrying metabolic waste products from the fetus (such as carbon dioxide, urea, and creatinine) travels to the placenta. The placenta filters these waste materials out of the fetal bloodstream and transfers them into the mother''s blood, where her kidneys and lungs excrete them. Essentially, the placenta acts as the temporary lungs, liver, and kidneys for the baby until birth.\n\n• Umbilical cord: This functions purely as a transport passageway or biological conduit. It contains blood vessels that physically carry waste to the placenta, but the cord itself does not process, filter, or remove the waste.\n• Amniotic sac: This is the fluid-filled \"bag of waters\" that surrounds, cushions, and thermally protects the fetus, but it plays no role in chemical waste extraction.\n• Uterus: This is the permanent muscular maternal organ that houses and protects the growing embryo and placenta, but it is not the actual specialized organ managing nutrient and waste exchange.","whyWrongChoices":"Alternative options: Amniotic sac, Umbilical cord, Uterus"}'::jsonb),
('mc:normally, an infant is able to meet its iron needs for the first 3 months from::::its own liver stores of iron', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'normally, an infant is able to meet its iron needs for the first 3 months from:', 'its own liver stores of iron', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the third trimester of pregnancy, there is a massive transfer of iron from the mother across the placenta to the fetus. This allows a healthy, full-term newborn to be born with a rich endowment of iron, which is primarily accumulated and stored in the fetal liver as ferritin and hemosiderin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"its own liver stores of iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the third trimester of pregnancy, there is a massive transfer of iron from the mother across the placenta to the fetus. This allows a healthy, full-term newborn to be born with a rich endowment of iron, which is primarily accumulated and stored in the fetal liver as ferritin and hemosiderin.\n\nDuring the first two months of life, a newborn''s hemoglobin concentration drops naturally because they are transitioning from the low-oxygen intrauterine environment to normal air breathing. As these extra fetal red blood cells break down, the iron inside them is recycled and pushed directly into the infant''s hepatic (liver) stores. These accumulated stores safely meet 100% of the infant''s growth demands for the first 3 to 6 months of life.\n\n• The iron content in milk: Human breast milk contains exceptionally small, trace amounts of iron. While this minor amount is highly bioavailable, it is mathematically insufficient on its own to support rapid infant growth without the presence of the built-in hepatic reserves.\n• Supplements: Healthy, full-term infants do not routinely require iron supplements during the first 3 months of life. Standard guidelines (like those from the American Academy of Pediatrics) only advise starting daily supplemental iron drops at 4 months of age for exclusively breastfed infants as their liver stores begin to deplete.\n• Weaning food: Weaning foods (complementary solid foods) are strictly introduced at 6 months of age. An infant''s digestive and motor systems are completely unready for solid food within the first 3 months of life.","whyWrongChoices":"Alternative options: the iron content in milk, supplements, weaning food"}'::jsonb),
('mc:normally, an infant is able to meet its iron needs for the first 3 months from::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'normally, an infant is able to meet its iron needs for the first 3 months from:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the third trimester of pregnancy, there is a massive transfer of iron from the mother across the placenta to the fetus. This allows a healthy, full-term newborn to be born with a rich endowment of iron, which is primarily accumulated and stored in the fetal liver as ferritin and hemosiderin.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"its own liver stores of iron\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the third trimester of pregnancy, there is a massive transfer of iron from the mother across the placenta to the fetus. This allows a healthy, full-term newborn to be born with a rich endowment of iron, which is primarily accumulated and stored in the fetal liver as ferritin and hemosiderin.\n\nDuring the first two months of life, a newborn''s hemoglobin concentration drops naturally because they are transitioning from the low-oxygen intrauterine environment to normal air breathing. As these extra fetal red blood cells break down, the iron inside them is recycled and pushed directly into the infant''s hepatic (liver) stores. These accumulated stores safely meet 100% of the infant''s growth demands for the first 3 to 6 months of life.\n\n• The iron content in milk: Human breast milk contains exceptionally small, trace amounts of iron. While this minor amount is highly bioavailable, it is mathematically insufficient on its own to support rapid infant growth without the presence of the built-in hepatic reserves.\n• Supplements: Healthy, full-term infants do not routinely require iron supplements during the first 3 months of life. Standard guidelines (like those from the American Academy of Pediatrics) only advise starting daily supplemental iron drops at 4 months of age for exclusively breastfed infants as their liver stores begin to deplete.\n• Weaning food: Weaning foods (complementary solid foods) are strictly introduced at 6 months of age. An infant''s digestive and motor systems are completely unready for solid food within the first 3 months of life.","whyWrongChoices":"Alternative options: the iron content in milk, supplements, weaning food"}'::jsonb),
('mc:cooking an egg primarily causes its proteins to undergo::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'cooking an egg primarily causes its proteins to undergo:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Egg proteins denature and then coagulate during cooking, changing the egg from a fluid to a firmer structure.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Denaturation and coagulation\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Egg proteins denature and then coagulate during cooking, changing the egg from a fluid to a firmer structure.\n\n• Gelatinization is a starch phenomenon involving starch and water under heat.\n• Caramelization is a nonenzymatic browning reaction involving sugars.\n• Retrogradation refers primarily to reassociation of starch molecules after gelatinization.","whyWrongChoices":"Alternative options: Gelatinization, Retrogadation, Caramelization"}'::jsonb),
('mc:what is the estimated weight of the amniotic fluid of a pregnant woman?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the estimated weight of the amniotic fluid of a pregnant woman?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When breaking down the component weight gain of a full-term pregnancy using clinical reference values (totaling 12.5 kg or ~27.5 lbs), the components weigh out as follows:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 lbs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When breaking down the component weight gain of a full-term pregnancy using clinical reference values (totaling 12.5 kg or ~27.5 lbs), the components weigh out as follows:\n\n• Amniotic Fluid: ~1.8 lbs (0.80 kg) — which rounds to 2 lbs\n• Baby (Fetus): ~7.5 lbs (3.40 kg) — note: this is likely where the answer key confused \"7 lbs\"\n• Maternal Fat Stores: ~7.4 lbs (3.35 kg)\n• Extracellular Extravascular Fluid: ~3.3 lbs (1.48 kg)\n• Blood Volume: ~3.2 lbs (1.45 kg)\n• Maternal Tissue: ~3.0 lbs (1.38 kg)\n• Placenta: ~1.4 lbs (0.65 kg)","whyWrongChoices":"Alternative options: 5 lbs, 10.5 lbs, 7 lbs"}'::jsonb),
('mc:the following are dietary management for morning sickness during pregnancy except::::citrus juice, water, milk, coffee, or tea if experiencing nausea', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are dietary management for morning sickness during pregnancy except:', 'Citrus juice, water, milk, coffee, or tea if experiencing nausea', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"When actively experiencing nausea, drinking standard beverages like citrus juices, plain water, milk, coffee, or tea is heavily discouraged because they can stimulate the stomach lining or trigger the gag reflex. Citrus juice is highly acidic, milk is heavy, and coffee/tea contain caffeine, which acts as a gastric irritant.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Citrus juice, water, milk, coffee, or tea if experiencing nausea\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"When actively experiencing nausea, drinking standard beverages like citrus juices, plain water, milk, coffee, or tea is heavily discouraged because they can stimulate the stomach lining or trigger the gag reflex. Citrus juice is highly acidic, milk is heavy, and coffee/tea contain caffeine, which acts as a gastric irritant.\n\nClinical guidelines state that when a woman is actively nauseated, she should instead sip carbonated beverages (like ginger ale), suck on ice chips, or use clear broths. Furthermore, liquids should always be consumed between meals rather than with solid foods to prevent over-distending the stomach.","whyWrongChoices":"Alternative options: Frequent small meals, Dry toast or crackers, Avoidance of foods with offensive odors"}'::jsonb),
('mc:a characteristic of complementary foods wherein its nutritional value is comparable with breast milk:::adequate', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a characteristic of complementary foods wherein its nutritional value is comparable with breast milk', 'Adequate', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The World Health Organization (WHO) outlines four essential characteristics for complementary feeding (often referred to as the T.A.S.A. guidelines). Each has a distinct definition:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Adequate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The World Health Organization (WHO) outlines four essential characteristics for complementary feeding (often referred to as the T.A.S.A. guidelines). Each has a distinct definition:\n\n• Adequate: This means the food is nutritionally balanced and sufficient. It provides the exact amount of energy, protein, macronutrients, and micronutrients necessary to bridge the gap and match or complement the high nutritional value of breast milk for a growing infant.\n• Timely: This means the foods are introduced at the correct developmental age—specifically when the infant''s nutritional demands exceed what exclusive breast milk can provide (at 6 months of age).\n• Safe: This means the foods are hygienically prepared, stored, and fed using clean hands and utensils to minimize the risk of contamination or diarrheal illness.\n• Appropriate: This means the foods are given in a texture, consistency, and frequency that match the child''s developmental and motor abilities (e.g., transitioning from pureed to mashed to finger foods).","whyWrongChoices":"Alternative options: Timely, Safe, Appropriate"}'::jsonb),
('mc:the following are hormones of lactation except::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are hormones of lactation except:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Direct Lactation Hormones:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Insulin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Direct Lactation Hormones:\n\t• Prolactin: The absolute primary hormone responsible for the synthesis and production of milk within the mammary alveoli.\n\t• Oxytocin: The hormone responsible for the milk ejection (let-down) reflex, causing the myoepithelial cells surrounding the alveoli to contract.\n\t• Estrogen: Crucial during pregnancy for mammogenesis (the structural development and branching of the milk ducts) to prepare the breasts for lactation.\n\nInsulin is a general metabolic hormone produced by the pancreas to regulate blood glucose homeostasis. While it exhibits minor cellular synergy to maintain healthy maternal tissue, it is an endocrine system baseline hormone rather than a primary, targeted hormone of lactation.","whyWrongChoices":"Alternative options: Prolactin, Estrogen, Oxytocin"}'::jsonb),
('mc:a characteristic of complementary foods wherein its nutritional value is comparable with breast milk:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a characteristic of complementary foods wherein its nutritional value is comparable with breast milk', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The World Health Organization (WHO) outlines four essential characteristics for complementary feeding (often referred to as the T.A.S.A. guidelines). Each has a distinct definition:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Adequate\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The World Health Organization (WHO) outlines four essential characteristics for complementary feeding (often referred to as the T.A.S.A. guidelines). Each has a distinct definition:\n\n• Adequate: This means the food is nutritionally balanced and sufficient. It provides the exact amount of energy, protein, macronutrients, and micronutrients necessary to bridge the gap and match or complement the high nutritional value of breast milk for a growing infant.\n• Timely: This means the foods are introduced at the correct developmental age—specifically when the infant''s nutritional demands exceed what exclusive breast milk can provide (at 6 months of age).\n• Safe: This means the foods are hygienically prepared, stored, and fed using clean hands and utensils to minimize the risk of contamination or diarrheal illness.\n• Appropriate: This means the foods are given in a texture, consistency, and frequency that match the child''s developmental and motor abilities (e.g., transitioning from pureed to mashed to finger foods).","whyWrongChoices":"Alternative options: Timely, Safe, Appropriate"}'::jsonb),
('mc:a drug that should be given to nursing with nursing mothers because of it may cause metabolic acidosis and can cause rash.:::aspirin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a drug that should be given to nursing with nursing mothers because of it may cause metabolic acidosis and can cause rash.', 'Aspirin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aspirin (acetylsalicylic acid) is rapidly broken down into salicylic acid. When taken by a breastfeeding mother in high doses, significant amounts can pass into breast milk. Salicylates disrupt cellular metabolism by uncoupling oxidative phosphorylation. In young nursing infants with immature metabolic pathways, this accumulation directly leads to high anion gap metabolic acidosis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspirin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aspirin (acetylsalicylic acid) is rapidly broken down into salicylic acid. When taken by a breastfeeding mother in high doses, significant amounts can pass into breast milk. Salicylates disrupt cellular metabolism by uncoupling oxidative phosphorylation. In young nursing infants with immature metabolic pathways, this accumulation directly leads to high anion gap metabolic acidosis.\n\nIn addition to metabolic imbalances, aspirin exposure through breast milk can trigger hypersensitivity reactions in the infant, causing a rash or skin abnormalities. It can also interfere with platelet aggregation, causing an increased risk of bruising or petechiae.\n\nBeyond the immediate side effects of a rash and acidosis, maternal aspirin use is heavily discouraged because pediatric salicylate exposure is closely linked to Reye''s syndrome, a rare but life-threatening condition causing severe liver and brain swelling.\n\n• Phenobarbital & Primidone: These are anticonvulsant medications. Their primary adverse effects on a nursing infant are severe drowsiness, sedation, poor feeding, and potential withdrawal symptoms upon weaning, rather than metabolic acidosis.\n• Clemastine: This is an antihistamine. Its primary reported side effects in a breastfed baby include extreme drowsiness, irritability, and a high-pitched cry.","whyWrongChoices":"Alternative options: Clemastine, Phenobarital, Primidone"}'::jsonb),
('mc:a drug that should be given to nursing with nursing mothers because of it may cause metabolic acidosis and can cause rash.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a drug that should be given to nursing with nursing mothers because of it may cause metabolic acidosis and can cause rash.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Aspirin (acetylsalicylic acid) is rapidly broken down into salicylic acid. When taken by a breastfeeding mother in high doses, significant amounts can pass into breast milk. Salicylates disrupt cellular metabolism by uncoupling oxidative phosphorylation. In young nursing infants with immature metabolic pathways, this accumulation directly leads to high anion gap metabolic acidosis.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Aspirin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Aspirin (acetylsalicylic acid) is rapidly broken down into salicylic acid. When taken by a breastfeeding mother in high doses, significant amounts can pass into breast milk. Salicylates disrupt cellular metabolism by uncoupling oxidative phosphorylation. In young nursing infants with immature metabolic pathways, this accumulation directly leads to high anion gap metabolic acidosis.\n\nIn addition to metabolic imbalances, aspirin exposure through breast milk can trigger hypersensitivity reactions in the infant, causing a rash or skin abnormalities. It can also interfere with platelet aggregation, causing an increased risk of bruising or petechiae.\n\nBeyond the immediate side effects of a rash and acidosis, maternal aspirin use is heavily discouraged because pediatric salicylate exposure is closely linked to Reye''s syndrome, a rare but life-threatening condition causing severe liver and brain swelling.\n\n• Phenobarbital & Primidone: These are anticonvulsant medications. Their primary adverse effects on a nursing infant are severe drowsiness, sedation, poor feeding, and potential withdrawal symptoms upon weaning, rather than metabolic acidosis.\n• Clemastine: This is an antihistamine. Its primary reported side effects in a breastfed baby include extreme drowsiness, irritability, and a high-pitched cry.","whyWrongChoices":"Alternative options: Clemastine, Phenobarital, Primidone"}'::jsonb),
('mc:the following are hormones of lactation except::::insulin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the following are hormones of lactation except:', 'Insulin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Direct Lactation Hormones:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Insulin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Direct Lactation Hormones:\n\t• Prolactin: The absolute primary hormone responsible for the synthesis and production of milk within the mammary alveoli.\n\t• Oxytocin: The hormone responsible for the milk ejection (let-down) reflex, causing the myoepithelial cells surrounding the alveoli to contract.\n\t• Estrogen: Crucial during pregnancy for mammogenesis (the structural development and branching of the milk ducts) to prepare the breasts for lactation.\n\nInsulin is a general metabolic hormone produced by the pancreas to regulate blood glucose homeostasis. While it exhibits minor cellular synergy to maintain healthy maternal tissue, it is an endocrine system baseline hormone rather than a primary, targeted hormone of lactation.","whyWrongChoices":"Alternative options: Prolactin, Estrogen, Oxytocin"}'::jsonb),
('mc:a premature infant is born fewer than days of gestation.:::270', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a premature infant is born fewer than days of gestation.', '270', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In many classic nutrition and nursing reviewers (such as local dietetics or NCM/obstetric notes), a premature infant is traditionally defined as one born fewer than 270 days of gestation (or weighing less than 2,500 grams).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"270\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In many classic nutrition and nursing reviewers (such as local dietetics or NCM/obstetric notes), a premature infant is traditionally defined as one born fewer than 270 days of gestation (or weighing less than 2,500 grams).\n\nGlobally, the World Health Organization (WHO) and modern obstetrics define preterm birth strictly as a baby born before 37 completed weeks (which equals fewer than 259 days). However, among the standard multiple-choice options provided (270, 300, 170, 200), 270 days aligns with the classic threshold taught in older local curricula.","whyWrongChoices":"Alternative options: 300, 170, 200"}'::jsonb),
('mc:a premature infant is born fewer than days of gestation.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a premature infant is born fewer than days of gestation.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"In many classic nutrition and nursing reviewers (such as local dietetics or NCM/obstetric notes), a premature infant is traditionally defined as one born fewer than 270 days of gestation (or weighing less than 2,500 grams).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"270\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"In many classic nutrition and nursing reviewers (such as local dietetics or NCM/obstetric notes), a premature infant is traditionally defined as one born fewer than 270 days of gestation (or weighing less than 2,500 grams).\n\nGlobally, the World Health Organization (WHO) and modern obstetrics define preterm birth strictly as a baby born before 37 completed weeks (which equals fewer than 259 days). However, among the standard multiple-choice options provided (270, 300, 170, 200), 270 days aligns with the classic threshold taught in older local curricula.","whyWrongChoices":"Alternative options: 300, 170, 200"}'::jsonb),
('mc:what is true about the purpose of the menstrual cycle?:::a and b are both true', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is true about the purpose of the menstrual cycle?', 'A and B are both TRUE', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The overarching biological purpose of the entire menstrual cycle is to prepare the female reproductive system for a potential pregnancy. To achieve this goal, the cycle carries out two separate but deeply connected processes simultaneously:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both TRUE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The overarching biological purpose of the entire menstrual cycle is to prepare the female reproductive system for a potential pregnancy. To achieve this goal, the cycle carries out two separate but deeply connected processes simultaneously:\n\n• Statement A is TRUE: Driven by Follicle-Stimulating Hormone (FSH) and Luteinizing Hormone (LH), the ovarian cycle works to develop and release a single mature ovum (egg cell) from the ovaries during the ovulation phase.\n• Statement D is TRUE: Driven by estrogen and progesterone, the uterine cycle concurrently works to prepare, thicken, and enrich the uterus lining (endometrium), creating a plush environment ready to sustain a fertilized egg if implantation takes place.","whyWrongChoices":"Alternative options: To develop and release a mature ovum, To prepare the uterus lining, A and B are both FALSE"}'::jsonb),
('mc:what is true about the purpose of the menstrual cycle?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is true about the purpose of the menstrual cycle?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The overarching biological purpose of the entire menstrual cycle is to prepare the female reproductive system for a potential pregnancy. To achieve this goal, the cycle carries out two separate but deeply connected processes simultaneously:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"A and B are both TRUE\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The overarching biological purpose of the entire menstrual cycle is to prepare the female reproductive system for a potential pregnancy. To achieve this goal, the cycle carries out two separate but deeply connected processes simultaneously:\n\n• Statement A is TRUE: Driven by Follicle-Stimulating Hormone (FSH) and Luteinizing Hormone (LH), the ovarian cycle works to develop and release a single mature ovum (egg cell) from the ovaries during the ovulation phase.\n• Statement D is TRUE: Driven by estrogen and progesterone, the uterine cycle concurrently works to prepare, thicken, and enrich the uterus lining (endometrium), creating a plush environment ready to sustain a fertilized egg if implantation takes place.","whyWrongChoices":"Alternative options: To develop and release a mature ovum, To prepare the uterus lining, A and B are both FALSE"}'::jsonb),
('mc:the mesoderm gives rise to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the mesoderm gives rise to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During early embryonic development, the mesoderm forms the intermediate layer sandwiched between the ectoderm and endoderm. It gives rise to structural, circulatory, and excretory systems.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Urogenital system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During early embryonic development, the mesoderm forms the intermediate layer sandwiched between the ectoderm and endoderm. It gives rise to structural, circulatory, and excretory systems.\n\nThe intermediate mesoderm specifically condenses into the urogenital ridges, which directly differentiate into the urinary system (kidneys and ducts) and the reproductive/genital system (gonads, internal sex organs, and uterus).\n\n• Nervous system: Arises from the ectoderm (the outermost layer), specifically through the differentiation of the neuroectoderm into the neural tube and neural crest.\n• Pancreas and Thyroid: Develop from the endoderm (the innermost layer), which buds outward to form the linings and organs of the digestive and respiratory tracts.","whyWrongChoices":"Alternative options: Nervous system, Pancreas, Thyroid"}'::jsonb),
('mc:what is the estimated weight of the placenta of a pregnant woman?:::2 lbs', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the estimated weight of the placenta of a pregnant woman?', '2 lbs', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At full term, a normal, healthy human placenta typically weighs around 500 to 650 grams (roughly 1.4 to 1.5 lbs, or up to ~2 lbs when grouped in standard prenatal weight-gain breakdowns).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 lbs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At full term, a normal, healthy human placenta typically weighs around 500 to 650 grams (roughly 1.4 to 1.5 lbs, or up to ~2 lbs when grouped in standard prenatal weight-gain breakdowns).\n\nWhen clinical references (such as the Mayo Clinic or standard obstetrics texts) break down the typical 25–35 lb pregnancy weight gain, the placenta is consistently categorized at 1.5 to 2 lbs.\n\nWhen breaking down the component weight gain of a full-term pregnancy using clinical reference values (totaling 12.5 kg or ~27.5 lbs), the components weigh out as follows:\n\n• Amniotic Fluid: ~1.8 lbs (0.80 kg) — which rounds to 2 lbs\n• Baby (Fetus): ~7.5 lbs (3.40 kg) — note: this is likely where the answer key confused \"7 lbs\"\n• Maternal Fat Stores: ~7.4 lbs (3.35 kg)\n• Extracellular Extravascular Fluid: ~3.3 lbs (1.48 kg)\n• Blood Volume: ~3.2 lbs (1.45 kg)\n• Maternal Tissue: ~3.0 lbs (1.38 kg)\n• Placenta: ~1.4 lbs (0.65 kg)","whyWrongChoices":"Alternative options: 5 lbs, 10.5 lbs, 7 lbs"}'::jsonb),
('mc:age period characterized by rapid differentiation and establishment of systems and orgarns::::embryonic', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'age period characterized by rapid differentiation and establishment of systems and orgarns:', 'Embryonic', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The embryonic period spans from the third week through the eighth week of pregnancy. This critical phase is defined by organogenesis, which is the rapid differentiation of cells into distinct germ cell layers (ectoderm, mesoderm, and endoderm) and the foundation of all major body systems and rudimentary organs. By the end of the eighth week, the basic structural form of the human body and its systems are fully established.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Embryonic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The embryonic period spans from the third week through the eighth week of pregnancy. This critical phase is defined by organogenesis, which is the rapid differentiation of cells into distinct germ cell layers (ectoderm, mesoderm, and endoderm) and the foundation of all major body systems and rudimentary organs. By the end of the eighth week, the basic structural form of the human body and its systems are fully established.\n\nThe fetal periods (both early and late) span from the ninth week until birth. This phase is primarily characterized by the growth, refinement, and functional maturation of those already established systems rather than their initial structural establishment or differentiation.\n\nThe neonatal period refers to the first 28 days of life after birth, where the newborn adapts physiologically to extrauterine life.","whyWrongChoices":"Alternative options: Early fetal, Late fetal, Neonatal"}'::jsonb),
('mc:what is the estimated weight of the placenta of a pregnant woman?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the estimated weight of the placenta of a pregnant woman?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"At full term, a normal, healthy human placenta typically weighs around 500 to 650 grams (roughly 1.4 to 1.5 lbs, or up to ~2 lbs when grouped in standard prenatal weight-gain breakdowns).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"2 lbs\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"At full term, a normal, healthy human placenta typically weighs around 500 to 650 grams (roughly 1.4 to 1.5 lbs, or up to ~2 lbs when grouped in standard prenatal weight-gain breakdowns).\n\nWhen clinical references (such as the Mayo Clinic or standard obstetrics texts) break down the typical 25–35 lb pregnancy weight gain, the placenta is consistently categorized at 1.5 to 2 lbs.\n\nWhen breaking down the component weight gain of a full-term pregnancy using clinical reference values (totaling 12.5 kg or ~27.5 lbs), the components weigh out as follows:\n\n• Amniotic Fluid: ~1.8 lbs (0.80 kg) — which rounds to 2 lbs\n• Baby (Fetus): ~7.5 lbs (3.40 kg) — note: this is likely where the answer key confused \"7 lbs\"\n• Maternal Fat Stores: ~7.4 lbs (3.35 kg)\n• Extracellular Extravascular Fluid: ~3.3 lbs (1.48 kg)\n• Blood Volume: ~3.2 lbs (1.45 kg)\n• Maternal Tissue: ~3.0 lbs (1.38 kg)\n• Placenta: ~1.4 lbs (0.65 kg)","whyWrongChoices":"Alternative options: 5 lbs, 10.5 lbs, 7 lbs"}'::jsonb),
('mc:the mesoderm gives rise to::::urogenital system', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the mesoderm gives rise to:', 'Urogenital system', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During early embryonic development, the mesoderm forms the intermediate layer sandwiched between the ectoderm and endoderm. It gives rise to structural, circulatory, and excretory systems.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Urogenital system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During early embryonic development, the mesoderm forms the intermediate layer sandwiched between the ectoderm and endoderm. It gives rise to structural, circulatory, and excretory systems.\n\nThe intermediate mesoderm specifically condenses into the urogenital ridges, which directly differentiate into the urinary system (kidneys and ducts) and the reproductive/genital system (gonads, internal sex organs, and uterus).\n\n• Nervous system: Arises from the ectoderm (the outermost layer), specifically through the differentiation of the neuroectoderm into the neural tube and neural crest.\n• Pancreas and Thyroid: Develop from the endoderm (the innermost layer), which buds outward to form the linings and organs of the digestive and respiratory tracts.","whyWrongChoices":"Alternative options: Nervous system, Pancreas, Thyroid"}'::jsonb),
('mc:cut-off weight for low birth weight::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'cut-off weight for low birth weight:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The World Health Organization (WHO) defines Low Birth Weight (LBW) as an absolute birth weight of less than 2,500 grams (up to and including 2,499 grams).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5.50 lbs or less\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The World Health Organization (WHO) defines Low Birth Weight (LBW) as an absolute birth weight of less than 2,500 grams (up to and including 2,499 grams).\n\nConverting 2,500 grams into the imperial system commonly used in board exams:\n2,500 grams ÷ 453.59 = 5.511 lbs\n\nTherefore, a threshold of 5.50 lbs represents the direct equivalent cutoff used to diagnose low birth weight in medical and public health data.\n\n• Low Birth Weight (LBW): Less than 2,500 grams (~5.5 lbs)\n• Very Low Birth Weight (VLBW): Less than 1,500 grams (~3.3 lbs)\n• Extremely Low Birth Weight (ELBW): Less than 1,000 grams (~2.2 lbs)","whyWrongChoices":"Alternative options: 5 lbs or less, 5 kg or less, 25 kg or less"}'::jsonb),
('mc:physiologic anemia of pregnancy is due to::::increased blood volume', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'physiologic anemia of pregnancy is due to:', 'Increased blood volume', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During pregnancy, a woman''s total blood volume expands dramatically to support the growing fetus. However, the plasma volume increases by roughly 50%, while the actual mass of red blood cells only increases by about 20% to 30%.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Increased blood volume\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During pregnancy, a woman''s total blood volume expands dramatically to support the growing fetus. However, the plasma volume increases by roughly 50%, while the actual mass of red blood cells only increases by about 20% to 30%.\n\nBecause the liquid portion of the blood (plasma) expands much faster and more significantly than the red blood cells, it creates a dilutional effect. This lowers the overall concentration of hemoglobin and hematocrit, leading to what is safely classified as physiologic (or normal) anemia of pregnancy.\n\nNote on other options: While iron deficiency and Vitamin B12 deficiency are common causes of pathological anemia during pregnancy, they do not cause the normal physiologic adaptation described above.","whyWrongChoices":"Alternative options: Iron deficiency, Vitamin B12 deficiency, Decreased blood volume"}'::jsonb),
('mc:acrolein is associated with::::overheated fats', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'acrolein is associated with:', 'Overheated fats', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Acrolein can form when fats are overheated, particularly when glycerol components break down.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Overheated fats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Acrolein can form when fats are overheated, particularly when glycerol components break down.\n\n• Fermented milk is associated with lactic acid fermentation rather than acrolein formation.\n• Gelatinized starch results from starch absorbing water and swelling during heating.\n• Fresh fruits are not the food phenomenon described by acrolein formation.","whyWrongChoices":"Alternative options: Fresh fruits, Fermented milk, Gelatinized starch"}'::jsonb),
('mc:physiologic anemia of pregnancy is due to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'physiologic anemia of pregnancy is due to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During pregnancy, a woman''s total blood volume expands dramatically to support the growing fetus. However, the plasma volume increases by roughly 50%, while the actual mass of red blood cells only increases by about 20% to 30%.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Increased blood volume\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During pregnancy, a woman''s total blood volume expands dramatically to support the growing fetus. However, the plasma volume increases by roughly 50%, while the actual mass of red blood cells only increases by about 20% to 30%.\n\nBecause the liquid portion of the blood (plasma) expands much faster and more significantly than the red blood cells, it creates a dilutional effect. This lowers the overall concentration of hemoglobin and hematocrit, leading to what is safely classified as physiologic (or normal) anemia of pregnancy.\n\nNote on other options: While iron deficiency and Vitamin B12 deficiency are common causes of pathological anemia during pregnancy, they do not cause the normal physiologic adaptation described above.","whyWrongChoices":"Alternative options: Iron deficiency, Vitamin B12 deficiency, Decreased blood volume"}'::jsonb),
('mc:the calcium recommendation in the pdri for a pregnant woman on her first month versus a six-month pregnant woman is::::the same', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the calcium recommendation in the pdri for a pregnant woman on her first month versus a six-month pregnant woman is:', 'the same', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the Philippine Dietary Reference Intakes (PDRI), the baseline calcium requirement for a woman of childbearing age (e.g., 750–800 mg/day depending on age) does not change during the first two trimesters of pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the same\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the Philippine Dietary Reference Intakes (PDRI), the baseline calcium requirement for a woman of childbearing age (e.g., 750–800 mg/day depending on age) does not change during the first two trimesters of pregnancy.\n\nA woman in her first month is in her 1st trimester, and a woman in her sixth month is in her 2nd trimester. Because neither phase requires an increase, their daily recommended intakes are identical.\n\nThe PDRI explicitly applies the +50 mg/day calcium addition only during the 3rd trimester. This is when rapid fetal skeletal mineralization occurs, requiring extra maternal dietary support. In the earlier months (1st and 6th), the mother''s body naturally compensates by increasing its own intestinal calcium absorption efficiency, keeping the dietary recommendation unchanged.","whyWrongChoices":"Alternative options: lower, higher, not comparable"}'::jsonb)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.ai_explanation_cache (id, question_hash, front_text, back_text, options, explanation, breakdown, created_at, question_text, user_answer, is_correct, ai_explanation) VALUES
('mc:a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chorionic gonadotropin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.\n\nIts primary biological purpose is to travel to the ovaries and rescue the corpus luteum from breaking down. By binding to shared luteinizing hormone receptors, chorionic gonadotropin continuously stimulates the corpus luteum to secrete high levels of progesterone and estrogen. This preserves the lush endometrium and maintains the pregnancy until the placenta grows large enough to take over steroid production entirely.\n\n• Placental lactogen: Also secreted by the placenta, this protein hormone primarily alters maternal carbohydrate and lipid metabolism to ensure a steady supply of glucose reaches the fetus. It also prepares the maternal breast tissue for future lactation, rather than stimulating steroid hormone production.\n• Follicle-stimulating hormone (FSH) and Luteinizing hormone (LH): These are gonadotropins secreted by the anterior pituitary gland, not the placenta. Furthermore, maternal pituitary secretion of FSH and LH drops to near-zero during pregnancy due to the high negative feedback loops caused by circulating gestational steroids.","whyWrongChoices":"Alternative options: Luteinizing hormone, Placental lactogen, Follicle-stimulating hormone"}'::jsonb),
('mc:the calcium recommendation in the pdri for a pregnant woman on her first month versus a six-month pregnant woman is::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the calcium recommendation in the pdri for a pregnant woman on her first month versus a six-month pregnant woman is:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the Philippine Dietary Reference Intakes (PDRI), the baseline calcium requirement for a woman of childbearing age (e.g., 750–800 mg/day depending on age) does not change during the first two trimesters of pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"the same\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the Philippine Dietary Reference Intakes (PDRI), the baseline calcium requirement for a woman of childbearing age (e.g., 750–800 mg/day depending on age) does not change during the first two trimesters of pregnancy.\n\nA woman in her first month is in her 1st trimester, and a woman in her sixth month is in her 2nd trimester. Because neither phase requires an increase, their daily recommended intakes are identical.\n\nThe PDRI explicitly applies the +50 mg/day calcium addition only during the 3rd trimester. This is when rapid fetal skeletal mineralization occurs, requiring extra maternal dietary support. In the earlier months (1st and 6th), the mother''s body naturally compensates by increasing its own intestinal calcium absorption efficiency, keeping the dietary recommendation unchanged.","whyWrongChoices":"Alternative options: lower, higher, not comparable"}'::jsonb),
('mc:how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?:::6.8kg', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?', '6.8kg', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.8kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):\n\n• Obese Category (BMI ≥ 30.0): The official guideline recommends a total weight gain of 11 to 20 lbs, which mathematically converts to a range of 5.0 to 9.0 kg.\n• Evaluating the Options: Among the given choices, 6.8 kg is the only value that falls squarely within the recommended 5.0–9.0 kg clinical safety window for a singleton pregnancy.\n\nRecommended Gestational Weight Gain Guidelines\n\n• Underweight (BMI < 18.5): 12.5 to 18.0 kg (28 to 40 lbs)\n• Normal Weight (BMI 18.5 – 24.9): 11.5 to 16.0 kg (25 to 35 lbs)\n• Overweight (BMI 25.0 – 29.9): 6.8 to 11.3 kg (15 to 25 lbs)\n• Obese (BMI ≥ 30.0): 5.0 to 9.0 kg (11 to 20 lbs)","whyWrongChoices":"Alternative options: 12.5kg, 11.5kg, 7.8kg"}'::jsonb),
('mc:how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'how much weight gain will you recommend if a woman has a pre-pregnancy weight status of obese?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"6.8kg\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"According to the Institute of Medicine (IOM) global standards for gestational weight gain, recommendations are tailored specifically to a woman''s pre-pregnancy Body Mass Index (BMI):\n\n• Obese Category (BMI ≥ 30.0): The official guideline recommends a total weight gain of 11 to 20 lbs, which mathematically converts to a range of 5.0 to 9.0 kg.\n• Evaluating the Options: Among the given choices, 6.8 kg is the only value that falls squarely within the recommended 5.0–9.0 kg clinical safety window for a singleton pregnancy.\n\nRecommended Gestational Weight Gain Guidelines\n\n• Underweight (BMI < 18.5): 12.5 to 18.0 kg (28 to 40 lbs)\n• Normal Weight (BMI 18.5 – 24.9): 11.5 to 16.0 kg (25 to 35 lbs)\n• Overweight (BMI 25.0 – 29.9): 6.8 to 11.3 kg (15 to 25 lbs)\n• Obese (BMI ≥ 30.0): 5.0 to 9.0 kg (11 to 20 lbs)","whyWrongChoices":"Alternative options: 12.5kg, 11.5kg, 7.8kg"}'::jsonb),
('mc:a condition in pregnancy formerly called toxemia:::pregnancy induced hypertension', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a condition in pregnancy formerly called toxemia', 'Pregnancy induced hypertension', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pregnancy induced hypertension\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.\n\nToday, the medical community recognizes that this condition is rooted in a dysfunction of the placenta and blood vessels rather than a biological poison. As a result, the umbrella classification was updated to Pregnancy-Induced Hypertension (PIH), which encompasses a clinical spectrum including gestational hypertension, preeclampsia, and eclampsia.\n\n• Gestational Diabetes: High blood glucose levels that develop for the first time during pregnancy.\n• Hyperemesis Gravidarum: A severe, unrelenting form of nausea and vomiting during pregnancy that leads to dehydration and weight loss.\n• Cachexia: A profound metabolic state of muscle wasting and severe weight loss typically associated with chronic illnesses like cancer.","whyWrongChoices":"Alternative options: Gestational diabetes, Cachexia, Hyperemesis gravidarum"}'::jsonb),
('mc:a condition in pregnancy formerly called toxemia:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a condition in pregnancy formerly called toxemia', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Pregnancy induced hypertension\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Historically, healthcare providers used the term toxemia (or toxemia of pregnancy) because it was believed that the condition was caused by a mysterious \"toxin\" circulating in the maternal bloodstream.\n\nToday, the medical community recognizes that this condition is rooted in a dysfunction of the placenta and blood vessels rather than a biological poison. As a result, the umbrella classification was updated to Pregnancy-Induced Hypertension (PIH), which encompasses a clinical spectrum including gestational hypertension, preeclampsia, and eclampsia.\n\n• Gestational Diabetes: High blood glucose levels that develop for the first time during pregnancy.\n• Hyperemesis Gravidarum: A severe, unrelenting form of nausea and vomiting during pregnancy that leads to dehydration and weight loss.\n• Cachexia: A profound metabolic state of muscle wasting and severe weight loss typically associated with chronic illnesses like cancer.","whyWrongChoices":"Alternative options: Gestational diabetes, Cachexia, Hyperemesis gravidarum"}'::jsonb),
('mc:which is a nutritional risk factor during pregnancy?:::weight gain of less than 1 kg per month after the 1st trimester', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is a nutritional risk factor during pregnancy?', 'Weight gain of less than 1 kg per month after the 1st trimester', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Weight gain of less than 1 kg per month after the 1st trimester\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).\n\nStandard public health and maternal nutrition protocols (such as clinical criteria for identifying high-risk pregnancies) explicitly classify a weight gain of less than 1 kg (about 2.2 lbs) per month after the first trimester as a key indicator of inadequate gestational weight gain. This increases the statistical risk of intrauterine growth restriction (IUGR) and having a low birth weight infant.\n\n• Hematocrit of greater than 35%: Normal hematocrit levels for pregnant women typically drop slightly due to hemodilution but a value above 35% indicates safe red blood cell concentrations (anemia is diagnosed when it drops below 32–33%). (Note: The unit in the question is a common exam typo; hematocrit is measured in percentages, not mg/dL).\n• Weight gain of more than 85% standard weight: This option contains confusing terminology, but being at or above standard body weight thresholds is a baseline classification rather than an active gestational risk factor like low ongoing weight gain.\n• Hemoglobin of greater than 12 g/dL: A hemoglobin level above 12 g/dL is completely normal and healthy. Maternal anemia is only diagnosed when hemoglobin falls below 11.0 g/dL in the first/third trimesters or below 10.5 g/dL in the second trimester.","whyWrongChoices":"Alternative options: Hemoglobin of greater than 12 g/dL, Hematocrit of greater than 35%, Weight gain of more than 85% standard weight"}'::jsonb),
('mc:which is a nutritional risk factor during pregnancy?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is a nutritional risk factor during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Weight gain of less than 1 kg per month after the 1st trimester\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During the second and third trimesters, steady weight gain is critical because this is when the fetus grows rapidly and the mother expands her supportive tissues (blood volume, uterus, and fat stores).\n\nStandard public health and maternal nutrition protocols (such as clinical criteria for identifying high-risk pregnancies) explicitly classify a weight gain of less than 1 kg (about 2.2 lbs) per month after the first trimester as a key indicator of inadequate gestational weight gain. This increases the statistical risk of intrauterine growth restriction (IUGR) and having a low birth weight infant.\n\n• Hematocrit of greater than 35%: Normal hematocrit levels for pregnant women typically drop slightly due to hemodilution but a value above 35% indicates safe red blood cell concentrations (anemia is diagnosed when it drops below 32–33%). (Note: The unit in the question is a common exam typo; hematocrit is measured in percentages, not mg/dL).\n• Weight gain of more than 85% standard weight: This option contains confusing terminology, but being at or above standard body weight thresholds is a baseline classification rather than an active gestational risk factor like low ongoing weight gain.\n• Hemoglobin of greater than 12 g/dL: A hemoglobin level above 12 g/dL is completely normal and healthy. Maternal anemia is only diagnosed when hemoglobin falls below 11.0 g/dL in the first/third trimesters or below 10.5 g/dL in the second trimester.","whyWrongChoices":"Alternative options: Hemoglobin of greater than 12 g/dL, Hematocrit of greater than 35%, Weight gain of more than 85% standard weight"}'::jsonb),
('mc:a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.:::chorionic gonadotropin', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'a hormone secreted by the placenta that stimulates the secretion of estrogen and progresterone.', 'Chorionic gonadotropin', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chorionic gonadotropin\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Secreted by the syncytiotrophoblast cells of the placenta immediately after implantation, hCG acts as a crucial chemical messenger during early pregnancy.\n\nIts primary biological purpose is to travel to the ovaries and rescue the corpus luteum from breaking down. By binding to shared luteinizing hormone receptors, chorionic gonadotropin continuously stimulates the corpus luteum to secrete high levels of progesterone and estrogen. This preserves the lush endometrium and maintains the pregnancy until the placenta grows large enough to take over steroid production entirely.\n\n• Placental lactogen: Also secreted by the placenta, this protein hormone primarily alters maternal carbohydrate and lipid metabolism to ensure a steady supply of glucose reaches the fetus. It also prepares the maternal breast tissue for future lactation, rather than stimulating steroid hormone production.\n• Follicle-stimulating hormone (FSH) and Luteinizing hormone (LH): These are gonadotropins secreted by the anterior pituitary gland, not the placenta. Furthermore, maternal pituitary secretion of FSH and LH drops to near-zero during pregnancy due to the high negative feedback loops caused by circulating gestational steroids.","whyWrongChoices":"Alternative options: Luteinizing hormone, Placental lactogen, Follicle-stimulating hormone"}'::jsonb),
('mc:effect of poor maternal diet, i.e. low in energy and protein, on human milk:::decreased milk volume', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'effect of poor maternal diet, i.e. low in energy and protein, on human milk', 'Decreased milk volume', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased milk volume\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.\n\nWhile the quality is physiologically buffered, extreme or prolonged deficiency in maternal energy and protein intake triggers the body to save energy by reducing the total quantity (volume) of milk produced. Research shows that when a lactating mother''s intake falls below critical thresholds, it directly results in decreased milk volume rather than diluted milk quality.","whyWrongChoices":"Alternative options: Cassation of lactation, Reduced quality of milk, Reduced quality and quantity"}'::jsonb),
('mc:acrolein is associated with::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'acrolein is associated with:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Acrolein can form when fats are overheated, particularly when glycerol components break down.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Overheated fats\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Acrolein can form when fats are overheated, particularly when glycerol components break down.\n\n• Fermented milk is associated with lactic acid fermentation rather than acrolein formation.\n• Gelatinized starch results from starch absorbing water and swelling during heating.\n• Fresh fruits are not the food phenomenon described by acrolein formation.","whyWrongChoices":"Alternative options: Fresh fruits, Fermented milk, Gelatinized starch"}'::jsonb),
('mc:effect of poor maternal diet, i.e. low in energy and protein, on human milk:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'effect of poor maternal diet, i.e. low in energy and protein, on human milk', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decreased milk volume\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The human body prioritizes the survival of the infant by preserving the macronutrient quality (concentrations of protein, fat, and lactose) of breast milk even during maternal malnutrition. The body draws directly from maternal tissue and nutrient reserves to keep the milk''s nutrient composition remarkably stable.\n\nWhile the quality is physiologically buffered, extreme or prolonged deficiency in maternal energy and protein intake triggers the body to save energy by reducing the total quantity (volume) of milk produced. Research shows that when a lactating mother''s intake falls below critical thresholds, it directly results in decreased milk volume rather than diluted milk quality.","whyWrongChoices":"Alternative options: Cassation of lactation, Reduced quality of milk, Reduced quality and quantity"}'::jsonb),
('mc:what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?:::1', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the recommended ratio of whole milk and water when preparing milk for an infant below three months of age?', '1', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"For an infant below three months of age, the immature kidneys cannot handle the high solute load (protein and minerals) found in undiluted cow''s milk. To make it safer, traditional guidelines recommend mixing 1 part whole milk with 1 part water (a 1:1 ratio) to dilute the nutrient concentration.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"1\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"For an infant below three months of age, the immature kidneys cannot handle the high solute load (protein and minerals) found in undiluted cow''s milk. To make it safer, traditional guidelines recommend mixing 1 part whole milk with 1 part water (a 1:1 ratio) to dilute the nutrient concentration.\n\nBecause the question asks for the numeric value of the ratio itself (whole milk to water), a 1:1 proportion reduces mathematically to 1.\n\nFor Your Review Notes:\n• Below 3 months: 1:1 ratio (1 part milk to 1 part water) + sugar/carbohydrates to adjust calories.\n• Over 3 months: The ratio traditionally shifts to 2:1 (2 parts milk to 1 part water) as the infant''s renal capacity matures.","whyWrongChoices":"Alternative options: 2, 3, 4"}'::jsonb),
('mc:immunological factor in human milk that inhibits intracellular viral replication:::interferon', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'immunological factor in human milk that inhibits intracellular viral replication', 'Interferon', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Interferon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.\n\n• Macrophages: Large white blood cells that act locally in the infant''s gut to engulf and digest whole bacteria, cellular debris, and foreign particles through phagocytosis.\n• Lactoferrin: An iron-binding glycoprotein that primarily prevents bacterial growth by starving iron-dependent pathogens (like E. coli). It also exerts surface-level antiviral effects by blocking viruses from physically sticking or adhering to the outside of host cell receptors, rather than working inside the cell.\n• Lysozyme: An active enzyme that protects the infant by splitting open and lysing the cell walls of harmful Gram-positive bacteria.","whyWrongChoices":"Alternative options: Lactoferrin, Macrophages, Lysozyme"}'::jsonb),
('mc:which is true about the amino acids in human milk?:::rich in taurine', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is true about the amino acids in human milk?', 'Rich in taurine', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rich in taurine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).\n\n• Human milk is uniquely characterized by being low in methionine and rich in cysteine. This provides a high cysteine-to-methionine ratio, which is ideal for newborns because their livers have a temporary deficiency in the enzyme cystathionase needed to convert methionine into cysteine. Option B actually describes the profile of cow''s milk.\n• Human milk is physiologically designed to be low in phenylalanine and tyrosine. This low concentration safely protects the neonate’s immature metabolic capacity and prevents the harmful accumulation of these aromatic compounds in the blood. Cow''s milk and older infant formulas contain much higher levels of these two amino acids.","whyWrongChoices":"Alternative options: Higher in methionine and lower in cysteine, High in phenylalanine and tyrosine, All of the above"}'::jsonb),
('mc:which is true about the amino acids in human milk?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is true about the amino acids in human milk?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Rich in taurine\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Taurine is a sulfur-containing amino acid that is highly essential for infants to support bile acid conjugation, retinal development, and brain growth. It is famously recognized as the second most abundant free amino acid in human milk (surpassed only by glutamate).\n\n• Human milk is uniquely characterized by being low in methionine and rich in cysteine. This provides a high cysteine-to-methionine ratio, which is ideal for newborns because their livers have a temporary deficiency in the enzyme cystathionase needed to convert methionine into cysteine. Option B actually describes the profile of cow''s milk.\n• Human milk is physiologically designed to be low in phenylalanine and tyrosine. This low concentration safely protects the neonate’s immature metabolic capacity and prevents the harmful accumulation of these aromatic compounds in the blood. Cow''s milk and older infant formulas contain much higher levels of these two amino acids.","whyWrongChoices":"Alternative options: Higher in methionine and lower in cysteine, High in phenylalanine and tyrosine, All of the above"}'::jsonb),
('mc:an anti-infectious factor in human milk that protects the integrity of the git epithelium::::prostaglandins', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an anti-infectious factor in human milk that protects the integrity of the git epithelium:', 'Prostaglandins', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prostaglandins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.\n\nRoles of the other anti-infectious factors in human milk:\n• Bifidus factor: A carbohydrate compound that selectively promotes the growth of beneficial Lactobacillus bifidus in the infant’s gut. This creates an acidic environment that indirectly crowds out and prevents the colonization of pathogenic bacteria.\n• Lactoferrin: An iron-binding glycoprotein that exerts its anti-infective effect by tightly sequestering free iron, making it completely unavailable to iron-dependent pathogenic bacteria (like E. coli).\n• Lactoperoxidase: An enzyme that participates in the oxidative destruction of harmful bacteria by converting peroxide into antibacterial hypothiocyanite ions.","whyWrongChoices":"Alternative options: Bifidusfactor, Lactoperoxidase, Lactoferrin"}'::jsonb),
('mc:an anti-infectious factor in human milk that protects the integrity of the git epithelium::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'an anti-infectious factor in human milk that protects the integrity of the git epithelium:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Prostaglandins\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Prostaglandins (specifically PGE2 and PGI2) present in human milk exert a robust cytoprotective effect on the newborn''s gastrointestinal tract. They stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, accelerate cellular repair, and prevent mucosal injury, thereby actively protecting the structural integrity of the gastrointestinal tract (GIT) epithelium against inflammatory and infectious damage.\n\nRoles of the other anti-infectious factors in human milk:\n• Bifidus factor: A carbohydrate compound that selectively promotes the growth of beneficial Lactobacillus bifidus in the infant’s gut. This creates an acidic environment that indirectly crowds out and prevents the colonization of pathogenic bacteria.\n• Lactoferrin: An iron-binding glycoprotein that exerts its anti-infective effect by tightly sequestering free iron, making it completely unavailable to iron-dependent pathogenic bacteria (like E. coli).\n• Lactoperoxidase: An enzyme that participates in the oxidative destruction of harmful bacteria by converting peroxide into antibacterial hypothiocyanite ions.","whyWrongChoices":"Alternative options: Bifidusfactor, Lactoperoxidase, Lactoferrin"}'::jsonb),
('mc:immunological factor in human milk that inhibits intracellular viral replication:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'immunological factor in human milk that inhibits intracellular viral replication', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Interferon\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Interferon is a signaling protein (cytokine) found naturally in human breast milk. Its primary biological function is to trigger protective defenses within cells. When a virus attempts to attack, interferon signals neighboring cells to produce specific antiviral proteins that directly inhibit and block intracellular viral replication, limiting the spread of the virus within the infant''s host tissues.\n\n• Macrophages: Large white blood cells that act locally in the infant''s gut to engulf and digest whole bacteria, cellular debris, and foreign particles through phagocytosis.\n• Lactoferrin: An iron-binding glycoprotein that primarily prevents bacterial growth by starving iron-dependent pathogens (like E. coli). It also exerts surface-level antiviral effects by blocking viruses from physically sticking or adhering to the outside of host cell receptors, rather than working inside the cell.\n• Lysozyme: An active enzyme that protects the infant by splitting open and lysing the cell walls of harmful Gram-positive bacteria.","whyWrongChoices":"Alternative options: Lactoferrin, Macrophages, Lysozyme"}'::jsonb),
('mc:what is the dosage for vitamin a supplementation for pregnant women?:::10,000 iu', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the dosage for vitamin a supplementation for pregnant women?', '10,000 IU', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10,000 IU\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).\n\nUnder standard DOH guidelines for pregnant women in vitamin A-deficient areas, the official recommendation is 10,000 IU taken orally once a day, starting from the 4th month (2nd trimester) of pregnancy until delivery.\n\nSafety Considerations by Population:\n\n• High-dose capsules (such as 100,000 IU): These are strictly administered to specific infant populations rather than pregnant individuals.\n• Massive-dose capsules (such as 200,000 IU): These are reserved for older children and postpartum or lactating mothers within a specific window after delivery.","whyWrongChoices":"Alternative options: 20,000 IU, 100,000 IU, 200,000 IU"}'::jsonb),
('mc:what is the dosage for vitamin a supplementation for pregnant women?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'what is the dosage for vitamin a supplementation for pregnant women?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"10,000 IU\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"High doses of preformed Vitamin A (retinol) are highly teratogenic, meaning they can cross the placenta and cause severe congenital birth defects in the developing fetus. To balance maternal health with fetal safety, the World Health Organization (WHO) and the Philippine Department of Health (DOH) state that routine daily supplementation for pregnant women should never exceed 10,000 IU (or 25,000 IU if given as a weekly dose).\n\nUnder standard DOH guidelines for pregnant women in vitamin A-deficient areas, the official recommendation is 10,000 IU taken orally once a day, starting from the 4th month (2nd trimester) of pregnancy until delivery.\n\nSafety Considerations by Population:\n\n• High-dose capsules (such as 100,000 IU): These are strictly administered to specific infant populations rather than pregnant individuals.\n• Massive-dose capsules (such as 200,000 IU): These are reserved for older children and postpartum or lactating mothers within a specific window after delivery.","whyWrongChoices":"Alternative options: 20,000 IU, 100,000 IU, 200,000 IU"}'::jsonb),
('mc:the lowest level of structural organization of the living human body:::chemical level', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the lowest level of structural organization of the living human body', 'Chemical level', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The structural organization of the human body progresses systematically from the simplest chemical building blocks up to the complete living being. The levels are arranged from lowest to highest complexity:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Chemical level\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The structural organization of the human body progresses systematically from the simplest chemical building blocks up to the complete living being. The levels are arranged from lowest to highest complexity:\n\n• Chemical level: The lowest and absolute simplest level. It is composed of atoms that combine to form molecules like water, DNA, and proteins.\n• Cellular level: The level where molecules interact to form cells, which are the basic functional units of life.\n• Tissue level: Groups of similar cells working together to perform a specialized shared function.\n• Organ level: Structures made of two or more different tissue types joined together to perform specific tasks.\n• System level: Consists of related organs that work together to accomplish a common purpose, like the digestive system.\n• Organismal level: The highest level of organization, representing the living human body as a whole.\n\nBecause atoms and molecules form the foundation for all structures above it, the chemical level is always classified as the lowest tier.","whyWrongChoices":"Alternative options: Cellular level, Tissue level, Organ level"}'::jsonb),
('mc:cut-off weight for low birth weight::::5.50 lbs or less', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'cut-off weight for low birth weight:', '5.50 lbs or less', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The World Health Organization (WHO) defines Low Birth Weight (LBW) as an absolute birth weight of less than 2,500 grams (up to and including 2,499 grams).","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"5.50 lbs or less\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The World Health Organization (WHO) defines Low Birth Weight (LBW) as an absolute birth weight of less than 2,500 grams (up to and including 2,499 grams).\n\nConverting 2,500 grams into the imperial system commonly used in board exams:\n2,500 grams ÷ 453.59 = 5.511 lbs\n\nTherefore, a threshold of 5.50 lbs represents the direct equivalent cutoff used to diagnose low birth weight in medical and public health data.\n\n• Low Birth Weight (LBW): Less than 2,500 grams (~5.5 lbs)\n• Very Low Birth Weight (VLBW): Less than 1,500 grams (~3.3 lbs)\n• Extremely Low Birth Weight (ELBW): Less than 1,000 grams (~2.2 lbs)","whyWrongChoices":"Alternative options: 5 lbs or less, 5 kg or less, 25 kg or less"}'::jsonb),
('mc:it is a phase in cell growth characterized by cell proliferation:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is a phase in cell growth characterized by cell proliferation', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperplasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.\n\nHypertrophy (Cell Size): This refers to an increase in the physical size or volume of existing cells due to the accumulation of proteins, functional units, and cytoplasm, rather than cell multiplication.\n\n• Cephalocaudal and Proximodistal: These describe the predictable directional paths or trends of physical growth and motor development (e.g., \"head-to-toe\" and \"center-to-periphery\"), not cellular mechanisms.","whyWrongChoices":"Alternative options: Cephalocaudal, Proximodistal, Hypertropy"}'::jsonb),
('mc:which of the following is a physiologic change which is common during pregnancy?:::decrease gastric acidity', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is a physiologic change which is common during pregnancy?', 'Decrease gastric acidity', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decrease gastric acidity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:\n\nIn this traditional testing framework, the massive surges of progesterone and estrogen during the first and second trimesters are taught to slow down general gastric acid secretion along with reducing smooth muscle tone.\n\nThis traditional framework asserts that a temporary reduction in gastric hydrochloric acid production occurs early in pregnancy. (Note: In these same test banks, the common symptom of heartburn is explained as a mechanical issue—the relaxation of the lower esophageal sphincter allowing even small amounts of stomach acid to travel upward—rather than a state of hyperacidity).\n\nFixed Rationale for Your Review Notes:\n• Decrease gastric acidity: In localized test banks, pregnancy hormones are noted for temporarily suppressing gastric secretions and hydrochloric acid production, particularly during the first two trimesters.\n• Increase calcium absorption: While physiologically true that calcium absorption increases significantly during pregnancy, if your specific board reviewer identifies Option B as the intended answer key, it means the test author is explicitly testing you on the hormone-driven reductions in gastric secretions.","whyWrongChoices":"Alternative options: Increase gastric tone and motility, Increase calcium absorption, Decrease metabolic rate"}'::jsonb),
('mc:which of the following is a physiologic change which is common during pregnancy?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which of the following is a physiologic change which is common during pregnancy?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Decrease gastric acidity\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"While modern maternal clinical textbooks show that gastric pH can fluctuate or decrease (become more acidic) because the placenta releases the hormone gastrin, traditional local board exam reviewers and certain nursing test banks (like older HESI or maternal-child question matrices) rely on a different classic framework:\n\nIn this traditional testing framework, the massive surges of progesterone and estrogen during the first and second trimesters are taught to slow down general gastric acid secretion along with reducing smooth muscle tone.\n\nThis traditional framework asserts that a temporary reduction in gastric hydrochloric acid production occurs early in pregnancy. (Note: In these same test banks, the common symptom of heartburn is explained as a mechanical issue—the relaxation of the lower esophageal sphincter allowing even small amounts of stomach acid to travel upward—rather than a state of hyperacidity).\n\nFixed Rationale for Your Review Notes:\n• Decrease gastric acidity: In localized test banks, pregnancy hormones are noted for temporarily suppressing gastric secretions and hydrochloric acid production, particularly during the first two trimesters.\n• Increase calcium absorption: While physiologically true that calcium absorption increases significantly during pregnancy, if your specific board reviewer identifies Option B as the intended answer key, it means the test author is explicitly testing you on the hormone-driven reductions in gastric secretions.","whyWrongChoices":"Alternative options: Increase gastric tone and motility, Increase calcium absorption, Decrease metabolic rate"}'::jsonb),
('mc:additional fluid intake per day recommended for lactation mothers:::750-1000ml', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'additional fluid intake per day recommended for lactation mothers', '750-1000ml', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"750-1000ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.\n\nSince human breast milk is roughly 87% water, a mother producing 1,000 ml of milk is losing nearly 870 ml of pure water directly to her baby every single day. To completely balance this fluid loss and safeguard against dehydration, nutritional models advise expanding daily beverage consumption by an additional 750–1000 ml above basic baseline needs.\n\nBreast milk is highly fluid-dense (~87% water). Because a fully lactating mother produces an average of 750–1000 ml of breast milk daily, guidelines suggest a direct, corresponding addition of 750–1000 ml of fluid per day to adequately preserve maternal hydration without compromising milk output volume.","whyWrongChoices":"Alternative options: 100-250ml, 250-500ml, 500-750ml"}'::jsonb),
('mc:additional fluid intake per day recommended for lactation mothers:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'additional fluid intake per day recommended for lactation mothers', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"750-1000ml\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Standard textbooks and regional nutrition guidelines point out that a mother''s milk production typically reaches 750 to 1,000 ml per day during established, exclusive breastfeeding.\n\nSince human breast milk is roughly 87% water, a mother producing 1,000 ml of milk is losing nearly 870 ml of pure water directly to her baby every single day. To completely balance this fluid loss and safeguard against dehydration, nutritional models advise expanding daily beverage consumption by an additional 750–1000 ml above basic baseline needs.\n\nBreast milk is highly fluid-dense (~87% water). Because a fully lactating mother produces an average of 750–1000 ml of breast milk daily, guidelines suggest a direct, corresponding addition of 750–1000 ml of fluid per day to adequately preserve maternal hydration without compromising milk output volume.","whyWrongChoices":"Alternative options: 100-250ml, 250-500ml, 500-750ml"}'::jsonb),
('mc:age period characterized by rapid differentiation and establishment of systems and orgarns::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'age period characterized by rapid differentiation and establishment of systems and orgarns:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"The embryonic period spans from the third week through the eighth week of pregnancy. This critical phase is defined by organogenesis, which is the rapid differentiation of cells into distinct germ cell layers (ectoderm, mesoderm, and endoderm) and the foundation of all major body systems and rudimentary organs. By the end of the eighth week, the basic structural form of the human body and its systems are fully established.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Embryonic\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"The embryonic period spans from the third week through the eighth week of pregnancy. This critical phase is defined by organogenesis, which is the rapid differentiation of cells into distinct germ cell layers (ectoderm, mesoderm, and endoderm) and the foundation of all major body systems and rudimentary organs. By the end of the eighth week, the basic structural form of the human body and its systems are fully established.\n\nThe fetal periods (both early and late) span from the ninth week until birth. This phase is primarily characterized by the growth, refinement, and functional maturation of those already established systems rather than their initial structural establishment or differentiation.\n\nThe neonatal period refers to the first 28 days of life after birth, where the newborn adapts physiologically to extrauterine life.","whyWrongChoices":"Alternative options: Early fetal, Late fetal, Neonatal"}'::jsonb),
('mc:the ectoderm give rise to::::nervous system', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the ectoderm give rise to:', 'Nervous system', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nervous system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.\n\n• Thyroid and Pancreas: These organs develop from the endoderm (the innermost germ layer), which forms the epithelial linings of the digestive tract, respiratory tract, and associated glands/organs.\n• Urogenital system: Most components of the urinary and reproductive systems develop from the mesoderm (the middle germ layer), which also forms the bones, muscles, and circulatory system.","whyWrongChoices":"Alternative options: Urogenital system, Pancreas, Thyroid"}'::jsonb),
('mc:the ectoderm give rise to::::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'the ectoderm give rise to:', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Nervous system\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During early embryonic development, the ectoderm forms the outermost layer of the germ cells. It is responsible for giving rise to tissues that interact with the outside world. This includes the entire nervous system (brain, spinal cord, and peripheral nerves) as well as the epidermis of the skin, hair, nails, and the lens of the eye.\n\n• Thyroid and Pancreas: These organs develop from the endoderm (the innermost germ layer), which forms the epithelial linings of the digestive tract, respiratory tract, and associated glands/organs.\n• Urogenital system: Most components of the urinary and reproductive systems develop from the mesoderm (the middle germ layer), which also forms the bones, muscles, and circulatory system.","whyWrongChoices":"Alternative options: Urogenital system, Pancreas, Thyroid"}'::jsonb),
('mc:which is true about the physical growth of an infant?:::the infant''s length changes more slowly than the weight', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which is true about the physical growth of an infant?', 'The infant''s length changes more slowly than the weight', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"During infancy, a baby undergoes a massive, rapid increase in physical mass compared to linear growth. An infant’s weight increases by roughly 200% in the first year (it triples from birth weight). In contrast, their linear length increases by about 50% over that same first year (gaining roughly 10 inches). Because the percentage and relative rate of height accumulation are much more gradual than the explosive accumulation of mass, it is clinically stated that infant length changes more slowly than weight.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"The infant''s length changes more slowly than the weight\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"During infancy, a baby undergoes a massive, rapid increase in physical mass compared to linear growth. An infant’s weight increases by roughly 200% in the first year (it triples from birth weight). In contrast, their linear length increases by about 50% over that same first year (gaining roughly 10 inches). Because the percentage and relative rate of height accumulation are much more gradual than the explosive accumulation of mass, it is clinically stated that infant length changes more slowly than weight.\n\n• An infant''s birth weight typically doubles by 5 months of age (Gaber, 2019), not by two months. While it is true that birth weight triples by one year, the first half of that statement is physiologically incorrect for a standard, healthy tracking curve.","whyWrongChoices":"Alternative options: Infants birth weight doubles by about two months and triples by one year, A and B are both TRUE, A and B are both FALSE"}'::jsonb),
('mc:it is a phase in cell growth characterized by cell proliferation:::hyperplasia', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'it is a phase in cell growth characterized by cell proliferation', 'Hyperplasia', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hyperplasia\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hyperplasia (Cell Proliferation): This is defined as an increase in the absolute number of cells resulting from cell division and proliferation. During this growth phase, a mother cell divides into identical daughter cells (mitosis), expanding the body''s total cell count.\n\nHypertrophy (Cell Size): This refers to an increase in the physical size or volume of existing cells due to the accumulation of proteins, functional units, and cytoplasm, rather than cell multiplication.\n\n• Cephalocaudal and Proximodistal: These describe the predictable directional paths or trends of physical growth and motor development (e.g., \"head-to-toe\" and \"center-to-periphery\"), not cellular mechanisms.","whyWrongChoices":"Alternative options: Cephalocaudal, Proximodistal, Hypertropy"}'::jsonb),
('mc:decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume:::hemodilution', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume', 'Hemodilution', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemodilution\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.\n\n• Hemoconcentration: This is the exact opposite of hemodilution. It happens when plasma volume decreases (often due to severe dehydration), making the concentration of red blood cells appear falsely elevated.\n• Hypochromic anemia: This refers to red blood cells that have less hemoglobin than normal, causing them to look pale under a microscope (typically seen in iron deficiency). It is an issue of cell quality, not plasma volume.\n• Pernicious anemia: This is a specific type of macrocytic anemia caused by an autoimmune inability to absorb Vitamin B12 due to a lack of intrinsic factor, unrelated to plasma expansion.","whyWrongChoices":"Alternative options: Hypochromic anemia, Hemoconcentration, Pernicious anemia"}'::jsonb),
('mc:decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'decrease in the proportion of red blood cells relative to the plasma brought about by an increase in total plasma volume', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Hemodilution\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Hemodilution occurs when the volume of plasma (the liquid portion of the blood) increases at a faster rate than the actual production of red blood cells. Because there is more fluid stretching across the same relative mass of cells, the overall concentration of red blood cells, hemoglobin, and hematocrit decreases. This is the exact mechanism that causes physiologic anemia of pregnancy.\n\n• Hemoconcentration: This is the exact opposite of hemodilution. It happens when plasma volume decreases (often due to severe dehydration), making the concentration of red blood cells appear falsely elevated.\n• Hypochromic anemia: This refers to red blood cells that have less hemoglobin than normal, causing them to look pale under a microscope (typically seen in iron deficiency). It is an issue of cell quality, not plasma volume.\n• Pernicious anemia: This is a specific type of macrocytic anemia caused by an autoimmune inability to absorb Vitamin B12 due to a lack of intrinsic factor, unrelated to plasma expansion.","whyWrongChoices":"Alternative options: Hypochromic anemia, Hemoconcentration, Pernicious anemia"}'::jsonb),
('mc:approximately how many iq points are lost at birth among infants of iodine deficient mothers?:::13.5', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'approximately how many iq points are lost at birth among infants of iodine deficient mothers?', '13.5', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"13.5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.\n\nIodine is essential for thyroid hormone synthesis, which drives fetal brain and central nervous system development. Iodine deficiency is recognized globally as the leading cause of preventable brain damage and intellectual disability.","whyWrongChoices":"Alternative options: 11.5, 12, 12.5"}'::jsonb),
('mc:approximately how many iq points are lost at birth among infants of iodine deficient mothers?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'approximately how many iq points are lost at birth among infants of iodine deficient mothers?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"13.5\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Classic meta-analyses (such as the landmark review by Bleichrodt and Born) estimate that children and populations in severe-to-moderate iodine-deficient regions experience an average reduction of 13.5 intelligence quotient (IQ) points compared to iodine-sufficient populations.\n\nIodine is essential for thyroid hormone synthesis, which drives fetal brain and central nervous system development. Iodine deficiency is recognized globally as the leading cause of preventable brain damage and intellectual disability.","whyWrongChoices":"Alternative options: 11.5, 12, 12.5"}'::jsonb),
('mc:according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?:::0%', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?', '0%', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. \n\nHistorical Context \n• Old Rule (Pre-2019): Under the original text of Article 96 of the Labor Code, 85% went to the employees and 15% was retained by management.\n• New Rule (2019 Onward): The 15% management share was completely removed, making the employee share 100%.","whyWrongChoices":"Alternative options: 20%, 15%, 30%"}'::jsonb),
('mc:according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?:::', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'according to the updated labor code (ra 11360) of the philippines, what percent of the service charge goes to the management?', NULL, true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. ","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"0%\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Under Republic Act No. 11360, which amended Article 96 of the Labor Code, 100% of the service charges are distributed among covered employees, excluding managerial employees from the distribution. Thus, management receives 0% as a statutory share. \n\nHistorical Context \n• Old Rule (Pre-2019): Under the original text of Article 96 of the Labor Code, 85% went to the employees and 15% was retained by management.\n• New Rule (2019 Onward): The 15% management share was completely removed, making the employee share 100%.","whyWrongChoices":"Alternative options: 20%, 15%, 30%"}'::jsonb),
('mc:which statement best describes ergonomics in foodservice facility design?:::designing workstations to fit workers and promote safe, efficient performance', NULL, NULL, NULL, NULL, NULL, NULL, '"2026-11-04T11:21:38.282Z"'::jsonb, 'which statement best describes ergonomics in foodservice facility design?', 'Designing workstations to fit workers and promote safe, efficient performance', true, '{"sources":[{"url":"","title":"Krause and Mahan''s Food & the Nutrition Care Process"},{"url":"","title":"NDLE Board Licensure Reference Manual"}],"whyRight":"Ergonomics applies human capabilities and limitations to workplace design to improve safety, comfort, and efficiency.","modelUsed":"Gemini 2.5 Flash","isAiPowered":true,"keyDifference":"Key differentiator: \"Designing workstations to fit workers and promote safe, efficient performance\" aligns strictly with standard dietetics criteria.","searchOverview":"Official NDLE Board Licensure Reference & Evidence Breakdown","authorRationale":"Ergonomics applies human capabilities and limitations to workplace design to improve safety, comfort, and efficiency.","whyWrongChoices":"Alternative options: Option B, Designing menus according to customer preferences, Designing storage systems according to food cost"}'::jsonb),
